const Region = base.Region;
const DeferredConstraintCheck = unifier.DeferredConstraintCheck;
const StaticDispatchConstraint = types_mod.StaticDispatchConstraint;
const InterpolationPartMetadata = types_mod.InterpolationPartMetadata;
const Func = types_mod.Func;
const Var = types_mod.Var;
const Flex = types_mod.Flex;
const Rigid = types_mod.Rigid;
const Content = types_mod.Content;
const FlatType = types_mod.FlatType;
const Rank = types_mod.Rank;
const Polarity = types_mod.Polarity;
const Instantiator = types_mod.instantiate.Instantiator;
const InstantiationProofPair = types_mod.instantiate.ProofPair;
const InstantiationProofConstraintPair = types_mod.instantiate.ProofConstraintPair;
const InstantiationProofWitness = types_mod.instantiate.ProofWitness;
const InstantiationProofRootPair = types_mod.instantiate.ProofRootPair;
const InstantiationProofRootSelection = types_mod.instantiate.ProofRootSelection;
const PolarityVarBehavior = Instantiator.PolarityVarBehavior;
const Generalizer = types_mod.generalize.Generalizer;
const VarPool = types_mod.generalize.VarPool;
const SnapshotStore = snapshot_mod.Store;
const ProblemStore = @import("problem.zig").Store;

const Self = @This();

const TypeDeclGenerationState = enum {
    not_generated,
    generating,
    generated,
};

const TypeDeclDependency = struct {
    dependent: u32,
    dependency: u32,
};

const InterpolationPartsIdx = InterpolationPartMetadata.SafeList.Idx;

const no_type_decl_dense_index = std.math.maxInt(u32);

const no_def_group = std.math.maxInt(u32);

const FunctionEffectState = enum {
    pure,
    effectful,
    unresolved,
};

const FunctionEffectResolution = enum {
    visiting,
    pure,
    effectful,
    unresolved,

    fn state(self: @This()) FunctionEffectState {
        return switch (self) {
            .visiting, .pure => .pure,
            .effectful => .effectful,
            .unresolved => .unresolved,
        };
    }
};

const ExpectEffectSlotId = enum(u32) { _ };

const ExpectEffectSlot = struct {
    region: Region,
    effectful: bool = false,
};

const ExpectDispatchWatcher = struct {
    slot: ExpectEffectSlotId,
    fn_var: Var,
};

const PendingInspectMethodUse = struct {
    call_expr: CIR.Expr.Idx,
    argument_expr: CIR.Expr.Idx,
};

/// How a type variable occurrence will be represented in the checked type
/// artifact consumed by later compiler stages.
const InspectTypePosition = enum(u2) {
    value,
    record_row,
    tag_row,
};

/// Transient checker input carrying the platform root's requirement surface:
/// the platform's checked env (read-only; instantiated into the app's store,
/// never referenced by checker output) and its path for diagnostics.
pub const PlatformRequirementInput = struct {
    env: *const ModuleEnv,
    /// Owner-minted authority for `env`. The checker binds this exact handle
    /// to one slot of its already-validated semantic dependency closure before
    /// any canonical input is mutated.
    validated_env: ValidatedModuleEnv,
    /// Exact semantic owner closure available while copying and checking the
    /// platform's requirement types in the app.
    owner_modules: []const *const ModuleEnv,
    path: []const u8,
};

/// An exact raw occurrence endpoint produced by an earlier marker-copy proof.
/// Expected-type propagation keeps this identity separate from the solved
/// representative: redirects do not authenticate a different raw variable.
const ExpectedMarkerAnchor = struct {
    copy_step: u32,
    occurrence_offset: u32,
    side: ModuleEnv.WhereMarkerCopyOccurrenceSide,
};

/// A call-shape producer row is itself the finite authority for one exact raw
/// formal. It deliberately carries no copy endpoint: the formal graph remains
/// mutable until a later consumer copies it.
const ExpectedProducerRootAnchor = struct {
    plan_index: u32,
    raw_var: Var,
};

/// Exact producer plan which proved that this raw Expected occurrence carries
/// no attached/default/where evidence. The plan identity, not a descriptive
/// enum, is the authority and may itself be selected as a later copy parent.
const ExpectedEvidenceFreeAnchor = struct {
    plan_index: u32,
    raw_var: Var,
};

/// One successful producer-authored relation between a branch body/owner and
/// the unchanged semantic accumulator. No Store copy is implied: the plan row
/// itself records the exact relation outcome and carries the raw accumulator
/// selected by its prior authority.
const ExpectedRelationPlanAnchor = struct {
    plan_index: u32,
    raw_var: Var,
};

const ExpectedParentAuthority = union(enum) {
    copy_occurrence: ExpectedMarkerAnchor,
    producer_root: ExpectedProducerRootAnchor,
    evidence_free_plan: ExpectedEvidenceFreeAnchor,
    relation_plan: ExpectedRelationPlanAnchor,
};

const ExpectedMarkerAuthority = union(enum) {
    anchored: ExpectedParentAuthority,
    evidence_free: ExpectedEvidenceFreeAnchor,
};

/// Producer-authored state of the exact Expected endpoint carried into a
/// consumer. An error is either direct at this boundary, or arrives through
/// one exact earlier Expected-consumption plan; consumers never rediscover
/// either case from the mutable solved graph.
const ExpectedSourceStatus = union(enum) {
    established,
    checked_error: struct {
        cause: ModuleEnv.CauseOwner,
        route: ErrorRoute,
    },

    const ErrorRoute = union(enum) {
        direct,
        upstream_plan: u32,
    };
};

const PlatformRequiredDef = struct {
    expected_var: Var,
    expected_anchor: ExpectedMarkerAnchor,
    required_ident: Ident.Idx,
    /// Where the platform's requires clause declares this requirement.
    platform_region: Region,
};

/// A platform requirement type instantiated into this module's store, plus
/// its identity variables in canonical slot order (checker-owned slice).
const InstantiatedRequirement = struct {
    expected_var: Var,
    expected_anchor: ExpectedMarkerAnchor,
    identity_vars: []Var,
};

gpa: std.mem.Allocator,
// This module's types store
types: *types_mod.Store,
/// This module's env
cir: *ModuleEnv,
/// A list of regions. Owned copy, cloned from NodeStore at init time.
regions: Region.List,
/// Owned copy of the directly imported module pointers. Import indexes in CIR
/// refer to this list; the pointed-to ModuleEnvs remain caller-owned.
imported_modules: []const *const ModuleEnv,
/// Immutable admission capabilities parallel to `imported_modules`. These
/// bind each resolved import index to the exact checked environment and
/// content hash whose contextual alias certificates were admitted.
validated_imported_modules: []const ValidatedModuleEnv,
/// Immutable admission capabilities parallel to `owner_modules`. The full
/// closure is retained through terminal publication so inherited marker bases
/// can be admitted against the same owners checking consumed.
validated_owner_modules: []const ValidatedModuleEnv,
/// Capability for this module, minted only at the final checked boundary.
/// It remains null throughout solving and on every failed check.
validated_module: ?OwnedValidatedModuleEnv,
/// Exact semantic-dependency slot that authorizes platform-requirement copy
/// roots, or null when this check has no platform requirement surface.
platform_dependency_index: ?usize,
/// Owned copy of module pointers whose public APIs are semantically visible
/// through imported checked data; the pointed-to ModuleEnvs remain caller-owned.
owner_modules: []const *const ModuleEnv,
/// Content identity to owner env, built once for constant-time nominal and
/// alias owner resolution during checking.
owner_envs_by_identity: std.AutoHashMapUnmanaged(base.ModuleIdentity.Hash, OwnerEnvCandidate),
/// Env-local identity (in `cir`'s module identity table) that types minted
/// from compiler-builtin declarations carry as their `origin_module`: the
/// Builtin module's deep content identity (or this module's own identity when
/// checking the Builtin module itself, whose content identity is identical).
builtin_origin_identity: base.ModuleIdentity.Idx,
/// Map of auto-imported type names (like "Str", "List", "Bool") to their defining modules.
/// This is used to resolve type names that are automatically available without explicit imports.
auto_imported_types: ?*const std.AutoHashMap(Ident.Idx, can.Can.AutoImportedType),
/// Builtin type context for the module being type-checked
builtin_ctx: BuiltinContext,
/// type snapshots used in error messages
snapshots: SnapshotStore,
/// type problems
problems: ProblemStore,
/// import mapping for auto-imported builtin types (for error display)
import_mapping: @import("types").import_mapping.ImportMapping,
/// reusable scratch arrays used in unification
unify_scratch: unifier.Scratch,
/// reusable scratch arrays used in occurs check
occurs_scratch: occurs.Scratch,
/// Type annotation nodes already seen while generating one annotation type.
seen_annos: std.DynamicBitSetUnmanaged,
/// A pool of solver envs
env_pool: EnvPool,
/// wrapper around generalization, contains some internal state used to do it's work
generalizer: Generalizer,
/// A list of generated recursive/cross-definition constraints with solving deferred.
constraints: Constraint.SafeList,
/// Return-flow constraints (`return` and `?`) owned by the lambda that produced them.
return_constraints: std.ArrayListUnmanaged(ReturnConstraint),
/// Stack of active lambda-owned return constraint ranges.
return_constraint_frames: std.ArrayListUnmanaged(ReturnConstraintFrame),
/// A map from one var to another. Used in instantiation and var copying
var_map: std.AutoHashMap(Var, Var),
/// A map from one var to another. Used in instantiation and var copying
var_set: std.AutoHashMap(Var, void),
/// Reusable visited set for validating the concrete content of values passed
/// to `Str.inspect`. Each value is a bitset of occurrence positions because
/// the same type variable can appear both as a row tail and as an ordinary
/// value.
inspect_type_visits: std.AutoHashMap(Var, u8),
/// Explicit visit stack for `varContainsError`'s heap-worklist type-graph
/// walk. Entries are base-relative: each entry point operates only on the
/// slots it pushed and drains back to its entry length, so the walk may nest
/// freely.
type_visit_stack: std.ArrayListUnmanaged(Var),
/// Explicit worklist for alias row validation, carrying both pending nodes and
/// in-flight row frames so the whole walk—spines and rows alike—descends on
/// the heap rather than the native stack. Base-relative, like the stack above.
alias_row_frames: std.ArrayListUnmanaged(AliasRowFrame),
/// Row field/tag names collected by the row frames in flight, one contiguous
/// run per frame.
alias_row_names: std.ArrayListUnmanaged(Ident.Idx),
/// A map from one var to another. Used to apply type arguments in instantiation
rigid_var_substitutions: std.AutoHashMapUnmanaged(Ident.Idx, Var),
/// Exact receiver/argument ordinal paired with each annotation substitution.
/// Populated by the same source traversal that builds the variable map.
rigid_var_substitution_origins: std.AutoHashMapUnmanaged(Ident.Idx, u32) = .empty,
/// Header rigid vars for the currently-processed type declaration.
/// Used to resolve rigid vars in local type decl bodies that were not
/// rewritten as rigid_var_lookup during canonicalization.
type_decl_rigid_vars: std.AutoHashMapUnmanaged(Ident.Idx, Var),
/// Default expressions recorded at annotation/type-decl materialization and
/// CHECKED at finalize (design.md "Defaulted Fields"): materialization can
/// run before check order exists (type-decl generation, scheme
/// predeclaration) and before callee effects resolve, so typing the default
/// against its field, judging purity, and (later) concreteness all wait
/// until every def is checked. Deduplicated by expression node.
pending_default_checks: std.ArrayList(PendingDefaultCheck),
/// `.?field` accesses, judged at every generalization boundary (and at
/// finalize as backstop): a required/defaulted receiver field is rejected
/// (`.?` on an always-present field), and a still-flex kind pins to
/// `optional` BEFORE the scheme forms, so instantiated copies of a
/// generalized function's rows carry the concrete kind (design.md "Field
/// Kinds"). Entries owned by an enclosing rank remain pending for that
/// rank's boundary; judged entries are removed.
optional_field_accesses: std.ArrayList(OptionalFieldAccess),
/// Field-kind vars minted by record LITERALS (the fresh flex `.unknown`
/// presence every literal field gets), recorded at the mint site so the
/// finalize sweep (`defaultLiteralFieldKinds`) can commit still-undetermined
/// MONOMORPHIC kinds to `required` from explicit data instead of walking the
/// type store (design.md "Field Kinds"—kind defaulting as a checker pass).
/// `.?`-minted kind vars are deliberately NOT recorded here:
/// `judgeOptionalFieldAccesses` owns those and pins them to `optional`.
/// `literal_field_kind_watermark` tracks the swept prefix (REPL sessions
/// finalize repeatedly on one Check).
literal_field_kinds: std.ArrayList(LiteralFieldKind),
literal_field_kind_watermark: usize = 0,
/// Update-field probes are committed at their owning generalization boundary
/// so an unresolved scheme cannot change runtime field layout per caller.
pending_record_updates: std.ArrayList(PendingRecordUpdate),
/// Record-destructure fields pending the kind-directed binder judgment
/// (design.md "Field Kinds"): each destructured field probes the record with
/// a kind-FLEXIBLE fresh presence var (the same mint as a record update's
/// probe), and the field's value type in the row is a FRESH payload var the
/// binder is deliberately NOT unified with at pattern-check time. Judged by
/// `judgeRecordDestructBinds` at every generalization boundary (immediately
/// after `judgeOptionalFieldAccesses`, so `.?`-driven optional pins land
/// first) and at finalize: a kind resolved `required`/`defaulted` binds the
/// binder to the payload plainly; `optional` binds it to
/// `Try(payload, [MissingField])`; a still-flex kind pins `required` first
/// (destructuring must not silently make a field optional) and binds
/// plainly. Deliberately NOT recorded in `literal_field_kinds`: the kind
/// decision belongs to this judgment, not the finalize defaulting sweep
/// (double-commit ordering hazard). Judged entries are removed; an entry
/// whose kind is still flex at a boundary that does not own its rank is
/// retained for the scope that does (see `judgeRecordDestructBinds`).
pending_record_destructs: std.ArrayList(PendingRecordDestruct),
pending_default_seen: std.AutoHashMapUnmanaged(CIR.Expr.Idx, void) = .{},
/// True while `predeclareAnnotationScheme` materializes an annotation ahead
/// of all body checking: a defaulted field's kind (identity) is minted as
/// usual, but its default EXPRESSION is not checked—the body-pass
/// generation types it exactly once, after dependency-ordered defs are
/// checked (design.md "Defaulted Fields").
predeclaring_annotation: bool = false,
/// Type declaration bodies are generated on demand so forward references
/// instantiate fully generated declarations instead of predeclared shells.
type_decl_generation_states: std.ArrayListUnmanaged(TypeDeclGenerationState) = .empty,
/// Dense declaration index for each CIR node, or `no_type_decl_dense_index`.
type_decl_dense_indices: std.ArrayListUnmanaged(u32) = .empty,
/// CIR statement for each dense declaration index.
type_decl_statements: std.ArrayListUnmanaged(CIR.Statement.Idx) = .empty,
/// Local annotation-generation failure, closed transitively during finalization.
type_decl_invalid: std.ArrayListUnmanaged(bool) = .empty,
/// Directed references from one local type declaration to another.
type_decl_dependencies: std.ArrayListUnmanaged(TypeDeclDependency) = .empty,
/// scratch vars used to build up intermediate lists, used for various things
scratch_vars: base.Scratch(Var),
/// scratch (parameter name, instantiated flex copy) pairs for the default
/// parameter-constraint judgment (`checkDefaultParameterConstraints`)
scratch_default_param_vars: base.Scratch(DefaultParamVar),
/// scratch tags used to build up intermediate lists, used for various things
scratch_tags: base.Scratch(types_mod.Tag),
/// scratch record fields used to build up intermediate lists, used for various things
scratch_record_fields: base.Scratch(types_mod.RecordField),
/// scratch record-field value-type vars, copied out of the record-fields store
/// so a graph walk can iterate them while its loop body reallocates that store
/// (see `dupeRecordFieldTypeVars`). Used as a stack: each copy pushes a batch and
/// its caller releases it with `clearFrom`, so nested/recursive copies compose.
scratch_record_field_vars: base.Scratch(Var),
/// scratch static dispatch constraints used to build up intermediate lists, used for various things
scratch_static_dispatch_constraints: base.Scratch(ScratchStaticDispatchConstraint),
/// scratch deferred static dispatch constraints
scratch_deferred_static_dispatch_constraints: base.Scratch(DeferredConstraintCheck),
/// Concrete generated-codec obligations parked until the module's single type
/// finalization point. Their receiver can still gain nominal layers while
/// later definitions are checked, so validating them earlier would publish a
/// derivation for a shape that is no longer the call's final type.
final_codec_dispatch_constraints: std.ArrayListUnmanaged(FinalCodecDispatchConstraint) = .empty,
final_codec_dispatch_constraint_fns: std.AutoHashMapUnmanaged(Var, void) = .empty,
checking_final_codec_dispatch_constraints: bool = false,
// Cache for imported types. This cache lives for the entire type-checking session
/// of a module, so the same imported type can be reused across the entire module.
import_cache: ImportCache,
/// Exact canonicalization-authored external lookup stream admitted before the
/// checker can rewrite an associated lookup in place. The final producer gate
/// byte-compares this snapshot so no checker path can add, remove, or retarget
/// a token after its complete nine-kind inverse was replayed.
external_lookup_token_snapshot: []ModuleEnv.ExternalLookupToken,
/// Exact cache insertions performed inside nested Probe scopes. Inner commits
/// retain their suffix so an outer rollback can still remove the entries;
/// only the outermost commit discards the undo history.
import_cache_insertion_journal: std.ArrayListUnmanaged(ImportCacheKey) = .empty,
/// Generalized imported method schemes copied into this solver exactly once.
/// Each use still instantiates from this immutable scheme, so polymorphic uses
/// remain fresh without recopied import graphs. The append-only log gives
/// speculative probes an exact rollback boundary.
imported_method_schemes: std.ArrayListUnmanaged(ImportedMethodScheme) = .empty,
imported_method_scheme_by_source: std.AutoHashMapUnmanaged(ImportedMethodSchemeKey, u32) = .empty,
/// Exact associated-item targets keyed by the alias declaration type var and
/// item. Alias traversal and owner-scope lookup happen once per declaration.
associated_lookup_cache: std.AutoHashMapUnmanaged(AssociatedLookupCacheKey, ?AssociatedLookupResolution) = .empty,
/// Copied Bool type from Bool module (for use in if conditions, etc.)
bool_var: Var,
/// Copied Str type from Builtin module (for use in string literals, etc.)
str_var: Var,
/// Copied U64 type from Builtin module (for generated structural metadata counts, etc.)
u64_var: Var,
/// Builtin type vars are initialized during Check.init and may be reused by later entrypoints.
builtin_types_copied: bool,
/// Map representation of Ident -> Var, used in checking static dispatch constraints
ident_to_var_map: std.AutoHashMap(Ident.Idx, Var),
/// Interpolation metadata ranges whose occurrence-specific custom part checks
/// have already run.
checked_interpolation_part_constraints: std.AutoHashMap(InterpolationPartsIdx, void),
/// Vars that originated as single-quote (.int_unbound) literals.
int_unbound_vars: std.AutoHashMap(Var, void),
/// Dispatcher/method pairs already reported by `reportConstraintError`, so a
/// constraint failing in multiple passes (or reachable through several aliased
/// type variables) is reported once.
reported_constraint_errors: std.AutoHashMap(ReportedConstraintError, void),
/// Sparse effect slots for actual expect bodies. Static-dispatch watchers name
/// these slots; constraint copying and unification therefore cannot manufacture
/// or lose an expect context.
expect_effect_slots: std.ArrayListUnmanaged(ExpectEffectSlot),
expect_dispatch_effect_watchers: std.ArrayListUnmanaged(ExpectDispatchWatcher),
successful_dispatch_fn_vars: std.ArrayListUnmanaged(Var),
current_expect_effect_slot: ?ExpectEffectSlotId,
/// Dense table of top-level patterns, and whether their defs have been processed.
top_level_ptrns: std.ArrayListUnmanaged(?DefProcessed),
/// Read-only platform requirement surface used only when checking an app root.
platform_requirements: ?PlatformRequirementInput,
/// How this module's compile-time roots are established, which decides
/// whether an app root's entrypoint contract with its platform is enforced
/// here. See `can.Can.Validation`.
validation: can.Can.Validation = .checking,
/// App defs constrained by platform requirements before their bodies are checked.
platform_required_defs: std.AutoHashMapUnmanaged(CIR.Def.Idx, PlatformRequiredDef),
/// One row per platform requirement that resolved to an exported app def, in
/// requires-clause order. The solved correspondence (requirement type and its
/// identity bindings, as vars in this module's store) that publication
/// materializes into the app artifact's `PlatformRequirementSolutionTable`.
/// Each row's `identity_vars` slice is checker-owned.
platform_requirement_solutions: std.ArrayListUnmanaged(requirement_solution.SolutionInput),
/// Local block-statement (`s_decl`) function patterns whose body is currently
/// being type-checked. Used to detect self-recursion (and references to an
/// enclosing in-flight def) of LOCAL function defs: an unannotated in-flight
/// reference unifies monomorphically with the pattern var—the same
/// binding-group recursion rule as top-level defs—which is why a
/// self-capturing local `s_decl` is checked inside its own rank frame (the
/// pattern var lives in that frame, so the monomorphic links generalize with
/// the def at the frame's exit). An annotated local def's scheme is
/// pre-declared before its body, so its in-flight references instantiate the
/// scheme instead. Analogous to `top_level_ptrns` but for block-local defs.
///
/// Presence == "currently being checked"; absence == normal
/// lookup/instantiate. A reference can only resolve to the current def or an
/// enclosing in-flight one: forward references to a *later* sibling, and local
/// mutual recursion, are rejected during canonicalization (local defs are
/// sequentially scoped), so this is always a single self/enclosing chain.
local_processing_ptrns: std.AutoHashMapUnmanaged(CIR.Pattern.Idx, LocalDefProcessed) = .{},

/// Every local binding root (`x = ..` / `var x = ..` statement pattern)
/// encountered while checking, in solve order. The settled-state occurs sweep
/// checks these alongside the top-level defs: a local binding's cyclic type
/// may never be reachable from the enclosing def's root type, and checking
/// earlier would be premature because later constraints in the same statement
/// can still determine the root's final graph.
local_binding_roots: std.ArrayListUnmanaged(CIR.Pattern.Idx) = .empty,
/// The name of the enclosing function, if known.
/// Used to provide better error messages when type checking lambda arguments.
enclosing_func_name: ?Ident.Idx,
/// Type writer for formatting types at snapshot time
type_writer: types_mod.TypeWriter,
/// --- Dependency-ordered driver state ---
///
/// Type checking processes top-level defs as binding groups: the SCC
/// condensation of canonicalization's name-reference graph, in deterministic
/// topological order (see `DependencyGraph.computeCheckOrder`). A name
/// reference between groups therefore always points at an already-checked
/// def. Static-dispatch dependencies are type-directed and cannot be in the
/// name graph; when one resolves to an unchecked, unannotated local def, the
/// obligation is recorded in `pending_dispatch_targets` and resolved at the
/// current group's generalization boundary by checking the target's group in
/// its own frame—never by re-entering `checkDef` mid-body.
///
/// Checking order for the current module's top-level defs. Owned; freed in
/// `deinit`. Transient: computed when file checking starts, never part of
/// the checked module.
check_order: ?DependencyGraph.EvaluationOrder = null,
/// A Check owns one solver run. Mutable-cache checking constructs a fresh
/// Check over the deserialized ModuleEnv; re-entering a completed Check would
/// reuse checked group state while rerunning destructive predeclaration.
check_file_started: bool = false,
/// Which check-order group each top-level def belongs to.
def_group: std.ArrayListUnmanaged(u32) = .empty,
/// Per-group progress; a `.checking` group has a frame on `group_stack`.
group_states: std.ArrayListUnmanaged(GroupState) = .empty,
/// Groups currently being checked, outermost first. Nesting happens only at
/// group generalization boundaries (Invariant E): a dispatch obligation whose
/// target group is unchecked suspends the current group at its boundary,
/// checks the target group in a deeper frame, and resumes. Group merge for
/// dispatch cycles needs no dedicated structure: a suspended group's members
/// are `.processed` but not yet generalized, so a back-reference links to
/// their still-live vars monomorphically and rank adjustment keeps the shared
/// structure at the suspended group's rank, where it generalizes when that
/// group's boundary completes.
group_stack: std.ArrayListUnmanaged(GroupFrame) = .empty,
/// Dispatch obligations whose targets are unchecked, unannotated local defs,
/// owned by the group that discovered them (stack-suffix discipline: entries
/// at index >= the owning frame's `pending_targets_top` belong to that frame).
pending_dispatch_targets: std.ArrayListUnmanaged(CIR.Def.Idx) = .empty,
/// Uses of a predeclared annotation made before the annotated body has
/// published its complete scheme. The annotation supplies the type shape
/// immediately; the owning group boundary checks the target body and replays
/// the use with any body-inferred dispatch requirements before generalizing.
pending_predeclared_scheme_uses: std.ArrayListUnmanaged(PendingPredeclaredSchemeUse) = .empty,
/// Explicit generalized schemes whose type has pending static-dispatch
/// requirements not structurally reachable from the type root. Requirements
/// are copied under the same substitution as the root at every use.
type_schemes: std.ArrayListUnmanaged(TypeScheme) = .empty,
/// Active scheme lookup by stable source vars. Union-find representatives are
/// deliberately not identities: unification may replace one at any time. Each
/// binding explicitly registers its expression, pattern, and definition vars
/// against the same scheme index, and retirement removes all of those aliases.
type_scheme_by_var: std.AutoHashMapUnmanaged(Var, u32) = .empty,
/// Source-node identities that checking has explicitly classified as rank-1
/// polymorphic bindings. This is deliberately separate from descriptor rank:
/// a partially generalized scheme may have a monomorphic structural root.
/// The dense node table keeps ordinary local lookup O(1).
binding_scheme_nodes: std.DynamicBitSetUnmanaged,
/// Scheme identities without a source node, currently pristine annotation
/// schemes created by the annotated-definition pre-pass.
synthetic_binding_schemes: std.AutoHashMapUnmanaged(Var, void) = .empty,
/// Reused exact graph walk for classifying a freshly generalized binding.
/// Classification happens once at the producer boundary, never on lookup.
binding_scheme_classification_seen: std.AutoHashMapUnmanaged(Var, void) = .empty,
binding_scheme_classification_stack: std.ArrayListUnmanaged(Var) = .empty,
/// Constraint function vars whose deferred relation was actually consumed by
/// static-dispatch checking (success or rejection). Receiver shape alone is not
/// evidence of discharge: an unrelated error can poison the receiver, and a
/// relation may be concrete before its place in the worklist is visited.
settled_static_dispatch_constraint_fns: std.AutoHashMapUnmanaged(Var, void) = .empty,
/// Dispatch requirements discovered while checking a prospective scheme.
/// Candidates live in an append-only arena while any prospective owner is
/// active, and the owner index lets each generalization boundary visit only its
/// own entries. Probe rollback removes speculative tail entries from both.
scheme_requirement_candidates: std.ArrayListUnmanaged(SchemeRequirementCandidate) = .empty,
