}

/// These record-update rows transport an already-owned ExpectedFailure cause;
/// they do not become a second owner of that failure publication.
fn recordUpdateExpectedPlanCarriesCausalReference(
    plan: ModuleEnv.ExpectedConsumptionPlan,
) bool {
    return plan.decodedOutcome() == .source_root_copy_checked_error or
        plan.decodedReason() == .record_update_field_base_checked_error;
}

fn expectedFailuresEqual(
    left: ModuleEnv.ExpectedFailure,
    right: ModuleEnv.ExpectedFailure,
) bool {
    inline for (.{
        "owner_node",
        "site_node",
        "owner_kind",
        "kind",
        "raw_owner_var",
        "raw_subject_var",
        "raw_peer_var",
        "constraint_index",
        "slot",
        "plan_index",
        "reserved_0",
    }) |field_name| {
        if (@field(left, field_name) != @field(right, field_name)) return false;
    }
    return expectedSubjectAuthoritiesEqual(left.subject_authority, right.subject_authority) and
        expectedCauseOwnersEqual(left.cause_owner, right.cause_owner);
}

fn expectedRetirementKeyLessThan(
    retirements: []const ModuleEnv.ExpectedConsumerRetirement,
    left_index: u32,
    right_index: u32,
) bool {
    const left = retirements[left_index];
    const right = retirements[right_index];
    if (left.owner_kind != right.owner_kind) return left.owner_kind < right.owner_kind;
    if (left.retired_node != right.retired_node) return left.retired_node < right.retired_node;
    return left_index < right_index;
}

fn expectedFailureRetirementOrderIsCanonical(
    failures: []const ModuleEnv.ExpectedFailure,
    retirements: []const ModuleEnv.ExpectedConsumerRetirement,
    retirement_failures: []const ModuleEnv.ExpectedRetirementFailure,
) bool {
    var consumed_failures: usize = 0;
    var consumed_retirements: usize = 0;
    while (consumed_failures != failures.len or consumed_retirements != retirements.len) {
        var best_failure: ?u32 = null;
        for (failures, 0..) |failure, failure_index| {
            if (failure_index < consumed_failures) continue;
            if (failure.decodedKind() == .direct_binder_lookup_checked_error) {
                const direct = failure.subject_authority.decodedDirect() orelse continue;
                if (failure.subject_authority.decodedDirectPhase() !=
                    .direct_binder_lookup_checked_error or
                    direct.local_record_index >= consumed_failures)
                {
                    continue;
                }
            }
            if (failure.cause_owner.decodedExpectedFailure()) |cause| {
                if (cause.index >= consumed_failures) continue;
            }
            if (failure.cause_owner.decodedExpectedConsumerRetirement()) |cause| {
                if (cause.index >= consumed_retirements) continue;
            }
            const candidate: u32 = @intCast(failure_index);
            if (best_failure == null or expectedFailureKeyLessThan(
                failures,
                candidate,
                best_failure.?,
            )) {
                best_failure = candidate;
            }
        }
        if (best_failure) |selected| {
            if (selected != consumed_failures) return false;
            consumed_failures += 1;
            continue;
        }

        var best_retirement: ?u32 = null;
        for (retirements, 0..) |retirement, retirement_index| {
            if (retirement_index < consumed_retirements) continue;
            const start: usize = retirement.expected_failures_start;
            const len: usize = retirement.expected_failures_len;
            if (start > retirement_failures.len or len > retirement_failures.len - start) return false;
            var causes_ready = true;
            for (retirement_failures[start..][0..len]) |cause| {
                if (cause.failure_index >= consumed_failures) {
                    causes_ready = false;
                    break;
                }
            }
            if (!causes_ready) continue;
            const candidate: u32 = @intCast(retirement_index);
            if (best_retirement == null or expectedRetirementKeyLessThan(
                retirements,
                candidate,
                best_retirement.?,
            )) {
                best_retirement = candidate;
            }
        }
        const selected = best_retirement orelse return false;
        if (selected != consumed_retirements) return false;
        consumed_retirements += 1;
    }
    return true;
}

fn expectedCauseOwnerIsLocallyValid(
    cir: *const ModuleEnv,
    cause: ModuleEnv.CauseOwner,
) bool {
    const required = cause.kind != ModuleEnv.CauseOwner.none;
    if (!cause.hasCanonicalTags(required)) return false;
    return switch (cause.decodedKind() orelse return true) {
        .expected_failure => cause.payload.expected_failure.index < cir.expected_failures.items.items.len,
        .expected_consumer_retirement => cause.payload.expected_consumer_retirement.index <
            cir.expected_consumer_retirements.items.items.len,
        .cir_diagnostic => cir.store.isDiagnosticIndex(
            @enumFromInt(cause.payload.cir_diagnostic.index),
        ),
        .provider_where_alias_checked_error => true,
    };
}

fn invalidTagChildExpectedFailureIsLocallyValid(
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    direct: ModuleEnv.SubjectAuthority.Direct,
) bool {
    const diagnostic = failure.cause_owner.decodedCirDiagnostic() orelse return false;
    if (direct.local_record_index >=
        cir.body_annotation_malformed_type_publications.items.items.len)
    {
        return false;
    }
    const publication = cir.body_annotation_malformed_type_publications.items.items[
        direct.local_record_index
    ];
    if (!bodyAnnotationMalformedTypePublicationIsLocallyValid(cir, publication) or
        publication.body_expr != failure.owner_node or
        failure.raw_owner_var != @intFromEnum(ModuleEnv.varFrom(
            @as(CIR.Expr.Idx, @enumFromInt(publication.body_expr)),
        )) or
        publication.malformed_type_publication_index >=
            cir.malformed_type_annotation_publications.items.items.len)
    {
        return false;
    }

    const attachment_kind = publication.decodedAttachmentKind() orelse return false;
    const annotation_idx: CIR.Annotation.Idx = @enumFromInt(publication.annotation_root);
    const attachment_index = cir.bodyAnnotationAttachmentIndex(
        attachment_kind,
        publication.attachment_node,
        annotation_idx,
        @enumFromInt(publication.body_expr),
    ) orelse return false;

    if (cir.store.nodes.get(@enumFromInt(direct.producer_node)).tag != .ty_tag_union) {
        return false;
    }
    const parent_idx: CIR.TypeAnno.Idx = @enumFromInt(direct.producer_node);
    if (!cir.bodyAnnotationAttachmentContainsTypeAnno(attachment_index, parent_idx) or
        failure.raw_subject_var != @intFromEnum(ModuleEnv.varFrom(parent_idx)))
    {
        return false;
    }
    const parent = cir.store.getTypeAnno(parent_idx);
    const tag_children = cir.store.sliceTypeAnnos(parent.tag_union.tags);
    const child_offset: usize = @intCast(failure.slot);
    if (child_offset >= tag_children.len) return false;

    const malformed_publication = cir.malformed_type_annotation_publications.items.items[
        publication.malformed_type_publication_index
    ];
    if (malformed_publication.annotation_node != @intFromEnum(tag_children[child_offset]) or
        malformed_publication.diagnostic_index != diagnostic.index)
    {
        return false;
    }
    if (publication.decodedAttachmentKind().? == .local_var and
        cir.store.getAnnotation(annotation_idx).introduces_type_var)
    {
        return false;
    }
    return true;
}

fn invalidTagChildExpectedFailureMatchesFresh(
    env: *const ModuleEnv,
    resolution_env: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    direct: ModuleEnv.SubjectAuthority.Direct,
) bool {
    if (!invalidTagChildExpectedFailureIsLocallyValid(env, failure, direct) or
        direct.local_record_index >=
            resolution_env.body_annotation_malformed_type_publications.items.items.len or
        direct.producer_node >= resolution_env.store.nodes.len() or
        resolution_env.store.nodes.get(@enumFromInt(direct.producer_node)).tag != .ty_tag_union)
    {
        return false;
    }

    const publication = env.body_annotation_malformed_type_publications.items.items[
        direct.local_record_index
    ];
    const fresh_publication = resolution_env.body_annotation_malformed_type_publications.items.items[
        direct.local_record_index
    ];
    if (!std.meta.eql(publication, fresh_publication) or
        !bodyAnnotationMalformedTypePublicationIsLocallyValid(
            resolution_env,
            fresh_publication,
        ))
    {
        return false;
    }

    const parent_idx: CIR.TypeAnno.Idx = @enumFromInt(direct.producer_node);
    const parent = env.store.getTypeAnno(parent_idx);
    const fresh_parent = resolution_env.store.getTypeAnno(parent_idx);
    if (!std.meta.eql(parent, fresh_parent)) return false;
    const tag_children = env.store.sliceTypeAnnos(parent.tag_union.tags);
    const fresh_tag_children = resolution_env.store.sliceTypeAnnos(fresh_parent.tag_union.tags);
    if (!std.mem.eql(CIR.TypeAnno.Idx, tag_children, fresh_tag_children)) return false;

    const attachment_kind = fresh_publication.decodedAttachmentKind() orelse return false;
    const fresh_attachment_index = resolution_env.bodyAnnotationAttachmentIndex(
        attachment_kind,
        fresh_publication.attachment_node,
        @enumFromInt(fresh_publication.annotation_root),
        @enumFromInt(fresh_publication.body_expr),
    ) orelse return false;
    if (!resolution_env.bodyAnnotationAttachmentContainsTypeAnno(
        fresh_attachment_index,
        parent_idx,
    )) {
        return false;
    }

    if (fresh_publication.malformed_type_publication_index >=
        resolution_env.malformed_type_annotation_publications.items.items.len)
    {
        return false;
    }
    const fresh_malformed_publication = resolution_env.malformed_type_annotation_publications.items.items[
        fresh_publication.malformed_type_publication_index
    ];
    if (!malformedTypeAnnotationPublicationIsLocallyValid(
        resolution_env,
        fresh_malformed_publication,
    )) {
        return false;
    }
    const child_offset: usize = @intCast(failure.slot);
    return child_offset < fresh_tag_children.len and
        fresh_malformed_publication.annotation_node ==
            @intFromEnum(fresh_tag_children[child_offset]) and
        fresh_malformed_publication.diagnostic_index ==
            (failure.cause_owner.decodedCirDiagnostic() orelse return false).index;
}

fn malformedWhereClauseDiagnosticIsLocallyValid(
    cir: *const ModuleEnv,
    where_idx: CIR.WhereClause.Idx,
    diagnostic_idx: CIR.Diagnostic.Idx,
) bool {
    const raw_where: u32 = @intFromEnum(where_idx);
    if (raw_where >= cir.store.nodes.len() or
        cir.store.nodes.get(ModuleEnv.nodeIdxFrom(where_idx)).tag != .where_malformed or
        !cir.store.isDiagnosticIndex(diagnostic_idx))
    {
        return false;
    }
    const clause = cir.store.getWhereClause(where_idx);
    if (clause != .w_malformed or clause.w_malformed.diagnostic != diagnostic_idx) return false;
    return switch (cir.store.getDiagnostic(diagnostic_idx)) {
        .malformed_where_clause => |malformed| std.meta.eql(
            malformed.region,
            cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(where_idx)),
        ),
        else => false,
    };
}

fn malformedWhereSpanMatchesFresh(
    env: *const ModuleEnv,
    where: CIR.WhereClause.Span,
    resolution_env: *const ModuleEnv,
    fresh_where: CIR.WhereClause.Span,
) bool {
    if (!std.meta.eql(where, fresh_where) or
        !rangeFits(where.span.start, where.span.len, env.store.index_data.items.items.len) or
        !rangeFits(fresh_where.span.start, fresh_where.span.len, resolution_env.store.index_data.items.items.len) or
        !rangeFits(where.owners.span.start, where.owners.span.len, env.store.where_clause_owners.items.items.len) or
        !rangeFits(
            fresh_where.owners.span.start,
            fresh_where.owners.span.len,
            resolution_env.store.where_clause_owners.items.items.len,
        ))
    {
        return false;
    }
    if (!std.mem.eql(
        CIR.WhereClause.Idx,
        env.store.sliceWhereClauses(where),
        resolution_env.store.sliceWhereClauses(fresh_where),
    )) return false;
    const owners = env.store.sliceWhereClauseOwners(where);
    const fresh_owners = resolution_env.store.sliceWhereClauseOwners(fresh_where);
    if (owners.len != fresh_owners.len) return false;
    for (owners, fresh_owners) |owner, fresh_owner| {
        if (!std.meta.eql(owner, fresh_owner)) return false;
    }
    return true;
}

fn malformedWhereExpectedFailureIsLocallyValid(
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    direct: ModuleEnv.SubjectAuthority.Direct,
) bool {
    const diagnostic = failure.cause_owner.decodedCirDiagnostic() orelse return false;
    if (direct.local_record_index >= cir.body_annotation_attachments.items.items.len or
        !cir.bodyAnnotationAttachmentIsLocallyValid(direct.local_record_index))
    {
        return false;
    }
    const attachment = cir.body_annotation_attachments.items.items[direct.local_record_index];
    if (attachment.body_expr != failure.owner_node or
        failure.raw_owner_var != @intFromEnum(ModuleEnv.varFrom(
            @as(CIR.Expr.Idx, @enumFromInt(attachment.body_expr)),
        )) or
        direct.producer_node != failure.site_node)
    {
        return false;
    }

    const annotation_idx: CIR.Annotation.Idx = @enumFromInt(attachment.annotation_root);
    const annotation = cir.store.getAnnotation(annotation_idx);
    if (failure.raw_subject_var != @intFromEnum(ModuleEnv.varFrom(annotation.anno)) or
        (attachment.decodedAttachmentKind() == .local_var and annotation.introduces_type_var))
    {
        return false;
    }
    const where = annotation.where orelse return false;
    if (!rangeFits(where.span.start, where.span.len, cir.store.index_data.items.items.len)) return false;
    const clauses = cir.store.sliceWhereClauses(where);
    const slot: usize = failure.slot;
    if (slot >= clauses.len) return false;
    const where_idx = clauses[slot];
    if (@intFromEnum(where_idx) != failure.site_node or
        !cir.bodyAnnotationAttachmentContainsWhereClause(direct.local_record_index, where_idx))
    {
        return false;
    }
    return malformedWhereClauseDiagnosticIsLocallyValid(
        cir,
        where_idx,
        @enumFromInt(diagnostic.index),
    );
}

fn malformedWhereExpectedFailureMatchesFresh(
    env: *const ModuleEnv,
    resolution_env: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    direct: ModuleEnv.SubjectAuthority.Direct,
) bool {
    if (!malformedWhereExpectedFailureIsLocallyValid(env, failure, direct) or
        direct.local_record_index >= resolution_env.body_annotation_attachments.items.items.len or
        !resolution_env.bodyAnnotationAttachmentIsLocallyValid(direct.local_record_index))
    {
        return false;
    }
    const attachment = env.body_annotation_attachments.items.items[direct.local_record_index];
    const fresh_attachment = resolution_env.body_annotation_attachments.items.items[direct.local_record_index];
    if (!std.meta.eql(attachment, fresh_attachment)) return false;

    const annotation_idx: CIR.Annotation.Idx = @enumFromInt(attachment.annotation_root);
    const annotation = env.store.getAnnotation(annotation_idx);
    const fresh_annotation = resolution_env.store.getAnnotation(annotation_idx);
    if (!std.meta.eql(annotation, fresh_annotation)) return false;
    const where = annotation.where orelse return false;
    const fresh_where = fresh_annotation.where orelse return false;
    if (!malformedWhereSpanMatchesFresh(env, where, resolution_env, fresh_where)) return false;

    const clauses = env.store.sliceWhereClauses(where);
    const fresh_clauses = resolution_env.store.sliceWhereClauses(fresh_where);
    const slot: usize = failure.slot;
    if (slot >= clauses.len or slot >= fresh_clauses.len or clauses[slot] != fresh_clauses[slot]) return false;
    const where_idx = clauses[slot];
    const fresh_where_idx = fresh_clauses[slot];
    if (!std.meta.eql(
        env.store.getWhereClause(where_idx),
        resolution_env.store.getWhereClause(fresh_where_idx),
    )) return false;

    const diagnostic = failure.cause_owner.decodedCirDiagnostic() orelse return false;
    const diagnostic_idx: CIR.Diagnostic.Idx = @enumFromInt(diagnostic.index);
    if (!resolution_env.store.isDiagnosticIndex(diagnostic_idx) or
        !malformedWhereClauseDiagnosticIsLocallyValid(env, where_idx, diagnostic_idx) or
        !malformedWhereClauseDiagnosticIsLocallyValid(resolution_env, fresh_where_idx, diagnostic_idx))
    {
        return false;
    }
    return std.meta.eql(
        env.store.getDiagnostic(diagnostic_idx),
        resolution_env.store.getDiagnostic(diagnostic_idx),
    );
}

const BuiltinNotTypeSite = union(enum) {
    lookup: Ident.Idx,
    apply: struct {
        name: Ident.Idx,
        args: CIR.TypeAnno.Span,
    },
};

fn builtinNotTypeSite(
    cir: *const ModuleEnv,
    raw_site: u32,
) ?BuiltinNotTypeSite {
    if (raw_site >= cir.store.nodes.len()) return null;
    const node = cir.store.nodes.get(@enumFromInt(raw_site));
    const anno_idx: CIR.TypeAnno.Idx = @enumFromInt(raw_site);
    return switch (node.tag) {
        .ty_lookup => switch (cir.store.getTypeAnno(anno_idx)) {
            .lookup => |lookup| switch (lookup.base) {
                .builtin => |builtin_type| if (builtin_type == .num)
                    .{ .lookup = lookup.name }
                else
                    null,
                .local, .external, .pending => null,
            },
            else => null,
        },
        .ty_apply => switch (cir.store.getTypeAnno(anno_idx)) {
            .apply => |apply| switch (apply.base) {
                .builtin => |builtin_type| if (builtin_type == .num)
                    .{ .apply = .{ .name = apply.name, .args = apply.args } }
                else
                    null,
                .local, .external, .pending => null,
            },
            else => null,
        },
        else => null,
    };
}

fn builtinNotTypeExpectedFailureIsLocallyValid(
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    direct: ModuleEnv.SubjectAuthority.Direct,
) bool {
    if (!failure.cause_owner.hasCanonicalTags(false) or
        direct.local_record_index >= cir.body_annotation_attachments.items.items.len or
        !cir.bodyAnnotationAttachmentIsLocallyValid(direct.local_record_index))
    {
        return false;
    }
    const attachment = cir.body_annotation_attachments.items.items[direct.local_record_index];
    if (attachment.body_expr != failure.owner_node or
        failure.raw_owner_var != @intFromEnum(ModuleEnv.varFrom(
            @as(CIR.Expr.Idx, @enumFromInt(attachment.body_expr)),
        )) or
        direct.producer_node != failure.site_node or
        failure.raw_subject_var != @intFromEnum(ModuleEnv.varFrom(
            @as(CIR.TypeAnno.Idx, @enumFromInt(direct.producer_node)),
        )))
    {
        return false;
    }

    const annotation_idx: CIR.Annotation.Idx = @enumFromInt(attachment.annotation_root);
    if (!cir.bodyAnnotationAttachmentContainsTypeAnno(
        direct.local_record_index,
        @enumFromInt(direct.producer_node),
    ) or
        (attachment.decodedAttachmentKind() == .local_var and
            cir.store.getAnnotation(annotation_idx).introduces_type_var))
    {
        return false;
    }
    return builtinNotTypeSite(cir, direct.producer_node) != null;
}

fn builtinNotTypeExpectedFailureMatchesFresh(
    env: *const ModuleEnv,
    resolution_env: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    direct: ModuleEnv.SubjectAuthority.Direct,
) bool {
    if (!builtinNotTypeExpectedFailureIsLocallyValid(env, failure, direct) or
        direct.local_record_index >= resolution_env.body_annotation_attachments.items.items.len or
        !resolution_env.bodyAnnotationAttachmentIsLocallyValid(direct.local_record_index))
    {
        return false;
    }
    const attachment = env.body_annotation_attachments.items.items[direct.local_record_index];
    const fresh_attachment = resolution_env.body_annotation_attachments.items.items[
        direct.local_record_index
    ];
    if (!std.meta.eql(attachment, fresh_attachment) or
        !resolution_env.bodyAnnotationAttachmentContainsTypeAnno(
            direct.local_record_index,
            @enumFromInt(direct.producer_node),
        ))
    {
        return false;
    }

    const candidate = builtinNotTypeSite(env, direct.producer_node) orelse return false;
    const fresh_site = builtinNotTypeSite(resolution_env, direct.producer_node) orelse return false;
    return switch (candidate) {
        .lookup => |name| switch (fresh_site) {
            .lookup => |fresh_name| identTextMatchesFresh(
                env,
                name,
                resolution_env,
                fresh_name,
            ),
            .apply => false,
        },
        .apply => |apply| switch (fresh_site) {
            .lookup => false,
            .apply => |fresh_apply| blk: {
                if (!identTextMatchesFresh(
                    env,
                    apply.name,
                    resolution_env,
                    fresh_apply.name,
                ) or
                    !std.meta.eql(apply.args, fresh_apply.args) or
                    !rangeFits(
                        apply.args.span.start,
                        apply.args.span.len,
                        env.store.index_data.items.items.len,
                    ) or
                    !rangeFits(
                        fresh_apply.args.span.start,
                        fresh_apply.args.span.len,
                        resolution_env.store.index_data.items.items.len,
                    ))
                {
                    break :blk false;
                }
                break :blk std.mem.eql(
                    CIR.TypeAnno.Idx,
                    env.store.sliceTypeAnnos(apply.args),
                    resolution_env.store.sliceTypeAnnos(fresh_apply.args),
                );
            },
        },
    };
}

fn expectedRetirementOwnsFailure(
    cir: *const ModuleEnv,
    retirement_index: u32,
    failure_index: u32,
) bool {
    if (retirement_index >= cir.expected_consumer_retirements.items.items.len) return false;
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    if (!rangeFits(
        retirement.expected_failures_start,
        retirement.expected_failures_len,
        cir.expected_retirement_failures.items.items.len,
    )) return false;
    var matches: usize = 0;
    for (cir.expected_retirement_failures.items.items[retirement.expected_failures_start..][0..retirement.expected_failures_len]) |owned| {
        if (owned.failure_index == failure_index) matches += 1;
    }
    return matches == 1;
}

fn expectedFailureOwningRetirement(
    cir: *const ModuleEnv,
    failure_index: u32,
) ?u32 {
    var selected: ?u32 = null;
    for (cir.expected_consumer_retirements.items.items, 0..) |retirement, retirement_index| {
        if (!rangeFits(
            retirement.expected_failures_start,
            retirement.expected_failures_len,
            cir.expected_retirement_failures.items.items.len,
        )) return null;
        for (cir.expected_retirement_failures.items.items[retirement.expected_failures_start..][0..retirement.expected_failures_len]) |owned| {
            if (owned.failure_index != failure_index) continue;
            if (selected != null) return null;
            selected = @intCast(retirement_index);
        }
    }
    return selected;
}

fn expectedAnnotationRetirementOwnsFailure(
    cir: *const ModuleEnv,
    retirement_index: u32,
    failure_index: u32,
    owner_node: u32,
) bool {
    if (retirement_index >= cir.expected_consumer_retirements.items.items.len) return false;
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    return retirement.decodedOwnerKind() == .expression and
        retirement.decodedKind() == .checker_rewrite_ineligible and
        retirement.retired_node == owner_node and
        retirement.retired_consumers_start == 0 and
        retirement.retired_consumers_len == 0 and
        retirement.rejection_owner_kind == ModuleEnv.ExpectedConsumerRetirement.none and
        retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none and
        cir.store.isDiagnosticIndex(@enumFromInt(retirement.diagnostic_index)) and
        expectedRetirementOwnsFailure(cir, retirement_index, failure_index);
}

fn bodyAnnotationBindingPattern(
    cir: *const ModuleEnv,
    publication: ModuleEnv.BodyAnnotationMalformedTypePublication,
) ?CIR.Pattern.Idx {
    if (!bodyAnnotationMalformedTypePublicationIsLocallyValid(cir, publication)) return null;
    const pattern: CIR.Pattern.Idx = switch (publication.decodedAttachmentKind() orelse return null) {
        .top_level_def => cir.store.getDef(@enumFromInt(publication.attachment_node)).pattern,
        .local_decl => local: {
            const statement = cir.store.getStatement(@enumFromInt(publication.attachment_node));
            break :local switch (statement) {
                .s_decl => |decl| decl.pattern,
                else => return null,
            };
        },
        .local_var => return null,
    };
    if (cir.store.getPattern(pattern) != .assign) return null;
    return pattern;
}

fn firstMalformedWhereAliasTarget(
    cir: *const ModuleEnv,
    annotation_idx: CIR.Annotation.Idx,
) ?CIR.TypeAnno.Idx {
    return cir.firstMalformedWhereAliasTarget(annotation_idx);
}

fn firstMalformedWhereAliasTargetForRigid(
    cir: *const ModuleEnv,
    annotation_idx: CIR.Annotation.Idx,
    rigid_var: u32,
) ?CIR.TypeAnno.Idx {
    return cir.firstMalformedWhereAliasTargetForOwnedRigid(annotation_idx, rigid_var);
}

fn annotationMalformedFailureForBodyPublication(
    cir: *const ModuleEnv,
    publication_index: u32,
) ?u32 {
    if (publication_index >= cir.body_annotation_malformed_type_publications.items.items.len) {
        return null;
    }
    const publication = cir.body_annotation_malformed_type_publications.items.items[publication_index];
    if (!bodyAnnotationMalformedTypePublicationIsLocallyValid(cir, publication) or
        publication.malformed_type_publication_index >=
            cir.malformed_type_annotation_publications.items.items.len)
    {
        return null;
    }
    const malformed = cir.malformed_type_annotation_publications.items.items[
        publication.malformed_type_publication_index
    ];
    var selected: ?u32 = null;
    for (cir.expected_failures.items.items, 0..) |failure, failure_index| {
        if (failure.decodedKind() != .annotation_malformed_type or
            failure.owner_node != publication.body_expr or
            failure.site_node != malformed.annotation_node or
            failure.cause_owner.decodedCirDiagnostic() == null or
            failure.cause_owner.payload.cir_diagnostic.index != malformed.diagnostic_index)
        {
            continue;
        }
        const direct = failure.subject_authority.decodedDirect() orelse continue;
        if (failure.subject_authority.decodedDirectPhase() != .annotation_malformed_type or
            direct.local_record_index != publication_index)
        {
            continue;
        }
        if (selected != null) return null;
        selected = @intCast(failure_index);
    }
    return selected;
}

const ExpectedLookupRetirementSnapshot = struct {
    retirement_index: u32,
    pattern_idx: CIR.Pattern.Idx,
};

fn expectedLookupRetirementOwningFailure(
    cir: *const ModuleEnv,
    failure_index: u32,
) ?ExpectedLookupRetirementSnapshot {
    const retirement_index = expectedFailureOwningRetirement(cir, failure_index) orelse return null;
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    if (retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_ineligible or
        retirement.decodedOriginalNodeTag() != .expr_var or
        retirement.retired_consumers_start != 0 or retirement.retired_consumers_len != 0 or
        retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.expected_failures_len != 1 or
        !rangeFits(
            retirement.expected_failures_start,
            retirement.expected_failures_len,
            cir.expected_retirement_failures.items.items.len,
        ) or
        cir.expected_retirement_failures.items.items[
            retirement.expected_failures_start
        ].failure_index != failure_index or
        retirement.diagnostic_index == ModuleEnv.ExpectedConsumerRetirement.none or
        !cir.store.isDiagnosticIndex(@enumFromInt(retirement.diagnostic_index)))
    {
        return null;
    }
    const payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    if (!std.mem.allEqual(u8, &payload.expr_var._padding, 0) or
        payload.expr_var.pattern_idx >= cir.store.nodes.len())
    {
        return null;
    }
    return .{
        .retirement_index = retirement_index,
        .pattern_idx = @enumFromInt(payload.expr_var.pattern_idx),
    };
}

fn expectedCallRootTokenForLookupFailure(
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    pattern_idx: CIR.Pattern.Idx,
) ?u32 {
    var selected: ?u32 = null;
    for (cir.expected_call_slot_tokens.items.items, 0..) |token, token_index| {
        if (!token.hasCanonicalTags() or token.decodedRole() != .root or
            token.site_node != failure.owner_node)
        {
            continue;
        }
        _ = expectedCallInstantiationStepForLookup(
            cir,
            @intCast(token_index),
            pattern_idx,
        ) orelse return null;
        if (selected != null) return null;
        selected = @intCast(token_index);
    }
    return selected;
}

const ExpectedAnnotationLambdaPattern = struct {
    lambda_expr: u32,
    pattern_idx: CIR.Pattern.Idx,
};

const ExpectedAnnotationFunctionFormal = struct {
    annotation_payload: CIR.Node.Payload.Annotation,
    function_payload: CIR.Node.Payload.TyFn,
    formal_raw: u32,
    formal_payload: CIR.Node.Payload.TyRigidVar,
};

/// Read one direct rigid formal only after validating every node and index-data
/// edge needed to reach it. Checked-artifact admission calls this before any
/// typed getter may interpret candidate-controlled payloads.
fn annotationFunctionFormalAtSlot(
    cir: *const ModuleEnv,
    annotation_raw: u32,
    slot: u32,
) ?ExpectedAnnotationFunctionFormal {
    if (annotation_raw >= cir.store.nodes.len()) return null;
    const annotation_node = cir.store.nodes.get(@enumFromInt(annotation_raw));
    if (annotation_node.tag != .annotation) return null;
    const annotation_payload = annotation_node.getPayload().annotation;
    if (annotation_payload.flags.unused != 0 or
        annotation_payload.anno >= cir.store.nodes.len())
    {
        return null;
    }
    const function_node = cir.store.nodes.get(@enumFromInt(annotation_payload.anno));
    if (function_node.tag != .ty_fn) return null;
    const function_payload = function_node.getPayload().ty_fn;
    if (slot >= function_payload.args_len or
        !rangeFits(
            function_payload.args_start,
            function_payload.args_len,
            cir.store.index_data.items.items.len,
        ))
    {
        return null;
    }
    const formal_raw = cir.store.index_data.items.items[function_payload.args_start + slot];
    if (formal_raw >= cir.store.nodes.len()) return null;
    const formal_node = cir.store.nodes.get(@enumFromInt(formal_raw));
    if (formal_node.tag != .ty_rigid_var) return null;
    return .{
        .annotation_payload = annotation_payload,
        .function_payload = function_payload,
        .formal_raw = formal_raw,
        .formal_payload = formal_node.getPayload().ty_rigid_var,
    };
}

fn annotationRetirementDirectPatternAtSlot(
    cir: *const ModuleEnv,
    retirement_index: u32,
    slot: u32,
) ?ExpectedAnnotationLambdaPattern {
    if (retirement_index >= cir.expected_consumer_retirements.items.items.len) return null;
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    if (retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_ineligible)
    {
        return null;
    }
    const original_tag = retirement.decodedOriginalNodeTag() orelse return null;
    const payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    var lambda_expr = retirement.retired_node;
    var lambda_payload: CIR.Node.Payload.ExprLambda = undefined;
    switch (original_tag) {
        .expr_lambda => lambda_payload = payload.expr_lambda,
        .expr_closure => {
            const closure = payload.expr_closure;
            if (!std.mem.allEqual(u8, &closure._padding, 0) or
                closure.closure_data_idx >= cir.store.closure_data.items.items.len)
            {
                return null;
            }
            const closure_data = cir.store.closure_data.items.items[closure.closure_data_idx];
            lambda_expr = closure_data.lambda_idx;
            if (lambda_expr >= cir.store.nodes.len()) return null;
            const lambda_node = cir.store.nodes.get(@enumFromInt(lambda_expr));
            if (lambda_node.tag != .expr_lambda) return null;
            lambda_payload = lambda_node.getPayload().expr_lambda;
        },
        else => return null,
    }
    if (slot >= lambda_payload.args_len or
        !rangeFits(
            lambda_payload.args_start,
            lambda_payload.args_len,
            cir.store.index_data.items.items.len,
        ))
    {
        return null;
    }
    const pattern_raw = cir.store.index_data.items.items[
        lambda_payload.args_start + slot
    ];
    if (pattern_raw >= cir.store.nodes.len()) return null;
    if (cir.store.nodes.get(@enumFromInt(pattern_raw)).tag != .pattern_identifier) return null;
    return .{
        .lambda_expr = lambda_expr,
        .pattern_idx = @enumFromInt(pattern_raw),
    };
}

fn directBinderLookupExpectedFailureIsLocallyValid(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    failure_index: u32,
    direct: ModuleEnv.SubjectAuthority.Direct,
) bool {
    if (direct.local_record_index >= failure_index or
        direct.local_record_index >= cir.expected_failures.items.items.len)
    {
        return false;
    }
    const source_failure = cir.expected_failures.items.items[direct.local_record_index];
    if (source_failure.decodedKind() != .annotation_malformed_type or
        !expectedFailureSubjectIsLocallyValid(
            types,
            cir,
            source_failure,
            direct.local_record_index,
        ))
    {
        return false;
    }
    const source_retirement = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return false;
    if (!expectedAnnotationRetirementOwnsFailure(
        cir,
        source_retirement.index,
        direct.local_record_index,
        source_failure.owner_node,
    )) {
        return false;
    }
    const source_direct = source_failure.subject_authority.decodedDirect() orelse return false;
    if (source_direct.local_record_index >=
        cir.body_annotation_malformed_type_publications.items.items.len)
    {
        return false;
    }
    const publication = cir.body_annotation_malformed_type_publications.items.items[
        source_direct.local_record_index
    ];
    if (publication.body_expr != source_failure.owner_node or
        source_failure.site_node != @intFromEnum(firstMalformedWhereAliasTargetForRigid(
            cir,
            @enumFromInt(publication.annotation_root),
            failure.raw_peer_var,
        ) orelse return false))
    {
        return false;
    }
    const formal = annotationFunctionFormalAtSlot(
        cir,
        publication.annotation_root,
        failure.slot,
    ) orelse return false;
    if (formal.formal_raw != failure.raw_peer_var) return false;
    const lookup_snapshot = expectedLookupRetirementOwningFailure(cir, failure_index) orelse
        return false;
    const lambda_pattern = annotationRetirementDirectPatternAtSlot(
        cir,
        source_retirement.index,
        failure.slot,
    ) orelse return false;
    return publication.body_expr == cir.expected_consumer_retirements.items.items[
        source_retirement.index
    ].retired_node and
        lookup_snapshot.pattern_idx == lambda_pattern.pattern_idx and
        failure.owner_node == cir.expected_consumer_retirements.items.items[
            lookup_snapshot.retirement_index
        ].retired_node and
        failure.site_node == @intFromEnum(lambda_pattern.pattern_idx) and
        direct.producer_node == failure.site_node and
        failure.raw_owner_var == @intFromEnum(ModuleEnv.varFrom(
            @as(CIR.Expr.Idx, @enumFromInt(failure.owner_node)),
        )) and
        failure.raw_subject_var == @intFromEnum(ModuleEnv.varFrom(lambda_pattern.pattern_idx));
}

fn annotatedBindingLookupExpectedFailureIsLocallyValid(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    failure_index: u32,
    direct: ModuleEnv.SubjectAuthority.Direct,
) bool {
    _ = types;
    if (direct.local_record_index >=
        cir.body_annotation_malformed_type_publications.items.items.len)
    {
        return false;
    }
    const publication = cir.body_annotation_malformed_type_publications.items.items[
        direct.local_record_index
    ];
    const pattern = bodyAnnotationBindingPattern(cir, publication) orelse return false;
    const malformed_target = firstMalformedWhereAliasTarget(
        cir,
        @enumFromInt(publication.annotation_root),
    ) orelse return false;
    if (publication.malformed_type_publication_index >=
        cir.malformed_type_annotation_publications.items.items.len)
    {
        return false;
    }
    const malformed = cir.malformed_type_annotation_publications.items.items[
        publication.malformed_type_publication_index
    ];
    if (malformed.annotation_node != @intFromEnum(malformed_target)) return false;
    const source_failure_index = annotationMalformedFailureForBodyPublication(
        cir,
        direct.local_record_index,
    ) orelse return false;
    const source_retirement = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return false;
    if (!expectedAnnotationRetirementOwnsFailure(
        cir,
        source_retirement.index,
        source_failure_index,
        publication.body_expr,
    )) {
        return false;
    }
    const lookup_snapshot = expectedLookupRetirementOwningFailure(cir, failure_index) orelse
        return false;
    _ = expectedCallRootTokenForLookupFailure(cir, failure, pattern) orelse return false;
    return publication.body_expr == cir.expected_consumer_retirements.items.items[
        source_retirement.index
    ].retired_node and
        lookup_snapshot.pattern_idx == pattern and
        failure.owner_node == cir.expected_consumer_retirements.items.items[
            lookup_snapshot.retirement_index
        ].retired_node and
        failure.site_node == @intFromEnum(pattern) and
        direct.producer_node == failure.site_node and
        failure.raw_owner_var == @intFromEnum(ModuleEnv.varFrom(
            @as(CIR.Expr.Idx, @enumFromInt(failure.owner_node)),
        )) and
        failure.raw_subject_var == @intFromEnum(ModuleEnv.varFrom(pattern)) and
        failure.raw_peer_var == ModuleEnv.ExpectedFailure.none and
        failure.slot == 0;
}

/// Replay the call/slot/formal half of one operand failure without following
/// its lookup cause. Keeping this half nonrecursive lets the owning R_C prove
/// its complete F_C set while each F_C separately performs the full terminal
/// direct-lookup source replay.
fn callOperandExpectedFailureMatchesSnapshot(
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    subject: ModuleEnv.SubjectAuthority.ExpectedPlan,
    call_snapshot: ExpectedCallOperandRetirementSnapshot,
) bool {
    if (failure.decodedKind() != .call_operand_checked_error or
        failure.decodedOwnerKind() != .expression or
        failure.plan_index != subject.plan_index or
        failure.raw_subject_var != subject.raw_var or
        failure.owner_node >= cir.store.nodes.len() or
        failure.site_node >= cir.store.nodes.len() or
        failure.raw_owner_var != failure.owner_node or
        failure.raw_peer_var != failure.site_node or
        failure.constraint_index != ModuleEnv.ExpectedFailure.none)
    {
        return false;
    }
    const plans = cir.expected_consumption_plans.items.items;
    if (call_snapshot.root_plan_index >= plans.len or
        plans[call_snapshot.root_plan_index].owner_node != failure.owner_node or
        failure.slot >= call_snapshot.call.args_len)
    {
        return false;
    }
    const argument_site = cir.store.index_data.items.items[
        call_snapshot.call.args_start + failure.slot
    ];
    if (argument_site != failure.site_node) return false;

    if (subject.plan_index >= plans.len or call_snapshot.root_plan_index >= plans.len or
        !expectedCallArgumentPlanIsTerminal(
            cir,
            .{
                .plan_index = call_snapshot.root_plan_index,
                .plan = plans[call_snapshot.root_plan_index],
                .call = call_snapshot.call,
                .root_token_index = expectedCallSlotTokenIndex(
                    cir,
                    failure.owner_node,
                    .root,
                    ModuleEnv.ExpectedCallSlotToken.none,
                ) orelse return false,
            },
            subject.plan_index,
            failure.slot,
        ))
    {
        return false;
    }
    const root_token_index = expectedCallSlotTokenIndex(
        cir,
        failure.owner_node,
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse return false;
    const slot_token_index = expectedCallSlotTokenIndex(
        cir,
        failure.owner_node,
        .argument,
        failure.slot,
    ) orelse return false;
    const validated_root = ExpectedCallValidatedRoot{
        .plan_index = call_snapshot.root_plan_index,
        .plan = plans[call_snapshot.root_plan_index],
        .call = call_snapshot.call,
        .root_token_index = root_token_index,
    };
    var formal_matches: usize = 0;
    for (cir.expected_call_formals.items.items) |formal| {
        if (formal.owner_node != failure.owner_node or
            formal.argument_plan_index != subject.plan_index or
            formal.slot != failure.slot)
        {
            continue;
        }
        if (!expectedCallFormalMatchesValidatedRoot(
            cir,
            formal,
            validated_root,
            subject.plan_index,
            slot_token_index,
        ) or formal.raw_formal_var != failure.raw_subject_var) {
            return false;
        }
        formal_matches += 1;
    }
    if (formal_matches != 1) return false;

    return true;
}

fn callOperandExpectedFailureIsLocallyValid(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    failure_index: u32,
    subject: ModuleEnv.SubjectAuthority.ExpectedPlan,
) bool {
    const owning_retirement = expectedFailureOwningRetirement(cir, failure_index) orelse
        return false;
    const call_snapshot = expectedCallOperandRetirementSnapshot(
        types,
        cir,
        owning_retirement,
    ) orelse return false;
    if (!callOperandExpectedFailureMatchesSnapshot(
        cir,
        failure,
        subject,
        call_snapshot,
    )) return false;

    const lookup_retirement = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return false;
    const lookup_failure_index = completedDirectBinderLookupFailureForRetirement(
        cir,
        lookup_retirement.index,
    ) orelse return false;
    if (cir.expected_consumer_retirements.items.items[lookup_retirement.index].retired_node !=
        failure.site_node)
    {
        return false;
    }
    const lookup_failure = cir.expected_failures.items.items[lookup_failure_index];
    return directBinderLookupExpectedFailureIsLocallyValid(
        types,
        cir,
        lookup_failure,
        lookup_failure_index,
        lookup_failure.subject_authority.decodedDirect() orelse return false,
    );
}

fn expectedFailureSubjectIsLocallyValid(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    failure: ModuleEnv.ExpectedFailure,
    failure_index: u32,
) bool {
    const authority = failure.subject_authority;
    if (!authority.hasCanonicalTags(true)) return false;
    return switch (authority.decodedKind() orelse return false) {
        .direct => blk: {
            const direct = authority.payload.direct;
            if (direct.producer_node != failure.site_node or
                direct.producer_node >= cir.store.nodes.len())
            {
                break :blk false;
            }
            const phase = authority.decodedDirectPhase() orelse break :blk false;
            break :blk switch (phase) {
                .annotation_malformed_type => malformed: {
                    const diagnostic = failure.cause_owner.decodedCirDiagnostic() orelse
                        break :malformed false;
                    if (direct.local_record_index >=
                        cir.body_annotation_malformed_type_publications.items.items.len)
                    {
                        break :malformed false;
                    }
                    const publication = cir.body_annotation_malformed_type_publications.items.items[
                        direct.local_record_index
                    ];
                    if (!bodyAnnotationMalformedTypePublicationIsLocallyValid(cir, publication) or
                        publication.body_expr != failure.owner_node or
                        failure.raw_owner_var != @intFromEnum(ModuleEnv.varFrom(
                            @as(CIR.Expr.Idx, @enumFromInt(publication.body_expr)),
                        )) or
                        publication.malformed_type_publication_index >=
                            cir.malformed_type_annotation_publications.items.items.len)
                    {
                        break :malformed false;
                    }
                    const malformed_publication = cir.malformed_type_annotation_publications.items.items[
                        publication.malformed_type_publication_index
                    ];
                    if (malformed_publication.annotation_node != direct.producer_node or
                        malformed_publication.diagnostic_index != diagnostic.index or
                        failure.raw_subject_var != @intFromEnum(ModuleEnv.varFrom(
                            @as(CIR.TypeAnno.Idx, @enumFromInt(malformed_publication.annotation_node)),
                        )))
                    {
                        break :malformed false;
                    }
                    if (publication.decodedAttachmentKind().? == .local_var and
                        cir.store.getAnnotation(@enumFromInt(publication.annotation_root)).introduces_type_var)
                    {
                        break :malformed false;
                    }
                    break :malformed true;
                },
                .annotation_malformed_where => malformedWhereExpectedFailureIsLocallyValid(
                    cir,
                    failure,
                    direct,
                ),
                .annotation_invalid_tag_child => invalidTagChildExpectedFailureIsLocallyValid(
                    cir,
                    failure,
                    direct,
                ),
                .annotation_builtin_not_type => builtinNotTypeExpectedFailureIsLocallyValid(
                    cir,
                    failure,
                    direct,
                ),
                .direct_binder_lookup_checked_error => directBinderLookupExpectedFailureIsLocallyValid(
                    types,
                    cir,
                    failure,
                    failure_index,
                    direct,
                ),
                .annotated_binding_lookup_checked_error => annotatedBindingLookupExpectedFailureIsLocallyValid(
                    types,
                    cir,
                    failure,
                    failure_index,
                    direct,
                ),
                .annotation_local_where_alias_checked_error => local_alias: {
                    if (direct.local_record_index >= cir.where_alias_declaration_publications.items.items.len) {
                        break :local_alias false;
                    }
                    const publication = cir.where_alias_declaration_publications.items.items[direct.local_record_index];
                    break :local_alias publication.decodedOutcome() == .checked_error;
                },
                else => direct.local_record_index == ModuleEnv.SubjectAuthority.none,
            };
        },
        .expected_copy_occurrence => blk: {
            const endpoint = authority.payload.expected_copy_occurrence;
            const steps = cir.where_marker_copy_steps.items.items;
            const occurrences = cir.where_marker_copy_occurrences.items.items;
            if (endpoint.copy_step >= steps.len) break :blk false;
            const step = steps[endpoint.copy_step];
            if (endpoint.occurrence_offset >= step.occurrences_len or
                !rangeFits(step.occurrences_start, step.occurrences_len, occurrences.len))
            {
                break :blk false;
            }
            const occurrence = occurrences[step.occurrences_start + endpoint.occurrence_offset];
            const side = authority.decodedExpectedCopySide() orelse break :blk false;
            const raw = switch (side) {
                .source => occurrence.raw_source_var,
                .destination => occurrence.raw_destination_var,
            };
            break :blk raw == failure.raw_subject_var;
        },
        .expected_producer_root_plan => blk: {
            const subject = authority.payload.expected_producer_root_plan;
            if (failure.decodedKind() == .call_operand_checked_error) {
                break :blk callOperandExpectedFailureIsLocallyValid(
                    types,
                    cir,
                    failure,
                    failure_index,
                    subject,
                );
            }
            const plans = cir.expected_consumption_plans.items.items;
            if (subject.plan_index >= plans.len or subject.raw_var >= types.len() or
                subject.raw_var != failure.raw_subject_var)
            {
                break :blk false;
            }
            const plan = plans[subject.plan_index];
            break :blk plan.hasLegalTags() and plan.decodedOutcome() == .producer_root and
                plan.raw_consumer_var == subject.raw_var;
        },
        .expected_evidence_free_plan => blk: {
            const subject = authority.payload.expected_evidence_free_plan;
            const plans = cir.expected_consumption_plans.items.items;
            if (subject.plan_index >= plans.len or subject.raw_var >= types.len() or
                subject.raw_var != failure.raw_subject_var)
            {
                break :blk false;
            }
            const plan = plans[subject.plan_index];
            break :blk plan.hasLegalTags() and plan.raw_consumer_var == subject.raw_var and
                (plan.decodedOutcome() == .evidence_free or
                    (plan.decodedOutcome() == .checked_error and
                        plan.decodedReason() == .aggregate_child_relation_rejected));
        },
        .expected_relation_plan => blk: {
            const subject = authority.payload.expected_relation_plan;
            const plans = cir.expected_consumption_plans.items.items;
            if (subject.plan_index >= plans.len or subject.raw_var >= types.len() or
                subject.raw_var != failure.raw_subject_var)
            {
                break :blk false;
            }
            const plan = plans[subject.plan_index];
            if (!plan.hasLegalTags() or
                plan.decodedRole() != .branch_contribution or
                plan.decodedOutcome() != .related)
            {
                break :blk false;
            }
            const parent_raw = expectedParentAuthorityRawForProof(
                cir,
                plan.parent_authority,
                cir.where_marker_copy_steps.items.items,
                cir.where_marker_copy_occurrences.items.items,
                null,
            ) orelse break :blk false;
            break :blk parent_raw == subject.raw_var;
        },
        // The sealed dependency and provider publication are replayed by the
        // contextual validator; this layer proves only the canonical arm.
        .provider_where_alias_checked_error => true,
    };
}

fn malformedExpressionPublicationIsLocallyValid(
    cir: *const ModuleEnv,
    publication: ModuleEnv.MalformedExpressionPublication,
) bool {
    if (!publication.hasLegalTags() or publication.expr_node >= cir.store.nodes.len()) return false;
    const node = cir.store.nodes.get(@enumFromInt(publication.expr_node));
    return node.tag == .malformed and
        cir.store.isDiagnosticIndex(@enumFromInt(publication.diagnostic_index)) and
        cir.store.getExpr(@enumFromInt(publication.expr_node)).e_runtime_error.diagnostic ==
            @as(CIR.Diagnostic.Idx, @enumFromInt(publication.diagnostic_index));
}

fn malformedExpressionPublicationContains(
    cir: *const ModuleEnv,
    expr_node: u32,
    diagnostic_index: u32,
) bool {
    for (cir.malformed_expression_publications.items.items) |publication| {
        if (publication.expr_node == expr_node and
            publication.diagnostic_index == diagnostic_index)
        {
            return true;
        }
    }
    return false;
}

fn malformedTypeAnnotationPublicationIsLocallyValid(
    cir: *const ModuleEnv,
    publication: ModuleEnv.MalformedTypeAnnotationPublication,
) bool {
    if (!publication.hasLegalTags() or publication.annotation_node >= cir.store.nodes.len()) return false;
    const node = cir.store.nodes.get(@enumFromInt(publication.annotation_node));
    return node.tag == .malformed and
        cir.store.isDiagnosticIndex(@enumFromInt(publication.diagnostic_index)) and
        cir.store.getTypeAnno(@enumFromInt(publication.annotation_node)).malformed.diagnostic ==
            @as(CIR.Diagnostic.Idx, @enumFromInt(publication.diagnostic_index));
}

fn malformedTypeAnnotationPublicationContains(
    cir: *const ModuleEnv,
    annotation_node: u32,
    diagnostic_index: u32,
) bool {
    for (cir.malformed_type_annotation_publications.items.items) |publication| {
        if (publication.annotation_node == annotation_node and
            publication.diagnostic_index == diagnostic_index)
        {
            return true;
        }
    }
    return false;
}

fn malformedTypeAnnotationPublicationIndex(
    cir: *const ModuleEnv,
    annotation_node: u32,
    diagnostic_index: u32,
) ?u32 {
    for (cir.malformed_type_annotation_publications.items.items, 0..) |publication, publication_index| {
        if (publication.annotation_node == annotation_node and
            publication.diagnostic_index == diagnostic_index)
        {
            return @intCast(publication_index);
        }
    }
    return null;
}

fn bodyAnnotationMalformedTypePublicationIsLocallyValid(
    cir: *const ModuleEnv,
    publication: ModuleEnv.BodyAnnotationMalformedTypePublication,
) bool {
    if (!publication.hasLegalTags() or
        publication.attachment_node >= cir.store.nodes.len() or
        publication.annotation_root >= cir.store.nodes.len() or
        publication.body_expr >= cir.store.nodes.len() or
        publication.malformed_type_publication_index >=
            cir.malformed_type_annotation_publications.items.items.len)
    {
        return false;
    }
    if (cir.store.nodes.get(@enumFromInt(publication.annotation_root)).tag != .annotation) {
        return false;
    }
    const annotation_idx: CIR.Annotation.Idx = @enumFromInt(publication.annotation_root);
    const attachment_kind = publication.decodedAttachmentKind() orelse return false;
    const attachment_index = cir.bodyAnnotationAttachmentIndex(
        attachment_kind,
        publication.attachment_node,
        annotation_idx,
        @enumFromInt(publication.body_expr),
    ) orelse return false;
    if (!cir.bodyAnnotationAttachmentIsLocallyValid(attachment_index)) return false;
    if (!cir.annotationOwnsMalformedTypePublication(
        annotation_idx,
        publication.malformed_type_publication_index,
    )) return false;
    return true;
}

fn bodyAnnotationMalformedTypePublicationIndex(
    cir: *const ModuleEnv,
    attachment: BodyAnnotationAttachment,
    annotation_root: u32,
    body_expr: u32,
    malformed_type_publication_index: u32,
) ?u32 {
    var found: ?u32 = null;
    for (cir.body_annotation_malformed_type_publications.items.items, 0..) |publication, publication_index| {
        if (publication.attachment_kind == @intFromEnum(attachment.kind) and
            publication.attachment_node == attachment.node and
            publication.annotation_root == annotation_root and
            publication.body_expr == body_expr and
            publication.malformed_type_publication_index == malformed_type_publication_index)
        {
            if (found != null) {
                std.debug.panic("canonicalization published a duplicate body-annotation ownership row", .{});
            }
            found = @intCast(publication_index);
        }
    }
    return found;
}

/// Replay the exact node state authorized by one consumer retirement. A
/// preexisting malformed expression is its own immutable producer, whereas a
/// checker rewrite retains the pre-rewrite bytes and must name the exact final
/// runtime-error diagnostic. Pattern poisoning does not rewrite CIR bytes, so
/// its original nominal node remains byte-identical.
fn expectedConsumerRetirementNodeIsLocallyValid(
    cir: *const ModuleEnv,
    retirement: ModuleEnv.ExpectedConsumerRetirement,
) bool {
    const owner_kind = retirement.decodedOwnerKind() orelse return false;
    const kind = retirement.decodedKind() orelse return false;
    const original_tag = retirement.decodedOriginalNodeTag() orelse return false;
    const raw_node = retirement.retired_node;
    if (raw_node >= cir.store.nodes.len()) return false;

    const node = cir.store.nodes.get(@enumFromInt(raw_node));
    const payload_words: [4]u32 = @bitCast(node.getPayload());
    return switch (kind) {
        .preexisting_runtime_error => owner_kind == .expression and
            malformedExpressionPublicationContains(
                cir,
                raw_node,
                retirement.diagnostic_index,
            ) and
            node.tag == .malformed and
            std.meta.eql(payload_words, retirement.original_payload) and
            cir.store.isDiagnosticIndex(@enumFromInt(retirement.diagnostic_index)) and
            cir.store.getExpr(@enumFromInt(raw_node)).e_runtime_error.diagnostic ==
                @as(CIR.Diagnostic.Idx, @enumFromInt(retirement.diagnostic_index)),
        .checker_rewrite_expected,
        .checker_rewrite_ineligible,
        => owner_kind == .expression and
            isExprNodeTag(original_tag) and
            node.tag == .malformed and
            cir.store.isDiagnosticIndex(@enumFromInt(retirement.diagnostic_index)) and
            cir.store.getExpr(@enumFromInt(raw_node)).e_runtime_error.diagnostic ==
                @as(CIR.Diagnostic.Idx, @enumFromInt(retirement.diagnostic_index)),
        .checker_poison_expected_pattern => owner_kind == .pattern and
            node.tag == original_tag and
            std.meta.eql(payload_words, retirement.original_payload),
    };
}

fn expectedRetiredPlanOutcomeIsLocallyValid(
    cir: *const ModuleEnv,
    plan: ModuleEnv.ExpectedConsumptionPlan,
    retirement_index: u32,
    retirement_reason: ModuleEnv.ExpectedConsumptionPlan.Reason,
) bool {
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    const outcome = plan.decodedOutcome() orelse return false;
    switch (retirement_reason) {
        .aggregate_retired_after_child_relation => return switch (outcome) {
            .anchored, .evidence_free => true,
            .checked_error => blk: {
                const reason = plan.decodedReason() orelse break :blk false;
                break :blk (reason == .aggregate_child_relation_rejected or
                    reason == .aggregate_child_relation_suppressed) and
                    expectedCauseOwnerIsLocallyValid(cir, plan.failure_owner) and
                    plan.failure_cause_plan_index == none;
            },
            .related,
            .source_root_copy,
            .source_root_copy_checked_error,
            .producer_root,
            .retained,
            .not_projected,
            .reserved,
            => false,
        },
        .aggregate_retired_by_parent_branch_failure => return switch (outcome) {
            .anchored, .evidence_free => true,
            .not_projected => plan.decodedReason() == .aggregate_no_expected and
                plan.parent_authority.kind == ModuleEnv.ExpectedMarkerAuthority.none and
                plan.failure_owner.kind == ModuleEnv.CauseOwner.none and
                plan.failure_cause_plan_index == none,
            .related,
            .source_root_copy,
            .source_root_copy_checked_error,
            .producer_root,
            .retained,
            .checked_error,
            .reserved,
            => false,
        },
        .branch_retired_after_failure => return switch (plan.decodedRole() orelse return false) {
            .branch_seed => outcome == .anchored,
            .branch_contribution => switch (outcome) {
                .related, .retained => true,
                .checked_error => blk: {
                    const reason = plan.decodedReason() orelse break :blk false;
                    break :blk (reason == .branch_body_error_short_circuit or
                        reason == .branch_expected_compatibility_rejected or
                        reason == .branch_accumulator_fold_rejected) and
                        expectedCauseOwnerIsLocallyValid(cir, plan.failure_owner) and
                        plan.failure_cause_plan_index == none;
                },
                .anchored,
                .source_root_copy,
                .source_root_copy_checked_error,
                .producer_root,
                .evidence_free,
                .not_projected,
                .reserved,
                => false,
            },
            .branch_final => switch (outcome) {
                .related => true,
                .checked_error => plan.decodedReason() == .branch_final_relation_rejected and
                    plan.failure_owner.decodedExpectedConsumerRetirement() != null and
                    plan.failure_owner.payload.expected_consumer_retirement.index == retirement_index and
                    plan.failure_cause_plan_index == none,
                .anchored,
                .source_root_copy,
                .source_root_copy_checked_error,
                .producer_root,
                .evidence_free,
                .retained,
                .not_projected,
                .reserved,
                => false,
            },
            .aggregate_owner,
            .list_element,
            .tuple_element,
            .record_field,
            .tag_payload,
            .record_update_base,
            .record_update_field,
            .nominal_decl,
            .nominal_backing,
            .call_root,
            .call_argument,
            .default_field,
            .lambda_return,
            => false,
        },
        .branch_retired_after_ambiguity_verdict => return switch (plan.decodedRole() orelse return false) {
            .branch_seed => outcome == .anchored and
                plan.decodedReason() == null and
                plan.failure_owner.kind == ModuleEnv.CauseOwner.none,
            .branch_final => outcome == .related and
                plan.decodedReason() == null and
                plan.failure_owner.kind == ModuleEnv.CauseOwner.none,
            .branch_contribution => switch (outcome) {
                .related => plan.decodedReason() == null and
                    plan.failure_owner.kind == ModuleEnv.CauseOwner.none,
                .retained => plan.decodedReason() == .branch_body_already_expected and
                    plan.failure_owner.kind == ModuleEnv.CauseOwner.none and
                    plan.failure_cause_plan_index == none,
                .anchored,
                .source_root_copy,
                .source_root_copy_checked_error,
                .producer_root,
                .evidence_free,
                .not_projected,
                .checked_error,
                .reserved,
                => false,
            },
            .aggregate_owner,
            .list_element,
            .tuple_element,
            .record_field,
            .tag_payload,
            .record_update_base,
            .record_update_field,
            .nominal_decl,
            .nominal_backing,
            .call_root,
            .call_argument,
            .default_field,
            .lambda_return,
            => false,
        },
        .call_retired,
        .call_retired_after_operand_checked_error,
        => return switch (plan.decodedRole() orelse return false) {
            .call_root => outcome == .not_projected and
                plan.decodedReason() == .call_shape_ready and
                plan.parent_authority.kind == ModuleEnv.ExpectedMarkerAuthority.none and
                plan.produced_copy_step == none and
                plan.produced_occurrence_offset == none and
                plan.produced_side == none and
                plan.call_root_plan_index == none and
                plan.failure_owner.kind == ModuleEnv.CauseOwner.none and
                plan.failure_cause_plan_index == none,
            .call_argument => outcome == .producer_root and
                plan.decodedReason() == null and
                plan.parent_authority.kind == ModuleEnv.ExpectedMarkerAuthority.none and
                plan.produced_copy_step == none and
                plan.produced_occurrence_offset == none and
                plan.produced_side == none and
                plan.call_root_plan_index != none and
                plan.failure_owner.kind == ModuleEnv.CauseOwner.none and
                plan.failure_cause_plan_index == none,
            .aggregate_owner,
            .list_element,
            .tuple_element,
            .record_field,
            .tag_payload,
            .record_update_base,
            .record_update_field,
            .branch_seed,
            .branch_contribution,
            .branch_final,
            .nominal_decl,
            .nominal_backing,
            .default_field,
            .lambda_return,
            => false,
        },
        else => return outcome == .checked_error and
            plan.decodedReason() == retirement_reason and
            plan.failure_owner.decodedExpectedConsumerRetirement() != null and
            plan.failure_owner.payload.expected_consumer_retirement.index == retirement_index and
            plan.failure_cause_plan_index == none,
    }
}

const ExpectedCallOperandRetirementSnapshot = struct {
    call: ExpectedCallOwnerSnapshot,
    root_plan_index: u32,
};

/// Validate the nonrecursive scalar/topology half of the direct-operand call
/// retirement. Failure rows use this snapshot to authenticate their call; the
/// complete failure inverse is deliberately checked outside this helper so a
/// call formal which replays an annotated callee cannot recurse back into the
/// same F_C validation.
fn expectedCallOperandRetirementSnapshot(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    retirement_index: u32,
) ?ExpectedCallOperandRetirementSnapshot {
    if (retirement_index >= cir.expected_consumer_retirements.items.items.len) return null;
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    if (retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_expected or
        retirement.decodedOriginalNodeTag() != .expr_call or
        retirement.decodedRejectionOwnerKind() != null or
        retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.rejection_owner_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.rejection_subject_var != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.expected_failures_len == 0 or retirement.retired_consumers_len == 0 or
        !rangeFits(
            retirement.expected_failures_start,
            retirement.expected_failures_len,
            cir.expected_retirement_failures.items.items.len,
        ) or
        !rangeFits(
            retirement.retired_consumers_start,
            retirement.retired_consumers_len,
            cir.expected_retired_consumers.items.items.len,
        ) or !expectedConsumerRetirementNodeIsLocallyValid(cir, retirement))
    {
        return null;
    }
    const original_payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    if (original_payload.expr_call.constraint_fn_var_plus_one != 0) return null;
    const call = expectedCallOperandRetirementTopologyFromPayload(cir, original_payload) orelse
        return null;
    const consumers = cir.expected_retired_consumers.items.items[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
    if (consumers.len != @as(usize, call.args_len) + 1) return null;

    const plans = cir.expected_consumption_plans.items.items;
    var owned_plan_count: usize = 0;
    for (plans) |plan| {
        if (plan.owner_node == retirement.retired_node) owned_plan_count += 1;
    }
    if (owned_plan_count != consumers.len) return null;
    var root_plan_index: ?u32 = null;
    var next_argument_slot: u32 = 0;
    for (consumers, 0..) |consumer, consumer_offset| {
        if (consumer.reserved_0 != 0 or
            consumer.decodedReason() != .call_retired_after_operand_checked_error or
            consumer.plan_index >= plans.len or
            consumer.owner_node != retirement.retired_node or
            consumer.raw_owner_var != retirement.retired_node or
            consumer.site_node >= cir.store.nodes.len() or
            consumer.raw_consumer_var >= types.len() or
            (consumer_offset != 0 and
                !expectedRetiredConsumerLessThan({}, consumers[consumer_offset - 1], consumer)))
        {
            return null;
        }
        const plan = plans[consumer.plan_index];
        if (!plan.hasLegalTags() or
            consumer.owner_node != plan.owner_node or
            consumer.site_node != plan.site_node or
            consumer.role != plan.role or consumer.slot != plan.slot or
            consumer.raw_consumer_var != plan.raw_consumer_var or
            !expectedRetiredPlanOutcomeIsLocallyValid(
                cir,
                plan,
                retirement_index,
                .call_retired_after_operand_checked_error,
            ))
        {
            return null;
        }
        switch (consumer.decodedRole() orelse return null) {
            .call_root => {
                if (consumer_offset != 0 or root_plan_index != null or
                    consumer.site_node != call.func or
                    consumer.raw_consumer_var != call.func or consumer.slot != 0)
                {
                    return null;
                }
                root_plan_index = consumer.plan_index;
            },
            .call_argument => {
                if (root_plan_index == null or consumer.slot != next_argument_slot or
                    consumer.slot >= call.args_len or
                    plan.call_root_plan_index != root_plan_index.?)
                {
                    return null;
                }
                const site = cir.store.index_data.items.items[call.args_start + consumer.slot];
                if (!expectedCallChildHasLegalState(cir, site, call.child_phase) or
                    consumer.site_node != site)
                {
                    return null;
                }
                next_argument_slot += 1;
            },
            .aggregate_owner,
            .list_element,
            .tuple_element,
            .record_field,
            .tag_payload,
            .record_update_base,
            .record_update_field,
            .branch_seed,
            .branch_contribution,
            .branch_final,
            .nominal_decl,
            .nominal_backing,
            .default_field,
            .lambda_return,
            => return null,
        }
    }
    const root = root_plan_index orelse return null;
    if (next_argument_slot != call.args_len or
        !expectedCallRootPlanMatchesSnapshot(cir, plans[root], call)) return null;

    const failures = cir.expected_failures.items.items;
    const references = cir.expected_retirement_failures.items.items[retirement.expected_failures_start..][0..retirement.expected_failures_len];
    for (references, 0..) |reference, reference_offset| {
        if (!reference.hasLegalTags() or reference.failure_index >= failures.len) return null;
        const failure = failures[reference.failure_index];
        if (!failure.hasLegalTagsAt(reference.failure_index) or
            failure.decodedKind() != .call_operand_checked_error or
            failure.owner_node != retirement.retired_node)
        {
            return null;
        }
        if (reference_offset != 0) {
            const previous = references[reference_offset - 1];
            if (previous.failure_index == reference.failure_index or
                expectedFailureKeyLessThan(
                    failures,
                    reference.failure_index,
                    previous.failure_index,
                ))
            {
                return null;
            }
        }
    }
    return .{ .call = call, .root_plan_index = root };
}

/// Close both directions of the finite call-operand failure relation without
/// entering the full direct-binder annotation replay. Every listed F_C must
/// match its exact call slot and completed direct-lookup R_L, and the sole
/// direct-lookup producer installs that same R_L as the argument's returned
/// checked status, so every completed R_L at an exact argument site must have
/// one listed F_C. No solved descriptor participates in this inverse.
fn expectedCallOperandFailureSetIsComplete(
    cir: *const ModuleEnv,
    retirement_index: u32,
    snapshot: ExpectedCallOperandRetirementSnapshot,
) bool {
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    const references = cir.expected_retirement_failures.items.items[retirement.expected_failures_start..][0..retirement.expected_failures_len];
    const failures = cir.expected_failures.items.items;

    for (references) |reference| {
        if (reference.failure_index >= failures.len) return false;
        const failure = failures[reference.failure_index];
        const subject = failure.subject_authority.decodedExpectedProducerRootPlan() orelse
            return false;
        if (!callOperandExpectedFailureMatchesSnapshot(
            cir,
            failure,
            subject,
            snapshot,
        )) return false;
        const source = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return false;
        if (completedDirectBinderLookupFailureForRetirement(cir, source.index) == null or
            cir.expected_consumer_retirements.items.items[source.index].retired_node !=
                failure.site_node)
        {
            return false;
        }
    }

    const arguments = cir.store.index_data.items.items[snapshot.call.args_start..][0..snapshot.call.args_len];
    for (arguments, 0..) |argument_site, slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        var source_retirement: ?u32 = null;
        for (cir.expected_consumer_retirements.items.items, 0..) |candidate, candidate_index| {
            if (candidate.retired_node != argument_site or
                completedDirectBinderLookupFailureForRetirement(
                    cir,
                    @intCast(candidate_index),
                ) == null)
            {
                continue;
            }
            if (source_retirement != null) return false;
            source_retirement = @intCast(candidate_index);
        }

        var matching_failures: usize = 0;
        for (references) |reference| {
            const failure = failures[reference.failure_index];
            if (failure.slot != slot or failure.site_node != argument_site) continue;
            const cause = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
                return false;
            if (source_retirement == null or cause.index != source_retirement.?) return false;
            matching_failures += 1;
        }
        if ((source_retirement == null and matching_failures != 0) or
            (source_retirement != null and matching_failures != 1))
        {
            return false;
        }
    }
    return true;
}

fn expectedCallOperandRetirementIsLocallyValid(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    retirement_index: u32,
) bool {
    const snapshot = expectedCallOperandRetirementSnapshot(
        types,
        cir,
        retirement_index,
    ) orelse return false;
    return expectedCallOperandFailureSetIsComplete(
        cir,
        retirement_index,
        snapshot,
    );
}

fn aggregateParentBranchRetirementEdgeIsLocallyValid(
    cir: *const ModuleEnv,
    retirement_index: u32,
    retired_node: u32,
) bool {
    var edge_count: usize = 0;
    for (cir.expected_consumption_plans.items.items) |plan| {
        const cause = plan.failure_owner.decodedExpectedConsumerRetirement() orelse continue;
        if (cause.index != retirement_index) continue;
        const reason = plan.decodedReason() orelse return false;
        if (!plan.hasLegalTags() or
            plan.decodedRole() != .branch_contribution or
            plan.decodedOutcome() != .checked_error or
            (reason != .branch_expected_compatibility_rejected and
                reason != .branch_accumulator_fold_rejected) or
            plan.owner_node == retired_node or
            plan.site_node != retired_node or
            plan.raw_consumer_var != retired_node or
            plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
        {
            return false;
        }
        edge_count += 1;
    }
    return edge_count == 1;
}

fn expectedRetiredAggregateChild(
    cir: *const ModuleEnv,
    tag: CIR.Node.Tag,
    payload: CIR.Node.Payload,
    slot: u32,
) ?struct {
    role: ModuleEnv.ExpectedConsumptionPlan.Role,
    site_node: u32,
} {
    return switch (tag) {
        .expr_list => blk: {
            const list = payload.expr_list;
            if (!std.mem.allEqual(u8, &list._padding, 0) or
                slot >= list.elems_len or
                !rangeFits(list.elems_start, list.elems_len, cir.store.nodes.len()))
            {
                break :blk null;
            }
            const site = list.elems_start + slot;
            if (!isExprNodeTag(cir.store.nodes.get(@enumFromInt(site)).tag)) break :blk null;
            break :blk .{ .role = .list_element, .site_node = site };
        },
        .expr_tuple => blk: {
            const tuple = payload.expr_tuple;
            if (!std.mem.allEqual(u8, &tuple._padding, 0) or
                slot >= tuple.elems_len or
                !rangeFits(tuple.elems_start, tuple.elems_len, cir.store.nodes.len()))
            {
                break :blk null;
            }
            const site = tuple.elems_start + slot;
            if (!isExprNodeTag(cir.store.nodes.get(@enumFromInt(site)).tag)) break :blk null;
            break :blk .{ .role = .tuple_element, .site_node = site };
        },
        .expr_record => blk: {
            const record = payload.expr_record;
            if (!std.mem.allEqual(u8, &record._padding, 0) or
                record.fields_ext_idx >= cir.store.span_with_node_data.len())
            {
                break :blk null;
            }
            const fields = cir.store.span_with_node_data.items.items[record.fields_ext_idx];
            if (fields.node != 0 or slot >= fields.len or
                !rangeFits(fields.start, fields.len, cir.store.nodes.len()))
            {
                break :blk null;
            }
            const field_node = fields.start + slot;
            const field = cir.store.nodes.get(@enumFromInt(field_node));
            if (field.tag != .record_field) break :blk null;
            const field_payload = field.getPayload().record_field;
            if (!std.mem.allEqual(u8, &field_payload._padding, 0) or
                field_payload.expr >= cir.store.nodes.len() or
                !isExprNodeTag(cir.store.nodes.get(@enumFromInt(field_payload.expr)).tag))
            {
                break :blk null;
            }
            break :blk .{ .role = .record_field, .site_node = field_payload.expr };
        },
        .expr_tag => blk: {
            const tag_payload = payload.expr_tag;
            if (slot >= tag_payload.args_len or
                !rangeFits(tag_payload.args_start, tag_payload.args_len, cir.store.nodes.len()))
            {
                break :blk null;
            }
            const site = tag_payload.args_start + slot;
            if (!isExprNodeTag(cir.store.nodes.get(@enumFromInt(site)).tag)) break :blk null;
            break :blk .{ .role = .tag_payload, .site_node = site };
        },
        else => null,
    };
}

fn expectedRetiredAggregateChildCount(
    cir: *const ModuleEnv,
    tag: CIR.Node.Tag,
    payload: CIR.Node.Payload,
) ?u32 {
    return switch (tag) {
        .expr_list => blk: {
            const list = payload.expr_list;
            if (!std.mem.allEqual(u8, &list._padding, 0) or
                !rangeFits(list.elems_start, list.elems_len, cir.store.nodes.len()))
            {
                break :blk null;
            }
            break :blk list.elems_len;
        },
        .expr_tuple => blk: {
            const tuple = payload.expr_tuple;
            if (!std.mem.allEqual(u8, &tuple._padding, 0) or
                !rangeFits(tuple.elems_start, tuple.elems_len, cir.store.nodes.len()))
            {
                break :blk null;
            }
            break :blk tuple.elems_len;
        },
        .expr_record => blk: {
            const record = payload.expr_record;
            if (!std.mem.allEqual(u8, &record._padding, 0) or
                record.fields_ext_idx >= cir.store.span_with_node_data.len())
            {
                break :blk null;
            }
            const fields = cir.store.span_with_node_data.items.items[record.fields_ext_idx];
            if (fields.node != 0 or
                !rangeFits(fields.start, fields.len, cir.store.nodes.len()))
            {
                break :blk null;
            }
            break :blk fields.len;
        },
        .expr_tag => blk: {
            const tag_payload = payload.expr_tag;
            if (!rangeFits(tag_payload.args_start, tag_payload.args_len, cir.store.nodes.len())) {
                break :blk null;
            }
            break :blk tag_payload.args_len;
        },
        else => null,
    };
}

fn expectedRetiredBranchContributionCount(
    cir: *const ModuleEnv,
    owner: WhereMarkerBranchOwnerSnapshot,
) ?u32 {
    return switch (owner.tag) {
        .expr_if_then_else => blk: {
            const payload = owner.payload.expr_if_then_else;
            if (!std.mem.allEqual(u8, &payload._padding, 0) or
                payload.branches_else_idx >= cir.store.if_data.len())
            {
                break :blk null;
            }
            const if_data = cir.store.if_data.items.items[payload.branches_else_idx];
            if (if_data.branches_len == 0 or
                !rangeFits(if_data.branches_start, if_data.branches_len, cir.store.index_data.len()) or
                if_data.final_else >= cir.store.nodes.len())
            {
                break :blk null;
            }
            break :blk std.math.add(u32, if_data.branches_len, 1) catch null;
        },
        .expr_match => blk: {
            const payload = owner.payload.expr_match;
            if (!std.mem.allEqual(u8, &payload._padding, 0) or
                payload.match_data_idx >= cir.store.match_data.len())
            {
                break :blk null;
            }
            const match_data = cir.store.match_data.items.items[payload.match_data_idx];
            if (match_data.branches_len == 0 or
                !rangeFits(match_data.branches_start, match_data.branches_len, cir.store.index_data.len()))
            {
                break :blk null;
            }
            break :blk match_data.branches_len;
        },
        else => null,
    };
}

fn expectedRetiredRecordUpdateOwnerRangeIsLocallyValid(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    retirement: ModuleEnv.ExpectedConsumerRetirement,
    retirement_index: u32,
    consumers: []const ModuleEnv.ExpectedRetiredConsumer,
) bool {
    const owner = retiredRecordUpdateOwnerSnapshot(
        cir,
        retirement.retired_node,
        .retired,
    ) orelse return false;
    if (owner.retirement_index != retirement_index or
        owner.retirement.retired_node != retirement.retired_node or
        consumers.len != @as(usize, owner.syntax.fields_len) + 1)
    {
        return false;
    }
    const plans = cir.expected_consumption_plans.items.items;
    var base_plan_index: ?u32 = null;
    var base_plan_value: ?ModuleEnv.ExpectedConsumptionPlan = null;
    for (consumers, 0..) |consumer, consumer_offset| {
        if (consumer.reserved_0 != 0 or
            consumer.decodedRetirementOnlyReason() !=
                .record_update_retired_after_base_checked_error or
            consumer.decodedReason() != null or consumer.plan_index >= plans.len or
            consumer.owner_node != retirement.retired_node or
            consumer.raw_owner_var != retirement.retired_node or
            consumer.owner_node >= cir.store.nodes.len() or
            consumer.site_node >= cir.store.nodes.len() or
            consumer.raw_owner_var >= types.len() or consumer.raw_consumer_var >= types.len() or
            (consumer_offset != 0 and !expectedRetiredConsumerLessThan(
                {},
                consumers[consumer_offset - 1],
                consumer,
            )))
        {
            return false;
        }
        const plan = plans[consumer.plan_index];
        if (!plan.hasLegalTags() or consumer.owner_node != plan.owner_node or
            consumer.site_node != plan.site_node or consumer.role != plan.role or
            consumer.slot != plan.slot or consumer.raw_consumer_var != plan.raw_consumer_var)
        {
            return false;
        }
        switch (consumer.decodedRole() orelse return false) {
            .record_update_base => {
                if (base_plan_index != null or consumer.slot != 0 or
                    consumer.site_node != owner.syntax.base_expr or
                    plan.decodedOutcome() != .source_root_copy_checked_error or
                    plan.decodedReason() != .record_update_base_checked_error or
                    !expectedRecordUpdateBasePlanMatchesStep(cir, plan) or
                    !expectedRecordUpdateBaseCauseIsLocallyValid(
                        types,
                        cir,
                        owner.syntax.base_expr,
                        consumer.plan_index,
                        plan.failure_owner,
                    ) or !expectedRecordUpdateBaseSourceRetirementIsLocallyValid(cir, plan))
                {
                    return false;
                }
                const source_retirement = plan.decodedSourceRetirementIndex() orelse return false;
                if (source_retirement == retirement_index) return false;
                base_plan_index = consumer.plan_index;
                base_plan_value = plan;
            },
            .record_update_field => {},
            else => return false,
        }
    }
    const base_index = base_plan_index orelse return false;
    const base_plan = base_plan_value orelse return false;
    const base_authority = expectedRecordUpdateBaseAuthority(base_plan) orelse return false;
    for (0..@as(usize, owner.syntax.fields_len)) |slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        const site = expectedRecordUpdateFieldSite(cir, owner.syntax, slot) orelse return false;
        var count: usize = 0;
        for (consumers) |consumer| {
            if (consumer.decodedRole() != .record_update_field or
                consumer.slot != slot or consumer.site_node != site)
            {
                continue;
            }
            const plan = plans[consumer.plan_index];
            if (plan.decodedOutcome() != .checked_error or
                plan.decodedReason() != .record_update_field_base_checked_error or
                plan.failure_cause_plan_index != base_index or
                !expectedCauseOwnersEqual(plan.failure_owner, base_plan.failure_owner) or
                !expectedRecordUpdateFieldBeginsAtBase(
                    cir,
                    consumer.plan_index,
                    plan,
                    base_authority,
                ))
            {
                return false;
            }
            count += 1;
        }
        if (count != 1) return false;
    }
    for (plans, 0..) |plan, plan_index| {
        if (plan.owner_node != retirement.retired_node) continue;
        const role = plan.decodedRole() orelse return false;
        if (role != .record_update_base and role != .record_update_field) return false;
        var count: usize = 0;
        for (consumers) |consumer| {
            count += @intFromBool(consumer.plan_index == @as(u32, @intCast(plan_index)));
        }
        if (count != 1) return false;
    }
    return true;
}

fn expectedRetiredConsumerRangeIsLocallyValid(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    retirement: ModuleEnv.ExpectedConsumerRetirement,
    retirement_index: u32,
    consumers: []const ModuleEnv.ExpectedRetiredConsumer,
) bool {
    if (consumers.len == 0) return retirement.retired_consumers_len == 0;
    if (consumers[0].decodedRetirementOnlyReason()) |reason| {
        return switch (reason) {
            .record_update_retired_after_base_checked_error => expectedRetiredRecordUpdateOwnerRangeIsLocallyValid(
                types,
                cir,
                retirement,
                retirement_index,
                consumers,
            ),
        };
    }
    const plans = cir.expected_consumption_plans.items.items;
    const retirement_reason = consumers[0].decodedReason() orelse return false;
    var aggregate_direct_failures: usize = 0;
    var aggregate_no_expected_rows: usize = 0;
    var branch_direct_failures: usize = 0;
    var branch_final_was_related = false;

    for (consumers, 0..) |consumer, consumer_offset| {
        if (consumer.reserved_0 != 0 or
            consumer.decodedReason() != retirement_reason or
            consumer.plan_index >= plans.len or
            consumer.owner_node >= cir.store.nodes.len() or
            consumer.site_node >= cir.store.nodes.len() or
            consumer.raw_owner_var >= types.len() or
            consumer.raw_consumer_var >= types.len() or
            consumer.owner_node != retirement.retired_node or
            consumer.raw_owner_var != retirement.retired_node or
            (consumer_offset != 0 and
                !expectedRetiredConsumerLessThan({}, consumers[consumer_offset - 1], consumer)))
        {
            return false;
        }
        const plan = plans[consumer.plan_index];
        const role = consumer.decodedRole() orelse return false;
        if (!plan.hasLegalTags() or
            !ModuleEnv.ExpectedConsumptionPlan.legalCombination(
                role,
                .checked_error,
                retirement_reason,
                .expected_consumer_retirement,
                false,
            ) or
            consumer.owner_node != plan.owner_node or
            consumer.site_node != plan.site_node or
            consumer.role != plan.role or
            consumer.slot != plan.slot or
            consumer.raw_consumer_var != plan.raw_consumer_var or
            !expectedRetiredPlanOutcomeIsLocallyValid(
                cir,
                plan,
                retirement_index,
                retirement_reason,
            ))
        {
            return false;
        }
        if (retirement_reason == .aggregate_retired_after_child_relation and
            plan.decodedOutcome() == .checked_error)
        {
            aggregate_direct_failures += 1;
        }
        if (retirement_reason == .aggregate_retired_by_parent_branch_failure and
            plan.decodedOutcome() == .not_projected)
        {
            aggregate_no_expected_rows += 1;
        }
        if (retirement_reason == .branch_retired_after_failure) {
            if (role == .branch_contribution and plan.decodedOutcome() == .checked_error) {
                branch_direct_failures += 1;
            }
            if (role == .branch_final and plan.decodedOutcome() == .related) {
                branch_final_was_related = true;
            }
        }
    }

    const original_tag = retirement.decodedOriginalNodeTag() orelse return false;
    const original_payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    switch (original_tag) {
        .expr_list, .expr_tuple, .expr_record, .expr_tag => {
            if (retirement_reason != .aggregate_retired_after_child_relation and
                retirement_reason != .aggregate_retired_by_parent_branch_failure and
                retirement_reason != .aggregate_shape_mismatch)
            {
                return false;
            }
            const child_count = expectedRetiredAggregateChildCount(
                cir,
                original_tag,
                original_payload,
            ) orelse return false;
            if (consumers.len != @as(usize, child_count) + 1) return false;
            var owner_count: usize = 0;
            for (consumers) |consumer| {
                const role = consumer.decodedRole() orelse return false;
                if (role == .aggregate_owner) {
                    if (consumer.site_node != retirement.retired_node or consumer.slot != 0) {
                        return false;
                    }
                    owner_count += 1;
                    continue;
                }
                const child = expectedRetiredAggregateChild(
                    cir,
                    original_tag,
                    original_payload,
                    consumer.slot,
                ) orelse return false;
                if (role != child.role or consumer.site_node != child.site_node) return false;
            }
            if (owner_count != 1) return false;
            for (0..child_count) |slot_usize| {
                const slot: u32 = @intCast(slot_usize);
                const child = expectedRetiredAggregateChild(
                    cir,
                    original_tag,
                    original_payload,
                    slot,
                ) orelse return false;
                var slot_count: usize = 0;
                for (consumers) |consumer| {
                    if (consumer.decodedRole() == child.role and
                        consumer.slot == slot and consumer.site_node == child.site_node)
                    {
                        slot_count += 1;
                    }
                }
                if (slot_count != 1) return false;
            }
            if (retirement_reason == .aggregate_retired_after_child_relation and
                aggregate_direct_failures == 0)
            {
                return false;
            }
            if (retirement_reason == .aggregate_retired_by_parent_branch_failure and
                aggregate_no_expected_rows != 0 and aggregate_no_expected_rows != consumers.len)
            {
                return false;
            }
            if (retirement_reason == .aggregate_retired_by_parent_branch_failure and
                !aggregateParentBranchRetirementEdgeIsLocallyValid(
                    cir,
                    retirement_index,
                    retirement.retired_node,
                ))
            {
                return false;
            }
        },
        .expr_if_then_else, .expr_match => {
            if (retirement_reason != .branch_retired_after_failure and
                retirement_reason != .branch_retired_after_ambiguity_verdict)
            {
                return false;
            }
            const snapshot = whereMarkerBranchOwnerSnapshot(cir, retirement.retired_node) orelse
                return false;
            const contribution_count = expectedRetiredBranchContributionCount(cir, snapshot) orelse
                return false;
            if (consumers.len != @as(usize, contribution_count) + 2) return false;
            var seed_count: usize = 0;
            var final_count: usize = 0;
            for (consumers) |consumer| {
                switch (consumer.decodedRole() orelse return false) {
                    .branch_seed => {
                        if (consumer.site_node != retirement.retired_node or consumer.slot != 0) {
                            return false;
                        }
                        seed_count += 1;
                    },
                    .branch_contribution => {
                        const site = whereMarkerBranchContributionSite(
                            cir,
                            snapshot,
                            consumer.slot,
                        ) orelse return false;
                        if (consumer.site_node != site or consumer.raw_consumer_var != site) {
                            return false;
                        }
                    },
                    .branch_final => {
                        if (consumer.site_node != retirement.retired_node or
                            consumer.raw_consumer_var != retirement.retired_node or consumer.slot != 0)
                        {
                            return false;
                        }
                        final_count += 1;
                    },
                    .aggregate_owner,
                    .list_element,
                    .tuple_element,
                    .record_field,
                    .tag_payload,
                    .record_update_base,
                    .record_update_field,
                    .nominal_decl,
                    .nominal_backing,
                    .call_root,
                    .call_argument,
                    .default_field,
                    .lambda_return,
                    => return false,
                }
            }
            if (seed_count != 1 or final_count != 1) return false;
            for (0..contribution_count) |slot_usize| {
                const slot: u32 = @intCast(slot_usize);
                const site = whereMarkerBranchContributionSite(cir, snapshot, slot) orelse
                    return false;
                var slot_count: usize = 0;
                for (consumers) |consumer| {
                    if (consumer.decodedRole() == .branch_contribution and
                        consumer.slot == slot and consumer.site_node == site)
                    {
                        slot_count += 1;
                    }
                }
                if (slot_count != 1) return false;
            }
            // An anchored final denotes a branch which completed before an
            // enclosing branch retired it; that completed branch cannot also
            // contain one of its own direct failed contributions.
            if (retirement_reason == .branch_retired_after_failure and
                branch_final_was_related and branch_direct_failures != 0)
            {
                return false;
            }
            if (retirement_reason == .branch_retired_after_ambiguity_verdict and
                branch_direct_failures != 0)
            {
                return false;
            }
        },
        .expr_call => call_retirement: {
            if (retirement_reason == .call_retired_after_operand_checked_error) {
                if (!expectedCallOperandRetirementIsLocallyValid(
                    types,
                    cir,
                    retirement_index,
                )) return false;
                break :call_retirement;
            }
            if (retirement_reason != .call_retired) return false;
            const call = original_payload.expr_call;
            if (call.func >= cir.store.nodes.len() or
                !isExprNodeTag(cir.store.nodes.get(@enumFromInt(call.func)).tag) or
                call.args_span2_idx >= cir.store.span2_data.items.items.len or
                call.constraint_fn_var_plus_one == 0 or
                call.constraint_fn_var_plus_one - 1 >= types.len())
            {
                return false;
            }
            const called_via = std.enums.fromInt(base.CalledVia, call.called_via) orelse return false;
            if (called_via != .apply and called_via != .record_builder) return false;
            const args_span = cir.store.span2_data.items.items[call.args_span2_idx];
            if (!rangeFits(args_span.start, args_span.len, cir.store.index_data.items.items.len) or
                consumers.len != @as(usize, args_span.len) + 1)
            {
                return false;
            }
            var root_plan_index: ?u32 = null;
            for (consumers) |consumer| {
                const role = consumer.decodedRole() orelse return false;
                switch (role) {
                    .call_root => {
                        if (root_plan_index != null or
                            consumer.site_node != call.func or
                            consumer.raw_consumer_var != call.func or
                            consumer.slot != 0)
                        {
                            return false;
                        }
                        root_plan_index = consumer.plan_index;
                    },
                    .call_argument => {
                        if (consumer.slot >= args_span.len) return false;
                        const site = cir.store.index_data.items.items[args_span.start + consumer.slot];
                        if (site >= cir.store.nodes.len() or
                            !isExprNodeTag(cir.store.nodes.get(@enumFromInt(site)).tag) or
                            consumer.site_node != site)
                        {
                            return false;
                        }
                    },
                    .aggregate_owner,
                    .list_element,
                    .tuple_element,
                    .record_field,
                    .tag_payload,
                    .record_update_base,
                    .record_update_field,
                    .branch_seed,
                    .branch_contribution,
                    .branch_final,
                    .nominal_decl,
                    .nominal_backing,
                    .default_field,
                    .lambda_return,
                    => return false,
                }
            }
            const root = root_plan_index orelse return false;
            for (0..args_span.len) |slot_usize| {
                const slot: u32 = @intCast(slot_usize);
                const site = cir.store.index_data.items.items[args_span.start + slot];
                var slot_count: usize = 0;
                for (consumers) |consumer| {
                    if (consumer.decodedRole() == .call_argument and
                        consumer.slot == slot and
                        consumer.site_node == site and
                        plans[consumer.plan_index].call_root_plan_index == root)
                    {
                        slot_count += 1;
                    }
                }
                if (slot_count != 1) return false;
            }
        },
        else => {},
    }

    var owner_plan_count: usize = 0;
    for (plans) |plan| {
        if (plan.owner_node == retirement.retired_node) owner_plan_count += 1;
    }
    return owner_plan_count == consumers.len;
}

/// Replay the in-module dispatch-use bit recorded by an ambiguity verdict.
/// Constraint provenance is immutable producer metadata; an absent provenance
/// is a synthetic/no-use constraint, while an out-of-bounds provenance is a
/// corrupt artifact rather than permission to treat the use as absent.
fn expectedAmbiguityConstraintHasLiveDispatchUse(
    cir: *const ModuleEnv,
    constraint: StaticDispatchConstraint,
) ?bool {
    const raw_expr = constraint.provenance.intro_expr.get() orelse return false;
    if (raw_expr >= cir.store.nodes.len()) return null;
    const expr_idx: CIR.Expr.Idx = @enumFromInt(raw_expr);
    const expr = cir.store.getExpr(expr_idx);
    if (expr == .e_runtime_error) return false;
    return switch (expr) {
        .e_dispatch_call => |call| call.method_name.eql(constraint.fn_name),
        .e_type_dispatch_call => |call| call.method_name.eql(constraint.fn_name),
        else => false,
    };
}

/// Validate one exact late ambiguity publication without attempting to
/// rediscover its copy occurrence, selected constraint, or consumer group by
/// graph shape. The closed kind controls whether copy-driver coordinates are
/// required (body-forced branch) or forbidden (direct creation call).
fn expectedAmbiguityRetirementIsLocallyValid(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    row: ModuleEnv.ExpectedAmbiguityRetirement,
) bool {
    if (!row.hasCanonicalTags() or
        row.raw_receiver_var >= types.len() or
        row.retired_expr >= cir.store.nodes.len() or
        row.selected_constraint_index >= types.static_dispatch_constraints.items.items.len or
        row.consumer_root_plan >= cir.expected_consumption_plans.items.items.len or
        !cir.store.isDiagnosticIndex(@enumFromInt(row.diagnostic_index)))
    {
        return false;
    }

    const expr_idx: CIR.Expr.Idx = @enumFromInt(row.retired_expr);
    const expr = cir.store.getExpr(expr_idx);
    if (expr != .e_runtime_error or
        @intFromEnum(expr.e_runtime_error.diagnostic) != row.diagnostic_index)
    {
        return false;
    }

    const resolved_receiver = types.resolveVar(@enumFromInt(row.raw_receiver_var));
    const range = contentConstraintRange(resolved_receiver.desc.content) orelse return false;
    const range_start: u32 = @intFromEnum(range.start);
    if (row.selected_constraint_index < range_start or
        row.selected_constraint_index - range_start >= range.len())
    {
        return false;
    }
    const selected = types.static_dispatch_constraints.items.items[row.selected_constraint_index];
    return switch (row.decodedKind() orelse return false) {
        .body_forced_instantiation_branch => blk: {
            if (row.copy_step >= cir.where_marker_copy_steps.items.items.len) break :blk false;
            const step = cir.where_marker_copy_steps.items.items[row.copy_step];
            const step_kind = step.decodedKind() orelse break :blk false;
            if (step_kind.sourceNamespace() != .local or
                !rangeFits(step.pairs_start, step.pairs_len, cir.where_marker_copy_pairs.items.items.len) or
                !rangeFits(
                    step.occurrences_start,
                    step.occurrences_len,
                    cir.where_marker_copy_occurrences.items.items.len,
                ) or
                row.pair_offset >= step.pairs_len or
                row.occurrence_offset >= step.occurrences_len)
            {
                break :blk false;
            }
            const pair = cir.where_marker_copy_pairs.items.items[step.pairs_start + row.pair_offset];
            const occurrence = cir.where_marker_copy_occurrences.items.items[
                step.occurrences_start + row.occurrence_offset
            ];
            if (pair.source_var >= types.len() or pair.destination_var >= types.len() or
                occurrence.raw_source_var >= types.len() or
                occurrence.raw_destination_var >= types.len() or
                occurrence.raw_destination_var != row.raw_receiver_var or
                occurrence.canonical_pair_offset != row.pair_offset or
                types.resolveVar(@enumFromInt(occurrence.raw_source_var)).var_ !=
                    @as(Var, @enumFromInt(pair.source_var)) or
                types.resolveVar(@enumFromInt(occurrence.raw_destination_var)).var_ !=
                    @as(Var, @enumFromInt(pair.destination_var)) or
                resolved_receiver.var_ != @as(Var, @enumFromInt(pair.destination_var)))
            {
                break :blk false;
            }
            if (selected.origin != .where_clause or
                !selected.origin.where_clause.body_required or
                !row.isInstantiatedWhereClause() or
                !row.isBodyForced())
            {
                break :blk false;
            }
            var only_where_clause_contracts = true;
            for (types.sliceStaticDispatchConstraints(range)) |constraint| {
                if (constraint.origin != .where_clause) {
                    only_where_clause_contracts = false;
                    break;
                }
            }
            const has_dispatch_use = expectedAmbiguityConstraintHasLiveDispatchUse(cir, selected) orelse
                break :blk false;
            break :blk row.onlyWhereClauseContracts() == only_where_clause_contracts and
                row.hasWhereDispatchUse() == has_dispatch_use and
                !has_dispatch_use;
        },
        .creation_dispatch_call => row.raw_receiver_var == row.retired_expr and
            switch (selected.origin) {
                .method_call, .desugared_binop, .desugared_unaryop => true,
                .from_literal, .where_clause => false,
            },
    };
}

fn expectedAmbiguityRetirementOwnerIsLocallyValid(
    cir: *const ModuleEnv,
    retirement: ModuleEnv.ExpectedConsumerRetirement,
    ambiguity_index: u32,
) bool {
    if (ambiguity_index >= cir.expected_ambiguity_retirements.items.items.len) return false;
    const row = cir.expected_ambiguity_retirements.items.items[ambiguity_index];
    if (retirement.decodedOwnerKind() != .expression) return false;
    if (retirement.decodedKind() != .checker_rewrite_expected or
        retirement.retired_node != row.retired_expr or
        retirement.diagnostic_index != row.diagnostic_index or
        retirement.expected_failures_len != 0 or
        retirement.expected_failures_start != 0 or
        retirement.rejection_subject_var != row.raw_receiver_var or
        retirement.retired_consumers_len != row.consumer_plan_count or
        !rangeFits(
            retirement.retired_consumers_start,
            retirement.retired_consumers_len,
            cir.expected_retired_consumers.items.items.len,
        ))
    {
        return false;
    }
    const group_kind = row.decodedConsumerGroupKind() orelse return false;
    const expected_reason: ModuleEnv.ExpectedConsumptionPlan.Reason = switch (group_kind) {
        .branch => .branch_retired_after_ambiguity_verdict,
        .call => .call_retired,
    };
    const root_role = cir.expected_consumption_plans.items.items[row.consumer_root_plan].decodedRole() orelse
        return false;
    const expected_root_role: ModuleEnv.ExpectedConsumptionPlan.Role = switch (group_kind) {
        .branch => .branch_seed,
        .call => .call_root,
    };
    if (root_role != expected_root_role) return false;
    var root_count: usize = 0;
    const consumers = cir.expected_retired_consumers.items.items[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
    for (consumers) |consumer| {
        if (consumer.decodedReason() != expected_reason) return false;
        if (consumer.plan_index == row.consumer_root_plan) root_count += 1;
    }
    return root_count == 1;
}

/// Allocation-free replay of the combined Expected-failure/consumer-retirement
/// causal graph. The two pools retain type-local indices, but their canonical
/// order is induced by one tagged Kahn walk: every ready failure precedes every
/// ready retirement, and each kind uses its stable semantic key internally.
fn validateExpectedFailureRetirementLocal(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
) bool {
    const none = std.math.maxInt(u32);
    const failures = cir.expected_failures.items.items;
    const retirements = cir.expected_consumer_retirements.items.items;
    const ambiguity_retirements = cir.expected_ambiguity_retirements.items.items;
    const retirement_failures = cir.expected_retirement_failures.items.items;
    const retired_consumers = cir.expected_retired_consumers.items.items;
    const plans = cir.expected_consumption_plans.items.items;
    const constraints = types.static_dispatch_constraints.items.items;

    for (cir.malformed_expression_publications.items.items, 0..) |publication, publication_index| {
        if (!malformedExpressionPublicationIsLocallyValid(cir, publication)) return false;
        if (publication_index != 0 and
            cir.malformed_expression_publications.items.items[publication_index - 1].expr_node >=
                publication.expr_node)
        {
            return false;
        }
    }
    for (cir.malformed_type_annotation_publications.items.items, 0..) |publication, publication_index| {
        if (!malformedTypeAnnotationPublicationIsLocallyValid(cir, publication)) return false;
        if (publication_index != 0 and
            cir.malformed_type_annotation_publications.items.items[publication_index - 1].annotation_node >=
                publication.annotation_node)
        {
            return false;
        }
    }
    for (cir.body_annotation_attachments.items.items, 0..) |attachment, attachment_index| {
        if (!cir.bodyAnnotationAttachmentIsLocallyValid(@intCast(attachment_index))) return false;
        if (attachment_index != 0 and
            !ModuleEnv.bodyAnnotationAttachmentLessThan(
                cir.body_annotation_attachments.items.items[attachment_index - 1],
                attachment,
            ))
        {
            return false;
        }
    }
    for (cir.body_annotation_malformed_type_publications.items.items, 0..) |publication, publication_index| {
        if (!bodyAnnotationMalformedTypePublicationIsLocallyValid(cir, publication)) return false;
        if (publication_index == 0) continue;
        const prior = cir.body_annotation_malformed_type_publications.items.items[publication_index - 1];
        if (prior.attachment_node > publication.attachment_node) return false;
        if (prior.attachment_node == publication.attachment_node and
            (prior.attachment_kind != publication.attachment_kind or
                prior.annotation_root != publication.annotation_root or
                prior.body_expr != publication.body_expr or
                prior.malformed_type_publication_index >=
                    publication.malformed_type_publication_index))
        {
            return false;
        }
    }
    for (ambiguity_retirements, 0..) |row, row_index| {
        if (!expectedAmbiguityRetirementIsLocallyValid(types, cir, row) or
            (row_index != 0 and
                !ModuleEnv.ExpectedAmbiguityRetirement.canonicalLessThan(
                    ambiguity_retirements[row_index - 1],
                    row,
                )))
        {
            return false;
        }
    }

    for (plans, 0..) |plan, plan_index| {
        if (!plan.hasLegalTags() or
            !expectedCauseOwnerIsLocallyValid(cir, plan.failure_owner))
        {
            return false;
        }
        switch (plan.parent_authority.decodedKind() orelse continue) {
            .copy_occurrence => {},
            .producer_root_plan => {
                const parent = plan.parent_authority.payload.producer_root_plan;
                if (parent.plan_index >= plan_index or parent.plan_index >= plans.len) return false;
                const parent_plan = plans[parent.plan_index];
                if (!parent_plan.hasLegalTags() or
                    parent_plan.decodedOutcome() != .producer_root or
                    parent_plan.raw_consumer_var != parent.raw_var)
                {
                    return false;
                }
            },
            .evidence_free_plan => {
                const parent = plan.parent_authority.payload.evidence_free_plan;
                if (parent.plan_index >= plan_index or parent.plan_index >= plans.len) return false;
                const parent_plan = plans[parent.plan_index];
                if (!parent_plan.hasLegalTags() or parent_plan.raw_consumer_var != parent.raw_var or
                    (parent_plan.decodedOutcome() != .evidence_free and
                        !(parent_plan.decodedOutcome() == .checked_error and
                            parent_plan.decodedReason() == .aggregate_child_relation_rejected)))
                {
                    return false;
                }
            },
            .relation_plan => {
                const parent = plan.parent_authority.payload.relation_plan;
                if (parent.plan_index >= plan_index or parent.plan_index >= plans.len) return false;
                const parent_plan = plans[parent.plan_index];
                if (!parent_plan.hasLegalTags() or
                    parent_plan.decodedRole() != .branch_contribution or
                    parent_plan.decodedOutcome() != .related)
                {
                    return false;
                }
                const parent_raw = expectedParentAuthorityRawForProof(
                    cir,
                    parent_plan.parent_authority,
                    cir.where_marker_copy_steps.items.items,
                    cir.where_marker_copy_occurrences.items.items,
                    null,
                ) orelse return false;
                if (parent.raw_var != parent_raw) return false;
            },
        }
    }
    for (failures, 0..) |failure, failure_index| {
        if (!failure.hasLegalTagsAt(@intCast(failure_index)) or
            failure.owner_node >= cir.store.nodes.len() or
            failure.site_node >= cir.store.nodes.len() or
            failure.raw_owner_var >= types.len() or
            failure.raw_subject_var >= types.len() or
            (failure.raw_peer_var != none and failure.raw_peer_var >= types.len()) or
            (failure.constraint_index != none and failure.constraint_index >= constraints.len) or
            (failure.plan_index != none and failure.plan_index >= plans.len) or
            !expectedFailureSubjectIsLocallyValid(types, cir, failure, @intCast(failure_index)) or
            !expectedCauseOwnerIsLocallyValid(cir, failure.cause_owner))
        {
            return false;
        }
        for (failures[0..failure_index]) |prior| {
            if (expectedFailureKeysEqual(prior, failure)) return false;
        }
    }
    var retirement_failure_end: usize = 0;
    var retired_consumer_end: usize = 0;
    for (retirements, 0..) |retirement, retirement_index| {
        if (!retirement.hasLegalTags() or
            !expectedConsumerRetirementNodeIsLocallyValid(cir, retirement))
        {
            return false;
        }
        if (retirement.decodedRejectionOwnerKind()) |rejection_owner_kind| {
            switch (rejection_owner_kind) {
                .rejected_static_dispatch => {
                    if (retirement.rejection_owner_index >=
                        cir.rejected_static_dispatches.items.items.len or
                        retirement.rejection_subject_var >= types.len() or
                        cir.rejected_static_dispatches.items.items[
                            retirement.rejection_owner_index
                        ].constraint_fn_var >= types.len())
                    {
                        return false;
                    }
                },
                .expected_ambiguity_retirement => if (!expectedAmbiguityRetirementOwnerIsLocallyValid(
                    cir,
                    retirement,
                    retirement.rejection_owner_index,
                )) return false,
            }
        } else if (retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none) {
            return false;
        }
        if (retirement.expected_failures_len == 0) {
            if (retirement.expected_failures_start != 0) return false;
        } else {
            if (retirement.expected_failures_start != retirement_failure_end or
                !rangeFits(
                    retirement.expected_failures_start,
                    retirement.expected_failures_len,
                    retirement_failures.len,
                ))
            {
                return false;
            }
            const causes = retirement_failures[retirement.expected_failures_start..][0..retirement.expected_failures_len];
            for (causes, 0..) |cause, cause_offset| {
                if (!cause.hasLegalTags() or cause.failure_index >= failures.len) return false;
                const failure = failures[cause.failure_index];
                if (failure.owner_kind != retirement.owner_kind or
                    failure.owner_node != retirement.retired_node)
                {
                    return false;
                }
                if (cause_offset != 0) {
                    const prior = causes[cause_offset - 1];
                    if (prior.failure_index == cause.failure_index or
                        expectedFailureKeyLessThan(
                            failures,
                            cause.failure_index,
                            prior.failure_index,
                        ))
                    {
                        return false;
                    }
                }
            }
            retirement_failure_end += retirement.expected_failures_len;
        }
        if (retirement.retired_consumers_len == 0) {
            if (retirement.retired_consumers_start != 0) return false;
        } else {
            if (retirement.retired_consumers_start != retired_consumer_end or
                !rangeFits(
                    retirement.retired_consumers_start,
                    retirement.retired_consumers_len,
                    retired_consumers.len,
                ))
            {
                return false;
            }
            const consumers = retired_consumers[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
            if (!expectedRetiredConsumerRangeIsLocallyValid(
                types,
                cir,
                retirement,
                @intCast(retirement_index),
                consumers,
            )) return false;
            const ambiguity_owned = retirement.decodedRejectionOwnerKind() ==
                .expected_ambiguity_retirement;
            const ambiguity_reason = if (consumers[0].decodedReason()) |retired_reason|
                retired_reason == .branch_retired_after_ambiguity_verdict or
                    retired_reason == .call_retired
            else if (consumers[0].decodedRetirementOnlyReason()) |_| false else return false;
            if (ambiguity_reason != ambiguity_owned) {
                return false;
            }
            retired_consumer_end += retirement.retired_consumers_len;
        }
        for (retirements[0..retirement_index]) |prior| {
            if (prior.owner_kind == retirement.owner_kind and
                prior.retired_node == retirement.retired_node)
            {
                return false;
            }
        }
    }

    if (retirement_failure_end != retirement_failures.len) return false;
    if (retired_consumer_end != retired_consumers.len) return false;
    for (retired_consumers, 0..) |consumer, consumer_index| {
        for (retired_consumers[0..consumer_index]) |prior| {
            if (prior.plan_index == consumer.plan_index) return false;
        }
    }
    for (plans, 0..) |plan, plan_index| {
        const reason = plan.decodedReason() orelse continue;
        if (ModuleEnv.ExpectedConsumptionPlan.ownerRelationForReason(reason) !=
            .same_node_retirement)
        {
            continue;
        }
        const owner = plan.failure_owner.decodedExpectedConsumerRetirement() orelse
            return false;
        if (owner.index >= retirements.len) return false;
        const retirement = retirements[owner.index];
        if (!rangeFits(
            retirement.retired_consumers_start,
            retirement.retired_consumers_len,
            retired_consumers.len,
        )) return false;
        var membership_count: usize = 0;
        const owned = retired_consumers[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
        for (owned) |consumer| {
            if (consumer.plan_index == plan_index) membership_count += 1;
        }
        if (membership_count != 1) return false;
    }
    for (failures, 0..) |_, failure_index| {
        var owner_count: usize = 0;
        for (plans) |plan| {
            if (recordUpdateExpectedPlanCarriesCausalReference(plan)) continue;
            if (plan.failure_owner.decodedExpectedFailure()) |owner| {
                if (owner.index == failure_index) owner_count += 1;
            }
        }
        for (retirement_failures) |owner| {
            if (owner.failure_index == failure_index) owner_count += 1;
        }
        if (owner_count != 1) return false;
    }
    for (ambiguity_retirements, 0..) |_, ambiguity_index| {
        var owner_count: usize = 0;
        for (retirements) |retirement| {
            if (retirement.decodedRejectionOwnerKind() == .expected_ambiguity_retirement and
                retirement.rejection_owner_index == ambiguity_index)
            {
                owner_count += 1;
            }
        }
        if (owner_count != 1) return false;
    }

    return expectedFailureRetirementOrderIsCanonical(
        failures,
        retirements,
        retirement_failures,
    );
}

fn copiedOpenLiteralComponentMatchesStep(
    env: *const ModuleEnv,
    component: ModuleEnv.CopiedOpenLiteralComponent,
    copy_step_index: u32,
) bool {
    if (!component.hasCanonicalTags() or
        copy_step_index >= env.where_marker_copy_steps.items.items.len)
    {
        return false;
    }
    const step = env.where_marker_copy_steps.items.items[copy_step_index];
    const step_kind = step.decodedKind() orelse return false;
    return switch (component.decodedKind() orelse return false) {
        .root_graph => step_kind != .binding_codec_receiver and
            step_kind != .binding_codec_function,
        .scheme_requirement => true,
        .binding_codec_receiver => step_kind == .binding_codec_receiver and
            step.origin.binding_codec_receiver.binding_root_step == component.binding_root_step and
            step.origin.binding_codec_receiver.requirement_ordinal == component.requirement_ordinal,
        .binding_codec_function => step_kind == .binding_codec_function and
            step.origin.binding_codec_function.binding_root_step == component.binding_root_step and
            step.origin.binding_codec_function.requirement_ordinal == component.requirement_ordinal,
    };
}

fn copiedOpenLiteralComponentMatchesReceiver(
    env: *const ModuleEnv,
    group: ModuleEnv.CopiedOpenLiteralGroup,
    receiver_ref: ModuleEnv.CopiedConstraintComponentRef,
) bool {
    if (receiver_ref.copy_step_index != group.copy_step_index or
        receiver_ref.occurrence_offset != group.receiver_occurrence_offset or
        receiver_ref.copy_step_index >= env.where_marker_copy_steps.items.items.len)
    {
        return false;
    }
    const component_kind = group.component.decodedKind() orelse return false;
    const receiver_kind = receiver_ref.decodedKind() orelse return false;
    if (!copiedOpenLiteralComponentMatchesStep(env, group.component, group.copy_step_index)) {
        return false;
    }
    return switch (component_kind) {
        .root_graph => receiver_kind == .root_graph,
        .scheme_requirement => receiver_kind == .scheme_requirement and
            receiver_ref.requirement_ordinal == group.component.requirement_ordinal,
        // Inner receiver/function constraints are ordinary step-local graph
        // sources. Their group's component tag carries the binding origin;
        // the separately appended composite ingress remains nonliteral.
        .binding_codec_receiver, .binding_codec_function => receiver_kind == .root_graph,
    };
}

fn copiedOpenLiteralGroupContainsSource(
    env: *const ModuleEnv,
    group: ModuleEnv.CopiedOpenLiteralGroup,
    copied: ModuleEnv.DispatchSettlementSource.CopiedConstraint,
) bool {
    if (!copiedOpenLiteralComponentMatchesReceiver(env, group, copied.receiver_component_ref) or
        copied.function_component_ref.copy_step_index != group.copy_step_index or
        copied.function_component_ref.copy_step_index >= env.where_marker_copy_steps.items.items.len)
    {
        return false;
    }
    const function_step = env.where_marker_copy_steps.items.items[
        copied.function_component_ref.copy_step_index
    ];
    if (copied.function_component_ref.constraint_pair_offset >= function_step.constraint_pairs_len or
        !rangeFits(
            function_step.constraint_pairs_start,
            function_step.constraint_pairs_len,
            env.where_marker_constraint_copy_pairs.items.items.len,
        ))
    {
        return false;
    }
    const pair = env.where_marker_constraint_copy_pairs.items.items[
        function_step.constraint_pairs_start + copied.function_component_ref.constraint_pair_offset
    ];
    if (pair.source_constraint_index < group.source_constraints_start or
        pair.destination_constraint_index < group.destination_constraints_start)
    {
        return false;
    }
    const source_offset = pair.source_constraint_index - group.source_constraints_start;
    const destination_offset = pair.destination_constraint_index - group.destination_constraints_start;
    return source_offset == destination_offset and source_offset < group.source_constraints_len;
}

fn copiedOpenLiteralConstraintKind(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    constraint_index: u32,
) ?ModuleEnv.CopiedOpenLiteralEvent.LiteralKind {
    if (constraint_index >= types.static_dispatch_constraints.items.items.len) return null;
    const constraint = types.static_dispatch_constraints.items.items[constraint_index];
    const kind = literal_defaulting.constraintLiteralKind(.{
        .from_numeral = cir.idents.from_numeral,
        .from_quote = cir.idents.from_quote,
        .from_interpolation = cir.idents.from_interpolation,
    }, constraint) orelse return null;
    return copiedOpenLiteralKind(kind);
}

fn copiedOpenLiteralSourceKindForCopiedConstraint(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    copied: ModuleEnv.DispatchSettlementSource.CopiedConstraint,
) ?ModuleEnv.CopiedOpenLiteralEvent.LiteralKind {
    if (copied.anchor_index >= cir.selected_receiver_anchors.items.items.len or
        copied.function_component_ref.copy_step_index >= cir.where_marker_copy_steps.items.items.len)
    {
        return null;
    }
    const function_step = cir.where_marker_copy_steps.items.items[
        copied.function_component_ref.copy_step_index
    ];
    if (copied.function_component_ref.constraint_pair_offset >= function_step.constraint_pairs_len or
        !rangeFits(
            function_step.constraint_pairs_start,
            function_step.constraint_pairs_len,
            cir.where_marker_constraint_copy_pairs.items.items.len,
        ))
    {
        return null;
    }
    const pair = cir.where_marker_constraint_copy_pairs.items.items[
        function_step.constraint_pairs_start + copied.function_component_ref.constraint_pair_offset
    ];
    const constraint_index = if ((function_step.decodedKind() orelse return null).sourceNamespace() == .local)
        pair.source_constraint_index
    else
        cir.selected_receiver_anchors.items.items[copied.anchor_index].constraint_index;
    return copiedOpenLiteralConstraintKind(types, cir, constraint_index);
}

fn copiedOpenLiteralEventCreationConstraint(
    env: *const ModuleEnv,
    event_index: u32,
) ?u32 {
    const events = env.copied_open_literal_events.items.items;
    const groups = env.copied_open_literal_groups.items.items;
    if (event_index >= events.len) return null;
    const event = events[event_index];
    if (event.group_index >= groups.len) return null;
    const group = groups[event.group_index];
    if (event.constraint_offset >= group.destination_constraints_len) return null;
    return std.math.add(
        u32,
        group.destination_constraints_start,
        event.constraint_offset,
    ) catch null;
}

/// Validate the canonical partition and BFS certificate for every persisted
/// marker-copy proof without allocating. Contextual admission separately
/// replays each typed semantic edge against its exact fresh/admitted origin;
/// this layer proves that cached bytes form a closed, gapless certificate and
/// cannot hide a disconnected pair component.
fn validateWhereMarkerCopyProofLocal(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
) bool {
    const none = std.math.maxInt(u32);
    const type_len: usize = @intCast(types.len());
    const constraints = types.static_dispatch_constraints.items.items;
    const steps = cir.where_marker_copy_steps.items.items;
    const all_pairs = cir.where_marker_copy_pairs.items.items;
    const all_occurrences = cir.where_marker_copy_occurrences.items.items;
    const all_constraint_pairs = cir.where_marker_constraint_copy_pairs.items.items;
    const all_witnesses = cir.where_marker_copy_witnesses.items.items;
    const copied_groups = cir.copied_open_literal_groups.items.items;
    const copied_events = cir.copied_open_literal_events.items.items;
    const substitutions = cir.where_marker_platform_substitutions.items.items;
    const expected_plans = cir.expected_consumption_plans.items.items;
    const settlement_sources = cir.dispatch_settlement_sources.items.items;

    var pair_end: usize = 0;
    var occurrence_end: usize = 0;
    var constraint_pair_end: usize = 0;
    var witness_end: usize = 0;
    var copied_group_end: usize = 0;
    var copied_event_end: usize = 0;
    var substitution_end: usize = 0;
    for (steps, 0..) |step, step_index| {
        const kind = step.decodedKind() orelse return false;
        if (kind == .reserved or kind == .discarded) return false;
        const copy_policy = step.decodedCopyPolicy() orelse return false;
        if (!whereMarkerCopyOriginReservedIsZero(step, kind) or
            !whereMarkerCopyOriginAllowsPolicy(kind, copy_policy) or
            step.destination_root_var >= type_len)
        {
            return false;
        }
        if (kind.sourceNamespace() == .local and step.source_root_var >= type_len) return false;

        if (step.pairs_len == 0 or step.pairs_start != pair_end or
            !rangeFits(step.pairs_start, step.pairs_len, all_pairs.len))
        {
            return false;
        }
        const pairs = all_pairs[step.pairs_start..][0..step.pairs_len];
        var root_offset: ?u32 = null;
        for (pairs, 0..) |pair, pair_offset| {
            if (pair.destination_var >= type_len or
                (kind.sourceNamespace() == .local and pair.source_var >= type_len) or
                (pair_offset != 0 and !durableWhereMarkerCopyPairLessThan(
                    {},
                    pairs[pair_offset - 1],
                    pair,
                )))
            {
                return false;
            }
            if (pair.source_var == step.source_root_var and
                pair.destination_var == step.destination_root_var)
            {
                if (root_offset != null) return false;
                root_offset = @intCast(pair_offset);
            }
        }
        const root = root_offset orelse return false;
        pair_end += step.pairs_len;

        if (step.occurrences_len == 0 or step.occurrences_start != occurrence_end or
            !rangeFits(step.occurrences_start, step.occurrences_len, all_occurrences.len) or
            step.root_occurrence_offset >= step.occurrences_len)
        {
            return false;
        }
        const occurrences = all_occurrences[step.occurrences_start..][0..step.occurrences_len];
        if (!whereMarkerRawOccurrenceRelationIsFunctional(occurrences)) return false;
        var expected_pair_offset: u32 = 0;
        for (occurrences, 0..) |occurrence, occurrence_offset| {
            if (occurrence.canonical_pair_offset >= pairs.len or
                occurrence.raw_destination_var >= type_len or
                (kind.sourceNamespace() == .local and occurrence.raw_source_var >= type_len) or
                (occurrence_offset != 0 and !whereMarkerCopyOccurrenceLessThan(
                    {},
                    occurrences[occurrence_offset - 1],
                    occurrence,
                )))
            {
                return false;
            }
            if (occurrence.canonical_pair_offset > expected_pair_offset) return false;
            if (occurrence.canonical_pair_offset == expected_pair_offset and
                (occurrence_offset == 0 or
                    occurrences[occurrence_offset - 1].canonical_pair_offset != expected_pair_offset))
            {
                expected_pair_offset = std.math.add(u32, expected_pair_offset, 1) catch return false;
            }
            const canonical_pair = pairs[occurrence.canonical_pair_offset];
            if (types.resolveVar(@enumFromInt(occurrence.raw_destination_var)).var_ !=
                @as(Var, @enumFromInt(canonical_pair.destination_var)))
            {
                return false;
            }
            if (kind.sourceNamespace() == .local and
                types.resolveVar(@enumFromInt(occurrence.raw_source_var)).var_ !=
                    @as(Var, @enumFromInt(canonical_pair.source_var)))
            {
                return false;
            }
        }
        if (expected_pair_offset != pairs.len or
            occurrences[step.root_occurrence_offset].canonical_pair_offset != root)
        {
            return false;
        }
        switch (kind) {
            .expected_call_instantiation => {
                if (!expectedCallInstantiationStepMatchesSource(cir, step_index)) return false;
            },
            .predeclared_annotation => {
                const origin = step.origin.predeclared_annotation;
                const root_occurrence = occurrences[step.root_occurrence_offset];
                if (origin.node >= cir.store.nodes.len() or
                    root_occurrence.raw_source_var != origin.node)
                {
                    return false;
                }
                var attachment_matches: usize = 0;
                for (cir.body_annotation_attachments.items.items, 0..) |attachment, attachment_index| {
                    if (attachment.annotation_root == origin.node and
                        cir.bodyAnnotationAttachmentIsLocallyValid(@intCast(attachment_index)))
                    {
                        attachment_matches += 1;
                    }
                }
                if (attachment_matches != 1) return false;
            },
            .record_update_base => {
                const origin = step.origin.record_update_base;
                const root_occurrence = occurrences[step.root_occurrence_offset];
                if (origin.base_expr >= type_len or
                    (!recordUpdateBaseOriginMatchesCanonicalEdge(cir, origin) and
                        !recordUpdateBaseStepHasRetiredSource(
                            cir,
                            @intCast(step_index),
                            origin,
                        )) or
                    origin.decodedRootBinding() == null)
                {
                    return false;
                }
                const root_pair = pairs[root_occurrence.canonical_pair_offset];
                switch (origin.decodedRootBinding().?) {
                    .direct_request => if (root_occurrence.raw_source_var != origin.base_expr) {
                        return false;
                    },
                    .redirected_identity_share => {
                        if (root_occurrence.raw_source_var == origin.base_expr or
                            root_occurrence.raw_source_var != root_occurrence.raw_destination_var or
                            root_pair.source_var != root_pair.destination_var or
                            types.resolveVar(@enumFromInt(origin.base_expr)).var_ !=
                                @as(Var, @enumFromInt(root_pair.source_var)))
                        {
                            return false;
                        }
                    },
                }
            },
            .aggregate_fresh_shape_child => {
                const origin = step.origin.aggregate_fresh_shape_child;
                if (origin.expected_plans_len == 0 or
                    !rangeFits(
                        origin.expected_plans_start,
                        origin.expected_plans_len,
                        expected_plans.len,
                    ) or origin.parent_authority.decodedKind() != .copy_occurrence or
                    expectedParentAuthorityRawForProof(
                        cir,
                        origin.parent_authority,
                        steps,
                        all_occurrences,
                        step_index,
                    ) == null)
                {
                    return false;
                }
                const root_occurrence = occurrences[step.root_occurrence_offset];
                const plans = expected_plans[origin.expected_plans_start..][0..origin.expected_plans_len];
                const plan_range_start: usize = origin.expected_plans_start;
                const plan_range_end = plan_range_start + @as(usize, origin.expected_plans_len);
                const first_role = plans[0].decodedRole() orelse return false;
                if (first_role == .list_element) {
                    const owner = cir.store.getExpr(@enumFromInt(plans[0].owner_node));
                    const list = switch (owner) {
                        .e_list => |present| present,
                        else => return false,
                    };
                    if (cir.store.exprSlice(list.elems).len != plans.len) return false;
                } else if (plans.len != 1) {
                    return false;
                }
                for (plans, 0..) |plan, relative_plan_index| {
                    if (!plan.hasLegalTags() or plan.decodedOutcome() != .anchored or
                        plan.decodedReason() != null or
                        plan.raw_consumer_var != root_occurrence.raw_source_var or
                        !expectedMarkerAuthoritiesEqual(plan.parent_authority, origin.parent_authority) or
                        plan.produced_copy_step != step_index or
                        plan.produced_occurrence_offset != step.root_occurrence_offset or
                        plan.decodedProducedSide() != .destination or
                        plan.call_root_plan_index != none or
                        !plan.failure_owner.hasCanonicalTags(false) or
                        plan.failure_cause_plan_index != none or
                        !expectedFreshShapePlanMatchesCir(cir, plan))
                    {
                        return false;
                    }
                    if (first_role == .list_element and
                        (plan.owner_node != plans[0].owner_node or
                            plan.decodedRole() != first_role or
                            plan.slot != @as(u32, @intCast(relative_plan_index))))
                    {
                        return false;
                    }
                }
                for (expected_plans, 0..) |plan, plan_index| {
                    if (plan.produced_copy_step != step_index) continue;
                    if (plan_index < plan_range_start or plan_index >= plan_range_end) {
                        return false;
                    }
                }
            },
            .aggregate_expected_projection, .branch_expected_copy => {
                const origin = if (kind == .aggregate_expected_projection)
                    step.origin.aggregate_expected_projection
                else
                    step.origin.branch_expected_copy;
                // Evidence-free plans authorize only producer-authored plan
                // transitions. Aggregate projection copies never borrow them;
                // the branch validator admits them only for the exact flexed
                // seed plan which consumes that authority.
                if (kind == .aggregate_expected_projection and
                    origin.parent_authority.decodedKind() == .evidence_free_plan)
                {
                    return false;
                }
                const selected_parent_raw = expectedParentAuthorityRawForProof(
                    cir,
                    origin.parent_authority,
                    steps,
                    all_occurrences,
                    step_index,
                ) orelse return false;
                if (occurrences[step.root_occurrence_offset].raw_source_var != selected_parent_raw) {
                    return false;
                }
                if (!whereMarkerExpectedConsumerMatches(
                    types,
                    cir,
                    step_index,
                    step,
                    kind,
                    origin,
                    occurrences[step.root_occurrence_offset],
                )) {
                    return false;
                }
            },
            else => {},
        }
        occurrence_end += step.occurrences_len;

        if (step.constraint_pairs_start != constraint_pair_end or
            !rangeFits(step.constraint_pairs_start, step.constraint_pairs_len, all_constraint_pairs.len))
        {
            return false;
        }
        const constraint_pairs = all_constraint_pairs[step.constraint_pairs_start..][0..step.constraint_pairs_len];
        for (constraint_pairs, 0..) |pair, pair_offset| {
            if (pair.destination_constraint_index >= constraints.len or
                (kind.sourceNamespace() == .local and pair.source_constraint_index >= constraints.len) or
                (kind.sourceNamespace() == .local and
                    pair.source_constraint_index == pair.destination_constraint_index) or
                (pair_offset != 0 and !ModuleEnv.WhereMarkerConstraintCopyPair.canonicalLessThan(
                    constraint_pairs[pair_offset - 1],
                    pair,
                )))
            {
                return false;
            }
        }
        constraint_pair_end += step.constraint_pairs_len;

        if (step.witnesses_start != witness_end or
            !rangeFits(step.witnesses_start, step.witnesses_len, all_witnesses.len))
        {
            return false;
        }
        const witnesses = all_witnesses[step.witnesses_start..][0..step.witnesses_len];
        var root_action_count: usize = 0;
        var root_traverse_action = false;
        var root_structural_outgoing_count: usize = 0;
        for (witnesses, 0..) |witness, witness_offset| {
            const edge_kind = witness.decodedEdgeKind() orelse return false;
            const action = witness.decodedAction() orelse return false;
            const auxiliary = witness.decodedAuxiliaryOriginKind() orelse return false;
            if (witness.parent_occurrence_offset >= occurrences.len or
                witness.child_occurrence_offset >= occurrences.len or
                (witness.constraint_pair_offset != none and
                    witness.constraint_pair_offset >= constraint_pairs.len) or
                (witness_offset != 0 and !ModuleEnv.WhereMarkerCopyWitness.canonicalLessThan(
                    witnesses[witness_offset - 1],
                    witness,
                )))
            {
                return false;
            }
            const child_occurrence = occurrences[witness.child_occurrence_offset];
            const child_pair_offset = child_occurrence.canonical_pair_offset;
            if (!whereMarkerCopyPolicyAllowsAction(copy_policy, action) or
                !whereMarkerWitnessActionAuxiliaryIsValid(action, auxiliary))
            {
                return false;
            }
            if (whereMarkerWitnessActionIsRequirementComponentIngress(action) and
                !whereMarkerWitnessEdgeIsRequirementComponentIngress(edge_kind))
            {
                return false;
            }
            if (witness.parent_occurrence_offset == step.root_occurrence_offset and
                child_pair_offset != root and
                !whereMarkerWitnessActionIsRequirementComponentIngress(action))
            {
                root_structural_outgoing_count += 1;
            }
            const raw_present = witness.raw_source_var != none or witness.raw_destination_var != none;
            if (raw_present and
                (witness.raw_source_var == none or witness.raw_destination_var == none or
                    witness.raw_source_var >= type_len or witness.raw_destination_var >= type_len))
            {
                return false;
            }
            const child_pair = pairs[child_pair_offset];
            if (raw_present) {
                if (witness.raw_source_var != child_occurrence.raw_source_var or
                    witness.raw_destination_var != child_occurrence.raw_destination_var or
                    types.resolveVar(@enumFromInt(witness.raw_source_var)).var_ !=
                        @as(Var, @enumFromInt(child_pair.source_var)) or
                    types.resolveVar(@enumFromInt(witness.raw_destination_var)).var_ !=
                        @as(Var, @enumFromInt(child_pair.destination_var)))
                {
                    return false;
                }
            }
            if (whereMarkerWitnessActionClaimsFreshFlexAllocation(action)) {
                for (witnesses[0..witness_offset]) |prior_witness| {
                    const prior_action = prior_witness.decodedAction() orelse return false;
                    if (whereMarkerWitnessActionClaimsFreshFlexAllocation(prior_action) and
                        prior_witness.child_occurrence_offset == witness.child_occurrence_offset)
                    {
                        return false;
                    }
                }
            }
            switch (action) {
                .traverse, .binding_codec_reuse_cut, .platform_preseed_cut, .requirement_component_ingress => if (raw_present) return false,
                .local_raw_identity_share_cut,
                .rigid_fresh_flex_cut,
                .rigid_fresh_rigid_cut,
                .flex_fresh_flex_copy,
                .requirement_component_fresh_flex_copy,
                .exact_annotation_substitution_cut,
                .polarity_open_cut,
                .polarity_close_cut,
                .polarity_preserve_cut,
                => if (!raw_present) return false,
            }
            if (action == .local_raw_identity_share_cut and
                witness.raw_source_var != witness.raw_destination_var)
            {
                return false;
            }
            if ((action == .flex_fresh_flex_copy or
                action == .requirement_component_fresh_flex_copy) and
                witness.raw_source_var == witness.raw_destination_var)
            {
                return false;
            }
            if (auxiliary == .none and witness.auxiliary_origin_index != 0) return false;
            if (auxiliary != .binding_copy_pair and witness.auxiliary_origin_step != 0) {
                return false;
            }
            if (auxiliary == .binding_copy_pair and !bindingCodecReuseOriginIsValid(
                steps,
                all_pairs,
                all_occurrences,
                all_witnesses,
                step_index,
                witness,
                child_pair,
            )) {
                return false;
            }
            switch (edge_kind) {
                .root_copy_action => {
                    root_action_count += 1;
                    root_traverse_action = action == .traverse;
                    if (witness.parent_occurrence_offset != step.root_occurrence_offset or
                        witness.child_occurrence_offset != step.root_occurrence_offset or
                        witness.constraint_pair_offset != none)
                    {
                        return false;
                    }
                },
                .static_dispatch_function,
                .interpolation_part,
                .interpolation_item,
                .scheme_requirement_function,
                => if (witness.constraint_pair_offset == none) return false,
                .scheme_requirement_receiver => if (witness.constraint_pair_offset != none) return false,
                .alias_backing,
                .alias_argument,
                .tuple_element,
                .nominal_argument,
                .function_argument,
                .function_return,
                .function_effect_dependency,
                .record_field_type,
                .record_field_presence,
                .record_extension,
                .record_unbound_field_type,
                .record_unbound_field_presence,
                .tag_payload,
                .tag_extension,
                => if (witness.constraint_pair_offset != none) return false,
            }
        }
        // A pair-bearing interpolation/reference edge is not a producer for
        // the copied constraint. Every pair must have exactly one primary
        // function witness whose exact coordinates the copied-source converse
        // below replays.
        for (constraint_pairs, 0..) |_, constraint_pair_offset| {
            var primary_function_count: usize = 0;
            for (witnesses) |witness| {
                if (witness.constraint_pair_offset != constraint_pair_offset) continue;
                switch (witness.decodedEdgeKind() orelse return false) {
                    .static_dispatch_function, .scheme_requirement_function => primary_function_count += 1,
                    else => {},
                }
            }
            if (primary_function_count != 1) return false;
        }
        for (witnesses) |interpolation_witness| {
            const interpolation_edge = interpolation_witness.decodedEdgeKind() orelse return false;
            if (interpolation_edge != .interpolation_part and
                interpolation_edge != .interpolation_item)
            {
                continue;
            }
            const interpolation_action = interpolation_witness.decodedAction() orelse return false;
            var primary: ?ModuleEnv.WhereMarkerCopyWitness = null;
            for (witnesses) |candidate| {
                if (candidate.constraint_pair_offset != interpolation_witness.constraint_pair_offset) continue;
                switch (candidate.decodedEdgeKind() orelse return false) {
                    .static_dispatch_function, .scheme_requirement_function => {
                        if (primary != null) return false;
                        primary = candidate;
                    },
                    else => {},
                }
            }
            const primary_witness = primary orelse return false;
            const primary_edge = primary_witness.decodedEdgeKind() orelse return false;
            const primary_auxiliary = primary_witness.decodedAuxiliaryOriginKind() orelse return false;
            const detached_local_ingress = kind.sourceNamespace() == .local and
                primary_edge == .scheme_requirement_function and
                primary_auxiliary == .none;
            if (whereMarkerWitnessActionIsRequirementComponentIngress(interpolation_action) !=
                detached_local_ingress)
            {
                return false;
            }
            if (detached_local_ingress and
                (interpolation_witness.parent_occurrence_offset !=
                    primary_witness.parent_occurrence_offset or
                    interpolation_witness.parent_occurrence_offset != step.root_occurrence_offset))
            {
                return false;
            }
        }
        for (witnesses) |receiver_witness| {
            if (receiver_witness.decodedEdgeKind() != .scheme_requirement_receiver) continue;
            const receiver_action = receiver_witness.decodedAction() orelse return false;
            if (receiver_witness.parent_occurrence_offset != step.root_occurrence_offset or
                !whereMarkerWitnessActionIsRequirementComponentIngress(receiver_action) or
                receiver_witness.decodedAuxiliaryOriginKind() != .none or
                receiver_witness.auxiliary_origin_index != 0)
            {
                return false;
            }
            var matching_receivers: usize = 0;
            var matching_functions: usize = 0;
            for (witnesses) |candidate| {
                if (candidate.parent_occurrence_offset != receiver_witness.parent_occurrence_offset or
                    candidate.edge_index != receiver_witness.edge_index)
                {
                    continue;
                }
                switch (candidate.decodedEdgeKind() orelse return false) {
                    .scheme_requirement_receiver => matching_receivers += 1,
                    .scheme_requirement_function => {
                        const candidate_action = candidate.decodedAction() orelse return false;
                        if (!whereMarkerWitnessActionIsRequirementComponentIngress(candidate_action) or
                            candidate.decodedAuxiliaryOriginKind() != .none or
                            candidate.auxiliary_origin_index != 0)
                        {
                            return false;
                        }
                        matching_functions += 1;
                    },
                    else => {},
                }
            }
            if (matching_receivers != 1 or matching_functions > 1) return false;
            if (matching_functions == 0) {
                const receiver_occurrence = occurrences[receiver_witness.child_occurrence_offset];
                if (kind.sourceNamespace() != .local or
                    receiver_occurrence.raw_source_var != receiver_occurrence.raw_destination_var)
                {
                    return false;
                }
            }
        }
        // The reverse half rejects a function ingress whose receiver group was
        // deleted in concert. Binding-codec ingresses have their own explicit
        // two-step composite replay and therefore carry the distinct auxiliary
        // origin rather than participating in this same-step group.
        for (witnesses) |function_witness| {
            if (function_witness.decodedEdgeKind() != .scheme_requirement_function or
                function_witness.decodedAuxiliaryOriginKind() != .none)
            {
                continue;
            }
            const function_action = function_witness.decodedAction() orelse return false;
            if (function_witness.parent_occurrence_offset != step.root_occurrence_offset or
                !whereMarkerWitnessActionIsRequirementComponentIngress(function_action) or
                function_witness.auxiliary_origin_index != 0)
            {
                return false;
            }
            var matching_receivers: usize = 0;
            for (witnesses) |candidate| {
                if (candidate.decodedEdgeKind() == .scheme_requirement_receiver and
                    candidate.parent_occurrence_offset == function_witness.parent_occurrence_offset and
                    candidate.edge_index == function_witness.edge_index)
                {
                    matching_receivers += 1;
                }
            }
            if (matching_receivers != 1) return false;
        }
        for (constraint_pairs, 0..) |_, constraint_pair_offset| {
            var copied_source_count: usize = 0;
            for (settlement_sources) |source| {
                if (source.decodedKind() != .copied_constraint) continue;
                const function_ref = source.payload.copied_constraint.function_component_ref;
                if (function_ref.copy_step_index == @as(u32, @intCast(step_index)) and
                    function_ref.constraint_pair_offset == constraint_pair_offset)
                {
                    copied_source_count += 1;
                }
            }
            if (copied_source_count != 1) return false;
        }

        if (step.copied_groups_start != copied_group_end or
            !rangeFits(step.copied_groups_start, step.copied_groups_len, copied_groups.len))
        {
            return false;
        }
        const step_groups = copied_groups[step.copied_groups_start..][0..step.copied_groups_len];
        for (step_groups, 0..) |group, relative_group_index| {
            const group_index = step.copied_groups_start + @as(u32, @intCast(relative_group_index));
            if (!group.hasCanonicalTags() or
                group.copy_step_index != @as(u32, @intCast(step_index)) or
                group.receiver_occurrence_offset >= step.occurrences_len or
                (relative_group_index != 0 and
                    !ModuleEnv.CopiedOpenLiteralGroup.canonicalLessThan(
                        step_groups[relative_group_index - 1],
                        group,
                    )) or
                group.events_start != copied_event_end or
                !rangeFits(group.events_start, group.events_len, copied_events.len))
            {
                return false;
            }
            const receiver_occurrence = occurrences[group.receiver_occurrence_offset];
            if (kind.sourceNamespace() == .local and
                receiver_occurrence.raw_source_var == receiver_occurrence.raw_destination_var)
            {
                return false;
            }
            const events = copied_events[group.events_start..][0..group.events_len];
            for (events, 0..) |event, relative_event_index| {
                if (!event.hasCanonicalTags() or event.group_index != group_index or
                    event.constraint_offset >= group.destination_constraints_len or
                    (relative_event_index != 0 and
                        !ModuleEnv.CopiedOpenLiteralEvent.canonicalLessThan(
                            events[relative_event_index - 1],
                            event,
                        )))
                {
                    return false;
                }
            }

            for (0..group.source_constraints_len) |raw_constraint_offset| {
                const constraint_offset: u32 = @intCast(raw_constraint_offset);
                const expected_source = std.math.add(
                    u32,
                    group.source_constraints_start,
                    constraint_offset,
                ) catch return false;
                const expected_destination = std.math.add(
                    u32,
                    group.destination_constraints_start,
                    constraint_offset,
                ) catch return false;
                if (expected_destination >= constraints.len) return false;

                var source_count: usize = 0;
                for (settlement_sources) |source| {
                    if (source.decodedKind() != .copied_constraint) continue;
                    const copied = source.payload.copied_constraint;
                    if (!copiedOpenLiteralGroupContainsSource(cir, group, copied) or
                        copied.anchor_index >= cir.selected_receiver_anchors.items.items.len)
                    {
                        continue;
                    }
                    const anchor = cir.selected_receiver_anchors.items.items[copied.anchor_index];
                    const function_step = steps[copied.function_component_ref.copy_step_index];
                    const pair = all_constraint_pairs[
                        function_step.constraint_pairs_start +
                            copied.function_component_ref.constraint_pair_offset
                    ];
                    if (pair.source_constraint_index == expected_source and
                        pair.destination_constraint_index == expected_destination and
                        anchor.constraint_index == expected_destination)
                    {
                        source_count += 1;
                    }
                }
                if (source_count != 1) return false;

                const expected_kind = copiedOpenLiteralConstraintKind(
                    types,
                    cir,
                    if (kind.sourceNamespace() == .local) expected_source else expected_destination,
                );
                var event_count: usize = 0;
                for (events, 0..) |event, relative_event_index| {
                    if (event.constraint_offset != constraint_offset) continue;
                    if (expected_kind == null or event.decodedLiteralKind() != expected_kind.?) {
                        return false;
                    }
                    const event_index = group.events_start + @as(u32, @intCast(relative_event_index));
                    const evidence = constraints[expected_destination].constraint_evidence;
                    if (!rangeFits(evidence.start, evidence.len, types.constraint_evidence_handles.items.items.len)) {
                        return false;
                    }
                    var handle_count: usize = 0;
                    for (types.constraint_evidence_handles.items.items[evidence.start..][0..evidence.len]) |handle| {
                        if (handle.decodedKind() == .copied_literal_event and
                            handle.index == event_index)
                        {
                            handle_count += 1;
                        }
                    }
                    if (handle_count != 1) return false;
                    var terminal_occurrence_count: usize = 0;
                    for (constraints, 0..) |candidate_constraint, candidate_constraint_index| {
                        if (!rangeFits(
                            candidate_constraint.constraint_evidence.start,
                            candidate_constraint.constraint_evidence.len,
                            types.constraint_evidence_handles.items.items.len,
                        )) return false;
                        var occurrence_count: usize = 0;
                        for (types.constraint_evidence_handles.items.items[candidate_constraint.constraint_evidence.start..][0..candidate_constraint.constraint_evidence.len]) |candidate_handle| {
                            if (candidate_handle.decodedKind() == .copied_literal_event and
                                candidate_handle.index == event_index)
                            {
                                occurrence_count += 1;
                            }
                        }
                        if (occurrence_count > 1) return false;
                        if (occurrence_count == 1) {
                            if (!constraintEvidenceHasCreationPath(
                                cir,
                                .{
                                    .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.copied_literal_event),
                                    .index = event_index,
                                },
                                expected_destination,
                                @intCast(candidate_constraint_index),
                            )) return false;
                            terminal_occurrence_count += 1;
                        }
                    }
                    if (terminal_occurrence_count == 0) return false;
                    event_count += 1;
                }
                if (event_count != @intFromBool(expected_kind != null)) return false;
            }
            copied_event_end += group.events_len;
        }
        copied_group_end += step.copied_groups_len;

        // Every ordinary copied source belongs to the unique group for its
        // fresh receiver whenever that receiver copied at least one literal
        // constraint. The detached binding-codec ingress spans two proof
        // steps and is a distinct, non-literal composite source.
        for (settlement_sources) |source| {
            if (source.decodedKind() != .copied_constraint) continue;
            const copied = source.payload.copied_constraint;
            if (copied.receiver_component_ref.copy_step_index != @as(u32, @intCast(step_index))) continue;
            if (copied.anchor_index >= cir.selected_receiver_anchors.items.items.len) return false;
            const eligible = copied.function_component_ref.copy_step_index == @as(u32, @intCast(step_index));
            const is_literal = copiedOpenLiteralSourceKindForCopiedConstraint(types, cir, copied) != null;
            if (!eligible) {
                if (is_literal) return false;
                continue;
            }
            var matching_group_count: usize = 0;
            var containing_group_count: usize = 0;
            var receiver_has_literal = false;
            if (copied.receiver_component_ref.occurrence_offset >= step.occurrences_len) return false;
            const copied_receiver_occurrence = occurrences[copied.receiver_component_ref.occurrence_offset];
            const fresh_receiver = kind.sourceNamespace() == .cross_module or
                copied_receiver_occurrence.raw_source_var != copied_receiver_occurrence.raw_destination_var;
            for (settlement_sources) |candidate_source| {
                if (candidate_source.decodedKind() != .copied_constraint) continue;
                const candidate = candidate_source.payload.copied_constraint;
                if (candidate.function_component_ref.copy_step_index != @as(u32, @intCast(step_index)) or
                    !std.meta.eql(candidate.receiver_component_ref, copied.receiver_component_ref) or
                    candidate.anchor_index >= cir.selected_receiver_anchors.items.items.len)
                {
                    continue;
                }
                receiver_has_literal = receiver_has_literal or
                    copiedOpenLiteralSourceKindForCopiedConstraint(types, cir, candidate) != null;
            }
            for (step_groups) |group| {
                if (!copiedOpenLiteralComponentMatchesReceiver(
                    cir,
                    group,
                    copied.receiver_component_ref,
                )) continue;
                matching_group_count += 1;
                if (copiedOpenLiteralGroupContainsSource(cir, group, copied)) {
                    containing_group_count += 1;
                }
            }
            const expects_group = fresh_receiver and receiver_has_literal;
            if (matching_group_count != @intFromBool(expects_group) or
                containing_group_count != @intFromBool(expects_group))
            {
                return false;
            }
        }
        if (root_action_count > 1 or
            (root_traverse_action and root_structural_outgoing_count != 0) or
            (root_action_count == 0 and root_structural_outgoing_count == 0))
        {
            return false;
        }
        if (kind == .record_update_base and
            step.origin.record_update_base.decodedRootBinding() == .redirected_identity_share)
        {
            const root_occurrence = occurrences[step.root_occurrence_offset];
            var matching_share_actions: usize = 0;
            for (witnesses) |witness| {
                if (witness.decodedEdgeKind() == .root_copy_action and
                    witness.parent_occurrence_offset == step.root_occurrence_offset and
                    witness.child_occurrence_offset == step.root_occurrence_offset and
                    witness.decodedAction() == .local_raw_identity_share_cut and
                    witness.decodedAuxiliaryOriginKind() == .none and
                    witness.auxiliary_origin_step == 0 and
                    witness.auxiliary_origin_index == 0 and
                    witness.raw_source_var == root_occurrence.raw_source_var and
                    witness.raw_destination_var == root_occurrence.raw_destination_var)
                {
                    matching_share_actions += 1;
                }
            }
            if (matching_share_actions != 1) return false;
        }
        witness_end += step.witnesses_len;

        if (kind == .platform_requirement) {
            const platform = step.origin.platform_requirement;
            if (platform.substitutions_start != substitution_end or
                !rangeFits(platform.substitutions_start, platform.substitutions_len, substitutions.len))
            {
                return false;
            }
            substitution_end += platform.substitutions_len;
        }

        for (pairs, 0..) |pair, pair_offset| {
            if (pair_offset == root) {
                if (pair.discovery_depth != 0 or pair.predecessor_pair_offset != none or
                    pair.predecessor_edge_ordinal != none)
                {
                    return false;
                }
                continue;
            }
            if (pair.discovery_depth == 0 or pair.discovery_depth == none or
                pair.predecessor_pair_offset >= pairs.len or pair.predecessor_edge_ordinal == none)
            {
                return false;
            }
            var best_parent: u32 = none;
            var best_ordinal: u32 = none;
            for (witnesses, 0..) |witness, witness_index| {
                const witness_parent_pair = occurrences[witness.parent_occurrence_offset].canonical_pair_offset;
                const witness_child_pair = occurrences[witness.child_occurrence_offset].canonical_pair_offset;
                var parent_edge_ordinal: u32 = 0;
                for (witnesses[0..witness_index]) |prior| {
                    const prior_parent = occurrences[prior.parent_occurrence_offset].canonical_pair_offset;
                    if (prior_parent != witness_parent_pair) continue;
                    parent_edge_ordinal = std.math.add(u32, parent_edge_ordinal, 1) catch return false;
                }
                if (witness_parent_pair == witness_child_pair) continue;
                const predecessor_parent = pairs[witness_parent_pair];
                const predecessor_child = pairs[witness_child_pair];
                const edge_limit = std.math.add(u32, predecessor_parent.discovery_depth, 1) catch return false;
                if (predecessor_child.discovery_depth > edge_limit) return false;
                if (witness_child_pair != pair_offset or edge_limit != pair.discovery_depth) continue;
                if (best_parent == none or witness_parent_pair < best_parent or
                    (witness_parent_pair == best_parent and parent_edge_ordinal < best_ordinal))
                {
                    best_parent = witness_parent_pair;
                    best_ordinal = parent_edge_ordinal;
                }
            }
            if (pair.predecessor_pair_offset != best_parent or
                pair.predecessor_edge_ordinal != best_ordinal)
            {
                return false;
            }
        }
    }
    for (constraints, 0..) |constraint, constraint_index| {
        if (!rangeFits(
            constraint.constraint_evidence.start,
            constraint.constraint_evidence.len,
            types.constraint_evidence_handles.items.items.len,
        )) return false;
        for (types.constraint_evidence_handles.items.items[constraint.constraint_evidence.start..][0..constraint.constraint_evidence.len]) |handle| {
            if (handle.decodedKind() != .copied_literal_event) continue;
            if (handle.index >= copied_events.len) return false;
            const event = copied_events[handle.index];
            if (event.group_index >= copied_groups.len) return false;
            const group = copied_groups[event.group_index];
            const expected_constraint = std.math.add(
                u32,
                group.destination_constraints_start,
                event.constraint_offset,
            ) catch return false;
            if (!constraintEvidenceHasCreationPath(
                cir,
                handle,
                expected_constraint,
                @intCast(constraint_index),
            )) return false;
        }
    }

    return pair_end == all_pairs.len and
        occurrence_end == all_occurrences.len and
        constraint_pair_end == all_constraint_pairs.len and
        witness_end == all_witnesses.len and
        copied_group_end == copied_groups.len and
        copied_event_end == copied_events.len and
        substitution_end == substitutions.len;
}

fn validateLocalW6bProof(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
) bool {
    return validateExpectedFailureRetirementLocal(types, cir) and
        validateExternalCacheSeedsLocal(cir) and
        validateWhereMarkerCopyProofLocal(types, cir) and
        validateExpectedRecordUpdatePlans(types, cir) and
        validateExpectedBranchPlans(types, cir) and
        validateExpectedCallPlans(cir);
}

fn validateRehydratedWhereMethodState(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    node_count: usize,
    builtin_ctx: BuiltinContext,
    builtin_origin_identity: base.ModuleIdentity.Idx,
) W6bSemanticValidationError!void {
    if (!validateLocalW6bProof(types, cir)) return error.CorruptArtifact;
    return validateRehydratedWhereMethodStateAfterLocalProof(
        types,
        cir,
        node_count,
        builtin_ctx,
        builtin_origin_identity,
    );
}

fn validateRehydratedWhereMethodStateAfterLocalProof(
    types: *const types_mod.Store,
    cir: *const ModuleEnv,
    node_count: usize,
    builtin_ctx: BuiltinContext,
    builtin_origin_identity: base.ModuleIdentity.Idx,
) W6bSemanticValidationError!void {
    const type_len: usize = @intCast(types.len());
    const type_len_u32: u32 = @intCast(type_len);
    const node_count_u32: u32 = @intCast(node_count);
    if (builtin_ctx.builtin_indices) |builtin_indices| {
        if (!validateDefaultDecisionTargetContext(types, cir, builtin_indices)) {
            return error.CorruptArtifact;
        }
    } else if (builtin_ctx.builtin_module != null) {
        // Both are null only while producing Builtin itself. Its owner-only
        // admission immediately reruns this validation with embedded indices.
        return error.CorruptArtifact;
    }
    const try_identity = methodOutputTryIdentity(builtin_ctx, builtin_origin_identity);
    const type_paths = types.where_method_marker_path_steps.items.items;
    const type_markers = types.where_method_marker_contracts.items.items;
    const type_bases = types.where_method_marker_bases.items.items;
    const no_producer = std.math.maxInt(u32);
    for (type_paths) |step| {
        if (!whereMethodPathStepIsValid(step) or
            !whereMethodPathStepNameIsCanonical(types, cir, step))
        {
            return error.CorruptArtifact;
        }
    }
    var owned_type_path_end: usize = 0;
    for (type_markers) |marker| {
        const owner_present = marker.producer_owner_node != no_producer;
        const where_present = marker.producer_where_node != no_producer;
        const method_present = marker.producer_method_name != no_producer;
        const position = marker.positionOrNull();
        if (position == null or marker.isWidened() == null or marker.isReady() != true or
            owner_present != where_present or owner_present != method_present or
            marker.path_len == 0 or
            !rangeFits(marker.path_start, marker.path_len, type_paths.len) or
            @as(usize, marker.path_start) != owned_type_path_end)
        {
            return error.CorruptArtifact;
        }
        if (!outputRowPositionMatchesPath(
            try_identity,
            position.?,
            type_paths[marker.path_start..][0..marker.path_len],
        )) {
            return error.CorruptArtifact;
        }
        owned_type_path_end += marker.path_len;
    }
    if (owned_type_path_end != type_paths.len) return error.CorruptArtifact;

    var owned_type_marker_end: usize = 0;
    var owned_type_basis_end: usize = 0;
    for (types.static_dispatch_constraints.items.items) |constraint| {
        const range = constraint.where_method_markers;
        if (range.len() != 0) {
            if (@intFromEnum(constraint.fn_var) >= type_len_u32 or
                !cir.getIdentStoreConst().validateExactIdx(constraint.fn_name, false) or
                !rangeFits(@intFromEnum(range.start), @intCast(range.len()), type_markers.len) or
                @as(usize, @intFromEnum(range.start)) != owned_type_marker_end)
            {
                return error.CorruptArtifact;
            }
            const constraint_resolved = types.resolveVar(constraint.fn_var);
            const skip_solved_reachability = constraint_resolved.desc.content == .err or
                constraint_resolved.desc.flags.static_dispatch_rejected;
            for (type_markers[@intFromEnum(range.start)..][0..range.len()], 0..) |marker, marker_index| {
                if (marker.producer_owner_node != no_producer or
                    marker.producer_where_node != no_producer or
                    marker.producer_method_name != no_producer)
                {
                    return error.CorruptArtifact;
                }
                if (!skip_solved_reachability) {
                    if (methodOutputPathReachesPositiveTagRow(
                        types,
                        constraint.fn_var,
                        type_paths[marker.path_start..][0..marker.path_len],
                    ) == null) {
                        return error.CorruptArtifact;
                    }
                }
                if (marker_index > 0 and types.compareWhereMethodMarkerContracts(
                    type_markers[@intFromEnum(range.start) + marker_index - 1],
                    marker,
                ) != .lt) {
                    return error.CorruptArtifact;
                }
            }
            owned_type_marker_end += range.len();
        }

        const basis_range = constraint.where_method_marker_bases;
        if (basis_range.len() != 0) {
            if (!rangeFits(@intFromEnum(basis_range.start), @intCast(basis_range.len()), type_bases.len) or
                @as(usize, @intFromEnum(basis_range.start)) != owned_type_basis_end)
            {
                return error.CorruptArtifact;
            }
            for (type_bases[@intFromEnum(basis_range.start)..][0..basis_range.len()]) |basis| {
                if (basis.marker_offset >= range.len()) return error.CorruptArtifact;
            }
            owned_type_basis_end += basis_range.len();
        }
    }
    if (owned_type_basis_end != type_bases.len) return error.CorruptArtifact;

    try validateWhereAliasExpansionLocalState(types, cir);

    const sources = cir.where_method_sources.items.items;
    for (sources, 0..) |source, source_index| {
        const expected_source_ordinal: u32 = if (source_index == 0 or
            source.owner_node != sources[source_index - 1].owner_node)
            0
        else
            std.math.add(u32, sources[source_index - 1].source_ordinal, 1) catch
                return error.CorruptArtifact;
        if (source.owner_node >= node_count_u32 or
            source.where_node >= node_count_u32 or
            !cir.getIdentStoreConst().validateExactIdx(@bitCast(source.method_ident), false) or
            source.retained_constraint_index >= types.static_dispatch_constraints.items.items.len or
            source.source_ordinal != expected_source_ordinal or
            !whereMethodSourceOwnerRootIsAuthentic(cir, source.owner_node))
        {
            return error.CorruptArtifact;
        }
        if (source.source_contracts_len == 0) {
            if (source.source_contracts_start != 0) return error.CorruptArtifact;
        } else if (!rangeFits(source.source_contracts_start, source.source_contracts_len, type_markers.len) or
            @as(usize, source.source_contracts_start) != owned_type_marker_end)
        {
            return error.CorruptArtifact;
        }
        const owner = sourceProducerOwnerForKey(
            cir,
            source.owner_node,
            source.where_node,
            source.method_ident,
        ) orelse return error.CorruptArtifact;
        if (@intFromEnum(owner.rigid_var) >= type_len_u32) return error.CorruptArtifact;

        const retained = types.static_dispatch_constraints.items.items[source.retained_constraint_index];
        if (@as(u32, @bitCast(retained.fn_name)) != source.method_ident or
            @intFromEnum(retained.fn_var) >= type_len_u32)
        {
            return error.CorruptArtifact;
        }
        const source_contracts = type_markers[source.source_contracts_start..][0..source.source_contracts_len];
        const retained_range = retained.where_method_markers;
        if (retained_range.len() != 0 and !rangeFits(
            @intFromEnum(retained_range.start),
            @intCast(retained_range.len()),
            type_markers.len,
        )) {
            return error.CorruptArtifact;
        }
        const retained_contracts: []const types_mod.WhereMethodMarkerContract = if (retained_range.len() == 0)
            &.{}
        else
            type_markers[@intFromEnum(retained_range.start)..][0..retained_range.len()];
        for (source_contracts, 0..) |contract, contract_index| {
            if (contract.producer_owner_node != source.owner_node or
                contract.producer_where_node != source.where_node or
                contract.producer_method_name != source.method_ident)
            {
                return error.CorruptArtifact;
            }
            if (contract_index > 0 and types.compareWhereMethodMarkerContracts(
                source_contracts[contract_index - 1],
                contract,
            ) != .lt) return error.CorruptArtifact;
            var matches: usize = 0;
            for (retained_contracts) |candidate| {
                if (candidate.position != contract.position) continue;
                const candidate_path = type_paths[candidate.path_start..][0..candidate.path_len];
                const contract_path = type_paths[contract.path_start..][0..contract.path_len];
                if (types_mod.compareWhereMethodMarkerPathSlices(candidate_path, contract_path) != .eq or
                    !types_mod.whereMethodMarkerNominalNamesMatch(candidate_path, contract_path))
                {
                    continue;
                }
                if (contract.isWidened() == true and candidate.isWidened() != true) {
                    return error.CorruptArtifact;
                }
                matches += 1;
            }
            if (matches != 1) return error.CorruptArtifact;
        }
        owned_type_marker_end += source.source_contracts_len;
        if (source_index > 0 and compareWhereMethodSources(sources[source_index - 1], source) != .lt) {
            return error.CorruptArtifact;
        }
    }
    if (owned_type_marker_end != type_markers.len) return error.CorruptArtifact;

    const use_pairs = cir.scheme_use_pairs.items.items;
    const marker_paths = cir.where_method_marker_path_steps.items.items;
    const marker_uses = cir.where_method_marker_uses.items.items;
    for (use_pairs) |pair| {
        if (pair.old_var >= type_len_u32 or pair.fresh_var >= type_len_u32) {
            return error.CorruptArtifact;
        }
    }
    for (marker_paths) |step| {
        if (!whereMethodPathStepIsValid(step) or
            !whereMethodPathStepNameIsCanonical(types, cir, step))
        {
            return error.CorruptArtifact;
        }
    }
    var owned_marker_end: usize = 0;
    for (cir.scheme_uses.items.items) |record| {
        const slot = std.enums.fromInt(ModuleEnv.SchemeUseRecord.Slot, record.slot_kind) orelse
            return error.CorruptArtifact;
        if (record.node_idx >= node_count_u32 or record.scheme_root >= type_len_u32 or
            !rangeFits(record.pairs_start, record.pairs_len, use_pairs.len) or
            !rangeFits(record.marker_uses_start, record.marker_uses_len, marker_uses.len))
        {
            return error.CorruptArtifact;
        }
        if (slot != .where_method_use) {
            if (record.marker_uses_len != 0) return error.CorruptArtifact;
            continue;
        }
        if (record.slot_data >= type_len_u32) return error.CorruptArtifact;

        const pairs = use_pairs[record.pairs_start..][0..record.pairs_len];
        var previous_old_var: ?u32 = null;
        const signature_root = types.resolveVar(@enumFromInt(record.scheme_root));
        var callable_pair: ?ModuleEnv.SchemeUsePair = null;
        for (pairs) |pair| {
            if (previous_old_var != null and previous_old_var.? >= pair.old_var) return error.CorruptArtifact;
            previous_old_var = pair.old_var;
            if (types.resolveVar(@as(Var, @enumFromInt(pair.old_var))).var_ == signature_root.var_) {
                if (callable_pair != null) return error.CorruptArtifact;
                callable_pair = pair;
            }
        }
        const root_pair = callable_pair orelse return error.CorruptArtifact;
        const body_callable = types.resolveVar(@enumFromInt(record.slot_data));
        if (body_callable.desc.content != .err and
            types.resolveVar(@as(Var, @enumFromInt(root_pair.fresh_var))).var_ != body_callable.var_)
        {
            return error.CorruptArtifact;
        }
        if (@as(usize, record.marker_uses_start) != owned_marker_end) return error.CorruptArtifact;
        const markers = marker_uses[record.marker_uses_start..][0..record.marker_uses_len];
        for (markers, 0..) |marker, marker_index| {
            const none = std.math.maxInt(u32);
            const position = std.enums.fromInt(types_mod.WhereMethodMarkerContract.Position, marker.position);
            if (marker.producer_owner_node == none or marker.producer_owner_node >= node_count_u32 or
                marker.producer_where_node == none or marker.producer_where_node >= node_count_u32 or
                marker.producer_method_name == none or
                !cir.getIdentStoreConst().validateExactIdx(@bitCast(marker.producer_method_name), false) or
                marker.source_row_var >= type_len_u32 or marker.source_tail_var >= type_len_u32 or
                marker.fresh_row_var >= type_len_u32 or marker.fresh_tail_var >= type_len_u32 or
                position == null or
                marker.path_len == 0 or !rangeFits(marker.path_start, marker.path_len, marker_paths.len))
            {
                return error.CorruptArtifact;
            }
            if (!whereMethodMarkerUseMatchesExactPairs(marker, pairs)) return error.CorruptArtifact;
            if (!sourceProducerKeyMatchesRecord(types, cir, record, marker)) return error.CorruptArtifact;
            if (!outputRowPositionMatchesPath(
                try_identity,
                position.?,
                marker_paths[marker.path_start..][0..marker.path_len],
            )) return error.CorruptArtifact;
            const path = marker_paths[marker.path_start..][0..marker.path_len];
            if (!methodOutputPathReachesRow(
                types,
                @enumFromInt(record.scheme_root),
                path,
                @enumFromInt(marker.source_row_var),
            ) or !tagRowTailMatches(
                types,
                @enumFromInt(marker.source_row_var),
                @enumFromInt(marker.source_tail_var),
            ) or !tagRowWrittenCountMatches(
                types,
                @enumFromInt(marker.source_row_var),
                @enumFromInt(marker.source_tail_var),
                marker.written_tag_count,
            )) return error.CorruptArtifact;
            if (marker_index > 0 and
                compareWhereMethodMarkerUses(cir, markers[marker_index - 1], marker) != .lt)
            {
                return error.CorruptArtifact;
            }
        }
        owned_marker_end += record.marker_uses_len;
    }
    if (owned_marker_end != marker_uses.len) return error.CorruptArtifact;

    const output_paths = cir.method_output_row_path_steps.items.items;
    const output_rows = cir.method_output_rows.items.items;
    for (output_paths) |step| {
        if (!whereMethodPathStepNameIsCanonical(types, cir, step)) return error.CorruptArtifact;
    }
    if (!methodOutputSlicesAreValid(
        try_identity,
        node_count,
        type_len,
        cir.method_output_publications.items.items,
        output_rows,
        output_paths,
    )) {
        return error.CorruptArtifact;
    }
    if (!methodOutputPublicationRegistryIsBijective(types, cir)) {
        return error.CorruptArtifact;
    }
    for (cir.method_output_publications.items.items) |publication| {
        const root = ModuleEnv.varFrom(@as(CIR.Node.Idx, @enumFromInt(publication.type_node_idx)));
        if (!methodOutputTypeNodeIsRegistered(cir, publication.type_node_idx) or
            !methodOutputRootIsFunction(types, root))
        {
            return error.CorruptArtifact;
        }
        const rows = output_rows[publication.rows_start..][0..publication.rows_len];
        for (rows) |row| {
            if (!methodOutputPathReachesRow(
                types,
                root,
                output_paths[row.path_start..][0..row.path_len],
                @enumFromInt(row.row_var),
            ) or !methodOutputRowTailMatches(types, row)) {
                return error.CorruptArtifact;
            }
        }
    }
    var previous_authorized_fn: ?u32 = null;
    for (cir.result_row_widening_uses.items.items) |authorization| {
        const widening = ModuleEnv.ResultRowWidening.fromBits(authorization.widening) orelse
            return error.CorruptArtifact;
        if (authorization.constraint_fn_var >= type_len_u32 or authorization.source_where_fn_var >= type_len_u32 or
            authorization.constraint_fn_var != authorization.source_where_fn_var or widening.isEmpty() or
            (previous_authorized_fn != null and previous_authorized_fn.? >= authorization.constraint_fn_var))
        {
            return error.CorruptArtifact;
        }
        var matching_use: ?ModuleEnv.SchemeUseRecord = null;
        for (cir.scheme_uses.items.items) |record| {
            if (record.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.where_method_use) or
                record.slot_data != authorization.source_where_fn_var)
            {
                continue;
            }
            if (matching_use != null) {
                return error.CorruptArtifact;
            }
            matching_use = record;
        }
        const use = matching_use orelse
            return error.CorruptArtifact;
        var justified: ModuleEnv.ResultRowWidening = .{};
        for (marker_uses[use.marker_uses_start..][0..use.marker_uses_len]) |marker| {
            const widened = persistedMarkerUseIsWidened(types, marker) orelse
                return error.CorruptArtifact;
            if (!widened) continue;
            switch (std.enums.fromInt(types_mod.WhereMethodMarkerContract.Position, marker.position).?) {
                .direct => justified.direct = true,
                .try_ok => justified.try_ok = true,
                .try_err => justified.try_err = true,
                .nested => {},
            }
        }
        if (!justified.hasValidShape() or justified.bits() != widening.bits()) {
            return error.CorruptArtifact;
        }
        previous_authorized_fn = authorization.constraint_fn_var;
    }
}

/// Validate every persisted W6b table in `env` before a cache loader or import
/// copier may consume it. The builtin nominal key is translated by exact
/// content identity lookup in the env being validated; validation never
/// interns an identity or repairs cached state.
fn validatedModuleIdentityHash(
    env: *const ModuleEnv,
    identity: base.ModuleIdentity.Idx,
) ?*const base.ModuleIdentity.Hash {
    env.module_identities.validateSemanticState(@sizeOf(base.ModuleIdentity.Hash)) catch return null;
    const identity_count = env.module_identities.count();
    if (env.module_identity_displays.len() != identity_count or identity.isNone()) return null;
    const raw_identity = @intFromEnum(identity);
    if (raw_identity >= identity_count) return null;
    const bytes = env.module_identities.getText(raw_identity);
    if (bytes.len != @sizeOf(base.ModuleIdentity.Hash)) return null;
    return @ptrCast(bytes.ptr);
}

fn validateW6bSemanticStateReadOnly(
    env: *const ModuleEnv,
    builtin_env: *const ModuleEnv,
    builtin_indices: CIR.BuiltinIndices,
) W6bSemanticValidationError!void {
    if (env.typecheck_state != .checked_file and env.typecheck_state != .checked_repl) {
        return error.CorruptArtifact;
    }
    try env.getIdentStoreConst().validateSemanticState();
    const try_statement = @intFromEnum(builtin_indices.try_type);
    if (try_statement > types_mod.SourceDecl.max_statement) return error.CorruptArtifact;
    _ = validatedModuleIdentityHash(env, env.self_module_identity) orelse return error.CorruptArtifact;
    const builtin_origin_identity = if (env.module_role == .builtin) env.self_module_identity else blk: {
        const builtin_hash = validatedModuleIdentityHash(builtin_env, builtin_env.self_module_identity) orelse
            return error.CorruptArtifact;
        const identity = env.lookupModuleIdentity(builtin_hash) orelse return error.CorruptArtifact;
        const local_hash = validatedModuleIdentityHash(env, identity) orelse return error.CorruptArtifact;
        if (!std.mem.eql(u8, builtin_hash, local_hash)) return error.CorruptArtifact;
        break :blk identity;
    };
    try env.types.validateNominalDeclSemanticState(
        env.getIdentStoreConst(),
        env.module_identities.count(),
        builtin_origin_identity,
    );
    try validateRehydratedWhereMethodState(
        &env.types,
        env,
        env.store.nodes.len(),
        .{
            .bool_stmt = builtin_indices.bool_type,
            .try_stmt = builtin_indices.try_type,
            .str_stmt = builtin_indices.str_type,
            .builtin_module = builtin_env,
            .builtin_indices = builtin_indices,
        },
        builtin_origin_identity,
    );
}

/// Disk cache entries are written only for modules with zero diagnostics.
/// Therefore none of the exact error-suppression states accepted for a fresh
/// diagnostic-bearing checked module may be authenticated by cache bytes.
fn rejectCacheRecoveryPublicationsEarly(env: *const ModuleEnv) W6bSemanticValidationError!void {
    if (env.malformed_expression_publications.items.items.len != 0 or
        env.malformed_type_annotation_publications.items.items.len != 0 or
        env.body_annotation_malformed_type_publications.items.items.len != 0)
    {
        return error.CorruptArtifact;
    }
}

fn validateCleanCacheW6bState(env: *const ModuleEnv) W6bSemanticValidationError!void {
    try rejectCacheRecoveryPublicationsEarly(env);
    if (env.expected_consumer_retirements.items.items.len != 0) {
        return error.CorruptArtifact;
    }
    for (env.expected_consumption_plans.items.items) |plan| {
        switch (plan.decodedOutcome() orelse return error.CorruptArtifact) {
            .source_root_copy_checked_error, .checked_error, .reserved => return error.CorruptArtifact,
            .anchored,
            .source_root_copy,
            .producer_root,
            .evidence_free,
            .retained,
            .related,
            .not_projected,
            => {},
        }
    }
    for (env.where_alias_declaration_publications.items.items) |publication| {
        if (publication.decodedOutcome() != .ready) return error.CorruptArtifact;
    }
    for (env.types.static_dispatch_constraints.items.items) |constraint| {
        if (constraint.where_method_markers.len() == 0) continue;
        const resolved = env.types.resolveVar(constraint.fn_var);
        if (resolved.desc.content == .err or resolved.desc.flags.static_dispatch_rejected) {
            return error.CorruptArtifact;
        }
    }
    for (env.scheme_uses.items.items) |record| {
        const slot = std.enums.fromInt(ModuleEnv.SchemeUseRecord.Slot, record.slot_kind) orelse
            return error.CorruptArtifact;
        if (slot != .where_method_use) continue;
        if (env.types.resolveVar(@enumFromInt(record.slot_data)).desc.content == .err) {
            return error.CorruptArtifact;
        }
    }
}

/// Owner-only admission for the embedded or freshly baked Builtin module.
/// The candidate is untrusted at entry and remains untrusted on every error.
pub fn admitBuiltinOwned(
    gpa: Allocator,
    env: *ModuleEnv,
    builtin_indices: CIR.BuiltinIndices,
) (Allocator.Error || W6bSemanticValidationError)!OwnedValidatedModuleEnv {
    if (env.w6b_semantically_validated or env.module_role != .builtin) {
        return error.CorruptArtifact;
    }
    try rejectCacheRecoveryPublicationsEarly(env);
    try validateW6bSemanticStateReadOnly(env, env, builtin_indices);
    try validateCleanCacheW6bState(env);
    const resolution = ImportResolution.recoveryForbiddenEmpty(env);
    try validateWhereAliasExpansionContext(env, resolution);
    try validateWhereMarkerCopySourceNamespaces(env, env, resolution);
    const hash = validatedModuleIdentityHash(env, env.self_module_identity) orelse
        return error.CorruptArtifact;
    const owned = try OwnedValidatedModuleEnv.init(
        gpa,
        env,
        hash.*,
        .{ .supplied = .{ .envs = &.{}, .modules = &.{} } },
        .{ .supplied = .{ .envs = &.{}, .modules = &.{} } },
        null,
    );
    env.w6b_semantically_validated = true;
    return owned;
}

/// Owner-only admission for one terminal checked environment. `context` is
/// supplied by the fresh canonical request; a cached candidate's serialized
/// redirect table is never accepted independently of that exact mapping.
pub fn admitCheckedOwned(
    gpa: Allocator,
    env: *ModuleEnv,
    builtin_module: ValidatedModuleEnv,
    builtin_indices: CIR.BuiltinIndices,
    authority: CacheAdmissionResolution,
) (Allocator.Error || W6bSemanticValidationError)!OwnedValidatedModuleEnv {
    if (env.w6b_semantically_validated) return error.CorruptArtifact;
    try rejectCacheRecoveryPublicationsEarly(env);
    const resolution_env: *const ModuleEnv, const imported_modules: AdmissionImports, const semantic_dependencies: AdmissionImports, const platform_dependency_index: ?usize, const expected_failure_replay: ImportResolution.ExpectedFailureReplay = switch (authority) {
        .fresh => |fresh_resolution| blk: {
            if (env == fresh_resolution.env or fresh_resolution.env.typecheck_state != .canonical_unchecked or
                !checkerOwnedDurableStateIsEmpty(&fresh_resolution.env.types, fresh_resolution.env))
            {
                return error.CorruptArtifact;
            }
            break :blk .{
                fresh_resolution.env,
                .{ .supplied = fresh_resolution.imported_modules },
                .{ .supplied = fresh_resolution.semantic_dependencies },
                fresh_resolution.platform_dependency_index,
                .fresh_canonical,
            };
        },
        .admitted => |admitted| blk: {
            const admitted_env = try admitted.validate();
            if (env == admitted_env) return error.CorruptArtifact;
            const record = try admitted.record();
            break :blk .{
                admitted_env,
                .{ .admitted = record.directImports() },
                .{ .admitted = record.semanticDependencies() },
                record.platform_dependency_index,
                .recovery_forbidden,
            };
        },
    };
    try imported_modules.validateResolution(resolution_env);
    try validateSemanticDependencyClosure(resolution_env, imported_modules, semantic_dependencies);
    try validateSemanticDependencyClosure(env, imported_modules, semantic_dependencies);
    if (platform_dependency_index) |index| {
        if (index >= semantic_dependencies.len()) return error.CorruptArtifact;
    }
    const builtin_env = try builtin_module.validate();
    if (builtin_env.module_role != .builtin) return error.CorruptArtifact;
    try validateW6bSemanticStateReadOnly(env, builtin_env, builtin_indices);
    try validateCleanCacheW6bState(env);
    const resolution = ImportResolution.init(
        resolution_env,
        imported_modules,
        semantic_dependencies,
        platform_dependency_index,
        expected_failure_replay,
    );
    try validateWhereAliasExpansionContext(env, resolution);
    try validateWhereMarkerCopySourceNamespaces(env, builtin_env, resolution);
    const hash = validatedModuleIdentityHash(env, env.self_module_identity) orelse
        return error.CorruptArtifact;
    const owned = try OwnedValidatedModuleEnv.init(
        gpa,
        env,
        hash.*,
        imported_modules,
        semantic_dependencies,
        platform_dependency_index,
    );
    env.w6b_semantically_validated = true;
    return owned;
}

/// Prove that one already-admitted terminal module remains eligible for the
/// diagnostic-free checked cache. Cache storage consumes the capability, not
/// the caller-writable validation bit, so arbitrary public code cannot turn an
/// unchecked/error-suppressed environment into a cache entry.
pub fn validateCleanCacheW6bEligibility(
    env: *const ModuleEnv,
    validated_module: ValidatedModuleEnv,
) W6bSemanticValidationError!void {
    if (try validated_module.validate() != env) return error.CorruptArtifact;
    try validateCleanCacheW6bState(env);
}

/// Local semantic-gate helper used only by corruption unit tests below. It
/// deliberately does not mint a capability: cross-module consumers must go
/// through owner admission with an exact `ImportResolution`.
fn validateW6bSemanticStateForTest(
    env: *const ModuleEnv,
    builtin_env: *const ModuleEnv,
    builtin_indices: CIR.BuiltinIndices,
) W6bSemanticValidationError!void {
    try validateW6bSemanticStateReadOnly(builtin_env, builtin_env, builtin_indices);
    try validateW6bSemanticStateReadOnly(env, builtin_env, builtin_indices);
}

/// Checker-owned copies of the parallel raw-environment and admission-capability
/// slices. The pointed-to environments and capability records remain owned by
/// their producers; only these four indexable slice backings are checker-owned.
const OwnedModuleInputs = struct {
    imported_envs: []const *const ModuleEnv,
    imported_capabilities: []const ValidatedModuleEnv,
    owner_envs: []const *const ModuleEnv,
    owner_capabilities: []const ValidatedModuleEnv,

    fn init(
        gpa: Allocator,
        imported_modules: ValidatedModuleSet,
        owner_modules: ValidatedModuleSet,
    ) Allocator.Error!OwnedModuleInputs {
        const imported_envs = try gpa.dupe(*const ModuleEnv, imported_modules.envs);
        errdefer gpa.free(imported_envs);
        const owner_envs = try gpa.dupe(*const ModuleEnv, owner_modules.envs);
        errdefer gpa.free(owner_envs);
        const imported_capabilities = try gpa.dupe(
            ValidatedModuleEnv,
            imported_modules.modules,
        );
        errdefer gpa.free(imported_capabilities);
        const owner_capabilities = try gpa.dupe(
            ValidatedModuleEnv,
            owner_modules.modules,
        );
        errdefer gpa.free(owner_capabilities);
        return .{
            .imported_envs = imported_envs,
            .imported_capabilities = imported_capabilities,
            .owner_envs = owner_envs,
            .owner_capabilities = owner_capabilities,
        };
    }

    fn deinit(self: OwnedModuleInputs, gpa: Allocator) void {
        gpa.free(self.imported_envs);
        gpa.free(self.imported_capabilities);
        gpa.free(self.owner_envs);
        gpa.free(self.owner_capabilities);
    }
};

fn initAssumePrepared(
    gpa: std.mem.Allocator,
    types: *types_mod.Store,
    cir: *ModuleEnv,
    imported_modules: ValidatedModuleSet,
    owner_modules: ValidatedModuleSet,
    platform_requirements: ?PlatformRequirementInput,
    platform_dependency_index: ?usize,
    auto_imported_types: ?*const std.AutoHashMap(Ident.Idx, can.Can.AutoImportedType),
    regions: *const Region.List,
    builtin_ctx: BuiltinContext,
) (std.mem.Allocator.Error || W6bSemanticValidationError)!Self {
    // Public checking inputs carry owner-minted immutable capabilities. Pair
    // every raw pointer with its exact token before any content-identity read,
    // owner-map insertion, or imported evidence copy.
    try imported_modules.validateResolution(cir);
    try validateSemanticDependencyClosure(
        cir,
        .{ .supplied = imported_modules },
        .{ .supplied = owner_modules },
    );
    if (try validatePlatformDependencyAuthority(
        cir,
        platform_requirements,
        .{ .supplied = owner_modules },
    ) != platform_dependency_index) return error.CorruptArtifact;
    if (!validateExternalLookupTokenProducerInventory(cir)) {
        return error.CorruptArtifact;
    }
    try validateExternalWhereAliasLookupGroups(
        cir,
        ImportResolution.producedSupplied(cir, imported_modules, owner_modules, platform_dependency_index),
    );
    const external_lookup_token_snapshot = try gpa.dupe(
        ModuleEnv.ExternalLookupToken,
        cir.external_lookup_tokens.items.items,
    );
    errdefer gpa.free(external_lookup_token_snapshot);
    const owned_module_inputs = try OwnedModuleInputs.init(
        gpa,
        imported_modules,
        owner_modules,
    );
    errdefer owned_module_inputs.deinit(gpa);
    if (builtin_ctx.builtin_module) |builtin_env| {
        const builtin_indices = builtin_ctx.builtin_indices orelse return error.CorruptArtifact;
        var builtin_matches: usize = 0;
        for (imported_modules.envs, imported_modules.modules) |imported_env, capability| {
            if (imported_env != builtin_env) continue;
            if (try capability.validate() != builtin_env) return error.CorruptArtifact;
            builtin_matches += 1;
        }
        if (builtin_matches != 1) return error.CorruptArtifact;
        _ = builtin_indices;
    } else if (imported_modules.envs.len != 0 or owner_modules.envs.len != 0) {
        return error.CorruptArtifact;
    }

    // Finalize this module's deep content identity before any unification: the
    // unifier only ever compares precomputed identities. Imported identities
    // were semantically validated above, so this cannot dereference an
    // untrusted self-identity index. Idempotent—the coordinator already
    // finalized coordinator-driven modules (it needs the identity for the
    // checked-cache key probe); this covers every other checking entry point
    // with the same inputs.
    try cir.ensureContentIdentity(imported_modules.envs);
    _ = validatedModuleIdentityHash(cir, cir.self_module_identity) orelse return error.CorruptArtifact;

    // Resolve the env-local identity that builtin-origin types minted during
    // this check will carry. When a separate Builtin module env exists, rebase
    // its content identity into this module's table; when checking the Builtin
    // module itself, its own identity IS the builtin identity.
    const builtin_origin_identity = blk: {
        if (builtin_ctx.builtin_module) |builtin_env| {
            const builtin_hash = validatedModuleIdentityHash(builtin_env, builtin_env.self_module_identity) orelse
                return error.CorruptArtifact;
            break :blk try cir.internModuleIdentity(builtin_hash, cir.idents.builtin_module);
        }
        break :blk cir.selfModuleIdentity();
    };

    const node_count: usize = @intCast(cir.store.nodes.len());

    var owner_envs_by_identity: std.AutoHashMapUnmanaged(base.ModuleIdentity.Hash, OwnerEnvCandidate) = .empty;
    errdefer owner_envs_by_identity.deinit(gpa);
    try appendOwnerEnvByIdentity(gpa, &owner_envs_by_identity, cir, true);
    for (imported_modules.envs) |imported_env| {
        try appendOwnerEnvByIdentity(gpa, &owner_envs_by_identity, imported_env, false);
    }
    for (owner_modules.envs) |owner_env| {
        try appendOwnerEnvByIdentity(gpa, &owner_envs_by_identity, owner_env, false);
    }

    var import_mapping = try createImportMapping(
        gpa,
        cir.getIdentStore(),
        cir,
        builtin_ctx.builtin_module,
        builtin_ctx.builtin_indices,
    );
    errdefer import_mapping.deinit();

    var binding_scheme_nodes = try std.DynamicBitSetUnmanaged.initEmpty(gpa, node_count);
    errdefer binding_scheme_nodes.deinit(gpa);

    var type_schemes: std.ArrayListUnmanaged(TypeScheme) = .empty;
    errdefer type_schemes.deinit(gpa);
    var type_scheme_by_var: std.AutoHashMapUnmanaged(Var, u32) = .empty;
    errdefer type_scheme_by_var.deinit(gpa);
    var where_method_use_record_by_fn_var: std.AutoHashMapUnmanaged(Var, u32) = .empty;
    errdefer where_method_use_record_by_fn_var.deinit(gpa);

    const self: Self = .{
        .gpa = gpa,
        .types = types,
        .cir = cir,
        .imported_modules = owned_module_inputs.imported_envs,
        .validated_imported_modules = owned_module_inputs.imported_capabilities,
        .validated_owner_modules = owned_module_inputs.owner_capabilities,
        .validated_module = null,
        .platform_dependency_index = platform_dependency_index,
        .owner_modules = owned_module_inputs.owner_envs,
        .owner_envs_by_identity = owner_envs_by_identity,
        .builtin_origin_identity = builtin_origin_identity,
        .auto_imported_types = auto_imported_types,
        .regions = blk: {
            var owned = Region.List{};
            _ = try owned.appendSlice(gpa, regions.items.items);
            break :blk owned;
        },
        .builtin_ctx = builtin_ctx,
        .snapshots = try SnapshotStore.initCapacity(gpa, 512),
        .problems = try ProblemStore.initCapacity(gpa, 64),
        .import_mapping = import_mapping,
        .unify_scratch = try unifier.Scratch.init(gpa),
        .occurs_scratch = try occurs.Scratch.init(gpa),
        .seen_annos = try std.DynamicBitSetUnmanaged.initEmpty(gpa, node_count),
        .env_pool = try EnvPool.init(gpa),
        .generalizer = try Generalizer.init(gpa, types),
        .var_map = std.AutoHashMap(Var, Var).init(gpa),
        .constraints = try Constraint.SafeList.initCapacity(gpa, 32),
        .return_constraints = .empty,
        .return_constraint_frames = .empty,
        .var_set = std.AutoHashMap(Var, void).init(gpa),
        .inspect_type_visits = std.AutoHashMap(Var, u8).init(gpa),
        .type_visit_stack = .empty,
        .alias_row_frames = .empty,
        .alias_row_names = .empty,
        .rigid_var_substitutions = std.AutoHashMapUnmanaged(Ident.Idx, Var){},
        .type_decl_rigid_vars = std.AutoHashMapUnmanaged(Ident.Idx, Var){},
        .pending_default_checks = .empty,
        .optional_field_accesses = .empty,
        .literal_field_kinds = .empty,
        .pending_record_updates = .empty,
        .pending_record_destructs = .empty,
        .type_decl_generation_states = try initNodeSlots(TypeDeclGenerationState, gpa, node_count, .not_generated),
        .type_decl_dense_indices = try initNodeSlots(u32, gpa, node_count, no_type_decl_dense_index),
        .type_decl_statements = .empty,
        .type_decl_invalid = .empty,
        .type_decl_dependencies = .empty,
        .scratch_vars = try base.Scratch(types_mod.Var).init(gpa),
