/// Returns the hoisted roots selected while checking this module.
pub fn selectedHoistedRoots(self: *const Self) []const hoist_roots.SelectedHoistedRoot {
    return self.selected_hoisted_roots.items;
}

/// Whether a selected root materializes a top-level binding.
pub fn selectedHoistedRootIsTopLevel(self: *const Self, root: hoist_roots.SelectedHoistedRoot) bool {
    const pattern = switch (root.body) {
        .expr => root.pattern orelse return false,
        .pattern_extraction => |extraction| extraction.scrutinee_pattern,
        .pattern_validation => |validation| validation.scrutinee_pattern,
    };
    return self.patternIsTopLevelDef(pattern);
}

/// Record a top-level root that will be evaluated as a zero-arg executable
/// thunk. This must be explicit producer metadata from canonicalization or the
/// caller; the checker never recovers roots from names or source shape.
pub fn addExecutableRootDef(self: *Self, def_idx: CIR.Def.Idx) Allocator.Error!void {
    try self.executable_root_defs.append(self.gpa, def_idx);
}

/// Record a zero-arg executable root whose body will be evaluated during
/// checked finalization rather than invoked at runtime.
pub fn addCompileTimeExecutableRootDef(
    self: *Self,
    def_idx: CIR.Def.Idx,
    lambda_idx: CIR.Expr.Idx,
    body_expr: CIR.Expr.Idx,
) Allocator.Error!void {
    try self.addExecutableRootDef(def_idx);
    try self.compile_time_executable_roots.append(self.gpa, .{
        .def = def_idx,
        .lambda = lambda_idx,
        .body = body_expr,
    });
}

/// Return the exact body identity supplied for a compile-time executable root.
pub fn compileTimeExecutableRootBody(self: *const Self, def_idx: CIR.Def.Idx) ?CIR.Expr.Idx {
    for (self.compile_time_executable_roots.items) |root| {
        if (root.def == def_idx) return root.body;
    }
    return null;
}

fn beginHoistFrame(self: *Self, expr: CIR.Expr.Idx, binding_rhs: bool, hoist_position: HoistPosition) Allocator.Error!HoistFrameGuard {
    try self.hoist_frames.append(self.gpa, .{
        .expr = expr,
        .hoist_position = hoist_position,
        .binding_rhs = binding_rhs,
        .binding_pattern = if (binding_rhs) self.checking_binding_rhs_pattern else null,
        .candidate_start = self.hoist_expr_candidates.items.len,
        .deferred_dependency_start = self.hoist_deferred_roots.items.len,
    });
    self.last_hoist_result = null;
    return .{
        .checker = self,
        .expr = expr,
    };
}

fn abortHoistFrame(self: *Self, expr: CIR.Expr.Idx) void {
    if (self.hoist_frames.items.len == 0) {
        std.debug.panic("check invariant violated: missing hoist frame during abort", .{});
    }
    const frame = self.hoist_frames.items[self.hoist_frames.items.len - 1];
    if (frame.expr != expr) {
        std.debug.panic("check invariant violated: aborting non-top hoist frame", .{});
    }
    _ = self.hoist_frames.pop();
    self.hoist_expr_candidates.shrinkRetainingCapacity(frame.candidate_start);
    self.hoist_deferred_roots.shrinkRetainingCapacity(frame.deferred_dependency_start);
    self.last_hoist_result = null;
}

fn finishHoistFrame(self: *Self, expr: CIR.Expr.Idx, does_fx: bool) Allocator.Error!void {
    if (self.hoist_frames.items.len == 0) {
        std.debug.panic("check invariant violated: missing hoist frame", .{});
    }
    const frame_index = self.hoist_frames.items.len - 1;
    var frame = self.hoist_frames.items[frame_index];
    std.debug.assert(frame.expr == expr);
    if (does_fx) frame.has_observable_effect = true;

    const semantically_eligible = frame.eligible();
    const top_level_equivalent = semantically_eligible and !frame.has_contextual_dependency;
    const can_be_root = top_level_equivalent and self.exprCanBeHoistedRoot(expr);
    const can_cover_children = top_level_equivalent and self.exprCanCoverHoistedChildren(expr);
    const selection_allowed = frame.hoist_position.allowsSelection();
    const binding_rhs_can_cover_children = frame.binding_rhs and
        top_level_equivalent and
        selection_allowed and
        self.exprCanBeHoistedBindingRoot(expr) and
        !isFunctionDef(&self.cir.store, self.cir.store.getExpr(expr)) and
        !self.varIsFunctionType(ModuleEnv.varFrom(expr));
    const current_covers_children = (can_cover_children and !frame.binding_rhs) or binding_rhs_can_cover_children;
    // Any eligible binding RHS suppresses smaller expression candidates, but
    // only a pattern that can publish that RHS as a binding root may become a
    // prospective owner for its deferred validation. Other patterns must
    // bubble validation to an enclosing root or retain a dedicated validation root.
    const current_covers_deferred_roots = current_covers_children and
        (!frame.binding_rhs or
            (frame.binding_pattern != null and self.patternCanOwnHoistedBindingRoot(frame.binding_pattern.?)));
    const has_child_candidates = self.hoist_expr_candidates.items.len > frame.candidate_start;
    const action: HoistSelectionAction = if (!selection_allowed)
        .suppress_children
    else if (current_covers_children)
        .cover_with_current_root
    else if (has_child_candidates)
        .flush_child_candidates
    else
        .drop_empty;
    const should_flush_child_candidates = action == .flush_child_candidates;
    const should_bubble_to_parent = frame_index != 0 and
        can_be_root and !frame.binding_rhs and selection_allowed;
    if (should_bubble_to_parent) {
        try self.hoist_expr_candidates.ensureUnusedCapacity(self.gpa, 1);
    }

    const has_deferred_roots = self.hoist_deferred_roots.items.len > frame.deferred_dependency_start;
    const should_flush_deferred_roots = selection_allowed and has_deferred_roots and
        (frame_index == 0 or !semantically_eligible);
    if (should_flush_child_candidates or should_flush_deferred_roots) {
        var transaction = HoistSelectionTransaction.init(self);
        defer transaction.deinit();

        if (should_flush_child_candidates) {
            for (self.hoist_expr_candidates.items[frame.candidate_start..]) |candidate| {
                if (self.hoistExprInvalidated(candidate)) continue;
                _ = try transaction.stageExprRoot(candidate, null);
            }
        }
        if (should_flush_deferred_roots) {
            // Binding roots go first so post-solve pruning can let a kept live
            // extraction subsume the dedicated validation root.
            for (self.hoist_deferred_roots.items[frame.deferred_dependency_start..]) |deferred| {
                switch (deferred) {
                    .binding => |pattern| _ = try transaction.stageBindingRoot(pattern),
                    .pattern_validation => {},
                }
            }
            for (self.hoist_deferred_roots.items[frame.deferred_dependency_start..]) |deferred| {
                switch (deferred) {
                    .binding => {},
                    .pattern_validation => |pending| _ = try transaction.stagePatternValidationRoot(pending.validation, pending.owner_expr),
                }
            }
        }
        try transaction.commit();
    }

    if (builtin.mode == .Debug and has_child_candidates) {
        switch (action) {
            .suppress_children,
            .cover_with_current_root,
            .flush_child_candidates,
            => {},
            .drop_empty => hoistSelectionInvariant("hoist frame dropped child candidates without an explicit action"),
        }
    }
    self.hoist_expr_candidates.shrinkRetainingCapacity(frame.candidate_start);

    if (!selection_allowed or should_flush_deferred_roots) {
        self.hoist_deferred_roots.shrinkRetainingCapacity(frame.deferred_dependency_start);
    } else if (current_covers_deferred_roots) {
        // The current expression may become the maximal selected owner. Keep a
        // distinct validation root until post-solve pruning proves that it did,
        // but consume binding dependencies that the expression evaluates locally.
        var retained = frame.deferred_dependency_start;
        for (self.hoist_deferred_roots.items[frame.deferred_dependency_start..]) |deferred| {
            switch (deferred) {
                .binding => {},
                .pattern_validation => |pending| {
                    self.hoist_deferred_roots.items[retained] = .{ .pattern_validation = .{
                        .validation = pending.validation,
                        .owner_expr = expr,
                    } };
                    retained += 1;
                },
            }
        }
        self.hoist_deferred_roots.shrinkRetainingCapacity(retained);
    }

    const completed = CompletedHoistResult{
        .expr = expr,
        .eligible = semantically_eligible,
        .top_level_equivalent = top_level_equivalent,
        .has_observable_effect = frame.has_observable_effect,
        .hoist_position = frame.hoist_position,
    };
    self.last_hoist_result = completed;

    if (frame_index != 0) {
        const parent = &self.hoist_frames.items[frame_index - 1];
        if (!completed.eligible) {
            parent.has_runtime_dependency = true;
        } else if (can_be_root and !frame.binding_rhs and selection_allowed) {
            self.hoist_expr_candidates.appendAssumeCapacity(expr);
        }
    }

    _ = self.hoist_frames.pop();
    self.debugAssertHoistSelectionConsistent();
}

fn markCurrentHoistRuntimeDependency(self: *Self) void {
    if (self.hoist_frames.items.len == 0) return;
    self.hoist_frames.items[self.hoist_frames.items.len - 1].has_runtime_dependency = true;
}

fn markCurrentHoistObservableEffect(self: *Self) void {
    if (self.hoist_frames.items.len == 0) return;
    self.hoist_frames.items[self.hoist_frames.items.len - 1].has_observable_effect = true;
}

fn checkedExprBlocksLaterHoists(self: *const Self, expr: CIR.Expr.Idx, does_fx: bool) bool {
    if (does_fx) return true;
    const completed = self.last_hoist_result orelse return false;
    if (completed.expr != expr) return false;
    return completed.has_observable_effect;
}

fn warnIfComptimeConditionalExpr(
    self: *Self,
    expr: CIR.Expr.Idx,
    kind: @FieldType(problem.ComptimeCondition, "kind"),
    expected: Expected,
) Allocator.Error!void {
    if (!expected.emitsComptimeConditionWarnings()) return;

    const completed = self.last_hoist_result orelse return;
    if (completed.expr != expr or !completed.top_level_equivalent) return;

    self.var_set.clearRetainingCapacity();
    if (try self.varContainsError(ModuleEnv.varFrom(expr), &self.var_set)) return;

    _ = try self.problems.appendProblem(self.gpa, .{ .comptime_condition = .{
        .kind = kind,
        .region = self.cir.store.getExprRegion(expr),
    } });
}

fn recordHoistBindingCandidate(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    expr: CIR.Expr.Idx,
    hoist_position: HoistPosition,
) Allocator.Error!void {
    const completed = self.last_hoist_result orelse return;
    if (completed.expr != expr) return;
    if (builtin.mode == .Debug) std.debug.assert(completed.hoist_position == hoist_position);
    if (!completed.hoist_position.allowsSelection() or !completed.top_level_equivalent) return;
    if (!self.patternCanOwnHoistedBindingRoot(pattern)) return;
    if (!self.exprCanBeHoistedBindingRoot(expr)) return;
    if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(expr))) return;
    if (self.varIsFunctionType(ModuleEnv.varFrom(expr))) return;

    const entry = try self.hoist_binding_candidates.getOrPut(self.gpa, pattern);
    const had_existing = entry.found_existing;
    const previous_expr = if (had_existing) entry.value_ptr.* else undefined;
    const previous_scope_len = self.hoist_binding_scope_patterns.items.len;
    if (!entry.found_existing) {
        self.hoist_binding_scope_patterns.append(self.gpa, pattern) catch |err| {
            _ = self.hoist_binding_candidates.remove(pattern);
            return err;
        };
    }
    entry.value_ptr.* = expr;

    self.recordHoistKnownValue(pattern, .{ .binding_rhs = expr }) catch |err| {
        if (had_existing) {
            entry.value_ptr.* = previous_expr;
        } else {
            _ = self.hoist_binding_candidates.remove(pattern);
            self.hoist_binding_scope_patterns.shrinkRetainingCapacity(previous_scope_len);
        }
        return err;
    };
}

fn recordHoistPatternProvenance(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    expr: CIR.Expr.Idx,
    hoist_position: HoistPosition,
) Allocator.Error!void {
    const completed = self.last_hoist_result orelse return;
    if (completed.expr != expr) return;
    if (builtin.mode == .Debug) std.debug.assert(completed.hoist_position == hoist_position);
    if (!completed.hoist_position.allowsSelection() or !completed.top_level_equivalent) return;
    if (!self.exprCanBeHoistedBindingRoot(expr)) return;
    if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(expr))) return;
    if (self.varIsFunctionType(ModuleEnv.varFrom(expr))) return;

    switch (self.cir.store.getPattern(pattern)) {
        .assign => {},
        .as,
        .tuple,
        .record_destructure,
        .applied_tag,
        .nominal,
        .nominal_external,
        .list,
        .str_interpolation,
        .underscore,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => try self.recordHoistPatternExtractionProvenanceHelp(pattern, expr, pattern, .deferred),
    }
}

/// A pending destructure diagnostic is a strict compile-time demand on the
/// complete scrutinee, independent of whether any binder is later referenced.
/// Keep the demand pending until the maximal eligible enclosing expression is
/// known; only then can selection decide whether that expression owns the
/// validation or a dedicated validation root is necessary.
fn recordHoistPatternValidationCandidate(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    expr: CIR.Expr.Idx,
    hoist_position: HoistPosition,
) Allocator.Error!void {
    const completed = self.last_hoist_result orelse return;
    if (completed.expr != expr) return;
    if (builtin.mode == .Debug) std.debug.assert(completed.hoist_position == hoist_position);
    if (!completed.hoist_position.allowsSelection() or !completed.top_level_equivalent) return;

    try self.hoist_deferred_roots.append(self.gpa, .{ .pattern_validation = .{
        .validation = .{
            .base_expr = expr,
            .scrutinee_pattern = pattern,
            .erase_runtime = !self.patternIntroducesValueBinding(pattern),
        },
    } });
    self.problems.markPendingStaticExhaustivenessEmpirical(.{ .destructure_pattern = pattern });
}

fn patternIntroducesValueBinding(self: *const Self, pattern: CIR.Pattern.Idx) bool {
    return switch (self.cir.store.getPattern(pattern)) {
        .assign, .as => true,
        .tuple => |tuple| blk: {
            for (self.cir.store.slicePatterns(tuple.patterns)) |child| {
                if (self.patternIntroducesValueBinding(child)) break :blk true;
            }
            break :blk false;
        },
        .record_destructure => |destructure| blk: {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                if (self.patternIntroducesValueBinding(destruct.kind.toPatternIdx())) break :blk true;
            }
            break :blk false;
        },
        .applied_tag => |tag| blk: {
            for (self.cir.store.slicePatterns(tag.args)) |child| {
                if (self.patternIntroducesValueBinding(child)) break :blk true;
            }
            break :blk false;
        },
        .nominal => |nominal| self.patternIntroducesValueBinding(nominal.backing_pattern),
        .nominal_external => |nominal| self.patternIntroducesValueBinding(nominal.backing_pattern),
        .list => |list| blk: {
            for (self.cir.store.slicePatterns(list.patterns)) |child| {
                if (self.patternIntroducesValueBinding(child)) break :blk true;
            }
            if (list.rest_info) |rest| {
                if (rest.pattern) |child| break :blk self.patternIntroducesValueBinding(child);
            }
            break :blk false;
        },
        .str_interpolation => |str| blk: {
            var offset: u32 = 0;
            while (offset < str.steps.span.len) : (offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, offset);
                if (step.capture != null) break :blk true;
            }
            break :blk false;
        },
        .underscore,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => false,
    };
}

fn patternCanOwnHoistedBindingRoot(self: *Self, pattern: CIR.Pattern.Idx) bool {
    return switch (self.cir.store.getPattern(pattern)) {
        .assign,
        .as,
        => true,
        .tuple,
        .record_destructure,
        .applied_tag,
        .nominal,
        .nominal_external,
        .list,
        .str_interpolation,
        .underscore,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => false,
    };
}

fn recordHoistSingleBranchMatchPatternProvenance(
    self: *Self,
    match: CIR.Expr.Match,
    branch: CIR.Expr.Match.Branch,
    branch_patterns: []const CIR.Expr.Match.BranchPattern.Idx,
    hoist_position: HoistPosition,
) Allocator.Error!void {
    if (match.is_try_suffix) return;
    if (match.branches.span.len != 1) return;
    if (branch.guard != null) return;
    if (branch_patterns.len != 1) return;

    const branch_pattern = self.cir.store.getMatchBranchPattern(branch_patterns[0]);
    if (branch_pattern.degenerate) return;
    if (!self.patternIsIrrefutableForHoistExtraction(branch_pattern.pattern)) return;

    try self.recordHoistPatternProvenance(branch_pattern.pattern, match.cond, hoist_position);
}

fn patternIsIrrefutableForHoistExtraction(self: *Self, pattern: CIR.Pattern.Idx) bool {
    return switch (self.cir.store.getPattern(pattern)) {
        .assign,
        .underscore,
        => true,
        .as => |as_pattern| self.patternIsIrrefutableForHoistExtraction(as_pattern.pattern),
        .tuple => |tuple| {
            for (self.cir.store.slicePatterns(tuple.patterns)) |elem_pattern| {
                if (!self.patternIsIrrefutableForHoistExtraction(elem_pattern)) return false;
            }
            return true;
        },
        .record_destructure => |destructure| {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                if (!self.patternIsIrrefutableForHoistExtraction(destruct.kind.toPatternIdx())) return false;
            }
            return true;
        },
        .list => |list| {
            if (list.patterns.span.len != 0) return false;
            const rest_info = list.rest_info orelse return false;
            if (rest_info.pattern) |rest_pattern| {
                return self.patternIsIrrefutableForHoistExtraction(rest_pattern);
            }
            return true;
        },
        .nominal => |nominal| self.patternIsIrrefutableForHoistExtraction(nominal.backing_pattern),
        .nominal_external => |nominal| self.patternIsIrrefutableForHoistExtraction(nominal.backing_pattern),
        .applied_tag,
        .str_interpolation,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => false,
    };
}

fn recordHoistMatchBranchContextualBindings(
    self: *Self,
    branch_patterns: []const CIR.Expr.Match.BranchPattern.Idx,
    owner_frame_index: usize,
) Allocator.Error!void {
    for (branch_patterns) |branch_pattern_idx| {
        const branch_pattern = self.cir.store.getMatchBranchPattern(branch_pattern_idx);
        try self.recordHoistContextualPatternBindings(branch_pattern.pattern, owner_frame_index);
    }
}

const HoistPatternExtractionSelection = enum {
    deferred,
    immediate,
};

fn recordHoistPatternExtractionProvenanceHelp(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    base_expr: CIR.Expr.Idx,
    scrutinee_pattern: CIR.Pattern.Idx,
    selection: HoistPatternExtractionSelection,
) Allocator.Error!void {
    switch (self.cir.store.getPattern(pattern)) {
        .assign => {
            try self.recordHoistPatternExtractionProvenance(pattern, base_expr, scrutinee_pattern);
            if (selection == .immediate) {
                _ = try self.ensureHoistedBindingRoot(pattern);
            }
        },
        .as => |as_pattern| {
            try self.recordHoistPatternExtractionProvenance(pattern, base_expr, scrutinee_pattern);
            if (selection == .immediate) {
                _ = try self.ensureHoistedBindingRoot(pattern);
            }
            try self.recordHoistPatternExtractionProvenanceHelp(as_pattern.pattern, base_expr, scrutinee_pattern, selection);
        },
        .tuple => |tuple| {
            for (self.cir.store.slicePatterns(tuple.patterns)) |elem_pattern| {
                try self.recordHoistPatternExtractionProvenanceHelp(elem_pattern, base_expr, scrutinee_pattern, selection);
            }
        },
        .record_destructure => |destructure| {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                try self.recordHoistPatternExtractionProvenanceHelp(destruct.kind.toPatternIdx(), base_expr, scrutinee_pattern, selection);
            }
        },
        .applied_tag => |tag| {
            for (self.cir.store.slicePatterns(tag.args)) |arg_pattern| {
                try self.recordHoistPatternExtractionProvenanceHelp(arg_pattern, base_expr, scrutinee_pattern, selection);
            }
        },
        .nominal => |nominal| {
            try self.recordHoistPatternExtractionProvenanceHelp(nominal.backing_pattern, base_expr, scrutinee_pattern, selection);
        },
        .nominal_external => |nominal| {
            try self.recordHoistPatternExtractionProvenanceHelp(nominal.backing_pattern, base_expr, scrutinee_pattern, selection);
        },
        .list => |list| {
            for (self.cir.store.slicePatterns(list.patterns)) |elem_pattern| {
                try self.recordHoistPatternExtractionProvenanceHelp(elem_pattern, base_expr, scrutinee_pattern, selection);
            }
            if (list.rest_info) |rest_info| {
                if (rest_info.pattern) |rest_pattern| {
                    try self.recordHoistPatternExtractionProvenanceHelp(rest_pattern, base_expr, scrutinee_pattern, selection);
                }
            }
        },
        .str_interpolation => |str| {
            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture| {
                    try self.recordHoistPatternExtractionProvenanceHelp(capture, base_expr, scrutinee_pattern, selection);
                }
            }
        },
        .underscore,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => {},
    }
}

fn recordHoistPatternExtractionProvenance(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    base_expr: CIR.Expr.Idx,
    scrutinee_pattern: CIR.Pattern.Idx,
) Allocator.Error!void {
    try self.recordHoistKnownValue(pattern, .{ .pattern_extraction = .{
        .base_expr = base_expr,
        .scrutinee_pattern = scrutinee_pattern,
        .result_pattern = pattern,
    } });
}

fn recordHoistContextualPatternBindings(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    owner_frame_index: usize,
) Allocator.Error!void {
    switch (self.cir.store.getPattern(pattern)) {
        .assign => {
            try self.recordHoistContextualBinding(pattern, owner_frame_index);
        },
        .as => |as_pattern| {
            try self.recordHoistContextualBinding(pattern, owner_frame_index);
            try self.recordHoistContextualPatternBindings(as_pattern.pattern, owner_frame_index);
        },
        .tuple => |tuple| {
            for (self.cir.store.slicePatterns(tuple.patterns)) |elem_pattern| {
                try self.recordHoistContextualPatternBindings(elem_pattern, owner_frame_index);
            }
        },
        .record_destructure => |destructure| {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                try self.recordHoistContextualPatternBindings(destruct.kind.toPatternIdx(), owner_frame_index);
            }
        },
        .applied_tag => |tag| {
            for (self.cir.store.slicePatterns(tag.args)) |arg_pattern| {
                try self.recordHoistContextualPatternBindings(arg_pattern, owner_frame_index);
            }
        },
        .nominal => |nominal| {
            try self.recordHoistContextualPatternBindings(nominal.backing_pattern, owner_frame_index);
        },
        .nominal_external => |nominal| {
            try self.recordHoistContextualPatternBindings(nominal.backing_pattern, owner_frame_index);
        },
        .list => |list| {
            for (self.cir.store.slicePatterns(list.patterns)) |elem_pattern| {
                try self.recordHoistContextualPatternBindings(elem_pattern, owner_frame_index);
            }
            if (list.rest_info) |rest_info| {
                if (rest_info.pattern) |rest_pattern| {
                    try self.recordHoistContextualPatternBindings(rest_pattern, owner_frame_index);
                }
            }
        },
        .str_interpolation => |str| {
            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture| {
                    try self.recordHoistContextualPatternBindings(capture, owner_frame_index);
                }
            }
        },
        .underscore,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => {},
    }
}

fn recordHoistContextualBinding(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    owner_frame_index: usize,
) Allocator.Error!void {
    const entry = try self.hoist_contextual_bindings.getOrPut(self.gpa, pattern);
    if (!entry.found_existing) {
        self.hoist_contextual_binding_scope_patterns.append(self.gpa, pattern) catch |err| {
            _ = self.hoist_contextual_bindings.remove(pattern);
            return err;
        };
    }
    entry.value_ptr.* = owner_frame_index;
}

fn discardHoistBindingCandidate(self: *Self, pattern: CIR.Pattern.Idx) void {
    _ = self.hoist_binding_candidates.remove(pattern);
    self.markHoistKnownValueUnavailable(pattern);
    _ = self.hoist_selected_bindings.remove(pattern);
}

fn popHoistBindingCandidateScope(self: *Self, start: usize) void {
    for (self.hoist_binding_scope_patterns.items[start..]) |pattern| {
        _ = self.hoist_binding_candidates.remove(pattern);
    }
    self.hoist_binding_scope_patterns.shrinkRetainingCapacity(start);
}

fn popHoistContextualBindingScope(self: *Self, start: usize) void {
    for (self.hoist_contextual_binding_scope_patterns.items[start..]) |pattern| {
        _ = self.hoist_contextual_bindings.remove(pattern);
    }
    self.hoist_contextual_binding_scope_patterns.shrinkRetainingCapacity(start);
}

fn markHoistContextualDependencyForLookup(self: *Self, pattern: CIR.Pattern.Idx) bool {
    const owner_frame_index = self.hoist_contextual_bindings.get(pattern) orelse return false;
    if (owner_frame_index >= self.hoist_frames.items.len) {
        std.debug.panic("check invariant violated: contextual hoist binding outlived its owner frame", .{});
    }

    var frame_index = owner_frame_index + 1;
    while (frame_index < self.hoist_frames.items.len) : (frame_index += 1) {
        self.hoist_frames.items[frame_index].has_contextual_dependency = true;
    }
    return true;
}

fn currentHoistFrameIndexForExpr(self: *const Self, expr: CIR.Expr.Idx) usize {
    if (self.hoist_frames.items.len == 0) {
        std.debug.panic("check invariant violated: missing contextual hoist owner frame", .{});
    }
    const frame_index = self.hoist_frames.items.len - 1;
    if (self.hoist_frames.items[frame_index].expr != expr) {
        std.debug.panic("check invariant violated: contextual hoist owner was not the current expression frame", .{});
    }
    return frame_index;
}

const HoistLexicalScope = struct {
    binding_candidate_start: usize,
    known_value_start: usize,
    contextual_binding_start: usize,
};

fn beginHoistLexicalScope(self: *const Self) HoistLexicalScope {
    return .{
        .binding_candidate_start = self.hoist_binding_scope_patterns.items.len,
        .known_value_start = self.hoist_known_value_scope_patterns.items.len,
        .contextual_binding_start = self.hoist_contextual_binding_scope_patterns.items.len,
    };
}

fn endHoistLexicalScope(self: *Self, scope: HoistLexicalScope) void {
    self.popHoistContextualBindingScope(scope.contextual_binding_start);
    self.popHoistKnownValueScope(scope.known_value_start);
    self.popHoistBindingCandidateScope(scope.binding_candidate_start);
}

fn deinitHoistKnownValue(_: *Self, value: HoistKnownValue) void {
    switch (value) {
        .pattern_extraction,
        .binding_rhs,
        .selected_root,
        .unavailable_runtime,
        => {},
    }
}

fn recordHoistKnownValue(self: *Self, pattern: CIR.Pattern.Idx, value: HoistKnownValue) Allocator.Error!void {
    const entry = self.hoist_known_values.getOrPut(self.gpa, pattern) catch |err| {
        self.deinitHoistKnownValue(value);
        return err;
    };
    if (!entry.found_existing) {
        self.hoist_known_value_scope_patterns.append(self.gpa, pattern) catch |err| {
            _ = self.hoist_known_values.remove(pattern);
            self.deinitHoistKnownValue(value);
            return err;
        };
    } else {
        self.deinitHoistKnownValue(entry.value_ptr.*);
    }
    entry.value_ptr.* = value;
}

fn markHoistKnownValueUnavailable(self: *Self, pattern: CIR.Pattern.Idx) void {
    if (self.hoist_known_values.getPtr(pattern)) |value| {
        self.deinitHoistKnownValue(value.*);
        value.* = .unavailable_runtime;
    }
}

fn popHoistKnownValueScope(self: *Self, start: usize) void {
    for (self.hoist_known_value_scope_patterns.items[start..]) |pattern| {
        if (self.hoist_known_values.fetchRemove(pattern)) |entry| {
            self.deinitHoistKnownValue(entry.value);
        }
    }
    self.hoist_known_value_scope_patterns.shrinkRetainingCapacity(start);
}

fn ensureHoistedBindingRoot(self: *Self, pattern: CIR.Pattern.Idx) Allocator.Error!bool {
    if (self.hoist_selected_bindings.contains(pattern)) return true;
    var transaction = HoistSelectionTransaction.init(self);
    defer transaction.deinit();
    const selected = try transaction.stageBindingRoot(pattern);
    if (!selected) return false;
    try transaction.commit();
    return true;
}

fn hoistKnownBindingAvailable(self: *Self, pattern: CIR.Pattern.Idx) bool {
    const known = self.hoist_known_values.get(pattern) orelse return false;
    return switch (known) {
        .binding_rhs => |expr| !self.hoistExprInvalidated(expr),
        .pattern_extraction => |extraction| !self.hoistExprInvalidated(extraction.base_expr),
        .selected_root => |root_index| !self.selectedHoistedRootInvalidated(root_index),
        .unavailable_runtime => false,
    };
}

fn shouldDeferHoistedBindingSelection(self: *const Self) bool {
    if (self.hoist_frames.items.len == 0) return false;
    return self.hoist_frames.items[self.hoist_frames.items.len - 1].hoist_position.allowsSelection();
}

fn ensureHoistedPatternExtractionRoot(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    extraction: HoistPatternExtraction,
) Allocator.Error!u32 {
    if (self.hoist_selected_bindings.get(pattern)) |root_index| return root_index;
    var transaction = HoistSelectionTransaction.init(self);
    defer transaction.deinit();
    const root_index = try transaction.stagePatternExtractionRoot(pattern, extraction);
    try transaction.commit();
    return root_index;
}

fn ensureHoistedExprRoot(self: *Self, expr: CIR.Expr.Idx, pattern: ?CIR.Pattern.Idx) Allocator.Error!u32 {
    var transaction = HoistSelectionTransaction.init(self);
    defer transaction.deinit();
    const root_index = try transaction.stageExprRoot(expr, pattern);
    try transaction.commit();
    return root_index;
}

fn hoistExprInvalidated(self: *const Self, expr: CIR.Expr.Idx) bool {
    return self.hoist_invalidated_exprs.contains(expr);
}

fn moduleHoistExprInvalidated(self: *const Self, module: *const ModuleEnv, expr: CIR.Expr.Idx) bool {
    return module == self.cir and self.hoistExprInvalidated(expr);
}

fn selectedHoistedRootInvalidated(self: *const Self, root_index: u32) bool {
    if (root_index >= self.selected_hoisted_roots.items.len) {
        std.debug.panic("check invariant violated: hoist-known selected root index out of range", .{});
    }
    return self.hoistExprInvalidated(self.selected_hoisted_roots.items[root_index].expr);
}

fn replaceExprWithRuntimeError(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    diagnostic_idx: CIR.Diagnostic.Idx,
) Allocator.Error!void {
    const record_update_owner = try self.prepareRecordUpdateOwnerRetirement(
        expr_idx,
        diagnostic_idx,
    );
    try self.invalidateExprSubtreeMetadata(expr_idx);
    if (record_update_owner) |prepared| {
        self.commitRecordUpdateOwnerRetirement(prepared, diagnostic_idx);
        self.cir.store.replaceExprWithRuntimeError(expr_idx, diagnostic_idx);
        return;
    }
    try self.completeAggregateExpectedRetirement(expr_idx, diagnostic_idx);
    try self.completeIneligibleFailureRetirement(expr_idx, diagnostic_idx);
    self.cir.store.replaceExprWithRuntimeError(expr_idx, diagnostic_idx);
}

const PreparedRecordUpdateOwnerRetirement = struct {
    draft_index: usize,
    draft: RecordUpdateOwnerRetirementDraft,
    retired_consumers_start: usize,
    member_count: usize,
};

fn prepareRecordUpdateOwnerRetirement(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    diagnostic_idx: CIR.Diagnostic.Idx,
) Allocator.Error!?PreparedRecordUpdateOwnerRetirement {
    var draft_index: ?usize = null;
    for (self.record_update_owner_retirement_drafts.items, 0..) |draft, index| {
        if (draft.owner_expr != expr_idx) continue;
        if (draft_index != null) {
            std.debug.panic("record-update owner reached multiple checked-base retirements", .{});
        }
        draft_index = index;
    }
    const selected_index = draft_index orelse return null;
    if (self.probe_depth != 0) {
        std.debug.panic("record-update owner retirement completed inside a Probe", .{});
    }
    if (!self.cir.store.isDiagnosticIndex(diagnostic_idx)) {
        std.debug.panic("record-update owner retirement lost its runtime-error diagnostic", .{});
    }
    const draft = self.record_update_owner_retirement_drafts.items[selected_index];
    for (self.aggregate_expected_retirement_drafts.items) |other| {
        if (other.owner_expr == expr_idx) {
            std.debug.panic("record-update owner retirement mixed an aggregate lifecycle", .{});
        }
    }
    for (self.annotation_expected_failure_drafts.items) |other| {
        if (other.owner_expr == expr_idx) {
            std.debug.panic("record-update owner retirement mixed a failure lifecycle", .{});
        }
    }
    if (draft.base_plan_index >= self.cir.expected_consumption_plans.items.items.len or
        draft.retirement_index >= self.cir.expected_consumer_retirements.items.items.len)
    {
        std.debug.panic("record-update owner retirement lost its durable coordinates", .{});
    }
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(expr_idx));
    if (node.tag != .expr_record or draft.original_node_tag != @intFromEnum(node.tag) or
        !std.meta.eql(
            draft.original_payload,
            @as([4]u32, @bitCast(node.getPayload())),
        ))
    {
        std.debug.panic("record-update owner retirement changed its original record", .{});
    }
    const base_plan = self.cir.expected_consumption_plans.items.items[draft.base_plan_index];
    const base_node = if (base_plan.site_node < self.cir.store.nodes.len())
        self.cir.store.nodes.get(@enumFromInt(base_plan.site_node))
    else
        std.debug.panic("record-update owner retirement lost its base node", .{});
    const base_phase: RecordUpdateBaseNodePhase = if (base_node.tag == .malformed)
        .retired
    else if (isExprNodeTag(base_node.tag))
        .live
    else
        std.debug.panic("record-update owner retirement found an invalid base phase", .{});
    if (!recordUpdateOwnerExpectedMembershipAtPhase(
        self,
        expr_idx,
        draft.base_plan_index,
        draft.base_cause,
        base_phase,
    ) or !recordUpdateBaseCauseIsValidAtProducer(
        self,
        @enumFromInt(base_plan.site_node),
        draft.base_plan_index,
        draft.base_cause,
    )) {
        std.debug.panic("record-update owner retirement changed its exact plan membership", .{});
    }
    const source_retirement_index = base_plan.decodedSourceRetirementIndex() orelse
        std.debug.panic("record-update owner retirement lost its base retirement", .{});
    if (base_phase == .retired) {
        if (!expectedRecordUpdateBaseSourceRetirementIsLocallyValid(self.cir, base_plan)) {
            std.debug.panic("record-update owner retirement lost its completed base lifecycle", .{});
        }
    } else {
        const pending = pendingExpressionRetirementAtProducer(
            self,
            @enumFromInt(base_plan.site_node),
        ) orelse std.debug.panic("record-update owner retirement lost its pending base lifecycle", .{});
        if (pending != source_retirement_index) {
            std.debug.panic("record-update owner retirement changed its pending base lifecycle", .{});
        }
    }
    const retirement = self.cir.expected_consumer_retirements.items.items[
        draft.retirement_index
    ];
    if (retirement.retired_node != @intFromEnum(expr_idx) or
        retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_expected or
        retirement.original_node_tag != draft.original_node_tag or
        !std.meta.eql(retirement.original_payload, draft.original_payload) or
        retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.retired_consumers_start != 0 or retirement.retired_consumers_len != 0 or
        retirement.expected_failures_start != 0 or retirement.expected_failures_len != 0 or
        retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.rejection_owner_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.rejection_subject_var != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.reserved_0 != 0 or retirement.reserved_1 != 0)
    {
        std.debug.panic("record-update owner retirement changed before completion", .{});
    }
    var member_count: usize = 0;
    for (self.record_update_expected_plan_registrations.items) |registration| {
        member_count += @intFromBool(registration.owner_expr == expr_idx);
    }
    if (member_count == 0) {
        std.debug.panic("record-update owner retirement lost its base registration", .{});
    }
    const retired_consumers_start = self.cir.expected_retired_consumers.items.items.len;
    try self.cir.expected_retired_consumers.items.ensureUnusedCapacity(
        self.cir.gpa,
        member_count,
    );
    return .{
        .draft_index = selected_index,
        .draft = draft,
        .retired_consumers_start = retired_consumers_start,
        .member_count = member_count,
    };
}

fn commitRecordUpdateOwnerRetirement(
    self: *Self,
    prepared: PreparedRecordUpdateOwnerRetirement,
    diagnostic_idx: CIR.Diagnostic.Idx,
) void {
    if (self.probe_depth != 0 or
        self.cir.expected_retired_consumers.items.items.len != prepared.retired_consumers_start or
        prepared.draft_index >= self.record_update_owner_retirement_drafts.items.len)
    {
        std.debug.panic("record-update owner retirement changed after reservation", .{});
    }
    const current_draft = self.record_update_owner_retirement_drafts.items[
        prepared.draft_index
    ];
    if (current_draft.owner_expr != prepared.draft.owner_expr or
        current_draft.retirement_index != prepared.draft.retirement_index or
        current_draft.base_plan_index != prepared.draft.base_plan_index or
        !expectedCauseOwnersEqual(current_draft.base_cause, prepared.draft.base_cause) or
        current_draft.original_node_tag != prepared.draft.original_node_tag or
        !std.meta.eql(current_draft.original_payload, prepared.draft.original_payload))
    {
        std.debug.panic("record-update owner retirement changed after reservation", .{});
    }
    const plans = self.cir.expected_consumption_plans.items.items;
    var appended: usize = 0;
    for (self.record_update_expected_plan_registrations.items) |registration| {
        if (registration.owner_expr != prepared.draft.owner_expr) continue;
        const plan = plans[registration.plan_index];
        self.cir.expected_retired_consumers.items.appendAssumeCapacity(.{
            .plan_index = registration.plan_index,
            .owner_node = plan.owner_node,
            .site_node = plan.site_node,
            .role = plan.role,
            .slot = plan.slot,
            .raw_owner_var = @intFromEnum(prepared.draft.owner_expr),
            .raw_consumer_var = plan.raw_consumer_var,
            .reason = @intFromEnum(
                ModuleEnv.ExpectedRetiredConsumer.RetirementOnlyReason.record_update_retired_after_base_checked_error,
            ),
        });
        appended += 1;
    }
    if (appended != prepared.member_count) {
        std.debug.panic("record-update owner retirement changed its reserved member count", .{});
    }
    const new_consumers = self.cir.expected_retired_consumers.items.items[prepared.retired_consumers_start..];
    std.mem.sortUnstable(
        ModuleEnv.ExpectedRetiredConsumer,
        new_consumers,
        {},
        expectedRetiredConsumerLessThan,
    );
    for (new_consumers[1..], new_consumers[0 .. new_consumers.len - 1]) |current, prior| {
        if (std.meta.eql(current, prior)) {
            std.debug.panic("record-update owner retirement duplicated one consumer", .{});
        }
    }
    const retirement = &self.cir.expected_consumer_retirements.items.items[
        prepared.draft.retirement_index
    ];
    retirement.retired_consumers_start = @intCast(prepared.retired_consumers_start);
    retirement.retired_consumers_len = @intCast(prepared.member_count);
    retirement.diagnostic_index = @intFromEnum(diagnostic_idx);
    _ = self.record_update_owner_retirement_drafts.swapRemove(prepared.draft_index);
}

fn directBinderLookupFailureHasBasicRetirementIdentity(
    cir: *const ModuleEnv,
    retirement_index: u32,
    failure_index: u32,
) bool {
    if (retirement_index >= cir.expected_consumer_retirements.items.items.len or
        failure_index >= cir.expected_failures.items.items.len)
    {
        return false;
    }
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    if (retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_ineligible or
        retirement.decodedOriginalNodeTag() != .expr_var or
        retirement.retired_consumers_start != 0 or retirement.retired_consumers_len != 0 or
        retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none)
    {
        return false;
    }
    const payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    if (!std.mem.allEqual(u8, &payload.expr_var._padding, 0) or
        payload.expr_var.pattern_idx >= cir.store.nodes.len())
    {
        return false;
    }
    const failure = cir.expected_failures.items.items[failure_index];
    const direct = failure.subject_authority.decodedDirect() orelse return false;
    const source_retirement = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return false;
    if (direct.local_record_index >= failure_index or
        direct.local_record_index >= cir.expected_failures.items.items.len)
    {
        return false;
    }
    const source_failure = cir.expected_failures.items.items[direct.local_record_index];
    return failure.hasLegalTagsAt(failure_index) and
        failure.decodedKind() == .direct_binder_lookup_checked_error and
        failure.decodedOwnerKind() == .expression and
        failure.owner_node == retirement.retired_node and
        failure.raw_owner_var == retirement.retired_node and
        failure.site_node == payload.expr_var.pattern_idx and
        failure.raw_subject_var == payload.expr_var.pattern_idx and
        failure.raw_peer_var < cir.types.len() and
        failure.constraint_index == ModuleEnv.ExpectedFailure.none and
        failure.plan_index == ModuleEnv.ExpectedFailure.none and
        failure.subject_authority.decodedDirectPhase() ==
            .direct_binder_lookup_checked_error and
        direct.producer_node == payload.expr_var.pattern_idx and
        source_retirement.index < cir.expected_consumer_retirements.items.items.len and
        source_failure.hasLegalTagsAt(direct.local_record_index) and
        source_failure.decodedKind() == .annotation_malformed_type;
}

fn completedDirectBinderLookupFailureForRetirement(
    cir: *const ModuleEnv,
    retirement_index: u32,
) ?u32 {
    if (retirement_index >= cir.expected_consumer_retirements.items.items.len) return null;
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    if (retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_ineligible or
        retirement.expected_failures_len != 1 or
        !expectedConsumerRetirementNodeIsLocallyValid(cir, retirement) or
        !rangeFits(
            retirement.expected_failures_start,
            retirement.expected_failures_len,
            cir.expected_retirement_failures.items.items.len,
        ))
    {
        return null;
    }
    const failure_index = cir.expected_retirement_failures.items.items[
        retirement.expected_failures_start
    ].failure_index;
    if (failure_index >= cir.expected_failures.items.items.len) return null;
    if (!directBinderLookupFailureHasBasicRetirementIdentity(
        cir,
        retirement_index,
        failure_index,
    )) return null;
    const snapshot = expectedLookupRetirementOwningFailure(cir, failure_index) orelse
        return null;
    return if (snapshot.retirement_index == retirement_index) failure_index else null;
}

/// At call retirement time hash-table order may leave the argument lookup
/// either pending or already rewritten. Authenticate those two producer phases
/// explicitly; the complete F_A/R_A source replay remains a terminal admission
/// requirement rather than an ordering constraint on poisoning.
fn directBinderLookupFailureForCallCompletion(
    self: *const Self,
    retirement_index: u32,
) ?u32 {
    if (retirement_index >= self.cir.expected_consumer_retirements.items.items.len) {
        return null;
    }
    const retirement = self.cir.expected_consumer_retirements.items.items[retirement_index];
    if (retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none) {
        var matching_drafts: usize = 0;
        for (self.annotation_expected_failure_drafts.items) |draft| {
            if (draft.retirement_index == retirement_index or
                draft.owner_expr == @as(CIR.Expr.Idx, @enumFromInt(retirement.retired_node)))
            {
                matching_drafts += 1;
            }
        }
        if (matching_drafts != 0 or
            !expectedConsumerRetirementNodeIsLocallyValid(self.cir, retirement))
        {
            return null;
        }
        return completedDirectBinderLookupFailureForRetirement(
            self.cir,
            retirement_index,
        );
    }
    if (retirement.expected_failures_start != 0 or retirement.expected_failures_len != 0 or
        retirement.retired_node >= self.cir.store.nodes.len())
    {
        return null;
    }
    const current_node = self.cir.store.nodes.get(@enumFromInt(retirement.retired_node));
    if (current_node.tag != .expr_var or
        !std.meta.eql(
            retirement.original_payload,
            @as([4]u32, @bitCast(current_node.getPayload())),
        ))
    {
        return null;
    }
    var selected_failure: ?u32 = null;
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.retirement_index != retirement_index and
            draft.owner_expr != @as(CIR.Expr.Idx, @enumFromInt(retirement.retired_node)))
        {
            continue;
        }
        if (draft.retirement_index != retirement_index or
            draft.owner_expr != @as(CIR.Expr.Idx, @enumFromInt(retirement.retired_node)) or
            draft.producer_kind != .direct_binder_lookup or selected_failure != null)
        {
            return null;
        }
        selected_failure = draft.failure_index;
    }
    const failure_index = selected_failure orelse return null;
    if (expectedFailureOwningRetirement(self.cir, failure_index) != null) return null;
    return if (directBinderLookupFailureHasBasicRetirementIdentity(
        self.cir,
        retirement_index,
        failure_index,
    )) failure_index else null;
}

/// Complete the one aggregate retirement reason which owns both a successful
/// call-plan range and a failure-reference range. Every semantic check and all
/// scratch allocation precede both capacity reservations; after the first
/// append no operation may fail.
fn completeCallOperandExpectedRetirement(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    diagnostic_idx: CIR.Diagnostic.Idx,
    aggregate_draft_index: usize,
    draft: AggregateExpectedRetirementDraft,
) Allocator.Error!void {
    const plans = self.cir.expected_consumption_plans.items.items;
    const failures = self.cir.expected_failures.items.items;
    if (draft.retired_reason != .call_retired_after_operand_checked_error or
        draft.plans_len < 2 or
        !rangeFits(draft.plans_start, draft.plans_len, plans.len) or
        draft.retirement_index >= self.cir.expected_consumer_retirements.items.items.len)
    {
        std.debug.panic("call operand retirement lost its complete plan draft", .{});
    }
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(expr_idx));
    if (node.tag != .expr_call or !self.cir.store.isDiagnosticIndex(diagnostic_idx)) {
        std.debug.panic("call operand retirement lost its live call or diagnostic", .{});
    }
    const call = switch (self.cir.store.getExpr(expr_idx)) {
        .e_call => |present| present,
        else => unreachable,
    };
    const call_payload = node.getPayload().expr_call;
    const call_args = self.cir.store.sliceExpr(call.args);
    if (call_payload.constraint_fn_var_plus_one != 0 or call.constraint_fn_var != null or
        draft.plans_len != call_args.len + 1)
    {
        std.debug.panic("call operand retirement changed its zero-stamp call", .{});
    }
    const retirement = &self.cir.expected_consumer_retirements.items.items[
        draft.retirement_index
    ];
    if (retirement.retired_node != @intFromEnum(expr_idx) or
        retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_expected or
        retirement.decodedOriginalNodeTag() != .expr_call or
        !std.meta.eql(
            retirement.original_payload,
            @as([4]u32, @bitCast(node.getPayload())),
        ) or
        retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.retired_consumers_start != 0 or retirement.retired_consumers_len != 0 or
        retirement.expected_failures_start != 0 or retirement.expected_failures_len != 0 or
        retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none)
    {
        std.debug.panic("call operand retirement changed before completion", .{});
    }

    var failure_count: usize = 0;
    for (self.annotation_expected_failure_drafts.items) |failure_draft| {
        if (failure_draft.owner_expr != expr_idx) continue;
        if (failure_draft.producer_kind != .call_operand or
            failure_draft.retirement_index != draft.retirement_index or
            failure_draft.failure_index >= failures.len)
        {
            std.debug.panic("call operand retirement mixed failure draft producers", .{});
        }
        failure_count += 1;
    }
    if (failure_count == 0) {
        std.debug.panic("call operand retirement had no exact operand failure", .{});
    }
    var failure_indices_sfa = std.heap.stackFallback(16 * @sizeOf(u32), self.gpa);
    const failure_indices_allocator = failure_indices_sfa.get();
    const failure_indices = try failure_indices_allocator.alloc(u32, failure_count);
    defer failure_indices_allocator.free(failure_indices);
    var next_failure: usize = 0;
    for (self.annotation_expected_failure_drafts.items) |failure_draft| {
        if (failure_draft.owner_expr != expr_idx) continue;
        failure_indices[next_failure] = failure_draft.failure_index;
        next_failure += 1;
    }
    std.mem.sortUnstable(
        u32,
        failure_indices,
        failures,
        struct {
            fn lessThan(
                expected_failures: []const ModuleEnv.ExpectedFailure,
                left: u32,
                right: u32,
            ) bool {
                return expectedFailureKeyLessThan(expected_failures, left, right);
            }
        }.lessThan,
    );
    for (failure_indices, 0..) |failure_index, failure_offset| {
        if (failure_offset != 0 and failure_indices[failure_offset - 1] == failure_index) {
            std.debug.panic("call operand retirement duplicated one failure", .{});
        }
    }

    const root_plan = plans[draft.plans_start];
    const call_snapshot = expectedCallOperandRetirementTopologyFromPayload(
        self.cir,
        node.getPayload(),
    ) orelse std.debug.panic("call operand retirement lost its canonical call payload", .{});
    if (!expectedCallRootPlanMatchesSnapshot(self.cir, root_plan, call_snapshot)) {
        std.debug.panic("call operand retirement lost its successful root plan", .{});
    }
    const root_token_index = expectedCallSlotTokenIndex(
        self.cir,
        @intFromEnum(expr_idx),
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse std.debug.panic("call operand retirement lost its root token", .{});
    const validated_root = ExpectedCallValidatedRoot{
        .plan_index = draft.plans_start,
        .plan = root_plan,
        .call = call_snapshot,
        .root_token_index = root_token_index,
    };
    for (call_args, 0..) |argument_expr, slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        const argument_plan_index = draft.plans_start + 1 + slot;
        if (!expectedCallArgumentPlanIsTerminal(
            self.cir,
            validated_root,
            argument_plan_index,
            slot,
        )) {
            std.debug.panic("call operand retirement changed an argument plan", .{});
        }
        var formal_matches: usize = 0;
        for (self.cir.expected_call_formals.items.items) |formal| {
            if (formal.owner_node != @intFromEnum(expr_idx) or formal.slot != slot) continue;
            const slot_token_index = expectedCallSlotTokenIndex(
                self.cir,
                @intFromEnum(expr_idx),
                .argument,
                slot,
            ) orelse std.debug.panic("call operand retirement lost an argument token", .{});
            if (!expectedCallFormalMatchesValidatedRoot(
                self.cir,
                formal,
                validated_root,
                argument_plan_index,
                slot_token_index,
            )) {
                std.debug.panic("call operand retirement changed an exact formal", .{});
            }
            formal_matches += 1;
        }
        if (formal_matches != 1) {
            std.debug.panic("call operand retirement lost its unique formal", .{});
        }
        _ = argument_expr;
    }

    var previous_slot: ?u32 = null;
    for (failure_indices) |failure_index| {
        const failure = failures[failure_index];
        const source_retirement = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            std.debug.panic("call operand failure lost its lookup retirement", .{});
        if (!failure.hasLegalTagsAt(failure_index) or
            failure.decodedKind() != .call_operand_checked_error or
            failure.owner_node != @intFromEnum(expr_idx) or
            failure.raw_owner_var != @intFromEnum(ModuleEnv.varFrom(expr_idx)) or
            failure.constraint_index != ModuleEnv.ExpectedFailure.none or
            failure.slot >= call_args.len or
            failure.site_node != @intFromEnum(call_args[failure.slot]) or
            failure.raw_peer_var != @intFromEnum(ModuleEnv.varFrom(call_args[failure.slot])) or
            failure.plan_index != draft.plans_start + 1 + failure.slot or
            failure.raw_subject_var != plans[failure.plan_index].raw_consumer_var or
            !expectedSubjectAuthoritiesEqual(
                failure.subject_authority,
                ModuleEnv.SubjectAuthority.expectedProducerRootPlan(
                    failure.plan_index,
                    failure.raw_subject_var,
                ),
            ) or
            self.directBinderLookupFailureForCallCompletion(
                source_retirement.index,
            ) == null or
            self.cir.expected_consumer_retirements.items.items[
                source_retirement.index
            ].retired_node != failure.site_node)
        {
            std.debug.panic("call operand retirement changed an exact operand failure", .{});
        }
        if (previous_slot != null and previous_slot.? == failure.slot) {
            std.debug.panic("call operand retirement duplicated one argument slot", .{});
        }
        previous_slot = failure.slot;
    }

    // Both allocations finish before either semantic range grows. Capacity
    // changes alone are harmless on failure; the append lengths, row, drafts,
    // and live call remain unchanged for the exact retry.
    try self.cir.expected_retired_consumers.items.ensureUnusedCapacity(
        self.cir.gpa,
        draft.plans_len,
    );
    try self.cir.expected_retirement_failures.items.ensureUnusedCapacity(
        self.cir.gpa,
        failure_count,
    );
    const retired_start: u32 = @intCast(self.cir.expected_retired_consumers.items.items.len);
    const failures_start: u32 = @intCast(self.cir.expected_retirement_failures.items.items.len);
    for (plans[draft.plans_start..][0..draft.plans_len], 0..) |plan, plan_offset| {
        self.cir.expected_retired_consumers.items.appendAssumeCapacity(.{
            .plan_index = draft.plans_start + @as(u32, @intCast(plan_offset)),
            .owner_node = plan.owner_node,
            .site_node = plan.site_node,
            .role = plan.role,
            .slot = plan.slot,
            .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(expr_idx)),
            .raw_consumer_var = plan.raw_consumer_var,
            .reason = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error),
        });
    }
    for (failure_indices) |failure_index| {
        self.cir.expected_retirement_failures.items.appendAssumeCapacity(.{
            .failure_index = failure_index,
        });
    }
    retirement.original_node_tag = @intFromEnum(node.tag);
    retirement.original_payload = @bitCast(node.getPayload());
    retirement.retired_consumers_start = retired_start;
    retirement.retired_consumers_len = draft.plans_len;
    retirement.expected_failures_start = failures_start;
    retirement.expected_failures_len = @intCast(failure_count);
    retirement.diagnostic_index = @intFromEnum(diagnostic_idx);

    var retained_drafts: usize = 0;
    for (self.annotation_expected_failure_drafts.items) |failure_draft| {
        if (failure_draft.owner_expr == expr_idx) continue;
        self.annotation_expected_failure_drafts.items[retained_drafts] = failure_draft;
        retained_drafts += 1;
    }
    self.annotation_expected_failure_drafts.shrinkRetainingCapacity(retained_drafts);
    _ = self.aggregate_expected_retirement_drafts.swapRemove(aggregate_draft_index);
}

/// Complete a projection-rejection retirement at the destructive rewrite
/// boundary. Its owned consumer range is copied directly from the exact
/// producer-reserved plan range; no final-CIR topology scan participates.
fn completeAggregateExpectedRetirement(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    diagnostic_idx: CIR.Diagnostic.Idx,
) Allocator.Error!void {
    var draft_index: ?usize = null;
    for (self.aggregate_expected_retirement_drafts.items, 0..) |draft, index| {
        if (draft.owner_expr != expr_idx) continue;
        if (draft_index != null) {
            std.debug.panic("one aggregate owner reached multiple projection retirements", .{});
        }
        draft_index = index;
    }
    const selected_index = draft_index orelse return;
    const draft = self.aggregate_expected_retirement_drafts.items[selected_index];
    if (!self.cir.store.isDiagnosticIndex(diagnostic_idx) or
        draft.retirement_index >= self.cir.expected_consumer_retirements.items.items.len or
        (draft.plans_len != 0 and
            !rangeFits(draft.plans_start, draft.plans_len, self.cir.expected_consumption_plans.items.items.len)))
    {
        std.debug.panic("aggregate projection retirement lost its producer draft", .{});
    }
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(expr_idx));
    const retirement = &self.cir.expected_consumer_retirements.items.items[draft.retirement_index];
    const expected_retirement_kind: ModuleEnv.ExpectedConsumerRetirement.Kind =
        if (draft.plans_len == 0) .checker_rewrite_ineligible else .checker_rewrite_expected;
    if (retirement.retired_node != @intFromEnum(expr_idx) or
        retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != expected_retirement_kind or
        retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.retired_consumers_start != 0 or retirement.retired_consumers_len != 0 or
        retirement.expected_failures_start != 0 or retirement.expected_failures_len != 0)
    {
        std.debug.panic("aggregate projection retirement changed before completion", .{});
    }

    if (draft.retired_reason == .call_retired_after_operand_checked_error) {
        try self.completeCallOperandExpectedRetirement(
            expr_idx,
            diagnostic_idx,
            selected_index,
            draft,
        );
        return;
    }

    // A branch-body rejection retires only the body expression. The enclosing
    // branch contribution stays present and names this row as its direct
    // source cause, so there is deliberately no retired-consumer range.
    if (draft.plans_len == 0) {
        if (retirement.decodedKind() != .checker_rewrite_ineligible or
            draft.retired_reason != .branch_body_error_short_circuit)
        {
            std.debug.panic("branch-body retirement used the aggregate-owner lifecycle", .{});
        }
        retirement.original_node_tag = @intFromEnum(node.tag);
        retirement.original_payload = @bitCast(node.getPayload());
        retirement.diagnostic_index = @intFromEnum(diagnostic_idx);
        _ = self.aggregate_expected_retirement_drafts.swapRemove(selected_index);
        return;
    }

    const retired_start = self.cir.expected_retired_consumers.items.items.len;
    errdefer self.cir.expected_retired_consumers.items.shrinkRetainingCapacity(retired_start);
    try self.cir.expected_retired_consumers.items.ensureUnusedCapacity(
        self.cir.gpa,
        draft.plans_len,
    );
    const plans = self.cir.expected_consumption_plans.items.items[draft.plans_start..][0..draft.plans_len];
    const cause = ModuleEnv.CauseOwner.expectedConsumerRetirement(draft.retirement_index);
    const retired_reason = draft.retired_reason;
    if (ModuleEnv.ExpectedConsumptionPlan.ownerRelationForReason(retired_reason) != .same_node_retirement) {
        std.debug.panic("Expected-plan retirement borrowed a non-owning reason", .{});
    }
    var child_relation_failures: usize = 0;
    var parent_retired_no_expected_rows: usize = 0;
    var branch_final_rows: usize = 0;
    var call_root_rows: usize = 0;
    var call_argument_rows: usize = 0;
    for (plans, 0..) |plan, relative_index| {
        const role = plan.decodedRole() orelse
            std.debug.panic("Expected-plan retirement contained an invalid role", .{});
        if (!plan.hasLegalTags() or !ModuleEnv.ExpectedConsumptionPlan.legalCombination(
            role,
            .checked_error,
            retired_reason,
            .expected_consumer_retirement,
            false,
        )) {
            std.debug.panic("aggregate retirement plan did not name its exact rejection", .{});
        }
        if (retired_reason == .aggregate_retired_after_child_relation) {
            switch (plan.decodedOutcome() orelse
                std.debug.panic("aggregate child retirement contained an invalid plan outcome", .{})) {
                .anchored, .evidence_free => {},
                .checked_error => {
                    const plan_reason = plan.decodedReason() orelse
                        std.debug.panic("failed aggregate child lost its direct reason", .{});
                    if ((plan_reason != .aggregate_child_relation_rejected and
                        plan_reason != .aggregate_child_relation_suppressed) or
                        !plan.failure_owner.hasCanonicalTags(true) or
                        plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                    {
                        std.debug.panic("aggregate child retirement changed its exact direct failure", .{});
                    }
                    child_relation_failures += 1;
                },
                .related,
                .source_root_copy,
                .source_root_copy_checked_error,
                .producer_root,
                .retained,
                .not_projected,
                .reserved,
                => std.debug.panic(
                    "aggregate child retirement contained an unestablished consumer",
                    .{},
                ),
            }
        } else if (retired_reason == .aggregate_retired_by_parent_branch_failure) {
            switch (plan.decodedOutcome() orelse
                std.debug.panic("parent-retired aggregate contained an invalid plan outcome", .{})) {
                .anchored, .evidence_free => {},
                .not_projected => {
                    if (plan.decodedReason() != .aggregate_no_expected or
                        plan.parent_authority.kind != ModuleEnv.ExpectedMarkerAuthority.none or
                        plan.failure_owner.kind != ModuleEnv.CauseOwner.none or
                        plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                    {
                        std.debug.panic("parent-retired aggregate changed its benign no-Expected outcome", .{});
                    }
                    parent_retired_no_expected_rows += 1;
                },
                .producer_root,
                .source_root_copy,
                .source_root_copy_checked_error,
                .related,
                .retained,
                .checked_error,
                .reserved,
                => std.debug.panic(
                    "parent-retired aggregate contained a failed or incomplete consumer",
                    .{},
                ),
            }
        } else if (retired_reason == .branch_retired_after_failure) {
            switch (role) {
                .branch_seed => switch (plan.decodedOutcome() orelse
                    std.debug.panic("retired branch seed contained an invalid outcome", .{})) {
                    .anchored => {},
                    .related,
                    .source_root_copy,
                    .source_root_copy_checked_error,
                    .producer_root,
                    .evidence_free,
                    .retained,
                    .not_projected,
                    .checked_error,
                    .reserved,
                    => std.debug.panic(
                        "retired branch contained an unestablished seed",
                        .{},
                    ),
                },
                .branch_contribution => switch (plan.decodedOutcome() orelse
                    std.debug.panic("retired branch contribution contained an invalid outcome", .{})) {
                    .related, .retained => {},
                    .checked_error => {
                        const plan_reason = plan.decodedReason() orelse
                            std.debug.panic("retired branch contribution lost its direct failure", .{});
                        if ((plan_reason != .branch_body_error_short_circuit and
                            plan_reason != .branch_expected_compatibility_rejected and
                            plan_reason != .branch_accumulator_fold_rejected) or
                            !plan.failure_owner.hasCanonicalTags(true) or
                            plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                        {
                            std.debug.panic("retired branch contribution changed its direct failure", .{});
                        }
                    },
                    .anchored,
                    .source_root_copy,
                    .source_root_copy_checked_error,
                    .producer_root,
                    .evidence_free,
                    .not_projected,
                    .reserved,
                    => std.debug.panic(
                        "retired branch contained an unestablished contribution",
                        .{},
                    ),
                },
                .branch_final => {
                    branch_final_rows += 1;
                    switch (plan.decodedOutcome() orelse
                        std.debug.panic("retired branch final contained an invalid outcome", .{})) {
                        // A containing branch may retire a nested branch whose
                        // own final relation had already completed.
                        .related => {},
                        .checked_error => if (plan.decodedReason() != .branch_final_relation_rejected or
                            !expectedCauseOwnersEqual(plan.failure_owner, cause) or
                            plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                        {
                            std.debug.panic("retired branch final changed its same-node rejection", .{});
                        },
                        .anchored,
                        .source_root_copy,
                        .source_root_copy_checked_error,
                        .producer_root,
                        .evidence_free,
                        .retained,
                        .not_projected,
                        .reserved,
                        => std.debug.panic(
                            "retired branch contained an unestablished final relation",
                            .{},
                        ),
                    }
                },
                .aggregate_owner,
                .list_element,
                .tuple_element,
                .record_field,
                .tag_payload,
                .record_update_base,
                .record_update_field,
                .nominal_decl,
                .nominal_backing,
                .call_root,
                .call_argument,
                .default_field,
                .lambda_return,
                => std.debug.panic("branch retirement contained a non-branch plan", .{}),
            }
        } else if (retired_reason == .branch_retired_after_ambiguity_verdict) {
            // The ambiguity pass runs only after branch checking has settled.
            // Unlike a relation failure, it cannot borrow a failed row: every
            // member must still describe the successful pre-rewrite branch.
            switch (role) {
                .branch_seed => if (plan.decodedOutcome() != .anchored or
                    plan.decodedReason() != null or
                    plan.failure_owner.kind != ModuleEnv.CauseOwner.none)
                {
                    std.debug.panic("ambiguity-retired branch changed its settled seed", .{});
                },
                .branch_contribution => switch (plan.decodedOutcome() orelse
                    std.debug.panic("ambiguity-retired branch contribution had an invalid outcome", .{})) {
                    .related, .retained => {},
                    .anchored,
                    .source_root_copy,
                    .source_root_copy_checked_error,
                    .producer_root,
                    .evidence_free,
                    .not_projected,
                    .checked_error,
                    .reserved,
                    => std.debug.panic(
                        "ambiguity-retired branch contained an unsettled contribution",
                        .{},
                    ),
                },
                .branch_final => {
                    branch_final_rows += 1;
                    if (plan.decodedOutcome() != .related or
                        plan.decodedReason() != null or
                        plan.failure_owner.kind != ModuleEnv.CauseOwner.none)
                    {
                        std.debug.panic("ambiguity-retired branch changed its settled final relation", .{});
                    }
                },
                .aggregate_owner,
                .list_element,
                .tuple_element,
                .record_field,
                .tag_payload,
                .record_update_base,
                .record_update_field,
                .nominal_decl,
                .nominal_backing,
                .call_root,
                .call_argument,
                .default_field,
                .lambda_return,
                => std.debug.panic("ambiguity retirement contained a non-branch plan", .{}),
            }
        } else if (retired_reason == .call_retired) {
            const call = switch (self.cir.store.getExpr(expr_idx)) {
                .e_call => |present| present,
                else => std.debug.panic("call ambiguity retirement lost its original call", .{}),
            };
            const args = self.cir.store.sliceExpr(call.args);
            switch (role) {
                .call_root => {
                    call_root_rows += 1;
                    if (relative_index != 0 or
                        plan.decodedOutcome() != .not_projected or
                        plan.decodedReason() != .call_shape_ready or
                        plan.site_node != @intFromEnum(call.func) or
                        plan.raw_consumer_var != @intFromEnum(call.func) or
                        plan.call_root_plan_index != ModuleEnv.ExpectedConsumptionPlan.none or
                        plan.failure_owner.kind != ModuleEnv.CauseOwner.none or
                        plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                    {
                        std.debug.panic("call ambiguity retirement changed its settled root", .{});
                    }
                },
                .call_argument => {
                    call_argument_rows += 1;
                    const slot: usize = plan.slot;
                    if (plan.decodedOutcome() != .producer_root or
                        plan.decodedReason() != null or
                        slot >= args.len or
                        plan.site_node != @intFromEnum(args[slot]) or
                        plan.call_root_plan_index != draft.plans_start or
                        plan.failure_owner.kind != ModuleEnv.CauseOwner.none or
                        plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                    {
                        std.debug.panic("call ambiguity retirement changed an exact argument root", .{});
                    }
                },
                .aggregate_owner,
                .list_element,
                .tuple_element,
                .record_field,
                .tag_payload,
                .record_update_base,
                .record_update_field,
                .branch_seed,
                .branch_contribution,
                .branch_final,
                .nominal_decl,
                .nominal_backing,
                .default_field,
                .lambda_return,
                => std.debug.panic("call ambiguity retirement contained a non-call plan", .{}),
            }
        } else {
            const plan_reason = plan.decodedReason() orelse
                std.debug.panic("Expected-plan retirement contained a successful row", .{});
            if (plan_reason != retired_reason or
                !expectedCauseOwnersEqual(plan.failure_owner, cause) or
                plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
            {
                std.debug.panic("aggregate retirement plan did not name its exact rejection", .{});
            }
        }
        self.cir.expected_retired_consumers.items.appendAssumeCapacity(.{
            .plan_index = draft.plans_start + @as(u32, @intCast(relative_index)),
            .owner_node = plan.owner_node,
            .site_node = plan.site_node,
            .role = plan.role,
            .slot = plan.slot,
            .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(expr_idx)),
            .raw_consumer_var = plan.raw_consumer_var,
            .reason = @intFromEnum(retired_reason),
        });
    }
    if (retired_reason == .aggregate_retired_after_child_relation and child_relation_failures == 0) {
        std.debug.panic("aggregate child retirement had no exact failing child", .{});
    }
    if (retired_reason == .aggregate_retired_by_parent_branch_failure) {
        if (parent_retired_no_expected_rows != 0 and
            parent_retired_no_expected_rows != plans.len)
        {
            std.debug.panic("parent-retired aggregate mixed projected and no-Expected consumers", .{});
        }
        if (!aggregateParentBranchRetirementEdgeIsLocallyValid(
            self.cir,
            draft.retirement_index,
            @intFromEnum(expr_idx),
        )) {
            std.debug.panic("parent-retired aggregate lost its exact enclosing branch edge", .{});
        }
    }
    if ((retired_reason == .branch_retired_after_failure or
        retired_reason == .branch_retired_after_ambiguity_verdict) and branch_final_rows != 1)
    {
        std.debug.panic("branch retirement lost its unique final row", .{});
    }
    if (retired_reason == .call_retired and
        (call_root_rows != 1 or call_argument_rows + 1 != plans.len))
    {
        std.debug.panic("call ambiguity retirement lost its exact root-plus-arguments range", .{});
    }

    retirement.original_node_tag = @intFromEnum(node.tag);
    retirement.original_payload = @bitCast(node.getPayload());
    retirement.retired_consumers_start = @intCast(retired_start);
    retirement.retired_consumers_len = draft.plans_len;
    retirement.diagnostic_index = @intFromEnum(diagnostic_idx);

    _ = self.aggregate_expected_retirement_drafts.swapRemove(selected_index);
}

/// Complete one closed ineligible producer's retirement at the mutation
/// boundary where its final runtime-error diagnostic becomes known. Failure
/// rows may be authored in any global order, so this builds the retirement's
/// owned range by their stable semantic key rather than by assuming adjacent
/// publications.
fn completeIneligibleFailureRetirement(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    diagnostic_idx: CIR.Diagnostic.Idx,
) Allocator.Error!void {
    var retirement_index: ?u32 = null;
    var producer_kind: ?AnnotationExpectedFailureDraft.ProducerKind = null;
    var cause_count: usize = 0;
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != expr_idx) continue;
        if (retirement_index) |existing| {
            if (existing != draft.retirement_index) {
                std.debug.panic("one annotation owner reached multiple retirement drafts", .{});
            }
        } else {
            retirement_index = draft.retirement_index;
        }
        if (producer_kind) |existing| {
            if (existing != draft.producer_kind) {
                std.debug.panic("one ineligible owner mixed failure producer kinds", .{});
            }
        } else {
            producer_kind = draft.producer_kind;
        }
        cause_count += 1;
    }
    const selected_retirement = retirement_index orelse return;
    const selected_producer = producer_kind orelse unreachable;

    if (!self.cir.store.isDiagnosticIndex(diagnostic_idx) or
        selected_retirement >= self.cir.expected_consumer_retirements.items.items.len)
    {
        std.debug.panic("ineligible retirement completion lost its final diagnostic or draft", .{});
    }
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(expr_idx));
    const retirement = &self.cir.expected_consumer_retirements.items.items[selected_retirement];
    const reserved_tag = retirement.decodedOriginalNodeTag() orelse
        std.debug.panic("annotation retirement draft lost its original node tag", .{});
    if (retirement.retired_node != @intFromEnum(expr_idx) or
        retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_ineligible or
        !isExprNodeTag(reserved_tag) or
        !isExprNodeTag(node.tag) or
        retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.retired_consumers_start != 0 or
        retirement.retired_consumers_len != 0 or
        retirement.expected_failures_start != 0 or
        retirement.expected_failures_len != 0 or
        cause_count == 0)
    {
        std.debug.panic("ineligible retirement completion changed its exact incomplete draft", .{});
    }
    if ((selected_producer == .direct_binder_lookup or
        selected_producer == .annotated_binding_lookup) and
        (node.tag != .expr_var or reserved_tag != .expr_var or
            !std.meta.eql(
                retirement.original_payload,
                @as([4]u32, @bitCast(node.getPayload())),
            )))
    {
        std.debug.panic("typed lookup retirement changed its original lookup payload", .{});
    }

    // This first producer slice intentionally covers only owners for which no
    // Expected-consumer plan has yet been established. Current plan reason and
    // cardinality schemas cannot truthfully retire every call/aggregate slot;
    // extending that closed table is a separate design slice.
    for (self.cir.expected_consumption_plans.items.items) |plan| {
        if (plan.owner_node == @intFromEnum(expr_idx)) {
            std.debug.panic("ineligible failure on an Expected-eligible owner needs a closed plan-retirement transition", .{});
        }
    }

    const causes_start = self.cir.expected_retirement_failures.items.items.len;
    errdefer self.cir.expected_retirement_failures.items.shrinkRetainingCapacity(causes_start);
    const failures = self.cir.expected_failures.items.items;
    var previous_failure: ?u32 = null;
    for (0..cause_count) |_| {
        var next_failure: ?u32 = null;
        for (self.annotation_expected_failure_drafts.items) |draft| {
            if (draft.owner_expr != expr_idx or draft.retirement_index != selected_retirement or
                draft.failure_index >= failures.len)
            {
                continue;
            }
            if (previous_failure) |previous| {
                if (!expectedFailureKeyLessThan(failures, previous, draft.failure_index)) continue;
            }
            if (next_failure == null or
                expectedFailureKeyLessThan(failures, draft.failure_index, next_failure.?))
            {
                next_failure = draft.failure_index;
            }
        }
        const failure_index = next_failure orelse
            std.debug.panic("annotation retirement draft repeated or lost one failure", .{});
        const failure = failures[failure_index];
        if (failure.owner_kind != retirement.owner_kind or
            failure.owner_node != retirement.retired_node)
        {
            std.debug.panic("annotation retirement borrowed another owner's failure", .{});
        }
        switch (selected_producer) {
            .annotation => switch (failure.decodedKind() orelse
                std.debug.panic("annotation retirement owned an invalid failure kind", .{})) {
                .annotation_malformed_type,
                .annotation_malformed_where,
                .annotation_invalid_tag_child,
                .annotation_where_receiver_not_introduced,
                .annotation_where_alias_not_alias,
                .annotation_recursive_where_alias,
                .annotation_where_alias_publication_error,
                .annotation_where_alias_unresolved,
                .annotation_where_alias_arity,
                .annotation_where_alias_in_type_position,
                .annotation_builtin_not_type,
                .annotation_recursive_type_decl,
                .annotation_type_decl_poisoned,
                .annotation_type_formal_poisoned,
                .annotation_type_apply_arity,
                .annotation_alias_row_rejected,
                .annotation_external_type_unresolved,
                .annotation_child_failure,
                .annotation_duplicate_where_signature_rejected,
                => {},
                .direct_binder_lookup_checked_error,
                .annotated_binding_lookup_checked_error,
                .call_operand_checked_error,
                .nominal_pattern_external_unresolved,
                .nominal_pattern_decl_poisoned,
                .nominal_pattern_opaque_inaccessible,
                .nominal_pattern_backing_unavailable,
                .nominal_pattern_backing_checked_error,
                .nominal_pattern_backing_relation_rejected,
                .aggregate_child_relation_rejected,
                => std.debug.panic("annotation retirement borrowed a non-annotation failure", .{}),
            },
            .direct_binder_lookup => if (failure.decodedKind() != .direct_binder_lookup_checked_error) {
                std.debug.panic("direct binder lookup retirement borrowed another failure kind", .{});
            },
            .annotated_binding_lookup => if (failure.decodedKind() != .annotated_binding_lookup_checked_error) {
                std.debug.panic("annotated binding lookup retirement borrowed another failure kind", .{});
            },
            .call_operand => std.debug.panic(
                "call operand failure entered the ineligible-retirement completion path",
                .{},
            ),
        }
        _ = try self.cir.expected_retirement_failures.append(self.cir.gpa, .{
            .failure_index = failure_index,
        });
        previous_failure = failure_index;
    }

    // Expression checking may legitimately stamp exact plan metadata after
    // annotation generation (numeric literals are one example). Nothing may
    // observe this transient row, so complete it with the actual last node
    // bytes immediately before the destructive rewrite, after all fallible
    // failure-reference publication has succeeded.
    retirement.original_node_tag = @intFromEnum(node.tag);
    retirement.original_payload = @bitCast(node.getPayload());
    retirement.expected_failures_start = @intCast(causes_start);
    retirement.expected_failures_len = @intCast(cause_count);
    retirement.diagnostic_index = @intFromEnum(diagnostic_idx);

    var retained: usize = 0;
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr == expr_idx) continue;
        self.annotation_expected_failure_drafts.items[retained] = draft;
        retained += 1;
    }
    self.annotation_expected_failure_drafts.shrinkRetainingCapacity(retained);
}

const ExprInvalidationDiscovery = std.AutoArrayHashMapUnmanaged(CIR.Expr.Idx, void);

fn invalidateExprSubtreeMetadata(self: *Self, root: CIR.Expr.Idx) Allocator.Error!void {
    // Discover offside. The array hash map is both the insertion-ordered work
    // queue and the dedup set, so shared children and return-to-lambda cycles
    // terminate without publishing a partial durable invalidation.
    var discovered: ExprInvalidationDiscovery = .empty;
    defer discovered.deinit(self.gpa);

    try self.discoverInvalidatedExprChildren(root, &discovered);
    var next: usize = 0;
    while (next < discovered.count()) : (next += 1) {
        const expr = discovered.keys()[next];
        try self.discoverInvalidatedExprChildren(expr, &discovered);
    }

    var new_count: u32 = 0;
    for (discovered.keys()) |expr| {
        if (!self.hoist_invalidated_exprs.contains(expr)) new_count += 1;
    }
    try self.hoist_invalidated_exprs.ensureUnusedCapacity(self.gpa, new_count);

    // Every operation after the one durable reserve is infallible. Preserve
    // discovery order because literal-plan retirement uses ordered swap-removal.
    for (discovered.keys()) |expr| {
        if (self.hoist_invalidated_exprs.contains(expr)) continue;
        self.hoist_invalidated_exprs.putAssumeCapacityNoClobber(expr, {});
        self.cir.store.retireLiteralDispatchPlan(ModuleEnv.nodeIdxFrom(expr));
    }

    // Replacing the root makes every construction in its old subtree
    // unreachable. Retire the omission plans attached to those constructions
    // before checked-artifact publication consumes the surviving source tree.
    var retained: usize = 0;
    for (self.cir.record_omitted_defaults.items.items) |omitted| {
        if (self.omittedDefaultBelongsToInvalidatedSubtree(root, omitted.expr)) continue;
        self.cir.record_omitted_defaults.items.items[retained] = omitted;
        retained += 1;
    }
    self.cir.record_omitted_defaults.items.shrinkRetainingCapacity(retained);

    if (builtin.mode == .Debug) {
        for (discovered.keys()) |expr| {
            std.debug.assert(self.hoist_invalidated_exprs.contains(expr));
        }
    }
}

fn omittedDefaultBelongsToInvalidatedSubtree(
    self: *const Self,
    root: CIR.Expr.Idx,
    construction: CIR.Expr.Idx,
) bool {
    return construction == root or self.hoist_invalidated_exprs.contains(construction);
}

fn discoverInvalidatedExpr(
    self: *Self,
    expr: CIR.Expr.Idx,
    discovered: *ExprInvalidationDiscovery,
) Allocator.Error!void {
    _ = try discovered.getOrPut(self.gpa, expr);
}

fn discoverInvalidatedExprSpan(
    self: *Self,
    span: CIR.Expr.Span,
    discovered: *ExprInvalidationDiscovery,
) Allocator.Error!void {
    for (self.cir.store.sliceExpr(span)) |expr| {
        try self.discoverInvalidatedExpr(expr, discovered);
    }
}

fn discoverInvalidatedStatementSpan(
    self: *Self,
    span: CIR.Statement.Span,
    discovered: *ExprInvalidationDiscovery,
) Allocator.Error!void {
    for (self.cir.store.sliceStatements(span)) |statement| {
        try self.discoverInvalidatedStatementExprs(statement, discovered);
    }
}

fn discoverInvalidatedStatementExprs(
    self: *Self,
    statement: CIR.Statement.Idx,
    discovered: *ExprInvalidationDiscovery,
) Allocator.Error!void {
    switch (self.cir.store.getStatement(statement)) {
        .s_decl => |decl| try self.discoverInvalidatedExpr(decl.expr, discovered),
        .s_var => |var_| try self.discoverInvalidatedExpr(var_.expr, discovered),
        .s_reassign => |reassign| try self.discoverInvalidatedExpr(reassign.expr, discovered),
        .s_dbg => |dbg| try self.discoverInvalidatedExpr(dbg.expr, discovered),
        .s_expr => |expr| try self.discoverInvalidatedExpr(expr.expr, discovered),
        .s_expect => |expect| try self.discoverInvalidatedExpr(expect.body, discovered),
        .s_for => |for_| {
            try self.discoverInvalidatedExpr(for_.expr, discovered);
            try self.discoverInvalidatedExpr(for_.body, discovered);
        },
        .s_while => |while_| {
            try self.discoverInvalidatedExpr(while_.cond, discovered);
            try self.discoverInvalidatedExpr(while_.body, discovered);
        },
        .s_infinite_loop => |loop| {
            try self.discoverInvalidatedExpr(loop.cond, discovered);
            try self.discoverInvalidatedExpr(loop.body, discovered);
        },
        .s_breakable_loop => |loop| {
            try self.discoverInvalidatedExpr(loop.cond, discovered);
            try self.discoverInvalidatedExpr(loop.body, discovered);
        },
        .s_return => |ret| {
            try self.discoverInvalidatedExpr(ret.expr, discovered);
            try self.discoverInvalidatedExpr(ret.lambda, discovered);
        },
        .s_var_uninitialized,
        .s_crash,
        .s_break,
        .s_import,
        .s_alias_decl,
        .s_nominal_decl,
        .s_where_alias_decl,
        .s_type_anno,
        .s_type_var_alias,
        .s_runtime_error,
        => {},
    }
}

fn discoverInvalidatedExprChildren(
    self: *Self,
    expr: CIR.Expr.Idx,
    discovered: *ExprInvalidationDiscovery,
) Allocator.Error!void {
    switch (self.cir.store.getExpr(expr)) {
        .e_str => |str| try self.discoverInvalidatedExprSpan(str.span, discovered),
        .e_list => |list| try self.discoverInvalidatedExprSpan(list.elems, discovered),
        .e_tuple => |tuple| try self.discoverInvalidatedExprSpan(tuple.elems, discovered),
        .e_match => |match| {
            try self.discoverInvalidatedExpr(match.cond, discovered);
            for (self.cir.store.sliceMatchBranches(match.branches)) |branch_idx| {
                const branch = self.cir.store.getMatchBranch(branch_idx);
                if (branch.guard) |guard| try self.discoverInvalidatedExpr(guard, discovered);
                try self.discoverInvalidatedExpr(branch.value, discovered);
            }
        },
        .e_if => |if_| {
            for (self.cir.store.sliceIfBranches(if_.branches)) |branch_idx| {
                const branch = self.cir.store.getIfBranch(branch_idx);
                try self.discoverInvalidatedExpr(branch.cond, discovered);
                try self.discoverInvalidatedExpr(branch.body, discovered);
            }
            try self.discoverInvalidatedExpr(if_.final_else, discovered);
        },
        .e_call => |call| {
            try self.discoverInvalidatedExpr(call.func, discovered);
            try self.discoverInvalidatedExprSpan(call.args, discovered);
        },
        .e_record => |record| {
            for (self.cir.store.sliceRecordFields(record.fields)) |field_idx| {
                try self.discoverInvalidatedExpr(self.cir.store.getRecordField(field_idx).value, discovered);
            }
            if (record.ext) |ext| try self.discoverInvalidatedExpr(ext, discovered);
        },
        .e_block => |block| {
            try self.discoverInvalidatedStatementSpan(block.stmts, discovered);
            try self.discoverInvalidatedExpr(block.final_expr, discovered);
        },
        .e_tag => |tag| try self.discoverInvalidatedExprSpan(tag.args, discovered),
        .e_nominal => |nominal| try self.discoverInvalidatedExpr(nominal.backing_expr, discovered),
        .e_nominal_external => |nominal| try self.discoverInvalidatedExpr(nominal.backing_expr, discovered),
        .e_closure => |closure| try self.discoverInvalidatedExpr(closure.lambda_idx, discovered),
        .e_lambda => |lambda| try self.discoverInvalidatedExpr(lambda.body, discovered),
        .e_binop => |binop| {
            try self.discoverInvalidatedExpr(binop.lhs, discovered);
            try self.discoverInvalidatedExpr(binop.rhs, discovered);
        },
        .e_unary_minus => |unary| try self.discoverInvalidatedExpr(unary.expr, discovered),
        .e_unary_not => |unary| try self.discoverInvalidatedExpr(unary.expr, discovered),
        .e_field_access => |field| try self.discoverInvalidatedExpr(field.receiver, discovered),
        .e_method_call => |call| {
            try self.discoverInvalidatedExpr(call.receiver, discovered);
            try self.discoverInvalidatedExprSpan(call.args, discovered);
        },
        .e_dispatch_call => |call| {
            try self.discoverInvalidatedExpr(call.receiver, discovered);
            try self.discoverInvalidatedExprSpan(call.args, discovered);
        },
        .e_interpolation => |interpolation| {
            try self.discoverInvalidatedExpr(interpolation.first, discovered);
            try self.discoverInvalidatedExprSpan(interpolation.parts, discovered);
        },
        .e_structural_eq => |eq| {
            try self.discoverInvalidatedExpr(eq.lhs, discovered);
            try self.discoverInvalidatedExpr(eq.rhs, discovered);
        },
        .e_structural_hash => |hash| {
            try self.discoverInvalidatedExpr(hash.value, discovered);
            try self.discoverInvalidatedExpr(hash.hasher, discovered);
        },
        .e_method_eq => |eq| {
            try self.discoverInvalidatedExpr(eq.lhs, discovered);
            try self.discoverInvalidatedExpr(eq.rhs, discovered);
        },
        .e_type_method_call => |call| try self.discoverInvalidatedExprSpan(call.args, discovered),
        .e_type_dispatch_call => |call| try self.discoverInvalidatedExprSpan(call.args, discovered),
        .e_tuple_access => |access| try self.discoverInvalidatedExpr(access.tuple, discovered),
        .e_dbg => |dbg| try self.discoverInvalidatedExpr(dbg.expr, discovered),
        .e_expect_err => |expect_err| try self.discoverInvalidatedExpr(expect_err.expr, discovered),
        .e_expect => |expect| try self.discoverInvalidatedExpr(expect.body, discovered),
        .e_return => |ret| {
            try self.discoverInvalidatedExpr(ret.expr, discovered);
            try self.discoverInvalidatedExpr(ret.lambda, discovered);
        },
        .e_for => |for_| {
            try self.discoverInvalidatedExpr(for_.expr, discovered);
            try self.discoverInvalidatedExpr(for_.body, discovered);
        },
        .e_run_low_level => |run| try self.discoverInvalidatedExprSpan(run.args, discovered),
        .e_num,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_num_from_numeral,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_str_segment,
        .e_bytes_literal,
        .e_lookup_local,
        .e_lookup_external,
        .e_lookup_associated_local,
        .e_lookup_associated,
        .e_lookup_associated_resolved,
        .e_lookup_required,
        .e_empty_list,
        .e_empty_record,
        .e_zero_argument_tag,
        .e_runtime_error,
        .e_crash,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_break,
        .e_hosted_lambda,
        => {},
    }
}

fn debugAssertHoistSelectionConsistent(self: *const Self) void {
    if (builtin.mode != .Debug) return;

    var expr_iter = self.hoist_selected_exprs.iterator();
    while (expr_iter.next()) |entry| {
        const root_index = entry.value_ptr.*;
        std.debug.assert(root_index < self.selected_hoisted_roots.items.len);
        std.debug.assert(self.selected_hoisted_roots.items[root_index].expr == entry.key_ptr.*);
    }

    var binding_iter = self.hoist_selected_bindings.iterator();
    while (binding_iter.next()) |entry| {
        const root_index = entry.value_ptr.*;
        std.debug.assert(root_index < self.selected_hoisted_roots.items.len);
        const selected = self.selected_hoisted_roots.items[root_index];
        std.debug.assert(selected.pattern != null);
        std.debug.assert(selected.pattern.? == entry.key_ptr.*);
    }

    var validation_iter = self.hoist_selected_pattern_validations.iterator();
    while (validation_iter.next()) |entry| {
        const root_index = entry.value_ptr.*;
        std.debug.assert(root_index < self.selected_hoisted_roots.items.len);
        const selected = self.selected_hoisted_roots.items[root_index];
        const validation = switch (selected.body) {
            .pattern_validation => |value| value,
            .expr, .pattern_extraction => unreachable,
        };
        std.debug.assert(validation.scrutinee_pattern == entry.key_ptr.*);
    }

    for (self.selected_hoisted_roots.items, 0..) |root, i| {
        const root_index: u32 = @intCast(i);
        switch (root.body) {
            .expr => std.debug.assert(self.hoist_selected_exprs.get(root.expr) == root_index),
            .pattern_extraction => {},
            .pattern_validation => |validation| std.debug.assert(self.hoist_selected_pattern_validations.get(validation.scrutinee_pattern) == root_index),
        }
        if (root.pattern) |pattern| {
            std.debug.assert(self.hoist_selected_bindings.get(pattern) == root_index);
        } else {
            switch (root.body) {
                .expr => {},
                .pattern_extraction => std.debug.panic("check invariant violated: pattern extraction hoisted root had no binding pattern", .{}),
                .pattern_validation => {},
            }
        }
    }
}

const HoistSelectionTestState = struct {
    checker: Self,
    allocator: Allocator,

    fn init(allocator: Allocator) HoistSelectionTestState {
        var checker: Self = undefined;
        checker.gpa = allocator;
        checker.hoist_frames = .empty;
        checker.hoist_expr_candidates = .empty;
        checker.hoist_deferred_roots = .empty;
        checker.hoist_binding_candidates = .{};
        checker.hoist_binding_scope_patterns = .empty;
        checker.hoist_known_values = .{};
        checker.hoist_known_value_scope_patterns = .empty;
        checker.hoist_contextual_bindings = .{};
        checker.hoist_contextual_binding_scope_patterns = .empty;
        checker.hoist_selected_bindings = .{};
        checker.hoist_selected_exprs = .{};
        checker.hoist_selected_pattern_validations = .{};
        checker.hoist_invalidated_exprs = .{};
        checker.selected_hoisted_roots = .empty;
        checker.last_hoist_result = null;
        return .{
            .checker = checker,
            .allocator = allocator,
        };
    }

    fn deinit(self: *HoistSelectionTestState) void {
        self.checker.hoist_frames.deinit(self.allocator);
        self.checker.hoist_expr_candidates.deinit(self.allocator);
        self.checker.hoist_deferred_roots.deinit(self.allocator);
        self.checker.hoist_binding_candidates.deinit(self.allocator);
        self.checker.hoist_binding_scope_patterns.deinit(self.allocator);
        var known_value_iter = self.checker.hoist_known_values.iterator();
        while (known_value_iter.next()) |entry| {
            self.checker.deinitHoistKnownValue(entry.value_ptr.*);
        }
        self.checker.hoist_known_values.deinit(self.allocator);
        self.checker.hoist_known_value_scope_patterns.deinit(self.allocator);
        self.checker.hoist_contextual_bindings.deinit(self.allocator);
        self.checker.hoist_contextual_binding_scope_patterns.deinit(self.allocator);
        self.checker.hoist_selected_bindings.deinit(self.allocator);
        self.checker.hoist_selected_exprs.deinit(self.allocator);
        self.checker.hoist_selected_pattern_validations.deinit(self.allocator);
        self.checker.hoist_invalidated_exprs.deinit(self.allocator);
        for (self.checker.selected_hoisted_roots.items) |*root| {
            hoist_roots.deinitSelectedRoot(self.allocator, root);
        }
        self.checker.selected_hoisted_roots.deinit(self.allocator);
    }

    fn borrowCheckedContext(self: *HoistSelectionTestState, checked: *Self) error{ExpectedHoistSelectionTestExpr}!CIR.Expr.Idx {
        self.checker.cir = checked.cir;
        self.checker.types = checked.types;
        return firstHoistSelectionTestExpr(checked);
    }
};

fn firstHoistSelectionTestExpr(checker: *Self) error{ExpectedHoistSelectionTestExpr}!CIR.Expr.Idx {
    var raw_node_idx: u32 = 0;
    while (raw_node_idx < checker.cir.store.nodes.len()) : (raw_node_idx += 1) {
        const node_idx: CIR.Node.Idx = @enumFromInt(raw_node_idx);
        if (!isExprNodeTag(checker.cir.store.nodes.get(node_idx).tag)) continue;

        const expr_idx: CIR.Expr.Idx = @enumFromInt(raw_node_idx);
        switch (checker.cir.store.getExpr(expr_idx)) {
            .e_num,
            .e_num_from_numeral,
            .e_typed_int,
            .e_typed_num_from_numeral,
            => return expr_idx,
            .e_lookup_local,
            .e_lookup_external,
            .e_lookup_associated_local,
            .e_lookup_associated,
            .e_lookup_associated_resolved,
            .e_lookup_required,
            .e_str_segment,
            .e_bytes_literal,
            .e_frac_f32,
            .e_frac_f64,
            .e_dec,
            .e_dec_small,
            .e_typed_frac,
            .e_empty_list,
            .e_empty_record,
            .e_zero_argument_tag,
            .e_str,
            .e_list,
            .e_tuple,
            .e_block,
            .e_match,
            .e_if,
            .e_call,
            .e_method_call,
            .e_dispatch_call,
            .e_record,
            .e_tag,
            .e_nominal,
            .e_nominal_external,
            .e_binop,
            .e_unary_minus,
            .e_unary_not,
            .e_field_access,
            .e_interpolation,
            .e_structural_eq,
            .e_structural_hash,
            .e_method_eq,
            .e_type_method_call,
            .e_type_dispatch_call,
            .e_tuple_access,
            .e_dbg,
            .e_expect_err,
            .e_expect,
            .e_for,
            .e_return,
            .e_break,
            .e_run_low_level,
            .e_runtime_error,
            .e_ellipsis,
            .e_anno_only,
            .e_derived_method,
            .e_crash,
            .e_closure,
            .e_lambda,
            .e_hosted_lambda,
            => {},
        }
    }
    return error.ExpectedHoistSelectionTestExpr;
}

test "hoist frame finish leaves child candidates unchanged when selection allocation fails" {
    const parent_expr: CIR.Expr.Idx = @enumFromInt(1);
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("HoistSelection", "1.I64");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    var state = HoistSelectionTestState.init(std.testing.allocator);
    defer state.deinit();
    const child_expr = try state.borrowCheckedContext(&test_env.checker);

    var guard = try state.checker.beginHoistFrame(parent_expr, false, .eligible);
    defer guard.deinit();
    try state.checker.hoist_expr_candidates.append(std.testing.allocator, child_expr);
    state.checker.markCurrentHoistRuntimeDependency();

    var failing_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = 0,
    });
    state.checker.gpa = failing_allocator.allocator();

    try std.testing.expectError(error.OutOfMemory, guard.finish(false));
    try std.testing.expectEqual(@as(usize, 1), state.checker.hoist_frames.items.len);
    try std.testing.expectEqual(@as(usize, 1), state.checker.hoist_expr_candidates.items.len);
    try std.testing.expectEqual(child_expr, state.checker.hoist_expr_candidates.items[0]);
    try std.testing.expectEqual(@as(usize, 0), state.checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_selected_exprs.count());

    state.checker.gpa = std.testing.allocator;
    try guard.finish(false);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_frames.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_expr_candidates.items.len);
    try std.testing.expectEqual(@as(usize, 1), state.checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(child_expr, state.checker.selected_hoisted_roots.items[0].expr);
    try std.testing.expectEqual(@as(?CIR.Pattern.Idx, null), state.checker.selected_hoisted_roots.items[0].pattern);
}

test "fresh expected context suppresses hoist selection by default" {
    try std.testing.expectEqual(HoistPosition.suppressed, Expected.none().hoist_position);

    const parent_expr: CIR.Expr.Idx = @enumFromInt(1);
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("HoistSelection", "1.I64");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    var state = HoistSelectionTestState.init(std.testing.allocator);
    defer state.deinit();
    const child_expr = try state.borrowCheckedContext(&test_env.checker);

    var guard = try state.checker.beginHoistFrame(parent_expr, false, Expected.none().hoist_position);
    defer guard.deinit();
    try state.checker.hoist_expr_candidates.append(std.testing.allocator, child_expr);
    state.checker.markCurrentHoistRuntimeDependency();

    try guard.finish(false);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_frames.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_expr_candidates.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_selected_exprs.count());
}

test "hoist frame finish is atomic when child flush precedes deferred dependency failure" {
    const parent_expr: CIR.Expr.Idx = @enumFromInt(1);
    const dependency_pattern: CIR.Pattern.Idx = @enumFromInt(2);
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("HoistSelection", "1.I64");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    var saw_late_oom = false;
    for (0..8) |fail_index| {
        var state = HoistSelectionTestState.init(std.testing.allocator);
        defer state.deinit();
        const child_expr = try state.borrowCheckedContext(&test_env.checker);

        state.checker.checking_binding_rhs_pattern = null;
        var guard = try state.checker.beginHoistFrame(parent_expr, true, .eligible);
        defer guard.deinit();
        try state.checker.hoist_expr_candidates.append(std.testing.allocator, child_expr);
        try state.checker.hoist_deferred_roots.append(std.testing.allocator, .{ .binding = dependency_pattern });
        try state.checker.recordHoistKnownValue(dependency_pattern, .{ .binding_rhs = child_expr });
        state.checker.markCurrentHoistRuntimeDependency();

        var failing_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = fail_index,
        });
        state.checker.gpa = failing_allocator.allocator();

        guard.finish(false) catch |err| switch (err) {
            error.OutOfMemory => {
                if (fail_index > 0) saw_late_oom = true;
                try std.testing.expectEqual(@as(usize, 1), state.checker.hoist_frames.items.len);
                try std.testing.expectEqual(@as(usize, 1), state.checker.hoist_expr_candidates.items.len);
                try std.testing.expectEqual(child_expr, state.checker.hoist_expr_candidates.items[0]);
                try std.testing.expectEqual(@as(usize, 1), state.checker.hoist_deferred_roots.items.len);
                switch (state.checker.hoist_deferred_roots.items[0]) {
                    .binding => |pattern| try std.testing.expectEqual(dependency_pattern, pattern),
                    .pattern_validation => return error.ExpectedDeferredBindingRoot,
                }
                try std.testing.expectEqual(@as(usize, 0), state.checker.selected_hoisted_roots.items.len);
                try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_selected_exprs.count());
                try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_selected_bindings.count());
                const known = state.checker.hoist_known_values.get(dependency_pattern) orelse return error.ExpectedKnownHoistDependency;
                switch (known) {
                    .binding_rhs => |expr| try std.testing.expectEqual(child_expr, expr),
                    .pattern_extraction,
                    .selected_root,
                    .unavailable_runtime,
                    => return error.KnownHoistDependencyMutatedAfterFailedFinish,
                }
                continue;
            },
        };

        try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_frames.items.len);
        try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_expr_candidates.items.len);
        try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_deferred_roots.items.len);
        try std.testing.expectEqual(@as(usize, 1), state.checker.selected_hoisted_roots.items.len);
        try std.testing.expectEqual(child_expr, state.checker.selected_hoisted_roots.items[0].expr);
        try std.testing.expectEqual(dependency_pattern, state.checker.selected_hoisted_roots.items[0].pattern.?);
    }
    try std.testing.expect(saw_late_oom);
}

test "hoisted binding root selection is atomic when binding map allocation fails" {
    const pattern: CIR.Pattern.Idx = @enumFromInt(2);
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("HoistSelection", "1.I64");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    var state = HoistSelectionTestState.init(std.testing.allocator);
    defer state.deinit();
    const expr = try state.borrowCheckedContext(&test_env.checker);

    try state.checker.selected_hoisted_roots.ensureUnusedCapacity(std.testing.allocator, 1);
    try state.checker.hoist_selected_exprs.ensureUnusedCapacity(std.testing.allocator, 1);

    var failing_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = 0,
    });
    state.checker.gpa = failing_allocator.allocator();

    try std.testing.expectError(error.OutOfMemory, state.checker.ensureHoistedExprRoot(expr, pattern));
    try std.testing.expectEqual(@as(usize, 0), state.checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_selected_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_selected_bindings.count());

    state.checker.gpa = std.testing.allocator;
    _ = try state.checker.ensureHoistedExprRoot(expr, pattern);
    try std.testing.expectEqual(@as(usize, 1), state.checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(expr, state.checker.selected_hoisted_roots.items[0].expr);
    try std.testing.expectEqual(pattern, state.checker.selected_hoisted_roots.items[0].pattern.?);
    try std.testing.expectEqual(@as(?u32, 0), state.checker.hoist_selected_exprs.get(expr));
    try std.testing.expectEqual(@as(?u32, 0), state.checker.hoist_selected_bindings.get(pattern));
}

test "hoisted pattern extraction root selection is atomic when binding map allocation fails" {
    const scrutinee_pattern: CIR.Pattern.Idx = @enumFromInt(2);
    const result_pattern: CIR.Pattern.Idx = @enumFromInt(3);
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("HoistSelection", "1.I64");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    var state = HoistSelectionTestState.init(std.testing.allocator);
    defer state.deinit();
    const expr = try state.borrowCheckedContext(&test_env.checker);

    const extraction: HoistPatternExtraction = .{
        .base_expr = expr,
        .scrutinee_pattern = scrutinee_pattern,
        .result_pattern = result_pattern,
    };

    try state.checker.selected_hoisted_roots.ensureUnusedCapacity(std.testing.allocator, 1);

    var failing_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = 0,
    });
    state.checker.gpa = failing_allocator.allocator();

    try std.testing.expectError(error.OutOfMemory, state.checker.ensureHoistedPatternExtractionRoot(result_pattern, extraction));
    try std.testing.expectEqual(@as(usize, 0), state.checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_selected_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_selected_bindings.count());

    state.checker.gpa = std.testing.allocator;
    _ = try state.checker.ensureHoistedPatternExtractionRoot(result_pattern, extraction);
    try std.testing.expectEqual(@as(usize, 1), state.checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(expr, state.checker.selected_hoisted_roots.items[0].expr);
    try std.testing.expectEqual(result_pattern, state.checker.selected_hoisted_roots.items[0].pattern.?);
    try std.testing.expectEqual(@as(?u32, null), state.checker.hoist_selected_exprs.get(expr));
    try std.testing.expectEqual(@as(?u32, 0), state.checker.hoist_selected_bindings.get(result_pattern));
    const selected_extraction = switch (state.checker.selected_hoisted_roots.items[0].body) {
        .pattern_extraction => |selected| selected,
        .expr, .pattern_validation => return error.ExpectedPatternExtractionRoot,
    };
    try std.testing.expectEqual(extraction.base_expr, selected_extraction.base_expr);
    try std.testing.expectEqual(extraction.scrutinee_pattern, selected_extraction.scrutinee_pattern);
    try std.testing.expectEqual(extraction.result_pattern, selected_extraction.result_pattern);
}

test "hoist lexical scope removes branch-local candidates and known values" {
    const expr: CIR.Expr.Idx = @enumFromInt(1);
    const pattern: CIR.Pattern.Idx = @enumFromInt(2);

    var state = HoistSelectionTestState.init(std.testing.allocator);
    defer state.deinit();

    const scope = state.checker.beginHoistLexicalScope();
    try state.checker.hoist_binding_candidates.put(std.testing.allocator, pattern, expr);
    try state.checker.hoist_binding_scope_patterns.append(std.testing.allocator, pattern);
    try state.checker.recordHoistKnownValue(pattern, .{ .binding_rhs = expr });

    try std.testing.expect(state.checker.hoist_binding_candidates.contains(pattern));
    try std.testing.expect(state.checker.hoist_known_values.contains(pattern));

    state.checker.endHoistLexicalScope(scope);

    try std.testing.expect(!state.checker.hoist_binding_candidates.contains(pattern));
    try std.testing.expect(!state.checker.hoist_known_values.contains(pattern));
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_binding_scope_patterns.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.checker.hoist_known_value_scope_patterns.items.len);
}

