fn patternIsTopLevel(self: *Self, pattern: CIR.Pattern.Idx) bool {
    return self.patternIsTopLevelDef(pattern);
}

fn exprCanBeHoistedRoot(self: *Self, expr: CIR.Expr.Idx) bool {
    if (self.hoistExprInvalidated(expr)) return false;
    if (self.varIsFunctionType(ModuleEnv.varFrom(expr))) return false;
    return switch (self.cir.store.getExpr(expr)) {
        .e_lookup_local => false,
        .e_lookup_external,
        .e_lookup_associated_local,
        .e_lookup_associated,
        .e_lookup_associated_resolved,
        .e_lookup_required,
        .e_str_segment,
        .e_bytes_literal,
        .e_num,
        .e_num_from_numeral,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_empty_list,
        .e_empty_record,
        .e_zero_argument_tag,
        .e_runtime_error,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_crash,
        .e_closure,
        .e_lambda,
        .e_hosted_lambda,
        => false,
        .e_str => |str| self.stringHasInterpolation(str.span),
        .e_method_call => |call| !self.methodCallPreservesIteratorSourceInput(expr, call),
        .e_dispatch_call => |call| !self.methodCallPreservesIteratorSourceInput(expr, call),
        .e_list,
        .e_tuple,
        .e_block,
        .e_match,
        .e_if,
        .e_call,
        .e_record,
        .e_tag,
        .e_nominal,
        .e_nominal_external,
        .e_binop,
        .e_unary_minus,
        .e_unary_not,
        .e_field_access,
        .e_interpolation,
        .e_structural_eq,
        .e_structural_hash,
        .e_method_eq,
        .e_type_method_call,
        .e_type_dispatch_call,
        .e_tuple_access,
        .e_dbg,
        .e_expect_err,
        .e_expect,
        .e_for,
        .e_return,
        .e_break,
        .e_run_low_level,
        => true,
    };
}

/// True when this expression can replace already-bubbled child candidates with
/// one larger stored data root. This is intentionally stricter than semantic
/// eligibility: function/lambda/closure and observable expression frames may
/// contain closed child work, but they cannot cover that work as data roots.
fn exprCanCoverHoistedChildren(self: *Self, expr: CIR.Expr.Idx) bool {
    if (self.hoistExprInvalidated(expr)) return false;
    if (self.varIsFunctionType(ModuleEnv.varFrom(expr))) return false;
    return switch (self.cir.store.getExpr(expr)) {
        .e_lookup_local,
        .e_lookup_external,
        .e_lookup_associated_local,
        .e_lookup_associated,
        .e_lookup_associated_resolved,
        .e_lookup_required,
        .e_str_segment,
        .e_bytes_literal,
        .e_num,
        .e_num_from_numeral,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_empty_list,
        .e_empty_record,
        .e_zero_argument_tag,
        .e_runtime_error,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_crash,
        .e_closure,
        .e_lambda,
        .e_hosted_lambda,
        .e_dbg,
        .e_expect_err,
        .e_expect,
        .e_for,
        .e_return,
        .e_break,
        .e_run_low_level,
        => false,
        .e_str => |str| self.stringHasInterpolation(str.span),
        .e_method_call => |call| !self.methodCallPreservesIteratorSourceInput(expr, call),
        .e_dispatch_call => |call| !self.methodCallPreservesIteratorSourceInput(expr, call),
        .e_list,
        .e_tuple,
        .e_block,
        .e_match,
        .e_if,
        .e_call,
        .e_record,
        .e_tag,
        .e_nominal,
        .e_nominal_external,
        .e_binop,
        .e_unary_minus,
        .e_unary_not,
        .e_field_access,
        .e_interpolation,
        .e_structural_eq,
        .e_structural_hash,
        .e_method_eq,
        .e_type_method_call,
        .e_type_dispatch_call,
        .e_tuple_access,
        => true,
    };
}

fn exprCanBeHoistedBindingRoot(self: *Self, expr: CIR.Expr.Idx) bool {
    if (self.hoistExprInvalidated(expr)) return false;
    if (self.varIsFunctionType(ModuleEnv.varFrom(expr))) return false;
    return switch (self.cir.store.getExpr(expr)) {
        .e_lookup_local => true,
        .e_call,
        .e_type_method_call,
        .e_type_dispatch_call,
        => true,
        .e_method_call => |call| !self.methodCallPreservesIteratorSourceInput(expr, call),
        .e_dispatch_call => |call| !self.methodCallPreservesIteratorSourceInput(expr, call),
        .e_for,
        .e_run_low_level,
        .e_lookup_required,
        .e_runtime_error,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_crash,
        .e_closure,
        .e_lambda,
        .e_hosted_lambda,
        .e_dbg,
        .e_expect_err,
        .e_expect,
        .e_return,
        .e_break,
        => false,
        .e_lookup_external,
        .e_lookup_associated_local,
        .e_lookup_associated,
        .e_lookup_associated_resolved,
        .e_str_segment,
        .e_bytes_literal,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_typed_int,
        .e_typed_frac,
        .e_empty_list,
        .e_empty_record,
        .e_zero_argument_tag,
        .e_list,
        .e_tuple,
        .e_block,
        .e_match,
        .e_if,
        .e_record,
        .e_tag,
        .e_nominal,
        .e_nominal_external,
        .e_binop,
        .e_unary_minus,
        .e_unary_not,
        .e_field_access,
        .e_interpolation,
        .e_structural_eq,
        .e_structural_hash,
        .e_method_eq,
        .e_tuple_access,
        => true,
        .e_num,
        .e_num_from_numeral,
        .e_typed_num_from_numeral,
        .e_str,
        => !self.exprHasDedicatedLiteralConversionRoot(expr),
    };
}

fn methodCallPreservesIteratorSourceInput(self: *Self, expr: CIR.Expr.Idx, call: anytype) bool {
    if (self.hoist_iterator_source_memo) |memo| {
        if (memo.expr == expr) return memo.preserves;
    }
    const preserves = self.computeMethodCallPreservesIteratorSourceInput(expr, call);
    self.hoist_iterator_source_memo = .{ .expr = expr, .preserves = preserves };
    return preserves;
}

fn computeMethodCallPreservesIteratorSourceInput(self: *Self, expr: CIR.Expr.Idx, call: anytype) bool {
    // Every def that can answer true is reachable only through the registry's
    // hoist-preserving method names: its producer table, the delegating
    // Dict/Set wrappers, and the FieldNames intrinsic all bind those names,
    // and a user-defined conversion is recognized by result type under the
    // same names (`static_dispatch_registry.zig` pins this by comptime
    // check). Anything else skips receiver resolution and the cross-module
    // binding lookup.
    if (!methodNameIsHoistPreservingCandidate(self.cir.getIdentText(call.method_name))) return false;
    var owner_var = ModuleEnv.varFrom(call.receiver);
    const nominal = while (true) {
        const resolved = self.types.resolveVar(owner_var);
        switch (resolved.desc.content) {
            .alias => |alias| owner_var = self.types.getAliasBackingVar(alias),
            .flex, .rigid, .field_presence, .structure, .err => break resolved.desc.content.unwrapNominalType() orelse return false,
        }
    };
    const owner_env = self.getNominalOriginEnv(nominal);
    const method = self.lookupStaticDispatchMethodBinding(
        owner_env,
        nominal.sourceDeclOptional(),
        self.cir,
        call.method_name,
    ) orelse return false;
    if (method.env.module_role == .builtin) {
        return static_dispatch.procedurePreservesHoistableSourceInputForEnvDef(
            method.env,
            method.binding.def_idx,
        );
    }
    // A user-defined conversion has no registry entry, so its result type
    // decides: an `Iter` holds its step closure by value, and selecting the
    // conversion itself as a static-data root would bake that closure instead
    // of the receiver collection it reads.
    return self.varIsIteratorNominal(ModuleEnv.varFrom(expr));
}

fn methodNameIsHoistPreservingCandidate(method_text: []const u8) bool {
    for (static_dispatch.hoist_preserving_method_names) |candidate| {
        if (Ident.textEql(method_text, candidate)) return true;
    }
    return false;
}

/// Whether this type is the builtin `Iter` nominal, looking through
/// transparent aliases.
fn varIsIteratorNominal(self: *Self, var_: Var) bool {
    const iter_source_decl = self.iteratorNominalSourceDecl() orelse return false;
    var walk = var_;
    while (true) {
        const resolved = self.types.resolveVar(walk);
        switch (resolved.desc.content) {
            .alias => |alias| walk = self.types.getAliasBackingVar(alias),
            .flex, .rigid, .field_presence, .structure, .err => {
                const nominal = resolved.desc.content.unwrapNominalType() orelse return false;
                const source_decl = nominal.sourceDeclOptional() orelse return false;
                return source_decl == iter_source_decl;
            },
        }
    }
}

fn iteratorNominalSourceDecl(self: *const Self) ?u32 {
    if (self.builtin_ctx.builtin_indices) |indices| return @intFromEnum(indices.iter_type);
    if (self.cir.module_role != .builtin) return null;
    const iter_stmt_idx = self.findLocalTypeDeclByName(self.cir.idents.builtin_iter) orelse return null;
    return @intFromEnum(iter_stmt_idx);
}

fn stringHasInterpolation(self: *Self, span: CIR.Expr.Span) bool {
    for (self.cir.store.sliceExpr(span)) |segment| {
        if (self.cir.store.getExpr(segment) != .e_str_segment) return true;
    }
    return false;
}
/// In debug builds, verifies that region and type arrays have matching lengths.
pub inline fn debugAssertArraysInSync(self: *const Self) void {
    if (builtin.mode == .Debug) {
        const region_nodes = self.regions.len();
        const type_nodes = self.types.len();
        if (!(region_nodes == type_nodes)) {
            std.debug.panic(
                "Arrays out of sync:\n type_nodes={}\n  region_nodes={}\n ",
                .{ type_nodes, region_nodes },
            );
        }
    }
}

/// Fills the type store with fresh variables up to the number of regions
inline fn ensureTypeStoreIsFilled(self: *Self) Allocator.Error!void {
    const region_nodes: usize = @intCast(self.regions.len());
    const type_nodes: usize = @intCast(self.types.len());
    if (type_nodes >= region_nodes) return;
    try self.types.ensureTotalCapacity(region_nodes);
    for (type_nodes..region_nodes) |_| {
        _ = self.types.appendFromContentAssumeCapacity(.{ .flex = Flex.init() }, Rank.outermost);
    }
}

// import caches //

/// Key for the import cache: module index + expression index in that module
const ImportCacheKey = struct {
    resolved_module_idx: u32,
    node_idx: CIR.Node.Idx,
};

/// Cache for imported types to avoid repeated copying
///
/// When we import a type from another module, we need to copy it into our module's
/// type store because type variables are module-specific. However, since we use
/// "preserve" mode unification with imported types (meaning the imported type is
/// read-only and never modified), we can safely cache these copies and reuse them;
/// they will never be mutated during unification.
///
/// Benefits:
/// - Reduces memory usage by avoiding duplicate copies of the same imported type
/// - Improves performance by avoiding redundant copying operations
/// - Particularly beneficial for commonly imported values/functions
///
/// Example: If a module imports `List.map` and uses it 10 times, without caching
/// we would create 10 separate copies of the `List.map` type. With caching, we
/// create just one copy and reuse it.
const ImportedTypeCopy = struct {
    var_: Var,
    /// Every external cache entry owns one eager immutable provider support
    /// step through its canonical minimum-token seed row.
    copy_step: u32,
    seed_index: u32,
};

const ImportCache = std.HashMapUnmanaged(ImportCacheKey, ImportedTypeCopy, struct {
    pub fn hash(_: @This(), key: ImportCacheKey) u64 {
        var hasher = std.hash.Wyhash.init(0);
        hasher.update(std.mem.asBytes(&key.resolved_module_idx));
        hasher.update(std.mem.asBytes(&key.node_idx));
        return hasher.final();
    }

    pub fn eql(_: @This(), a: ImportCacheKey, b: ImportCacheKey) bool {
        return a.resolved_module_idx == b.resolved_module_idx and a.node_idx == b.node_idx;
    }
}, 80);

const BindingSchemeMutation = union(enum) {
    node: u32,
    synthetic: Var,
};

const OpenNumeralLiteral = struct {
    var_: Var,
    constraint: StaticDispatchConstraint,
    source_node: ?CIR.Node.Idx,
};

const PendingTupleAccess = struct {
    tuple_var: Var,
    result_var: Var,
    elem_index: u32,
    region: Region,
};

// env //

/// Solver env
const Env = struct {
    /// Pool of variables created during solving, use by let-polymorphism
    var_pool: VarPool,
    /// Deferred static dispatch constraints - accumulated during type checking,
    /// then solved for at the end
    deferred_static_dispatch_constraints: DeferredConstraintCheck.SafeList,

    fn init(
        gpa: std.mem.Allocator,
        at: Rank,
    ) std.mem.Allocator.Error!Env {
        var pool = try VarPool.init(gpa);
        pool.current_rank = at;
        try pool.ensureRanksThrough(at);

        return .{
            .var_pool = pool,
            .deferred_static_dispatch_constraints = try DeferredConstraintCheck.SafeList.initCapacity(gpa, 32),
        };
    }

    fn deinit(self: *Env, gpa: std.mem.Allocator) void {
        self.var_pool.deinit();
        self.deferred_static_dispatch_constraints.deinit(gpa);
    }

    /// Resets internal state of env and set rank to generalized
    fn reset(self: *Env, to: Rank) Allocator.Error!void {
        self.var_pool.current_rank = to;
        self.var_pool.clearRetainingCapacity();
        try self.var_pool.ensureRanksThrough(to);
        self.deferred_static_dispatch_constraints.items.clearRetainingCapacity();
    }

    fn rank(self: *const Env) Rank {
        return self.var_pool.current_rank;
    }
};

// unify //

/// Build the borrowed dependency bundle the unifier needs. Cheap (9 pointers);
/// constructed per call and inlined.
fn unifyEnv(self: *Self) unifier.Env {
    return .{
        // problems is owned by self.gpa.
        .problems_gpa = self.gpa,
        .ident_store = self.cir.getIdentStoreConst(),
        .self_module_identity = self.cir.selfModuleIdentity(),
        .types = self.types,
        .problems = &self.problems,
        .snapshots = &self.snapshots,
        .type_writer = &self.type_writer,
        .unify_scratch = &self.unify_scratch,
        .occurs_scratch = &self.occurs_scratch,
        .construction_probe = .{ .ctx = self, .isRecordConstruction = probeRecordConstruction },
    };
}

fn probeRecordConstruction(ctx: *const anyopaque, var_: Var) bool {
    const self: *const Self = @ptrCast(@alignCast(ctx));
    return self.sourceRecordConstructionForVar(var_) != null;
}

fn sourceRecordConstructionForVar(self: *const Self, var_: Var) ?CIR.Expr.Idx {
    const raw = @intFromEnum(var_);
    if (raw < self.cir.store.nodes.len()) {
        const node = self.cir.store.nodes.get(@enumFromInt(raw));
        if (node.tag == .expr_record or node.tag == .expr_empty_record) {
            return @enumFromInt(raw);
        }
    }
    return null;
}

/// Persist the exact source-occurrence movement maps emitted by the unifier
/// before its scratch is reset by another relation. Both durable pools are
/// reserved before either grows, so an allocation failure cannot publish an
/// owner row without its complete offset map (or vice versa).
fn recordUnifierWhereMarkerConstraintMoves(self: *Self) Allocator.Error!void {
    const scratch_moves = self.unify_scratch.where_marker_constraint_moves.items;
    const scratch_offsets = self.unify_scratch.where_marker_constraint_move_offsets.items;
    if (scratch_moves.len == 0) {
        if (scratch_offsets.len != 0) {
            @panic("unifier published marker-movement offsets without owner rows");
        }
        return;
    }

    var expected_offset_end: usize = 0;
    for (scratch_moves) |move| {
        const start: usize = move.offsets_start;
        const len: usize = move.offsets_len;
        if (move.offsets_len == 0 or
            start != expected_offset_end or
            start > scratch_offsets.len or
            len > scratch_offsets.len - start)
        {
            @panic("unifier published a malformed marker-movement partition");
        }
        expected_offset_end += len;
    }
    if (expected_offset_end != scratch_offsets.len) {
        @panic("unifier published orphan marker-movement offsets");
    }

    try self.cir.where_marker_constraint_moves.items.ensureUnusedCapacity(
        self.cir.gpa,
        scratch_moves.len,
    );
    try self.cir.where_marker_constraint_move_offsets.items.ensureUnusedCapacity(
        self.cir.gpa,
        scratch_offsets.len,
    );
    const offset_base: u32 = @intCast(self.cir.where_marker_constraint_move_offsets.items.items.len);
    self.cir.where_marker_constraint_move_offsets.items.appendSliceAssumeCapacity(scratch_offsets);
    for (scratch_moves) |move| {
        self.cir.where_marker_constraint_moves.items.appendAssumeCapacity(.{
            .source_constraint_index = move.source_constraint_index,
            .destination_constraint_index = move.destination_constraint_index,
            .offsets_start = offset_base + move.offsets_start,
            .offsets_len = move.offsets_len,
        });
    }
}

/// Persist the unifier's marker-independent tagged evidence transitions before
/// its scratch is reset. The unifier has already attached the complete
/// canonical handle set to each destination constraint.
fn recordUnifierConstraintEvidenceMoves(self: *Self) Allocator.Error!void {
    const scratch_moves = self.unify_scratch.constraint_evidence_moves.items;
    try self.cir.constraint_evidence_moves.items.ensureUnusedCapacity(
        self.cir.gpa,
        scratch_moves.len,
    );
    for (scratch_moves) |move| {
        if (move.handle.decodedKind() == null or
            move.source_constraint_index >= self.types.static_dispatch_constraints.items.items.len or
            move.destination_constraint_index >= self.types.static_dispatch_constraints.items.items.len)
        {
            std.debug.panic("unifier constraint-evidence movement escaped its producer pools", .{});
        }
        const source = self.types.static_dispatch_constraints.items.items[move.source_constraint_index];
        const destination = self.types.static_dispatch_constraints.items.items[move.destination_constraint_index];
        var source_has = false;
        for (self.types.sliceConstraintEvidenceHandles(source.constraint_evidence)) |handle| {
            source_has = source_has or types_mod.ConstraintEvidenceHandle.eql(handle, move.handle);
        }
        var destination_has = false;
        for (self.types.sliceConstraintEvidenceHandles(destination.constraint_evidence)) |handle| {
            destination_has = destination_has or types_mod.ConstraintEvidenceHandle.eql(handle, move.handle);
        }
        if (!source_has or !destination_has) {
            std.debug.panic("unifier constraint-evidence movement did not preserve its exact handle", .{});
        }
        self.cir.constraint_evidence_moves.items.appendAssumeCapacity(.{
            .handle = move.handle,
            .source_constraint_index = move.source_constraint_index,
            .destination_constraint_index = move.destination_constraint_index,
        });
    }
}

fn recordAbsorbedDefaults(self: *Self, construction_var: ?Var, a: Var, b: Var) std.mem.Allocator.Error!void {
    for (self.unify_scratch.absorbed_record_defaults.items.items) |absorbed| {
        var mb_expr = self.sourceRecordConstructionForVar(absorbed.record_var);
        // The pair enclosing the absorption names the construction directly,
        // including when it is nested inside the operands (a record literal in
        // a tag payload, say), which the outer operand vars cannot reach.
        if (mb_expr == null) {
            if (absorbed.enclosing_records) |pair| {
                mb_expr = self.sourceRecordConstructionForVar(pair[1]) orelse
                    self.sourceRecordConstructionForVar(pair[0]);
            }
        }
        if (mb_expr == null) {
            if (construction_var) |owner| mb_expr = self.sourceRecordConstructionForVar(owner);
        }
        if (mb_expr == null) mb_expr = self.sourceRecordConstructionForVar(b);
        if (mb_expr == null) mb_expr = self.sourceRecordConstructionForVar(a);
        const expr = mb_expr orelse
            std.debug.panic("type checker invariant violated: defaulted-field width absorption lost its source record construction", .{});

        var already_recorded = false;
        for (self.cir.record_omitted_defaults.items.items) |existing| {
            if (existing.expr == expr and existing.field_name == absorbed.name and
                existing.origin_module == absorbed.default.origin_module and
                existing.default_expr_node == absorbed.default.expr_node)
            {
                already_recorded = true;
                break;
            }
        }
        if (already_recorded) continue;

        _ = try self.cir.record_omitted_defaults.append(self.cir.gpa, .{
            .expr = expr,
            .field_name = absorbed.name,
            .origin_module = absorbed.default.origin_module,
            .default_expr_node = absorbed.default.expr_node,
        });
    }
}

/// The single core: run unification, then assign ranks/regions to fresh vars,
/// copy out deferred constraints, and assert array sync.
fn runUnify(self: *Self, a: Var, b: Var, env: *Env, opts: unifier.Options) std.mem.Allocator.Error!unifier.Result {
    const trace = tracy.trace(@src());
    defer trace.end();

    const annotation_unify_event = if (self.activePredeclaredAnnoEventScope()) |scope| blk: {
        const slot = scope.unify_slot;
        scope.unify_slot = std.math.add(u32, scope.unify_slot, 1) catch
            std.debug.panic("annotation producer unify slot overflowed u32", .{});
        break :blk .{ .anchor_node = scope.anchor_node, .slot = slot };
    } else null;
    const constraints_before_unify = self.types.static_dispatch_constraints.items.items.len;

    const construction_var = opts.record_construction_var orelse if (self.instantiation_source_expr) |source|
        if (self.exprIsFreshRecordConstruction(source)) ModuleEnv.varFrom(source) else null
    else
        null;
    const unify_env = self.unifyEnv();
    // The unifier decides whether a defaulted row may be absorbed at all, so it
    // needs the same owner the absorption will later be attributed to.
    var unify_opts = opts;
    unify_opts.record_construction_var = construction_var;
    const result = try unifier.unify(&unify_env, a, b, unify_opts);
    try self.recordUnifierWhereMarkerConstraintMoves();
    try self.recordUnifierConstraintEvidenceMoves();

    if (result.isAccepted()) {
        try self.recordAbsorbedDefaults(construction_var, a, b);
    }
    // Unifier scratch is reset by the next call, so inspect every omission
    // now. A top-level mismatch is partial-commit: an earlier receiver merge
    // can remain established even when later unrelated work rejects. Keep
    // exactly those omissions whose two raw receiver operands now share a
    // committed root. The owning boundary will separately prove either an exact
    // where-use copy map or equal callable TypeDigests under its identity anchors.
    for (self.unify_scratch.generalized_dispatch_target_share_candidates.items.items) |candidate| {
        const omitted_receiver_root = self.types.resolveVar(candidate.omitted_receiver_var).var_;
        const retained_receiver_root = self.types.resolveVar(candidate.retained_receiver_var).var_;
        if (omitted_receiver_root != retained_receiver_root) {
            if (result.isEstablished()) {
                @panic("established unification left an omitted dispatch target's receiver operands unrelated");
            }
            continue;
        }

        // A monomorphic relation reaches no generalized ModuleEnv-output boundary
        // and therefore needs no durable target-share row. Recursive SCC boundary
        // work uses an explicit group token because no individual member owns
        // its shared fixpoint.
        const owner: PendingGeneralizedTargetShareCandidate.Owner = if (self.active_scheme_root) |owner_root|
            .{ .scheme = owner_root }
        else if (self.active_generalized_target_share_group) |group_index|
            .{ .recursive_group = group_index }
        else
            continue;
        const pending = PendingGeneralizedTargetShareCandidate{
            .owner = owner,
            .omission = candidate,
        };
        const already_recorded = for (self.pending_generalized_target_share_candidates.items) |existing| {
            if (std.meta.eql(existing, pending)) break true;
        } else false;
        if (already_recorded) continue;
        try self.pending_generalized_target_share_candidates.append(self.gpa, pending);
    }

    // Set regions and add to the current rank all variables created during unification.
    //
    // We assign all fresh variables the region of `b` (the "actual" type), since `a` is
    // typically the "expected" type from an annotation. This policy works well for
    // most cases but can be imprecise for deeply nested unifications where fresh variables
    // are created for sub-components (e.g., record fields, tag payloads). In those cases,
    // error messages may point to the outer expression rather than the specific field.
    //
    // A more precise solution would track the origin of each fresh variable during
    // unification and propagate that back, but the current approach is sufficient for
    // typical error reporting scenarios.
    const region = self.getRegionAt(b);
    for (self.unify_scratch.fresh_vars.items.items) |fresh_var| {
        // Set the rank
        const fresh_rank = self.types.resolveVar(fresh_var).desc.rank;
        try env.var_pool.addVarToRank(fresh_var, fresh_rank);

        // Set the region
        try self.fillInRegionsThrough(fresh_var);
        self.setRegionAt(fresh_var, region);
    }
    if (annotation_unify_event) |event| {
        for (self.unify_scratch.fresh_vars.items.items, 0..) |fresh_var, ordinal| {
            try self.appendPredeclaredAnnoGenEvent(.{
                .anchor_node = event.anchor_node,
                .kind = @intFromEnum(PredeclaredAnnoGenEventKind.unify_fresh_var),
                .slot = event.slot,
                .ordinal = @intCast(ordinal),
            }, .{ .var_ = fresh_var }, null);
        }
        const constraints_after_unify = self.types.static_dispatch_constraints.items.items.len;
        for (constraints_before_unify..constraints_after_unify, 0..) |constraint_index, ordinal| {
            try self.appendPredeclaredAnnoGenEvent(.{
                .anchor_node = event.anchor_node,
                .kind = @intFromEnum(PredeclaredAnnoGenEventKind.unify_constraint),
                .slot = event.slot,
                .ordinal = @intCast(ordinal),
            }, .{ .constraint_index = @intCast(constraint_index) }, null);
        }
    }

    // Copy any constraints created during unification into our own array. A
    // where-clause obligation that becomes concrete while checking a scheme use
    // belongs to that use; ordinary dispatch and literal constraints retain
    // their own creation-time provenance. The group whose checking ran this
    // unification owns each obligation's boundary-time resolution.
    const failure_expr = self.discarded_binding_rhs_expr orelse self.instantiation_source_expr;
    for (self.unify_scratch.deferred_constraints.items.items) |deferred_constraint| {
        var owned_constraint = deferred_constraint;
        if (failure_expr) |expr_idx| {
            if (owned_constraint.failure_expr == .none) {
                for (self.types.sliceStaticDispatchConstraints(owned_constraint.constraints)) |constraint| {
                    if (constraint.origin == .where_clause) {
                        owned_constraint.failure_expr = .from(@intFromEnum(expr_idx));
                        break;
                    }
                }
            }
        }
        try self.enqueueDeferredDispatchConstraint(env, owned_constraint, .current_group);
    }

    // Ensure arrays are in sync
    self.debugAssertArraysInSync();

    return result;
}

/// Unify two types where `a` is the expected type and `b` is the actual type.
fn unify(self: *Self, a: Var, b: Var, env: *Env) std.mem.Allocator.Error!unifier.Result {
    return self.runUnify(a, b, env, .{});
}

fn fieldPresenceRelationForContext(
    ctx: problem.Context,
    row_width_relation: unifier.RowWidthRelation,
) unifier.FieldPresenceRelation {
    if (ctx == .record_access) {
        return if (ctx.record_access.mode == .required) .required_access else .ordinary;
    }
    return if (row_width_relation == .exact) .committed_value else .ordinary;
}

fn unifyOptionsForContext(ctx: problem.Context, on_mismatch: unifier.MismatchBehavior) unifier.Options {
    const row_width_relation: unifier.RowWidthRelation = if (std.meta.activeTag(ctx) == .platform_requirement)
        .exact
    else
        .construction;
    return .{
        .context = ctx,
        .on_mismatch = on_mismatch,
        .row_width_relation = row_width_relation,
        .field_presence_relation = fieldPresenceRelationForContext(ctx, row_width_relation),
    };
}

/// Unify two types with a context for error reporting.
fn unifyInContext(self: *Self, a: Var, b: Var, env: *Env, ctx: problem.Context) std.mem.Allocator.Error!unifier.Result {
    return self.runUnify(a, b, env, unifyOptionsForContext(ctx, .poison_to_err));
}

fn exprIsFreshRecordConstruction(self: *const Self, expr_idx: CIR.Expr.Idx) bool {
    const expr = self.cir.store.getExpr(expr_idx);
    return expr == .e_record or expr == .e_empty_record;
}

/// Check one relation owned by a single expression without letting a rejected
/// relation poison the operand type graphs. Those graphs can be shared with
/// otherwise valid producer expressions—a callee, an argument, or the record
/// a field access reads from—so only the owning expression becomes erroneous.
fn unifyOwnedRelation(
    self: *Self,
    expected: Var,
    actual: Var,
    env: *Env,
    ctx: problem.Context,
    row_width_relation: unifier.RowWidthRelation,
) std.mem.Allocator.Error!unifier.Result {
    return self.unifyOwnedRootRelation(expected, actual, env, ctx, row_width_relation, .ordinary);
}

/// `unifyOwnedRelation` for a relation whose initial pair carries a root
/// relation beyond ordinary unification.
fn unifyOwnedRootRelation(
    self: *Self,
    expected: Var,
    actual: Var,
    env: *Env,
    ctx: problem.Context,
    row_width_relation: unifier.RowWidthRelation,
    root_relation: unifier.RootRelation,
) std.mem.Allocator.Error!unifier.Result {
    const result = try self.runUnify(expected, actual, env, .{
        .context = ctx,
        .on_mismatch = .write_no_report,
        .root_relation = root_relation,
        .row_width_relation = row_width_relation,
        .field_presence_relation = fieldPresenceRelationForContext(ctx, row_width_relation),
        .record_construction_var = if (row_width_relation == .construction) actual else null,
    });
    if (result.isAccepted()) return result;
    return .{ .problem = try self.appendTypeMismatch(expected, actual, ctx) };
}

/// Record a type mismatch between two vars under a context. Every caller that
/// owns its own rejection reports through here, so a rejection re-decided at
/// the settled state renders exactly like the relation-time one.
fn appendTypeMismatch(
    self: *Self,
    expected: Var,
    actual: Var,
    ctx: problem.Context,
) std.mem.Allocator.Error!problem.Problem.Idx {
    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, expected);
    const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, actual);
    return self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
        .types = .{
            .expected_var = expected,
            .expected_snapshot = expected_snapshot,
            .actual_var = actual,
            .actual_snapshot = actual_snapshot,
        },
        .context = ctx,
    } });
}

/// The constructor's operand is an ordinary value expression whose solved class
/// is shared with everything else that value flows through—in the very case
/// this relation exists to reject, `..receiver` has already lifted the update to
/// the nominal, so the operand's class *is* the receiver's. Rejecting the
/// constructor therefore owns the diagnostic and poisons only the constructor
/// node; the receiver keeps the type it legitimately has.
fn unifyNominalConstructorBacking(
    self: *Self,
    expected_backing: Var,
    actual_backing: Var,
    env: *Env,
    ctx: problem.Context.NominalConstructorContext,
    row_width_relation: unifier.RowWidthRelation,
) std.mem.Allocator.Error!unifier.Result {
    return self.unifyOwnedRootRelation(
        expected_backing,
        actual_backing,
        env,
        .{ .nominal_constructor = ctx },
        row_width_relation,
        .nominal_constructor_backing,
    );
}

/// Check if a variable contains an infinite type after solving a binding.
/// This catches cases like `f = |x| f([x])` which creates `a = List(a)`.
///
/// Runs at binding roots: top-level defs (`CIR.Def.Idx`, the settled-state
/// sweep), local bindings (`CIR.Pattern.Idx`, when their statement finishes
/// solving), and standalone checked expressions (`CIR.Expr.Idx`, REPL roots).
fn checkForInfiniteType(self: *Self, comptime Idx: anytype, idx: Idx) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    std.debug.assert(Idx == CIR.Def.Idx or Idx == CIR.Expr.Idx or Idx == CIR.Pattern.Idx);

    const var_ = ModuleEnv.varFrom(idx);
    const occurs_result = try occurs.occurs(self.types, &self.occurs_scratch, var_);

    switch (occurs_result) {
        .valid => {
            // This is fine - no cycle, or valid recursion through a nominal type
        },
        .recursive_anonymous => {
            // Anonymous recursion (a recursive type not routed through a
            // nominal) is always disallowed, at every binding root—top-level
            // defs, checked expression roots, and local bindings alike. A
            // recursive type must go through a nominal to be valid. The
            // `.recursive_anonymous` vs `.infinite` classification only selects
            // a clearer error message; it never permits the type.
            std.debug.assert(self.occurs_scratch.err_var != null);
            const err_var = self.occurs_scratch.err_var.?;

            const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, err_var);
            _ = try self.problems.appendProblem(self.gpa, .{ .anonymous_recursion = .{
                .var_ = var_,
                .snapshot = snapshot,
                .def_name = self.bindingRootName(Idx, idx),
            } });
            try self.types.setVarContent(var_, .err);
        },
        .infinite => {
            std.debug.assert(self.occurs_scratch.err_var != null);
            const err_var = self.occurs_scratch.err_var.?;

            // Infinite type (like `a = List(a)`)
            const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, err_var);
            _ = try self.problems.appendProblem(self.gpa, .{ .infinite_recursion = .{
                .var_ = var_,
                .snapshot = snapshot,
                .def_name = self.bindingRootName(Idx, idx),
            } });
            try self.types.setVarContent(var_, .err);
        },
    }
}

/// The settled-state occurs sweep: check every binding root—top-level defs
/// and recorded local bindings—for infinite/anonymous-recursive types, after
/// all deferred constraints have been solved.
fn checkBindingRootsForInfiniteTypes(self: *Self) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Local bindings first: when a local binding's cycle is also reachable
    // from the enclosing top-level def's type, reporting (and poisoning) the
    // local binding attributes the error to the tighter root and suppresses a
    // duplicate report at the def.
    for (self.local_binding_roots.items) |pattern_idx| {
        try self.checkForInfiniteType(CIR.Pattern.Idx, pattern_idx);
    }
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        try self.checkForInfiniteType(CIR.Def.Idx, def_idx);
    }
}

/// The settled-state re-decision of every accepted explicit nominal constructor
/// backing relation.
///
/// The relation rejects lifting an already-nominal operand back through an
/// anonymous expected backing. That is decided from the operand's solved shape,
/// and unification can widen the shape after the relation runs: an operand that
/// was still an open row when the constructor was checked lifts to the nominal
/// once a later call pins it, which is exactly the shape the rule exists to
/// reject. Re-deciding here is what makes the rule's verdict independent of
/// where the constructor happens to be written.
///
/// A constructor rejected here has already handed its result type to every
/// consumer, so poisoning the target var would corrupt the annotation classes it
/// merged into. Only the constructor expression becomes a runtime error.
fn recheckNominalConstructorBackings(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    var rejected: std.ArrayListUnmanaged(u32) = .empty;
    defer rejected.deinit(self.gpa);

    // Indexed rather than over a captured slice: nothing here appends to the
    // list today, and a captured slice would be the thing that breaks first if
    // that ever changed.
    var index: usize = 0;
    while (index < self.accepted_nominal_constructor_backings.items.len) : (index += 1) {
        const accepted = self.accepted_nominal_constructor_backings.items[index];
        const lifted = unifier.constructorBackingActualIsNominal(self.types, accepted.actual_backing) orelse continue;
        if (!lifted) continue;
        if (self.cir.store.getExpr(accepted.expr_idx) == .e_runtime_error) continue;
        try rejected.append(self.gpa, @intCast(index));
    }
    if (rejected.items.len == 0) return;

    // Source order, widest first where two rejections start together: this is
    // the order the reports come out in, and it puts an enclosing rejection
    // ahead of the ones its own replacement is about to discard.
    const RejectionOrder = struct {
        check: *const Self,
        fn lessThan(check: *const Self, a: u32, b: u32) bool {
            const region_a = check.rejectedNominalConstructorRegion(a);
            const region_b = check.rejectedNominalConstructorRegion(b);
            if (region_a.start.offset != region_b.start.offset) {
                return region_a.start.offset < region_b.start.offset;
            }
            if (region_a.end.offset != region_b.end.offset) {
                return region_a.end.offset > region_b.end.offset;
            }
            return a < b;
        }
    };
    std.mem.sort(u32, rejected.items, @as(*const Self, self), RejectionOrder.lessThan);

    var reported_regions: std.ArrayListUnmanaged(Region) = .empty;
    defer reported_regions.deinit(self.gpa);

    for (rejected.items) |entry_index| {
        const accepted = self.accepted_nominal_constructor_backings.items[entry_index];
        const region = self.rejectedNominalConstructorRegion(entry_index);
        if (self.expressionErrorAlreadyEncloses(region, reported_regions.items)) continue;

        // One var rebuilt from the declared backing's own content. It describes
        // the expected side the merged class can no longer show, and minting it
        // touches nothing the solved graph already holds.
        const expected_backing = try self.freshFromContent(accepted.expected_backing_content, env, region);
        _ = try self.appendTypeMismatch(
            expected_backing,
            accepted.actual_backing,
            .{ .nominal_constructor = accepted.context },
        );

        const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{ .region = region } });
        try self.replaceExprWithRuntimeError(accepted.expr_idx, diagnostic_idx);
        try reported_regions.append(self.gpa, region);
    }
}

fn rejectedNominalConstructorRegion(self: *const Self, entry_index: u32) Region {
    return self.cir.store.getExprRegion(self.accepted_nominal_constructor_backings.items[entry_index].expr_idx);
}

/// Whether an expression already destined to become a runtime error encloses
/// this region. The enclosing error replaces the whole subtree, so a second
/// report would describe source the checked module no longer contains—which is
/// exactly what a relation-time rejection avoids by poisoning its own node and
/// letting the enclosing relations read `.err`.
fn expressionErrorAlreadyEncloses(self: *const Self, region: Region, reported: []const Region) bool {
    for (reported) |outer| {
        if (outer.start.offset <= region.start.offset and region.end.offset <= outer.end.offset) return true;
    }
    var queued = self.erroneous_value_exprs.keyIterator();
    while (queued.next()) |expr_idx| {
        const outer = self.cir.store.getExprRegion(expr_idx.*);
        if (outer.start.offset <= region.start.offset and region.end.offset <= outer.end.offset) return true;
    }
    return false;
}

/// The display name for a binding root being occurs-checked, when it has one.
fn bindingRootName(self: *const Self, comptime Idx: anytype, idx: Idx) ?Ident.Idx {
    if (comptime Idx == CIR.Def.Idx) {
        const def = self.cir.store.getDef(idx);
        return self.getPatternIdent(def.pattern);
    }
    if (comptime Idx == CIR.Pattern.Idx) {
        return self.getPatternIdent(idx);
    }
    return null;
}

fn propagateTypeDeclarationInvalidity(
    self: *Self,
    dependent_offsets: []const usize,
    dependents: []const u32,
    propagated: []bool,
    worklist: *std.ArrayListUnmanaged(u32),
) void {
    worklist.clearRetainingCapacity();
    for (self.type_decl_invalid.items, propagated, 0..) |invalid, *was_propagated, dense_idx| {
        if (!invalid or was_propagated.*) continue;
        was_propagated.* = true;
        worklist.appendAssumeCapacity(@intCast(dense_idx));
    }

    var next: usize = 0;
    while (next < worklist.items.len) : (next += 1) {
        const dependency = worklist.items[next];
        for (dependents[dependent_offsets[dependency]..dependent_offsets[dependency + 1]]) |dependent| {
            if (self.type_decl_invalid.items[dependent]) continue;
            self.type_decl_invalid.items[dependent] = true;
            propagated[dependent] = true;
            worklist.appendAssumeCapacity(dependent);
        }
    }
}

fn poisonInvalidTypeDeclarations(self: *Self, poisoned: []bool) std.mem.Allocator.Error!void {
    const self_origin = self.cir.selfModuleIdentity();
    for (self.type_decl_statements.items, self.type_decl_invalid.items, poisoned) |decl_idx, invalid, *was_poisoned| {
        if (!invalid or was_poisoned.*) continue;
        was_poisoned.* = true;

        const backing_var: ?Var = switch (self.cir.store.getStatement(decl_idx)) {
            .s_alias_decl => |alias| if (alias.anno == .placeholder) null else ModuleEnv.varFrom(alias.anno),
            .s_nominal_decl => blk: {
                const nominal_idx = self.types.lookupNominalDeclByKey(
                    self_origin,
                    @intFromEnum(decl_idx),
                ) orelse unreachable;
                const nominal = self.types.getNominalDecl(nominal_idx);
                try self.types.markNominalDeclInvalid(nominal_idx);
                break :blk nominal.backing;
            },
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => unreachable,
        };

        try self.types.setVarContent(ModuleEnv.varFrom(decl_idx), .err);
        if (backing_var) |var_| try self.types.setVarContent(var_, .err);
    }
}

/// Close declaration-template invalidity over local declaration references,
/// validate nominal recursion, and poison every transitively invalid declaration.
fn finalizeTypeDeclarationValidity(self: *Self) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const decl_count = self.type_decl_statements.items.len;
    if (decl_count == 0) return;

    var dependent_counts = try self.gpa.alloc(usize, decl_count);
    defer self.gpa.free(dependent_counts);
    @memset(dependent_counts, 0);

    for (self.type_decl_dependencies.items) |edge| {
        dependent_counts[edge.dependency] += 1;
    }

    var dependent_offsets = try self.gpa.alloc(usize, decl_count + 1);
    defer self.gpa.free(dependent_offsets);
    dependent_offsets[0] = 0;
    for (dependent_counts, 0..) |count, dense_idx| {
        dependent_offsets[dense_idx + 1] = dependent_offsets[dense_idx] + count;
    }

    var fill_offsets = try self.gpa.dupe(usize, dependent_offsets[0..decl_count]);
    defer self.gpa.free(fill_offsets);
    const dependents = try self.gpa.alloc(u32, self.type_decl_dependencies.items.len);
    defer self.gpa.free(dependents);

    for (self.type_decl_dependencies.items) |edge| {
        const offset = fill_offsets[edge.dependency];
        dependents[offset] = edge.dependent;
        fill_offsets[edge.dependency] += 1;
    }

    var worklist: std.ArrayListUnmanaged(u32) = .empty;
    defer worklist.deinit(self.gpa);
    try worklist.ensureTotalCapacity(self.gpa, decl_count);

    const propagated = try self.gpa.alloc(bool, decl_count);
    defer self.gpa.free(propagated);
    @memset(propagated, false);

    const poisoned = try self.gpa.alloc(bool, decl_count);
    defer self.gpa.free(poisoned);
    @memset(poisoned, false);

    self.propagateTypeDeclarationInvalidity(dependent_offsets, dependents, propagated, &worklist);
    try self.poisonInvalidTypeDeclarations(poisoned);

    try self.validateNominalDeclRecursion();
    try self.validateNominalDeclArgumentGrowth();

    self.propagateTypeDeclarationInvalidity(dependent_offsets, dependents, propagated, &worklist);
    try self.poisonInvalidTypeDeclarations(poisoned);
}

/// Validate every local nominal type declaration's backing recursion, after
/// all type declarations have been generated and before any value checking.
///
/// The traversal resolves nominal backings through the store's declaration
/// table by key (`occurs.occursDeclarationGraph`), so recursive references
/// close cycles by declaration identity—including mutual recursion that
/// per-use instantiation copies disconnect. Classification matches the
/// value-graph occurs rules: a cycle is valid only when it passes through
/// both a recursion-allowed position (tag payload / record field) and a
/// nominal backing.
///
/// An invalid declaration is reported once, here, at the declaration; the
/// declaration is marked invalid in the table and its decl var and backing
/// template are poisoned to `.err`, so every use is suppressed instead of
/// re-reporting the same cycle.
fn validateNominalDeclRecursion(self: *Self) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const self_origin = self.cir.selfModuleIdentity();
    const decl_count = self.types.nominalDeclCount();
    var decl_int: u32 = 0;
    while (decl_int < decl_count) : (decl_int += 1) {
        const decl_idx: types_mod.NominalDecl.Idx = @enumFromInt(decl_int);
        const decl = self.types.getNominalDecl(decl_idx);

        // Imported declarations were validated by their own module; module
        // imports are acyclic, so no cycle involving a local declaration can
        // route through them except via type arguments, which the local
        // traversal covers.
        if (decl.origin_module != self_origin) continue;

        const decl_var: Var = @enumFromInt(decl.statement());
        const resolved = self.types.resolveVar(decl_var).desc.content;
        // A declaration whose generation already failed (malformed backing)
        // has nothing further to validate.
        if (resolved != .structure or resolved.structure != .nominal_type) continue;

        const occurs_result = try occurs.occursDeclarationGraph(self.types, &self.occurs_scratch, decl_var);
        const kind: problem.InvalidNominalDeclRecursion.Kind = switch (occurs_result) {
            .valid => continue,
            .infinite => .infinite,
            .recursive_anonymous => .anonymous,
        };

        // Snapshot the declaration's backing template (not the cycle var,
        // which resolves to the bare nominal application and would render as
        // just the type's name).
        const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, decl.backing);
        _ = try self.problems.appendProblem(self.gpa, .{ .invalid_nominal_decl_recursion = .{
            .decl_var = decl_var,
            .snapshot = snapshot,
            .type_name = decl.ident.ident_idx,
            .kind = kind,
        } });

        // Poison the declaration: uses instantiate `.err` and are suppressed,
        // and no later stage can walk the cyclic template graph.
        self.markTypeDeclInvalid(@enumFromInt(decl.statement()));
        try self.types.markNominalDeclInvalid(decl_idx);
        try self.types.setVarContent(decl_var, .err);
        try self.types.setVarContent(decl.backing, .err);
    }
}

/// One nominal application found inside a local declaration's backing
/// template that resolves to another local declaration.
const NominalDeclMention = struct {
    from_slot: u32,
    to_slot: u32,
    args: types_mod.Var.SafeList.Range,
};

/// One directed edge of the formal-flow graph: instantiating the mention
/// that produced it substitutes something built from the source formal for
/// the target formal—the formal itself passed straight through
/// (`grows == false`) or a composite containing it (`grows == true`).
const FormalFlowEdge = struct {
    from_formal: u32,
    to_formal: u32,
    grows: bool,
    owner_slot: u32,
};

/// Reject nominal declarations whose recursion admits no finite set of
/// instantiations. Monomorphization instantiates a declaration's backing at
/// every distinct argument tuple, so a declaration group is monomorphizable
/// exactly when the argument tuples reachable from any application form a
/// finite set. Two shapes break that:
///
/// - A formal that flows around a mention cycle while some step of the
///   cycle wraps it in more structure (`Nest(a) := [More(Nest(List(a)))]`):
///   each trip produces a strictly larger argument, so every expansion
///   level is a distinct type. This is tracked exactly on the formal-flow
///   graph—a mention argument that is a formal passed straight through
///   adds a plain edge from the source formal to the mentioned
///   declaration's formal, and one that embeds a formal inside a composite
///   adds a growing edge—and a declaration is invalid exactly when one of
///   its growing edges lies inside a formal-flow cycle. Growth that never
///   returns to its origin stays finite (a mention cycle whose growing step
///   is reached only through closed arguments resets every trip), so only
///   cyclic growth is rejected.
///
/// - A recursive mention argument containing a variable that is no formal
///   of the mentioning declaration: nothing binds it, so every expansion
///   mints it fresh, and a mention whose target reaches back to its owner
///   then re-enters at a new tuple every level. Outside a declaration
///   cycle a stray variable cannot recur and is left to the diagnostics
///   that own it.
///
/// Unbounded growth is a property of the declarations alone (mirroring the
/// derived-codec growth rule), so it is reported here, once, at the
/// declaration. Imported declarations were validated by their own module,
/// and module imports are acyclic, so no recursive group spans modules.
///
/// Everything this rule admits terminates in Monotype lowering: a formal
/// argument resolves in the innermost declaration scope to the enclosing
/// instance's own cell and hits the backing cache's placeholder, a closed
/// argument memoizes to one cell per instantiation context, and growing
/// edges descend the formal-flow condensation, so every expansion draws its
/// argument tuple from a finite universe of cells.
fn validateNominalDeclArgumentGrowth(self: *Self) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const self_origin = self.cir.selfModuleIdentity();
    const decl_count: u32 = @intCast(self.types.nominalDeclCount());

    // Slot table: local, still-valid declarations with nominal content.
    var slots: std.ArrayListUnmanaged(types_mod.NominalDecl.Idx) = .empty;
    defer slots.deinit(self.gpa);
    var slot_by_decl = std.AutoHashMap(types_mod.NominalDecl.Idx, u32).init(self.gpa);
    defer slot_by_decl.deinit();

    var decl_int: u32 = 0;
    while (decl_int < decl_count) : (decl_int += 1) {
        const decl_idx: types_mod.NominalDecl.Idx = @enumFromInt(decl_int);
        const decl = self.types.getNominalDecl(decl_idx);
        if (decl.origin_module != self_origin) continue;
        if (!decl.isValid()) continue;
        const decl_var: Var = @enumFromInt(decl.statement());
        const resolved = self.types.resolveVar(decl_var).desc.content;
        if (resolved != .structure or resolved.structure != .nominal_type) continue;
        const slot: u32 = @intCast(slots.items.len);
        try slots.append(self.gpa, decl_idx);
        try slot_by_decl.put(decl_idx, slot);
    }
    if (slots.items.len == 0) return;
    const slot_count = slots.items.len;

    // Collect every local-declaration mention inside each backing template.
    // The walk stays within the mentioning declaration's own template: a
    // mentioned declaration's backing belongs to its own slot's analysis.
    var mentions: std.ArrayListUnmanaged(NominalDeclMention) = .empty;
    defer mentions.deinit(self.gpa);
    var walk_stack: std.ArrayListUnmanaged(Var) = .empty;
    defer walk_stack.deinit(self.gpa);
    var visited = std.AutoHashMap(Var, void).init(self.gpa);
    defer visited.deinit();

    for (slots.items, 0..) |decl_idx, from_slot_usize| {
        const from_slot: u32 = @intCast(from_slot_usize);
        const decl = self.types.getNominalDecl(decl_idx);
        visited.clearRetainingCapacity();
        walk_stack.clearRetainingCapacity();
        try walk_stack.append(self.gpa, decl.backing);
        while (walk_stack.pop()) |var_| {
            const root = self.types.resolveVar(var_);
            if (visited.contains(root.var_)) continue;
            try visited.put(root.var_, {});
            switch (root.desc.content) {
                .structure => |flat_type| switch (flat_type) {
                    .nominal_type => |nominal_type| {
                        if (self.types.lookupNominalDecl(nominal_type)) |target_idx| {
                            if (slot_by_decl.get(target_idx)) |to_slot| {
                                try mentions.append(self.gpa, .{
                                    .from_slot = from_slot,
                                    .to_slot = to_slot,
                                    .args = nominal_type.args,
                                });
                            }
                        }
                        var arg_iter = self.types.iterNominalArgs(nominal_type);
                        while (arg_iter.next()) |arg_var| {
                            try walk_stack.append(self.gpa, arg_var);
                        }
                    },
                    .tuple => |tuple| {
                        try walk_stack.appendSlice(self.gpa, self.types.sliceVars(tuple.elems));
                    },
                    .fn_pure, .fn_effectful, .fn_unbound => |func| {
                        try walk_stack.append(self.gpa, func.ret);
                        try walk_stack.appendSlice(self.gpa, self.types.sliceVars(func.args));
                        try walk_stack.appendSlice(self.gpa, self.types.sliceVars(func.effect_deps));
                    },
                    .record => |record| {
                        try walk_stack.append(self.gpa, record.ext);
                        const fields = self.types.getRecordFieldsSlice(record.fields);
                        for (fields.items(.presence)) |presence| {
                            try walk_stack.append(self.gpa, presence.typeVar());
                            if (presence.presenceVar()) |presence_var| {
                                try walk_stack.append(self.gpa, presence_var);
                            }
                        }
                    },
                    .record_unbound => |fields| {
                        const fields_slice = self.types.getRecordFieldsSlice(fields);
                        for (fields_slice.items(.presence)) |presence| {
                            try walk_stack.append(self.gpa, presence.typeVar());
                            if (presence.presenceVar()) |presence_var| {
                                try walk_stack.append(self.gpa, presence_var);
                            }
                        }
                    },
                    .tag_union => |tag_union| {
                        try walk_stack.append(self.gpa, tag_union.ext);
                        const tags = self.types.getTagsSlice(tag_union.tags);
                        for (tags.items(.args)) |tag_args| {
                            try walk_stack.appendSlice(self.gpa, self.types.sliceVars(tag_args));
                        }
                    },
                    .empty_record, .empty_tag_union => {},
                },
                .alias => |alias| {
                    try walk_stack.append(self.gpa, self.types.getAliasBackingVar(alias));
                    var arg_iter = self.types.iterAliasArgs(alias);
                    while (arg_iter.next()) |arg_var| {
                        try walk_stack.append(self.gpa, arg_var);
                    }
                },
                .flex, .rigid, .field_presence, .err => {},
            }
        }
    }
    if (mentions.items.len == 0) return;

    // Declaration-graph components: a mention is recursive exactly when its
    // target's component reaches back to its owner, i.e. both share one
    // strongly connected component.
    var decl_adjacency = try self.gpa.alloc(std.ArrayListUnmanaged(u32), slot_count);
    defer {
        for (decl_adjacency) |*list| list.deinit(self.gpa);
        self.gpa.free(decl_adjacency);
    }
    @memset(decl_adjacency, .empty);
    for (mentions.items) |mention| {
        try decl_adjacency[mention.from_slot].append(self.gpa, mention.to_slot);
    }
    const decl_component = try self.gpa.alloc(u32, slot_count);
    defer self.gpa.free(decl_component);
    try self.stronglyConnectedComponents(decl_adjacency, decl_component);

    // Flatten each declaration's resolved formal roots so mention arguments
    // classify by direct var comparison.
    var formal_base = try self.gpa.alloc(u32, slot_count + 1);
    defer self.gpa.free(formal_base);
    formal_base[0] = 0;
    for (slots.items, 0..) |decl_idx, slot| {
        const decl = self.types.getNominalDecl(decl_idx);
        formal_base[slot + 1] = formal_base[slot] + @as(u32, @intCast(self.types.sliceVars(decl.formals).len));
    }
    const formal_count = formal_base[slot_count];
    var formal_roots = try self.gpa.alloc(Var, formal_count);
    defer self.gpa.free(formal_roots);
    var max_decl_formals: usize = 0;
    for (slots.items, 0..) |decl_idx, slot| {
        const decl = self.types.getNominalDecl(decl_idx);
        const formals = self.types.sliceVars(decl.formals);
        max_decl_formals = @max(max_decl_formals, formals.len);
        for (formals, formal_roots[formal_base[slot]..formal_base[slot + 1]]) |formal, *out| {
            out.* = self.types.resolveVar(formal).var_;
        }
    }

    const reported = try self.gpa.alloc(bool, slot_count);
    defer self.gpa.free(reported);
    @memset(reported, false);
    const found_formals = try self.gpa.alloc(bool, max_decl_formals);
    defer self.gpa.free(found_formals);

    // Classify every mention argument into formal-flow edges, rejecting
    // recursive mentions that carry unbindable variables outright.
    var flow_edges: std.ArrayListUnmanaged(FormalFlowEdge) = .empty;
    defer flow_edges.deinit(self.gpa);

    mention_loop: for (mentions.items) |mention| {
        if (reported[mention.from_slot]) continue;
        const recursive = decl_component[mention.from_slot] == decl_component[mention.to_slot];
        const owner_formals = formal_roots[formal_base[mention.from_slot]..formal_base[mention.from_slot + 1]];
        const target_formal_count = formal_base[mention.to_slot + 1] - formal_base[mention.to_slot];
        for (self.types.sliceVars(mention.args), 0..) |arg_var, position| {
            // An arity mismatch against the declaration is diagnosed at the
            // application; extra arguments carry no formal-flow meaning.
            if (position >= target_formal_count) continue;
            const to_formal = formal_base[mention.to_slot] + @as(u32, @intCast(position));
            const arg_root = self.types.resolveVar(arg_var);
            switch (arg_root.desc.content) {
                .flex, .rigid => {
                    var matched = false;
                    for (owner_formals, 0..) |formal, formal_position| {
                        if (formal == arg_root.var_) {
                            try flow_edges.append(self.gpa, .{
                                .from_formal = formal_base[mention.from_slot] + @as(u32, @intCast(formal_position)),
                                .to_formal = to_formal,
                                .grows = false,
                                .owner_slot = mention.from_slot,
                            });
                            matched = true;
                            break;
                        }
                    }
                    if (!matched and recursive) {
                        reported[mention.from_slot] = true;
                        try self.reportGrowingNominalDecl(slots.items[mention.from_slot]);
                        continue :mention_loop;
                    }
                },
                .err, .field_presence => {},
                .structure, .alias => {
                    @memset(found_formals[0..owner_formals.len], false);
                    const saw_non_formal = try self.collectFormalOccurrences(
                        arg_root.var_,
                        owner_formals,
                        found_formals,
                        &walk_stack,
                        &visited,
                    );
                    if (saw_non_formal and recursive) {
                        reported[mention.from_slot] = true;
                        try self.reportGrowingNominalDecl(slots.items[mention.from_slot]);
                        continue :mention_loop;
                    }
                    for (found_formals[0..owner_formals.len], 0..) |occurred, formal_position| {
                        if (!occurred) continue;
                        try flow_edges.append(self.gpa, .{
                            .from_formal = formal_base[mention.from_slot] + @as(u32, @intCast(formal_position)),
                            .to_formal = to_formal,
                            .grows = true,
                            .owner_slot = mention.from_slot,
                        });
                    }
                },
            }
        }
    }
    if (flow_edges.items.len == 0) return;

    // A growing edge repeats exactly when it lies inside a formal-flow
    // cycle, i.e. when its endpoints share a strongly connected component.
    var flow_adjacency = try self.gpa.alloc(std.ArrayListUnmanaged(u32), formal_count);
    defer {
        for (flow_adjacency) |*list| list.deinit(self.gpa);
        self.gpa.free(flow_adjacency);
    }
    @memset(flow_adjacency, .empty);
    for (flow_edges.items) |edge| {
        try flow_adjacency[edge.from_formal].append(self.gpa, edge.to_formal);
    }
    const flow_component = try self.gpa.alloc(u32, formal_count);
    defer self.gpa.free(flow_component);
    try self.stronglyConnectedComponents(flow_adjacency, flow_component);

    for (flow_edges.items) |edge| {
        if (!edge.grows) continue;
        if (flow_component[edge.from_formal] != flow_component[edge.to_formal]) continue;
        if (reported[edge.owner_slot]) continue;
        reported[edge.owner_slot] = true;
        try self.reportGrowingNominalDecl(slots.items[edge.owner_slot]);
    }
}

/// Report one growing declaration and poison it exactly like the other
/// invalid-recursion kinds: uses instantiate `.err` and are suppressed, and
/// no later stage walks the template.
fn reportGrowingNominalDecl(self: *Self, decl_idx: types_mod.NominalDecl.Idx) std.mem.Allocator.Error!void {
    const decl = self.types.getNominalDecl(decl_idx);
    const decl_var: Var = @enumFromInt(decl.statement());
    const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, decl.backing);
    _ = try self.problems.appendProblem(self.gpa, .{ .invalid_nominal_decl_recursion = .{
        .decl_var = decl_var,
        .snapshot = snapshot,
        .type_name = decl.ident.ident_idx,
        .kind = .growing_args,
    } });
    self.markTypeDeclInvalid(@enumFromInt(decl.statement()));
    try self.types.markNominalDeclInvalid(decl_idx);
    try self.types.setVarContent(decl_var, .err);
    try self.types.setVarContent(decl.backing, .err);
}

/// Walk `start` recording which of `formals` (resolved roots) occur inside
/// it and whether any variable outside that set occurs. Structural
/// positions, alias backings and arguments, function effect dependencies,
/// and nominal application arguments are traversed; nominal backings are
/// not entered, because a mentioned declaration's template can only
/// reference that declaration's own formals, never the caller's. `.err`
/// counts as variable-free so already-poisoned declarations are not
/// re-reported through their poisoned types. This deliberately treats a
/// transparent alias of a formal as an occurrence inside a composite: the
/// alias mention instantiates its own node per expansion level, so passing
/// a formal through an alias does not preserve the argument cell the way a
/// bare formal does.
fn collectFormalOccurrences(
    self: *Self,
    start: Var,
    formals: []const Var,
    found: []bool,
    walk_stack: *std.ArrayListUnmanaged(Var),
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    visited.clearRetainingCapacity();
    walk_stack.clearRetainingCapacity();
    try walk_stack.append(self.gpa, start);
    var saw_non_formal = false;
    while (walk_stack.pop()) |var_| {
        const root = self.types.resolveVar(var_);
        if (visited.contains(root.var_)) continue;
        try visited.put(root.var_, {});
        switch (root.desc.content) {
            .flex, .rigid => {
                var matched = false;
                for (formals, 0..) |formal, position| {
                    if (formal == root.var_) {
                        found[position] = true;
                        matched = true;
                        break;
                    }
                }
                if (!matched) saw_non_formal = true;
            },
            .structure => |flat_type| switch (flat_type) {
                .nominal_type => |nominal_type| {
                    var arg_iter = self.types.iterNominalArgs(nominal_type);
                    while (arg_iter.next()) |arg_var| {
                        try walk_stack.append(self.gpa, arg_var);
                    }
                },
                .tuple => |tuple| {
                    try walk_stack.appendSlice(self.gpa, self.types.sliceVars(tuple.elems));
                },
                .fn_pure, .fn_effectful, .fn_unbound => |func| {
                    try walk_stack.append(self.gpa, func.ret);
                    try walk_stack.appendSlice(self.gpa, self.types.sliceVars(func.args));
                    try walk_stack.appendSlice(self.gpa, self.types.sliceVars(func.effect_deps));
                },
                .record => |record| {
                    try walk_stack.append(self.gpa, record.ext);
                    const fields = self.types.getRecordFieldsSlice(record.fields);
                    for (fields.items(.presence)) |presence| {
                        try walk_stack.append(self.gpa, presence.typeVar());
                        if (presence.presenceVar()) |presence_var| {
                            try walk_stack.append(self.gpa, presence_var);
                        }
                    }
                },
                .record_unbound => |fields| {
                    const fields_slice = self.types.getRecordFieldsSlice(fields);
                    for (fields_slice.items(.presence)) |presence| {
                        try walk_stack.append(self.gpa, presence.typeVar());
                        if (presence.presenceVar()) |presence_var| {
                            try walk_stack.append(self.gpa, presence_var);
                        }
                    }
                },
                .tag_union => |tag_union| {
                    try walk_stack.append(self.gpa, tag_union.ext);
                    const tags = self.types.getTagsSlice(tag_union.tags);
                    for (tags.items(.args)) |tag_args| {
                        try walk_stack.appendSlice(self.gpa, self.types.sliceVars(tag_args));
                    }
                },
                .empty_record, .empty_tag_union => {},
            },
            .alias => |alias| {
                try walk_stack.append(self.gpa, self.types.getAliasBackingVar(alias));
                var arg_iter = self.types.iterAliasArgs(alias);
                while (arg_iter.next()) |arg_var| {
                    try walk_stack.append(self.gpa, arg_var);
                }
            },
            .field_presence, .err => {},
        }
    }
    return saw_non_formal;
}

/// Iterative Tarjan strongly-connected components over a dense node range.
/// Two nodes receive the same component id exactly when each reaches the
/// other through the adjacency lists.
fn stronglyConnectedComponents(
    self: *Self,
    adjacency: []const std.ArrayListUnmanaged(u32),
    component_of: []u32,
) std.mem.Allocator.Error!void {
    const node_count = adjacency.len;
    const unvisited = std.math.maxInt(u32);
    const index_of = try self.gpa.alloc(u32, node_count);
    defer self.gpa.free(index_of);
    @memset(index_of, unvisited);
    const low_of = try self.gpa.alloc(u32, node_count);
    defer self.gpa.free(low_of);
    const on_stack = try self.gpa.alloc(bool, node_count);
    defer self.gpa.free(on_stack);
    @memset(on_stack, false);

    var component_stack: std.ArrayListUnmanaged(u32) = .empty;
    defer component_stack.deinit(self.gpa);
    const WalkFrame = struct { node: u32, edge: u32 };
    var walk_frames: std.ArrayListUnmanaged(WalkFrame) = .empty;
    defer walk_frames.deinit(self.gpa);

    var next_index: u32 = 0;
    var next_component: u32 = 0;
    for (0..node_count) |start| {
        if (index_of[start] != unvisited) continue;
        index_of[start] = next_index;
        low_of[start] = next_index;
        next_index += 1;
        try component_stack.append(self.gpa, @intCast(start));
        on_stack[start] = true;
        try walk_frames.append(self.gpa, .{ .node = @intCast(start), .edge = 0 });
        while (walk_frames.items.len != 0) {
            const frame = &walk_frames.items[walk_frames.items.len - 1];
            const node = frame.node;
            if (frame.edge < adjacency[node].items.len) {
                const next = adjacency[node].items[frame.edge];
                frame.edge += 1;
                if (index_of[next] == unvisited) {
                    index_of[next] = next_index;
                    low_of[next] = next_index;
                    next_index += 1;
                    try component_stack.append(self.gpa, next);
                    on_stack[next] = true;
                    try walk_frames.append(self.gpa, .{ .node = next, .edge = 0 });
                } else if (on_stack[next]) {
                    low_of[node] = @min(low_of[node], index_of[next]);
                }
                continue;
            }
            walk_frames.items.len -= 1;
            if (walk_frames.items.len != 0) {
                const parent = walk_frames.items[walk_frames.items.len - 1].node;
                low_of[parent] = @min(low_of[parent], low_of[node]);
            }
            if (low_of[node] == index_of[node]) {
                while (true) {
                    const member = component_stack.pop().?;
                    on_stack[member] = false;
                    component_of[member] = next_component;
                    if (member == node) break;
                }
                next_component += 1;
            }
        }
    }
}

fn resolvePendingTupleAccess(
    self: *Self,
    pending: PendingTupleAccess,
    env: *Env,
    final: bool,
) Allocator.Error!bool {
    const tuple_resolved = self.types.resolveVar(pending.tuple_var);
    switch (tuple_resolved.desc.content) {
        .structure => |structure| switch (structure) {
            .tuple => |tuple| {
                const elems = self.types.sliceVars(tuple.elems);
                if (pending.elem_index < elems.len) {
                    _ = try self.unify(pending.result_var, elems[pending.elem_index], env);
                } else {
                    _ = try self.problems.appendProblem(self.gpa, .{ .invalid_tuple_access = .{
                        .region = pending.region,
                        .elem_index = pending.elem_index,
                        .reason = .{ .index_out_of_bounds = @intCast(elems.len) },
                    } });
                    try self.markErroneous(pending.result_var);
                }
                return true;
            },
            .record,
            .record_unbound,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => {
                _ = try self.problems.appendProblem(self.gpa, .{ .invalid_tuple_access = .{
                    .region = pending.region,
                    .elem_index = pending.elem_index,
                    .reason = .not_tuple,
                } });
                try self.markErroneous(pending.result_var);
                return true;
            },
        },
        .alias => |alias| {
            const backing_var = self.types.getAliasBackingVar(alias);
            const alias_pending = PendingTupleAccess{
                .tuple_var = backing_var,
                .result_var = pending.result_var,
                .elem_index = pending.elem_index,
                .region = pending.region,
            };
            return try self.resolvePendingTupleAccess(alias_pending, env, final);
        },
        .err, .field_presence => {
            try self.markErroneous(pending.result_var);
            return true;
        },
        .flex, .rigid => {
            if (!final) return false;

            _ = try self.problems.appendProblem(self.gpa, .{ .tuple_access_needs_annotation = .{
                .region = pending.region,
                .elem_index = pending.elem_index,
            } });
            try self.markErroneous(pending.result_var);
            try self.markErroneous(pending.tuple_var);
            return true;
        },
    }
}

fn resolvePendingTupleAccesses(
    self: *Self,
    env: *Env,
    final: bool,
) Allocator.Error!void {
    var write_i: usize = 0;
    var read_i: usize = 0;
    while (read_i < self.pending_tuple_accesses.items.len) : (read_i += 1) {
        const pending = self.pending_tuple_accesses.items[read_i];
        if (try self.resolvePendingTupleAccess(pending, env, final)) continue;

        self.pending_tuple_accesses.items[write_i] = pending;
        write_i += 1;
    }
    self.pending_tuple_accesses.shrinkRetainingCapacity(write_i);
}

// instantiate  //

const InstantiateRegionBehavior = union(enum) {
    explicit: Region,
    use_root_instantiated,
    use_last_var,
};

fn typeSchemeIndexForRoot(self: *Self, root_var: Var) ?usize {
    const raw_index = self.type_scheme_by_var.get(root_var) orelse return null;
    const index: usize = raw_index;
    std.debug.assert(index < self.type_schemes.items.len);
    return index;
}

fn isBindingSchemeVar(self: *const Self, var_: Var) bool {
    const raw_var: usize = @intFromEnum(var_);
    if (raw_var < self.binding_scheme_nodes.bit_length) {
        return self.binding_scheme_nodes.isSet(raw_var);
    }
    return self.synthetic_binding_schemes.contains(var_);
}

fn markBindingSchemeVar(self: *Self, var_: Var) Allocator.Error!void {
    const raw_var: usize = @intFromEnum(var_);
    if (raw_var < self.binding_scheme_nodes.bit_length) {
        if (self.binding_scheme_nodes.isSet(raw_var)) return;
        if (self.probe_depth != 0) {
            try self.binding_scheme_mutation_journal.ensureUnusedCapacity(self.gpa, 1);
        }
        self.binding_scheme_nodes.set(raw_var);
        if (self.probe_depth != 0) {
            self.binding_scheme_mutation_journal.appendAssumeCapacity(.{ .node = @intCast(raw_var) });
        }
        return;
    }
    if (self.synthetic_binding_schemes.contains(var_)) return;
    try self.synthetic_binding_schemes.ensureUnusedCapacity(self.gpa, 1);
    if (self.probe_depth != 0) {
        try self.binding_scheme_mutation_journal.ensureUnusedCapacity(self.gpa, 1);
    }
    self.synthetic_binding_schemes.putAssumeCapacity(var_, {});
    if (self.probe_depth != 0) {
        self.binding_scheme_mutation_journal.appendAssumeCapacity(.{ .synthetic = var_ });
    }
}

/// Publish the dense checker-local classification as the compact sorted table
/// stored in checked module output. Scanning node order once avoids maintaining
/// a sorted list while dependency-order checking discovers schemes.
fn finalizeBindingSchemeNodes(self: *Self) Allocator.Error!void {
    self.cir.binding_schemes.items.clearRetainingCapacity();
    var raw_node: usize = 0;
    while (raw_node < self.binding_scheme_nodes.bit_length) : (raw_node += 1) {
        if (self.binding_scheme_nodes.isSet(raw_node)) {
            try self.cir.recordBindingScheme(@enumFromInt(raw_node));
        }
    }
}

fn bindBindingSchemeVar(self: *Self, scheme_var: Var, alias_var: Var) Allocator.Error!void {
    if (self.isBindingSchemeVar(scheme_var)) {
        try self.markBindingSchemeVar(alias_var);
    }
}

/// Whether the post-generalization graph reachable from `root_var` contains a
/// quantified variable. This exact producer-side walk classifies a rank-1
/// binding once; use sites consume the recorded classification in O(1).
fn typeHasGeneralizedVar(self: *Self, root_var: Var) Allocator.Error!bool {
    if (self.types.resolveVar(root_var).desc.rank == .generalized) return true;

    self.binding_scheme_classification_seen.clearRetainingCapacity();
    self.binding_scheme_classification_stack.clearRetainingCapacity();
    defer self.binding_scheme_classification_stack.clearRetainingCapacity();

    try self.binding_scheme_classification_stack.append(self.gpa, root_var);
    while (self.binding_scheme_classification_stack.pop()) |pending_var| {
        const resolved = self.types.resolveVar(pending_var);
        if (resolved.desc.rank == .generalized) return true;
        const seen = try self.binding_scheme_classification_seen.getOrPut(self.gpa, resolved.var_);
        if (seen.found_existing) continue;

        switch (resolved.desc.content) {
            .err, .field_presence => {},
            .flex, .rigid => {},
            .alias => |alias| try self.binding_scheme_classification_stack.appendSlice(
                self.gpa,
                self.types.sliceAliasArgs(alias),
            ),
            .structure => |flat| switch (flat) {
                .empty_record, .empty_tag_union => {},
                .tuple => |tuple| try self.binding_scheme_classification_stack.appendSlice(
                    self.gpa,
                    self.types.sliceVars(tuple.elems),
                ),
                .nominal_type => |nominal| try self.binding_scheme_classification_stack.appendSlice(
                    self.gpa,
                    self.types.sliceNominalArgs(nominal),
                ),
                .fn_pure, .fn_effectful, .fn_unbound => |func| {
                    try self.binding_scheme_classification_stack.appendSlice(self.gpa, self.types.sliceVars(func.args));
                    try self.binding_scheme_classification_stack.append(self.gpa, func.ret);
                    try self.binding_scheme_classification_stack.appendSlice(self.gpa, self.types.sliceVars(func.effect_deps));
                },
                .record => |record| {
                    const presences = self.types.getRecordFieldsSlice(record.fields).items(.presence);
                    for (presences) |presence| {
                        try self.binding_scheme_classification_stack.append(self.gpa, presence.typeVar());
                        if (presence.presenceVar()) |presence_var| {
                            try self.binding_scheme_classification_stack.append(self.gpa, presence_var);
                        }
                    }
                    try self.binding_scheme_classification_stack.append(self.gpa, record.ext);
                },
                .record_unbound => |fields_range| {
                    const presences = self.types.getRecordFieldsSlice(fields_range).items(.presence);
                    for (presences) |presence| {
                        try self.binding_scheme_classification_stack.append(self.gpa, presence.typeVar());
                        if (presence.presenceVar()) |presence_var| {
                            try self.binding_scheme_classification_stack.append(self.gpa, presence_var);
                        }
                    }
                },
                .tag_union => |tag_union| {
                    const tag_args = self.types.getTagsSlice(tag_union.tags).items(.args);
                    for (tag_args) |args| {
                        try self.binding_scheme_classification_stack.appendSlice(self.gpa, self.types.sliceVars(args));
                    }
                    try self.binding_scheme_classification_stack.append(self.gpa, tag_union.ext);
                },
            },
        }
    }
    return false;
}

fn publishBindingScheme(self: *Self, root_var: Var) Allocator.Error!void {
    if (try self.typeHasGeneralizedVar(root_var)) {
        try self.markBindingSchemeVar(root_var);
    }
}

const OutputRowDraft = struct {
    row_var: Var,
    tail_var: Var,
    written_tag_count: u32,
    position: types_mod.WhereMethodMarkerContract.Position,
    path_start: u32,
    path_len: u32,
};

/// Durable identity of one where-method constraint as written in this
/// ModuleEnv. The method component is the expanded method name, so an alias
/// reference is rebound to its enclosing source occurrence without depending
/// on the reusable alias declaration's constraint order. This key never
/// crosses ModuleEnv copying.
const SourceProducerKey = struct {
    owner_node: u32,
    where_node: u32,
    method_name: u32,

    fn fromContract(contract: types_mod.WhereMethodMarkerContract) @This() {
        if (!contract.hasProducer()) {
            std.debug.panic("flattened where-method marker has no local producer", .{});
        }
        return .{
            .owner_node = contract.producer_owner_node,
            .where_node = contract.producer_where_node,
            .method_name = contract.producer_method_name,
        };
    }

    fn fromUse(marker: ModuleEnv.WhereMethodMarkerUse) @This() {
        return .{
            .owner_node = marker.producer_owner_node,
            .where_node = marker.producer_where_node,
            .method_name = marker.producer_method_name,
        };
    }
};

const OutputRowVisit = struct {
    var_: Var,
    polarity: Polarity,
    position: types_mod.WhereMethodMarkerContract.Position,
    path_start: u32,
    path_len: u32,
    active_start: u32,
    active_len: u32,
};

const OutputFunctionKind = enum(u32) {
    pure,
    effectful,
    unbound,
};

fn outputPathWithStep(
    self: *Self,
    pool: *std.ArrayListUnmanaged(ModuleEnv.WhereMethodMarkerPathStep),
    start: u32,
    len: u32,
    step: ModuleEnv.WhereMethodMarkerPathStep,
) Allocator.Error!struct { start: u32, len: u32 } {
    const child_start: u32 = @intCast(pool.items.len);
    try pool.ensureUnusedCapacity(self.gpa, @as(usize, len) + 1);
    pool.appendSliceAssumeCapacity(pool.items[start..][0..len]);
    pool.appendAssumeCapacity(step);
    return .{ .start = child_start, .len = len + 1 };
}

fn outputActiveWithVar(
    self: *Self,
    pool: *std.ArrayListUnmanaged(Var),
    start: u32,
    len: u32,
    var_: Var,
) Allocator.Error!struct { start: u32, len: u32 } {
    const child_start: u32 = @intCast(pool.items.len);
    try pool.ensureUnusedCapacity(self.gpa, @as(usize, len) + 1);
    pool.appendSliceAssumeCapacity(pool.items[start..][0..len]);
    pool.appendAssumeCapacity(var_);
    return .{ .start = child_start, .len = len + 1 };
}

fn outputPathStep(
    kind: ModuleEnv.WhereMethodMarkerPathStep.Kind,
    index: u32,
    arity: u32,
    name: u32,
    origin_module: u32,
    source_decl: u32,
) ModuleEnv.WhereMethodMarkerPathStep {
    return .{
        .kind = @intFromEnum(kind),
        .index = index,
        .arity = arity,
        .name = name,
        .origin_module = origin_module,
        .source_decl = source_decl,
    };
}

fn outputFunctionKind(flat: FlatType) ?OutputFunctionKind {
    return switch (flat) {
        .fn_pure => .pure,
        .fn_effectful => .effectful,
        .fn_unbound => .unbound,
        .empty_record, .empty_tag_union, .tuple, .nominal_type, .record, .record_unbound, .tag_union => null,
    };
}

fn compareOutputPathSteps(
    a: anytype,
    b: anytype,
) std.math.Order {
    return types_mod.compareWhereMethodMarkerPathSlices(a, b);
}

const OutputRowSortContext = struct {
    paths: []const ModuleEnv.WhereMethodMarkerPathStep,

    fn lessThan(ctx: @This(), a: OutputRowDraft, b: OutputRowDraft) bool {
        return compareOutputPathSteps(
            ctx.paths[a.path_start..][0..a.path_len],
            ctx.paths[b.path_start..][0..b.path_len],
        ) == .lt;
    }
};

/// Enumerate every positive tag row by an explicit semantic position. Alias
/// wrappers and row-extension storage are transparent. A shared acyclic node
/// is visited once per occurrence; only a node already on the current branch
/// stops descent, so distinct occurrences never collapse through a global
/// visited set.
fn enumerateOutputRows(
    self: *Self,
    root_var: Var,
    marker_rows_only: bool,
    rows: *std.ArrayListUnmanaged(OutputRowDraft),
    paths: *std.ArrayListUnmanaged(ModuleEnv.WhereMethodMarkerPathStep),
) Allocator.Error!void {
    rows.clearRetainingCapacity();
    paths.clearRetainingCapacity();
    var visits: std.ArrayListUnmanaged(OutputRowVisit) = .empty;
    defer visits.deinit(self.gpa);
    var active_pool: std.ArrayListUnmanaged(Var) = .empty;
    defer active_pool.deinit(self.gpa);

    try visits.append(self.gpa, .{
        .var_ = root_var,
        .polarity = .pos,
        .position = .nested,
        .path_start = 0,
        .path_len = 0,
        .active_start = 0,
        .active_len = 0,
    });

    while (visits.pop()) |visit| {
        const resolved = self.types.resolveVar(visit.var_);
        var cyclic = false;
        for (active_pool.items[visit.active_start..][0..visit.active_len]) |active| {
            if (active == resolved.var_) {
                cyclic = true;
                break;
            }
        }
        if (cyclic) continue;
        const child_active = try self.outputActiveWithVar(
            &active_pool,
            visit.active_start,
            visit.active_len,
            resolved.var_,
        );

        switch (resolved.desc.content) {
            .flex, .rigid, .field_presence, .err => {},
            .alias => |alias| {
                try visits.append(self.gpa, .{
                    .var_ = self.types.getAliasBackingVar(alias),
                    .polarity = visit.polarity,
                    .position = visit.position,
                    .path_start = visit.path_start,
                    .path_len = visit.path_len,
                    .active_start = child_active.start,
                    .active_len = child_active.len,
                });
            },
            .structure => |flat| switch (flat) {
                .empty_record => {},
                .empty_tag_union => if (!marker_rows_only and visit.polarity == .pos) {
                    try rows.append(self.gpa, .{
                        .row_var = resolved.var_,
                        .tail_var = resolved.var_,
                        .written_tag_count = 0,
                        .position = visit.position,
                        .path_start = visit.path_start,
                        .path_len = visit.path_len,
                    });
                },
                .tuple => |tuple| {
                    const elems = self.types.sliceVars(tuple.elems);
                    for (elems, 0..) |elem, index| {
                        const child_path = try self.outputPathWithStep(paths, visit.path_start, visit.path_len, outputPathStep(
                            .tuple_elem,
                            @intCast(index),
                            @intCast(elems.len),
                            0,
                            0,
                            0,
                        ));
                        try visits.append(self.gpa, .{
                            .var_ = elem,
                            .polarity = visit.polarity,
                            .position = .nested,
                            .path_start = child_path.start,
                            .path_len = child_path.len,
                            .active_start = child_active.start,
                            .active_len = child_active.len,
                        });
                    }
                },
                .nominal_type => |nominal| {
                    const args = self.types.sliceNominalArgs(nominal);
                    const decl_idx = self.types.lookupNominalDecl(nominal) orelse
                        std.debug.panic("output-row nominal application had no declaration entry", .{});
                    const decl = self.types.getNominalDecl(decl_idx);
                    if (decl.origin_module != nominal.origin_module or
                        !decl.source.sourceDecl().eql(nominal.sourceDecl()) or
                        decl.formals.len() != args.len)
                    {
                        std.debug.panic("output-row nominal declaration did not match its application", .{});
                    }
                    const builtin_try = self.nominalIsBuiltinTryType(nominal);
                    for (args, 0..) |arg, index| {
                        const child_path = try self.outputPathWithStep(paths, visit.path_start, visit.path_len, outputPathStep(
                            .nominal_arg,
                            @intCast(index),
                            @intCast(args.len),
                            @bitCast(decl.ident.ident_idx),
                            @intFromEnum(nominal.origin_module),
                            @bitCast(nominal.sourceDecl()),
                        ));
                        const position: types_mod.WhereMethodMarkerContract.Position = if (visit.position == .direct and builtin_try and index == 0)
                            .try_ok
                        else if (visit.position == .direct and builtin_try and index == 1)
                            .try_err
                        else
                            .nested;
                        try visits.append(self.gpa, .{
                            .var_ = arg,
                            .polarity = visit.polarity,
                            .position = position,
                            .path_start = child_path.start,
                            .path_len = child_path.len,
                            .active_start = child_active.start,
                            .active_len = child_active.len,
                        });
                    }
                },
                .fn_pure, .fn_effectful, .fn_unbound => |func| {
                    const fn_kind = outputFunctionKind(flat).?;
                    const args = self.types.sliceVars(func.args);
                    for (args, 0..) |arg, index| {
                        const child_path = try self.outputPathWithStep(paths, visit.path_start, visit.path_len, outputPathStep(
                            .fn_arg,
                            @intCast(index),
                            @intCast(args.len),
                            @intFromEnum(fn_kind),
                            0,
                            0,
                        ));
                        try visits.append(self.gpa, .{
                            .var_ = arg,
                            .polarity = visit.polarity.flip(),
                            .position = .nested,
                            .path_start = child_path.start,
                            .path_len = child_path.len,
                            .active_start = child_active.start,
                            .active_len = child_active.len,
                        });
                    }
                    const ret_path = try self.outputPathWithStep(paths, visit.path_start, visit.path_len, outputPathStep(
                        .fn_ret,
                        0,
                        @intCast(args.len),
                        @intFromEnum(fn_kind),
                        0,
                        0,
                    ));
                    try visits.append(self.gpa, .{
                        .var_ = func.ret,
                        .polarity = visit.polarity,
                        .position = if (visit.path_len == 0) .direct else .nested,
                        .path_start = ret_path.start,
                        .path_len = ret_path.len,
                        .active_start = child_active.start,
                        .active_len = child_active.len,
                    });
                },
                .record, .record_unbound => {
                    var fields: std.ArrayListUnmanaged(DispatchRecordField) = .empty;
                    defer fields.deinit(self.gpa);
                    _ = try self.dispatchCollectRecordRow(resolved.var_, &fields);
                    for (fields.items) |field| {
                        const child_path = try self.outputPathWithStep(paths, visit.path_start, visit.path_len, outputPathStep(
                            .record_field,
                            0,
                            0,
                            @bitCast(field.name),
                            0,
                            0,
                        ));
                        try visits.append(self.gpa, .{
                            .var_ = field.presence.typeVar(),
                            .polarity = visit.polarity,
                            .position = .nested,
                            .path_start = child_path.start,
                            .path_len = child_path.len,
                            .active_start = child_active.start,
                            .active_len = child_active.len,
                        });
                    }
                },
                .tag_union => {
                    var tags: std.ArrayListUnmanaged(DispatchUnionTag) = .empty;
                    defer tags.deinit(self.gpa);
                    const tail = try self.dispatchCollectTagRow(resolved.var_, &tags);
                    const tail_is_marker = tail.kind == .open and blk: {
                        const tail_content = self.types.resolveVar(tail.var_).desc.content;
                        break :blk tail_content == .rigid and tail_content.rigid.name.eql(self.cir.idents.polarity_var);
                    };
                    if (visit.polarity == .pos and (!marker_rows_only or tail_is_marker)) {
                        try rows.append(self.gpa, .{
                            .row_var = resolved.var_,
                            .tail_var = tail.var_,
                            .written_tag_count = @intCast(tags.items.len),
                            .position = visit.position,
                            .path_start = visit.path_start,
                            .path_len = visit.path_len,
                        });
                    }
                    for (tags.items) |tag| {
                        const args = self.types.sliceVars(tag.args);
                        for (args, 0..) |arg, index| {
                            const child_path = try self.outputPathWithStep(paths, visit.path_start, visit.path_len, outputPathStep(
                                .tag_payload,
                                @intCast(index),
                                @intCast(args.len),
                                @bitCast(tag.name),
                                0,
                                0,
                            ));
                            try visits.append(self.gpa, .{
                                .var_ = arg,
                                .polarity = visit.polarity,
                                .position = .nested,
                                .path_start = child_path.start,
                                .path_len = child_path.len,
                                .active_start = child_active.start,
                                .active_len = child_active.len,
                            });
                        }
                    }
                },
            },
        }
    }

    std.mem.sort(OutputRowDraft, rows.items, OutputRowSortContext{ .paths = paths.items }, OutputRowSortContext.lessThan);
    for (rows.items, 0..) |row, index| {
        if (index == 0) continue;
        const previous = rows.items[index - 1];
        const previous_path = paths.items[previous.path_start..][0..previous.path_len];
        const row_path = paths.items[row.path_start..][0..row.path_len];
        if (compareOutputPathSteps(previous_path, row_path) == .eq and
            !types_mod.whereMethodMarkerNominalNamesMatch(previous_path, row_path))
        {
            std.debug.panic("equal output-row paths carried different nominal declaration names", .{});
        }
        if (compareOutputPathSteps(previous_path, row_path) == .eq and
            self.types.resolveVar(previous.row_var).var_ != self.types.resolveVar(row.row_var).var_)
        {
            std.debug.panic("one output-row position named two distinct rows", .{});
        }
    }
}

fn methodOutputBindingLessThan(
    _: void,
    a: ModuleEnv.MethodBinding,
    b: ModuleEnv.MethodBinding,
) bool {
    const a_type = @intFromEnum(a.type_node_idx);
    const b_type = @intFromEnum(b.type_node_idx);
    if (a_type != b_type) return a_type < b_type;
    return @intFromEnum(a.def_idx) < @intFromEnum(b.def_idx);
}

/// Publish the complete positive-output-row inventory for every distinct
/// callable method binding. All allocations and semantic validation happen
/// off-side; the three durable pools change only at the final infallible swap.
fn finalizeMethodOutputPublications(self: *Self) Allocator.Error!void {
    if (self.probe_depth != 0) {
        @panic("method-output publication cannot run under a checker probe");
    }

    var bindings: std.ArrayListUnmanaged(ModuleEnv.MethodBinding) = .empty;
    defer bindings.deinit(self.gpa);
    try bindings.ensureTotalCapacity(self.gpa, self.cir.method_defs.entries.items.len);
    for (self.cir.method_defs.entries.items, 0..) |entry, entry_index| {
        const binding = entry.value;
        const type_node_idx = @intFromEnum(binding.type_node_idx);
        const def_idx = @intFromEnum(binding.def_idx);
        if (type_node_idx >= self.types.len() or type_node_idx >= self.cir.store.nodes.len() or
            def_idx >= self.cir.store.nodes.len() or !self.cir.store.isDefNode(def_idx))
        {
            @panic("method-output registry contained an invalid binding coordinate");
        }

        var duplicate = false;
        for (self.cir.method_defs.entries.items[0..entry_index]) |previous_entry| {
            const previous = previous_entry.value;
            if (previous.type_node_idx == binding.type_node_idx and
                previous.def_idx != binding.def_idx)
            {
                @panic("one method-output type node named two definitions");
            }
            if (methodOutputBindingsEqual(previous, binding)) duplicate = true;
        }
        if (!duplicate) bindings.appendAssumeCapacity(binding);
    }
    std.mem.sortUnstable(
        ModuleEnv.MethodBinding,
        bindings.items,
        {},
        methodOutputBindingLessThan,
    );

    var replacement_publications = try ModuleEnv.MethodOutputPublication.SafeList.initCapacity(
        self.cir.gpa,
        bindings.items.len,
    );
    defer replacement_publications.deinit(self.cir.gpa);
    var replacement_paths = try ModuleEnv.WhereMethodMarkerPathStep.SafeList.initCapacity(
        self.cir.gpa,
        self.cir.method_output_row_path_steps.items.items.len,
    );
    defer replacement_paths.deinit(self.cir.gpa);
    var replacement_rows = try ModuleEnv.MethodOutputRow.SafeList.initCapacity(
        self.cir.gpa,
        self.cir.method_output_rows.items.items.len,
    );
    defer replacement_rows.deinit(self.cir.gpa);

    var rows: std.ArrayListUnmanaged(OutputRowDraft) = .empty;
    defer rows.deinit(self.gpa);
    var paths: std.ArrayListUnmanaged(ModuleEnv.WhereMethodMarkerPathStep) = .empty;
    defer paths.deinit(self.gpa);

    for (bindings.items) |binding| {
        const root = ModuleEnv.varFrom(binding.type_node_idx);
        if (!methodOutputRootIsFunction(self.types, root)) continue;

        try self.enumerateOutputRows(root, false, &rows, &paths);
        const rows_start = std.math.cast(
            u32,
            replacement_rows.items.items.len,
        ) orelse return error.OutOfMemory;
        var rows_len: u32 = 0;
        var previous_row: ?OutputRowDraft = null;
        for (rows.items) |row| {
            if (row.path_len == 0 or !rangeFits(row.path_start, row.path_len, paths.items.len)) {
                @panic("method-output producer enumerated an invalid row path");
            }
            if (previous_row) |previous| {
                const previous_path = paths.items[previous.path_start..][0..previous.path_len];
                const row_path = paths.items[row.path_start..][0..row.path_len];
                const order = compareOutputPathSteps(previous_path, row_path);
                if (order == .gt) {
                    @panic("method-output producer enumerated noncanonical row paths");
                }
                if (order == .eq) {
                    if (!types_mod.whereMethodMarkerNominalNamesMatch(previous_path, row_path) or
                        self.types.resolveVar(previous.row_var).var_ != self.types.resolveVar(row.row_var).var_ or
                        self.types.resolveVar(previous.tail_var).var_ != self.types.resolveVar(row.tail_var).var_ or
                        previous.position != row.position)
                    {
                        @panic("one method-output path named incompatible rows");
                    }
                    continue;
                }
            }

            const path_start = std.math.cast(
                u32,
                replacement_paths.items.items.len,
            ) orelse return error.OutOfMemory;
            _ = try replacement_paths.appendSlice(
                self.cir.gpa,
                paths.items[row.path_start..][0..row.path_len],
            );
            _ = try replacement_rows.append(self.cir.gpa, .{
                .row_var = @intFromEnum(row.row_var),
                .tail_var = @intFromEnum(row.tail_var),
                .position = @intFromEnum(row.position),
                .path_start = path_start,
                .path_len = row.path_len,
            });
            rows_len = std.math.add(u32, rows_len, 1) catch return error.OutOfMemory;
            previous_row = row;
        }

        _ = try replacement_publications.append(self.cir.gpa, .{
            .type_node_idx = @intFromEnum(binding.type_node_idx),
            .rows_start = rows_start,
            .rows_len = rows_len,
        });
    }

    const try_identity = methodOutputTryIdentity(
        self.builtin_ctx,
        self.builtin_origin_identity,
    );
    if (!methodOutputSlicesAreValid(
        try_identity,
        self.cir.store.nodes.len(),
        self.types.len(),
        replacement_publications.items.items,
        replacement_rows.items.items,
        replacement_paths.items.items,
    )) {
        @panic("method-output producer built an invalid canonical publication");
    }
    if (!methodOutputPublicationsMatchRegistry(
        self.types,
        self.cir,
        replacement_publications.items.items,
    )) {
        @panic("method-output producer built an incomplete registry projection");
    }
    for (replacement_paths.items.items) |step| {
        if (!whereMethodPathStepNameIsCanonical(self.types, self.cir, step)) {
            @panic("method-output producer built a noncanonical named path");
        }
    }

    // Every allocation and validation is complete. These swaps are the sole
    // publication boundary; deferred cleanup destroys the displaced pools.
    std.mem.swap(
        ModuleEnv.MethodOutputPublication.SafeList,
        &self.cir.method_output_publications,
        &replacement_publications,
    );
    std.mem.swap(
        ModuleEnv.WhereMethodMarkerPathStep.SafeList,
        &self.cir.method_output_row_path_steps,
        &replacement_paths,
    );
    std.mem.swap(
        ModuleEnv.MethodOutputRow.SafeList,
        &self.cir.method_output_rows,
        &replacement_rows,
    );
}

/// Attach the immutable path certificates for one exact where-method source
/// occurrence. Row identities are deliberately not stored here: a body-use
/// instantiation records its own source/fresh rows, and a selected method
/// target records its own checked rows. Reusable where-alias declarations
/// pass no producer and therefore remain metadata-free until each reference
/// rebinds them to its enclosing annotation.
fn makeWhereMethodMarkerContracts(
    self: *Self,
    signature_var: Var,
    producer_owner_node: u32,
    producer_where_node: u32,
    producer_method_name: u32,
) Allocator.Error!types_mod.WhereMethodMarkerContract.SafeList.Range {
    if (producer_owner_node == std.math.maxInt(u32)) return .empty();

    var rows: std.ArrayListUnmanaged(OutputRowDraft) = .empty;
    defer rows.deinit(self.gpa);
    var paths: std.ArrayListUnmanaged(ModuleEnv.WhereMethodMarkerPathStep) = .empty;
    defer paths.deinit(self.gpa);
    try self.enumerateOutputRows(signature_var, true, &rows, &paths);

    var durable_paths: std.ArrayListUnmanaged(ModuleEnv.WhereMethodMarkerPathStep) = .empty;
    defer durable_paths.deinit(self.gpa);
    var durable_contracts: std.ArrayListUnmanaged(types_mod.WhereMethodMarkerContract) = .empty;
    defer durable_contracts.deinit(self.gpa);
    var path_count: usize = 0;
    for (rows.items) |row| path_count += row.path_len;
    try durable_paths.ensureTotalCapacity(self.gpa, path_count);
    try durable_contracts.ensureTotalCapacity(self.gpa, rows.items.len);
    for (rows.items) |row| {
        const local_path_start: u32 = @intCast(durable_paths.items.len);
        durable_paths.appendSliceAssumeCapacity(paths.items[row.path_start..][0..row.path_len]);
        durable_contracts.appendAssumeCapacity(.{
            .producer_owner_node = producer_owner_node,
            .producer_where_node = producer_where_node,
            .producer_method_name = producer_method_name,
            .position = @intFromEnum(row.position),
            .widened = 0,
            .ready = 0,
            .path_start = local_path_start,
            .path_len = row.path_len,
        });
    }

    const path_base: u32 = @intCast(self.types.where_method_marker_path_steps.items.items.len);
    const contract_base: u32 = @intCast(self.types.where_method_marker_contracts.items.items.len);
    // Reserve both durable pools before changing either one. An allocation
    // failure cannot leave path entries without the contract range that owns
    // them.
    try self.types.where_method_marker_path_steps.items.ensureUnusedCapacity(self.gpa, durable_paths.items.len);
    try self.types.where_method_marker_contracts.items.ensureUnusedCapacity(self.gpa, durable_contracts.items.len);
    for (durable_paths.items) |path| {
        self.types.where_method_marker_path_steps.items.appendAssumeCapacity(.{
            .kind = path.kind,
            .index = path.index,
            .arity = path.arity,
            .name = path.name,
            .origin_module = path.origin_module,
            .source_decl = path.source_decl,
        });
    }

    for (durable_contracts.items) |contract| {
        var rebased = contract;
        rebased.path_start += path_base;
        self.types.where_method_marker_contracts.items.appendAssumeCapacity(rebased);
    }
    return .{ .start = @enumFromInt(contract_base), .count = @intCast(durable_contracts.items.len) };
}

fn compareWhereMethodMarkerContracts(
    self: *const Self,
    a: types_mod.WhereMethodMarkerContract,
    b: types_mod.WhereMethodMarkerContract,
) std.math.Order {
    return self.types.compareWhereMethodMarkerContracts(a, b);
}

fn mergeWhereMethodMarkerMetadata(
    self: *Self,
    a: types_mod.WhereMethodMarkerMetadata,
    b: types_mod.WhereMethodMarkerMetadata,
) Allocator.Error!types_mod.WhereMethodMarkerMetadata {
    return try self.types.mergeWhereMethodMarkerMetadata(a, b);
}

const PendingWhereMarkerConstraintMove = struct {
    source_constraint_index: u32,
    destination_constraint_index: u32,
    offsets: []const u32,
};

/// Commit one complete batch of constraint-metadata movement evidence. Source
/// occurrences remain immutable; these maps only prove how their marker
/// offsets contributed to newly appended destination occurrences.
fn appendWhereMarkerConstraintMoves(
    self: *Self,
    pending: []const PendingWhereMarkerConstraintMove,
) Allocator.Error!void {
    var unique_count: usize = 0;
    var total_offsets: usize = 0;
    for (pending, 0..) |move, move_index| {
        if (move.source_constraint_index >= self.types.static_dispatch_constraints.items.items.len or
            move.destination_constraint_index >= self.types.static_dispatch_constraints.items.items.len)
        {
            @panic("where-marker constraint movement named an absent constraint occurrence");
        }
        const source = self.types.static_dispatch_constraints.items.items[move.source_constraint_index];
        const destination = self.types.static_dispatch_constraints.items.items[move.destination_constraint_index];
        if (move.offsets.len == 0 or move.offsets.len != source.where_method_markers.len()) {
            @panic("where-marker constraint movement was not total over its source range");
        }
        for (move.offsets) |offset| {
            if (offset >= destination.where_method_markers.len()) {
                @panic("where-marker constraint movement named an out-of-range destination offset");
            }
        }

        const duplicate = for (pending[0..move_index]) |earlier| {
            if (earlier.source_constraint_index != move.source_constraint_index or
                earlier.destination_constraint_index != move.destination_constraint_index)
            {
                continue;
            }
            if (!std.mem.eql(u32, earlier.offsets, move.offsets)) {
                @panic("one constraint movement carried two distinct offset maps");
            }
            break true;
        } else false;
        if (duplicate) continue;
        unique_count += 1;
        total_offsets = std.math.add(usize, total_offsets, move.offsets.len) catch
            @panic("where-marker constraint movement offset count overflowed usize");
    }

    try self.cir.where_marker_constraint_moves.items.ensureUnusedCapacity(
        self.cir.gpa,
        unique_count,
    );
    try self.cir.where_marker_constraint_move_offsets.items.ensureUnusedCapacity(
        self.cir.gpa,
        total_offsets,
    );
    for (pending, 0..) |move, move_index| {
        const duplicate = for (pending[0..move_index]) |earlier| {
            if (earlier.source_constraint_index == move.source_constraint_index and
                earlier.destination_constraint_index == move.destination_constraint_index)
            {
                break true;
            }
        } else false;
        if (duplicate) continue;
        const offsets_start: u32 = @intCast(self.cir.where_marker_constraint_move_offsets.items.items.len);
        self.cir.where_marker_constraint_move_offsets.items.appendSliceAssumeCapacity(move.offsets);
        self.cir.where_marker_constraint_moves.items.appendAssumeCapacity(.{
            .source_constraint_index = move.source_constraint_index,
            .destination_constraint_index = move.destination_constraint_index,
            .offsets_start = offsets_start,
            .offsets_len = @intCast(move.offsets.len),
        });
    }
}

fn appendWhereMarkerConstraintIdentityMove(
    self: *Self,
    source_constraint_index: u32,
    destination_constraint_index: u32,
) Allocator.Error!void {
    const source = self.types.static_dispatch_constraints.items.items[source_constraint_index];
    const marker_len = source.where_method_markers.len();
    if (marker_len == 0) return;
    const offsets = try self.gpa.alloc(u32, marker_len);
    defer self.gpa.free(offsets);
    for (offsets, 0..) |*offset, index| offset.* = @intCast(index);
    try self.appendWhereMarkerConstraintMoves(&.{.{
        .source_constraint_index = source_constraint_index,
        .destination_constraint_index = destination_constraint_index,
        .offsets = offsets,
    }});
}

/// Publish marker-independent tagged evidence movement for one freshly
/// appended destination occurrence. The destination must carry exactly the
/// canonical union of every source handle, and every distinct source
/// occurrence contributes one row per handle even when two sources share it.
fn appendConstraintEvidenceMoves(
    self: *Self,
    source_constraint_indices: []const u32,
    destination_constraint_index: u32,
) Allocator.Error!void {
    if (destination_constraint_index >= self.types.static_dispatch_constraints.items.items.len) {
        @panic("constraint-evidence movement named an absent destination constraint");
    }

    var expected_handles: std.ArrayListUnmanaged(types_mod.ConstraintEvidenceHandle) = .empty;
    defer expected_handles.deinit(self.gpa);
    for (source_constraint_indices, 0..) |source_constraint_index, source_ordinal| {
        if (source_constraint_index >= destination_constraint_index) {
            @panic("constraint-evidence movement was not append-chronological");
        }
        const repeated_source = for (source_constraint_indices[0..source_ordinal]) |earlier| {
            if (earlier == source_constraint_index) break true;
        } else false;
        if (repeated_source) continue;
        const source = self.types.static_dispatch_constraints.items.items[source_constraint_index];
        try expected_handles.appendSlice(
            self.gpa,
            self.types.sliceConstraintEvidenceHandles(source.constraint_evidence),
        );
    }
    std.mem.sortUnstable(
        types_mod.ConstraintEvidenceHandle,
        expected_handles.items,
        {},
        types_mod.ConstraintEvidenceHandle.canonicalLessThan,
    );
    var write: usize = 0;
    for (expected_handles.items) |handle| {
        if (write != 0 and types_mod.ConstraintEvidenceHandle.eql(expected_handles.items[write - 1], handle)) continue;
        expected_handles.items[write] = handle;
        write += 1;
    }
    expected_handles.items.len = write;

    const destination = self.types.static_dispatch_constraints.items.items[destination_constraint_index];
    const destination_handles = self.types.sliceConstraintEvidenceHandles(
        destination.constraint_evidence,
    );
    if (expected_handles.items.len != destination_handles.len) {
        @panic("constraint-evidence destination did not carry its complete contributor handle set");
    }
    for (expected_handles.items, destination_handles) |expected, actual| {
        if (!types_mod.ConstraintEvidenceHandle.eql(expected, actual)) {
            @panic("constraint-evidence destination did not carry its complete contributor handle set");
        }
    }

    var transition_count: usize = 0;
    for (source_constraint_indices, 0..) |source_constraint_index, source_ordinal| {
        const repeated_source = for (source_constraint_indices[0..source_ordinal]) |earlier| {
            if (earlier == source_constraint_index) break true;
        } else false;
        if (repeated_source) continue;
        const source = self.types.static_dispatch_constraints.items.items[source_constraint_index];
        transition_count += self.types.sliceConstraintEvidenceHandles(
            source.constraint_evidence,
        ).len;
    }
    try self.cir.constraint_evidence_moves.items.ensureUnusedCapacity(
        self.cir.gpa,
        transition_count,
    );
    for (source_constraint_indices, 0..) |source_constraint_index, source_ordinal| {
        const repeated_source = for (source_constraint_indices[0..source_ordinal]) |earlier| {
            if (earlier == source_constraint_index) break true;
        } else false;
        if (repeated_source) continue;
        const source = self.types.static_dispatch_constraints.items.items[source_constraint_index];
        for (self.types.sliceConstraintEvidenceHandles(source.constraint_evidence)) |handle| {
            if (handle.decodedKind() == null) {
                @panic("constraint-evidence movement named an invalid handle kind");
            }
            for (self.cir.constraint_evidence_moves.items.items) |existing| {
                if (types_mod.ConstraintEvidenceHandle.eql(existing.handle, handle) and
                    existing.source_constraint_index == source_constraint_index and
                    existing.destination_constraint_index == destination_constraint_index)
                {
                    @panic("constraint-evidence movement repeated an exact producer transition");
                }
            }
            self.cir.constraint_evidence_moves.items.appendAssumeCapacity(.{
                .handle = handle,
                .source_constraint_index = source_constraint_index,
                .destination_constraint_index = destination_constraint_index,
            });
        }
    }
}

fn markerUsePathMatchesContract(
    self: *const Self,
    marker: ModuleEnv.WhereMethodMarkerUse,
    contract: types_mod.WhereMethodMarkerContract,
) bool {
    const use_steps = self.cir.where_method_marker_path_steps.items.items[marker.path_start..][0..marker.path_len];
    const contract_steps = self.types.where_method_marker_path_steps.items.items[contract.path_start..][0..contract.path_len];
    if (use_steps.len != contract_steps.len) return false;
    for (use_steps, contract_steps) |use_step, contract_step| {
        inline for (.{ "kind", "index", "arity", "name", "origin_module", "source_decl" }) |field| {
            if (@field(use_step, field) != @field(contract_step, field)) return false;
        }
    }
    return true;
}

fn whereMethodMarkerUseWidened(
    self: *Self,
    marker: ModuleEnv.WhereMethodMarkerUse,
) Allocator.Error!bool {
    if (self.types.resolveVar(@enumFromInt(marker.fresh_row_var)).desc.content == .err) return false;
    var tags: std.ArrayListUnmanaged(DispatchUnionTag) = .empty;
    defer tags.deinit(self.gpa);
    const tail = try self.dispatchCollectTagRow(@enumFromInt(marker.fresh_row_var), &tags);
    if (self.types.resolveVar(tail.var_).desc.content == .err) return false;
    // An unused/open marker still denotes exactly the written row at this
    // body-use boundary. Only concrete tags absorbed beyond the written list
    // establish widening authority.
    return tags.items.len > marker.written_tag_count;
}

const PendingWhereMethodMarkerFact = struct {
    contract_index: u32,
    widened: bool,
    written_tag_count: ?u32 = null,
};

fn pendingWhereMethodFactForContract(
    self: *const Self,
    pending: []PendingWhereMethodMarkerFact,
    contract: types_mod.WhereMethodMarkerContract,
) ?usize {
    const producer = SourceProducerKey.fromContract(contract);
    for (pending, 0..) |fact, fact_index| {
        const existing = self.types.where_method_marker_contracts.items.items[fact.contract_index];
        if (!std.meta.eql(SourceProducerKey.fromContract(existing), producer)) continue;
        if (self.compareWhereMethodMarkerPathsOnly(existing, contract) != .eq) continue;
        if (existing.position != contract.position) {
            std.debug.panic("one where-method producer path had incompatible position classes", .{});
        }
        return fact_index;
    }
    return null;
}

/// `design.md`'s `finalizeWhereMethodWideningContract` rewrite. This runs only
/// after the enclosing body has reached dispatch/effect quiescence. It reads
/// the exact source/fresh row pairs recorded by the instantiator, then stamps
/// every central producer/path ref. It never inspects a callable to recover a
/// path and never runs under a speculative probe.
fn finalizeWhereMethodWideningForOwner(
    self: *Self,
    owner_node: u32,
) Allocator.Error!void {
    if (self.probe_depth != 0) {
        @panic("where-method widening finalization cannot run under a checker probe");
    }

    // Compute one central fact per exact source producer/path before mutating
    // the producer pool. A marker contributes only through the containing
    // constraint whose callable is the marker record's exact scheme root;
    // key/path similarity alone is never authority. Tag-row collection
    // allocates, so committing one producer at a time would leave a partially
    // finalized owner if a later collection ran out of memory.
    var pending: std.ArrayListUnmanaged(PendingWhereMethodMarkerFact) = .empty;
    defer pending.deinit(self.gpa);
    for (self.types.static_dispatch_constraints.items.items) |constraint| {
        const constraint_root = self.types.resolveVar(constraint.fn_var).var_;
        for (self.types.sliceWhereMethodMarkerContracts(constraint.where_method_markers), 0..) |contract, range_index| {
            if (!contract.hasProducer() or contract.producer_owner_node != owner_node) continue;
            const contract_index: u32 = @intCast(@intFromEnum(constraint.where_method_markers.start) + range_index);
            const fact_index = self.pendingWhereMethodFactForContract(pending.items, contract) orelse blk: {
                try pending.append(self.gpa, .{
                    .contract_index = contract_index,
                    .widened = false,
                });
                break :blk pending.items.len - 1;
            };
            const fact = &pending.items[fact_index];
            const producer = SourceProducerKey.fromContract(contract);
            for (self.cir.scheme_uses.items.items) |record| {
                if (record.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.where_method_use) or
                    self.types.resolveVar(@enumFromInt(record.scheme_root)).var_ != constraint_root)
                {
                    continue;
                }
                for (self.cir.where_method_marker_uses.items.items[record.marker_uses_start..][0..record.marker_uses_len]) |marker| {
                    if (!std.meta.eql(SourceProducerKey.fromUse(marker), producer)) continue;
                    if (!self.markerUsePathMatchesContract(marker, contract)) continue;
                    if (marker.position != contract.position) {
                        std.debug.panic("one where-method producer path had incompatible position classes", .{});
                    }
                    if (fact.written_tag_count) |written| {
                        if (written != marker.written_tag_count) {
                            std.debug.panic("one where-method producer path had incompatible written rows", .{});
                        }
                    } else {
                        fact.written_tag_count = marker.written_tag_count;
                    }
                    fact.widened = fact.widened or try self.whereMethodMarkerUseWidened(marker);
                }
            }
        }
    }

    // Every copy of the stable producer/path ref consumes the same central
    // fact. This includes copies made before an annotated body settled.
    for (self.types.where_method_marker_contracts.items.items) |*contract| {
        if (!contract.hasProducer() or contract.producer_owner_node != owner_node) continue;
        const fact_index = self.pendingWhereMethodFactForContract(pending.items, contract.*) orelse
            std.debug.panic("where-method producer ref had no containing signature", .{});
        const fact = pending.items[fact_index];
        contract.ready = 1;
        contract.widened = @intFromBool(contract.isWidened().? or fact.widened);
    }
}

/// Rebuild the checked lowering authorization from exact durable body-use
/// witnesses after all producer facts are ready. This derived table contains
/// no nested-position facts and is validated before checked-module use.
fn resultRowWideningUseLessThan(
    _: void,
    a: ModuleEnv.ResultRowWideningUse,
    b: ModuleEnv.ResultRowWideningUse,
) bool {
    if (a.constraint_fn_var != b.constraint_fn_var) return a.constraint_fn_var < b.constraint_fn_var;
    return a.source_where_fn_var < b.source_where_fn_var;
}

fn collectResultRowWideningUses(
    self: *Self,
    pending: *std.ArrayListUnmanaged(ModuleEnv.ResultRowWideningUse),
) Allocator.Error!void {
    for (self.cir.scheme_uses.items.items) |record| {
        if (record.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.where_method_use)) continue;
        const constraint_fn_var: Var = @enumFromInt(record.slot_data);
        if (self.types.varStaticDispatchRejected(constraint_fn_var) or
            self.types.resolveVar(constraint_fn_var).desc.content == .err)
        {
            continue;
        }

        var widening: ModuleEnv.ResultRowWidening = .{};
        const markers = self.cir.where_method_marker_uses.items.items[record.marker_uses_start..][0..record.marker_uses_len];
        for (markers) |marker| {
            if (!try self.whereMethodMarkerUseWidened(marker)) continue;
            const position = std.enums.fromInt(types_mod.WhereMethodMarkerContract.Position, marker.position) orelse
                std.debug.panic("where-method marker use had invalid position", .{});
            switch (position) {
                .direct => widening.direct = true,
                .try_ok => widening.try_ok = true,
                .try_err => widening.try_err = true,
                .nested => {},
            }
        }
        if (widening.isEmpty()) continue;
        if (!widening.hasValidShape()) {
            std.debug.panic("one where-method use mixed direct and Try result-row widening", .{});
        }

        const existing = for (pending.items) |*candidate| {
            if (candidate.constraint_fn_var == record.slot_data and
                candidate.source_where_fn_var == record.slot_data)
            {
                break candidate;
            }
        } else null;
        if (existing) |candidate| {
            var merged = ModuleEnv.ResultRowWidening.fromBits(candidate.widening) orelse
                std.debug.panic("result-row widening authorization had invalid bits", .{});
            merged.merge(widening);
            candidate.widening = merged.bits();
        } else {
            try pending.append(self.gpa, .{
                .constraint_fn_var = record.slot_data,
                .source_where_fn_var = record.slot_data,
                .widening = widening.bits(),
            });
        }
    }
    std.mem.sort(
        ModuleEnv.ResultRowWideningUse,
        pending.items,
        {},
        resultRowWideningUseLessThan,
    );
}

fn finalizeWhereMethodWideningForAnnotation(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
) Allocator.Error!void {
    try self.finalizeWhereMethodWideningForOwner(@intFromEnum(annotation_idx));
}

fn compareWhereMethodMarkerPathsOnly(
    self: *const Self,
    a: types_mod.WhereMethodMarkerContract,
    b: types_mod.WhereMethodMarkerContract,
) std.math.Order {
    const all_steps = self.types.where_method_marker_path_steps.items.items;
    const a_steps = all_steps[a.path_start..][0..a.path_len];
    const b_steps = all_steps[b.path_start..][0..b.path_len];
    const order = types_mod.compareWhereMethodMarkerPathSlices(a_steps, b_steps);
    if (order == .eq and !types_mod.whereMethodMarkerNominalNamesMatch(a_steps, b_steps)) {
        std.debug.panic("equal where-method marker paths carried different nominal declaration names", .{});
    }
    return order;
}

fn whereAliasExpansionLessThan(
    _: void,
    a: ModuleEnv.WhereAliasExpansion,
    b: ModuleEnv.WhereAliasExpansion,
) bool {
    return compareWhereAliasExpansions(a, b) == .lt;
}

fn whereAliasDeclarationPublicationIndexLessThan(
    publications: []const ModuleEnv.WhereAliasDeclarationPublication,
    a: u32,
    b: u32,
) bool {
    const order = compareWhereAliasDeclarationPublications(publications[a], publications[b]);
    return if (order == .eq) a < b else order == .lt;
}

/// Canonicalize the declaration-authored alias expansion certificate. One
/// source clause can export many methods, but one declaration/clause/method
/// triple can be authored only once; duplicate rows are a producer invariant
/// violation rather than a winner-selection opportunity.
fn finalizeWhereAliasExpansions(self: *Self) Allocator.Error!void {
    if (self.probe_depth != 0) {
        @panic("where-alias expansion publication cannot run under a checker probe");
    }

    const publications = self.cir.where_alias_declaration_publications.items.items;
    const items = self.cir.where_alias_expansions.items.items;
    const failures = self.cir.expected_failures.items.items;
    const publication_order = try self.gpa.alloc(u32, publications.len);
    defer self.gpa.free(publication_order);
    const old_to_new = try self.gpa.alloc(u32, publications.len);
    defer self.gpa.free(old_to_new);
    const replacement_publications = try self.gpa.alloc(
        ModuleEnv.WhereAliasDeclarationPublication,
        publications.len,
    );
    defer self.gpa.free(replacement_publications);
    const replacement_items = try self.gpa.dupe(ModuleEnv.WhereAliasExpansion, items);
    defer self.gpa.free(replacement_items);

    for (publication_order, 0..) |*slot, index| slot.* = @intCast(index);
    @memset(old_to_new, std.math.maxInt(u32));
    std.mem.sort(
        ModuleEnv.WhereAliasExpansion,
        replacement_items,
        {},
        whereAliasExpansionLessThan,
    );
    if (replacement_items.len >= 2) {
        for (replacement_items[1..], 1..) |expansion, index| {
            if (compareWhereAliasExpansions(replacement_items[index - 1], expansion) != .lt) {
                @panic("one where-alias source expansion was published more than once");
            }
        }
    }

    std.mem.sort(
        u32,
        publication_order,
        publications,
        whereAliasDeclarationPublicationIndexLessThan,
    );
    var expansion_index: usize = 0;
    for (publication_order, 0..) |old_publication_index, new_publication_index| {
        var publication = publications[old_publication_index];
        if (new_publication_index != 0 and
            replacement_publications[new_publication_index - 1].decl_node == publication.decl_node)
        {
            @panic("one where-alias declaration was settled more than once");
        }
        const expansion_start = expansion_index;
        publication.expansions_start = @intCast(expansion_start);
        while (expansion_index < replacement_items.len and
            replacement_items[expansion_index].alias_decl_node == publication.decl_node)
        {
            expansion_index += 1;
        }
        publication.expansions_len = @intCast(expansion_index - expansion_start);
        switch (publication.decodedOutcome() orelse @panic("where-alias producer published invalid outcome")) {
            .ready => {},
            .checked_error => if (publication.dependency_rank != 0 or publication.expansions_len != 0) {
                @panic("checked-error where alias published rank or expansion rows");
            },
        }
        replacement_publications[new_publication_index] = publication;
        old_to_new[old_publication_index] = @intCast(new_publication_index);
    }
    if (expansion_index != replacement_items.len) {
        @panic("where-alias expansion row had no declaration settlement");
    }

    // Validate every local durable handle before the first mutation. Provider
    // handles live in a sealed dependency namespace and are deliberately not
    // interpreted through this module's relocation map.
    for (failures) |failure| {
        const direct = failure.subject_authority.decodedDirect() orelse continue;
        if (failure.subject_authority.decodedDirectPhase() !=
            ModuleEnv.SubjectAuthority.DirectPhase.annotation_local_where_alias_checked_error)
        {
            continue;
        }
        if (direct.local_record_index == ModuleEnv.SubjectAuthority.none) continue;
        if (direct.local_record_index >= old_to_new.len or
            old_to_new[direct.local_record_index] == std.math.maxInt(u32) or
            replacement_publications[old_to_new[direct.local_record_index]].decodedOutcome() != .checked_error)
        {
            @panic("local Expected-failure where-alias handle escaped publication relocation");
        }
    }

    @memcpy(items, replacement_items);
    @memcpy(publications, replacement_publications);
    for (failures) |*failure| {
        const direct = failure.subject_authority.decodedDirect() orelse continue;
        if (failure.subject_authority.decodedDirectPhase() !=
            ModuleEnv.SubjectAuthority.DirectPhase.annotation_local_where_alias_checked_error)
        {
            continue;
        }
        if (direct.local_record_index == ModuleEnv.SubjectAuthority.none) continue;
        failure.subject_authority.payload.direct.local_record_index =
            old_to_new[direct.local_record_index];
    }
}

const CheckedBoundaryConstraintRelocation = struct {
    new_constraint_index: u32 = std.math.maxInt(u32),
    marker_map_start: u32 = 0,
    old_marker_len: u32 = 0,
    new_marker_start: u32 = 0,
    new_marker_len: u32 = 0,

    fn retained(self: @This()) bool {
        return self.new_constraint_index != std.math.maxInt(u32);
    }
};

const ConstraintEvidenceNode = struct {
    handle: types_mod.ConstraintEvidenceHandle,
    constraint_index: u32,
};

const PendingCanonicalConstraintMove = struct {
    row: ModuleEnv.WhereMarkerConstraintMove,
    temporary_offsets_start: u32,
};

fn checkedBoundaryValidatedOwnerEnv(self: *const Self, expected: *const ModuleEnv) *const ModuleEnv {
    if (self.owner_modules.len != self.validated_owner_modules.len) {
        @panic("checked-boundary semantic-owner authority was not parallel");
    }
    var matches: usize = 0;
    for (self.owner_modules, self.validated_owner_modules) |env, capability| {
        if (env != expected) continue;
        const validated = capability.validate() catch
            @panic("checked-boundary semantic-owner capability was invalid");
        if (validated != env) {
            @panic("checked-boundary semantic-owner capability named another environment");
        }
        matches += 1;
    }
    if (matches != 1) {
        @panic("checked-boundary marker copy did not name exactly one semantic owner");
    }
    return expected;
}

/// Recover the exact provider pointer from the sealed durable typed-origin
/// authority shared by first publication, repeated publication, and checked
/// admission. Transient checker caches are never provider authority.
fn checkedBoundaryCrossStepProvider(
    self: *const Self,
    steps: []const ModuleEnv.WhereMarkerCopyStep,
    step_index: u32,
) *const ModuleEnv {
    if (step_index >= steps.len) {
        @panic("checked-boundary marker-copy provider step was out of bounds");
    }
    const step = steps[step_index];
    const kind = step.decodedKind() orelse
        @panic("checked-boundary marker-copy provider had an invalid kind");
    if (kind.sourceNamespace() != .cross_module or
        step.root_occurrence_offset >= step.occurrences_len or
        !rangeFits(
            step.occurrences_start,
            step.occurrences_len,
            self.cir.where_marker_copy_occurrences.items.items.len,
        ))
    {
        @panic("checked-boundary marker-copy provider had no exact cross-module root");
    }
    if (kind == .default_method) {
        const builtin_indices = self.builtin_ctx.builtin_indices orelse
            @panic("default-method marker copy had no Builtin index authority");
        if (!defaultMethodOriginMatchesDecisionTarget(
            self.types,
            self.cir,
            builtin_indices,
            step.origin.default_method,
        )) {
            @panic("default-method marker copy disagreed with its exact decision target");
        }
    }

    // Terminal relocation and repeated rebuilding must consume the same
    // typed origin authority as checked-module admission. Checker import and
    // method caches retain preterminal step ids and are intentionally not a
    // durable provider index.
    const resolution = ImportResolution.producedSupplied(
        self.cir,
        .{ .envs = self.imported_modules, .modules = self.validated_imported_modules },
        .{ .envs = self.owner_modules, .modules = self.validated_owner_modules },
        self.platform_dependency_index,
    );
    const authority = whereMarkerCrossRootAuthority(
        self.cir,
        self.builtin_ctx.builtin_module orelse self.cir,
        resolution,
        steps,
        step_index,
    ) orelse @panic("checked-boundary marker-copy step lost its typed producer authority");
    const root = self.cir.where_marker_copy_occurrences.items.items[
        step.occurrences_start + step.root_occurrence_offset
    ];
    if (root.raw_source_var != authority.raw_source_root) {
        @panic("checked-boundary marker-copy provider changed its exact raw source root");
    }
    return self.checkedBoundaryValidatedOwnerEnv(authority.provider);
}

fn checkedBoundaryBasisLessThan(
    _: void,
    a: types_mod.WhereMethodMarkerBasis,
    b: types_mod.WhereMethodMarkerBasis,
) bool {
    inline for (.{
        "marker_offset",
        "copy_step",
        "source_constraint_index",
        "source_contract_offset",
    }) |field| {
        const order = std.math.order(@field(a, field), @field(b, field));
        if (order != .eq) return order == .lt;
    }
    return false;
}

fn checkedBoundaryBasesEqual(
    a: types_mod.WhereMethodMarkerBasis,
    b: types_mod.WhereMethodMarkerBasis,
) bool {
    return a.marker_offset == b.marker_offset and
        a.copy_step == b.copy_step and
        a.source_constraint_index == b.source_constraint_index and
        a.source_contract_offset == b.source_contract_offset;
}

fn checkedBoundaryMarkerPathsEqual(
    paths: []const types_mod.WhereMethodMarkerPathStep,
    a: types_mod.WhereMethodMarkerContract,
    b: types_mod.WhereMethodMarkerContract,
) bool {
    const a_path = paths[a.path_start..][0..a.path_len];
    const b_path = paths[b.path_start..][0..b.path_len];
    return types_mod.compareWhereMethodMarkerPathSlices(a_path, b_path) == .eq and
        types_mod.whereMethodMarkerNominalNamesMatch(a_path, b_path);
}

fn canonicalConstraintMoveLessThan(
    _: void,
    a: PendingCanonicalConstraintMove,
    b: PendingCanonicalConstraintMove,
) bool {
    if (a.row.source_constraint_index != b.row.source_constraint_index) {
        return a.row.source_constraint_index < b.row.source_constraint_index;
    }
    return a.row.destination_constraint_index < b.row.destination_constraint_index;
}

fn markCheckedBoundaryConstraint(referenced: []bool, index: u32) bool {
    if (index >= referenced.len) {
        @panic("checked-boundary root named an absent static-dispatch constraint");
    }
    if (referenced[index]) return false;
    referenced[index] = true;
    return true;
}

fn markCheckedBoundaryConstraintRange(
    referenced: []bool,
    range: types_mod.StaticDispatchConstraint.SafeList.Range,
) bool {
    const len: usize = range.len();
    if (len == 0) return false;
    const start: usize = @intFromEnum(range.start);
    if (start > referenced.len or len > referenced.len - start) {
        @panic("checked-boundary descriptor constraint range escaped its pool");
    }
    var changed = false;
    for (referenced[start..][0..len]) |*is_referenced| {
        if (!is_referenced.*) {
            is_referenced.* = true;
            changed = true;
        }
    }
    return changed;
}

fn markCheckedBoundaryCopyStep(referenced: []bool, index: u32) bool {
    if (index >= referenced.len) {
        @panic("checked-boundary marker basis named an absent copy step");
    }
    if (referenced[index]) return false;
    referenced[index] = true;
    return true;
}

fn markCheckedBoundaryExpectedAuthorityCopyStep(
    referenced: []bool,
    authority: ModuleEnv.ExpectedMarkerAuthority,
) bool {
    if (!authority.hasCanonicalTags(true)) {
        @panic("checked-boundary Expected authority had noncanonical tags");
    }
    return switch (authority.decodedKind().?) {
        .copy_occurrence => markCheckedBoundaryCopyStep(
            referenced,
            authority.payload.copy_occurrence.copy_step,
        ),
        .producer_root_plan => false,
        .evidence_free_plan => false,
        .relation_plan => false,
    };
}

fn markCheckedBoundaryOwnedRange(
    owned: []bool,
    start: u32,
    len: u32,
) void {
    const range_start: usize = start;
    const range_len: usize = len;
    if (range_start > owned.len or range_len > owned.len - range_start) {
        @panic("checked-boundary copy-step owned range escaped its pool");
    }
    for (owned[range_start..][0..range_len]) |*row_owned| {
        if (row_owned.*) {
            @panic("checked-boundary copy-step ranges overlapped");
        }
        row_owned.* = true;
    }
}

fn checkedBoundaryRelocatedMarkerOffset(
    relocations: []const CheckedBoundaryConstraintRelocation,
    marker_offsets: []const u32,
    constraint_index: u32,
    old_offset: u32,
) u32 {
    if (constraint_index >= relocations.len) {
        @panic("checked-boundary relocation named an absent constraint");
    }
    const relocation = relocations[constraint_index];
    if (!relocation.retained() or old_offset >= relocation.old_marker_len) {
        @panic("checked-boundary relocation omitted a referenced marker occurrence");
    }
    return marker_offsets[relocation.marker_map_start + old_offset];
}

fn checkedBoundaryRelocatedConstraintIndex(
    relocations: []const CheckedBoundaryConstraintRelocation,
    old_index: u32,
) u32 {
    if (old_index >= relocations.len or !relocations[old_index].retained()) {
        @panic("checked-boundary relocation omitted a referenced constraint occurrence");
    }
    return relocations[old_index].new_constraint_index;
}

fn checkedBoundaryRelocatedCopyStep(step_map: []const u32, old_index: u32) u32 {
    if (old_index >= step_map.len or step_map[old_index] == std.math.maxInt(u32)) {
        @panic("checked-boundary relocation omitted a referenced marker-copy step");
    }
    return step_map[old_index];
}

fn expectedConsumptionPlanKeyLessThan(
    plans: []const ModuleEnv.ExpectedConsumptionPlan,
    left_index: u32,
    right_index: u32,
) bool {
    const left = plans[left_index];
    const right = plans[right_index];
    if (left.owner_node != right.owner_node) return left.owner_node < right.owner_node;
    if (left.role != right.role) return left.role < right.role;
    if (left.slot != right.slot) return left.slot < right.slot;
    if (left.site_node != right.site_node) return left.site_node < right.site_node;
    return left_index < right_index;
}

fn expectedConsumptionPlanKeysEqual(
    left: ModuleEnv.ExpectedConsumptionPlan,
    right: ModuleEnv.ExpectedConsumptionPlan,
) bool {
    return left.owner_node == right.owner_node and
        left.role == right.role and
        left.slot == right.slot and
        left.site_node == right.site_node;
}

fn expectedRetiredConsumerLessThan(
    _: void,
    left: ModuleEnv.ExpectedRetiredConsumer,
    right: ModuleEnv.ExpectedRetiredConsumer,
) bool {
    if (left.plan_index != right.plan_index) return left.plan_index < right.plan_index;
    if (left.owner_node != right.owner_node) return left.owner_node < right.owner_node;
    if (left.role != right.role) return left.role < right.role;
    if (left.slot != right.slot) return left.slot < right.slot;
    return left.site_node < right.site_node;
}

fn expectedFailureKeyLessThan(
    failures: []const ModuleEnv.ExpectedFailure,
    left_index: u32,
    right_index: u32,
) bool {
    const left = failures[left_index];
    const right = failures[right_index];
    inline for (.{
        "owner_kind",
        "owner_node",
        "site_node",
        "kind",
        "slot",
        "raw_owner_var",
        "raw_subject_var",
        "raw_peer_var",
    }) |field_name| {
        const left_value = @field(left, field_name);
        const right_value = @field(right, field_name);
        if (left_value != right_value) return left_value < right_value;
    }
    return left_index < right_index;
}

fn expectedFailureKeysEqual(
    left: ModuleEnv.ExpectedFailure,
    right: ModuleEnv.ExpectedFailure,
) bool {
    inline for (.{
        "owner_kind",
        "owner_node",
        "site_node",
        "kind",
        "slot",
        "raw_owner_var",
        "raw_subject_var",
        "raw_peer_var",
    }) |field_name| {
        if (@field(left, field_name) != @field(right, field_name)) return false;
    }
    return true;
}

fn checkedBoundaryValidateProviderWhereAliasFailureRef(
    self: *const Self,
    dependency_index: u32,
    publication_index: u32,
) void {
    if (dependency_index >= self.owner_modules.len) {
        @panic("Expected failure escaped the semantic-dependency closure");
    }
    const provider = self.checkedBoundaryValidatedOwnerEnv(self.owner_modules[dependency_index]);
    if (publication_index >= provider.where_alias_declaration_publications.items.items.len) {
        @panic("Expected failure named an absent provider where-alias publication");
    }
    const publication = provider.where_alias_declaration_publications.items.items[publication_index];
    if (publication.decodedOutcome() != .checked_error) {
        @panic("Expected failure named a provider where alias without a checked error");
    }
}

fn checkedBoundaryValidateExpectedCauseOwner(
    self: *const Self,
    cause: ModuleEnv.CauseOwner,
    failure_count: usize,
    retirement_count: usize,
) void {
    const required = cause.kind != ModuleEnv.CauseOwner.none;
    if (!cause.hasCanonicalTags(required)) {
        @panic("Expected cause owner had noncanonical tags");
    }
    const kind = cause.decodedKind() orelse return;
    switch (kind) {
        .expected_failure => if (cause.payload.expected_failure.index >= failure_count) {
            @panic("Expected cause named an absent failure publication");
        },
        .expected_consumer_retirement => if (cause.payload.expected_consumer_retirement.index >= retirement_count) {
            @panic("Expected cause named an absent consumer retirement");
        },
        .cir_diagnostic => {
            const diagnostic_index = cause.payload.cir_diagnostic.index;
            if (!self.cir.store.isDiagnosticIndex(@enumFromInt(diagnostic_index))) {
                @panic("Expected cause named an absent CIR diagnostic");
            }
        },
        .provider_where_alias_checked_error => {
            const provider = cause.payload.provider_where_alias_checked_error;
            self.checkedBoundaryValidateProviderWhereAliasFailureRef(
                provider.dependency_index,
                provider.publication_index,
            );
        },
    }
}

fn checkedBoundaryValidateExpectedFailureSubject(
    self: *const Self,
    failure: ModuleEnv.ExpectedFailure,
    failure_index: u32,
    old_steps: []const ModuleEnv.WhereMarkerCopyStep,
    old_occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
    old_expected_plans: []const ModuleEnv.ExpectedConsumptionPlan,
) void {
    const authority = failure.subject_authority;
    if (!authority.hasCanonicalTags(true)) {
        @panic("Expected failure subject authority had noncanonical tags");
    }
    switch (authority.decodedKind().?) {
        .direct => {
            const direct = authority.payload.direct;
            if (direct.producer_node >= self.cir.store.nodes.len()) {
                @panic("Expected failure direct producer escaped the CIR");
            }
            if (!expectedFailureSubjectIsLocallyValid(
                self.types,
                self.cir,
                failure,
                @intCast(failure_index),
            )) {
                @panic("Expected failure disagreed with its phase-specific local producer record");
            }
        },
        .expected_copy_occurrence => {
            const endpoint = authority.payload.expected_copy_occurrence;
            const side = authority.decodedExpectedCopySide() orelse
                @panic("Expected failure subject had an invalid copy side");
            const raw_endpoint = whereMarkerCopyEndpointRawVar(
                old_steps,
                old_occurrences,
                endpoint.copy_step,
                endpoint.occurrence_offset,
                side,
            );
            if (raw_endpoint != failure.raw_subject_var) {
                @panic("Expected failure subject did not equal its exact copy occurrence");
            }
        },
        .expected_producer_root_plan => {
            const root = authority.payload.expected_producer_root_plan;
            if (failure.decodedKind() == .call_operand_checked_error and
                !callOperandExpectedFailureIsLocallyValid(
                    self.types,
                    self.cir,
                    failure,
                    failure_index,
                    root,
                ))
            {
                @panic("call operand failure lost its exact call/formal/lookup inverse");
            }
            if (root.plan_index >= old_expected_plans.len or root.raw_var >= self.types.len() or
                root.raw_var != failure.raw_subject_var)
            {
                @panic("Expected failure escaped its producer-root subject plan");
            }
            const plan = old_expected_plans[root.plan_index];
            if (!plan.hasLegalTags() or plan.decodedOutcome() != .producer_root or
                plan.raw_consumer_var != root.raw_var)
            {
                @panic("Expected failure named a mismatched producer-root subject plan");
            }
        },
        .expected_evidence_free_plan => {
            const evidence_free = authority.payload.expected_evidence_free_plan;
            if (evidence_free.plan_index >= old_expected_plans.len or
                evidence_free.raw_var >= self.types.len() or
                evidence_free.raw_var != failure.raw_subject_var)
            {
                @panic("Expected failure escaped its evidence-free subject plan");
            }
            const plan = old_expected_plans[evidence_free.plan_index];
            if (!plan.hasLegalTags() or plan.raw_consumer_var != evidence_free.raw_var or
                (plan.decodedOutcome() != .evidence_free and
                    !(plan.decodedOutcome() == .checked_error and
                        plan.decodedReason() == .aggregate_child_relation_rejected)))
            {
                @panic("Expected failure named a mismatched evidence-free subject plan");
            }
        },
        .expected_relation_plan => {
            const relation = authority.payload.expected_relation_plan;
            if (relation.plan_index >= old_expected_plans.len or
                relation.raw_var >= self.types.len() or
                relation.raw_var != failure.raw_subject_var)
            {
                @panic("Expected failure escaped its relation-plan subject");
            }
            const plan = old_expected_plans[relation.plan_index];
            if (!plan.hasLegalTags() or
                plan.decodedRole() != .branch_contribution or
                plan.decodedOutcome() != .related)
            {
                @panic("Expected failure named a mismatched relation-plan subject");
            }
            const parent_raw = expectedParentAuthorityRawForProof(
                self.cir,
                plan.parent_authority,
                old_steps,
                old_occurrences,
                null,
            ) orelse @panic("Expected failure relation plan lost its prior authority");
            if (parent_raw != relation.raw_var) {
                @panic("Expected failure relation plan changed its exact raw subject");
            }
        },
        .provider_where_alias_checked_error => {
            const provider = authority.payload.provider_where_alias_checked_error;
            self.checkedBoundaryValidateProviderWhereAliasFailureRef(
                provider.dependency_index,
                provider.publication_index,
            );
        },
    }
}

fn checkedBoundaryRelocatedExpectedCauseOwner(
    cause: ModuleEnv.CauseOwner,
    expected_failure_map: []const u32,
    expected_retirement_map: []const u32,
) ModuleEnv.CauseOwner {
    if (!cause.hasCanonicalTags(cause.kind != ModuleEnv.CauseOwner.none)) {
        @panic("Expected cause owner had noncanonical tags during relocation");
    }
    const kind = cause.decodedKind() orelse return cause;
    return switch (kind) {
        .expected_failure => blk: {
            const old_index = cause.payload.expected_failure.index;
            if (old_index >= expected_failure_map.len or
                expected_failure_map[old_index] == std.math.maxInt(u32))
            {
                @panic("Expected cause lost its failure publication");
            }
            break :blk ModuleEnv.CauseOwner.expectedFailure(expected_failure_map[old_index]);
        },
        .expected_consumer_retirement => blk: {
            const old_index = cause.payload.expected_consumer_retirement.index;
            if (old_index >= expected_retirement_map.len or
                expected_retirement_map[old_index] == std.math.maxInt(u32))
            {
                @panic("Expected cause lost its consumer retirement");
            }
            break :blk ModuleEnv.CauseOwner.expectedConsumerRetirement(
                expected_retirement_map[old_index],
            );
        },
        .cir_diagnostic, .provider_where_alias_checked_error => cause,
    };
}

fn whereMarkerCopyEndpointRawVar(
    steps: []const ModuleEnv.WhereMarkerCopyStep,
    occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
    copy_step: u32,
    occurrence_offset: u32,
    side: ModuleEnv.WhereMarkerCopyOccurrenceSide,
) u32 {
    if (copy_step >= steps.len) {
        @panic("Expected-consumption endpoint named an absent copy step");
    }
    const step = steps[copy_step];
    if (occurrence_offset >= step.occurrences_len or
        step.occurrences_start > occurrences.len or
        step.occurrences_len > occurrences.len - step.occurrences_start)
    {
        @panic("Expected-consumption endpoint escaped its copy occurrence range");
    }
    const occurrence = occurrences[step.occurrences_start + occurrence_offset];
    return switch (side) {
        .source => occurrence.raw_source_var,
        .destination => occurrence.raw_destination_var,
    };
}

const RelocatedExpectedCopyEndpoint = struct {
    copy_step: u32,
    occurrence_offset: u32,
};

fn checkedBoundaryRelocatedExpectedCopyEndpoint(
    old_steps: []const ModuleEnv.WhereMarkerCopyStep,
    step_map: []const u32,
    occurrence_relocations: []const u32,
    old_copy_step: u32,
    old_occurrence_offset: u32,
) RelocatedExpectedCopyEndpoint {
    if (old_copy_step >= old_steps.len) {
        @panic("Expected-consumption endpoint named an absent copy step");
    }
    const old_step = old_steps[old_copy_step];
    if (old_occurrence_offset >= old_step.occurrences_len) {
        @panic("Expected-consumption endpoint escaped its copy occurrence range");
    }
    const relocated_occurrence = occurrence_relocations[
        old_step.occurrences_start + old_occurrence_offset
    ];
    if (relocated_occurrence == std.math.maxInt(u32)) {
        @panic("Expected-consumption endpoint lost its exact raw occurrence");
    }
    return .{
        .copy_step = checkedBoundaryRelocatedCopyStep(step_map, old_copy_step),
        .occurrence_offset = relocated_occurrence,
    };
}

fn checkedBoundaryRelocatedExpectedAuthority(
    authority: ModuleEnv.ExpectedMarkerAuthority,
    old_steps: []const ModuleEnv.WhereMarkerCopyStep,
    old_occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
    step_map: []const u32,
    occurrence_relocations: []const u32,
    expected_plan_map: []const u32,
    new_steps: []const ModuleEnv.WhereMarkerCopyStep,
    new_occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
) ModuleEnv.ExpectedMarkerAuthority {
    if (!authority.hasCanonicalTags(true)) {
        @panic("Expected authority had noncanonical tags during relocation");
    }
    return switch (authority.decodedKind().?) {
        .copy_occurrence => blk: {
            const old_endpoint = authority.payload.copy_occurrence;
            const side = std.enums.fromInt(
                ModuleEnv.WhereMarkerCopyOccurrenceSide,
                old_endpoint.side,
            ) orelse @panic("Expected authority had an invalid occurrence side");
            const old_raw = whereMarkerCopyEndpointRawVar(
                old_steps,
                old_occurrences,
                old_endpoint.copy_step,
                old_endpoint.occurrence_offset,
                side,
            );
            const relocated = checkedBoundaryRelocatedExpectedCopyEndpoint(
                old_steps,
                step_map,
                occurrence_relocations,
                old_endpoint.copy_step,
                old_endpoint.occurrence_offset,
            );
            const new_raw = whereMarkerCopyEndpointRawVar(
                new_steps,
                new_occurrences,
                relocated.copy_step,
                relocated.occurrence_offset,
                side,
            );
            if (old_raw != new_raw) {
                @panic("Expected authority changed its exact raw occurrence side");
            }
            break :blk .{
                .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.copy_occurrence),
                .payload = .{ .copy_occurrence = .{
                    .copy_step = relocated.copy_step,
                    .occurrence_offset = relocated.occurrence_offset,
                    .side = old_endpoint.side,
                } },
            };
        },
        .producer_root_plan => blk: {
            const old_root = authority.payload.producer_root_plan;
            if (old_root.plan_index >= expected_plan_map.len or
                expected_plan_map[old_root.plan_index] == std.math.maxInt(u32))
            {
                @panic("Expected authority lost its producer-root plan");
            }
            break :blk .{
                .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.producer_root_plan),
                .payload = .{ .producer_root_plan = .{
                    .plan_index = expected_plan_map[old_root.plan_index],
                    .raw_var = old_root.raw_var,
                } },
            };
        },
        .evidence_free_plan => blk: {
            const old_plan = authority.payload.evidence_free_plan;
            if (old_plan.plan_index >= expected_plan_map.len or
                expected_plan_map[old_plan.plan_index] == std.math.maxInt(u32))
            {
                @panic("Expected authority lost its evidence-free plan");
            }
            break :blk .{
                .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.evidence_free_plan),
                .payload = .{ .evidence_free_plan = .{
                    .plan_index = expected_plan_map[old_plan.plan_index],
                    .raw_var = old_plan.raw_var,
                } },
            };
        },
        .relation_plan => blk: {
            const old_plan = authority.payload.relation_plan;
            if (old_plan.plan_index >= expected_plan_map.len or
                expected_plan_map[old_plan.plan_index] == std.math.maxInt(u32))
            {
                @panic("Expected authority lost its relation plan");
            }
            break :blk .{
                .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.relation_plan),
                .payload = .{ .relation_plan = .{
                    .plan_index = expected_plan_map[old_plan.plan_index],
                    .raw_var = old_plan.raw_var,
                } },
            };
        },
    };
}

fn checkedBoundaryRelocatedExpectedFailureSubject(
    authority: ModuleEnv.SubjectAuthority,
    old_steps: []const ModuleEnv.WhereMarkerCopyStep,
    old_occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
    step_map: []const u32,
    occurrence_relocations: []const u32,
    expected_plan_map: []const u32,
    new_steps: []const ModuleEnv.WhereMarkerCopyStep,
    new_occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
) ModuleEnv.SubjectAuthority {
    if (!authority.hasCanonicalTags(true)) {
        @panic("Expected failure subject authority had noncanonical tags during relocation");
    }
    return switch (authority.decodedKind().?) {
        .direct, .provider_where_alias_checked_error => authority,
        .expected_copy_occurrence => blk: {
            const old_endpoint = authority.payload.expected_copy_occurrence;
            const side = authority.decodedExpectedCopySide() orelse
                @panic("Expected failure subject had an invalid copy side");
            const old_raw = whereMarkerCopyEndpointRawVar(
                old_steps,
                old_occurrences,
                old_endpoint.copy_step,
                old_endpoint.occurrence_offset,
                side,
            );
            const relocated = checkedBoundaryRelocatedExpectedCopyEndpoint(
                old_steps,
                step_map,
                occurrence_relocations,
                old_endpoint.copy_step,
                old_endpoint.occurrence_offset,
            );
            const new_raw = whereMarkerCopyEndpointRawVar(
                new_steps,
                new_occurrences,
                relocated.copy_step,
                relocated.occurrence_offset,
                side,
            );
            if (old_raw != new_raw) {
                @panic("Expected failure subject changed its exact raw copy occurrence");
            }
            break :blk ModuleEnv.SubjectAuthority.expectedCopyOccurrence(
                relocated.copy_step,
                relocated.occurrence_offset,
                side,
            );
        },
        .expected_producer_root_plan => blk: {
            const old_plan = authority.payload.expected_producer_root_plan;
            if (old_plan.plan_index >= expected_plan_map.len or
                expected_plan_map[old_plan.plan_index] == std.math.maxInt(u32))
            {
                @panic("Expected failure subject lost its producer-root plan");
            }
            break :blk ModuleEnv.SubjectAuthority.expectedProducerRootPlan(
                expected_plan_map[old_plan.plan_index],
                old_plan.raw_var,
            );
        },
        .expected_evidence_free_plan => blk: {
            const old_plan = authority.payload.expected_evidence_free_plan;
            if (old_plan.plan_index >= expected_plan_map.len or
                expected_plan_map[old_plan.plan_index] == std.math.maxInt(u32))
            {
                @panic("Expected failure subject lost its evidence-free plan");
            }
            break :blk ModuleEnv.SubjectAuthority.expectedEvidenceFreePlan(
                expected_plan_map[old_plan.plan_index],
                old_plan.raw_var,
            );
        },
        .expected_relation_plan => blk: {
            const old_plan = authority.payload.expected_relation_plan;
            if (old_plan.plan_index >= expected_plan_map.len or
                expected_plan_map[old_plan.plan_index] == std.math.maxInt(u32))
            {
                @panic("Expected failure subject lost its relation plan");
            }
            break :blk ModuleEnv.SubjectAuthority.expectedRelationPlan(
                expected_plan_map[old_plan.plan_index],
                old_plan.raw_var,
            );
        },
    };
}

/// Stamp the canonical allocation-free reachability certificate for one
/// already-sorted copy relation. The root remains the sole depth-zero row.
/// Self-addressed root/cut witnesses authenticate an action but never create
/// a BFS edge; every other pair must be reached by a producer-authored edge.
fn canonicalizeCheckedBoundaryCopyPairBfs(
    pairs: []ModuleEnv.WhereMarkerCopyPair,
    occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
    witnesses: []const ModuleEnv.WhereMarkerCopyWitness,
    root_occurrence_offset: u32,
) void {
    const none = std.math.maxInt(u32);
    if (root_occurrence_offset >= occurrences.len) {
        @panic("marker-copy BFS root occurrence escaped its step");
    }
    const root = occurrences[root_occurrence_offset].canonical_pair_offset;
    if (root >= pairs.len) @panic("marker-copy BFS root occurrence named an absent pair");
    for (pairs) |*pair| {
        pair.discovery_depth = none;
        pair.predecessor_pair_offset = none;
        pair.predecessor_edge_ordinal = none;
    }
    pairs[root].discovery_depth = 0;

    var changed = true;
    while (changed) {
        changed = false;
        for (witnesses, 0..) |witness, witness_index| {
            if (witness.parent_occurrence_offset >= occurrences.len or
                witness.child_occurrence_offset >= occurrences.len)
            {
                @panic("marker-copy BFS witness escaped its occurrence relation");
            }
            const parent_pair_offset = occurrences[witness.parent_occurrence_offset].canonical_pair_offset;
            const child_pair_offset = occurrences[witness.child_occurrence_offset].canonical_pair_offset;
            if (parent_pair_offset >= pairs.len or child_pair_offset >= pairs.len) {
                @panic("marker-copy BFS occurrence escaped its pair relation");
            }
            var parent_edge_ordinal: u32 = 0;
            for (witnesses[0..witness_index]) |prior| {
                const prior_parent = occurrences[prior.parent_occurrence_offset].canonical_pair_offset;
                if (prior_parent != parent_pair_offset) continue;
                parent_edge_ordinal = std.math.add(u32, parent_edge_ordinal, 1) catch
                    @panic("marker-copy BFS edge ordinal overflowed u32");
            }
            if (parent_pair_offset == child_pair_offset) continue;
            const parent_depth = pairs[parent_pair_offset].discovery_depth;
            if (parent_depth == none) continue;
            const child = &pairs[child_pair_offset];
            if (child_pair_offset == root) continue;
            const candidate_depth = std.math.add(u32, parent_depth, 1) catch
                @panic("marker-copy BFS depth overflowed u32");
            const candidate_is_better = candidate_depth < child.discovery_depth or
                (candidate_depth == child.discovery_depth and
                    (parent_pair_offset < child.predecessor_pair_offset or
                        (parent_pair_offset == child.predecessor_pair_offset and
                            parent_edge_ordinal < child.predecessor_edge_ordinal)));
            if (!candidate_is_better) continue;
            child.discovery_depth = candidate_depth;
            child.predecessor_pair_offset = parent_pair_offset;
            child.predecessor_edge_ordinal = parent_edge_ordinal;
            changed = true;
        }
    }

    for (pairs, 0..) |pair, raw_pair_offset| {
        if (raw_pair_offset == root) {
            if (pair.discovery_depth != 0 or pair.predecessor_pair_offset != none or
                pair.predecessor_edge_ordinal != none)
            {
                @panic("marker-copy BFS root carried a predecessor");
            }
            continue;
        }
        if (pair.discovery_depth == none or pair.discovery_depth == 0 or
            pair.predecessor_pair_offset == none or pair.predecessor_edge_ordinal == none)
        {
            @panic("marker-copy proof contained a disconnected pair");
        }
    }

    for (witnesses) |witness| {
        const parent_pair_offset = occurrences[witness.parent_occurrence_offset].canonical_pair_offset;
        const child_pair_offset = occurrences[witness.child_occurrence_offset].canonical_pair_offset;
        if (parent_pair_offset == child_pair_offset) continue;
        const parent_depth = pairs[parent_pair_offset].discovery_depth;
        const child_depth = pairs[child_pair_offset].discovery_depth;
        const edge_limit = std.math.add(u32, parent_depth, 1) catch
            @panic("marker-copy BFS edge depth overflowed u32");
        if (child_depth > edge_limit) {
            @panic("marker-copy BFS did not compute a shortest child depth");
        }
    }
}

fn checkedBoundaryLocalSourceFact(
    self: *Self,
    source: ModuleEnv.WhereMethodSource,
    contract: types_mod.WhereMethodMarkerContract,
) Allocator.Error!bool {
    if (source.retained_constraint_index >= self.types.static_dispatch_constraints.items.items.len) {
        @panic("checked-boundary where-method source named an absent constraint");
    }
    if (!contract.hasProducer() or contract.isReady() != true or
        contract.producer_owner_node != source.owner_node or
        contract.producer_where_node != source.where_node or
        contract.producer_method_name != source.method_ident)
    {
        @panic("checked-boundary where-method source contract had the wrong producer");
    }
    const retained = self.types.static_dispatch_constraints.items.items[source.retained_constraint_index];
    const retained_root = self.types.resolveVar(retained.fn_var).var_;
    const producer = SourceProducerKey.fromContract(contract);
    var written_tag_count: ?u32 = null;
    var widened = false;
    for (self.cir.scheme_uses.items.items) |record| {
        if (record.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.where_method_use) or
            self.types.resolveVar(@enumFromInt(record.scheme_root)).var_ != retained_root)
        {
            continue;
        }
        if (!rangeFits(
            record.marker_uses_start,
            record.marker_uses_len,
            self.cir.where_method_marker_uses.items.items.len,
        )) {
            @panic("checked-boundary where-method use escaped its marker pool");
        }
        for (self.cir.where_method_marker_uses.items.items[record.marker_uses_start..][0..record.marker_uses_len]) |marker| {
            if (!std.meta.eql(SourceProducerKey.fromUse(marker), producer) or
                !self.markerUsePathMatchesContract(marker, contract))
            {
                continue;
            }
            if (marker.position != contract.position) {
                @panic("one where-method source path had incompatible position classes");
            }
            if (written_tag_count) |written| {
                if (written != marker.written_tag_count) {
                    @panic("one where-method source path had incompatible written rows");
                }
            } else {
                written_tag_count = marker.written_tag_count;
            }
            widened = widened or try self.whereMethodMarkerUseWidened(marker);
        }
    }
    if (contract.isWidened().? != widened) {
        @panic("settled where-method source fact disagreed with its exact body uses");
    }
    return widened;
}

fn durableDefaultDecisionContributor(
    self: *const Self,
    draft: DefaultDecisionDraft,
    driver: OpenLiteralDriver,
) ModuleEnv.DefaultDecisionContributor {
    const final_receiver = self.types.resolveVar(draft.receiver_var).var_;
    return switch (driver) {
        .instantiation_copy => |copy_driver| blk: {
            const bound = switch (copy_driver) {
                .bound => |exact| exact,
                .pending => std.debug.panic("terminal default publication encountered an unbound copy contributor", .{}),
                .none => std.debug.panic("terminal default publication encountered an origin-less copy contributor", .{}),
            };
            if (bound.copy_step >= self.cir.where_marker_copy_steps.items.items.len) {
                std.debug.panic("default copy contributor named an absent producer step", .{});
            }
            const step = self.cir.where_marker_copy_steps.items.items[bound.copy_step];
            if (bound.pair_offset >= step.pairs_len or
                bound.occurrence_offset >= step.occurrences_len)
            {
                std.debug.panic("default copy contributor escaped its producer occurrence/pair range", .{});
            }
            const pair = self.cir.where_marker_copy_pairs.items.items[step.pairs_start + bound.pair_offset];
            const occurrence = self.cir.where_marker_copy_occurrences.items.items[
                step.occurrences_start + bound.occurrence_offset
            ];
            if (occurrence.canonical_pair_offset != bound.pair_offset or
                pair.destination_var >= self.types.len() or
                self.types.resolveVar(@enumFromInt(pair.destination_var)).var_ != final_receiver)
            {
                std.debug.panic("default copy contributor produced a different receiver component", .{});
            }
            break :blk .{
                .driver_kind = @intFromEnum(ModuleEnv.DefaultDecision.DriverKind.instantiation_copy),
                .driver_copy_step = bound.copy_step,
                .driver_pair_offset = bound.pair_offset,
                .literal_source_node = 0,
                .literal_occurrence_kind = 0,
                .literal_kind = 0,
            };
        },
        .literal_creation => |creation| blk: {
            if (@intFromEnum(creation.source_node) >= self.cir.store.nodes.len() or
                @intFromEnum(creation.source_node) >= self.types.len())
            {
                std.debug.panic("default literal contributor escaped its CIR/type node space", .{});
            }
            const durable_kind: ModuleEnv.DefaultDecision.LiteralKind = switch (creation.kind) {
                .numeral => .numeral,
                .quote => .quote,
                .interpolation => .interpolation,
            };
            if (!literalCreationDriverMatchesTag(
                creation.occurrence_kind,
                durable_kind,
                self.cir.store.nodes.get(creation.source_node).tag,
            )) {
                std.debug.panic("default literal contributor disagreed with its exact CIR tag", .{});
            }
            if (self.types.resolveVar(ModuleEnv.varFrom(creation.source_node)).var_ != final_receiver) {
                std.debug.panic("default literal contributor produced a different receiver component", .{});
            }
            var kind_present = false;
            for (self.types.sliceStaticDispatchConstraints(draft.constraints)) |constraint| {
                if (literal_defaulting.constraintLiteralKind(self.literalMethodIdents(), constraint) == creation.kind) {
                    kind_present = true;
                    break;
                }
            }
            if (!kind_present) {
                std.debug.panic("default literal contributor kind was absent from the decision range", .{});
            }
            break :blk .{
                .driver_kind = @intFromEnum(ModuleEnv.DefaultDecision.DriverKind.literal_creation),
                .driver_copy_step = 0,
                .driver_pair_offset = 0,
                .literal_source_node = @intFromEnum(creation.source_node),
                .literal_occurrence_kind = @intFromEnum(creation.occurrence_kind),
                .literal_kind = @intFromEnum(durable_kind),
            };
        },
    };
}

/// Freeze every explicit default-decision draft after the final
/// registration-producing fixpoint. The replacement pools and draft map are
/// completely built before any live origin is rewritten, so OOM is a no-op.
fn finalizeDefaultDecisionDrafts(self: *Self) Allocator.Error!void {
    if (self.probe_depth != 0) {
        std.debug.panic("default decisions cannot freeze under a checker probe", .{});
    }
    if (self.default_decision_drafts_frozen) {
        std.debug.panic("default decisions were frozen twice", .{});
    }
    if (self.cir.default_decisions.items.items.len != 0 or
        self.cir.default_decision_contributors.items.items.len != 0)
    {
        std.debug.panic("default decision drafts collided with preexisting durable rows", .{});
    }

    const none = std.math.maxInt(u32);
    const draft_count = self.default_decision_drafts.items.len;
    const draft_map = try self.gpa.alloc(u32, draft_count);
    defer self.gpa.free(draft_map);
    @memset(draft_map, none);
    const draft_order = try self.gpa.alloc(u32, draft_count);
    defer self.gpa.free(draft_order);
    for (draft_order, 0..) |*slot, index| slot.* = @intCast(index);
    std.mem.sortUnstable(u32, draft_order, @as(*const Self, self), struct {
        fn lessThan(check: *const Self, lhs_index: u32, rhs_index: u32) bool {
            const lhs = check.default_decision_drafts.items[lhs_index];
            const rhs = check.default_decision_drafts.items[rhs_index];
            const lhs_receiver = check.types.resolveVar(lhs.receiver_var).var_;
            const rhs_receiver = check.types.resolveVar(rhs.receiver_var).var_;
            if (@intFromEnum(lhs_receiver) != @intFromEnum(rhs_receiver)) {
                return @intFromEnum(lhs_receiver) < @intFromEnum(rhs_receiver);
            }
            if (@intFromEnum(lhs.constraints.start) != @intFromEnum(rhs.constraints.start)) {
                return @intFromEnum(lhs.constraints.start) < @intFromEnum(rhs.constraints.start);
            }
            if (lhs.constraints.len() != rhs.constraints.len()) return lhs.constraints.len() < rhs.constraints.len();
            return @intFromEnum(lhs.target) < @intFromEnum(rhs.target);
        }
    }.lessThan);

    for (self.default_decision_draft_contributors.items) |contributor| {
        if (contributor.decision_draft_index >= draft_count) {
            std.debug.panic("default contributor ledger named an absent draft", .{});
        }
    }

    var replacement_decisions = try ModuleEnv.DefaultDecision.SafeList.initCapacity(self.cir.gpa, draft_count);
    defer replacement_decisions.deinit(self.cir.gpa);
    var replacement_contributors = try ModuleEnv.DefaultDecisionContributor.SafeList.initCapacity(
        self.cir.gpa,
        self.default_decision_draft_contributors.items.len,
    );
    defer replacement_contributors.deinit(self.cir.gpa);
    var scratch: std.ArrayListUnmanaged(ModuleEnv.DefaultDecisionContributor) = .empty;
    defer scratch.deinit(self.gpa);

    for (draft_order, 0..) |draft_index, durable_index| {
        const draft = self.default_decision_drafts.items[draft_index];
        const constraints_start: usize = @intFromEnum(draft.constraints.start);
        if (@intFromEnum(draft.receiver_var) >= self.types.len() or
            draft.constraints.len() == 0 or
            constraints_start > self.types.static_dispatch_constraints.items.items.len or
            draft.constraints.len() > self.types.static_dispatch_constraints.items.items.len - constraints_start)
        {
            std.debug.panic("default decision draft escaped its exact receiver/range", .{});
        }
        const exact_target = self.specializationDefaultTargetForConstraints(
            self.types.sliceStaticDispatchConstraints(draft.constraints),
        ) orelse std.debug.panic("default decision draft range was no longer defaultable", .{});
        if (exact_target != draft.target) {
            std.debug.panic("default decision draft target drifted from its complete constraint range", .{});
        }
        if (durable_index != 0) {
            const prior = self.default_decision_drafts.items[draft_order[durable_index - 1]];
            if (self.types.resolveVar(prior.receiver_var).var_ ==
                self.types.resolveVar(draft.receiver_var).var_ and
                prior.constraints.start == draft.constraints.start and
                prior.constraints.len() == draft.constraints.len())
            {
                std.debug.panic("default decision drafts duplicated one logical identity", .{});
            }
        }

        scratch.clearRetainingCapacity();
        for (self.default_decision_draft_contributors.items) |contributor| {
            if (contributor.decision_draft_index != draft_index) continue;
            try scratch.append(self.gpa, self.durableDefaultDecisionContributor(draft, contributor.driver));
        }
        std.mem.sortUnstable(ModuleEnv.DefaultDecisionContributor, scratch.items, {}, struct {
            fn lessThan(
                _: void,
                lhs: ModuleEnv.DefaultDecisionContributor,
                rhs: ModuleEnv.DefaultDecisionContributor,
            ) bool {
                return ModuleEnv.DefaultDecisionContributor.canonicalLessThan(lhs, rhs);
            }
        }.lessThan);
        var write_index: usize = 0;
        for (scratch.items) |contributor| {
            if (write_index != 0 and std.meta.eql(scratch.items[write_index - 1], contributor)) continue;
            scratch.items[write_index] = contributor;
            write_index += 1;
        }
        scratch.shrinkRetainingCapacity(write_index);
        if (scratch.items.len == 0) {
            std.debug.panic("default decision draft had no producer contributors", .{});
        }

        const contributors_start = std.math.cast(u32, replacement_contributors.items.items.len) orelse
            return error.OutOfMemory;
        replacement_contributors.items.appendSliceAssumeCapacity(scratch.items);
        replacement_decisions.items.appendAssumeCapacity(.{
            .receiver_var = @intFromEnum(self.types.resolveVar(draft.receiver_var).var_),
            .constraints_start = @intFromEnum(draft.constraints.start),
            .constraints_len = draft.constraints.len(),
            .target = @intFromEnum(switch (draft.target) {
                .dec => ModuleEnv.DefaultDecision.Target.dec,
                .str => ModuleEnv.DefaultDecision.Target.str,
            }),
            .contributors_start = contributors_start,
            .contributors_len = @intCast(scratch.items.len),
        });
        draft_map[draft_index] = @intCast(durable_index);
    }

    // No fallible operation follows. Default-method origins temporarily carry
    // stable draft ids and become durable indices in the same publication.
    for (self.cir.where_marker_copy_steps.items.items) |*step| {
        const kind = step.decodedKind() orelse
            std.debug.panic("default freeze encountered an invalid copy-step kind", .{});
        const draft_index = switch (kind) {
            .default_method => step.origin.default_method.decision_index,
            .default_method_use => step.origin.default_method_use.decision_index,
            else => continue,
        };
        if (draft_index >= draft_map.len or draft_map[draft_index] == none) {
            std.debug.panic("default-method copy origin named an absent decision draft", .{});
        }
        switch (kind) {
            .default_method => step.origin.default_method.decision_index = draft_map[draft_index],
            .default_method_use => step.origin.default_method_use.decision_index = draft_map[draft_index],
            else => unreachable,
        }
    }
    std.mem.swap(ModuleEnv.DefaultDecision.SafeList, &self.cir.default_decisions, &replacement_decisions);
    std.mem.swap(
        ModuleEnv.DefaultDecisionContributor.SafeList,
        &self.cir.default_decision_contributors,
        &replacement_contributors,
    );
    self.default_decision_drafts_frozen = true;
}

/// Transactionally replace all W6b marker metadata with its referenced-only
/// canonical checked-boundary form. Every source occurrence remains distinct;
/// only this index-space relocation rewrites durable coordinates.
const CheckedBoundaryRebuild = struct {
    const Transaction = @This();
    const none = std.math.maxInt(u32);

    const Input = struct {
        constraints: []const types_mod.StaticDispatchConstraint,
        contracts: []const types_mod.WhereMethodMarkerContract,
        bases: []const types_mod.WhereMethodMarkerBasis,
        type_paths: []const types_mod.WhereMethodMarkerPathStep,
        steps: []const ModuleEnv.WhereMarkerCopyStep,
        default_decisions: []const ModuleEnv.DefaultDecision,
        default_contributors: []const ModuleEnv.DefaultDecisionContributor,
        selected_decisions: []const ModuleEnv.SelectedMethodDecision,
        selected_anchors: []const ModuleEnv.SelectedReceiverAnchor,
        for_loop_plans: []const ModuleEnv.ForLoopDispatchPlan,
        settlement_sources: []const ModuleEnv.DispatchSettlementSource,
        selected_moves: []const ModuleEnv.ConstraintEvidenceMove,
        selected_decision_moves: []const ModuleEnv.SelectedMethodDecisionMove,
        pairs: []const ModuleEnv.WhereMarkerCopyPair,
        occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
        constraint_pairs: []const ModuleEnv.WhereMarkerConstraintCopyPair,
        witnesses: []const ModuleEnv.WhereMarkerCopyWitness,
        copied_literal_groups: []const ModuleEnv.CopiedOpenLiteralGroup,
        copied_literal_events: []const ModuleEnv.CopiedOpenLiteralEvent,
        substitutions: []const ModuleEnv.WhereMarkerPlatformSubstitution,
        moves: []const ModuleEnv.WhereMarkerConstraintMove,
        move_offsets: []const u32,
        expected_plans: []const ModuleEnv.ExpectedConsumptionPlan,
        expected_failures: []const ModuleEnv.ExpectedFailure,
        expected_retirements: []const ModuleEnv.ExpectedConsumerRetirement,
        expected_ambiguity_retirements: []const ModuleEnv.ExpectedAmbiguityRetirement,
        expected_retirement_failures: []const ModuleEnv.ExpectedRetirementFailure,
        expected_retired_consumers: []const ModuleEnv.ExpectedRetiredConsumer,
        expected_call_formals: []const ModuleEnv.ExpectedCallFormal,
        external_cache_seeds: []const ModuleEnv.ExternalCacheSeed,
        where_method_sources: []const ModuleEnv.WhereMethodSource,
        where_alias_expansions: []const ModuleEnv.WhereAliasExpansion,
        codec_requirements: []const ModuleEnv.BindingSchemeCodecRequirement,
        marker_uses: []const ModuleEnv.WhereMethodMarkerUse,
        use_paths: []const ModuleEnv.WhereMethodMarkerPathStep,

        fn capture(checker: *const Self) Input {
            return .{
                .constraints = checker.types.static_dispatch_constraints.items.items,
                .contracts = checker.types.where_method_marker_contracts.items.items,
                .bases = checker.types.where_method_marker_bases.items.items,
                .type_paths = checker.types.where_method_marker_path_steps.items.items,
                .steps = checker.cir.where_marker_copy_steps.items.items,
                .default_decisions = checker.cir.default_decisions.items.items,
                .default_contributors = checker.cir.default_decision_contributors.items.items,
                .selected_decisions = checker.cir.selected_method_decisions.items.items,
                .selected_anchors = checker.cir.selected_receiver_anchors.items.items,
                .for_loop_plans = checker.cir.for_loop_dispatch_plans.items.items,
                .settlement_sources = checker.cir.dispatch_settlement_sources.items.items,
                .selected_moves = checker.cir.constraint_evidence_moves.items.items,
                .selected_decision_moves = checker.cir.selected_method_decision_moves.items.items,
                .pairs = checker.cir.where_marker_copy_pairs.items.items,
                .occurrences = checker.cir.where_marker_copy_occurrences.items.items,
                .constraint_pairs = checker.cir.where_marker_constraint_copy_pairs.items.items,
                .witnesses = checker.cir.where_marker_copy_witnesses.items.items,
                .copied_literal_groups = checker.cir.copied_open_literal_groups.items.items,
                .copied_literal_events = checker.cir.copied_open_literal_events.items.items,
                .substitutions = checker.cir.where_marker_platform_substitutions.items.items,
                .moves = checker.cir.where_marker_constraint_moves.items.items,
                .move_offsets = checker.cir.where_marker_constraint_move_offsets.items.items,
                .expected_plans = checker.cir.expected_consumption_plans.items.items,
                .expected_failures = checker.cir.expected_failures.items.items,
                .expected_retirements = checker.cir.expected_consumer_retirements.items.items,
                .expected_ambiguity_retirements = checker.cir.expected_ambiguity_retirements.items.items,
                .expected_retirement_failures = checker.cir.expected_retirement_failures.items.items,
                .expected_retired_consumers = checker.cir.expected_retired_consumers.items.items,
                .expected_call_formals = checker.cir.expected_call_formals.items.items,
                .external_cache_seeds = checker.cir.external_cache_seeds.items.items,
                .where_method_sources = checker.cir.where_method_sources.items.items,
                .where_alias_expansions = checker.cir.where_alias_expansions.items.items,
                .codec_requirements = checker.cir.binding_scheme_codec_requirements.items.items,
                .marker_uses = checker.cir.where_method_marker_uses.items.items,
                .use_paths = checker.cir.where_method_marker_path_steps.items.items,
            };
        }
    };

    checker: *Self,
    input: Input,

    external_seed_order: ?[]u32 = null,
    external_seed_map: ?[]u32 = null,
    live_ranges: ?[]?types_mod.StaticDispatchConstraint.SafeList.Range = null,
    expected_failure_order: ?[]u32 = null,
    expected_failure_map: ?[]u32 = null,
    expected_retirement_order: ?[]u32 = null,
    expected_retirement_map: ?[]u32 = null,
    expected_plan_order: ?[]u32 = null,
    expected_plan_map: ?[]u32 = null,
    where_source_order: ?[]u32 = null,
    where_source_map: ?[]u32 = null,

    referenced_constraints: ?[]bool = null,
    referenced_steps: ?[]bool = null,
    referenced_default_decisions: ?[]bool = null,
    referenced_moves: ?[]bool = null,
    referenced_selected_anchors: ?[]bool = null,
    referenced_selected_moves: ?[]bool = null,
    referenced_evidence_nodes: std.AutoHashMap(ConstraintEvidenceNode, void),
    retained_constraint_count: usize = 0,
    retained_step_count: usize = 0,
    retained_default_decision_count: usize = 0,
    retained_default_contributor_count: usize = 0,
    retained_move_count: usize = 0,
    retained_selected_anchor_count: usize = 0,
    retained_selected_move_count: usize = 0,

    replacement_constraints: types_mod.StaticDispatchConstraint.SafeList = .{},
    replacement_evidence_handles: MkSafeList(types_mod.ConstraintEvidenceHandle) = .{},
    replacement_contracts: types_mod.WhereMethodMarkerContract.SafeList = .{},
    replacement_bases: types_mod.WhereMethodMarkerBasis.SafeList = .{},
    replacement_type_paths: types_mod.WhereMethodMarkerPathStep.SafeList = .{},
    relocations: ?[]CheckedBoundaryConstraintRelocation = null,
    marker_offset_maps: std.ArrayListUnmanaged(u32) = .empty,
    staged_sources: ?[]ModuleEnv.WhereMethodSource = null,

    step_map: ?[]u32 = null,
    default_decision_map: ?[]u32 = null,
    step_provider_envs: ?[]?*const ModuleEnv = null,
    pair_relocations: ?[]u32 = null,
    constraint_pair_relocations: ?[]u32 = null,
    occurrence_relocations: ?[]u32 = null,
    copied_literal_group_map: ?[]u32 = null,
    copied_literal_event_map: ?[]u32 = null,
    replacement_steps: ModuleEnv.WhereMarkerCopyStep.SafeList = .{},
    replacement_pairs: ModuleEnv.WhereMarkerCopyPair.SafeList = .{},
    replacement_occurrences: ModuleEnv.WhereMarkerCopyOccurrence.SafeList = .{},
    replacement_constraint_pairs: ModuleEnv.WhereMarkerConstraintCopyPair.SafeList = .{},
    replacement_witnesses: ModuleEnv.WhereMarkerCopyWitness.SafeList = .{},
    replacement_copied_literal_groups: ModuleEnv.CopiedOpenLiteralGroup.SafeList = .{},
    replacement_copied_literal_events: ModuleEnv.CopiedOpenLiteralEvent.SafeList = .{},
    replacement_substitutions: ModuleEnv.WhereMarkerPlatformSubstitution.SafeList = .{},

    replacement_external_cache_seeds: ModuleEnv.ExternalCacheSeed.SafeList = .{},
    replacement_expected_failures: ModuleEnv.ExpectedFailure.SafeList = .{},
    replacement_expected_plans: ModuleEnv.ExpectedConsumptionPlan.SafeList = .{},
    replacement_expected_call_formals: ModuleEnv.ExpectedCallFormal.SafeList = .{},
    replacement_expected_ambiguity_retirements: ModuleEnv.ExpectedAmbiguityRetirement.SafeList = .{},
    replacement_expected_retirements: ModuleEnv.ExpectedConsumerRetirement.SafeList = .{},
    replacement_expected_retirement_failures: ModuleEnv.ExpectedRetirementFailure.SafeList = .{},
    replacement_expected_retired_consumers: ModuleEnv.ExpectedRetiredConsumer.SafeList = .{},

    replacement_default_decisions: ModuleEnv.DefaultDecision.SafeList = .{},
    replacement_default_contributors: ModuleEnv.DefaultDecisionContributor.SafeList = .{},
    replacement_selected_anchors: ModuleEnv.SelectedReceiverAnchor.SafeList = .{},
    replacement_for_loop_plans: ModuleEnv.ForLoopDispatchPlan.SafeList = .{},
    replacement_settlement_sources: ModuleEnv.DispatchSettlementSource.SafeList = .{},
    replacement_selected_moves: ModuleEnv.ConstraintEvidenceMove.SafeList = .{},
    replacement_selected_decisions: ModuleEnv.SelectedMethodDecision.SafeList = .{},
    replacement_selected_decision_moves: ModuleEnv.SelectedMethodDecisionMove.SafeList = .{},
    replacement_moves: ModuleEnv.WhereMarkerConstraintMove.SafeList = .{},
    replacement_move_offsets: MkSafeList(u32) = .{},

    staged_alias_expansions: ?[]ModuleEnv.WhereAliasExpansion = null,
    staged_codec_requirements: ?[]ModuleEnv.BindingSchemeCodecRequirement = null,
    staged_marker_uses: ?[]ModuleEnv.WhereMethodMarkerUse = null,
    replacement_use_paths: ModuleEnv.WhereMethodMarkerPathStep.SafeList = .{},
    replacement_authorizations: ModuleEnv.ResultRowWideningUse.SafeList = .{},
    remapped_live_ranges: ?[]?types_mod.StaticDispatchConstraint.SafeList.Range = null,

    fn init(checker: *Self) Transaction {
        if (checker.probe_depth != 0) {
            @panic("where-method checked-boundary rebuild cannot run under a checker probe");
        }
        return .{
            .checker = checker,
            .input = Input.capture(checker),
            .referenced_evidence_nodes = std.AutoHashMap(
                ConstraintEvidenceNode,
                void,
            ).init(checker.gpa),
        };
    }

    fn freeOptional(comptime T: type, allocator: Allocator, maybe_items: ?[]T) void {
        if (maybe_items) |items| allocator.free(items);
    }

    fn deinit(transaction: *Transaction) void {
        const self = transaction.checker;

        freeOptional(u32, self.gpa, transaction.external_seed_order);
        freeOptional(u32, self.gpa, transaction.external_seed_map);
        freeOptional(?types_mod.StaticDispatchConstraint.SafeList.Range, self.gpa, transaction.live_ranges);
        freeOptional(u32, self.gpa, transaction.expected_failure_order);
        freeOptional(u32, self.gpa, transaction.expected_failure_map);
        freeOptional(u32, self.gpa, transaction.expected_retirement_order);
        freeOptional(u32, self.gpa, transaction.expected_retirement_map);
        freeOptional(u32, self.gpa, transaction.expected_plan_order);
        freeOptional(u32, self.gpa, transaction.expected_plan_map);
        freeOptional(u32, self.gpa, transaction.where_source_order);
        freeOptional(u32, self.gpa, transaction.where_source_map);
        freeOptional(bool, self.gpa, transaction.referenced_constraints);
        freeOptional(bool, self.gpa, transaction.referenced_steps);
        freeOptional(bool, self.gpa, transaction.referenced_default_decisions);
        freeOptional(bool, self.gpa, transaction.referenced_moves);
        freeOptional(bool, self.gpa, transaction.referenced_selected_anchors);
        freeOptional(bool, self.gpa, transaction.referenced_selected_moves);
        transaction.referenced_evidence_nodes.deinit();

        transaction.replacement_constraints.deinit(self.types.gpa);
        transaction.replacement_evidence_handles.deinit(self.types.gpa);
        transaction.replacement_contracts.deinit(self.types.gpa);
        transaction.replacement_bases.deinit(self.types.gpa);
        transaction.replacement_type_paths.deinit(self.types.gpa);
        freeOptional(CheckedBoundaryConstraintRelocation, self.gpa, transaction.relocations);
        transaction.marker_offset_maps.deinit(self.gpa);
        freeOptional(ModuleEnv.WhereMethodSource, self.gpa, transaction.staged_sources);
        freeOptional(u32, self.gpa, transaction.step_map);
        freeOptional(u32, self.gpa, transaction.default_decision_map);
        freeOptional(?*const ModuleEnv, self.gpa, transaction.step_provider_envs);
        freeOptional(u32, self.gpa, transaction.pair_relocations);
        freeOptional(u32, self.gpa, transaction.constraint_pair_relocations);
        freeOptional(u32, self.gpa, transaction.occurrence_relocations);
        freeOptional(u32, self.gpa, transaction.copied_literal_group_map);
        freeOptional(u32, self.gpa, transaction.copied_literal_event_map);

        transaction.replacement_steps.deinit(self.cir.gpa);
        transaction.replacement_pairs.deinit(self.cir.gpa);
        transaction.replacement_occurrences.deinit(self.cir.gpa);
        transaction.replacement_constraint_pairs.deinit(self.cir.gpa);
        transaction.replacement_witnesses.deinit(self.cir.gpa);
        transaction.replacement_copied_literal_groups.deinit(self.cir.gpa);
        transaction.replacement_copied_literal_events.deinit(self.cir.gpa);
        transaction.replacement_substitutions.deinit(self.cir.gpa);
        transaction.replacement_external_cache_seeds.deinit(self.cir.gpa);
        transaction.replacement_expected_failures.deinit(self.cir.gpa);
        transaction.replacement_expected_plans.deinit(self.cir.gpa);
        transaction.replacement_expected_call_formals.deinit(self.cir.gpa);
        transaction.replacement_expected_ambiguity_retirements.deinit(self.cir.gpa);
        transaction.replacement_expected_retirements.deinit(self.cir.gpa);
        transaction.replacement_expected_retirement_failures.deinit(self.cir.gpa);
        transaction.replacement_expected_retired_consumers.deinit(self.cir.gpa);
        transaction.replacement_default_decisions.deinit(self.cir.gpa);
        transaction.replacement_default_contributors.deinit(self.cir.gpa);
        transaction.replacement_selected_anchors.deinit(self.cir.gpa);
        transaction.replacement_for_loop_plans.deinit(self.cir.gpa);
        transaction.replacement_settlement_sources.deinit(self.cir.gpa);
        transaction.replacement_selected_moves.deinit(self.cir.gpa);
        transaction.replacement_selected_decisions.deinit(self.cir.gpa);
        transaction.replacement_selected_decision_moves.deinit(self.cir.gpa);
        transaction.replacement_moves.deinit(self.cir.gpa);
        transaction.replacement_move_offsets.deinit(self.cir.gpa);

        freeOptional(ModuleEnv.WhereAliasExpansion, self.gpa, transaction.staged_alias_expansions);
        freeOptional(ModuleEnv.BindingSchemeCodecRequirement, self.gpa, transaction.staged_codec_requirements);
        freeOptional(ModuleEnv.WhereMethodMarkerUse, self.gpa, transaction.staged_marker_uses);
        transaction.replacement_use_paths.deinit(self.cir.gpa);
        transaction.replacement_authorizations.deinit(self.cir.gpa);
        freeOptional(?types_mod.StaticDispatchConstraint.SafeList.Range, self.gpa, transaction.remapped_live_ranges);
    }

    fn validateAndOrder(transaction: *Transaction) Allocator.Error!void {
        const self = transaction.checker;
        const old_constraints = transaction.input.constraints;
        const old_contracts = transaction.input.contracts;
        const old_bases = transaction.input.bases;
        const old_type_paths = transaction.input.type_paths;
        const old_steps = transaction.input.steps;
        const old_default_decisions = transaction.input.default_decisions;
        const old_default_contributors = transaction.input.default_contributors;
        const old_selected_decisions = transaction.input.selected_decisions;
        const old_selected_anchors = transaction.input.selected_anchors;
        const old_settlement_sources = transaction.input.settlement_sources;
        const old_selected_moves = transaction.input.selected_moves;
        const old_selected_decision_moves = transaction.input.selected_decision_moves;
        const old_pairs = transaction.input.pairs;
        const old_occurrences = transaction.input.occurrences;
        const old_constraint_pairs = transaction.input.constraint_pairs;
        const old_witnesses = transaction.input.witnesses;
        const old_copied_literal_groups = transaction.input.copied_literal_groups;
        const old_copied_literal_events = transaction.input.copied_literal_events;
        const old_substitutions = transaction.input.substitutions;
        const old_moves = transaction.input.moves;
        const old_move_offsets = transaction.input.move_offsets;
        const old_expected_plans = transaction.input.expected_plans;
        const old_expected_failures = transaction.input.expected_failures;
        const old_expected_retirements = transaction.input.expected_retirements;
        const old_expected_ambiguity_retirements = transaction.input.expected_ambiguity_retirements;
        const old_expected_retirement_failures = transaction.input.expected_retirement_failures;
        const old_expected_retired_consumers = transaction.input.expected_retired_consumers;
        const old_external_cache_seeds = transaction.input.external_cache_seeds;
        const old_where_sources = transaction.input.where_method_sources;

        transaction.where_source_order = try self.gpa.alloc(u32, old_where_sources.len);
        const where_source_order = transaction.where_source_order.?;
        transaction.where_source_map = try self.gpa.alloc(u32, old_where_sources.len);
        const where_source_map = transaction.where_source_map.?;
        @memset(where_source_map, none);
        for (where_source_order, 0..) |*old_index, index| old_index.* = @intCast(index);
        std.mem.sortUnstable(
            u32,
            where_source_order,
            old_where_sources,
            struct {
                fn lessThan(
                    sources: []const ModuleEnv.WhereMethodSource,
                    lhs_index: u32,
                    rhs_index: u32,
                ) bool {
                    const order = compareWhereMethodSources(sources[lhs_index], sources[rhs_index]);
                    return order == .lt or (order == .eq and lhs_index < rhs_index);
                }
            }.lessThan,
        );
        for (where_source_order, 0..) |old_source_index, new_source_index| {
            const source = old_where_sources[old_source_index];
            const expected_ordinal: u32 = if (new_source_index == 0 or
                old_where_sources[where_source_order[new_source_index - 1]].owner_node != source.owner_node)
                0
            else
                std.math.add(
                    u32,
                    old_where_sources[where_source_order[new_source_index - 1]].source_ordinal,
                    1,
                ) catch @panic("where-method source ordinal overflowed");
            var settlement_plan_count: usize = 0;
            for (old_settlement_sources) |settlement_source| {
                if (settlement_source.decodedKind() == .where_requirement and
                    settlement_source.payload.where_requirement.source_index == old_source_index)
                {
                    settlement_plan_count += 1;
                }
            }
            const owner_authentic = whereMethodSourceOwnerRootIsAuthentic(self.cir, source.owner_node);
            const source_owner = sourceProducerOwnerForKey(
                self.cir,
                source.owner_node,
                source.where_node,
                source.method_ident,
            );
            const retained_in_bounds = source.retained_constraint_index < old_constraints.len;
            const has_evidence = retained_in_bounds and self.constraintHasEvidenceHandle(
                source.retained_constraint_index,
                .{
                    .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.where_requirement_source),
                    .index = old_source_index,
                },
            );
            const strict_order = new_source_index == 0 or compareWhereMethodSources(
                old_where_sources[where_source_order[new_source_index - 1]],
                source,
            ) == .lt;
            if (source.source_ordinal != expected_ordinal or
                !owner_authentic or source_owner == null or !retained_in_bounds or
                !has_evidence or settlement_plan_count != 1 or !strict_order)
            {
                @panic("checked-boundary where-method source key was not canonical");
            }
            where_source_map[old_source_index] = @intCast(new_source_index);
        }

        transaction.external_seed_order = try self.gpa.alloc(u32, old_external_cache_seeds.len);
        const external_seed_order = transaction.external_seed_order.?;
        transaction.external_seed_map = try self.gpa.alloc(u32, old_external_cache_seeds.len);
        const external_seed_map = transaction.external_seed_map.?;
        @memset(external_seed_map, none);
        for (external_seed_order, 0..) |*slot, index| slot.* = @intCast(index);
        std.mem.sortUnstable(
            u32,
            external_seed_order,
            old_external_cache_seeds,
            struct {
                fn lessThan(
                    seeds: []const ModuleEnv.ExternalCacheSeed,
                    left_index: u32,
                    right_index: u32,
                ) bool {
                    return ModuleEnv.ExternalCacheSeed.canonicalLessThan(
                        {},
                        seeds[left_index],
                        seeds[right_index],
                    );
                }
            }.lessThan,
        );
        for (external_seed_order, 0..) |old_seed_index, new_seed_index| {
            const seed = old_external_cache_seeds[old_seed_index];
            if (!seed.hasCanonicalTags() or seed.support_step >= old_steps.len or
                @as(usize, seed.seed_token) >= self.cir.external_lookup_tokens.items.items.len)
            {
                @panic("checked-boundary external cache seed was incomplete");
            }
            const minimum = self.cir.minimumExternalLookupToken(seed.key) orelse
                @panic("checked-boundary external cache seed had no owning token");
            const token = self.cir.external_lookup_tokens.items.items[seed.seed_token];
            if (@intFromEnum(minimum) != seed.seed_token or
                !ModuleEnv.ExternalLookupKey.eql(token.key, seed.key) or
                token.origin_node != seed.seed_node)
            {
                @panic("checked-boundary external cache seed changed its minimum token");
            }
            const support = old_steps[seed.support_step];
            if (support.decodedKind() != .external_cache_seed or
                support.origin.external_cache_seed.seed_row != old_seed_index)
            {
                @panic("checked-boundary external cache seed lost its support-step inverse");
            }
            if (new_seed_index != 0) {
                const previous = old_external_cache_seeds[external_seed_order[new_seed_index - 1]];
                if (ModuleEnv.ExternalLookupKey.eql(previous.key, seed.key)) {
                    @panic("checked-boundary external cache key had two seed rows");
                }
            }
            external_seed_map[old_seed_index] = @intCast(new_seed_index);
        }

        transaction.live_ranges = try self.gpa.alloc(
            ?types_mod.StaticDispatchConstraint.SafeList.Range,
            self.types.checkedBoundaryDescriptorCount(),
        );
        const live_ranges = transaction.live_ranges.?;
        self.types.snapshotCheckedBoundaryLiveConstraintRanges(live_ranges);

        var old_default_contributor_end: usize = 0;
        for (old_default_decisions) |decision| {
            const constraints_start: usize = decision.constraints_start;
            const constraints_len: usize = decision.constraints_len;
            const target = decision.decodedTarget() orelse
                @panic("checked-boundary default decision had an invalid target");
            if (decision.receiver_var >= self.types.len() or constraints_len == 0 or
                constraints_start > old_constraints.len or
                constraints_len > old_constraints.len - constraints_start or
                decision.contributors_len == 0 or
                decision.contributors_start != old_default_contributor_end or
                decision.contributors_start > old_default_contributors.len or
                decision.contributors_len > old_default_contributors.len - decision.contributors_start)
            {
                @panic("checked-boundary default decision escaped its receiver/range/contributor ownership");
            }
            const selected_target = self.specializationDefaultTargetForConstraints(
                old_constraints[constraints_start..][0..constraints_len],
            ) orelse @panic("checked-boundary default decision owned a non-defaultable range");
            const expected_target: ModuleEnv.DefaultDecision.Target = switch (selected_target) {
                .dec => .dec,
                .str => .str,
            };
            if (target != expected_target) {
                @panic("checked-boundary default target disagreed with its complete constraint range");
            }

            const contributors = old_default_contributors[decision.contributors_start..][0..decision.contributors_len];
            for (contributors, 0..) |contributor, contributor_offset| {
                if (contributor_offset != 0 and
                    !ModuleEnv.DefaultDecisionContributor.canonicalLessThan(
                        contributors[contributor_offset - 1],
                        contributor,
                    ))
                {
                    @panic("checked-boundary default contributor range was not strictly canonical");
                }
                const driver_kind = contributor.decodedDriverKind() orelse
                    @panic("checked-boundary default contributor had an invalid driver kind");
                switch (driver_kind) {
                    .instantiation_copy => {
                        if (contributor.driver_copy_step >= old_steps.len or
                            contributor.driver_pair_offset >= old_steps[contributor.driver_copy_step].pairs_len or
                            contributor.literal_source_node != 0 or
                            contributor.literal_occurrence_kind != 0 or contributor.literal_kind != 0)
                        {
                            @panic("checked-boundary instantiation default contributor was malformed");
                        }
                        const step = old_steps[contributor.driver_copy_step];
                        const pair = old_pairs[step.pairs_start + contributor.driver_pair_offset];
                        if (pair.destination_var >= self.types.len() or
                            self.types.resolveVar(@enumFromInt(pair.destination_var)).var_ !=
                                self.types.resolveVar(@enumFromInt(decision.receiver_var)).var_)
                        {
                            @panic("checked-boundary instantiation contributor named a different receiver");
                        }
                    },
                    .literal_creation => {
                        const literal_kind = contributor.decodedLiteralKind() orelse
                            @panic("checked-boundary literal contributor had an invalid kind");
                        const occurrence_kind = contributor.decodedLiteralOccurrenceKind() orelse
                            @panic("checked-boundary literal contributor had an invalid occurrence kind");
                        if (contributor.driver_copy_step != 0 or contributor.driver_pair_offset != 0 or
                            contributor.literal_source_node >= self.cir.store.nodes.len() or
                            contributor.literal_source_node >= self.types.len() or
                            !literalCreationDriverMatchesTag(
                                occurrence_kind,
                                literal_kind,
                                self.cir.store.nodes.get(
                                    @as(CIR.Node.Idx, @enumFromInt(contributor.literal_source_node)),
                                ).tag,
                            ) or
                            self.types.resolveVar(@as(Var, @enumFromInt(contributor.literal_source_node))).var_ !=
                                self.types.resolveVar(@enumFromInt(decision.receiver_var)).var_)
                        {
                            @panic("checked-boundary literal default contributor was malformed");
                        }
                    },
                }
            }
            old_default_contributor_end += decision.contributors_len;
        }
        if (old_default_contributor_end != old_default_contributors.len) {
            @panic("checked-boundary default contributor pool had orphan rows");
        }

        // Validate every checker-produced owner range before selecting roots.
        for (old_constraints, 0..) |constraint, old_constraint_index| {
            const evidence_start: usize = constraint.constraint_evidence.start;
            const evidence_len: usize = constraint.constraint_evidence.len;
            const evidence_pool = self.types.constraint_evidence_handles.items.items;
            if (evidence_start > evidence_pool.len or
                evidence_len > evidence_pool.len - evidence_start)
            {
                @panic("checked-boundary constraint-evidence handle range escaped its pool");
            }
            const evidence_handles = evidence_pool[evidence_start..][0..evidence_len];
            for (evidence_handles, 0..) |handle, handle_offset| {
                const kind = handle.decodedKind() orelse
                    @panic("checked-boundary constraint evidence had an invalid kind");
                if ((handle_offset != 0 and !types_mod.ConstraintEvidenceHandle.canonicalLessThan(
                    {},
                    evidence_handles[handle_offset - 1],
                    handle,
                )) or
                    switch (kind) {
                        .selected_receiver_anchor => handle.index >= old_selected_anchors.len,
                        .where_requirement_source => handle.index >= old_where_sources.len or
                            !constraintEvidenceHasCreationPath(
                                self.cir,
                                handle,
                                old_where_sources[handle.index].retained_constraint_index,
                                @intCast(old_constraint_index),
                            ),
                        .copied_literal_event => blk: {
                            const creation = copiedOpenLiteralEventCreationConstraint(
                                self.cir,
                                handle.index,
                            ) orelse break :blk true;
                            break :blk !constraintEvidenceHasCreationPath(
                                self.cir,
                                handle,
                                creation,
                                @intCast(old_constraint_index),
                            );
                        },
                    })
                {
                    @panic("checked-boundary constraint-evidence handle range was not canonical");
                }
            }
            const marker_len: usize = constraint.where_method_markers.len();
            const basis_len: usize = constraint.where_method_marker_bases.len();
            const marker_start: usize = if (marker_len == 0)
                0
            else
                @intFromEnum(constraint.where_method_markers.start);
            const basis_start: usize = if (basis_len == 0)
                0
            else
                @intFromEnum(constraint.where_method_marker_bases.start);
            if (marker_start > old_contracts.len or marker_len > old_contracts.len - marker_start or
                basis_start > old_bases.len or basis_len > old_bases.len - basis_start or
                (marker_len == 0 and basis_len != 0))
            {
                @panic("checked-boundary static-dispatch metadata range escaped its pool");
            }
            const markers = old_contracts[marker_start..][0..marker_len];
            for (markers, 0..) |marker, marker_offset| {
                if (marker.positionOrNull() == null or marker.isWidened() == null or marker.isReady() == null or
                    marker.path_len == 0 or marker.path_start > old_type_paths.len or
                    marker.path_len > old_type_paths.len - marker.path_start)
                {
                    @panic("checked-boundary marker occurrence was malformed");
                }
                _ = marker.hasProducer();
                if (marker_offset != 0 and
                    self.compareWhereMethodMarkerContracts(markers[marker_offset - 1], marker) == .gt)
                {
                    @panic("checked-boundary marker occurrence range was not sorted");
                }
            }
            for (old_bases[basis_start..][0..basis_len], 0..) |basis, basis_offset| {
                if (basis.marker_offset >= marker_len or basis.copy_step >= old_steps.len) {
                    @panic("checked-boundary marker basis escaped its owner");
                }
                if (basis_offset != 0 and !checkedBoundaryBasisLessThan(
                    {},
                    old_bases[basis_start + basis_offset - 1],
                    basis,
                )) {
                    @panic("checked-boundary marker basis range was not canonical");
                }
            }
        }

        for (old_selected_anchors, 0..) |anchor, anchor_index| {
            self.validateSelectedReceiverAnchorForDecision(
                @intCast(anchor_index),
                @enumFromInt(anchor.receiver_var),
            );
        }
        for (old_settlement_sources) |source| {
            if (!source.hasCanonicalTags()) {
                @panic("dispatch-settlement source had a noncanonical producer arm");
            }
            if (source.primaryAnchorIndex()) |anchor_index| {
                if (anchor_index >= old_selected_anchors.len) {
                    @panic("dispatch-settlement source escaped its selected-receiver anchor pool");
                }
            }
        }
        var seen_evidence_moves = std.AutoHashMap(
            ModuleEnv.ConstraintEvidenceMove,
            void,
        ).init(self.gpa);
        defer seen_evidence_moves.deinit();
        try seen_evidence_moves.ensureTotalCapacity(@intCast(old_selected_moves.len));
        for (old_selected_moves) |move| {
            if (move.handle.decodedKind() == null or
                move.source_constraint_index >= move.destination_constraint_index or
                move.destination_constraint_index >= old_constraints.len or
                !self.constraintHasEvidenceHandle(
                    move.source_constraint_index,
                    move.handle,
                ) or
                !self.constraintHasEvidenceHandle(
                    move.destination_constraint_index,
                    move.handle,
                ))
            {
                @panic("checked-boundary constraint-evidence movement was malformed");
            }
            switch (move.handle.decodedKind().?) {
                .selected_receiver_anchor => if (move.handle.index >= old_selected_anchors.len) {
                    @panic("checked-boundary selected-receiver movement escaped its anchor pool");
                },
                .where_requirement_source => if (move.handle.index >= old_where_sources.len) {
                    @panic("checked-boundary where-source movement escaped its source pool");
                } else if (!constraintEvidenceHasCreationPath(
                    self.cir,
                    move.handle,
                    old_where_sources[move.handle.index].retained_constraint_index,
                    move.source_constraint_index,
                ) or !constraintEvidenceHasCreationPath(
                    self.cir,
                    move.handle,
                    old_where_sources[move.handle.index].retained_constraint_index,
                    move.destination_constraint_index,
                )) {
                    @panic("checked-boundary where-source movement was disconnected from its creation source");
                },
                .copied_literal_event => {
                    const creation = copiedOpenLiteralEventCreationConstraint(
                        self.cir,
                        move.handle.index,
                    ) orelse @panic("checked-boundary copied-literal movement escaped its event pool");
                    if (!constraintEvidenceHasCreationPath(
                        self.cir,
                        move.handle,
                        creation,
                        move.source_constraint_index,
                    ) or !constraintEvidenceHasCreationPath(
                        self.cir,
                        move.handle,
                        creation,
                        move.destination_constraint_index,
                    )) {
                        @panic("checked-boundary copied-literal movement was disconnected from its creation event");
                    }
                },
            }
            const entry = seen_evidence_moves.getOrPutAssumeCapacity(move);
            if (entry.found_existing) {
                @panic("checked-boundary constraint-evidence movement repeated a producer transition");
            }
        }

        var selected_decision_move_end: usize = 0;
        var previous_selected_scheme_use: ?u32 = null;
        for (old_selected_decisions) |decision| {
            const decision_moves_start: usize = decision.constraint_moves_start;
            const decision_moves_len: usize = decision.constraint_moves_len;
            if (decision.decodedState() != .complete or
                decision.constraint_index >= old_constraints.len or
                decision.receiver_var >= self.types.len() or
                decision.scheme_use_index >= self.cir.scheme_uses.items.items.len or
                decision.root_copy_step >= old_steps.len or
                decision.use_copy_step >= old_steps.len or
                decision.root_copy_step >= decision.use_copy_step or
                decision_moves_start != selected_decision_move_end or
                decision_moves_start > old_selected_decision_moves.len or
                decision_moves_len > old_selected_decision_moves.len - decision_moves_start)
            {
                @panic("checked-boundary selected decision escaped its exact owner ranges");
            }
            if (previous_selected_scheme_use) |previous| {
                if (previous >= decision.scheme_use_index) {
                    @panic("checked-boundary selected decisions were not in dispatch-target event order");
                }
            }
            previous_selected_scheme_use = decision.scheme_use_index;

            const constraint = old_constraints[decision.constraint_index];
            if (decision.constraint_evidence_len == 0 or
                decision.constraint_evidence_start != constraint.constraint_evidence.start or
                decision.constraint_evidence_len != constraint.constraint_evidence.len)
            {
                @panic("checked-boundary selected decision did not consume its terminal handle set");
            }
            const use = self.cir.scheme_uses.items.items[decision.scheme_use_index];
            const root_step = old_steps[decision.root_copy_step];
            const use_step = old_steps[decision.use_copy_step];
            if (use.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target) or
                use.slot_data != @intFromEnum(constraint.fn_var) or
                use.scheme_root >= self.types.len() or
                use_step.decodedKind() != .scheme_use or
                use_step.origin.scheme_use.scheme_use_index != decision.scheme_use_index or
                root_step.destination_root_var >= self.types.len() or
                use_step.source_root_var >= self.types.len() or
                self.types.resolveVar(@enumFromInt(use.scheme_root)).var_ !=
                    self.types.resolveVar(@enumFromInt(root_step.destination_root_var)).var_ or
                self.types.resolveVar(@enumFromInt(use.scheme_root)).var_ !=
                    self.types.resolveVar(@enumFromInt(use_step.source_root_var)).var_)
            {
                @panic("checked-boundary selected decision disagreed with its SchemeUse/root steps");
            }

            var expected_moves: std.ArrayListUnmanaged(ModuleEnv.SelectedMethodDecisionMove) = .empty;
            defer expected_moves.deinit(self.gpa);
            const expected_receiver = try self.collectSelectedMethodDecisionMoves(
                @enumFromInt(decision.receiver_var),
                decision.constraint_index,
                constraint,
                &expected_moves,
            );
            if (expected_receiver != decision.receiver_var) {
                @panic("checked-boundary selected decision did not name its canonical receiver anchor");
            }
            const recorded_moves = old_selected_decision_moves[decision_moves_start..][0..decision_moves_len];
            if (expected_moves.items.len != recorded_moves.len) {
                @panic("checked-boundary selected decision did not own its complete canonical movement DAG");
            }
            for (expected_moves.items, recorded_moves) |expected, recorded| {
                if (!std.meta.eql(expected, recorded)) {
                    @panic("checked-boundary selected decision did not own its complete canonical movement DAG");
                }
            }
            selected_decision_move_end += decision_moves_len;
        }
        if (selected_decision_move_end != old_selected_decision_moves.len) {
            @panic("checked-boundary selected decision movement pool contained orphan rows");
        }

        // A reserved outer step can complete after nested steps, so preterminal
        // owner ranges are not ordered by step id. Validate an exact nonoverlapping
        // partition here; the replacement transaction below restores canonical
        // step-id order in checked output.
        const owned_pairs = try self.gpa.alloc(bool, old_pairs.len);
        defer self.gpa.free(owned_pairs);
        @memset(owned_pairs, false);
        const owned_occurrences = try self.gpa.alloc(bool, old_occurrences.len);
        defer self.gpa.free(owned_occurrences);
        @memset(owned_occurrences, false);
        const owned_constraint_pairs = try self.gpa.alloc(bool, old_constraint_pairs.len);
        defer self.gpa.free(owned_constraint_pairs);
        @memset(owned_constraint_pairs, false);
        const owned_witnesses = try self.gpa.alloc(bool, old_witnesses.len);
        defer self.gpa.free(owned_witnesses);
        @memset(owned_witnesses, false);
        const owned_copied_literal_groups = try self.gpa.alloc(bool, old_copied_literal_groups.len);
        defer self.gpa.free(owned_copied_literal_groups);
        @memset(owned_copied_literal_groups, false);
        const owned_copied_literal_events = try self.gpa.alloc(bool, old_copied_literal_events.len);
        defer self.gpa.free(owned_copied_literal_events);
        @memset(owned_copied_literal_events, false);
        const owned_substitutions = try self.gpa.alloc(bool, old_substitutions.len);
        defer self.gpa.free(owned_substitutions);
        @memset(owned_substitutions, false);
        for (old_steps, 0..) |step, step_index| {
            const kind = step.decodedKind() orelse
                @panic("checked-boundary marker-copy step had an invalid kind");
            if (kind == .reserved) {
                @panic("checked-boundary rebuild encountered a reserved marker-copy step");
            }
            if (kind == .discarded) {
                if (step.copy_policy != 0 or step.source_root_var != 0 or
                    step.destination_root_var != 0 or step.pairs_start != 0 or
                    step.pairs_len != 0 or step.occurrences_start != 0 or
                    step.occurrences_len != 0 or step.root_occurrence_offset != 0 or
                    step.constraint_pairs_start != 0 or step.constraint_pairs_len != 0 or
                    step.witnesses_start != 0 or step.witnesses_len != 0 or
                    step.copied_groups_start != 0 or step.copied_groups_len != 0 or
                    !std.mem.allEqual(u8, std.mem.asBytes(&step.origin.discarded), 0))
                {
                    @panic("checked-boundary discarded marker-copy step was not canonical");
                }
                if (self.localWhereMarkerCopyStepIsReferenced(@intCast(step_index))) {
                    @panic("checked-boundary discarded marker-copy step retained a reference");
                }
                continue;
            }
            if (kind == .selected_dispatch_method) {
                const origin = step.origin.selected_dispatch_method;
                if (origin.decision_index >= old_selected_decisions.len) {
                    @panic("selected-method marker-copy origin escaped its decision ledger");
                }
                const decision = old_selected_decisions[origin.decision_index];
                if (decision.decodedState() != .complete or
                    decision.root_copy_step != step_index)
                {
                    @panic("selected-method marker-copy origin did not name its exact first decision");
                }
            }
            if (kind == .default_method) {
                const origin = step.origin.default_method;
                if (origin.decision_index >= old_default_decisions.len or
                    origin.constraint_offset >= old_default_decisions[origin.decision_index].constraints_len or
                    origin.reserved_0 != 0)
                {
                    @panic("default-method marker-copy origin escaped its exact decision anchors");
                }
                const decision = old_default_decisions[origin.decision_index];
                for (old_default_contributors[decision.contributors_start..][0..decision.contributors_len]) |contributor| {
                    if (contributor.decodedDriverKind().? == .instantiation_copy and
                        @as(usize, contributor.driver_copy_step) >= step_index)
                    {
                        @panic("default-method decision named a non-prior instantiation contributor");
                    }
                }
            }
            if (kind == .default_method_use) {
                const origin = step.origin.default_method_use;
                if (origin.decision_index >= old_default_decisions.len or
                    origin.constraint_offset >= old_default_decisions[origin.decision_index].constraints_len or
                    origin.scheme_use_index >= self.cir.scheme_uses.items.items.len or
                    origin.root_copy_step >= step_index)
                {
                    @panic("default-method use step escaped its exact decision/use/root anchors");
                }
                const root_step = old_steps[origin.root_copy_step];
                const root_kind = root_step.decodedKind() orelse
                    @panic("default-method use named an invalid cached root");
                const use = self.cir.scheme_uses.items.items[origin.scheme_use_index];
                if (root_kind.sourceNamespace() != .cross_module or
                    root_step.destination_root_var >= self.types.len() or
                    step.source_root_var >= self.types.len() or
                    use.scheme_root >= self.types.len() or
                    self.types.resolveVar(@enumFromInt(root_step.destination_root_var)).var_ !=
                        self.types.resolveVar(@enumFromInt(step.source_root_var)).var_ or
                    self.types.resolveVar(@enumFromInt(use.scheme_root)).var_ !=
                        self.types.resolveVar(@enumFromInt(step.source_root_var)).var_)
                {
                    @panic("default-method use did not descend from its exact cached root/SchemeUse");
                }
            }
            const pair_start: usize = step.pairs_start;
            const pair_len: usize = step.pairs_len;
            if (pair_len == 0 or pair_start > old_pairs.len or pair_len > old_pairs.len - pair_start) {
                @panic("checked-boundary marker-copy pair ownership was invalid");
            }
            markCheckedBoundaryOwnedRange(owned_pairs, step.pairs_start, step.pairs_len);
            var root_pairs: usize = 0;
            for (old_pairs[pair_start..][0..pair_len], 0..) |pair, pair_offset| {
                if ((kind.sourceNamespace() == .local and pair.source_var >= self.types.len()) or
                    pair.destination_var >= self.types.len() or
                    (pair_offset != 0 and !durableWhereMarkerCopyPairLessThan(
                        {},
                        old_pairs[pair_start + pair_offset - 1],
                        pair,
                    )))
                {
                    @panic("checked-boundary marker-copy relation was not a strict tuple ordering");
                }
                if (pair.source_var == step.source_root_var and
                    pair.destination_var == step.destination_root_var)
                {
                    root_pairs += 1;
                }
            }
            if (root_pairs != 1) {
                @panic("checked-boundary marker-copy relation did not own exactly one root pair");
            }
            const occurrence_start: usize = step.occurrences_start;
            const occurrence_len: usize = step.occurrences_len;
            if (occurrence_len == 0 or occurrence_start > old_occurrences.len or
                occurrence_len > old_occurrences.len - occurrence_start or
                step.root_occurrence_offset >= occurrence_len)
            {
                @panic("checked-boundary marker-copy occurrence ownership was not gapless");
            }
            markCheckedBoundaryOwnedRange(
                owned_occurrences,
                step.occurrences_start,
                step.occurrences_len,
            );
            const occurrences = old_occurrences[occurrence_start..][0..occurrence_len];
            if (!whereMarkerRawOccurrenceRelationIsFunctional(occurrences)) {
                @panic("checked-boundary marker-copy raw occurrence relation was not functional");
            }
            var expected_pair_offset: u32 = 0;
            for (occurrences, 0..) |occurrence, occurrence_offset| {
                if (occurrence.canonical_pair_offset >= pair_len or
                    occurrence.raw_destination_var >= self.types.len() or
                    (kind.sourceNamespace() == .local and occurrence.raw_source_var >= self.types.len()) or
                    (occurrence_offset != 0 and !ModuleEnv.WhereMarkerCopyOccurrence.canonicalLessThan(
                        occurrences[occurrence_offset - 1],
                        occurrence,
                    )))
                {
                    @panic("checked-boundary marker-copy occurrence was invalid");
                }
                if (occurrence.canonical_pair_offset > expected_pair_offset) {
                    @panic("checked-boundary marker-copy occurrence relation omitted a pair");
                }
                if (occurrence.canonical_pair_offset == expected_pair_offset and
                    (occurrence_offset == 0 or
                        occurrences[occurrence_offset - 1].canonical_pair_offset != expected_pair_offset))
                {
                    expected_pair_offset = std.math.add(u32, expected_pair_offset, 1) catch
                        @panic("checked-boundary marker-copy pair coverage overflowed u32");
                }
            }
            if (expected_pair_offset != pair_len or
                occurrences[step.root_occurrence_offset].canonical_pair_offset >= pair_len)
            {
                @panic("checked-boundary marker-copy occurrence relation was incomplete");
            }
            const constraint_pair_start: usize = step.constraint_pairs_start;
            const constraint_pair_len: usize = step.constraint_pairs_len;
            if (constraint_pair_start > old_constraint_pairs.len or
                constraint_pair_len > old_constraint_pairs.len - constraint_pair_start)
            {
                @panic("checked-boundary constraint-copy ownership was not gapless");
            }
            markCheckedBoundaryOwnedRange(
                owned_constraint_pairs,
                step.constraint_pairs_start,
                step.constraint_pairs_len,
            );
            const constraint_pairs = old_constraint_pairs[constraint_pair_start..][0..constraint_pair_len];
            for (constraint_pairs, 0..) |pair, pair_offset| {
                if (pair.destination_constraint_index >= old_constraints.len or
                    (kind.sourceNamespace() == .local and pair.source_constraint_index >= old_constraints.len))
                {
                    @panic("checked-boundary constraint-copy relation escaped its local store");
                }
                if (pair_offset != 0 and !ModuleEnv.WhereMarkerConstraintCopyPair.canonicalLessThan(
                    constraint_pairs[pair_offset - 1],
                    pair,
                )) {
                    @panic("checked-boundary constraint-copy relation was not strictly canonical");
                }
            }
            const witness_start: usize = step.witnesses_start;
            const witness_len: usize = step.witnesses_len;
            if (witness_start > old_witnesses.len or
                witness_len > old_witnesses.len - witness_start)
            {
                @panic("checked-boundary marker-copy witness ownership was not gapless");
            }
            markCheckedBoundaryOwnedRange(owned_witnesses, step.witnesses_start, step.witnesses_len);
            const witnesses = old_witnesses[witness_start..][0..witness_len];
            var root_action_count: usize = 0;
            for (witnesses, 0..) |witness, witness_offset| {
                const edge_kind = witness.decodedEdgeKind() orelse
                    @panic("checked-boundary marker-copy witness had an invalid edge kind");
                _ = witness.decodedAction() orelse
                    @panic("checked-boundary marker-copy witness had an invalid action");
                const auxiliary_kind = witness.decodedAuxiliaryOriginKind() orelse
                    @panic("checked-boundary marker-copy witness had an invalid auxiliary origin");
                if (witness.parent_occurrence_offset >= occurrence_len or
                    witness.child_occurrence_offset >= occurrence_len or
                    (witness.constraint_pair_offset != none and
                        witness.constraint_pair_offset >= constraint_pair_len))
                {
                    @panic("checked-boundary marker-copy witness escaped its owned relation");
                }
                const child_occurrence = occurrences[witness.child_occurrence_offset];
                const child_pair = old_pairs[
                    pair_start + child_occurrence.canonical_pair_offset
                ];
                if (auxiliary_kind != .binding_copy_pair and witness.auxiliary_origin_step != 0) {
                    @panic("checked-boundary witness retained an inactive auxiliary step");
                }
                if (auxiliary_kind == .binding_copy_pair and !bindingCodecReuseOriginIsValid(
                    old_steps,
                    old_pairs,
                    old_occurrences,
                    old_witnesses,
                    step_index,
                    witness,
                    child_pair,
                )) {
                    @panic("checked-boundary binding reuse cut lost its exact prior pair");
                }
                if (witness_offset != 0 and !ModuleEnv.WhereMarkerCopyWitness.canonicalLessThan(
                    witnesses[witness_offset - 1],
                    witness,
                )) {
                    @panic("checked-boundary marker-copy witnesses were not strictly canonical");
                }
                if (edge_kind == .root_copy_action) {
                    root_action_count += 1;
                    if (witness.parent_occurrence_offset != step.root_occurrence_offset or
                        witness.child_occurrence_offset != step.root_occurrence_offset)
                    {
                        @panic("checked-boundary root action did not self-address the exact root occurrence");
                    }
                }
            }
            if (root_action_count > 1) {
                @panic("checked-boundary marker-copy step published duplicate root actions");
            }
            const copied_group_start: usize = step.copied_groups_start;
            const copied_group_len: usize = step.copied_groups_len;
            if (copied_group_start > old_copied_literal_groups.len or
                copied_group_len > old_copied_literal_groups.len - copied_group_start)
            {
                @panic("checked-boundary copied-literal group ownership escaped its pool");
            }
            markCheckedBoundaryOwnedRange(
                owned_copied_literal_groups,
                step.copied_groups_start,
                step.copied_groups_len,
            );
            const step_groups = old_copied_literal_groups[copied_group_start..][0..copied_group_len];
            const source_env = if (kind.sourceNamespace() == .local)
                self.cir
            else
                self.checkedBoundaryCrossStepProvider(old_steps, @intCast(step_index));
            for (step_groups, 0..) |group, relative_group_index| {
                const old_group_index = step.copied_groups_start +
                    @as(u32, @intCast(relative_group_index));
                if (!group.hasCanonicalTags() or group.copy_step_index != step_index or
                    group.receiver_occurrence_offset >= step.occurrences_len or
                    !copiedOpenLiteralComponentMatchesStep(
                        self.cir,
                        group.component,
                        @intCast(step_index),
                    ) or
                    (relative_group_index != 0 and
                        !ModuleEnv.CopiedOpenLiteralGroup.canonicalLessThan(
                            step_groups[relative_group_index - 1],
                            group,
                        )))
                {
                    @panic("checked-boundary copied-literal group was not a canonical exact component");
                }
                if (!rangeFits(
                    group.destination_constraints_start,
                    group.destination_constraints_len,
                    old_constraints.len,
                ) or (kind.sourceNamespace() == .local and !rangeFits(
                    group.source_constraints_start,
                    group.source_constraints_len,
                    old_constraints.len,
                ))) {
                    @panic("checked-boundary copied-literal group escaped its constraint namespace");
                }
                if (!rangeFits(group.events_start, group.events_len, old_copied_literal_events.len)) {
                    @panic("checked-boundary copied-literal event ownership escaped its pool");
                }
                markCheckedBoundaryOwnedRange(
                    owned_copied_literal_events,
                    group.events_start,
                    group.events_len,
                );
                const events = old_copied_literal_events[group.events_start..][0..group.events_len];
                for (events, 0..) |event, event_offset| {
                    if (!event.hasCanonicalTags() or event.group_index != old_group_index or
                        event.constraint_offset >= group.destination_constraints_len or
                        (event_offset != 0 and
                            !ModuleEnv.CopiedOpenLiteralEvent.canonicalLessThan(
                                events[event_offset - 1],
                                event,
                            )))
                    {
                        @panic("checked-boundary copied-literal event range was not canonical");
                    }
                }
                for (0..group.source_constraints_len) |raw_constraint_offset| {
                    const constraint_offset: u32 = @intCast(raw_constraint_offset);
                    const expected_source = std.math.add(
                        u32,
                        group.source_constraints_start,
                        constraint_offset,
                    ) catch @panic("checked-boundary copied-literal source range overflowed");
                    const expected_destination = std.math.add(
                        u32,
                        group.destination_constraints_start,
                        constraint_offset,
                    ) catch @panic("checked-boundary copied-literal destination range overflowed");
                    if (expected_source >= source_env.types.static_dispatch_constraints.items.items.len) {
                        @panic("checked-boundary copied-literal source escaped its authenticated store");
                    }
                    var copied_source_count: usize = 0;
                    for (old_settlement_sources) |settlement_source| {
                        if (settlement_source.decodedKind() != .copied_constraint) continue;
                        const copied = settlement_source.payload.copied_constraint;
                        if (!copiedOpenLiteralGroupContainsSource(self.cir, group, copied) or
                            copied.anchor_index >= old_selected_anchors.len)
                        {
                            continue;
                        }
                        const function_step = old_steps[copied.function_component_ref.copy_step_index];
                        const pair = old_constraint_pairs[
                            function_step.constraint_pairs_start +
                                copied.function_component_ref.constraint_pair_offset
                        ];
                        if (pair.source_constraint_index == expected_source and
                            pair.destination_constraint_index == expected_destination and
                            old_selected_anchors[copied.anchor_index].constraint_index == expected_destination)
                        {
                            copied_source_count += 1;
                        }
                    }
                    if (copied_source_count != 1) {
                        @panic("checked-boundary copied-literal group lost its exact copied-source converse");
                    }
                    const expected_kind = copiedOpenLiteralConstraintKind(
                        &source_env.types,
                        source_env,
                        expected_source,
                    );
                    var event_count: usize = 0;
                    var expected_event_index: ?u32 = null;
                    for (events, 0..) |event, event_offset| {
                        if (event.constraint_offset != constraint_offset) continue;
                        if (expected_kind == null or event.decodedLiteralKind() != expected_kind.?) {
                            @panic("checked-boundary copied-literal event changed its source literal kind");
                        }
                        expected_event_index = group.events_start +
                            @as(u32, @intCast(event_offset));
                        event_count += 1;
                    }
                    if (event_count != @intFromBool(expected_kind != null)) {
                        @panic("checked-boundary copied-literal event cardinality disagreed with its source constraint");
                    }
                    if (expected_event_index) |event_index| {
                        const evidence = old_constraints[expected_destination].constraint_evidence;
                        var creation_handle_count: usize = 0;
                        for (self.types.constraint_evidence_handles.items.items[evidence.start..][0..evidence.len]) |handle| {
                            if (handle.decodedKind() == .copied_literal_event and
                                handle.index == event_index)
                            {
                                creation_handle_count += 1;
                            }
                        }
                        if (creation_handle_count != 1) {
                            @panic("checked-boundary copied-literal event lost its exact creation handle");
                        }
                    }
                }
            }
            if (kind == .platform_requirement) {
                const platform = step.origin.platform_requirement;
                const start: usize = platform.substitutions_start;
                const len: usize = platform.substitutions_len;
                if (start > old_substitutions.len or len > old_substitutions.len - start) {
                    @panic("checked-boundary platform substitutions were not gaplessly owned");
                }
                markCheckedBoundaryOwnedRange(
                    owned_substitutions,
                    platform.substitutions_start,
                    platform.substitutions_len,
                );
            }
        }
        if (!std.mem.allEqual(bool, owned_pairs, true) or
            !std.mem.allEqual(bool, owned_occurrences, true) or
            !std.mem.allEqual(bool, owned_constraint_pairs, true) or
            !std.mem.allEqual(bool, owned_witnesses, true) or
            !std.mem.allEqual(bool, owned_copied_literal_groups, true) or
            !std.mem.allEqual(bool, owned_copied_literal_events, true) or
            !std.mem.allEqual(bool, owned_substitutions, true))
        {
            @panic("checked-boundary marker-copy proof pools contained orphan rows");
        }

        var old_move_offset_end: usize = 0;
        for (old_moves) |move| {
            const start: usize = move.offsets_start;
            const len: usize = move.offsets_len;
            if (move.source_constraint_index >= old_constraints.len or
                move.destination_constraint_index >= old_constraints.len or
                len == 0 or start != old_move_offset_end or start > old_move_offsets.len or
                len > old_move_offsets.len - start or
                len != old_constraints[move.source_constraint_index].where_method_markers.len())
            {
                @panic("checked-boundary constraint movement was malformed");
            }
            const destination_len = old_constraints[move.destination_constraint_index].where_method_markers.len();
            for (old_move_offsets[start..][0..len]) |offset| {
                if (offset >= destination_len) {
                    @panic("checked-boundary constraint movement escaped its destination");
                }
            }
            old_move_offset_end += len;
        }
        if (old_move_offset_end != old_move_offsets.len) {
            @panic("checked-boundary constraint movement offsets had orphan rows");
        }

        // Expected failures and consumer retirements are immutable producer
        // publications in one causal graph: either kind may name the other. Build
        // both type-local relocation maps from a single deterministic Kahn walk so
        // cross-kind cycles and omitted causal owners cannot hide behind separate
        // pool ordering.
        transaction.expected_failure_order = try self.gpa.alloc(u32, old_expected_failures.len);
        const expected_failure_order = transaction.expected_failure_order.?;
        transaction.expected_failure_map = try self.gpa.alloc(u32, old_expected_failures.len);
        const expected_failure_map = transaction.expected_failure_map.?;
        @memset(expected_failure_map, none);
        transaction.expected_retirement_order = try self.gpa.alloc(u32, old_expected_retirements.len);
        const expected_retirement_order = transaction.expected_retirement_order.?;
        transaction.expected_retirement_map = try self.gpa.alloc(u32, old_expected_retirements.len);
        const expected_retirement_map = transaction.expected_retirement_map.?;
        @memset(expected_retirement_map, none);
        const owned_retired_consumers = try self.gpa.alloc(bool, old_expected_retired_consumers.len);
        defer self.gpa.free(owned_retired_consumers);
        @memset(owned_retired_consumers, false);
        const owned_retirement_failures = try self.gpa.alloc(bool, old_expected_retirement_failures.len);
        defer self.gpa.free(owned_retirement_failures);
        @memset(owned_retirement_failures, false);
        const referenced_expected_ambiguity_retirements = try self.gpa.alloc(
            u8,
            old_expected_ambiguity_retirements.len,
        );
        defer self.gpa.free(referenced_expected_ambiguity_retirements);
        @memset(referenced_expected_ambiguity_retirements, 0);

        // Ambiguity retirements are immutable verdict publications. Validate their
        // exact old-space coordinates before any pruning; the root pass below
        // retains every selected constraint and only the branch arm's copy step.
        for (old_expected_ambiguity_retirements) |retirement| {
            if (!expectedAmbiguityRetirementIsLocallyValid(self.types, self.cir, retirement)) {
                @panic("checked-boundary Expected ambiguity retirement was malformed");
            }
        }

        for (old_expected_failures, 0..) |failure, failure_index| {
            if (!failure.hasLegalTagsAt(@intCast(failure_index)) or
                failure.owner_node >= self.cir.store.nodes.len() or
                failure.site_node >= self.cir.store.nodes.len() or
                failure.raw_owner_var >= self.types.len() or
                failure.raw_subject_var >= self.types.len() or
                (failure.raw_peer_var != none and failure.raw_peer_var >= self.types.len()) or
                (failure.constraint_index != none and failure.constraint_index >= old_constraints.len) or
                (failure.plan_index != none and failure.plan_index >= old_expected_plans.len))
            {
                @panic("checked-boundary Expected failure was malformed");
            }
            self.checkedBoundaryValidateExpectedFailureSubject(
                failure,
                @intCast(failure_index),
                old_steps,
                old_occurrences,
                old_expected_plans,
            );
            self.checkedBoundaryValidateExpectedCauseOwner(
                failure.cause_owner,
                old_expected_failures.len,
                old_expected_retirements.len,
            );
            for (old_expected_failures[0..failure_index]) |prior| {
                if (expectedFailureKeysEqual(prior, failure)) {
                    @panic("Expected failures repeated one canonical producer slot");
                }
            }
        }

        for (old_expected_retirements, 0..) |retirement, retirement_index| {
            if (!retirement.hasLegalTags() or
                !expectedConsumerRetirementNodeIsLocallyValid(self.cir, retirement))
            {
                @panic("checked-boundary Expected-consumer retirement was malformed");
            }
            var has_expected_ambiguity_owner = false;
            if (retirement.decodedRejectionOwnerKind()) |rejection_kind| {
                switch (rejection_kind) {
                    .rejected_static_dispatch => {},
                    .expected_ambiguity_retirement => {
                        if (retirement.rejection_owner_index >= old_expected_ambiguity_retirements.len) {
                            @panic("Expected-consumer retirement named an absent ambiguity verdict");
                        }
                        if (!expectedAmbiguityRetirementOwnerIsLocallyValid(
                            self.cir,
                            retirement,
                            retirement.rejection_owner_index,
                        )) {
                            @panic("Expected-consumer retirement changed its exact ambiguity verdict owner");
                        }
                        referenced_expected_ambiguity_retirements[retirement.rejection_owner_index] +|= 1;
                        has_expected_ambiguity_owner = true;
                    },
                }
            }
            if (retirement.expected_failures_len == 0) {
                if (retirement.expected_failures_start != 0) {
                    @panic("empty Expected-consumer failure range was not canonical");
                }
            } else {
                markCheckedBoundaryOwnedRange(
                    owned_retirement_failures,
                    retirement.expected_failures_start,
                    retirement.expected_failures_len,
                );
                const causes = old_expected_retirement_failures[retirement.expected_failures_start..][0..retirement.expected_failures_len];
                for (causes, 0..) |cause, cause_offset| {
                    if (!cause.hasLegalTags() or cause.failure_index >= old_expected_failures.len) {
                        @panic("Expected-consumer retirement named an invalid failure");
                    }
                    const failure = old_expected_failures[cause.failure_index];
                    if (failure.owner_kind != retirement.owner_kind or
                        failure.owner_node != retirement.retired_node)
                    {
                        @panic("Expected-consumer retirement borrowed another owner's failure");
                    }
                    if (cause_offset != 0) {
                        const prior = causes[cause_offset - 1];
                        if (prior.failure_index == cause.failure_index or
                            expectedFailureKeyLessThan(
                                old_expected_failures,
                                cause.failure_index,
                                prior.failure_index,
                            ))
                        {
                            @panic("Expected-consumer retirement failures were not strictly canonical");
                        }
                    }
                }
            }
            var has_expected_ambiguity_consumers = false;
            if (retirement.retired_consumers_len == 0) {
                if (retirement.retired_consumers_start != 0) {
                    @panic("empty Expected-consumer retirement range was not canonical");
                }
            } else {
                markCheckedBoundaryOwnedRange(
                    owned_retired_consumers,
                    retirement.retired_consumers_start,
                    retirement.retired_consumers_len,
                );
                const consumers = old_expected_retired_consumers[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
                if (!expectedRetiredConsumerRangeIsLocallyValid(
                    self.types,
                    self.cir,
                    retirement,
                    @intCast(retirement_index),
                    consumers,
                )) {
                    const first = consumers[0];
                    const first_plan = old_expected_plans[first.plan_index];
                    std.debug.panic(
                        "Expected-consumer retirement did not replay its exact erased plan range retirement={d} owner={d} tag={?s} len={d} reason={?s} first_plan={d}/{?s}/{?s}",
                        .{
                            retirement_index,
                            retirement.retired_node,
                            if (retirement.decodedOriginalNodeTag()) |tag| @tagName(tag) else null,
                            retirement.retired_consumers_len,
                            if (first.decodedReason()) |reason| @tagName(reason) else null,
                            first.plan_index,
                            if (first_plan.decodedRole()) |role| @tagName(role) else null,
                            if (first_plan.decodedOutcome()) |outcome| @tagName(outcome) else null,
                        },
                    );
                }
                const reason = consumers[0].decodedReason();
                has_expected_ambiguity_consumers = reason == .branch_retired_after_ambiguity_verdict or
                    reason == .call_retired;
            }
            if (has_expected_ambiguity_owner != has_expected_ambiguity_consumers) {
                @panic("Expected ambiguity verdict ownership disagreed with its retired consumer group");
            }
            for (old_expected_retirements[0..retirement_index]) |prior| {
                if (prior.owner_kind == retirement.owner_kind and
                    prior.retired_node == retirement.retired_node)
                {
                    @panic("Expected-consumer retirements repeated one owner identity");
                }
            }
        }
        if (!std.mem.allEqual(bool, owned_retired_consumers, true)) {
            @panic("Expected-retired-consumer pool contained orphan rows");
        }
        if (!std.mem.allEqual(bool, owned_retirement_failures, true)) {
            @panic("Expected-retirement-failure pool contained orphan rows");
        }
        if (!std.mem.allEqual(u8, referenced_expected_ambiguity_retirements, 1)) {
            @panic("Expected-ambiguity-retirement pool did not have exact ownership");
        }

        var failure_write: usize = 0;
        var retirement_write: usize = 0;
        for (0..old_expected_failures.len + old_expected_retirements.len) |_| {
            var best_failure: ?u32 = null;
            for (old_expected_failures, 0..) |failure, old_failure_index_usize| {
                if (expected_failure_map[old_failure_index_usize] != none) continue;
                if (failure.decodedKind() == .direct_binder_lookup_checked_error) {
                    const direct = failure.subject_authority.decodedDirect() orelse continue;
                    if (failure.subject_authority.decodedDirectPhase() !=
                        .direct_binder_lookup_checked_error or
                        direct.local_record_index >= expected_failure_map.len or
                        expected_failure_map[direct.local_record_index] == none)
                    {
                        continue;
                    }
                }
                if (failure.cause_owner.decodedExpectedFailure()) |cause| {
                    if (expected_failure_map[cause.index] == none) continue;
                }
                if (failure.cause_owner.decodedExpectedConsumerRetirement()) |cause| {
                    if (expected_retirement_map[cause.index] == none) continue;
                }
                const old_failure_index: u32 = @intCast(old_failure_index_usize);
                if (best_failure == null or expectedFailureKeyLessThan(
                    old_expected_failures,
                    old_failure_index,
                    best_failure.?,
                )) {
                    best_failure = old_failure_index;
                }
            }

            // The tagged semantic key orders failure rows before retirement rows.
            // Therefore a ready failure always wins; only when none is ready do we
            // select the minimum ready retirement identity.
            if (best_failure) |selected| {
                expected_failure_order[failure_write] = selected;
                expected_failure_map[selected] = @intCast(failure_write);
                failure_write += 1;
                continue;
            }

            var best_retirement: ?u32 = null;
            for (old_expected_retirements, 0..) |retirement, old_retirement_index_usize| {
                if (expected_retirement_map[old_retirement_index_usize] != none) continue;
                const causes = old_expected_retirement_failures[retirement.expected_failures_start..][0..retirement.expected_failures_len];
                var causes_ready = true;
                for (causes) |cause| {
                    if (expected_failure_map[cause.failure_index] == none) {
                        causes_ready = false;
                        break;
                    }
                }
                if (!causes_ready) continue;
                const old_retirement_index: u32 = @intCast(old_retirement_index_usize);
                if (best_retirement == null) {
                    best_retirement = old_retirement_index;
                    continue;
                }
                const best = old_expected_retirements[best_retirement.?];
                if (retirement.owner_kind < best.owner_kind or
                    (retirement.owner_kind == best.owner_kind and
                        retirement.retired_node < best.retired_node))
                {
                    best_retirement = old_retirement_index;
                }
            }
            const selected = best_retirement orelse
                @panic("Expected failure/retirement causal graph contained a cycle");
            expected_retirement_order[retirement_write] = selected;
            expected_retirement_map[selected] = @intCast(retirement_write);
            retirement_write += 1;
        }
        if (failure_write != old_expected_failures.len or
            retirement_write != old_expected_retirements.len)
        {
            @panic("Expected failure/retirement causal ordering was incomplete");
        }

        // Expected-consumption plans are unconditional syntax roots. Establish a
        // deterministic causal order before copy-step pruning so every endpoint
        // and every fresh-support range can be relocated through stable maps.
        transaction.expected_plan_order = try self.gpa.alloc(u32, old_expected_plans.len);
        const expected_plan_order = transaction.expected_plan_order.?;
        transaction.expected_plan_map = try self.gpa.alloc(u32, old_expected_plans.len);
        const expected_plan_map = transaction.expected_plan_map.?;
        @memset(expected_plan_map, none);
        for (old_expected_plans, 0..) |plan, plan_index| {
            const outcome = plan.decodedOutcome() orelse
                @panic("checked-boundary Expected-consumption plan had an invalid outcome");
            if (!plan.hasLegalTags() or
                outcome == .reserved or
                plan.owner_node >= self.cir.store.nodes.len() or
                plan.site_node >= self.cir.store.nodes.len() or
                plan.raw_consumer_var >= self.types.len())
            {
                @panic("checked-boundary Expected-consumption plan was not terminal");
            }
            const parent_present = plan.parent_authority.kind != ModuleEnv.ExpectedMarkerAuthority.none;
            if (!plan.parent_authority.hasCanonicalTags(parent_present)) {
                @panic("Expected-consumption parent endpoint was not canonical");
            }
            const produced_present = plan.produced_copy_step != none or
                plan.produced_occurrence_offset != none or plan.produced_side != none;
            if (produced_present and
                (plan.produced_copy_step == none or plan.produced_occurrence_offset == none or
                    plan.decodedProducedSide() == null))
            {
                @panic("Expected-consumption produced endpoint was not canonical");
            }
            const reason = plan.decodedReason();
            const owner_relation = if (reason) |present_reason|
                ModuleEnv.ExpectedConsumptionPlan.ownerRelationForReason(present_reason)
            else
                ModuleEnv.ExpectedConsumptionPlan.OwnerRelation.none;
            switch (outcome) {
                .anchored => if (!parent_present or !produced_present) {
                    @panic("anchored Expected-consumption plan omitted an exact endpoint");
                },
                .source_root_copy => if (parent_present or !produced_present or
                    reason != null or plan.failure_owner.kind != ModuleEnv.CauseOwner.none)
                {
                    @panic("record-update source-root plan had noncanonical success fields");
                },
                .source_root_copy_checked_error => if (parent_present or !produced_present or
                    reason != .record_update_base_checked_error or
                    plan.failure_owner.kind == ModuleEnv.CauseOwner.none)
                {
                    @panic("record-update source-root plan lost its exact checked-error fields");
                },
                .related => if (!parent_present or produced_present or reason != null or
                    plan.failure_owner.kind != ModuleEnv.CauseOwner.none)
                {
                    @panic("related Expected-consumption plan had noncanonical relation fields");
                },
                .producer_root => if (parent_present or produced_present) {
                    @panic("producer-root Expected-consumption plan had noncanonical endpoints");
                },
                .evidence_free => if (!parent_present or produced_present or
                    plan.parent_authority.decodedKind() != .evidence_free_plan)
                {
                    @panic("evidence-free Expected-consumption plan lost its proving parent plan");
                },
                .retained => if (!parent_present or produced_present or
                    reason != .branch_body_already_expected or
                    plan.failure_owner.kind != ModuleEnv.CauseOwner.none)
                {
                    @panic("retained Expected-consumption plan lost its exact predecessor authority");
                },
                .not_projected => {
                    const unavailable_record_update_field =
                        reason == .record_update_projection_unavailable and
                        plan.decodedRole() == .record_update_field and
                        plan.raw_consumer_var == plan.site_node and
                        owner_relation == .none and parent_present;
                    if (produced_present or
                        (owner_relation == .none and parent_present and
                            !unavailable_record_update_field))
                    {
                        @panic("not-projected Expected-consumption plan carried a noncanonical endpoint");
                    }
                },
                .checked_error => {
                    if (produced_present or
                        ((owner_relation == .direct_source_retirement or
                            owner_relation == .upstream_retirement) and !parent_present))
                    {
                        @panic("failed Expected-consumption plan carried a noncanonical endpoint");
                    }
                },
                .reserved => unreachable,
            }
            self.checkedBoundaryValidateExpectedCauseOwner(
                plan.failure_owner,
                old_expected_failures.len,
                old_expected_retirements.len,
            );
            if (plan.decodedSourceRetirementIndex()) |source_retirement_index| {
                if (source_retirement_index >= old_expected_retirements.len) {
                    @panic("record-update base plan named an absent source retirement");
                }
            }
            if (plan.failure_cause_plan_index != none and
                (plan.failure_cause_plan_index >= old_expected_plans.len or
                    plan.failure_cause_plan_index == plan_index))
            {
                @panic("Expected-consumption plan named an invalid causal predecessor");
            }
            if (plan.call_root_plan_index != none and
                (plan.call_root_plan_index >= old_expected_plans.len or
                    plan.call_root_plan_index == plan_index))
            {
                @panic("Expected-consumption plan named an invalid call root");
            }
            if (plan.parent_authority.decodedKind() == .producer_root_plan) {
                const producer = plan.parent_authority.payload.producer_root_plan;
                if (producer.plan_index >= old_expected_plans.len or
                    producer.plan_index == plan_index or producer.raw_var >= self.types.len())
                {
                    @panic("Expected-consumption plan named an invalid producer-root authority");
                }
                const producer_plan = old_expected_plans[producer.plan_index];
                if (!producer_plan.hasLegalTags() or
                    producer_plan.decodedRole() != .call_argument or
                    producer_plan.decodedOutcome() != .producer_root or
                    producer_plan.raw_consumer_var != producer.raw_var)
                {
                    @panic("Expected-consumption plan named a mismatched producer-root authority");
                }
            }
            if (plan.parent_authority.decodedKind() == .evidence_free_plan) {
                const parent = plan.parent_authority.payload.evidence_free_plan;
                if (parent.plan_index >= old_expected_plans.len or
                    parent.plan_index == plan_index or parent.raw_var >= self.types.len())
                {
                    @panic("Expected-consumption plan named an invalid evidence-free authority");
                }
                const parent_plan = old_expected_plans[parent.plan_index];
                if (!parent_plan.hasLegalTags() or
                    parent_plan.raw_consumer_var != parent.raw_var or
                    (parent_plan.decodedOutcome() != .evidence_free and
                        !(parent_plan.decodedOutcome() == .checked_error and
                            parent_plan.decodedReason() == .aggregate_child_relation_rejected)))
                {
                    @panic("Expected-consumption plan named a mismatched evidence-free authority");
                }
            }
            if (plan.parent_authority.decodedKind() == .relation_plan) {
                const parent = plan.parent_authority.payload.relation_plan;
                if (parent.plan_index >= old_expected_plans.len or
                    parent.plan_index == plan_index or parent.raw_var >= self.types.len())
                {
                    @panic("Expected-consumption plan named an invalid relation authority");
                }
                const parent_plan = old_expected_plans[parent.plan_index];
                if (!parent_plan.hasLegalTags() or
                    parent_plan.decodedRole() != .branch_contribution or
                    parent_plan.decodedOutcome() != .related)
                {
                    @panic("Expected-consumption plan named a mismatched relation authority");
                }
                const parent_raw = expectedParentAuthorityRawForProof(
                    self.cir,
                    parent_plan.parent_authority,
                    old_steps,
                    old_occurrences,
                    null,
                ) orelse @panic("relation authority lost its exact prior raw endpoint");
                if (parent.raw_var != parent_raw) {
                    @panic("relation authority changed its unchanged accumulator variable");
                }
            }
            for (old_expected_plans[0..plan_index]) |prior| {
                if (expectedConsumptionPlanKeysEqual(prior, plan)) {
                    @panic("Expected-consumption plans repeated one canonical syntax slot");
                }
            }
        }
        for (0..old_expected_plans.len) |new_plan_index| {
            var best_old_index: ?u32 = null;
            for (old_expected_plans, 0..) |plan, old_plan_index_usize| {
                if (expected_plan_map[old_plan_index_usize] != none) continue;
                if (plan.failure_cause_plan_index != none and
                    expected_plan_map[plan.failure_cause_plan_index] == none)
                {
                    continue;
                }
                if (plan.call_root_plan_index != none and
                    expected_plan_map[plan.call_root_plan_index] == none)
                {
                    continue;
                }
                if (plan.parent_authority.decodedKind() == .producer_root_plan and
                    expected_plan_map[plan.parent_authority.payload.producer_root_plan.plan_index] == none)
                {
                    continue;
                }
                if (plan.parent_authority.decodedKind() == .evidence_free_plan and
                    expected_plan_map[plan.parent_authority.payload.evidence_free_plan.plan_index] == none)
                {
                    continue;
                }
                if (plan.parent_authority.decodedKind() == .relation_plan and
                    expected_plan_map[plan.parent_authority.payload.relation_plan.plan_index] == none)
                {
                    continue;
                }
                const old_plan_index: u32 = @intCast(old_plan_index_usize);
                if (best_old_index == null or expectedConsumptionPlanKeyLessThan(
                    old_expected_plans,
                    old_plan_index,
                    best_old_index.?,
                )) {
                    best_old_index = old_plan_index;
                }
            }
            const selected = best_old_index orelse
                @panic("Expected-consumption causal plan graph contained a cycle");
            expected_plan_order[new_plan_index] = selected;
            expected_plan_map[selected] = @intCast(new_plan_index);
        }

        const referenced_expected_failures = try self.gpa.alloc(u8, old_expected_failures.len);
        defer self.gpa.free(referenced_expected_failures);
        @memset(referenced_expected_failures, 0);
        for (old_expected_plans) |plan| {
            if (recordUpdateExpectedPlanCarriesCausalReference(plan)) continue;
            if (plan.failure_owner.decodedExpectedFailure()) |owner| {
                referenced_expected_failures[owner.index] +|= 1;
            }
        }
        for (old_expected_retirements) |retirement| {
            const causes = old_expected_retirement_failures[retirement.expected_failures_start..][0..retirement.expected_failures_len];
            for (causes) |cause| {
                referenced_expected_failures[cause.failure_index] +|= 1;
            }
        }
        if (!std.mem.allEqual(u8, referenced_expected_failures, 1)) {
            @panic("checked-boundary Expected-failure pool did not have exact ownership");
        }
    }

    fn markReachable(transaction: *Transaction) Allocator.Error!void {
        const self = transaction.checker;
        const old_constraints = transaction.input.constraints;
        const old_bases = transaction.input.bases;
        const old_steps = transaction.input.steps;
        const old_default_decisions = transaction.input.default_decisions;
        const old_default_contributors = transaction.input.default_contributors;
        const old_selected_decisions = transaction.input.selected_decisions;
        const old_selected_anchors = transaction.input.selected_anchors;
        const old_settlement_sources = transaction.input.settlement_sources;
        const old_selected_moves = transaction.input.selected_moves;
        const old_selected_decision_moves = transaction.input.selected_decision_moves;
        const old_constraint_pairs = transaction.input.constraint_pairs;
        const old_witnesses = transaction.input.witnesses;
        const old_copied_literal_groups = transaction.input.copied_literal_groups;
        const old_copied_literal_events = transaction.input.copied_literal_events;
        const old_substitutions = transaction.input.substitutions;
        const old_moves = transaction.input.moves;
        const old_expected_plans = transaction.input.expected_plans;
        const old_expected_failures = transaction.input.expected_failures;
        const old_expected_ambiguity_retirements = transaction.input.expected_ambiguity_retirements;
        const old_expected_call_formals = transaction.input.expected_call_formals;
        const old_external_cache_seeds = transaction.input.external_cache_seeds;
        const old_where_sources = transaction.input.where_method_sources;
        const live_ranges = transaction.live_ranges.?;

        transaction.referenced_constraints = try self.gpa.alloc(bool, old_constraints.len);
        const referenced_constraints = transaction.referenced_constraints.?;
        @memset(referenced_constraints, false);
        transaction.referenced_steps = try self.gpa.alloc(bool, old_steps.len);
        const referenced_steps = transaction.referenced_steps.?;
        @memset(referenced_steps, false);
        for (old_external_cache_seeds) |seed| {
            _ = markCheckedBoundaryCopyStep(referenced_steps, seed.support_step);
        }
        for (old_expected_failures) |failure| {
            if (failure.subject_authority.decodedExpectedCopyOccurrence()) |endpoint| {
                _ = markCheckedBoundaryCopyStep(referenced_steps, endpoint.copy_step);
            }
            if (failure.constraint_index != none) {
                _ = markCheckedBoundaryConstraint(referenced_constraints, failure.constraint_index);
            }
        }
        for (old_expected_ambiguity_retirements) |retirement| {
            _ = markCheckedBoundaryConstraint(
                referenced_constraints,
                retirement.selected_constraint_index,
            );
            switch (retirement.decodedKind() orelse
                @panic("Expected ambiguity retirement had an invalid kind while rooting")) {
                .body_forced_instantiation_branch => _ = markCheckedBoundaryCopyStep(referenced_steps, retirement.copy_step),
                .creation_dispatch_call => if (retirement.copy_step !=
                    ModuleEnv.ExpectedAmbiguityRetirement.none)
                {
                    @panic("creation-call ambiguity retirement carried a copy step");
                },
            }
        }
        for (old_expected_plans) |plan| {
            if (plan.parent_authority.decodedKind() == .copy_occurrence) {
                const parent = plan.parent_authority.payload.copy_occurrence;
                if (parent.copy_step >= old_steps.len or
                    parent.occurrence_offset >= old_steps[parent.copy_step].occurrences_len)
                {
                    @panic("Expected-consumption parent endpoint escaped its copy proof");
                }
                _ = markCheckedBoundaryCopyStep(referenced_steps, parent.copy_step);
            }
            if (plan.produced_copy_step != none) {
                if (plan.produced_copy_step >= old_steps.len or
                    plan.produced_occurrence_offset >= old_steps[plan.produced_copy_step].occurrences_len)
                {
                    @panic("Expected-consumption produced endpoint escaped its copy proof");
                }
                _ = markCheckedBoundaryCopyStep(referenced_steps, plan.produced_copy_step);
            }
        }
        for (old_expected_call_formals, 0..) |formal, formal_index| {
            if (!expectedCallFormalMatchesPlans(
                self.cir,
                formal,
                formal.call_root_plan_index,
                formal.argument_plan_index,
            )) {
                @panic("checked-boundary call formal lost its producer witness");
            }
            for (old_expected_call_formals[0..formal_index]) |prior| {
                if (prior.argument_plan_index == formal.argument_plan_index) {
                    @panic("checked-boundary call argument owned more than one formal witness");
                }
            }
            if (formal.instantiation_copy_step != ModuleEnv.ExpectedCallFormal.none) {
                _ = markCheckedBoundaryCopyStep(
                    referenced_steps,
                    formal.instantiation_copy_step,
                );
            }
        }

        // A committed default-method use is itself the explicit successful
        // copy event until DefaultMethodInstantiation owns that terminal root.
        // Failed compatibility probes roll their speculative child back, so
        // only producer-authored successes reach this pool. Root each such
        // child directly; its closure retains the immutable cache root,
        // committed SchemeUse, exact decision/constraint, and contributors.
        for (old_steps, 0..) |step, step_index| {
            if (step.decodedKind() == .default_method_use) {
                _ = markCheckedBoundaryCopyStep(referenced_steps, @intCast(step_index));
            }
        }
        transaction.referenced_default_decisions = try self.gpa.alloc(bool, old_default_decisions.len);
        const referenced_default_decisions = transaction.referenced_default_decisions.?;
        @memset(referenced_default_decisions, false);
        transaction.referenced_moves = try self.gpa.alloc(bool, old_moves.len);
        const referenced_moves = transaction.referenced_moves.?;
        @memset(referenced_moves, false);
        transaction.referenced_selected_anchors = try self.gpa.alloc(bool, old_selected_anchors.len);
        const referenced_selected_anchors = transaction.referenced_selected_anchors.?;
        @memset(referenced_selected_anchors, false);
        transaction.referenced_selected_moves = try self.gpa.alloc(bool, old_selected_moves.len);
        const referenced_selected_moves = transaction.referenced_selected_moves.?;
        @memset(referenced_selected_moves, false);
        const referenced_evidence_nodes = &transaction.referenced_evidence_nodes;

        for (old_settlement_sources) |source| {
            if (!source.hasCanonicalTags()) {
                @panic("dispatch-settlement source had a noncanonical producer arm while rooting");
            }
            if (source.primaryAnchorIndex()) |anchor_index| {
                if (anchor_index >= old_selected_anchors.len) {
                    @panic("dispatch-settlement source escaped its selected-receiver anchor pool");
                }
                referenced_selected_anchors[anchor_index] = true;
                const anchor = old_selected_anchors[anchor_index];
                _ = markCheckedBoundaryConstraint(referenced_constraints, anchor.constraint_index);
                try referenced_evidence_nodes.put(.{
                    .handle = .{
                        .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.selected_receiver_anchor),
                        .index = anchor_index,
                    },
                    .constraint_index = anchor.constraint_index,
                }, {});
            }
            switch (source.decodedKind().?) {
                .negated_equality_not => _ = markCheckedBoundaryConstraint(
                    referenced_constraints,
                    source.payload.negated_equality_not.equality_constraint_index,
                ),
                .copied_constraint => {
                    _ = markCheckedBoundaryCopyStep(
                        referenced_steps,
                        source.payload.copied_constraint.receiver_component_ref.copy_step_index,
                    );
                    _ = markCheckedBoundaryCopyStep(
                        referenced_steps,
                        source.payload.copied_constraint.function_component_ref.copy_step_index,
                    );
                },
                .dispatch_expr,
                .literal_conversion,
                .interpolation,
                .pattern_literal_equality,
                .for_loop_dispatch,
                => {},
                .where_requirement => {
                    const old_source_index = source.payload.where_requirement.source_index;
                    if (old_source_index >= old_where_sources.len) {
                        @panic("where settlement source escaped its source ledger");
                    }
                    const where_source = old_where_sources[old_source_index];
                    _ = markCheckedBoundaryConstraint(
                        referenced_constraints,
                        where_source.retained_constraint_index,
                    );
                    try referenced_evidence_nodes.put(.{
                        .handle = .{
                            .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.where_requirement_source),
                            .index = old_source_index,
                        },
                        .constraint_index = where_source.retained_constraint_index,
                    }, {});
                },
            }
        }

        for (live_ranges) |maybe_range| {
            if (maybe_range) |range| _ = markCheckedBoundaryConstraintRange(referenced_constraints, range);
        }
        for (self.cir.where_method_sources.items.items) |source| {
            _ = markCheckedBoundaryConstraint(referenced_constraints, source.retained_constraint_index);
        }
        for (self.cir.where_alias_expansions.items.items) |expansion| {
            _ = markCheckedBoundaryConstraint(referenced_constraints, expansion.retained_constraint_index);
        }
        for (self.cir.binding_scheme_codec_requirements.items.items) |requirement| {
            _ = markCheckedBoundaryConstraint(referenced_constraints, requirement.constraint_index);
        }
        for (old_selected_decisions) |decision| {
            _ = markCheckedBoundaryConstraint(referenced_constraints, decision.constraint_index);
            _ = markCheckedBoundaryCopyStep(referenced_steps, decision.root_copy_step);
            _ = markCheckedBoundaryCopyStep(referenced_steps, decision.use_copy_step);
            const handles = self.types.constraint_evidence_handles.items.items[decision.constraint_evidence_start..][0..decision.constraint_evidence_len];
            for (handles) |handle| {
                if (handle.decodedKind() != .selected_receiver_anchor) continue;
                const anchor_index = handle.index;
                referenced_selected_anchors[anchor_index] = true;
                const anchor = old_selected_anchors[anchor_index];
                _ = markCheckedBoundaryConstraint(referenced_constraints, anchor.constraint_index);
                try referenced_evidence_nodes.put(.{
                    .handle = handle,
                    .constraint_index = anchor.constraint_index,
                }, {});
                try referenced_evidence_nodes.put(.{
                    .handle = handle,
                    .constraint_index = decision.constraint_index,
                }, {});
                if (anchor.decodedKind().? == .copied_constraint) {
                    _ = markCheckedBoundaryCopyStep(referenced_steps, anchor.copy_step);
                }
            }
            const decision_moves = old_selected_decision_moves[decision.constraint_moves_start..][0..decision.constraint_moves_len];
            for (decision_moves) |decision_move| {
                referenced_selected_anchors[decision_move.receiver_anchor_index] = true;
                referenced_selected_moves[decision_move.constraint_move_index] = true;
                const move = old_selected_moves[decision_move.constraint_move_index];
                _ = markCheckedBoundaryConstraint(referenced_constraints, move.source_constraint_index);
                _ = markCheckedBoundaryConstraint(referenced_constraints, move.destination_constraint_index);
                try referenced_evidence_nodes.put(.{
                    .handle = move.handle,
                    .constraint_index = move.source_constraint_index,
                }, {});
                try referenced_evidence_nodes.put(.{
                    .handle = move.handle,
                    .constraint_index = move.destination_constraint_index,
                }, {});
            }
        }

        var changed = true;
        while (changed) {
            changed = false;

            // A retained copy step owns its complete copied-literal
            // group/event range. Step reachability itself is transitive, so
            // event creation nodes and movements participate in this same
            // fixpoint: a basis, binding root, platform substitution, or
            // default contributor may retain a support step after the first
            // iteration. A group never roots its own otherwise-unreferenced
            // step, which keeps step->group->event pruning atomic.
            for (old_copied_literal_groups) |group| {
                if (group.copy_step_index >= referenced_steps.len or
                    !referenced_steps[group.copy_step_index])
                {
                    continue;
                }
                for (old_copied_literal_events[group.events_start..][0..group.events_len], 0..) |_, event_offset| {
                    const event_index = group.events_start + @as(u32, @intCast(event_offset));
                    const creation = copiedOpenLiteralEventCreationConstraint(
                        self.cir,
                        event_index,
                    ) orelse @panic("retained copied-literal event lost its creation constraint");
                    if (markCheckedBoundaryConstraint(referenced_constraints, creation)) {
                        changed = true;
                    }
                    try referenced_evidence_nodes.put(.{
                        .handle = .{
                            .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.copied_literal_event),
                            .index = event_index,
                        },
                        .constraint_index = creation,
                    }, {});
                }
            }

            // Source and copied-literal movement rows are themselves part of
            // their durable source closure. Preserve every exact transition
            // and both endpoint handles; contextual replay proves that each
            // graph begins at its authenticated creation constraint and has no
            // disconnected row.
            for (old_selected_moves, 0..) |move, move_index| {
                const handle_kind = move.handle.decodedKind() orelse
                    @panic("constraint-evidence movement had an invalid handle kind while rooting");
                switch (handle_kind) {
                    .where_requirement_source => if (move.handle.index >= old_where_sources.len) {
                        @panic("where-source evidence movement named an absent source");
                    },
                    .copied_literal_event => {
                        if (move.handle.index >= old_copied_literal_events.len) {
                            @panic("copied-literal evidence movement named an absent event");
                        }
                        const group_index = old_copied_literal_events[move.handle.index].group_index;
                        if (group_index >= old_copied_literal_groups.len or
                            !referenced_steps[old_copied_literal_groups[group_index].copy_step_index])
                        {
                            continue;
                        }
                    },
                    .selected_receiver_anchor => continue,
                }
                if (!referenced_selected_moves[move_index]) {
                    referenced_selected_moves[move_index] = true;
                    changed = true;
                }
                if (markCheckedBoundaryConstraint(
                    referenced_constraints,
                    move.source_constraint_index,
                )) changed = true;
                if (markCheckedBoundaryConstraint(
                    referenced_constraints,
                    move.destination_constraint_index,
                )) changed = true;
                try referenced_evidence_nodes.put(.{
                    .handle = move.handle,
                    .constraint_index = move.source_constraint_index,
                }, {});
                try referenced_evidence_nodes.put(.{
                    .handle = move.handle,
                    .constraint_index = move.destination_constraint_index,
                }, {});
            }

            for (old_constraints, 0..) |constraint, raw_constraint_index| {
                if (!referenced_constraints[raw_constraint_index]) continue;
                const basis_len: usize = constraint.where_method_marker_bases.len();
                const basis_start: usize = if (basis_len == 0)
                    0
                else
                    @intFromEnum(constraint.where_method_marker_bases.start);
                for (old_bases[basis_start..][0..basis_len]) |basis| {
                    if (markCheckedBoundaryCopyStep(referenced_steps, basis.copy_step)) changed = true;
                    const kind = old_steps[basis.copy_step].decodedKind().?;
                    if (kind.sourceNamespace() == .local and
                        markCheckedBoundaryConstraint(referenced_constraints, basis.source_constraint_index))
                    {
                        changed = true;
                    }
                }
            }
            for (old_moves, 0..) |move, move_index| {
                if (!referenced_constraints[move.destination_constraint_index]) continue;
                if (!referenced_moves[move_index]) {
                    referenced_moves[move_index] = true;
                    changed = true;
                }
                if (markCheckedBoundaryConstraint(referenced_constraints, move.source_constraint_index)) {
                    changed = true;
                }
            }
            for (old_steps, 0..) |step, step_index| {
                if (!referenced_steps[step_index]) continue;
                const kind = step.decodedKind().?;
                const constraint_pairs = old_constraint_pairs[step.constraint_pairs_start..][0..step.constraint_pairs_len];
                for (constraint_pairs) |pair| {
                    if (markCheckedBoundaryConstraint(
                        referenced_constraints,
                        pair.destination_constraint_index,
                    )) {
                        changed = true;
                    }
                    if (kind.sourceNamespace() == .local and markCheckedBoundaryConstraint(
                        referenced_constraints,
                        pair.source_constraint_index,
                    )) {
                        changed = true;
                    }
                }
                for (old_witnesses[step.witnesses_start..][0..step.witnesses_len]) |witness| {
                    if (witness.decodedAuxiliaryOriginKind() != .binding_copy_pair) continue;
                    if (markCheckedBoundaryCopyStep(
                        referenced_steps,
                        witness.auxiliary_origin_step,
                    )) {
                        changed = true;
                    }
                }
                switch (kind) {
                    .binding_codec_receiver => if (markCheckedBoundaryCopyStep(
                        referenced_steps,
                        step.origin.binding_codec_receiver.binding_root_step,
                    )) {
                        changed = true;
                    },
                    .binding_codec_function => if (markCheckedBoundaryCopyStep(
                        referenced_steps,
                        step.origin.binding_codec_function.binding_root_step,
                    )) {
                        changed = true;
                    },
                    .platform_requirement => {
                        const platform = step.origin.platform_requirement;
                        for (old_substitutions[platform.substitutions_start..][0..platform.substitutions_len]) |substitution| {
                            if (markCheckedBoundaryCopyStep(
                                referenced_steps,
                                substitution.app_instantiation_step,
                            )) {
                                changed = true;
                            }
                        }
                    },
                    .selected_dispatch_method => {
                        const decision = old_selected_decisions[
                            step.origin.selected_dispatch_method.decision_index
                        ];
                        if (markCheckedBoundaryConstraint(
                            referenced_constraints,
                            decision.constraint_index,
                        )) changed = true;
                    },
                    .candidate_probe_method_root => if (markCheckedBoundaryConstraint(
                        referenced_constraints,
                        step.origin.candidate_probe_method_root.constraint_index,
                    )) {
                        changed = true;
                    },
                    .candidate_probe_method_use => if (markCheckedBoundaryConstraint(
                        referenced_constraints,
                        step.origin.candidate_probe_method_use.constraint_index,
                    )) {
                        changed = true;
                    },
                    .default_method => {
                        const decision_index = step.origin.default_method.decision_index;
                        if (decision_index >= referenced_default_decisions.len) {
                            @panic("default-method copy step named an absent decision");
                        }
                        if (!referenced_default_decisions[decision_index]) {
                            referenced_default_decisions[decision_index] = true;
                            changed = true;
                        }
                        const decision = old_default_decisions[decision_index];
                        if (markCheckedBoundaryConstraintRange(referenced_constraints, .{
                            .start = @enumFromInt(decision.constraints_start),
                            .count = decision.constraints_len,
                        })) changed = true;
                        for (old_default_contributors[decision.contributors_start..][0..decision.contributors_len]) |contributor| {
                            if (contributor.decodedDriverKind().? == .instantiation_copy and
                                markCheckedBoundaryCopyStep(referenced_steps, contributor.driver_copy_step))
                            {
                                changed = true;
                            }
                        }
                    },
                    .default_method_use => {
                        const origin = step.origin.default_method_use;
                        const decision_index = origin.decision_index;
                        if (decision_index >= referenced_default_decisions.len) {
                            @panic("default-method use step named an absent decision");
                        }
                        if (!referenced_default_decisions[decision_index]) {
                            referenced_default_decisions[decision_index] = true;
                            changed = true;
                        }
                        if (markCheckedBoundaryCopyStep(referenced_steps, origin.root_copy_step)) {
                            changed = true;
                        }
                        const decision = old_default_decisions[decision_index];
                        if (markCheckedBoundaryConstraintRange(referenced_constraints, .{
                            .start = @enumFromInt(decision.constraints_start),
                            .count = decision.constraints_len,
                        })) changed = true;
                        for (old_default_contributors[decision.contributors_start..][0..decision.contributors_len]) |contributor| {
                            if (contributor.decodedDriverKind().? == .instantiation_copy and
                                markCheckedBoundaryCopyStep(referenced_steps, contributor.driver_copy_step))
                            {
                                changed = true;
                            }
                        }
                    },
                    .aggregate_expected_projection => if (markCheckedBoundaryExpectedAuthorityCopyStep(
                        referenced_steps,
                        step.origin.aggregate_expected_projection.parent_authority,
                    )) {
                        changed = true;
                    },
                    .branch_expected_copy => if (markCheckedBoundaryExpectedAuthorityCopyStep(
                        referenced_steps,
                        step.origin.branch_expected_copy.parent_authority,
                    )) {
                        changed = true;
                    },
                    .aggregate_fresh_shape_child => if (markCheckedBoundaryExpectedAuthorityCopyStep(
                        referenced_steps,
                        step.origin.aggregate_fresh_shape_child.parent_authority,
                    )) {
                        changed = true;
                    },
                    .expected_call_instantiation => {
                        const origin = step.origin.expected_call_instantiation;
                        switch (origin.decodedSourceKind() orelse
                            @panic("call instantiation had an invalid source kind")) {
                            .local_predeclared_annotation => if (markCheckedBoundaryCopyStep(
                                referenced_steps,
                                origin.source_support_step,
                            )) {
                                changed = true;
                            },
                            .external_import_root => {
                                if (origin.source_seed_index >= old_external_cache_seeds.len) {
                                    @panic("call instantiation named an absent external cache seed");
                                }
                                if (markCheckedBoundaryCopyStep(
                                    referenced_steps,
                                    old_external_cache_seeds[origin.source_seed_index].support_step,
                                )) {
                                    changed = true;
                                }
                            },
                            .local_callee_expression,
                            .local_binding_pattern,
                            => {},
                        }
                    },
                    .reserved => @panic("reserved where-marker copy step escaped to checked-boundary rooting"),
                    .discarded => @panic("discarded where-marker copy step was referenced at the checked boundary"),
                    .external_cir_node,
                    .external_numeric_suffix,
                    .external_where_alias_receiver,
                    .external_where_alias_parameter,
                    .external_cache_seed,
                    .generated_codec_method,
                    .inspect_method,
                    .associated_method,
                    .scheme_use,
                    .type_annotation,
                    .numeric_suffix_use,
                    .nominal_expr_decl,
                    .nominal_expr_backing,
                    .nominal_pattern_decl,
                    .nominal_pattern_backing,
                    .required_lookup,
                    .platform_requirement_instance,
                    .platform_alias_app_decl,
                    .default_field_type,
                    .record_update_base,
                    .predeclared_annotation,
                    .generated_codec_snapshot,
                    => {},
                }
            }
        }

        var retained_constraint_count: usize = 0;
        for (referenced_constraints) |is_referenced| retained_constraint_count += @intFromBool(is_referenced);
        transaction.retained_constraint_count = retained_constraint_count;
        var retained_step_count: usize = 0;
        for (referenced_steps) |is_referenced| retained_step_count += @intFromBool(is_referenced);
        transaction.retained_step_count = retained_step_count;
        var retained_default_decision_count: usize = 0;
        var retained_default_contributor_count: usize = 0;
        for (referenced_default_decisions) |is_referenced| {
            retained_default_decision_count += @intFromBool(is_referenced);
        }
        for (referenced_default_decisions, old_default_decisions) |is_referenced, decision| {
            if (is_referenced) retained_default_contributor_count += decision.contributors_len;
        }
        transaction.retained_default_decision_count = retained_default_decision_count;
        transaction.retained_default_contributor_count = retained_default_contributor_count;
        var retained_move_count: usize = 0;
        for (referenced_moves) |is_referenced| retained_move_count += @intFromBool(is_referenced);
        transaction.retained_move_count = retained_move_count;
        var retained_selected_anchor_count: usize = 0;
        for (referenced_selected_anchors) |is_referenced| {
            retained_selected_anchor_count += @intFromBool(is_referenced);
        }
        transaction.retained_selected_anchor_count = retained_selected_anchor_count;
        var retained_selected_move_count: usize = 0;
        for (referenced_selected_moves) |is_referenced| {
            retained_selected_move_count += @intFromBool(is_referenced);
        }
        transaction.retained_selected_move_count = retained_selected_move_count;
    }

    fn rebuildConstraintsAndCopies(transaction: *Transaction) Allocator.Error!void {
        const self = transaction.checker;
        const old_constraints = transaction.input.constraints;
        const old_contracts = transaction.input.contracts;
        const old_type_paths = transaction.input.type_paths;
        const old_steps = transaction.input.steps;
        const old_default_decisions = transaction.input.default_decisions;
        const old_pairs = transaction.input.pairs;
        const old_occurrences = transaction.input.occurrences;
        const old_constraint_pairs = transaction.input.constraint_pairs;
        const old_witnesses = transaction.input.witnesses;
        const old_copied_literal_groups = transaction.input.copied_literal_groups;
        const old_copied_literal_events = transaction.input.copied_literal_events;
        const old_substitutions = transaction.input.substitutions;
        const old_expected_plans = transaction.input.expected_plans;
        const referenced_constraints = transaction.referenced_constraints.?;
        const referenced_steps = transaction.referenced_steps.?;
        const referenced_default_decisions = transaction.referenced_default_decisions.?;
        const external_seed_map = transaction.external_seed_map.?;
        const expected_plan_map = transaction.expected_plan_map.?;
        const retained_constraint_count = transaction.retained_constraint_count;
        const retained_step_count = transaction.retained_step_count;
        const retained_default_decision_count = transaction.retained_default_decision_count;

        transaction.replacement_constraints = try types_mod.StaticDispatchConstraint.SafeList.initCapacity(
            self.types.gpa,
            retained_constraint_count,
        );
        const replacement_constraints = &transaction.replacement_constraints;
        transaction.replacement_contracts = try types_mod.WhereMethodMarkerContract.SafeList.initCapacity(
            self.types.gpa,
            old_contracts.len,
        );
        const replacement_contracts = &transaction.replacement_contracts;
        transaction.replacement_bases = try types_mod.WhereMethodMarkerBasis.SafeList.initCapacity(
            self.types.gpa,
            transaction.input.bases.len,
        );
        transaction.replacement_type_paths = try types_mod.WhereMethodMarkerPathStep.SafeList.initCapacity(
            self.types.gpa,
            old_type_paths.len,
        );
        const replacement_type_paths = &transaction.replacement_type_paths;

        transaction.relocations = try self.gpa.alloc(CheckedBoundaryConstraintRelocation, old_constraints.len);
        const relocations = transaction.relocations.?;
        @memset(relocations, .{});
        const marker_offset_maps = &transaction.marker_offset_maps;

        for (old_constraints, 0..) |constraint, raw_constraint_index| {
            if (!referenced_constraints[raw_constraint_index]) continue;
            const old_marker_len: usize = constraint.where_method_markers.len();
            const old_marker_start: usize = if (old_marker_len == 0)
                0
            else
                @intFromEnum(constraint.where_method_markers.start);
            const source_markers = old_contracts[old_marker_start..][0..old_marker_len];
            const marker_map_start: u32 = @intCast(marker_offset_maps.items.len);
            try marker_offset_maps.ensureUnusedCapacity(self.gpa, old_marker_len);
            const new_marker_start: u32 = @intCast(replacement_contracts.items.items.len);
            var previous_source: ?types_mod.WhereMethodMarkerContract = null;
            for (source_markers) |source_marker| {
                if (source_marker.isReady() != true) {
                    @panic("referenced where-method producer escaped its settled boundary");
                }
                if (previous_source) |previous| {
                    if (self.compareWhereMethodMarkerPathsOnly(previous, source_marker) == .eq) {
                        const output_offset: u32 = @intCast(replacement_contracts.items.items.len - new_marker_start - 1);
                        marker_offset_maps.appendAssumeCapacity(output_offset);
                        const output = &replacement_contracts.items.items[new_marker_start + output_offset];
                        if (output.position != source_marker.position) {
                            @panic("one canonical marker path had incompatible position classes");
                        }
                        previous_source = source_marker;
                        continue;
                    }
                }
                const source_path = old_type_paths[source_marker.path_start..][0..source_marker.path_len];
                const new_path = try replacement_type_paths.appendSlice(self.types.gpa, source_path);
                var canonical_marker = source_marker;
                canonical_marker.producer_owner_node = none;
                canonical_marker.producer_where_node = none;
                canonical_marker.producer_method_name = none;
                canonical_marker.widened = 0;
                canonical_marker.ready = 1;
                canonical_marker.path_start = @intFromEnum(new_path.start);
                _ = try replacement_contracts.append(self.types.gpa, canonical_marker);
                marker_offset_maps.appendAssumeCapacity(
                    @intCast(replacement_contracts.items.items.len - new_marker_start - 1),
                );
                previous_source = source_marker;
            }
            var canonical_constraint = constraint;
            const new_marker_len: u32 = @intCast(replacement_contracts.items.items.len - new_marker_start);
            canonical_constraint.where_method_markers = if (new_marker_len == 0)
                .empty()
            else
                .{ .start = @enumFromInt(new_marker_start), .count = new_marker_len };
            canonical_constraint.where_method_marker_bases = .empty();
            canonical_constraint.constraint_evidence = .none;
            const new_constraint_index: u32 = @intCast(replacement_constraints.items.items.len);
            _ = try replacement_constraints.append(self.types.gpa, canonical_constraint);
            relocations[raw_constraint_index] = .{
                .new_constraint_index = new_constraint_index,
                .marker_map_start = marker_map_start,
                .old_marker_len = @intCast(old_marker_len),
                .new_marker_start = new_marker_start,
                .new_marker_len = new_marker_len,
            };
        }

        transaction.staged_sources = try self.gpa.alloc(
            ModuleEnv.WhereMethodSource,
            transaction.input.where_method_sources.len,
        );
        const staged_sources = transaction.staged_sources.?;
        for (transaction.where_source_order.?, 0..) |old_source_index, new_source_index| {
            const old_source = transaction.input.where_method_sources[old_source_index];
            var source = old_source;
            const start: usize = old_source.source_contracts_start;
            const len: usize = old_source.source_contracts_len;
            if ((len == 0 and start != 0) or
                (len != 0 and (start > old_contracts.len or len > old_contracts.len - start)))
            {
                @panic("checked-boundary where-method source range escaped its pool");
            }
            source.retained_constraint_index = checkedBoundaryRelocatedConstraintIndex(
                relocations,
                old_source.retained_constraint_index,
            );
            source.source_contracts_start = if (len == 0)
                0
            else
                @intCast(replacement_contracts.items.items.len);
            const source_contracts = old_contracts[start..][0..len];
            for (source_contracts, 0..) |marker, marker_offset| {
                if (marker.positionOrNull() == null or marker.isWidened() == null or
                    !marker.hasProducer() or marker.isReady() != true or marker.path_len == 0 or
                    marker.producer_owner_node != source.owner_node or
                    marker.producer_where_node != source.where_node or
                    marker.producer_method_name != source.method_ident or
                    marker.path_start > old_type_paths.len or
                    marker.path_len > old_type_paths.len - marker.path_start)
                {
                    @panic("checked-boundary where-method source did not own its exact producer rows");
                }
                if (marker_offset != 0 and self.compareWhereMethodMarkerContracts(
                    source_contracts[marker_offset - 1],
                    marker,
                ) != .lt) {
                    @panic("checked-boundary where-method source rows were not strictly ordered");
                }
                const source_path = old_type_paths[marker.path_start..][0..marker.path_len];
                const new_path = try replacement_type_paths.appendSlice(self.types.gpa, source_path);
                var canonical_marker = marker;
                canonical_marker.widened = @intFromBool(try self.checkedBoundaryLocalSourceFact(
                    old_source,
                    marker,
                ));
                canonical_marker.path_start = @intFromEnum(new_path.start);
                _ = try replacement_contracts.append(self.types.gpa, canonical_marker);
            }
            staged_sources[new_source_index] = source;
        }

        transaction.step_map = try self.gpa.alloc(u32, old_steps.len);
        const step_map = transaction.step_map.?;
        @memset(step_map, none);
        var next_step: u32 = 0;
        for (referenced_steps, 0..) |is_referenced, old_step_index| {
            if (!is_referenced) continue;
            step_map[old_step_index] = next_step;
            next_step += 1;
        }
        if (next_step != retained_step_count) {
            @panic("checked-boundary copy-step count overflowed");
        }
        transaction.default_decision_map = try self.gpa.alloc(u32, old_default_decisions.len);
        const default_decision_map = transaction.default_decision_map.?;
        @memset(default_decision_map, none);
        var next_default_decision: u32 = 0;
        for (referenced_default_decisions, 0..) |is_referenced, old_decision_index| {
            if (!is_referenced) continue;
            default_decision_map[old_decision_index] = next_default_decision;
            next_default_decision += 1;
        }
        if (next_default_decision != retained_default_decision_count) {
            @panic("checked-boundary default-decision count overflowed");
        }
        transaction.step_provider_envs = try self.gpa.alloc(?*const ModuleEnv, retained_step_count);
        const step_provider_envs = transaction.step_provider_envs.?;
        @memset(step_provider_envs, null);
        for (old_steps, 0..) |old_step, old_step_index| {
            if (!referenced_steps[old_step_index]) continue;
            const kind = old_step.decodedKind().?;
            switch (kind.sourceNamespace()) {
                .local => continue,
                .cross_module => step_provider_envs[step_map[old_step_index]] =
                    self.checkedBoundaryCrossStepProvider(old_steps, @intCast(old_step_index)),
                .transient => unreachable,
            }
        }

        transaction.replacement_steps = try ModuleEnv.WhereMarkerCopyStep.SafeList.initCapacity(
            self.cir.gpa,
            retained_step_count,
        );
        const replacement_steps = &transaction.replacement_steps;
        transaction.replacement_pairs = try ModuleEnv.WhereMarkerCopyPair.SafeList.initCapacity(
            self.cir.gpa,
            old_pairs.len,
        );
        const replacement_pairs = &transaction.replacement_pairs;
        transaction.replacement_occurrences = try ModuleEnv.WhereMarkerCopyOccurrence.SafeList.initCapacity(
            self.cir.gpa,
            old_occurrences.len,
        );
        const replacement_occurrences = &transaction.replacement_occurrences;
        transaction.replacement_constraint_pairs = try ModuleEnv.WhereMarkerConstraintCopyPair.SafeList.initCapacity(
            self.cir.gpa,
            old_constraint_pairs.len,
        );
        const replacement_constraint_pairs = &transaction.replacement_constraint_pairs;
        transaction.replacement_witnesses = try ModuleEnv.WhereMarkerCopyWitness.SafeList.initCapacity(
            self.cir.gpa,
            old_witnesses.len,
        );
        const replacement_witnesses = &transaction.replacement_witnesses;
        transaction.replacement_copied_literal_groups =
            try ModuleEnv.CopiedOpenLiteralGroup.SafeList.initCapacity(
                self.cir.gpa,
                old_copied_literal_groups.len,
            );
        const replacement_copied_literal_groups = &transaction.replacement_copied_literal_groups;
        transaction.replacement_copied_literal_events =
            try ModuleEnv.CopiedOpenLiteralEvent.SafeList.initCapacity(
                self.cir.gpa,
                old_copied_literal_events.len,
            );
        const replacement_copied_literal_events = &transaction.replacement_copied_literal_events;
        transaction.replacement_substitutions = try ModuleEnv.WhereMarkerPlatformSubstitution.SafeList.initCapacity(
            self.cir.gpa,
            old_substitutions.len,
        );
        const replacement_substitutions = &transaction.replacement_substitutions;

        transaction.pair_relocations = try self.gpa.alloc(u32, old_pairs.len);
        const pair_relocations = transaction.pair_relocations.?;
        @memset(pair_relocations, none);
        transaction.constraint_pair_relocations = try self.gpa.alloc(u32, old_constraint_pairs.len);
        const constraint_pair_relocations = transaction.constraint_pair_relocations.?;
        @memset(constraint_pair_relocations, none);
        transaction.occurrence_relocations = try self.gpa.alloc(u32, old_occurrences.len);
        const occurrence_relocations = transaction.occurrence_relocations.?;
        @memset(occurrence_relocations, none);
        transaction.copied_literal_group_map = try self.gpa.alloc(u32, old_copied_literal_groups.len);
        const copied_literal_group_map = transaction.copied_literal_group_map.?;
        @memset(copied_literal_group_map, none);
        transaction.copied_literal_event_map = try self.gpa.alloc(u32, old_copied_literal_events.len);
        const copied_literal_event_map = transaction.copied_literal_event_map.?;
        @memset(copied_literal_event_map, none);

        for (old_steps, 0..) |old_step, old_step_index| {
            if (!referenced_steps[old_step_index]) continue;
            var step = old_step;
            const kind = step.decodedKind().?;
            const provider = step_provider_envs[step_map[old_step_index]];

            var step_pairs: std.ArrayListUnmanaged(ModuleEnv.WhereMarkerCopyPair) = .empty;
            defer step_pairs.deinit(self.gpa);
            try step_pairs.ensureTotalCapacity(self.gpa, old_step.occurrences_len);
            const old_step_occurrences = old_occurrences[old_step.occurrences_start..][0..old_step.occurrences_len];
            for (old_step_occurrences) |old_occurrence| {
                const raw_source: Var = @enumFromInt(old_occurrence.raw_source_var);
                const raw_destination: Var = @enumFromInt(old_occurrence.raw_destination_var);
                const source_root = if (kind.sourceNamespace() == .local)
                    self.types.resolveVar(raw_source).var_
                else blk: {
                    const source_env = provider orelse
                        @panic("cross-module copy occurrence had no provider authority");
                    if (old_occurrence.raw_source_var >= source_env.types.len()) {
                        @panic("cross-module raw source occurrence escaped its provider store");
                    }
                    break :blk source_env.types.resolveVar(raw_source).var_;
                };
                const destination_root = self.types.resolveVar(raw_destination).var_;
                step_pairs.appendAssumeCapacity(.{
                    .source_var = @intFromEnum(source_root),
                    .destination_var = @intFromEnum(destination_root),
                    .discovery_depth = none,
                    .predecessor_pair_offset = none,
                    .predecessor_edge_ordinal = none,
                });
            }
            std.mem.sortUnstable(
                ModuleEnv.WhereMarkerCopyPair,
                step_pairs.items,
                {},
                durableWhereMarkerCopyPairLessThan,
            );
            const step_pair_write = deduplicateSortedWhereMarkerCopyPairs(step_pairs.items);
            step_pairs.items.len = step_pair_write;
            if (step_pair_write == 0 or step_pair_write > std.math.maxInt(u32)) {
                @panic("checked-boundary copy step had an invalid final pair count");
            }

            var step_occurrences: std.ArrayListUnmanaged(ModuleEnv.WhereMarkerCopyOccurrence) = .empty;
            defer step_occurrences.deinit(self.gpa);
            try step_occurrences.ensureTotalCapacity(self.gpa, old_step_occurrences.len);
            for (old_step_occurrences) |old_occurrence| {
                const raw_source: Var = @enumFromInt(old_occurrence.raw_source_var);
                const raw_destination: Var = @enumFromInt(old_occurrence.raw_destination_var);
                const source_root = if (kind.sourceNamespace() == .local)
                    self.types.resolveVar(raw_source).var_
                else
                    (provider orelse unreachable).types.resolveVar(raw_source).var_;
                const destination_root = self.types.resolveVar(raw_destination).var_;
                step_occurrences.appendAssumeCapacity(.{
                    .raw_source_var = old_occurrence.raw_source_var,
                    .raw_destination_var = old_occurrence.raw_destination_var,
                    .canonical_pair_offset = proofPairOffset(
                        step_pairs.items,
                        @intFromEnum(source_root),
                        @intFromEnum(destination_root),
                    ),
                });
            }
            std.mem.sortUnstable(
                ModuleEnv.WhereMarkerCopyOccurrence,
                step_occurrences.items,
                {},
                whereMarkerCopyOccurrenceLessThan,
            );
            for (step_occurrences.items, 0..) |occurrence, occurrence_offset| {
                if (occurrence_offset != 0 and
                    occurrence.raw_source_var == step_occurrences.items[occurrence_offset - 1].raw_source_var and
                    occurrence.raw_destination_var == step_occurrences.items[occurrence_offset - 1].raw_destination_var)
                {
                    @panic("checked-boundary copy step repeated a raw occurrence");
                }
                const old_relative = proofOccurrenceOffset(
                    old_step_occurrences,
                    occurrence.raw_source_var,
                    occurrence.raw_destination_var,
                );
                occurrence_relocations[old_step.occurrences_start + old_relative] = @intCast(occurrence_offset);
            }
            for (0..old_step.pairs_len) |old_pair_offset| {
                var mapped_pair: u32 = none;
                for (old_step_occurrences, 0..) |old_occurrence, old_occurrence_offset| {
                    if (old_occurrence.canonical_pair_offset != old_pair_offset) continue;
                    const new_occurrence_offset = occurrence_relocations[
                        old_step.occurrences_start + old_occurrence_offset
                    ];
                    const candidate = step_occurrences.items[new_occurrence_offset].canonical_pair_offset;
                    if (mapped_pair != none and mapped_pair != candidate) {
                        @panic("one old canonical pair split during final occurrence resolution");
                    }
                    mapped_pair = candidate;
                }
                if (mapped_pair == none) @panic("old canonical pair had no raw occurrence");
                pair_relocations[old_step.pairs_start + old_pair_offset] = mapped_pair;
            }

            step.pairs_start = @intCast(replacement_pairs.items.items.len);
            step.pairs_len = @intCast(step_pairs.items.len);
            for (step_pairs.items) |pair| {
                _ = try replacement_pairs.append(self.cir.gpa, pair);
            }
            step.occurrences_start = @intCast(replacement_occurrences.items.items.len);
            step.occurrences_len = @intCast(step_occurrences.items.len);
            step.root_occurrence_offset = occurrence_relocations[
                old_step.occurrences_start + old_step.root_occurrence_offset
            ];
            if (step.root_occurrence_offset == none) {
                @panic("checked-boundary copy step lost its exact root occurrence");
            }
            const root_pair = step_pairs.items[
                step_occurrences.items[step.root_occurrence_offset].canonical_pair_offset
            ];
            step.source_root_var = root_pair.source_var;
            step.destination_root_var = root_pair.destination_var;
            for (step_occurrences.items) |occurrence| {
                _ = try replacement_occurrences.append(self.cir.gpa, occurrence);
            }
            step.constraint_pairs_start = @intCast(replacement_constraint_pairs.items.items.len);
            const RelocatedConstraintPair = struct {
                old_offset: u32,
                pair: ModuleEnv.WhereMarkerConstraintCopyPair,
            };
            var step_constraint_pairs: std.ArrayListUnmanaged(RelocatedConstraintPair) = .empty;
            defer step_constraint_pairs.deinit(self.gpa);
            try step_constraint_pairs.ensureTotalCapacity(self.gpa, old_step.constraint_pairs_len);
            for (
                old_constraint_pairs[old_step.constraint_pairs_start..][0..old_step.constraint_pairs_len],
                0..,
            ) |old_pair, old_pair_offset| {
                var pair = old_pair;
                if (kind.sourceNamespace() == .local) {
                    pair.source_constraint_index = checkedBoundaryRelocatedConstraintIndex(
                        relocations,
                        old_pair.source_constraint_index,
                    );
                } else {
                    const source_env = provider orelse
                        @panic("cross-module constraint-copy step had no provider authority");
                    if (old_pair.source_constraint_index >= source_env.types.static_dispatch_constraints.items.items.len) {
                        @panic("cross-module constraint-copy source escaped its provider");
                    }
                }
                pair.destination_constraint_index = checkedBoundaryRelocatedConstraintIndex(
                    relocations,
                    old_pair.destination_constraint_index,
                );
                step_constraint_pairs.appendAssumeCapacity(.{
                    .old_offset = @intCast(old_pair_offset),
                    .pair = pair,
                });
            }
            std.mem.sortUnstable(RelocatedConstraintPair, step_constraint_pairs.items, {}, struct {
                fn lessThan(_: void, left: RelocatedConstraintPair, right: RelocatedConstraintPair) bool {
                    return ModuleEnv.WhereMarkerConstraintCopyPair.canonicalLessThan(
                        left.pair,
                        right.pair,
                    );
                }
            }.lessThan);
            for (step_constraint_pairs.items, 0..) |relocated_pair, new_pair_offset| {
                if (new_pair_offset != 0 and
                    !ModuleEnv.WhereMarkerConstraintCopyPair.canonicalLessThan(
                        step_constraint_pairs.items[new_pair_offset - 1].pair,
                        relocated_pair.pair,
                    ))
                {
                    @panic("checked-boundary constraint-copy relation repeated one source occurrence");
                }
                constraint_pair_relocations[
                    old_step.constraint_pairs_start + relocated_pair.old_offset
                ] = @intCast(new_pair_offset);
                _ = try replacement_constraint_pairs.append(self.cir.gpa, relocated_pair.pair);
            }
            var step_witnesses: std.ArrayListUnmanaged(ModuleEnv.WhereMarkerCopyWitness) = .empty;
            defer step_witnesses.deinit(self.gpa);
            try step_witnesses.ensureTotalCapacity(self.gpa, old_step.witnesses_len);
            for (old_witnesses[old_step.witnesses_start..][0..old_step.witnesses_len]) |old_witness| {
                const auxiliary_kind = old_witness.decodedAuxiliaryOriginKind().?;
                if (auxiliary_kind == .predeclared_annotation_event) {
                    @panic("checked-boundary rebuild retained a provisional annotation witness");
                }
                var witness = old_witness;
                witness.parent_occurrence_offset = occurrence_relocations[
                    old_step.occurrences_start + old_witness.parent_occurrence_offset
                ];
                witness.child_occurrence_offset = occurrence_relocations[
                    old_step.occurrences_start + old_witness.child_occurrence_offset
                ];
                if (witness.parent_occurrence_offset == none or witness.child_occurrence_offset == none) {
                    @panic("checked-boundary witness lost a raw occurrence");
                }
                if (old_witness.constraint_pair_offset != none) {
                    if (old_witness.constraint_pair_offset >= old_step.constraint_pairs_len) {
                        @panic("checked-boundary witness constraint pair escaped its owner step");
                    }
                    witness.constraint_pair_offset = constraint_pair_relocations[
                        old_step.constraint_pairs_start + old_witness.constraint_pair_offset
                    ];
                    if (witness.constraint_pair_offset == none) {
                        @panic("checked-boundary witness lost its exact constraint pair");
                    }
                }
                if (auxiliary_kind == .binding_copy_pair) {
                    const origin_step_index = old_witness.auxiliary_origin_step;
                    if (origin_step_index >= old_step_index) {
                        @panic("binding-codec cut named a non-prior mapping origin step");
                    }
                    const parent_step = old_steps[origin_step_index];
                    if (old_witness.auxiliary_origin_index >= parent_step.pairs_len) {
                        @panic("binding-codec cut escaped its origin pair relation");
                    }
                    witness.auxiliary_origin_index = pair_relocations[
                        parent_step.pairs_start + old_witness.auxiliary_origin_index
                    ];
                    if (witness.auxiliary_origin_index == none) {
                        @panic("binding-codec cut lost its exact origin pair");
                    }
                    witness.auxiliary_origin_step = checkedBoundaryRelocatedCopyStep(
                        step_map,
                        origin_step_index,
                    );
                }
                step_witnesses.appendAssumeCapacity(witness);
            }
            std.mem.sortUnstable(
                ModuleEnv.WhereMarkerCopyWitness,
                step_witnesses.items,
                {},
                whereMarkerCopyWitnessLessThan,
            );
            if (step_witnesses.items.len > 1) {
                for (step_witnesses.items[1..], step_witnesses.items[0 .. step_witnesses.items.len - 1]) |current, previous| {
                    if (std.meta.eql(current, previous)) {
                        @panic("checked-boundary copy step repeated a relocated witness");
                    }
                }
            }
            step.witnesses_start = @intCast(replacement_witnesses.items.items.len);
            step.witnesses_len = @intCast(step_witnesses.items.len);
            for (step_witnesses.items) |witness| {
                _ = try replacement_witnesses.append(self.cir.gpa, witness);
            }

            const RelocatedCopiedLiteralGroup = struct {
                old_group_index: u32,
                old_events_start: u32,
                old_events_len: u32,
                group: ModuleEnv.CopiedOpenLiteralGroup,
            };
            var relocated_copied_groups: std.ArrayListUnmanaged(RelocatedCopiedLiteralGroup) = .empty;
            defer relocated_copied_groups.deinit(self.gpa);
            try relocated_copied_groups.ensureTotalCapacity(self.gpa, old_step.copied_groups_len);
            for (
                old_copied_literal_groups[old_step.copied_groups_start..][0..old_step.copied_groups_len],
                0..,
            ) |old_group, old_group_offset| {
                const old_group_index = old_step.copied_groups_start +
                    @as(u32, @intCast(old_group_offset));
                var group = old_group;
                if (old_group.copy_step_index != old_step_index or
                    old_group.receiver_occurrence_offset >= old_step.occurrences_len)
                {
                    @panic("checked-boundary copied-literal group escaped its old copy step");
                }
                group.copy_step_index = checkedBoundaryRelocatedCopyStep(
                    step_map,
                    @intCast(old_step_index),
                );
                group.receiver_occurrence_offset = occurrence_relocations[
                    old_step.occurrences_start + old_group.receiver_occurrence_offset
                ];
                if (group.receiver_occurrence_offset == none) {
                    @panic("checked-boundary copied-literal group lost its receiver occurrence");
                }
                switch (group.component.decodedKind() orelse
                    @panic("checked-boundary copied-literal group had an invalid component")) {
                    .root_graph, .scheme_requirement => {},
                    .binding_codec_receiver, .binding_codec_function => {
                        group.component.binding_root_step = checkedBoundaryRelocatedCopyStep(
                            step_map,
                            old_group.component.binding_root_step,
                        );
                    },
                }

                if (kind.sourceNamespace() == .local) {
                    const source_start = checkedBoundaryRelocatedConstraintIndex(
                        relocations,
                        old_group.source_constraints_start,
                    );
                    for (0..old_group.source_constraints_len) |constraint_offset| {
                        const relocated = checkedBoundaryRelocatedConstraintIndex(
                            relocations,
                            old_group.source_constraints_start + @as(u32, @intCast(constraint_offset)),
                        );
                        if (relocated != source_start + @as(u32, @intCast(constraint_offset))) {
                            @panic("copied-literal source constraint range did not remain contiguous");
                        }
                    }
                    group.source_constraints_start = source_start;
                }
                const destination_start = checkedBoundaryRelocatedConstraintIndex(
                    relocations,
                    old_group.destination_constraints_start,
                );
                for (0..old_group.destination_constraints_len) |constraint_offset| {
                    const relocated = checkedBoundaryRelocatedConstraintIndex(
                        relocations,
                        old_group.destination_constraints_start + @as(u32, @intCast(constraint_offset)),
                    );
                    if (relocated != destination_start + @as(u32, @intCast(constraint_offset))) {
                        @panic("copied-literal destination constraint range did not remain contiguous");
                    }
                }
                group.destination_constraints_start = destination_start;
                relocated_copied_groups.appendAssumeCapacity(.{
                    .old_group_index = old_group_index,
                    .old_events_start = old_group.events_start,
                    .old_events_len = old_group.events_len,
                    .group = group,
                });
            }
            std.mem.sortUnstable(
                RelocatedCopiedLiteralGroup,
                relocated_copied_groups.items,
                {},
                struct {
                    fn lessThan(
                        _: void,
                        left: RelocatedCopiedLiteralGroup,
                        right: RelocatedCopiedLiteralGroup,
                    ) bool {
                        return ModuleEnv.CopiedOpenLiteralGroup.canonicalLessThan(
                            left.group,
                            right.group,
                        );
                    }
                }.lessThan,
            );
            step.copied_groups_start = @intCast(replacement_copied_literal_groups.items.items.len);
            step.copied_groups_len = @intCast(relocated_copied_groups.items.len);
            for (relocated_copied_groups.items, 0..) |relocated_group, relative_group_index| {
                var group = relocated_group.group;
                const new_group_index = step.copied_groups_start +
                    @as(u32, @intCast(relative_group_index));
                if (relative_group_index != 0 and
                    !ModuleEnv.CopiedOpenLiteralGroup.canonicalLessThan(
                        relocated_copied_groups.items[relative_group_index - 1].group,
                        group,
                    ))
                {
                    @panic("checked-boundary copied-literal groups coalesced after relocation");
                }
                copied_literal_group_map[relocated_group.old_group_index] = new_group_index;
                group.events_start = @intCast(replacement_copied_literal_events.items.items.len);
                for (
                    old_copied_literal_events[relocated_group.old_events_start..][0..relocated_group.old_events_len],
                    0..,
                ) |old_event, old_event_offset| {
                    const old_event_index = relocated_group.old_events_start +
                        @as(u32, @intCast(old_event_offset));
                    if (old_event.group_index != relocated_group.old_group_index) {
                        @panic("checked-boundary copied-literal event lost its old group owner");
                    }
                    const new_event_index: u32 = @intCast(
                        replacement_copied_literal_events.items.items.len,
                    );
                    copied_literal_event_map[old_event_index] = new_event_index;
                    var event = old_event;
                    event.group_index = new_group_index;
                    _ = try replacement_copied_literal_events.append(self.cir.gpa, event);
                }
                group.events_len = relocated_group.old_events_len;
                _ = try replacement_copied_literal_groups.append(self.cir.gpa, group);
            }
            switch (step.decodedKind().?) {
                .external_cache_seed => {
                    const old_seed_index = old_step.origin.external_cache_seed.seed_row;
                    if (old_seed_index >= external_seed_map.len or
                        external_seed_map[old_seed_index] == none)
                    {
                        @panic("external cache support lost its owning seed row");
                    }
                    step.origin.external_cache_seed.seed_row = external_seed_map[old_seed_index];
                },
                .binding_codec_receiver => {
                    step.origin.binding_codec_receiver.binding_root_step =
                        checkedBoundaryRelocatedCopyStep(
                            step_map,
                            step.origin.binding_codec_receiver.binding_root_step,
                        );
                },
                .binding_codec_function => {
                    step.origin.binding_codec_function.binding_root_step =
                        checkedBoundaryRelocatedCopyStep(
                            step_map,
                            step.origin.binding_codec_function.binding_root_step,
                        );
                },
                .platform_requirement => {
                    const old_platform = old_step.origin.platform_requirement;
                    step.origin.platform_requirement.substitutions_start =
                        @intCast(replacement_substitutions.items.items.len);
                    for (old_substitutions[old_platform.substitutions_start..][0..old_platform.substitutions_len]) |old_substitution| {
                        var substitution = old_substitution;
                        substitution.app_instantiation_step = checkedBoundaryRelocatedCopyStep(
                            step_map,
                            old_substitution.app_instantiation_step,
                        );
                        _ = try replacement_substitutions.append(self.cir.gpa, substitution);
                    }
                },
                .selected_dispatch_method => {},
                .candidate_probe_method_root => {
                    step.origin.candidate_probe_method_root.constraint_index =
                        checkedBoundaryRelocatedConstraintIndex(
                            relocations,
                            step.origin.candidate_probe_method_root.constraint_index,
                        );
                },
                .candidate_probe_method_use => {
                    step.origin.candidate_probe_method_use.constraint_index =
                        checkedBoundaryRelocatedConstraintIndex(
                            relocations,
                            step.origin.candidate_probe_method_use.constraint_index,
                        );
                },
                .default_method => {
                    const old_decision_index = step.origin.default_method.decision_index;
                    if (old_decision_index >= default_decision_map.len or
                        default_decision_map[old_decision_index] == none)
                    {
                        @panic("retained default-method copy lost its decision root");
                    }
                    step.origin.default_method.decision_index = default_decision_map[old_decision_index];
                },
                .default_method_use => {
                    const old_decision_index = step.origin.default_method_use.decision_index;
                    if (old_decision_index >= default_decision_map.len or
                        default_decision_map[old_decision_index] == none)
                    {
                        @panic("retained default-method use lost its decision root");
                    }
                    step.origin.default_method_use.decision_index = default_decision_map[old_decision_index];
                    step.origin.default_method_use.root_copy_step = checkedBoundaryRelocatedCopyStep(
                        step_map,
                        step.origin.default_method_use.root_copy_step,
                    );
                },
                .aggregate_fresh_shape_child => {
                    const old_origin = old_step.origin.aggregate_fresh_shape_child;
                    if (old_origin.expected_plans_len == 0 or
                        !rangeFits(
                            old_origin.expected_plans_start,
                            old_origin.expected_plans_len,
                            old_expected_plans.len,
                        ))
                    {
                        @panic("fresh aggregate support escaped its Expected-plan range");
                    }
                    const relocated_plan_start = expected_plan_map[old_origin.expected_plans_start];
                    for (0..old_origin.expected_plans_len) |relative_index| {
                        const old_plan_index = old_origin.expected_plans_start +
                            @as(u32, @intCast(relative_index));
                        if (expected_plan_map[old_plan_index] != relocated_plan_start +
                            @as(u32, @intCast(relative_index)))
                        {
                            @panic("fresh aggregate support lost its canonical gapless plan range");
                        }
                    }
                    if (old_origin.parent_authority.decodedKind() != .copy_occurrence or
                        old_origin.parent_authority.payload.copy_occurrence.copy_step >= old_step_index)
                    {
                        @panic("fresh aggregate support did not name an earlier copy authority");
                    }
                    step.origin.aggregate_fresh_shape_child.expected_plans_start = relocated_plan_start;
                    step.origin.aggregate_fresh_shape_child.parent_authority =
                        checkedBoundaryRelocatedExpectedAuthority(
                            old_origin.parent_authority,
                            old_steps,
                            old_occurrences,
                            step_map,
                            occurrence_relocations,
                            expected_plan_map,
                            replacement_steps.items.items,
                            replacement_occurrences.items.items,
                        );
                },
                .aggregate_expected_projection, .branch_expected_copy => {
                    const old_origin = if (kind == .aggregate_expected_projection)
                        old_step.origin.aggregate_expected_projection
                    else
                        old_step.origin.branch_expected_copy;
                    if (old_origin.expected_plan_index >= old_expected_plans.len or
                        expected_plan_map[old_origin.expected_plan_index] == none)
                    {
                        @panic("expected-copy origin lost its exact consumer plan");
                    }
                    if (old_origin.parent_authority.decodedKind() == .evidence_free_plan) {
                        @panic("marker-copy origin borrowed an evidence-free plan as a copy occurrence");
                    }
                    if (old_origin.parent_authority.decodedKind() == .copy_occurrence and
                        old_origin.parent_authority.payload.copy_occurrence.copy_step >= old_step_index)
                    {
                        @panic("expected-copy origin named a non-prior parent copy step");
                    }
                    const selected_parent_raw = expectedParentAuthorityRawForProof(
                        self.cir,
                        old_origin.parent_authority,
                        old_steps,
                        old_occurrences,
                        old_step_index,
                    ) orelse @panic("expected-copy origin lost its exact parent authority");
                    if (old_step_occurrences[old_step.root_occurrence_offset].raw_source_var !=
                        selected_parent_raw)
                    {
                        @panic("expected-copy root did not consume its exact parent authority");
                    }
                    const relocated_authority = checkedBoundaryRelocatedExpectedAuthority(
                        old_origin.parent_authority,
                        old_steps,
                        old_occurrences,
                        step_map,
                        occurrence_relocations,
                        expected_plan_map,
                        replacement_steps.items.items,
                        replacement_occurrences.items.items,
                    );
                    if (kind == .aggregate_expected_projection) {
                        step.origin.aggregate_expected_projection.parent_authority = relocated_authority;
                        step.origin.aggregate_expected_projection.expected_plan_index =
                            expected_plan_map[old_origin.expected_plan_index];
                    } else {
                        step.origin.branch_expected_copy.parent_authority = relocated_authority;
                        step.origin.branch_expected_copy.expected_plan_index =
                            expected_plan_map[old_origin.expected_plan_index];
                    }
                },
                .expected_call_instantiation => {
                    const old_origin = old_step.origin.expected_call_instantiation;
                    switch (old_origin.decodedSourceKind() orelse
                        @panic("call instantiation had an invalid source kind")) {
                        .local_predeclared_annotation => {
                            if (old_origin.source_support_step >= step_map.len or
                                step_map[old_origin.source_support_step] == none)
                            {
                                @panic("call instantiation lost its exact source support step");
                            }
                            step.origin.expected_call_instantiation.source_support_step =
                                step_map[old_origin.source_support_step];
                        },
                        .external_import_root => {
                            const old_seed_index = old_origin.source_seed_index;
                            if (old_seed_index >= external_seed_map.len or
                                external_seed_map[old_seed_index] == none)
                            {
                                @panic("call instantiation lost its external cache seed");
                            }
                            step.origin.expected_call_instantiation.source_seed_index =
                                external_seed_map[old_seed_index];
                        },
                        .local_callee_expression,
                        .local_binding_pattern,
                        => {},
                    }
                },
                .reserved,
                .discarded,
                => unreachable,
                .external_cir_node,
                .external_numeric_suffix,
                .external_where_alias_receiver,
                .external_where_alias_parameter,
                .generated_codec_method,
                .inspect_method,
                .associated_method,
                .scheme_use,
                .type_annotation,
                .numeric_suffix_use,
                .nominal_expr_decl,
                .nominal_expr_backing,
                .nominal_pattern_decl,
                .nominal_pattern_backing,
                .required_lookup,
                .platform_requirement_instance,
                .platform_alias_app_decl,
                .default_field_type,
                .record_update_base,
                .predeclared_annotation,
                .generated_codec_snapshot,
                => {},
            }
            canonicalizeCheckedBoundaryCopyPairBfs(
                replacement_pairs.items.items[step.pairs_start..][0..step.pairs_len],
                replacement_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len],
                replacement_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len],
                step.root_occurrence_offset,
            );
            _ = try replacement_steps.append(self.cir.gpa, step);
        }
    }

    fn rebuildExpectedLedgers(transaction: *Transaction) Allocator.Error!void {
        const self = transaction.checker;
        const old_steps = transaction.input.steps;
        const old_occurrences = transaction.input.occurrences;
        const old_expected_plans = transaction.input.expected_plans;
        const old_expected_failures = transaction.input.expected_failures;
        const old_expected_retirements = transaction.input.expected_retirements;
        const old_expected_ambiguity_retirements = transaction.input.expected_ambiguity_retirements;
        const old_expected_retirement_failures = transaction.input.expected_retirement_failures;
        const old_expected_retired_consumers = transaction.input.expected_retired_consumers;
        const old_expected_call_formals = transaction.input.expected_call_formals;
        const old_external_cache_seeds = transaction.input.external_cache_seeds;
        const external_seed_order = transaction.external_seed_order.?;
        const expected_failure_order = transaction.expected_failure_order.?;
        const expected_failure_map = transaction.expected_failure_map.?;
        const expected_retirement_order = transaction.expected_retirement_order.?;
        const expected_retirement_map = transaction.expected_retirement_map.?;
        const expected_plan_order = transaction.expected_plan_order.?;
        const expected_plan_map = transaction.expected_plan_map.?;
        const step_map = transaction.step_map.?;
        const pair_relocations = transaction.pair_relocations.?;
        const occurrence_relocations = transaction.occurrence_relocations.?;
        const relocations = transaction.relocations.?;
        const replacement_steps = &transaction.replacement_steps;
        const replacement_occurrences = &transaction.replacement_occurrences;

        transaction.replacement_external_cache_seeds = try ModuleEnv.ExternalCacheSeed.SafeList.initCapacity(
            self.cir.gpa,
            old_external_cache_seeds.len,
        );
        const replacement_external_cache_seeds = &transaction.replacement_external_cache_seeds;
        for (external_seed_order) |old_seed_index| {
            var seed = old_external_cache_seeds[old_seed_index];
            seed.support_step = checkedBoundaryRelocatedCopyStep(step_map, seed.support_step);
            if (!seed.hasCanonicalTags()) {
                @panic("relocated external cache seed was not terminal");
            }
            _ = try replacement_external_cache_seeds.append(self.cir.gpa, seed);
        }

        transaction.replacement_expected_failures = try ModuleEnv.ExpectedFailure.SafeList.initCapacity(
            self.cir.gpa,
            old_expected_failures.len,
        );
        const replacement_expected_failures = &transaction.replacement_expected_failures;
        for (expected_failure_order, 0..) |old_failure_index, new_failure_index| {
            var failure = old_expected_failures[old_failure_index];
            failure.subject_authority = checkedBoundaryRelocatedExpectedFailureSubject(
                failure.subject_authority,
                old_steps,
                old_occurrences,
                step_map,
                occurrence_relocations,
                expected_plan_map,
                replacement_steps.items.items,
                replacement_occurrences.items.items,
            );
            if (failure.decodedKind() == .direct_binder_lookup_checked_error) {
                const direct = failure.subject_authority.decodedDirect() orelse
                    @panic("direct binder lookup failure lost its direct subject");
                if (failure.subject_authority.decodedDirectPhase() !=
                    .direct_binder_lookup_checked_error or
                    direct.local_record_index >= expected_failure_map.len or
                    expected_failure_map[direct.local_record_index] == none or
                    expected_failure_map[direct.local_record_index] >= new_failure_index)
                {
                    @panic("direct binder lookup failure lost its exact source failure");
                }
                failure.subject_authority.payload.direct.local_record_index =
                    expected_failure_map[direct.local_record_index];
            }
            if (failure.constraint_index != none) {
                failure.constraint_index = checkedBoundaryRelocatedConstraintIndex(
                    relocations,
                    failure.constraint_index,
                );
            }
            if (failure.plan_index != none) {
                const relocated_plan = expected_plan_map[failure.plan_index];
                if (relocated_plan == none) {
                    @panic("Expected failure lost its exact consumption plan");
                }
                failure.plan_index = relocated_plan;
            }
            failure.cause_owner = checkedBoundaryRelocatedExpectedCauseOwner(
                failure.cause_owner,
                expected_failure_map,
                expected_retirement_map,
            );
            if (failure.cause_owner.decodedExpectedFailure()) |cause| {
                if (cause.index >= new_failure_index) {
                    @panic("Expected failure lost its exact causal predecessor");
                }
            }
            _ = try replacement_expected_failures.append(self.cir.gpa, failure);
        }

        transaction.replacement_expected_plans = try ModuleEnv.ExpectedConsumptionPlan.SafeList.initCapacity(
            self.cir.gpa,
            old_expected_plans.len,
        );
        const replacement_expected_plans = &transaction.replacement_expected_plans;
        for (expected_plan_order, 0..) |old_plan_index, new_plan_index| {
            var plan = old_expected_plans[old_plan_index];
            if (plan.parent_authority.kind != ModuleEnv.ExpectedMarkerAuthority.none) {
                plan.parent_authority = checkedBoundaryRelocatedExpectedAuthority(
                    plan.parent_authority,
                    old_steps,
                    old_occurrences,
                    step_map,
                    occurrence_relocations,
                    expected_plan_map,
                    replacement_steps.items.items,
                    replacement_occurrences.items.items,
                );
                if (plan.parent_authority.decodedKind() == .producer_root_plan) {
                    const root = plan.parent_authority.payload.producer_root_plan;
                    if (root.plan_index >= new_plan_index) {
                        @panic("Expected-consumption producer-root authority did not remain a predecessor");
                    }
                    const root_plan = replacement_expected_plans.items.items[root.plan_index];
                    if (root_plan.decodedOutcome() != .producer_root or
                        root_plan.decodedRole() != .call_argument or
                        root_plan.raw_consumer_var != root.raw_var)
                    {
                        @panic("Expected-consumption parent authority changed its producer-root identity");
                    }
                }
                if (plan.parent_authority.decodedKind() == .evidence_free_plan) {
                    const parent = plan.parent_authority.payload.evidence_free_plan;
                    if (parent.plan_index >= new_plan_index) {
                        @panic("Expected-consumption evidence-free authority did not remain a predecessor");
                    }
                    const parent_plan = replacement_expected_plans.items.items[parent.plan_index];
                    if (parent_plan.raw_consumer_var != parent.raw_var or
                        (parent_plan.decodedOutcome() != .evidence_free and
                            !(parent_plan.decodedOutcome() == .checked_error and
                                parent_plan.decodedReason() == .aggregate_child_relation_rejected)))
                    {
                        @panic("Expected-consumption parent authority changed its evidence-free identity");
                    }
                }
                if (plan.parent_authority.decodedKind() == .relation_plan) {
                    const parent = plan.parent_authority.payload.relation_plan;
                    if (parent.plan_index >= new_plan_index) {
                        @panic("Expected-consumption relation authority did not remain a predecessor");
                    }
                    const parent_plan = replacement_expected_plans.items.items[parent.plan_index];
                    if (parent_plan.decodedRole() != .branch_contribution or
                        parent_plan.decodedOutcome() != .related)
                    {
                        @panic("Expected-consumption parent authority changed its relation identity");
                    }
                }
            }
            if (plan.produced_copy_step != none) {
                const side = plan.decodedProducedSide() orelse
                    @panic("Expected-consumption produced endpoint had an invalid side");
                const old_raw_endpoint = whereMarkerCopyEndpointRawVar(
                    old_steps,
                    old_occurrences,
                    plan.produced_copy_step,
                    plan.produced_occurrence_offset,
                    side,
                );
                const relocated = checkedBoundaryRelocatedExpectedCopyEndpoint(
                    old_steps,
                    step_map,
                    occurrence_relocations,
                    plan.produced_copy_step,
                    plan.produced_occurrence_offset,
                );
                plan.produced_copy_step = relocated.copy_step;
                plan.produced_occurrence_offset = relocated.occurrence_offset;
                const new_raw_endpoint = whereMarkerCopyEndpointRawVar(
                    replacement_steps.items.items,
                    replacement_occurrences.items.items,
                    plan.produced_copy_step,
                    plan.produced_occurrence_offset,
                    side,
                );
                if (old_raw_endpoint != new_raw_endpoint) {
                    @panic("Expected-consumption produced endpoint changed its selected raw side");
                }
            }
            if (plan.failure_cause_plan_index != none) {
                const relocated_cause = expected_plan_map[plan.failure_cause_plan_index];
                if (relocated_cause == none or relocated_cause >= new_plan_index) {
                    @panic("Expected-consumption cause did not remain an exact causal predecessor");
                }
                plan.failure_cause_plan_index = relocated_cause;
            }
            if (plan.call_root_plan_index != none) {
                const relocated_root = expected_plan_map[plan.call_root_plan_index];
                if (relocated_root == none or relocated_root >= new_plan_index) {
                    @panic("Expected-consumption call root did not remain a predecessor");
                }
                plan.call_root_plan_index = relocated_root;
            }
            plan.failure_owner = checkedBoundaryRelocatedExpectedCauseOwner(
                plan.failure_owner,
                expected_failure_map,
                expected_retirement_map,
            );
            if (plan.decodedSourceRetirementIndex()) |old_retirement_index| {
                if (old_retirement_index >= expected_retirement_map.len or
                    expected_retirement_map[old_retirement_index] == none or
                    expected_retirement_map[old_retirement_index] == std.math.maxInt(u32))
                {
                    @panic("record-update base plan lost its exact source retirement");
                }
                plan.source_retirement_index_plus_one =
                    expected_retirement_map[old_retirement_index] + 1;
            }
            _ = try replacement_expected_plans.append(self.cir.gpa, plan);
        }

        transaction.replacement_expected_call_formals =
            try ModuleEnv.ExpectedCallFormal.SafeList.initCapacity(
                self.cir.gpa,
                old_expected_call_formals.len,
            );
        const replacement_expected_call_formals = &transaction.replacement_expected_call_formals;
        for (old_expected_call_formals) |old_formal| {
            var formal = old_formal;
            if (old_formal.call_root_plan_index >= expected_plan_map.len or
                old_formal.argument_plan_index >= expected_plan_map.len or
                expected_plan_map[old_formal.call_root_plan_index] == none or
                expected_plan_map[old_formal.argument_plan_index] == none)
            {
                @panic("call formal lost one of its exact Expected plans");
            }
            formal.call_root_plan_index = expected_plan_map[old_formal.call_root_plan_index];
            formal.argument_plan_index = expected_plan_map[old_formal.argument_plan_index];
            if (old_formal.instantiation_copy_step != ModuleEnv.ExpectedCallFormal.none) {
                const relocated_root = checkedBoundaryRelocatedExpectedCopyEndpoint(
                    old_steps,
                    step_map,
                    occurrence_relocations,
                    old_formal.instantiation_copy_step,
                    old_formal.instantiation_root_occurrence,
                );
                formal.instantiation_copy_step = relocated_root.copy_step;
                formal.instantiation_root_occurrence = relocated_root.occurrence_offset;
                if (old_formal.instantiation_formal_occurrence !=
                    ModuleEnv.ExpectedCallFormal.none)
                {
                    const relocated_formal = checkedBoundaryRelocatedExpectedCopyEndpoint(
                        old_steps,
                        step_map,
                        occurrence_relocations,
                        old_formal.instantiation_copy_step,
                        old_formal.instantiation_formal_occurrence,
                    );
                    if (relocated_formal.copy_step != relocated_root.copy_step) {
                        @panic("call formal occurrences split across relocated steps");
                    }
                    formal.instantiation_formal_occurrence =
                        relocated_formal.occurrence_offset;
                }
            }
            _ = try replacement_expected_call_formals.append(self.cir.gpa, formal);
        }
        std.mem.sortUnstable(
            ModuleEnv.ExpectedCallFormal,
            replacement_expected_call_formals.items.items,
            {},
            ModuleEnv.ExpectedCallFormal.canonicalLessThan,
        );
        if (replacement_expected_call_formals.items.items.len >= 2) {
            for (
                replacement_expected_call_formals.items.items[1..],
                replacement_expected_call_formals.items.items[0 .. replacement_expected_call_formals.items.items.len - 1],
            ) |formal, previous| {
                if (!ModuleEnv.ExpectedCallFormal.canonicalLessThan({}, previous, formal)) {
                    @panic("call formal relocation produced a duplicate canonical row");
                }
            }
        }

        // Relocate every ambiguity verdict off-side before rebuilding the
        // retirements which own it. Canonical order is defined over the final
        // durable coordinates, not the producer's transient pool ordinals.
        const remapped_expected_ambiguity_retirements = try self.gpa.alloc(
            ModuleEnv.ExpectedAmbiguityRetirement,
            old_expected_ambiguity_retirements.len,
        );
        defer self.gpa.free(remapped_expected_ambiguity_retirements);
        for (old_expected_ambiguity_retirements, 0..) |old_retirement, old_index| {
            var retirement = old_retirement;
            retirement.selected_constraint_index = checkedBoundaryRelocatedConstraintIndex(
                relocations,
                old_retirement.selected_constraint_index,
            );
            if (old_retirement.consumer_root_plan >= expected_plan_map.len or
                expected_plan_map[old_retirement.consumer_root_plan] == none)
            {
                @panic("Expected ambiguity retirement lost its consumer root plan");
            }
            retirement.consumer_root_plan = expected_plan_map[old_retirement.consumer_root_plan];
            switch (old_retirement.decodedKind() orelse
                @panic("Expected ambiguity retirement had invalid tags during relocation")) {
                .body_forced_instantiation_branch => {
                    const old_step = old_steps[old_retirement.copy_step];
                    retirement.copy_step = checkedBoundaryRelocatedCopyStep(
                        step_map,
                        old_retirement.copy_step,
                    );
                    retirement.occurrence_offset = occurrence_relocations[
                        old_step.occurrences_start + old_retirement.occurrence_offset
                    ];
                    retirement.pair_offset = pair_relocations[
                        old_step.pairs_start + old_retirement.pair_offset
                    ];
                    if (retirement.occurrence_offset == none or retirement.pair_offset == none) {
                        @panic("Expected ambiguity retirement lost its exact copy coordinates");
                    }
                    const new_step = replacement_steps.items.items[retirement.copy_step];
                    if (retirement.occurrence_offset >= new_step.occurrences_len or
                        retirement.pair_offset >= new_step.pairs_len)
                    {
                        @panic("Expected ambiguity retirement escaped its relocated copy relation");
                    }
                    const new_occurrence = replacement_occurrences.items.items[
                        new_step.occurrences_start + retirement.occurrence_offset
                    ];
                    if (new_occurrence.raw_destination_var != retirement.raw_receiver_var or
                        new_occurrence.canonical_pair_offset != retirement.pair_offset)
                    {
                        @panic("Expected ambiguity retirement changed its selected raw occurrence");
                    }
                },
                .creation_dispatch_call => {
                    if (old_retirement.copy_step != ModuleEnv.ExpectedAmbiguityRetirement.none or
                        old_retirement.occurrence_offset != ModuleEnv.ExpectedAmbiguityRetirement.none or
                        old_retirement.pair_offset != ModuleEnv.ExpectedAmbiguityRetirement.none)
                    {
                        @panic("creation-call ambiguity retirement carried active copy coordinates");
                    }
                },
            }
            remapped_expected_ambiguity_retirements[old_index] = retirement;
        }

        const expected_ambiguity_order = try self.gpa.alloc(
            u32,
            old_expected_ambiguity_retirements.len,
        );
        defer self.gpa.free(expected_ambiguity_order);
        for (expected_ambiguity_order, 0..) |*old_index, index| old_index.* = @intCast(index);
        std.mem.sortUnstable(
            u32,
            expected_ambiguity_order,
            remapped_expected_ambiguity_retirements,
            struct {
                fn lessThan(
                    rows: []const ModuleEnv.ExpectedAmbiguityRetirement,
                    left_index: u32,
                    right_index: u32,
                ) bool {
                    return ModuleEnv.ExpectedAmbiguityRetirement.canonicalLessThan(
                        rows[left_index],
                        rows[right_index],
                    );
                }
            }.lessThan,
        );
        const expected_ambiguity_map = try self.gpa.alloc(
            u32,
            old_expected_ambiguity_retirements.len,
        );
        defer self.gpa.free(expected_ambiguity_map);
        @memset(expected_ambiguity_map, none);
        transaction.replacement_expected_ambiguity_retirements =
            try ModuleEnv.ExpectedAmbiguityRetirement.SafeList.initCapacity(
                self.cir.gpa,
                old_expected_ambiguity_retirements.len,
            );
        const replacement_expected_ambiguity_retirements =
            &transaction.replacement_expected_ambiguity_retirements;
        for (expected_ambiguity_order, 0..) |old_index, new_index| {
            const retirement = remapped_expected_ambiguity_retirements[old_index];
            if (new_index != 0) {
                const previous = replacement_expected_ambiguity_retirements.items.items[new_index - 1];
                if (!ModuleEnv.ExpectedAmbiguityRetirement.canonicalLessThan(previous, retirement) and
                    !ModuleEnv.ExpectedAmbiguityRetirement.canonicalLessThan(retirement, previous))
                {
                    @panic("Expected ambiguity retirements repeated one canonical verdict key");
                }
            }
            expected_ambiguity_map[old_index] = @intCast(new_index);
            _ = try replacement_expected_ambiguity_retirements.append(self.cir.gpa, retirement);
        }

        const retired_plan_membership = try self.gpa.alloc(bool, old_expected_plans.len);
        defer self.gpa.free(retired_plan_membership);
        @memset(retired_plan_membership, false);
        transaction.replacement_expected_retirements =
            try ModuleEnv.ExpectedConsumerRetirement.SafeList.initCapacity(
                self.cir.gpa,
                old_expected_retirements.len,
            );
        const replacement_expected_retirements = &transaction.replacement_expected_retirements;
        transaction.replacement_expected_retirement_failures =
            try ModuleEnv.ExpectedRetirementFailure.SafeList.initCapacity(
                self.cir.gpa,
                old_expected_retirement_failures.len,
            );
        const replacement_expected_retirement_failures =
            &transaction.replacement_expected_retirement_failures;
        transaction.replacement_expected_retired_consumers =
            try ModuleEnv.ExpectedRetiredConsumer.SafeList.initCapacity(
                self.cir.gpa,
                old_expected_retired_consumers.len,
            );
        const replacement_expected_retired_consumers =
            &transaction.replacement_expected_retired_consumers;
        var retired_consumer_scratch: std.ArrayListUnmanaged(ModuleEnv.ExpectedRetiredConsumer) = .empty;
        defer retired_consumer_scratch.deinit(self.gpa);
        var retirement_failure_scratch: std.ArrayListUnmanaged(ModuleEnv.ExpectedRetirementFailure) = .empty;
        defer retirement_failure_scratch.deinit(self.gpa);
        for (expected_retirement_order) |old_retirement_index| {
            var retirement = old_expected_retirements[old_retirement_index];
            if (retirement.decodedRejectionOwnerKind() == .expected_ambiguity_retirement) {
                const old_ambiguity_index = retirement.rejection_owner_index;
                if (old_ambiguity_index >= expected_ambiguity_map.len or
                    expected_ambiguity_map[old_ambiguity_index] == none)
                {
                    @panic("Expected-consumer retirement lost its ambiguity verdict owner");
                }
                retirement.rejection_owner_index = expected_ambiguity_map[old_ambiguity_index];
            }
            retirement_failure_scratch.clearRetainingCapacity();
            try retirement_failure_scratch.ensureTotalCapacity(
                self.gpa,
                retirement.expected_failures_len,
            );
            const old_retirement_causes = old_expected_retirement_failures[retirement.expected_failures_start..][0..retirement.expected_failures_len];
            for (old_retirement_causes) |old_cause| {
                const relocated_failure = expected_failure_map[old_cause.failure_index];
                if (relocated_failure == none) {
                    @panic("Expected-consumer retirement lost one of its failure publications");
                }
                retirement_failure_scratch.appendAssumeCapacity(.{ .failure_index = relocated_failure });
            }
            std.mem.sortUnstable(
                ModuleEnv.ExpectedRetirementFailure,
                retirement_failure_scratch.items,
                replacement_expected_failures.items.items,
                struct {
                    fn lessThan(
                        failures: []const ModuleEnv.ExpectedFailure,
                        left: ModuleEnv.ExpectedRetirementFailure,
                        right: ModuleEnv.ExpectedRetirementFailure,
                    ) bool {
                        return expectedFailureKeyLessThan(
                            failures,
                            left.failure_index,
                            right.failure_index,
                        );
                    }
                }.lessThan,
            );
            for (retirement_failure_scratch.items, 0..) |cause, cause_offset| {
                if (cause_offset != 0 and
                    retirement_failure_scratch.items[cause_offset - 1].failure_index == cause.failure_index)
                {
                    @panic("Expected-consumer retirement duplicated one failure publication");
                }
            }
            retirement.expected_failures_start = if (retirement_failure_scratch.items.len == 0)
                0
            else
                @intCast(replacement_expected_retirement_failures.items.items.len);
            retirement.expected_failures_len = @intCast(retirement_failure_scratch.items.len);
            _ = try replacement_expected_retirement_failures.appendSlice(
                self.cir.gpa,
                retirement_failure_scratch.items,
            );
            retired_consumer_scratch.clearRetainingCapacity();
            try retired_consumer_scratch.ensureTotalCapacity(
                self.gpa,
                retirement.retired_consumers_len,
            );
            const retired_consumers = old_expected_retired_consumers[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
            const record_update_owner_retirement = retired_consumers.len != 0 and
                retired_consumers[0].decodedRetirementOnlyReason() ==
                    .record_update_retired_after_base_checked_error;
            if (record_update_owner_retirement and
                !expectedRetiredRecordUpdateOwnerRangeIsLocallyValid(
                    self.types,
                    self.cir,
                    old_expected_retirements[old_retirement_index],
                    old_retirement_index,
                    retired_consumers,
                ))
            {
                @panic("record-update owner retirement lost its exact plan group before relocation");
            }
            for (retired_consumers) |old_consumer| {
                if (old_consumer.plan_index >= old_expected_plans.len or
                    old_consumer.raw_owner_var >= self.types.len() or
                    old_consumer.raw_consumer_var >= self.types.len())
                {
                    @panic("Expected-retired consumer escaped its exact raw owners");
                }
                const old_plan = old_expected_plans[old_consumer.plan_index];
                const consumer_role = old_consumer.decodedRole() orelse
                    @panic("Expected-retired consumer had an invalid role");
                if (record_update_owner_retirement) {
                    if (old_consumer.decodedRetirementOnlyReason() !=
                        .record_update_retired_after_base_checked_error or
                        old_consumer.decodedReason() != null or
                        old_consumer.owner_node != old_plan.owner_node or
                        old_consumer.site_node != old_plan.site_node or
                        old_consumer.role != old_plan.role or
                        old_consumer.slot != old_plan.slot or
                        old_consumer.raw_owner_var != old_plan.owner_node or
                        old_consumer.raw_consumer_var != old_plan.raw_consumer_var)
                    {
                        @panic("record-update owner retirement changed its exact plan row");
                    }
                } else {
                    const consumer_reason = old_consumer.decodedReason() orelse
                        @panic("Expected-retired consumer had an invalid reason");
                    if (ModuleEnv.ExpectedConsumptionPlan.ownerRelationForReason(consumer_reason) !=
                        .same_node_retirement or
                        !ModuleEnv.ExpectedConsumptionPlan.legalCombination(
                            consumer_role,
                            .checked_error,
                            consumer_reason,
                            .expected_consumer_retirement,
                            false,
                        ) or
                        old_consumer.owner_node != old_plan.owner_node or
                        old_consumer.site_node != old_plan.site_node or
                        old_consumer.role != old_plan.role or
                        old_consumer.slot != old_plan.slot or
                        old_consumer.raw_owner_var != old_plan.owner_node or
                        old_consumer.raw_consumer_var != old_plan.raw_consumer_var)
                    {
                        @panic("Expected-retired consumer disagreed with its exact same-node plan");
                    }
                    switch (old_plan.decodedOutcome() orelse
                        @panic("Expected-retired consumer named a plan with invalid outcome")) {
                        .anchored => {
                            if (old_plan.decodedReason() != null or
                                old_plan.failure_owner.kind != ModuleEnv.CauseOwner.none)
                            {
                                @panic("retired successful Expected plan carried failure fields");
                            }
                        },
                        .related => {
                            if (old_plan.decodedReason() != null or
                                old_plan.failure_owner.kind != ModuleEnv.CauseOwner.none or
                                old_plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                            {
                                @panic("retired successful Expected relation carried failure fields");
                            }
                        },
                        .evidence_free => {
                            if (old_plan.decodedReason() != .parent_evidence_free or
                                old_plan.failure_owner.kind != ModuleEnv.CauseOwner.none)
                            {
                                @panic("retired evidence-free Expected plan carried failure fields");
                            }
                        },
                        .retained => {
                            if (old_plan.decodedReason() != .branch_body_already_expected or
                                old_plan.failure_owner.kind != ModuleEnv.CauseOwner.none or
                                old_plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                            {
                                @panic("retired retained branch plan changed its predecessor relation");
                            }
                        },
                        .not_projected => {
                            if (consumer_reason == .call_retired or
                                consumer_reason == .call_retired_after_operand_checked_error)
                            {
                                if (consumer_role != .call_root or
                                    old_plan.decodedReason() != .call_shape_ready or
                                    old_plan.call_root_plan_index != ModuleEnv.ExpectedConsumptionPlan.none or
                                    old_plan.failure_owner.kind != ModuleEnv.CauseOwner.none or
                                    old_plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                                {
                                    @panic("retired call changed its exact root plan");
                                }
                            } else if (consumer_reason != .aggregate_retired_by_parent_branch_failure or
                                old_plan.decodedReason() != .aggregate_no_expected or
                                old_plan.parent_authority.kind != ModuleEnv.ExpectedMarkerAuthority.none or
                                old_plan.failure_owner.kind != ModuleEnv.CauseOwner.none or
                                old_plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                            {
                                @panic("retired no-Expected aggregate changed its exact benign outcome");
                            }
                        },
                        .checked_error => {
                            if (consumer_reason == .aggregate_retired_after_child_relation) {
                                const plan_reason = old_plan.decodedReason() orelse
                                    @panic("retired aggregate child lost its direct failure reason");
                                if ((plan_reason != .aggregate_child_relation_rejected and
                                    plan_reason != .aggregate_child_relation_suppressed) or
                                    !old_plan.failure_owner.hasCanonicalTags(true) or
                                    old_plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                                {
                                    @panic("retired aggregate child changed its direct failure");
                                }
                            } else if (consumer_reason == .aggregate_retired_by_parent_branch_failure) {
                                @panic("successful parent-retired aggregate contained a failed plan");
                            } else if (consumer_reason == .branch_retired_after_failure) {
                                switch (consumer_role) {
                                    .branch_contribution => {
                                        const plan_reason = old_plan.decodedReason() orelse
                                            @panic("retired branch contribution lost its direct failure reason");
                                        if ((plan_reason != .branch_body_error_short_circuit and
                                            plan_reason != .branch_expected_compatibility_rejected and
                                            plan_reason != .branch_accumulator_fold_rejected) or
                                            !old_plan.failure_owner.hasCanonicalTags(true) or
                                            old_plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                                        {
                                            @panic("retired branch contribution changed its direct failure");
                                        }
                                    },
                                    .branch_final => {
                                        if (old_plan.decodedReason() != .branch_final_relation_rejected or
                                            old_plan.failure_owner.decodedExpectedConsumerRetirement() == null or
                                            old_plan.failure_owner.payload.expected_consumer_retirement.index !=
                                                old_retirement_index or
                                            old_plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                                        {
                                            @panic("retired branch final changed its same-node rejection");
                                        }
                                    },
                                    .branch_seed,
                                    .aggregate_owner,
                                    .list_element,
                                    .tuple_element,
                                    .record_field,
                                    .tag_payload,
                                    .record_update_base,
                                    .record_update_field,
                                    .nominal_decl,
                                    .nominal_backing,
                                    .call_root,
                                    .call_argument,
                                    .default_field,
                                    .lambda_return,
                                    => @panic("retired branch failure occupied an invalid role"),
                                }
                            } else if (old_plan.decodedReason() != consumer_reason or
                                old_plan.failure_owner.decodedExpectedConsumerRetirement() == null or
                                old_plan.failure_owner.payload.expected_consumer_retirement.index != old_retirement_index)
                            {
                                @panic("failed Expected plan disagreed with its same-node retirement");
                            }
                        },
                        .source_root_copy,
                        .source_root_copy_checked_error,
                        => @panic("record-update source-root plan entered an undeclared retirement"),
                        .producer_root => if ((consumer_reason != .call_retired and
                            consumer_reason != .call_retired_after_operand_checked_error) or
                            consumer_role != .call_argument or
                            old_plan.decodedReason() != null or
                            old_plan.call_root_plan_index == ModuleEnv.ExpectedConsumptionPlan.none or
                            old_plan.failure_owner.kind != ModuleEnv.CauseOwner.none or
                            old_plan.failure_cause_plan_index != ModuleEnv.ExpectedConsumptionPlan.none)
                        {
                            @panic("retired call changed an exact argument producer root");
                        },
                        .reserved => @panic("retirement named an Expected plan without an established consumer"),
                    }
                }
                if (retired_plan_membership[old_consumer.plan_index]) {
                    @panic("one Expected-consumption plan appeared in multiple retirement rows");
                }
                retired_plan_membership[old_consumer.plan_index] = true;
                var consumer = old_consumer;
                consumer.plan_index = expected_plan_map[old_consumer.plan_index];
                if (consumer.plan_index == none) {
                    @panic("Expected-retired consumer lost its exact plan");
                }
                retired_consumer_scratch.appendAssumeCapacity(consumer);
            }
            std.mem.sortUnstable(
                ModuleEnv.ExpectedRetiredConsumer,
                retired_consumer_scratch.items,
                {},
                expectedRetiredConsumerLessThan,
            );
            if (retired_consumer_scratch.items.len > 1) {
                for (
                    retired_consumer_scratch.items[1..],
                    retired_consumer_scratch.items[0 .. retired_consumer_scratch.items.len - 1],
                ) |current, previous| {
                    if (std.meta.eql(current, previous)) {
                        @panic("Expected-consumer retirement repeated one canonical consumer row");
                    }
                }
            }
            retirement.retired_consumers_start = if (retired_consumer_scratch.items.len == 0)
                0
            else
                @intCast(replacement_expected_retired_consumers.items.items.len);
            retirement.retired_consumers_len = @intCast(retired_consumer_scratch.items.len);
            _ = try replacement_expected_retired_consumers.appendSlice(
                self.cir.gpa,
                retired_consumer_scratch.items,
            );
            _ = try replacement_expected_retirements.append(self.cir.gpa, retirement);
        }
        for (old_expected_plans, 0..) |plan, old_plan_index| {
            const reason = plan.decodedReason();
            const is_same_node_retirement = if (reason) |present_reason|
                ModuleEnv.ExpectedConsumptionPlan.ownerRelationForReason(present_reason) ==
                    .same_node_retirement
            else
                false;
            if (is_same_node_retirement and !retired_plan_membership[old_plan_index]) {
                @panic("Expected-consumer retirement membership was not bijective with its plans");
            }
        }
    }

    fn relocateForLoopOutcome(
        transaction: *Transaction,
        old_plan_index: u32,
        plan: ModuleEnv.ForLoopDispatchPlan,
        slot: ModuleEnv.DispatchSettlementSource.ForLoopSlot,
        selected_anchor_map: []const u32,
        relocations: []const CheckedBoundaryConstraintRelocation,
    ) ModuleEnv.ForLoopDispatchOutcome {
        const self = transaction.checker;
        const outcome, const expected_fn, const expected_receiver = switch (slot) {
            .iter => .{ plan.iter_outcome, plan.iter_fn_var, plan.iterable_idx },
            .next => .{ plan.next_outcome, plan.next_fn_var, plan.iterator_var },
        };
        if (!outcome.hasCanonicalTags() or expected_fn >= self.types.len() or
            expected_receiver >= self.types.len())
        {
            @panic("for-loop dispatch outcome escaped its producer vars");
        }

        var matching_source_count: usize = 0;
        var matching_source_anchor: u32 = none;
        for (transaction.input.settlement_sources) |source| {
            if (source.decodedKind() != .for_loop_dispatch) continue;
            const row = source.payload.for_loop_dispatch;
            if (row.plan_index != old_plan_index or row.slot != @intFromEnum(slot)) continue;
            matching_source_count += 1;
            matching_source_anchor = row.anchor_index;
        }

        return switch (outcome.decodedKind() orelse
            @panic("for-loop dispatch outcome had an invalid kind")) {
            .live_constraint => blk: {
                const old_constraint_index = outcome.constraintIndex().?;
                const old_anchor_index = outcome.anchorIndex().?;
                if (old_constraint_index >= transaction.input.constraints.len or
                    old_anchor_index >= transaction.input.selected_anchors.len or
                    old_anchor_index >= selected_anchor_map.len or
                    selected_anchor_map[old_anchor_index] == none or
                    matching_source_count != 1 or matching_source_anchor != old_anchor_index)
                {
                    @panic("live for-loop slot lost its exact source/anchor occurrence");
                }
                const constraint = transaction.input.constraints[old_constraint_index];
                const anchor = transaction.input.selected_anchors[old_anchor_index];
                if (anchor.decodedKind() != .for_loop_dispatch or
                    anchor.constraint_index != old_constraint_index or
                    anchor.receiver_var != expected_receiver or
                    anchor.node != plan.node_idx or anchor.slot != @intFromEnum(slot) or
                    @intFromEnum(constraint.fn_var) != expected_fn)
                {
                    @panic("live for-loop slot disagreed with its producer snapshot");
                }
                break :blk ModuleEnv.ForLoopDispatchOutcome.liveConstraint(
                    checkedBoundaryRelocatedConstraintIndex(relocations, old_constraint_index),
                    selected_anchor_map[old_anchor_index],
                );
            },
            .rejected_before_constraint => blk: {
                const rejection_index = outcome.rejectionIndex().?;
                if (matching_source_count != 0 or
                    rejection_index >= self.cir.rejected_static_dispatches.items.items.len or
                    self.cir.rejected_static_dispatches.items.items[rejection_index].constraint_fn_var != expected_fn or
                    !self.types.varStaticDispatchRejected(@enumFromInt(expected_fn)))
                {
                    @panic("rejected for-loop slot lost its exact rejection occurrence");
                }
                break :blk outcome;
            },
        };
    }

    fn rebuildDispatchEvidenceAndMoves(transaction: *Transaction) Allocator.Error!void {
        const self = transaction.checker;
        const old_constraints = transaction.input.constraints;
        const old_bases = transaction.input.bases;
        const old_steps = transaction.input.steps;
        const old_default_decisions = transaction.input.default_decisions;
        const old_default_contributors = transaction.input.default_contributors;
        const old_selected_decisions = transaction.input.selected_decisions;
        const old_selected_anchors = transaction.input.selected_anchors;
        const old_settlement_sources = transaction.input.settlement_sources;
        const old_for_loop_plans = transaction.input.for_loop_plans;
        const old_selected_moves = transaction.input.selected_moves;
        const old_selected_decision_moves = transaction.input.selected_decision_moves;
        const old_moves = transaction.input.moves;
        const old_move_offsets = transaction.input.move_offsets;
        const referenced_constraints = transaction.referenced_constraints.?;
        const referenced_default_decisions = transaction.referenced_default_decisions.?;
        const referenced_moves = transaction.referenced_moves.?;
        const referenced_selected_anchors = transaction.referenced_selected_anchors.?;
        const referenced_selected_moves = transaction.referenced_selected_moves.?;
        const referenced_evidence_nodes = &transaction.referenced_evidence_nodes;
        const relocations = transaction.relocations.?;
        const marker_offset_maps = &transaction.marker_offset_maps;
        const step_map = transaction.step_map.?;
        const where_source_map = transaction.where_source_map.?;
        const pair_relocations = transaction.pair_relocations.?;
        const constraint_pair_relocations = transaction.constraint_pair_relocations.?;
        const occurrence_relocations = transaction.occurrence_relocations.?;
        const copied_literal_event_map = transaction.copied_literal_event_map.?;
        const retained_default_decision_count = transaction.retained_default_decision_count;
        const retained_default_contributor_count = transaction.retained_default_contributor_count;
        const retained_move_count = transaction.retained_move_count;
        const retained_selected_anchor_count = transaction.retained_selected_anchor_count;
        const retained_selected_move_count = transaction.retained_selected_move_count;
        const replacement_constraints = &transaction.replacement_constraints;
        const replacement_bases = &transaction.replacement_bases;

        transaction.replacement_default_decisions = try ModuleEnv.DefaultDecision.SafeList.initCapacity(
            self.cir.gpa,
            retained_default_decision_count,
        );
        const replacement_default_decisions = &transaction.replacement_default_decisions;
        transaction.replacement_default_contributors = try ModuleEnv.DefaultDecisionContributor.SafeList.initCapacity(
            self.cir.gpa,
            retained_default_contributor_count,
        );
        const replacement_default_contributors = &transaction.replacement_default_contributors;
        for (old_default_decisions, 0..) |old_decision, old_decision_index| {
            if (!referenced_default_decisions[old_decision_index]) continue;
            var decision = old_decision;
            const new_constraints_start = checkedBoundaryRelocatedConstraintIndex(
                relocations,
                old_decision.constraints_start,
            );
            for (0..old_decision.constraints_len) |offset| {
                const mapped = checkedBoundaryRelocatedConstraintIndex(
                    relocations,
                    old_decision.constraints_start + @as(u32, @intCast(offset)),
                );
                if (mapped != new_constraints_start + @as(u32, @intCast(offset))) {
                    @panic("default decision constraint range did not remain contiguous");
                }
            }
            decision.constraints_start = new_constraints_start;
            decision.contributors_start = @intCast(replacement_default_contributors.items.items.len);
            for (old_default_contributors[old_decision.contributors_start..][0..old_decision.contributors_len]) |old_contributor| {
                var contributor = old_contributor;
                if (old_contributor.decodedDriverKind().? == .instantiation_copy) {
                    const old_driver_step = old_steps[old_contributor.driver_copy_step];
                    const relocated_pair = pair_relocations[
                        old_driver_step.pairs_start + old_contributor.driver_pair_offset
                    ];
                    if (relocated_pair == none) {
                        @panic("default decision lost an exact instantiation contributor pair");
                    }
                    contributor.driver_copy_step = checkedBoundaryRelocatedCopyStep(
                        step_map,
                        old_contributor.driver_copy_step,
                    );
                    contributor.driver_pair_offset = relocated_pair;
                }
                _ = try replacement_default_contributors.append(self.cir.gpa, contributor);
            }
            _ = try replacement_default_decisions.append(self.cir.gpa, decision);
        }

        const selected_anchor_map = try self.gpa.alloc(u32, old_selected_anchors.len);
        defer self.gpa.free(selected_anchor_map);
        @memset(selected_anchor_map, none);
        transaction.replacement_selected_anchors = try ModuleEnv.SelectedReceiverAnchor.SafeList.initCapacity(
            self.cir.gpa,
            retained_selected_anchor_count,
        );
        const replacement_selected_anchors = &transaction.replacement_selected_anchors;
        const RelocatedSelectedAnchor = struct {
            old_index: u32,
            anchor: ModuleEnv.SelectedReceiverAnchor,
        };
        var relocated_selected_anchors: std.ArrayListUnmanaged(RelocatedSelectedAnchor) = .empty;
        defer relocated_selected_anchors.deinit(self.gpa);
        try relocated_selected_anchors.ensureTotalCapacity(self.gpa, retained_selected_anchor_count);
        for (old_selected_anchors, 0..) |old_anchor, old_anchor_index| {
            if (!referenced_selected_anchors[old_anchor_index]) continue;
            var anchor = old_anchor;
            anchor.constraint_index = checkedBoundaryRelocatedConstraintIndex(
                relocations,
                old_anchor.constraint_index,
            );
            if (old_anchor.decodedKind().? == .copied_constraint) {
                const old_step = old_steps[old_anchor.copy_step];
                const relocated_occurrence = occurrence_relocations[
                    old_step.occurrences_start + old_anchor.receiver_occurrence_offset
                ];
                if (relocated_occurrence == none) {
                    @panic("selected receiver anchor lost its exact copied occurrence");
                }
                anchor.copy_step = checkedBoundaryRelocatedCopyStep(step_map, old_anchor.copy_step);
                anchor.receiver_occurrence_offset = relocated_occurrence;

                // The copied source is the composite owner of the function
                // pair. Binding-codec anchors cannot interpret that pair in
                // their receiver step, so relocate through the source's exact
                // function component instead.
                var copied_source: ?ModuleEnv.DispatchSettlementSource.CopiedConstraint = null;
                for (old_settlement_sources) |source| {
                    if (source.decodedKind() != .copied_constraint or
                        source.payload.copied_constraint.anchor_index != old_anchor_index)
                    {
                        continue;
                    }
                    if (copied_source != null) {
                        @panic("selected copied anchor had duplicate source producers during relocation");
                    }
                    copied_source = source.payload.copied_constraint;
                }
                const source = copied_source orelse
                    @panic("selected copied anchor lost its source producer during relocation");
                const function_ref = source.function_component_ref;
                if (source.receiver_component_ref.copy_step_index != old_anchor.copy_step or
                    source.receiver_component_ref.occurrence_offset != old_anchor.receiver_occurrence_offset or
                    function_ref.constraint_pair_offset != old_anchor.constraint_pair_offset or
                    function_ref.copy_step_index >= old_steps.len or
                    function_ref.constraint_pair_offset >= old_steps[function_ref.copy_step_index].constraint_pairs_len)
                {
                    @panic("selected copied anchor disagreed with its composite source coordinates");
                }
                anchor.constraint_pair_offset = constraint_pair_relocations[
                    old_steps[function_ref.copy_step_index].constraint_pairs_start +
                        function_ref.constraint_pair_offset
                ];
                if (anchor.constraint_pair_offset == none) {
                    @panic("selected copied anchor lost its function-owned constraint pair");
                }
            }
            relocated_selected_anchors.appendAssumeCapacity(.{
                .old_index = @intCast(old_anchor_index),
                .anchor = anchor,
            });
        }
        std.mem.sortUnstable(RelocatedSelectedAnchor, relocated_selected_anchors.items, {}, struct {
            fn lessThan(_: void, left: RelocatedSelectedAnchor, right: RelocatedSelectedAnchor) bool {
                return selectedReceiverAnchorCanonicalLessThan({}, left.anchor, right.anchor);
            }
        }.lessThan);
        for (relocated_selected_anchors.items, 0..) |relocated, new_anchor_index| {
            if (new_anchor_index != 0 and
                !selectedReceiverAnchorCanonicalLessThan(
                    {},
                    relocated_selected_anchors.items[new_anchor_index - 1].anchor,
                    relocated.anchor,
                ))
            {
                @panic("selected receiver anchors repeated one canonical producer coordinate");
            }
            selected_anchor_map[relocated.old_index] = @intCast(new_anchor_index);
            _ = try replacement_selected_anchors.append(self.cir.gpa, relocated.anchor);
        }

        // For-loop plans are durable producer topology, not mutable CIR
        // annotations. Canonicalize by loop owner and remap both live slot
        // outcomes before rewriting any source foreign key.
        const for_loop_plan_order = try self.gpa.alloc(u32, old_for_loop_plans.len);
        defer self.gpa.free(for_loop_plan_order);
        const for_loop_plan_map = try self.gpa.alloc(u32, old_for_loop_plans.len);
        defer self.gpa.free(for_loop_plan_map);
        @memset(for_loop_plan_map, none);
        for (for_loop_plan_order, 0..) |*old_index, index| old_index.* = @intCast(index);
        std.mem.sortUnstable(
            u32,
            for_loop_plan_order,
            old_for_loop_plans,
            struct {
                fn lessThan(
                    plans: []const ModuleEnv.ForLoopDispatchPlan,
                    lhs_index: u32,
                    rhs_index: u32,
                ) bool {
                    const lhs = plans[lhs_index];
                    const rhs = plans[rhs_index];
                    if (lhs.node_idx != rhs.node_idx) return lhs.node_idx < rhs.node_idx;
                    return lhs_index < rhs_index;
                }
            }.lessThan,
        );
        transaction.replacement_for_loop_plans =
            try ModuleEnv.ForLoopDispatchPlan.SafeList.initCapacity(
                self.cir.gpa,
                old_for_loop_plans.len,
            );
        const replacement_for_loop_plans = &transaction.replacement_for_loop_plans;
        for (for_loop_plan_order, 0..) |old_plan_index, new_plan_index| {
            var plan = old_for_loop_plans[old_plan_index];
            if (plan.node_idx >= self.cir.store.nodes.len() or
                plan.pattern_idx >= self.cir.store.nodes.len() or
                plan.iterable_idx >= self.cir.store.nodes.len() or
                plan.iterator_var >= self.types.len() or plan.step_var >= self.types.len() or
                plan.iter_fn_var >= self.types.len() or plan.next_fn_var >= self.types.len() or
                (new_plan_index != 0 and
                    old_for_loop_plans[for_loop_plan_order[new_plan_index - 1]].node_idx >= plan.node_idx))
            {
                @panic("for-loop dispatch plans were not a unique finite owner set");
            }
            plan.iter_outcome = transaction.relocateForLoopOutcome(
                old_plan_index,
                plan,
                .iter,
                selected_anchor_map,
                relocations,
            );
            plan.next_outcome = transaction.relocateForLoopOutcome(
                old_plan_index,
                plan,
                .next,
                selected_anchor_map,
                relocations,
            );
            for_loop_plan_map[old_plan_index] = @intCast(new_plan_index);
            _ = try replacement_for_loop_plans.append(self.cir.gpa, plan);
        }

        transaction.replacement_settlement_sources =
            try ModuleEnv.DispatchSettlementSource.SafeList.initCapacity(
                self.cir.gpa,
                transaction.input.settlement_sources.len,
            );
        const replacement_settlement_sources = &transaction.replacement_settlement_sources;
        for (transaction.input.settlement_sources) |old_source| {
            var source = old_source;
            if (source.primaryAnchorIndex()) |old_anchor_index| {
                if (old_anchor_index >= selected_anchor_map.len or
                    selected_anchor_map[old_anchor_index] == none)
                {
                    @panic("dispatch-settlement source lost its selected-receiver anchor");
                }
                const new_anchor_index = selected_anchor_map[old_anchor_index];
                switch (source.decodedKind() orelse
                    @panic("dispatch-settlement source had an invalid kind while relocating")) {
                    .dispatch_expr => source.payload.dispatch_expr.anchor_index = new_anchor_index,
                    .literal_conversion => source.payload.literal_conversion.anchor_index = new_anchor_index,
                    .interpolation => source.payload.interpolation.anchor_index = new_anchor_index,
                    .pattern_literal_equality => source.payload.pattern_literal_equality.anchor_index = new_anchor_index,
                    .negated_equality_not => {
                        source.payload.negated_equality_not.anchor_index = new_anchor_index;
                        source.payload.negated_equality_not.equality_constraint_index =
                            checkedBoundaryRelocatedConstraintIndex(
                                relocations,
                                source.payload.negated_equality_not.equality_constraint_index,
                            );
                    },
                    .for_loop_dispatch => {
                        source.payload.for_loop_dispatch.anchor_index = new_anchor_index;
                        const old_plan_index = source.payload.for_loop_dispatch.plan_index;
                        if (old_plan_index >= for_loop_plan_map.len or
                            for_loop_plan_map[old_plan_index] == none)
                        {
                            @panic("for-loop settlement source lost its exact owner plan");
                        }
                        source.payload.for_loop_dispatch.plan_index = for_loop_plan_map[old_plan_index];
                    },
                    .copied_constraint => {
                        source.payload.copied_constraint.anchor_index = new_anchor_index;
                        const receiver_ref = &source.payload.copied_constraint.receiver_component_ref;
                        const function_ref = &source.payload.copied_constraint.function_component_ref;
                        const refs = .{ receiver_ref, function_ref };
                        inline for (refs) |component_ref| {
                            const old_step_index = component_ref.copy_step_index;
                            if (old_step_index >= old_steps.len or
                                component_ref.occurrence_offset >= old_steps[old_step_index].occurrences_len)
                            {
                                @panic("copied dispatch-settlement source escaped its copy occurrence");
                            }
                            const relocated_occurrence = occurrence_relocations[
                                old_steps[old_step_index].occurrences_start + component_ref.occurrence_offset
                            ];
                            if (relocated_occurrence == none) {
                                @panic("copied dispatch-settlement source lost its copy occurrence");
                            }
                            component_ref.copy_step_index = checkedBoundaryRelocatedCopyStep(
                                step_map,
                                old_step_index,
                            );
                            component_ref.occurrence_offset = relocated_occurrence;
                            const component_kind = component_ref.decodedKind() orelse
                                @panic("copied dispatch-settlement component had an invalid kind");
                            switch (component_kind) {
                                .binding_codec_receiver, .binding_codec_function => {
                                    component_ref.binding_root_step = checkedBoundaryRelocatedCopyStep(
                                        step_map,
                                        component_ref.binding_root_step,
                                    );
                                },
                                .root_graph, .scheme_requirement => {},
                            }
                        }
                        const old_function_step = old_steps[old_source.payload.copied_constraint.function_component_ref.copy_step_index];
                        if (old_source.payload.copied_constraint.function_component_ref.constraint_pair_offset >=
                            old_function_step.constraint_pairs_len)
                        {
                            @panic("copied dispatch-settlement function pair escaped its owner step");
                        }
                        function_ref.constraint_pair_offset = constraint_pair_relocations[
                            old_function_step.constraint_pairs_start +
                                old_source.payload.copied_constraint.function_component_ref.constraint_pair_offset
                        ];
                        if (function_ref.constraint_pair_offset == none) {
                            @panic("copied dispatch-settlement source lost its function-owned pair");
                        }
                        if (receiver_ref.constraint_pair_offset != 0) {
                            @panic("copied dispatch-settlement receiver activated its function-only pair word");
                        }
                    },
                    .where_requirement => unreachable,
                }
            }
            if (source.decodedKind() == .where_requirement) {
                const old_source_index = source.payload.where_requirement.source_index;
                if (old_source_index >= where_source_map.len or
                    where_source_map[old_source_index] == none)
                {
                    @panic("where settlement source lost its exact source row");
                }
                source.payload.where_requirement.source_index = where_source_map[old_source_index];
            }
            _ = try replacement_settlement_sources.append(self.cir.gpa, source);
        }

        const selected_move_map = try self.gpa.alloc(u32, old_selected_moves.len);
        defer self.gpa.free(selected_move_map);
        @memset(selected_move_map, none);
        transaction.replacement_selected_moves =
            try ModuleEnv.ConstraintEvidenceMove.SafeList.initCapacity(
                self.cir.gpa,
                retained_selected_move_count,
            );
        const replacement_selected_moves = &transaction.replacement_selected_moves;
        for (old_selected_moves, 0..) |old_move, old_move_index| {
            if (!referenced_selected_moves[old_move_index]) continue;
            const relocated_handle: types_mod.ConstraintEvidenceHandle = switch (old_move.handle.decodedKind() orelse
                @panic("constraint-evidence movement had an invalid handle kind")) {
                .selected_receiver_anchor => blk: {
                    const relocated_anchor = selected_anchor_map[old_move.handle.index];
                    if (relocated_anchor == none) {
                        @panic("selected receiver movement lost its provenance anchor");
                    }
                    break :blk .{
                        .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.selected_receiver_anchor),
                        .index = relocated_anchor,
                    };
                },
                .where_requirement_source => blk: {
                    const relocated_source = where_source_map[old_move.handle.index];
                    if (relocated_source == none) {
                        @panic("where-source movement lost its provenance source");
                    }
                    break :blk .{
                        .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.where_requirement_source),
                        .index = relocated_source,
                    };
                },
                .copied_literal_event => blk: {
                    if (old_move.handle.index >= copied_literal_event_map.len or
                        copied_literal_event_map[old_move.handle.index] == none)
                    {
                        @panic("copied-literal evidence movement lost its producer event");
                    }
                    break :blk .{
                        .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.copied_literal_event),
                        .index = copied_literal_event_map[old_move.handle.index],
                    };
                },
            };
            selected_move_map[old_move_index] = @intCast(
                replacement_selected_moves.items.items.len,
            );
            _ = try replacement_selected_moves.append(self.cir.gpa, .{
                .handle = relocated_handle,
                .source_constraint_index = checkedBoundaryRelocatedConstraintIndex(
                    relocations,
                    old_move.source_constraint_index,
                ),
                .destination_constraint_index = checkedBoundaryRelocatedConstraintIndex(
                    relocations,
                    old_move.destination_constraint_index,
                ),
            });
        }

        transaction.replacement_evidence_handles = try MkSafeList(types_mod.ConstraintEvidenceHandle).initCapacity(
            self.types.gpa,
            self.types.constraint_evidence_handles.items.items.len,
        );
        const replacement_evidence_handles = &transaction.replacement_evidence_handles;
        var mapped_constraint_handles: std.ArrayListUnmanaged(types_mod.ConstraintEvidenceHandle) = .empty;
        defer mapped_constraint_handles.deinit(self.gpa);
        for (old_constraints, 0..) |old_constraint, old_constraint_index| {
            if (!referenced_constraints[old_constraint_index]) continue;
            mapped_constraint_handles.clearRetainingCapacity();
            const old_handles = self.types.sliceConstraintEvidenceHandles(
                old_constraint.constraint_evidence,
            );
            try mapped_constraint_handles.ensureTotalCapacity(self.gpa, old_handles.len);
            for (old_handles) |old_handle| {
                if (!referenced_evidence_nodes.contains(.{
                    .handle = old_handle,
                    .constraint_index = @intCast(old_constraint_index),
                })) continue;
                const relocated_handle: types_mod.ConstraintEvidenceHandle = switch (old_handle.decodedKind() orelse
                    @panic("retained constraint evidence had an invalid handle kind")) {
                    .selected_receiver_anchor => blk: {
                        const relocated_anchor = selected_anchor_map[old_handle.index];
                        if (relocated_anchor == none) {
                            @panic("selected constraint node lost its provenance anchor");
                        }
                        break :blk .{
                            .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.selected_receiver_anchor),
                            .index = relocated_anchor,
                        };
                    },
                    .where_requirement_source => blk: {
                        const relocated_source = where_source_map[old_handle.index];
                        if (relocated_source == none) {
                            @panic("where constraint node lost its provenance source");
                        }
                        break :blk .{
                            .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.where_requirement_source),
                            .index = relocated_source,
                        };
                    },
                    .copied_literal_event => blk: {
                        if (old_handle.index >= copied_literal_event_map.len or
                            copied_literal_event_map[old_handle.index] == none)
                        {
                            @panic("copied-literal constraint evidence lost its producer event");
                        }
                        break :blk .{
                            .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.copied_literal_event),
                            .index = copied_literal_event_map[old_handle.index],
                        };
                    },
                };
                mapped_constraint_handles.appendAssumeCapacity(relocated_handle);
            }
            std.mem.sortUnstable(
                types_mod.ConstraintEvidenceHandle,
                mapped_constraint_handles.items,
                {},
                types_mod.ConstraintEvidenceHandle.canonicalLessThan,
            );
            if (mapped_constraint_handles.items.len > 1) {
                for (
                    mapped_constraint_handles.items[1..],
                    mapped_constraint_handles.items[0 .. mapped_constraint_handles.items.len - 1],
                ) |current, previous| {
                    if (types_mod.ConstraintEvidenceHandle.eql(previous, current)) {
                        @panic("terminal constraint evidence map coalesced two producer handles");
                    }
                }
            }
            const handle_start: u32 = @intCast(
                replacement_evidence_handles.items.items.len,
            );
            _ = try replacement_evidence_handles.appendSlice(
                self.types.gpa,
                mapped_constraint_handles.items,
            );
            replacement_constraints.items.items[
                relocations[old_constraint_index].new_constraint_index
            ].constraint_evidence = if (mapped_constraint_handles.items.len == 0)
                .none
            else
                .{
                    .start = handle_start,
                    .len = @intCast(mapped_constraint_handles.items.len),
                };
        }

        transaction.replacement_selected_decisions = try ModuleEnv.SelectedMethodDecision.SafeList.initCapacity(
            self.cir.gpa,
            old_selected_decisions.len,
        );
        const replacement_selected_decisions = &transaction.replacement_selected_decisions;
        transaction.replacement_selected_decision_moves =
            try ModuleEnv.SelectedMethodDecisionMove.SafeList.initCapacity(
                self.cir.gpa,
                old_selected_decision_moves.len,
            );
        const replacement_selected_decision_moves = &transaction.replacement_selected_decision_moves;
        for (old_selected_decisions) |old_decision| {
            var decision = old_decision;
            decision.constraint_index = checkedBoundaryRelocatedConstraintIndex(
                relocations,
                old_decision.constraint_index,
            );
            decision.root_copy_step = checkedBoundaryRelocatedCopyStep(
                step_map,
                old_decision.root_copy_step,
            );
            decision.use_copy_step = checkedBoundaryRelocatedCopyStep(
                step_map,
                old_decision.use_copy_step,
            );
            const terminal_provenance = replacement_constraints.items.items[
                decision.constraint_index
            ].constraint_evidence;
            if (terminal_provenance.len != old_decision.constraint_evidence_len) {
                @panic("selected decision lost one of its terminal provenance handles");
            }
            decision.constraint_evidence_start = terminal_provenance.start;
            decision.constraint_evidence_len = terminal_provenance.len;
            decision.constraint_moves_start = @intCast(
                replacement_selected_decision_moves.items.items.len,
            );
            const old_decision_moves = old_selected_decision_moves[old_decision.constraint_moves_start..][0..old_decision.constraint_moves_len];
            for (old_decision_moves) |old_decision_move| {
                const relocated_anchor = selected_anchor_map[old_decision_move.receiver_anchor_index];
                const relocated_move = selected_move_map[old_decision_move.constraint_move_index];
                if (relocated_anchor == none or relocated_move == none) {
                    @panic("selected decision lost its exact movement subgraph");
                }
                _ = try replacement_selected_decision_moves.append(self.cir.gpa, .{
                    .receiver_anchor_index = relocated_anchor,
                    .constraint_move_index = relocated_move,
                });
            }
            decision.constraint_moves_len = @intCast(
                replacement_selected_decision_moves.items.items.len -
                    @as(usize, decision.constraint_moves_start),
            );
            _ = try replacement_selected_decisions.append(self.cir.gpa, decision);
        }

        for (old_constraints, 0..) |constraint, raw_constraint_index| {
            if (!referenced_constraints[raw_constraint_index]) continue;
            const relocation = relocations[raw_constraint_index];
            const basis_len: usize = constraint.where_method_marker_bases.len();
            const basis_start: usize = if (basis_len == 0)
                0
            else
                @intFromEnum(constraint.where_method_marker_bases.start);
            var canonical_bases: std.ArrayListUnmanaged(types_mod.WhereMethodMarkerBasis) = .empty;
            defer canonical_bases.deinit(self.gpa);
            try canonical_bases.ensureTotalCapacity(self.gpa, basis_len);
            for (old_bases[basis_start..][0..basis_len]) |old_basis| {
                var basis = old_basis;
                basis.marker_offset = checkedBoundaryRelocatedMarkerOffset(
                    relocations,
                    marker_offset_maps.items,
                    @intCast(raw_constraint_index),
                    old_basis.marker_offset,
                );
                const kind = old_steps[old_basis.copy_step].decodedKind().?;
                basis.copy_step = checkedBoundaryRelocatedCopyStep(step_map, old_basis.copy_step);
                if (kind.sourceNamespace() == .local) {
                    basis.source_contract_offset = checkedBoundaryRelocatedMarkerOffset(
                        relocations,
                        marker_offset_maps.items,
                        old_basis.source_constraint_index,
                        old_basis.source_contract_offset,
                    );
                    basis.source_constraint_index = checkedBoundaryRelocatedConstraintIndex(
                        relocations,
                        old_basis.source_constraint_index,
                    );
                }
                canonical_bases.appendAssumeCapacity(basis);
            }
            std.mem.sortUnstable(
                types_mod.WhereMethodMarkerBasis,
                canonical_bases.items,
                {},
                checkedBoundaryBasisLessThan,
            );
            var basis_write: usize = 0;
            for (canonical_bases.items) |basis| {
                if (basis_write != 0 and checkedBoundaryBasesEqual(
                    canonical_bases.items[basis_write - 1],
                    basis,
                )) {
                    continue;
                }
                canonical_bases.items[basis_write] = basis;
                basis_write += 1;
            }
            canonical_bases.items.len = basis_write;
            const new_basis_range = try replacement_bases.appendSlice(self.types.gpa, canonical_bases.items);
            replacement_constraints.items.items[relocation.new_constraint_index].where_method_marker_bases =
                new_basis_range;
        }

        var pending_moves: std.ArrayListUnmanaged(PendingCanonicalConstraintMove) = .empty;
        defer pending_moves.deinit(self.gpa);
        try pending_moves.ensureTotalCapacity(self.gpa, retained_move_count);
        var temporary_move_offsets: std.ArrayListUnmanaged(u32) = .empty;
        defer temporary_move_offsets.deinit(self.gpa);
        for (old_moves, referenced_moves) |old_move, is_referenced| {
            if (!is_referenced) continue;
            const source_relocation = relocations[old_move.source_constraint_index];
            const destination_relocation = relocations[old_move.destination_constraint_index];
            const temporary_start: u32 = @intCast(temporary_move_offsets.items.len);
            try temporary_move_offsets.ensureUnusedCapacity(self.gpa, source_relocation.new_marker_len);
            for (0..source_relocation.new_marker_len) |_| {
                temporary_move_offsets.appendAssumeCapacity(none);
            }
            const old_offsets = old_move_offsets[old_move.offsets_start..][0..old_move.offsets_len];
            for (old_offsets, 0..) |old_destination_offset, old_source_offset| {
                const new_source_offset = checkedBoundaryRelocatedMarkerOffset(
                    relocations,
                    marker_offset_maps.items,
                    old_move.source_constraint_index,
                    @intCast(old_source_offset),
                );
                const new_destination_offset = checkedBoundaryRelocatedMarkerOffset(
                    relocations,
                    marker_offset_maps.items,
                    old_move.destination_constraint_index,
                    old_destination_offset,
                );
                const output = &temporary_move_offsets.items[temporary_start + new_source_offset];
                if (output.* != none and output.* != new_destination_offset) {
                    @panic("constraint movement coalesced one source marker into two destinations");
                }
                output.* = new_destination_offset;
            }
            for (temporary_move_offsets.items[temporary_start..][0..source_relocation.new_marker_len]) |offset| {
                if (offset == none) {
                    @panic("constraint movement omitted a canonical source marker");
                }
            }
            pending_moves.appendAssumeCapacity(.{
                .row = .{
                    .source_constraint_index = source_relocation.new_constraint_index,
                    .destination_constraint_index = destination_relocation.new_constraint_index,
                    .offsets_start = 0,
                    .offsets_len = source_relocation.new_marker_len,
                },
                .temporary_offsets_start = temporary_start,
            });
        }
        std.mem.sortUnstable(
            PendingCanonicalConstraintMove,
            pending_moves.items,
            {},
            canonicalConstraintMoveLessThan,
        );
        transaction.replacement_moves = try ModuleEnv.WhereMarkerConstraintMove.SafeList.initCapacity(
            self.cir.gpa,
            pending_moves.items.len,
        );
        const replacement_moves = &transaction.replacement_moves;
        transaction.replacement_move_offsets = try MkSafeList(u32).initCapacity(
            self.cir.gpa,
            temporary_move_offsets.items.len,
        );
        const replacement_move_offsets = &transaction.replacement_move_offsets;
        for (pending_moves.items, 0..) |pending_move, move_index| {
            if (move_index != 0) {
                const previous = pending_moves.items[move_index - 1];
                if (previous.row.source_constraint_index == pending_move.row.source_constraint_index and
                    previous.row.destination_constraint_index == pending_move.row.destination_constraint_index)
                {
                    @panic("checked-boundary constraint movement was published more than once");
                }
            }
            var row = pending_move.row;
            row.offsets_start = @intCast(replacement_move_offsets.items.items.len);
            const offsets = temporary_move_offsets.items[pending_move.temporary_offsets_start..][0..row.offsets_len];
            _ = try replacement_move_offsets.appendSlice(self.cir.gpa, offsets);
            _ = try replacement_moves.append(self.cir.gpa, row);
        }
    }

    fn recomputeFactsAndConsumers(transaction: *Transaction) Allocator.Error!void {
        const self = transaction.checker;
        const staged_sources = transaction.staged_sources.?;
        const replacement_constraints = &transaction.replacement_constraints;
        const replacement_contracts = &transaction.replacement_contracts;
        const replacement_bases = &transaction.replacement_bases;
        const replacement_type_paths = &transaction.replacement_type_paths;
        const replacement_moves = &transaction.replacement_moves;
        const replacement_move_offsets = &transaction.replacement_move_offsets;
        const step_provider_envs = transaction.step_provider_envs.?;
        const relocations = transaction.relocations.?;

        // Recompute every retained fact from authority inputs, never from the
        // historical destination boolean. Local source groups are exact raw body-
        // use ORs. Cross-module bases terminate at an already-admitted provider;
        // local bases and constraint-movement edges form a monotone graph whose
        // least fixed point gives false to unsupported cycles.
        const canonical_contracts = replacement_contracts.items.items;
        const canonical_paths = replacement_type_paths.items.items;
        for (staged_sources) |source| {
            const retained = &replacement_constraints.items.items[source.retained_constraint_index];
            if (source.source_contracts_len == 0) continue;
            if (retained.where_method_markers.len() == 0) {
                @panic("marker-bearing local source named a retained constraint without marker paths");
            }
            const retained_markers = canonical_contracts[@intFromEnum(retained.where_method_markers.start)..][0..retained.where_method_markers.len()];
            const source_markers = canonical_contracts[source.source_contracts_start..][0..source.source_contracts_len];
            for (source_markers) |source_marker| {
                var matched: ?*types_mod.WhereMethodMarkerContract = null;
                for (retained_markers) |*candidate| {
                    if (candidate.position != source_marker.position or
                        !checkedBoundaryMarkerPathsEqual(canonical_paths, candidate.*, source_marker))
                    {
                        continue;
                    }
                    if (matched != null) {
                        @panic("one local source marker matched two retained marker paths");
                    }
                    matched = candidate;
                }
                const destination = matched orelse
                    @panic("local source marker had no retained marker path");
                if (source_marker.isWidened().?) destination.widened = 1;
            }
        }

        for (replacement_constraints.items.items) |*constraint| {
            const marker_start: usize = if (constraint.where_method_markers.len() == 0)
                0
            else
                @intFromEnum(constraint.where_method_markers.start);
            const basis_start: usize = if (constraint.where_method_marker_bases.len() == 0)
                0
            else
                @intFromEnum(constraint.where_method_marker_bases.start);
            for (replacement_bases.items.items[basis_start..][0..constraint.where_method_marker_bases.len()]) |basis| {
                const provider = step_provider_envs[basis.copy_step] orelse continue;
                if (basis.source_constraint_index >= provider.types.static_dispatch_constraints.items.items.len) {
                    @panic("cross-module marker basis named an absent provider constraint");
                }
                const provider_constraint = provider.types.static_dispatch_constraints.items.items[basis.source_constraint_index];
                const provider_range = provider_constraint.where_method_markers;
                if (provider_range.len() == 0 or basis.source_contract_offset >= provider_range.len()) {
                    @panic("cross-module marker basis named an absent provider marker");
                }
                const provider_marker = provider.types.where_method_marker_contracts.items.items[
                    @intFromEnum(provider_range.start) + basis.source_contract_offset
                ];
                if (provider_marker.hasProducer() or provider_marker.isReady() != true or
                    provider_marker.isWidened() == null)
                {
                    @panic("cross-module marker basis named an unsettled provider fact");
                }
                if (provider_marker.isWidened().?) {
                    canonical_contracts[marker_start + basis.marker_offset].widened = 1;
                }
            }
        }

        var fact_changed = true;
        while (fact_changed) {
            fact_changed = false;
            for (replacement_constraints.items.items) |constraint| {
                const marker_start: usize = if (constraint.where_method_markers.len() == 0)
                    0
                else
                    @intFromEnum(constraint.where_method_markers.start);
                const basis_start: usize = if (constraint.where_method_marker_bases.len() == 0)
                    0
                else
                    @intFromEnum(constraint.where_method_marker_bases.start);
                for (replacement_bases.items.items[basis_start..][0..constraint.where_method_marker_bases.len()]) |basis| {
                    if (step_provider_envs[basis.copy_step] != null) continue;
                    if (basis.source_constraint_index >= replacement_constraints.items.items.len) {
                        @panic("local marker basis named an absent source constraint");
                    }
                    const source_constraint = replacement_constraints.items.items[basis.source_constraint_index];
                    if (source_constraint.where_method_markers.len() == 0 or
                        basis.source_contract_offset >= source_constraint.where_method_markers.len())
                    {
                        @panic("local marker basis named an absent source marker");
                    }
                    const source_marker = canonical_contracts[
                        @intFromEnum(source_constraint.where_method_markers.start) +
                            basis.source_contract_offset
                    ];
                    const destination = &canonical_contracts[marker_start + basis.marker_offset];
                    if (source_marker.isWidened().? and !destination.isWidened().?) {
                        destination.widened = 1;
                        fact_changed = true;
                    }
                }
            }
            for (replacement_moves.items.items) |move| {
                const source = replacement_constraints.items.items[move.source_constraint_index];
                const destination = replacement_constraints.items.items[move.destination_constraint_index];
                const offsets = replacement_move_offsets.items.items[move.offsets_start..][0..move.offsets_len];
                for (offsets, 0..) |destination_offset, source_offset| {
                    const source_marker = canonical_contracts[
                        @intFromEnum(source.where_method_markers.start) + source_offset
                    ];
                    const destination_marker = &canonical_contracts[
                        @intFromEnum(destination.where_method_markers.start) + destination_offset
                    ];
                    if (source_marker.isWidened().? and !destination_marker.isWidened().?) {
                        destination_marker.widened = 1;
                        fact_changed = true;
                    }
                }
            }
        }

        transaction.staged_alias_expansions = try self.gpa.dupe(
            ModuleEnv.WhereAliasExpansion,
            transaction.input.where_alias_expansions,
        );
        const staged_alias_expansions = transaction.staged_alias_expansions.?;
        for (staged_alias_expansions) |*expansion| {
            expansion.retained_constraint_index = checkedBoundaryRelocatedConstraintIndex(
                relocations,
                expansion.retained_constraint_index,
            );
        }
        transaction.staged_codec_requirements = try self.gpa.dupe(
            ModuleEnv.BindingSchemeCodecRequirement,
            transaction.input.codec_requirements,
        );
        const staged_codec_requirements = transaction.staged_codec_requirements.?;
        for (staged_codec_requirements) |*requirement| {
            requirement.constraint_index = checkedBoundaryRelocatedConstraintIndex(
                relocations,
                requirement.constraint_index,
            );
        }

        transaction.staged_marker_uses = try self.gpa.dupe(
            ModuleEnv.WhereMethodMarkerUse,
            transaction.input.marker_uses,
        );
        const staged_marker_uses = transaction.staged_marker_uses.?;
        var old_marker_use_end: usize = 0;
        for (self.cir.scheme_uses.items.items) |record| {
            const start: usize = record.marker_uses_start;
            const len: usize = record.marker_uses_len;
            if (start != old_marker_use_end or start > staged_marker_uses.len or
                len > staged_marker_uses.len - start)
            {
                @panic("checked-boundary scheme-use marker ownership was not gapless");
            }
            const slot = std.enums.fromInt(ModuleEnv.SchemeUseRecord.Slot, record.slot_kind) orelse
                @panic("checked-boundary scheme use had an invalid slot");
            if (slot != .where_method_use and len != 0) {
                @panic("non-where scheme use owned where-method marker rows");
            }
            old_marker_use_end += len;
        }
        if (old_marker_use_end != staged_marker_uses.len) {
            @panic("checked-boundary scheme-use marker pool contained orphan rows");
        }
        const old_use_paths = transaction.input.use_paths;
        transaction.replacement_use_paths = try ModuleEnv.WhereMethodMarkerPathStep.SafeList.initCapacity(
            self.cir.gpa,
            old_use_paths.len,
        );
        const replacement_use_paths = &transaction.replacement_use_paths;
        for (staged_marker_uses) |*marker| {
            const start: usize = marker.path_start;
            const len: usize = marker.path_len;
            if (len == 0 or start > old_use_paths.len or
                len > old_use_paths.len - start)
            {
                @panic("checked-boundary marker-use path escaped its pool");
            }
            const new_path = try replacement_use_paths.appendSlice(
                self.cir.gpa,
                old_use_paths[start..][0..len],
            );
            marker.path_start = @intFromEnum(new_path.start);
        }

        var pending_authorizations: std.ArrayListUnmanaged(ModuleEnv.ResultRowWideningUse) = .empty;
        defer pending_authorizations.deinit(self.gpa);
        try self.collectResultRowWideningUses(&pending_authorizations);
        transaction.replacement_authorizations = try ModuleEnv.ResultRowWideningUse.SafeList.initCapacity(
            self.cir.gpa,
            pending_authorizations.items.len,
        );
        const replacement_authorizations = &transaction.replacement_authorizations;
        _ = try replacement_authorizations.appendSlice(self.cir.gpa, pending_authorizations.items);

        transaction.remapped_live_ranges = try self.gpa.alloc(
            ?types_mod.StaticDispatchConstraint.SafeList.Range,
            transaction.live_ranges.?.len,
        );
        const remapped_live_ranges = transaction.remapped_live_ranges.?;
        const live_ranges = transaction.live_ranges.?;
        for (live_ranges, 0..) |maybe_range, descriptor_index| {
            const old_range = maybe_range orelse {
                remapped_live_ranges[descriptor_index] = null;
                continue;
            };
            if (old_range.len() == 0) {
                remapped_live_ranges[descriptor_index] = .empty();
                continue;
            }
            const new_start = checkedBoundaryRelocatedConstraintIndex(
                relocations,
                @intFromEnum(old_range.start),
            );
            for (0..old_range.len()) |offset| {
                const mapped = checkedBoundaryRelocatedConstraintIndex(
                    relocations,
                    @intFromEnum(old_range.start) + @as(u32, @intCast(offset)),
                );
                if (mapped != new_start + @as(u32, @intCast(offset))) {
                    @panic("checked-boundary descriptor range did not remain contiguous");
                }
            }
            remapped_live_ranges[descriptor_index] = .{
                .start = @enumFromInt(new_start),
                .count = old_range.len(),
            };
        }

        if (self.predeclared_anno_event_scopes.items.len != 0) {
            @panic("checked-boundary rebuild retained an active annotation producer scope");
        }
        for (self.predeclared_anno_drafts.items) |draft| {
            switch (draft.state) {
                .rebased, .marker_free => {},
                .recording_prepass, .awaiting_orphan_copy, .awaiting_body => @panic("checked-boundary rebuild retained an unresolved annotation producer draft"),
            }
        }
    }

    /// The only mutation boundary in the rebuild. Every coordinate and every
    /// replacement pool was constructed and validated by the preceding
    /// fallible phases, so this method can only swap or copy prepared state.
    fn commit(transaction: *Transaction) void {
        const self = transaction.checker;

        // From this point onward every operation is infallible.
        self.types.commitCheckedBoundaryStaticDispatchRebuild(
            &transaction.replacement_constraints,
            &transaction.replacement_evidence_handles,
            &transaction.replacement_contracts,
            &transaction.replacement_bases,
            &transaction.replacement_type_paths,
            transaction.remapped_live_ranges.?,
        );
        std.mem.swap(
            ModuleEnv.WhereMarkerCopyStep.SafeList,
            &self.cir.where_marker_copy_steps,
            &transaction.replacement_steps,
        );
        std.mem.swap(
            ModuleEnv.ExternalCacheSeed.SafeList,
            &self.cir.external_cache_seeds,
            &transaction.replacement_external_cache_seeds,
        );
        std.mem.swap(
            ModuleEnv.WhereMarkerCopyPair.SafeList,
            &self.cir.where_marker_copy_pairs,
            &transaction.replacement_pairs,
        );
        std.mem.swap(
            ModuleEnv.WhereMarkerCopyOccurrence.SafeList,
            &self.cir.where_marker_copy_occurrences,
            &transaction.replacement_occurrences,
        );
        std.mem.swap(
            ModuleEnv.WhereMarkerConstraintCopyPair.SafeList,
