            &transaction.replacement_witnesses,
        );
        std.mem.swap(
            ModuleEnv.CopiedOpenLiteralGroup.SafeList,
            &self.cir.copied_open_literal_groups,
            &transaction.replacement_copied_literal_groups,
        );
        std.mem.swap(
            ModuleEnv.CopiedOpenLiteralEvent.SafeList,
            &self.cir.copied_open_literal_events,
            &transaction.replacement_copied_literal_events,
        );
        std.mem.swap(
            ModuleEnv.WhereMarkerPlatformSubstitution.SafeList,
            &self.cir.where_marker_platform_substitutions,
            &transaction.replacement_substitutions,
        );
        std.mem.swap(
            ModuleEnv.ExpectedConsumptionPlan.SafeList,
            &self.cir.expected_consumption_plans,
            &transaction.replacement_expected_plans,
        );
        std.mem.swap(
            ModuleEnv.ExpectedCallFormal.SafeList,
            &self.cir.expected_call_formals,
            &transaction.replacement_expected_call_formals,
        );
        std.mem.swap(
            ModuleEnv.ExpectedFailure.SafeList,
            &self.cir.expected_failures,
            &transaction.replacement_expected_failures,
        );
        std.mem.swap(
            ModuleEnv.ExpectedConsumerRetirement.SafeList,
            &self.cir.expected_consumer_retirements,
            &transaction.replacement_expected_retirements,
        );
        std.mem.swap(
            ModuleEnv.ExpectedAmbiguityRetirement.SafeList,
            &self.cir.expected_ambiguity_retirements,
            &transaction.replacement_expected_ambiguity_retirements,
        );
        std.mem.swap(
            ModuleEnv.ExpectedRetirementFailure.SafeList,
            &self.cir.expected_retirement_failures,
            &transaction.replacement_expected_retirement_failures,
        );
        std.mem.swap(
            ModuleEnv.ExpectedRetiredConsumer.SafeList,
            &self.cir.expected_retired_consumers,
            &transaction.replacement_expected_retired_consumers,
        );
        std.mem.swap(
            ModuleEnv.DefaultDecision.SafeList,
            &self.cir.default_decisions,
            &transaction.replacement_default_decisions,
        );
        std.mem.swap(
            ModuleEnv.SelectedMethodDecision.SafeList,
            &self.cir.selected_method_decisions,
            &transaction.replacement_selected_decisions,
        );
        std.mem.swap(
            ModuleEnv.SelectedReceiverAnchor.SafeList,
            &self.cir.selected_receiver_anchors,
            &transaction.replacement_selected_anchors,
        );
        std.mem.swap(
            ModuleEnv.ForLoopDispatchPlan.SafeList,
            &self.cir.for_loop_dispatch_plans,
            &transaction.replacement_for_loop_plans,
        );
        std.mem.swap(
            ModuleEnv.DispatchSettlementSource.SafeList,
            &self.cir.dispatch_settlement_sources,
            &transaction.replacement_settlement_sources,
        );
        std.mem.swap(
            ModuleEnv.ConstraintEvidenceMove.SafeList,
            &self.cir.constraint_evidence_moves,
            &transaction.replacement_selected_moves,
        );
        std.mem.swap(
            ModuleEnv.SelectedMethodDecisionMove.SafeList,
            &self.cir.selected_method_decision_moves,
            &transaction.replacement_selected_decision_moves,
        );
        std.mem.swap(
            ModuleEnv.DefaultDecisionContributor.SafeList,
            &self.cir.default_decision_contributors,
            &transaction.replacement_default_contributors,
        );
        std.mem.swap(
            ModuleEnv.WhereMarkerConstraintMove.SafeList,
            &self.cir.where_marker_constraint_moves,
            &transaction.replacement_moves,
        );
        std.mem.swap(
            MkSafeList(u32),
            &self.cir.where_marker_constraint_move_offsets,
            &transaction.replacement_move_offsets,
        );
        std.mem.swap(
            ModuleEnv.WhereMethodMarkerPathStep.SafeList,
            &self.cir.where_method_marker_path_steps,
            &transaction.replacement_use_paths,
        );
        std.mem.swap(
            ModuleEnv.ResultRowWideningUse.SafeList,
            &self.cir.result_row_widening_uses,
            &transaction.replacement_authorizations,
        );
        @memcpy(self.cir.where_method_sources.items.items, transaction.staged_sources.?);
        @memcpy(self.cir.where_alias_expansions.items.items, transaction.staged_alias_expansions.?);
        @memcpy(self.cir.binding_scheme_codec_requirements.items.items, transaction.staged_codec_requirements.?);
        @memcpy(self.cir.where_method_marker_uses.items.items, transaction.staged_marker_uses.?);

        // These producer drafts deliberately name discarded prepass history. Once
        // all marker-bearing copies have been rebased, they are neither durable
        // roots nor admissible checked-module data.
        self.predeclared_anno_draft_by_annotation.clearRetainingCapacity();
        self.predeclared_anno_drafts.clearRetainingCapacity();
        self.predeclared_anno_events.clearRetainingCapacity();
        self.predeclared_anno_orphan_pairs.clearRetainingCapacity();
        if (!self.record_update_expected_plan_registrations_consumed) {
            self.record_update_expected_plan_registrations.clearRetainingCapacity();
            self.record_update_expected_plan_registrations_consumed = true;
        } else if (self.record_update_expected_plan_registrations.items.len != 0) {
            @panic("consumed record-update registrations became nonempty during rebuild");
        }
    }
};

fn rebuildCheckedBoundaryWhereMethodState(self: *Self) Allocator.Error!void {
    if (self.probe_depth != 0) {
        @panic("checked-boundary rebuild cannot run inside a Probe transaction");
    }
    if (self.record_update_owner_retirement_drafts.items.len != 0) {
        @panic("checked-boundary rebuild found an incomplete record-update owner retirement");
    }
    if (!self.validateRecordUpdateExpectedPlanRegistrations()) {
        @panic("record-update Expected plan registrations lost their producer membership");
    }
    var transaction = CheckedBoundaryRebuild.init(self);
    defer transaction.deinit();
    try transaction.validateAndOrder();
    try transaction.markReachable();
    try transaction.rebuildConstraintsAndCopies();
    try transaction.rebuildExpectedLedgers();
    try transaction.rebuildDispatchEvidenceAndMoves();
    try transaction.recomputeFactsAndConsumers();
    transaction.commit();
}

/// Finite, caller-authored origin for an in-module Instantiator copy. This is
/// deliberately disjoint from `copy_import.CrossModuleWhereMarkerCopyOrigin`:
/// a cross-module boundary cannot encode a local-use anchor, and an
/// Instantiator cannot claim an external import boundary.
const LocalWhereMarkerCopyOrigin = union(enum) {
    scheme_use: ModuleEnv.WhereMarkerSchemeUseOrigin,
    type_annotation: ModuleEnv.WhereMarkerNodeOrigin,
    numeric_suffix_use: ModuleEnv.WhereMarkerNodeOrigin,
    nominal_expr_decl: ModuleEnv.WhereMarkerNodeOrigin,
    nominal_expr_backing: ModuleEnv.WhereMarkerNodeOrigin,
    nominal_pattern_decl: ModuleEnv.WhereMarkerNodeOrigin,
    nominal_pattern_backing: ModuleEnv.WhereMarkerNodeOrigin,
    required_lookup: ModuleEnv.WhereMarkerNodeOrigin,
    platform_requirement_instance: ModuleEnv.WhereMarkerPlatformInstanceOrigin,
    platform_alias_app_decl: ModuleEnv.WhereMarkerPlatformAliasAppDeclOrigin,
    default_field_type: ModuleEnv.WhereMarkerDefaultFieldTypeOrigin,
    record_update_base: ModuleEnv.WhereMarkerRecordUpdateBaseOrigin,
    aggregate_fresh_shape_child: ModuleEnv.WhereMarkerAggregateFreshShapeChildOrigin,
    predeclared_annotation: ModuleEnv.WhereMarkerNodeOrigin,
    generated_codec_snapshot: ModuleEnv.WhereMarkerNodeOrigin,
    expected_call_instantiation: ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin,
    aggregate_expected_projection: ModuleEnv.WhereMarkerExpectedProjectionOrigin,
    branch_expected_copy: ModuleEnv.WhereMarkerExpectedProjectionOrigin,
    candidate_probe_method_use: ModuleEnv.WhereMarkerCandidateProbeMethodOrigin,
    default_method_use: ModuleEnv.WhereMarkerDefaultMethodUseOrigin,

    const Encoded = struct {
        kind: ModuleEnv.WhereMarkerCopyStep.Kind,
        origin: ModuleEnv.WhereMarkerCopyOrigin,
    };

    fn encode(self: @This()) Encoded {
        return switch (self) {
            inline else => |payload, tag| .{
                .kind = @field(ModuleEnv.WhereMarkerCopyStep.Kind, @tagName(tag)),
                .origin = @unionInit(ModuleEnv.WhereMarkerCopyOrigin, @tagName(tag), payload),
            },
        };
    }
};

const DefaultMethodUseDraftOrigin = struct {
    decision_index: u32,
    constraint_offset: u32,
    root_copy_step: u32,
};

fn whereMarkerInstantiationPairLessThan(
    _: void,
    a: InstantiationProofPair,
    b: InstantiationProofPair,
) bool {
    if (a.raw_source_var != b.raw_source_var) return a.raw_source_var < b.raw_source_var;
    if (a.raw_destination_var != b.raw_destination_var) {
        return a.raw_destination_var < b.raw_destination_var;
    }
    if (a.canonical_source_var != b.canonical_source_var) {
        return a.canonical_source_var < b.canonical_source_var;
    }
    return a.canonical_destination_var < b.canonical_destination_var;
}

/// Resolve, sort, and deduplicate one Instantiator's immutable copy-time
/// occurrences. Canonical pair deduplication is deliberately deferred to the
/// durable publisher: distinct raw occurrences may collapse after solving,
/// but they remain separate proof identities.
fn canonicalizeWhereMarkerInstantiationPairs(
    self: *Self,
    pairs: *std.ArrayListUnmanaged(InstantiationProofPair),
) void {
    for (pairs.items) |*pair| {
        pair.canonical_source_var = @intFromEnum(
            self.types.resolveVar(@enumFromInt(pair.raw_source_var)).var_,
        );
        pair.canonical_destination_var = @intFromEnum(
            self.types.resolveVar(@enumFromInt(pair.raw_destination_var)).var_,
        );
    }
    std.mem.sortUnstable(
        InstantiationProofPair,
        pairs.items,
        {},
        whereMarkerInstantiationPairLessThan,
    );
    var write: usize = 0;
    for (pairs.items) |pair| {
        if (write != 0 and pairs.items[write - 1].raw_source_var == pair.raw_source_var) {
            if (pairs.items[write - 1].raw_destination_var != pair.raw_destination_var) {
                std.debug.panic("one raw instantiated source occurrence named two destinations", .{});
            }
            if (pairs.items[write - 1].canonical_source_var != pair.canonical_source_var or
                pairs.items[write - 1].canonical_destination_var != pair.canonical_destination_var)
            {
                std.debug.panic("one raw instantiated occurrence resolved to two canonical pairs", .{});
            }
            continue;
        }
        pairs.items[write] = pair;
        write += 1;
    }
    pairs.items.len = write;
}

fn durableWhereMarkerCopyPairLessThan(
    _: void,
    a: ModuleEnv.WhereMarkerCopyPair,
    b: ModuleEnv.WhereMarkerCopyPair,
) bool {
    if (a.source_var != b.source_var) return a.source_var < b.source_var;
    return a.destination_var < b.destination_var;
}

/// Deduplicate an already tuple-sorted canonical relation. Either coordinate
/// may be shared; only an exact `(source, destination)` pair is duplicate.
fn deduplicateSortedWhereMarkerCopyPairs(
    pairs: []ModuleEnv.WhereMarkerCopyPair,
) usize {
    var write: usize = 0;
    for (pairs) |pair| {
        if (write != 0 and pairs[write - 1].source_var == pair.source_var and
            pairs[write - 1].destination_var == pair.destination_var)
        {
            continue;
        }
        pairs[write] = pair;
        write += 1;
    }
    return write;
}

fn whereMarkerCopyOccurrenceLessThan(
    _: void,
    a: ModuleEnv.WhereMarkerCopyOccurrence,
    b: ModuleEnv.WhereMarkerCopyOccurrence,
) bool {
    return ModuleEnv.WhereMarkerCopyOccurrence.canonicalLessThan(a, b);
}

/// Raw occurrence identity is a copy-time function even though final
/// canonical pairs are only a tuple-key relation: distinct raw sources may
/// later resolve together, but one exact raw source may never be retargeted
/// to two raw destinations. Occurrences are sorted by canonical pair, so a
/// corrupt split need not be adjacent and must be checked against every
/// earlier row.
fn whereMarkerRawOccurrenceRelationIsFunctional(
    occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
) bool {
    for (occurrences, 0..) |occurrence, occurrence_index| {
        for (occurrences[0..occurrence_index]) |prior| {
            if (prior.raw_source_var == occurrence.raw_source_var and
                prior.raw_destination_var != occurrence.raw_destination_var)
            {
                return false;
            }
        }
    }
    return true;
}

fn whereMarkerInstantiationConstraintPairLessThan(
    _: void,
    a: InstantiationProofConstraintPair,
    b: InstantiationProofConstraintPair,
) bool {
    return ModuleEnv.WhereMarkerConstraintCopyPair.canonicalLessThan(.{
        .source_constraint_index = a.source_constraint_index,
        .destination_constraint_index = a.destination_constraint_index,
    }, .{
        .source_constraint_index = b.source_constraint_index,
        .destination_constraint_index = b.destination_constraint_index,
    });
}

fn canonicalizeWhereMarkerInstantiationConstraintPairs(
    pairs: *std.ArrayListUnmanaged(InstantiationProofConstraintPair),
) void {
    std.mem.sortUnstable(
        InstantiationProofConstraintPair,
        pairs.items,
        {},
        whereMarkerInstantiationConstraintPairLessThan,
    );
    var write: usize = 0;
    for (pairs.items) |pair| {
        if (pair.source_constraint_index == pair.destination_constraint_index) {
            std.debug.panic("terminating local share cut published a constraint-copy pair", .{});
        }
        if (write != 0 and
            pairs.items[write - 1].source_constraint_index == pair.source_constraint_index)
        {
            if (pairs.items[write - 1].destination_constraint_index != pair.destination_constraint_index) {
                std.debug.panic("one instantiated source constraint mapped to two destination constraints", .{});
            }
            continue;
        }
        pairs.items[write] = pair;
        write += 1;
    }
    pairs.items.len = write;
}

fn proofPairOffset(
    pairs: []const ModuleEnv.WhereMarkerCopyPair,
    source_var: u32,
    destination_var: u32,
) u32 {
    var low: usize = 0;
    var high: usize = pairs.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        if (pairs[mid].source_var < source_var or
            (pairs[mid].source_var == source_var and
                pairs[mid].destination_var < destination_var))
        {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    if (low >= pairs.len or pairs[low].source_var != source_var or
        pairs[low].destination_var != destination_var)
    {
        std.debug.panic("instantiation witness endpoint was absent from its complete pair relation", .{});
    }
    return @intCast(low);
}

fn proofOccurrenceOffset(
    occurrences: []const ModuleEnv.WhereMarkerCopyOccurrence,
    raw_source_var: u32,
    raw_destination_var: u32,
) u32 {
    var found: ?u32 = null;
    for (occurrences, 0..) |occurrence, offset| {
        if (occurrence.raw_source_var != raw_source_var or
            occurrence.raw_destination_var != raw_destination_var) continue;
        if (found != null) {
            std.debug.panic("local marker-copy proof repeated one raw occurrence", .{});
        }
        found = @intCast(offset);
    }
    return found orelse
        std.debug.panic("local marker-copy witness named an absent raw occurrence", .{});
}

fn proofConstraintPairOffset(
    pairs: []const InstantiationProofConstraintPair,
    source_constraint_index: u32,
) u32 {
    var low: usize = 0;
    var high: usize = pairs.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        if (pairs[mid].source_constraint_index < source_constraint_index) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    if (low >= pairs.len or pairs[low].source_constraint_index != source_constraint_index) {
        std.debug.panic("instantiation witness named an absent constraint-copy pair", .{});
    }
    return @intCast(low);
}

fn whereMarkerCopyWitnessLessThan(
    _: void,
    a: ModuleEnv.WhereMarkerCopyWitness,
    b: ModuleEnv.WhereMarkerCopyWitness,
) bool {
    return ModuleEnv.WhereMarkerCopyWitness.canonicalLessThan(a, b);
}

