/// Validate a platform module's hosted section against the hosted functions
/// its imported type modules declare: every hosted function must appear
/// exactly once, every entry must name a real hosted function, linker symbols
/// must be unique across the hosted and provides sections, and the fixed
/// runtime symbols plus the internal roc__ namespace are reserved.
///
/// Applications never pay for this: it only runs for platform modules.
///
/// One hosted function declaration, identified by the module and definition
/// the hosted transform rewrote rather than by any name it goes under.
const HostedTarget = struct {
    module: *const ModuleEnv,
    def: CIR.Def.Idx,
};

/// Record every hosted function `module` declares, keeping one display name per
/// definition for the missing-entry diagnostic.
fn collectDeclaredHostedFunctions(
    self: *Self,
    declared: *std.AutoHashMap(HostedTarget, []const u8),
    module: *const ModuleEnv,
) std.mem.Allocator.Error!void {
    for (module.store.sliceDefs(module.hosted_defs)) |def_idx| {
        const def = module.store.getDef(def_idx);
        const expr = module.store.getExpr(def.expr);
        // A declaration the hosted transform rewrote can still be replaced by a
        // runtime error afterwards, when canonicalization rejects the
        // declaration itself. That is already reported where it was rejected,
        // and it names no host function for the section to map.
        if (expr != .e_hosted_lambda) continue;

        // A declaration this platform module makes is named in the hosted
        // section without a module, so the diagnostic names it the same way.
        const name = if (module == self.cir)
            try hostedOwnDeclarationDisplayName(self.gpa, module, expr.e_hosted_lambda.symbol_name)
        else
            try hostedDefinitionDisplayName(self.gpa, module, expr.e_hosted_lambda.symbol_name);
        const gop = try declared.getOrPut(.{ .module = module, .def = def_idx });
        if (gop.found_existing) {
            self.gpa.free(name);
        } else {
            gop.value_ptr.* = name;
        }
    }
}

fn checkPlatformHostedSection(self: *Self) std.mem.Allocator.Error!void {
    if (self.cir.module_kind != .platform) return;

    const section = self.cir.hosted_entries.items.items;

    // Exact definitions of every hosted function declared by imported modules.
    // Display names are retained only for missing-entry diagnostics.
    var declared = std.AutoHashMap(HostedTarget, []const u8).init(self.gpa);
    defer {
        var value_it = declared.valueIterator();
        while (value_it.next()) |name| self.gpa.free(name.*);
        declared.deinit();
    }
    // Walk owner modules (direct imports plus their transitive public
    // dependencies), since hosted functions can live in modules the platform
    // root never imports directly. The hosted transform publishes the exact
    // rewritten defs, including associated items of nested type modules.
    //
    // The platform root is walked alongside them. A section entry names its
    // target through an import, so an entry can never resolve to a definition
    // in the root itself; a hosted declaration written there is therefore
    // always missing from the section, and reporting it here is what tells the
    // author so instead of leaving a declaration no linker symbol reaches.
    for (self.owner_modules) |imported_env| {
        try self.collectDeclaredHostedFunctions(&declared, imported_env);
    }
    try self.collectDeclaredHostedFunctions(&declared, self.cir);

    // Walk the section's resolved targets, detect duplicate functions and
    // duplicate/reserved symbols (provides symbols share the namespace).
    var mapped = std.AutoHashMap(HostedTarget, void).init(self.gpa);
    defer mapped.deinit();
    var symbols = std.StringHashMap(void).init(self.gpa);
    defer symbols.deinit();
    for (self.cir.provides_entries.items.items) |provides_entry| {
        const symbol_text = self.cir.getString(provides_entry.ffi_symbol);
        try self.checkHostSymbol(symbol_text, &symbols);
        try self.checkProvidesEntryHostBoundaryRows(provides_entry);
    }

    for (section) |entry| {
        // A resolved entry with no import named this platform module's own
        // declaration, so the module owning the target is this one.
        const target_env = if (entry.target_import) |import_idx|
            self.hoistedImportedModule(self.cir, import_idx)
        else if (entry.target_status == .resolved)
            self.cir
        else
            null;
        const target = if (target_env) |env|
            if (entry.target_def) |def_idx| HostedTarget{ .module = env, .def = def_idx } else null
        else
            null;

        if (target) |resolved| {
            const def = resolved.module.store.getDef(resolved.def);
            const expr = resolved.module.store.getExpr(def.expr);
            if (expr != .e_hosted_lambda) {
                const display_name = try hostedEntryDisplayName(self.gpa, self.cir, entry);
                defer self.gpa.free(display_name);
                const name_idx = try self.problems.putExtraString(display_name);
                _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                    .name = name_idx,
                    .reason = .function_has_implementation,
                } });
            } else {
                const gop = try mapped.getOrPut(resolved);
                if (gop.found_existing) {
                    const display_name = try hostedEntryDisplayName(self.gpa, self.cir, entry);
                    defer self.gpa.free(display_name);
                    const name_idx = try self.problems.putExtraString(display_name);
                    _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                        .name = name_idx,
                        .reason = .duplicate_function,
                    } });
                }
            }
        } else {
            const display_name = try hostedEntryDisplayName(self.gpa, self.cir, entry);
            defer self.gpa.free(display_name);
            const name_idx = try self.problems.putExtraString(display_name);
            _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                .name = name_idx,
                .reason = .unknown_function,
            } });
        }

        const symbol_text = self.cir.getString(entry.symbol);
        try self.checkHostSymbol(symbol_text, &symbols);
    }

    // Every declared hosted function needs exactly one section entry.
    var declared_it = declared.iterator();
    while (declared_it.next()) |decl| {
        if (mapped.contains(decl.key_ptr.*)) continue;
        const name_idx = try self.problems.putExtraString(decl.value_ptr.*);
        _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
            .name = name_idx,
            .reason = .function_not_in_section,
        } });
    }
}

fn hostedDefinitionDisplayName(
    allocator: Allocator,
    module: *const ModuleEnv,
    symbol_name: Ident.Idx,
) Allocator.Error![]const u8 {
    var module_name = module.module_name;
    if (Ident.textEndsWith(module_name, ".roc")) {
        module_name = module_name[0 .. module_name.len - 4];
    }
    var func_name = module.getIdent(symbol_name);
    if (Ident.textEndsWith(func_name, "!")) {
        func_name = func_name[0 .. func_name.len - 1];
    }
    return std.fmt.allocPrint(allocator, "{s}.{s}", .{ module_name, func_name });
}

/// How a declaration this platform module makes is written in its own hosted
/// section: the function name alone, with the trailing `!` dropped the way
/// every other hosted name is displayed.
fn hostedOwnDeclarationDisplayName(
    allocator: Allocator,
    module: *const ModuleEnv,
    symbol_name: Ident.Idx,
) Allocator.Error![]const u8 {
    var func_name = module.getIdent(symbol_name);
    if (Ident.textEndsWith(func_name, "!")) {
        func_name = func_name[0 .. func_name.len - 1];
    }
    return allocator.dupe(u8, func_name);
}

fn hostedEntryDisplayName(
    allocator: Allocator,
    platform: *const ModuleEnv,
    entry: ModuleEnv.HostedEntry,
) Allocator.Error![]const u8 {
    var func_name = platform.getIdent(entry.func_ident);
    if (Ident.textEndsWith(func_name, "!")) {
        func_name = func_name[0 .. func_name.len - 1];
    }
    return if (entry.module_ident) |module_ident|
        std.fmt.allocPrint(allocator, "{s}.{s}", .{ platform.getIdent(module_ident), func_name })
    else
        allocator.dupe(u8, func_name);
}

fn checkProvidesEntryHostBoundaryRows(
    self: *Self,
    provides_entry: ModuleEnv.ProvidesEntry,
) std.mem.Allocator.Error!void {
    const def_idx = provides_entry.local_def orelse return;
    const def = self.cir.store.getDef(def_idx);
    const def_var = ModuleEnv.varFrom(def_idx);

    try self.checkHostBoundaryType(def_var, self.cir.store.getPatternRegion(def.pattern));
}

fn checkHostBoundaryType(self: *Self, var_: Var, region: Region) std.mem.Allocator.Error!void {
    if (try self.varContainsOpenRowInHostBoundary(var_)) {
        _ = try self.problems.appendProblem(self.gpa, .{ .host_boundary_open_row = .{
            .region = region,
        } });
    }
    if (try self.varContainsOptionalFieldInHostBoundary(var_)) {
        _ = try self.problems.appendProblem(self.gpa, .{ .host_boundary_optional_field = .{
            .region = region,
        } });
    }
}

/// The fixed runtime symbols every host defines; platform headers may not
/// reuse them for provides or hosted entries.
const reserved_host_symbols = [_][]const u8{
    "roc_alloc",
    "roc_dealloc",
    "roc_realloc",
    "roc_dbg",
    "roc_expect_failed",
    "roc_crashed",
};

fn checkHostSymbol(
    self: *Self,
    symbol_text: []const u8,
    symbols: *std.StringHashMap(void),
) std.mem.Allocator.Error!void {
    const gop = try symbols.getOrPut(symbol_text);
    if (!isValidHostSymbol(symbol_text)) {
        if (!gop.found_existing) {
            const name_idx = try self.problems.putExtraString(symbol_text);
            _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                .name = name_idx,
                .reason = .invalid_symbol,
            } });
        }
        return;
    }
    for (reserved_host_symbols) |reserved| {
        if (Ident.textEql(symbol_text, reserved)) {
            if (!gop.found_existing) {
                const name_idx = try self.problems.putExtraString(symbol_text);
                _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                    .name = name_idx,
                    .reason = .reserved_symbol,
                } });
            }
            return;
        }
    }
    if (Ident.textStartsWith(symbol_text, "roc__")) {
        if (!gop.found_existing) {
            const name_idx = try self.problems.putExtraString(symbol_text);
            _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                .name = name_idx,
                .reason = .reserved_prefix,
            } });
        }
        return;
    }
    if (gop.found_existing) {
        const name_idx = try self.problems.putExtraString(symbol_text);
        _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
            .name = name_idx,
            .reason = .duplicate_symbol,
        } });
    }
}

fn isValidHostSymbol(symbol_text: []const u8) bool {
    if (symbol_text.len == 0) return false;
    if (!isHostSymbolStart(symbol_text[0])) return false;
    for (symbol_text[1..]) |byte| {
        if (!isHostSymbolContinue(byte)) return false;
    }
    return true;
}

fn isHostSymbolStart(byte: u8) bool {
    return byte == '_' or std.ascii.isAlphabetic(byte);
}

fn isHostSymbolContinue(byte: u8) bool {
    return isHostSymbolStart(byte) or std.ascii.isDigit(byte);
}

/// Process the requires_types annotations for platform modules, like:
///
///   { [Model : model] for main : { init : model, ... } }
///
/// For each required type, we first process the introduced alias variables:
///   { [Model : model] for main : { init : model, ... } }
///     ^^^^^^^^^^^^^^
/// Here, we create `model` as a *rigid* var, and a type alias `Model` pointing to
/// that exact rigid var.
///
/// We create this variable at the `.outermost` rank, so that every places
/// that references this var gets the same instance
///
/// Then, we generate the type for the actual required type
///   { [Model : model] for main : { init : model, ... } }
///                                ^^^^^^^^^^^^^^^^^^^^^^
///
/// Note on scoping: Type scopes are defined in czer. So in the example above,
///   { [Model : model] for main : { init : model, ... } }
///             a^^^^^                     b^^^^^
/// So `a` get the node CIR.TypeAnno.rigid_var{ .. }
/// So `b` get the node CIR.TypeAnno.rigid_var_lookup{ .ref = <a_id> }
/// Then, any reference to `b` replaced with `a` in `generateAnnoTypeInPlace`.
fn processRequiresTypes(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Ensure we are generalized
    // This is because we do not want the type checking we do here to be let-polymorphic
    std.debug.assert(env.rank() == .outermost);

    const requires_types_slice = self.cir.requires_types.items.items;
    for (requires_types_slice) |required_type| {

        // First, processes the required type aliases
        //   { [Model : model] for main : { init : model, ... } }
        //     ^^^^^^^^^^^^^^
        const required_type_aliases_slice = self.cir.for_clause_aliases.sliceRange(required_type.type_aliases);
        for (required_type_aliases_slice) |type_alias| {
            const stmt = self.cir.store.getStatement(type_alias.alias_stmt_idx);
            const stmt_var = ModuleEnv.varFrom(type_alias.alias_stmt_idx);

            // We should only ever have alias decls here
            std.debug.assert(stmt == .s_alias_decl);
            const alias = stmt.s_alias_decl;

            // Assert that this alias header is well formed
            const alias_lhs = self.cir.store.getTypeHeader(alias.header);
            std.debug.assert(alias_lhs.name.eql(alias_lhs.relative_name));
            std.debug.assert(alias_lhs.args.span.len == 0);

            // Assert that this alias body is well formed
            const alias_rhs_var = ModuleEnv.varFrom(alias.anno);
            const alias_rhs = self.cir.store.getTypeAnno(alias.anno);
            std.debug.assert(alias_rhs == .rigid_var);

            // Set ranks to generalized
            try self.setVarRank(stmt_var, env);
            try self.setVarRank(alias_rhs_var, env);

            // Set the rhs of the expr to be a rigid var
            try self.unifyWith(alias_rhs_var, .{
                .rigid = Rigid.init(type_alias.rigid_name),
            }, env);

            const stmt_content = self.types.resolveVar(stmt_var).desc.content;
            if (stmt_content != .alias) {
                try self.unifyWithTargetRank(
                    stmt_var,
                    try self.types.mkAliasWithSourceDeclAndBuiltinOrigin(
                        .{ .ident_idx = alias_lhs.relative_name },
                        alias_rhs_var,
                        &.{},
                        self.aliasOriginModule(),
                        @intFromEnum(type_alias.alias_stmt_idx),
                        self.cir.module_role == .builtin,
                    ),
                    env,
                );
            }
        }

        // Then, generate the type for the actual required type
        //   { [Model : model] for main : { init : model, ... } }
        //                                ^^^^^^^^^^^^^^^^^^^^^^
        // A platform requirement is a host-boundary contract: rows are kept
        // as written (see `AnnotationGenCtx.opening`).
        var failure_accumulator = AnnotationGenerationAccumulator{};
        try self.generateAnnoTypeInPlace(required_type.type_anno, env, .{ .annotation = .{
            .where = null,
            .producer_owner_node = std.math.maxInt(u32),
            .failure_publication = .{ .no_publication = .platform_requirement },
            .failure_accumulator = &failure_accumulator,
            .where_source_publication = .{ .no_publication = .platform_requirement },
            .opening = .as_written,
        } }, .pos);
        failure_accumulator.assertNoPublication();
    }
}

fn processAppPlatformRequirements(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const input = self.platform_requirements orelse return;
    switch (self.cir.module_kind) {
        .app, .default_app => {},
        .type_module, .package, .platform, .hosted, .module, .malformed => return,
    }

    // For-clause aliases live in the platform root's module-level scope, so a
    // requirement other than the declaring one can reference an alias by name;
    // bind each alias once for the whole requires clause and share the app's
    // instantiated declaration across every requirement that mentions it.
    var alias_bindings = std.ArrayListUnmanaged(ForClauseAliasBinding).empty;
    defer alias_bindings.deinit(self.gpa);
    try self.collectForClauseAliasBindings(input, env, &alias_bindings);

    var alias_var_substitutions = std.AutoHashMap(Var, Var).init(self.gpa);
    defer alias_var_substitutions.deinit();
    var alias_source_substitutions = std.AutoHashMap(copy_import.AliasSource, Var).init(self.gpa);
    defer alias_source_substitutions.deinit();
    for (alias_bindings.items) |binding| {
        const app_type_var = binding.app_type_var orelse continue;
        try alias_var_substitutions.put(binding.platform_alias_var, app_type_var);
        try alias_var_substitutions.put(binding.platform_identity_var, app_type_var);
        try alias_source_substitutions.put(binding.platform_alias_source, app_type_var);
    }

    for (input.env.requires_types.items.items, 0..) |required_type, requires_idx| {
        const required_ident = try self.copyPlatformIdent(input.env, required_type.ident);
        const def_idx = self.exposedAppDefByIdent(required_ident) orelse {
            // Without the entrypoint contract, an unsupplied requirement is
            // simply unbound: the requirements that the app does supply still
            // constrain those definitions.
            if (self.validation == .explicit_roots) continue;

            const top_level_def = self.topLevelDefByIdent(required_ident);
            const app_region = if (top_level_def) |def_idx|
                self.defPatternRegion(def_idx)
            else
                self.appModuleRegion();
            _ = try self.problems.appendProblem(self.gpa, .{ .platform_def_not_found = .{
                .expected_def_ident = required_ident,
                .app_region = app_region,
                .platform_region = required_type.region,
                .ctx = if (top_level_def == null) .not_found else .found_but_not_exported,
            } });
            continue;
        };

        const instantiated = (try self.instantiatePlatformRequiredType(
            input,
            required_type,
            @intCast(requires_idx),
            def_idx,
            env,
            alias_bindings.items,
            &alias_var_substitutions,
            &alias_source_substitutions,
        )) orelse continue;
        var identity_vars_owned = true;
        defer if (identity_vars_owned) self.gpa.free(instantiated.identity_vars);

        const map_entry = try self.platform_required_defs.getOrPut(self.gpa, def_idx);
        if (map_entry.found_existing) {
            // One def satisfying several requirements (a platform declaring one
            // name twice): the def unifies against the retained entry, so tie
            // this requirement's instance to that entry to enforce both.
            _ = try self.unifyInContext(
                map_entry.value_ptr.expected_var,
                instantiated.expected_var,
                env,
                .{ .platform_requirement = .{ .required_ident = required_ident, .platform_region = required_type.region } },
            );
        } else {
            map_entry.value_ptr.* = .{
                .expected_var = instantiated.expected_var,
                .expected_anchor = instantiated.expected_anchor,
                .required_ident = required_ident,
                .platform_region = required_type.region,
            };
        }

        try self.platform_requirement_solutions.append(self.gpa, .{
            .requires_idx = @intCast(requires_idx),
            .def = def_idx,
            .solved_var = instantiated.expected_var,
            .is_function = input.env.types.varResolvesToFunction(ModuleEnv.varFrom(required_type.type_anno)),
            .identity_vars = instantiated.identity_vars,
        });
        identity_vars_owned = false;
    }
}

/// The platform requirement solutions recorded while checking this app root,
/// in requires-clause order. The rows and their identity slices are
/// checker-owned and remain valid until `deinit`.
pub fn platformRequirementSolutions(self: *const Self) []const requirement_solution.SolutionInput {
    return self.platform_requirement_solutions.items;
}

/// Whether any of this module's requires-clause type annotations still carry
/// erroneous type content after checking. A platform root in that state keeps
/// its check-time publication: the env-derived requirement context a deferred
/// publication needs is a canonical key digest, and erroneous content has no
/// canonical key.
pub fn requiresTypesContainError(self: *Self) std.mem.Allocator.Error!bool {
    for (self.cir.requires_types.items.items) |required_type| {
        if (try canonical_type_keys.containsError(
            self.gpa,
            self.types,
            self.cir,
            ModuleEnv.varFrom(required_type.type_anno),
        )) {
            return true;
        }
    }
    return false;
}

fn instantiatePlatformRequiredType(
    self: *Self,
    input: PlatformRequirementInput,
    required_type: ModuleEnv.RequiredType,
    requires_idx: u32,
    solution_def: CIR.Def.Idx,
    env: *Env,
    bindings: []const ForClauseAliasBinding,
    alias_var_substitutions: *const std.AutoHashMap(Var, Var),
    alias_source_substitutions: *const std.AutoHashMap(copy_import.AliasSource, Var),
) std.mem.Allocator.Error!?InstantiatedRequirement {
    const declared_aliases = input.env.for_clause_aliases.sliceRange(required_type.type_aliases);
    for (declared_aliases) |alias| {
        const binding = forClauseAliasBinding(bindings, alias.alias_stmt_idx) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("platform requirement for-clause alias was not collected for the requires clause", .{});
            }
            unreachable;
        };
        // The alias's app declaration was not found; the diagnostic was
        // emitted when the clause's bindings were collected.
        if (binding.app_type_var == null) return null;
    }

    // Enumerate the requirement type's identity variables (flex/rigid) in the
    // platform's store, in canonical slot order—the same first-encounter
    // order the platform's published requirement payload assigns them.
    const platform_identity_vars = try canonical_type_keys.identityVarsFromVar(
        self.gpa,
        &input.env.types,
        input.env,
        ModuleEnv.varFrom(required_type.type_anno),
    );
    defer self.gpa.free(platform_identity_vars);

    // Aliases are module-scoped, so an entry can use an alias declared by an
    // earlier flat entry even though it is absent from `declared_aliases`.
    for (platform_identity_vars) |platform_var| {
        const binding = forClauseAliasBindingForIdentity(bindings, platform_var) orelse continue;
        // The alias's app declaration was not found; the diagnostic was
        // emitted when the clause's bindings were collected.
        if (binding.app_type_var == null) return null;
    }

    var platform_substitutions: std.ArrayListUnmanaged(copy_import.PlatformAliasSubstitutionInput) = .empty;
    defer platform_substitutions.deinit(self.gpa);
    try platform_substitutions.ensureTotalCapacity(self.gpa, bindings.len);
    for (bindings) |binding| {
        if (binding.app_type_var == null) continue;
        const app_type_stmt = binding.app_type_stmt orelse
            std.debug.panic("resolved platform alias binding omitted its app declaration", .{});
        const app_instantiation_step = binding.app_instantiation_step orelse
            std.debug.panic("resolved platform alias binding omitted its app instantiation proof", .{});
        platform_substitutions.appendAssumeCapacity(.{
            .platform_alias_var = binding.platform_alias_var,
            .platform_identity_var = binding.platform_identity_var,
            .platform_alias_source = binding.platform_alias_source,
            .platform_alias_statement = @intFromEnum(binding.platform_alias_stmt_idx),
            .app_declaration_node = @intFromEnum(app_type_stmt),
            .app_instantiation_step = app_instantiation_step,
        });
    }

    const copied_result = try self.copyVarWithSourceSubstitutionsResult(
        ModuleEnv.varFrom(required_type.type_anno),
        input.env,
        required_type.region,
        alias_var_substitutions,
        alias_source_substitutions,
        .{
            .platform_requirement = .{
                .requires_index = requires_idx,
                .solution_def = @intFromEnum(solution_def),
                .substitutions = platform_substitutions.items,
            },
        },
        true,
    );
    const copied = copied_result.var_;

    // `copyVar` keyed `var_map` by the platform store's resolved vars—the
    // same roots the identity enumeration returned—so each identity slot
    // maps to its copied var here, then to its instantiated var below.
    const identity_vars = try self.gpa.alloc(Var, platform_identity_vars.len);
    errdefer self.gpa.free(identity_vars);
    for (platform_identity_vars, identity_vars) |platform_var, *slot_var| {
        slot_var.* = self.var_map.get(platform_var) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("platform requirement identity var was not copied into the app store", .{});
            }
            unreachable;
        };
    }

    const expected_copy = try self.instantiateVarWithMarkerCopy(
        copied,
        env,
        .{ .explicit = required_type.region },
        .{ .platform_requirement_instance = .{
            .requires_index = requires_idx,
            .solution_def = @intFromEnum(solution_def),
        } },
        .eager_support,
    );
    const expected_var = expected_copy.var_;

    // `instantiateVar` keyed `var_map` by the copied store's resolved vars.
    // Clause-bound identities were replaced during copying and already are
    // the exact app declaration; every other identity must have been visited
    // and instantiated with the requirement root.
    for (platform_identity_vars, identity_vars) |platform_var, *slot_var| {
        if (alias_var_substitutions.get(platform_var)) |app_type_var| {
            const resolved_app_type = self.types.resolveVar(app_type_var).var_;
            if (builtin.mode == .Debug) {
                std.debug.assert(self.types.resolveVar(slot_var.*).var_ == resolved_app_type);
            }
            slot_var.* = resolved_app_type;
            continue;
        }

        const resolved = self.types.resolveVar(slot_var.*);
        slot_var.* = self.var_map.get(resolved.var_) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("platform requirement identity var was not instantiated with its requirement root", .{});
            }
            unreachable;
        };
    }

    return .{
        .expected_var = expected_var,
        .expected_anchor = self.expectedMarkerAnchorForRoot(
            expected_copy.copy_step orelse
                std.debug.panic("platform requirement instance did not publish its expected anchor", .{}),
            .destination,
        ),
        .identity_vars = identity_vars,
    };
}

/// An app type declaration bound to a requires clause's for-clause alias
/// (`[Model : model]` binds `Model` to the app's own `Model` declaration).
/// A null `app_type_var` records that the app declares no such type; the
/// diagnostic was emitted when the binding was collected.
const ForClauseAliasBinding = struct {
    /// Exact declaration locator in the platform root. Names are consulted
    /// only while resolving the app-side declaration at the language boundary;
    /// copied occurrences match this declaration identity thereafter.
    platform_alias_stmt_idx: CIR.Statement.Idx,
    /// Resolved platform-store roots replaced during cross-module copying.
    platform_alias_var: Var,
    platform_identity_var: Var,
    /// Declaration identity shared by every application of this alias.
    platform_alias_source: copy_import.AliasSource,
    /// Exact app declaration chosen for this alias and the eager local copy
    /// step that instantiated it. Both are absent when lookup failed.
    app_type_stmt: ?CIR.Statement.Idx,
    app_instantiation_step: ?u32,
    app_type_var: ?Var,
};

fn forClauseAliasBinding(bindings: []const ForClauseAliasBinding, platform_alias_stmt_idx: CIR.Statement.Idx) ?ForClauseAliasBinding {
    for (bindings) |binding| {
        if (binding.platform_alias_stmt_idx == platform_alias_stmt_idx) return binding;
    }
    return null;
}

fn forClauseAliasBindingForIdentity(bindings: []const ForClauseAliasBinding, platform_identity_var: Var) ?ForClauseAliasBinding {
    for (bindings) |binding| {
        if (binding.platform_identity_var == platform_identity_var) return binding;
    }
    return null;
}

/// Bind every for-clause alias of the platform's requires clause to the app's
/// own type declaration, instantiating each declaration once so all
/// requirements that mention an alias share one binder.
fn collectForClauseAliasBindings(
    self: *Self,
    input: PlatformRequirementInput,
    env: *Env,
    bindings: *std.ArrayListUnmanaged(ForClauseAliasBinding),
) std.mem.Allocator.Error!void {
    for (input.env.requires_types.items.items) |required_type| {
        const aliases = input.env.for_clause_aliases.sliceRange(required_type.type_aliases);
        for (aliases) |alias| {
            if (forClauseAliasBinding(bindings.items, alias.alias_stmt_idx) != null) continue;
            const alias_statement = input.env.store.getStatement(alias.alias_stmt_idx);
            if (alias_statement != .s_alias_decl) {
                if (builtin.mode == .Debug) {
                    std.debug.panic("platform requirement for-clause alias referenced a non-alias statement", .{});
                }
                unreachable;
            }
            const alias_anno = alias_statement.s_alias_decl.anno;
            const platform_alias_resolved = input.env.types.resolveVar(ModuleEnv.varFrom(alias.alias_stmt_idx));
            const platform_alias_content = platform_alias_resolved.desc.content;
            if (platform_alias_content != .alias) {
                if (builtin.mode == .Debug) {
                    std.debug.panic("platform requirement for-clause alias statement had no alias type", .{});
                }
                unreachable;
            }
            const platform_alias = platform_alias_content.alias;
            const platform_alias_source = copy_import.AliasSource{
                .origin_module = platform_alias.origin_module,
                .source_decl = platform_alias.source_decl.toOptional() orelse {
                    if (builtin.mode == .Debug) {
                        std.debug.panic("platform requirement for-clause alias had no source declaration", .{});
                    }
                    unreachable;
                },
            };
            const platform_identity_var = input.env.types.resolveVar(ModuleEnv.varFrom(alias_anno)).var_;
            const alias_ident = try self.copyPlatformIdent(input.env, alias.alias_name);

            const app_type_stmt = self.appTypeDeclByIdent(alias_ident) orelse {
                const value_region = self.topLevelValueRegionByIdent(alias_ident);
                const app_region = value_region orelse self.appModuleRegion();
                _ = try self.problems.appendProblem(self.gpa, .{ .platform_alias_not_found = .{
                    .expected_alias_ident = alias_ident,
                    .app_region = app_region,
                    .platform_region = input.env.store.getNodeRegion(ModuleEnv.nodeIdxFrom(alias.alias_stmt_idx)),
                    .ctx = if (value_region == null) .not_found else .found_but_not_type,
                } });
                try bindings.append(self.gpa, .{
                    .platform_alias_stmt_idx = alias.alias_stmt_idx,
                    .platform_alias_var = platform_alias_resolved.var_,
                    .platform_identity_var = platform_identity_var,
                    .platform_alias_source = platform_alias_source,
                    .app_type_stmt = null,
                    .app_instantiation_step = null,
                    .app_type_var = null,
                });
                continue;
            };

            const app_type_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(app_type_stmt));
            const app_type_copy = try self.instantiateVarWithMarkerCopy(
                ModuleEnv.varFrom(app_type_stmt),
                env,
                .{ .explicit = app_type_region },
                .{ .platform_alias_app_decl = .{
                    .platform_alias_statement = @intFromEnum(alias.alias_stmt_idx),
                    .app_declaration_node = @intFromEnum(app_type_stmt),
                } },
                .eager_support,
            );
            try bindings.append(self.gpa, .{
                .platform_alias_stmt_idx = alias.alias_stmt_idx,
                .platform_alias_var = platform_alias_resolved.var_,
                .platform_identity_var = platform_identity_var,
                .platform_alias_source = platform_alias_source,
                .app_type_stmt = app_type_stmt,
                .app_instantiation_step = app_type_copy.copy_step,
                .app_type_var = app_type_copy.var_,
            });
        }
    }
}

fn copyPlatformIdent(self: *Self, platform_env: *const ModuleEnv, ident: Ident.Idx) std.mem.Allocator.Error!Ident.Idx {
    return try self.cir.insertIdent(Ident.for_text(platform_env.getIdent(ident)));
}

fn appTypeDeclByIdent(self: *Self, ident: Ident.Idx) ?CIR.Statement.Idx {
    if (self.findLocalTypeDeclByNameInSpan(self.cir.type_decls, ident)) |stmt_idx| return stmt_idx;
    return self.findLocalTypeDeclByNameInSpan(self.cir.forward_type_decls, ident);
}

fn exposedAppDefByIdent(self: *Self, ident: Ident.Idx) ?CIR.Def.Idx {
    const node_idx = self.cir.getExposedValueNodeIndexById(ident) orelse return null;
    if (node_idx >= self.cir.store.nodes.len()) return null;
    const cir_node: CIR.Node.Idx = @enumFromInt(node_idx);
    if (self.cir.store.nodes.get(cir_node).tag != .def) return null;
    return @enumFromInt(node_idx);
}

/// Record every annotation that types a host-boundary value — a hosted
/// lambda or a `provides` def — so annotation generation keeps its rows as
/// written instead of implicitly opening output-position tag unions (see
/// `GenTypeAnnoCtx.AnnotationGenCtx.opening`).
fn collectHostBoundaryAnnotations(self: *Self) std.mem.Allocator.Error!void {
    self.host_boundary_annotations.clearRetainingCapacity();

    for (self.cir.provides_entries.items.items) |provides_entry| {
        const def_idx = provides_entry.local_def orelse continue;
        const def = self.cir.store.getDef(def_idx);
        const annotation_idx = def.annotation orelse continue;
        try self.host_boundary_annotations.put(self.gpa, annotation_idx, {});
    }

    // Hosted lambdas hoisted out of (possibly nested) type modules appear in
    // global_value_defs only, so scan both def lists (the set dedupes).
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        try self.recordHostBoundaryAnnotationIfHosted(def_idx);
    }
    for (self.cir.store.sliceDefs(self.cir.global_value_defs)) |def_idx| {
        try self.recordHostBoundaryAnnotationIfHosted(def_idx);
    }
}

fn recordHostBoundaryAnnotationIfHosted(self: *Self, def_idx: CIR.Def.Idx) std.mem.Allocator.Error!void {
    const def = self.cir.store.getDef(def_idx);
    const annotation_idx = def.annotation orelse return;
    if (self.cir.store.getExpr(def.expr) != .e_hosted_lambda) return;
    try self.host_boundary_annotations.put(self.gpa, annotation_idx, {});
}

fn topLevelDefByIdent(self: *Self, ident: Ident.Idx) ?CIR.Def.Idx {
    for (self.cir.store.sliceDefs(self.cir.top_level_value_defs)) |def_idx| {
        const def_ident = self.getPatternIdent(self.cir.store.getDef(def_idx).pattern) orelse continue;
        if (def_ident == ident) return def_idx;
    }
    return null;
}

fn topLevelValueRegionByIdent(self: *Self, ident: Ident.Idx) ?Region {
    if (self.topLevelDefByIdent(ident)) |def_idx| {
        return self.defPatternRegion(def_idx);
    }
    return self.topLevelTagConstructorRegionByIdent(ident);
}

fn topLevelTagConstructorRegionByIdent(self: *Self, ident: Ident.Idx) ?Region {
    for (0..self.cir.all_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.all_statements, stmt_offset);
        const stmt = self.cir.store.getStatement(stmt_idx);
        const anno_idx = switch (stmt) {
            .s_alias_decl => |alias| alias.anno,
            .s_nominal_decl => |nominal| nominal.anno,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => continue,
        };
        if (self.typeAnnoTagRegionByIdent(anno_idx, ident)) |region| return region;
    }
    return null;
}

fn typeAnnoTagRegionByIdent(self: *Self, anno_idx: CIR.TypeAnno.Idx, wanted: Ident.Idx) ?Region {
    const anno = self.cir.store.getTypeAnno(anno_idx);
    switch (anno) {
        .tag_union => |tag_union| {
            for (self.cir.store.sliceTypeAnnos(tag_union.tags)) |tag_idx| {
                if (self.typeAnnoTagRegionByIdent(tag_idx, wanted)) |region| return region;
            }
            if (tag_union.ext) |ext| return self.typeAnnoTagRegionByIdent(ext, wanted);
            return null;
        },
        .tag => |tag| {
            if (tag.name == wanted) {
                return self.cir.store.getTypeAnnoRegion(anno_idx);
            }
            for (self.cir.store.sliceTypeAnnos(tag.args)) |arg_idx| {
                if (self.typeAnnoTagRegionByIdent(arg_idx, wanted)) |region| return region;
            }
            return null;
        },
        .apply => |apply| {
            for (self.cir.store.sliceTypeAnnos(apply.args)) |arg_idx| {
                if (self.typeAnnoTagRegionByIdent(arg_idx, wanted)) |region| return region;
            }
            return null;
        },
        .record => |record| {
            for (self.cir.store.sliceAnnoRecordFields(record.fields)) |field_idx| {
                const field = self.cir.store.getAnnoRecordField(field_idx);
                if (self.typeAnnoTagRegionByIdent(field.ty, wanted)) |region| return region;
            }
            if (record.ext) |ext| return self.typeAnnoTagRegionByIdent(ext, wanted);
            return null;
        },
        .tuple => |tuple| {
            for (self.cir.store.sliceTypeAnnos(tuple.elems)) |elem_idx| {
                if (self.typeAnnoTagRegionByIdent(elem_idx, wanted)) |region| return region;
            }
            return null;
        },
        .@"fn" => |func| {
            for (self.cir.store.sliceTypeAnnos(func.args)) |arg_idx| {
                if (self.typeAnnoTagRegionByIdent(arg_idx, wanted)) |region| return region;
            }
            return self.typeAnnoTagRegionByIdent(func.ret, wanted);
        },
        .parens => |parens| return self.typeAnnoTagRegionByIdent(parens.anno, wanted),
        .rigid_var,
        .rigid_var_lookup,
        .underscore,
        .lookup,
        .malformed,
        => return null,
    }
}

fn defPatternRegion(self: *Self, def_idx: CIR.Def.Idx) Region {
    const def = self.cir.store.getDef(def_idx);
    return self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(def.pattern));
}

fn appModuleRegion(self: *Self) Region {
    if (self.cir.all_defs.span.len > 0) {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, 0);
        return self.defPatternRegion(def_idx);
    }
    if (self.cir.all_statements.span.len > 0) {
        const stmt_idx = self.cir.store.statementAt(self.cir.all_statements, 0);
        return self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(stmt_idx));
    }
    return Region.zero();
}

/// Check if a statement index is a for-clause alias statement.
/// For-clause alias statements are created during platform header processing
/// for type aliases like [Model : model] in the requires clause.
///
/// When these are looked up, we need to *not* instantiate the alias, so all
/// references in the module Point to the same var.
fn isForClauseAliasStatement(self: *Self, stmt_idx: CIR.Statement.Idx) bool {
    // Slice the for-clause alias statements and check if stmt_idx is in the list
    for (self.cir.for_clause_aliases.items.items) |for_clause| {
        if (stmt_idx == for_clause.alias_stmt_idx) {
            return true;
        }
    }
    return false;
}

fn generateForClauseAliasApplication(
    self: *Self,
    anno_var: Var,
    decl_var: Var,
    anno_arg_vars: []const Var,
    env: *Env,
) std.mem.Allocator.Error!void {
    const decl_resolved = self.types.resolveVar(decl_var).desc.content;
    const decl_alias = switch (decl_resolved) {
        .alias => |alias| alias,
        .err => {
            try self.markErroneous(anno_var);
            return;
        },
        .flex, .rigid, .field_presence, .structure => {
            std.debug.assert(false);
            try self.markErroneous(anno_var);
            return;
        },
    };

    try self.unifyWith(
        anno_var,
        try self.types.mkAliasWithSourceDeclAndBuiltinOrigin(
            decl_alias.ident,
            self.types.getAliasBackingVar(decl_alias),
            anno_arg_vars,
            decl_alias.origin_module,
            decl_alias.source_decl.toOptional(),
            decl_alias.source_decl.originIsBuiltin(),
        ),
        env,
    );
}

// repl //

/// Check an expr for the repl
pub fn checkExprRepl(self: *Self, expr_idx: CIR.Expr.Idx) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    self.beginTypecheck();

    try ensureTypeStoreIsFilled(self);
    try self.reserveWhereAliasDeclarationPublications();

    // Record which annotations type host-boundary values before any
    // annotation is generated (their rows are kept as written rather than
    // implicitly opened by polarity).
    try self.collectHostBoundaryAnnotations();

    // Copy builtin types into this module's type store
    try self.copyBuiltinTypes();

    // Create a solver env
    var env = try self.env_pool.acquire();
    defer self.env_pool.release(env);
    std.debug.assert(env.rank() == .generalized);

    // First, iterate over the statements, generating types for each type declaration
    for (0..self.cir.builtin_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.builtin_statements, stmt_offset);
        // If the statement is a type declaration, then generate the it's type
        // The resulting generalized type is saved at the type var slot at `stmt_idx`
        try self.generateStmtTypeDeclType(stmt_idx, &env);
    }

    // Validate nominal declaration recursion before checking values.
    try self.finalizeTypeDeclarationValidity();

    // Set the rank to be outermost
    try env.var_pool.pushRank();
    std.debug.assert(env.rank() == .outermost);

    // Check the expr
    _ = try self.checkExpr(expr_idx, &env, Expected.none());

    try self.finalizeTypes(&env, .{ .repl_expr = expr_idx });
    try self.reportPolymorphicConstrainedExpr(expr_idx);

    // Check for infinite types, at the expression root and at every binding
    // root the expression contains
    try self.checkForInfiniteType(CIR.Expr.Idx, expr_idx);
    try self.checkBindingRootsForInfiniteTypes();
    try self.recheckNominalConstructorBackings(&env);
    try self.finalizeExpectEffectSlots();

    try self.finalizeDefaultDecisionDrafts();
    try self.finalizeWhereAliasExpansions();
    try self.rebuildCheckedBoundaryWhereMethodState();
    try self.finalizeMethodOutputPublications();
    try self.finalizeBindingSchemeNodes();

    if (self.pending_generalized_target_share_candidates.items.len != 0) {
        @panic("checked REPL expression retained generalized target-share candidates past every owning boundary");
    }
    self.debugAssertNominalDeclTableComplete();
    try self.validateProducedW6bState();
    self.finishTypecheck(.checked_repl);
}

/// Check a REPL expression, also type-checking any definitions (for local type declarations)
pub fn checkExprReplWithDefs(self: *Self, expr_idx: CIR.Expr.Idx) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    self.beginTypecheck();

    try ensureTypeStoreIsFilled(self);
    try self.reserveWhereAliasDeclarationPublications();

    // Record which annotations type host-boundary values before any
    // annotation is generated (their rows are kept as written rather than
    // implicitly opened by polarity).
    try self.collectHostBoundaryAnnotations();

    // Copy builtin types into this module's type store
    try self.copyBuiltinTypes();

    // Create a solver env
    var env = try self.env_pool.acquire();
    defer self.env_pool.release(env);
    std.debug.assert(env.rank() == .generalized);

    // First, iterate over the statements, generating types for each type declaration
    // Note that any types generated will be generalized
    for (0..self.cir.builtin_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.builtin_statements, stmt_offset);
        try self.generateStmtTypeDeclType(stmt_idx, &env);
    }

    // Reserve canonical type constructors before generating any declaration
    // bodies. This mirrors file checking: REPL-with-defs accepts local type
    // declarations, and block checking deliberately skips them after this
    // preprocessing phase.
    for (0..self.cir.type_decls.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.type_decls, stmt_offset);
        const stmt = self.cir.store.getStatement(stmt_idx);
        const stmt_var = ModuleEnv.varFrom(stmt_idx);
        switch (stmt) {
            .s_alias_decl => |alias| {
                try self.setVarRank(stmt_var, &env);
                try self.predeclareAliasDecl(stmt_var, alias, &env);
            },
            .s_nominal_decl => |nominal| {
                try self.setVarRank(stmt_var, &env);
                try self.predeclareNominalDecl(stmt_var, nominal, &env);
            },
            else => {},
        }
    }

    // Generate every local declaration exactly once before checking the REPL
    // definition groups. In particular, reusable where aliases must publish
    // their settlement rows even when the expression never references them.
    for (0..self.cir.all_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.all_statements, stmt_offset);
        const stmt = self.cir.store.getStatement(stmt_idx);
        const stmt_var = ModuleEnv.varFrom(stmt_idx);
        switch (stmt) {
            .s_alias_decl, .s_nominal_decl, .s_where_alias_decl => {
                _ = try self.ensureTypeDeclGenerated(stmt_idx, &env);
            },
            .s_runtime_error => {
                try self.setVarRank(stmt_var, &env);
                try self.markErroneous(stmt_var);
            },
            .s_type_anno => unreachable,
            else => {},
        }
    }

    // Validate nominal declaration recursion before checking values.
    try self.finalizeTypeDeclarationValidity();

    // Initialize top_level_ptrns with any defs from local type declarations
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        const def = self.cir.store.getDef(def_idx);
        self.setTopLevelPattern(def.pattern, DefProcessed{
            .def_idx = def_idx,
            .def_name = null,
            .status = .not_processed,
        });
    }

    // Set the rank to be outermost
    try env.var_pool.pushRank();
    std.debug.assert(env.rank() == .outermost);

    // Type-check defs from local type declarations (their associated blocks),
    // as dependency-ordered binding groups just like file checking.
    try self.setupCheckOrder();
    try self.predeclareAnnotatedDefSchemes(&env);
    const group_count: u32 = @intCast(self.check_order.?.sccs.len);
    var group_index: u32 = 0;
    while (group_index < group_count) : (group_index += 1) {
        try self.ensureGroupChecked(group_index, &env);
        std.debug.assert(env.rank() == .outermost);
    }

    // Check the expr
    _ = try self.checkExpr(expr_idx, &env, Expected.none());

    // Check any accumulated constraints
    try self.checkAllConstraints(&env);
    try self.resolvePendingTupleAccesses(&env, false);
    try self.checkAllConstraints(&env);
    try self.resolveNumericLiteralsFromContext(&env);
    // Destructure binders bind before the defaulting rounds so defaulting
    // sees them through the row (see `judgeRecordDestructBinds`).
    try self.judgeRecordDestructBinds(&env);
    try self.finalizeLiteralDefaults(&env);

    // After finalizing literal defaults, resolve any remaining deferred static
    // dispatch constraints: committing a default can generate deferred
    // method_call constraints (e.g. Dec.to_str returns Str). Without this step,
    // the return type of methods on numerics stays an unconstrained flex var,
    // causing incorrect .zst layouts.
    if (env.deferred_static_dispatch_constraints.items.items.len > 0) {
        try self.checkStaticDispatchConstraints(&env, true);
        try self.checkAllConstraints(&env);
    }

    // After solving all deferred constraints, check every binding root
    // (top-level defs and local bindings) for infinite types
    try self.checkBindingRootsForInfiniteTypes();

    // Check the result expression itself, matching checkExprRepl: its type may
    // have incompatible constraints (e.g. !3) or be infinite/anonymously
    // recursive, neither of which is covered by the per-def checks above.
    const expr_var = ModuleEnv.varFrom(expr_idx);
    try self.checkPendingDefaults(&env);
    try self.judgeFieldKindsAtBoundary(&env);
    _ = try self.checkFlexVarConstraintCompatibility(expr_var, &env, true, .{
        .open_literal_driver = self.openLiteralDriverForRawVar(expr_var),
    });
    try self.validateResolvedOpenNumeralLiterals(&env);
    try self.checkFinalGeneratedCodecConstraints(&env);
    try self.resolvePendingTupleAccesses(&env, true);
    try self.checkAllConstraints(&env);
    try self.checkDefaultRestrictions();
    // Kind defaulting, mirroring `finalizeTypes` (this path inlines its own
    // finalize sequence): last, after every judgment above, for the same
    // reasons documented there.
    try self.defaultLiteralFieldKinds(&env);
    try self.checkForInfiniteType(CIR.Expr.Idx, expr_idx);
    try self.recheckNominalConstructorBackings(&env);

    try self.reportPolymorphicConstrainedExpr(expr_idx);
    try self.poisonErroneousValueUses();
    try self.finalizeExpectEffectSlots();

    try self.finalizeDefaultDecisionDrafts();
    try self.finalizeWhereAliasExpansions();
    try self.rebuildCheckedBoundaryWhereMethodState();
    try self.finalizeMethodOutputPublications();
    try self.finalizeBindingSchemeNodes();

    if (self.pending_generalized_target_share_candidates.items.len != 0) {
        @panic("checked REPL expression retained generalized target-share candidates past every owning boundary");
    }
    self.debugAssertNominalDeclTableComplete();
    try self.validateProducedW6bState();
    self.finishTypecheck(.checked_repl);
}

// defs //

/// Check the types for a single definition
fn checkDef(self: *Self, def_idx: CIR.Def.Idx, env: *Env) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const def = self.cir.store.getDef(def_idx);

    const saved_checking_executable_root = self.checking_executable_root;
    self.checking_executable_root = self.isExecutableRootDef(def_idx);
    defer self.checking_executable_root = saved_checking_executable_root;

    if (self.topLevelPattern(def.pattern)) |processing_def| {
        if (processing_def.status == .processed) {
            // If we've already processed this def, return immediately
            return;
        }
    }

    // Scope the ambiguity-judgment cursors to this def: a generalization event
    // inside it judges only candidates recorded while checking it, against a
    // pinnable frontier built from its own lambda params and open literals.
    // Saved/restored (not reset) because groups check defs back to back and a
    // dispatch obligation can nest another group's defs at a boundary.
    const saved_ambiguity_candidates_def_start = self.ambiguity_candidates_def_start;
    self.ambiguity_candidates_def_start = self.ambiguity_candidates.items.len;
    defer self.ambiguity_candidates_def_start = saved_ambiguity_candidates_def_start;
    const saved_checked_lambda_params_def_start = self.checked_lambda_params_def_start;
    self.checked_lambda_params_def_start = self.checked_lambda_params.items.len;
    defer self.checked_lambda_params_def_start = saved_checked_lambda_params_def_start;
    const saved_open_literal_vars_def_start = self.open_literal_vars_def_start;
    self.open_literal_vars_def_start = self.open_literal_vars.items.len;
    defer self.open_literal_vars_def_start = saved_open_literal_vars_def_start;

    // Make as processing
    const def_name = self.getPatternIdent(def.pattern);
    self.setTopLevelPattern(def.pattern, .{
        .def_idx = def_idx,
        .def_name = def_name,
        .status = .processing,
    });

    // Check if this expr is one that should be generalized
    const def_var = ModuleEnv.varFrom(def_idx);
    const ptrn_var = ModuleEnv.varFrom(def.pattern);
    const expr_var = ModuleEnv.varFrom(def.expr);

    // Ensure we're at the rank the driver checks defs at: the outermost rank,
    // or a recursive group's shared frame (whose members are checked inside
    // it), or a nested group frame opened at a dispatch boundary.
    std.debug.assert(env.rank() == self.currentDefCheckRank());

    // Whether the driver already ranked this def's pattern in the current
    // recursive group's shared frame (so in-group forward references can link
    // to it monomorphically before this def's body is checked).
    const group_prechecked = self.defInCurrentRecursiveGroup(def_idx);

    if (!group_prechecked) {
        // Set the ptrn and expr rank
        try self.setVarRank(def_var, env);
        try self.setVarRank(ptrn_var, env);

        const def_pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(def.pattern)) .match_branch else .bound;

        // Check the pattern
        try self.checkPattern(def.pattern, def_pattern_ctx, env);
    }

    // Extract function name from the pattern (for better error messages)
    const saved_func_name = self.enclosing_func_name;
    self.enclosing_func_name = def_name;
    defer self.enclosing_func_name = saved_func_name;

    // Check the annotation, if it exists
    const platform_required = self.platform_required_defs.get(def_idx);
    const expectation = blk: {
        if (def.annotation) |annotation_idx| {
            break :blk Expected.fromAnnotation(annotation_idx, .{
                .kind = .top_level_def,
                .node = @intFromEnum(def_idx),
            });
        } else if (platform_required) |required| {
            break :blk Expected.none().withExpectedType(.{
                .var_ = required.expected_var,
                .context = .{ .platform_requirement = .{ .required_ident = required.required_ident, .platform_region = required.platform_region } },
                .marker_authority = .{ .anchored = .{ .copy_occurrence = required.expected_anchor } },
                .status = .established,
            });
        } else {
            break :blk Expected.none();
        }
    };

    const exhaustiveness_scope = self.exhaustiveness_context.enterCompileTimeRoot();
    defer exhaustiveness_scope.leave();

    // Infer types for the body, checking against the instantiated annotation.
    // Ordinary top-level constants are already compile-time roots, so nested
    // hoisted roots inside them would duplicate compile-time work. Top-level
    // functions are not evaluated as data constants, so their bodies may still
    // contain top-level-equivalent local values.
    const def_expr = self.cir.store.getExpr(def.expr);
    const def_is_function = isFunctionDef(&self.cir.store, def_expr);
    const def_expectation = if (def_is_function)
        expectation.withHoistPosition(.eligible)
    else
        expectation.forComptimeRoot();
    const saved_checking_immediate_callee = self.checking_immediate_callee;
    if (self.checking_executable_root) self.checking_immediate_callee = true;
    defer self.checking_immediate_callee = saved_checking_immediate_callee;
    self.checking_binding_rhs = true;
    self.checking_binding_rhs_pattern = def.pattern;
    const saved_active_scheme_root = self.active_scheme_root;
    // A singleton value definition has no scheme boundary and therefore owns
    // no side-table candidates. Recursive groups still provisionally own every
    // member here because the shared group boundary decides which roots
    // actually generalize. A singleton closure delegates that boundary to its
    // inner lambda, so candidates must use the lambda's owner from the start;
    // recursive SCC members continue to use the def expression root captured
    // by their shared group boundary.
    const scheme_owner = if (!group_prechecked and def_expr == .e_closure)
        ModuleEnv.varFrom(def_expr.e_closure.lambda_idx)
    else
        expr_var;
    self.active_scheme_root = if (def_is_function or group_prechecked) scheme_owner else saved_active_scheme_root;
    defer self.active_scheme_root = saved_active_scheme_root;
    const def_does_fx = (try self.checkExpr(def.expr, env, def_expectation)).does_fx;
    // The annotation bounds the definition: a tag the body produced beyond an
    // implicitly opened union is an error (design.md "Polarity").
    if (def.annotation) |annotation_idx| {
        // A function, a pure signature, and a value alias generalize
        // regardless of any written `..`, so a `..` in their output
        // positions is redundant; on a value it is the opt-in to a
        // quantified row.
        const is_value_alias = def_expr == .e_lookup_local or def_expr == .e_lookup_external;
        const generalizes_regardless = def_is_function or def_expr == .e_anno_only or is_value_alias;
        try self.auditImplicitOpenExts(annotation_idx, generalizes_regardless);

        // A top-level value binding that does not generalize (not a function,
        // not a pure signature, not a value alias, and no written type
        // variable) shares its implicitly opened rows weakly with every use;
        // whatever is still open after the module solves is grounded to `[]`
        // (`closeWeakValueImplicitOpenExts`).
        if (!generalizes_regardless and
            !self.cir.store.getAnnotation(annotation_idx).mentions_type_var)
        {
            if (self.annotation_implicit_open_exts.get(annotation_idx)) |range| {
                if (range.len > 0) try self.weak_value_implicit_open_ext_ranges.append(self.gpa, range);
            }
        }
    }
    if (def.annotation != null) {
        if (platform_required) |required| {
            _ = try self.unifyInContext(
                required.expected_var,
                ModuleEnv.varFrom(def.expr),
                env,
                .{ .platform_requirement = .{ .required_ident = required.required_ident, .platform_region = required.platform_region } },
            );
        }
    }
    if (def_does_fx) {
        _ = try self.problems.appendProblem(self.gpa, .{ .effectful_top_level = .{
            .region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(def.expr)),
        } });
        try self.markErroneous(expr_var);
    }
    // A platform requirement is the def's explicit expected type even when the
    // source has no annotation. Only truly unconstrained crashing defs default
    // to unit; otherwise this would overwrite the requirement type with `{}`.
    if (def.annotation == null and platform_required == null and self.exprAlwaysCrashes(def.expr)) {
        try self.unifyWith(expr_var, .{ .structure = .empty_record }, env);
    }
    if (def.annotation == null and self.erroneous_value_exprs.contains(def.expr)) {
        try self.erroneous_value_patterns.put(self.gpa, def.pattern, {});
    }
    try self.closeAbsentConstructedPayloadVars(def.expr, expr_var);
    if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(def.expr)) and
        !self.defInCurrentRecursiveGroup(def_idx) and
        !self.isCompileTimeExecutableRootDef(def_idx))
    {
        try self.checkEffectfulFunctionName(def.pattern, def.expr);
    }

    // Unify the ptrn and the expr
    const ptrn_result = try self.unify(ptrn_var, expr_var, env);

    // Unify the def and ptrn
    _ = try self.unify(def_var, ptrn_var, env);

    // Scheme identity follows stable source vars, never the mutable class
    // representative. Publish every binding alias explicitly after the
    // ordinary pattern/body unifications have completed.
    try self.bindTypeSchemeVar(expr_var, ptrn_var);
    try self.bindTypeSchemeVar(expr_var, def_var);
    if (self.predeclaredSchemeVar(def_idx)) |predeclared_scheme_var| {
        try self.bindTypeSchemeVar(expr_var, predeclared_scheme_var);
    }
    if (ptrn_result.isEstablished()) {
        const def_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(def.pattern));
        _ = try self.checkDestructureExhaustiveness(def.pattern, def.expr, expr_var, env, def_region);
        if (self.cir.store.getPattern(def.pattern) != .assign) {
            try self.recordHoistPatternExtractionProvenanceHelp(def.pattern, def.expr, def.pattern, .immediate);
        }
    }

    // Mark as processed
    self.setTopLevelPattern(def.pattern, .{
        .def_idx = def_idx,
        .def_name = def_name,
        .status = .processed,
    });
}

fn isExecutableRootDef(self: *const Self, def_idx: CIR.Def.Idx) bool {
    for (self.executable_root_defs.items) |root_def_idx| {
        if (root_def_idx == def_idx) return true;
    }
    return false;
}

fn isCompileTimeExecutableRootDef(self: *const Self, def_idx: CIR.Def.Idx) bool {
    for (self.compile_time_executable_roots.items) |root| {
        if (root.def == def_idx) return true;
    }
    return false;
}

// dependency-ordered driver //

/// Compute the module's dependency-ordered checking plan: the SCC condensation
/// of the name-reference graph in deterministic topological order. Transient—
/// owned by this Check instance and freed in deinit, never part of the checked
/// module.
fn setupCheckOrder(self: *Self) std.mem.Allocator.Error!void {
    if (self.check_order != null) return;
    self.check_order = try DependencyGraph.computeCheckOrder(self.cir, self.cir.all_defs, self.gpa);
    const sccs = self.check_order.?.sccs;
    try self.group_states.appendNTimes(self.gpa, .pending, sccs.len);
    for (sccs, 0..) |scc, group_index| {
        for (scc.defs) |def_idx| {
            self.setDefGroupIndex(def_idx, @intCast(group_index));
        }
    }
}

fn activePredeclaredAnnoEventScope(self: *Self) ?*PredeclaredAnnoEventScope {
    if (self.predeclared_anno_event_scopes.items.len == 0) return null;
    const scope = &self.predeclared_anno_event_scopes.items[self.predeclared_anno_event_scopes.items.len - 1];
    return if (scope.kind == .suspended) null else scope;
}

fn beginPredeclaredAnnoEventScope(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
) Allocator.Error!bool {
    // Any annotation generated on demand while another producer stream is
    // active belongs to that dependency, not to the caller. Represent the
    // suspension explicitly so nested scopes compose and cannot accidentally
    // resume the parent early.
    if (self.predeclared_anno_event_scopes.items.len != 0) {
        try self.predeclared_anno_event_scopes.append(self.gpa, .{
            .kind = .suspended,
            .draft_index = null,
            .annotation_idx = annotation_idx,
            .events_start = @intCast(self.predeclared_anno_events.items.len),
            .anchor_node = @intFromEnum(annotation_idx),
        });
        return true;
    }

    const draft_index = self.predeclared_anno_draft_by_annotation.get(annotation_idx) orelse return false;
    const draft = &self.predeclared_anno_drafts.items[draft_index];
    const kind: PredeclaredAnnoEventScopeKind = switch (draft.state) {
        .recording_prepass => .record,
        .awaiting_body => .replay,
        .awaiting_orphan_copy, .rebased, .marker_free => return false,
    };
    try self.predeclared_anno_event_scopes.append(self.gpa, .{
        .kind = kind,
        .draft_index = draft_index,
        .annotation_idx = annotation_idx,
        .events_start = @intCast(self.predeclared_anno_events.items.len),
        .anchor_node = @intFromEnum(annotation_idx),
    });
    return true;
}

fn abortPredeclaredAnnoEventScope(self: *Self) void {
    const scope = self.predeclared_anno_event_scopes.pop() orelse
        std.debug.panic("predeclared annotation event scope stack underflow", .{});
    self.predeclared_anno_events.shrinkRetainingCapacity(scope.events_start);
}

fn freezePredeclaredAnnoEvent(event: *PredeclaredAnnoGenEvent, types: *types_mod.Store) void {
    // Raw producer ids are the durable transient authority. Resolving here
    // would collapse distinct prepass occurrences before they can be joined
    // to their exact regenerated events.
    _ = event;
    _ = types;
}

fn predeclaredAnnoEventEndpointTag(endpoint: PredeclaredAnnoGenEndpoint) std.meta.Tag(PredeclaredAnnoGenEndpoint) {
    return std.meta.activeTag(endpoint);
}

fn appendPredeclaredAnnoGenEventWithWitness(
    self: *Self,
    key: PredeclaredAnnoGenEventKey,
    endpoint: PredeclaredAnnoGenEndpoint,
    source_var: ?Var,
    source_constraint_index: ?u32,
) Allocator.Error!void {
    const scope = self.activePredeclaredAnnoEventScope() orelse return;
    if (scope.kind == .replay) {
        const draft = self.predeclared_anno_drafts.items[scope.draft_index.?];
        const body_offset = self.predeclared_anno_events.items.len - scope.events_start;
        if (body_offset >= draft.prepass_events.len) {
            std.debug.panic("regenerated annotation emitted an extra producer event", .{});
        }
        const expected = self.predeclared_anno_events.items[draft.prepass_events.start + body_offset];
        if (!std.meta.eql(expected.key, key) or
            predeclaredAnnoEventEndpointTag(expected.endpoint) != predeclaredAnnoEventEndpointTag(endpoint))
        {
            std.debug.panic("regenerated annotation producer event stream diverged", .{});
        }
        if (expected.source_var != source_var) {
            std.debug.panic("regenerated annotation instantiation changed its exact template source", .{});
        }
        if (expected.source_constraint_index != source_constraint_index) {
            std.debug.panic("regenerated annotation instantiation changed its exact template constraint", .{});
        }
    }
    try self.predeclared_anno_events.append(self.gpa, .{
        .key = key,
        .endpoint = endpoint,
        .source_var = source_var,
        .source_constraint_index = source_constraint_index,
    });
}

fn appendPredeclaredAnnoGenEvent(
    self: *Self,
    key: PredeclaredAnnoGenEventKey,
    endpoint: PredeclaredAnnoGenEndpoint,
    source_var: ?Var,
) Allocator.Error!void {
    return self.appendPredeclaredAnnoGenEventWithWitness(key, endpoint, source_var, null);
}

fn nextPredeclaredAnnoEventOrdinal(
    self: *Self,
    anchor_node: u32,
    kind: PredeclaredAnnoGenEventKind,
    slot: u32,
) u32 {
    const scope = self.activePredeclaredAnnoEventScope() orelse return 0;
    var count: u32 = 0;
    for (self.predeclared_anno_events.items[scope.events_start..]) |event| {
        if (event.key.anchor_node == anchor_node and
            event.key.kind == @intFromEnum(kind) and
            event.key.slot == slot)
        {
            count = std.math.add(u32, count, 1) catch
                std.debug.panic("annotation producer event ordinal overflowed u32", .{});
        }
    }
    return count;
}

fn recordPredeclaredAnnoVarEvent(
    self: *Self,
    kind: PredeclaredAnnoGenEventKind,
    slot: u32,
    var_: Var,
) Allocator.Error!void {
    const scope = self.activePredeclaredAnnoEventScope() orelse return;
    const ordinal = self.nextPredeclaredAnnoEventOrdinal(scope.anchor_node, kind, slot);
    try self.appendPredeclaredAnnoGenEvent(.{
        .anchor_node = scope.anchor_node,
        .kind = @intFromEnum(kind),
        .slot = slot,
        .ordinal = ordinal,
    }, .{ .var_ = var_ }, null);
}

fn recordPredeclaredAnnoConstraintEvent(
    self: *Self,
    kind: PredeclaredAnnoGenEventKind,
    slot: u32,
    constraint_index: u32,
) Allocator.Error!void {
    const scope = self.activePredeclaredAnnoEventScope() orelse return;
    const ordinal = self.nextPredeclaredAnnoEventOrdinal(scope.anchor_node, kind, slot);
    try self.appendPredeclaredAnnoGenEvent(.{
        .anchor_node = scope.anchor_node,
        .kind = @intFromEnum(kind),
        .slot = slot,
        .ordinal = ordinal,
    }, .{ .constraint_index = constraint_index }, null);
}

fn recordPredeclaredAnnoMarkerEvents(
    self: *Self,
    slot: u32,
    constraint_index: u32,
) Allocator.Error!void {
    const scope = self.activePredeclaredAnnoEventScope() orelse return;
    if (constraint_index >= self.types.static_dispatch_constraints.items.items.len) {
        std.debug.panic("annotation producer attempted to record an out-of-range retained constraint", .{});
    }
    const constraint = self.types.static_dispatch_constraints.items.items[constraint_index];
    const marker_start: u32 = @intFromEnum(constraint.where_method_markers.start);
    for (0..constraint.where_method_markers.len()) |raw_offset| {
        const offset: u32 = @intCast(raw_offset);
        const marker_index = std.math.add(u32, marker_start, offset) catch
            std.debug.panic("annotation producer marker index overflowed u32", .{});
        if (marker_index >= self.types.where_method_marker_contracts.items.items.len) {
            std.debug.panic("annotation producer marker escaped its pool", .{});
        }
        const marker = self.types.where_method_marker_contracts.items.items[marker_index];
        try self.appendPredeclaredAnnoGenEvent(.{
            .anchor_node = scope.anchor_node,
            .kind = @intFromEnum(PredeclaredAnnoGenEventKind.retained_marker),
            .slot = slot,
            .ordinal = offset,
        }, .{ .marker = .{
            .constraint_index = constraint_index,
            .contract_offset = offset,
            .contract_index = marker_index,
            .path_start = marker.path_start,
            .path_len = marker.path_len,
        } }, null);
        for (0..marker.path_len) |raw_path_offset| {
            try self.appendPredeclaredAnnoGenEvent(.{
                .anchor_node = scope.anchor_node,
                .kind = @intFromEnum(PredeclaredAnnoGenEventKind.retained_marker_path),
                .slot = offset,
                .ordinal = @intCast(raw_path_offset),
            }, .{ .marker = .{
                .constraint_index = constraint_index,
                .contract_offset = offset,
                .contract_index = marker_index,
                .path_start = marker.path_start,
                .path_len = marker.path_len,
            } }, null);
        }
    }
}

fn setPredeclaredAnnoEventAnchor(self: *Self, anchor_node: u32) ?u32 {
    const scope = self.activePredeclaredAnnoEventScope() orelse return null;
    const previous = scope.anchor_node;
    scope.anchor_node = anchor_node;
    return previous;
}

fn restorePredeclaredAnnoEventAnchor(self: *Self, previous: ?u32) void {
    const value = previous orelse return;
    const scope = self.activePredeclaredAnnoEventScope() orelse
        std.debug.panic("annotation producer scope disappeared while restoring its anchor", .{});
    scope.anchor_node = value;
}

fn recordPredeclaredAnnoInstantiationEvents(
    self: *Self,
    pairs: *std.ArrayListUnmanaged(InstantiationProofPair),
    constraint_pairs: *std.ArrayListUnmanaged(InstantiationProofConstraintPair),
) Allocator.Error!void {
    const scope = self.activePredeclaredAnnoEventScope() orelse return;
    self.canonicalizeWhereMarkerInstantiationPairs(pairs);
    const slot = scope.instantiation_slot;
    scope.instantiation_slot = std.math.add(u32, scope.instantiation_slot, 1) catch
        std.debug.panic("annotation producer instantiation slot overflowed u32", .{});
    for (pairs.items, 0..) |pair, ordinal| {
        try self.appendPredeclaredAnnoGenEvent(.{
            .anchor_node = scope.anchor_node,
            .kind = @intFromEnum(PredeclaredAnnoGenEventKind.instantiation_pair),
            .slot = slot,
            .ordinal = @intCast(ordinal),
        }, .{ .var_ = @enumFromInt(pair.raw_destination_var) }, @enumFromInt(pair.raw_source_var));
    }
    std.mem.sortUnstable(InstantiationProofConstraintPair, constraint_pairs.items, {}, struct {
        fn lessThan(_: void, a: InstantiationProofConstraintPair, b: InstantiationProofConstraintPair) bool {
            if (a.source_constraint_index != b.source_constraint_index) {
                return a.source_constraint_index < b.source_constraint_index;
            }
            return a.destination_constraint_index < b.destination_constraint_index;
        }
    }.lessThan);
    var write: usize = 0;
    for (constraint_pairs.items) |pair| {
        if (write != 0 and
            constraint_pairs.items[write - 1].source_constraint_index == pair.source_constraint_index)
        {
            if (constraint_pairs.items[write - 1].destination_constraint_index != pair.destination_constraint_index) {
                std.debug.panic("one instantiated source constraint mapped to two destination constraints", .{});
            }
            continue;
        }
        constraint_pairs.items[write] = pair;
        write += 1;
    }
    constraint_pairs.items.len = write;
    for (constraint_pairs.items, 0..) |pair, ordinal| {
        try self.appendPredeclaredAnnoGenEventWithWitness(.{
            .anchor_node = scope.anchor_node,
            .kind = @intFromEnum(PredeclaredAnnoGenEventKind.instantiation_constraint),
            .slot = slot,
            .ordinal = @intCast(ordinal),
        }, .{ .constraint_index = pair.destination_constraint_index }, null, pair.source_constraint_index);
    }
}

fn finishPredeclaredAnnoEventScope(self: *Self) Allocator.Error!void {
    const scope = self.predeclared_anno_event_scopes.pop() orelse
        std.debug.panic("predeclared annotation event scope stack underflow", .{});
    if (scope.kind == .suspended) {
        if (self.predeclared_anno_events.items.len != scope.events_start) {
            std.debug.panic("suspended annotation generation emitted producer events", .{});
        }
        return;
    }

    const draft_index = scope.draft_index.?;
    const draft = &self.predeclared_anno_drafts.items[draft_index];
    const event_count = self.predeclared_anno_events.items.len - scope.events_start;
    if (event_count > std.math.maxInt(u32)) {
        std.debug.panic("annotation producer event stream exceeded u32", .{});
    }
    for (self.predeclared_anno_events.items[scope.events_start..]) |*event| {
        freezePredeclaredAnnoEvent(event, self.types);
    }

    switch (scope.kind) {
        .record => {
            if (draft.state != .recording_prepass) {
                std.debug.panic("annotation prepass event scope had the wrong draft state", .{});
            }
            draft.prepass_events = .{
                .start = scope.events_start,
                .len = @intCast(event_count),
            };
            draft.prepass_root = ModuleEnv.varFrom(draft.annotation_idx);
            draft.state = .awaiting_orphan_copy;
        },
        .replay => {
            if (draft.state != .awaiting_body or event_count != draft.prepass_events.len) {
                std.debug.panic("regenerated annotation producer stream was not total", .{});
            }
            const regenerated_events = VarPairRange{
                .start = scope.events_start,
                .len = @intCast(event_count),
            };
            try self.rebasePredeclaredAnnotationDraft(draft_index, regenerated_events);
            draft.regenerated_events = regenerated_events;
            draft.state = .rebased;
        },
        .suspended => unreachable,
    }
}

fn beginPredeclaredAnnotationDraft(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
) Allocator.Error!u32 {
    const entry = try self.predeclared_anno_draft_by_annotation.getOrPut(self.gpa, annotation_idx);
    if (entry.found_existing) {
        std.debug.panic("one annotation was predeclared more than once", .{});
    }
    errdefer _ = self.predeclared_anno_draft_by_annotation.remove(annotation_idx);
    const index: u32 = @intCast(self.predeclared_anno_drafts.items.len);
    try self.predeclared_anno_drafts.append(self.gpa, .{ .annotation_idx = annotation_idx });
    entry.value_ptr.* = index;
    return index;
}

fn finishPredeclaredAnnotationOrphanCopy(
    self: *Self,
    draft_index: u32,
    predicted_step: u32,
) void {
    const draft = &self.predeclared_anno_drafts.items[draft_index];
    if (draft.state != .awaiting_orphan_copy) {
        std.debug.panic("predeclared annotation orphan copy preceded its producer stream", .{});
    }
    const prepass_events = self.predeclared_anno_events.items[draft.prepass_events.start..][0..draft.prepass_events.len];
    for (self.predeclared_anno_orphan_pairs.items[draft.orphan_pairs.start..][0..draft.orphan_pairs.len]) |pair| {
        const covered = for (prepass_events) |event| {
            if (event.endpoint == .var_ and event.endpoint.var_ == pair.old_var) break true;
        } else false;
        if (!covered) {
            std.debug.panic("annotation producer event stream omitted a predeclared orphan source var", .{});
        }
    }
    const steps_len = self.cir.where_marker_copy_steps.items.items.len;
    if (predicted_step >= steps_len) {
        std.debug.panic("predeclared annotation orphan copy lost its reserved step", .{});
    }
    const step = self.cir.where_marker_copy_steps.items.items[predicted_step];
    const step_kind = step.decodedKind() orelse
        std.debug.panic("predeclared annotation orphan copy published an invalid step kind", .{});
    if (step_kind == .discarded) {
        // Marker-free predeclarations publish no durable lineage step, but
        // their exact producer relation is still required to replay an early
        // use against body-discovered dispatch requirements. Keep the
        // checker-local stream until regeneration; it is discarded with the
        // Check and never serialized.
        if (draft.orphan_pairs.len == 0) {
            std.debug.panic("predeclared annotation orphan copy emitted no complete relation", .{});
        }
        draft.state = .awaiting_body;
        return;
    }
    if (step_kind == .reserved) {
        std.debug.panic("predeclared annotation orphan copy left its step reserved", .{});
    }
    if (step_kind != .predeclared_annotation or
        step.origin.predeclared_annotation.node != @intFromEnum(draft.annotation_idx))
    {
        std.debug.panic("predeclared annotation orphan copy published the wrong finite origin", .{});
    }
    for (self.types.where_method_marker_bases.items.items) |basis| {
        if (basis.copy_step != predicted_step) continue;
        const covered = for (prepass_events) |event| {
            if (event.endpoint != .marker) continue;
            const marker = event.endpoint.marker;
            if (marker.constraint_index == basis.source_constraint_index and
                marker.contract_offset == basis.source_contract_offset) break true;
        } else false;
        if (!covered) {
            std.debug.panic("annotation producer event stream omitted a predeclared marker source", .{});
        }
    }
    draft.provisional_copy_step = predicted_step;
    draft.state = .awaiting_body;
}

const PredeclaredMarkerCoordinate = struct {
    constraint_index: u32,
    contract_offset: u32,
};

const PredeclaredBasisRewrite = struct {
    basis_index: u32,
    source_constraint_index: u32,
    source_contract_offset: u32,
};

const PredeclaredCopiedSourceRewrite = struct {
    source_index: u32,
    anchor_index: u32,
    receiver_occurrence_offset: u32,
    function_occurrence_offset: u32,
    constraint_pair_offset: u32,
};

fn validatePredeclaredMarkerEventPair(
    self: *Self,
    prepass: PredeclaredAnnoGenMarkerEndpoint,
    regenerated: PredeclaredAnnoGenMarkerEndpoint,
) void {
    const constraints = self.types.static_dispatch_constraints.items.items;
    if (regenerated.constraint_index >= constraints.len) {
        std.debug.panic("annotation producer marker named an out-of-range constraint", .{});
    }
    const regenerated_constraint = constraints[regenerated.constraint_index];
    if (regenerated.contract_offset >= regenerated_constraint.where_method_markers.len()) {
        std.debug.panic("annotation producer marker offset escaped its constraint", .{});
    }
    const expected_regenerated_index = std.math.add(
        u32,
        @intFromEnum(regenerated_constraint.where_method_markers.start),
        regenerated.contract_offset,
    ) catch std.debug.panic("annotation producer marker index overflowed u32", .{});
    // The prepass constraint range is intentionally retired before body
    // generation. Its frozen event therefore names the immutable absolute
    // contract/path endpoint directly; only the regenerated occurrence can be
    // required to remain attached to its live constraint range here.
    if (regenerated.contract_index != expected_regenerated_index) {
        std.debug.panic("annotation producer marker event did not name its exact contract", .{});
    }
    const contracts = self.types.where_method_marker_contracts.items.items;
    if (prepass.contract_index >= contracts.len or regenerated.contract_index >= contracts.len) {
        std.debug.panic("annotation producer marker event escaped the marker pool", .{});
    }
    const prepass_contract = contracts[prepass.contract_index];
    const regenerated_contract = contracts[regenerated.contract_index];
    inline for (.{ "producer_owner_node", "producer_where_node", "producer_method_name", "position", "widened", "ready", "path_len" }) |field| {
        if (@field(prepass_contract, field) != @field(regenerated_contract, field)) {
            std.debug.panic("annotation producer marker facts diverged during regeneration", .{});
        }
    }
    if (prepass.path_start != prepass_contract.path_start or
        prepass.path_len != prepass_contract.path_len or
        regenerated.path_start != regenerated_contract.path_start or
        regenerated.path_len != regenerated_contract.path_len)
    {
        std.debug.panic("annotation producer marker event carried the wrong path range", .{});
    }
    const paths = self.types.where_method_marker_path_steps.items.items;
    if (prepass.path_start > paths.len or prepass.path_len > paths.len - prepass.path_start or
        regenerated.path_start > paths.len or regenerated.path_len > paths.len - regenerated.path_start)
    {
        std.debug.panic("annotation producer marker path escaped its pool", .{});
    }
    for (
        paths[prepass.path_start..][0..prepass.path_len],
        paths[regenerated.path_start..][0..regenerated.path_len],
    ) |prepass_step, regenerated_step| {
        if (!std.meta.eql(prepass_step, regenerated_step)) {
            std.debug.panic("annotation producer marker path changed during regeneration", .{});
        }
    }
}

fn whereMarkerCopyPairLessThan(
    _: void,
    a: ModuleEnv.WhereMarkerCopyPair,
    b: ModuleEnv.WhereMarkerCopyPair,
) bool {
    if (a.source_var != b.source_var) return a.source_var < b.source_var;
    return a.destination_var < b.destination_var;
}

fn durableWhereMarkerPairOffset(
    pairs: []const ModuleEnv.WhereMarkerCopyPair,
    source_var: u32,
    destination_var: u32,
) u32 {
    var low: usize = 0;
    var high: usize = pairs.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        if (pairs[mid].source_var < source_var or
            (pairs[mid].source_var == source_var and
                pairs[mid].destination_var < destination_var))
        {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    if (low >= pairs.len or pairs[low].source_var != source_var or
        pairs[low].destination_var != destination_var)
    {
        std.debug.panic("rebased annotation witness endpoint was absent from its pair relation", .{});
    }
    return @intCast(low);
}

fn durableWhereMarkerConstraintPairOffset(
    pairs: []const ModuleEnv.WhereMarkerConstraintCopyPair,
    source_constraint_index: u32,
    destination_constraint_index: u32,
) u32 {
    var low: usize = 0;
    var high: usize = pairs.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        if (pairs[mid].source_constraint_index < source_constraint_index) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    if (low >= pairs.len or
        pairs[low].source_constraint_index != source_constraint_index or
        pairs[low].destination_constraint_index != destination_constraint_index)
    {
        std.debug.panic("rebased annotation witness constraint was absent from its pair relation", .{});
    }
    return @intCast(low);
}

/// Join a regenerated annotation occurrence B to its frozen prepass occurrence
/// A and the provisional orphan relation A→O. Every allocation and every
/// equality/coverage check completes before the durable step, pair rows, or
/// basis coordinates are changed; the final commit is infallible.
fn rebasePredeclaredAnnotationDraft(
    self: *Self,
    draft_index: u32,
    regenerated_events: VarPairRange,
) Allocator.Error!void {
    const draft = self.predeclared_anno_drafts.items[draft_index];
    const mb_step_index = draft.provisional_copy_step;
    const mb_step: ?ModuleEnv.WhereMarkerCopyStep = if (mb_step_index) |step_index| blk: {
        if (step_index >= self.cir.where_marker_copy_steps.items.items.len) {
            std.debug.panic("predeclared annotation provisional step escaped its pool", .{});
        }
        const step = self.cir.where_marker_copy_steps.items.items[step_index];
        if (step.kind != @intFromEnum(ModuleEnv.WhereMarkerCopyStep.Kind.predeclared_annotation)) {
            std.debug.panic("predeclared annotation draft named a non-predeclared copy step", .{});
        }
        break :blk step;
    } else null;
    const prepass = self.predeclared_anno_events.items[draft.prepass_events.start..][0..draft.prepass_events.len];
    const regenerated = self.predeclared_anno_events.items[regenerated_events.start..][0..regenerated_events.len];
    if (prepass.len != regenerated.len) {
        std.debug.panic("regenerated annotation producer stream was not total", .{});
    }

    var var_forward = std.AutoHashMap(Var, Var).init(self.gpa);
    defer var_forward.deinit();
    var var_reverse = std.AutoHashMap(Var, Var).init(self.gpa);
    defer var_reverse.deinit();
    var constraint_forward = std.AutoHashMap(u32, u32).init(self.gpa);
    defer constraint_forward.deinit();
    var constraint_reverse = std.AutoHashMap(u32, u32).init(self.gpa);
    defer constraint_reverse.deinit();
    var marker_forward = std.AutoHashMap(PredeclaredMarkerCoordinate, PredeclaredMarkerCoordinate).init(self.gpa);
    defer marker_forward.deinit();
    var marker_reverse = std.AutoHashMap(PredeclaredMarkerCoordinate, PredeclaredMarkerCoordinate).init(self.gpa);
    defer marker_reverse.deinit();

    for (prepass, regenerated) |prepass_event, regenerated_event| {
        if (!std.meta.eql(prepass_event.key, regenerated_event.key) or
            predeclaredAnnoEventEndpointTag(prepass_event.endpoint) != predeclaredAnnoEventEndpointTag(regenerated_event.endpoint) or
            prepass_event.source_var != regenerated_event.source_var or
            prepass_event.source_constraint_index != regenerated_event.source_constraint_index)
        {
            std.debug.panic("regenerated annotation producer stream changed its key or endpoint kind", .{});
        }
        switch (prepass_event.endpoint) {
            .var_ => |prepass_var| {
                const body_var = regenerated_event.endpoint.var_;
                const forward = try var_forward.getOrPut(prepass_var);
                if (forward.found_existing and forward.value_ptr.* != body_var) {
                    std.debug.panic("one prepass producer occurrence mapped to two regenerated vars", .{});
                }
                forward.value_ptr.* = body_var;
                const reverse = try var_reverse.getOrPut(body_var);
                if (reverse.found_existing and reverse.value_ptr.* != prepass_var) {
                    std.debug.panic("two prepass producer occurrences collapsed during regeneration", .{});
                }
                reverse.value_ptr.* = prepass_var;
            },
            .constraint_index => |prepass_constraint| {
                const body_constraint = regenerated_event.endpoint.constraint_index;
                const forward = try constraint_forward.getOrPut(prepass_constraint);
                if (forward.found_existing and forward.value_ptr.* != body_constraint) {
                    std.debug.panic("one prepass constraint mapped to two regenerated constraints", .{});
                }
                forward.value_ptr.* = body_constraint;
                const reverse = try constraint_reverse.getOrPut(body_constraint);
                if (reverse.found_existing and reverse.value_ptr.* != prepass_constraint) {
                    std.debug.panic("two prepass constraints collapsed during regeneration", .{});
                }
                reverse.value_ptr.* = prepass_constraint;
            },
            .marker => |prepass_marker| {
                const body_marker = regenerated_event.endpoint.marker;
                self.validatePredeclaredMarkerEventPair(prepass_marker, body_marker);
                const prepass_coord = PredeclaredMarkerCoordinate{
                    .constraint_index = prepass_marker.constraint_index,
                    .contract_offset = prepass_marker.contract_offset,
                };
                const body_coord = PredeclaredMarkerCoordinate{
                    .constraint_index = body_marker.constraint_index,
                    .contract_offset = body_marker.contract_offset,
                };
                const forward = try marker_forward.getOrPut(prepass_coord);
                if (forward.found_existing and !std.meta.eql(forward.value_ptr.*, body_coord)) {
                    std.debug.panic("one prepass marker mapped to two regenerated markers", .{});
                }
                forward.value_ptr.* = body_coord;
                const reverse = try marker_reverse.getOrPut(body_coord);
                if (reverse.found_existing and !std.meta.eql(reverse.value_ptr.*, prepass_coord)) {
                    std.debug.panic("two prepass markers collapsed during regeneration", .{});
                }
                reverse.value_ptr.* = prepass_coord;
            },
        }
    }

    if (draft.orphan_pairs.start > self.predeclared_anno_orphan_pairs.items.len or
        draft.orphan_pairs.len > self.predeclared_anno_orphan_pairs.items.len - draft.orphan_pairs.start)
    {
        std.debug.panic("predeclared annotation orphan relation escaped its checker pool", .{});
    }
    const rewritten_orphan_pairs = try self.gpa.dupe(
        VarPair,
        self.predeclared_anno_orphan_pairs.items[draft.orphan_pairs.start..][0..draft.orphan_pairs.len],
    );
    defer self.gpa.free(rewritten_orphan_pairs);
    for (rewritten_orphan_pairs) |*pair| {
        pair.old_var = var_forward.get(pair.old_var) orelse
            std.debug.panic("annotation producer stream omitted an orphan-copy source var", .{});
    }
    const prepass_root = draft.prepass_root orelse
        std.debug.panic("predeclared annotation draft lost its frozen source root", .{});
    const orphan_root = if (mb_step) |step|
        @as(Var, @enumFromInt(self.cir.where_marker_copy_occurrences.items.items[
            step.occurrences_start + step.root_occurrence_offset
        ].raw_destination_var))
    else blk: {
        for (self.predeclared_anno_orphan_pairs.items[draft.orphan_pairs.start..][0..draft.orphan_pairs.len]) |pair| {
            if (pair.old_var == prepass_root) break :blk pair.fresh_var;
        }
        std.debug.panic("marker-free predeclared relation omitted its root pair", .{});
    };
    const body_root = var_forward.get(prepass_root) orelse
        std.debug.panic("annotation producer stream omitted the orphan-copy source root", .{});

    var rewritten_durable_pairs: std.ArrayListUnmanaged(ModuleEnv.WhereMarkerCopyPair) = .empty;
    defer rewritten_durable_pairs.deinit(self.gpa);
    var rewritten_occurrences: ?[]ModuleEnv.WhereMarkerCopyOccurrence = null;
    defer if (rewritten_occurrences) |occurrences| self.gpa.free(occurrences);
    var rewritten_constraint_pairs: ?[]ModuleEnv.WhereMarkerConstraintCopyPair = null;
    defer if (rewritten_constraint_pairs) |pairs| self.gpa.free(pairs);
    var rewritten_witnesses: ?[]ModuleEnv.WhereMarkerCopyWitness = null;
    defer if (rewritten_witnesses) |witnesses| self.gpa.free(witnesses);
    var rewritten_copied_groups: ?[]ModuleEnv.CopiedOpenLiteralGroup = null;
    defer if (rewritten_copied_groups) |groups| self.gpa.free(groups);
    var copied_source_rewrites: std.ArrayListUnmanaged(PredeclaredCopiedSourceRewrite) = .empty;
    defer copied_source_rewrites.deinit(self.gpa);
    if (mb_step) |step| {
        if (step.pairs_start > self.cir.where_marker_copy_pairs.items.items.len or
            step.pairs_len > self.cir.where_marker_copy_pairs.items.items.len - step.pairs_start or
            step.occurrences_start > self.cir.where_marker_copy_occurrences.items.items.len or
            step.occurrences_len > self.cir.where_marker_copy_occurrences.items.items.len - step.occurrences_start or
            step.root_occurrence_offset >= step.occurrences_len or
            step.occurrences_len != rewritten_orphan_pairs.len)
        {
            std.debug.panic("predeclared annotation provisional pair range escaped its pool", .{});
        }
        try rewritten_durable_pairs.ensureTotalCapacity(self.gpa, rewritten_orphan_pairs.len);
        for (rewritten_orphan_pairs) |checker_pair| {
            const canonical_source = self.types.resolveVar(checker_pair.old_var).var_;
            const canonical_destination = self.types.resolveVar(checker_pair.fresh_var).var_;
            rewritten_durable_pairs.appendAssumeCapacity(.{
                .source_var = @intFromEnum(canonical_source),
                .destination_var = @intFromEnum(canonical_destination),
                .discovery_depth = if (canonical_source == self.types.resolveVar(body_root).var_ and
                    canonical_destination == self.types.resolveVar(orphan_root).var_)
                    0
                else
                    std.math.maxInt(u32),
                .predecessor_pair_offset = std.math.maxInt(u32),
                .predecessor_edge_ordinal = std.math.maxInt(u32),
            });
        }
        std.mem.sortUnstable(
            ModuleEnv.WhereMarkerCopyPair,
            rewritten_durable_pairs.items,
            {},
            whereMarkerCopyPairLessThan,
        );
        const pair_write = deduplicateSortedWhereMarkerCopyPairs(rewritten_durable_pairs.items);
        rewritten_durable_pairs.items.len = pair_write;
        if (pair_write != step.pairs_len) {
            std.debug.panic("rebased annotation changed its canonical pair partition", .{});
        }
        var root_pair_count: usize = 0;
        for (rewritten_durable_pairs.items) |pair| {
            if (pair.source_var == @intFromEnum(self.types.resolveVar(body_root).var_) and
                pair.destination_var == @intFromEnum(self.types.resolveVar(orphan_root).var_))
            {
                root_pair_count += 1;
            }
        }
        if (root_pair_count != 1) {
            std.debug.panic("rebased predeclared copy did not contain exactly one root pair", .{});
        }
        const old_occurrences = self.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
        const occurrences = try self.gpa.alloc(ModuleEnv.WhereMarkerCopyOccurrence, old_occurrences.len);
        for (old_occurrences, occurrences) |old_occurrence, *new_occurrence| {
            const raw_source = var_forward.get(@enumFromInt(old_occurrence.raw_source_var)) orelse
                std.debug.panic("annotation producer stream omitted a raw orphan-copy source", .{});
            const raw_destination: Var = @enumFromInt(old_occurrence.raw_destination_var);
            new_occurrence.* = .{
                .raw_source_var = @intFromEnum(raw_source),
                .raw_destination_var = old_occurrence.raw_destination_var,
                .canonical_pair_offset = durableWhereMarkerPairOffset(
                    rewritten_durable_pairs.items,
                    @intFromEnum(self.types.resolveVar(raw_source).var_),
                    @intFromEnum(self.types.resolveVar(raw_destination).var_),
                ),
            };
        }
        std.mem.sortUnstable(
            ModuleEnv.WhereMarkerCopyOccurrence,
            occurrences,
            {},
            whereMarkerCopyOccurrenceLessThan,
        );
        if (!whereMarkerRawOccurrenceRelationIsFunctional(occurrences)) {
            std.debug.panic("rebased annotation raw occurrence relation was not functional", .{});
        }
        if (occurrences.len > 1) {
            for (occurrences[1..], occurrences[0 .. occurrences.len - 1]) |current, previous| {
                if (current.raw_source_var == previous.raw_source_var and
                    current.raw_destination_var == previous.raw_destination_var)
                {
                    std.debug.panic("rebased annotation repeated one raw occurrence", .{});
                }
            }
        }
        rewritten_occurrences = occurrences;

        if (step.constraint_pairs_start > self.cir.where_marker_constraint_copy_pairs.items.items.len or
            step.constraint_pairs_len > self.cir.where_marker_constraint_copy_pairs.items.items.len - step.constraint_pairs_start or
            step.witnesses_start > self.cir.where_marker_copy_witnesses.items.items.len or
            step.witnesses_len > self.cir.where_marker_copy_witnesses.items.items.len - step.witnesses_start)
        {
            std.debug.panic("predeclared annotation proof range escaped its pool", .{});
        }
        const old_constraint_pairs = self.cir.where_marker_constraint_copy_pairs.items.items[step.constraint_pairs_start..][0..step.constraint_pairs_len];
        const constraint_pairs = try self.gpa.alloc(
            ModuleEnv.WhereMarkerConstraintCopyPair,
            old_constraint_pairs.len,
        );
        for (old_constraint_pairs, constraint_pairs) |old_pair, *new_pair| {
            new_pair.* = .{
                .source_constraint_index = constraint_forward.get(old_pair.source_constraint_index) orelse
                    std.debug.panic("annotation producer stream omitted a copied constraint source", .{}),
                .destination_constraint_index = old_pair.destination_constraint_index,
            };
        }
        std.mem.sortUnstable(ModuleEnv.WhereMarkerConstraintCopyPair, constraint_pairs, {}, struct {
            fn lessThan(_: void, a: ModuleEnv.WhereMarkerConstraintCopyPair, b: ModuleEnv.WhereMarkerConstraintCopyPair) bool {
                if (a.source_constraint_index != b.source_constraint_index) {
                    return a.source_constraint_index < b.source_constraint_index;
                }
                return a.destination_constraint_index < b.destination_constraint_index;
            }
        }.lessThan);
        if (constraint_pairs.len > 1) {
            for (constraint_pairs[1..], constraint_pairs[0 .. constraint_pairs.len - 1]) |current, previous| {
                if (current.source_constraint_index == previous.source_constraint_index) {
                    std.debug.panic("rebased annotation mapped two constraints to one source", .{});
                }
            }
        }
        rewritten_constraint_pairs = constraint_pairs;

        const old_witnesses = self.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len];
        const witnesses = try self.gpa.alloc(ModuleEnv.WhereMarkerCopyWitness, old_witnesses.len);
        for (old_witnesses, witnesses) |old_witness, *new_witness| {
            if (old_witness.parent_occurrence_offset >= old_occurrences.len or
                old_witness.child_occurrence_offset >= old_occurrences.len)
            {
                std.debug.panic("predeclared annotation witness occurrence offset escaped its step", .{});
            }
            const old_parent = old_occurrences[old_witness.parent_occurrence_offset];
            const old_child = old_occurrences[old_witness.child_occurrence_offset];
            const parent_source = var_forward.get(@enumFromInt(old_parent.raw_source_var)) orelse
                std.debug.panic("annotation producer stream omitted a witness parent source", .{});
            const child_source = var_forward.get(@enumFromInt(old_child.raw_source_var)) orelse
                std.debug.panic("annotation producer stream omitted a witness child source", .{});
            new_witness.* = old_witness;
            new_witness.parent_occurrence_offset = proofOccurrenceOffset(
                occurrences,
                @intFromEnum(parent_source),
                old_parent.raw_destination_var,
            );
            new_witness.child_occurrence_offset = proofOccurrenceOffset(
                occurrences,
                @intFromEnum(child_source),
                old_child.raw_destination_var,
            );
            if (old_witness.constraint_pair_offset != std.math.maxInt(u32)) {
                if (old_witness.constraint_pair_offset >= old_constraint_pairs.len) {
                    std.debug.panic("predeclared annotation witness constraint offset escaped its step", .{});
                }
                const old_constraint_pair = old_constraint_pairs[old_witness.constraint_pair_offset];
                const source_constraint = constraint_forward.get(old_constraint_pair.source_constraint_index) orelse
                    std.debug.panic("annotation producer stream omitted a witness constraint source", .{});
                new_witness.constraint_pair_offset = durableWhereMarkerConstraintPairOffset(
                    constraint_pairs,
                    source_constraint,
                    old_constraint_pair.destination_constraint_index,
                );
            }
            if (old_witness.raw_source_var != std.math.maxInt(u32)) {
                const raw_source = var_forward.get(@enumFromInt(old_witness.raw_source_var)) orelse
                    std.debug.panic("annotation producer stream omitted a witness raw source", .{});
                new_witness.raw_source_var = @intFromEnum(raw_source);
            }
        }
        std.mem.sortUnstable(
            ModuleEnv.WhereMarkerCopyWitness,
            witnesses,
            {},
            whereMarkerCopyWitnessLessThan,
        );
        if (witnesses.len > 1) {
            for (witnesses[1..], witnesses[0 .. witnesses.len - 1]) |current, previous| {
                if (std.meta.eql(current, previous)) {
                    std.debug.panic("rebased annotation repeated one exact witness", .{});
                }
            }
        }
        rewritten_witnesses = witnesses;

        if (step.copied_groups_start > self.cir.copied_open_literal_groups.items.items.len or
            step.copied_groups_len > self.cir.copied_open_literal_groups.items.items.len -
                step.copied_groups_start)
        {
            std.debug.panic("predeclared copied-literal group range escaped its proof step", .{});
        }
        const old_copied_groups = self.cir.copied_open_literal_groups.items.items[step.copied_groups_start..][0..step.copied_groups_len];
        const copied_groups = try self.gpa.dupe(
            ModuleEnv.CopiedOpenLiteralGroup,
            old_copied_groups,
        );
        for (old_copied_groups, copied_groups, 0..) |old_group, *group, group_offset| {
            if (old_group.copy_step_index != mb_step_index.? or
                old_group.receiver_occurrence_offset >= old_occurrences.len or
                old_group.source_constraints_len == 0 or
                old_group.source_constraints_len != old_group.destination_constraints_len)
            {
                std.debug.panic("predeclared copied-literal group escaped its provisional coordinates", .{});
            }
            const old_receiver = old_occurrences[old_group.receiver_occurrence_offset];
            const new_receiver_source = var_forward.get(
                @enumFromInt(old_receiver.raw_source_var),
            ) orelse std.debug.panic(
                "annotation producer stream omitted a copied-literal receiver source",
                .{},
            );
            group.receiver_occurrence_offset = proofOccurrenceOffset(
                occurrences,
                @intFromEnum(new_receiver_source),
                old_receiver.raw_destination_var,
            );

            const new_source_start = constraint_forward.get(
                old_group.source_constraints_start,
            ) orelse std.debug.panic(
                "annotation producer stream omitted a copied-literal constraint source",
                .{},
            );
            for (0..old_group.source_constraints_len) |raw_constraint_offset| {
                const constraint_offset: u32 = @intCast(raw_constraint_offset);
                const old_source = std.math.add(
                    u32,
                    old_group.source_constraints_start,
                    constraint_offset,
                ) catch std.debug.panic(
                    "predeclared copied-literal source range overflowed",
                    .{},
                );
                const new_source = constraint_forward.get(old_source) orelse
                    std.debug.panic(
                        "annotation producer stream omitted a copied-literal constraint source",
                        .{},
                    );
                if (new_source != std.math.add(
                    u32,
                    new_source_start,
                    constraint_offset,
                ) catch std.debug.panic(
                    "rebased copied-literal source range overflowed",
                    .{},
                )) {
                    std.debug.panic(
                        "regenerated annotation changed a copied-literal constraint range partition",
                        .{},
                    );
                }
            }
            group.source_constraints_start = new_source_start;
            if (group_offset != 0 and
                !ModuleEnv.CopiedOpenLiteralGroup.canonicalLessThan(
                    copied_groups[group_offset - 1],
                    group.*,
                ))
            {
                std.debug.panic(
                    "regenerated annotation changed copied-literal group ordering",
                    .{},
                );
            }
        }
        rewritten_copied_groups = copied_groups;

        // Copied settlement sources are immutable coordinate projections of
        // this proof relation. Rebase every projection in scratch before the
        // infallible commit; retaining its old owner-relative offsets would
        // silently retarget an anchor after occurrence/pair sorting.
        const step_index = mb_step_index.?;
        try copied_source_rewrites.ensureTotalCapacity(
            self.gpa,
            self.cir.dispatch_settlement_sources.items.items.len,
        );
        for (self.cir.dispatch_settlement_sources.items.items, 0..) |source, raw_source_index| {
            if (source.decodedKind() != .copied_constraint) continue;
            const copied = source.payload.copied_constraint;
            const receiver_ref = copied.receiver_component_ref;
            const function_ref = copied.function_component_ref;
            const touches_step = receiver_ref.copy_step_index == step_index or
                function_ref.copy_step_index == step_index;
            if (!touches_step) continue;
            // A predeclared local step can only own a root-graph or detached-
            // scheme pair, whose two refs share this exact step. Binding-codec
            // split refs are cross-module and cannot be rebased here.
            if (receiver_ref.copy_step_index != step_index or
                function_ref.copy_step_index != step_index or
                receiver_ref.occurrence_offset >= old_occurrences.len or
                function_ref.occurrence_offset >= old_occurrences.len or
                function_ref.constraint_pair_offset >= old_constraint_pairs.len or
                copied.anchor_index >= self.cir.selected_receiver_anchors.items.items.len)
            {
                std.debug.panic("predeclared copied source escaped its provisional proof relation", .{});
            }
            const anchor = self.cir.selected_receiver_anchors.items.items[copied.anchor_index];
            if (anchor.decodedKind() != .copied_constraint or
                anchor.copy_step != step_index or
                anchor.receiver_occurrence_offset != receiver_ref.occurrence_offset or
                anchor.constraint_pair_offset != function_ref.constraint_pair_offset)
            {
                std.debug.panic("predeclared copied anchor disagreed with its source projection", .{});
            }
            const old_receiver = old_occurrences[receiver_ref.occurrence_offset];
            const old_function = old_occurrences[function_ref.occurrence_offset];
            const new_receiver_source = var_forward.get(@enumFromInt(old_receiver.raw_source_var)) orelse
                std.debug.panic("annotation producer stream omitted a copied receiver source", .{});
            const new_function_source = var_forward.get(@enumFromInt(old_function.raw_source_var)) orelse
                std.debug.panic("annotation producer stream omitted a copied function source", .{});
            const old_constraint_pair = old_constraint_pairs[function_ref.constraint_pair_offset];
            const new_constraint_source = constraint_forward.get(old_constraint_pair.source_constraint_index) orelse
                std.debug.panic("annotation producer stream omitted a copied constraint source", .{});
            copied_source_rewrites.appendAssumeCapacity(.{
                .source_index = @intCast(raw_source_index),
                .anchor_index = copied.anchor_index,
                .receiver_occurrence_offset = proofOccurrenceOffset(
                    occurrences,
                    @intFromEnum(new_receiver_source),
                    old_receiver.raw_destination_var,
                ),
                .function_occurrence_offset = proofOccurrenceOffset(
                    occurrences,
                    @intFromEnum(new_function_source),
                    old_function.raw_destination_var,
                ),
                .constraint_pair_offset = durableWhereMarkerConstraintPairOffset(
                    constraint_pairs,
                    new_constraint_source,
                    old_constraint_pair.destination_constraint_index,
                ),
            });
        }
        for (self.cir.selected_receiver_anchors.items.items, 0..) |anchor, raw_anchor_index| {
            if (anchor.decodedKind() != .copied_constraint or anchor.copy_step != step_index) continue;
            var producer_count: usize = 0;
            for (copied_source_rewrites.items) |rewrite| {
                if (rewrite.anchor_index == raw_anchor_index) producer_count += 1;
            }
            if (producer_count != 1) {
                std.debug.panic("predeclared copied anchor did not have one rebased source producer", .{});
            }
        }
    }

    var basis_rewrites: std.ArrayListUnmanaged(PredeclaredBasisRewrite) = .empty;
    defer basis_rewrites.deinit(self.gpa);
    for (self.types.where_method_marker_bases.items.items, 0..) |basis, raw_basis_index| {
        const step_index = mb_step_index orelse break;
        if (basis.copy_step != step_index) continue;
        const mapped = marker_forward.get(.{
            .constraint_index = basis.source_constraint_index,
            .contract_offset = basis.source_contract_offset,
        }) orelse std.debug.panic("annotation producer stream omitted an orphan-copy marker source", .{});
        try basis_rewrites.append(self.gpa, .{
            .basis_index = @intCast(raw_basis_index),
            .source_constraint_index = mapped.constraint_index,
            .source_contract_offset = mapped.contract_offset,
        });
    }
    const prepass_has_marker = for (prepass) |event| {
        if (event.endpoint == .marker) break true;
    } else false;
    if (mb_step != null and prepass_has_marker and basis_rewrites.items.len == 0) {
        std.debug.panic("marker-bearing predeclared copy owned no destination bases", .{});
    }

    // No operation below can fail.
    if (mb_step) |step| {
        const step_index = mb_step_index.?;
        const old_occurrences = self.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
        const new_occurrences = rewritten_occurrences.?;
        for (self.cir.where_marker_copy_steps.items.items, 0..) |*child_step, child_step_index| {
            if (child_step_index == step_index) continue;
            const child_kind = child_step.decodedKind() orelse
                std.debug.panic("annotation rebase found an invalid child copy kind", .{});
            const child_origin = switch (child_kind) {
                .aggregate_expected_projection => &child_step.origin.aggregate_expected_projection,
                .branch_expected_copy => &child_step.origin.branch_expected_copy,
                else => continue,
            };
            if (child_origin.parent_authority.decodedKind() != .copy_occurrence) continue;
            const child_endpoint = &child_origin.parent_authority.payload.copy_occurrence;
            if (child_endpoint.copy_step != step_index) continue;
            if (child_endpoint.occurrence_offset >= old_occurrences.len) {
                std.debug.panic("annotation rebase child escaped its parent occurrence relation", .{});
            }
            const old_endpoint = old_occurrences[child_endpoint.occurrence_offset];
            const new_source = var_forward.get(@enumFromInt(old_endpoint.raw_source_var)) orelse
                std.debug.panic("annotation producer stream omitted an expected-child source", .{});
            child_endpoint.occurrence_offset = proofOccurrenceOffset(
                new_occurrences,
                @intFromEnum(new_source),
                old_endpoint.raw_destination_var,
            );
        }
    }
    @memcpy(
        self.predeclared_anno_orphan_pairs.items[draft.orphan_pairs.start..][0..draft.orphan_pairs.len],
        rewritten_orphan_pairs,
    );
    if (mb_step) |step| {
        const step_index = mb_step_index.?;
        @memcpy(
            self.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
            rewritten_durable_pairs.items,
        );
        @memcpy(
            self.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len],
            rewritten_occurrences.?,
        );
        @memcpy(
            self.cir.where_marker_constraint_copy_pairs.items.items[step.constraint_pairs_start..][0..step.constraint_pairs_len],
            rewritten_constraint_pairs.?,
        );
        @memcpy(
            self.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len],
            rewritten_witnesses.?,
        );
        @memcpy(
            self.cir.copied_open_literal_groups.items.items[step.copied_groups_start..][0..step.copied_groups_len],
            rewritten_copied_groups.?,
        );
        for (copied_source_rewrites.items) |rewrite| {
            const copied = &self.cir.dispatch_settlement_sources.items.items[
                rewrite.source_index
            ].payload.copied_constraint;
            copied.receiver_component_ref.occurrence_offset = rewrite.receiver_occurrence_offset;
            copied.function_component_ref.occurrence_offset = rewrite.function_occurrence_offset;
            copied.function_component_ref.constraint_pair_offset = rewrite.constraint_pair_offset;
            const anchor = &self.cir.selected_receiver_anchors.items.items[rewrite.anchor_index];
            anchor.receiver_occurrence_offset = rewrite.receiver_occurrence_offset;
            anchor.constraint_pair_offset = rewrite.constraint_pair_offset;
        }
        const final_origin = (LocalWhereMarkerCopyOrigin{
            .predeclared_annotation = .{ .node = @intFromEnum(draft.annotation_idx) },
        }).encode();
        const committed_step = &self.cir.where_marker_copy_steps.items.items[step_index];
        committed_step.kind = @intFromEnum(final_origin.kind);
        committed_step.origin = final_origin.origin;
        committed_step.root_occurrence_offset = proofOccurrenceOffset(
            rewritten_occurrences.?,
            @intFromEnum(body_root),
            @intFromEnum(orphan_root),
        );
        const root_pair = rewritten_durable_pairs.items[
            rewritten_occurrences.?[committed_step.root_occurrence_offset].canonical_pair_offset
        ];
        committed_step.source_root_var = root_pair.source_var;
        committed_step.destination_root_var = root_pair.destination_var;
    }
    for (basis_rewrites.items) |rewrite| {
        const basis = &self.types.where_method_marker_bases.items.items[rewrite.basis_index];
        basis.source_constraint_index = rewrite.source_constraint_index;
        basis.source_contract_offset = rewrite.source_contract_offset;
    }
}

/// Declare every annotated top-level def's scheme from its annotation, before
/// any body is checked. A reference to an annotated def—by name or by
/// dispatch—then instantiates the scheme and never requires the referenced
/// body to have been checked; bodies are later checked on the ordinary path,
/// in graph order like everything else.
fn predeclareAnnotatedDefSchemes(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    std.debug.assert(env.rank() == .outermost);
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        const def = self.cir.store.getDef(def_idx);
        const annotation_idx = def.annotation orelse continue;
        if (!self.annotationIsPredeclarableScheme(def.pattern, annotation_idx)) continue;
        const scheme_var = try self.predeclareAnnotationScheme(annotation_idx, env);
        self.setPredeclaredSchemeVar(def_idx, scheme_var);
    }
}

/// Whether a def's annotation can be declared as a standalone scheme before
/// its body is checked: a simple `.assign` binding whose annotation has no
/// `_` inference hole (a hole is inferred from the body, so the annotation
/// alone does not determine the scheme). Defs that fail this are simply
/// checked in graph order like unannotated defs.
fn annotationIsPredeclarableScheme(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    annotation_idx: CIR.Annotation.Idx,
) bool {
    if (self.cir.store.getPattern(pattern_idx) != .assign) return false;
    return !self.cir.store.getAnnotation(annotation_idx).contains_underscore;
}

/// Build a standalone generalized scheme from an annotation, leaving the
/// annotation's CIR nodes untouched for the def's own body check.
///
/// The annotation's type is generated in place (through the one and only
/// generation path), deep-copied into orphan vars, and the copy generalized
/// in its own rank frame. The generation's side effects are then unwound: its
/// diagnostics are discarded (the body pass regenerates the annotation and
/// reports them exactly as it always has) and the annotation nodes are reset
/// to pristine unbound slots so the body-pass generation starts fresh. The
/// def itself therefore checks byte-for-byte as before this pre-pass existed—
/// in particular its body shares vars with its own scheme, which
/// dispatch-evidence publication relies on—while early references hold a
/// disjoint copy, exactly like references to an imported scheme.
fn predeclareAnnotationScheme(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
    env: *Env,
) std.mem.Allocator.Error!Var {
    const draft_index = try self.beginPredeclaredAnnotationDraft(annotation_idx);
    const problems_len = self.problems.len();
    const snapshots_mark = self.snapshots.mark();

    try env.var_pool.pushRank();
    const saved_predeclaring = self.predeclaring_annotation;
    const saved_active_scheme_root = self.active_scheme_root;
    self.predeclaring_annotation = true;
    self.active_scheme_root = ModuleEnv.varFrom(annotation_idx);
    defer {
        self.predeclaring_annotation = saved_predeclaring;
        self.active_scheme_root = saved_active_scheme_root;
    }
    const retired_constraint_start = self.types.static_dispatch_constraints.items.items.len;
    consumeNonPublishingAnnotationOutcome(try self.generateAnnotationType(
        annotation_idx,
        env,
        .{ .no_publication = .predeclared_scheme },
    ));
    const retired_constraint_end = self.types.static_dispatch_constraints.items.items.len;
    const predicted_copy_step: u32 = @intCast(self.cir.where_marker_copy_steps.items.items.len);
    const orphan_pairs_start: u32 = @intCast(self.predeclared_anno_orphan_pairs.items.len);
    const scheme_copy = try self.instantiateVarOrphanWithMarkerCopy(
        ModuleEnv.varFrom(annotation_idx),
        env,
        env.rank(),
        .use_last_var,
        .{ .predeclared_annotation = .{ .node = @intFromEnum(annotation_idx) } },
        &self.predeclared_anno_orphan_pairs,
        .eager_support,
    );
    const scheme_var = scheme_copy.var_;
    self.predeclared_anno_drafts.items[draft_index].orphan_pairs = .{
        .start = orphan_pairs_start,
        .len = @intCast(self.predeclared_anno_orphan_pairs.items.len - orphan_pairs_start),
    };
    self.finishPredeclaredAnnotationOrphanCopy(draft_index, predicted_copy_step);
    try self.judgeFieldKindsAtBoundary(env);
    try self.generalizer.generalize(self.gpa, &env.var_pool, env.rank());
    try self.flushGeneralizedTargetSharesAtBoundary(&.{.{
        .owner = ModuleEnv.varFrom(annotation_idx),
        .interface = scheme_var,
    }}, null);
    try self.deduplicateGeneralizedDispatchRequirements(scheme_var);
    try self.publishBindingScheme(scheme_var);
    env.var_pool.popRank();

    self.problems.truncate(problems_len);
    self.snapshots.truncateToMark(snapshots_mark);

    // The reset helper performs every allocation and range check before its
    // no-fail commit. The orphan constraints are distinct entries which share
    // the immutable contract-pool ranges, so clearing source fields cannot
    // alter the escaped scheme.
    try self.resetAnnotationNodesAndRetireWhereMethodConstraints(
        annotation_idx,
        retired_constraint_start,
        retired_constraint_end,
    );
    return scheme_var;
}

/// Reset every type-annotation node var this annotation's generation wrote
/// (the annotation node itself, its type tree, and its where-clause
/// signatures) to a pristine unbound slot. Sound because nothing live
/// references those vars afterwards: the pre-declared scheme is a fully
/// disjoint orphan copy, and generation-internal fresh vars are garbage.
fn resetAnnotationNodesAndRetireWhereMethodConstraints(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
    retired_constraint_start: usize,
    retired_constraint_end: usize,
) std.mem.Allocator.Error!void {
    if (self.probe_depth != 0) {
        @panic("annotation reset cannot mutate solver state inside a probe");
    }
    var stack_allocator_state = std.heap.stackFallback(1024, self.gpa);
    const stack_allocator = stack_allocator_state.get();
    var nodes: std.ArrayList(CIR.TypeAnno.Idx) = .empty;
    defer nodes.deinit(stack_allocator);
    try self.collectAnnotationTypeAnnos(annotation_idx, &nodes, stack_allocator);

    const constraint_count = self.types.static_dispatch_constraints.items.items.len;
    if (retired_constraint_start > retired_constraint_end or retired_constraint_end > constraint_count) {
        std.debug.panic("type checker invariant violated: retired annotation source interval changed", .{});
    }
    // Reserve the complete descriptor/root-metadata batch before either the
    // marker-range retirement or any slot detachment becomes visible.
    const reset_var_count = std.math.add(usize, nodes.items.len, 1) catch return error.OutOfMemory;
    try self.types.ensureResetVarsCapacity(reset_var_count);

    for (self.types.static_dispatch_constraints.items.items[retired_constraint_start..retired_constraint_end]) |*constraint| {
        constraint.where_method_markers = .empty();
        constraint.where_method_marker_bases = .empty();
    }

    self.types.resetVarToUnboundAssumeCapacity(ModuleEnv.varFrom(annotation_idx), Rank.outermost);
    for (nodes.items) |anno_idx| {
        self.types.resetVarToUnboundAssumeCapacity(ModuleEnv.varFrom(anno_idx), Rank.outermost);
    }
}

/// Collect every TypeAnno node in an annotation—its type tree plus its
/// where-clause method signatures—via an explicit worklist. Rigid-var
/// lookups are NOT followed (`.ref` can point outside this annotation, e.g.
/// a local annotation referencing an enclosing def's type variable); the
/// nodes a `.ref` targets inside this annotation are reached as part of the
/// tree itself.
fn collectAnnotationTypeAnnos(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
    out: *std.ArrayList(CIR.TypeAnno.Idx),
    allocator: std.mem.Allocator,
) std.mem.Allocator.Error!void {
    const annotation = self.cir.store.getAnnotation(annotation_idx);

    var pending: std.ArrayList(CIR.TypeAnno.Idx) = .empty;
    defer pending.deinit(allocator);

    try pending.append(allocator, annotation.anno);
    if (annotation.where) |where_span| {
        for (self.cir.store.sliceWhereClauses(where_span)) |where_idx| {
            switch (self.cir.store.getWhereClause(where_idx)) {
                .w_method => |method| {
                    try pending.append(allocator, method.var_);
                    for (self.cir.store.sliceTypeAnnos(method.args)) |arg_idx| {
                        try pending.append(allocator, arg_idx);
                    }
                    try pending.append(allocator, method.ret);
                },
                // A where alias reference's arguments are generated in place
                // (`generateWhereAliasReferenceArgs`), so its node tree must be
                // reset like any other. This matters when an argument's rigid
                // var occurs nowhere else in the annotation: its node is the
                // primary occurrence, and a stale rigid left behind here fails
                // to re-unify on the body pass.
                .w_alias => |alias| try pending.append(allocator, alias.alias),
                .w_malformed => {},
            }
        }
    }

    while (pending.pop()) |anno_idx| {
        try out.append(allocator, anno_idx);
        switch (self.cir.store.getTypeAnno(anno_idx)) {
            .underscore, .rigid_var, .rigid_var_lookup, .lookup, .malformed => {},
            .apply => |apply| {
                for (self.cir.store.sliceTypeAnnos(apply.args)) |arg_idx| {
                    try pending.append(allocator, arg_idx);
                }
            },
            .tag_union => |tag_union| {
                for (self.cir.store.sliceTypeAnnos(tag_union.tags)) |tag_idx| {
                    try pending.append(allocator, tag_idx);
                }
                if (tag_union.ext) |ext_idx| try pending.append(allocator, ext_idx);
            },
            .tag => |tag| {
                for (self.cir.store.sliceTypeAnnos(tag.args)) |arg_idx| {
                    try pending.append(allocator, arg_idx);
                }
            },
            .tuple => |tuple| {
                for (self.cir.store.sliceTypeAnnos(tuple.elems)) |elem_idx| {
                    try pending.append(allocator, elem_idx);
                }
            },
            .record => |record| {
                for (self.cir.store.sliceAnnoRecordFields(record.fields)) |field_idx| {
                    const field = self.cir.store.getAnnoRecordField(field_idx);
                    try pending.append(allocator, field.ty);
                }
                if (record.ext) |ext_idx| try pending.append(allocator, ext_idx);
            },
            .@"fn" => |func| {
                for (self.cir.store.sliceTypeAnnos(func.args)) |arg_idx| {
                    try pending.append(allocator, arg_idx);
                }
                try pending.append(allocator, func.ret);
            },
            .parens => |parens| try pending.append(allocator, parens.anno),
        }
    }
}

/// The rank `checkDef` expects the env to sit at: the current group's
/// def-check rank (a recursive group's members check inside its shared
/// frame), or the outermost rank outside any group (REPL, expect bodies).
fn currentDefCheckRank(self: *const Self) Rank {
    if (self.group_stack.items.len == 0) return .outermost;
    return self.group_stack.items[self.group_stack.items.len - 1].def_check_rank;
}

/// The rank of the current group's generalization boundary: the frame where a
/// singleton def's RHS generalizes (or a recursive group's shared frame), and
/// where pending dispatch obligations resolve. Obligation vars are pinned at
/// this rank so no inner frame can generalize them first (Invariant D).
fn currentGroupBoundaryRank(self: *const Self) Rank {
    if (self.group_stack.items.len == 0) return Rank.outermost.next();
    return self.group_stack.items[self.group_stack.items.len - 1].boundary_rank;
}

/// The binding group currently being checked (top of `group_stack`), or null
/// outside any group (REPL, expect bodies).
fn currentGroupIndex(self: *const Self) ?u32 {
    if (self.group_stack.items.len == 0) return null;
    return self.group_stack.items[self.group_stack.items.len - 1].group_index;
}

fn currentFramePendingTargetsTop(self: *const Self) usize {
    if (self.group_stack.items.len == 0) return 0;
    return self.group_stack.items[self.group_stack.items.len - 1].pending_targets_top;
}

fn currentFramePendingPredeclaredUsesTop(self: *const Self) usize {
    if (self.group_stack.items.len == 0) return 0;
    return self.group_stack.items[self.group_stack.items.len - 1].pending_predeclared_uses_top;
}

/// Whether `def_idx` is a member of the group currently on top of the stack,
/// and that group is recursive (so the driver pre-ranked its pattern in the
/// group's shared frame).
fn defInCurrentRecursiveGroup(self: *const Self, def_idx: CIR.Def.Idx) bool {
    if (self.group_stack.items.len == 0) return false;
    const frame = self.group_stack.items[self.group_stack.items.len - 1];
    if (!self.check_order.?.sccs[frame.group_index].is_recursive) return false;
    const group_index = self.defGroupIndex(def_idx) orelse return false;
    return group_index == frame.group_index;
}

fn ensureGroupsCheckedUpTo(self: *Self, group_index: u32, env: *Env) std.mem.Allocator.Error!void {
    // Groups are in topological order, so every group this one name-depends on
    // has a smaller index. Checking the whole prefix keeps nested checking
    // deterministic and guarantees the target group's name dependencies are in
    // place before its bodies run.
    var gi: u32 = 0;
    while (gi <= group_index) : (gi += 1) {
        try self.ensureGroupChecked(gi, env);
    }
}

fn ensureGroupChecked(self: *Self, group_index: u32, env: *Env) std.mem.Allocator.Error!void {
    switch (self.group_states.items[group_index]) {
        .checked => return,
        .checking => {
            // A suspended group—the current group, or an ancestor paused at
            // its own boundary. Its members are already checked (`.processed`)
            // with still-live, not-yet-generalized vars, so a dispatch
            // back-edge resolves against them directly (the monomorphic merge)—
            // the group is never re-entered. This also covers a pending
            // target recorded mid-body for a later member of the SAME group:
            // by boundary time the member loop has checked it.
            if (builtin.mode == .Debug) {
                var on_stack = false;
                for (self.group_stack.items) |frame| {
                    if (frame.group_index == group_index) {
                        on_stack = true;
                        break;
                    }
                }
                std.debug.assert(on_stack);
            }
        },
        .pending => try self.checkGroup(group_index, env),
    }
}

/// Check one binding group. A non-recursive singleton runs the ordinary
/// per-def path (its RHS frame is the group's boundary). A recursive group
/// gets one shared rank frame: members' patterns are ranked in it first (so
/// in-group references—forward or backward—link to them monomorphically),
/// unannotated function members' top-level lambdas are kept in the frame
/// instead of generalizing on their own, and the whole group generalizes at
/// the frame's boundary (the ML binding-group rule).
fn checkGroup(self: *Self, group_index: u32, env: *Env) std.mem.Allocator.Error!void {
    const scc = self.check_order.?.sccs[group_index];
    const base_rank = env.rank();

    // Invariant E (boundary cleanliness): group checks start—and nest—
    // only with no mid-body state pending.
    std.debug.assert(self.suppress_generalize_expr == null);

    // A group's recorded scheme contents are a property of its own defs, never
    // of whichever definition's boundary caused the group to be checked. A
    // group check nested inside another definition's generalization boundary
    // therefore runs with no active owner, exactly like a driver-initiated
    // check; members that generalize install their own owners in `checkDef`.
    const saved_active_scheme_root = self.active_scheme_root;
    const saved_active_generalized_target_share_group = self.active_generalized_target_share_group;
    self.active_scheme_root = null;
    self.active_generalized_target_share_group = null;
    defer {
        self.active_scheme_root = saved_active_scheme_root;
        self.active_generalized_target_share_group = saved_active_generalized_target_share_group;
    }

    // A singleton value def never generalizes, so its obligations resolve at
    // the base rank (after checkDef); everything else's boundary is the RHS
    // or shared group frame.
    const singleton_def = self.cir.store.getDef(scc.defs[0]);
    const singleton_expr = self.cir.store.getExpr(singleton_def.expr);
    const singleton_generalizes = !scc.is_recursive and self.shouldGeneralize(
        singleton_expr,
        singleton_def.annotation,
        true,
        false,
    );
    const group_is_value_def = !scc.is_recursive and !singleton_generalizes;

    self.group_states.items[group_index] = .checking;
    try self.group_stack.append(self.gpa, .{
        .group_index = group_index,
        .base_rank = base_rank,
        .def_check_rank = if (scc.is_recursive) base_rank.next() else base_rank,
        .boundary_rank = if (group_is_value_def) base_rank else base_rank.next(),
        .pending_targets_top = self.pending_dispatch_targets.items.len,
        .pending_predeclared_uses_top = self.pending_predeclared_scheme_uses.items.len,
    });

    if (!scc.is_recursive) {
        std.debug.assert(scc.defs.len == 1);
        try self.checkDef(scc.defs[0], env);
        std.debug.assert(env.rank() == base_rank);
        // A function def resolved its dispatch obligations at its RHS
        // generalization boundary (inside checkExpr); a value def has no such
        // boundary, so any obligations its RHS recorded resolve here.
        try self.resolveGroupPendingDispatchTargets(env);
        _ = try self.resolvePendingPredeclaredSchemeUses(env, false);
        if (!singleton_generalizes) {
            if (singleton_def.annotation) |annotation_idx| {
                try self.finalizeWhereMethodWideningForAnnotation(annotation_idx);
            }
        }
    } else {
        // The recursive SCC's boundary fixpoint is shared by all members.
        // Member bodies install their exact scheme owner; work between those
        // scopes belongs to this explicit group token and is flushed once
        // under the union of member interfaces.
        self.active_generalized_target_share_group = group_index;
        try env.var_pool.pushRank();
        const frame_rank = env.rank();

        // Rank every member's def/pattern vars in the shared frame first, so
        // an earlier member's body can reference a later member.
        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            try self.setVarRank(ModuleEnv.varFrom(member_def_idx), env);
            try self.setVarRank(ModuleEnv.varFrom(member_def.pattern), env);
            const member_pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(member_def.pattern)) .match_branch else .bound;
            try self.checkPattern(member_def.pattern, member_pattern_ctx, env);
        }

        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(member_def.expr))) {
                // Every recursive member's top-level RHS lives in the group
                // frame and generalizes at the shared boundary. Annotated
                // in-group references still instantiate their predeclared
                // schemes (polymorphic recursion), but deferring publication
                // lets forward members contribute their complete inferred
                // requirements before any member freezes.
                self.suppress_generalize_expr = member_def.expr;
            }
            try self.checkDef(member_def_idx, env);
            std.debug.assert(self.suppress_generalize_expr == null);
            std.debug.assert(env.rank() == frame_rank);
        }

        // The group's generalization boundary. (Owned copy, not scratch: the
        // boundary can nest other groups' checks, which use the scratch
        // lists themselves.)
        const member_roots = try self.gpa.alloc(BoundaryRoot, scc.defs.len);
        defer self.gpa.free(member_roots);
        for (scc.defs, 0..) |member_def_idx, i| {
            const member_def = self.cir.store.getDef(member_def_idx);
            member_roots[i] = .{
                .owner = ModuleEnv.varFrom(member_def.expr),
                .interface = ModuleEnv.varFrom(member_def.expr),
            };
        }

        // Destructure binders bind before the boundary's literal defaulting
        // (inside `runGroupBoundary`) so defaulting sees them through the
        // row (see `judgeRecordDestructBinds`).
        try self.judgeRecordDestructBinds(env);
        try self.runGroupBoundary(member_roots, env);
        // Recursive members create their schemes together at the shared group
        // boundary, after `checkDef`'s ordinary binding publication already
        // ran. Publish the stable pattern/def aliases now that the schemes
        // exist, before any use can instantiate a member through those vars.
        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            const expr_var = ModuleEnv.varFrom(member_def.expr);
            try self.bindTypeSchemeVar(expr_var, ModuleEnv.varFrom(member_def.pattern));
            try self.bindTypeSchemeVar(expr_var, ModuleEnv.varFrom(member_def_idx));
            if (self.predeclaredSchemeVar(member_def_idx)) |predeclared_scheme_var| {
                try self.bindTypeSchemeVar(expr_var, predeclared_scheme_var);
            }
        }
        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(member_def.expr))) {
                try self.checkEffectfulFunctionName(member_def.pattern, member_def.expr);
            }
        }
        try self.judgeFieldKindsAtBoundary(env);
        for (scc.defs) |member_def_idx| {
            if (self.cir.store.getDef(member_def_idx).annotation) |annotation_idx| {
                try self.finalizeWhereMethodWideningForAnnotation(annotation_idx);
            }
        }
        try self.generalizer.generalize(self.gpa, &env.var_pool, env.rank());
        try self.flushGeneralizedTargetSharesAtBoundary(member_roots, group_index);
        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            const expr_var = ModuleEnv.varFrom(member_def.expr);
            try self.deduplicateGeneralizedDispatchRequirements(expr_var);
            try self.publishBindingScheme(expr_var);
            try self.bindBindingSchemeVar(expr_var, ModuleEnv.varFrom(member_def.pattern));
            try self.bindBindingSchemeVar(expr_var, ModuleEnv.varFrom(member_def_idx));
            if (self.predeclaredSchemeVar(member_def_idx)) |predeclared_scheme_var| {
                try self.bindBindingSchemeVar(expr_var, predeclared_scheme_var);
            }
        }
        self.retireNonGeneralizedTypeSchemes(member_roots);
        try self.retireStructurallyPublishedTypeSchemeRequirements(member_roots, env.rank());
        try self.judgeAmbiguityCandidatesAtGeneralizationMultiRoot(member_roots);
        env.var_pool.popRank();
    }

    std.debug.assert(env.rank() == base_rank);
    // Invariant B: every dispatch obligation this group discovered was
    // resolved at its boundary.
    std.debug.assert(self.pending_dispatch_targets.items.len ==
        self.group_stack.items[self.group_stack.items.len - 1].pending_targets_top);
    std.debug.assert(self.pending_predeclared_scheme_uses.items.len ==
        self.group_stack.items[self.group_stack.items.len - 1].pending_predeclared_uses_top);
    _ = self.group_stack.pop();
    self.group_states.items[group_index] = .checked;
}

/// Run the group generalization boundary up to (not including) the generalize
/// call: resolve pending dispatch obligations by checking their target groups
/// in nested frames (Invariant D—nothing may generalize while an obligation
/// into an unchecked group is outstanding), interleaved with boundary literal
/// defaulting to a fixpoint, since a defaulting round can pin a receiver and
/// surface a new obligation.
fn runGroupBoundary(
    self: *Self,
    roots: []const BoundaryRoot,
    env: *Env,
) std.mem.Allocator.Error!void {
    while (true) {
        // Deferred dispatch receivers may have been pinned since the last
        // in-body pass—in a recursive group, the members' def-level
        // pattern=body unifications run after their bodies' dispatch passes,
        // and they can pin a recursive call's result (e.g. #9885's
        // `reverse(rest).append(first)`). Resolve those before generalizing.
        try self.checkStaticDispatchConstraints(env, false);
        try self.resolveGroupPendingDispatchTargets(env);
        const pending_before = self.pending_dispatch_targets.items.len;
        const replayed_before_capture = try self.resolvePendingPredeclaredSchemeUses(env, false);
        try self.defaultLiteralsAtGeneralizationBoundaryMultiRoot(roots, env);
        const replayed_after_capture = try self.resolvePendingPredeclaredSchemeUses(env, true);
        if (replayed_before_capture or replayed_after_capture) continue;
        if (self.pending_dispatch_targets.items.len == pending_before) break;
    }
    try self.finalizeFunctionEffectsAtBoundary(roots, env);
    // Invariant D: every remaining deferred dispatch constraint targets a
    // checked def, an annotated scheme, or a still-flex receiver.
    std.debug.assert(self.pending_dispatch_targets.items.len == self.currentFramePendingTargetsTop());
    std.debug.assert(self.pending_predeclared_scheme_uses.items.len == self.currentFramePendingPredeclaredUsesTop());
}

/// Materialize positive directed-effect results before the enclosing type
/// scheme generalizes. Unresolved results remain `fn_unbound` because their
/// dependency formula is part of the generalized scheme and will be resolved
/// after call-site arguments instantiate and unify it.
fn finalizeFunctionEffectsAtBoundary(self: *Self, roots: []const BoundaryRoot, env: *Env) Allocator.Error!void {
    for (roots) |root| {
        const resolved = self.types.resolveVar(root.interface);
        const flat = switch (resolved.desc.content) {
            .structure => |flat| flat,
            .flex, .rigid, .alias, .field_presence, .err => continue,
        };
        if (try self.functionEffectState(resolved.var_) != .effectful) continue;
        switch (flat) {
            .fn_unbound => |func| try self.types.setVarContent(resolved.var_, .{ .structure = .{ .fn_effectful = func } }),
            .fn_pure => |func| {
                // The body was still effect-polymorphic when it met a pure
                // annotation, but a dependency became positive later in this
                // recursive group. Re-run ordinary effect unification now so
                // the annotation mismatch is reported instead of mutating the
                // annotated type behind the user's back.
                const effectful = try self.freshFromContent(.{ .structure = .{ .fn_effectful = func } }, env, self.getRegionAt(resolved.var_));
                _ = try self.unifyInContext(resolved.var_, effectful, env, .type_annotation);
            },
            .fn_effectful => {},
            .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => continue,
        }
    }
}

/// Drain the current frame's pending dispatch targets: check each target's
/// group (nested, in its own frame, together with the topological prefix it
/// may name-depend on), then re-run dispatch constraint processing, which may
/// pin further receivers and record further targets—loop to quiescence.
fn resolveGroupPendingDispatchTargets(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const top = self.currentFramePendingTargetsTop();
    while (self.pending_dispatch_targets.items.len > top) {
        while (self.pending_dispatch_targets.items.len > top) {
            const target_def = self.pending_dispatch_targets.pop().?;
            const target_group = self.defGroupIndex(target_def).?;
            try self.ensureGroupsCheckedUpTo(target_group, env);
        }
        try self.checkStaticDispatchConstraints(env, false);
    }
}

/// Record that a dispatch obligation resolved to `target_def_idx`—an
/// unchecked, unannotated local def—for resolution at the current group's
/// boundary.
fn recordPendingDispatchTarget(self: *Self, target_def_idx: CIR.Def.Idx) std.mem.Allocator.Error!void {
    try self.pending_dispatch_targets.append(self.gpa, target_def_idx);
}

/// The `group_stack` index of the active frame that owns a deferred dispatch
/// obligation stamped with `owner_group_index`, or null when no active frame
/// matches—an unstamped obligation (created outside any group frame) or one
/// whose stamped group already finished, which the frame processing it adopts.
/// Ownership is by group identity, never by rank comparison: ranks are a
/// shared depth counter, so a nested value-def group's boundary rank aliases
/// its enclosing frame's, and unification can collapse a callable's rank all
/// the way to generalized—neither may move an obligation between frames.
fn activeDeferredDispatchObligationOwnerFrame(
    self: *const Self,
    owner_group_index: ?u32,
) ?usize {
    const owner_group = owner_group_index orelse return null;
    var frame_idx = self.group_stack.items.len;
    while (frame_idx > 0) {
        frame_idx -= 1;
        if (self.group_stack.items[frame_idx].group_index == owner_group) return frame_idx;
    }
    return null;
}

/// Whether the frame currently being checked may take over a deferred
/// dispatch obligation whose active owner frame is `owner_frame`.
///
/// An obligation with a live owner is adopted only by that owner, which is
/// the top frame exactly when the lookup found the last index. An obligation
/// with no live owner—never stamped, or stamped by a group that has already
/// popped—is an orphan, and only the outermost active frame may take it: the
/// adopting frame records the target and checks the target's topological
/// prefix inside itself, and a prefix group that names an enclosing frame's
/// still in-flight def would merge with it monomorphically instead of
/// instantiating its finished scheme. The outermost frame encloses no such
/// def, and neither does the frameless context (module finalization, REPL,
/// expect bodies), where nothing is in flight at all.
fn currentFrameAdoptsDeferredDispatchObligation(
    self: *const Self,
    owner_frame: ?usize,
) bool {
    if (owner_frame) |frame_idx| return frame_idx + 1 == self.group_stack.items.len;
    return self.group_stack.items.len <= 1;
}

/// The generalization boundary rank at which a deferred dispatch obligation's
/// callable and receiver are pinned (Invariant D): its owner frame's, the
/// outermost active frame's when the obligation is an orphan that some inner
/// frame is processing, and the current boundary rank when there are no
/// frames.
fn deferredDispatchObligationBoundaryRank(
    self: *const Self,
    owner_frame: ?usize,
) Rank {
    if (owner_frame) |frame_idx| return self.group_stack.items[frame_idx].boundary_rank;
    if (self.group_stack.items.len > 0) return self.group_stack.items[0].boundary_rank;
    return self.currentGroupBoundaryRank();
}

/// Which group owns a dispatch obligation entering the deferred queue.
const DeferredDispatchObligationOwner = union(enum) {
    /// The group frame whose checking created this obligation: the top of
    /// `group_stack`, or none outside every frame.
    current_group,
    /// The creating group captured when the obligation was first recorded,
    /// replayed here from that record.
    recorded: ?u32,
};

/// The single door into the deferred dispatch queue, so an obligation's owning
/// group is stamped in exactly one place. `owner` is explicit at every call:
/// an obligation created by the work of the frame being checked takes
/// `.current_group`, one replayed from a record that already captured its
/// creating frame takes `.recorded`. The retained entries
/// `checkStaticDispatchConstraints` copies back at the end of a pass are not
/// enqueues—they keep the stamp they entered with.
fn enqueueDeferredDispatchConstraint(
    self: *Self,
    env: *Env,
    deferred: DeferredConstraintCheck,
    owner: DeferredDispatchObligationOwner,
) Allocator.Error!void {
    var owned = deferred;
    owned.owner_group_index = switch (owner) {
        .current_group => self.currentGroupIndex(),
        .recorded => |group_index| group_index,
    };
    _ = try env.deferred_static_dispatch_constraints.append(self.gpa, owned);
}

/// Re-defer a dispatch obligation whose method target is an unchecked,
/// unannotated local def. The obligation's owning group frame records the
/// target for its own boundary and pins the relation there; any other frame
/// leaves the obligation waiting, because recording it as a nested frame's
/// pending target would check the target's topological prefix inside that
/// frame, where a prefix group can name the nested frame's still in-flight
/// def and merge with it monomorphically instead of instantiating its
/// finished scheme. An orphan obligation—one whose stamp names no active
/// frame, or that carries no stamp—goes to the outermost active frame for the
/// same reason; only that frame (and the frameless context) encloses no def
/// that a prefix group could capture. A frame that does not adopt still pins
/// the callable and receiver at the adopting frame's boundary rank
/// (Invariant D): the obligation stays waiting across every nested boundary
/// between here and its owner, and nothing it touches may generalize before
/// the owner resolves it.
///
/// Recording the target with no frames at all appends to
/// `pending_dispatch_targets` outside any frame's window, and
/// `currentGroupIndex` leaves the obligation unstamped—both correct there:
/// module finalization and REPL/expect checking have no in-flight def whose
/// boundary could own the resolution.
fn deferDispatchObligationForUncheckedTarget(
    self: *Self,
    deferred_constraint: DeferredConstraintCheck,
    constraint: StaticDispatchConstraint,
    target_def_idx: CIR.Def.Idx,
    env: *Env,
) std.mem.Allocator.Error!void {
    var waiting_constraint = deferred_constraint;
    waiting_constraint.waiting_on_target_def = true;
    const owner_frame = self.activeDeferredDispatchObligationOwnerFrame(
        deferred_constraint.owner_group_index,
    );
    if (self.currentFrameAdoptsDeferredDispatchObligation(owner_frame)) {
        waiting_constraint.owner_group_index = self.currentGroupIndex();
        try self.recordPendingDispatchTarget(target_def_idx);
    }
    const owner_boundary_rank = self.deferredDispatchObligationBoundaryRank(owner_frame);
    try self.pinVarAtRank(constraint.fn_var, owner_boundary_rank, env);
    try self.pinVarAtRank(deferred_constraint.var_, owner_boundary_rank, env);
    try self.scratch_deferred_static_dispatch_constraints.append(waiting_constraint);
}

/// Instantiate an annotation that is available before its body, then retain
/// the use until the current group boundary can replay it against the body's
/// complete scheme. The first instantiation is necessary for ordinary local
/// checking; pinning its result at the boundary keeps all call-site evidence
/// live until the replay adds body-inferred dispatch requirements.
fn instantiatePendingPredeclaredSchemeUse(
    self: *Self,
    target_def: CIR.Def.Idx,
    scheme_var: Var,
    use_var: Var,
    source_expr: CIR.Expr.Idx,
    env: *Env,
    callee_frame: ?*ExprCheckFrame,
    source_pattern: CIR.Pattern.Idx,
    source_annotation: CIR.Annotation.Idx,
) Allocator.Error!void {
    const scheme_uses_before = self.cir.scheme_uses.items.items.len;
    const instantiated = if (callee_frame != null and
        self.bindingVarRequiresInstantiation(scheme_var))
        try self.instantiateExpectedCallCalleeForFrame(
            callee_frame.?,
            scheme_var,
            env,
            .use_last_var,
            .local_predeclared_annotation,
            @intFromEnum(source_pattern),
            self.predeclaredAnnotationSupportStep(source_annotation),
            ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
        )
    else
        try self.instantiateBindingVar(scheme_var, env, .use_last_var);
    const use_pairs_start: u32 = @intCast(self.pending_predeclared_use_pairs.items.len);
    var use_pairs = self.var_map.iterator();
    while (use_pairs.next()) |pair| {
        try self.pending_predeclared_use_pairs.append(self.gpa, .{
            .old_var = pair.key_ptr.*,
            .fresh_var = pair.value_ptr.*,
        });
    }
    _ = try self.unify(use_var, instantiated, env);

    var initial_scheme_use_index: ?u32 = null;
    if (self.cir.scheme_uses.items.items.len > scheme_uses_before) {
        const last_index = self.cir.scheme_uses.items.items.len - 1;
        const record = self.cir.scheme_uses.items.items[last_index];
        if (record.node_idx == @intFromEnum(source_expr) and
            record.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.value_use))
        {
            initial_scheme_use_index = @intCast(last_index);
        }
    }

    // Pending predeclared uses are only minted while a group frame is open.
    std.debug.assert(self.group_stack.items.len > 0);
    const current_group = self.group_stack.items[self.group_stack.items.len - 1].group_index;
    if (self.defGroupIndex(target_def).? != current_group) {
        try self.pinVarAtGroupBoundaryRank(use_var, env);
    }
    try self.pending_predeclared_scheme_uses.append(self.gpa, .{
        .target_def = target_def,
        .use_var = use_var,
        .source_expr = source_expr,
        .owner_root = self.active_scheme_root,
        .discarded_binding_rhs_expr = self.discarded_binding_rhs_expr,
        .checking_executable_root = self.checking_executable_root,
        .delayed_dependency_depth = self.delayed_dependency_depth,
        .instantiation_is_immediate_callee = self.instantiation_is_immediate_callee,
        .parent_constraint_fn_var = if (self.evidence_target_site) |target| target.constraint_fn_var else null,
        .initial_scheme_use_index = initial_scheme_use_index,
        .use_pairs = .{
            .start = use_pairs_start,
            .len = @intCast(self.pending_predeclared_use_pairs.items.len - @as(usize, use_pairs_start)),
        },
    });
}

fn replayPredeclaredSchemeUse(
    self: *Self,
    pending: PendingPredeclaredSchemeUse,
    scheme_root: Var,
    env: *Env,
) Allocator.Error!void {
    const ambiguity_candidates_start = self.ambiguity_candidates.items.len;
    const open_literals_start = self.open_literal_vars.items.len;
    const previous_active_scheme_root = self.active_scheme_root;
    const previous_discarded_binding_rhs_expr = self.discarded_binding_rhs_expr;
    const previous_instantiation_source_expr = self.instantiation_source_expr;
    const previous_checking_executable_root = self.checking_executable_root;
    const previous_delayed_dependency_depth = self.delayed_dependency_depth;
    const previous_instantiation_is_immediate_callee = self.instantiation_is_immediate_callee;
    defer {
        self.active_scheme_root = previous_active_scheme_root;
        self.discarded_binding_rhs_expr = previous_discarded_binding_rhs_expr;
        self.instantiation_source_expr = previous_instantiation_source_expr;
        self.checking_executable_root = previous_checking_executable_root;
        self.delayed_dependency_depth = previous_delayed_dependency_depth;
        self.instantiation_is_immediate_callee = previous_instantiation_is_immediate_callee;
    }

    self.active_scheme_root = pending.owner_root;
    self.discarded_binding_rhs_expr = pending.discarded_binding_rhs_expr;
    self.instantiation_source_expr = pending.source_expr;
    self.checking_executable_root = pending.checking_executable_root;
    self.delayed_dependency_depth = pending.delayed_dependency_depth;
    self.instantiation_is_immediate_callee = pending.instantiation_is_immediate_callee;

    var transaction = try self.beginLocalMarkerCopyTransaction(env);
    defer transaction.rollback();
    const reserved_copy_step = try self.reserveLocalWhereMarkerCopyStep();

    const scheme_idx = self.typeSchemeIndexForRoot(scheme_root).?;

    // Compose body-scheme vars with this use through two pieces of explicit
    // producer data: body identity-slot → predeclared-scheme pairs, then the
    // predeclared-scheme → use pairs saved by the early instantiation.
    // No structural matching or second root unification is involved.
    self.var_map.clearRetainingCapacity();
    var seeded_body_vars = std.AutoHashMap(Var, void).init(self.gpa);
    defer seeded_body_vars.deinit();
    const target_annotation = self.cir.store.getDef(pending.target_def).annotation orelse
        std.debug.panic("predeclared scheme target lost its annotation", .{});
    const draft_index = self.predeclared_anno_draft_by_annotation.get(target_annotation) orelse
        std.debug.panic("predeclared scheme target lost its producer draft", .{});
    const draft = self.predeclared_anno_drafts.items[draft_index];
    if (draft.state != .rebased) {
        std.debug.panic("predeclared scheme replay preceded exact annotation regeneration", .{});
    }
    self.scratch_where_marker_copy_pairs.clearRetainingCapacity();
    self.scratch_where_marker_constraint_pairs.clearRetainingCapacity();
    self.scratch_where_marker_copy_witnesses.clearRetainingCapacity();
    defer self.scratch_where_marker_copy_pairs.clearRetainingCapacity();
    defer self.scratch_where_marker_constraint_pairs.clearRetainingCapacity();
    defer self.scratch_where_marker_copy_witnesses.clearRetainingCapacity();
    var carried_where_marker = false;
    const annotation_pairs = draft.orphan_pairs.slice(self.predeclared_anno_orphan_pairs.items);
    const use_pairs = pending.use_pairs.slice(self.pending_predeclared_use_pairs.items);
    for (annotation_pairs) |annotation_pair| {
        const predeclared_root = self.types.resolveVar(annotation_pair.fresh_var).var_;
        for (use_pairs) |use_pair| {
            if (self.types.resolveVar(use_pair.old_var).var_ != predeclared_root) continue;
            const body_root = self.types.resolveVar(annotation_pair.old_var).var_;
            try self.var_map.put(body_root, use_pair.fresh_var);
            try seeded_body_vars.put(body_root, {});
            break;
        }
    }

    var instantiator = Instantiator{
        .store = self.types,
        .idents = self.cir.getIdentStoreConst(),
        .var_map = &self.var_map,
        .proof_pairs = &self.scratch_where_marker_copy_pairs,
        .proof_constraint_pairs = &self.scratch_where_marker_constraint_pairs,
        .proof_witnesses = &self.scratch_where_marker_copy_witnesses,
        .where_marker_copy_step = reserved_copy_step,
        .where_marker_carried = &carried_where_marker,
        .current_rank = env.rank(),
        .rigid_behavior = .fresh_flex,
        .polarity_var_ident = self.cir.idents.polarity_var,
        .anonymous_ext_ident = self.cir.idents.open_ext,
        .polarity_var_behavior = .close,
    };
    var instantiated_requirements: std.ArrayListUnmanaged(InstantiatedSchemeDispatchRequirement) = .empty;
    defer instantiated_requirements.deinit(self.gpa);
    try self.copySchemeDispatchRequirements(
        scheme_idx,
        scheme_root,
        self.var_map.get(self.types.resolveVar(scheme_root).var_) orelse
            std.debug.panic("predeclared scheme replay omitted its root substitution", .{}),
        &instantiator,
        false,
        &instantiated_requirements,
    );

    // Register only vars created while copying the newly known requirements;
    // seeded body vars are the already-registered early-use vars. Build the
    // complete body-scheme evidence substitution at the same time.
    self.scratch_evidence_pairs.clearRetainingCapacity();
    var map_iter = self.var_map.iterator();
    while (map_iter.next()) |entry| {
        const old_var = entry.key_ptr.*;
        const fresh_var = entry.value_ptr.*;
        const old_resolved = self.types.resolveVar(old_var);
        const fresh_resolved = self.types.resolveVar(fresh_var);
        const old_constraints = switch (old_resolved.desc.content) {
            .flex => |flex| flex.constraints,
            .rigid => |rigid| rigid.constraints,
            .alias, .field_presence, .structure, .err => StaticDispatchConstraint.SafeList.Range.empty(),
        };
        if (old_constraints.len() > 0) {
            try self.scratch_evidence_pairs.append(self.gpa, .{
                .old_var = @intFromEnum(old_resolved.var_),
                .fresh_var = @intFromEnum(fresh_resolved.var_),
            });
            for (self.types.sliceStaticDispatchConstraints(old_constraints)) |old_constraint| {
                const old_fn_root = self.types.resolveVar(old_constraint.fn_var).var_;
                const fresh_fn_var = self.var_map.get(old_fn_root) orelse continue;
                try self.scratch_evidence_pairs.append(self.gpa, .{
                    .old_var = @intFromEnum(old_fn_root),
                    .fresh_var = @intFromEnum(self.types.resolveVar(fresh_fn_var).var_),
                });
            }
        }

        if (seeded_body_vars.contains(old_var)) continue;
        if (fresh_resolved.desc.content == .flex) {
            const flex = fresh_resolved.desc.content.flex;
            if (flex.constraints.len() > 0) {
                // Every constraint copied out of a selected dispatch target
                // belongs to that edge's derivation chain, literal conversions
                // included: recursive-dispatch detection walks this lineage.
                if (pending.parent_constraint_fn_var) |parent_fn_var| {
                    try self.recordDispatchDerivations(flex.constraints, parent_fn_var);
                }
                const constraints = self.types.sliceStaticDispatchConstraints(flex.constraints);
                var has_literal_constraint = false;
                var has_other_constraint = false;
                for (constraints) |constraint| {
                    if (self.constraintIsLiteralConversion(constraint)) {
                        has_literal_constraint = true;
                    } else {
                        has_other_constraint = true;
                    }
                }
                if (has_literal_constraint) {
                    try instantiator.ensureProofOccurrence(old_var, fresh_var);
                    try self.recordOpenLiteralVar(fresh_var, constraints, null, .{ .pending = .{
                        .copy_step = reserved_copy_step,
                        .raw_source_var = old_var,
                        .raw_destination_var = fresh_var,
                    } });
                }
                if (has_other_constraint) {
                    try self.registerInstantiatedAttachedDispatch(
                        old_var,
                        fresh_var,
                        flex.constraints,
                        pending.source_expr,
                        &instantiator,
                    );
                }
            }
        }
        try env.var_pool.addVarToRank(fresh_var, fresh_resolved.desc.rank);
        try self.fillInRegionsThrough(fresh_var);
        self.setRegionAt(fresh_var, self.regions.get(@enumFromInt(@intFromEnum(old_var))).*);
    }

    try self.appendSchemeRequirementEvidencePairs(instantiated_requirements.items);

    try self.canonicalizeSchemeUsePairs(&self.scratch_evidence_pairs);

    const scheme_uses_before = self.cir.scheme_uses.items.items.len;
    try self.cir.recordSchemeUse(
        @intFromEnum(pending.source_expr),
        .value_use,
        0,
        scheme_root,
        self.scratch_evidence_pairs.items,
    );
    self.scratch_evidence_pairs.clearRetainingCapacity();
    const complete_record = self.cir.scheme_uses.items.items[scheme_uses_before];

    for (instantiated_requirements.items) |requirement| {
        try self.registerInstantiatedSchemeRequirement(
            requirement,
            pending.source_expr,
            pending.parent_constraint_fn_var,
            &instantiator,
            env,
        );
    }
    const destination_root = self.var_map.get(self.types.resolveVar(scheme_root).var_) orelse
        std.debug.panic("predeclared scheme replay omitted its exact root destination", .{});
    try instantiator.ensureProofOccurrence(scheme_root, destination_root);
    var complete_map = self.var_map.iterator();
    while (complete_map.next()) |entry| {
        try instantiator.ensureProofOccurrence(entry.key_ptr.*, entry.value_ptr.*);
    }
    if (self.cir.where_marker_copy_steps.items.items[reserved_copy_step].decodedKind() != .reserved) {
        std.debug.panic("predeclared scheme replay lost its reserved support step", .{});
    }
    const final_scheme_use_index = pending.initial_scheme_use_index orelse @as(u32, @intCast(scheme_uses_before));
    const published_step = try self.publishLocalWhereMarkerCopyStep(
        reserved_copy_step,
        scheme_root,
        destination_root,
        .{ .scheme_use = .{ .scheme_use_index = final_scheme_use_index } },
        rankedFreshFlexMarkerCopyPolicy(.close, .pos, true),
        &self.scratch_where_marker_copy_pairs,
        &self.scratch_where_marker_constraint_pairs,
        &self.scratch_where_marker_copy_witnesses,
    );
    if (published_step != reserved_copy_step) {
        std.debug.panic("predeclared scheme replay published the wrong support step", .{});
    }

    // If the annotation itself already carried evidence, replace that early
    // record only after every fallible step/publication allocation succeeded.
    // The final assignment and tail removal are one infallible commit, so a
    // failed replay never mutates a pre-existing SchemeUse row.
    if (pending.initial_scheme_use_index) |initial_index| {
        std.debug.assert(self.cir.scheme_uses.items.items.len == scheme_uses_before + 1);
        self.cir.scheme_uses.items.items[initial_index] = complete_record;
        self.cir.scheme_uses.items.shrinkRetainingCapacity(scheme_uses_before);
    }
    self.bindPendingDefaultDriversForPublishedStep(
        published_step,
        ambiguity_candidates_start,
        open_literals_start,
    );
    transaction.commit();
}

/// Replay this frame's early annotated uses once their target bodies have
/// published complete schemes. `current_boundary_captured` means the current
/// recursive/SCC roots have just been captured; a current-group target with no
/// side-table scheme then has no hidden requirements and can be discarded.
fn resolvePendingPredeclaredSchemeUses(
    self: *Self,
    env: *Env,
    current_boundary_captured: bool,
) Allocator.Error!bool {
    const top = self.currentFramePendingPredeclaredUsesTop();
    const end = self.pending_predeclared_scheme_uses.items.len;
    var write = top;
    var replayed_any = false;
    var read = top;
    while (read < end) : (read += 1) {
        const pending = self.pending_predeclared_scheme_uses.items[read];
        const target_group = self.defGroupIndex(pending.target_def).?;
        try self.ensureGroupsCheckedUpTo(target_group, env);
        std.debug.assert(self.pending_predeclared_scheme_uses.items.len == end);

        const target_def = self.cir.store.getDef(pending.target_def);
        const target_scheme_root = ModuleEnv.varFrom(target_def.expr);
        const has_pending_requirements = self.typeSchemeIndexForRoot(target_scheme_root) != null;
        // Replays drain a frame's own pending list, so that frame is open.
        std.debug.assert(self.group_stack.items.len > 0);
        const current_group = self.group_stack.items[self.group_stack.items.len - 1].group_index;
        const target_boundary_finished = self.group_states.items[target_group] == .checked or
            (current_boundary_captured and target_group == current_group);
        if (has_pending_requirements) {
            try self.replayPredeclaredSchemeUse(pending, target_scheme_root, env);
            replayed_any = true;
            continue;
        }
        if (target_boundary_finished) continue;

        self.pending_predeclared_scheme_uses.items[write] = pending;
        write += 1;
    }
    self.pending_predeclared_scheme_uses.shrinkRetainingCapacity(write);
    // Saved use pairs are referenced only through the pending entries' ranges
    // (and only while a drain is on the stack, which keeps this list
    // non-empty), so once every frame's suffix has drained the pair storage
    // holds no live ranges and can be reclaimed.
    if (self.pending_predeclared_scheme_uses.items.len == 0) {
        self.pending_predeclared_use_pairs.clearRetainingCapacity();
    }
    return replayed_any;
}

/// Pin `obligation_var`'s class at the current group's boundary rank so no
/// inner frame generalizes it before the obligation resolves (Invariant D,
/// enforced by rank: rank adjustment at each inner generalization keeps
/// everything the obligation touched below the generalizing rank—escaped,
/// alive, and un-generalized until the boundary).
fn pinVarAtGroupBoundaryRank(self: *Self, obligation_var: Var, env: *Env) std.mem.Allocator.Error!void {
    try self.pinVarAtRank(obligation_var, self.currentGroupBoundaryRank(), env);
}

/// Pin `obligation_var`'s class at `boundary_rank` (some active frame's
/// generalization boundary) so no frame nested inside that boundary
/// generalizes it before the obligation pinned there resolves. Never raises a
/// rank and never touches a generalized class.
fn pinVarAtRank(self: *Self, obligation_var: Var, boundary_rank: Rank, env: *Env) std.mem.Allocator.Error!void {
    const resolved = self.types.resolveVar(obligation_var);
    if (resolved.desc.rank != .generalized and
        @intFromEnum(resolved.desc.rank) > @intFromEnum(boundary_rank))
    {
        try self.types.setDescRank(resolved.desc_idx, boundary_rank);
        try env.var_pool.addVarToRank(resolved.var_, boundary_rank);
    }
}

// create types for type decls //

/// Generate a type variable from the provided type statement.
/// If the stmt is not an alias or nominal dec, then do nothing
///
/// The created variable is put in-place at the var slot at `decl_idx`
/// The created variable will be generalized
fn generateStmtTypeDeclType(
    self: *Self,
    decl_idx: CIR.Statement.Idx,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const decl = self.cir.store.getStatement(decl_idx);
    const decl_var = ModuleEnv.varFrom(decl_idx);

    switch (decl) {
        .s_alias_decl, .s_nominal_decl => _ = try self.registerTypeDecl(decl_idx),
        .s_decl,
        .s_var,
        .s_var_uninitialized,
        .s_reassign,
        .s_crash,
        .s_dbg,
        .s_expr,
        .s_expect,
        .s_for,
        .s_while,
        .s_infinite_loop,
        .s_breakable_loop,
        .s_break,
        .s_return,
        .s_import,
        .s_where_alias_decl,
        .s_type_anno,
        .s_type_var_alias,
        .s_runtime_error,
        => {},
    }

    switch (decl) {
        .s_alias_decl => |alias| {
            try self.generateAliasDecl(decl_idx, decl_var, alias, env);
        },
        .s_nominal_decl => |nominal| {
            try self.generateNominalDecl(decl_idx, decl_var, nominal, env);
        },
        .s_where_alias_decl => |where_alias| {
            try self.generateWhereAliasDecl(decl_var, where_alias, env);
        },
        .s_runtime_error => {
            try self.markErroneous(decl_var);
        },
        .s_decl,
        .s_var,
        .s_var_uninitialized,
        .s_reassign,
        .s_crash,
        .s_dbg,
        .s_expr,
        .s_expect,
        .s_for,
        .s_while,
        .s_infinite_loop,
        .s_breakable_loop,
        .s_break,
        .s_return,
        .s_import,
        .s_type_anno,
        .s_type_var_alias,
        => {
            // Do nothing
        },
    }
}

fn ensureTypeDeclGenerated(
    self: *Self,
    decl_idx: CIR.Statement.Idx,
    env: *Env,
) std.mem.Allocator.Error!bool {
    switch (self.typeDeclGenerationState(decl_idx)) {
        .generated => return true,
        .generating => return switch (self.cir.store.getStatement(decl_idx)) {
            // Neither aliases nor where aliases can refer to themselves, so
            // re-entering one means the declaration is cyclic.
            .s_alias_decl, .s_where_alias_decl => false,
            .s_nominal_decl => true,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => true,
        },
        .not_generated => {},
    }

    self.setTypeDeclGenerationState(decl_idx, .generating);
    errdefer self.setTypeDeclGenerationState(decl_idx, .not_generated);

    const outer_seen_annos = self.seen_annos;
    const outer_type_decl_rigid_vars = self.type_decl_rigid_vars;
    self.seen_annos = try std.DynamicBitSetUnmanaged.initEmpty(self.gpa, @intCast(self.cir.store.nodes.len()));
    self.type_decl_rigid_vars = .{};
    defer {
        self.seen_annos.deinit(self.gpa);
        self.seen_annos = outer_seen_annos;
        self.type_decl_rigid_vars.deinit(self.gpa);
        self.type_decl_rigid_vars = outer_type_decl_rigid_vars;
    }

    try self.generateStmtTypeDeclType(decl_idx, env);
    self.setTypeDeclGenerationState(decl_idx, .generated);
    return true;
}

fn aliasOriginModule(self: *const Self) base.ModuleIdentity.Idx {
    return self.cir.selfModuleIdentity();
}

fn predeclareAliasDecl(
    self: *Self,
    decl_var: Var,
    alias: std.meta.fieldInfo(CIR.Statement, .s_alias_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const header = self.cir.store.getTypeHeader(alias.header);
    const header_args = self.cir.store.sliceTypeAnnos(header.args);
    const header_vars = try self.generateHeaderVars(header_args, env);
    const backing_var: Var = ModuleEnv.varFrom(alias.anno);

    try self.unifyWithTargetRank(
        decl_var,
        try self.types.mkAliasWithSourceDeclAndBuiltinOrigin(
            .{ .ident_idx = header.relative_name },
            backing_var,
            header_vars,
            self.aliasOriginModule(),
            @intFromEnum(decl_var),
            self.cir.module_role == .builtin,
        ),
        env,
    );
}

fn predeclareNominalDecl(
    self: *Self,
    decl_var: Var,
    nominal: std.meta.fieldInfo(CIR.Statement, .s_nominal_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const header = self.cir.store.getTypeHeader(nominal.header);
    const header_args = self.cir.store.sliceTypeAnnos(header.args);
    const header_vars = try self.generateHeaderVars(header_args, env);
    const backing_var: Var = ModuleEnv.varFrom(nominal.anno);

    try self.unifyWithTargetRank(
        decl_var,
        try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
            .{ .ident_idx = header.relative_name },
            header_vars,
            self.cir.selfModuleIdentity(),
            @intFromEnum(decl_var),
            nominal.is_opaque,
            self.cir.module_role == .builtin,
        ),
        env,
    );

    try self.registerLocalNominalDecl(
        @intFromEnum(decl_var),
        header.relative_name,
        header_vars,
        backing_var,
        nominal.is_opaque,
    );
}

/// Register (or refresh) the declaration-table entry for a local nominal
/// type declaration. The entry carries exactly the identity bits that nominal
/// applications of this declaration embed, so keyed lookups resolve for every
/// application in this store.
fn registerLocalNominalDecl(
    self: *Self,
    decl_statement: u32,
    name: Ident.Idx,
    header_vars: []const Var,
    backing_var: Var,
    is_opaque: bool,
) Allocator.Error!void {
    const builtin_origin = self.cir.module_role == .builtin;
    _ = try self.types.registerNominalDecl(.{
        .ident = .{ .ident_idx = name },
        .origin_module = self.cir.selfModuleIdentity(),
        .source = try types_mod.NominalType.Source.initChecked(
            try types_mod.SourceDecl.fromStatementWithBuiltinOriginChecked(decl_statement, builtin_origin),
            is_opaque,
            builtin_origin,
        ),
        .formals = try self.types.appendVars(header_vars),
        .backing = backing_var,
        .flags = .{ .valid = true },
    });
}

fn predeclaredAliasArgs(self: *const Self, decl_var: Var) ?[]Var {
    const resolved = self.types.resolveVar(decl_var).desc.content;
    if (resolved != .alias) return null;
    return self.types.sliceAliasArgs(resolved.alias);
}

fn predeclaredNominalArgs(self: *const Self, decl_var: Var) ?[]Var {
    const resolved = self.types.resolveVar(decl_var).desc.content;
    if (resolved != .structure or resolved.structure != .nominal_type) return null;
    return self.types.sliceNominalArgs(resolved.structure.nominal_type);
}

/// Generate types for an alias type declaration
fn generateAliasDecl(
    self: *Self,
    decl_idx: CIR.Statement.Idx,
    decl_var: Var,
    alias: std.meta.fieldInfo(CIR.Statement, .s_alias_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // A never-filled forward placeholder: a forward reference prepared this
    // declaration, then its owner's associated block was skipped after an
    // already-reported redeclaration/rejection, so the real declaration
    // never filled it. There is no annotation to generate (`.placeholder`
    // is the reserved node index 0, not a TypeAnno); poison the decl var so
    // every reference resolves to `.err` and is suppressed.
    if (alias.anno == .placeholder) {
        try self.markErroneous(decl_var);
        return;
    }

    // Get the type header's args
    const header = self.cir.store.getTypeHeader(alias.header);
    const header_args = self.cir.store.sliceTypeAnnos(header.args);

    // Next, generate the provided arg types and build the map of rigid variables in the header
    const predeclared_header_vars = self.predeclaredAliasArgs(decl_var);
    const header_vars = if (predeclared_header_vars) |vars| vars else try self.generateHeaderVars(header_args, env);
    for (header_args) |header_arg_idx| {
        if (self.cir.store.getTypeAnno(header_arg_idx) == .malformed) {
            self.markTypeDeclInvalid(decl_idx);
        }
    }
    if (predeclared_header_vars == null) {
        try self.unifyWithTargetRank(
            decl_var,
            try self.types.mkAliasWithSourceDeclAndBuiltinOrigin(
                .{ .ident_idx = header.relative_name },
                ModuleEnv.varFrom(alias.anno),
                header_vars,
                self.aliasOriginModule(),
                @intFromEnum(decl_idx),
                self.cir.module_role == .builtin,
            ),
            env,
        );
    }

    self.type_decl_rigid_vars.clearRetainingCapacity();
    defer self.type_decl_rigid_vars.clearRetainingCapacity();
    for (header_args, header_vars) |header_arg_idx, header_var| {
        const header_arg = self.cir.store.getTypeAnno(header_arg_idx);
        if (header_arg == .rigid_var) {
            try self.type_decl_rigid_vars.put(self.gpa, header_arg.rigid_var.name, header_var);
        }
    }

    // Now we have a built of list of rigid variables for the decl lhs (header).
    // With this in hand, we can now generate the type for the lhs (body).
    self.seen_annos.unsetAll();
    const backing_var: Var = ModuleEnv.varFrom(alias.anno);
    try self.generateAnnoTypeInPlace(alias.anno, env, .{ .type_decl = .{
        .idx = decl_idx,
        .name = header.relative_name,
        .type_ = .alias,
        .backing_var = backing_var,
        .is_opaque = false,
        .num_args = @intCast(header_args.len),
    } }, .pos);

    if (!try self.validateAliasRows(backing_var, env, self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(alias.anno)))) {
        self.markTypeDeclInvalid(decl_idx);
        try self.markErroneous(decl_var);
        return;
    }
}

/// Generate the type of a where alias declaration.
///
/// A where alias's type is its receiver: a rigid variable carrying every
/// constraint the declaration names. Referencing the alias instantiates those
/// constraints onto the referencing signature's own variable, so the receiver
/// is the whole of what the declaration contributes.
fn generateWhereAliasDecl(
    self: *Self,
    decl_var: Var,
    where_alias: std.meta.fieldInfo(CIR.Statement, .s_where_alias_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // The public run boundary reserved one settlement slot for every
    // declaration before any type generation. Nested on-demand generation may
    // consume earlier slots but cannot exhaust that whole-module reservation,
    // so checked_error publication below is infallible after solver recovery.

    // A never-filled forward placeholder (see `generateAliasDecl`): there is
    // no receiver to generate; poison the decl var so every reference
    // resolves to `.err` and is suppressed.
    if (where_alias.receiver == .placeholder) {
        try self.markErroneous(decl_var);
        self.publishWhereAliasCheckedError(@intFromEnum(decl_var));
        return;
    }

    // A where alias is generated on demand, which can happen part way through
    // building a referencing signature's constraints. Its own scratch entries
    // must not land in that signature's range.
    const scratch_static_dispatch_constraints_top = self.scratch_static_dispatch_constraints.top();
    defer self.scratch_static_dispatch_constraints.clearFrom(scratch_static_dispatch_constraints_top);

    self.seen_annos.unsetAll();
    var dependencies = WhereAliasDependencyAccumulator{};
    var failure_accumulator = AnnotationGenerationAccumulator{};
    const ctx = GenTypeAnnoCtx{ .annotation = .{
        .where = where_alias.where,
        .producer_owner_node = std.math.maxInt(u32),
        .where_alias_dependencies = &dependencies,
        .failure_publication = .{ .no_publication = .where_alias_declaration },
        .failure_accumulator = &failure_accumulator,
        .where_source_publication = .{ .no_publication = .where_alias_declaration },
        .opening = .implicit_open,
    } };
    defer failure_accumulator.assertNoPublication();

    // Consume malformed source clauses through the same typed producer used by
    // ordinary annotations before generating any parameter or receiver tree.
    if (try self.scanMalformedWhereClauses(where_alias.receiver, where_alias.where, ctx)) {
        consumeNonPublishingAnnotationOutcome(failure_accumulator.finish(ModuleEnv.varFrom(where_alias.receiver)));
        try self.markErroneous(decl_var);
        self.publishWhereAliasCheckedError(@intFromEnum(decl_var));
        return;
    }

    // Malformed clauses and clauses whose receiver did not canonicalize to a
    // declaration-owned rigid are deliberately absent from the ownership
    // table. Inspect the complete authored span before walking owners so no
    // unowned source can accidentally disappear into a ready-empty alias.
    const alias_decl_node: u32 = @intFromEnum(decl_var);
    const decl_view = whereAliasDeclView(self.cir, alias_decl_node) orelse
        @panic("generated where-alias declaration had invalid canonical topology");
    for (self.cir.store.sliceWhereClauses(where_alias.where)) |where_idx| {
        const method_ident: u32 = switch (self.cir.store.getWhereClause(where_idx)) {
            .w_method => |method| @bitCast(method.method_name),
            .w_alias => 0,
            .w_malformed => unreachable,
        };
        if (whereAliasSourceClause(
            self.cir,
            decl_view,
            @intFromEnum(ModuleEnv.nodeIdxFrom(where_idx)),
            method_ident,
        ) == null) {
            try self.markErroneous(decl_var);
            self.publishWhereAliasCheckedError(alias_decl_node);
            return;
        }
    }

    // Parameters are generated the same way as the receiver rather than as
    // plain header variables, because a constraint can be written against a
    // parameter and must end up on that parameter's own variable.
    // Both are rigid var annos, so polarity is irrelevant for them.
    const header = self.cir.store.getTypeHeader(where_alias.header);
    for (self.cir.store.sliceTypeAnnos(header.args)) |param_idx| {
        try self.generateAnnoTypeInPlace(param_idx, env, ctx, .neg);
    }
    try self.generateAnnoTypeInPlace(where_alias.receiver, env, ctx, .neg);

    if (try self.generateRemainingWhereConstraintOwners(where_alias.where, env, ctx)) {
        try self.markErroneous(decl_var);
        self.publishWhereAliasCheckedError(@intFromEnum(decl_var));
        return;
    }

    const receiver_var = ModuleEnv.varFrom(where_alias.receiver);
    _ = try self.unify(decl_var, receiver_var, env);
    if (dependencies.saw_checked_error and self.types.resolveVar(decl_var).desc.content != .err) {
        try self.markErroneous(decl_var);
    }
    if (self.types.resolveVar(decl_var).desc.content == .err) {
        self.publishWhereAliasCheckedError(@intFromEnum(decl_var));
        return;
    }

    // A duplicate or malformed source signature can poison only its callable
    // while leaving the receiver's rigid constraint set intact. Such a
    // declaration exports no usable method set: make that outcome explicit on
    // the declaration root before publishing any certificate rows.
    const receiver_root = self.types.resolveVar(receiver_var).var_;
    for (self.scratch_static_dispatch_constraints.items.items[scratch_static_dispatch_constraints_top..]) |entry| {
        if (self.types.resolveVar(entry.var_).var_ != receiver_root or
            self.types.resolveVar(entry.constraint.fn_var).desc.content == .err)
        {
            try self.markErroneous(decl_var);
            self.publishWhereAliasCheckedError(@intFromEnum(decl_var));
            return;
        }
    }

    try self.publishWhereAliasDeclaration(
        @intFromEnum(decl_var),
        receiver_var,
        scratch_static_dispatch_constraints_top,
        dependencies.finalRank(),
    );
}

fn publishWhereAliasCheckedError(self: *Self, alias_decl_node: u32) void {
    if (self.probe_depth != 0) {
        @panic("where-alias settlement cannot be published inside a checker probe");
    }
    self.cir.where_alias_declaration_publications.items.appendAssumeCapacity(.{
        .decl_node = alias_decl_node,
        .dependency_rank = 0,
        .expansions_start = @intCast(self.cir.where_alias_expansions.items.items.len),
        .expansions_len = 0,
        .outcome = @intFromEnum(ModuleEnv.WhereAliasDeclarationPublication.Outcome.checked_error),
    });
}

/// Commit one reusable where-alias declaration's complete flattened source
/// certificate. Generation scratch is still intact here: each direct source
/// clause contributes one entry, and each alias source clause contributes one
/// entry per method exported by the referenced declaration. Every check and
/// allocation precedes the first durable append.
fn publishWhereAliasDeclaration(
    self: *Self,
    alias_decl_node: u32,
    receiver_var: Var,
    scratch_start: usize,
    dependency_rank: u32,
) Allocator.Error!void {
    if (self.probe_depth != 0) {
        @panic("where-alias expansion certificates cannot be published inside a checker probe");
    }
    const scratch_end = self.scratch_static_dispatch_constraints.top();
    if (scratch_start > scratch_end) {
        @panic("where-alias expansion scratch interval moved backwards");
    }
    const entries = self.scratch_static_dispatch_constraints.items.items[scratch_start..scratch_end];

    const receiver_root = self.types.resolveVar(receiver_var).var_;
    for (entries, 0..) |entry, entry_index| {
        if (entry.state != .completed or
            entry.producer_owner_node != std.math.maxInt(u32) or
            self.types.resolveVar(entry.var_).var_ != receiver_root or
            entry.store_index == std.math.maxInt(u32) or
            entry.store_index >= self.types.static_dispatch_constraints.len())
        {
            @panic("where-alias expansion entry did not name its declaration receiver");
        }
        const retained = self.types.static_dispatch_constraints.items.items[entry.store_index];
        if (@as(u32, @bitCast(retained.fn_name)) != entry.producer_method_name or
            self.types.resolveVar(retained.fn_var).var_ != self.types.resolveVar(entry.constraint.fn_var).var_)
        {
            @panic("where-alias expansion entry did not name its retained method constraint");
        }
        const source_where_node = @intFromEnum(ModuleEnv.nodeIdxFrom(entry.where_clause));
        for (entries[0..entry_index]) |previous| {
            if (@intFromEnum(ModuleEnv.nodeIdxFrom(previous.where_clause)) == source_where_node and
                previous.producer_method_name == entry.producer_method_name)
            {
                @panic("where-alias declaration produced one source method more than once");
            }
        }
    }

    const expansions_start: u32 = @intCast(self.cir.where_alias_expansions.items.items.len);
    try self.cir.where_alias_expansions.items.ensureUnusedCapacity(self.gpa, entries.len);
    for (entries) |entry| {
        self.cir.where_alias_expansions.items.appendAssumeCapacity(.{
            .alias_decl_node = alias_decl_node,
            .source_where_node = @intFromEnum(ModuleEnv.nodeIdxFrom(entry.where_clause)),
            .method_ident = entry.producer_method_name,
            .retained_constraint_index = entry.store_index,
        });
    }
    self.cir.where_alias_declaration_publications.items.appendAssumeCapacity(.{
        .decl_node = alias_decl_node,
        .dependency_rank = dependency_rank,
        .expansions_start = expansions_start,
        .expansions_len = @intCast(entries.len),
        .outcome = @intFromEnum(ModuleEnv.WhereAliasDeclarationPublication.Outcome.ready),
    });
}

/// Generate types for nominal type declaration
fn generateNominalDecl(
    self: *Self,
    decl_idx: CIR.Statement.Idx,
    decl_var: Var,
    nominal: std.meta.fieldInfo(CIR.Statement, .s_nominal_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // A never-filled forward placeholder (see `generateAliasDecl`): there is
    // no backing annotation to generate, and the declaration was never
    // registered in the nominal table, so it must not be marked invalid
    // either (`poisonInvalidTypeDeclarations` requires a table entry).
    // Poison the decl var so every reference instantiates `.err`.
    if (nominal.anno == .placeholder) {
        try self.unifyWithTargetRank(decl_var, .err, env);
        return;
    }

    // Get the type header's args
    const header = self.cir.store.getTypeHeader(nominal.header);
    const header_args = self.cir.store.sliceTypeAnnos(header.args);

    // Next, generate the provided arg types and build the map of rigid variables in the header
    const predeclared_header_vars = self.predeclaredNominalArgs(decl_var);
    const header_vars = if (predeclared_header_vars) |vars| vars else try self.generateHeaderVars(header_args, env);
    for (header_args) |header_arg_idx| {
        if (self.cir.store.getTypeAnno(header_arg_idx) == .malformed) {
            self.markTypeDeclInvalid(decl_idx);
        }
    }
    if (predeclared_header_vars == null) {
        try self.unifyWithTargetRank(
            decl_var,
            try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
                .{ .ident_idx = header.relative_name },
                header_vars,
                self.cir.selfModuleIdentity(),
                @intFromEnum(decl_idx),
                nominal.is_opaque,
                self.cir.module_role == .builtin,
            ),
            env,
        );

        try self.registerLocalNominalDecl(
            @intFromEnum(decl_idx),
            header.relative_name,
            header_vars,
            ModuleEnv.varFrom(nominal.anno),
            nominal.is_opaque,
        );
    }

    self.type_decl_rigid_vars.clearRetainingCapacity();
    defer self.type_decl_rigid_vars.clearRetainingCapacity();
    for (header_args, header_vars) |header_arg_idx, header_var| {
        const header_arg = self.cir.store.getTypeAnno(header_arg_idx);
        if (header_arg == .rigid_var) {
            try self.type_decl_rigid_vars.put(self.gpa, header_arg.rigid_var.name, header_var);
        }
    }

    // Now we have a built of list of rigid variables for the decl lhs (header).
    // With this in hand, we can now generate the type for the lhs (body).
    self.seen_annos.unsetAll();
    const backing_var: Var = ModuleEnv.varFrom(nominal.anno);
    try self.generateAnnoTypeInPlace(nominal.anno, env, .{ .type_decl = .{
        .idx = decl_idx,
        .name = header.relative_name,
        .type_ = .nominal,
        .backing_var = backing_var,
        .is_opaque = nominal.is_opaque,
        .num_args = @intCast(header_args.len),
    } }, .pos);

    // A malformed backing (its error was already reported while generating
    // the annotation) invalidates the declaration: mark it in the table and
    // poison the decl var so every use instantiates `.err` and is suppressed
    // (declaration validity replaced the unifier's err-backed-nominal
    // short-circuit).
    if (self.types.resolveVar(backing_var).desc.content == .err) {
        if (self.types.lookupNominalDeclByKey(self.cir.selfModuleIdentity(), @intFromEnum(decl_idx))) |table_idx| {
            try self.types.markNominalDeclInvalid(table_idx);
        }
        try self.unifyWithTargetRank(decl_var, .err, env);
    }
}

/// Generate types for type anno args
fn generateHeaderVars(
    self: *Self,
    header_args: []CIR.TypeAnno.Idx,
    env: *Env,
) std.mem.Allocator.Error![]Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    for (header_args) |header_arg_idx| {
        const header_arg = self.cir.store.getTypeAnno(header_arg_idx);
        const header_var = ModuleEnv.varFrom(header_arg_idx);
        try self.setVarRank(header_var, env);

        switch (header_arg) {
            .rigid_var => |rigid| {
                try self.unifyWith(header_var, .{ .rigid = Rigid.init(rigid.name) }, env);
            },
            .underscore, .malformed => {
                try self.markErroneous(header_var);
            },
            .apply,
            .rigid_var_lookup,
            .lookup,
            .tag_union,
            .tag,
            .tuple,
            .record,
            .@"fn",
            .parens,
            => {
                // The canonicalizer should only produce rigid_var, underscore, or malformed
                // for header args. If we hit this, there's a compiler bug.
                std.debug.assert(false);
                try self.markErroneous(header_var);
            },
        }
    }

    return @ptrCast(header_args);
}

// type gen config //

const OutVar = enum {
    in_place,
    fresh,

    pub fn voidOrVar(comptime out_var: OutVar) type {
        return switch (out_var) {
            .in_place => void,
            .fresh => Var,
        };
    }
};

// annotations //

/// Allocation-free dependency facts collected while one reusable where alias
/// is generated. Every resolved local alias contributes even when it exports
/// no methods, so rank never depends on expansion-row presence.
const WhereAliasDependencyAccumulator = struct {
    max_local_rank: ?u32 = null,
    saw_checked_error: bool = false,

    fn observe(
        self: *@This(),
        publication: ModuleEnv.WhereAliasDeclarationPublication,
        is_local: bool,
    ) void {
        switch (publication.decodedOutcome() orelse
            @panic("generated where-alias dependency carried an invalid outcome")) {
            .checked_error => self.saw_checked_error = true,
            .ready => if (is_local) {
                if (self.max_local_rank == null or publication.dependency_rank > self.max_local_rank.?) {
                    self.max_local_rank = publication.dependency_rank;
                }
            },
        }
    }

    fn finalRank(self: @This()) u32 {
        const max_rank = self.max_local_rank orelse return 0;
        return std.math.add(u32, max_rank, 1) catch
            @panic("where-alias dependency rank overflowed");
    }
};

const BodyAnnotationAttachment = struct {
    kind: ModuleEnv.BodyAnnotationAttachment.AttachmentKind,
    node: u32,
};

/// The context use for free var generation
const AnnotationFailurePublicationMode = union(enum) {
    /// The sole annotation-generation mode allowed to publish a checked
    /// consumer failure. The expression frame owns every draft produced by
    /// this generation and completes it against the materialized annotation
    /// copy before the frame can escape.
    body_expression: struct {
        owner_expr: CIR.Expr.Idx,
        attachment: BodyAnnotationAttachment,
    },
    /// The authenticated body was already a canonicalization-authored runtime
    /// error. Its baseline retirement suppresses annotation relation
    /// publication; it never becomes the owner of an annotation failure.
    preexisting_runtime_error_owner: struct {
        owner_expr: CIR.Expr.Idx,
        attachment: BodyAnnotationAttachment,
        cause_owner: ModuleEnv.CauseOwner,
    },
    /// Explicit producer-owned reasons why this generation cannot publish an
    /// expression/pattern Expected failure. Keeping these reasons closed makes
    /// every new annotation-generation entry point choose its semantics.
    no_publication: NoPublicationReason,

    const NoPublicationReason = enum {
        predeclared_scheme,
        uninitialized_var,
        platform_requirement,
        where_alias_declaration,
    };
};

/// Closed ownership mode for the complete body where-requirement source
/// ledger. This is deliberately independent from Expected-failure publication.
const WhereMethodSourcePublicationMode = union(enum) {
    body_annotation,
    no_publication: NoPublicationReason,

    const NoPublicationReason = enum {
        predeclared_scheme,
        uninitialized_var,
        platform_requirement,
        where_alias_declaration,
    };
};

/// The typed result of one annotation-generation root. This first producer
/// slice records malformed type syntax; later finite producers extend the same
/// result instead of rediscovering failure from a solved `.err` descriptor.
const AnnotationGenerationFailure = struct {
    kind: ModuleEnv.ExpectedFailure.Kind,
    cause_owner: ModuleEnv.CauseOwner,
    /// Exact durable failure returned by a publishing body producer. Direct
    /// diagnostic/nonpublishing results use the canonical inactive value.
    failure_index: u32 = ModuleEnv.ExpectedFailure.none,
};

const AnnotationGenerationOutcome = union(enum) {
    established: Var,
    checked_error: AnnotationGenerationFailure,
    suppressed: ModuleEnv.CauseOwner,
};

/// Validate the exact transient cause arm returned by an annotation producer.
/// A body publication returns its reserved retirement, whereas a
/// nonpublishing producer returns the direct cause its durable row would have
/// carried. Kinds without a wired producer are deliberately rejected here.
fn annotationGenerationFailureHasLegalTransientCause(
    failure: AnnotationGenerationFailure,
) bool {
    const cause_present = failure.cause_owner.kind != ModuleEnv.CauseOwner.none;
    if (!failure.cause_owner.hasCanonicalTags(cause_present)) return false;
    const cause_kind = failure.cause_owner.decodedKind();
    if ((failure.failure_index != ModuleEnv.ExpectedFailure.none) !=
        (cause_kind == .expected_consumer_retirement))
    {
        return false;
    }
    return switch (failure.kind) {
        .annotation_malformed_type,
        .annotation_malformed_where,
        .annotation_invalid_tag_child,
        => cause_kind == .cir_diagnostic or cause_kind == .expected_consumer_retirement,
        .annotation_builtin_not_type => cause_kind == null or
            cause_kind == .expected_consumer_retirement,
        else => false,
    };
}

/// The nonpublishing modes cannot borrow any checked-expression authority.
/// They retain only the exact direct cause for the producer kind.
fn annotationGenerationFailureHasLegalNonPublishingCause(
    failure: AnnotationGenerationFailure,
) bool {
    if (!annotationGenerationFailureHasLegalTransientCause(failure)) return false;
    return switch (failure.kind) {
        .annotation_malformed_type,
        .annotation_malformed_where,
        .annotation_invalid_tag_child,
        => failure.cause_owner.decodedKind() == .cir_diagnostic,
        .annotation_builtin_not_type => failure.cause_owner.decodedKind() == null,
        else => false,
    };
}

/// Per-generation accumulator carried explicitly through `GenTypeAnnoCtx`.
/// Recursive annotation generation preserves the pointer byte-for-byte, while
/// independent dependency/declaration generation installs its own scope.
const AnnotationGenerationAccumulator = struct {
    first_failure: ?AnnotationGenerationFailure = null,
    suppression: ?ModuleEnv.CauseOwner = null,

    fn record(
        self: *@This(),
        failure: AnnotationGenerationFailure,
    ) void {
        if (!annotationGenerationFailureHasLegalTransientCause(failure)) {
            std.debug.panic("annotation generation carried a noncanonical failure cause", .{});
        }
        if (self.suppression != null) {
            std.debug.panic("one annotation generation mixed a new failure with prior suppression", .{});
        }
        if (self.first_failure) |first| {
            // Several malformed leaves may poison one annotation. A publishing
            // body scope reserves one shared owner retirement; a nonpublishing
            // scope needs no aggregate cause after consuming each diagnostic.
            const first_retirement = first.cause_owner.decodedExpectedConsumerRetirement();
            const next_retirement = failure.cause_owner.decodedExpectedConsumerRetirement();
            if (first_retirement != null or next_retirement != null) {
                const exact_first = first_retirement orelse
                    std.debug.panic("one annotation generation mixed retirement and non-retirement causes", .{});
                const exact_next = next_retirement orelse
                    std.debug.panic("one annotation generation mixed retirement and non-retirement causes", .{});
                if (exact_first.index != exact_next.index) {
                    std.debug.panic("one annotation generation split one owner across retirements", .{});
                }
            }
            return;
        }
        self.first_failure = failure;
    }

    fn recordSuppression(self: *@This(), cause: ModuleEnv.CauseOwner) void {
        if (!cause.hasCanonicalTags(true) or cause.decodedExpectedConsumerRetirement() == null) {
            std.debug.panic("annotation generation carried an invalid suppression cause", .{});
        }
        if (self.first_failure != null) {
            std.debug.panic("one annotation generation mixed suppression with a new failure", .{});
        }
        if (self.suppression) |existing| {
            if (!expectedCauseOwnersEqual(existing, cause)) {
                std.debug.panic("one annotation generation changed its suppression cause", .{});
            }
            return;
        }
        self.suppression = cause;
    }

    fn finish(self: @This(), generated_var: Var) AnnotationGenerationOutcome {
        if (self.suppression) |cause| return .{ .suppressed = cause };
        if (self.first_failure) |failure| return .{ .checked_error = failure };
        return .{ .established = generated_var };
    }

    fn assertNoPublication(self: @This()) void {
        if (self.first_failure) |failure| {
            if (!annotationGenerationFailureHasLegalNonPublishingCause(failure)) {
                std.debug.panic("nonpublishing annotation generation minted a checked-expression owner", .{});
            }
        }
        if (self.suppression != null) {
            std.debug.panic("ordinary nonpublishing annotation generation borrowed expression suppression", .{});
        }
    }
};

fn consumeNonPublishingAnnotationOutcome(outcome: AnnotationGenerationOutcome) void {
    switch (outcome) {
        .established => {},
        .checked_error => |failure| if (!annotationGenerationFailureHasLegalNonPublishingCause(failure)) {
            std.debug.panic("nonpublishing annotation outcome carried checked-expression authority", .{});
        },
        .suppressed => std.debug.panic(
            "ordinary nonpublishing annotation outcome borrowed expression suppression",
            .{},
        ),
    }
}

/// Explicit producer link retained until the exact runtime-error diagnostic is
/// chosen. It is checker-local and never serialized; completion consumes it
/// into `ExpectedConsumerRetirement.expected_failures_*`.
const AnnotationExpectedFailureDraft = struct {
    owner_expr: CIR.Expr.Idx,
    retirement_index: u32,
    failure_index: u32,
    producer_kind: ProducerKind = .annotation,

    const ProducerKind = enum {
        annotation,
        direct_binder_lookup,
        annotated_binding_lookup,
        call_operand,
    };
};

const DirectFormalFailureSource = struct {
    annotation_idx: CIR.Annotation.Idx,
    owner_expr: CIR.Expr.Idx,
    where_clause: CIR.WhereClause.Idx,
    rigid_var: Var,
    failure_index: u32,
    retirement_index: u32,
};

const DirectFormalFailureActivationScope = struct {
    annotation_idx: ?CIR.Annotation.Idx,
    sources_start: usize,
    owns_sources: bool,
};

fn recordDirectFormalFailureSourceAssumeCapacity(
    self: *Self,
    where_idx: CIR.WhereClause.Idx,
    alias_target: CIR.TypeAnno.Idx,
    owner_var: Var,
    failure: AnnotationGenerationFailure,
    ctx: GenTypeAnnoCtx,
) void {
    const anno_ctx = switch (ctx) {
        .annotation => |present| present,
        .type_decl => std.debug.panic(
            "a type declaration attempted to publish a direct formal failure source",
            .{},
        ),
    };
    const body = switch (anno_ctx.failure_publication) {
        .body_expression => |present| present,
        .no_publication, .preexisting_runtime_error_owner => std.debug.panic(
            "a nonpublishing annotation attempted to retain a direct formal failure source",
            .{},
        ),
    };
    const retirement_ref = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        std.debug.panic("a direct formal failure source lost its annotation retirement", .{});
    if (failure.kind != .annotation_malformed_type or
        failure.failure_index == ModuleEnv.ExpectedFailure.none or
        failure.failure_index >= self.cir.expected_failures.items.items.len or
        retirement_ref.index >= self.cir.expected_consumer_retirements.items.items.len)
    {
        std.debug.panic("a direct formal failure source lost its exact published failure", .{});
    }
    const published = self.cir.expected_failures.items.items[failure.failure_index];
    if (published.decodedKind() != .annotation_malformed_type or
        published.owner_node != @intFromEnum(body.owner_expr) or
        published.site_node != @intFromEnum(alias_target) or
        published.raw_owner_var != @intFromEnum(ModuleEnv.varFrom(body.owner_expr)) or
        !expectedCauseOwnersEqual(published.cause_owner, ModuleEnv.CauseOwner.cirDiagnostic(
            @intFromEnum(self.cir.store.getTypeAnno(alias_target).malformed.diagnostic),
        )))
    {
        std.debug.panic("a direct formal failure source changed its malformed alias publication", .{});
    }

    const annotation_idx: CIR.Annotation.Idx = @enumFromInt(anno_ctx.producer_owner_node);
    const annotation = self.cir.store.getAnnotation(annotation_idx);
    const where = annotation.where orelse
        std.debug.panic("a direct formal failure source lost its annotation where span", .{});
    if (anno_ctx.where == null or !std.meta.eql(anno_ctx.where.?, where)) {
        std.debug.panic("a direct formal failure source changed its annotation where span", .{});
    }
    var owns_clause = false;
    for (self.cir.store.sliceWhereClauseOwners(where)) |owner| {
        if (!owner.owned_by_annotation or owner.rigid_var != @intFromEnum(owner_var)) continue;
        for (self.cir.store.sliceWhereClausesForOwner(owner)) |owned_where| {
            if (owned_where == where_idx) owns_clause = true;
        }
    }
    const clause = self.cir.store.getWhereClause(where_idx);
    if (!owns_clause or clause != .w_alias or clause.w_alias.alias != alias_target) {
        std.debug.panic("a direct formal failure source escaped its exact rigid owner", .{});
    }

    const source = DirectFormalFailureSource{
        .annotation_idx = annotation_idx,
        .owner_expr = body.owner_expr,
        .where_clause = where_idx,
        .rigid_var = owner_var,
        .failure_index = failure.failure_index,
        .retirement_index = retirement_ref.index,
    };
    for (self.direct_formal_failure_sources.items) |existing| {
        if (existing.annotation_idx != annotation_idx or
            existing.where_clause != where_idx or existing.rigid_var != owner_var)
        {
            continue;
        }
        if (!std.meta.eql(existing, source)) {
            std.debug.panic("a revisited direct formal failure source changed identity", .{});
        }
        return;
    }
    self.direct_formal_failure_sources.appendAssumeCapacity(source);
}

const ActiveDirectBinderFailure = struct {
    annotation_idx: CIR.Annotation.Idx,
    annotation_owner_expr: CIR.Expr.Idx,
    lambda_expr: CIR.Expr.Idx,
    pattern_idx: CIR.Pattern.Idx,
    formal_var: Var,
    slot: u32,
    source_failure_index: u32,
    source_retirement_index: u32,
};

fn firstDirectFormalFailureSource(
    self: *const Self,
    annotation_idx: CIR.Annotation.Idx,
    rigid_var: Var,
    sources_start: usize,
) ?DirectFormalFailureSource {
    if (sources_start > self.direct_formal_failure_sources.items.len) {
        std.debug.panic("a direct formal source frame escaped its transient suffix", .{});
    }
    const annotation = self.cir.store.getAnnotation(annotation_idx);
    const where = annotation.where orelse return null;
    var matched_owner = false;
    for (self.cir.store.sliceWhereClauseOwners(where)) |owner| {
        if (!owner.owned_by_annotation or owner.rigid_var != @intFromEnum(rigid_var)) continue;
        if (matched_owner) {
            std.debug.panic("one annotation repeated a direct formal where owner", .{});
        }
        matched_owner = true;
        for (self.cir.store.sliceWhereClausesForOwner(owner)) |where_idx| {
            const clause = self.cir.store.getWhereClause(where_idx);
            const alias_target = switch (clause) {
                .w_alias => |alias| alias.alias,
                .w_method, .w_malformed => continue,
            };
            if (self.cir.store.getTypeAnno(alias_target) != .malformed) continue;

            var selected: ?DirectFormalFailureSource = null;
            for (self.direct_formal_failure_sources.items[sources_start..]) |source| {
                if (source.annotation_idx != annotation_idx or
                    source.where_clause != where_idx or source.rigid_var != rigid_var)
                {
                    continue;
                }
                if (selected != null) {
                    std.debug.panic("one malformed where alias repeated its direct formal source", .{});
                }
                selected = source;
            }
            return selected orelse
                std.debug.panic("the first malformed where alias lost its direct formal source", .{});
        }
    }
    return null;
}

fn activateDirectBinderFailuresForLambda(
    self: *Self,
    scope: DirectFormalFailureActivationScope,
    lambda_expr: CIR.Expr.Idx,
) Allocator.Error!void {
    const annotation_idx = scope.annotation_idx orelse return;
    if (!scope.owns_sources) return;
    if (scope.sources_start == self.direct_formal_failure_sources.items.len) return;
    const annotation = self.cir.store.getAnnotation(annotation_idx);
    const annotation_fn = switch (self.cir.store.getTypeAnno(annotation.anno)) {
        .@"fn" => |present| present,
        else => return,
    };
    const lambda = switch (self.cir.store.getExpr(lambda_expr)) {
        .e_lambda => |present| present,
        else => std.debug.panic("a direct formal source entered a non-lambda frame", .{}),
    };
    const formal_annos = self.cir.store.sliceTypeAnnos(annotation_fn.args);
    const patterns = self.cir.store.slicePatterns(lambda.args);
    if (formal_annos.len != patterns.len) return;

    try self.active_direct_binder_failures.ensureUnusedCapacity(self.gpa, patterns.len);
    for (formal_annos, patterns, 0..) |formal_anno, pattern_idx, slot| {
        if (self.cir.store.getTypeAnno(formal_anno) != .rigid_var) continue;
        const formal_var = ModuleEnv.varFrom(formal_anno);
        const source = self.firstDirectFormalFailureSource(
            annotation_idx,
            formal_var,
            scope.sources_start,
        ) orelse continue;
        if (self.cir.store.getPattern(pattern_idx) != .assign) continue;
        const owner = self.cir.store.getExpr(source.owner_expr);
        switch (owner) {
            .e_lambda => if (source.owner_expr != lambda_expr) continue,
            .e_closure => |closure| if (closure.lambda_idx != lambda_expr) continue,
            else => continue,
        }
        self.active_direct_binder_failures.appendAssumeCapacity(.{
            .annotation_idx = annotation_idx,
            .annotation_owner_expr = source.owner_expr,
            .lambda_expr = lambda_expr,
            .pattern_idx = pattern_idx,
            .formal_var = formal_var,
            .slot = @intCast(slot),
            .source_failure_index = source.failure_index,
            .source_retirement_index = source.retirement_index,
        });
    }
}

fn activeDirectBinderFailureForPattern(
    self: *const Self,
    pattern_idx: CIR.Pattern.Idx,
) ?ActiveDirectBinderFailure {
    var selected: ?ActiveDirectBinderFailure = null;
    for (self.active_direct_binder_failures.items) |active| {
        if (active.pattern_idx != pattern_idx) continue;
        if (selected != null) {
            std.debug.panic("one direct binder had multiple active annotation failures", .{});
        }
        selected = active;
    }
    return selected;
}

fn directBinderLookupExpectedFailure(
    expr_idx: CIR.Expr.Idx,
    pattern_idx: CIR.Pattern.Idx,
    active: ActiveDirectBinderFailure,
) ModuleEnv.ExpectedFailure {
    const none = ModuleEnv.ExpectedFailure.none;
    return .{
        .owner_node = @intFromEnum(expr_idx),
        .site_node = @intFromEnum(pattern_idx),
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.direct_binder_lookup_checked_error),
        .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(expr_idx)),
        .raw_subject_var = @intFromEnum(ModuleEnv.varFrom(pattern_idx)),
        .raw_peer_var = @intFromEnum(active.formal_var),
        .constraint_index = none,
        .slot = active.slot,
        .plan_index = none,
        .subject_authority = ModuleEnv.SubjectAuthority.direct(
            @intFromEnum(pattern_idx),
            .direct_binder_lookup_checked_error,
            active.source_failure_index,
        ),
        .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(
            active.source_retirement_index,
        ),
    };
}

fn publishDirectBinderLookupCheckedError(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    pattern_idx: CIR.Pattern.Idx,
    active: ActiveDirectBinderFailure,
) Allocator.Error!ModuleEnv.CauseOwner {
    const current = self.cir.store.getExpr(expr_idx);
    if (current != .e_lookup_local or current.e_lookup_local.pattern_idx != pattern_idx or
        pattern_idx != active.pattern_idx or self.cir.store.getPattern(pattern_idx) != .assign)
    {
        std.debug.panic("a direct binder lookup changed its exact canonical payload", .{});
    }
    if (active.source_failure_index >= self.cir.expected_failures.items.items.len or
        active.source_retirement_index >= self.cir.expected_consumer_retirements.items.items.len)
    {
        std.debug.panic("a direct binder lookup lost its upstream annotation source", .{});
    }
    const source_failure = self.cir.expected_failures.items.items[active.source_failure_index];
    if (source_failure.decodedKind() != .annotation_malformed_type or
        source_failure.owner_node != @intFromEnum(active.annotation_owner_expr))
    {
        std.debug.panic("a direct binder lookup changed its upstream annotation failure", .{});
    }
    const expected_failure = directBinderLookupExpectedFailure(
        expr_idx,
        pattern_idx,
        active,
    );
    if (!expected_failure.hasLegalTagsAt(@intCast(self.cir.expected_failures.items.items.len))) {
        std.debug.panic("a direct binder lookup built an illegal Expected failure", .{});
    }

    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != expr_idx) continue;
        if (draft.producer_kind != .direct_binder_lookup or
            draft.failure_index >= self.cir.expected_failures.items.items.len)
        {
            std.debug.panic("a revisited direct binder lookup changed its failure producer", .{});
        }
        const existing = self.cir.expected_failures.items.items[draft.failure_index];
        if (!expectedFailuresEqual(existing, expected_failure)) {
            std.debug.panic("a revisited direct binder lookup changed its exact failure", .{});
        }
        return ModuleEnv.CauseOwner.expectedConsumerRetirement(draft.retirement_index);
    }

    const retirements_len = self.cir.expected_consumer_retirements.items.items.len;
    const failures_len = self.cir.expected_failures.items.items.len;
    const drafts_len = self.annotation_expected_failure_drafts.items.len;
    errdefer {
        self.cir.expected_consumer_retirements.items.shrinkRetainingCapacity(retirements_len);
        self.cir.expected_failures.items.shrinkRetainingCapacity(failures_len);
        self.annotation_expected_failure_drafts.shrinkRetainingCapacity(drafts_len);
    }

    const retirement_index = try self.reserveIneligibleFailureRetirement(
        expr_idx,
        .direct_binder_lookup,
    );
    const failure = try self.cir.expected_failures.append(self.cir.gpa, expected_failure);
    const failure_index: u32 = @intFromEnum(failure);
    try self.annotation_expected_failure_drafts.append(self.gpa, .{
        .owner_expr = expr_idx,
        .retirement_index = retirement_index,
        .failure_index = failure_index,
        .producer_kind = .direct_binder_lookup,
    });
    return ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index);
}

const AnnotatedBindingLookupFailureSource = struct {
    body_publication_index: u32,
    annotation_failure_index: u32,
    annotation_retirement_index: u32,
};

fn annotationRetirementForFailureAtProducer(
    self: *const Self,
    owner_expr: CIR.Expr.Idx,
    failure_index: u32,
) ?u32 {
    var selected: ?u32 = null;
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != owner_expr or draft.failure_index != failure_index or
            draft.producer_kind != .annotation)
        {
            continue;
        }
        if (selected != null and selected.? != draft.retirement_index) return null;
        selected = draft.retirement_index;
    }
    if (selected) |retirement_index| return retirement_index;
    return expectedFailureOwningRetirement(self.cir, failure_index);
}

fn annotatedBindingLookupFailureSource(
    self: *const Self,
    entry: ValueLookupEntry,
) ?AnnotatedBindingLookupFailureSource {
    if (entry.call_root_token_index == ModuleEnv.ExpectedCallSlotToken.none or
        entry.call_root_token_index >= self.cir.expected_call_slot_tokens.items.items.len or
        self.cir.store.getPattern(entry.pattern_idx) != .assign)
    {
        return null;
    }
    const call_token = self.cir.expected_call_slot_tokens.items.items[
        entry.call_root_token_index
    ];
    if (!call_token.hasCanonicalTags() or call_token.decodedRole() != .root or
        call_token.site_node != @intFromEnum(entry.expr_idx))
    {
        return null;
    }
    const current = self.cir.store.getExpr(entry.expr_idx);
    if (current != .e_lookup_local or current.e_lookup_local.pattern_idx != entry.pattern_idx) {
        return null;
    }
    _ = expectedCallInstantiationStepForLookup(
        self.cir,
        entry.call_root_token_index,
        entry.pattern_idx,
    ) orelse return null;

    var selected: ?AnnotatedBindingLookupFailureSource = null;
    for (self.cir.body_annotation_malformed_type_publications.items.items, 0..) |publication, publication_index| {
        const binding_pattern = bodyAnnotationBindingPattern(self.cir, publication) orelse continue;
        if (binding_pattern != entry.pattern_idx) continue;
        const first_malformed = firstMalformedWhereAliasTarget(
            self.cir,
            @enumFromInt(publication.annotation_root),
        ) orelse continue;
        if (publication.malformed_type_publication_index >=
            self.cir.malformed_type_annotation_publications.items.items.len)
        {
            return null;
        }
        const malformed = self.cir.malformed_type_annotation_publications.items.items[
            publication.malformed_type_publication_index
        ];
        if (malformed.annotation_node != @intFromEnum(first_malformed)) continue;
        const source_failure_index = annotationMalformedFailureForBodyPublication(
            self.cir,
            @intCast(publication_index),
        ) orelse return null;
        const source_retirement_index = self.annotationRetirementForFailureAtProducer(
            @enumFromInt(publication.body_expr),
            source_failure_index,
        ) orelse return null;
        if (source_retirement_index >= self.cir.expected_consumer_retirements.items.items.len) {
            return null;
        }
        const retirement = self.cir.expected_consumer_retirements.items.items[
            source_retirement_index
        ];
        if (retirement.retired_node != publication.body_expr or
            retirement.decodedOwnerKind() != .expression or
            retirement.decodedKind() != .checker_rewrite_ineligible or
            retirement.retired_consumers_start != 0 or retirement.retired_consumers_len != 0 or
            retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none)
        {
            return null;
        }
        if (retirement.diagnostic_index == ModuleEnv.ExpectedConsumerRetirement.none) {
            if (retirement.expected_failures_start != 0 or retirement.expected_failures_len != 0) {
                return null;
            }
        } else if (!expectedRetirementOwnsFailure(
            self.cir,
            source_retirement_index,
            source_failure_index,
        )) {
            return null;
        }
        if (selected != null) return null;
        selected = .{
            .body_publication_index = @intCast(publication_index),
            .annotation_failure_index = source_failure_index,
            .annotation_retirement_index = source_retirement_index,
        };
    }
    return selected;
}

/// Publish the finite recovery edge for an annotated binding used as an
/// ordinary call's immediate callee. The producer decision is the exact root
/// token captured while checking the still-live lookup; the canonical body
/// publication selects its source independently of the binding's solved type.
fn publishAnnotatedBindingLookupCheckedError(
    self: *Self,
    entry: ValueLookupEntry,
) Allocator.Error!bool {
    const source = self.annotatedBindingLookupFailureSource(entry) orelse return false;
    const none = ModuleEnv.ExpectedFailure.none;
    const expected_failure = ModuleEnv.ExpectedFailure{
        .owner_node = @intFromEnum(entry.expr_idx),
        .site_node = @intFromEnum(entry.pattern_idx),
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.annotated_binding_lookup_checked_error),
        .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(entry.expr_idx)),
        .raw_subject_var = @intFromEnum(ModuleEnv.varFrom(entry.pattern_idx)),
        .raw_peer_var = none,
        .constraint_index = none,
        .slot = 0,
        .plan_index = none,
        .subject_authority = ModuleEnv.SubjectAuthority.direct(
            @intFromEnum(entry.pattern_idx),
            .annotated_binding_lookup_checked_error,
            source.body_publication_index,
        ),
        .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(
            source.annotation_retirement_index,
        ),
    };
    if (!expected_failure.hasLegalTagsAt(@intCast(self.cir.expected_failures.items.items.len))) {
        std.debug.panic("an annotated binding callee built an illegal Expected failure", .{});
    }

    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != entry.expr_idx) continue;
        if (draft.producer_kind != .annotated_binding_lookup or
            draft.failure_index >= self.cir.expected_failures.items.items.len or
            draft.retirement_index >= self.cir.expected_consumer_retirements.items.items.len)
        {
            std.debug.panic("a revisited annotated binding callee changed its failure producer", .{});
        }
        const existing = self.cir.expected_failures.items.items[draft.failure_index];
        const retirement = self.cir.expected_consumer_retirements.items.items[draft.retirement_index];
        if (!expectedFailuresEqual(existing, expected_failure) or
            retirement.retired_node != @intFromEnum(entry.expr_idx) or
            retirement.decodedOwnerKind() != .expression or
            retirement.decodedKind() != .checker_rewrite_ineligible or
            retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none)
        {
            std.debug.panic("a revisited annotated binding callee changed its exact failure", .{});
        }
        return true;
    }

    const retirements_len = self.cir.expected_consumer_retirements.items.items.len;
    const failures_len = self.cir.expected_failures.items.items.len;
    const drafts_len = self.annotation_expected_failure_drafts.items.len;
    errdefer {
        self.cir.expected_consumer_retirements.items.shrinkRetainingCapacity(retirements_len);
        self.cir.expected_failures.items.shrinkRetainingCapacity(failures_len);
        self.annotation_expected_failure_drafts.shrinkRetainingCapacity(drafts_len);
    }

    const retirement_index = try self.reserveIneligibleFailureRetirement(
        entry.expr_idx,
        .annotated_binding_lookup,
    );
    const failure = try self.cir.expected_failures.append(self.cir.gpa, expected_failure);
    try self.annotation_expected_failure_drafts.append(self.gpa, .{
        .owner_expr = entry.expr_idx,
        .retirement_index = retirement_index,
        .failure_index = @intFromEnum(failure),
        .producer_kind = .annotated_binding_lookup,
    });
    return true;
}

const DirectBinderCallOperandSource = struct {
    retirement_index: u32,
    failure_index: u32,
};

/// Authenticate one argument's returned typed status while its direct local
/// lookup and its checker-local failure draft are both still live. Terminal
/// replay uses the completed singleton retirement instead; this producer edge
/// must not infer the cause from the solved error descriptor or dense flags.
fn directBinderCallOperandSourceAtProducer(
    self: *const Self,
    argument_expr: CIR.Expr.Idx,
    status: CheckedExprStatus,
) ?DirectBinderCallOperandSource {
    const cause = switch (status) {
        .established => return null,
        .checked_error => |present| present,
    };
    const retirement_ref = cause.decodedExpectedConsumerRetirement() orelse return null;
    if (retirement_ref.index >= self.cir.expected_consumer_retirements.items.items.len) {
        return null;
    }
    const lookup = switch (self.cir.store.getExpr(argument_expr)) {
        .e_lookup_local => |present| present,
        else => return null,
    };
    const active = self.activeDirectBinderFailureForPattern(lookup.pattern_idx) orelse return null;

    var selected_draft: ?AnnotationExpectedFailureDraft = null;
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != argument_expr) continue;
        if (draft.producer_kind != .direct_binder_lookup or
            draft.retirement_index != retirement_ref.index or
            selected_draft != null)
        {
            std.debug.panic("a call argument changed its direct-binder lookup draft", .{});
        }
        selected_draft = draft;
    }
    const draft = selected_draft orelse return null;
    if (draft.failure_index >= self.cir.expected_failures.items.items.len) {
        std.debug.panic("a call argument lost its direct-binder lookup failure", .{});
    }
    const expected_failure = directBinderLookupExpectedFailure(
        argument_expr,
        lookup.pattern_idx,
        active,
    );
    if (!expectedFailuresEqual(
        self.cir.expected_failures.items.items[draft.failure_index],
        expected_failure,
    )) {
        std.debug.panic("a call argument changed its direct-binder lookup failure", .{});
    }

    const retirement = self.cir.expected_consumer_retirements.items.items[
        retirement_ref.index
    ];
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(argument_expr));
    if (retirement.retired_node != @intFromEnum(argument_expr) or
        retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .checker_rewrite_ineligible or
        retirement.decodedOriginalNodeTag() != .expr_var or
        retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.retired_consumers_start != 0 or retirement.retired_consumers_len != 0 or
        retirement.expected_failures_start != 0 or retirement.expected_failures_len != 0 or
        retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none or
        !std.meta.eql(
            retirement.original_payload,
            @as([4]u32, @bitCast(node.getPayload())),
        ))
    {
        std.debug.panic("a call argument changed its incomplete lookup retirement", .{});
    }
    return .{
        .retirement_index = retirement_ref.index,
        .failure_index = draft.failure_index,
    };
}

/// A canonicalization-authored malformed call argument remains a legal sibling
/// of the finite direct-lookup cause set only through its returned typed
/// outcome. The exact preexisting retirement independently authenticates the
/// expression namespace, malformed publication, payload, and diagnostic; a
/// malformed tag by itself never supplies producer authority.
fn preexistingMalformedCallOperandStatusMatches(
    cir: *const ModuleEnv,
    argument_expr: CIR.Expr.Idx,
    status: CheckedExprStatus,
) bool {
    const argument_raw: u32 = @intFromEnum(argument_expr);
    if (argument_raw >= cir.store.nodes.len() or
        cir.store.nodes.get(ModuleEnv.nodeIdxFrom(argument_expr)).tag != .malformed)
    {
        return false;
    }
    const cause = switch (status) {
        .established => return false,
        .checked_error => |present| present,
    };
    if (!cause.hasCanonicalTags(true)) return false;
    const retirement_ref = cause.decodedExpectedConsumerRetirement() orelse return false;
    if (retirement_ref.index >= cir.expected_consumer_retirements.items.items.len) {
        return false;
    }
    const retirement = cir.expected_consumer_retirements.items.items[retirement_ref.index];
    if (!retirement.hasLegalTags() or
        retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .preexisting_runtime_error or
        retirement.decodedOriginalNodeTag() != .malformed or
        retirement.retired_node != argument_raw or
        retirement.retired_consumers_start != 0 or retirement.retired_consumers_len != 0 or
        retirement.expected_failures_start != 0 or retirement.expected_failures_len != 0 or
        retirement.decodedRejectionOwnerKind() != null or
        retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none or
        !expectedConsumerRetirementNodeIsLocallyValid(cir, retirement))
    {
        return false;
    }

    var matching_retirements: usize = 0;
    for (cir.expected_consumer_retirements.items.items) |candidate| {
        if (candidate.decodedOwnerKind() == .expression and
            candidate.decodedKind() == .preexisting_runtime_error and
            candidate.retired_node == argument_raw)
        {
            matching_retirements += 1;
        }
    }
    return matching_retirements == 1;
}

fn callOperandProducerChildMatchesStatus(
    cir: *const ModuleEnv,
    argument_expr: CIR.Expr.Idx,
    status: CheckedExprStatus,
) bool {
    const argument_raw: u32 = @intFromEnum(argument_expr);
    if (argument_raw >= cir.store.nodes.len()) return false;
    const tag = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(argument_expr)).tag;
    return if (isExprNodeTag(tag))
        true
    else if (tag == .malformed)
        preexistingMalformedCallOperandStatusMatches(cir, argument_expr, status)
    else
        false;
}

fn callOperandExpectedFailure(
    call_expr: CIR.Expr.Idx,
    argument_expr: CIR.Expr.Idx,
    slot: u32,
    argument_plan: u32,
    formal_var: Var,
    lookup_retirement_index: u32,
) ModuleEnv.ExpectedFailure {
    const none = ModuleEnv.ExpectedFailure.none;
    return .{
        .owner_node = @intFromEnum(call_expr),
        .site_node = @intFromEnum(argument_expr),
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.call_operand_checked_error),
        .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(call_expr)),
        .raw_subject_var = @intFromEnum(formal_var),
        .raw_peer_var = @intFromEnum(ModuleEnv.varFrom(argument_expr)),
        .constraint_index = none,
        .slot = slot,
        .plan_index = argument_plan,
        .subject_authority = ModuleEnv.SubjectAuthority.expectedProducerRootPlan(
            argument_plan,
            @intFromEnum(formal_var),
        ),
        .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(
            lookup_retirement_index,
        ),
    };
}

/// Publish the complete finite direct-lookup operand cause set for one
/// otherwise-established ordinary call. All argument statuses have already
/// returned, so capacity is reserved for the whole R_C/F_C tuple before any
/// durable append; no later argument can strand a prefix.
fn publishCallOperandCheckedErrors(
    self: *Self,
    call_expr: CIR.Expr.Idx,
    call: @FieldType(CIR.Expr, "e_call"),
    call_shape: types_mod.Func,
    support: CallExpectedSupport,
    argument_statuses: []const CheckedExprStatus,
) Allocator.Error!?ModuleEnv.CauseOwner {
    const argument_exprs = self.cir.store.sliceExpr(call.args);
    if (argument_exprs.len != argument_statuses.len or
        argument_exprs.len != support.argument_plans.len or
        call_shape.args.len() != argument_exprs.len or
        support.root_plan >= self.cir.expected_consumption_plans.items.items.len)
    {
        std.debug.panic("a call operand publication lost its complete argument group", .{});
    }
    var source_count: usize = 0;
    for (argument_exprs, argument_statuses) |argument_expr, status| {
        switch (status) {
            .established => {},
            .checked_error => {
                if (self.directBinderCallOperandSourceAtProducer(
                    argument_expr,
                    status,
                ) != null) source_count += 1;
            },
        }
    }
    if (source_count == 0) return null;

    const current_node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(call_expr));
    const current_call = switch (self.cir.store.getExpr(call_expr)) {
        .e_call => |present| present,
        else => std.debug.panic("a call operand publication lost its live call", .{}),
    };
    if (current_node.tag != .expr_call or !std.meta.eql(current_call, call) or
        current_node.getPayload().expr_call.constraint_fn_var_plus_one != 0 or
        call.constraint_fn_var != null)
    {
        std.debug.panic("a call operand publication changed its zero-stamp call", .{});
    }
    const root_plan = self.cir.expected_consumption_plans.items.items[support.root_plan];
    const root_snapshot = expectedCallOperandProducerSnapshotFromPayload(
        self.cir,
        current_node.getPayload(),
    ) orelse std.debug.panic("a call operand publication lost its canonical call payload", .{});
    if (!expectedCallRootPlanMatchesSnapshot(self.cir, root_plan, root_snapshot)) {
        std.debug.panic("a call operand publication lost its successful root plan", .{});
    }
    const root_token_index = expectedCallSlotTokenIndex(
        self.cir,
        @intFromEnum(call_expr),
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse std.debug.panic("a call operand publication lost its root token", .{});
    const validated_root = ExpectedCallValidatedRoot{
        .plan_index = support.root_plan,
        .plan = root_plan,
        .call = root_snapshot,
        .root_token_index = root_token_index,
    };

    for (argument_exprs, argument_statuses, 0..) |argument_expr, status, slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        const argument_plan = support.argument_plans[slot_usize];
        if (argument_plan != support.root_plan + 1 + slot or
            !expectedCallArgumentPlanIsTerminal(
                self.cir,
                validated_root,
                argument_plan,
                slot,
            ) or !callOperandProducerChildMatchesStatus(
            self.cir,
            argument_expr,
            status,
        )) {
            std.debug.panic("a call operand publication changed an argument plan", .{});
        }
        var formal_matches: usize = 0;
        for (self.cir.expected_call_formals.items.items) |formal| {
            if (formal.owner_node != @intFromEnum(call_expr) or formal.slot != slot) continue;
            const slot_token_index = expectedCallSlotTokenIndex(
                self.cir,
                @intFromEnum(call_expr),
                .argument,
                slot,
            ) orelse std.debug.panic("a call operand publication lost an argument token", .{});
            if (!expectedCallFormalMatchesValidatedRoot(
                self.cir,
                formal,
                validated_root,
                argument_plan,
                slot_token_index,
            ) or formal.raw_formal_var != @intFromEnum(self.types.getVarAt(call_shape.args, slot))) {
                std.debug.panic("a call operand publication changed an exact formal", .{});
            }
            formal_matches += 1;
        }
        if (formal_matches != 1) {
            std.debug.panic("a call operand publication lost its unique formal", .{});
        }
    }

    const plan_count = std.math.cast(u32, argument_exprs.len + 1) orelse
        return error.OutOfMemory;
    const source_count_u32 = std.math.cast(u32, source_count) orelse
        return error.OutOfMemory;

    var existing_aggregate: ?AggregateExpectedRetirementDraft = null;
    for (self.aggregate_expected_retirement_drafts.items) |draft| {
        if (draft.owner_expr != call_expr) continue;
        if (existing_aggregate != null or draft.plans_start != support.root_plan or
            draft.plans_len != plan_count or
            draft.retired_reason != .call_retired_after_operand_checked_error)
        {
            std.debug.panic("a revisited call operand retirement changed its plan group", .{});
        }
        existing_aggregate = draft;
    }
    if (existing_aggregate) |aggregate| {
        var matched_count: usize = 0;
        for (argument_exprs, argument_statuses, 0..) |argument_expr, status, slot_usize| {
            const source = self.directBinderCallOperandSourceAtProducer(
                argument_expr,
                status,
            ) orelse continue;
            const slot: u32 = @intCast(slot_usize);
            const expected_failure = callOperandExpectedFailure(
                call_expr,
                argument_expr,
                slot,
                support.argument_plans[slot_usize],
                self.types.getVarAt(call_shape.args, slot),
                source.retirement_index,
            );
            var matches: usize = 0;
            for (self.annotation_expected_failure_drafts.items) |draft| {
                if (draft.owner_expr != call_expr) continue;
                if (draft.producer_kind != .call_operand or
                    draft.retirement_index != aggregate.retirement_index or
                    draft.failure_index >= self.cir.expected_failures.items.items.len)
                {
                    std.debug.panic("a revisited call changed its operand failure draft", .{});
                }
                if (expectedFailuresEqual(
                    self.cir.expected_failures.items.items[draft.failure_index],
                    expected_failure,
                )) matches += 1;
            }
            if (matches != 1) {
                std.debug.panic("a revisited call changed an exact operand failure", .{});
            }
            matched_count += 1;
        }
        var owned_draft_count: usize = 0;
        for (self.annotation_expected_failure_drafts.items) |draft| {
            if (draft.owner_expr == call_expr) owned_draft_count += 1;
        }
        if (matched_count != source_count or owned_draft_count != source_count) {
            std.debug.panic("a revisited call changed its complete operand cause set", .{});
        }
        return ModuleEnv.CauseOwner.expectedConsumerRetirement(
            aggregate.retirement_index,
        );
    }
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr == call_expr) {
            std.debug.panic("a call operand failure lost its aggregate retirement draft", .{});
        }
    }

    try self.cir.expected_consumer_retirements.items.ensureUnusedCapacity(
        self.cir.gpa,
        1,
    );
    try self.aggregate_expected_retirement_drafts.ensureUnusedCapacity(self.gpa, 1);
    try self.cir.expected_failures.items.ensureUnusedCapacity(
        self.cir.gpa,
        source_count_u32,
    );
    try self.annotation_expected_failure_drafts.ensureUnusedCapacity(
        self.gpa,
        source_count_u32,
    );
    const cause = try self.reserveExpectedPlanRetirement(
        call_expr,
        support.root_plan,
        plan_count,
        .call_retired_after_operand_checked_error,
    );
    const retirement_ref = cause.decodedExpectedConsumerRetirement() orelse unreachable;
    for (argument_exprs, argument_statuses, 0..) |argument_expr, status, slot_usize| {
        const source = self.directBinderCallOperandSourceAtProducer(
            argument_expr,
            status,
        ) orelse continue;
        const slot: u32 = @intCast(slot_usize);
        const failure = callOperandExpectedFailure(
            call_expr,
            argument_expr,
            slot,
            support.argument_plans[slot_usize],
            self.types.getVarAt(call_shape.args, slot),
            source.retirement_index,
        );
        const failure_index: u32 = @intCast(self.cir.expected_failures.items.items.len);
        if (!failure.hasLegalTagsAt(failure_index)) {
            std.debug.panic("a call operand producer built an illegal Expected failure", .{});
        }
        self.cir.expected_failures.items.appendAssumeCapacity(failure);
        self.annotation_expected_failure_drafts.appendAssumeCapacity(.{
            .owner_expr = call_expr,
            .retirement_index = retirement_ref.index,
            .failure_index = failure_index,
            .producer_kind = .call_operand,
        });
    }
    return cause;
}

const AggregateExpectedRetirementDraft = struct {
    owner_expr: CIR.Expr.Idx,
    retirement_index: u32,
    plans_start: u32,
    plans_len: u32,
    retired_reason: ModuleEnv.ExpectedConsumptionPlan.Reason,
};

/// Exact Expected-consumer plan range authored by one expression. The closed
/// union preserves which producer enumerated the range, so a later enclosing
/// branch rejection can retire the erased topology without reclassifying the
/// owner from its current CIR payload or plan outcomes.
const ExpectedOwnerPlanRange = struct {
    owner_expr: CIR.Expr.Idx,
    plans: union(enum) {
        aggregate: ExpectedAggregatePlanRange,
        branch: ExpectedBranchPlanRange,
    },
};

const RecordUpdateExpectedPlanRegistration = struct {
    owner_expr: CIR.Expr.Idx,
    plan_index: u32,
    role: ModuleEnv.ExpectedConsumptionPlan.Role,
    slot: u32,
    site: CIR.Expr.Idx,
};

const RecordUpdateOwnerRetirementDraft = struct {
    owner_expr: CIR.Expr.Idx,
    retirement_index: u32,
    base_plan_index: u32,
    base_cause: ModuleEnv.CauseOwner,
    original_node_tag: u32,
    original_payload: [4]u32,
};

const GenTypeAnnoCtx = union(enum) {
    annotation: AnnotationGenCtx,
    type_decl: struct {
        idx: CIR.Statement.Idx,
        name: Ident.Idx,
        type_: enum { nominal, alias },
        backing_var: Var,
        is_opaque: bool,
        num_args: u32,
    },

    const AnnotationGenCtx = struct {
        where: ?CIR.WhereClause.Span,
        /// Exact enclosing source scheme occurrence. Reusable where-alias
        /// declarations use `none`; expansion rebinds their contracts to the
        /// referencing annotation before the constraint can escape.
        producer_owner_node: u32,
        /// Set only while generating one reusable where-alias declaration.
        /// Nested declaration generation installs its own accumulator.
        where_alias_dependencies: ?*WhereAliasDependencyAccumulator = null,
        /// Exact checked-consumer publication ownership. Recursive generation
        /// and where-method subcontexts preserve this value unchanged.
        failure_publication: AnnotationFailurePublicationMode,
        /// Typed failures produced by this exact generation root. This is
        /// explicit context, never ambient checker state.
        failure_accumulator: *AnnotationGenerationAccumulator,
        /// Exact ownership of complete where-requirement source publication.
        /// Recursive generation and where-method subcontexts preserve this
        /// independently from Expected-failure ownership.
        where_source_publication: WhereMethodSourcePublicationMode,
        /// Whether extensionless tag unions in output (positive) positions are
        /// implicitly opened — given the anonymous `#others` rigid ext a
        /// written `..` produces, instead of `[]` — and polarity vars in
        /// referenced aliases resolved by position.
        ///
        /// Disabled for host-boundary annotations (hosted lambdas and
        /// `provides` defs): the host is not a Roc producer participating in
        /// unification, so those rows keep their written, closed meaning.
        opening: OpeningBehavior,

        pub const OpeningBehavior = enum {
            /// An output-position union gets a fresh flex ext, recorded for
            /// the post-body audit.
            implicit_open,
            /// An output-position union gets the polarity marker: the
            /// annotation is a where-method signature, a scheme the
            /// constrained body instantiates per use (fresh flex) and every
            /// obligation closes (`[]`). See `instantiateWhereMethodForUse`.
            per_use,
            /// Rows are generated as written (host boundaries).
            as_written,
        };
    };

    fn producerOwnerNode(self: GenTypeAnnoCtx) u32 {
        return switch (self) {
            .annotation => |ctx| ctx.producer_owner_node,
            .type_decl => std.math.maxInt(u32),
        };
    }

    fn whereAliasDependencies(self: GenTypeAnnoCtx) ?*WhereAliasDependencyAccumulator {
        return switch (self) {
            .annotation => |ctx| ctx.where_alias_dependencies,
            .type_decl => null,
        };
    }

    /// How polarity vars in referenced type declarations should be
    /// instantiated when this ctx generates a lookup/apply of a declaration.
    fn polarityVarBehavior(self: GenTypeAnnoCtx) PolarityVarBehavior {
        return switch (self) {
            .annotation => |anno_ctx| switch (anno_ctx.opening) {
                .implicit_open => .resolve_by_polarity,
                // A referenced alias's markers stay deferred inside a
                // where-method signature: the signature's own instantiation
                // decides them.
                .per_use => .defer_open,
                .as_written => .close,
            },
            // An alias body keeps the decision deferred (its own use sites
            // decide); a nominal body has no use-site polarity, so its rows
            // close as written.
            .type_decl => |decl| switch (decl.type_) {
                .alias => .preserve,
                .nominal => .close,
            },
        };
    }
};

/// Publish a root's complete written where-requirement sequence. Type-tree
/// generation groups clauses by rigid owner, so scratch order is not source
/// order; the canonical where span supplies the dense whole-root ordinal.
/// Every allocation and every coordinate check precedes the first durable
/// append or evidence-range mutation.
fn publishWhereMethodSourcesForRoot(
    self: *Self,
    ctx: GenTypeAnnoCtx,
    scratch_start: usize,
) Allocator.Error!void {
    const anno_ctx = switch (ctx) {
        .annotation => |annotation_ctx| annotation_ctx,
        .type_decl => @panic("type declarations cannot publish body where-method sources"),
    };
    const scratch_end = self.scratch_static_dispatch_constraints.top();
    if (scratch_start > scratch_end) {
        @panic("where-method source scratch interval moved backwards");
    }
    const entries = self.scratch_static_dispatch_constraints.items.items[scratch_start..scratch_end];

    switch (anno_ctx.where_source_publication) {
        .no_publication => {
            for (entries) |entry| {
                if (entry.source_ordinal != std.math.maxInt(u32) or
                    entry.source_index != std.math.maxInt(u32))
                {
                    @panic("nonpublishing annotation retained a where-method source draft");
                }
            }
            return;
        },
        .body_annotation => {
            const annotation_idx: CIR.Annotation.Idx = @enumFromInt(anno_ctx.producer_owner_node);
            const attachment_valid = switch (anno_ctx.failure_publication) {
                .body_expression => |body| self.cir.bodyAnnotationAttachmentIndex(
                    body.attachment.kind,
                    body.attachment.node,
                    annotation_idx,
                    body.owner_expr,
                ) != null,
                .preexisting_runtime_error_owner => |body| self.cir.bodyAnnotationAttachmentIndex(
                    body.attachment.kind,
                    body.attachment.node,
                    annotation_idx,
                    body.owner_expr,
                ) != null,
                .no_publication => false,
            };
            if (anno_ctx.producer_owner_node >= self.cir.store.nodes.len() or
                self.cir.store.nodes.get(@enumFromInt(anno_ctx.producer_owner_node)).tag != .annotation or
                !attachment_valid)
            {
                @panic("body where-method source lacked its exact annotation attachment");
            }
        },
    }

    if (entries.len == 0) return;
    const where_span = anno_ctx.where orelse
        @panic("where-method source scratch escaped an annotation where span");
    for (entries) |entry| {
        if (entry.state != .completed or
            entry.producer_owner_node != anno_ctx.producer_owner_node or
            entry.store_index == std.math.maxInt(u32) or
            entry.store_index >= self.types.static_dispatch_constraints.len() or
            entry.source_ordinal != std.math.maxInt(u32) or
            entry.source_index != std.math.maxInt(u32))
        {
            @panic("where-method source draft was not a complete root-owned constraint");
        }
    }

    var next_ordinal: u32 = 0;
    for (self.cir.store.sliceWhereClauses(where_span)) |where_idx| {
        for (entries) |*entry| {
            if (entry.where_clause != where_idx) continue;
            if (entry.source_ordinal != std.math.maxInt(u32)) {
                @panic("where-method source clause appeared more than once in its root span");
            }
            entry.source_ordinal = next_ordinal;
            next_ordinal = std.math.add(u32, next_ordinal, 1) catch return error.OutOfMemory;
        }
    }
    if (next_ordinal != entries.len) {
        @panic("where-method source scratch was not exhausted by its written root span");
    }

    const source_base = std.math.cast(u32, self.cir.where_method_sources.items.items.len) orelse
        return error.OutOfMemory;
    _ = std.math.add(u32, source_base, next_ordinal) catch return error.OutOfMemory;
    try self.cir.where_method_sources.items.ensureUnusedCapacity(self.gpa, entries.len);
    try self.cir.dispatch_settlement_sources.items.ensureUnusedCapacity(self.gpa, entries.len);
    try self.types.constraint_evidence_handles.items.ensureUnusedCapacity(self.types.gpa, entries.len);

    var ordinal: u32 = 0;
    while (ordinal < next_ordinal) : (ordinal += 1) {
        var matched_entry: ?*ScratchStaticDispatchConstraint = null;
        for (entries) |*entry| {
            if (entry.source_ordinal != ordinal) continue;
            if (matched_entry != null) @panic("where-method source ordinal was not unique");
            matched_entry = entry;
        }
        const entry = matched_entry orelse @panic("where-method source ordinal was not dense");
        const retained = self.types.static_dispatch_constraints.items.items[entry.store_index];
        if (@as(u32, @bitCast(retained.fn_name)) != entry.producer_method_name or
            self.types.resolveVar(retained.fn_var).var_ !=
                self.types.resolveVar(entry.constraint.fn_var).var_)
        {
            @panic("where-method source callable did not match its retained constraint");
        }
        const where_node = @intFromEnum(ModuleEnv.nodeIdxFrom(entry.where_clause));
        const source_range = entry.constraint.where_method_markers;
        const source_contracts_start: u32 = if (source_range.len() == 0)
            0
        else
            @intFromEnum(source_range.start);
        if (!rangeFits(
            source_contracts_start,
            source_range.len(),
            self.types.where_method_marker_contracts.items.items.len,
        )) {
            @panic("where-method source marker range escaped its contract pool");
        }
        for (self.types.sliceWhereMethodMarkerContracts(source_range)) |contract| {
            if (contract.producer_owner_node != entry.producer_owner_node or
                contract.producer_where_node != where_node or
                contract.producer_method_name != entry.producer_method_name)
            {
                @panic("where-method source marker range changed its producer identity");
            }
        }
        const source_index = source_base + ordinal;
        entry.source_index = source_index;
        self.cir.where_method_sources.items.appendAssumeCapacity(.{
            .owner_node = entry.producer_owner_node,
            .where_node = where_node,
            .method_ident = entry.producer_method_name,
            .source_ordinal = ordinal,
            .retained_constraint_index = entry.store_index,
            .source_contracts_start = source_contracts_start,
            .source_contracts_len = @intCast(source_range.len()),
        });
        self.cir.dispatch_settlement_sources.items.appendAssumeCapacity(
            ModuleEnv.DispatchSettlementSource.whereRequirement(source_index),
        );
    }

    // Evidence ranges follow retained constraint order even when written
    // source order interleaves multiple constrained rigids. Within one range,
    // source indices are increasing and therefore canonically ordered.
    var previous_store_index: ?u32 = null;
    while (true) {
        var next_store_index: ?u32 = null;
        for (entries) |entry| {
            if (previous_store_index != null and entry.store_index <= previous_store_index.?) continue;
            if (next_store_index == null or entry.store_index < next_store_index.?) {
                next_store_index = entry.store_index;
            }
        }
        const store_index = next_store_index orelse break;
        const retained = &self.types.static_dispatch_constraints.items.items[store_index];
        if (retained.constraint_evidence.start != 0 or retained.constraint_evidence.len != 0) {
            @panic("new where-method source constraint already carried evidence");
        }
        const evidence_start: u32 = @intCast(self.types.constraint_evidence_handles.items.items.len);
        var evidence_len: u32 = 0;
        ordinal = 0;
        while (ordinal < next_ordinal) : (ordinal += 1) {
            for (entries) |entry| {
                if (entry.source_ordinal != ordinal or entry.store_index != store_index) continue;
                self.types.constraint_evidence_handles.items.appendAssumeCapacity(.{
                    .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.where_requirement_source),
                    .index = entry.source_index,
                });
                evidence_len += 1;
            }
        }
        retained.constraint_evidence = .{ .start = evidence_start, .len = evidence_len };
        previous_store_index = store_index;
    }
}

fn recordTypeDeclDependencyFromContext(
    self: *Self,
    ctx: GenTypeAnnoCtx,
    dependency_idx: CIR.Statement.Idx,
) std.mem.Allocator.Error!void {
    switch (ctx) {
        .annotation => {},
        .type_decl => |decl| try self.recordTypeDeclDependency(decl.idx, dependency_idx),
    }
}

fn recordTypeDeclAnnoResult(self: *Self, ctx: GenTypeAnnoCtx, anno_var: Var) void {
    switch (ctx) {
        .annotation => {},
        .type_decl => |decl| {
            if (self.types.resolveVar(anno_var).desc.content == .err) {
                self.markTypeDeclInvalid(decl.idx);
            }
        },
    }
}

/// Reserve the unique checker-rewrite retirement for an expression at the
/// exact producer decision which first makes that rewrite inevitable. The
/// diagnostic and owned failure range deliberately remain incomplete until
/// `replaceExprWithRuntimeError` selects the final runtime-error diagnostic.
fn reserveIneligibleFailureRetirement(
    self: *Self,
    owner_expr: CIR.Expr.Idx,
    producer_kind: AnnotationExpectedFailureDraft.ProducerKind,
) std.mem.Allocator.Error!u32 {
    const owner_raw: u32 = @intFromEnum(owner_expr);
    const current_node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(owner_expr));
    if (!isExprNodeTag(current_node.tag)) {
        std.debug.panic("annotation failure cannot reserve a checker rewrite without an exact original expression tag", .{});
    }

    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != owner_expr) continue;
        if (draft.producer_kind != producer_kind) {
            std.debug.panic("one ineligible expression mixed failure producers", .{});
        }
        if (draft.retirement_index >= self.cir.expected_consumer_retirements.items.items.len) {
            std.debug.panic("ineligible failure draft lost its reserved retirement", .{});
        }
        const retirement = self.cir.expected_consumer_retirements.items.items[draft.retirement_index];
        if (retirement.retired_node != owner_raw or
            retirement.decodedOwnerKind() != .expression or
            retirement.decodedKind() != .checker_rewrite_ineligible or
            retirement.original_node_tag != @intFromEnum(current_node.tag) or
            !std.meta.eql(retirement.original_payload, @as([4]u32, @bitCast(current_node.getPayload()))) or
            retirement.diagnostic_index != ModuleEnv.ExpectedConsumerRetirement.none or
            retirement.expected_failures_start != 0 or
            retirement.expected_failures_len != 0)
        {
            std.debug.panic("ineligible failure changed its pre-rewrite retirement draft", .{});
        }
        return draft.retirement_index;
    }

    // One typed expression owner has exactly one retirement identity. Do not
    // borrow a baseline or another producer's checker rewrite merely because
    // it happens to use the same raw node number.
    for (self.cir.expected_consumer_retirements.items.items) |retirement| {
        if (retirement.owner_kind == @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression) and
            retirement.retired_node == owner_raw)
        {
            std.debug.panic("ineligible failure collided with another retirement producer", .{});
        }
    }

    const retirement = try self.cir.expected_consumer_retirements.append(self.cir.gpa, .{
        .retired_node = owner_raw,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression),
        .original_node_tag = @intFromEnum(current_node.tag),
        .original_payload = @bitCast(current_node.getPayload()),
        .kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible),
        .retired_consumers_start = 0,
        .retired_consumers_len = 0,
        .diagnostic_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .expected_failures_start = 0,
        .expected_failures_len = 0,
        .rejection_owner_kind = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_owner_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_subject_var = ModuleEnv.ExpectedConsumerRetirement.none,
    });
    return @intFromEnum(retirement);
}

fn validatePreexistingRuntimeErrorAnnotationSuppression(
    self: *const Self,
    owner_expr: CIR.Expr.Idx,
    cause_owner: ModuleEnv.CauseOwner,
) void {
    if (!cause_owner.hasCanonicalTags(true)) {
        std.debug.panic("preexisting annotation suppression carried a noncanonical cause", .{});
    }
    const cause = cause_owner.decodedExpectedConsumerRetirement() orelse
        std.debug.panic("preexisting annotation suppression did not cite a retirement", .{});
    if (cause.index >= self.cir.expected_consumer_retirements.items.items.len) {
        std.debug.panic("preexisting annotation suppression cited a missing retirement", .{});
    }
    const retirement = self.cir.expected_consumer_retirements.items.items[cause.index];
    if (retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != .preexisting_runtime_error or
        retirement.retired_node != @intFromEnum(owner_expr) or
        retirement.retired_consumers_start != 0 or
        retirement.retired_consumers_len != 0 or
        retirement.expected_failures_start != 0 or
        retirement.expected_failures_len != 0 or
        !expectedConsumerRetirementNodeIsLocallyValid(self.cir, retirement))
    {
        std.debug.panic("preexisting annotation suppression changed its exact empty baseline retirement", .{});
    }
}

/// Author the exact malformed-type failure at its leaf. Nonpublishing modes
/// return the canonical diagnostic cause without touching durable Expected
/// pools; only a body-expression scope creates the failure and its explicit
/// pending retirement attachment.
fn malformedAnnotationGenerationFailure(
    self: *Self,
    anno_idx: CIR.TypeAnno.Idx,
    diagnostic: CIR.Diagnostic.Idx,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!?AnnotationGenerationFailure {
    if (!self.cir.store.isDiagnosticIndex(diagnostic) or
        self.cir.store.getTypeAnno(anno_idx) != .malformed or
        self.cir.store.getTypeAnno(anno_idx).malformed.diagnostic != diagnostic)
    {
        std.debug.panic("malformed annotation producer lost its exact CIR diagnostic", .{});
    }

    const diagnostic_cause = ModuleEnv.CauseOwner.cirDiagnostic(@intFromEnum(diagnostic));
    const anno_ctx = switch (ctx) {
        .type_decl => return null,
        .annotation => |annotation_ctx| annotation_ctx,
    };
    const body = switch (anno_ctx.failure_publication) {
        .no_publication => return .{
            .kind = .annotation_malformed_type,
            .cause_owner = diagnostic_cause,
        },
        .body_expression => |body| body,
        .preexisting_runtime_error_owner => |owner| {
            self.validatePreexistingRuntimeErrorAnnotationSuppression(
                owner.owner_expr,
                owner.cause_owner,
            );
            _ = bodyAnnotationMalformedTypePublicationIndex(
                self.cir,
                owner.attachment,
                anno_ctx.producer_owner_node,
                @intFromEnum(owner.owner_expr),
                malformedTypeAnnotationPublicationIndex(
                    self.cir,
                    @intFromEnum(anno_idx),
                    @intFromEnum(diagnostic),
                ) orelse std.debug.panic(
                    "suppressed malformed annotation lacked its typed canonicalization publication",
                    .{},
                ),
            ) orelse std.debug.panic(
                "suppressed malformed annotation lacked its exact canonicalization body attachment",
                .{},
            );
            anno_ctx.failure_accumulator.recordSuppression(owner.cause_owner);
            return null;
        },
    };

    const owner_expr = body.owner_expr;
    const owner_raw: u32 = @intFromEnum(owner_expr);
    const site_raw: u32 = @intFromEnum(anno_idx);
    const none = ModuleEnv.ExpectedFailure.none;
    const malformed_type_publication_index = malformedTypeAnnotationPublicationIndex(
        self.cir,
        site_raw,
        @intFromEnum(diagnostic),
    ) orelse std.debug.panic(
        "malformed annotation lacked its typed canonicalization publication",
        .{},
    );
    const body_publication_index = bodyAnnotationMalformedTypePublicationIndex(
        self.cir,
        body.attachment,
        anno_ctx.producer_owner_node,
        owner_raw,
        malformed_type_publication_index,
    ) orelse std.debug.panic(
        "malformed annotation lacked its exact canonicalization body attachment",
        .{},
    );
    const expected_failure = ModuleEnv.ExpectedFailure{
        .owner_node = owner_raw,
        .site_node = site_raw,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type),
        .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(owner_expr)),
        .raw_subject_var = @intFromEnum(ModuleEnv.varFrom(anno_idx)),
        .raw_peer_var = none,
        .constraint_index = none,
        .slot = 0,
        .plan_index = none,
        .subject_authority = ModuleEnv.SubjectAuthority.direct(
            site_raw,
            .annotation_malformed_type,
            body_publication_index,
        ),
        .cause_owner = diagnostic_cause,
    };
    if (!expected_failure.hasLegalTags()) {
        std.debug.panic("malformed annotation producer built an illegal Expected failure", .{});
    }

    // Expression checking can revisit one node after more constraints settle.
    // Reuse the exact producer row rather than publishing a duplicate key.
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != owner_expr or
            draft.failure_index >= self.cir.expected_failures.items.items.len)
        {
            continue;
        }
        const existing = self.cir.expected_failures.items.items[draft.failure_index];
        if (existing.site_node != site_raw or existing.kind != expected_failure.kind) continue;
        if (!expectedFailuresEqual(existing, expected_failure)) {
            std.debug.panic("revisited malformed annotation changed its exact failure publication", .{});
        }
        return .{
            .kind = .annotation_malformed_type,
            .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(draft.retirement_index),
            .failure_index = draft.failure_index,
        };
    }

    const retirements_len = self.cir.expected_consumer_retirements.items.items.len;
    const failures_len = self.cir.expected_failures.items.items.len;
    const drafts_len = self.annotation_expected_failure_drafts.items.len;
    errdefer {
        self.cir.expected_consumer_retirements.items.shrinkRetainingCapacity(retirements_len);
        self.cir.expected_failures.items.shrinkRetainingCapacity(failures_len);
        self.annotation_expected_failure_drafts.shrinkRetainingCapacity(drafts_len);
    }

    const retirement_index = try self.reserveIneligibleFailureRetirement(owner_expr, .annotation);
    const failure = try self.cir.expected_failures.append(self.cir.gpa, expected_failure);
    const failure_index: u32 = @intFromEnum(failure);
    try self.annotation_expected_failure_drafts.append(self.gpa, .{
        .owner_expr = owner_expr,
        .retirement_index = retirement_index,
        .failure_index = failure_index,
    });
    return .{
        .kind = .annotation_malformed_type,
        .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index),
        .failure_index = failure_index,
    };
}

/// Author the exact failure for a malformed child occupying one tag-union
/// member slot. The parent tag union is the subject and producer site, while
/// the canonicalization-authored body/malformed join authenticates the exact
/// child diagnostic which made that slot invalid.
fn invalidTagChildAnnotationGenerationFailure(
    self: *Self,
    tag_union_idx: CIR.TypeAnno.Idx,
    malformed_child_idx: CIR.TypeAnno.Idx,
    child_slot: u32,
    diagnostic: CIR.Diagnostic.Idx,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!?AnnotationGenerationFailure {
    const parent = self.cir.store.getTypeAnno(tag_union_idx);
    if (parent != .tag_union) {
        std.debug.panic("invalid-tag annotation producer lost its parent tag union", .{});
    }
    const tag_children = self.cir.store.sliceTypeAnnos(parent.tag_union.tags);
    const child_offset: usize = @intCast(child_slot);
    if (child_offset >= tag_children.len or
        tag_children[child_offset] != malformed_child_idx)
    {
        std.debug.panic("invalid-tag annotation producer changed its exact child slot", .{});
    }
    const child = self.cir.store.getTypeAnno(malformed_child_idx);
    if (!self.cir.store.isDiagnosticIndex(diagnostic) or
        child != .malformed or
        child.malformed.diagnostic != diagnostic)
    {
        std.debug.panic("invalid-tag annotation producer lost its exact malformed child diagnostic", .{});
    }

    const diagnostic_cause = ModuleEnv.CauseOwner.cirDiagnostic(@intFromEnum(diagnostic));
    const anno_ctx = switch (ctx) {
        .type_decl => return null,
        .annotation => |annotation_ctx| annotation_ctx,
    };
    const malformed_type_publication_index = malformedTypeAnnotationPublicationIndex(
        self.cir,
        @intFromEnum(malformed_child_idx),
        @intFromEnum(diagnostic),
    ) orelse std.debug.panic(
        "invalid-tag annotation child lacked its typed canonicalization publication",
        .{},
    );
    const body = switch (anno_ctx.failure_publication) {
        .no_publication => return .{
            .kind = .annotation_invalid_tag_child,
            .cause_owner = diagnostic_cause,
        },
        .body_expression => |body| body,
        .preexisting_runtime_error_owner => |owner| {
            self.validatePreexistingRuntimeErrorAnnotationSuppression(
                owner.owner_expr,
                owner.cause_owner,
            );
            const body_publication_index = bodyAnnotationMalformedTypePublicationIndex(
                self.cir,
                owner.attachment,
                anno_ctx.producer_owner_node,
                @intFromEnum(owner.owner_expr),
                malformed_type_publication_index,
            ) orelse std.debug.panic(
                "suppressed invalid-tag annotation lacked its exact canonicalization body attachment",
                .{},
            );
            const body_publication = self.cir.body_annotation_malformed_type_publications.items.items[
                body_publication_index
            ];
            const attachment_index = self.cir.bodyAnnotationAttachmentIndex(
                body_publication.decodedAttachmentKind() orelse
                    std.debug.panic("suppressed invalid-tag annotation carried an invalid attachment kind", .{}),
                body_publication.attachment_node,
                @enumFromInt(body_publication.annotation_root),
                owner.owner_expr,
            ) orelse std.debug.panic(
                "suppressed invalid-tag annotation lost its generic body attachment",
                .{},
            );
            if (!self.cir.bodyAnnotationAttachmentContainsTypeAnno(
                attachment_index,
                tag_union_idx,
            )) {
                std.debug.panic("suppressed invalid-tag annotation parent escaped its annotation root", .{});
            }
            anno_ctx.failure_accumulator.recordSuppression(owner.cause_owner);
            return null;
        },
    };

    const owner_expr = body.owner_expr;
    const owner_raw: u32 = @intFromEnum(owner_expr);
    const site_raw: u32 = @intFromEnum(tag_union_idx);
    const none = ModuleEnv.ExpectedFailure.none;
    const body_publication_index = bodyAnnotationMalformedTypePublicationIndex(
        self.cir,
        body.attachment,
        anno_ctx.producer_owner_node,
        owner_raw,
        malformed_type_publication_index,
    ) orelse std.debug.panic(
        "invalid-tag annotation lacked its exact canonicalization body attachment",
        .{},
    );
    const body_publication = self.cir.body_annotation_malformed_type_publications.items.items[
        body_publication_index
    ];
    const attachment_index = self.cir.bodyAnnotationAttachmentIndex(
        body_publication.decodedAttachmentKind() orelse
            std.debug.panic("invalid-tag annotation carried an invalid attachment kind", .{}),
        body_publication.attachment_node,
        @enumFromInt(body_publication.annotation_root),
        owner_expr,
    ) orelse std.debug.panic(
        "invalid-tag annotation lost its generic body attachment",
        .{},
    );
    if (!self.cir.bodyAnnotationAttachmentContainsTypeAnno(
        attachment_index,
        tag_union_idx,
    )) {
        std.debug.panic("invalid-tag annotation parent escaped its annotation root", .{});
    }

    const expected_failure = ModuleEnv.ExpectedFailure{
        .owner_node = owner_raw,
        .site_node = site_raw,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.annotation_invalid_tag_child),
        .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(owner_expr)),
        .raw_subject_var = @intFromEnum(ModuleEnv.varFrom(tag_union_idx)),
        .raw_peer_var = none,
        .constraint_index = none,
        .slot = child_slot,
        .plan_index = none,
        .subject_authority = ModuleEnv.SubjectAuthority.direct(
            site_raw,
            .annotation_invalid_tag_child,
            body_publication_index,
        ),
        .cause_owner = diagnostic_cause,
    };
    if (!expected_failure.hasLegalTags()) {
        std.debug.panic("invalid-tag annotation producer built an illegal Expected failure", .{});
    }

    // A repeated check of the same expression must replay the same first
    // malformed member, including its ordinal, rather than minting another
    // producer key for the tag union.
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != owner_expr or
            draft.failure_index >= self.cir.expected_failures.items.items.len)
        {
            continue;
        }
        const existing = self.cir.expected_failures.items.items[draft.failure_index];
        if (existing.site_node != site_raw or existing.kind != expected_failure.kind) continue;
        if (!expectedFailuresEqual(existing, expected_failure)) {
            std.debug.panic("revisited invalid-tag annotation changed its exact failure publication", .{});
        }
        return .{
            .kind = .annotation_invalid_tag_child,
            .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(draft.retirement_index),
            .failure_index = draft.failure_index,
        };
    }

    const retirements_len = self.cir.expected_consumer_retirements.items.items.len;
    const failures_len = self.cir.expected_failures.items.items.len;
    const drafts_len = self.annotation_expected_failure_drafts.items.len;
    errdefer {
        self.cir.expected_consumer_retirements.items.shrinkRetainingCapacity(retirements_len);
        self.cir.expected_failures.items.shrinkRetainingCapacity(failures_len);
        self.annotation_expected_failure_drafts.shrinkRetainingCapacity(drafts_len);
    }

    const retirement_index = try self.reserveIneligibleFailureRetirement(owner_expr, .annotation);
    const failure = try self.cir.expected_failures.append(self.cir.gpa, expected_failure);
    const failure_index: u32 = @intFromEnum(failure);
    try self.annotation_expected_failure_drafts.append(self.gpa, .{
        .owner_expr = owner_expr,
        .retirement_index = retirement_index,
        .failure_index = failure_index,
    });
    return .{
        .kind = .annotation_invalid_tag_child,
        .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index),
        .failure_index = failure_index,
    };
}

fn bodyAnnotationAttachmentIndexForTypeAnno(
    cir: *const ModuleEnv,
    attachment: BodyAnnotationAttachment,
    annotation_root: u32,
    body_expr: CIR.Expr.Idx,
    anno_idx: CIR.TypeAnno.Idx,
) ?u32 {
    const attachment_index = cir.bodyAnnotationAttachmentIndex(
        attachment.kind,
        attachment.node,
        @enumFromInt(annotation_root),
        body_expr,
    ) orelse return null;
    if (!cir.bodyAnnotationAttachmentContainsTypeAnno(attachment_index, anno_idx)) return null;
    return attachment_index;
}

fn bodyAnnotationAttachmentIndexForWhereClause(
    cir: *const ModuleEnv,
    attachment: BodyAnnotationAttachment,
    annotation_root: u32,
    body_expr: CIR.Expr.Idx,
    annotation_anno: CIR.TypeAnno.Idx,
    where_idx: CIR.WhereClause.Idx,
) ?u32 {
    const attachment_index = cir.bodyAnnotationAttachmentIndex(
        attachment.kind,
        attachment.node,
        @enumFromInt(annotation_root),
        body_expr,
    ) orelse return null;
    const attachment_row = cir.body_annotation_attachments.items.items[attachment_index];
    const annotation_node = cir.store.nodes.get(@enumFromInt(attachment_row.annotation_root));
    if (annotation_node.tag != .annotation) return null;
    const annotation = annotation_node.getPayload().annotation;
    if (annotation.flags.unused != 0 or
        annotation.anno != @intFromEnum(annotation_anno) or
        (attachment_row.decodedAttachmentKind() == .local_var and annotation.flags.introduces_type_var) or
        !cir.bodyAnnotationAttachmentContainsWhereClause(attachment_index, where_idx))
    {
        return null;
    }
    return attachment_index;
}

/// Author one malformed member of the exact written where span. The malformed
/// WhereClause is the producer site, while the main annotation occurrence is
/// the raw subject which the clause poisons.
fn malformedWhereAnnotationGenerationFailure(
    self: *Self,
    annotation_anno: CIR.TypeAnno.Idx,
    where_idx: CIR.WhereClause.Idx,
    where_slot: u32,
    diagnostic: CIR.Diagnostic.Idx,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!?AnnotationGenerationFailure {
    const anno_ctx = switch (ctx) {
        .type_decl => return null,
        .annotation => |annotation_ctx| annotation_ctx,
    };
    const where_span = anno_ctx.where orelse
        std.debug.panic("malformed-where producer lost its written where span", .{});
    const clauses = self.cir.store.sliceWhereClauses(where_span);
    const slot: usize = where_slot;
    if (slot >= clauses.len or clauses[slot] != where_idx or
        !malformedWhereClauseDiagnosticIsLocallyValid(self.cir, where_idx, diagnostic))
    {
        std.debug.panic("malformed-where producer changed its exact clause, ordinal, or diagnostic", .{});
    }

    const diagnostic_cause = ModuleEnv.CauseOwner.cirDiagnostic(@intFromEnum(diagnostic));
    const body = switch (anno_ctx.failure_publication) {
        .no_publication => |reason| switch (reason) {
            .predeclared_scheme,
            .uninitialized_var,
            .platform_requirement,
            .where_alias_declaration,
            => return .{
                .kind = .annotation_malformed_where,
                .cause_owner = diagnostic_cause,
            },
        },
        .body_expression => |body| body,
        .preexisting_runtime_error_owner => |owner| {
            self.validatePreexistingRuntimeErrorAnnotationSuppression(
                owner.owner_expr,
                owner.cause_owner,
            );
            _ = bodyAnnotationAttachmentIndexForWhereClause(
                self.cir,
                owner.attachment,
                anno_ctx.producer_owner_node,
                owner.owner_expr,
                annotation_anno,
                where_idx,
            ) orelse std.debug.panic(
                "suppressed malformed where clause lacked its exact body attachment",
                .{},
            );
            anno_ctx.failure_accumulator.recordSuppression(owner.cause_owner);
            return null;
        },
    };

    const owner_expr = body.owner_expr;
    const owner_raw: u32 = @intFromEnum(owner_expr);
    const site_raw: u32 = @intFromEnum(where_idx);
    const attachment_index = bodyAnnotationAttachmentIndexForWhereClause(
        self.cir,
        body.attachment,
        anno_ctx.producer_owner_node,
        owner_expr,
        annotation_anno,
        where_idx,
    ) orelse std.debug.panic(
        "malformed where clause lacked its exact body attachment",
        .{},
    );
    const none = ModuleEnv.ExpectedFailure.none;
    const expected_failure = ModuleEnv.ExpectedFailure{
        .owner_node = owner_raw,
        .site_node = site_raw,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.annotation_malformed_where),
        .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(owner_expr)),
        .raw_subject_var = @intFromEnum(ModuleEnv.varFrom(annotation_anno)),
        .raw_peer_var = none,
        .constraint_index = none,
        .slot = where_slot,
        .plan_index = none,
        .subject_authority = ModuleEnv.SubjectAuthority.direct(
            site_raw,
            .annotation_malformed_where,
            attachment_index,
        ),
        .cause_owner = diagnostic_cause,
    };
    if (!expected_failure.hasLegalTags()) {
        std.debug.panic("malformed-where producer built an illegal Expected failure", .{});
    }

    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != owner_expr or
            draft.failure_index >= self.cir.expected_failures.items.items.len)
        {
            continue;
        }
        const existing = self.cir.expected_failures.items.items[draft.failure_index];
        if (existing.site_node != site_raw or existing.kind != expected_failure.kind) continue;
        if (!expectedFailuresEqual(existing, expected_failure)) {
            std.debug.panic("revisited malformed where clause changed its exact failure publication", .{});
        }
        return .{
            .kind = .annotation_malformed_where,
            .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(draft.retirement_index),
            .failure_index = draft.failure_index,
        };
    }

    const retirements_len = self.cir.expected_consumer_retirements.items.items.len;
    const failures_len = self.cir.expected_failures.items.items.len;
    const drafts_len = self.annotation_expected_failure_drafts.items.len;
    errdefer {
        self.cir.expected_consumer_retirements.items.shrinkRetainingCapacity(retirements_len);
        self.cir.expected_failures.items.shrinkRetainingCapacity(failures_len);
        self.annotation_expected_failure_drafts.shrinkRetainingCapacity(drafts_len);
    }

    const retirement_index = try self.reserveIneligibleFailureRetirement(owner_expr, .annotation);
    const failure = try self.cir.expected_failures.append(self.cir.gpa, expected_failure);
    const failure_index: u32 = @intFromEnum(failure);
    try self.annotation_expected_failure_drafts.append(self.gpa, .{
        .owner_expr = owner_expr,
        .retirement_index = retirement_index,
        .failure_index = failure_index,
    });
    return .{
        .kind = .annotation_malformed_where,
        .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index),
        .failure_index = failure_index,
    };
}

/// Scan every written clause before ordinary annotation-tree generation. This
/// outer transaction makes a multi-malformed span atomic when a later draft
/// allocation fails after an earlier member was already published.
fn scanMalformedWhereClauses(
    self: *Self,
    annotation_anno: CIR.TypeAnno.Idx,
    where_span: CIR.WhereClause.Span,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!bool {
    const anno_ctx = switch (ctx) {
        .type_decl => return false,
        .annotation => |annotation_ctx| annotation_ctx,
    };
    if (anno_ctx.where == null or !std.meta.eql(anno_ctx.where.?, where_span)) {
        std.debug.panic("malformed-where scan changed its exact annotation span", .{});
    }

    const retirements_len = self.cir.expected_consumer_retirements.items.items.len;
    const failures_len = self.cir.expected_failures.items.items.len;
    const drafts_len = self.annotation_expected_failure_drafts.items.len;
    errdefer {
        self.cir.expected_consumer_retirements.items.shrinkRetainingCapacity(retirements_len);
        self.cir.expected_failures.items.shrinkRetainingCapacity(failures_len);
        self.annotation_expected_failure_drafts.shrinkRetainingCapacity(drafts_len);
    }

    var saw_malformed = false;
    for (self.cir.store.sliceWhereClauses(where_span), 0..) |where_idx, where_slot| {
        switch (self.cir.store.getWhereClause(where_idx)) {
            .w_malformed => |malformed| {
                saw_malformed = true;
                if (try self.malformedWhereAnnotationGenerationFailure(
                    annotation_anno,
                    where_idx,
                    @intCast(where_slot),
                    malformed.diagnostic,
                    ctx,
                )) |failure| {
                    anno_ctx.failure_accumulator.record(failure);
                }
            },
            .w_method, .w_alias => {},
        }
    }
    return saw_malformed;
}

/// Publish the direct failure for using the builtin `Num` module as a type.
/// Unlike malformed syntax, this branch has no producer diagnostic: the
/// failure carries canonical inactive cause bytes and its owner retirement
/// independently records the final runtime-error diagnostic.
fn builtinNotTypeAnnotationGenerationFailure(
    self: *Self,
    anno_idx: CIR.TypeAnno.Idx,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!?AnnotationGenerationFailure {
    const raw_site: u32 = @intFromEnum(anno_idx);
    const node_tag = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(anno_idx)).tag;
    const is_builtin_num = switch (self.cir.store.getTypeAnno(anno_idx)) {
        .lookup => |lookup| switch (lookup.base) {
            .builtin => |builtin_type| node_tag == .ty_lookup and builtin_type == .num,
            .local, .external, .pending => false,
        },
        .apply => |apply| switch (apply.base) {
            .builtin => |builtin_type| node_tag == .ty_apply and builtin_type == .num,
            .local, .external, .pending => false,
        },
        else => false,
    };
    if (!is_builtin_num) {
        std.debug.panic("builtin-not-type producer lost its exact Num lookup/application", .{});
    }

    const anno_ctx = switch (ctx) {
        .type_decl => return null,
        .annotation => |annotation_ctx| annotation_ctx,
    };
    const no_cause = ModuleEnv.CauseOwner.inactive();
    const body = switch (anno_ctx.failure_publication) {
        .no_publication => |reason| switch (reason) {
            .predeclared_scheme,
            .uninitialized_var,
            .platform_requirement,
            .where_alias_declaration,
            => return .{
                .kind = .annotation_builtin_not_type,
                .cause_owner = no_cause,
            },
        },
        .body_expression => |body| body,
        .preexisting_runtime_error_owner => |owner| {
            self.validatePreexistingRuntimeErrorAnnotationSuppression(
                owner.owner_expr,
                owner.cause_owner,
            );
            _ = bodyAnnotationAttachmentIndexForTypeAnno(
                self.cir,
                owner.attachment,
                anno_ctx.producer_owner_node,
                owner.owner_expr,
                anno_idx,
            ) orelse std.debug.panic(
                "suppressed builtin-not-type annotation lacked its exact body attachment",
                .{},
            );
            anno_ctx.failure_accumulator.recordSuppression(owner.cause_owner);
            return null;
        },
    };

    const owner_expr = body.owner_expr;
    const owner_raw: u32 = @intFromEnum(owner_expr);
    const attachment_index = bodyAnnotationAttachmentIndexForTypeAnno(
        self.cir,
        body.attachment,
        anno_ctx.producer_owner_node,
        owner_expr,
        anno_idx,
    ) orelse std.debug.panic(
        "builtin-not-type annotation lacked its exact body attachment",
        .{},
    );
    const none = ModuleEnv.ExpectedFailure.none;
    const expected_failure = ModuleEnv.ExpectedFailure{
        .owner_node = owner_raw,
        .site_node = raw_site,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.annotation_builtin_not_type),
        .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(owner_expr)),
        .raw_subject_var = @intFromEnum(ModuleEnv.varFrom(anno_idx)),
        .raw_peer_var = none,
        .constraint_index = none,
        .slot = 0,
        .plan_index = none,
        .subject_authority = ModuleEnv.SubjectAuthority.direct(
            raw_site,
            .annotation_builtin_not_type,
            attachment_index,
        ),
        .cause_owner = no_cause,
    };
    if (!expected_failure.hasLegalTags()) {
        std.debug.panic("builtin-not-type producer built an illegal Expected failure", .{});
    }

    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != owner_expr or
            draft.failure_index >= self.cir.expected_failures.items.items.len)
        {
            continue;
        }
        const existing = self.cir.expected_failures.items.items[draft.failure_index];
        if (existing.site_node != raw_site or existing.kind != expected_failure.kind) continue;
        if (!expectedFailuresEqual(existing, expected_failure)) {
            std.debug.panic("revisited builtin-not-type annotation changed its exact failure publication", .{});
        }
        return .{
            .kind = .annotation_builtin_not_type,
            .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(draft.retirement_index),
            .failure_index = draft.failure_index,
        };
    }

    const retirements_len = self.cir.expected_consumer_retirements.items.items.len;
    const failures_len = self.cir.expected_failures.items.items.len;
    const drafts_len = self.annotation_expected_failure_drafts.items.len;
    errdefer {
        self.cir.expected_consumer_retirements.items.shrinkRetainingCapacity(retirements_len);
        self.cir.expected_failures.items.shrinkRetainingCapacity(failures_len);
        self.annotation_expected_failure_drafts.shrinkRetainingCapacity(drafts_len);
    }

    const retirement_index = try self.reserveIneligibleFailureRetirement(owner_expr, .annotation);
    const failure = try self.cir.expected_failures.append(self.cir.gpa, expected_failure);
    const failure_index: u32 = @intFromEnum(failure);
    try self.annotation_expected_failure_drafts.append(self.gpa, .{
        .owner_expr = owner_expr,
        .retirement_index = retirement_index,
        .failure_index = failure_index,
    });
    return .{
        .kind = .annotation_builtin_not_type,
        .cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index),
        .failure_index = failure_index,
    };
}

fn generateAnnotationType(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
    env: *Env,
    failure_publication: AnnotationFailurePublicationMode,
) std.mem.Allocator.Error!AnnotationGenerationOutcome {
    const trace = tracy.trace(@src());
    defer trace.end();

    const event_scope_pushed = try self.beginPredeclaredAnnoEventScope(annotation_idx);
    var abort_event_scope = event_scope_pushed;
    defer if (abort_event_scope) self.abortPredeclaredAnnoEventScope();

    const annotation_var = ModuleEnv.varFrom(annotation_idx);
    try self.setVarRank(annotation_var, env);
    try self.recordPredeclaredAnnoVarEvent(.annotation_root, 0, annotation_var);

    const annotation = self.cir.store.getAnnotation(annotation_idx);

    // Every implicitly opened extension this generation mints is recorded for
    // the post-body audit (`auditImplicitOpenExts`); the range is committed
    // at the end of this function.
    const implicit_open_exts_start: u32 = @intCast(self.implicit_open_exts.items.len);

    // Reset seen type annos
    self.seen_annos.unsetAll();

    // Save top of scratch static dispatch constraints
    const scratch_static_dispatch_constraints_top = self.scratch_static_dispatch_constraints.top();
    defer self.scratch_static_dispatch_constraints.clearFrom(scratch_static_dispatch_constraints_top);

    // Then, generate the type for the annotation.
    //
    // Host-boundary annotations (hosted lambdas and `provides` defs) keep
    // their rows as written: the host side is a fixed ABI, not a Roc producer,
    // so implicit polarity opening does not apply across that boundary.
    const opening: GenTypeAnnoCtx.AnnotationGenCtx.OpeningBehavior = if (self.host_boundary_annotations.contains(annotation_idx))
        .as_written
    else
        .implicit_open;
    var failure_accumulator = AnnotationGenerationAccumulator{};
    const ctx = GenTypeAnnoCtx{ .annotation = .{
        .where = annotation.where,
        .producer_owner_node = @intFromEnum(annotation_idx),
        .failure_publication = failure_publication,
        .failure_accumulator = &failure_accumulator,
        .where_source_publication = switch (failure_publication) {
            .body_expression, .preexisting_runtime_error_owner => .body_annotation,
            .no_publication => |reason| switch (reason) {
                .predeclared_scheme => .{ .no_publication = .predeclared_scheme },
                .uninitialized_var => .{ .no_publication = .uninitialized_var },
                .platform_requirement => .{ .no_publication = .platform_requirement },
                .where_alias_declaration => .{ .no_publication = .where_alias_declaration },
            },
        },
        .opening = opening,
    } };
    const malformed_where = if (annotation.where) |where_span|
        try self.scanMalformedWhereClauses(annotation.anno, where_span, ctx)
    else
        false;
    try self.generateAnnoTypeInPlace(annotation.anno, env, ctx, .pos);
    if (malformed_where) {
        try self.markErroneous(ModuleEnv.varFrom(annotation.anno));
    }
    if (annotation.where) |where_span| {
        if (try self.generateRemainingWhereConstraintOwners(where_span, env, ctx)) {
            try self.markErroneous(ModuleEnv.varFrom(annotation.anno));
        }
    }
    try self.publishWhereMethodSourcesForRoot(
        ctx,
        scratch_static_dispatch_constraints_top,
    );

    try self.annotation_implicit_open_exts.put(self.gpa, annotation_idx, .{
        .start = implicit_open_exts_start,
        .len = @intCast(self.implicit_open_exts.items.len - implicit_open_exts_start),
    });

    // Redirect the root annotation to inner annotation
    _ = try self.unify(annotation_var, ModuleEnv.varFrom(annotation.anno), env);
    try self.recordPredeclaredAnnoVarEvent(.annotation_final_root, 0, annotation_var);

    if (event_scope_pushed) {
        // `finishPredeclaredAnnoEventScope` owns removal even when its replay
        // validation fails; the checker aborts in that case and must not pop a
        // parent scope a second time.
        abort_event_scope = false;
        try self.finishPredeclaredAnnoEventScope();
    }

    return failure_accumulator.finish(annotation_var);
}

/// One implicitly opened tag-union extension minted while generating an
/// annotation, with the region of the tag union it extends.
const ImplicitOpenExt = struct {
    var_: Var,
    region: Region,
    /// The region of the explicit anonymous `..` this extension came from,
    /// when it did (an output-position `..` is generated like absence); null
    /// for an absent ext or an alias marker resolved open. Reported as
    /// redundant when the binding generalizes regardless of it.
    explicit_ext_region: ?Region = null,
    /// The tags the annotation lists on the union this extension opens,
    /// captured when the extension is minted. They cannot be re-read from
    /// the union var after the body check: unifying the annotated row with
    /// the body's row merges both sides into one descriptor holding every
    /// tag, listed or not. The audit uses them to suggest a listed tag for
    /// an unlisted one that looks like a typo; null (no hint) when the
    /// minting site did not see the union.
    listed_tags: ?types_mod.Tag.SafeMultiList.Range = null,
};

/// The slice of `implicit_open_exts` one annotation's generation minted.
const ImplicitOpenExtRange = struct {
    start: u32,
    len: u32,
};

/// After a binding's right-hand side has been checked against its annotation,
/// verify that the definition did not EXTEND any implicitly opened tag-union
/// row (design.md "Polarity": the annotation bounds the definition; only its
/// callers widen the row, at instantiation). An implicitly opened extension is
/// a flex var during the body check so a closed value can flow into the row
/// (closing it) and an open value can share it; a tag the annotation does not
/// list is absorbed into that flex by ordinary unification, so it is detected
/// here rather than at the producing expression.
///
/// `redundant_open_warns`: the binding generalizes regardless of any written
/// `..` (a function, a pure signature, a value alias), so an explicit
/// anonymous `..` in an output position adds nothing and warns. On a value
/// binding `..` is the opt-in to a quantified row, so it never warns there.
fn auditImplicitOpenExts(self: *Self, annotation_idx: CIR.Annotation.Idx, redundant_open_warns: bool) std.mem.Allocator.Error!void {
    const range = self.annotation_implicit_open_exts.get(annotation_idx) orelse return;
    for (self.implicit_open_exts.items[range.start..][0..range.len]) |entry| {
        if (redundant_open_warns) {
            if (entry.explicit_ext_region) |open_region| {
                _ = try self.problems.appendProblem(self.gpa, .{ .redundant_open_tag_union = .{
                    .region = open_region,
                } });
            }
        }
        const resolved = self.types.resolveVar(entry.var_);
        if (resolved.desc.content != .structure) continue;
        if (resolved.desc.content.structure != .tag_union) continue;
        const extension = resolved.desc.content.structure.tag_union;
        if (extension.tags.count == 0) continue;
        const first_tag = self.types.tags.get(extension.tags.start);
        // The same close-match judgment as the Type Mismatch tag-typo hint,
        // over the tags the annotation actually lists.
        const suggestion: ?Ident.Idx = if (entry.listed_tags) |listed_tags|
            type_diff.findBestTypoSuggestion(
                first_tag.name,
                self.types.getTagsSlice(listed_tags).items(.name),
                self.cir.getIdentStoreConst(),
            )
        else
            null;
        _ = try self.problems.appendProblem(self.gpa, .{ .tag_union_extended_beyond_annotation = .{
            .region = entry.region,
            .tag_name = first_tag.name,
            .suggestion = suggestion,
        } });
        try self.markErroneous(entry.var_);
    }
}

/// After the module solves, ground every still-open implicitly opened
/// extension of a top-level weak value binding to `[]` (design.md
/// "Polarity"). Nothing in this module can widen the row any further, and
/// the closed row is exactly what the annotation produced before polarity,
/// so importers and Monotype's stored constants see the type they always
/// did. An extension that meanwhile joined a generalized scheme (a function's
/// quantified row) is left alone: closing a quantified variable after it has
/// been instantiated would desync the scheme from its uses.
fn closeWeakValueImplicitOpenExts(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    for (self.weak_value_implicit_open_ext_ranges.items) |range| {
        for (self.implicit_open_exts.items[range.start..][0..range.len]) |entry| {
            const resolved = self.types.resolveVar(entry.var_);
            if (resolved.desc.content != .flex) continue;
            if (resolved.desc.content.flex.constraints.len() != 0) continue;
            if (resolved.desc.rank == .generalized) continue;
            const empty_tu_var = try self.freshFromContent(.{ .structure = .empty_tag_union }, env, entry.region);
            _ = try self.unify(entry.var_, empty_tu_var, env);
        }
    }
}

/// Whether this ext anno is the anonymous `..` of an open tag union or
/// record (canonicalized as a rigid var named `#others`). User-written type
/// vars can never collide: `#` is not valid in source identifiers.
fn annoIsAnonymousOpenExt(self: *const Self, ext_anno_idx: CIR.TypeAnno.Idx) bool {
    const ext_anno = self.cir.store.getTypeAnno(ext_anno_idx);
    return ext_anno == .rigid_var and ext_anno.rigid_var.name.eql(self.cir.idents.open_ext);
}

/// Push every constraint one where clause places on `owner_var`. A method
/// clause declares exactly one, left for `completeOwnedStaticDispatchConstraint`
/// to type from its annotation; a where alias contributes each constraint it
/// names, already typed by instantiating the declaration.
fn declareOwnedStaticDispatchConstraints(
    self: *Self,
    where_idx: CIR.WhereClause.Idx,
    producer_owner_node: u32,
    owner_var: Var,
    dependency_accumulator: ?*WhereAliasDependencyAccumulator,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!void {
    const where_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(where_idx));
    switch (self.cir.store.getWhereClause(where_idx)) {
        .w_method => |method| {
            const func_var = try self.fresh(env, where_region);
            try self.recordPredeclaredAnnoVarEvent(
                .fresh_var,
                @intFromEnum(PredeclaredAnnoFreshSlot.where_method_function),
                func_var,
            );

            try self.scratch_static_dispatch_constraints.append(ScratchStaticDispatchConstraint{
                .where_clause = where_idx,
                .producer_owner_node = producer_owner_node,
                .producer_method_name = @bitCast(method.method_name),
                .var_ = owner_var,
                .constraint = StaticDispatchConstraint{
                    .fn_name = method.method_name,
                    .fn_var = func_var,
                    .origin = .{ .where_clause = .{} },
                },
                .state = .declared,
            });
        },
        .w_alias => |alias| try self.declareWhereAliasConstraints(
            where_idx,
            producer_owner_node,
            alias,
            owner_var,
            dependency_accumulator,
            env,
            ctx,
        ),
        .w_malformed => {
            try self.markErroneous(owner_var);
        },
    }
}

fn completeOwnedStaticDispatchConstraint(
    self: *Self,
    where_idx: CIR.WhereClause.Idx,
    method: std.meta.fieldInfo(CIR.WhereClause, .w_method).type,
    owner_var: Var,
    constraint_index: usize,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!void {
    const entry = self.scratch_static_dispatch_constraints.items.items[constraint_index];
    if (entry.state != .declared or entry.where_clause != where_idx or entry.var_ != owner_var) {
        try self.markErroneous(entry.var_);
        try self.markStaticDispatchRejected(entry.constraint);
        self.scratch_static_dispatch_constraints.items.items[constraint_index].state = .completed;
        return;
    }

    // A where-method signature is a SCHEME the constrained body instantiates
    // at each use, exactly like a call of an annotated function, and that
    // every obligation instantiates closed. Its implicitly opened output
    // rows are therefore generated as polarity markers (`.per_use`): a body
    // use resolves them to fresh flex vars (`instantiateWhereMethodForUse`),
    // so the body may match the result exhaustively or widen it per use, and
    // an obligation at the enclosing scheme's instantiation sites closes
    // them, bounding an implementation by the listed tags. The signature is
    // walked like any function annotation: its arguments are inputs (closed
    // as written) and its return an output.
    const method_ctx: GenTypeAnnoCtx = switch (ctx) {
        .annotation => |anno_ctx| .{ .annotation = .{
            .where = anno_ctx.where,
            .producer_owner_node = anno_ctx.producer_owner_node,
            .failure_publication = anno_ctx.failure_publication,
            .failure_accumulator = anno_ctx.failure_accumulator,
            .where_source_publication = anno_ctx.where_source_publication,
            .opening = switch (anno_ctx.opening) {
                .implicit_open, .per_use => .per_use,
                .as_written => .as_written,
            },
        } },
        .type_decl => ctx,
    };

    // The receiver is a rigid var anno; polarity is irrelevant for it.
    try self.generateAnnoTypeInPlace(method.var_, env, method_ctx, .neg);

    const args_anno_slice = self.cir.store.sliceTypeAnnos(method.args);
    for (args_anno_slice) |arg_anno_idx| {
        try self.generateAnnoTypeInPlace(arg_anno_idx, env, method_ctx, .neg);
    }
    const anno_arg_vars: []Var = @ptrCast(args_anno_slice);

    try self.generateAnnoTypeInPlace(method.ret, env, method_ctx, .pos);
    const ret_var = ModuleEnv.varFrom(method.ret);

    const func_content = if (method.effectful)
        try self.types.mkFuncEffectful(anno_arg_vars, ret_var)
    else
        try self.types.mkFuncPure(anno_arg_vars, ret_var);
    try self.unifyWith(entry.constraint.fn_var, func_content, env);
    self.scratch_static_dispatch_constraints.items.items[constraint_index].state = .completed;
}

/// Relate two written occurrences of one method-keyed where constraint. The
/// row marker is a compiler-owned per-use decision, not a user rigid. Ordinary
/// signature unification therefore merges only rigids with the exact reserved
/// marker name; every source-written rigid and every structural component keeps
/// the ordinary exact relation.
fn relateDuplicateWhereMethodSignature(
    self: *Self,
    representative_fn: Var,
    duplicate_fn: Var,
    env: *Env,
) std.mem.Allocator.Error!void {
    _ = try self.runUnify(representative_fn, duplicate_fn, env, .{
        .duplicate_where_signature_marker_ident = self.cir.idents.polarity_var,
    });
}

fn generateRemainingWhereConstraintOwners(
    self: *Self,
    where_span: CIR.WhereClause.Span,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!bool {
    var invalid_receiver = false;
    for (self.cir.store.sliceWhereClauseOwners(where_span)) |owner| {
        if (owner.owned_by_annotation) {
            // The owner is a rigid var anno; polarity is irrelevant for it.
            try self.generateAnnoTypeInPlace(@enumFromInt(owner.rigid_var), env, ctx, .neg);
            continue;
        }

        invalid_receiver = true;
        const rigid_anno = self.cir.store.getTypeAnno(@enumFromInt(owner.rigid_var));
        std.debug.assert(rigid_anno == .rigid_var);
        const type_var_name = rigid_anno.rigid_var.name;
        for (self.cir.store.sliceWhereClausesForOwner(owner)) |where_idx| {
            switch (self.cir.store.getWhereClause(where_idx)) {
                .w_method => |method| {
                    _ = try self.problems.appendProblem(self.gpa, .{ .where_clause_receiver_not_introduced = .{
                        .type_var_name = type_var_name,
                        .method_name = method.method_name,
                        .region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(where_idx)),
                    } });
                },
                .w_alias, .w_malformed => {},
            }
        }
    }
    return invalid_receiver;
}

/// Report and poison a type reference that names a where alias, which is a set
/// of method constraints rather than a type. Returns true once reported.
fn rejectWhereAliasInTypePosition(
    self: *Self,
    name: Ident.Idx,
    base_ref: CIR.TypeAnno.LocalOrExternal,
    anno_var: Var,
    anno_region: Region,
    _: *Env,
) std.mem.Allocator.Error!bool {
    const names_where_alias = switch (base_ref) {
        .local => |local| self.cir.store.getStatement(local.decl_idx) == .s_where_alias_decl,
        .external => |ext| blk: {
            const ext_ref = (try self.resolveVarFromExternal(
                ext.module_idx,
                ext.target_node_idx,
                externalTypeAnnotationLookupUse(
                    self.cir,
                    @enumFromInt(@intFromEnum(anno_var)),
                ),
            )) orelse break :blk false;
            const stmt: CIR.Statement.Idx = @enumFromInt(@intFromEnum(ext_ref.other_cir_node_idx));
            break :blk ext_ref.other_cir.store.getStatement(stmt) == .s_where_alias_decl;
        },
        .builtin, .pending => false,
    };
    if (!names_where_alias) return false;

    _ = try self.problems.appendProblem(self.gpa, .{ .where_alias_in_type_position = .{
        .name = name,
        .region = anno_region,
    } });
    try self.markErroneous(anno_var);
    return true;
}

/// A where alias declaration, resolved from a reference to it. Every variable
/// is in this module's type store, so a reference to an imported alias has
/// already been copied across the module boundary.
const WhereAliasPublicationRef = union(enum) {
    local: struct { publication_index: u32 },
    semantic_dependency: struct {
        dependency_index: u32,
        publication_index: u32,
    },

    fn isLocal(self: @This()) bool {
        return self == .local;
    }
};

const ResolvedWhereAlias = struct {
    /// The name the where clause used to refer to the declaration.
    name: Ident.Idx,
    /// The receiver, a rigid variable carrying the alias's own constraints.
    receiver: Var,
    /// The declaration's parameters, in declared order. Each is a rigid
    /// variable, and may carry constraints of its own.
    params: []const Var,
    publication: ModuleEnv.WhereAliasDeclarationPublication,
    publication_ref: WhereAliasPublicationRef,
};

/// Resolve a where clause's reference to a where alias declaration. Returns
/// null once the reason it could not resolve has been reported.
fn resolveWhereAliasReference(
    self: *Self,
    alias_anno_idx: CIR.TypeAnno.Idx,
    params_scratch: *std.ArrayListUnmanaged(Var),
    env: *Env,
) std.mem.Allocator.Error!?ResolvedWhereAlias {
    const anno = self.cir.store.getTypeAnno(alias_anno_idx);
    const region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(alias_anno_idx));
    const name, const base_ref = switch (anno) {
        .lookup => |lookup| .{ lookup.name, lookup.base },
        .apply => |apply| .{ apply.name, apply.base },
        // Canonicalization already reported why this name has no referent.
        .malformed => return null,
        .rigid_var,
        .rigid_var_lookup,
        .underscore,
        .tag_union,
        .tag,
        .tuple,
        .record,
        .@"fn",
        .parens,
        => unreachable, // canonicalization only builds a name reference here
    };

    switch (base_ref) {
        .local => |local| {
            const decl = switch (self.cir.store.getStatement(local.decl_idx)) {
                .s_where_alias_decl => |decl| decl,
                .s_decl,
                .s_var,
                .s_var_uninitialized,
                .s_reassign,
                .s_crash,
                .s_dbg,
                .s_expr,
                .s_expect,
                .s_for,
                .s_while,
                .s_infinite_loop,
                .s_breakable_loop,
                .s_break,
                .s_return,
                .s_import,
                .s_alias_decl,
                .s_nominal_decl,
                .s_type_anno,
                .s_type_var_alias,
                .s_runtime_error,
                => return try self.reportNotAWhereAlias(name, region),
            };

            if (!try self.ensureTypeDeclGenerated(local.decl_idx, env)) {
                _ = try self.problems.appendProblem(self.gpa, .{ .recursive_where_alias = .{
                    .name = name,
                    .region = region,
                } });
                return null;
            }

            for (self.cir.store.sliceTypeAnnos(self.cir.store.getTypeHeader(decl.header).args)) |param_anno_idx| {
                try params_scratch.append(self.gpa, ModuleEnv.varFrom(param_anno_idx));
            }
            const indexed_publication = indexedWhereAliasDeclarationPublication(
                self.cir,
                @intFromEnum(local.decl_idx),
            ) orelse @panic("generated local where alias had no settlement publication");
            return ResolvedWhereAlias{
                .name = name,
                .receiver = ModuleEnv.varFrom(decl.receiver),
                .params = params_scratch.items,
                .publication = indexed_publication.publication,
                .publication_ref = .{ .local = .{
                    .publication_index = indexed_publication.index,
                } },
            };
        },
        .external => |ext| {
            const resolved_module = self.cir.imports.getResolvedModule(ext.module_idx) orelse
                return null;
            if (resolved_module >= self.imported_modules.len) return null;
            const provider = self.imported_modules[resolved_module];
            if (ext.target_node_idx >= provider.store.nodes.len()) return null;
            if (provider.store.nodes.get(@enumFromInt(ext.target_node_idx)).tag !=
                .statement_where_alias_decl)
            {
                return try self.reportNotAWhereAlias(name, region);
            }
            const ext_ref = (try self.resolveVarFromExternal(
                ext.module_idx,
                ext.target_node_idx,
                .{
                    .site_kind = .external_where_alias_receiver,
                    .origin_node = @intFromEnum(alias_anno_idx),
                },
            )) orelse {
                // Canonicalization already reported the unresolved import.
                return null;
            };
            const decl = switch (ext_ref.other_cir.store.getStatement(@enumFromInt(@intFromEnum(ext_ref.other_cir_node_idx)))) {
                .s_where_alias_decl => |decl| decl,
                .s_decl,
                .s_var,
                .s_var_uninitialized,
                .s_reassign,
                .s_crash,
                .s_dbg,
                .s_expr,
                .s_expect,
                .s_for,
                .s_while,
                .s_infinite_loop,
                .s_breakable_loop,
                .s_break,
                .s_return,
                .s_import,
                .s_alias_decl,
                .s_nominal_decl,
                .s_type_anno,
                .s_type_var_alias,
                .s_runtime_error,
                => return try self.reportNotAWhereAlias(name, region),
            };

            // Each parameter is copied on its own. Every type variable a where
            // alias's constraints can mention is either the receiver or a
            // parameter, and both are substituted by name below, so the copies
            // do not need to share variables with each other.
            for (ext_ref.other_cir.store.sliceTypeAnnos(ext_ref.other_cir.store.getTypeHeader(decl.header).args), 0..) |param_anno_idx, parameter_ordinal| {
                const param_ref = (try self.resolveVarFromExternal(
                    ext.module_idx,
                    @intFromEnum(param_anno_idx),
                    .{
                        .site_kind = .external_where_alias_parameter,
                        .origin_node = @intFromEnum(alias_anno_idx),
                        .parameter_ordinal = @intCast(parameter_ordinal),
                    },
                )) orelse return null;
                try params_scratch.append(self.gpa, param_ref.local_var);
            }
            const indexed_publication = indexedWhereAliasDeclarationPublication(
                ext_ref.other_cir,
                @intFromEnum(ext_ref.other_cir_node_idx),
            ) orelse @panic("admitted imported where alias had no settlement publication");
            return ResolvedWhereAlias{
                .name = name,
                .receiver = ext_ref.local_var,
                .params = params_scratch.items,
                .publication = indexed_publication.publication,
                .publication_ref = .{ .semantic_dependency = .{
                    .dependency_index = self.semanticDependencyIndexForEnv(ext_ref.other_cir),
                    .publication_index = indexed_publication.index,
                } },
            };
        },
        .builtin => return try self.reportNotAWhereAlias(name, region),
        // An unresolvable import; canonicalization already reported it.
        .pending => return null,
    }
}

/// Report that a where clause named something other than a where alias. Always
/// returns null, so resolution can `return` it directly.
fn reportNotAWhereAlias(self: *Self, name: Ident.Idx, region: Region) std.mem.Allocator.Error!?ResolvedWhereAlias {
    _ = try self.problems.appendProblem(self.gpa, .{ .not_a_where_alias = .{
        .name = name,
        .region = region,
    } });
    return null;
}

/// Expand a where alias reference into the constraints it names, applied to the
/// referencing signature's own type variables.
fn declareWhereAliasConstraints(
    self: *Self,
    where_idx: CIR.WhereClause.Idx,
    producer_owner_node: u32,
    alias: std.meta.fieldInfo(CIR.WhereClause, .w_alias).type,
    owner_var: Var,
    dependency_accumulator: ?*WhereAliasDependencyAccumulator,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!void {
    const region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(where_idx));

    var params_scratch: std.ArrayListUnmanaged(Var) = .empty;
    defer params_scratch.deinit(self.gpa);
    switch (self.cir.store.getTypeAnno(alias.alias)) {
        .malformed => |malformed| {
            const publishes_direct_source = switch (ctx) {
                .annotation => |anno_ctx| switch (anno_ctx.failure_publication) {
                    .body_expression => true,
                    .no_publication, .preexisting_runtime_error_owner => false,
                },
                .type_decl => false,
            };
            if (publishes_direct_source) {
                // This capacity belongs to the same logical publication as the
                // durable malformed failure. Reserve it before that producer can
                // commit so allocation failure cannot strand a failure without
                // its exact formal-source transport.
                try self.direct_formal_failure_sources.ensureUnusedCapacity(self.gpa, 1);
            }
            if (try self.malformedAnnotationGenerationFailure(
                alias.alias,
                malformed.diagnostic,
                ctx,
            )) |failure| {
                if (publishes_direct_source !=
                    (failure.failure_index != ModuleEnv.ExpectedFailure.none))
                {
                    std.debug.panic("a malformed where alias changed its body source publication mode", .{});
                }
                if (publishes_direct_source) {
                    self.recordDirectFormalFailureSourceAssumeCapacity(
                        where_idx,
                        alias.alias,
                        owner_var,
                        failure,
                        ctx,
                    );
                }
                switch (ctx) {
                    .annotation => |anno_ctx| anno_ctx.failure_accumulator.record(failure),
                    .type_decl => unreachable,
                }
            }
            try self.markErroneous(owner_var);
            return;
        },
        else => {},
    }
    const resolved = (try self.resolveWhereAliasReference(alias.alias, &params_scratch, env)) orelse {
        try self.markErroneous(owner_var);
        return;
    };
    if (dependency_accumulator) |accumulator| {
        accumulator.observe(resolved.publication, resolved.publication_ref.isLocal());
    }
    if (resolved.publication.decodedOutcome() != .ready) {
        try self.markErroneous(owner_var);
        return;
    }

    // Already generated by `generateWhereAliasReferenceArgs`.
    const arg_vars: []const Var = @ptrCast(self.whereAliasReferenceArgs(alias));

    if (arg_vars.len != resolved.params.len) {
        _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
            .type_name = resolved.name,
            .region = region,
            .num_expected_args = @intCast(resolved.params.len),
            .num_actual_args = @intCast(arg_vars.len),
        } });
        try self.markErroneous(owner_var);
        return;
    }

    // Every rigid variable in the declaration is either the receiver or a
    // parameter, so substituting all of them by name rewrites the declaration's
    // constraints into this signature's variables.
    var subs = std.AutoHashMapUnmanaged(Ident.Idx, Var){};
    defer subs.deinit(self.gpa);
    var substitution_origins = std.AutoHashMapUnmanaged(Ident.Idx, u32){};
    defer substitution_origins.deinit(self.gpa);
    const receiver_rigid = self.resolvedRigid(resolved.receiver) orelse {
        try self.markErroneous(owner_var);
        return;
    };
    try subs.put(self.gpa, receiver_rigid.name, owner_var);
    try substitution_origins.put(self.gpa, receiver_rigid.name, 0);
    for (resolved.params, arg_vars, 0..) |param_var, arg_var, param_index| {
        if (self.resolvedRigid(param_var)) |param_rigid| {
            try subs.put(self.gpa, param_rigid.name, arg_var);
            try substitution_origins.put(self.gpa, param_rigid.name, @intCast(param_index + 1));
        }
    }

    // Canonicalization rejects a declaration whose constraints are not all on
    // its receiver, so the receiver carries the whole set. Instantiating one
    // appends to the constraint store, so iterate rather than hold a slice.
    var constraints = self.types.iterStaticDispatchConstraints(receiver_rigid.constraints);
    while (constraints.next()) |constraint| {
        try self.scratch_static_dispatch_constraints.append(ScratchStaticDispatchConstraint{
            .where_clause = where_idx,
            .producer_owner_node = producer_owner_node,
            .producer_method_name = @bitCast(constraint.fn_name),
            .var_ = owner_var,
            .constraint = try self.instantiateWhereAliasConstraint(
                constraint,
                producer_owner_node,
                @intFromEnum(ModuleEnv.nodeIdxFrom(where_idx)),
                @bitCast(constraint.fn_name),
                &subs,
                &substitution_origins,
                region,
                env,
            ),
            .state = .completed,
        });
    }
}

/// The arguments a where clause supplies for a where alias's parameters.
fn whereAliasReferenceArgs(self: *Self, alias: std.meta.fieldInfo(CIR.WhereClause, .w_alias).type) []const CIR.TypeAnno.Idx {
    return switch (self.cir.store.getTypeAnno(alias.alias)) {
        .apply => |apply| self.cir.store.sliceTypeAnnos(apply.args),
        // A name canonicalization could not resolve carries no arguments; it is
        // reported when the reference is resolved.
        .lookup, .malformed => &.{},
        .rigid_var,
        .rigid_var_lookup,
        .underscore,
        .tag_union,
        .tag,
        .tuple,
        .record,
        .@"fn",
        .parens,
        => unreachable, // canonicalization only builds a name reference here
    };
}

/// Generate the types of the arguments a where alias reference supplies.
fn generateWhereAliasReferenceArgs(
    self: *Self,
    alias: std.meta.fieldInfo(CIR.WhereClause, .w_alias).type,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!void {
    // A reference's arguments are substituted into the declaration's
    // parameters, which are matched rather than produced, so they carry the
    // written, closed meaning.
    for (self.whereAliasReferenceArgs(alias)) |arg_anno_idx| {
        try self.generateAnnoTypeInPlace(arg_anno_idx, env, ctx, .neg);
    }
}

/// Rewrite one of a where alias declaration's constraints into the referencing
/// signature's variables.
fn instantiateWhereAliasConstraint(
    self: *Self,
    constraint: StaticDispatchConstraint,
    producer_owner_node: u32,
    producer_where_node: u32,
    producer_method_name: u32,
    subs: *std.AutoHashMapUnmanaged(Ident.Idx, Var),
    substitution_origins: *const std.AutoHashMapUnmanaged(Ident.Idx, u32),
    region: Region,
    env: *Env,
) std.mem.Allocator.Error!StaticDispatchConstraint {
    if (constraint.where_method_markers.len() != 0 or
        constraint.where_method_marker_bases.len() != 0)
    {
        std.debug.panic("where-alias declaration unexpectedly carried body-owned marker contracts", .{});
    }
    const fn_var = try self.instantiateVarWithSubsPolarized(
        constraint.fn_var,
        subs,
        substitution_origins,
        env,
        .{ .explicit = region },
        .preserve,
        .pos,
    );
    const where_method_markers = try self.makeWhereMethodMarkerContracts(
        fn_var,
        producer_owner_node,
        producer_where_node,
        producer_method_name,
    );
    return StaticDispatchConstraint{
        .fn_name = constraint.fn_name,
        .fn_var = fn_var,
        .origin = .{ .where_clause = .{} },
        .where_method_markers = where_method_markers,
    };
}

/// The rigid variable a where alias declaration's receiver or parameter
/// resolved to. Null when the declaration was poisoned, in which case it
/// names no constraints and binds no name to substitute.
fn resolvedRigid(self: *Self, var_: Var) ?Rigid {
    return switch (self.types.resolveVar(var_).desc.content) {
        .rigid => |rigid| rigid,
        .flex, .alias, .field_presence, .structure, .err => null,
    };
}

/// Given an annotation, generate the corresponding type based on the CIR
///
/// This is used both for generation annotation types and type declaration types
///
/// This function will write the type into the type var node at `anno_idx`
///
/// Note on scoping for type decls: Type scopes are defined in czer
///   Point(x) : [Point(x, x)]
///        a^          b^  ^c
///
/// So `a` get the node CIR.TypeAnno.rigid_var{ .. }
/// And `b` & `c` get the node CIR.TypeAnno.rigid_var_lookup{ .ref = <a_id> }
/// Then, any reference to `b` or `c` are replaced with `a` in `generateAnnoTypeInPlace`.
///
/// `polarity` is the position of this anno within the annotation being
/// generated: annotations start at `.pos` (output) and function argument
/// positions negate it. Extensionless tag unions are implicitly opened in
/// `.pos` positions (see `AnnotationGenCtx.opening`); within type
/// declarations polarity is unused because the open-vs-closed decision is
/// deferred to use-site instantiation via polarity vars.
fn generateAnnoTypeInPlace(self: *Self, anno_idx: CIR.TypeAnno.Idx, env: *Env, ctx: GenTypeAnnoCtx, polarity: Polarity) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // First, check if we've seen this anno before
    // This guards against recursive types
    if (self.typeAnnoSeen(anno_idx)) {
        return;
    }

    const previous_event_anchor = self.setPredeclaredAnnoEventAnchor(@intFromEnum(anno_idx));
    defer self.restorePredeclaredAnnoEventAnchor(previous_event_anchor);

    // Get the annotation
    const anno = self.cir.store.getTypeAnno(anno_idx);
    const anno_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(anno_idx));
    const anno_var = ModuleEnv.varFrom(anno_idx);
    try self.setVarRank(anno_var, env);
    try self.recordPredeclaredAnnoVarEvent(.type_anno_node, 0, anno_var);
    defer self.recordTypeDeclAnnoResult(ctx, anno_var);

    // Put this anno in the "seen" map immediately, to support recursive references
    self.markTypeAnnoSeen(anno_idx);

    switch (anno) {
        .rigid_var => |rigid| {
            if (ctx == .type_decl) {
                if (self.type_decl_rigid_vars.get(rigid.name)) |decl_var| {
                    _ = try self.unify(anno_var, decl_var, env);
                    return;
                }
            }
            const owned_where_clauses: []const CIR.WhereClause.Idx = switch (ctx) {
                .annotation => |anno_ctx| blk: {
                    const where_span = anno_ctx.where orelse break :blk &.{};
                    for (self.cir.store.sliceWhereClauseOwners(where_span)) |owner| {
                        if (owner.rigid_var == @intFromEnum(anno_idx) and owner.owned_by_annotation) {
                            break :blk self.cir.store.sliceWhereClausesForOwner(owner);
                        }
                    }
                    break :blk &.{};
                },
                .type_decl => &.{},
            };
            // A where alias reference's arguments can be this annotation's own
            // constrained type variables, whose generation declares constraints
            // of their own. Generate them before opening this dispatcher's
            // scratch range so those constraints cannot land inside it.
            for (owned_where_clauses) |where_idx| {
                switch (self.cir.store.getWhereClause(where_idx)) {
                    .w_alias => |alias| try self.generateWhereAliasReferenceArgs(alias, env, ctx),
                    .w_method, .w_malformed => {},
                }
            }

            // One source clause can declare more than one constraint: a where
            // alias contributes every constraint it names.
            const scratch_constraints_start = self.scratch_static_dispatch_constraints.top();
            for (owned_where_clauses) |where_idx| {
                try self.declareOwnedStaticDispatchConstraints(
                    where_idx,
                    ctx.producerOwnerNode(),
                    anno_var,
                    ctx.whereAliasDependencies(),
                    env,
                    ctx,
                );
            }
            const scratch_constraints_end = self.scratch_static_dispatch_constraints.top();

            var constraint_representatives = std.AutoHashMap(Ident.Idx, usize).init(self.gpa);
            defer constraint_representatives.deinit();
            try constraint_representatives.ensureTotalCapacity(@intCast(scratch_constraints_end - scratch_constraints_start));

            // A dispatcher's requirements are a method-keyed set. Keep the
            // first source occurrence as its stable evidence position, and
            // share its callable type with every repeated source constraint.
            const static_dispatch_constraints_start = self.types.static_dispatch_constraints.len();
            for (scratch_constraints_start..scratch_constraints_end) |scratch_index| {
                const scratch_constraint = self.scratch_static_dispatch_constraints.items.items[scratch_index];
                const representative = try constraint_representatives.getOrPut(scratch_constraint.constraint.fn_name);
                if (representative.found_existing) {
                    const representative_index = representative.value_ptr.*;
                    const store_index = self.scratch_static_dispatch_constraints.items.items[representative_index].store_index;
                    std.debug.assert(store_index != std.math.maxInt(u32));
                    self.scratch_static_dispatch_constraints.items.items[scratch_index].store_index = store_index;
                    continue;
                }

                representative.value_ptr.* = scratch_index;
                const store_index = try self.types.static_dispatch_constraints.append(self.types.gpa, scratch_constraint.constraint);
                self.scratch_static_dispatch_constraints.items.items[scratch_index].store_index = @intFromEnum(store_index);
            }
            const static_dispatch_constraints_end = self.types.static_dispatch_constraints.len();
            const static_dispatch_constraints_range = StaticDispatchConstraint.SafeList.Range{ .start = @enumFromInt(static_dispatch_constraints_start), .count = @intCast(static_dispatch_constraints_end - static_dispatch_constraints_start) };

            try self.unifyWith(anno_var, .{ .rigid = Rigid{
                .name = rigid.name,
                .constraints = static_dispatch_constraints_range,
            } }, env);
            // Where-alias constraints were typed as they were declared; only a
            // written method signature still needs its annotation generated,
            // which requires the dispatcher above to already be rigid.
            for (scratch_constraints_start..scratch_constraints_end) |scratch_index| {
                const scratch_constraint = self.scratch_static_dispatch_constraints.items.items[scratch_index];
                if (scratch_constraint.state != .declared) continue;
                switch (self.cir.store.getWhereClause(scratch_constraint.where_clause)) {
                    .w_method => |method| try self.completeOwnedStaticDispatchConstraint(
                        scratch_constraint.where_clause,
                        method,
                        anno_var,
                        scratch_index,
                        env,
                        ctx,
                    ),
                    // Only method clauses are left declared.
                    .w_alias, .w_malformed => unreachable,
                }
            }

            // Repeated method constraints are checked only after every written
            // signature has been generated. Their compiler-owned polarity
            // marker rigids are distinct source occurrences. The dedicated
            // duplicate-signature relation merges only those internal markers
            // while ordinary unification checks every written tag, payload,
            // argument, function kind, and non-marker leaf exactly.
            for (scratch_constraints_start..scratch_constraints_end) |scratch_index| {
                const scratch_constraint = self.scratch_static_dispatch_constraints.items.items[scratch_index];
                const store_index = scratch_constraint.store_index;
                std.debug.assert(store_index != std.math.maxInt(u32));
                const representative_fn = self.types.static_dispatch_constraints.items.items[store_index].fn_var;
                if (representative_fn != scratch_constraint.constraint.fn_var) {
                    try self.relateDuplicateWhereMethodSignature(
                        representative_fn,
                        scratch_constraint.constraint.fn_var,
                        env,
                    );
                }
                const retained = &self.types.static_dispatch_constraints.items.items[store_index];
                const merged_metadata = try self.mergeWhereMethodMarkerMetadata(
                    types_mod.WhereMethodMarkerMetadata.fromConstraint(retained.*),
                    types_mod.WhereMethodMarkerMetadata.fromConstraint(scratch_constraint.constraint),
                );
                retained.where_method_markers = merged_metadata.markers;
                retained.where_method_marker_bases = merged_metadata.bases;
            }

            // All duplicate signatures have now been related, so enumerate
            // their final shared shape once per written occurrence and attach
            // every producer/path ref to the retained method-key constraint.
            for (scratch_constraints_start..scratch_constraints_end) |scratch_index| {
                const scratch_constraint = self.scratch_static_dispatch_constraints.items.items[scratch_index];
                if (self.cir.store.getWhereClause(scratch_constraint.where_clause) != .w_method) continue;
                const new_markers = try self.makeWhereMethodMarkerContracts(
                    scratch_constraint.constraint.fn_var,
                    scratch_constraint.producer_owner_node,
                    @intFromEnum(ModuleEnv.nodeIdxFrom(scratch_constraint.where_clause)),
                    scratch_constraint.producer_method_name,
                );
                const store_index = scratch_constraint.store_index;
                std.debug.assert(store_index != std.math.maxInt(u32));
                const retained = &self.types.static_dispatch_constraints.items.items[store_index];
                const merged_metadata = try self.mergeWhereMethodMarkerMetadata(
                    types_mod.WhereMethodMarkerMetadata.fromConstraint(retained.*),
                    .{ .markers = new_markers, .bases = .empty() },
                );
                retained.where_method_markers = merged_metadata.markers;
                retained.where_method_marker_bases = merged_metadata.bases;
                self.scratch_static_dispatch_constraints.items.items[scratch_index].constraint.where_method_markers = new_markers;
                self.scratch_static_dispatch_constraints.items.items[scratch_index].constraint.where_method_marker_bases = .empty();
            }

            // Freeze the exact final retained occurrence produced by each
            // authored constraint only after both duplicate-signature merge
            // loops have completed. Repeated source clauses deliberately emit
            // repeated events naming the same retained endpoint; replay must
            // preserve that equality partition.
            for (scratch_constraints_start..scratch_constraints_end) |scratch_index| {
                const scratch_constraint = self.scratch_static_dispatch_constraints.items.items[scratch_index];
                const store_index = scratch_constraint.store_index;
                if (store_index == std.math.maxInt(u32)) {
                    std.debug.panic("annotation producer constraint had no retained store index", .{});
                }
                const producer_slot: u32 = @intCast(scratch_index - scratch_constraints_start);
                try self.recordPredeclaredAnnoConstraintEvent(
                    .retained_constraint,
                    producer_slot,
                    store_index,
                );
                try self.recordPredeclaredAnnoMarkerEvents(producer_slot, store_index);
            }
        },
        .rigid_var_lookup => |rigid_lookup| {
            _ = try self.unify(anno_var, ModuleEnv.varFrom(rigid_lookup.ref), env);
        },
        .underscore => {
            try self.unifyWith(anno_var, .{ .flex = Flex.init() }, env);
        },
        .lookup => |lookup| {
            if (try self.rejectWhereAliasInTypePosition(lookup.name, lookup.base, anno_var, anno_region, env)) return;
            switch (lookup.base) {
                .builtin => |builtin_type| {
                    try self.setBuiltinTypeContent(
                        anno_idx,
                        anno_var,
                        lookup.name,
                        builtin_type,
                        &.{},
                        anno_region,
                        env,
                        ctx,
                    );
                },
                .local => |local| {
                    try self.recordTypeDeclDependencyFromContext(ctx, local.decl_idx);

                    // Check if we're in a declaration or an annotation
                    switch (ctx) {
                        .type_decl => |this_decl| {
                            // If so, check if this is a recursive reference
                            if (this_decl.idx == local.decl_idx) {

                                // If it is a recursive ref, check that there are
                                // no arguments (since this is a lookup, not an apply)
                                if (this_decl.num_args != 0) {
                                    _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                                        .type_name = this_decl.name,
                                        .region = anno_region,
                                        .num_expected_args = this_decl.num_args,
                                        .num_actual_args = 0,
                                    } });
                                    try self.markErroneous(anno_var);
                                    return;
                                }

                                // If so, then update this annotation to be an instance
                                // of this type using the same backing variable
                                switch (this_decl.type_) {
                                    .alias => {
                                        // Recursion is not allowed in aliases - emit error
                                        _ = try self.problems.appendProblem(self.gpa, .{ .recursive_alias = .{
                                            .type_name = this_decl.name,
                                            .region = anno_region,
                                        } });
                                        try self.markErroneous(anno_var);
                                        return;
                                    },
                                    .nominal => {
                                        // Nominal types can be recursive
                                        try self.unifyWith(anno_var, try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
                                            .{ .ident_idx = this_decl.name },
                                            &.{},
                                            self.cir.selfModuleIdentity(),
                                            @intFromEnum(this_decl.idx),
                                            this_decl.is_opaque,
                                            self.cir.module_role == .builtin,
                                        ), env);
                                    },
                                }

                                return;
                            }
                        },
                        .annotation => {
                            // Otherwise, we're in an annotation and this cannot
                            // be recursive
                        },
                    }

                    const local_decl_var = ModuleEnv.varFrom(local.decl_idx);

                    // Check if this is a for-clause alias (eg Model [Model : model]).
                    // For for-clause aliases, we do not want to instantiate the
                    // variable - each place that references it should reference
                    // the same var.
                    const is_for_clause_alias = self.isForClauseAliasStatement(local.decl_idx);
                    if (is_for_clause_alias) {
                        _ = try self.unify(anno_var, local_decl_var, env);
                    } else {
                        if (!try self.ensureTypeDeclGenerated(local.decl_idx, env)) {
                            _ = try self.problems.appendProblem(self.gpa, .{ .recursive_alias = .{
                                .type_name = lookup.name,
                                .region = anno_region,
                            } });
                            try self.markErroneous(anno_var);
                            return;
                        }
                        const instantiated_var = try self.instantiateVarPolarized(
                            local_decl_var,
                            env,
                            .{ .explicit = anno_region },
                            ctx.polarityVarBehavior(),
                            polarity,
                        );
                        _ = try self.unify(anno_var, instantiated_var, env);
                    }
                },
                .external => |ext| {
                    if (try self.resolveVarFromExternal(
                        ext.module_idx,
                        ext.target_node_idx,
                        externalTypeAnnotationLookupUse(self.cir, anno_idx),
                    )) |ext_ref| {
                        const ext_instantiated_var = try self.instantiateVarPolarized(
                            ext_ref.local_var,
                            env,
                            .{ .explicit = anno_region },
                            ctx.polarityVarBehavior(),
                            polarity,
                        );
                        _ = try self.unify(anno_var, ext_instantiated_var, env);
                    } else {
                        // If this external type is unresolved, can should've reported
                        // an error. So we set to error and continue
                        try self.markErroneous(anno_var);
                    }
                },
                .pending => {
                    // If an import references a non-existent module (e.g., missing from
                    // platform bundle), the pending lookup can't be resolved. Treat as error.
                    try self.markErroneous(anno_var);
                },
            }
        },
        .apply => |a| {
            if (try self.rejectWhereAliasInTypePosition(a.name, a.base, anno_var, anno_region, env)) return;

            // Generate the types for the arguments. Type application args
            // inherit the application's polarity: `Try(U8, [E])` in an output
            // position puts `[E]` in an output position too.
            const anno_args = self.cir.store.sliceTypeAnnos(a.args);
            for (anno_args) |anno_arg| {
                try self.generateAnnoTypeInPlace(anno_arg, env, ctx, polarity);
            }
            const anno_arg_vars: []Var = @ptrCast(anno_args);

            switch (a.base) {
                .builtin => |builtin_type| {
                    try self.setBuiltinTypeContent(
                        anno_idx,
                        anno_var,
                        a.name,
                        builtin_type,
                        anno_arg_vars,
                        anno_region,
                        env,
                        ctx,
                    );
                },
                .local => |local| {
                    try self.recordTypeDeclDependencyFromContext(ctx, local.decl_idx);
                    const decl_var = ModuleEnv.varFrom(local.decl_idx);
                    if (self.isForClauseAliasStatement(local.decl_idx)) {
                        try self.generateForClauseAliasApplication(anno_var, decl_var, anno_arg_vars, env);
                        return;
                    }

                    // Check if we're in a declaration or an annotation
                    switch (ctx) {
                        .type_decl => |this_decl| {
                            // If so, check if this is a recursive reference
                            if (this_decl.idx == local.decl_idx) {

                                // If it is a recursive ref, check that the args being
                                // applied here match the number of args of the decl
                                if (anno_arg_vars.len != this_decl.num_args) {
                                    _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                                        .type_name = this_decl.name,
                                        .region = anno_region,
                                        .num_expected_args = this_decl.num_args,
                                        .num_actual_args = @intCast(anno_args.len),
                                    } });
                                    try self.markErroneous(anno_var);
                                    return;
                                }

                                // If so, then update this annotation to be an instance
                                // of this type using the same backing variable
                                switch (this_decl.type_) {
                                    .alias => {
                                        // Recursion is not allowed in aliases - emit error
                                        _ = try self.problems.appendProblem(self.gpa, .{ .recursive_alias = .{
                                            .type_name = this_decl.name,
                                            .region = anno_region,
                                        } });
                                        try self.markErroneous(anno_var);
                                        return;
                                    },
                                    .nominal => {
                                        // Nominal types can be recursive
                                        try self.unifyWith(anno_var, try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
                                            .{ .ident_idx = this_decl.name },
                                            anno_arg_vars,
                                            self.cir.selfModuleIdentity(),
                                            @intFromEnum(this_decl.idx),
                                            this_decl.is_opaque,
                                            self.cir.module_role == .builtin,
                                        ), env);
                                    },
                                }

                                return;
                            }
                        },
                        .annotation => {
                            // Otherwise, we're in an annotation and this cannot
                            // be recursive
                        },
                    }

                    if (!try self.ensureTypeDeclGenerated(local.decl_idx, env)) {
                        _ = try self.problems.appendProblem(self.gpa, .{ .recursive_alias = .{
                            .type_name = a.name,
                            .region = anno_region,
                        } });
                        try self.markErroneous(anno_var);
                        return;
                    }

                    // Resolve the referenced type
                    const decl_resolved = self.types.resolveVar(decl_var).desc.content;
                    const decl_is_alias = decl_resolved == .alias;

                    // Get the arguments & name the referenced type
                    const decl_arg_vars, const decl_name = blk: {
                        if (decl_resolved == .alias) {
                            const decl_alias = decl_resolved.alias;
                            break :blk .{ self.types.sliceAliasArgs(decl_alias), decl_alias.ident.ident_idx };
                        } else if (decl_resolved == .structure and decl_resolved.structure == .nominal_type) {
                            const decl_nominal = decl_resolved.structure.nominal_type;
                            break :blk .{ self.types.sliceNominalArgs(decl_nominal), decl_nominal.ident.ident_idx };
                        } else if (decl_resolved == .err) {
                            try self.markErroneous(anno_var);
                            return;
                        } else {
                            // Type applications should only reference aliases or nominal types.
                            // If we hit this, there's a compiler bug.
                            std.debug.assert(false);
                            try self.markErroneous(anno_var);
                            return;
                        }
                    };

                    // Check for an arity mismatch
                    if (decl_arg_vars.len != anno_arg_vars.len) {
                        _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                            .type_name = decl_name,
                            .region = anno_region,
                            .num_expected_args = @intCast(decl_arg_vars.len),
                            .num_actual_args = @intCast(anno_args.len),
                        } });
                        try self.markErroneous(anno_var);
                        return;
                    }

                    // Then, built the map of applied variables
                    self.rigid_var_substitutions.clearRetainingCapacity();
                    self.rigid_var_substitution_origins.clearRetainingCapacity();
                    for (decl_arg_vars, anno_arg_vars, 0..) |decl_arg_var, anno_arg_var, arg_index| {
                        const decl_arg_resolved = self.types.resolveVar(decl_arg_var).desc.content;

                        if (decl_arg_resolved == .err) {
                            try self.markErroneous(anno_var);
                            return;
                        }
                        std.debug.assert(decl_arg_resolved == .rigid);
                        const decl_arg_rigid = decl_arg_resolved.rigid;

                        try self.rigid_var_substitutions.put(self.gpa, decl_arg_rigid.name, anno_arg_var);
                        try self.rigid_var_substitution_origins.put(self.gpa, decl_arg_rigid.name, @intCast(arg_index));
                    }

                    // Then instantiate the variable, substituting the rigid
                    // variables in the definition with the applied args from
                    // the annotation
                    const instantiated_var = try self.instantiateVarWithSubsPolarized(
                        decl_var,
                        &self.rigid_var_substitutions,
                        &self.rigid_var_substitution_origins,
                        env,
                        .{ .explicit = anno_region },
                        ctx.polarityVarBehavior(),
                        polarity,
                    );
                    if (decl_is_alias and !try self.validateAliasRows(instantiated_var, env, anno_region)) {
                        try self.markErroneous(anno_var);
                        return;
                    }
                    _ = try self.unify(anno_var, instantiated_var, env);
                },
                .external => |ext| {
                    if (try self.resolveVarFromExternal(
                        ext.module_idx,
                        ext.target_node_idx,
                        externalTypeAnnotationLookupUse(self.cir, anno_idx),
                    )) |ext_ref| {
                        // Resolve the referenced type
                        const ext_resolved = self.types.resolveVar(ext_ref.local_var).desc.content;
                        const ext_is_alias = ext_resolved == .alias;

                        // Get the arguments & name the referenced type
                        const ext_arg_vars, const ext_name = blk: {
                            switch (ext_resolved) {
                                .alias => |decl_alias| {
                                    break :blk .{ self.types.sliceAliasArgs(decl_alias), decl_alias.ident.ident_idx };
                                },
                                .structure => |flat_type| {
                                    if (flat_type == .nominal_type) {
                                        const decl_nominal = flat_type.nominal_type;
                                        break :blk .{ self.types.sliceNominalArgs(decl_nominal), decl_nominal.ident.ident_idx };
                                    } else {
                                        // External type resolved to a non-nominal structure (e.g., record, func, etc.)
                                        // This shouldn't happen for type applications, treat as error
                                        try self.markErroneous(anno_var);
                                        return;
                                    }
                                },
                                .err, .field_presence => {
                                    try self.markErroneous(anno_var);
                                    return;
                                },
                                .flex, .rigid => {
                                    // External type resolved to a flex or rigid.
                                    // This can happen when the external type is polymorphic but hasn't been
                                    // instantiated yet. We need to use the variable as-is, but this means
                                    // we can't get the arity/name information. This is likely a bug in how
                                    // the external type was set up. For now, treat it as an error.
                                    try self.markErroneous(anno_var);
                                    return;
                                },
                            }
                        };

                        // Check for an arity mismatch
                        if (ext_arg_vars.len != anno_arg_vars.len) {
                            _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                                .type_name = ext_name,
                                .region = anno_region,
                                .num_expected_args = @intCast(ext_arg_vars.len),
                                .num_actual_args = @intCast(anno_args.len),
                            } });
                            try self.markErroneous(anno_var);
                            return;
                        }

                        // Then, built the map of applied variables
                        self.rigid_var_substitutions.clearRetainingCapacity();
                        self.rigid_var_substitution_origins.clearRetainingCapacity();
                        for (ext_arg_vars, anno_arg_vars, 0..) |decl_arg_var, anno_arg_var, arg_index| {
                            const decl_arg_resolved = self.types.resolveVar(decl_arg_var).desc.content;

                            if (decl_arg_resolved == .err) {
                                try self.markErroneous(anno_var);
                                return;
                            }
                            std.debug.assert(decl_arg_resolved == .rigid);
                            const decl_arg_rigid = decl_arg_resolved.rigid;

                            try self.rigid_var_substitutions.put(self.gpa, decl_arg_rigid.name, anno_arg_var);
                            try self.rigid_var_substitution_origins.put(self.gpa, decl_arg_rigid.name, @intCast(arg_index));
                        }

                        // Then instantiate the variable, substituting the rigid
                        // variables in the definition with the applied args from
                        // the annotation
                        const instantiated_var = try self.instantiateVarWithSubsPolarized(
                            ext_ref.local_var,
                            &self.rigid_var_substitutions,
                            &self.rigid_var_substitution_origins,
                            env,
                            .{ .explicit = anno_region },
                            ctx.polarityVarBehavior(),
                            polarity,
                        );
                        if (ext_is_alias and !try self.validateAliasRows(instantiated_var, env, anno_region)) {
                            try self.markErroneous(anno_var);
                            return;
                        }
                        _ = try self.unify(anno_var, instantiated_var, env);
                    } else {
                        // If this external type is unresolved, can should've reported
                        // an error. So we set to error and continue
                        try self.markErroneous(anno_var);
                    }
                },
                .pending => {
                    // If an import references a non-existent module (e.g., missing from
                    // platform bundle), the pending lookup can't be resolved. Treat as error.
                    try self.markErroneous(anno_var);
                },
            }
        },
        .@"fn" => |func| {
            // Argument positions negate the surrounding polarity; the return
            // position preserves it.
            const args_anno_slice = self.cir.store.sliceTypeAnnos(func.args);
            for (args_anno_slice) |arg_anno_idx| {
                try self.generateAnnoTypeInPlace(arg_anno_idx, env, ctx, polarity.flip());
            }
            const args_var_slice: []Var = @ptrCast(args_anno_slice);

            try self.generateAnnoTypeInPlace(func.ret, env, ctx, polarity);

            const fn_type = inner_blk: {
                if (func.effectful) {
                    break :inner_blk try self.types.mkFuncEffectful(args_var_slice, ModuleEnv.varFrom(func.ret));
                } else {
                    break :inner_blk try self.types.mkFuncPure(args_var_slice, ModuleEnv.varFrom(func.ret));
                }
            };
            try self.unifyWith(anno_var, fn_type, env);
        },
        .tag_union => |tag_union| {
            const scratch_tags_top = self.scratch_tags.top();
            defer self.scratch_tags.clearFrom(scratch_tags_top);

            const tag_anno_slices = self.cir.store.sliceTypeAnnos(tag_union.tags);
            for (tag_anno_slices, 0..) |tag_anno_idx, tag_slot| {
                // Get the tag anno
                const tag_type_anno = self.cir.store.getTypeAnno(tag_anno_idx);
                try self.setVarRank(ModuleEnv.varFrom(tag_anno_idx), env);

                // Canonicalization retains a malformed TypeAnno at the exact
                // member slot when the written child is not a tag. Publish the
                // parent/slot failure before poisoning the parent type.
                if (tag_type_anno != .tag) {
                    const malformed = switch (tag_type_anno) {
                        .malformed => |malformed| malformed,
                        else => std.debug.panic(
                            "canonicalization produced a non-tag, non-malformed tag-union child",
                            .{},
                        ),
                    };
                    if (try self.invalidTagChildAnnotationGenerationFailure(
                        anno_idx,
                        tag_anno_idx,
                        @intCast(tag_slot),
                        malformed.diagnostic,
                        ctx,
                    )) |failure| {
                        switch (ctx) {
                            .annotation => |anno_ctx| anno_ctx.failure_accumulator.record(failure),
                            .type_decl => unreachable,
                        }
                    }
                    try self.markErroneous(anno_var);
                    return;
                }
                const tag = tag_type_anno.tag;

                // Generate the types for each tag arg
                const tag_anno_args_slice = self.cir.store.sliceTypeAnnos(tag.args);
                for (tag_anno_args_slice) |tag_arg_idx| {
                    try self.generateAnnoTypeInPlace(tag_arg_idx, env, ctx, polarity);
                }
                const tag_vars_slice: []Var = @ptrCast(tag_anno_args_slice);

                // Add the processed tag to scratch
                try self.scratch_tags.append(try self.types.mkTag(
                    tag.name,
                    tag_vars_slice,
                ));
            }

            // Get the slice of tags
            const tags_slice = self.scratch_tags.sliceFromStart(scratch_tags_top);
            std.mem.sort(types_mod.Tag, tags_slice, self, struct {
                fn less(checker: *const Self, a: types_mod.Tag, b: types_mod.Tag) bool {
                    return std.mem.order(u8, checker.cir.getIdentStoreConst().getText(a.name), checker.cir.getIdentStoreConst().getText(b.name)) == .lt;
                }
            }.less);

            // Materialize the tags into the types store before processing the
            // ext. `tags_slice` points into the scratch_tags buffer, and
            // generating the ext recurses and may append to scratch_tags,
            // reallocating that buffer and dangling the slice. Copying into a
            // stable range here mirrors the record case below.
            const tags_range = try self.types.appendTags(tags_slice);

            // Process the ext.
            //
            // An absent ext means:
            //   * in an opening annotation: implicitly open in output
            //     positions — a fresh flex ext, recorded for the post-body
            //     audit (`auditImplicitOpenExts`) that keeps the annotation a
            //     bound on the definition — and closed (`[]`) in input
            //     positions;
            //   * in an alias declaration body: deferred — a polarity marker
            //     resolved by the polarity of each use site (see
            //     `types.polarity_var_text`);
            //   * otherwise (nominal bodies, host-boundary annotations):
            //     closed, as written.
            //
            // An explicit ext anno is generated in place, with one exception:
            // an anonymous `..` in an output position of an opening annotation
            // means exactly what absence means there, so it is generated the
            // same way (a recorded flex) and the two spellings cannot drift.
            // Elsewhere `..` stays the rigid `#others` it always was.
            //
            // A union with no tags is exempt from all of this: `[]` asserts
            // uninhabitedness (eg `Try(a, [])` needs no `Err` branch), which
            // opening would silently destroy. It always means the closed
            // empty union.
            const anno_has_tags = tag_anno_slices.len > 0;
            const output_opening: ?GenTypeAnnoCtx.AnnotationGenCtx.OpeningBehavior = if (anno_has_tags and polarity == .pos and ctx == .annotation)
                ctx.annotation.opening
            else
                null;
            const implicitly_open = output_opening == .implicit_open;
            // A where-method signature's output row: deferred with the
            // polarity marker, resolved per body use and per obligation.
            const deferred_open = output_opening == .per_use;
            const ext_var = inner_blk: {
                if (tag_union.ext) |ext_anno_idx| {
                    if ((implicitly_open or deferred_open) and self.annoIsAnonymousOpenExt(ext_anno_idx)) {
                        const open_ext_var = ModuleEnv.varFrom(ext_anno_idx);
                        try self.setVarRank(open_ext_var, env);
                        self.markTypeAnnoSeen(ext_anno_idx);
                        {
                            const saved_ext_anchor = self.setPredeclaredAnnoEventAnchor(@intFromEnum(ext_anno_idx));
                            defer self.restorePredeclaredAnnoEventAnchor(saved_ext_anchor);
                            try self.recordPredeclaredAnnoVarEvent(.type_anno_node, 0, open_ext_var);
                        }
                        if (deferred_open) {
                            try self.unifyWith(open_ext_var, .{ .rigid = Rigid.init(self.cir.idents.polarity_var) }, env);
                        } else {
                            try self.unifyWith(open_ext_var, .{ .flex = Flex.init() }, env);
                        }
                        try self.implicit_open_exts.append(self.gpa, .{
                            .var_ = open_ext_var,
                            .region = anno_region,
                            .explicit_ext_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(ext_anno_idx)),
                            .listed_tags = tags_range,
                        });
                        break :inner_blk open_ext_var;
                    }
                    try self.generateAnnoTypeInPlace(ext_anno_idx, env, ctx, polarity);
                    break :inner_blk ModuleEnv.varFrom(ext_anno_idx);
                }

                if (!anno_has_tags) {
                    const empty_ext = try self.freshFromContent(.{ .structure = .empty_tag_union }, env, anno_region);
                    try self.recordPredeclaredAnnoVarEvent(
                        .fresh_var,
                        @intFromEnum(PredeclaredAnnoFreshSlot.tag_union_empty_extension),
                        empty_ext,
                    );
                    break :inner_blk empty_ext;
                }

                if (implicitly_open) {
                    const open_ext_var = try self.fresh(env, anno_region);
                    try self.recordPredeclaredAnnoVarEvent(
                        .fresh_var,
                        @intFromEnum(PredeclaredAnnoFreshSlot.tag_union_implicit_extension),
                        open_ext_var,
                    );
                    try self.implicit_open_exts.append(self.gpa, .{
                        .var_ = open_ext_var,
                        .region = anno_region,
                        .listed_tags = tags_range,
                    });
                    break :inner_blk open_ext_var;
                }

                if (deferred_open) {
                    const polarity_ext = try self.freshFromContent(.{ .rigid = Rigid.init(self.cir.idents.polarity_var) }, env, anno_region);
                    try self.recordPredeclaredAnnoVarEvent(
                        .fresh_var,
                        @intFromEnum(PredeclaredAnnoFreshSlot.tag_union_polarity_extension),
                        polarity_ext,
                    );
                    break :inner_blk polarity_ext;
                }

                const closed_ext = switch (ctx) {
                    .annotation => try self.freshFromContent(.{ .structure = .empty_tag_union }, env, anno_region),
                    .type_decl => |decl| switch (decl.type_) {
                        .alias => try self.freshFromContent(.{ .rigid = Rigid.init(self.cir.idents.polarity_var) }, env, anno_region),
                        .nominal => try self.freshFromContent(.{ .structure = .empty_tag_union }, env, anno_region),
                    },
                };
                try self.recordPredeclaredAnnoVarEvent(
                    .fresh_var,
                    @intFromEnum(PredeclaredAnnoFreshSlot.tag_union_closed_extension),
                    closed_ext,
                );
                break :inner_blk closed_ext;
            };

            // Set the anno's type
            try self.unifyWith(
                anno_var,
                .{ .structure = types_mod.FlatType{ .tag_union = .{
                    .tags = tags_range,
                    .ext = ext_var,
                } } },
                env,
            );
        },
        .tag => {
            // Tags should only exist as direct children of tag_unions in type annotations.
            // If we encounter a standalone tag here, it's a compiler bug in canonicalization.
            std.debug.assert(false);
            try self.markErroneous(anno_var);
        },
        .record => |rec| {
            const scratch_record_fields_top = self.scratch_record_fields.top();
            defer self.scratch_record_fields.clearFrom(scratch_record_fields_top);

            const recs_anno_slice = self.cir.store.sliceAnnoRecordFields(rec.fields);
            for (recs_anno_slice) |rec_anno_idx| {
                const rec_field = self.cir.store.getAnnoRecordField(rec_anno_idx);

                // Still resolve the field's annotated type (so unnamed padding
                // fields are type-checked), but unnamed fields are layout padding,
                // not real record fields: keep them out of the structural row so
                // they are never unified, name-resolved, or required at
                // construction (and so repeated `_` names cannot collide).
                try self.generateAnnoTypeInPlace(rec_field.ty, env, ctx, polarity);
                if (rec_field.is_unnamed) continue;
                const record_field_var = ModuleEnv.varFrom(rec_field.ty);

                // Add the processed field to scratch.
                //
                // Annotations pin field kinds CONCRETELY, in every syntactic
                // position and context: `?:` is the `optional` kind (tagged
                // slot, read with `.?`) and `:` is the `required` kind
                // (`present`), with no polarity split—layout is a function
                // of the annotation alone (design.md "Field Kinds
                // (All-Dynamic Optional Fields)").
                const presence: types_mod.RecordField.Presence = if (rec_field.is_optional) blk: {
                    const presence_var = try self.freshFromContent(
                        .{ .field_presence = .optional },
                        env,
                        anno_region,
                    );
                    try self.recordPredeclaredAnnoVarEvent(
                        .fresh_var,
                        @intFromEnum(PredeclaredAnnoFreshSlot.record_optional_presence),
                        presence_var,
                    );
                    break :blk .unknown(presence_var, record_field_var);
                } else if (rec_field.default_value) |default_expr_idx| blk: {
                    // A DEFAULTED field (design.md "Defaulted Fields"): pin
                    // the kind to `defaulted` carrying the default's stable
                    // identity, and RECORD the default expression for the
                    // finalize check—materialization can run before check
                    // order exists and before callee effects resolve, so
                    // typing and purity wait for finalize. Predeclaration's
                    // side effects are unwound, so only the body-pass
                    // materialization records.
                    if (!self.predeclaring_annotation) {
                        const seen = try self.pending_default_seen.getOrPut(self.gpa, default_expr_idx);
                        if (!seen.found_existing) {
                            try self.pending_default_checks.append(self.gpa, .{
                                .default_expr = default_expr_idx,
                                .field_type_anno = rec_field.ty,
                                .field_type_var = record_field_var,
                                .field_name = rec_field.name,
                            });
                        }
                    }
                    const presence_var = try self.freshFromContent(
                        .{ .field_presence = .{ .defaulted = .{
                            .origin_module = self.cir.selfModuleIdentity(),
                            .expr_node = @intFromEnum(default_expr_idx),
                        } } },
                        env,
                        anno_region,
                    );
                    try self.recordPredeclaredAnnoVarEvent(
                        .fresh_var,
                        @intFromEnum(PredeclaredAnnoFreshSlot.record_default_presence),
                        presence_var,
                    );
                    break :blk .unknown(presence_var, record_field_var);
                } else .required(record_field_var);
                try self.scratch_record_fields.append(types_mod.RecordField{
                    .name = rec_field.name,
                    .presence = presence,
                });
            }

            // Get the slice of record_fields
            const record_fields_slice = self.scratch_record_fields.sliceFromStart(scratch_record_fields_top);
            std.mem.sort(types_mod.RecordField, record_fields_slice, self.cir.getIdentStore(), types_mod.RecordField.sortByNameAsc);
            const fields_type_range = try self.types.appendRecordFields(record_fields_slice);

            // Process the ext if it exists. Absence (null) means it's a closed record.
            const ext_var = if (rec.ext) |ext_anno_idx| blk: {
                try self.generateAnnoTypeInPlace(ext_anno_idx, env, ctx, polarity);
                break :blk ModuleEnv.varFrom(ext_anno_idx);
            } else blk: {
                const empty_ext = try self.freshFromContent(.{ .structure = .empty_record }, env, anno_region);
                try self.recordPredeclaredAnnoVarEvent(
                    .fresh_var,
                    @intFromEnum(PredeclaredAnnoFreshSlot.record_empty_extension),
                    empty_ext,
                );
                break :blk empty_ext;
            };

            // Create the type for the anno in the store
            try self.unifyWith(
                anno_var,
                .{ .structure = types_mod.FlatType{ .record = .{
                    .fields = fields_type_range,
                    .ext = ext_var,
                } } },
                env,
            );
        },
        .tuple => |tuple| {
            const scratch_vars_top = self.scratch_vars.top();
            defer self.scratch_vars.clearFrom(scratch_vars_top);

            const elems_anno_slice = self.cir.store.sliceTypeAnnos(tuple.elems);
            for (elems_anno_slice) |arg_anno_idx| {
                try self.generateAnnoTypeInPlace(arg_anno_idx, env, ctx, polarity);
                try self.scratch_vars.append(ModuleEnv.varFrom(arg_anno_idx));
            }
            const elems_range = try self.types.appendVars(self.scratch_vars.sliceFromStart(scratch_vars_top));
            try self.unifyWith(anno_var, .{ .structure = .{ .tuple = .{ .elems = elems_range } } }, env);
        },
        .parens => |parens| {
            try self.generateAnnoTypeInPlace(parens.anno, env, ctx, polarity);
            _ = try self.unify(anno_var, ModuleEnv.varFrom(parens.anno), env);
        },
        .malformed => |malformed| {
            try self.markErroneous(anno_var);
            if (try self.malformedAnnotationGenerationFailure(
                anno_idx,
                malformed.diagnostic,
                ctx,
            )) |failure| {
                switch (ctx) {
                    .annotation => |anno_ctx| anno_ctx.failure_accumulator.record(failure),
                    .type_decl => unreachable,
                }
            }
        },
    }
}

fn validateAliasRows(self: *Self, var_: Var, env: *Env, region: Region) Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return self.validateAliasRowsHelp(var_, env, region, &self.var_set);
}

/// Which kind of row a bad-row diagnostic is about.
const AliasRowKind = enum { record, tag_union };

/// What a row frame's step decided: it asked for a child subtree and must be
/// resumed, it exhausted the row, or it reported a bad row and the whole walk
/// is over.
const RowStep = enum { suspended, finished, failed };

/// One suspended step of alias row validation.
///
/// A `node` is a var whose content still has to be inspected; a row frame is a
/// record or tag-union row partway through its own fields, interleaving each
/// field's duplicate-name check with a full walk of that field's type exactly
/// as the row's diagnostics require. Everything a frame pushes sits above it,
/// so a frame resumes only once the subtree it asked for has drained—which is
/// what makes "check name, then walk that field completely, then check the
/// next name" hold without a native frame per level.
const AliasRowFrame = union(enum) {
    node: Var,
    record_row: RecordRowFrame,
    tag_row: TagRowFrame,
};

/// A record row: its head fields, then everything its extension chain
/// contributes. Field names collected so far live in a run of
/// `alias_row_names` starting at `names_base`.
const RecordRowFrame = struct {
    names_base: u32,
    fields: types_mod.RecordField.SafeMultiList.Range,
    idx: u32 = 0,
    /// The var whose duplicate fields report against it while walking the
    /// extension chain; unused while the head fields are being checked, which
    /// report against the offending field itself.
    ext_source_var: Var = undefined,
    /// Where the extension chain resumes once the current run is exhausted.
    ext: Var,
    /// Whether the current run is the last one this row contributes.
    ext_terminates: bool = false,
    guard: types_mod.debug.IterationGuard,
    stage: enum { head_fields, ext_chain, ext_fields } = .head_fields,
};

/// A tag-union row: its head tags, then everything its extension chain
/// contributes. Tag names collected so far live in a run of `alias_row_names`
/// starting at `names_base`.
const TagRowFrame = struct {
    names_base: u32,
    tags: types_mod.Tag.SafeMultiList.Range,
    idx: u32 = 0,
    arg_idx: u32 = 0,
    /// The var duplicate tags report against. Head tags report against the
    /// row's own extension var, extension tags against the extension record
    /// they came from.
    report_var: Var,
    ext: Var,
    ext_terminates: bool = false,
    guard: types_mod.debug.IterationGuard,
    stage: enum { head_tags, head_args, ext_chain, ext_tags, ext_args } = .head_tags,
};

fn validateAliasRowsHelp(
    self: *Self,
    root_var: Var,
    env: *Env,
    region: Region,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    // The whole walk—constructor spines and row payloads alike—runs on an
    // explicit heap stack, so a type of any depth can be validated without a
    // native frame per level. Spine children are pushed in reverse, so pops
    // replay the recursion's exact preorder: a node's first child's whole
    // subtree drains before its next sibling. Rows suspend on a frame instead
    // of re-entering the walk, which keeps their interleaved duplicate-name
    // checks in the order their diagnostics are pinned to.
    const frames = &self.alias_row_frames;
    const frames_base = frames.items.len;
    const names_base = self.alias_row_names.items.len;
    defer {
        frames.items.len = frames_base;
        self.alias_row_names.items.len = names_base;
    }
    try frames.append(self.gpa, .{ .node = root_var });

    while (frames.items.len > frames_base) {
        const top = &frames.items[frames.items.len - 1];
        switch (top.*) {
            .node => |var_| {
                frames.items.len -= 1;
                try self.stepAliasRowNode(var_, visited);
            },
            .record_row => |*frame| {
                // Read the run's base before stepping: the step can push onto
                // `frames` and move the frame this pointer refers to.
                const row_names_base = frame.names_base;
                switch (try self.stepRecordRow(frame, env, region)) {
                    .suspended => {},
                    .finished => {
                        frames.items.len -= 1;
                        self.alias_row_names.items.len = row_names_base;
                    },
                    .failed => return false,
                }
            },
            .tag_row => |*frame| {
                const row_names_base = frame.names_base;
                switch (try self.stepTagRow(frame, env, region)) {
                    .suspended => {},
                    .finished => {
                        frames.items.len -= 1;
                        self.alias_row_names.items.len = row_names_base;
                    },
                    .failed => return false,
                }
            },
        }
    }
    return true;
}

/// Inspect one node: descend constructor spines by pushing their children, and
/// hand rows to a frame that owns their duplicate-name state.
fn stepAliasRowNode(
    self: *Self,
    var_: Var,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!void {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return;
    try visited.put(resolved.var_, {});

    switch (resolved.desc.content) {
        .alias => |alias| {
            try self.pushAliasRowVarsReversed(self.types.sliceAliasArgs(alias));
            try self.alias_row_frames.append(self.gpa, .{ .node = self.types.getAliasBackingVar(alias) });
        },
        .structure => |flat_type| switch (flat_type) {
            .tuple => |tuple| try self.pushAliasRowVarsReversed(self.types.sliceVars(tuple.elems)),
            .nominal_type => |nominal| try self.pushAliasRowVarsReversed(self.types.sliceNominalArgs(nominal)),
            .fn_pure, .fn_effectful, .fn_unbound => |func| {
                try self.alias_row_frames.append(self.gpa, .{ .node = func.ret });
                try self.pushAliasRowVarsReversed(self.types.sliceVars(func.args));
            },
            .record => |record| {
                try self.alias_row_frames.append(self.gpa, .{ .record_row = .{
                    .names_base = @intCast(self.alias_row_names.items.len),
                    .fields = record.fields,
                    .ext = record.ext,
                    .guard = types_mod.debug.IterationGuard.init("validateRecordExt"),
                } });
            },
            .record_unbound => |fields| {
                // An unbound record has no extension and no duplicate-name
                // check of its own, so its fields are ordinary spine children.
                const field_slice = self.types.getRecordFieldsSlice(fields);
                var i = field_slice.len;
                while (i > 0) {
                    i -= 1;
                    const presence = field_slice.items(.presence)[i];
                    if (presence.presenceVar()) |presence_var| {
                        try self.alias_row_frames.append(self.gpa, .{ .node = presence_var });
                    }
                    try self.alias_row_frames.append(self.gpa, .{ .node = presence.typeVar() });
                }
            },
            .tag_union => |tag_union| {
                try self.alias_row_frames.append(self.gpa, .{ .tag_row = .{
                    .names_base = @intCast(self.alias_row_names.items.len),
                    .tags = tag_union.tags,
                    .report_var = tag_union.ext,
                    .ext = tag_union.ext,
                    .guard = types_mod.debug.IterationGuard.init("validateTagUnionExt"),
                } });
            },
            .empty_record, .empty_tag_union => {},
        },
        .flex, .rigid, .field_presence, .err => {},
    }
}

/// Push a child run onto the alias row visit stack in reverse, so the stack
/// pops the children in their declared order.
fn pushAliasRowVarsReversed(self: *Self, vars: []const Var) Allocator.Error!void {
    var i = vars.len;
    while (i > 0) {
        i -= 1;
        try self.alias_row_frames.append(self.gpa, .{ .node = vars[i] });
    }
}

/// Whether `name` already appears in the row run that starts at `names_base`,
/// recording it when it does not. Names compare by identifier index, exactly
/// as the row's duplicate map keyed them.
///
/// Duplicate names are per row: a field's own type may contain rows that reuse
/// the enclosing row's names, and those are not duplicates of it. That holds
/// because a finished row frame pops its run, so once every frame this row
/// suspended on has drained, `alias_row_names[names_base..]` is exactly the
/// names this row contributed.
fn aliasRowNameIsDuplicate(self: *Self, names_base: u32, name: Ident.Idx) Allocator.Error!bool {
    for (self.alias_row_names.items[names_base..]) |seen| {
        if (seen == name) return true;
    }
    try self.alias_row_names.append(self.gpa, name);
    return false;
}

fn failAliasRow(
    self: *Self,
    comptime row_kind: AliasRowKind,
    actual_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!RowStep {
    try self.reportInvalidAliasRow(row_kind, actual_var, env, region);
    return .failed;
}

/// Read the source field at `idx` within `range`. Indexing through the run's
/// start only happens when the record has fields; start may be undefined when
/// count is 0.
fn aliasRowField(self: *Self, range: types_mod.RecordField.SafeMultiList.Range, idx: u32) types_mod.RecordField {
    return self.types.record_fields.get(@enumFromInt(@intFromEnum(range.start) + idx));
}

fn stepRecordRow(self: *Self, frame: *RecordRowFrame, env: *Env, region: Region) Allocator.Error!RowStep {
    while (true) {
        switch (frame.stage) {
            .head_fields => {
                if (frame.idx < frame.fields.count) {
                    const field = self.aliasRowField(frame.fields, frame.idx);
                    if (try self.aliasRowNameIsDuplicate(frame.names_base, field.name)) {
                        return try self.failAliasRow(.record, field.presence.typeVar(), env, region);
                    }
                    frame.idx += 1;
                    try self.alias_row_frames.append(self.gpa, .{ .node = field.presence.typeVar() });
                    return .suspended;
                }
                frame.stage = .ext_chain;
            },
            .ext_chain => {
                var current = frame.ext;
                while (true) {
                    frame.guard.tick();
                    const resolved = self.types.resolveVar(current);
                    switch (resolved.desc.content) {
                        .alias => |alias| {
                            current = self.types.getAliasBackingVar(alias);
                        },
                        .structure => |flat_type| switch (flat_type) {
                            .record => |record| {
                                frame.fields = record.fields;
                                frame.idx = 0;
                                frame.ext_source_var = current;
                                frame.ext = record.ext;
                                frame.ext_terminates = false;
                                frame.stage = .ext_fields;
                                break;
                            },
                            .record_unbound => |fields| {
                                frame.fields = fields;
                                frame.idx = 0;
                                frame.ext_source_var = current;
                                frame.ext_terminates = true;
                                frame.stage = .ext_fields;
                                break;
                            },
                            .empty_record => return .finished,
                            .tuple,
                            .nominal_type,
                            .fn_pure,
                            .fn_effectful,
                            .fn_unbound,
                            .tag_union,
                            .empty_tag_union,
                            => {
                                return try self.failAliasRow(.record, current, env, region);
                            },
                        },
                        .flex, .rigid, .field_presence, .err => return .finished,
                    }
                }
            },
            .ext_fields => {
                if (frame.idx < frame.fields.count) {
                    const field = self.aliasRowField(frame.fields, frame.idx);
                    if (try self.aliasRowNameIsDuplicate(frame.names_base, field.name)) {
                        return try self.failAliasRow(.record, frame.ext_source_var, env, region);
                    }
                    frame.idx += 1;
                    try self.alias_row_frames.append(self.gpa, .{ .node = field.presence.typeVar() });
                    return .suspended;
                }
                if (frame.ext_terminates) return .finished;
                frame.stage = .ext_chain;
            },
        }
    }
}

/// Read the source tag at `idx` within `range`. Indexing through the run's
/// start only happens when the tag union has tags; start may be undefined when
/// count is 0.
fn aliasRowTag(self: *Self, range: types_mod.Tag.SafeMultiList.Range, idx: u32) types_mod.Tag {
    return self.types.tags.get(@enumFromInt(@intFromEnum(range.start) + idx));
}

fn stepTagRow(self: *Self, frame: *TagRowFrame, env: *Env, region: Region) Allocator.Error!RowStep {
    while (true) {
        switch (frame.stage) {
            .head_tags => {
                if (frame.idx < frame.tags.count) {
                    const tag = self.aliasRowTag(frame.tags, frame.idx);
                    if (try self.aliasRowNameIsDuplicate(frame.names_base, tag.name)) {
                        return try self.failAliasRow(.tag_union, frame.report_var, env, region);
                    }
                    frame.arg_idx = 0;
                    frame.stage = .head_args;
                    continue;
                }
                frame.stage = .ext_chain;
            },
            .head_args, .ext_args => {
                const tag = self.aliasRowTag(frame.tags, frame.idx);
                const args = self.types.sliceVars(tag.args);
                if (frame.arg_idx < args.len) {
                    const arg_var = args[frame.arg_idx];
                    frame.arg_idx += 1;
                    try self.alias_row_frames.append(self.gpa, .{ .node = arg_var });
                    return .suspended;
                }
                frame.idx += 1;
                frame.stage = switch (frame.stage) {
                    .head_args => .head_tags,
                    .ext_args => .ext_tags,
                    .head_tags, .ext_chain, .ext_tags => unreachable,
                };
            },
            .ext_chain => {
                var current = frame.ext;
                while (true) {
                    frame.guard.tick();
                    const resolved = self.types.resolveVar(current);
                    switch (resolved.desc.content) {
                        .alias => |alias| {
                            current = self.types.getAliasBackingVar(alias);
                        },
                        .structure => |flat_type| switch (flat_type) {
                            .tag_union => |tag_union| {
                                frame.tags = tag_union.tags;
                                frame.idx = 0;
                                frame.report_var = current;
                                frame.ext = tag_union.ext;
                                frame.stage = .ext_tags;
                                break;
                            },
                            .empty_tag_union => return .finished,
                            .record,
                            .record_unbound,
                            .tuple,
                            .nominal_type,
                            .fn_pure,
                            .fn_effectful,
                            .fn_unbound,
                            .empty_record,
                            => {
                                return try self.failAliasRow(.tag_union, current, env, region);
                            },
                        },
                        .flex, .rigid, .field_presence, .err => return .finished,
                    }
                }
            },
            .ext_tags => {
                if (frame.idx < frame.tags.count) {
                    const tag = self.aliasRowTag(frame.tags, frame.idx);
                    if (try self.aliasRowNameIsDuplicate(frame.names_base, tag.name)) {
                        return try self.failAliasRow(.tag_union, frame.report_var, env, region);
                    }
                    frame.arg_idx = 0;
                    frame.stage = .ext_args;
                    continue;
                }
                frame.stage = .ext_chain;
            },
        }
    }
}

fn reportInvalidAliasRow(
    self: *Self,
    comptime row_kind: AliasRowKind,
    actual_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!void {
    const expected_content: Content = switch (row_kind) {
        .record => .{ .structure = .empty_record },
        .tag_union => .{ .structure = .empty_tag_union },
    };
    const expected_var = try self.freshFromContent(expected_content, env, region);
    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, expected_var);
    const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, actual_var);

    _ = try self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
        .types = .{
            .expected_var = expected_var,
            .expected_snapshot = expected_snapshot,
            .actual_var = actual_var,
            .actual_snapshot = actual_snapshot,
        },
        .context = .type_annotation,
    } });
}

/// Set the content of anno_var to the builtin type.
///
/// Uses unifyWith to efficiently set content directly when possible,
/// avoiding the creation of an intermediate type variable.
fn setBuiltinTypeContent(
    self: *Self,
    anno_idx: CIR.TypeAnno.Idx,
    anno_var: Var,
    anno_builtin_name: Ident.Idx,
    anno_builtin_type: CIR.TypeAnno.Builtin,
    anno_args: []Var,
    anno_region: Region,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    switch (anno_builtin_type) {
        // Phase 5: Use nominal types from Builtin instead of special .num content
        .u8 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u8), env),
        .u16 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u16), env),
        .u32 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u32), env),
        .u64 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u64), env),
        .u128 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u128), env),
        .i8 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i8), env),
        .i16 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i16), env),
        .i32 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i32), env),
        .i64 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i64), env),
        .i128 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i128), env),
        .f32 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.f32), env),
        .f64 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.f64), env),
        .dec => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.dec), env),
        .list => {
            // Then check arity
            if (anno_args.len != 1) {
                _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                    .type_name = anno_builtin_name,
                    .region = anno_region,
                    .num_expected_args = 1,
                    .num_actual_args = @intCast(anno_args.len),
                } });

                // Set error
                try self.markErroneous(anno_var);
                return;
            }

            // Create the nominal List type
            const list_content = try self.mkListContent(anno_args[0]);
            try self.unifyWith(anno_var, list_content, env);
        },
        .box => {
            // Then check arity
            if (anno_args.len != 1) {
                _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                    .type_name = anno_builtin_name,
                    .region = anno_region,
                    .num_expected_args = 1,
                    .num_actual_args = @intCast(anno_args.len),
                } });

                // Set error
                try self.markErroneous(anno_var);
                return;
            }

            // Create the nominal Box type
            const box_content = try self.mkBoxContent(anno_args[0]);
            try self.unifyWith(anno_var, box_content, env);
        },
        // Polymorphic Num type is a module, not a type itself
        .num => {
            if (try self.builtinNotTypeAnnotationGenerationFailure(anno_idx, ctx)) |failure| {
                switch (ctx) {
                    .annotation => |anno_ctx| anno_ctx.failure_accumulator.record(failure),
                    .type_decl => unreachable,
                }
            }
            // Set error - Num is a module containing numeric types, not a type
            try self.markErroneous(anno_var);
        },
    }
}

// types //

/// Expression-local expectations. Lambda return targets live in
/// `ReturnConstraintFrame` so a nested expression annotation cannot replace them.
const Expected = struct {
    annotation: ?CIR.Annotation.Idx = null,
    annotation_attachment: ?BodyAnnotationAttachment = null,
    /// Exact binding RHS expression authenticated by the annotation's
    /// canonicalization publication. An `e_closure` forwards annotation
    /// materialization to its inner lambda, but the lambda must not become the
    /// durable failure owner merely because it performs that work.
    annotation_owner_expr: ?CIR.Expr.Idx = null,
    expected_type: ?ExpectedType = null,
    /// A type whose aggregate shape may guide nested construction checking,
    /// without making this expression node itself own the final relation.
    ///
    /// Stored values (list elements, tuple elements, record fields, and tag
    /// payloads) can generalize before the enclosing aggregate relates their
    /// instantiated use to its slot. Passing `expected_type` to those children
    /// would constrain the generalized scheme rather than that use. This
    /// separate channel lets aggregate expressions project child slots early;
    /// their owner still establishes the ordinary relation after
    /// `checkStoredValueExpr` returns the instantiated value.
    contextual_type: ?ExpectedType = null,
    branch_result: ?ExpectedType = null,
    comptime_condition_warnings: enum { emit, suppress } = .emit,
    hoist_position: HoistPosition = .suppressed,

    const ExpectedType = struct {
        var_: Var,
        context: problem.Context,
        marker_authority: ExpectedMarkerAuthority,
        status: ExpectedSourceStatus,
    };

    fn none() Expected {
        return .{};
    }

    fn fromAnnotation(
        annotation_idx: CIR.Annotation.Idx,
        attachment: BodyAnnotationAttachment,
    ) Expected {
        return Expected.none().withAnnotation(annotation_idx, attachment);
    }

    fn withAnnotation(
        self: Expected,
        annotation_idx: CIR.Annotation.Idx,
        attachment: BodyAnnotationAttachment,
    ) Expected {
        if (self.annotation != null or self.annotation_attachment != null or
            self.annotation_owner_expr != null)
        {
            std.debug.panic("Expected received a second annotation owner", .{});
        }
        return .{
            .annotation = annotation_idx,
            .annotation_attachment = attachment,
            .annotation_owner_expr = null,
            .expected_type = self.expected_type,
            .contextual_type = self.contextual_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn withExpectedType(self: Expected, expected_type: ExpectedType) Expected {
        return .{
            .annotation = self.annotation,
            .annotation_attachment = self.annotation_attachment,
            .annotation_owner_expr = self.annotation_owner_expr,
            .expected_type = expected_type,
            .contextual_type = self.contextual_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn withMaterializedAnnotation(self: Expected, expected_type: ExpectedType) Expected {
        return .{
            .annotation = null,
            .annotation_attachment = null,
            .annotation_owner_expr = null,
            .expected_type = expected_type,
            .contextual_type = self.contextual_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn withContextualType(self: Expected, contextual_type: ExpectedType) Expected {
        return .{
            .annotation = self.annotation,
            .annotation_attachment = self.annotation_attachment,
            .annotation_owner_expr = self.annotation_owner_expr,
            .expected_type = self.expected_type,
            .contextual_type = contextual_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn aggregateType(self: Expected) ?ExpectedType {
        return self.expected_type orelse self.contextual_type;
    }

    fn withBranchResult(self: Expected, branch_result: ExpectedType) Expected {
        return .{
            .annotation = self.annotation,
            .annotation_attachment = self.annotation_attachment,
            .annotation_owner_expr = self.annotation_owner_expr,
            .expected_type = self.expected_type,
            .contextual_type = self.contextual_type,
            .branch_result = branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn withHoistPosition(self: Expected, hoist_position: HoistPosition) Expected {
        return .{
            .annotation = self.annotation,
            .annotation_attachment = self.annotation_attachment,
            .annotation_owner_expr = self.annotation_owner_expr,
            .expected_type = self.expected_type,
            .contextual_type = self.contextual_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = hoist_position,
        };
    }

    fn suppressHoistSelection(self: Expected) Expected {
        return self.withHoistPosition(.suppressed);
    }

    fn forComptimeRoot(self: Expected) Expected {
        return .{
            .annotation = self.annotation,
            .annotation_attachment = self.annotation_attachment,
            .annotation_owner_expr = self.annotation_owner_expr,
            .expected_type = self.expected_type,
            .contextual_type = self.contextual_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = .suppress,
            .hoist_position = .comptime_root,
        };
    }

    fn forBranchBody(self: Expected) Expected {
        return .{
            // The branch checker owns the final branch-to-result relation, so
            // branch bodies receive only the structural channel. This lets a
            // nested aggregate see the branch result shape without binding a
            // generalized stored value directly to it.
            .contextual_type = self.expected_type orelse self.contextual_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = .suppressed,
        };
    }

    fn forStatement(self: Expected) Expected {
        return .{
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn forReturnValue(self: Expected, expected_return: ?ExpectedType) Expected {
        return .{
            .branch_result = expected_return,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn suppressComptimeConditionWarnings(self: Expected) Expected {
        return .{
            .annotation = self.annotation,
            .annotation_attachment = self.annotation_attachment,
            .annotation_owner_expr = self.annotation_owner_expr,
            .expected_type = self.expected_type,
            .contextual_type = self.contextual_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = .suppress,
            .hoist_position = self.hoist_position,
        };
    }

    fn withForwardedAnnotationOwner(self: Expected, owner_expr: CIR.Expr.Idx) Expected {
        if (self.annotation == null or self.annotation_attachment == null) {
            std.debug.panic("Expected forwarded an annotation owner without an annotation", .{});
        }
        if (self.annotation_owner_expr) |existing| {
            if (existing != owner_expr) {
                std.debug.panic("Expected changed its authenticated annotation owner", .{});
            }
            return self;
        }
        var forwarded = self;
        forwarded.annotation_owner_expr = owner_expr;
        return forwarded;
    }

    fn emitsComptimeConditionWarnings(self: Expected) bool {
        return self.comptime_condition_warnings == .emit;
    }
};

const TryArgs = struct {
    ok: Var,
    err: Var,
};

// pattern //

/// Whether a pattern's tag union or record row should be inferred open or closed
const RowOpenness = enum { open, closed };

/// The context that this pattern is being called in
/// This determines if, for tag unions & records, they should be inferred
/// as open or closed
const PatternCtx = enum {
    bound,
    fn_arg,
    from_annotation,
    for_,
    match_branch,

    fn toRowOpenness(self: PatternCtx) RowOpenness {
        return switch (self) {
            .bound, .fn_arg, .for_ => .closed,
            .from_annotation, .match_branch => .open,
        };
    }
};

/// Check the types for the provided pattern, saving the type in-place
fn checkPattern(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    ctx: PatternCtx,
    env: *Env,
) std.mem.Allocator.Error!void {
    _ = try self.checkPatternHelp(pattern_idx, ctx, env, .in_place);
}

/// Check the types for the provided pattern, either as fresh var or in-place
fn checkPatternHelp(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    ctx: PatternCtx,
    env: *Env,
    comptime out_var: OutVar,
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    const pattern = self.cir.store.getPattern(pattern_idx);
    const pattern_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(pattern_idx));
    const pattern_var = switch (comptime out_var) {
        .fresh => try self.fresh(env, pattern_region),
        .in_place => blk: {
            try self.setVarRank(ModuleEnv.varFrom(pattern_idx), env);
            break :blk ModuleEnv.varFrom(pattern_idx);
        },
    };

    switch (pattern) {
        .assign => {
            // Assigned variables start out as flex (initialized in preflight),
            // and their type is refined by usage. Reassignments reuse the same
            // pattern var, so never overwrite existing constraints here.
        },
        .underscore => {
            // Underscore can be anything; leave its placeholder flex intact.
        },
        // str //
        .str_literal => {
            // A literal pattern converts through from_quote and compares the
            // matched value against the converted constant, so the type also
            // needs equality.
            const flex_var = try self.mkFlexWithFromQuoteConstraint(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_region, env);
            _ = try self.unify(pattern_var, flex_var, env);
            try self.mkPatternLiteralEqConstraint(
                pattern_var,
                ModuleEnv.nodeIdxFrom(pattern_idx),
                .quote,
                env,
                pattern_region,
            );
        },
        .str_interpolation => |str| {
            const str_var = try self.freshStr(env, pattern_region);
            _ = try self.unify(pattern_var, str_var, env);

            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture_idx| {
                    const capture_region = self.cir.store.getPatternRegion(capture_idx);
                    const capture_var = try self.checkPatternHelp(capture_idx, ctx, env, .in_place);
                    const capture_str_var = try self.freshStr(env, capture_region);
                    _ = try self.unify(capture_var, capture_str_var, env);
                }
            }
        },
        // as //
        .as => |p| {
            const var_ = try self.checkPatternHelp(p.pattern, ctx, env, out_var);
            _ = try self.unify(var_, pattern_var, env);
        },
        // tuple //
        .tuple => |tuple| {
            const elem_vars_slice = blk: {
                switch (comptime out_var) {
                    .fresh => {
                        const scratch_vars_top = self.scratch_vars.top();
                        defer self.scratch_vars.clearFrom(scratch_vars_top);

                        // Check tuple elements
                        const elems_slice = self.cir.store.slicePatterns(tuple.patterns);
                        for (elems_slice) |single_elem_ptrn_idx| {
                            const elem_var = try self.checkPatternHelp(single_elem_ptrn_idx, ctx, env, out_var);
                            try self.scratch_vars.append(elem_var);
                        }

                        // Add to types store
                        break :blk try self.types.appendVars(self.scratch_vars.sliceFromStart(scratch_vars_top));
                    },
                    .in_place => {
                        // Check tuple elements
                        const elems_slice = self.cir.store.slicePatterns(tuple.patterns);
                        for (elems_slice) |single_elem_ptrn_idx| {
                            _ = try self.checkPatternHelp(single_elem_ptrn_idx, ctx, env, out_var);
                        }

                        // Add to types store
                        // Cast the elems idxs to vars (this works because Anno Idx are 1-1 with type Vars)
                        break :blk try self.types.appendVars(@ptrCast(elems_slice));
                    },
                }
            };

            // Set the type in the store
            try self.unifyWith(pattern_var, .{ .structure = .{
                .tuple = .{ .elems = elem_vars_slice },
            } }, env);
        },
        // list //
        .list => |list| {
            const elems = self.cir.store.slicePatterns(list.patterns);
            if (elems.len == 0) {
                // Create a nominal List with a fresh unbound element type
                const elem_var = try self.fresh(env, pattern_region);
                const list_content = try self.mkListContent(elem_var);
                try self.unifyWith(pattern_var, list_content, env);
            } else {
                // Here, we use the list's 1st element as the element var to
                // constrain the rest of the list

                // Check the first elem
                const elem_var = try self.checkPatternHelp(elems[0], ctx, env, out_var);

                // Iterate over the remaining elements
                var last_elem_ptrn_idx = elems[0];
                for (elems[1..], 1..) |elem_ptrn_idx, i| {
                    const cur_elem_var = try self.checkPatternHelp(elem_ptrn_idx, ctx, env, out_var);

                    // Unify each element's var with the list's elem var
                    const result = try self.unifyInContext(elem_var, cur_elem_var, env, .{ .list_entry = .{
                        .elem_index = @intCast(i),
                        .list_length = @intCast(elems.len),
                        .last_elem_idx = ModuleEnv.nodeIdxFrom(last_elem_ptrn_idx),
                    } });

                    // If we errored, check the rest of the elements without comparing
                    // to the elem_var to catch their individual errors
                    if (!result.isEstablished()) {
                        for (elems[i + 1 ..]) |remaining_elem_expr_idx| {
                            _ = try self.checkPatternHelp(remaining_elem_expr_idx, ctx, env, out_var);
                        }

                        // Break to avoid cascading errors
                        break;
                    }

                    last_elem_ptrn_idx = elem_ptrn_idx;
                }

                // Create a nominal List type with the inferred element type
                const list_content = try self.mkListContent(elem_var);
                try self.unifyWith(pattern_var, list_content, env);
            }

            // Then, check the "rest" pattern is bound to the list value.
            // This is if the pattern is like `.. as x`.
            if (list.rest_info) |rest_info| {
                if (rest_info.pattern) |rest_pattern_idx| {
                    const rest_pattern_var = try self.checkPatternHelp(rest_pattern_idx, ctx, env, out_var);

                    _ = try self.unify(pattern_var, rest_pattern_var, env);
                }
            }
        },
        // applied tag //
        .applied_tag => |applied_tag| {
            // Create a tag type in the type system and assign it the expr_var

            const arg_vars_slice = blk: {
                switch (comptime out_var) {
                    .fresh => {
                        const scratch_vars_top = self.scratch_vars.top();
                        defer self.scratch_vars.clearFrom(scratch_vars_top);

                        // Check tuple elements
                        const arg_ptrn_idx_slice = self.cir.store.slicePatterns(applied_tag.args);
                        for (arg_ptrn_idx_slice) |arg_expr_idx| {
                            const arg_var = try self.checkPatternHelp(arg_expr_idx, ctx, env, out_var);
                            try self.scratch_vars.append(arg_var);
                        }

                        // Add to types store
                        break :blk try self.types.appendVars(self.scratch_vars.sliceFromStart(scratch_vars_top));
                    },

                    .in_place => {
                        // Process each tag arg
                        const arg_ptrn_idx_slice = self.cir.store.slicePatterns(applied_tag.args);
                        for (arg_ptrn_idx_slice) |arg_expr_idx| {
                            _ = try self.checkPatternHelp(arg_expr_idx, ctx, env, out_var);
                        }

                        // Add to types store
                        // Cast the elems idxs to vars (this works because Anno Idx are 1-1 with type Vars)
                        break :blk try self.types.appendVars(@ptrCast(arg_ptrn_idx_slice));
                    },
                }
            };

            // Create the type
            const ext_var = switch (ctx.toRowOpenness()) {
                .open => try self.fresh(env, pattern_region),
                .closed => try self.freshFromContent(.{ .structure = .empty_tag_union }, env, pattern_region),
            };

            const tag = types_mod.Tag{ .name = applied_tag.name, .args = arg_vars_slice };
            const tag_union_content = try self.types.mkTagUnion(&[_]types_mod.Tag{tag}, ext_var);

            // Update the expr to point to the new type
            try self.unifyWith(pattern_var, tag_union_content, env);
        },
        // nominal //
        .nominal => |nominal| {
            // Check the backing pattern first
            const actual_backing_var = try self.checkPatternHelp(nominal.backing_pattern, ctx, env, out_var);

            // Use shared nominal type checking logic
            _ = try self.checkNominalTypeUsage(
                pattern_var,
                actual_backing_var,
                ModuleEnv.varFrom(nominal.nominal_type_decl),
                nominal.backing_type,
                pattern_region,
                env,
                .exact,
                pattern_idx,
            );
        },
        .nominal_external => |nominal| {
            // Check the backing pattern first
            const actual_backing_var = try self.checkPatternHelp(nominal.backing_pattern, ctx, env, out_var);

            // Resolve the external type declaration
            if (try self.resolveVarFromExternal(
                nominal.module_idx,
                nominal.target_node_idx,
                .{
                    .site_kind = .external_nominal_pattern,
                    .origin_node = @intFromEnum(pattern_idx),
                },
            )) |ext_ref| {
                // Use shared nominal type checking logic
                _ = try self.checkNominalTypeUsage(
                    pattern_var,
                    actual_backing_var,
                    ext_ref.local_var,
                    nominal.backing_type,
                    pattern_region,
                    env,
                    .exact,
                    pattern_idx,
                );
            } else {
                try self.markErroneous(pattern_var);
            }
        },
        // record destructure //
        .record_destructure => |destructure| {
            const scratch_records_top = self.scratch_record_fields.top();
            defer self.scratch_record_fields.clearFrom(scratch_records_top);

            var mb_ext_var: ?Var = null;

            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                const destruct_var = ModuleEnv.varFrom(destruct_idx);
                try self.setVarRank(destruct_var, env);

                // Check the sub pattern
                const field_pattern_var = blk: {
                    switch (destruct.kind) {
                        .Required => |sub_pattern_idx| {
                            break :blk try self.checkPatternHelp(sub_pattern_idx, ctx, env, out_var);
                        },
                        .SubPattern => |sub_pattern_idx| {
                            break :blk try self.checkPatternHelp(sub_pattern_idx, ctx, env, out_var);
                        },
                        .Rest => |sub_pattern_idx| {
                            // If this pattern is rest pattern:
                            // eg { name, ...rest }
                            //               ^^^^
                            //
                            // Then capture this as the ext var, then  continue
                            const ext_var = try self.checkPatternHelp(sub_pattern_idx, ctx, env, out_var);
                            _ = try self.unify(destruct_var, ext_var, env);
                            mb_ext_var = ext_var;

                            continue;
                        },
                    }
                };

                // Set the destruct var to redirect to the field pattern var
                _ = try self.unify(destruct_var, field_pattern_var, env);

                // The destructured field probes the record with a
                // kind-FLEXIBLE presence var (the same mint as a record
                // update's probe): the record's kind decides what the binder
                // sees. The row's value type is a FRESH payload var—the
                // binder is deliberately NOT the field's value type here,
                // because an `optional` kind binds it to
                // `Try(payload, [MissingField])` instead of the payload
                // itself. `judgeRecordDestructBinds` performs that
                // kind-directed binding at every generalization boundary
                // (and finalize); a still-flex kind pins `required` there—
                // destructuring must not silently make a field optional—
                // which is also why this mint is NOT recorded in
                // `literal_field_kinds` (design.md "Field Kinds").
                const destruct_region = self.getRegionAt(destruct_var);
                const presence_var = try self.fresh(env, destruct_region);
                const payload_var = try self.fresh(env, destruct_region);
                try self.pending_record_destructs.append(self.gpa, .{
                    .presence_var = presence_var,
                    .payload_var = payload_var,
                    .binder_var = destruct_var,
                    .field_name = destruct.label,
                    .region = destruct_region,
                });

                // Append it to the scratch records array
                try self.scratch_record_fields.append(types_mod.RecordField{
                    .name = destruct.label,
                    .presence = .unknown(presence_var, payload_var),
                });
            }

            // Copy the scratch record fields into the types store
            const record_fields_scratch = self.scratch_record_fields.sliceFromStart(scratch_records_top);
            std.mem.sort(types_mod.RecordField, record_fields_scratch, self.cir.getIdentStore(), types_mod.RecordField.sortByNameAsc);

            const record_fields_range = try self.types.appendRecordFields(record_fields_scratch);
            // Update the pattern var. A `..` rest pattern makes the record open
            // (its extension absorbs any remaining fields); without one, the
            // pattern is closed, so destructuring a record that has extra fields
            // is a type mismatch the user must resolve (e.g. by adding the field
            // or a `..` rest).
            const ext_var = mb_ext_var orelse
                try self.freshFromContent(.{ .structure = .empty_record }, env, pattern_region);
            try self.unifyWith(pattern_var, .{ .structure = .{
                .record = .{
                    .fields = record_fields_range,
                    .ext = ext_var,
                },
            } }, env);
        },
        // nums //
        .num_from_numeral_literal => {
            try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_var, pattern_region, .pattern, env);
        },
        .num_literal => |num| {
            switch (num.kind) {
                // For unannotated literals, create a flex var with from_numeral constraint
                .num_unbound, .int_unbound => try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_var, pattern_region, .pattern, env),
                // Phase 5: For explicitly typed literals, use nominal types from Builtin
                .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => try self.unifyWith(pattern_var, try self.mkNumberTypeContent(num.kind), env),
            }
        },
        .frac_f32_literal => {
            // Phase 5: Use nominal F32 type
            try self.unifyWith(pattern_var, try self.mkNumberTypeContent(.f32), env);
        },
        .frac_f64_literal => {
            // Phase 5: Use nominal F64 type
            try self.unifyWith(pattern_var, try self.mkNumberTypeContent(.f64), env);
        },
        .dec_literal => |dec| {
            if (dec.has_suffix) {
                // Explicit suffix like `3.14dec` - use nominal Dec type
                try self.unifyWith(pattern_var, try self.mkNumberTypeContent(.dec), env);
            } else {
                try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_var, pattern_region, .pattern, env);
            }
        },
        .small_dec_literal => |dec| {
            if (dec.has_suffix) {
                // Explicit suffix - use nominal Dec type
                try self.unifyWith(pattern_var, try self.mkNumberTypeContent(.dec), env);
            } else {
                try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_var, pattern_region, .pattern, env);
            }
        },
        .runtime_error => {
            try self.markErroneous(pattern_var);
        },
    }

    return pattern_var;
}

fn getPatternIdent(self: *const Self, ptrn_idx: CIR.Pattern.Idx) ?Ident.Idx {
    const pattern = self.cir.store.getPattern(ptrn_idx);
    switch (pattern) {
        .assign => |assign| return assign.ident,
        .as => |as_pattern| return as_pattern.ident,
        .applied_tag,
        .nominal,
        .nominal_external,
        .record_destructure,
        .list,
        .tuple,
        .num_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .num_from_numeral_literal,
        .str_literal,
        .str_interpolation,
        .underscore,
        .runtime_error,
        => return null,
    }
}

const CirPatternRefutabilityAdapter = struct {
    pub const PatternId = CIR.Pattern.Idx;

    checker: *const Self,

    pub fn patternClass(self: @This(), pattern_idx: PatternId) PatternRefutability.PatternClass {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .assign,
            .underscore,
            .runtime_error,
            => .cannot_miss,
            .as,
            .nominal,
            .nominal_external,
            => .child,
            .tuple => .sequence,
            .record_destructure => .record,
            .list => .list,
            .applied_tag,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            => .can_miss,
        };
    }

    pub fn child(self: @This(), pattern_idx: PatternId) PatternId {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .as => |as_pattern| as_pattern.pattern,
            .nominal => |nominal| nominal.backing_pattern,
            .nominal_external => |nominal| nominal.backing_pattern,
            .assign,
            .applied_tag,
            .record_destructure,
            .list,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn sequenceLen(self: @This(), pattern_idx: PatternId) usize {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .tuple => |tuple| self.checker.cir.store.slicePatterns(tuple.patterns).len,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .list,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn sequenceChild(self: @This(), pattern_idx: PatternId, index: usize) PatternId {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .tuple => |tuple| self.checker.cir.store.slicePatterns(tuple.patterns)[index],
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .list,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn recordLen(self: @This(), pattern_idx: PatternId) usize {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .record_destructure => |destructure| self.checker.cir.store.sliceRecordDestructs(destructure.destructs).len,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .list,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn recordChild(self: @This(), pattern_idx: PatternId, index: usize) PatternId {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .record_destructure => |destructure| blk: {
                const destruct_idx = self.checker.cir.store.sliceRecordDestructs(destructure.destructs)[index];
                const destruct = self.checker.cir.store.getRecordDestruct(destruct_idx);
                break :blk destruct.kind.toPatternIdx();
            },
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .list,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn listFixedLen(self: @This(), pattern_idx: PatternId) usize {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .list => |list| self.checker.cir.store.slicePatterns(list.patterns).len,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn listHasRest(self: @This(), pattern_idx: PatternId) bool {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .list => |list| list.rest_info != null,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn listRestPattern(self: @This(), pattern_idx: PatternId) ?PatternId {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .list => |list| list.rest_info.?.pattern,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }
};

fn patternNeedsExhaustiveness(self: *const Self, pattern_idx: CIR.Pattern.Idx) bool {
    return PatternRefutability.canMiss(CirPatternRefutabilityAdapter, .{ .checker = self }, pattern_idx);
}

const PatternBinding = struct {
    ident: Ident.Idx,
    pattern_idx: CIR.Pattern.Idx,
};

const MatchAltBaselineEntry = struct { pattern_idx: CIR.Pattern.Idx, pattern_index: u32 };

fn reportMatchAltBinderProblem(
    self: *Self,
    expected_pattern_idx: CIR.Pattern.Idx,
    actual_pattern_idx: CIR.Pattern.Idx,
    binder_ident: Ident.Idx,
    branch_index: u32,
    first_pattern_index: u32,
    pattern_index: u32,
    num_branches: u32,
    num_patterns: u32,
    match_expr: CIR.Expr.Idx,
) std.mem.Allocator.Error!void {
    const expected_var = ModuleEnv.varFrom(expected_pattern_idx);
    const actual_var = ModuleEnv.varFrom(actual_pattern_idx);
    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, expected_var);
    const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, actual_var);

    _ = try self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
        .types = .{
            .expected_var = expected_var,
            .expected_snapshot = expected_snapshot,
            .actual_var = actual_var,
            .actual_snapshot = actual_snapshot,
        },
        .context = .{ .match_alt_binder = .{
            .branch_index = branch_index,
            .first_pattern_index = first_pattern_index,
            .pattern_index = pattern_index,
            .num_branches = num_branches,
            .num_patterns = num_patterns,
            .binder_ident = binder_ident,
            .match_expr = match_expr,
        } },
    } });
}

fn collectPatternBindings(
    self: *const Self,
    pattern_idx: CIR.Pattern.Idx,
    out: *std.ArrayList(PatternBinding),
) std.mem.Allocator.Error!void {
    const pattern = self.cir.store.getPattern(pattern_idx);
    switch (pattern) {
        .assign => |assign| try out.append(self.gpa, .{ .ident = assign.ident, .pattern_idx = pattern_idx }),
        .as => |as_pat| {
            try out.append(self.gpa, .{ .ident = as_pat.ident, .pattern_idx = pattern_idx });
            try self.collectPatternBindings(as_pat.pattern, out);
        },
        .tuple => |tuple| {
            for (self.cir.store.slicePatterns(tuple.patterns)) |elem_pattern_idx| {
                try self.collectPatternBindings(elem_pattern_idx, out);
            }
        },
        .applied_tag => |tag| {
            for (self.cir.store.slicePatterns(tag.args)) |arg_pattern_idx| {
                try self.collectPatternBindings(arg_pattern_idx, out);
            }
        },
        .record_destructure => |destructure| {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                switch (destruct.kind) {
                    .Required => |sub_pattern_idx| try self.collectPatternBindings(sub_pattern_idx, out),
                    .SubPattern => |sub_pattern_idx| try self.collectPatternBindings(sub_pattern_idx, out),
                    .Rest => |sub_pattern_idx| try self.collectPatternBindings(sub_pattern_idx, out),
                }
            }
        },
        .list => |list| {
            for (self.cir.store.slicePatterns(list.patterns)) |elem_pattern_idx| {
                try self.collectPatternBindings(elem_pattern_idx, out);
            }
            if (list.rest_info) |rest| {
                if (rest.pattern) |rest_pattern_idx| {
                    try self.collectPatternBindings(rest_pattern_idx, out);
                }
            }
        },
        .nominal => |nom| try self.collectPatternBindings(nom.backing_pattern, out),
        .nominal_external => |nom| try self.collectPatternBindings(nom.backing_pattern, out),
        .str_interpolation => |str| {
            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture_idx| {
                    try self.collectPatternBindings(capture_idx, out);
                }
            }
        },
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        .underscore,
        .runtime_error,
        => {},
    }
}

fn unifyMatchAltPatternBindings(
    self: *Self,
    branch_ptrn_idxs: []const CIR.Expr.Match.BranchPattern.Idx,
    branch_index: u32,
    num_branches: u32,
    match_expr: CIR.Expr.Idx,
    env: *Env,
) std.mem.Allocator.Error!bool {
    if (branch_ptrn_idxs.len <= 1) return false;

    self.alt_pattern_baseline.clearRetainingCapacity();
    self.alt_pattern_bindings.clearRetainingCapacity();

    {
        const first_branch_pattern = self.cir.store.getMatchBranchPattern(branch_ptrn_idxs[0]);
        try self.collectPatternBindings(first_branch_pattern.pattern, &self.alt_pattern_bindings);
        for (self.alt_pattern_bindings.items) |binding| {
            try self.alt_pattern_baseline.put(@as(u32, @bitCast(binding.ident)), .{
                .pattern_idx = binding.pattern_idx,
                .pattern_index = 0,
            });
        }
    }

    var had_type_error = false;

    for (branch_ptrn_idxs[1..], 1..) |branch_ptrn_idx, pattern_index| {
        self.alt_pattern_bindings.clearRetainingCapacity();
        const branch_pattern = self.cir.store.getMatchBranchPattern(branch_ptrn_idx);
        try self.collectPatternBindings(branch_pattern.pattern, &self.alt_pattern_bindings);

        self.alt_pattern_current.clearRetainingCapacity();

        for (self.alt_pattern_bindings.items) |binding| {
            const key: u32 = @bitCast(binding.ident);
            try self.alt_pattern_current.put(key, binding.pattern_idx);
            const first = self.alt_pattern_baseline.get(key) orelse {
                const first_branch_pattern = self.cir.store.getMatchBranchPattern(branch_ptrn_idxs[0]);
                try self.reportMatchAltBinderProblem(
                    first_branch_pattern.pattern,
                    binding.pattern_idx,
                    binding.ident,
                    branch_index,
                    0,
                    @intCast(pattern_index),
                    num_branches,
                    @intCast(branch_ptrn_idxs.len),
                    match_expr,
                );
                had_type_error = true;
                continue;
            };
            const result = try self.unifyInContext(
                ModuleEnv.varFrom(first.pattern_idx),
                ModuleEnv.varFrom(binding.pattern_idx),
                env,
                .{ .match_alt_binder = .{
                    .branch_index = branch_index,
                    .first_pattern_index = first.pattern_index,
                    .pattern_index = @intCast(pattern_index),
                    .num_branches = num_branches,
                    .num_patterns = @intCast(branch_ptrn_idxs.len),
                    .binder_ident = binding.ident,
                    .match_expr = match_expr,
                } },
            );
            if (!result.isEstablished()) had_type_error = true;
        }

        var baseline_iter = self.alt_pattern_baseline.iterator();
        while (baseline_iter.next()) |entry| {
            if (self.alt_pattern_current.contains(entry.key_ptr.*)) continue;

            const ident: Ident.Idx = @bitCast(entry.key_ptr.*);
            try self.reportMatchAltBinderProblem(
                entry.value_ptr.pattern_idx,
                branch_pattern.pattern,
                ident,
                branch_index,
                entry.value_ptr.pattern_index,
                @intCast(pattern_index),
                num_branches,
                @intCast(branch_ptrn_idxs.len),
                match_expr,
            );
            had_type_error = true;
        }
    }

    return had_type_error;
}

// expr //

const CheckedExprStatus = union(enum) {
    established,
    checked_error: ModuleEnv.CauseOwner,
};

const CallExpectedSupport = struct {
    root_plan: u32,
    argument_plans: []u32,
};

const CalleeInstantiationAuthority = struct {
    call_root_token_index: u32,
    copy_step: u32,
    root_occurrence: u32,
    raw_source_var: Var,
    raw_destination_var: Var,
    raw_callee_var: Var,
};

const CheckedExprOutcome = struct {
    does_fx: bool,
    status: CheckedExprStatus,
    callee_instantiation: ?CalleeInstantiationAuthority = null,
};

const CheckedStoredValue = struct {
    does_fx: bool,
    var_: Var,
    status: CheckedExprStatus,
};

/// Publish the immutable baseline for a canonicalization-authored runtime
/// error at the exact typed expression edge which first consumes it. The raw
/// `.malformed` node tag is shared by statements and expressions, so scanning
/// untyped node storage cannot establish this fact; `checkExpr` supplies the
/// producer-authored `Expr.Idx` namespace.
fn preexistingRuntimeErrorCause(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    diagnostic: CIR.Diagnostic.Idx,
) std.mem.Allocator.Error!ModuleEnv.CauseOwner {
    const raw_expr: u32 = @intFromEnum(expr_idx);
    for (self.cir.expected_consumer_retirements.items.items, 0..) |retirement, retirement_index| {
        if (retirement.owner_kind != @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression) or
            retirement.retired_node != raw_expr)
        {
            continue;
        }
        if (retirement.decodedKind() != .preexisting_runtime_error or
            retirement.diagnostic_index != @intFromEnum(diagnostic))
        {
            std.debug.panic("preexisting runtime-error expression changed its exact retirement", .{});
        }
        return ModuleEnv.CauseOwner.expectedConsumerRetirement(@intCast(retirement_index));
    }

    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(expr_idx));
    if (node.tag != .malformed or
        self.cir.store.getExpr(expr_idx).e_runtime_error.diagnostic != diagnostic)
    {
        std.debug.panic("preexisting runtime-error producer lost its exact expression node", .{});
    }
    if (!malformedExpressionPublicationContains(
        self.cir,
        raw_expr,
        @intFromEnum(diagnostic),
    )) {
        std.debug.panic("preexisting runtime-error expression lacked typed canonicalization authority", .{});
    }
    const retirement_index = try self.cir.expected_consumer_retirements.append(self.cir.gpa, .{
        .retired_node = raw_expr,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression),
        .original_node_tag = @intFromEnum(node.tag),
        .original_payload = @bitCast(node.getPayload()),
        .kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.Kind.preexisting_runtime_error),
        .retired_consumers_start = 0,
        .retired_consumers_len = 0,
        .diagnostic_index = @intFromEnum(diagnostic),
        .expected_failures_start = 0,
        .expected_failures_len = 0,
        .rejection_owner_kind = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_owner_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_subject_var = ModuleEnv.ExpectedConsumerRetirement.none,
    });
    return ModuleEnv.CauseOwner.expectedConsumerRetirement(@intFromEnum(retirement_index));
}

/// Check an expression that a containing value stores, instantiating an
/// expression-position function scheme at this exact construction edge. The
/// containing value must refer to the fresh instance: embedding the pristine
/// generalized scheme would let later projections bypass the scheme-use edge
/// that supplies the nested function's static-dispatch evidence.
fn checkStoredValueExpr(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    env: *Env,
    expected: Expected,
) std.mem.Allocator.Error!CheckedStoredValue {
    const outcome = try self.checkExpr(expr_idx, env, expected);
    const source_var = ModuleEnv.varFrom(expr_idx);
    const resolved_source = self.types.resolveVar(source_var);
    if (resolved_source.desc.rank != .generalized and !self.isBindingSchemeVar(source_var)) {
        return .{
            .does_fx = outcome.does_fx,
            .var_ = source_var,
            .status = outcome.status,
        };
    }

    const previous_source = self.instantiation_source_expr;
    self.instantiation_source_expr = expr_idx;
    defer self.instantiation_source_expr = previous_source;
    std.debug.assert(self.pending_nested_function_use == null);
    self.pending_nested_function_use = expr_idx;
    const instance_var = try self.instantiateBindingVar(source_var, env, .use_last_var);
    std.debug.assert(self.pending_nested_function_use == null);
    return .{
        .does_fx = outcome.does_fx,
        .var_ = instance_var,
        .status = outcome.status,
    };
}

const ExpectedFreshShapeSlot = struct {
    expected_plan: u32,
    site: CIR.Expr.Idx,
    role: ModuleEnv.ExpectedConsumptionPlan.Role,
    slot: u32,
    raw_fresh_var: Var,
};

const ExpectedAggregatePlanRange = struct {
    owner_plan: u32,
    children_start: u32,
    children_len: u32,
};

fn pendingExpectedFreshShapeSlot(
    site: CIR.Expr.Idx,
    role: ModuleEnv.ExpectedConsumptionPlan.Role,
    slot: u32,
    raw_fresh_var: Var,
) ExpectedFreshShapeSlot {
    return .{
        .expected_plan = ModuleEnv.ExpectedConsumptionPlan.none,
        .site = site,
        .role = role,
        .slot = slot,
        .raw_fresh_var = raw_fresh_var,
    };
}

fn reservedExpectedPlan(
    owner: CIR.Expr.Idx,
    site: CIR.Expr.Idx,
    role: ModuleEnv.ExpectedConsumptionPlan.Role,
    slot: u32,
    raw_consumer_var: Var,
) ModuleEnv.ExpectedConsumptionPlan {
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    return .{
        .owner_node = @intFromEnum(owner),
        .site_node = @intFromEnum(site),
        .role = @intFromEnum(role),
        .slot = slot,
        .outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.reserved),
        .reason = none,
        .raw_consumer_var = @intFromEnum(raw_consumer_var),
        .parent_authority = ModuleEnv.ExpectedMarkerAuthority.inactive(),
        .produced_copy_step = none,
        .produced_occurrence_offset = none,
        .produced_side = none,
        .call_root_plan_index = none,
        .failure_owner = ModuleEnv.CauseOwner.inactive(),
        .failure_cause_plan_index = none,
    };
}

/// Preflight the checker-local owner correspondence before any durable plan row
/// is appended. One source expression can own only one aggregate or branch
/// plan range; a second registration would make later retirement ambiguous.
fn preflightExpectedOwnerPlanRange(
    self: *Self,
    owner: CIR.Expr.Idx,
) std.mem.Allocator.Error!void {
    if (self.probe_depth == 0) {
        std.debug.panic("Expected owner plan range was reserved outside a Probe transaction", .{});
    }
    for (self.expected_owner_plan_ranges.items) |registered| {
        if (registered.owner_expr == owner) {
            std.debug.panic("one Expected owner reserved multiple plan ranges", .{});
        }
    }
    try self.expected_owner_plan_ranges.ensureUnusedCapacity(self.gpa, 1);
}

/// Complete a preflighted owner registration after its whole plan range is
/// visible. This validates the closed producer topology once and then appends
/// without allocation, keeping reservation failure atomic under Probe rollback.
fn registerExpectedOwnerPlanRangeAssumeCapacity(
    self: *Self,
    registration: ExpectedOwnerPlanRange,
) void {
    const plans = self.cir.expected_consumption_plans.items.items;
    var range_start: u32 = undefined;
    var range_len: u32 = undefined;
    var first_role: ModuleEnv.ExpectedConsumptionPlan.Role = undefined;
    var last_role: ?ModuleEnv.ExpectedConsumptionPlan.Role = null;
    switch (registration.plans) {
        .aggregate => |aggregate| {
            if (aggregate.children_start != aggregate.owner_plan + 1) {
                std.debug.panic("aggregate owner registration lost its gapless plan range", .{});
            }
            range_start = aggregate.owner_plan;
            range_len = aggregate.children_len + 1;
            first_role = .aggregate_owner;
        },
        .branch => |branch| {
            if (branch.contributions_start != branch.seed_plan + 1 or
                branch.final_plan != branch.contributions_start + branch.contributions_len)
            {
                std.debug.panic("branch owner registration lost its gapless plan range", .{});
            }
            range_start = branch.seed_plan;
            range_len = branch.contributions_len + 2;
            first_role = .branch_seed;
            last_role = .branch_final;
        },
    }
    if (!rangeFits(range_start, range_len, plans.len)) {
        std.debug.panic("Expected owner registration escaped its reserved plan pool", .{});
    }
    const owned_plans = plans[range_start..][0..range_len];
    if (owned_plans[0].decodedRole() != first_role or
        (last_role != null and owned_plans[owned_plans.len - 1].decodedRole() != last_role.?))
    {
        std.debug.panic("Expected owner registration changed its producer roles", .{});
    }
    for (owned_plans) |plan| {
        if (plan.owner_node != @intFromEnum(registration.owner_expr) or
            plan.decodedOutcome() != .reserved)
        {
            std.debug.panic("Expected owner registration did not cover its exact reserved rows", .{});
        }
    }
    self.expected_owner_plan_ranges.appendAssumeCapacity(registration);
}

/// Reserve one syntax-rooted aggregate owner followed by every exact child
/// slot. Capacity is acquired before the first row is visible, so a failed
/// allocation cannot leave a child-only or partial aggregate publication.
fn reserveExpectedAggregatePlans(
    self: *Self,
    owner: CIR.Expr.Idx,
    raw_shape_root: Var,
    slots: []ExpectedFreshShapeSlot,
) std.mem.Allocator.Error!ExpectedAggregatePlanRange {
    const plans = &self.cir.expected_consumption_plans.items;
    try self.preflightExpectedOwnerPlanRange(owner);
    try plans.ensureUnusedCapacity(self.cir.gpa, 1 + slots.len);
    const owner_plan: u32 = @intCast(plans.items.len);
    plans.appendAssumeCapacity(reservedExpectedPlan(
        owner,
        owner,
        .aggregate_owner,
        0,
        raw_shape_root,
    ));
    const children_start: u32 = @intCast(plans.items.len);
    for (slots) |*slot| {
        if (slot.expected_plan != ModuleEnv.ExpectedConsumptionPlan.none) {
            std.debug.panic("aggregate child plan was reserved twice", .{});
        }
        slot.expected_plan = @intCast(plans.items.len);
        plans.appendAssumeCapacity(reservedExpectedPlan(
            owner,
            slot.site,
            slot.role,
            slot.slot,
            slot.raw_fresh_var,
        ));
    }
    const range: ExpectedAggregatePlanRange = .{
        .owner_plan = owner_plan,
        .children_start = children_start,
        .children_len = @intCast(slots.len),
    };
    self.registerExpectedOwnerPlanRangeAssumeCapacity(.{
        .owner_expr = owner,
        .plans = .{ .aggregate = range },
    });
    return range;
}

fn expectedSourceParentAuthority(
    authority: ExpectedMarkerAuthority,
) ModuleEnv.ExpectedMarkerAuthority {
    return switch (authority) {
        .anchored => |parent| encodeExpectedParentAuthority(parent),
        .evidence_free => |parent| .{
            .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.evidence_free_plan),
            .payload = .{ .evidence_free_plan = .{
                .plan_index = parent.plan_index,
                .raw_var = @intFromEnum(parent.raw_var),
            } },
        },
    };
}

/// Re-encode the exact transient Expected endpoint as the durable subject of
/// a failed child relation. This preserves copy-time occurrence identity; it
/// never substitutes the endpoint's later solved representative.
fn expectedFailureSubjectAuthority(
    authority: ExpectedMarkerAuthority,
) ModuleEnv.SubjectAuthority {
    return switch (authority) {
        .anchored => |parent| switch (parent) {
            .copy_occurrence => |anchor| ModuleEnv.SubjectAuthority.expectedCopyOccurrence(
                anchor.copy_step,
                anchor.occurrence_offset,
                anchor.side,
            ),
            .producer_root => |root| ModuleEnv.SubjectAuthority.expectedProducerRootPlan(
                root.plan_index,
                @intFromEnum(root.raw_var),
            ),
            .evidence_free_plan => |root| ModuleEnv.SubjectAuthority.expectedEvidenceFreePlan(
                root.plan_index,
                @intFromEnum(root.raw_var),
            ),
            .relation_plan => |root| ModuleEnv.SubjectAuthority.expectedRelationPlan(
                root.plan_index,
                @intFromEnum(root.raw_var),
            ),
        },
        .evidence_free => |root| ModuleEnv.SubjectAuthority.expectedEvidenceFreePlan(
            root.plan_index,
            @intFromEnum(root.raw_var),
        ),
    };
}

fn expectedAggregatePlanAt(
    self: *Self,
    range: ExpectedAggregatePlanRange,
    offset: u32,
) *ModuleEnv.ExpectedConsumptionPlan {
    if (offset > range.children_len) {
        std.debug.panic("aggregate Expected plan offset escaped its owner range", .{});
    }
    const index = range.owner_plan + offset;
    if (index >= self.cir.expected_consumption_plans.items.items.len) {
        std.debug.panic("aggregate Expected plan range escaped its pool", .{});
    }
    return &self.cir.expected_consumption_plans.items.items[index];
}

fn settleExpectedPlanWithoutProducedEndpoint(
    plan: *ModuleEnv.ExpectedConsumptionPlan,
    outcome: ModuleEnv.ExpectedConsumptionPlan.Outcome,
    reason: ModuleEnv.ExpectedConsumptionPlan.Reason,
    parent_authority: ModuleEnv.ExpectedMarkerAuthority,
    failure_owner: ModuleEnv.CauseOwner,
    failure_cause_plan_index: u32,
) void {
    if (plan.decodedOutcome() != .reserved) {
        std.debug.panic("Expected plan was settled more than once", .{});
    }
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    plan.outcome = @intFromEnum(outcome);
    plan.reason = @intFromEnum(reason);
    plan.parent_authority = parent_authority;
    plan.produced_copy_step = none;
    plan.produced_occurrence_offset = none;
    plan.produced_side = none;
    plan.call_root_plan_index = none;
    plan.failure_owner = failure_owner;
    plan.failure_cause_plan_index = failure_cause_plan_index;
    if (!plan.hasLegalTags()) {
        std.debug.panic("Expected producer settled a noncanonical plan", .{});
    }
}

fn settleExpectedAggregateRange(
    self: *Self,
    range: ExpectedAggregatePlanRange,
    outcome: ModuleEnv.ExpectedConsumptionPlan.Outcome,
    reason: ModuleEnv.ExpectedConsumptionPlan.Reason,
    parent_authority: ModuleEnv.ExpectedMarkerAuthority,
    failure_owner: ModuleEnv.CauseOwner,
    failure_cause_plan_index: u32,
) void {
    for (0..range.children_len + 1) |offset| {
        settleExpectedPlanWithoutProducedEndpoint(
            self.expectedAggregatePlanAt(range, @intCast(offset)),
            outcome,
            reason,
            parent_authority,
            failure_owner,
            failure_cause_plan_index,
        );
    }
}

fn completeExpectedAggregateOwnerAnchored(
    self: *Self,
    range: ExpectedAggregatePlanRange,
    parent: ExpectedParentAuthority,
    produced: ExpectedMarkerAnchor,
) void {
    const owner = self.expectedAggregatePlanAt(range, 0);
    if (owner.decodedRole() != .aggregate_owner or owner.decodedOutcome() != .reserved) {
        std.debug.panic("aggregate projection lost its reserved owner plan", .{});
    }
    owner.outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.anchored);
    owner.reason = ModuleEnv.ExpectedConsumptionPlan.none;
    owner.parent_authority = encodeExpectedParentAuthority(parent);
    owner.produced_copy_step = produced.copy_step;
    owner.produced_occurrence_offset = produced.occurrence_offset;
    owner.produced_side = @intFromEnum(produced.side);
    owner.call_root_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
    owner.failure_owner = ModuleEnv.CauseOwner.inactive();
    owner.failure_cause_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
    if (!owner.hasLegalTags()) {
        std.debug.panic("aggregate projection completed a noncanonical owner plan", .{});
    }
}

fn completeExpectedAggregateOwnerEvidenceFree(
    self: *Self,
    range: ExpectedAggregatePlanRange,
    parent: ExpectedEvidenceFreeAnchor,
) void {
    const owner = self.expectedAggregatePlanAt(range, 0);
    settleExpectedPlanWithoutProducedEndpoint(
        owner,
        .evidence_free,
        .parent_evidence_free,
        expectedSourceParentAuthority(.{ .evidence_free = parent }),
        ModuleEnv.CauseOwner.inactive(),
        ModuleEnv.ExpectedConsumptionPlan.none,
    );
}

/// Preflight the exact ambiguity-verdict publication which will retire one
/// branch owner. The bound copy occurrence is the immutable producer token;
/// final resolved equality is checked only as a consistency projection and is
/// never used to discover the occurrence.
fn prepareExpectedAmbiguityBranchRetirement(
    self: *Self,
    verdict: AmbiguityVerdict,
    selection: AmbiguitySelection,
) Allocator.Error!?ExpectedAmbiguityRetirementReservation {
    const instantiation_expr = verdict.instantiation_expr orelse return null;

    var branch_plans: ?ExpectedBranchPlanRange = null;
    for (self.expected_owner_plan_ranges.items) |registration| {
        if (registration.owner_expr != instantiation_expr) continue;
        if (branch_plans != null) {
            std.debug.panic("ambiguity verdict found duplicate Expected owner registrations", .{});
        }
        branch_plans = switch (registration.plans) {
            .branch => |range| range,
            .aggregate => std.debug.panic(
                "body-forced ambiguity attempted to retire an unsupported aggregate Expected owner",
                .{},
            ),
        };
    }
    const plans = branch_plans orelse return null;

    if (verdict.source != .instantiation or
        !selection.is_instantiated_where_clause or
        !selection.body_forced or
        selection.where_dispatch_use != null)
    {
        std.debug.panic("branch ambiguity retirement did not come from the closed body-forced verdict arm", .{});
    }
    const driver = verdict.instantiation_driver orelse
        std.debug.panic("branch ambiguity retirement omitted its bound instantiation occurrence", .{});
    if (driver.copy_step >= self.cir.where_marker_copy_steps.items.items.len) {
        std.debug.panic("branch ambiguity retirement named an absent copy step", .{});
    }
    const step = self.cir.where_marker_copy_steps.items.items[driver.copy_step];
    if (driver.pair_offset >= step.pairs_len or
        !rangeFits(step.pairs_start, step.pairs_len, self.cir.where_marker_copy_pairs.items.items.len) or
        !rangeFits(
            step.occurrences_start,
            step.occurrences_len,
            self.cir.where_marker_copy_occurrences.items.items.len,
        ))
    {
        std.debug.panic("branch ambiguity retirement escaped its copy relation", .{});
    }
    const pair = self.cir.where_marker_copy_pairs.items.items[step.pairs_start + driver.pair_offset];
    if (pair.destination_var >= self.types.len() or
        self.types.resolveVar(@enumFromInt(pair.destination_var)).var_ !=
            self.types.resolveVar(verdict.var_).var_)
    {
        std.debug.panic("branch ambiguity retirement copy pair did not produce its receiver", .{});
    }

    if (driver.occurrence_offset >= step.occurrences_len) {
        std.debug.panic("branch ambiguity retirement occurrence escaped its copy step", .{});
    }
    const occurrence = self.cir.where_marker_copy_occurrences.items.items[
        step.occurrences_start + driver.occurrence_offset
    ];
    if (occurrence.raw_destination_var != @intFromEnum(verdict.var_) or
        occurrence.canonical_pair_offset != driver.pair_offset)
    {
        std.debug.panic("branch ambiguity retirement named a different raw copy occurrence", .{});
    }

    const resolved = self.types.resolveVar(verdict.var_);
    const constraint_range = contentConstraintRange(resolved.desc.content) orelse
        std.debug.panic("branch ambiguity retirement receiver lost its selected constraint range", .{});
    if (selection.constraint_index < @intFromEnum(constraint_range.start) or
        selection.constraint_index - @intFromEnum(constraint_range.start) >= constraint_range.len() or
        selection.constraint_index >= self.types.static_dispatch_constraints.items.items.len or
        !std.meta.eql(
            self.types.static_dispatch_constraints.items.items[selection.constraint_index],
            selection.constraint,
        ))
    {
        std.debug.panic("branch ambiguity retirement selected a different constraint occurrence", .{});
    }

    // Every allocation needed to reserve and later complete the durable
    // branch retirement happens before the diagnostic or CIR rewrite. Once
    // this returns, publication through the preflighted suffix is infallible.
    try self.cir.expected_ambiguity_retirements.items.ensureUnusedCapacity(self.cir.gpa, 1);
    try self.cir.expected_consumer_retirements.items.ensureUnusedCapacity(self.cir.gpa, 1);
    try self.aggregate_expected_retirement_drafts.ensureUnusedCapacity(self.gpa, 1);
    try self.cir.expected_retired_consumers.items.ensureUnusedCapacity(
        self.cir.gpa,
        plans.contributions_len + 2,
    );

    return .{
        .retired_expr = instantiation_expr,
        .consumer_root_plan = plans.seed_plan,
        .consumer_plan_count = plans.contributions_len + 2,
        .consumer_group_kind = .branch,
        .copy_step = driver.copy_step,
        .occurrence_offset = driver.occurrence_offset,
        .pair_offset = driver.pair_offset,
    };
}

/// Publish the complete ambiguity verdict and its reserved branch retirement
/// after the diagnostic has been allocated but before the expression is
/// mutated. All list capacity was acquired by
/// `prepareExpectedAmbiguityBranchRetirement`.
fn publishExpectedAmbiguityBranchRetirement(
    self: *Self,
    verdict: AmbiguityVerdict,
    selection: AmbiguitySelection,
    diagnostic_idx: CIR.Diagnostic.Idx,
    reservation: ExpectedAmbiguityRetirementReservation,
) void {
    if (!self.cir.store.isDiagnosticIndex(diagnostic_idx)) {
        std.debug.panic("branch ambiguity retirement lost its selected diagnostic", .{});
    }
    const ambiguity_index: u32 = @intCast(self.cir.expected_ambiguity_retirements.items.items.len);
    const row = ModuleEnv.ExpectedAmbiguityRetirement{
        .raw_receiver_var = @intFromEnum(verdict.var_),
        .retired_expr = @intFromEnum(reservation.retired_expr),
        .selected_constraint_index = selection.constraint_index,
        .copy_step = reservation.copy_step,
        .occurrence_offset = reservation.occurrence_offset,
        .pair_offset = reservation.pair_offset,
        .diagnostic_index = @intFromEnum(diagnostic_idx),
        .consumer_root_plan = reservation.consumer_root_plan,
        .consumer_plan_count = reservation.consumer_plan_count,
        .kind = @intFromEnum(ModuleEnv.ExpectedAmbiguityRetirement.Kind.body_forced_instantiation_branch),
        .source = @intFromEnum(ModuleEnv.ExpectedAmbiguityRetirement.Source.instantiation),
        .consumer_group_kind = @intFromEnum(reservation.consumer_group_kind),
        .selection_flags = ModuleEnv.ExpectedAmbiguityRetirement.encodeSelectionFlags(
            selection.is_instantiated_where_clause,
            selection.only_where_clause_contracts,
            selection.body_forced,
            selection.where_dispatch_use != null,
        ),
    };
    if (!row.hasCanonicalTags()) {
        std.debug.panic("branch ambiguity retirement authored a noncanonical verdict row", .{});
    }
    self.cir.expected_ambiguity_retirements.items.appendAssumeCapacity(row);

    const cause = self.reserveExpectedPlanRetirement(
        reservation.retired_expr,
        reservation.consumer_root_plan,
        reservation.consumer_plan_count,
        .branch_retired_after_ambiguity_verdict,
    ) catch unreachable;
    const retirement_ref = cause.decodedExpectedConsumerRetirement() orelse
        std.debug.panic("branch ambiguity reservation returned a different cause namespace", .{});
    const retirement = &self.cir.expected_consumer_retirements.items.items[retirement_ref.index];
    if (retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.rejection_owner_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.rejection_subject_var != ModuleEnv.ExpectedConsumerRetirement.none)
    {
        std.debug.panic("branch ambiguity retirement reused another rejection owner", .{});
    }
    retirement.rejection_owner_kind =
        @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.RejectionOwnerKind.expected_ambiguity_retirement);
    retirement.rejection_owner_index = ambiguity_index;
    retirement.rejection_subject_var = @intFromEnum(verdict.var_);
}

/// Preflight the exact successful call-plan group erased by a direct creation
/// ambiguity verdict. Unlike the body-forced instantiation arm, this producer
/// has no copy-time driver: its authority is the raw call result, selected
/// constraint occurrence, and complete root-plus-arguments plan publication.
fn prepareExpectedAmbiguityCallRetirement(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    raw_receiver: Var,
    selection: AmbiguitySelection,
) Allocator.Error!?ExpectedAmbiguityRetirementReservation {
    const call = switch (self.cir.store.getExpr(expr_idx)) {
        .e_call => |present| present,
        else => return null,
    };
    if (selection.is_instantiated_where_clause or
        selection.only_where_clause_contracts or
        selection.body_forced or
        selection.where_dispatch_use != null)
    {
        std.debug.panic("creation-call ambiguity carried instantiation selection flags", .{});
    }
    switch (selection.constraint.origin) {
        .method_call, .desugared_binop, .desugared_unaryop => {},
        .from_literal, .where_clause => std.debug.panic(
            "creation-call ambiguity selected an excluded constraint origin",
            .{},
        ),
    }

    const resolved = self.types.resolveVar(raw_receiver);
    const constraint_range = contentConstraintRange(resolved.desc.content) orelse
        std.debug.panic("creation-call ambiguity receiver lost its selected constraint range", .{});
    if (selection.constraint_index < @intFromEnum(constraint_range.start) or
        selection.constraint_index - @intFromEnum(constraint_range.start) >= constraint_range.len() or
        selection.constraint_index >= self.types.static_dispatch_constraints.items.items.len or
        !std.meta.eql(
            self.types.static_dispatch_constraints.items.items[selection.constraint_index],
            selection.constraint,
        ))
    {
        std.debug.panic("creation-call ambiguity selected a different constraint occurrence", .{});
    }

    const plans = self.cir.expected_consumption_plans.items.items;
    var root_plan_index: ?u32 = null;
    for (plans, 0..) |plan, plan_index| {
        if (plan.decodedRole() != .call_root or plan.owner_node != @intFromEnum(expr_idx)) continue;
        if (root_plan_index != null) {
            std.debug.panic("creation-call ambiguity found duplicate call roots", .{});
        }
        root_plan_index = @intCast(plan_index);
    }
    const root = root_plan_index orelse return null;
    if (!expectedCallRootPlanIsCanonical(self.cir, plans[root])) {
        std.debug.panic("creation-call ambiguity found a noncanonical call root", .{});
    }

    const args = self.cir.store.sliceExpr(call.args);
    const plan_count: u32 = std.math.add(u32, @intCast(args.len), 1) catch
        std.debug.panic("creation-call ambiguity plan cardinality overflowed", .{});
    if (!rangeFits(root, plan_count, plans.len)) {
        std.debug.panic("creation-call ambiguity plan group escaped the plan pool", .{});
    }
    for (args, 0..) |arg_expr, arg_index| {
        const plan_index = root + 1 + @as(u32, @intCast(arg_index));
        const plan = plans[plan_index];
        if (!plan.hasLegalTags() or
            plan.decodedRole() != .call_argument or
            plan.decodedOutcome() != .producer_root or
            plan.decodedReason() != null or
            plan.owner_node != @intFromEnum(expr_idx) or
            plan.site_node != @intFromEnum(arg_expr) or
            plan.slot != @as(u32, @intCast(arg_index)) or
            plan.call_root_plan_index != root)
        {
            std.debug.panic("creation-call ambiguity lost an exact argument plan", .{});
        }
    }
    var owned_plan_count: u32 = 0;
    for (plans) |plan| {
        if (plan.owner_node == @intFromEnum(expr_idx)) owned_plan_count += 1;
    }
    if (owned_plan_count != plan_count) {
        std.debug.panic("creation-call ambiguity plan group had missing or extra rows", .{});
    }

    try self.cir.expected_ambiguity_retirements.items.ensureUnusedCapacity(self.cir.gpa, 1);
    try self.cir.expected_consumer_retirements.items.ensureUnusedCapacity(self.cir.gpa, 1);
    try self.aggregate_expected_retirement_drafts.ensureUnusedCapacity(self.gpa, 1);
    try self.cir.expected_retired_consumers.items.ensureUnusedCapacity(self.cir.gpa, plan_count);

    return .{
        .retired_expr = expr_idx,
        .consumer_root_plan = root,
        .consumer_plan_count = plan_count,
        .consumer_group_kind = .call,
        .copy_step = ModuleEnv.ExpectedAmbiguityRetirement.none,
        .occurrence_offset = ModuleEnv.ExpectedAmbiguityRetirement.none,
        .pair_offset = ModuleEnv.ExpectedAmbiguityRetirement.none,
    };
}

/// Publish the preflighted direct-creation call ambiguity and bind it
/// bijectively to the call-group retirement before the CIR node is replaced.
fn publishExpectedAmbiguityCallRetirement(
    self: *Self,
    raw_receiver: Var,
    selection: AmbiguitySelection,
    diagnostic_idx: CIR.Diagnostic.Idx,
    reservation: ExpectedAmbiguityRetirementReservation,
) void {
    if (!self.cir.store.isDiagnosticIndex(diagnostic_idx) or
        reservation.consumer_group_kind != .call)
    {
        std.debug.panic("creation-call ambiguity retirement lost its selected diagnostic or group", .{});
    }
    const ambiguity_index: u32 = @intCast(self.cir.expected_ambiguity_retirements.items.items.len);
    const row = ModuleEnv.ExpectedAmbiguityRetirement{
        .raw_receiver_var = @intFromEnum(raw_receiver),
        .retired_expr = @intFromEnum(reservation.retired_expr),
        .selected_constraint_index = selection.constraint_index,
        .copy_step = ModuleEnv.ExpectedAmbiguityRetirement.none,
        .occurrence_offset = ModuleEnv.ExpectedAmbiguityRetirement.none,
        .pair_offset = ModuleEnv.ExpectedAmbiguityRetirement.none,
        .diagnostic_index = @intFromEnum(diagnostic_idx),
        .consumer_root_plan = reservation.consumer_root_plan,
        .consumer_plan_count = reservation.consumer_plan_count,
        .kind = @intFromEnum(ModuleEnv.ExpectedAmbiguityRetirement.Kind.creation_dispatch_call),
        .source = @intFromEnum(ModuleEnv.ExpectedAmbiguityRetirement.Source.creation),
        .consumer_group_kind = @intFromEnum(reservation.consumer_group_kind),
        .selection_flags = ModuleEnv.ExpectedAmbiguityRetirement.encodeSelectionFlags(
            false,
            false,
            false,
            false,
        ),
    };
    if (!row.hasCanonicalTags()) {
        std.debug.panic("creation-call ambiguity authored a noncanonical retirement row", .{});
    }
    self.cir.expected_ambiguity_retirements.items.appendAssumeCapacity(row);

    const cause = self.reserveExpectedPlanRetirement(
        reservation.retired_expr,
        reservation.consumer_root_plan,
        reservation.consumer_plan_count,
        .call_retired,
    ) catch unreachable;
    const retirement_ref = cause.decodedExpectedConsumerRetirement() orelse
        std.debug.panic("creation-call ambiguity reservation returned a different cause namespace", .{});
    const retirement = &self.cir.expected_consumer_retirements.items.items[retirement_ref.index];
    if (retirement.rejection_owner_kind != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.rejection_owner_index != ModuleEnv.ExpectedConsumerRetirement.none or
        retirement.rejection_subject_var != ModuleEnv.ExpectedConsumerRetirement.none)
    {
        std.debug.panic("creation-call ambiguity retirement reused another rejection owner", .{});
    }
    retirement.rejection_owner_kind =
        @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.RejectionOwnerKind.expected_ambiguity_retirement);
    retirement.rejection_owner_index = ambiguity_index;
    retirement.rejection_subject_var = @intFromEnum(raw_receiver);
}

/// Reserve the exact syntax retirement which owns a rejected aggregate-shape
/// projection. The row is deliberately transiently incomplete: the central
/// runtime-error rewrite supplies the selected diagnostic and snapshots the
/// final pre-rewrite node bytes before the row can become durable.
fn reserveExpectedPlanRetirement(
    self: *Self,
    owner_expr: CIR.Expr.Idx,
    plans_start: u32,
    plans_len: u32,
    retired_reason: ModuleEnv.ExpectedConsumptionPlan.Reason,
) std.mem.Allocator.Error!ModuleEnv.CauseOwner {
    if (plans_len == 0 or
        !rangeFits(plans_start, plans_len, self.cir.expected_consumption_plans.items.items.len))
    {
        std.debug.panic("aggregate retirement lost its gapless Expected-plan range", .{});
    }
    const owner_raw: u32 = @intFromEnum(owner_expr);
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(owner_expr));
    if (!isExprNodeTag(node.tag) or node.tag == .malformed) {
        std.debug.panic("aggregate projection rejection lost its original expression", .{});
    }
    if (ModuleEnv.ExpectedConsumptionPlan.ownerRelationForReason(retired_reason) !=
        .same_node_retirement)
    {
        std.debug.panic("Expected retirement used a non-owning consumer reason", .{});
    }
    for (self.aggregate_expected_retirement_drafts.items) |draft| {
        if (draft.owner_expr != owner_expr) continue;
        if (draft.plans_start != plans_start or draft.plans_len != plans_len or
            draft.retired_reason != retired_reason)
        {
            std.debug.panic("one Expected owner changed its retirement range or reason", .{});
        }
        return ModuleEnv.CauseOwner.expectedConsumerRetirement(draft.retirement_index);
    }
    for (self.cir.expected_consumer_retirements.items.items) |retirement| {
        if (retirement.owner_kind == @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression) and
            retirement.retired_node == owner_raw)
        {
            std.debug.panic("aggregate projection rejection collided with another retirement owner", .{});
        }
    }

    const retirements = &self.cir.expected_consumer_retirements.items;
    try retirements.ensureUnusedCapacity(self.cir.gpa, 1);
    try self.aggregate_expected_retirement_drafts.ensureUnusedCapacity(self.gpa, 1);
    const retirement_index: u32 = @intCast(retirements.items.len);
    retirements.appendAssumeCapacity(.{
        .retired_node = owner_raw,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression),
        .original_node_tag = @intFromEnum(node.tag),
        .original_payload = @bitCast(node.getPayload()),
        .kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_expected),
        .retired_consumers_start = 0,
        .retired_consumers_len = 0,
        .diagnostic_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .expected_failures_start = 0,
        .expected_failures_len = 0,
        .rejection_owner_kind = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_owner_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_subject_var = ModuleEnv.ExpectedConsumerRetirement.none,
    });
    self.aggregate_expected_retirement_drafts.appendAssumeCapacity(.{
        .owner_expr = owner_expr,
        .retirement_index = retirement_index,
        .plans_start = plans_start,
        .plans_len = plans_len,
        .retired_reason = retired_reason,
    });
    return ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index);
}

/// Reserve the exact body-local runtime-error rewrite used when an otherwise
/// established branch contribution fails its Expected compatibility or
/// accumulator fold. A nested aggregate or branch body owns the exact plan
/// range registered by its producer; an owner outside that closed inventory
/// owns no range. The enclosing contribution remains present and names this
/// retirement as its direct-source cause in either case.
fn reserveBranchBodyRetirement(
    self: *Self,
    body_expr: CIR.Expr.Idx,
) std.mem.Allocator.Error!ModuleEnv.CauseOwner {
    var registered_range: ?ExpectedOwnerPlanRange = null;
    for (self.expected_owner_plan_ranges.items) |registered| {
        if (registered.owner_expr != body_expr) continue;
        if (registered_range != null) {
            std.debug.panic("one branch body had multiple Expected owner plan ranges", .{});
        }
        registered_range = registered;
    }
    if (registered_range) |registered| {
        return switch (registered.plans) {
            .aggregate => |range| self.reserveExpectedPlanRetirement(
                body_expr,
                range.owner_plan,
                range.children_len + 1,
                .aggregate_retired_by_parent_branch_failure,
            ),
            .branch => |range| self.reserveExpectedPlanRetirement(
                body_expr,
                range.seed_plan,
                range.contributions_len + 2,
                .branch_retired_after_failure,
            ),
        };
    }

    for (self.aggregate_expected_retirement_drafts.items) |draft| {
        if (draft.owner_expr == body_expr) {
            return ModuleEnv.CauseOwner.expectedConsumerRetirement(draft.retirement_index);
        }
    }
    const raw_body: u32 = @intFromEnum(body_expr);
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(body_expr));
    if (!isExprNodeTag(node.tag) or node.tag == .malformed) {
        std.debug.panic("branch rejection lost its original body expression", .{});
    }
    for (self.cir.expected_consumer_retirements.items.items) |retirement| {
        if (retirement.owner_kind == @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression) and
            retirement.retired_node == raw_body)
        {
            std.debug.panic("branch rejection collided with another body retirement", .{});
        }
    }

    const retirements = &self.cir.expected_consumer_retirements.items;
    try retirements.ensureUnusedCapacity(self.cir.gpa, 1);
    try self.aggregate_expected_retirement_drafts.ensureUnusedCapacity(self.gpa, 1);
    const retirement_index: u32 = @intCast(retirements.items.len);
    retirements.appendAssumeCapacity(.{
        .retired_node = raw_body,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression),
        .original_node_tag = @intFromEnum(node.tag),
        .original_payload = @bitCast(node.getPayload()),
        .kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible),
        .retired_consumers_start = 0,
        .retired_consumers_len = 0,
        .diagnostic_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .expected_failures_start = 0,
        .expected_failures_len = 0,
        .rejection_owner_kind = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_owner_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_subject_var = ModuleEnv.ExpectedConsumerRetirement.none,
    });
    self.aggregate_expected_retirement_drafts.appendAssumeCapacity(.{
        .owner_expr = body_expr,
        .retirement_index = retirement_index,
        .plans_start = 0,
        .plans_len = 0,
        .retired_reason = .branch_body_error_short_circuit,
    });
    return ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index);
}

fn reserveExpectedCallPlan(
    self: *Self,
    owner: CIR.Expr.Idx,
    site: CIR.Expr.Idx,
    role: ModuleEnv.ExpectedConsumptionPlan.Role,
    slot: u32,
    raw_consumer_var: Var,
) std.mem.Allocator.Error!u32 {
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    const plan = try self.cir.expected_consumption_plans.append(self.cir.gpa, .{
        .owner_node = @intFromEnum(owner),
        .site_node = @intFromEnum(site),
        .role = @intFromEnum(role),
        .slot = slot,
        .outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.reserved),
        .reason = none,
        .raw_consumer_var = @intFromEnum(raw_consumer_var),
        .parent_authority = ModuleEnv.ExpectedMarkerAuthority.inactive(),
        .produced_copy_step = none,
        .produced_occurrence_offset = none,
        .produced_side = none,
        .call_root_plan_index = none,
        .failure_owner = ModuleEnv.CauseOwner.inactive(),
        .failure_cause_plan_index = none,
    });
    return @intFromEnum(plan);
}

fn completeExpectedCallRootPlan(self: *Self, plan_index: u32) void {
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    const plan = &self.cir.expected_consumption_plans.items.items[plan_index];
    if (plan.decodedRole() != .call_root or plan.decodedOutcome() != .reserved) {
        std.debug.panic("call-root Expected plan did not own its reservation", .{});
    }
    plan.outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.not_projected);
    plan.reason = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Reason.call_shape_ready);
    plan.parent_authority = ModuleEnv.ExpectedMarkerAuthority.inactive();
    plan.produced_copy_step = none;
    plan.produced_occurrence_offset = none;
    plan.produced_side = none;
    plan.call_root_plan_index = none;
    plan.failure_owner = ModuleEnv.CauseOwner.inactive();
    plan.failure_cause_plan_index = none;
}

fn completeExpectedCallArgumentPlan(
    self: *Self,
    plan_index: u32,
    call_root_plan_index: u32,
) void {
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    const plan = &self.cir.expected_consumption_plans.items.items[plan_index];
    if (plan.decodedRole() != .call_argument or plan.decodedOutcome() != .reserved) {
        std.debug.panic("call-argument Expected plan did not own its producer reservation", .{});
    }
    plan.outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.producer_root);
    plan.reason = none;
    plan.parent_authority = ModuleEnv.ExpectedMarkerAuthority.inactive();
    plan.produced_copy_step = none;
    plan.produced_occurrence_offset = none;
    plan.produced_side = none;
    plan.call_root_plan_index = call_root_plan_index;
    plan.failure_owner = ModuleEnv.CauseOwner.inactive();
    plan.failure_cause_plan_index = none;
}

fn reserveExpectedFreshShapeSlot(
    self: *Self,
    owner: CIR.Expr.Idx,
    site: CIR.Expr.Idx,
    role: ModuleEnv.ExpectedConsumptionPlan.Role,
    slot: u32,
    raw_fresh_var: Var,
) std.mem.Allocator.Error!ExpectedFreshShapeSlot {
    const expected_plan_idx = try self.cir.expected_consumption_plans.append(
        self.cir.gpa,
        reservedExpectedPlan(owner, site, role, slot, raw_fresh_var),
    );
    const expected_plan: u32 = @intFromEnum(expected_plan_idx);
    return .{
        .expected_plan = expected_plan,
        .site = site,
        .role = role,
        .slot = slot,
        .raw_fresh_var = raw_fresh_var,
    };
}

fn preflightRecordUpdateExpectedPlanRegistration(
    self: *Self,
    owner: CIR.Expr.Idx,
    role: ModuleEnv.ExpectedConsumptionPlan.Role,
    slot: u32,
) std.mem.Allocator.Error!void {
    if (self.record_update_expected_plan_registrations_consumed) {
        std.debug.panic("record-update Expected plan was published after registration consumption", .{});
    }
    if (self.probe_depth == 0) {
        std.debug.panic("record-update Expected plan was reserved outside a Probe transaction", .{});
    }
    if (role != .record_update_base and role != .record_update_field) {
        std.debug.panic("record-update registration received a foreign Expected role", .{});
    }
    for (self.record_update_expected_plan_registrations.items) |registration| {
        if (registration.owner_expr == owner and
            registration.role == role and registration.slot == slot)
        {
            std.debug.panic("record-update Expected slot was registered twice", .{});
        }
    }
    try self.record_update_expected_plan_registrations.ensureUnusedCapacity(self.gpa, 1);
}

fn validateRecordUpdateExpectedPlanRegistrations(self: *const Self) bool {
    const registrations = self.record_update_expected_plan_registrations.items;
    if (self.record_update_expected_plan_registrations_consumed) {
        return registrations.len == 0;
    }
    const plans = self.cir.expected_consumption_plans.items.items;
    for (registrations, 0..) |registration, registration_index| {
        if (registration.plan_index >= plans.len) return false;
        const plan = plans[registration.plan_index];
        if (!plan.hasLegalTags() or
            plan.owner_node != @intFromEnum(registration.owner_expr) or
            plan.site_node != @intFromEnum(registration.site) or
            plan.decodedRole() != registration.role or
            plan.slot != registration.slot or
            (registration.role != .record_update_base and
                registration.role != .record_update_field))
        {
            return false;
        }
        for (registrations[0..registration_index]) |prior| {
            if (prior.plan_index == registration.plan_index or
                (prior.owner_expr == registration.owner_expr and
                    prior.role == registration.role and prior.slot == registration.slot))
            {
                return false;
            }
        }
    }
    for (plans, 0..) |plan, plan_index| {
        const role = plan.decodedRole() orelse return false;
        if (role != .record_update_base and role != .record_update_field) continue;
        var registration_count: usize = 0;
        for (registrations) |registration| {
            if (registration.plan_index == @as(u32, @intCast(plan_index))) {
                registration_count += 1;
            }
        }
        if (registration_count != 1) return false;
    }
    return true;
}

fn registerRecordUpdateExpectedPlanAssumeCapacity(
    self: *Self,
    registration: RecordUpdateExpectedPlanRegistration,
) void {
    if (registration.plan_index >= self.cir.expected_consumption_plans.items.items.len) {
        std.debug.panic("record-update registration named an absent Expected plan", .{});
    }
    const plan = self.cir.expected_consumption_plans.items.items[registration.plan_index];
    if (!plan.hasLegalTags() or plan.decodedOutcome() == .reserved or
        plan.owner_node != @intFromEnum(registration.owner_expr) or
        plan.site_node != @intFromEnum(registration.site) or
        plan.decodedRole() != registration.role or plan.slot != registration.slot)
    {
        std.debug.panic("record-update registration changed its exact producer plan", .{});
    }
    self.record_update_expected_plan_registrations.appendAssumeCapacity(registration);
}

fn recordUpdateOwnerExpectedMembershipAtPhase(
    self: *const Self,
    owner_expr: CIR.Expr.Idx,
    base_plan_index: u32,
    base_cause: ModuleEnv.CauseOwner,
    base_phase: RecordUpdateBaseNodePhase,
) bool {
    if (self.record_update_expected_plan_registrations_consumed or
        base_plan_index >= self.cir.expected_consumption_plans.items.items.len)
    {
        return false;
    }
    const owner_raw: u32 = @intFromEnum(owner_expr);
    const update = expectedRecordUpdateSyntaxAtPhase(
        self.cir,
        owner_raw,
        base_phase,
    ) orelse return false;
    const plans = self.cir.expected_consumption_plans.items.items;
    const base_plan = plans[base_plan_index];
    if (!base_plan.hasLegalTags() or
        base_plan.owner_node != owner_raw or
        base_plan.site_node != update.base_expr or
        base_plan.decodedRole() != .record_update_base or
        base_plan.slot != 0 or
        base_plan.decodedOutcome() != .source_root_copy_checked_error or
        base_plan.decodedReason() != .record_update_base_checked_error or
        !expectedCauseOwnersEqual(base_plan.failure_owner, base_cause) or
        !expectedRecordUpdateBasePlanMatchesStep(self.cir, base_plan))
    {
        return false;
    }
    const base_authority = expectedRecordUpdateBaseAuthority(base_plan) orelse return false;

    var owner_registration_count: usize = 0;
    var base_registration_count: usize = 0;
    for (self.record_update_expected_plan_registrations.items) |registration| {
        if (registration.owner_expr != owner_expr) continue;
        owner_registration_count += 1;
        if (registration.plan_index >= plans.len) return false;
        const plan = plans[registration.plan_index];
        if (!plan.hasLegalTags() or plan.owner_node != owner_raw or
            plan.site_node != @intFromEnum(registration.site) or
            plan.decodedRole() != registration.role or plan.slot != registration.slot)
        {
            return false;
        }
        switch (registration.role) {
            .record_update_base => {
                if (registration.plan_index != base_plan_index or
                    registration.slot != 0 or registration.site != @as(CIR.Expr.Idx, @enumFromInt(update.base_expr)))
                {
                    return false;
                }
                base_registration_count += 1;
            },
            .record_update_field => {
                const field_site = expectedRecordUpdateFieldSite(
                    self.cir,
                    update,
                    registration.slot,
                ) orelse return false;
                if (field_site != @intFromEnum(registration.site) or
                    plan.decodedOutcome() != .checked_error or
                    plan.decodedReason() != .record_update_field_base_checked_error or
                    plan.failure_cause_plan_index != base_plan_index or
                    !expectedCauseOwnersEqual(plan.failure_owner, base_cause) or
                    !expectedFreshShapePlanMatchesCir(self.cir, plan) or
                    !expectedRecordUpdateFieldBeginsAtBase(
                        self.cir,
                        registration.plan_index,
                        plan,
                        base_authority,
                    ))
                {
                    return false;
                }
            },
            else => return false,
        }
    }
    if (base_registration_count != 1 or
        owner_registration_count != @as(usize, update.fields_len) + 1)
    {
        return false;
    }
    for (0..@as(usize, update.fields_len)) |slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        const site = expectedRecordUpdateFieldSite(self.cir, update, slot) orelse return false;
        var count: usize = 0;
        for (self.record_update_expected_plan_registrations.items) |registration| {
            if (registration.owner_expr == owner_expr and
                registration.role == .record_update_field and
                registration.slot == slot and @intFromEnum(registration.site) == site)
            {
                count += 1;
            }
        }
        if (count != 1) return false;
    }
    for (plans, 0..) |plan, plan_index| {
        if (plan.owner_node != owner_raw) continue;
        const role = plan.decodedRole() orelse return false;
        if (role != .record_update_base and role != .record_update_field) return false;
        var count: usize = 0;
        for (self.record_update_expected_plan_registrations.items) |registration| {
            count += @intFromBool(
                registration.owner_expr == owner_expr and
                    registration.plan_index == @as(u32, @intCast(plan_index)),
            );
        }
        if (count != 1) return false;
    }
    return true;
}

fn recordUpdateOwnerExpectedMembershipAtProducer(
    self: *const Self,
    owner_expr: CIR.Expr.Idx,
    base_plan_index: u32,
    base_cause: ModuleEnv.CauseOwner,
) bool {
    if (base_plan_index >= self.cir.expected_consumption_plans.items.items.len) return false;
    const base_plan = self.cir.expected_consumption_plans.items.items[base_plan_index];
    const source_retirement_index = base_plan.decodedSourceRetirementIndex() orelse return false;
    if (source_retirement_index >= self.cir.expected_consumer_retirements.items.items.len or
        base_plan.site_node >= self.cir.store.nodes.len())
    {
        return false;
    }
    const base_expr: CIR.Expr.Idx = @enumFromInt(base_plan.site_node);
    const base_node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(base_expr));
    const base_phase: RecordUpdateBaseNodePhase = if (base_node.tag == .malformed)
        .retired
    else if (isExprNodeTag(base_node.tag))
        .live
    else
        return false;
    const source_lifecycle_matches = switch (base_phase) {
        .retired => expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
            self.cir,
            base_plan,
        ),
        .live => blk: {
            const pending = pendingExpressionRetirementAtProducer(
                self,
                base_expr,
            ) orelse break :blk false;
            break :blk pending == source_retirement_index;
        },
    };
    return source_lifecycle_matches and recordUpdateOwnerExpectedMembershipAtPhase(
        self,
        owner_expr,
        base_plan_index,
        base_cause,
        base_phase,
    );
}

fn reserveRecordUpdateOwnerRetirement(
    self: *Self,
    owner_expr: CIR.Expr.Idx,
    base_plan_index: u32,
    base_cause: ModuleEnv.CauseOwner,
) Allocator.Error!ModuleEnv.CauseOwner {
    if (self.probe_depth == 0 or
        !recordUpdateOwnerExpectedMembershipAtProducer(
            self,
            owner_expr,
            base_plan_index,
            base_cause,
        ))
    {
        std.debug.panic("record-update checked base lost its complete owner membership", .{});
    }
    for (self.record_update_owner_retirement_drafts.items) |draft| {
        if (draft.owner_expr == owner_expr) {
            std.debug.panic("record-update owner reserved multiple checked-base retirements", .{});
        }
    }
    for (self.aggregate_expected_retirement_drafts.items) |draft| {
        if (draft.owner_expr == owner_expr) {
            std.debug.panic("record-update owner mixed aggregate retirement lifecycles", .{});
        }
    }
    for (self.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr == owner_expr) {
            std.debug.panic("record-update owner mixed failure retirement lifecycles", .{});
        }
    }
    const owner_raw: u32 = @intFromEnum(owner_expr);
    for (self.cir.expected_consumer_retirements.items.items) |retirement| {
        if (retirement.decodedOwnerKind() == .expression and
            retirement.retired_node == owner_raw)
        {
            std.debug.panic("record-update owner retirement collided with another lifecycle", .{});
        }
    }
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(owner_expr));
    if (node.tag != .expr_record) {
        std.debug.panic("record-update owner retirement lost its live record", .{});
    }
    const source_retirement = self.cir.expected_consumption_plans.items.items[
        base_plan_index
    ].decodedSourceRetirementIndex() orelse
        std.debug.panic("record-update checked base omitted its source retirement", .{});
    const source_retirement_complete = expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
        self.cir,
        self.cir.expected_consumption_plans.items.items[base_plan_index],
    );
    const pending_source_retirement = if (source_retirement_complete) null else pendingExpressionRetirementAtProducer(
        self,
        @enumFromInt(self.cir.expected_consumption_plans.items.items[base_plan_index].site_node),
    );
    if (!source_retirement_complete and
        (pending_source_retirement == null or pending_source_retirement.? != source_retirement))
    {
        std.debug.panic("record-update checked base changed its source retirement", .{});
    }

    try self.cir.expected_consumer_retirements.items.ensureUnusedCapacity(
        self.cir.gpa,
        1,
    );
    try self.record_update_owner_retirement_drafts.ensureUnusedCapacity(self.gpa, 1);
    const retirement_index: u32 = @intCast(
        self.cir.expected_consumer_retirements.items.items.len,
    );
    const payload: [4]u32 = @bitCast(node.getPayload());
    self.cir.expected_consumer_retirements.items.appendAssumeCapacity(.{
        .retired_node = owner_raw,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression),
        .original_node_tag = @intFromEnum(node.tag),
        .original_payload = payload,
        .kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_expected),
        .retired_consumers_start = 0,
        .retired_consumers_len = 0,
        .diagnostic_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .expected_failures_start = 0,
        .expected_failures_len = 0,
        .rejection_owner_kind = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_owner_index = ModuleEnv.ExpectedConsumerRetirement.none,
        .rejection_subject_var = ModuleEnv.ExpectedConsumerRetirement.none,
    });
    self.record_update_owner_retirement_drafts.appendAssumeCapacity(.{
        .owner_expr = owner_expr,
        .retirement_index = retirement_index,
        .base_plan_index = base_plan_index,
        .base_cause = base_cause,
        .original_node_tag = @intFromEnum(node.tag),
        .original_payload = payload,
    });
    return ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index);
}

/// Atomically reserve the checked-base retirement for one record-update owner.
/// The caller provides the exact producer-returned base cause and its already
/// published base plan; this boundary does not reconstruct either from solved
/// state.
fn publishRecordUpdateOwnerRetirement(
    self: *Self,
    env: *Env,
    owner_expr: CIR.Expr.Idx,
    base_plan_index: u32,
    base_cause: ModuleEnv.CauseOwner,
) Allocator.Error!ModuleEnv.CauseOwner {
    var publication = try self.beginProbe(env);
    var publication_open = true;
    defer if (publication_open) publication.rollback();
    const cause = try self.reserveRecordUpdateOwnerRetirement(
        owner_expr,
        base_plan_index,
        base_cause,
    );
    publication.commit();
    publication_open = false;
    return cause;
}

fn annotationFailureKindMatchesDraftProducer(
    kind: ModuleEnv.ExpectedFailure.Kind,
    producer: AnnotationExpectedFailureDraft.ProducerKind,
) bool {
    return switch (producer) {
        .annotation => switch (kind) {
            .annotation_malformed_type,
            .annotation_malformed_where,
            .annotation_invalid_tag_child,
            .annotation_where_receiver_not_introduced,
            .annotation_where_alias_not_alias,
            .annotation_recursive_where_alias,
            .annotation_where_alias_publication_error,
            .annotation_where_alias_unresolved,
            .annotation_where_alias_arity,
            .annotation_where_alias_in_type_position,
            .annotation_builtin_not_type,
            .annotation_recursive_type_decl,
            .annotation_type_decl_poisoned,
            .annotation_type_formal_poisoned,
            .annotation_type_apply_arity,
            .annotation_alias_row_rejected,
            .annotation_external_type_unresolved,
            .annotation_child_failure,
            .annotation_duplicate_where_signature_rejected,
            => true,
            .direct_binder_lookup_checked_error,
            .annotated_binding_lookup_checked_error,
            .call_operand_checked_error,
            .nominal_pattern_external_unresolved,
            .nominal_pattern_decl_poisoned,
            .nominal_pattern_opaque_inaccessible,
            .nominal_pattern_backing_unavailable,
            .nominal_pattern_backing_checked_error,
            .nominal_pattern_backing_relation_rejected,
            .aggregate_child_relation_rejected,
            => false,
        },
        .direct_binder_lookup => kind == .direct_binder_lookup_checked_error,
        .annotated_binding_lookup => kind == .annotated_binding_lookup_checked_error,
        .call_operand => kind == .call_operand_checked_error,
    };
}

const PendingExpressionRetirementIdentity = struct {
    retirement_index: u32,
    record_update_owner: ?RecordUpdateOwnerRetirementDraft,
};

fn pendingExpectedConsumerRetirementHasCanonicalInactiveWords(
    retirement: ModuleEnv.ExpectedConsumerRetirement,
) bool {
    return retirement.diagnostic_index == ModuleEnv.ExpectedConsumerRetirement.none and
        retirement.retired_consumers_start == 0 and retirement.retired_consumers_len == 0 and
        retirement.expected_failures_start == 0 and retirement.expected_failures_len == 0 and
        retirement.rejection_owner_kind == ModuleEnv.ExpectedConsumerRetirement.none and
        retirement.rejection_owner_index == ModuleEnv.ExpectedConsumerRetirement.none and
        retirement.rejection_subject_var == ModuleEnv.ExpectedConsumerRetirement.none and
        retirement.reserved_0 == 0 and retirement.reserved_1 == 0;
}

/// Select the one already-authored shallow pending retirement identity for a
/// live expression. This authenticates the exact producer-owned draft family
/// and row without recursively replaying a nested checked-base cause graph.
fn pendingExpressionRetirementIdentityAtProducer(
    self: *const Self,
    base_expr: CIR.Expr.Idx,
) ?PendingExpressionRetirementIdentity {
    const base_raw: u32 = @intFromEnum(base_expr);
    if (base_raw >= self.cir.store.nodes.len()) return null;
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(base_expr));
    if (!isExprNodeTag(node.tag)) {
        std.debug.panic("pending record-update base retirement lost its live expression", .{});
    }

    var aggregate: ?AggregateExpectedRetirementDraft = null;
    for (self.aggregate_expected_retirement_drafts.items) |draft| {
        if (draft.owner_expr != base_expr) continue;
        if (aggregate != null) {
            std.debug.panic("record-update base had multiple aggregate retirement lifecycles", .{});
        }
        aggregate = draft;
    }

    var annotation_retirement: ?u32 = null;
    var annotation_producer: ?AnnotationExpectedFailureDraft.ProducerKind = null;
    var annotation_count: usize = 0;
    for (self.annotation_expected_failure_drafts.items, 0..) |draft, draft_index| {
        if (draft.owner_expr != base_expr) continue;
        if (draft.retirement_index >= self.cir.expected_consumer_retirements.items.items.len or
            draft.failure_index >= self.cir.expected_failures.items.items.len)
        {
            std.debug.panic("record-update base failure draft lost its retirement or failure", .{});
        }
        if (annotation_retirement) |selected| {
            if (selected != draft.retirement_index) {
                std.debug.panic("record-update base failure drafts named multiple retirements", .{});
            }
        } else {
            annotation_retirement = draft.retirement_index;
        }
        if (annotation_producer) |selected| {
            if (selected != draft.producer_kind) {
                std.debug.panic("record-update base mixed failure-draft producer kinds", .{});
            }
        } else {
            annotation_producer = draft.producer_kind;
        }
        const failure = self.cir.expected_failures.items.items[draft.failure_index];
        if (!failure.hasLegalTagsAt(draft.failure_index) or
            failure.decodedOwnerKind() != .expression or
            failure.owner_node != base_raw or
            !annotationFailureKindMatchesDraftProducer(
                failure.decodedKind() orelse
                    std.debug.panic("record-update base failure draft had an unknown kind", .{}),
                draft.producer_kind,
            ) or !failure.cause_owner.hasCanonicalTags(true))
        {
            std.debug.panic("record-update base failure draft changed its exact producer edge", .{});
        }
        for (self.annotation_expected_failure_drafts.items[0..draft_index]) |prior| {
            if (prior.owner_expr == base_expr and prior.failure_index == draft.failure_index) {
                std.debug.panic("record-update base failure lifecycle duplicated one failure", .{});
            }
        }
        annotation_count += 1;
    }

    var record_update_owner: ?RecordUpdateOwnerRetirementDraft = null;
    for (self.record_update_owner_retirement_drafts.items) |draft| {
        if (draft.owner_expr != base_expr) continue;
        if (record_update_owner != null) {
            std.debug.panic("record-update base had multiple checked-base owner lifecycles", .{});
        }
        record_update_owner = draft;
    }
    if (record_update_owner) |draft| {
        if (aggregate != null or annotation_count != 0 or
            draft.retirement_index >= self.cir.expected_consumer_retirements.items.items.len or
            draft.base_plan_index >= self.cir.expected_consumption_plans.items.items.len)
        {
            std.debug.panic("record-update base mixed its checked-base owner lifecycle", .{});
        }
        const base_plan = self.cir.expected_consumption_plans.items.items[
            draft.base_plan_index
        ];
        if (base_plan.site_node >= self.cir.store.nodes.len()) {
            std.debug.panic("record-update base owner lifecycle lost its base site", .{});
        }
        const source_node = self.cir.store.nodes.get(@enumFromInt(base_plan.site_node));
        const base_phase: RecordUpdateBaseNodePhase = if (source_node.tag == .malformed)
            .retired
        else if (isExprNodeTag(source_node.tag))
            .live
        else
            std.debug.panic("record-update base owner lifecycle found an invalid base phase", .{});
        if (!recordUpdateOwnerExpectedMembershipAtPhase(
            self,
            draft.owner_expr,
            draft.base_plan_index,
            draft.base_cause,
            base_phase,
        )) {
            std.debug.panic("record-update base mixed its checked-base owner lifecycle", .{});
        }
        const retirement = self.cir.expected_consumer_retirements.items.items[
            draft.retirement_index
        ];
        if (retirement.retired_node != base_raw or
            retirement.decodedOwnerKind() != .expression or
            retirement.decodedKind() != .checker_rewrite_expected or
            retirement.original_node_tag != draft.original_node_tag or
            !std.meta.eql(retirement.original_payload, draft.original_payload) or
            !pendingExpectedConsumerRetirementHasCanonicalInactiveWords(retirement) or
            draft.original_node_tag != @intFromEnum(node.tag) or
            !std.meta.eql(
                draft.original_payload,
                @as([4]u32, @bitCast(node.getPayload())),
            ))
        {
            std.debug.panic("record-update base changed its checked-base owner lifecycle", .{});
        }
        for (self.cir.expected_consumer_retirements.items.items, 0..) |other, other_index| {
            if (other_index != draft.retirement_index and
                other.decodedOwnerKind() == .expression and other.retired_node == base_raw)
            {
                std.debug.panic("record-update base had multiple retirement rows", .{});
            }
        }
        return .{
            .retirement_index = draft.retirement_index,
            .record_update_owner = draft,
        };
    }

    const selected_index: u32 = if (aggregate) |draft| blk: {
        if (draft.retirement_index >= self.cir.expected_consumer_retirements.items.items.len or
            (draft.plans_len == 0 and
                (draft.plans_start != 0 or
                    draft.retired_reason != .branch_body_error_short_circuit)) or
            (draft.plans_len != 0 and !rangeFits(
                draft.plans_start,
                draft.plans_len,
                self.cir.expected_consumption_plans.items.items.len,
            )))
        {
            std.debug.panic("record-update base aggregate lifecycle lost its plan range", .{});
        }
        const owns_call_failures =
            draft.retired_reason == .call_retired_after_operand_checked_error;
        if ((owns_call_failures and draft.plans_len < 2) or
            owns_call_failures != (annotation_count != 0) or
            (owns_call_failures and
                (annotation_producer == null or
                    annotation_producer.? != .call_operand or
                    annotation_retirement == null or
                    annotation_retirement.? != draft.retirement_index)))
        {
            std.debug.panic("record-update base aggregate lifecycle mixed failure producers", .{});
        }
        break :blk draft.retirement_index;
    } else blk: {
        const selected = annotation_retirement orelse return null;
        if (annotation_count == 0 or annotation_producer == null or
            annotation_producer.? == .call_operand)
        {
            std.debug.panic("record-update base had an incomplete ineligible retirement lifecycle", .{});
        }
        break :blk selected;
    };

    const retirement = self.cir.expected_consumer_retirements.items.items[selected_index];
    const expected_kind: ModuleEnv.ExpectedConsumerRetirement.Kind = if (aggregate) |draft|
        if (draft.plans_len == 0) .checker_rewrite_ineligible else .checker_rewrite_expected
    else
        .checker_rewrite_ineligible;
    if (retirement.retired_node != base_raw or
        retirement.decodedOwnerKind() != .expression or
        retirement.decodedKind() != expected_kind or
        retirement.original_node_tag != @intFromEnum(node.tag) or
        !std.meta.eql(
            retirement.original_payload,
            @as([4]u32, @bitCast(node.getPayload())),
        ) or !pendingExpectedConsumerRetirementHasCanonicalInactiveWords(retirement))
    {
        std.debug.panic("record-update base changed its pending retirement lifecycle", .{});
    }
    for (self.cir.expected_consumer_retirements.items.items, 0..) |other, other_index| {
        if (other_index != selected_index and
            other.decodedOwnerKind() == .expression and other.retired_node == base_raw)
        {
            std.debug.panic("record-update base had multiple retirement rows", .{});
        }
    }
    return .{
        .retirement_index = selected_index,
        .record_update_owner = null,
    };
}

/// Select the one pending lifecycle and, for a nested checked-base owner,
/// authenticate its immediate source-retirement edge without recursively
/// traversing the nested cause graph.
fn pendingExpressionRetirementAtProducer(
    self: *const Self,
    base_expr: CIR.Expr.Idx,
) ?u32 {
    const identity = pendingExpressionRetirementIdentityAtProducer(self, base_expr) orelse
        return null;
    const draft = identity.record_update_owner orelse return identity.retirement_index;
    const base_plan = self.cir.expected_consumption_plans.items.items[draft.base_plan_index];
    const source_retirement_index = base_plan.decodedSourceRetirementIndex() orelse
        std.debug.panic("record-update base owner lifecycle lost its source retirement", .{});
    if (source_retirement_index == identity.retirement_index or
        source_retirement_index >= self.cir.expected_consumer_retirements.items.items.len or
        base_plan.site_node >= self.cir.store.nodes.len())
    {
        std.debug.panic("record-update base owner lifecycle changed its immediate source", .{});
    }
    const source_retirement = self.cir.expected_consumer_retirements.items.items[
        source_retirement_index
    ];
    if (source_retirement.decodedOwnerKind() != .expression or
        source_retirement.retired_node != base_plan.site_node)
    {
        std.debug.panic("record-update base owner lifecycle changed its source owner", .{});
    }
    const source_node = self.cir.store.nodes.get(@enumFromInt(base_plan.site_node));
    if (source_node.tag == .malformed) {
        if (!expectedRecordUpdateBaseSourceRetirementIsLocallyValid(self.cir, base_plan)) {
            std.debug.panic("record-update base owner lifecycle lost its completed source", .{});
        }
    } else if (isExprNodeTag(source_node.tag)) {
        const source_identity = pendingExpressionRetirementIdentityAtProducer(
            self,
            @enumFromInt(base_plan.site_node),
        ) orelse std.debug.panic("record-update base owner lifecycle lost its pending source", .{});
        if (source_identity.retirement_index != source_retirement_index) {
            std.debug.panic("record-update base owner lifecycle changed its pending source", .{});
        }
    } else {
        std.debug.panic("record-update base owner lifecycle found an invalid source phase", .{});
    }
    return identity.retirement_index;
}

fn recordUpdateBaseCauseIsValidAtProducer(
    self: *const Self,
    base_expr: CIR.Expr.Idx,
    base_plan_index: u32,
    cause: ModuleEnv.CauseOwner,
) bool {
    const base_raw: u32 = @intFromEnum(base_expr);
    if (!cause.hasCanonicalTags(true)) return false;
    const reference = cause.decodedExpectedConsumerRetirement() orelse
        return expectedRecordUpdateBaseCauseIsLocallyValid(
            self.types,
            self.cir,
            base_raw,
            base_plan_index,
            cause,
        );
    if (reference.index >= self.cir.expected_consumer_retirements.items.items.len) {
        return false;
    }
    const retirement = self.cir.expected_consumer_retirements.items.items[reference.index];
    if (retirement.decodedOwnerKind() != .expression or
        retirement.retired_node >= self.cir.store.nodes.len())
    {
        return false;
    }
    const retirement_is_authentic = if (expectedConsumerRetirementNodeIsLocallyValid(
        self.cir,
        retirement,
    )) true else blk: {
        const pending = pendingExpressionRetirementAtProducer(
            self,
            @enumFromInt(retirement.retired_node),
        ) orelse break :blk false;
        break :blk pending == reference.index;
    };
    if (!retirement_is_authentic) return false;
    if (retirement.retired_node == base_raw) return true;
    for (self.cir.expected_consumption_plans.items.items, 0..) |_, plan_index| {
        if (plan_index == @as(usize, base_plan_index)) continue;
        if (expectedRecordUpdateCausePlanHasLiveOwnerSite(
            self.types,
            self.cir,
            @intCast(plan_index),
            base_raw,
            cause,
        )) return true;
    }
    return false;
}

fn recordUpdateBaseSourceRetirement(
    self: *Self,
    base_expr: CIR.Expr.Idx,
    plan_index: u32,
    cause: ModuleEnv.CauseOwner,
) Allocator.Error!u32 {
    const base_raw: u32 = @intFromEnum(base_expr);
    const node = self.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(base_expr));
    if (!recordUpdateBaseCauseIsValidAtProducer(
        self,
        base_expr,
        plan_index,
        cause,
    )) {
        std.debug.panic("record-update base lost its exact checked-status cause", .{});
    }
    if (node.tag == .malformed) {
        const reference = cause.decodedExpectedConsumerRetirement() orelse
            std.debug.panic("preexisting record-update base lacked its retirement cause", .{});
        if (reference.index >= self.cir.expected_consumer_retirements.items.items.len) {
            std.debug.panic("preexisting record-update base cited an absent retirement", .{});
        }
        const retirement = self.cir.expected_consumer_retirements.items.items[reference.index];
        if (retirement.decodedOwnerKind() != .expression or
            retirement.retired_node != base_raw or
            retirement.decodedKind() != .preexisting_runtime_error or
            !expectedConsumerRetirementNodeIsLocallyValid(self.cir, retirement))
        {
            std.debug.panic("record-update base changed its preexisting runtime-error authority", .{});
        }
        return reference.index;
    }
    if (pendingExpressionRetirementAtProducer(self, base_expr)) |retirement_index| {
        return retirement_index;
    }
    std.debug.panic(
        "record-update checked-error base lacked producer-authored retirement authority",
        .{},
    );
}

fn completeExpectedRecordUpdateBasePlan(
    self: *Self,
    plan_index: u32,
    produced: ExpectedMarkerAnchor,
    status: CheckedExprStatus,
    source_retirement_index: ?u32,
) void {
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    if (plan_index >= self.cir.expected_consumption_plans.items.items.len) {
        std.debug.panic("record-update base completion named an absent Expected plan", .{});
    }
    const plan = &self.cir.expected_consumption_plans.items.items[plan_index];
    if (plan.decodedRole() != .record_update_base or plan.decodedOutcome() != .reserved or
        produced.side != .destination)
    {
        std.debug.panic("record-update base completion lost its reserved producer", .{});
    }
    plan.parent_authority = ModuleEnv.ExpectedMarkerAuthority.inactive();
    plan.produced_copy_step = produced.copy_step;
    plan.produced_occurrence_offset = produced.occurrence_offset;
    plan.produced_side = @intFromEnum(produced.side);
    plan.call_root_plan_index = none;
    plan.failure_cause_plan_index = none;
    switch (status) {
        .established => {
            if (source_retirement_index != null) {
                std.debug.panic("successful record-update base named a source retirement", .{});
            }
            plan.outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.source_root_copy);
            plan.reason = none;
            plan.failure_owner = ModuleEnv.CauseOwner.inactive();
            plan.source_retirement_index_plus_one = 0;
        },
        .checked_error => |cause| {
            const retirement_index = source_retirement_index orelse
                std.debug.panic("checked-error record-update base omitted its source retirement", .{});
            if (!cause.hasCanonicalTags(true) or retirement_index == std.math.maxInt(u32)) {
                std.debug.panic("record-update base carried a noncanonical checked-error cause", .{});
            }
            plan.outcome = @intFromEnum(
                ModuleEnv.ExpectedConsumptionPlan.Outcome.source_root_copy_checked_error,
            );
            plan.reason = @intFromEnum(
                ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_base_checked_error,
            );
            plan.failure_owner = cause;
            plan.source_retirement_index_plus_one = retirement_index + 1;
        },
    }
    if (!plan.hasLegalTags()) {
        std.debug.panic("record-update base completed a noncanonical Expected plan", .{});
    }
}

const PublishedRecordUpdateBasePlan = struct {
    copy: InstantiatedVarWithMarkerCopy,
    anchor: ExpectedMarkerAnchor,
    plan_index: u32,
};

/// Atomically publish the exact Expected base plan, marker copy, and
/// checker-local registration for one already-checked record-update base.
/// The caller supplies the raw syntax occurrence and its producer-returned
/// status; this boundary never reconstructs either from the solved graph.
fn publishRecordUpdateBasePlan(
    self: *Self,
    owner_expr: CIR.Expr.Idx,
    base_expr: CIR.Expr.Idx,
    raw_request: Var,
    status: CheckedExprStatus,
    env: *Env,
) Allocator.Error!PublishedRecordUpdateBasePlan {
    if (raw_request != ModuleEnv.varFrom(base_expr)) {
        std.debug.panic("record-update base publication changed its raw syntax occurrence", .{});
    }

    var publication = try self.beginLocalMarkerCopyTransaction(env);
    defer publication.rollback();
    try self.preflightRecordUpdateExpectedPlanRegistration(
        owner_expr,
        .record_update_base,
        0,
    );
    const plan_index: u32 = @intFromEnum(try self.cir.expected_consumption_plans.append(
        self.cir.gpa,
        reservedExpectedPlan(
            owner_expr,
            base_expr,
            .record_update_base,
            0,
            raw_request,
        ),
    ));
    const copy = try self.instantiateVarWithMarkerCopy(
        raw_request,
        env,
        .use_last_var,
        .{ .record_update_base = .{
            .record_expr = @intFromEnum(owner_expr),
            .base_expr = @intFromEnum(base_expr),
        } },
        .eager_support,
    );
    const anchor = self.expectedMarkerAnchorForRoot(
        copy.copy_step orelse
            std.debug.panic("record-update base did not publish expected support", .{}),
        .destination,
    );
    const source_retirement_index: ?u32 = switch (status) {
        .established => null,
        .checked_error => |cause| try self.recordUpdateBaseSourceRetirement(
            base_expr,
            plan_index,
            cause,
        ),
    };
    self.completeExpectedRecordUpdateBasePlan(
        plan_index,
        anchor,
        status,
        source_retirement_index,
    );
    self.registerRecordUpdateExpectedPlanAssumeCapacity(.{
        .owner_expr = owner_expr,
        .plan_index = plan_index,
        .role = .record_update_base,
        .slot = 0,
        .site = base_expr,
    });
    publication.commit();
    return .{
        .copy = copy,
        .anchor = anchor,
        .plan_index = plan_index,
    };
}

fn setExpectedFreshShapeSlotsOutcome(
    self: *Self,
    slots: []const ExpectedFreshShapeSlot,
    outcome: ModuleEnv.ExpectedConsumptionPlan.Outcome,
    reason: ModuleEnv.ExpectedConsumptionPlan.Reason,
) void {
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    for (slots) |slot| {
        const plan = &self.cir.expected_consumption_plans.items.items[slot.expected_plan];
        plan.outcome = @intFromEnum(outcome);
        plan.reason = @intFromEnum(reason);
        plan.parent_authority = ModuleEnv.ExpectedMarkerAuthority.inactive();
        plan.produced_copy_step = none;
        plan.produced_occurrence_offset = none;
        plan.produced_side = none;
        plan.call_root_plan_index = none;
        plan.failure_owner = ModuleEnv.CauseOwner.inactive();
        plan.failure_cause_plan_index = none;
    }
}

fn completeExpectedFreshShapeSlots(
    self: *Self,
    slots: []const ExpectedFreshShapeSlot,
    parent: ExpectedParentAuthority,
    produced: ExpectedMarkerAnchor,
) void {
    for (slots) |slot| {
        const plan = &self.cir.expected_consumption_plans.items.items[slot.expected_plan];
        plan.outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.anchored);
        plan.reason = ModuleEnv.ExpectedConsumptionPlan.none;
        plan.parent_authority = encodeExpectedParentAuthority(parent);
        plan.produced_copy_step = produced.copy_step;
        plan.produced_occurrence_offset = produced.occurrence_offset;
        plan.produced_side = @intFromEnum(produced.side);
        plan.call_root_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
        plan.failure_owner = ModuleEnv.CauseOwner.inactive();
        plan.failure_cause_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
    }
}

fn completeExpectedFreshShapeSlotsEvidenceFree(
    self: *Self,
    slots: []const ExpectedFreshShapeSlot,
    parent: ExpectedEvidenceFreeAnchor,
) void {
    if (parent.plan_index >= self.cir.expected_consumption_plans.items.items.len) {
        std.debug.panic("fresh aggregate child lost its evidence-free parent plan", .{});
    }
    for (slots) |slot| {
        if (parent.plan_index >= slot.expected_plan) {
            std.debug.panic("fresh aggregate child did not preserve its evidence-free plan topology", .{});
        }
        const plan = &self.cir.expected_consumption_plans.items.items[slot.expected_plan];
        plan.outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.evidence_free);
        plan.reason = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Reason.parent_evidence_free);
        plan.parent_authority = .{
            .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.evidence_free_plan),
            .payload = .{ .evidence_free_plan = .{
                .plan_index = parent.plan_index,
                .raw_var = @intFromEnum(parent.raw_var),
            } },
        };
        plan.produced_copy_step = ModuleEnv.ExpectedConsumptionPlan.none;
        plan.produced_occurrence_offset = ModuleEnv.ExpectedConsumptionPlan.none;
        plan.produced_side = ModuleEnv.ExpectedConsumptionPlan.none;
        plan.call_root_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
        plan.failure_owner = ModuleEnv.CauseOwner.inactive();
        plan.failure_cause_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
    }
}

const ExpectedAggregateProjection = struct {
    const Root = union(enum) {
        copied: struct {
            copy_step: u32,
            parent_authority: ExpectedParentAuthority,
        },
        evidence_free: ExpectedEvidenceFreeAnchor,
    };

    root: Root,
    plan_range: ExpectedAggregatePlanRange,
    context: problem.Context,

    fn child(
        self: @This(),
        check: *Self,
        env: *Env,
        slots: []const ExpectedFreshShapeSlot,
        target_kind: ModuleEnv.WhereMarkerCopyWitness.EdgeKind,
        target_index: u32,
        target_name: ?u32,
        container_extension: ?ModuleEnv.WhereMarkerCopyWitness.EdgeKind,
        evidence_free_var: Var,
    ) std.mem.Allocator.Error!Expected.ExpectedType {
        if (slots.len == 0) {
            std.debug.panic("projected expected child had no exhaustive consumer plan slots", .{});
        }
        if (self.plan_range.children_start != self.plan_range.owner_plan + 1 or
            self.plan_range.children_len == 0)
        {
            std.debug.panic("projected expected child lost its aggregate owner range", .{});
        }
        for (slots) |slot| {
            if (slot.raw_fresh_var != evidence_free_var) {
                std.debug.panic("one projected expected child plan named another fresh skeleton slot", .{});
            }
            if (slot.expected_plan < self.plan_range.children_start or
                slot.expected_plan >= self.plan_range.children_start + self.plan_range.children_len)
            {
                std.debug.panic("projected expected child escaped its aggregate plan range", .{});
            }
        }
        const expected_plans_start = slots[0].expected_plan;
        for (slots, 0..) |slot, relative_index| {
            if (slot.expected_plan != expected_plans_start + @as(u32, @intCast(relative_index))) {
                std.debug.panic("fresh aggregate skeleton support plans were not one canonical gapless range", .{});
            }
        }
        const copied = switch (self.root) {
            .evidence_free => |parent| {
                check.completeExpectedFreshShapeSlotsEvidenceFree(slots, parent);
                return .{
                    .var_ = evidence_free_var,
                    .context = self.context,
                    .marker_authority = .{ .evidence_free = .{
                        .plan_index = slots[0].expected_plan,
                        .raw_var = evidence_free_var,
                    } },
                    .status = .established,
                };
            },
            .copied => |copied| copied,
        };
        const copy_step = copied.copy_step;
        const root_anchor = check.expectedMarkerAnchorForRoot(copy_step, .destination);
        if (check.expectedMarkerChildAnchorForEdge(
            root_anchor,
            target_kind,
            target_index,
            target_name,
            container_extension,
        )) |child_anchor| {
            check.completeExpectedFreshShapeSlots(
                slots,
                copied.parent_authority,
                child_anchor,
            );
            return .{
                .var_ = check.expectedMarkerAnchorRawVar(child_anchor),
                .context = self.context,
                .marker_authority = .{ .anchored = .{ .copy_occurrence = child_anchor } },
                .status = .established,
            };
        }

        const support = try check.instantiateVarOrphanWithMarkerCopy(
            evidence_free_var,
            env,
            env.rank(),
            .use_last_var,
            .{ .aggregate_fresh_shape_child = .{
                .expected_plans_start = expected_plans_start,
                .expected_plans_len = @intCast(slots.len),
                .parent_authority = encodeExpectedParentAuthority(.{ .copy_occurrence = root_anchor }),
            } },
            null,
            .eager_support,
        );
        const support_anchor = check.expectedMarkerAnchorForRoot(
            support.copy_step orelse
                std.debug.panic("fresh aggregate skeleton slot did not publish expected support", .{}),
            .destination,
        );
        if (check.expectedMarkerAnchorRawVar(support_anchor) != support.var_) {
            std.debug.panic("fresh aggregate skeleton support did not match its destination occurrence", .{});
        }
        check.completeExpectedFreshShapeSlots(
            slots,
            .{ .copy_occurrence = root_anchor },
            support_anchor,
        );
        return .{
            .var_ = support.var_,
            .context = self.context,
            .marker_authority = .{ .anchored = .{ .copy_occurrence = support_anchor } },
            .status = .established,
        };
    }
};

const ExpectedAggregateProjectionOutcome = union(enum) {
    not_projected,
    established: ExpectedAggregateProjection,
    rejected: ModuleEnv.CauseOwner,
    suppressed: ModuleEnv.CauseOwner,
};

const ExpectedRecordUpdateProjectionOutcome = union(enum) {
    established: Expected.ExpectedType,
    not_projected,
    suppressed: ModuleEnv.CauseOwner,
};

const ExpectedStoredValueRelationOutcome = union(enum) {
    established,
    rejected: ModuleEnv.CauseOwner,
    suppressed: ModuleEnv.CauseOwner,
};

/// First-settle one record-update field whose speculative Expected projection
/// was unavailable. The discarded fresh slot is not durable authority: this
/// closed outcome instead names the exact syntax-site variable and the
/// successful base plan endpoint which supplied its projection context.
fn settleRecordUpdateProjectionUnavailable(
    self: *Self,
    consumer_expr: CIR.Expr.Idx,
    base_plan_index: u32,
    slot: ExpectedFreshShapeSlot,
    provisional_raw_var: Var,
    parent: ExpectedParentAuthority,
) void {
    if (slot.expected_plan >= self.cir.expected_consumption_plans.items.items.len or
        base_plan_index >= slot.expected_plan)
    {
        std.debug.panic("unavailable record-update projection lost its plan ordering", .{});
    }
    const base_plan = self.cir.expected_consumption_plans.items.items[base_plan_index];
    const base_authority = expectedRecordUpdateBaseAuthority(base_plan) orelse
        std.debug.panic("unavailable record-update projection lost its base authority", .{});
    if (base_plan.owner_node != @intFromEnum(consumer_expr) or
        base_plan.decodedOutcome() != .source_root_copy or
        !expectedMarkerAuthoritiesEqual(base_authority, encodeExpectedParentAuthority(parent)))
    {
        std.debug.panic("unavailable record-update projection named another base endpoint", .{});
    }

    const plan = &self.cir.expected_consumption_plans.items.items[slot.expected_plan];
    if (plan.decodedOutcome() != .reserved or
        plan.owner_node != @intFromEnum(consumer_expr) or
        plan.site_node != @intFromEnum(slot.site) or
        plan.decodedRole() != .record_update_field or
        plan.slot != slot.slot or
        plan.raw_consumer_var != @intFromEnum(provisional_raw_var) or
        provisional_raw_var != slot.raw_fresh_var)
    {
        std.debug.panic("unavailable record-update projection changed its reservation", .{});
    }
    plan.raw_consumer_var = @intFromEnum(slot.site);
    settleExpectedPlanWithoutProducedEndpoint(
        plan,
        .not_projected,
        .record_update_projection_unavailable,
        base_authority,
        ModuleEnv.CauseOwner.inactive(),
        ModuleEnv.ExpectedConsumptionPlan.none,
    );
}

/// Project one supplied record-update field from the eagerly copied base.
/// Record updates have their own exact per-field plan cardinality; they never
/// borrow a literal aggregate's owner+children range.
fn projectExpectedRecordUpdateField(
    self: *Self,
    consumer_expr: CIR.Expr.Idx,
    base_plan_index: u32,
    expected: Expected.ExpectedType,
    shape_var: Var,
    slot: *ExpectedFreshShapeSlot,
    field_name: u32,
    env: *Env,
) std.mem.Allocator.Error!ExpectedRecordUpdateProjectionOutcome {
    if (slot.expected_plan != ModuleEnv.ExpectedConsumptionPlan.none or
        slot.role != .record_update_field)
    {
        std.debug.panic("record-update projection did not receive one pending field plan", .{});
    }
    var publication = try self.beginLocalMarkerCopyTransaction(env);
    defer publication.rollback();
    try self.preflightRecordUpdateExpectedPlanRegistration(
        consumer_expr,
        slot.role,
        slot.slot,
    );
    slot.* = try self.reserveExpectedFreshShapeSlot(
        consumer_expr,
        slot.site,
        slot.role,
        slot.slot,
        slot.raw_fresh_var,
    );
    const registration = RecordUpdateExpectedPlanRegistration{
        .owner_expr = consumer_expr,
        .plan_index = slot.expected_plan,
        .role = slot.role,
        .slot = slot.slot,
        .site = slot.site,
    };

    switch (expected.status) {
        .established => {},
        .checked_error => |failure| {
            const failure_cause_plan_index = switch (failure.route) {
                .direct => ModuleEnv.ExpectedConsumptionPlan.none,
                .upstream_plan => |plan_index| plan_index,
            };
            settleExpectedPlanWithoutProducedEndpoint(
                &self.cir.expected_consumption_plans.items.items[slot.expected_plan],
                .checked_error,
                .record_update_field_base_checked_error,
                expectedSourceParentAuthority(expected.marker_authority),
                failure.cause,
                failure_cause_plan_index,
            );
            if (failure_cause_plan_index != base_plan_index) {
                std.debug.panic("record-update field lost its exact upstream base plan", .{});
            }
            self.registerRecordUpdateExpectedPlanAssumeCapacity(registration);
            publication.commit();
            return .{ .suppressed = failure.cause };
        },
    }
    const parent = switch (expected.marker_authority) {
        .anchored => |authority| authority,
        .evidence_free => std.debug.panic(
            "record-update base lost its eager copy occurrence",
            .{},
        ),
    };
    if (self.expectedParentAuthorityRawVar(parent) != expected.var_) {
        std.debug.panic("record-update field did not consume its exact base endpoint", .{});
    }

    var projection = try self.beginLocalMarkerCopyTransaction(env);
    defer projection.rollback();
    const expected_copy = try self.instantiateVarOrphanFlexedWithMarkerCopy(
        expected.var_,
        env,
        .use_last_var,
        .{ .aggregate_expected_projection = .{
            .consumer_node = @intFromEnum(consumer_expr),
            .parent_authority = encodeExpectedParentAuthority(parent),
            .expected_plan_index = slot.expected_plan,
        } },
    );
    const result = try self.runUnify(
        expected_copy.var_,
        shape_var,
        env,
        unifyOptionsForContext(expected.context, .write_no_report),
    );
    switch (result) {
        .unified => {},
        .suppressed_by_error => std.debug.panic(
            "established record-update base was suppressed by unowned error evidence",
            .{},
        ),
        .problem => std.debug.panic(
            "no-report record-update projection unexpectedly published a problem",
            .{},
        ),
        .mismatch => {
            projection.rollback();
            self.settleRecordUpdateProjectionUnavailable(
                consumer_expr,
                base_plan_index,
                slot.*,
                slot.raw_fresh_var,
                parent,
            );
            self.registerRecordUpdateExpectedPlanAssumeCapacity(registration);
            publication.commit();
            return .not_projected;
        },
    }
    projection.commit();

    const copy_step = expected_copy.copy_step orelse
        std.debug.panic("record-update projection did not publish its exact copy", .{});
    const root_anchor = self.expectedMarkerAnchorForRoot(copy_step, .destination);
    var slots = [_]ExpectedFreshShapeSlot{slot.*};
    const child_anchor = self.expectedMarkerChildAnchorForEdge(
        root_anchor,
        .record_field_type,
        0,
        field_name,
        .record_extension,
    ) orelse support: {
        const support = try self.instantiateVarOrphanWithMarkerCopy(
            slot.raw_fresh_var,
            env,
            env.rank(),
            .use_last_var,
            .{ .aggregate_fresh_shape_child = .{
                .expected_plans_start = slot.expected_plan,
                .expected_plans_len = 1,
                .parent_authority = encodeExpectedParentAuthority(.{ .copy_occurrence = root_anchor }),
            } },
            null,
            .eager_support,
        );
        break :support self.expectedMarkerAnchorForRoot(
            support.copy_step orelse
                std.debug.panic("record-update fresh field did not publish support", .{}),
            .destination,
        );
    };
    const plan_parent: ExpectedParentAuthority = if (child_anchor.copy_step == copy_step)
        parent
    else
        .{ .copy_occurrence = root_anchor };
    self.completeExpectedFreshShapeSlots(&slots, plan_parent, child_anchor);
    self.registerRecordUpdateExpectedPlanAssumeCapacity(registration);
    publication.commit();
    return .{ .established = .{
        .var_ = self.expectedMarkerAnchorRawVar(child_anchor),
        .context = expected.context,
        .marker_authority = .{ .anchored = .{ .copy_occurrence = child_anchor } },
        .status = .established,
    } };
}

fn expectedTypeForAggregatePlanSlot(
    expected: Expected.ExpectedType,
    slot: ExpectedFreshShapeSlot,
) Expected.ExpectedType {
    return switch (expected.marker_authority) {
        .anchored => expected,
        .evidence_free => blk: {
            if (slot.raw_fresh_var != expected.var_) {
                std.debug.panic("evidence-free aggregate Expected plan slot did not name its shared raw child", .{});
            }
            break :blk .{
                .var_ = expected.var_,
                .context = expected.context,
                .marker_authority = .{ .evidence_free = .{
                    .plan_index = slot.expected_plan,
                    .raw_var = expected.var_,
                } },
                .status = expected.status,
            };
        },
    };
}

fn assertExpectedEvidenceFree(
    self: *Self,
    root_var: Var,
    authority: ExpectedEvidenceFreeAnchor,
) std.mem.Allocator.Error!void {
    if (authority.raw_var != root_var or
        authority.plan_index >= self.cir.expected_consumption_plans.items.items.len)
    {
        std.debug.panic("evidence-free Expected did not match its exact producer plan", .{});
    }
    const plan = self.cir.expected_consumption_plans.items.items[authority.plan_index];
    if (!plan.hasLegalTags() or
        plan.decodedOutcome() != .evidence_free or
        plan.decodedReason() != .parent_evidence_free or
        plan.raw_consumer_var != @intFromEnum(root_var) or
        plan.parent_authority.decodedKind() != .evidence_free_plan or
        plan.parent_authority.payload.evidence_free_plan.plan_index >= authority.plan_index or
        switch (plan.decodedRole().?) {
            .aggregate_owner,
            .list_element,
            .tuple_element,
            .record_field,
            .tag_payload,
            .lambda_return,
            .branch_seed,
            => false,
            .record_update_base,
            .record_update_field,
            .branch_contribution,
            .branch_final,
            .nominal_decl,
            .nominal_backing,
            .call_root,
            .call_argument,
            .default_field,
            => true,
        })
    {
        std.debug.panic("evidence-free Expected producer plan was not complete", .{});
    }
}

/// Project an aggregate's child slots from an expected type before checking
/// those children. The projection is performed against a rigids-flexed orphan
/// copy: child checking may refine the copy, while the pristine expected var
/// remains available to the expression that owns the final relation and its
/// diagnostic.
///
/// `shape_var` is a freshly-built aggregate skeleton whose child vars the
/// caller retains. A non-matching expected constructor is not itself an error
/// here; the owning relation reports that mismatch after the expression has
/// checked all of its children.
fn projectExpectedAggregateShape(
    self: *Self,
    consumer_expr: CIR.Expr.Idx,
    expected: Expected,
    shape_var: Var,
    shape_slots: []ExpectedFreshShapeSlot,
    env: *Env,
) std.mem.Allocator.Error!ExpectedAggregateProjectionOutcome {
    var publication = try self.beginLocalMarkerCopyTransaction(env);
    defer publication.rollback();
    const plan_range = try self.reserveExpectedAggregatePlans(
        consumer_expr,
        shape_var,
        shape_slots,
    );
    const aggregate_type = expected.aggregateType() orelse {
        self.settleExpectedAggregateRange(
            plan_range,
            .not_projected,
            .aggregate_no_expected,
            ModuleEnv.ExpectedMarkerAuthority.inactive(),
            ModuleEnv.CauseOwner.inactive(),
            ModuleEnv.ExpectedConsumptionPlan.none,
        );
        publication.commit();
        return .not_projected;
    };

    switch (aggregate_type.status) {
        .established => {},
        .checked_error => |failure| {
            const parent = expectedSourceParentAuthority(aggregate_type.marker_authority);
            const reason: ModuleEnv.ExpectedConsumptionPlan.Reason = switch (failure.route) {
                .direct => .aggregate_expected_direct_error,
                .upstream_plan => .aggregate_expected_contains_error,
            };
            const failure_cause_plan_index = switch (failure.route) {
                .direct => ModuleEnv.ExpectedConsumptionPlan.none,
                .upstream_plan => |plan_index| plan_index,
            };
            self.settleExpectedAggregateRange(
                plan_range,
                .checked_error,
                reason,
                parent,
                failure.cause,
                failure_cause_plan_index,
            );
            publication.commit();
            return .{ .suppressed = failure.cause };
        },
    }

    // The copy and speculative shape relation are one nested suffix under the
    // owner/child-plan transaction. A rejected relation rolls this suffix
    // back before the same-node retirement is authored, so no failed copy step
    // or witness can survive as authority for the rejection.
    var projection = try self.beginLocalMarkerCopyTransaction(env);
    defer projection.rollback();

    const expected_copy: InstantiatedVarWithMarkerCopy = switch (aggregate_type.marker_authority) {
        .anchored => |parent_authority| blk: {
            if (self.expectedParentAuthorityRawVar(parent_authority) != aggregate_type.var_) {
                std.debug.panic("aggregate expectation did not equal its exact parent endpoint", .{});
            }
            break :blk try self.instantiateVarOrphanFlexedWithMarkerCopy(
                aggregate_type.var_,
                env,
                .use_last_var,
                .{ .aggregate_expected_projection = .{
                    .consumer_node = @intFromEnum(consumer_expr),
                    .parent_authority = encodeExpectedParentAuthority(parent_authority),
                    .expected_plan_index = plan_range.owner_plan,
                } },
            );
        },
        .evidence_free => |producer| blk: {
            try self.assertExpectedEvidenceFree(aggregate_type.var_, producer);
            break :blk .{
                .var_ = try self.instantiateVarOrphanFlexed(
                    aggregate_type.var_,
                    env,
                    .use_last_var,
                ),
                .copy_step = null,
            };
        },
    };

    const result = try self.runUnify(
        expected_copy.var_,
        shape_var,
        env,
        unifyOptionsForContext(aggregate_type.context, .write_no_report),
    );
    switch (result) {
        .unified => {},
        .suppressed_by_error => std.debug.panic(
            "established aggregate Expected was suppressed by unowned error evidence",
            .{},
        ),
        .problem => std.debug.panic(
            "no-report aggregate projection unexpectedly published a problem",
            .{},
        ),
        .mismatch => {
            projection.rollback();
            const cause = try self.reserveExpectedPlanRetirement(
                consumer_expr,
                plan_range.owner_plan,
                plan_range.children_len + 1,
                .aggregate_shape_mismatch,
            );
            self.settleExpectedAggregateRange(
                plan_range,
                .checked_error,
                .aggregate_shape_mismatch,
                expectedSourceParentAuthority(aggregate_type.marker_authority),
                cause,
                ModuleEnv.ExpectedConsumptionPlan.none,
            );
            publication.commit();
            return .{ .rejected = cause };
        },
    }
    projection.commit();

    const root: ExpectedAggregateProjection.Root = switch (aggregate_type.marker_authority) {
        .anchored => |parent_authority| copied: {
            const copy_step = expected_copy.copy_step orelse
                std.debug.panic("anchored aggregate projection did not publish its eager copy", .{});
            const root_anchor = self.expectedMarkerAnchorForRoot(copy_step, .destination);
            self.completeExpectedAggregateOwnerAnchored(
                plan_range,
                parent_authority,
                root_anchor,
            );
            break :copied .{ .copied = .{
                .copy_step = copy_step,
                .parent_authority = parent_authority,
            } };
        },
        .evidence_free => |parent| evidence_free: {
            self.completeExpectedAggregateOwnerEvidenceFree(plan_range, parent);
            break :evidence_free .{ .evidence_free = parent };
        },
    };
    publication.commit();
    return .{ .established = .{
        .root = root,
        .plan_range = plan_range,
        .context = aggregate_type.context,
    } };
}

/// Commit one exact aggregate-child relation and settle that child's already
/// reserved plan. Suppression is driven only by the child checker's typed
/// status. A rejected relation publishes its immutable subject/peer pair and
/// returns that exact producer cause; no solved `.err` inspection participates.
fn commitProjectedStoredValue(
    self: *Self,
    expected: Expected.ExpectedType,
    expected_plan_index: u32,
    plan_range: ExpectedAggregatePlanRange,
    actual: Var,
    actual_status: CheckedExprStatus,
    env: *Env,
) std.mem.Allocator.Error!ExpectedStoredValueRelationOutcome {
    if (expected_plan_index >= self.cir.expected_consumption_plans.items.items.len or
        expected_plan_index < plan_range.children_start or
        expected_plan_index >= plan_range.children_start + plan_range.children_len or
        plan_range.children_start != plan_range.owner_plan + 1)
    {
        std.debug.panic("projected aggregate child named an absent Expected plan", .{});
    }
    const plan_before = self.cir.expected_consumption_plans.items.items[expected_plan_index];
    const plan_expected_raw: ?u32 = switch (plan_before.decodedOutcome() orelse .reserved) {
        .anchored => if (plan_before.decodedProducedSide() == .destination)
            @intFromEnum(self.expectedMarkerAnchorRawVar(.{
                .copy_step = plan_before.produced_copy_step,
                .occurrence_offset = plan_before.produced_occurrence_offset,
                .side = .destination,
            }))
        else
            null,
        .evidence_free => plan_before.raw_consumer_var,
        .related,
        .source_root_copy,
        .source_root_copy_checked_error,
        .producer_root,
        .retained,
        .not_projected,
        .checked_error,
        .reserved,
        => null,
    };
    if (!plan_before.hasLegalTags() or
        plan_expected_raw != @intFromEnum(expected.var_) or
        switch (plan_before.decodedRole().?) {
            .list_element, .tuple_element, .record_field, .tag_payload => false,
            .aggregate_owner,
            .record_update_base,
            .record_update_field,
            .branch_seed,
            .branch_contribution,
            .branch_final,
            .nominal_decl,
            .nominal_backing,
            .call_root,
            .call_argument,
            .default_field,
            .lambda_return,
            => true,
        })
    {
        std.debug.panic("projected aggregate child did not own its exact consumer plan", .{});
    }

    switch (actual_status) {
        .established => {},
        .checked_error => |cause| {
            if (!cause.hasCanonicalTags(true)) {
                std.debug.panic("projected aggregate child carried a noncanonical checked-error cause", .{});
            }
            var publication = try self.beginLocalMarkerCopyTransaction(env);
            defer publication.rollback();
            const plan = &self.cir.expected_consumption_plans.items.items[expected_plan_index];
            if (!plan.hasLegalTags() or plan.raw_consumer_var != @intFromEnum(expected.var_)) {
                std.debug.panic("projected aggregate child suppression changed its producer plan", .{});
            }
            const parent_authority = plan.parent_authority;
            plan.outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error);
            plan.reason = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Reason.aggregate_child_relation_suppressed);
            plan.produced_copy_step = ModuleEnv.ExpectedConsumptionPlan.none;
            plan.produced_occurrence_offset = ModuleEnv.ExpectedConsumptionPlan.none;
            plan.produced_side = ModuleEnv.ExpectedConsumptionPlan.none;
            plan.call_root_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
            plan.failure_owner = cause;
            plan.failure_cause_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
            plan.parent_authority = parent_authority;
            if (!plan.hasLegalTags()) {
                std.debug.panic("projected aggregate child suppression produced a noncanonical plan", .{});
            }
            _ = try self.reserveExpectedPlanRetirement(
                @enumFromInt(plan.owner_node),
                plan_range.owner_plan,
                plan_range.children_len + 1,
                .aggregate_retired_after_child_relation,
            );
            publication.commit();
            return .{ .suppressed = cause };
        },
    }

    var commit_probe = try self.beginCommitProbe(env);
    var probe_closed = false;
    defer if (!probe_closed) commit_probe.rollback();
    const result = try commit_probe.unify(expected.var_, actual);
    switch (result) {
        .unified => {
            probe_closed = true;
            commit_probe.commit();
            return .established;
        },
        .suppressed_by_error => std.debug.panic(
            "established projected aggregate child was suppressed without producer error status",
            .{},
        ),
        .problem, .mismatch => {},
    }
    commit_probe.rollback();
    probe_closed = true;

    var publication = try self.beginLocalMarkerCopyTransaction(env);
    defer publication.rollback();
    const plan = &self.cir.expected_consumption_plans.items.items[expected_plan_index];
    if (!plan.hasLegalTags() or plan.raw_consumer_var != @intFromEnum(expected.var_)) {
        std.debug.panic("projected aggregate child rejection changed its producer plan", .{});
    }
    const failure_index: u32 = @intCast(self.cir.expected_failures.items.items.len);
    const failure = ModuleEnv.ExpectedFailure{
        .owner_node = plan.owner_node,
        .site_node = plan.site_node,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.aggregate_child_relation_rejected),
        .raw_owner_var = @intFromEnum(ModuleEnv.varFrom(
            @as(CIR.Expr.Idx, @enumFromInt(plan.owner_node)),
        )),
        .raw_subject_var = @intFromEnum(expected.var_),
        .raw_peer_var = @intFromEnum(actual),
        .constraint_index = ModuleEnv.ExpectedFailure.none,
        .slot = plan.slot,
        .plan_index = expected_plan_index,
        .subject_authority = expectedFailureSubjectAuthority(expected.marker_authority),
        .cause_owner = ModuleEnv.CauseOwner.inactive(),
    };
    if (!failure.hasLegalTagsAt(failure_index)) {
        std.debug.panic("projected aggregate child rejection produced a noncanonical failure", .{});
    }
    _ = try self.cir.expected_failures.append(self.cir.gpa, failure);
    const cause = ModuleEnv.CauseOwner.expectedFailure(failure_index);
    const parent_authority = plan.parent_authority;
    plan.outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error);
    plan.reason = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Reason.aggregate_child_relation_rejected);
    plan.produced_copy_step = ModuleEnv.ExpectedConsumptionPlan.none;
    plan.produced_occurrence_offset = ModuleEnv.ExpectedConsumptionPlan.none;
    plan.produced_side = ModuleEnv.ExpectedConsumptionPlan.none;
    plan.call_root_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
    plan.failure_owner = cause;
    plan.failure_cause_plan_index = ModuleEnv.ExpectedConsumptionPlan.none;
    plan.parent_authority = parent_authority;
    if (!plan.hasLegalTags()) {
        std.debug.panic("projected aggregate child rejection produced a noncanonical plan", .{});
    }
    _ = try self.reserveExpectedPlanRetirement(
        @enumFromInt(plan.owner_node),
        plan_range.owner_plan,
        plan_range.children_len + 1,
        .aggregate_retired_after_child_relation,
    );
    publication.commit();
    return .{ .rejected = cause };
}

const ExprCheckFrame = struct {
    checker: *Self,
    env: *Env,
    expr_idx: CIR.Expr.Idx,
    expr: CIR.Expr,
    expr_region: Region,
    expr_var_raw: Var,
    expr_var: Var,
    mb_anno_vars: ?AnnoVars,
    annotation_idx: ?CIR.Annotation.Idx,
    nested_expected: Expected,
    is_call_arg: bool,
    is_immediate_callee: bool,
    immediate_call_root_token: ?u32,
    is_binding_rhs: bool,
    previous_instantiation_source: ?CIR.Expr.Idx,
    previous_instantiation_is_immediate_callee: bool,
    previous_immediate_call_root_token: ?u32,
    previous_discarded_binding_rhs_expr: ?CIR.Expr.Idx,
    previous_active_scheme_root: ?Var,
    direct_formal_failure_sources_start: usize,
    owns_direct_formal_failure_sources: bool,
    suppress_group_member_generalize: bool,
    should_generalize: bool,
    rank_pushed: bool,
    hoist_frame: ?HoistFrameGuard,
    checked_status: CheckedExprStatus = .established,
    callee_instantiation: ?CalleeInstantiationAuthority = null,
    active: bool = true,

    fn deinit(self: *ExprCheckFrame) void {
        if (!self.active) return;

        if (self.hoist_frame) |*hoist_frame| {
            hoist_frame.deinit();
        }
        if (self.rank_pushed) {
            self.env.var_pool.popRank();
        }
        self.checker.active_scheme_root = self.previous_active_scheme_root;
        if (self.owns_direct_formal_failure_sources) {
            self.checker.direct_formal_failure_sources.shrinkRetainingCapacity(
                self.direct_formal_failure_sources_start,
            );
        }
        self.checker.discarded_binding_rhs_expr = self.previous_discarded_binding_rhs_expr;
        self.checker.instantiation_is_immediate_callee = self.previous_instantiation_is_immediate_callee;
        self.checker.checking_immediate_call_root_token = self.previous_immediate_call_root_token;
        self.checker.instantiation_source_expr = self.previous_instantiation_source;
        self.checker.checking_binding_rhs_pattern = null;
        self.active = false;
    }

    fn finish(self: *ExprCheckFrame, does_fx: bool) std.mem.Allocator.Error!CheckedExprOutcome {
        const checker = self.checker;
        const env = self.env;

        // Typed producer authority, not a solved `.err` scan, makes the final
        // executable rewrite mandatory. The central rewrite consumes the
        // exact pending retirement and supplies its final diagnostic.
        switch (self.checked_status) {
            .established => {},
            .checked_error => |cause| {
                if (!cause.hasCanonicalTags(true)) {
                    std.debug.panic("expression frame carried a noncanonical checked-error cause", .{});
                }
                try checker.erroneous_value_exprs.put(checker.gpa, self.expr_idx, {});
            },
        }

        // Check if we have an annotation
        if (self.mb_anno_vars) |anno_vars| {
            // Unify the anno with the expr var
            const annotation_result = try checker.unifyInContext(anno_vars.anno_var, self.expr_var, env, anno_vars.context);
            if (annotation_result.isProblem()) {
                // The diagnostic belongs to checking, but later stages need an
                // explicit executable value. End-of-check poisoning replaces this
                // expression with a runtime error while the binding retains the
                // annotation's checked type for all independent consumers.
                try checker.erroneous_value_exprs.put(checker.gpa, self.expr_idx, {});
            }

            // Check if the expression type contains any errors anywhere in its
            // structure. If it does and we have an annotation, use the annotation
            // type for the pattern instead of the expression type. This preserves
            // the annotation type for other code that references this identifier,
            // even when the expression has errors.
            checker.var_set.clearRetainingCapacity();
            if (try checker.varContainsError(self.expr_var, &checker.var_set)) {
                // A method's callable wrapper is explicit input to method-template
                // publication, so keep that wrapper around its already-erroneous
                // child. Other annotated values are the executable boundary and
                // must themselves become the runtime error.
                const is_method_callable = isFunctionDef(&checker.cir.store, checker.cir.store.getExpr(self.expr_idx)) and
                    checker.exprDefinesMethod(self.expr_idx);
                if (!is_method_callable) {
                    try checker.erroneous_value_exprs.put(checker.gpa, self.expr_idx, {});
                }
                // If there was an annotation AND the expr contains errors, then unify the
                // raw expr var against the annotation
                _ = try checker.unify(self.expr_var_raw, anno_vars.anno_var_backup, env);
            } else {
                // Otherwise, make the explicit annotation the checked root for
                // this expression. The body has already constrained the
                // annotation's backing and any underscore variables above.
                _ = try checker.unify(self.expr_var_raw, anno_vars.anno_var, env);
            }
        }

        checker.var_set.clearRetainingCapacity();
        if (self.mb_anno_vars == null) {
            if (try checker.varContainsError(self.expr_var, &checker.var_set)) {
                try checker.erroneous_value_exprs.put(checker.gpa, self.expr_idx, {});
                checker.call_operand_type_error_exprs.items[nodeSlot(self.expr_idx)] = true;
            }
        }

        // Check any accumulated static dispatch constraints
        try checker.checkStaticDispatchConstraints(env, false);

        // If this type of expr should be generalized, generalize it!
        if (self.should_generalize) {
            // Bind pending record-destructure binders BEFORE boundary literal
            // defaulting: a numeral flowing through a destructured field only
            // becomes signature-reachable once the binder is unified through
            // the row, and defaulting's reachability classification must see
            // that link (see `judgeRecordDestructBinds`).
            try checker.judgeRecordDestructBinds(env);
            const is_group_boundary = env.rank() == checker.currentGroupBoundaryRank();
            if (is_group_boundary) {
                // This frame is the enclosing group's generalization boundary (a
                // singleton group's def RHS). Resolve dispatch obligations into
                // unchecked groups before anything here generalizes (Invariant D),
                // interleaved with boundary defaulting.
                try checker.runGroupBoundary(&.{.{ .owner = self.expr_var_raw, .interface = self.expr_var }}, env);
            } else {
                // Inner lambda: boundary defaulting runs first—it must see
                // ranks BEFORE they are promoted to generalized. Pending dispatch
                // obligations (pinned at the group's boundary rank) escape this
                // frame and stay live for the group boundary.
                try checker.defaultLiteralsAtGeneralizationBoundary(.{ .owner = self.expr_var_raw, .interface = self.expr_var }, env);
            }
            try checker.judgeFieldKindsAtBoundary(env);
            if (self.annotation_idx) |annotation_idx| {
                try checker.finalizeWhereMethodWideningForAnnotation(annotation_idx);
            }
            try checker.generalizer.generalize(checker.gpa, &env.var_pool, env.rank());
            try checker.flushGeneralizedTargetSharesAtBoundary(&.{.{
                .owner = self.expr_var_raw,
                .interface = self.expr_var,
            }}, null);
            try checker.deduplicateGeneralizedDispatchRequirements(self.expr_var_raw);
            try checker.publishBindingScheme(self.expr_var_raw);
            checker.retireNonGeneralizedTypeSchemes(&.{.{ .owner = self.expr_var_raw, .interface = self.expr_var }});
            try checker.retireStructurallyPublishedTypeSchemeRequirements(
                &.{.{ .owner = self.expr_var_raw, .interface = self.expr_var }},
                env.rank(),
            );
            // The scheme's vars froze at generalized rank: judge this def's
            // dispatch-constrained receivers now, while the judgment is a
            // local question about one scheme (see
            // `judgeAmbiguityCandidatesAtGeneralization`).
            try checker.judgeAmbiguityCandidatesAtGeneralization(.{ .owner = self.expr_var_raw, .interface = self.expr_var });
        }

        try self.hoist_frame.?.finish(does_fx);
        const checked_status = self.checked_status;
        const callee_instantiation = self.callee_instantiation;
        if (callee_instantiation != null and self.immediate_call_root_token == null) {
            std.debug.panic("a non-call expression frame attempted to publish callee instantiation authority", .{});
        }
        self.deinit();
        return .{
            .does_fx = does_fx,
            .status = checked_status,
            .callee_instantiation = callee_instantiation,
        };
    }
};

fn beginExprCheckFrame(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    env: *Env,
    expected: Expected,
) std.mem.Allocator.Error!ExprCheckFrame {
    const expr = self.cir.store.getExpr(expr_idx);
    const expr_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(expr_idx));
    const expr_var_raw = ModuleEnv.varFrom(expr_idx);
    const previous_instantiation_source = self.instantiation_source_expr;
    const previous_instantiation_is_immediate_callee = self.instantiation_is_immediate_callee;
    const previous_immediate_call_root_token = self.checking_immediate_call_root_token;
    const previous_discarded_binding_rhs_expr = self.discarded_binding_rhs_expr;
    const previous_active_scheme_root = self.active_scheme_root;

    var frame = ExprCheckFrame{
        .checker = self,
        .env = env,
        .expr_idx = expr_idx,
        .expr = expr,
        .expr_region = expr_region,
        .expr_var_raw = expr_var_raw,
        .expr_var = undefined,
        .mb_anno_vars = null,
        .annotation_idx = expected.annotation,
        .nested_expected = expected,
        .is_call_arg = false,
        .is_immediate_callee = false,
        .immediate_call_root_token = null,
        .is_binding_rhs = false,
        .previous_instantiation_source = previous_instantiation_source,
        .previous_instantiation_is_immediate_callee = previous_instantiation_is_immediate_callee,
        .previous_immediate_call_root_token = previous_immediate_call_root_token,
        .previous_discarded_binding_rhs_expr = previous_discarded_binding_rhs_expr,
        .previous_active_scheme_root = previous_active_scheme_root,
        .direct_formal_failure_sources_start = self.direct_formal_failure_sources.items.len,
        .owns_direct_formal_failure_sources = false,
        .suppress_group_member_generalize = false,
        .should_generalize = false,
        .rank_pushed = false,
        .hoist_frame = null,
    };
    errdefer frame.deinit();

    // Attribute any dispatcher instantiated while checking this expression to it,
    // so an ambiguity verdict can pinpoint the source of an unsatisfiable
    // body-forced where-clause. Restored on exit to track the innermost expr.
    self.instantiation_source_expr = expr_idx;

    // Expression nodes can be checked again after more constraints settle. The
    // dense slot always describes this check, so a prior error cannot retire a
    // parent after the expression has checked successfully.
    self.call_operand_type_error_exprs.items[nodeSlot(expr_idx)] = false;

    // Consume the call-position flags. Value-producing wrappers explicitly
    // forward them only to the child that supplies their result.
    frame.is_call_arg = self.checking_call_arg;
    self.checking_call_arg = false;
    frame.is_immediate_callee = self.checking_immediate_callee;
    self.checking_immediate_callee = false;
    frame.immediate_call_root_token = self.checking_immediate_call_root_token;
    self.checking_immediate_call_root_token = null;
    if (frame.immediate_call_root_token != null and !frame.is_immediate_callee) {
        std.debug.panic("call-root token entered a non-callee expression frame", .{});
    }
    self.instantiation_is_immediate_callee = frame.is_immediate_callee;

    // Consume the binding-RHS flag: it applies only to this expression.
    frame.is_binding_rhs = self.checking_binding_rhs;
    const binding_rhs_pattern = self.checking_binding_rhs_pattern;
    self.checking_binding_rhs = false;
    self.checking_binding_rhs_pattern = null;
    if (frame.is_binding_rhs) {
        if (binding_rhs_pattern) |pattern_idx| {
            if (self.cir.store.getPattern(pattern_idx) == .underscore) {
                self.discarded_binding_rhs_expr = expr_idx;
            }
        }
    }

    // A recursive group member's top-level RHS lives in the group's shared
    // rank frame and generalizes at the group boundary, not on its own.
    frame.suppress_group_member_generalize = self.suppress_generalize_expr == expr_idx;
    if (frame.suppress_group_member_generalize) self.suppress_generalize_expr = null;

    frame.should_generalize = !frame.suppress_group_member_generalize and
        self.shouldGeneralize(expr, expected.annotation, frame.is_binding_rhs, frame.is_call_arg);
    if (frame.should_generalize) self.active_scheme_root = expr_var_raw;

    if (frame.should_generalize) {
        try env.var_pool.pushRank();
        frame.rank_pushed = true;
    }

    try self.setVarRank(expr_var_raw, env);

    // Materialize an annotation once at the expression frame that owns it.
    frame.expr_var, frame.mb_anno_vars, frame.nested_expected = blk: {
        if (expr == .e_closure) {
            const forwarded_expected = if (expected.annotation != null)
                expected.withForwardedAnnotationOwner(expr_idx)
            else
                expected;
            break :blk .{ expr_var_raw, null, forwarded_expected };
        }

        if (expected.annotation) |annotation_idx| {
            const annotation_attachment = expected.annotation_attachment orelse
                std.debug.panic("Expected carried an annotation without its exact binding attachment", .{});
            const annotation_owner_expr = expected.annotation_owner_expr orelse expr_idx;
            const failure_publication: AnnotationFailurePublicationMode = publication: {
                const owner = self.cir.store.getExpr(annotation_owner_expr);
                if (owner == .e_runtime_error) {
                    const baseline_cause = try self.preexistingRuntimeErrorCause(
                        annotation_owner_expr,
                        owner.e_runtime_error.diagnostic,
                    );
                    break :publication .{ .preexisting_runtime_error_owner = .{
                        .owner_expr = annotation_owner_expr,
                        .attachment = annotation_attachment,
                        .cause_owner = baseline_cause,
                    } };
                }
                break :publication .{ .body_expression = .{
                    .owner_expr = annotation_owner_expr,
                    .attachment = annotation_attachment,
                } };
            };
            frame.direct_formal_failure_sources_start = self.direct_formal_failure_sources.items.len;
            frame.owns_direct_formal_failure_sources = true;
            const annotation_generation = try self.generateAnnotationType(
                annotation_idx,
                env,
                failure_publication,
            );
            switch (annotation_generation) {
                .established => {},
                .checked_error => |failure| {
                    if (failure.cause_owner.decodedExpectedConsumerRetirement() == null) {
                        std.debug.panic("body annotation failure did not reserve its owner retirement", .{});
                    }
                    frame.checked_status = .{ .checked_error = failure.cause_owner };
                },
                .suppressed => |cause| {
                    const suppression = switch (failure_publication) {
                        .preexisting_runtime_error_owner => |owner| owner,
                        .body_expression, .no_publication => std.debug.panic(
                            "body annotation suppressed without a preexisting runtime-error owner",
                            .{},
                        ),
                    };
                    if (!expectedCauseOwnersEqual(suppression.cause_owner, cause)) {
                        std.debug.panic("body annotation changed its preexisting suppression cause", .{});
                    }
                    self.validatePreexistingRuntimeErrorAnnotationSuppression(
                        suppression.owner_expr,
                        cause,
                    );
                    frame.checked_status = .{ .checked_error = cause };
                },
            }
            const anno_var = ModuleEnv.varFrom(annotation_idx);
            const anno_copy = try self.instantiateVarOrphanWithMarkerCopy(
                anno_var,
                env,
                env.rank(),
                .use_last_var,
                .{ .type_annotation = .{ .node = @intFromEnum(annotation_idx) } },
                null,
                .eager_support,
            );
            const annotation_anchor = self.expectedMarkerAnchorForRoot(
                anno_copy.copy_step orelse
                    std.debug.panic("materialized annotation did not publish its expected anchor", .{}),
                .source,
            );
            const annotation_expected: Expected.ExpectedType = .{
                .var_ = anno_var,
                .context = .type_annotation,
                .marker_authority = .{ .anchored = .{ .copy_occurrence = annotation_anchor } },
                .status = switch (frame.checked_status) {
                    .established => .established,
                    .checked_error => |cause| .{ .checked_error = .{
                        .cause = cause,
                        .route = .direct,
                    } },
                },
            };
            break :blk .{
                try self.fresh(env, expr_region),
                AnnoVars{
                    .anno_var = anno_var,
                    .anno_var_backup = anno_copy.var_,
                    .context = .type_annotation,
                },
                expected.withMaterializedAnnotation(annotation_expected).withBranchResult(annotation_expected),
            };
        } else if (expected.expected_type) |expected_type| {
            const expected_var_backup = switch (expected_type.marker_authority) {
                .anchored => |authority| anchored: {
                    if (self.expectedParentAuthorityRawVar(authority) != expected_type.var_) {
                        std.debug.panic("expected type did not equal its authenticated occurrence endpoint", .{});
                    }
                    break :anchored switch (authority) {
                        .copy_occurrence => |anchor| self.expectedMarkerAnchorOppositeRawVar(anchor),
                        .producer_root => std.debug.panic(
                            "a producer-root Expected entered the copy-occurrence backup channel",
                            .{},
                        ),
                        .evidence_free_plan => std.debug.panic(
                            "an evidence-free Expected parent entered the generic backup channel",
                            .{},
                        ),
                        .relation_plan => std.debug.panic(
                            "a branch relation-plan Expected entered the generic backup channel",
                            .{},
                        ),
                    };
                },
                .evidence_free => std.debug.panic(
                    "evidence-free Expected entered the generic expression-frame backup channel",
                    .{},
                ),
            };
            break :blk .{
                try self.fresh(env, expr_region),
                AnnoVars{
                    .anno_var = expected_type.var_,
                    .anno_var_backup = expected_var_backup,
                    .context = expected_type.context,
                },
                expected.withBranchResult(expected_type),
            };
        } else {
            break :blk .{ expr_var_raw, null, expected };
        }
    };

    self.checking_binding_rhs_pattern = binding_rhs_pattern;
    frame.hoist_frame = try self.beginHoistFrame(expr_idx, frame.is_binding_rhs, frame.nested_expected.hoist_position);
    self.checking_binding_rhs_pattern = null;

    return frame;
}

fn checkExpr(self: *Self, expr_idx: CIR.Expr.Idx, env: *Env, expected: Expected) std.mem.Allocator.Error!CheckedExprOutcome {
    const trace = tracy.trace(@src());
    defer trace.end();

    var frame = try self.beginExprCheckFrame(expr_idx, env, expected);
    defer frame.deinit();

    const child_expected = frame.nested_expected.forStatement();

    // These noinline per-kind helpers are an intentional recursive-stack
    // boundary. Keep frame begin/finish here and do not inline the arm bodies
    // back into this wrapper, or recursive checks regain the combined frame.
    const does_fx = switch (frame.expr) {
        .e_str_segment => try self.checkExprStrSegment(&frame),
        .e_bytes_literal => try self.checkExprBytesLiteral(&frame),
        .e_str => |str| try self.checkExprStr(&frame, str, child_expected),
        .e_num => |num| try self.checkExprNum(&frame, num),
        .e_num_from_numeral => try self.checkExprNumFromNumeral(&frame),
        .e_frac_f32 => |frac| try self.checkExprFracF32(&frame, frac),
        .e_frac_f64 => |frac| try self.checkExprFracF64(&frame, frac),
        .e_dec => |frac| try self.checkExprDec(&frame, frac),
        .e_dec_small => |frac| try self.checkExprDecSmall(&frame, frac),
        .e_typed_int => try self.checkExprTypedInt(&frame),
        .e_typed_frac => try self.checkExprTypedFrac(&frame),
        .e_typed_num_from_numeral => try self.checkExprTypedNumFromNumeral(&frame),
        .e_empty_list => try self.checkExprEmptyList(&frame),
        .e_list => |list| try self.checkExprList(&frame, list, child_expected),
        .e_tuple => |tuple| try self.checkExprTuple(&frame, tuple, child_expected),
        .e_tuple_access => |tuple_access| try self.checkExprTupleAccess(&frame, tuple_access, child_expected),
        .e_record => |e| try self.checkExprRecord(&frame, e, child_expected),
        .e_empty_record => try self.checkExprEmptyRecord(&frame),
        .e_zero_argument_tag => |e| try self.checkExprZeroArgumentTag(&frame, e),
        .e_tag => |e| try self.checkExprTag(&frame, e, child_expected),
        .e_nominal => |nominal| try self.checkExprNominal(&frame, nominal, child_expected),
        .e_nominal_external => |nominal| try self.checkExprNominalExternal(&frame, nominal, child_expected),
        .e_lookup_local => |lookup| try self.checkExprLookupLocal(&frame, lookup, expected),
        .e_lookup_external => |ext| try self.checkExprLookupExternal(&frame, ext),
        .e_lookup_associated_local => |lookup| try self.checkExprLookupAssociatedLocal(&frame, lookup),
        .e_lookup_associated => |lookup| try self.checkExprLookupAssociated(&frame, lookup),
        .e_lookup_associated_resolved => |lookup| try self.checkExprLookupAssociatedResolved(&frame, lookup),
        .e_lookup_required => |req| try self.checkExprLookupRequired(&frame, req),
        .e_block => |block| try self.checkExprBlock(&frame, block),
        .e_lambda => |lambda| try self.checkExprLambda(&frame, lambda),
        .e_closure => |closure| try self.checkExprClosure(&frame, closure),
        .e_call => |call| try self.checkExprCall(&frame, call, child_expected),
        .e_if => |if_expr| try self.checkExprIf(&frame, if_expr),
        .e_match => |match| try self.checkExprMatch(&frame, match),
        .e_binop => |binop| try self.checkExprBinop(&frame, binop),
        .e_unary_minus => |unary| try self.checkExprUnaryMinus(&frame, unary),
        .e_unary_not => |unary| try self.checkExprUnaryNot(&frame, unary),
        .e_field_access => |field_access| try self.checkExprFieldAccess(&frame, field_access, child_expected),
        .e_interpolation => |interpolation| try self.checkExprInterpolation(&frame, interpolation, child_expected),
        .e_method_call => |method_call| try self.checkExprMethodCall(&frame, method_call, child_expected),
        .e_dispatch_call => |method_call| try self.checkExprDispatchCall(&frame, method_call, child_expected),
        .e_structural_eq => |eq| try self.checkExprStructuralEq(&frame, eq, child_expected),
        .e_structural_hash => |h| try self.checkExprStructuralHash(&frame, h, child_expected),
        .e_method_eq => |eq| try self.checkExprMethodEq(&frame, eq, child_expected),
        .e_type_method_call => |method_call| try self.checkExprTypeMethodCall(&frame, method_call, child_expected),
        .e_type_dispatch_call => |method_call| try self.checkExprTypeDispatchCall(&frame, method_call, child_expected),
        .e_crash => try self.checkExprCrash(&frame),
        .e_expect_err => |expect_err| try self.checkExprExpectErr(&frame, expect_err, child_expected),
        .e_dbg => |dbg| try self.checkExprDbg(&frame, dbg, child_expected),
        .e_expect => |expect| try self.checkExprExpect(&frame, expect, child_expected),
        .e_for => |for_expr| try self.checkExprFor(&frame, for_expr),
        .e_ellipsis => try self.checkExprEllipsis(&frame),
        .e_anno_only => |anno| try self.checkExprAnnoOnly(&frame, anno, expected),
        .e_derived_method => try self.checkExprDerivedMethod(&frame),
        .e_return => |ret| try self.checkExprReturn(&frame, ret),
        .e_break => try self.checkExprBreak(&frame),
        .e_hosted_lambda => |lambda| try self.checkExprHostedLambda(&frame, lambda, expected),
        .e_run_low_level => |run_ll| try self.checkExprRunLowLevel(&frame, run_ll, child_expected),
        .e_runtime_error => |runtime_error| try self.checkExprRuntimeError(&frame, runtime_error),
    };

    return frame.finish(does_fx);
}

noinline fn checkExprStrSegment(
    self: *Self,
    frame: *ExprCheckFrame,
) std.mem.Allocator.Error!bool {
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;

    const str_var = try self.freshStr(env, expr_region);
    _ = try self.unify(expr_var, str_var, env);
    return false;
}

noinline fn checkExprBytesLiteral(
    self: *Self,
    frame: *ExprCheckFrame,
) std.mem.Allocator.Error!bool {
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;

    // Create List(U8) type
    const u8_content = try self.mkNumberTypeContent(.u8);
    const u8_var = try self.freshFromContent(u8_content, env, expr_region);
    const list_content = try self.mkListContent(u8_var);
    try self.unifyWith(expr_var, list_content, env);
    return false;
}

noinline fn checkExprStr(
    self: *Self,
    frame: *ExprCheckFrame,
    str: @FieldType(CIR.Expr, "e_str"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    var does_fx = false;

    // Iterate over the string segments, checking each one
    const segment_expr_idx_slice = self.cir.store.sliceExpr(str.span);
    var did_err = false;
    var has_interpolation = false;
    for (segment_expr_idx_slice) |seg_expr_idx| {
        const seg_expr = self.cir.store.getExpr(seg_expr_idx);

        // String literal segments are already Str type
        if (seg_expr == .e_str_segment) {
            does_fx = (try self.checkExpr(seg_expr_idx, env, child_expected)).does_fx or does_fx;
        } else {
            has_interpolation = true;
            does_fx = (try self.checkExpr(seg_expr_idx, env, child_expected)).does_fx or does_fx;
            const seg_var = ModuleEnv.varFrom(seg_expr_idx);

            // Interpolated expressions must be of type Str
            const seg_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(seg_expr_idx));
            const expected_str_var = try self.freshStr(env, seg_region);

            const unify_result = try self.unify(expected_str_var, seg_var, env);
            if (!unify_result.isAccepted()) {
                // Unification failed - mark as error
                try self.markErroneous(seg_var);
                did_err = true;
            }
        }

        // Check if it errored (for non-interpolation segments)
        if (!did_err) {
            const seg_var = ModuleEnv.varFrom(seg_expr_idx);
            did_err = self.types.resolveVar(seg_var).desc.content == .err;
        }
    }

    if (did_err) {
        // If any segment errored, propagate that error to the root string
        try self.markErroneous(expr_var);
    } else if (has_interpolation) {
        // Interpolated strings are Str
        const str_var = try self.freshStr(env, expr_region);
        _ = try self.unify(expr_var, str_var, env);
    } else {
        // A plain literal converts to its target type through from_quote,
        // defaulting to Str if nothing pins it.
        const flex_var = try self.mkFlexWithFromQuoteConstraint(ModuleEnv.nodeIdxFrom(expr_idx), expr_region, env);
        if (self.cir.numericSuffixTargetForNode(ModuleEnv.nodeIdxFrom(expr_idx))) |suffix_target| {
            // Explicit type suffix, e.g. `"foo".MyType`.
            try self.unifyLiteralWithSuffixTarget(flex_var, suffix_target, expr_region, env);
        }
        _ = try self.unify(expr_var, flex_var, env);
    }
    return does_fx;
}

noinline fn checkExprNum(
    self: *Self,
    frame: *ExprCheckFrame,
    num: @FieldType(CIR.Expr, "e_num"),
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;

    switch (num.kind) {
        // For unannotated literals, create a flex var with from_numeral constraint
        .num_unbound, .int_unbound => try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env),
        .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => try self.unifyWith(expr_var, try self.mkNumberTypeContent(num.kind), env),
    }
    return false;
}

