noinline fn checkExprList(
    self: *Self,
    frame: *ExprCheckFrame,
    list: @FieldType(CIR.Expr, "e_list"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    const nested_expected = frame.nested_expected;
    var does_fx = false;

    const elems = self.cir.store.exprSlice(list.elems);

    if (elems.len == 0) {
        // Create a nominal List with a fresh unbound element type
        const elem_var = try self.fresh(env, expr_region);
        const list_content = try self.mkListContent(elem_var);
        try self.unifyWith(expr_var, list_content, env);
    } else {
        var list_seed_slots: ?[]ExpectedFreshShapeSlot = null;
        defer if (list_seed_slots) |slots| self.gpa.free(slots);

        // Element accumulator seed, mirroring the if/match branch
        // accumulator (`instantiateVarOrphanFlexed` seeding in
        // `checkIfElseExpr`/`checkMatchExpr`): when this list literal
        // is checked directly against an expected type (its def's
        // annotation or a platform requirement), seed the element
        // meet with the element of a rigids-flexed ORPHAN COPY of
        // that type, so annotation-declared facts—e.g. an
        // `optional` field kind—constrain every element as it
        // folds in, instead of the elements meeting each other first
        // with kinds still undetermined (design.md "Field Kinds
        // (All-Dynamic Optional Fields)"). The copy is unpacked to
        // its element through one unification with `List(seed)`
        // inside a CommitProbe: if the expected type is not a List
        // at all, the rollback discards the attempt (no problem is
        // recorded) and the annotation mismatch is reported after
        // the switch, exactly as without seeding.
        const ProjectedList = struct {
            elem: Expected.ExpectedType,
            plan_range: ExpectedAggregatePlanRange,
        };
        const mb_seed_elem: ?ProjectedList = seed: {
            const seed_elem_var = try self.fresh(env, expr_region);
            const seed_slots = try self.gpa.alloc(ExpectedFreshShapeSlot, elems.len);
            list_seed_slots = seed_slots;
            for (elems, seed_slots, 0..) |elem_expr, *slot, elem_index| {
                slot.* = pendingExpectedFreshShapeSlot(
                    elem_expr,
                    .list_element,
                    @intCast(elem_index),
                    seed_elem_var,
                );
            }
            const seed_list_var = try self.freshFromContent(try self.mkListContent(seed_elem_var), env, expr_region);
            const projection = try self.projectExpectedAggregateShape(
                expr_idx,
                nested_expected,
                seed_list_var,
                seed_slots,
                env,
            );
            const projected = switch (projection) {
                .established => |value| value,
                .not_projected, .suppressed => break :seed null,
                .rejected => |cause| {
                    switch (frame.checked_status) {
                        .established => frame.checked_status = .{ .checked_error = cause },
                        .checked_error => |existing| if (!expectedCauseOwnersEqual(existing, cause)) {
                            std.debug.panic("list projection changed its exact rejection owner", .{});
                        },
                    }
                    break :seed null;
                },
            };
            break :seed .{
                .elem = try projected.child(
                    self,
                    env,
                    seed_slots,
                    .nominal_argument,
                    0,
                    null,
                    null,
                    seed_elem_var,
                ),
                .plan_range = projected.plan_range,
            };
        };

        // Here, we use the list's 1st element as the element var to
        // constrain the rest of the list

        const elem_var = if (mb_seed_elem) |seed| seeded: {
            for (elems, 0..) |elem_expr_idx, elem_index| {
                const slot = list_seed_slots.?[elem_index];
                const projected_elem = expectedTypeForAggregatePlanSlot(seed.elem, slot);
                const current_elem = try self.checkStoredValueExpr(
                    elem_expr_idx,
                    env,
                    child_expected.withContextualType(projected_elem),
                );
                does_fx = current_elem.does_fx or does_fx;
                const relation = try self.commitProjectedStoredValue(
                    projected_elem,
                    slot.expected_plan,
                    seed.plan_range,
                    current_elem.var_,
                    current_elem.status,
                    env,
                );
                switch (relation) {
                    .established => {},
                    .rejected, .suppressed => |cause| switch (frame.checked_status) {
                        .established => frame.checked_status = .{ .checked_error = cause },
                        .checked_error => {},
                    },
                }
            }
            break :seeded seed.elem.var_;
        } else unseeded: {
            const first_elem = try self.checkStoredValueExpr(elems[0], env, child_expected);
            does_fx = first_elem.does_fx or does_fx;
            const unseeded_elem_var = first_elem.var_;

            // Without an Expected plan the ordinary list relation
            // retains its specialized diagnostics and stops comparing
            // after the first mismatch to avoid cascades.
            var last_elem_expr_idx = elems[0];
            for (elems[1..], 1..) |elem_expr_idx, i| {
                const current_elem = try self.checkStoredValueExpr(elem_expr_idx, env, child_expected);
                does_fx = current_elem.does_fx or does_fx;
                const cur_elem_var = current_elem.var_;

                // Unify each element's var with the list's elem var
                const result = try self.unifyInContext(unseeded_elem_var, cur_elem_var, env, .{ .list_entry = .{
                    .elem_index = @intCast(i),
                    .list_length = @intCast(elems.len),
                    .last_elem_idx = ModuleEnv.nodeIdxFrom(last_elem_expr_idx),
                } });

                // If we errored, check the rest of the elements without comparing
                // to the elem_var to catch their individual errors
                if (!result.isEstablished()) {
                    for (elems[i + 1 ..]) |remaining_elem_expr_idx| {
                        const remaining_elem = try self.checkStoredValueExpr(remaining_elem_expr_idx, env, child_expected);
                        does_fx = remaining_elem.does_fx or does_fx;
                    }

                    // Break to avoid cascading errors
                    break;
                }

                last_elem_expr_idx = elem_expr_idx;
            }
            break :unseeded unseeded_elem_var;
        };

        // Create a nominal List type with the inferred element type
        const list_content = try self.mkListContent(elem_var);
        try self.unifyWith(expr_var, list_content, env);
    }
    return does_fx;
}

noinline fn checkExprTuple(
    self: *Self,
    frame: *ExprCheckFrame,
    tuple: @FieldType(CIR.Expr, "e_tuple"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    const nested_expected = frame.nested_expected;
    var does_fx = false;

    const elems_slice = self.cir.store.exprSlice(tuple.elems);
    const ProjectedTuple = struct {
        elems: Var.SafeList.Range,
        slots: []ExpectedFreshShapeSlot,
        expected: ExpectedAggregateProjection,
    };
    var tuple_slots: ?[]ExpectedFreshShapeSlot = null;
    defer if (tuple_slots) |slots| self.gpa.free(slots);

    // Establish a tuple skeleton first, so an enclosing relation can
    // supply each element's shape before that element is checked.
    const mb_projected: ?ProjectedTuple = projected: {
        const projected_top = self.scratch_vars.top();
        defer self.scratch_vars.clearFrom(projected_top);
        for (elems_slice) |_| {
            try self.scratch_vars.append(try self.fresh(env, expr_region));
        }
        const projected_elems = try self.types.appendVars(self.scratch_vars.sliceFromStart(projected_top));
        const slots = try self.gpa.alloc(ExpectedFreshShapeSlot, elems_slice.len);
        tuple_slots = slots;
        for (elems_slice, slots, 0..) |elem_expr, *slot, elem_index| {
            slot.* = pendingExpectedFreshShapeSlot(
                elem_expr,
                .tuple_element,
                @intCast(elem_index),
                self.types.getVarAt(projected_elems, @intCast(elem_index)),
            );
        }
        const projected_tuple = try self.freshFromContent(.{ .structure = .{
            .tuple = .{ .elems = projected_elems },
        } }, env, expr_region);
        const projection = try self.projectExpectedAggregateShape(
            expr_idx,
            nested_expected,
            projected_tuple,
            slots,
            env,
        );
        const projected_expected = switch (projection) {
            .established => |value| value,
            .not_projected, .suppressed => break :projected null,
            .rejected => |cause| {
                switch (frame.checked_status) {
                    .established => frame.checked_status = .{ .checked_error = cause },
                    .checked_error => |existing| if (!expectedCauseOwnersEqual(existing, cause)) {
                        std.debug.panic("tuple projection changed its exact rejection owner", .{});
                    },
                }
                break :projected null;
            },
        };
        break :projected .{ .elems = projected_elems, .slots = slots, .expected = projected_expected };
    };

    // Check tuple elements, then relate each instantiated stored value
    // to the slot projected above.
    const scratch_vars_top = self.scratch_vars.top();
    defer self.scratch_vars.clearFrom(scratch_vars_top);
    for (elems_slice, 0..) |single_elem_expr_idx, elem_index| {
        const projected_elem = if (mb_projected) |projected|
            try projected.expected.child(
                self,
                env,
                projected.slots[elem_index..][0..1],
                .tuple_element,
                @intCast(elem_index),
                null,
                null,
                self.types.getVarAt(projected.elems, @intCast(elem_index)),
            )
        else
            null;
        const elem_expected = if (projected_elem) |expected_elem|
            child_expected.withContextualType(expected_elem)
        else
            child_expected;
        const elem = try self.checkStoredValueExpr(single_elem_expr_idx, env, elem_expected);
        does_fx = elem.does_fx or does_fx;
        if (projected_elem) |expected_elem| {
            const projected = mb_projected.?;
            const relation = try self.commitProjectedStoredValue(
                expected_elem,
                projected.slots[elem_index].expected_plan,
                projected.expected.plan_range,
                elem.var_,
                elem.status,
                env,
            );
            switch (relation) {
                .established => {},
                .rejected, .suppressed => |cause| switch (frame.checked_status) {
                    .established => frame.checked_status = .{ .checked_error = cause },
                    .checked_error => {},
                },
            }
        }
        try self.scratch_vars.append(elem.var_);
    }

    const elem_vars_slice = try self.types.appendVars(self.scratch_vars.sliceFromStart(scratch_vars_top));

    // Set the type in the store
    try self.unifyWith(expr_var, .{ .structure = .{
        .tuple = .{ .elems = elem_vars_slice },
    } }, env);
    return does_fx;
}

noinline fn checkExprTupleAccess(
    self: *Self,
    frame: *ExprCheckFrame,
    tuple_access: @FieldType(CIR.Expr, "e_tuple_access"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    var does_fx = false;

    // Check the tuple expression
    does_fx = (try self.checkExpr(tuple_access.tuple, env, child_expected)).does_fx or does_fx;

    const tuple_var = ModuleEnv.varFrom(tuple_access.tuple);
    const pending = PendingTupleAccess{
        .tuple_var = self.types.resolveVar(tuple_var).var_,
        .result_var = expr_var,
        .elem_index = tuple_access.elem_index,
        .region = expr_region,
    };
    if (!try self.resolvePendingTupleAccess(pending, env, false)) {
        try self.pending_tuple_accesses.append(self.gpa, pending);
    }
    return does_fx;
}

noinline fn checkExprRecord(
    self: *Self,
    frame: *ExprCheckFrame,
    e: @FieldType(CIR.Expr, "e_record"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    const nested_expected = frame.nested_expected;
    var does_fx = false;

    // Check if this is a record update
    if (e.ext) |record_being_updated_expr| {
        // Create a record type in the type system and assign it the expr_var

        // Check the record being updated. Its producer-authored status
        // travels with every Expected projection sourced from the base.
        const record_base_outcome = try self.checkExpr(
            record_being_updated_expr,
            env,
            child_expected,
        );
        does_fx = record_base_outcome.does_fx or does_fx;

        const record_being_updated_var = ModuleEnv.varFrom(record_being_updated_expr);
        const base_publication = try self.publishRecordUpdateBasePlan(
            expr_idx,
            record_being_updated_expr,
            record_being_updated_var,
            record_base_outcome.status,
            env,
        );
        const base_plan_index = base_publication.plan_index;
        const base_copy = base_publication.copy;
        const base_anchor = base_publication.anchor;
        const record_being_updated_name: ?Ident.Idx = self.getExprPatternIdent(record_being_updated_expr);

        // Process each field
        for (self.cir.store.sliceRecordFields(e.fields), 0..) |field_idx, field_index| {
            const field = self.cir.store.getRecordField(field_idx);

            // A supplied update field has CREATION semantics: like a
            // record-literal field, its KIND is undetermined—the
            // update can set a required, defaulted, or optional field
            // (design.md "Field Kinds (All-Dynamic Optional
            // Fields)"). Unifying the kind-flexible probe into the
            // base does the rest: a base kind of `optional` pins the
            // kind optional and checks the value against the payload
            // type (lowering then wraps the value in `Present`,
            // exactly as construction does); `required`/`defaulted`
            // pin as before. If no context decides a still-flex kind,
            // the update judgment commits it to required before its
            // owning generalization boundary.
            const field_kind_var = try self.fresh(env, expr_region);
            const projected_field_value = try self.fresh(env, expr_region);
            var slot_plan = pendingExpectedFreshShapeSlot(
                field.value,
                .record_update_field,
                @intCast(field_index),
                projected_field_value,
            );
            try self.pending_record_updates.append(self.gpa, .{
                .presence_var = field_kind_var,
                .region = expr_region,
            });

            // Create an unbound record with this field
            const single_field_record = try self.freshFromContent(.{
                .structure = .{
                    .record_unbound = try self.types.appendRecordFields(&.{types_mod.RecordField{
                        .name = field.name,
                        .presence = .unknown(field_kind_var, projected_field_value),
                    }}),
                },
            }, env, expr_region);

            // Relate the update slot to the base row before checking
            // its value, so a nested aggregate sees the field shape
            // declared by the base record.
            const update_context = problem.Context{ .record_update = .{
                .field_name = field.name,
                .field_region_idx = @enumFromInt(@intFromEnum(field.value)),
                .record_region_idx = @enumFromInt(@intFromEnum(record_being_updated_var)),
                .record_name = record_being_updated_name,
            } };
            const slot_projection = try self.projectExpectedRecordUpdateField(
                expr_idx,
                base_plan_index,
                .{
                    .var_ = base_copy.var_,
                    .context = update_context,
                    .marker_authority = .{ .anchored = .{ .copy_occurrence = base_anchor } },
                    .status = switch (record_base_outcome.status) {
                        .established => .established,
                        .checked_error => |cause| .{ .checked_error = .{
                            .cause = cause,
                            .route = .{ .upstream_plan = base_plan_index },
                        } },
                    },
                },
                single_field_record,
                &slot_plan,
                @bitCast(field.name),
                env,
            );

            const projected_field: ?Expected.ExpectedType = switch (slot_projection) {
                .established => |projected| projected,
                .suppressed => null,
                .not_projected => null,
            };
            const field_expected = if (projected_field) |expected_field|
                child_expected.withContextualType(expected_field)
            else
                child_expected;
            const field_value = try self.checkStoredValueExpr(field.value, env, field_expected);
            does_fx = field_value.does_fx or does_fx;

            // The base row owns the final update judgment and its
            // record-aware diagnostic. Use the instantiated stored
            // value here; the projection above was context only.
            const actual_field_record = try self.freshFromContent(.{
                .structure = .{
                    .record_unbound = try self.types.appendRecordFields(&.{types_mod.RecordField{
                        .name = field.name,
                        .presence = .unknown(field_kind_var, field_value.var_),
                    }}),
                },
            }, env, expr_region);
            _ = try self.unifyInContext(
                record_being_updated_var,
                actual_field_record,
                env,
                update_context,
            );
        }

        switch (record_base_outcome.status) {
            .established => {},
            .checked_error => |base_cause| {
                const cause = try self.publishRecordUpdateOwnerRetirement(
                    env,
                    expr_idx,
                    base_plan_index,
                    base_cause,
                );
                frame.checked_status = .{ .checked_error = cause };
            },
        }

        // Process each unset field. The probe mirrors `.?`-access
        // EXACTLY (design.md "In Progress: Unsetting an Optional
        // Field"): a kind-FLEXIBLE presence var—NOT a concrete
        // `optional` demand, which width absorption would admit into
        // a closed base that lacks the field, silently accepting
        // typo'd unsets. The access is recorded and JUDGED at every
        // generalization boundary (finalize as backstop): a kind
        // resolved `required`/`defaulted` is rejected, a still-flex
        // kind pins to `optional` BEFORE the scheme forms—an unset
        // is presence-evidence for optionality, exactly like `.?`.
        for (self.cir.store.sliceUnsetFields(e.unsets)) |field_idx| {
            const field = self.cir.store.getUnsetField(field_idx);
            const field_region = self.getRegionAt(ModuleEnv.varFrom(field_idx));

            const field_var = try self.fresh(env, expr_region);
            const presence_var = try self.fresh(env, expr_region);
            try self.optional_field_accesses.append(self.gpa, .{
                .presence_var = presence_var,
                .field_name = field.name,
                .region = field_region,
                .use = .unset,
            });
            const single_field_record = try self.freshFromContent(.{
                .structure = .{
                    .record_unbound = try self.types.appendRecordFields(&.{types_mod.RecordField{
                        .name = field.name,
                        .presence = .unknown(presence_var, field_var),
                    }}),
                },
            }, env, expr_region);

            // Unify this record update with the record we're updating
            _ = try self.unifyInContext(record_being_updated_var, single_field_record, env, .{ .record_update = .{
                .field_name = field.name,
                .field_region_idx = @enumFromInt(@intFromEnum(field_idx)),
                .record_region_idx = @enumFromInt(@intFromEnum(record_being_updated_var)),
                .record_name = record_being_updated_name,
            } });
        }

        // Then unify with the actual expression
        _ = try self.unify(record_being_updated_var, expr_var, env);
    } else {
        const source_fields = self.cir.store.sliceRecordFields(e.fields);
        const ProjectedRecord = struct {
            values: Var.SafeList.Range,
            slots: []ExpectedFreshShapeSlot,
            expected: ExpectedAggregateProjection,
        };
        var record_slots: ?[]ExpectedFreshShapeSlot = null;
        defer if (record_slots) |slots| self.gpa.free(slots);

        // Build a record skeleton with one payload slot per supplied
        // field. Relating an orphan expected copy to this skeleton
        // admits omitted defaulted fields at the real source record
        // construction, and pins each supplied field's payload before
        // its expression is checked.
        const mb_projected: ?ProjectedRecord = projected: {
            const projected_fields_top = self.scratch_record_fields.top();
            defer self.scratch_record_fields.clearFrom(projected_fields_top);
            const projected_values_top = self.scratch_vars.top();
            defer self.scratch_vars.clearFrom(projected_values_top);

            for (source_fields) |field_idx| {
                const field = self.cir.store.getRecordField(field_idx);
                const projected_value = try self.fresh(env, expr_region);
                try self.scratch_vars.append(projected_value);
                try self.scratch_record_fields.append(.{
                    .name = field.name,
                    .presence = .unknown(
                        try self.fresh(env, expr_region),
                        projected_value,
                    ),
                });
            }

            const projected_values = try self.types.appendVars(self.scratch_vars.sliceFromStart(projected_values_top));
            const slots = try self.gpa.alloc(ExpectedFreshShapeSlot, source_fields.len);
            record_slots = slots;
            for (source_fields, slots, 0..) |field_idx, *slot, field_index| {
                const field = self.cir.store.getRecordField(field_idx);
                slot.* = pendingExpectedFreshShapeSlot(
                    field.value,
                    .record_field,
                    @intCast(field_index),
                    self.types.getVarAt(projected_values, @intCast(field_index)),
                );
            }
            const projected_fields_scratch = self.scratch_record_fields.sliceFromStart(projected_fields_top);
            std.mem.sort(
                types_mod.RecordField,
                projected_fields_scratch,
                self.cir.getIdentStore(),
                types_mod.RecordField.sortByNameAsc,
            );
            const projected_fields = try self.types.appendRecordFields(projected_fields_scratch);
            const projected_ext = try self.freshFromContent(.{ .structure = .empty_record }, env, expr_region);
            const projected_record = try self.freshFromContent(.{ .structure = .{ .record = .{
                .fields = projected_fields,
                .ext = projected_ext,
            } } }, env, expr_region);
            const projection = try self.projectExpectedAggregateShape(
                expr_idx,
                nested_expected,
                projected_record,
                slots,
                env,
            );
            const projected_expected = switch (projection) {
                .established => |value| value,
                .not_projected, .suppressed => break :projected null,
                .rejected => |cause| {
                    switch (frame.checked_status) {
                        .established => frame.checked_status = .{ .checked_error = cause },
                        .checked_error => |existing| if (!expectedCauseOwnersEqual(existing, cause)) {
                            std.debug.panic("record projection changed its exact rejection owner", .{});
                        },
                    }
                    break :projected null;
                },
            };
            break :projected .{ .values = projected_values, .slots = slots, .expected = projected_expected };
        };

        // Write down the top of the scratch records array
        const record_fields_top = self.scratch_record_fields.top();
        defer self.scratch_record_fields.clearFrom(record_fields_top);

        // Process each field
        for (source_fields, 0..) |field_idx, field_index| {
            const field = self.cir.store.getRecordField(field_idx);

            // Check the field value expression
            const projected_field = if (mb_projected) |projected|
                try projected.expected.child(
                    self,
                    env,
                    projected.slots[field_index..][0..1],
                    .record_field_type,
                    0,
                    @bitCast(field.name),
                    .record_extension,
                    self.types.getVarAt(projected.values, @intCast(field_index)),
                )
            else
                null;
            const field_expected = if (projected_field) |expected_field|
                child_expected.withContextualType(expected_field)
            else
                child_expected;
            const field_value = try self.checkStoredValueExpr(field.value, env, field_expected);
            does_fx = field_value.does_fx or does_fx;
            if (projected_field) |expected_field| {
                const projected = mb_projected.?;
                const relation = try self.commitProjectedStoredValue(
                    expected_field,
                    projected.slots[field_index].expected_plan,
                    projected.expected.plan_range,
                    field_value.var_,
                    field_value.status,
                    env,
                );
                switch (relation) {
                    .established => {},
                    .rejected, .suppressed => |cause| switch (frame.checked_status) {
                        .established => frame.checked_status = .{ .checked_error = cause },
                        .checked_error => {},
                    },
                }
            }

            // A literal field's KIND is undetermined: the literal
            // can serve as a required field or as an optional one
            // (construction wraps the tag exactly when the solved
            // kind is `optional`). Unification pins the kind to
            // whichever concrete kind the context demands
            // (design.md "Field Kinds (All-Dynamic Optional
            // Fields)"). The mint is recorded so the finalize sweep
            // can commit a kind nothing ever pinned to `required`
            // (see `defaultLiteralFieldKinds`).
            const field_kind_var = try self.fresh(env, expr_region);
            try self.literal_field_kinds.append(self.gpa, .{
                .presence_var = field_kind_var,
                .region = expr_region,
            });

            // Append it to the scratch records array
            try self.scratch_record_fields.append(types_mod.RecordField{
                .name = field.name,
                .presence = .unknown(field_kind_var, field_value.var_),
            });
        }

        // Process each unset (ie absent) field: it joins the literal
        // row directly with a kind-flexible presence var and a fresh
        // flex payload var, and is enqueued in the SAME
        // `optional_field_accesses` queue as `.?` and update unsets.
        // Deliberately NOT in `literal_field_kinds`: that sweep
        // commits never-pinned kinds to `required`, and an unset
        // field's kind must default to `optional` instead—which the
        // judgment's flex-pin does. An annotation demanding
        // `required`/`defaulted` is rejected through the same
        // judgment as updates (design.md "In Progress: Unsetting an
        // Optional Field").
        for (self.cir.store.sliceUnsetFields(e.unsets)) |field_idx| {
            const field = self.cir.store.getUnsetField(field_idx);
            const field_region = self.getRegionAt(ModuleEnv.varFrom(field_idx));

            const field_var = try self.fresh(env, expr_region);
            const presence_var = try self.fresh(env, expr_region);
            try self.optional_field_accesses.append(self.gpa, .{
                .presence_var = presence_var,
                .field_name = field.name,
                .region = field_region,
                .use = .unset,
            });

            // Append it to the scratch records array
            try self.scratch_record_fields.append(types_mod.RecordField{
                .name = field.name,
                .presence = .unknown(presence_var, field_var),
            });
        }

        // Copy the scratch fields into the types store
        const record_fields_scratch = self.scratch_record_fields.sliceFromStart(record_fields_top);
        std.mem.sort(types_mod.RecordField, record_fields_scratch, self.cir.getIdentStore(), types_mod.RecordField.sortByNameAsc);
        const record_fields_range = try self.types.appendRecordFields(record_fields_scratch);

        // Create an unbound record with the provided fields
        const ext_var = try self.freshFromContent(.{ .structure = .empty_record }, env, expr_region);
        try self.unifyWith(expr_var, .{ .structure = .{ .record = .{
            .fields = record_fields_range,
            .ext = ext_var,
        } } }, env);
    }
    return does_fx;
}

noinline fn checkExprEmptyRecord(
    self: *Self,
    frame: *ExprCheckFrame,
) std.mem.Allocator.Error!bool {
    const env = frame.env;
    const expr_var = frame.expr_var;

    try self.unifyWith(expr_var, .{ .structure = .empty_record }, env);
    return false;
}

noinline fn checkExprZeroArgumentTag(
    self: *Self,
    frame: *ExprCheckFrame,
    e: @FieldType(CIR.Expr, "e_zero_argument_tag"),
) std.mem.Allocator.Error!bool {
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;

    const ext_var = try self.fresh(env, expr_region);

    const tag = try self.types.mkTag(e.name, &.{});
    const tag_union_content = try self.types.mkTagUnion(&[_]types_mod.Tag{tag}, ext_var);

    // Update the expr to point to the new type
    try self.unifyWith(expr_var, tag_union_content, env);
    return false;
}

noinline fn checkExprTag(
    self: *Self,
    frame: *ExprCheckFrame,
    e: @FieldType(CIR.Expr, "e_tag"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    const nested_expected = frame.nested_expected;
    var does_fx = false;

    const arg_expr_idx_slice = self.cir.store.sliceExpr(e.args);
    const ProjectedTag = struct {
        args: Var.SafeList.Range,
        slots: []ExpectedFreshShapeSlot,
        expected: ExpectedAggregateProjection,
    };
    var tag_slots: ?[]ExpectedFreshShapeSlot = null;
    defer if (tag_slots) |slots| self.gpa.free(slots);

    // Project this constructor's payload slots from the expected tag
    // union before checking payload expressions.
    const mb_projected: ?ProjectedTag = projected: {
        // A zero-payload tag has no nested construction to guide. Its
        // ordinary enclosing relation must remain the sole place that
        // grounds and discharges the expected type's constraints.
        if (arg_expr_idx_slice.len == 0) break :projected null;
        const projected_top = self.scratch_vars.top();
        defer self.scratch_vars.clearFrom(projected_top);
        for (arg_expr_idx_slice) |_| {
            try self.scratch_vars.append(try self.fresh(env, expr_region));
        }
        const projected_args = try self.types.appendVars(self.scratch_vars.sliceFromStart(projected_top));
        const slots = try self.gpa.alloc(ExpectedFreshShapeSlot, arg_expr_idx_slice.len);
        tag_slots = slots;
        for (arg_expr_idx_slice, slots, 0..) |arg_expr, *slot, arg_index| {
            slot.* = pendingExpectedFreshShapeSlot(
                arg_expr,
                .tag_payload,
                @intCast(arg_index),
                self.types.getVarAt(projected_args, @intCast(arg_index)),
            );
        }
        const projected_ext = try self.fresh(env, expr_region);
        const projected_tag = try self.types.mkTag(e.name, self.types.sliceVars(projected_args));
        const projected_union = try self.freshFromContent(
            try self.types.mkTagUnion(&[_]types_mod.Tag{projected_tag}, projected_ext),
            env,
            expr_region,
        );
        const projection = try self.projectExpectedAggregateShape(
            expr_idx,
            nested_expected,
            projected_union,
            slots,
            env,
        );
        const projected_expected = switch (projection) {
            .established => |value| value,
            .not_projected, .suppressed => break :projected null,
            .rejected => |cause| {
                switch (frame.checked_status) {
                    .established => frame.checked_status = .{ .checked_error = cause },
                    .checked_error => |existing| if (!expectedCauseOwnersEqual(existing, cause)) {
                        std.debug.panic("tag projection changed its exact rejection owner", .{});
                    },
                }
                break :projected null;
            },
        };
        break :projected .{ .args = projected_args, .slots = slots, .expected = projected_expected };
    };

    // Process each tag arg, preserving the stored-value instantiation
    // edge before relating it to the projected payload slot.
    const scratch_vars_top = self.scratch_vars.top();
    defer self.scratch_vars.clearFrom(scratch_vars_top);
    for (arg_expr_idx_slice, 0..) |arg_expr_idx, arg_index| {
        const projected_arg = if (mb_projected) |projected|
            try projected.expected.child(
                self,
                env,
                projected.slots[arg_index..][0..1],
                .tag_payload,
                @intCast(arg_index),
                @bitCast(e.name),
                .tag_extension,
                self.types.getVarAt(projected.args, @intCast(arg_index)),
            )
        else
            null;
        const arg_expected = if (projected_arg) |expected_arg|
            child_expected.withContextualType(expected_arg)
        else
            child_expected;
        const arg = try self.checkStoredValueExpr(arg_expr_idx, env, arg_expected);
        does_fx = arg.does_fx or does_fx;
        if (projected_arg) |expected_arg| {
            const projected = mb_projected.?;
            const relation = try self.commitProjectedStoredValue(
                expected_arg,
                projected.slots[arg_index].expected_plan,
                projected.expected.plan_range,
                arg.var_,
                arg.status,
                env,
            );
            switch (relation) {
                .established => {},
                .rejected, .suppressed => |cause| switch (frame.checked_status) {
                    .established => frame.checked_status = .{ .checked_error = cause },
                    .checked_error => {},
                },
            }
        }
        try self.scratch_vars.append(arg.var_);
    }

    // Create the type
    const ext_var = try self.fresh(env, expr_region);

    const tag = try self.types.mkTag(e.name, self.scratch_vars.sliceFromStart(scratch_vars_top));
    const tag_union_content = try self.types.mkTagUnion(&[_]types_mod.Tag{tag}, ext_var);

    // Update the expr to point to the new type
    try self.unifyWith(expr_var, tag_union_content, env);
    return does_fx;
}

noinline fn checkExprNominal(
    self: *Self,
    frame: *ExprCheckFrame,
    nominal: @FieldType(CIR.Expr, "e_nominal"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    var does_fx = false;

    const prepared = try self.prepareNominalTypeUsage(
        expr_var,
        ModuleEnv.varFrom(nominal.nominal_type_decl),
        expr_region,
        env,
        .{ .nominal_expr_decl = .{ .node = @intFromEnum(expr_idx) } },
        .{ .nominal_expr_backing = .{ .node = @intFromEnum(expr_idx) } },
    );
    const backing_expected = if (prepared) |usage|
        child_expected.withContextualType(.{
            .var_ = usage.backing_var,
            .context = .{ .nominal_constructor = .{
                .backing_type = @enumFromInt(@intFromEnum(nominal.backing_type)),
            } },
            .marker_authority = .{ .anchored = .{ .copy_occurrence = usage.backing_anchor } },
            .status = .established,
        })
    else
        child_expected;
    const backing = try self.checkStoredValueExpr(nominal.backing_expr, env, backing_expected);
    does_fx = backing.does_fx or does_fx;
    const actual_backing_var = backing.var_;

    if (prepared) |usage| {
        _ = try self.finishNominalTypeUsage(
            expr_var,
            actual_backing_var,
            usage,
            nominal.backing_type,
            env,
            if (self.exprIsFreshRecordConstruction(nominal.backing_expr)) .construction else .exact,
            expr_idx,
        );
    }
    return does_fx;
}

noinline fn checkExprNominalExternal(
    self: *Self,
    frame: *ExprCheckFrame,
    nominal: @FieldType(CIR.Expr, "e_nominal_external"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    var does_fx = false;

    // Resolve the external type declaration
    const prepared = if (try self.resolveVarFromExternal(
        nominal.module_idx,
        nominal.target_node_idx,
        .{
            .site_kind = .external_nominal_expr,
            .origin_node = @intFromEnum(expr_idx),
        },
    )) |ext_ref|
        try self.prepareNominalTypeUsage(
            expr_var,
            ext_ref.local_var,
            expr_region,
            env,
            .{ .nominal_expr_decl = .{ .node = @intFromEnum(expr_idx) } },
            .{ .nominal_expr_backing = .{ .node = @intFromEnum(expr_idx) } },
        )
    else prepared: {
        try self.markErroneous(expr_var);
        break :prepared null;
    };
    const backing_expected = if (prepared) |usage|
        child_expected.withContextualType(.{
            .var_ = usage.backing_var,
            .context = .{ .nominal_constructor = .{
                .backing_type = @enumFromInt(@intFromEnum(nominal.backing_type)),
            } },
            .marker_authority = .{ .anchored = .{ .copy_occurrence = usage.backing_anchor } },
            .status = .established,
        })
    else
        child_expected;
    const backing = try self.checkStoredValueExpr(nominal.backing_expr, env, backing_expected);
    does_fx = backing.does_fx or does_fx;

    if (prepared) |usage| {
        _ = try self.finishNominalTypeUsage(
            expr_var,
            backing.var_,
            usage,
            nominal.backing_type,
            env,
            if (self.exprIsFreshRecordConstruction(nominal.backing_expr)) .construction else .exact,
            expr_idx,
        );
    }
    return does_fx;
}

noinline fn checkExprLookupLocal(
    self: *Self,
    frame: *ExprCheckFrame,
    lookup: @FieldType(CIR.Expr, "e_lookup_local"),
    expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;

    blk: {
        const pat_var = ModuleEnv.varFrom(lookup.pattern_idx);

        if (self.localLookupIsGeneratedDerivedMethodMarker(lookup.pattern_idx)) {
            try self.reportAnnotationOnlyValueUse(expr_var, expr_region, env);
            break :blk;
        }

        if (self.localLookupHasNoValue(lookup.pattern_idx)) {
            try self.reportValuelessDeclarationUse(expr_var, expr_region);
            break :blk;
        }

        try self.value_lookup_tracking.append(self.gpa, .{
            .expr_idx = expr_idx,
            .pattern_idx = lookup.pattern_idx,
            .call_root_token_index = frame.immediate_call_root_token orelse
                ModuleEnv.ExpectedCallSlotToken.none,
        });

        const mb_processing_def = self.topLevelPattern(lookup.pattern_idx);
        if (mb_processing_def) |processing_def| {
            const referenced_def = self.cir.store.getDef(processing_def.def_idx);
            // A reference to an annotated def whose body has not been
            // checked yet instantiates the pre-declared scheme—the
            // uniform rule: annotated references never need the body.
            // (Once the def is `.processed`, its own pattern var carries
            // the checked scheme and the ordinary tail below applies.)
            const mb_predeclared_scheme = self.predeclaredSchemeVar(processing_def.def_idx);

            switch (processing_def.status) {
                .not_processed => {
                    if (mb_predeclared_scheme) |scheme_var| {
                        try self.instantiatePendingPredeclaredSchemeUse(
                            processing_def.def_idx,
                            scheme_var,
                            expr_var,
                            expr_idx,
                            env,
                            if (frame.immediate_call_root_token != null) frame else null,
                            lookup.pattern_idx,
                            referenced_def.annotation orelse std.debug.panic(
                                "predeclared top-level scheme lost its annotation",
                                .{},
                            ),
                        );
                        break :blk;
                    }
                    {
                        // The driver checks groups in topological order, so
                        // an unchecked, un-pre-declared target can only be
                        // a later member of the CURRENT recursive group—
                        // its pattern var was ranked in the group's shared
                        // frame before any member body ran.
                        if (builtin.mode == .Debug) {
                            if (!self.defInCurrentRecursiveGroup(processing_def.def_idx)) {
                                std.debug.panic("type checker invariant violated: name reference to unchecked def outside the current binding group", .{});
                            }
                        }
                        if (!isFunctionDef(&self.cir.store, self.cir.store.getExpr(referenced_def.expr)) and
                            self.delayed_dependency_depth == 0)
                        {
                            // A value member of a recursive group referenced
                            // outside any lambda body is a strict value
                            // cycle.
                            try self.poisonRecursiveNonFunctionProcessingDef(processing_def, expr_idx, env);
                        } else {
                            // The binding-group recursion rule: an in-group
                            // reference to an unannotated member unifies
                            // monomorphically with the member's in-flight
                            // type, so facts discovered at the call site
                            // flow into the inferred scheme.
                            _ = try self.unifyInContext(expr_var, pat_var, env, .{ .recursive_def = .{ .def_name = processing_def.def_name } });
                            try self.recordSharedSchemeUse(
                                @intFromEnum(expr_idx),
                                .shared_value_use,
                                0,
                                ModuleEnv.varFrom(processing_def.def_idx),
                            );
                        }
                        break :blk;
                    }
                },
                .processing => {
                    if (mb_predeclared_scheme) |scheme_var| {
                        // Annotated self-reference (or in-group reference
                        // to an in-flight annotated member): instantiate
                        // the declared scheme—sound polymorphic
                        // recursion for annotated defs. This is an internal
                        // recursive edge, not an external use of the body's
                        // eventual scheme; the enclosing body's own
                        // requirements cover the implementation cycle.
                        const instantiated = if (frame.immediate_call_root_token != null and
                            self.bindingVarRequiresInstantiation(scheme_var))
                            try self.instantiateExpectedCallCalleeForFrame(
                                frame,
                                scheme_var,
                                env,
                                .use_last_var,
                                .local_predeclared_annotation,
                                @intFromEnum(lookup.pattern_idx),
                                self.predeclaredAnnotationSupportStep(
                                    referenced_def.annotation orelse std.debug.panic(
                                        "predeclared recursive scheme lost its annotation",
                                        .{},
                                    ),
                                ),
                                ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
                            )
                        else
                            try self.instantiateBindingVar(scheme_var, env, .use_last_var);
                        _ = try self.unify(expr_var, instantiated, env);
                        break :blk;
                    }
                    if (!isFunctionDef(&self.cir.store, self.cir.store.getExpr(referenced_def.expr))) {
                        if (self.delayed_dependency_depth == 0) {
                            try self.poisonRecursiveNonFunctionProcessingDef(processing_def, expr_idx, env);
                        } else {
                            _ = try self.unify(expr_var, ModuleEnv.varFrom(referenced_def.expr), env);
                        }
                        break :blk;
                    }

                    // The def is mid-check, so it must not be generalized yet.
                    std.debug.assert(self.types.resolveVar(pat_var).desc.rank != .generalized);

                    // The binding-group recursion rule (see the
                    // .not_processed arm): a self-reference, or a
                    // reference to an in-flight unannotated member,
                    // links monomorphically. The link targets the def's
                    // RHS var—which lives in the frame that generalizes
                    // the def—rather than its pattern var: a suspended
                    // singleton's pattern sits at the outermost rank, and
                    // a dispatch back-edge linking there would pull the
                    // whole merged group out of generalization instead of
                    // generalizing with the suspended group's boundary.
                    _ = try self.unifyInContext(expr_var, ModuleEnv.varFrom(referenced_def.expr), env, .{ .recursive_def = .{ .def_name = processing_def.def_name } });
                    try self.recordSharedSchemeUse(
                        @intFromEnum(expr_idx),
                        .shared_value_use,
                        0,
                        ModuleEnv.varFrom(processing_def.def_idx),
                    );
                    break :blk;
                },
                .processed => {
                    if (mb_predeclared_scheme) |scheme_var| {
                        if (self.defInOnStackGroup(processing_def.def_idx)) {
                            // A previously checked member of this still-
                            // open recursive group has not reached the
                            // shared generalization boundary yet. Preserve
                            // the annotation's polymorphic-recursion rule
                            // until that boundary publishes the body scheme.
                            const instantiated = if (frame.immediate_call_root_token != null and
                                self.bindingVarRequiresInstantiation(scheme_var))
                                try self.instantiateExpectedCallCalleeForFrame(
                                    frame,
                                    scheme_var,
                                    env,
                                    .use_last_var,
                                    .local_predeclared_annotation,
                                    @intFromEnum(lookup.pattern_idx),
                                    self.predeclaredAnnotationSupportStep(
                                        referenced_def.annotation orelse std.debug.panic(
                                            "predeclared on-stack scheme lost its annotation",
                                            .{},
                                        ),
                                    ),
                                    ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
                                )
                            else
                                try self.instantiateBindingVar(scheme_var, env, .use_last_var);
                            _ = try self.unify(expr_var, instantiated, env);
                            break :blk;
                        }
                    }
                },
            }
        }

        // Local block-def recursion. If this lookup targets a local `s_decl`
        // function whose body is currently being checked, it's a recursive
        // reference (to the def itself, or to an enclosing in-flight def).
        // An annotated local def's scheme is pre-declared before its body,
        // so its pattern var is already generalized and the reference falls
        // through to the instantiate tail. An unannotated one follows the
        // binding-group recursion rule: unify monomorphically with the
        // pattern var, which lives in the def's own rank frame (see the
        // recursive `s_decl` frame in `checkStatement`) so the links
        // generalize with the def.
        //
        // A reference to an already-finished sibling local def is NOT in this
        // map (removed after it generalizes), so it falls through to the tail
        // below and instantiates normally.
        if (self.local_processing_ptrns.get(lookup.pattern_idx)) |local_def| {
            if (self.predeclared_local_scheme_vars.get(lookup.pattern_idx)) |scheme_var| {
                // Annotated local self/enclosing reference: instantiate
                // the declared scheme (sound polymorphic recursion).
                const annotation_idx = local_def.predeclared_annotation orelse
                    std.debug.panic("block-local predeclared scheme lost its annotation", .{});
                const instantiated = if (frame.immediate_call_root_token != null and
                    self.bindingVarRequiresInstantiation(scheme_var))
                    try self.instantiateExpectedCallCalleeForFrame(
                        frame,
                        scheme_var,
                        env,
                        .use_last_var,
                        .local_predeclared_annotation,
                        @intFromEnum(lookup.pattern_idx),
                        self.predeclaredAnnotationSupportStep(annotation_idx),
                        ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
                    )
                else
                    try self.instantiateBindingVar(scheme_var, env, .use_last_var);
                _ = try self.unify(expr_var, instantiated, env);
                break :blk;
            }

            // The def is mid-check, so it must not be generalized yet.
            std.debug.assert(self.types.resolveVar(pat_var).desc.rank != .generalized);

            _ = try self.unifyInContext(expr_var, pat_var, env, .{ .recursive_def = .{ .def_name = local_def.def_name } });
            try self.recordSharedSchemeUse(
                @intFromEnum(expr_idx),
                .shared_value_use,
                0,
                pat_var,
            );
            break :blk;
        }

        const compile_time_known_binding = known: {
            if (self.patternIsTopLevel(lookup.pattern_idx)) break :known true;
            if (expected.hoist_position == .suppressed) {
                if (self.hoist_known_values.get(lookup.pattern_idx)) |known_value| {
                    switch (known_value) {
                        .pattern_extraction => {
                            if (try self.ensureHoistedBindingRoot(lookup.pattern_idx)) break :known true;
                        },
                        .binding_rhs,
                        .selected_root,
                        .unavailable_runtime,
                        => {},
                    }
                }
            }
            if (self.shouldDeferHoistedBindingSelection() and self.hoistKnownBindingAvailable(lookup.pattern_idx)) {
                try self.hoist_deferred_roots.append(self.gpa, .{ .binding = lookup.pattern_idx });
                break :known true;
            }
            if (try self.ensureHoistedBindingRoot(lookup.pattern_idx)) break :known true;
            break :known self.markHoistContextualDependencyForLookup(lookup.pattern_idx);
        };
        if (!compile_time_known_binding) {
            self.markCurrentHoistRuntimeDependency();
        }

        const resolved_pat = self.types.resolveVar(pat_var);
        if (resolved_pat.desc.rank == Rank.generalized or self.isBindingSchemeVar(pat_var)) {
            const instantiated = if (frame.immediate_call_root_token != null)
                try self.instantiateExpectedCallCalleeForFrame(
                    frame,
                    pat_var,
                    env,
                    .use_last_var,
                    .local_binding_pattern,
                    @intFromEnum(lookup.pattern_idx),
                    ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
                    ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
                )
            else
                try self.instantiateBindingVar(pat_var, env, .use_last_var);
            _ = try self.unify(expr_var, instantiated, env);
        } else {
            _ = try self.unify(expr_var, pat_var, env);
            if (mb_processing_def) |processing_def| {
                try self.recordSharedSchemeUse(
                    @intFromEnum(expr_idx),
                    .shared_value_use,
                    0,
                    ModuleEnv.varFrom(processing_def.def_idx),
                );
            }
        }
        if (self.activeDirectBinderFailureForPattern(lookup.pattern_idx)) |active_failure| {
            const cause = try self.publishDirectBinderLookupCheckedError(
                expr_idx,
                lookup.pattern_idx,
                active_failure,
            );
            switch (frame.checked_status) {
                .established => frame.checked_status = .{ .checked_error = cause },
                .checked_error => |existing| if (!expectedCauseOwnersEqual(existing, cause)) {
                    std.debug.panic("a direct binder lookup changed its exact checked-error cause", .{});
                },
            }
        }
    }
    return false;
}

noinline fn checkExprLookupExternal(
    self: *Self,
    frame: *ExprCheckFrame,
    ext: @FieldType(CIR.Expr, "e_lookup_external"),
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;

    // With WaitingForDependencies phase, dependencies are guaranteed to be Done
    // before canonicalization, so target_node_idx is always valid.
    if (try self.resolveVarFromExternal(
        ext.module_idx,
        ext.target_node_idx,
        .{
            .site_kind = .external_lookup_expr,
            .origin_node = @intFromEnum(expr_idx),
        },
    )) |ext_ref| {
        const target_def: CIR.Def.Idx = @enumFromInt(@intFromEnum(ext_ref.other_cir_node_idx));
        if (generatedDerivedMethodDef(ext_ref.other_cir, target_def)) {
            try self.reportAnnotationOnlyValueUse(expr_var, expr_region, env);
        } else if (annotationOnlyValueDef(ext_ref.other_cir, target_def)) {
            try self.reportValuelessDeclarationUse(expr_var, expr_region);
        } else {
            const ext_instantiated_var = if (frame.immediate_call_root_token != null)
                try self.instantiateExpectedCallCalleeForFrame(
                    frame,
                    ext_ref.local_var,
                    env,
                    .{ .explicit = expr_region },
                    .external_import_root,
                    ext.target_node_idx,
                    ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
                    ext_ref.seed_index,
                )
            else
                try self.instantiateImportedBindingVar(
                    ext_ref.local_var,
                    env,
                    .{ .explicit = expr_region },
                );
            _ = try self.unify(expr_var, ext_instantiated_var, env);
        }
    } else {
        try self.markErroneous(expr_var);
    }
    return false;
}

noinline fn checkExprLookupAssociatedLocal(
    self: *Self,
