    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;

    try self.checkLocalAssociatedLookup(expr_idx, expr_var, lookup, expr_region, env);
    return false;
}

