noinline fn checkExprLookupRequired(
    self: *Self,
    frame: *ExprCheckFrame,
    req: @FieldType(CIR.Expr, "e_lookup_required"),
) std.mem.Allocator.Error!bool {
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;

    self.markCurrentHoistRuntimeDependency();
    // Look up the type from the platform's requires clause
    const requires_items = self.cir.requires_types.items.items;
    const idx = req.requires_idx.toU32();
    if (idx < requires_items.len) {
        const required_type = requires_items[idx];
        const type_var = ModuleEnv.varFrom(required_type.type_anno);
        const instantiated_var = try self.instantiateVar(
            type_var,
            env,
            .{ .explicit = expr_region },
        );
        _ = try self.unify(expr_var, instantiated_var, env);
    } else {
        try self.markErroneous(expr_var);
    }
    return false;
}

noinline fn checkExprBlock(
    self: *Self,
    frame: *ExprCheckFrame,
    block: @FieldType(CIR.Expr, "e_block"),
) std.mem.Allocator.Error!bool {
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    const nested_expected = frame.nested_expected;
    const is_call_arg = frame.is_call_arg;
    const is_immediate_callee = frame.is_immediate_callee;
    var does_fx = false;

    const hoist_scope = self.beginHoistLexicalScope();
    defer self.endHoistLexicalScope(hoist_scope);

    // Check all statements in the block
    const stmt_result = try self.checkBlockStatements(block.stmts, env, expr_region, nested_expected.forStatement());
    does_fx = stmt_result.does_fx or does_fx;

    // Check the final expression
    const final_expr_outcome = if (stmt_result.blocks_later_hoists)
        try self.checkExprInCallPosition(
            block.final_expr,
            env,
            nested_expected.suppressHoistSelection(),
            is_call_arg,
            is_immediate_callee,
        )
    else
        try self.checkExprInCallPosition(
            block.final_expr,
            env,
            nested_expected,
            is_call_arg,
            is_immediate_callee,
        );
    does_fx = final_expr_outcome.does_fx or does_fx;

    // If the block diverges (has a return/crash), use a flex var for the block's type
    // since the final expression is unreachable
    if (stmt_result.diverges) {
        try self.unifyWith(expr_var, .{ .flex = Flex.init() }, env);
    } else {
        // Link the root expr with the final expr
        _ = try self.unify(expr_var, ModuleEnv.varFrom(block.final_expr), env);
    }
    return does_fx;
}

noinline fn checkExprLambda(
    self: *Self,
    frame: *ExprCheckFrame,
    lambda: @FieldType(CIR.Expr, "e_lambda"),
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_var = frame.expr_var;
    const mb_anno_vars = frame.mb_anno_vars;
    const nested_expected = frame.nested_expected;
    const is_immediate_callee = frame.is_immediate_callee;

    const active_direct_binder_failures_start = self.active_direct_binder_failures.items.len;
    defer self.active_direct_binder_failures.shrinkRetainingCapacity(
        active_direct_binder_failures_start,
    );

    // Record the parameter span for the end-of-check pinnable
    // collection (see `checked_lambda_params`).
    try self.checked_lambda_params.append(self.gpa, lambda.args);

    // Then, even if we have an expected type, it may not actually be a function
    const mb_anno_func: ?types_mod.Func = blk: {
        if (mb_anno_vars) |anno_vars| {
            // Here, we unwrap the function, following aliases, to get
            // the actual function we want to check against
            var var_ = anno_vars.anno_var;
            var guard = types_mod.debug.IterationGuard.init("checkExpr.lambda.unwrapExpectedFunc");
            while (true) {
                guard.tick();
                switch (self.types.resolveVar(var_).desc.content) {
                    .structure => |flat_type| {
                        switch (flat_type) {
                            .fn_pure => |func| break :blk func,
                            .fn_unbound => |func| break :blk func,
                            .fn_effectful => |func| break :blk func,
                            .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => break :blk null,
                        }
                    },
                    .alias => |alias| {
                        var_ = self.types.getAliasBackingVar(alias);
                    },
                    .flex, .rigid, .field_presence, .err => break :blk null,
                }
            }
        } else {
            break :blk null;
        }
    };
    const anno_context = if (mb_anno_vars) |anno_vars| anno_vars.context else problem.Context.type_annotation;

    // Check the argument patterns
    // This must happen *before* checking against the expected type so
    // all the pattern types are inferred
    const arg_count = lambda.args.span.len;
    var arg_vars_sfa = std.heap.stackFallback(16 * @sizeOf(Var), self.gpa);
    const arg_vars_alloc = arg_vars_sfa.get();
    const arg_vars = try arg_vars_alloc.alloc(Var, arg_count);
    defer arg_vars_alloc.free(arg_vars);
    const pattern_ctx: PatternCtx = if (mb_anno_func != null) .from_annotation else .fn_arg;
    for (0..arg_count) |i| {
        const pattern_idx = self.cir.store.patternAt(lambda.args, i);
        arg_vars[i] = ModuleEnv.varFrom(pattern_idx);
        try self.checkPattern(pattern_idx, pattern_ctx, env);
    }

    // Now, check if we have an expected function to validate against
    if (mb_anno_func) |anno_func| {
        // Use index-based iteration instead of slices because unifyInContext
        // may trigger reallocations that would invalidate slice pointers
        const anno_func_args_range = anno_func.args;
        const anno_func_args_len = anno_func_args_range.len();

        // Next, check if the arguments arities match
        if (anno_func_args_len == arg_count) {
            // If so, check each argument, passing in the expected type

            // First, find all the rigid variables in a the function's type
            // and unify the matching corresponding lambda arguments together.
            for (0..anno_func_args_len) |i| {
                const anno_arg_1 = self.types.getVarAt(anno_func_args_range, @intCast(i));
                const anno_resolved_1 = self.types.resolveVar(anno_arg_1);

                // The expected type is an annotation and as such,
                // should never contain a flex var. If it did, that
                // would indicate that the annotation is malformed
                // std.debug.assert(expected_resolved_1.desc.content != .flex);

                // Skip any concrete arguments
                if (anno_resolved_1.desc.content != .rigid) {
                    continue;
                }

                // Look for other arguments with the same type variable
                for (i + 1..anno_func_args_len) |j| for_blk: {
                    const anno_arg_2 = self.types.getVarAt(anno_func_args_range, @intCast(j));
                    const anno_resolved_2 = self.types.resolveVar(anno_arg_2);
                    if (anno_resolved_1.var_ == anno_resolved_2.var_) {
                        // These two argument indexes in the called *function's*
                        // type have the same rigid variable! So, we unify
                        // the corresponding *lambda args*

                        const arg_1 = arg_vars[i];
                        const arg_2 = arg_vars[j];

                        const unify_result = try self.unifyInContext(arg_1, arg_2, env, .{
                            .fn_args_bound_var = .{
                                .fn_name = self.enclosing_func_name,
                                .first_arg_var = arg_1,
                                .second_arg_var = arg_2,
                                .first_arg_index = @intCast(i),
                                .second_arg_index = @intCast(j),
                                .num_args = @intCast(arg_count),
                            },
                        });
                        if (unify_result.isProblem()) {
                            // Context already set by unifyInContext
                            // Stop execution
                            try self.markErroneous(expr_var);
                            break :for_blk;
                        }
                    }
                }
            }

            // Then, lastly, we unify the annotation types against the
            // actual type
            for (arg_vars, 0..) |arg_var, i| {
                const expected_arg_var = self.types.getVarAt(anno_func_args_range, @intCast(i));
                _ = try self.unifyInContext(expected_arg_var, arg_var, env, anno_context);
            }
        } else {
            // This means the expected type and the actual lambda have
            // an arity mismatch. This will be caught by the regular
            // expectation checking code at the bottom of this function
        }
    }

    try self.activateDirectBinderFailuresForLambda(.{
        .annotation_idx = frame.annotation_idx,
        .sources_start = frame.direct_formal_failure_sources_start,
        .owns_sources = frame.owns_direct_formal_failure_sources,
    }, expr_idx);

    const body_var = ModuleEnv.varFrom(lambda.body);

    // Check the the body of the expr
    // If we have an expected function, use that as the expr's expected type
    const exhaustiveness_scope = self.exhaustiveness_context.resetForRuntimeFunction();
    defer exhaustiveness_scope.leave();

    const body_is_delayed_dependency = !is_immediate_callee;
    if (body_is_delayed_dependency) self.delayed_dependency_depth += 1;
    defer {
        if (body_is_delayed_dependency) self.delayed_dependency_depth -= 1;
    }

    const lambda_body_expected = Expected.none().withHoistPosition(nested_expected.hoist_position);
    const expected_result: ?Expected.ExpectedType = if (mb_anno_func) |expected_func| blk: {
        const parent_expected = nested_expected.expected_type orelse
            std.debug.panic("materialized expected function lost its root expectation", .{});
        const marker_authority: ExpectedMarkerAuthority = switch (parent_expected.marker_authority) {
            .anchored => |parent_authority| .{ .anchored = .{ .copy_occurrence = switch (parent_authority) {
                .copy_occurrence => |parent_anchor| self.expectedMarkerChildAnchorForEdge(
                    parent_anchor,
                    .function_return,
                    0,
                    0,
                    null,
                ) orelse std.debug.panic(
                    "expected function return was absent from its parent copy proof",
                    .{},
                ),
                .producer_root => std.debug.panic(
                    "a producer-root Expected entered function-result proof projection",
                    .{},
                ),
                .evidence_free_plan => std.debug.panic(
                    "an evidence-free plan entered anchored function-result projection",
                    .{},
                ),
                .relation_plan => std.debug.panic(
                    "a branch relation plan entered anchored function-result projection",
                    .{},
                ),
            } } },
            .evidence_free => |authority| evidence_free: {
                try self.assertExpectedEvidenceFree(parent_expected.var_, authority);
                var plan_transaction = try self.beginLocalMarkerCopyTransaction(env);
                defer plan_transaction.rollback();
                var return_slots = [_]ExpectedFreshShapeSlot{try self.reserveExpectedFreshShapeSlot(
                    expr_idx,
                    lambda.body,
                    .lambda_return,
                    0,
                    expected_func.ret,
                )};
                self.completeExpectedFreshShapeSlotsEvidenceFree(&return_slots, authority);
                plan_transaction.commit();
                break :evidence_free .{ .evidence_free = .{
                    .plan_index = return_slots[0].expected_plan,
                    .raw_var = expected_func.ret,
                } };
            },
        };
        if (marker_authority == .anchored) {
            if (self.expectedParentAuthorityRawVar(marker_authority.anchored) != expected_func.ret) {
                std.debug.panic("expected function return did not match its exact proof edge", .{});
            }
        }
        break :blk .{
            .var_ = expected_func.ret,
            .context = anno_context,
            .marker_authority = marker_authority,
            .status = parent_expected.status,
        };
    } else null;
    if (expected_result) |result_expected| {
        const resolved_expected = self.types.resolveVar(result_expected.var_);
        if (result_expected.status == .established and resolved_expected.desc.content == .err) {
            std.debug.panic(
                "lambda authored established status for an erroneous return Expected",
                .{},
            );
        }
    }
    try self.pushReturnConstraintFrame(expr_idx, body_var, expected_result);
    var return_constraints_processed = false;
    defer if (!return_constraints_processed) self.discardReturnConstraintFrame(expr_idx);

    const effect_dependencies_start = self.pending_function_effect_dependencies.items.len;
    try self.function_effect_dependency_frame_starts.append(self.gpa, effect_dependencies_start);
    defer {
        _ = self.function_effect_dependency_frame_starts.pop();
        self.pending_function_effect_dependencies.shrinkRetainingCapacity(effect_dependencies_start);
    }

    const body_does_fx = if (mb_anno_func) |expected_func| blk: {
        const lambda_body_outcome = try self.checkExpr(
            lambda.body,
            env,
            lambda_body_expected.withBranchResult(expected_result.?),
        );
        try self.closeAbsentConstructedPayloadVars(lambda.body, body_var);
        const body_result = try self.unifyInContext(expected_func.ret, body_var, env, anno_context);
        if (body_result.isProblem()) {
            try self.erroneous_value_exprs.put(self.gpa, lambda.body, {});
        }
        break :blk lambda_body_outcome.does_fx;
    } else blk: {
        const lambda_body_outcome = try self.checkExpr(lambda.body, env, lambda_body_expected);
        try self.closeAbsentConstructedPayloadVars(lambda.body, body_var);
        break :blk lambda_body_outcome.does_fx;
    };

    // Process any pending return constraints (from early returns / ? operator) before
    // creating the function type. This must happen after the body is fully checked
    // (for correct error reporting) but before the function type is generalized
    // (so instantiated copies at call sites have the complete type, including
    // both Ok and Err variants from the ? operator).
    try self.processReturnConstraints(env, expr_idx);
    return_constraints_processed = true;

    // NOTE: no occurs check here. Infinite/anonymous-recursive types
    // are detected at binding roots (top-level defs, local bindings,
    // REPL roots)—a cyclic type constructed while checking this
    // body is reachable from the enclosing binding's root type, and
    // running occurs per syntactic lambda re-traversed the whole body
    // type graph once per nesting level.

    // A dependency may already have become positive while checking a
    // later argument or definition. Materialize that result before
    // unifying with an annotation; only genuinely unresolved formulas
    // remain attached to an unbound function type.
    var body_is_effectful = body_does_fx;
    if (!body_is_effectful) {
        for (self.pending_function_effect_dependencies.items[effect_dependencies_start..]) |dependency| {
            if (try self.functionEffectState(dependency) == .effectful) {
                body_is_effectful = true;
                break;
            }
        }
    }

    // Create the function type
    if (body_is_effectful) {
        try self.effectful_lambda_bodies.put(expr_idx, {});
        try self.unifyWith(expr_var, try self.types.mkFuncEffectful(arg_vars, body_var), env);
    } else {
        try self.unifyWith(
            expr_var,
            try self.types.mkFuncUnboundWithEffectDeps(
                arg_vars,
                body_var,
                self.pending_function_effect_dependencies.items[effect_dependencies_start..],
            ),
            env,
        );
    }

    // Note that so far, we have not yet unified against the
    // annotation's effectfulness/pureness. This is intentional!
    // Below this large switch statement, there's the regular expr
    // <-> expected unification. This will catch any difference in
    // effectfullness, and it'll link the root expected var with the
    // expr_var
    return false;
}

noinline fn checkExprClosure(
    self: *Self,
    frame: *ExprCheckFrame,
    closure: @FieldType(CIR.Expr, "e_closure"),
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_var_raw = frame.expr_var_raw;
    const expr_var = frame.expr_var;
    const nested_expected = frame.nested_expected;
    const is_call_arg = frame.is_call_arg;
    const is_immediate_callee = frame.is_immediate_callee;
    const suppress_group_member_generalize = frame.suppress_group_member_generalize;
    var does_fx = false;

    // Here, we must forward the expected valued to the inner lambda, so
    // the annotation type is created at the same rank as the expr.
    // A closure is only the capture wrapper around its inner lambda, so
    // the lambda inherits this closure's call-arg status: an argument
    // lambda must NOT be generalized, or its body's static-dispatch chain
    // would be quantified before the caller pins the parameter types,
    // leaving the original (un-instantiated) dispatch nodes unresolved.
    // A group member's RHS suppression applies to the lambda the
    // closure wraps, exactly like the call-arg status above.
    if (suppress_group_member_generalize) {
        self.suppress_generalize_expr = closure.lambda_idx;
    }
    const lambda_outcome = try self.checkExprInCallPosition(
        closure.lambda_idx,
        env,
        nested_expected,
        is_call_arg,
        is_immediate_callee,
    );
    does_fx = lambda_outcome.does_fx or does_fx;
    switch (lambda_outcome.status) {
        .established => {},
        .checked_error => |cause| switch (frame.checked_status) {
            .established => frame.checked_status = .{ .checked_error = cause },
            .checked_error => |existing| if (!expectedCauseOwnersEqual(existing, cause)) {
                std.debug.panic("closure wrapper changed its lambda's exact checked-error cause", .{});
            },
        },
    }
    // The inner lambda owns generalization, while every source lookup
    // names the closure wrapper. Register that explicit source-level
    // alias instead of recovering the relationship from the mutable
    // union-find representative later.
    try self.bindTypeSchemeVar(ModuleEnv.varFrom(closure.lambda_idx), expr_var_raw);
    // The closure is the executable function-value expression. If its
    // delegated lambda check failed as a whole, poison the closure so
    // the lambda remains a valid structural child until the closure is
    // replaced with a runtime error.
    if (self.erroneous_value_exprs.remove(closure.lambda_idx) and
        lambda_outcome.status == .established)
    {
        try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
    }
    const lambda_var = ModuleEnv.varFrom(closure.lambda_idx);

    _ = try self.unify(expr_var, lambda_var, env);
    return does_fx;
}

noinline fn checkExprCall(
    self: *Self,
    frame: *ExprCheckFrame,
    call: @FieldType(CIR.Expr, "e_call"),
    child_expected: Expected,
) std.mem.Allocator.Error!bool {
    const expr_idx = frame.expr_idx;
    const env = frame.env;
    const expr_region = frame.expr_region;
    const expr_var = frame.expr_var;
    var does_fx = false;

    switch (call.called_via) {
        .apply, .record_builder => blk: {
            const call_kind = expectedCallKindFromBase(call.called_via) orelse unreachable;
            const call_arg_expr_idxs = self.cir.store.sliceExpr(call.args);
            const call_root_token_index = expectedCallSlotTokenIndex(
                self.cir,
                @intFromEnum(expr_idx),
                .root,
                ModuleEnv.ExpectedCallSlotToken.none,
            ) orelse std.debug.panic(
                "call producer had no unique canonical root token",
                .{},
            );
            const call_root_token = self.cir.expected_call_slot_tokens.items.items[
                call_root_token_index
            ];
            if (!call_root_token.hasCanonicalTags() or
                call_root_token.decodedRole() != .root or
                call_root_token.owner_node != @intFromEnum(expr_idx) or
                call_root_token.site_node != @intFromEnum(call.func) or
                call_root_token.cardinality != @as(u32, @intCast(call_arg_expr_idxs.len)) or
                call_root_token.decodedCalledVia() != call_kind)
            {
                std.debug.panic("call producer disagreed with its canonical root token", .{});
            }

            // First, check the function being called
            // It could be effectful, e.g. `(mk_fn!())(arg)`
            self.checking_call_arg = true;
            self.checking_immediate_callee = true;
            const callee_outcome = check_callee: {
                const previous_call_root_token = self.checking_immediate_call_root_token;
                self.checking_immediate_call_root_token = call_root_token_index;
                defer self.checking_immediate_call_root_token = previous_call_root_token;
                break :check_callee try self.checkExpr(call.func, env, child_expected);
            };
            does_fx = callee_outcome.does_fx or does_fx;
            const call_func_expr_var = ModuleEnv.varFrom(call.func);

            // If the function was generalized (e.g. an immediately-invoked
            // lambda `(|x| ...)(arg)`), instantiate it so the call site gets
            // fresh type variables. Without this, the generalized vars would
            // be unified directly with concrete arg types, which can leak
            // generalization into the enclosing function's types.
            var instantiation_copy_step: ?u32 = null;
            var instantiation_source_var: ?Var = null;
            const func_var = if (callee_outcome.callee_instantiation) |authority| consumed: {
                if (authority.call_root_token_index != call_root_token_index or
                    authority.copy_step >= self.cir.where_marker_copy_steps.items.items.len or
                    authority.raw_callee_var != call_func_expr_var)
                {
                    std.debug.panic("call consumed another callee's instantiation authority", .{});
                }
                const authority_step = self.cir.where_marker_copy_steps.items.items[
                    authority.copy_step
                ];
                if (authority_step.decodedKind() != .expected_call_instantiation or
                    authority_step.origin.expected_call_instantiation.call_root_token_index !=
                        call_root_token_index or
                    authority_step.root_occurrence_offset != authority.root_occurrence or
                    authority.root_occurrence >= authority_step.occurrences_len)
                {
                    std.debug.panic("call consumed a stale callee instantiation occurrence", .{});
                }
                const authority_root = self.cir.where_marker_copy_occurrences.items.items[
                    authority_step.occurrences_start + authority.root_occurrence
                ];
                if (authority_root.raw_source_var != @intFromEnum(authority.raw_source_var) or
                    authority_root.raw_destination_var != @intFromEnum(authority.raw_destination_var))
                {
                    std.debug.panic("call consumed a retargeted callee instantiation root", .{});
                }
                instantiation_copy_step = authority.copy_step;
                instantiation_source_var = authority.raw_source_var;
                break :consumed authority.raw_destination_var;
            } else blk_instantiate: {
                const resolved = self.types.resolveVar(call_func_expr_var);
                if (resolved.desc.rank == Rank.generalized or self.isBindingSchemeVar(call_func_expr_var)) {
                    const saved_instantiation_is_immediate_callee = self.instantiation_is_immediate_callee;
                    self.instantiation_is_immediate_callee = true;
                    defer self.instantiation_is_immediate_callee = saved_instantiation_is_immediate_callee;
                    const instantiated = try self.instantiateExpectedCallBindingVar(
                        call_func_expr_var,
                        env,
                        .use_last_var,
                        .{
                            .call_root_token_index = call_root_token_index,
                            .source_kind = @intFromEnum(ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.SourceKind.local_callee_expression),
                            .source_owner_node = @intFromEnum(call.func),
                            .source_support_step = ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
                            .source_seed_index = ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.none,
                        },
                    );
                    instantiation_copy_step = instantiated.copy_step;
                    instantiation_source_var = call_func_expr_var;
                    break :blk_instantiate instantiated.var_;
                } else {
                    break :blk_instantiate call_func_expr_var;
                }
            };
            const func_name: ?Ident.Idx = self.getExprPatternIdent(call.func);

            // Determine whether a concrete callee already fixes arity,
            // solely to select the arity diagnostic for the call-shape
            // relation below. The relation itself is uniform for known
            // functions, aliases, and still-flex callables.
            const KnownCallShape = struct {
                func: types_mod.Func,
                content: types_mod.Content,
            };
            const mb_known_func: ?KnownCallShape = known: {
                var var_ = func_var;
                var guard = types_mod.debug.IterationGuard.init("checkExpr.call.knownFunc");
                while (true) {
                    guard.tick();
                    const content = self.types.resolveVar(var_).desc.content;
                    switch (content) {
                        .structure => |flat_type| switch (flat_type) {
                            .fn_pure, .fn_unbound, .fn_effectful => |func| break :known .{
                                .func = func,
                                .content = content,
                            },
                            .record,
                            .record_unbound,
                            .tuple,
                            .nominal_type,
                            .empty_record,
                            .tag_union,
                            .empty_tag_union,
                            => break :known null,
                        },
                        .alias => |alias| var_ = self.types.getAliasBackingVar(alias),
                        .flex, .rigid, .field_presence, .err => break :known null,
                    }
                }
            };

            // A known function already is the arity-shaped constraint
            // for this call, so use its formal slots directly. A flex
            // or non-function callee gets one fresh call shape before
            // argument checking; a known arity mismatch gets the same
            // shape solely to record the existing arity diagnostic.
            // In the matching case, shared formal variables naturally
            // flow through the left-to-right argument fold, replacing
            // the previous pairwise O(n^2) scan.
            var fresh_call_shape_var: ?Var = null;
            const call_shape: struct {
                func: types_mod.Func,
                result: unifier.Result,
            } = shape: {
                if (mb_known_func) |known| {
                    if (known.func.args.len() == call_arg_expr_idxs.len) {
                        break :shape .{ .func = known.func, .result = .unified };
                    }
                }

                const expected_args_top = self.scratch_vars.top();
                defer self.scratch_vars.clearFrom(expected_args_top);
                for (call_arg_expr_idxs) |_| {
                    try self.scratch_vars.append(try self.fresh(env, expr_region));
                }
                const expected_arg_vars = try self.types.appendVars(self.scratch_vars.sliceFromStart(expected_args_top));
                const call_func_ret = try self.fresh(env, expr_region);
                const call_func = types_mod.Func{
                    .args = expected_arg_vars,
                    .ret = call_func_ret,
                    .effect_deps = Var.SafeList.Range.empty(),
                };
                const call_func_var = try self.freshFromContent(.{ .structure = .{
                    .fn_unbound = call_func,
                } }, env, expr_region);
                fresh_call_shape_var = call_func_var;
                const call_shape_context: problem.Context = if (mb_known_func) |known|
                    .{ .fn_call_arity = .{
                        .fn_name = func_name,
                        .expected_args = @intCast(known.func.args.len()),
                        .actual_args = @intCast(call_arg_expr_idxs.len),
                    } }
                else
                    .none;
                break :shape .{
                    .func = call_func,
                    .result = try self.unifyOwnedRelation(
                        func_var,
                        call_func_var,
                        env,
                        call_shape_context,
                        .exact,
                    ),
                };
            };

            var argument_statuses_sfa = std.heap.stackFallback(
                16 * @sizeOf(CheckedExprStatus),
                self.gpa,
            );
            const argument_statuses_allocator = argument_statuses_sfa.get();
            const argument_statuses = try argument_statuses_allocator.alloc(
                CheckedExprStatus,
                call_arg_expr_idxs.len,
            );
            defer argument_statuses_allocator.free(argument_statuses);

            var call_expected_support: ?CallExpectedSupport = null;
            defer if (call_expected_support) |support| {
                self.gpa.free(support.argument_plans);
            };
            if (call_shape.result.isEstablished()) {
                // The root row and every argument row form one producer
                // publication. Each argument row is itself the exact
                // authority for its raw formal; there is deliberately no
                // identity-copy bridge whose topology could go stale.
                var support_transaction = try self.beginLocalMarkerCopyTransaction(env);
                defer support_transaction.rollback();
                try self.cir.expected_call_formals.items.ensureUnusedCapacity(
                    self.gpa,
                    call_arg_expr_idxs.len,
                );
                const call_root_plan = try self.reserveExpectedCallPlan(
                    expr_idx,
                    call.func,
                    .call_root,
                    0,
                    call_func_expr_var,
                );
                const argument_plans = try self.gpa.alloc(u32, call_arg_expr_idxs.len);
                var argument_plans_owned = true;
                errdefer if (argument_plans_owned) self.gpa.free(argument_plans);

                // Reserve the complete call-shape plan before any row
                // becomes a first-class Expected producer root.
                for (call_arg_expr_idxs, argument_plans, 0..) |argument_expr, *argument_plan, arg_index| {
                    argument_plan.* = try self.reserveExpectedCallPlan(
                        expr_idx,
                        argument_expr,
                        .call_argument,
                        @intCast(arg_index),
                        self.types.getVarAt(call_shape.func.args, @intCast(arg_index)),
                    );
                }

                const immutable_exposure_var: ?Var = if (call_arg_expr_idxs.len != 0 and
                    fresh_call_shape_var == null and instantiation_copy_step == null)
                    try self.freshImmutableProofRoot(
                        mb_known_func.?.content,
                        env.rank(),
                        expr_region,
                    )
                else
                    null;
                self.completeExpectedCallRootPlan(call_root_plan);
                for (argument_plans, 0..) |argument_plan, arg_index| {
                    self.completeExpectedCallArgumentPlan(
                        argument_plan,
                        call_root_plan,
                    );
                    const raw_slot: u32 = @intCast(arg_index);
                    const raw_formal = self.types.getVarAt(call_shape.func.args, raw_slot);
                    const slot_token_index = expectedCallSlotTokenIndex(
                        self.cir,
                        @intFromEnum(expr_idx),
                        .argument,
                        raw_slot,
                    ) orelse std.debug.panic(
                        "call formal had no unique canonical slot token",
                        .{},
                    );
                    const slot_token = self.cir.expected_call_slot_tokens.items.items[
                        slot_token_index
                    ];
                    if (!slot_token.hasCanonicalTags() or
                        slot_token.decodedRole() != .argument or
                        slot_token.owner_node != @intFromEnum(expr_idx) or
                        slot_token.site_node != @intFromEnum(call_arg_expr_idxs[arg_index]) or
                        slot_token.slot != raw_slot or
                        slot_token.cardinality != @as(u32, @intCast(call_arg_expr_idxs.len)) or
                        slot_token.decodedCalledVia() != call_kind)
                    {
                        std.debug.panic("call formal disagreed with its canonical slot token", .{});
                    }

                    const formal_origin: ModuleEnv.ExpectedCallFormal.FormalOrigin = if (fresh_call_shape_var != null)
                        .fresh_arity_shape
                    else if (instantiation_copy_step != null)
                        .explicitly_instantiated
                    else
                        .direct_monomorphic_or_alias;
                    const instantiation_root_occurrence = if (instantiation_copy_step) |copy_step|
                        self.cir.where_marker_copy_steps.items.items[copy_step].root_occurrence_offset
                    else
                        ModuleEnv.ExpectedCallFormal.none;
                    const instantiation_formal_occurrence = if (formal_origin == .explicitly_instantiated)
                        self.expectedCallFormalOccurrenceForPublishedStep(
                            instantiation_copy_step.?,
                            raw_slot,
                        )
                    else
                        ModuleEnv.ExpectedCallFormal.none;
                    if (instantiation_formal_occurrence != ModuleEnv.ExpectedCallFormal.none) {
                        const copy_step = self.cir.where_marker_copy_steps.items.items[
                            instantiation_copy_step.?
                        ];
                        const occurrence = self.cir.where_marker_copy_occurrences.items.items[
                            copy_step.occurrences_start + instantiation_formal_occurrence
                        ];
                        if (occurrence.raw_destination_var != @intFromEnum(raw_formal)) {
                            std.debug.panic("call instantiation formal witness named another destination", .{});
                        }
                    }
                    const fresh_effect_deps_start = if (call_shape.func.effect_deps.len() == 0)
                        ModuleEnv.ExpectedCallFormal.none
                    else
                        @intFromEnum(call_shape.func.effect_deps.start);
                    _ = self.cir.expected_call_formals.appendAssumeCapacity(.{
                        .owner_node = @intFromEnum(expr_idx),
                        .call_root_plan_index = call_root_plan,
                        .argument_plan_index = argument_plan,
                        .call_root_token_index = call_root_token_index,
                        .slot_token_index = slot_token_index,
                        .raw_callee_var = @intFromEnum(call_func_expr_var),
                        .instantiation_source_var = if (instantiation_source_var) |source_var| @intFromEnum(source_var) else ModuleEnv.ExpectedCallFormal.none,
                        .raw_callable_var = @intFromEnum(func_var),
                        .fresh_shape_var = if (fresh_call_shape_var) |fresh_shape| @intFromEnum(fresh_shape) else ModuleEnv.ExpectedCallFormal.none,
                        .slot = raw_slot,
                        .raw_formal_var = @intFromEnum(raw_formal),
                        .immutable_exposure_var = if (immutable_exposure_var) |exposure| @intFromEnum(exposure) else ModuleEnv.ExpectedCallFormal.none,
                        .instantiation_copy_step = instantiation_copy_step orelse ModuleEnv.ExpectedCallFormal.none,
                        .instantiation_root_occurrence = instantiation_root_occurrence,
                        .instantiation_formal_occurrence = instantiation_formal_occurrence,
                        .fresh_args_start = if (fresh_call_shape_var != null) @intFromEnum(call_shape.func.args.start) else ModuleEnv.ExpectedCallFormal.none,
                        .fresh_args_len = if (fresh_call_shape_var != null) call_shape.func.args.len() else 0,
                        .fresh_ret_var = if (fresh_call_shape_var != null) @intFromEnum(call_shape.func.ret) else ModuleEnv.ExpectedCallFormal.none,
                        .fresh_effect_deps_start = if (fresh_call_shape_var != null) fresh_effect_deps_start else ModuleEnv.ExpectedCallFormal.none,
                        .fresh_effect_deps_len = if (fresh_call_shape_var != null) call_shape.func.effect_deps.len() else 0,
                        .called_via = @intFromEnum(call_kind),
                        .shape_kind = @intFromEnum(if (fresh_call_shape_var != null)
                            ModuleEnv.ExpectedCallFormal.ShapeKind.fresh_arity_shape
                        else
                            ModuleEnv.ExpectedCallFormal.ShapeKind.existing_callable),
                        .formal_origin = @intFromEnum(formal_origin),
                    });
                }
                support_transaction.commit();
                call_expected_support = .{
                    .root_plan = call_root_plan,
                    .argument_plans = argument_plans,
                };
                argument_plans_owned = false;
            }

            // Check every argument against its formal slot's
            // structural shape. The owned relations are committed in
            // a second linear fold, after all argument expressions
            // have checked, preserving error isolation between sibling
            // operands.
            for (call_arg_expr_idxs, 0..) |call_arg_idx, arg_index| {
                const arg_context = problem.Context{ .fn_call_arg = .{
                    .fn_name = func_name,
                    .call_expr = expr_idx,
                    .arg_index = @intCast(arg_index),
                    .num_args = @intCast(call_arg_expr_idxs.len),
                    .arg_var = ModuleEnv.varFrom(call_arg_idx),
                } };
                const arg_expected = if (call_expected_support) |support| expected: {
                    const raw_formal = self.types.getVarAt(
                        call_shape.func.args,
                        @intCast(arg_index),
                    );
                    const formal_expected: Expected.ExpectedType = .{
                        .var_ = raw_formal,
                        .context = arg_context,
                        .marker_authority = .{ .anchored = .{ .producer_root = .{
                            .plan_index = support.argument_plans[arg_index],
                            .raw_var = raw_formal,
                        } } },
                        .status = .established,
                    };
                    break :expected child_expected
                        .withContextualType(formal_expected)
                        .withBranchResult(formal_expected);
                } else child_expected;

                self.checking_call_arg = true;
                self.checking_immediate_callee = false;
                const argument_outcome = try self.checkExpr(call_arg_idx, env, arg_expected);
                argument_statuses[arg_index] = argument_outcome.status;
                does_fx = argument_outcome.does_fx or does_fx;
            }

            const call_operand_failure_cause: ?ModuleEnv.CauseOwner = if (call_expected_support) |support|
                try self.publishCallOperandCheckedErrors(
                    expr_idx,
                    call,
                    call_shape.func,
                    support,
                    argument_statuses,
                )
            else
                null;
            if (call_operand_failure_cause) |cause| {
                switch (frame.checked_status) {
                    .established => frame.checked_status = .{ .checked_error = cause },
                    .checked_error => |existing| if (!expectedCauseOwnersEqual(existing, cause)) {
                        std.debug.panic("a call changed its exact operand-retirement cause", .{});
                    },
                }
            }

            var arg_relation_failed = false;
            if (call_shape.result.isEstablished() and
                call_operand_failure_cause == null and
                !self.callLikeOperandsContainErroneousValue(call_arg_expr_idxs))
            {
                for (call_arg_expr_idxs, 0..) |call_arg_idx, arg_index| {
                    const expected_arg_var = self.types.getVarAt(call_shape.func.args, @intCast(arg_index));
                    const arg_context = problem.Context{ .fn_call_arg = .{
                        .fn_name = func_name,
                        .call_expr = expr_idx,
                        .arg_index = @intCast(arg_index),
                        .num_args = @intCast(call_arg_expr_idxs.len),
                        .arg_var = ModuleEnv.varFrom(call_arg_idx),
                    } };
                    const arg_result = try self.unifyOwnedRelation(
                        expected_arg_var,
                        ModuleEnv.varFrom(call_arg_idx),
                        env,
                        arg_context,
                        if (self.exprIsFreshRecordConstruction(call_arg_idx)) .construction else .exact,
                    );
                    arg_relation_failed = arg_result.isProblem();
                    if (arg_relation_failed) break;
                }
            }

            const args_did_err = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, call_arg_expr_idxs);
            if (call_shape.result.isProblem()) {
                // The call owns the callable/arity diagnostic, but its
                // result slot remains a valid continuation type. Keep
                // that type graph intact while lowering replaces only
                // this call with a runtime error.
                try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
            }
            const func_is_err = self.types.resolveVar(func_var).desc.content == .err;
            const did_err = func_is_err or
                arg_relation_failed or
                args_did_err or
                call_operand_failure_cause != null;

            if (did_err) {
                try self.retireCallLikeExpr(expr_idx, expr_var);
            } else {
                if (call.called_via == .record_builder and call_shape.result.isEstablished()) {
                    const result = try self.enforceRecordBuilderMap2Return(call_shape.func, env, expr_idx, func_name);
                    if (result.isProblem()) {
                        try self.markErroneous(expr_var);
                        try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
                        break :blk;
                    }
                }

                _ = try self.unify(expr_var, call_shape.func.ret, env);

                // Argument unification above is the point at which an
                // effect-polymorphic callback can become pure or
                // effectful. Resolve the directed formula now, never from
                // the pre-unification function tag.
                const call_effect_state: FunctionEffectState = if (self.callTargetIsInFlightRecursiveRef(call.func)) recursive_effect: {
                    // A declared pure/effectful tag on an in-flight
                    // recursive scheme must not seed the body's
                    // fixpoint. An inferred unbound slot, however, is a
                    // real directed edge between SCC members and must
                    // survive until the boundary resolves the group.
                    const recursive_func = self.types.resolveVar(func_var).desc.content;
                    break :recursive_effect switch (recursive_func) {
                        .structure => |flat| switch (flat) {
                            .fn_unbound => .unresolved,
                            .fn_pure, .fn_effectful => .pure,
                            .record,
                            .record_unbound,
                            .tuple,
                            .nominal_type,
                            .empty_record,
                            .tag_union,
                            .empty_tag_union,
                            => .unresolved,
                        },
                        .flex, .rigid, .alias, .field_presence, .err => .unresolved,
                    };
                } else try self.functionEffectState(func_var);
                switch (call_effect_state) {
                    .effectful => does_fx = true,
                    .unresolved => try self.recordCurrentFunctionEffectDependency(func_var),
                    .pure => {},
                }

                const published_constraint_args: []Var = @ptrCast(call_arg_expr_idxs);
                const published_constraint_func = Func{
                    .args = try self.types.appendVars(published_constraint_args),
                    .ret = expr_var,
                    .effect_deps = if (call_effect_state == .unresolved)
                        try self.types.appendVars(&.{func_var})
                    else
                        Var.SafeList.Range.empty(),
                };
                const published_constraint_flat: FlatType = switch (call_effect_state) {
                    .effectful => .{ .fn_effectful = published_constraint_func },
                    .pure => .{ .fn_pure = published_constraint_func },
                    .unresolved => .{ .fn_unbound = published_constraint_func },
                };
                const published_constraint_fn_var = try self.freshFromContent(.{ .structure = published_constraint_flat }, env, expr_region);

                try self.cir.store.replaceExprWithCallConstraint(
                    expr_idx,
                    call.func,
                    call.args,
                    call.called_via,
                    published_constraint_fn_var,
                );
            }
        },
        .binop, .unary_op, .string_interpolation => {
            // The canonicalizer currently only produces apply, record_builder, or range for e_call expressions.
            // Other call types (binop, unary_op, string_interpolation) are
            // represented as different expression types. If we hit this, there's a compiler bug.
            std.debug.assert(false);
            try self.markErroneous(expr_var);
        },
    }
    return does_fx;
}

