            checker.cir.selected_receiver_anchors.items.capacity,
        );
        try self.constraint_evidence_moves.expectUnchanged(
            checker.cir.constraint_evidence_moves.items.items,
            checker.cir.constraint_evidence_moves.items.capacity,
        );
        try self.selected_method_decision_moves.expectUnchanged(
            checker.cir.selected_method_decision_moves.items.items,
            checker.cir.selected_method_decision_moves.items.capacity,
        );
        try self.expected_consumption_plans.expectUnchanged(
            checker.cir.expected_consumption_plans.items.items,
            checker.cir.expected_consumption_plans.items.capacity,
        );
        try self.expected_failures.expectUnchanged(
            checker.cir.expected_failures.items.items,
            checker.cir.expected_failures.items.capacity,
        );
        try self.expected_consumer_retirements.expectUnchanged(
            checker.cir.expected_consumer_retirements.items.items,
            checker.cir.expected_consumer_retirements.items.capacity,
        );
        try self.expected_retirement_failures.expectUnchanged(
            checker.cir.expected_retirement_failures.items.items,
            checker.cir.expected_retirement_failures.items.capacity,
        );
        try self.expected_retired_consumers.expectUnchanged(
            checker.cir.expected_retired_consumers.items.items,
            checker.cir.expected_retired_consumers.items.capacity,
        );
        try self.malformed_expression_publications.expectUnchanged(
            checker.cir.malformed_expression_publications.items.items,
            checker.cir.malformed_expression_publications.items.capacity,
        );
        try self.malformed_type_annotation_publications.expectUnchanged(
            checker.cir.malformed_type_annotation_publications.items.items,
            checker.cir.malformed_type_annotation_publications.items.capacity,
        );
        try self.body_annotation_malformed_type_publications.expectUnchanged(
            checker.cir.body_annotation_malformed_type_publications.items.items,
            checker.cir.body_annotation_malformed_type_publications.items.capacity,
        );
        try self.body_annotation_attachments.expectUnchanged(
            checker.cir.body_annotation_attachments.items.items,
            checker.cir.body_annotation_attachments.items.capacity,
        );
        try self.expected_ambiguity_retirements.expectUnchanged(
            checker.cir.expected_ambiguity_retirements.items.items,
            checker.cir.expected_ambiguity_retirements.items.capacity,
        );
        try self.expected_call_formals.expectUnchanged(
            checker.cir.expected_call_formals.items.items,
            checker.cir.expected_call_formals.items.capacity,
        );
        try self.expected_call_slot_tokens.expectUnchanged(
            checker.cir.expected_call_slot_tokens.items.items,
            checker.cir.expected_call_slot_tokens.items.capacity,
        );
        try self.external_lookup_tokens.expectUnchanged(
            checker.cir.external_lookup_tokens.items.items,
            checker.cir.external_lookup_tokens.items.capacity,
        );
        try self.external_cache_seeds.expectUnchanged(
            checker.cir.external_cache_seeds.items.items,
            checker.cir.external_cache_seeds.items.capacity,
        );
    }

    /// Probe rollback may retain capacity obtained before a later allocation
    /// failed. The logical checked-boundary rows nevertheless remain exact.
    fn expectSameItems(
        self: *const @This(),
        gpa: Allocator,
        checker: *const Self,
    ) !void {
        var current = try @This().capture(gpa, checker);
        defer current.deinit(gpa);
        inline for (std.meta.fields(@This())) |field| {
            const expected = &@field(self, field.name);
            const actual = &@field(current, field.name);
            try expected.expectSameSnapshotItems(actual);
        }
    }

    fn deinit(self: *@This(), gpa: Allocator) void {
        self.static_dispatch_constraints.deinit(gpa);
        self.constraint_evidence_handles.deinit(gpa);
        self.type_marker_contracts.deinit(gpa);
        self.type_marker_bases.deinit(gpa);
        self.type_marker_path_steps.deinit(gpa);
        self.copy_steps.deinit(gpa);
        self.copy_pairs.deinit(gpa);
        self.copy_witnesses.deinit(gpa);
        self.copied_literal_groups.deinit(gpa);
        self.copied_literal_events.deinit(gpa);
        self.platform_substitutions.deinit(gpa);
        self.constraint_moves.deinit(gpa);
        self.constraint_move_offsets.deinit(gpa);
        self.cir_marker_path_steps.deinit(gpa);
        self.result_row_widening_uses.deinit(gpa);
        self.where_method_sources.deinit(gpa);
        self.where_alias_expansions.deinit(gpa);
        self.binding_scheme_codec_requirements.deinit(gpa);
        self.where_method_marker_uses.deinit(gpa);
        self.constraint_copy_pairs.deinit(gpa);
        self.copy_occurrences.deinit(gpa);
        self.default_decisions.deinit(gpa);
        self.default_decision_contributors.deinit(gpa);
        self.for_loop_dispatch_plans.deinit(gpa);
        self.dispatch_settlement_sources.deinit(gpa);
        self.selected_method_decisions.deinit(gpa);
        self.selected_receiver_anchors.deinit(gpa);
        self.constraint_evidence_moves.deinit(gpa);
        self.selected_method_decision_moves.deinit(gpa);
        self.expected_consumption_plans.deinit(gpa);
        self.expected_failures.deinit(gpa);
        self.expected_consumer_retirements.deinit(gpa);
        self.expected_retirement_failures.deinit(gpa);
        self.expected_retired_consumers.deinit(gpa);
        self.malformed_expression_publications.deinit(gpa);
        self.malformed_type_annotation_publications.deinit(gpa);
        self.body_annotation_malformed_type_publications.deinit(gpa);
        self.body_annotation_attachments.deinit(gpa);
        self.expected_ambiguity_retirements.deinit(gpa);
        self.expected_call_formals.deinit(gpa);
        self.expected_call_slot_tokens.deinit(gpa);
        self.external_lookup_tokens.deinit(gpa);
        self.external_cache_seeds.deinit(gpa);
        self.* = undefined;
    }
};

test "where marker canonical copy relation is keyed by the complete tuple" {
    const none = std.math.maxInt(u32);
    var pairs = [_]ModuleEnv.WhereMarkerCopyPair{
        .{ .source_var = 7, .destination_var = 11, .discovery_depth = none, .predecessor_pair_offset = none, .predecessor_edge_ordinal = none },
        .{ .source_var = 8, .destination_var = 11, .discovery_depth = none, .predecessor_pair_offset = none, .predecessor_edge_ordinal = none },
        .{ .source_var = 7, .destination_var = 10, .discovery_depth = none, .predecessor_pair_offset = none, .predecessor_edge_ordinal = none },
        .{ .source_var = 7, .destination_var = 11, .discovery_depth = none, .predecessor_pair_offset = none, .predecessor_edge_ordinal = none },
        .{ .source_var = 6, .destination_var = 11, .discovery_depth = none, .predecessor_pair_offset = none, .predecessor_edge_ordinal = none },
    };
    std.mem.sortUnstable(
        ModuleEnv.WhereMarkerCopyPair,
        &pairs,
        {},
        durableWhereMarkerCopyPairLessThan,
    );
    const retained = deduplicateSortedWhereMarkerCopyPairs(&pairs);
    try std.testing.expectEqual(@as(usize, 4), retained);
    const relation = pairs[0..retained];
    try std.testing.expectEqual(@as(u32, 1), proofPairOffset(relation, 7, 10));
    try std.testing.expectEqual(@as(u32, 2), proofPairOffset(relation, 7, 11));
    try std.testing.expectEqual(@as(u32, 3), proofPairOffset(relation, 8, 11));
    // A resolved source coordinate may participate in multiple exact tuples.
    try std.testing.expectEqual(relation[1].source_var, relation[2].source_var);
    try std.testing.expect(relation[1].destination_var != relation[2].destination_var);

    // Distinct raw requests may collapse to one resolved tuple without losing
    // their occurrence identities.
    const collapsed_occurrences = [_]ModuleEnv.WhereMarkerCopyOccurrence{
        .{ .raw_source_var = 20, .raw_destination_var = 30, .canonical_pair_offset = 0 },
        .{ .raw_source_var = 21, .raw_destination_var = 31, .canonical_pair_offset = 0 },
    };
    try std.testing.expect(whereMarkerRawOccurrenceRelationIsFunctional(&collapsed_occurrences));
    try std.testing.expectEqual(
        collapsed_occurrences[0].canonical_pair_offset,
        collapsed_occurrences[1].canonical_pair_offset,
    );
}

test "where marker raw occurrence function rejects a nonadjacent split" {
    const occurrences = [_]ModuleEnv.WhereMarkerCopyOccurrence{
        .{ .raw_source_var = 5, .raw_destination_var = 10, .canonical_pair_offset = 0 },
        .{ .raw_source_var = 6, .raw_destination_var = 11, .canonical_pair_offset = 1 },
        .{ .raw_source_var = 5, .raw_destination_var = 12, .canonical_pair_offset = 2 },
    };
    try std.testing.expect(!whereMarkerRawOccurrenceRelationIsFunctional(&occurrences));
}

test "preexisting runtime error publishes its exact baseline retirement" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("PreexistingRuntimeError", "1..<5..<10");
    defer test_env.deinit();

    const main_def = test_env.can.explicitRootDefByName("main") orelse unreachable;
    const expr_idx = test_env.module_env.store.getDef(main_def).expr;
    const expr = test_env.module_env.store.getExpr(expr_idx);
    try std.testing.expect(expr == .e_runtime_error);
    const diagnostic = expr.e_runtime_error.diagnostic;
    try std.testing.expect(test_env.module_env.store.getDiagnostic(diagnostic) == .range_op_chained);

    const raw_node = test_env.module_env.store.nodes.get(ModuleEnv.nodeIdxFrom(expr_idx));
    try std.testing.expectEqual(CIR.Node.Tag.malformed, raw_node.tag);
    const expected_payload: [4]u32 = @bitCast(raw_node.getPayload());

    const malformed_publications = test_env.module_env.malformed_expression_publications.items.items;
    try std.testing.expectEqual(@as(usize, 1), malformed_publications.len);
    const malformed_publication = malformed_publications[0];
    try std.testing.expect(malformed_publication.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(expr_idx), malformed_publication.expr_node);
    try std.testing.expectEqual(@intFromEnum(diagnostic), malformed_publication.diagnostic_index);
    try std.testing.expect(malformedExpressionPublicationIsLocallyValid(
        test_env.module_env,
        malformed_publication,
    ));

    const retirements = test_env.module_env.expected_consumer_retirements.items.items;
    try std.testing.expectEqual(@as(usize, 1), retirements.len);
    const retirement = retirements[0];
    try std.testing.expect(retirement.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(expr_idx), retirement.retired_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression,
        retirement.decodedOwnerKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.preexisting_runtime_error,
        retirement.decodedKind().?,
    );
    try std.testing.expectEqual(CIR.Node.Tag.malformed, retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(expected_payload, retirement.original_payload);
    try std.testing.expectEqual(@intFromEnum(diagnostic), retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_len);
    try std.testing.expectEqual(@as(usize, 0), test_env.module_env.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), test_env.module_env.expected_retirement_failures.items.items.len);

    // The typed direct-source producer returns the retirement identity by
    // value and reuses the baseline instead of publishing a duplicate row.
    const cause = try preexistingRuntimeErrorCause(&test_env.checker, expr_idx, diagnostic);
    try std.testing.expect(cause.hasCanonicalTags(true));
    try std.testing.expectEqual(@as(u32, 0), cause.decodedExpectedConsumerRetirement().?.index);
    try std.testing.expectEqual(@as(usize, 1), test_env.module_env.expected_consumer_retirements.items.items.len);
    try std.testing.expect(validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    ));

    const saved_payload = test_env.module_env.expected_consumer_retirements.items.items[0].original_payload;
    test_env.module_env.expected_consumer_retirements.items.items[0].original_payload[0] ^= 1;
    const accepted_corrupt_snapshot = validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    test_env.module_env.expected_consumer_retirements.items.items[0].original_payload = saved_payload;
    try std.testing.expect(!accepted_corrupt_snapshot);

    // Even an otherwise identical, valid diagnostic is not interchangeable
    // with the producer-authored diagnostic identity.
    const alternate_diagnostic = try test_env.module_env.addDiagnostic(
        test_env.module_env.store.getDiagnostic(diagnostic),
    );
    const saved_diagnostic = test_env.module_env.expected_consumer_retirements.items.items[0].diagnostic_index;
    test_env.module_env.expected_consumer_retirements.items.items[0].diagnostic_index = @intFromEnum(alternate_diagnostic);
    const accepted_retargeted_diagnostic = validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    test_env.module_env.expected_consumer_retirements.items.items[0].diagnostic_index = saved_diagnostic;
    try std.testing.expect(!accepted_retargeted_diagnostic);

    const saved_retired_node = test_env.module_env.expected_consumer_retirements.items.items[0].retired_node;
    test_env.module_env.expected_consumer_retirements.items.items[0].retired_node = @intFromEnum(alternate_diagnostic);
    const accepted_retargeted_node = validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    test_env.module_env.expected_consumer_retirements.items.items[0].retired_node = saved_retired_node;
    try std.testing.expect(!accepted_retargeted_node);
}

test "malformed body annotation publishes exact failure and completes checker retirement" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\main : 42
        \\main = 1
    ;
    var test_env = try TestEnv.init("MalformedBodyAnnotation", source);
    defer test_env.deinit();
    try std.testing.expect(test_env.parse_ast.hasErrors());

    const main_def_idx = test_env.can.explicitRootDefByName("main") orelse unreachable;
    const main_def = test_env.module_env.store.getDef(main_def_idx);
    const annotation_idx = main_def.annotation orelse unreachable;
    const malformed_anno_idx = test_env.module_env.store.getAnnotation(annotation_idx).anno;
    const malformed_anno = test_env.module_env.store.getTypeAnno(malformed_anno_idx);
    try std.testing.expect(malformed_anno == .malformed);
    const malformed_diagnostic = malformed_anno.malformed.diagnostic;
    try std.testing.expect(
        test_env.module_env.store.getDiagnostic(malformed_diagnostic) == .malformed_type_annotation,
    );

    const final_expr = test_env.module_env.store.getExpr(main_def.expr);
    try std.testing.expect(final_expr == .e_runtime_error);
    const final_diagnostic = final_expr.e_runtime_error.diagnostic;
    try std.testing.expect(
        test_env.module_env.store.getDiagnostic(final_diagnostic) == .erroneous_value_expr,
    );
    try std.testing.expect(final_diagnostic != malformed_diagnostic);

    // The predeclaration pass uses an explicit nonpublishing mode. Only the
    // body-expression generation owns this one durable failure publication.
    const failures = test_env.module_env.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 1), failures.len);
    const failure = failures[0];
    try std.testing.expect(failure.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(main_def.expr), failure.owner_node);
    try std.testing.expectEqual(@intFromEnum(malformed_anno_idx), failure.site_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.OwnerKind.expression,
        failure.decodedOwnerKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
        failure.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(ModuleEnv.varFrom(main_def.expr)), failure.raw_owner_var);
    try std.testing.expectEqual(@intFromEnum(ModuleEnv.varFrom(malformed_anno_idx)), failure.raw_subject_var);
    try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.raw_peer_var);
    try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.constraint_index);
    try std.testing.expectEqual(@as(u32, 0), failure.slot);
    try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.plan_index);
    const direct_subject = failure.subject_authority.decodedDirect() orelse unreachable;
    try std.testing.expectEqual(@intFromEnum(malformed_anno_idx), direct_subject.producer_node);
    try std.testing.expectEqual(
        ModuleEnv.SubjectAuthority.DirectPhase.annotation_malformed_type,
        failure.subject_authority.decodedDirectPhase().?,
    );
    try std.testing.expect(
        direct_subject.local_record_index <
            test_env.module_env.body_annotation_malformed_type_publications.items.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        test_env.module_env.body_annotation_malformed_type_publications.items.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        test_env.module_env.body_annotation_attachments.items.items.len,
    );
    const body_publication = test_env.module_env.body_annotation_malformed_type_publications.items.items[
        direct_subject.local_record_index
    ];
    try std.testing.expectEqual(
        ModuleEnv.BodyAnnotationMalformedTypePublication.AttachmentKind.top_level_def,
        body_publication.decodedAttachmentKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(main_def_idx), body_publication.attachment_node);
    try std.testing.expectEqual(@intFromEnum(annotation_idx), body_publication.annotation_root);
    try std.testing.expectEqual(@intFromEnum(main_def.expr), body_publication.body_expr);
    const attachment_index = test_env.module_env.bodyAnnotationAttachmentIndex(
        .top_level_def,
        @intFromEnum(main_def_idx),
        annotation_idx,
        main_def.expr,
    ) orelse unreachable;
    const attachment = test_env.module_env.body_annotation_attachments.items.items[attachment_index];
    try std.testing.expectEqual(body_publication.attachment_kind, attachment.attachment_kind);
    try std.testing.expectEqual(body_publication.attachment_node, attachment.attachment_node);
    try std.testing.expectEqual(body_publication.annotation_root, attachment.annotation_root);
    try std.testing.expectEqual(body_publication.body_expr, attachment.body_expr);
    try std.testing.expect(bodyAnnotationMalformedTypePublicationIsLocallyValid(
        test_env.module_env,
        body_publication,
    ));
    const malformed_publication = test_env.module_env.malformed_type_annotation_publications.items.items[
        body_publication.malformed_type_publication_index
    ];
    try std.testing.expectEqual(@intFromEnum(malformed_anno_idx), malformed_publication.annotation_node);
    try std.testing.expectEqual(@intFromEnum(malformed_diagnostic), malformed_publication.diagnostic_index);
    try std.testing.expectEqual(
        @intFromEnum(malformed_diagnostic),
        failure.cause_owner.decodedCirDiagnostic().?.index,
    );

    try std.testing.expectEqual(@as(usize, 0), test_env.module_env.expected_consumption_plans.items.items.len);
    try std.testing.expectEqual(@as(usize, 1), test_env.module_env.expected_consumer_retirements.items.items.len);
    const retirement = test_env.module_env.expected_consumer_retirements.items.items[0];
    try std.testing.expect(retirement.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(main_def.expr), retirement.retired_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        retirement.decodedKind().?,
    );
    try std.testing.expect(retirement.decodedOriginalNodeTag().? != .malformed);
    try std.testing.expectEqual(@intFromEnum(final_diagnostic), retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 1), retirement.expected_failures_len);
    const retirement_failures = test_env.module_env.expected_retirement_failures.items.items;
    try std.testing.expectEqual(@as(usize, 1), retirement_failures.len);
    try std.testing.expectEqual(@as(u32, 0), retirement_failures[0].failure_index);
    try std.testing.expectEqual(@as(usize, 0), test_env.checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expect(validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    ));
}

test "malformed annotation on preexisting runtime body preserves empty baseline retirement" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\main : 42
        \\main = 1..<5..<10
    ;
    var test_env = try TestEnv.init("MalformedAnnotationPreexistingRuntimeBody", source);
    defer test_env.deinit();
    try std.testing.expect(test_env.parse_ast.hasErrors());

    const main_def_idx = test_env.can.explicitRootDefByName("main") orelse unreachable;
    const main_def = test_env.module_env.store.getDef(main_def_idx);
    const annotation_idx = main_def.annotation orelse unreachable;
    const malformed_anno_idx = test_env.module_env.store.getAnnotation(annotation_idx).anno;
    const malformed_anno = test_env.module_env.store.getTypeAnno(malformed_anno_idx);
    try std.testing.expect(malformed_anno == .malformed);
    const malformed_diagnostic = malformed_anno.malformed.diagnostic;
    try std.testing.expect(
        test_env.module_env.store.getDiagnostic(malformed_diagnostic) == .malformed_type_annotation,
    );

    const body = test_env.module_env.store.getExpr(main_def.expr);
    try std.testing.expect(body == .e_runtime_error);
    const body_diagnostic = body.e_runtime_error.diagnostic;
    try std.testing.expect(
        test_env.module_env.store.getDiagnostic(body_diagnostic) == .range_op_chained,
    );

    // The body never establishes an annotation relation: its exact preexisting
    // retirement suppresses annotation generation without borrowing the
    // malformed annotation as a cause or reserving a checker rewrite.
    try std.testing.expectEqual(@as(usize, 0), test_env.module_env.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), test_env.module_env.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), test_env.checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqual(
        @as(usize, 1),
        test_env.module_env.body_annotation_malformed_type_publications.items.items.len,
    );
    const body_publication = test_env.module_env.body_annotation_malformed_type_publications.items.items[0];
    try std.testing.expectEqual(@intFromEnum(main_def_idx), body_publication.attachment_node);
    try std.testing.expectEqual(@intFromEnum(annotation_idx), body_publication.annotation_root);
    try std.testing.expectEqual(@intFromEnum(main_def.expr), body_publication.body_expr);
    try std.testing.expect(bodyAnnotationMalformedTypePublicationIsLocallyValid(
        test_env.module_env,
        body_publication,
    ));

    const retirements = test_env.module_env.expected_consumer_retirements.items.items;
    try std.testing.expectEqual(@as(usize, 1), retirements.len);
    const retirement = retirements[0];
    try std.testing.expect(retirement.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(main_def.expr), retirement.retired_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression,
        retirement.decodedOwnerKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.preexisting_runtime_error,
        retirement.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(body_diagnostic), retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_len);
    try std.testing.expect(validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    ));
}

