test "malformed annotation failure rejects a same-shaped sibling body attachment" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\first : 42
        \\first = 1
        \\
        \\second : 42
        \\second = 1
    ;
    var test_env = try TestEnv.init("MalformedAnnotationSiblingOwners", source);
    defer test_env.deinit();
    try std.testing.expect(test_env.parse_ast.hasErrors());

    const first_def_idx = test_env.can.explicitRootDefByName("first") orelse unreachable;
    const second_def_idx = test_env.can.explicitRootDefByName("second") orelse unreachable;
    const first_def = test_env.module_env.store.getDef(first_def_idx);
    const second_def = test_env.module_env.store.getDef(second_def_idx);
    const failures = test_env.module_env.expected_failures.items.items;
    const publications = test_env.module_env.body_annotation_malformed_type_publications.items.items;
    try std.testing.expectEqual(@as(usize, 2), failures.len);
    try std.testing.expectEqual(@as(usize, 2), publications.len);
    try std.testing.expect(validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    ));

    const first_failure_index: usize = for (failures, 0..) |failure, failure_index| {
        if (failure.owner_node == @intFromEnum(first_def.expr)) break failure_index;
    } else return error.TestUnexpectedResult;
    const second_failure_index: usize = for (failures, 0..) |failure, failure_index| {
        if (failure.owner_node == @intFromEnum(second_def.expr)) break failure_index;
    } else return error.TestUnexpectedResult;
    const first_publication_index = failures[first_failure_index].subject_authority.payload.direct.local_record_index;
    const second_publication_index = failures[second_failure_index].subject_authority.payload.direct.local_record_index;
    try std.testing.expect(first_publication_index != second_publication_index);

    failures[first_failure_index].subject_authority.payload.direct.local_record_index = second_publication_index;
    const accepted_sibling_failure = validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    failures[first_failure_index].subject_authority.payload.direct.local_record_index = first_publication_index;
    try std.testing.expect(!accepted_sibling_failure);

    const first_body_expr = publications[first_publication_index].body_expr;
    publications[first_publication_index].body_expr = publications[second_publication_index].body_expr;
    const accepted_sibling_publication = validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    publications[first_publication_index].body_expr = first_body_expr;
    try std.testing.expect(!accepted_sibling_publication);
    try std.testing.expect(validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    ));
}

test "invalid tag child publishes exact parent slot and rejects retargeted authority" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\first : [Good, bad_first, Other, bad_second]
        \\first = Good
        \\
        \\second : [Second, bad_third, Last]
        \\second = Second
    ;
    var test_env = try TestEnv.init("InvalidTagChildAuthority", source);
    defer test_env.deinit();
    var fresh_env = try TestEnv.init("InvalidTagChildAuthority", source);
    defer fresh_env.deinit();

    const cir = test_env.module_env;
    const first_def_idx = test_env.can.explicitRootDefByName("first") orelse unreachable;
    const second_def_idx = test_env.can.explicitRootDefByName("second") orelse unreachable;
    const first_def = cir.store.getDef(first_def_idx);
    const second_def = cir.store.getDef(second_def_idx);
    const first_annotation_idx = first_def.annotation orelse unreachable;
    const second_annotation_idx = second_def.annotation orelse unreachable;
    const first_parent_idx = cir.store.getAnnotation(first_annotation_idx).anno;
    const second_parent_idx = cir.store.getAnnotation(second_annotation_idx).anno;
    const first_parent = cir.store.getTypeAnno(first_parent_idx);
    const second_parent = cir.store.getTypeAnno(second_parent_idx);
    try std.testing.expect(first_parent == .tag_union);
    try std.testing.expect(second_parent == .tag_union);
    const first_children = cir.store.sliceTypeAnnos(first_parent.tag_union.tags);
    try std.testing.expectEqual(@as(usize, 4), first_children.len);
    try std.testing.expect(cir.store.getTypeAnno(first_children[1]) == .malformed);
    try std.testing.expect(cir.store.getTypeAnno(first_children[3]) == .malformed);

    const failures = cir.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 2), failures.len);
    const first_failure_index: usize = for (failures, 0..) |failure, failure_index| {
        if (failure.owner_node == @intFromEnum(first_def.expr)) break failure_index;
    } else return error.TestUnexpectedResult;
    const second_failure_index: usize = for (failures, 0..) |failure, failure_index| {
        if (failure.owner_node == @intFromEnum(second_def.expr)) break failure_index;
    } else return error.TestUnexpectedResult;
    var first_owner_failure_count: usize = 0;
    for (failures) |failure| {
        if (failure.owner_node == @intFromEnum(first_def.expr)) first_owner_failure_count += 1;
    }
    // The producer stops at the first malformed member of this parent.
    try std.testing.expectEqual(@as(usize, 1), first_owner_failure_count);

    const first_failure = &failures[first_failure_index];
    try std.testing.expect(first_failure.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.annotation_invalid_tag_child,
        first_failure.decodedKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.OwnerKind.expression,
        first_failure.decodedOwnerKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(first_def.expr), first_failure.owner_node);
    try std.testing.expectEqual(@intFromEnum(first_parent_idx), first_failure.site_node);
    try std.testing.expectEqual(
        @intFromEnum(ModuleEnv.varFrom(first_def.expr)),
        first_failure.raw_owner_var,
    );
    try std.testing.expectEqual(
        @intFromEnum(ModuleEnv.varFrom(first_parent_idx)),
        first_failure.raw_subject_var,
    );
    try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, first_failure.raw_peer_var);
    try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, first_failure.constraint_index);
    try std.testing.expectEqual(@as(u32, 1), first_failure.slot);
    try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, first_failure.plan_index);
    const first_direct = first_failure.subject_authority.decodedDirect() orelse unreachable;
    try std.testing.expectEqual(
        ModuleEnv.SubjectAuthority.DirectPhase.annotation_invalid_tag_child,
        first_failure.subject_authority.decodedDirectPhase().?,
    );
    try std.testing.expectEqual(@intFromEnum(first_parent_idx), first_direct.producer_node);

    const body_publications = cir.body_annotation_malformed_type_publications.items.items;
    try std.testing.expectEqual(@as(usize, 3), body_publications.len);
    try std.testing.expect(first_direct.local_record_index < body_publications.len);
    const selected_body_publication = body_publications[first_direct.local_record_index];
    try std.testing.expectEqual(
        ModuleEnv.BodyAnnotationMalformedTypePublication.AttachmentKind.top_level_def,
        selected_body_publication.decodedAttachmentKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(first_def_idx), selected_body_publication.attachment_node);
    try std.testing.expectEqual(@intFromEnum(first_annotation_idx), selected_body_publication.annotation_root);
    try std.testing.expectEqual(@intFromEnum(first_def.expr), selected_body_publication.body_expr);
    try std.testing.expect(bodyAnnotationMalformedTypePublicationIsLocallyValid(
        cir,
        selected_body_publication,
    ));
    const selected_malformed_publication = cir.malformed_type_annotation_publications.items.items[
        selected_body_publication.malformed_type_publication_index
    ];
    try std.testing.expectEqual(
        @intFromEnum(first_children[1]),
        selected_malformed_publication.annotation_node,
    );
    try std.testing.expectEqual(
        selected_malformed_publication.diagnostic_index,
        first_failure.cause_owner.decodedCirDiagnostic().?.index,
    );
    const first_attachment_index = cir.bodyAnnotationAttachmentIndex(
        .top_level_def,
        @intFromEnum(first_def_idx),
        first_annotation_idx,
        first_def.expr,
    ) orelse unreachable;
    try std.testing.expect(cir.bodyAnnotationAttachmentContainsTypeAnno(
        first_attachment_index,
        first_parent_idx,
    ));
    try std.testing.expect(invalidTagChildExpectedFailureIsLocallyValid(
        cir,
        first_failure.*,
        first_direct,
    ));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    const context = ImportResolution.freshEmpty(fresh_env.module_env);
    try validateExpectedFailureContext(cir, context);

    const alternate_same_body_publication_index: u32 = for (body_publications, 0..) |publication, publication_index| {
        if (publication_index == first_direct.local_record_index or
            publication.body_expr != @intFromEnum(first_def.expr))
        {
            continue;
        }
        break @intCast(publication_index);
    } else return error.TestUnexpectedResult;
    const sibling_body_publication_index = failures[second_failure_index]
        .subject_authority.payload.direct.local_record_index;
    const alternate_malformed_publication = cir.malformed_type_annotation_publications.items.items[
        body_publications[alternate_same_body_publication_index].malformed_type_publication_index
    ];

    // A same-shaped record owned by another body is not attachment authority.
    first_failure.subject_authority.payload.direct.local_record_index = sibling_body_publication_index;
    const accepted_sibling_body = validateExpectedFailureRetirementLocal(&cir.types, cir);
    first_failure.subject_authority.payload.direct.local_record_index = first_direct.local_record_index;
    try std.testing.expect(!accepted_sibling_body);

    // Retarget every parent-facing scalar together so the closed tags remain
    // legal; the selected body attachment still rejects the sibling parent.
    const saved_site = first_failure.site_node;
    const saved_raw_subject = first_failure.raw_subject_var;
    const saved_producer = first_failure.subject_authority.payload.direct.producer_node;
    first_failure.site_node = @intFromEnum(second_parent_idx);
    first_failure.raw_subject_var = @intFromEnum(ModuleEnv.varFrom(second_parent_idx));
    first_failure.subject_authority.payload.direct.producer_node = @intFromEnum(second_parent_idx);
    const accepted_parent = validateExpectedFailureRetirementLocal(&cir.types, cir);
    first_failure.site_node = saved_site;
    first_failure.raw_subject_var = saved_raw_subject;
    first_failure.subject_authority.payload.direct.producer_node = saved_producer;
    try std.testing.expect(!accepted_parent);

    const saved_slot = first_failure.slot;
    first_failure.slot = 0;
    const accepted_child_slot = validateExpectedFailureRetirementLocal(&cir.types, cir);
    first_failure.slot = saved_slot;
    try std.testing.expect(!accepted_child_slot);

    const saved_cause = first_failure.cause_owner;
    first_failure.cause_owner = ModuleEnv.CauseOwner.cirDiagnostic(
        alternate_malformed_publication.diagnostic_index,
    );
    const accepted_diagnostic = validateExpectedFailureRetirementLocal(&cir.types, cir);
    first_failure.cause_owner = saved_cause;
    try std.testing.expect(!accepted_diagnostic);

    first_failure.subject_authority.payload.direct.local_record_index =
        alternate_same_body_publication_index;
    const accepted_malformed_leaf = validateExpectedFailureRetirementLocal(&cir.types, cir);
    first_failure.subject_authority.payload.direct.local_record_index = first_direct.local_record_index;
    try std.testing.expect(!accepted_malformed_leaf);

    // Local evidence deliberately authenticates only the selected slot. A
    // cached retarget of another member in the same parent remains locally
    // well-formed, but exact fresh-context replay rejects the changed span.
    const saved_other_child = first_children[2];
    first_children[2] = first_children[0];
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    const accepted_cached_parent_span = validateExpectedFailureContext(cir, context);
    first_children[2] = saved_other_child;
    try std.testing.expectError(error.CorruptArtifact, accepted_cached_parent_span);

    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);
}

test "invalid tag child on preexisting runtime body propagates exact suppression" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\main : [Good, broken, Other]
        \\main = 1..<5..<10
    ;
    var test_env = try TestEnv.init("InvalidTagChildSuppression", source);
    defer test_env.deinit();

    const main_def_idx = test_env.can.explicitRootDefByName("main") orelse unreachable;
    const main_def = test_env.module_env.store.getDef(main_def_idx);
    const annotation_idx = main_def.annotation orelse unreachable;
    const parent_idx = test_env.module_env.store.getAnnotation(annotation_idx).anno;
    const parent = test_env.module_env.store.getTypeAnno(parent_idx);
    try std.testing.expect(parent == .tag_union);
    const children = test_env.module_env.store.sliceTypeAnnos(parent.tag_union.tags);
    try std.testing.expectEqual(@as(usize, 3), children.len);
    try std.testing.expect(test_env.module_env.store.getTypeAnno(children[1]) == .malformed);

    const body = test_env.module_env.store.getExpr(main_def.expr);
    try std.testing.expect(body == .e_runtime_error);
    try std.testing.expect(
        test_env.module_env.store.getDiagnostic(body.e_runtime_error.diagnostic) == .range_op_chained,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        test_env.module_env.expected_failures.items.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        test_env.module_env.expected_retirement_failures.items.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        test_env.module_env.body_annotation_malformed_type_publications.items.items.len,
    );
    const body_publication = test_env.module_env.body_annotation_malformed_type_publications.items.items[0];
    try std.testing.expectEqual(@intFromEnum(main_def_idx), body_publication.attachment_node);
    try std.testing.expectEqual(@intFromEnum(annotation_idx), body_publication.annotation_root);
    try std.testing.expectEqual(@intFromEnum(main_def.expr), body_publication.body_expr);
    try std.testing.expectEqual(
        @intFromEnum(children[1]),
        test_env.module_env.malformed_type_annotation_publications.items.items[
            body_publication.malformed_type_publication_index
        ].annotation_node,
    );

    const retirements = test_env.module_env.expected_consumer_retirements.items.items;
    try std.testing.expectEqual(@as(usize, 1), retirements.len);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.preexisting_runtime_error,
        retirements[0].decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(main_def.expr), retirements[0].retired_node);
    try std.testing.expectEqual(@as(u32, 0), retirements[0].expected_failures_len);
    try std.testing.expectEqual(@as(usize, 0), test_env.checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expect(validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    ));
}

test "malformed where clauses publish source ordinals and reject retargeted authority" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\main : a -> a where [42, a.keep : a -> a, 43]
        \\main = |value| value
        \\
        \\sibling : b -> b where [44]
        \\sibling = |value| value
    ;
    var test_env = try TestEnv.init("MalformedWhereAuthority", source);
    defer test_env.deinit();
    var fresh_env = try TestEnv.init("MalformedWhereAuthority", source);
    defer fresh_env.deinit();
    try std.testing.expect(test_env.parse_ast.hasErrors());

    const cir = test_env.module_env;
    const main_def_idx = test_env.can.explicitRootDefByName("main") orelse unreachable;
    const sibling_def_idx = test_env.can.explicitRootDefByName("sibling") orelse unreachable;
    const main_def = cir.store.getDef(main_def_idx);
    const sibling_def = cir.store.getDef(sibling_def_idx);
    const main_annotation_idx = main_def.annotation orelse unreachable;
    const sibling_annotation_idx = sibling_def.annotation orelse unreachable;
    const main_annotation = cir.store.getAnnotation(main_annotation_idx);
    const sibling_annotation = cir.store.getAnnotation(sibling_annotation_idx);
    const main_where = main_annotation.where orelse return error.TestUnexpectedResult;
    const sibling_where = sibling_annotation.where orelse return error.TestUnexpectedResult;
    const main_clauses = cir.store.sliceWhereClauses(main_where);
    const sibling_clauses = cir.store.sliceWhereClauses(sibling_where);
    try std.testing.expectEqual(@as(usize, 3), main_clauses.len);
    try std.testing.expectEqual(@as(usize, 1), sibling_clauses.len);
    try std.testing.expect(cir.store.getWhereClause(main_clauses[0]) == .w_malformed);
    try std.testing.expect(cir.store.getWhereClause(main_clauses[1]) == .w_method);
    try std.testing.expect(cir.store.getWhereClause(main_clauses[2]) == .w_malformed);
    try std.testing.expect(cir.store.getWhereClause(sibling_clauses[0]) == .w_malformed);

    const failures = cir.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 3), failures.len);
    var first_failure_index: ?usize = null;
    var second_failure_index: ?usize = null;
    var sibling_failure_index: ?usize = null;
    for (failures, 0..) |failure, failure_index| {
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.annotation_malformed_where,
            failure.decodedKind().?,
        );
        if (failure.owner_node == @intFromEnum(main_def.expr) and failure.slot == 0) {
            first_failure_index = failure_index;
        } else if (failure.owner_node == @intFromEnum(main_def.expr) and failure.slot == 2) {
            second_failure_index = failure_index;
        } else if (failure.owner_node == @intFromEnum(sibling_def.expr) and failure.slot == 0) {
            sibling_failure_index = failure_index;
        } else {
            return error.TestUnexpectedResult;
        }
    }
    const first_index = first_failure_index orelse return error.TestUnexpectedResult;
    const second_index = second_failure_index orelse return error.TestUnexpectedResult;
    const sibling_index = sibling_failure_index orelse return error.TestUnexpectedResult;
    const first_failure = &failures[first_index];
    const second_failure = &failures[second_index];
    const sibling_failure = &failures[sibling_index];
    const first_direct = first_failure.subject_authority.decodedDirect() orelse unreachable;
    const second_direct = second_failure.subject_authority.decodedDirect() orelse unreachable;
    const sibling_direct = sibling_failure.subject_authority.decodedDirect() orelse unreachable;
    const main_attachment_index = cir.bodyAnnotationAttachmentIndex(
        .top_level_def,
        @intFromEnum(main_def_idx),
        main_annotation_idx,
        main_def.expr,
    ) orelse return error.TestUnexpectedResult;
    const sibling_attachment_index = cir.bodyAnnotationAttachmentIndex(
        .top_level_def,
        @intFromEnum(sibling_def_idx),
        sibling_annotation_idx,
        sibling_def.expr,
    ) orelse return error.TestUnexpectedResult;

    try std.testing.expectEqual(main_attachment_index, first_direct.local_record_index);
    try std.testing.expectEqual(main_attachment_index, second_direct.local_record_index);
    try std.testing.expectEqual(sibling_attachment_index, sibling_direct.local_record_index);
    const expected_main_sites = [_]CIR.WhereClause.Idx{ main_clauses[0], main_clauses[2] };
    const expected_main_slots = [_]u32{ 0, 2 };
    const main_failure_indices = [_]usize{ first_index, second_index };
    for (main_failure_indices, expected_main_sites, expected_main_slots) |failure_index, where_idx, slot| {
        const failure = failures[failure_index];
        const direct = failure.subject_authority.decodedDirect() orelse unreachable;
        const malformed = cir.store.getWhereClause(where_idx).w_malformed;
        try std.testing.expect(failure.hasLegalTags());
        try std.testing.expectEqual(@intFromEnum(main_def.expr), failure.owner_node);
        try std.testing.expectEqual(@intFromEnum(where_idx), failure.site_node);
        try std.testing.expectEqual(@intFromEnum(ModuleEnv.varFrom(main_def.expr)), failure.raw_owner_var);
        try std.testing.expectEqual(@intFromEnum(ModuleEnv.varFrom(main_annotation.anno)), failure.raw_subject_var);
        try std.testing.expectEqual(slot, failure.slot);
        try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.raw_peer_var);
        try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.constraint_index);
        try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.plan_index);
        try std.testing.expectEqual(
            ModuleEnv.SubjectAuthority.DirectPhase.annotation_malformed_where,
            failure.subject_authority.decodedDirectPhase().?,
        );
        try std.testing.expectEqual(@intFromEnum(where_idx), direct.producer_node);
        try std.testing.expectEqual(@intFromEnum(malformed.diagnostic), failure.cause_owner.decodedCirDiagnostic().?.index);
        try std.testing.expect(cir.store.getDiagnostic(malformed.diagnostic) == .malformed_where_clause);
        try std.testing.expect(cir.bodyAnnotationAttachmentContainsWhereClause(main_attachment_index, where_idx));
        try std.testing.expect(malformedWhereExpectedFailureIsLocallyValid(cir, failure, direct));
    }
    try std.testing.expect(malformedWhereExpectedFailureIsLocallyValid(
        cir,
        sibling_failure.*,
        sibling_direct,
    ));

    try std.testing.expect(cir.store.getExpr(main_def.expr) == .e_runtime_error);
    try std.testing.expect(cir.store.getExpr(sibling_def.expr) == .e_runtime_error);
    const retirements = cir.expected_consumer_retirements.items.items;
    const main_retirement = for (retirements) |retirement| {
        if (retirement.retired_node == @intFromEnum(main_def.expr)) break retirement;
    } else return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 2), main_retirement.expected_failures_len);
    const retirement_causes = cir.expected_retirement_failures.items.items[main_retirement.expected_failures_start..][0..main_retirement.expected_failures_len];
    var saw_first = false;
    var saw_second = false;
    for (retirement_causes) |cause| {
        saw_first = saw_first or cause.failure_index == first_index;
        saw_second = saw_second or cause.failure_index == second_index;
    }
    try std.testing.expect(saw_first and saw_second);
    try std.testing.expectEqual(@as(usize, 0), test_env.checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    const context = ImportResolution.freshEmpty(fresh_env.module_env);
    try validateExpectedFailureContext(cir, context);

    const saved_first = first_failure.*;
    first_failure.subject_authority.payload.direct.local_record_index = sibling_attachment_index;
    try std.testing.expect(!malformedWhereExpectedFailureIsLocallyValid(
        cir,
        first_failure.*,
        first_failure.subject_authority.decodedDirect().?,
    ));
    first_failure.* = saved_first;

    first_failure.raw_owner_var = sibling_failure.raw_owner_var;
    try std.testing.expect(!malformedWhereExpectedFailureIsLocallyValid(cir, first_failure.*, first_direct));
    first_failure.* = saved_first;

    first_failure.site_node = @intFromEnum(main_clauses[2]);
    first_failure.subject_authority.payload.direct.producer_node = @intFromEnum(main_clauses[2]);
    try std.testing.expect(!malformedWhereExpectedFailureIsLocallyValid(
        cir,
        first_failure.*,
        first_failure.subject_authority.decodedDirect().?,
    ));
    first_failure.* = saved_first;

    first_failure.slot = 2;
    try std.testing.expect(!malformedWhereExpectedFailureIsLocallyValid(cir, first_failure.*, first_direct));
    first_failure.* = saved_first;

    first_failure.cause_owner = second_failure.cause_owner;
    try std.testing.expect(!malformedWhereExpectedFailureIsLocallyValid(cir, first_failure.*, first_direct));
    first_failure.* = saved_first;

    first_failure.raw_subject_var = sibling_failure.raw_subject_var;
    try std.testing.expect(!malformedWhereExpectedFailureIsLocallyValid(cir, first_failure.*, first_direct));
    first_failure.* = saved_first;

    first_failure.site_node = @intFromEnum(sibling_clauses[0]);
    first_failure.subject_authority.payload.direct.producer_node = @intFromEnum(sibling_clauses[0]);
    first_failure.slot = 0;
    try std.testing.expect(!malformedWhereExpectedFailureIsLocallyValid(
        cir,
        first_failure.*,
        first_failure.subject_authority.decodedDirect().?,
    ));
    first_failure.* = saved_first;

    const first_where_node_idx = ModuleEnv.nodeIdxFrom(main_clauses[0]);
    const saved_first_where_node = cir.store.nodes.get(first_where_node_idx);
    var changed_first_where_node = saved_first_where_node;
    var changed_first_where_payload = changed_first_where_node.getPayload();
    changed_first_where_payload.diag_single_value.value = second_failure.cause_owner.decodedCirDiagnostic().?.index;
    changed_first_where_node.setPayload(changed_first_where_payload);
    cir.store.nodes.set(first_where_node_idx, changed_first_where_node);
    try std.testing.expect(!malformedWhereExpectedFailureIsLocallyValid(cir, first_failure.*, first_direct));
    cir.store.nodes.set(first_where_node_idx, saved_first_where_node);

    // The selected failure remains locally exact when an unrelated written
    // member changes; fresh replay authenticates the complete authored span.
    const saved_middle_clause = main_clauses[1];
    main_clauses[1] = sibling_clauses[0];
    try std.testing.expect(malformedWhereExpectedFailureIsLocallyValid(cir, first_failure.*, first_direct));
    try std.testing.expect(!malformedWhereExpectedFailureMatchesFresh(
        cir,
        fresh_env.module_env,
        first_failure.*,
        first_direct,
    ));
    main_clauses[1] = saved_middle_clause;

    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);
}

test "malformed where failures use every generic body attachment kind" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\top : U64 where [42]
        \\top = 1
        \\
        \\main = {
        \\  local : U64 where [43]
        \\  local = 1
        \\  mutable : U64 where [44]
        \\  var mutable = 1
        \\  mutable
        \\}
    ;
    var test_env = try TestEnv.init("MalformedWhereAttachmentKinds", source);
    defer test_env.deinit();

    var saw_top = false;
    var saw_local_decl = false;
    var saw_local_var = false;
    const cir = test_env.module_env;
    const failures = cir.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 3), failures.len);
    for (failures) |failure| {
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.annotation_malformed_where,
            failure.decodedKind().?,
        );
        const direct = failure.subject_authority.decodedDirect() orelse unreachable;
        try std.testing.expect(malformedWhereExpectedFailureIsLocallyValid(cir, failure, direct));
        const attachment = cir.body_annotation_attachments.items.items[direct.local_record_index];
        switch (attachment.decodedAttachmentKind() orelse unreachable) {
            .top_level_def => saw_top = true,
            .local_decl => saw_local_decl = true,
            .local_var => {
                saw_local_var = true;
                try std.testing.expect(!cir.store.getAnnotation(
                    @enumFromInt(attachment.annotation_root),
                ).introduces_type_var);
            },
        }
    }
    try std.testing.expect(saw_top and saw_local_decl and saw_local_var);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
}

