test "invalid imported where alias publishes its exact malformed annotation failure" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("MalformedWhereAliasSourceA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import MalformedWhereAliasSourceA exposing [Status]
        \\
        \\first : a, U64 -> [Off, On] where [a.Status]
        \\first = |_, _| Off
    ;
    var consumer = try TestEnv.initWithImport(
        "MalformedWhereAliasSourceB",
        consumer_source,
        "MalformedWhereAliasSourceA",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());

    const cir = consumer.module_env;
    const def_idx = consumer.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const def = cir.store.getDef(def_idx);
    const annotation_idx = def.annotation orelse return error.TestUnexpectedResult;
    const annotation = cir.store.getAnnotation(annotation_idx);
    const annotation_fn = cir.store.getTypeAnno(annotation.anno);
    if (annotation_fn != .@"fn") return error.TestUnexpectedResult;
    const annotation_args = cir.store.sliceTypeAnnos(annotation_fn.@"fn".args);
    try std.testing.expectEqual(@as(usize, 2), annotation_args.len);
    const where_span = annotation.where orelse return error.TestUnexpectedResult;
    const where_clauses = cir.store.sliceWhereClauses(where_span);
    try std.testing.expectEqual(@as(usize, 1), where_clauses.len);
    const where_idx = where_clauses[0];
    const where_clause = cir.store.getWhereClause(where_idx);
    if (where_clause != .w_alias) return error.TestUnexpectedResult;
    const malformed_idx = where_clause.w_alias.alias;
    const malformed = cir.store.getTypeAnno(malformed_idx);
    if (malformed != .malformed) return error.TestUnexpectedResult;
    try std.testing.expect(cir.store.getDiagnostic(malformed.malformed.diagnostic) == .undeclared_type);

    var matching_owner_count: usize = 0;
    for (cir.store.sliceWhereClauseOwners(where_span)) |owner| {
        var owns_clause = false;
        for (cir.store.sliceWhereClausesForOwner(owner)) |owned_where| {
            owns_clause = owns_clause or owned_where == where_idx;
        }
        if (!owns_clause) continue;
        matching_owner_count += 1;
        try std.testing.expect(owner.owned_by_annotation);
        try std.testing.expectEqual(@intFromEnum(annotation_args[0]), owner.rigid_var);
    }
    try std.testing.expectEqual(@as(usize, 1), matching_owner_count);

    // Predeclaration consumes the same malformed result in a nonpublishing
    // mode. Only body checking owns this durable failure and retirement.
    const failures = cir.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 1), failures.len);
    const failure = failures[0];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
        failure.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(def.expr), failure.owner_node);
    try std.testing.expectEqual(@intFromEnum(malformed_idx), failure.site_node);
    try std.testing.expectEqual(@intFromEnum(ModuleEnv.varFrom(malformed_idx)), failure.raw_subject_var);
    const direct = failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        ModuleEnv.SubjectAuthority.DirectPhase.annotation_malformed_type,
        failure.subject_authority.decodedDirectPhase().?,
    );
    try std.testing.expectEqual(@intFromEnum(malformed_idx), direct.producer_node);
    try std.testing.expectEqual(
        @intFromEnum(malformed.malformed.diagnostic),
        failure.cause_owner.decodedCirDiagnostic().?.index,
    );
    try std.testing.expect(
        direct.local_record_index <
            cir.body_annotation_malformed_type_publications.items.items.len,
    );
    const publication = cir.body_annotation_malformed_type_publications.items.items[
        direct.local_record_index
    ];
    try std.testing.expectEqual(@intFromEnum(def_idx), publication.attachment_node);
    try std.testing.expectEqual(@intFromEnum(annotation_idx), publication.annotation_root);
    try std.testing.expectEqual(@intFromEnum(def.expr), publication.body_expr);
    try std.testing.expectEqual(@intFromEnum(malformed_idx), cir.malformed_type_annotation_publications.items.items[
        publication.malformed_type_publication_index
    ].annotation_node);

    const retirements = cir.expected_consumer_retirements.items.items;
    try std.testing.expectEqual(@as(usize, 1), retirements.len);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        retirements[0].decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(def.expr), retirements[0].retired_node);
    try std.testing.expectEqual(@as(u32, 1), retirements[0].expected_failures_len);
    try std.testing.expectEqual(@as(usize, 1), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(u32, 0), cir.expected_retirement_failures.items.items[0].failure_index);
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
}

const DirectBinderLookupTestProof = struct {
    failure_index: u32,
    direct: ModuleEnv.SubjectAuthority.Direct,
    source_retirement_index: u32,
    lookup_retirement_index: u32,
    pattern_idx: CIR.Pattern.Idx,
};

/// Test-only discovery for the sole direct-binder lookup publication in one
/// focused fixture. Durable admission uses the indexed producer authorities
/// themselves and never scans by failure kind.
fn uniqueDirectBinderLookupTestProof(
    cir: *const ModuleEnv,
) error{TestUnexpectedResult}!DirectBinderLookupTestProof {
    var selected: ?u32 = null;
    for (cir.expected_failures.items.items, 0..) |failure, failure_index| {
        if (failure.decodedKind() != .direct_binder_lookup_checked_error) continue;
        if (selected != null) return error.TestUnexpectedResult;
        selected = @intCast(failure_index);
    }
    const failure_index = selected orelse return error.TestUnexpectedResult;
    const failure = cir.expected_failures.items.items[failure_index];
    const direct = failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    const source_retirement = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return error.TestUnexpectedResult;
    const lookup = expectedLookupRetirementOwningFailure(cir, failure_index) orelse
        return error.TestUnexpectedResult;
    if (!directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        failure,
        failure_index,
        direct,
    )) return error.TestUnexpectedResult;
    return .{
        .failure_index = failure_index,
        .direct = direct,
        .source_retirement_index = source_retirement.index,
        .lookup_retirement_index = lookup.retirement_index,
        .pattern_idx = lookup.pattern_idx,
    };
}

fn expectDirectBinderTransientListsEmpty(checker: *const Self) !void {
    try std.testing.expectEqual(
