    try std.testing.expectEqual(
        @as(usize, 0),
        checker.direct_formal_failure_sources.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        checker.active_direct_binder_failures.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        checker.record_update_owner_retirement_drafts.items.len,
    );
}

const DirectBinderOwnerInverseTestProof = struct {
    annotation_idx: CIR.Annotation.Idx,
    function_idx: CIR.TypeAnno.Idx,
    formals: [2]CIR.TypeAnno.Idx,
    where_idx: CIR.WhereClause.Idx,
    receiver_idx: CIR.TypeAnno.Idx,
    owner_row_index: u32,
};

/// Test-only replay of the exact two-direct-formal annotation used to hold a
/// real sibling rigid while corrupting one listed where-clause receiver.
fn directBinderOwnerInverseTestProof(
    cir: *const ModuleEnv,
    def_idx: CIR.Def.Idx,
) error{TestUnexpectedResult}!DirectBinderOwnerInverseTestProof {
    const def = cir.store.getDef(def_idx);
    const annotation_idx = def.annotation orelse return error.TestUnexpectedResult;
    const annotation = cir.store.getAnnotation(annotation_idx);
    const function_idx = annotation.anno;
    const function = cir.store.getTypeAnno(function_idx);
    if (function != .@"fn") return error.TestUnexpectedResult;
    const formals = cir.store.sliceTypeAnnos(function.@"fn".args);
    if (formals.len != 2 or formals[0] == formals[1] or
        cir.store.getTypeAnno(formals[0]) != .rigid_var or
        cir.store.getTypeAnno(formals[1]) != .rigid_var)
    {
        return error.TestUnexpectedResult;
    }
    const where = annotation.where orelse return error.TestUnexpectedResult;
    const clauses = cir.store.sliceWhereClauses(where);
    if (clauses.len != 1) return error.TestUnexpectedResult;
    const where_idx = clauses[0];
    const clause = cir.store.getWhereClause(where_idx);
    if (clause != .w_alias or cir.store.getTypeAnno(clause.w_alias.alias) != .malformed) {
        return error.TestUnexpectedResult;
    }
    const receiver = cir.store.getTypeAnno(clause.w_alias.var_);
    if (receiver != .rigid_var_lookup or
        receiver.rigid_var_lookup.ref != formals[0] or
        clause.w_alias.var_ == formals[0] or
        clause.w_alias.var_ == formals[1])
    {
        return error.TestUnexpectedResult;
    }

    var owner_row_index: ?u32 = null;
    for (cir.store.sliceWhereClauseOwners(where), 0..) |owner, owner_offset| {
        var clause_matches: usize = 0;
        for (cir.store.sliceWhereClausesForOwner(owner)) |owned_where| {
            if (owned_where == where_idx) clause_matches += 1;
        }
        if (owner.rigid_var == @intFromEnum(formals[1])) return error.TestUnexpectedResult;
        if (clause_matches == 0) continue;
        if (clause_matches != 1 or owner_row_index != null or
            !owner.owned_by_annotation or owner.rigid_var != @intFromEnum(formals[0]))
        {
            return error.TestUnexpectedResult;
        }
        owner_row_index = where.owners.span.start + @as(u32, @intCast(owner_offset));
    }
    return .{
        .annotation_idx = annotation_idx,
        .function_idx = function_idx,
        .formals = .{ formals[0], formals[1] },
        .where_idx = where_idx,
        .receiver_idx = clause.w_alias.var_,
        .owner_row_index = owner_row_index orelse return error.TestUnexpectedResult,
    };
}

const SerializedDirectBinderRecoveryProof = struct {
    lookup: DirectBinderLookupTestProof,
    body_publication_index: u32,
    attachment_index: u32,
    malformed_publication_index: u32,
    malformed_diagnostic_index: u32,
};

fn expectSerializedDirectBinderRecoveryProofEqual(
    expected: SerializedDirectBinderRecoveryProof,
    actual: SerializedDirectBinderRecoveryProof,
) !void {
    inline for (.{
        "failure_index",
        "source_retirement_index",
        "lookup_retirement_index",
    }) |field_name| {
        try std.testing.expectEqual(
            @field(expected.lookup, field_name),
            @field(actual.lookup, field_name),
        );
    }
    try std.testing.expectEqual(
        @intFromEnum(expected.lookup.pattern_idx),
        @intFromEnum(actual.lookup.pattern_idx),
    );
    inline for (.{ "producer_node", "phase", "local_record_index" }) |field_name| {
        try std.testing.expectEqual(
            @field(expected.lookup.direct, field_name),
            @field(actual.lookup.direct, field_name),
        );
    }
    inline for (.{
        "body_publication_index",
        "attachment_index",
        "malformed_publication_index",
        "malformed_diagnostic_index",
    }) |field_name| {
        try std.testing.expectEqual(@field(expected, field_name), @field(actual, field_name));
    }
}

fn expectSerializedDirectBinderRecoveryState(
    cir: *const ModuleEnv,
    context: ImportResolution,
    expected: ?SerializedDirectBinderRecoveryProof,
) !SerializedDirectBinderRecoveryProof {
    try std.testing.expectEqual(@as(usize, 2), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 1), cir.malformed_type_annotation_publications.items.items.len);
    try std.testing.expectEqual(@as(usize, 1), cir.body_annotation_attachments.items.items.len);
    try std.testing.expectEqual(@as(usize, 1), cir.body_annotation_malformed_type_publications.items.items.len);

    const lookup = try uniqueDirectBinderLookupTestProof(cir);
    const lookup_failure = cir.expected_failures.items.items[lookup.failure_index];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.direct_binder_lookup_checked_error,
        lookup_failure.decodedKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.SubjectAuthority.DirectPhase.direct_binder_lookup_checked_error,
        lookup_failure.subject_authority.decodedDirectPhase().?,
    );
    try std.testing.expectEqual(@intFromEnum(lookup.pattern_idx), lookup.direct.producer_node);

    const source_failure_index = lookup.direct.local_record_index;
    try std.testing.expect(source_failure_index < lookup.failure_index);
    const source_failure = cir.expected_failures.items.items[source_failure_index];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
        source_failure.decodedKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.SubjectAuthority.DirectPhase.annotation_malformed_type,
        source_failure.subject_authority.decodedDirectPhase().?,
    );
    const source_direct = source_failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    const diagnostic = source_failure.cause_owner.decodedCirDiagnostic() orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(
        cir.store.getDiagnostic(@enumFromInt(diagnostic.index)) == .undeclared_type,
    );

    const body_publication_index = source_direct.local_record_index;
    try std.testing.expect(
        body_publication_index < cir.body_annotation_malformed_type_publications.items.items.len,
    );
    const body_publication = cir.body_annotation_malformed_type_publications.items.items[
        body_publication_index
    ];
    try std.testing.expect(bodyAnnotationMalformedTypePublicationIsLocallyValid(
        cir,
        body_publication,
    ));
    try std.testing.expectEqual(source_failure.owner_node, body_publication.body_expr);
    try std.testing.expectEqual(source_failure.site_node, source_direct.producer_node);

    const malformed_publication_index = body_publication.malformed_type_publication_index;
    try std.testing.expect(
        malformed_publication_index < cir.malformed_type_annotation_publications.items.items.len,
    );
    const malformed_publication = cir.malformed_type_annotation_publications.items.items[
        malformed_publication_index
    ];
    try std.testing.expectEqual(source_failure.site_node, malformed_publication.annotation_node);
    try std.testing.expectEqual(diagnostic.index, malformed_publication.diagnostic_index);

    const attachment_kind = body_publication.decodedAttachmentKind() orelse
        return error.TestUnexpectedResult;
    const attachment_index = cir.bodyAnnotationAttachmentIndex(
        attachment_kind,
        body_publication.attachment_node,
        @enumFromInt(body_publication.annotation_root),
        @enumFromInt(body_publication.body_expr),
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cir.bodyAnnotationAttachmentIsLocallyValid(attachment_index));

    const source_retirement = cir.expected_consumer_retirements.items.items[
        lookup.source_retirement_index
    ];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        source_retirement.decodedKind().?,
    );
    try std.testing.expectEqual(CIR.Node.Tag.expr_lambda, source_retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(@as(u32, 1), source_retirement.expected_failures_len);
    try std.testing.expect(expectedAnnotationRetirementOwnsFailure(
        cir,
        lookup.source_retirement_index,
        source_failure_index,
        source_failure.owner_node,
    ));
    try std.testing.expectEqual(
        source_failure_index,
        cir.expected_retirement_failures.items.items[
            source_retirement.expected_failures_start
        ].failure_index,
    );
    try std.testing.expect(
        cir.store.getDiagnostic(@enumFromInt(source_retirement.diagnostic_index)) ==
            .erroneous_value_expr,
    );
    try std.testing.expect(cir.store.getExpr(@enumFromInt(source_retirement.retired_node)) == .e_runtime_error);

    const lookup_retirement = cir.expected_consumer_retirements.items.items[
        lookup.lookup_retirement_index
    ];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        lookup_retirement.decodedKind().?,
    );
    try std.testing.expectEqual(CIR.Node.Tag.expr_var, lookup_retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(@as(u32, 1), lookup_retirement.expected_failures_len);
    try std.testing.expectEqual(
        lookup.failure_index,
        cir.expected_retirement_failures.items.items[
            lookup_retirement.expected_failures_start
        ].failure_index,
    );
    try std.testing.expect(
        cir.store.getDiagnostic(@enumFromInt(lookup_retirement.diagnostic_index)) ==
            .erroneous_value_use,
    );
    try std.testing.expect(cir.store.getExpr(@enumFromInt(lookup_retirement.retired_node)) == .e_runtime_error);

    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);

    const actual = SerializedDirectBinderRecoveryProof{
        .lookup = lookup,
        .body_publication_index = body_publication_index,
        .attachment_index = attachment_index,
        .malformed_publication_index = malformed_publication_index,
        .malformed_diagnostic_index = diagnostic.index,
    };
    if (expected) |wanted| {
        try expectSerializedDirectBinderRecoveryProofEqual(wanted, actual);
    }
    return actual;
}

fn expectSerializedRecoveryPoolHeaderCorruptionRejected(
    comptime field_name: []const u8,
    serialized: *const ModuleEnv.Serialized,
    backing_len: usize,
) !void {
    try std.testing.expect(@field(serialized.*, field_name).len != 0);

    var corrupt = serialized.*;
    @field(corrupt, field_name).offset = std.math.maxInt(i64);
    try std.testing.expectError(error.CorruptArtifact, corrupt.validate(backing_len));

    corrupt = serialized.*;
    @field(corrupt, field_name).len = std.math.maxInt(u64);
    @field(corrupt, field_name).capacity = std.math.maxInt(u64);
    try std.testing.expectError(error.CorruptArtifact, corrupt.validate(backing_len));
}

const direct_binder_transaction_provider_source =
    \\a.Status : where [a.status : a -> [Off, On]]
;

const direct_binder_transaction_consumer_source =
    \\import DirectBinderTransactionA exposing [Status]
    \\
    \\first : a -> (a, a, a, a, a, a, a, a, a, a, a, a, a, a, a, a) where [a.Status]
    \\first = |value| (value, value, value, value, value, value, value, value, value, value, value, value, value, value, value, value)
;

const DirectBinderTransactionTestSite = struct {
    def_idx: CIR.Def.Idx,
    annotation_idx: CIR.Annotation.Idx,
    where: CIR.WhereClause.Span,
    where_idx: CIR.WhereClause.Idx,
    owner_expr: CIR.Expr.Idx,
    lambda_expr: CIR.Expr.Idx,
    pattern_idx: CIR.Pattern.Idx,
    formal_var: Var,
    lookup_exprs: CIR.Expr.Span,
};

fn directBinderTransactionTestSite(
    test_env: anytype,
) error{TestUnexpectedResult}!DirectBinderTransactionTestSite {
    const cir = test_env.module_env;
    const def_idx = test_env.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const def = cir.store.getDef(def_idx);
    const annotation_idx = def.annotation orelse return error.TestUnexpectedResult;
    const annotation = cir.store.getAnnotation(annotation_idx);
    const where = annotation.where orelse return error.TestUnexpectedResult;
    const clauses = cir.store.sliceWhereClauses(where);
    if (clauses.len != 1) return error.TestUnexpectedResult;
    const where_idx = clauses[0];
    const clause = cir.store.getWhereClause(where_idx);
    if (clause != .w_alias or cir.store.getTypeAnno(clause.w_alias.alias) != .malformed) {
        return error.TestUnexpectedResult;
    }
    const annotation_fn = cir.store.getTypeAnno(annotation.anno);
    if (annotation_fn != .@"fn") return error.TestUnexpectedResult;
    const formals = cir.store.sliceTypeAnnos(annotation_fn.@"fn".args);
    if (formals.len != 1 or cir.store.getTypeAnno(formals[0]) != .rigid_var) {
        return error.TestUnexpectedResult;
    }
    const receiver = cir.store.getTypeAnno(clause.w_alias.var_);
    if (receiver != .rigid_var_lookup or receiver.rigid_var_lookup.ref != formals[0]) {
        return error.TestUnexpectedResult;
    }
    var matching_owner_count: usize = 0;
    var matching_clause_count: usize = 0;
    for (cir.store.sliceWhereClauseOwners(where)) |where_owner| {
        if (!where_owner.owned_by_annotation or
            where_owner.rigid_var != @intFromEnum(formals[0]))
        {
            continue;
        }
        matching_owner_count += 1;
        for (cir.store.sliceWhereClausesForOwner(where_owner)) |owned_where| {
            if (owned_where == where_idx) matching_clause_count += 1;
        }
    }
    if (matching_owner_count != 1 or matching_clause_count != 1) {
        return error.TestUnexpectedResult;
    }
    const owner = cir.store.getExpr(def.expr);
    if (owner != .e_lambda) return error.TestUnexpectedResult;
    const patterns = cir.store.slicePatterns(owner.e_lambda.args);
    if (patterns.len != 1 or cir.store.getPattern(patterns[0]) != .assign) {
        return error.TestUnexpectedResult;
    }
    const body = cir.store.getExpr(owner.e_lambda.body);
    if (body != .e_tuple) return error.TestUnexpectedResult;
    const lookups = cir.store.sliceExpr(body.e_tuple.elems);
    if (lookups.len != 16) return error.TestUnexpectedResult;
    for (lookups) |lookup_expr| {
        const lookup = cir.store.getExpr(lookup_expr);
        if (lookup != .e_lookup_local or lookup.e_lookup_local.pattern_idx != patterns[0]) {
            return error.TestUnexpectedResult;
        }
    }
    return .{
        .def_idx = def_idx,
        .annotation_idx = annotation_idx,
        .where = where,
        .where_idx = where_idx,
        .owner_expr = def.expr,
        .lambda_expr = def.expr,
        .pattern_idx = patterns[0],
        .formal_var = ModuleEnv.varFrom(formals[0]),
        .lookup_exprs = body.e_tuple.elems,
    };
}

fn publishDirectBinderTransactionSourceForTest(
    checker: *Self,
    site: DirectBinderTransactionTestSite,
    env: *Env,
    accumulator: *AnnotationGenerationAccumulator,
) Allocator.Error!void {
    const clause = checker.cir.store.getWhereClause(site.where_idx);
    if (clause != .w_alias) {
        std.debug.panic("direct-binder transaction fixture lost its malformed alias", .{});
    }
    try checker.declareWhereAliasConstraints(
        site.where_idx,
        @intFromEnum(site.annotation_idx),
        clause.w_alias,
        site.formal_var,
        null,
        env,
        .{ .annotation = .{
            .where = site.where,
            .producer_owner_node = @intFromEnum(site.annotation_idx),
            .failure_publication = .{ .body_expression = .{
                .owner_expr = site.owner_expr,
                .attachment = .{
                    .kind = .top_level_def,
                    .node = @intFromEnum(site.def_idx),
                },
            } },
            .failure_accumulator = accumulator,
            .where_source_publication = .body_annotation,
            .opening = .implicit_open,
        } },
    );
}

/// The unchecked fixture intentionally stops after canonicalization. The real
/// checker fills one placeholder type slot for every CIR region before any
/// annotation producer can resolve or poison its raw variable. Reproduce that
/// exact prerequisite before allocation calibration; do not manufacture a
/// type for the selected formal or run the surrounding file checker.
fn prepareDirectBinderTransactionCheckerForTest(
    checker: *Self,
    site: anytype,
) !void {
    try checker.ensureTypeStoreIsFilled();
    const type_nodes: usize = @intCast(checker.types.len());
    try std.testing.expectEqual(@as(usize, @intCast(checker.regions.len())), type_nodes);
    try std.testing.expect(@as(usize, @intFromEnum(site.formal_var)) < type_nodes);
    try std.testing.expect(@as(usize, @intFromEnum(site.owner_expr)) < type_nodes);
    const formal = checker.types.resolveVar(site.formal_var);
    try std.testing.expect(formal.is_root);
    try std.testing.expect(formal.desc.content == .flex);
    try std.testing.expectEqual(Rank.outermost, formal.desc.rank);
}

fn stageDirectBinderTransactionSourceForTest(
    checker: *Self,
    site: DirectBinderTransactionTestSite,
) !void {
    try prepareDirectBinderTransactionCheckerForTest(checker, site);
    const failure_start = checker.cir.expected_failures.items.items.len;
    const retirement_start = checker.cir.expected_consumer_retirements.items.items.len;
    const draft_start = checker.annotation_expected_failure_drafts.items.len;
    const source_start = checker.direct_formal_failure_sources.items.len;
    var env = try Env.init(std.testing.allocator, .outermost);
    defer env.deinit(std.testing.allocator);
    var accumulator = AnnotationGenerationAccumulator{};
    try publishDirectBinderTransactionSourceForTest(checker, site, &env, &accumulator);
    try std.testing.expectEqual(failure_start + 1, checker.cir.expected_failures.items.items.len);
    try std.testing.expectEqual(
        retirement_start + 1,
        checker.cir.expected_consumer_retirements.items.items.len,
    );
    try std.testing.expectEqual(draft_start + 1, checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqual(source_start + 1, checker.direct_formal_failure_sources.items.len);
    const failure = checker.cir.expected_failures.items.items[failure_start];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
        failure.decodedKind().?,
    );
    const source = checker.direct_formal_failure_sources.items[source_start];
    try std.testing.expectEqual(@as(u32, @intCast(failure_start)), source.failure_index);
    try std.testing.expectEqual(@as(u32, @intCast(retirement_start)), source.retirement_index);
    try std.testing.expectEqual(site.annotation_idx, source.annotation_idx);
    try std.testing.expectEqual(site.owner_expr, source.owner_expr);
    try std.testing.expectEqual(site.where_idx, source.where_clause);
    try std.testing.expectEqual(site.formal_var, source.rigid_var);
    const accumulated = accumulator.first_failure orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(source.failure_index, accumulated.failure_index);
    const accumulated_retirement = accumulated.cause_owner.decodedExpectedConsumerRetirement() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(source.retirement_index, accumulated_retirement.index);
    const clause = checker.cir.store.getWhereClause(site.where_idx);
    if (clause != .w_alias) return error.TestUnexpectedResult;
    const malformed = checker.cir.store.getTypeAnno(clause.w_alias.alias);
    if (malformed != .malformed) return error.TestUnexpectedResult;
    const diagnostic = failure.cause_owner.decodedCirDiagnostic() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(@intFromEnum(malformed.malformed.diagnostic), diagnostic.index);
}

