    try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 1), checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 1), checker.direct_formal_failure_sources.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
    const failure = cir.expected_failures.items.items[0];
