        ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
        failure.decodedKind().?,
    );
    const diagnostic = failure.cause_owner.decodedCirDiagnostic() orelse
        return error.TestUnexpectedResult;
    const clause = cir.store.getWhereClause(site.where_idx);
    if (clause != .w_alias) return error.TestUnexpectedResult;
    const malformed = cir.store.getTypeAnno(clause.w_alias.alias);
    if (malformed != .malformed) return error.TestUnexpectedResult;
    try std.testing.expectEqual(@intFromEnum(malformed.malformed.diagnostic), diagnostic.index);
    const retirement = cir.expected_consumer_retirements.items.items[0];
    try std.testing.expectEqual(@intFromEnum(site.owner_expr), retirement.retired_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        retirement.decodedKind().?,
    );
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_len);
    const draft = checker.annotation_expected_failure_drafts.items[0];
    try std.testing.expectEqual(site.owner_expr, draft.owner_expr);
    try std.testing.expectEqual(@as(u32, 0), draft.retirement_index);
    try std.testing.expectEqual(@as(u32, 0), draft.failure_index);
    try std.testing.expectEqual(AnnotationExpectedFailureDraft.ProducerKind.annotation, draft.producer_kind);
    const source = checker.direct_formal_failure_sources.items[0];
    try std.testing.expectEqual(site.annotation_idx, source.annotation_idx);
    try std.testing.expectEqual(site.owner_expr, source.owner_expr);
    try std.testing.expectEqual(site.where_idx, source.where_clause);
    try std.testing.expectEqual(site.formal_var, source.rigid_var);
    try std.testing.expectEqual(@as(u32, 0), source.failure_index);
    try std.testing.expectEqual(@as(u32, 0), source.retirement_index);
    return source;
}

