fn directBinderLookupAllocationTargetForTest(
    checker: *Self,
    site: DirectBinderTransactionTestSite,
    active: ActiveDirectBinderFailure,
) !CIR.Expr.Idx {
    for (checker.cir.store.sliceExpr(site.lookup_exprs)) |lookup_expr| {
        const retirement_items = &checker.cir.expected_consumer_retirements.items;
        const failure_items = &checker.cir.expected_failures.items;
        if (retirement_items.items.len == retirement_items.capacity or
            failure_items.items.len == failure_items.capacity or
            checker.annotation_expected_failure_drafts.items.len ==
                checker.annotation_expected_failure_drafts.capacity)
        {
            return lookup_expr;
        }
        _ = try checker.publishDirectBinderLookupCheckedError(
            lookup_expr,
            site.pattern_idx,
            active,
        );
    }
    return error.TestUnexpectedResult;
}

