fn expectDirectBinderLookupDraftForTest(
    checker: *const Self,
    site: anytype,
    active: ActiveDirectBinderFailure,
    lookup_expr: CIR.Expr.Idx,
    failure_index: u32,
    retirement_index: u32,
) !ModuleEnv.CauseOwner {
    const cir = checker.cir;
    if (failure_index >= cir.expected_failures.items.items.len or
        retirement_index >= cir.expected_consumer_retirements.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const failure = cir.expected_failures.items.items[failure_index];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.direct_binder_lookup_checked_error,
        failure.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(lookup_expr), failure.owner_node);
    try std.testing.expectEqual(@intFromEnum(site.pattern_idx), failure.site_node);
    try std.testing.expectEqual(@intFromEnum(site.formal_var), failure.raw_peer_var);
    const direct = failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        ModuleEnv.SubjectAuthority.DirectPhase.direct_binder_lookup_checked_error,
        failure.subject_authority.decodedDirectPhase().?,
    );
    try std.testing.expectEqual(active.source_failure_index, direct.local_record_index);
    const cause = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(active.source_retirement_index, cause.index);
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    try std.testing.expectEqual(@intFromEnum(lookup_expr), retirement.retired_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        retirement.decodedKind().?,
    );
    try std.testing.expectEqual(CIR.Node.Tag.expr_var, retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_len);
    const current_node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(lookup_expr));
    const current_payload: [4]u32 = @bitCast(current_node.getPayload());
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&retirement.original_payload),
        std.mem.asBytes(&current_payload),
    );
    var matching_drafts: usize = 0;
    for (checker.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr != lookup_expr) continue;
        try std.testing.expectEqual(retirement_index, draft.retirement_index);
        try std.testing.expectEqual(failure_index, draft.failure_index);
        try std.testing.expectEqual(
            AnnotationExpectedFailureDraft.ProducerKind.direct_binder_lookup,
            draft.producer_kind,
        );
        matching_drafts += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), matching_drafts);
    return ModuleEnv.CauseOwner.expectedConsumerRetirement(retirement_index);
}

fn addDirectBinderLookupDiagnosticForTest(
    checker: *Self,
    site: DirectBinderTransactionTestSite,
    lookup_expr: CIR.Expr.Idx,
) !CIR.Diagnostic.Idx {
    const ident = checker.getPatternIdent(site.pattern_idx) orelse
        return error.TestUnexpectedResult;
    const diagnostic_idx = try checker.cir.addDiagnostic(.{ .erroneous_value_use = .{
        .ident = ident,
        .region = checker.cir.store.getExprRegion(lookup_expr),
    } });
    if (checker.cir.store.getDiagnostic(diagnostic_idx) != .erroneous_value_use) {
        return error.TestUnexpectedResult;
    }
    return diagnostic_idx;
}

const DirectBinderDiagnosticState = struct {
    published: CIR.Diagnostic.Span,
    pending: []CIR.Diagnostic.Idx,

    fn capture(cir: *const ModuleEnv) !DirectBinderDiagnosticState {
        const scratch = cir.store.scratch orelse return error.TestUnexpectedResult;
        return .{
            .published = cir.diagnostics,
            .pending = try std.testing.allocator.dupe(
                CIR.Diagnostic.Idx,
                scratch.diagnostics.items.items,
            ),
        };
    }

    fn deinit(self: DirectBinderDiagnosticState) void {
        std.testing.allocator.free(self.pending);
    }

    fn expectUnchanged(self: DirectBinderDiagnosticState, cir: *const ModuleEnv) !void {
        const scratch = cir.store.scratch orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&self.published),
            std.mem.asBytes(&cir.diagnostics),
        );
        try std.testing.expectEqualSlices(
            CIR.Diagnostic.Idx,
            self.pending,
            scratch.diagnostics.items.items,
        );
    }
};

fn expectCompletedDirectBinderLookupForTest(
    checker: *const Self,
    site: DirectBinderTransactionTestSite,
    active: ActiveDirectBinderFailure,
    lookup_expr: CIR.Expr.Idx,
    failure_index: u32,
    retirement_index: u32,
    failure_refs_start: usize,
    diagnostic_idx: CIR.Diagnostic.Idx,
    original_node: CIR.Node,
) !void {
    const cir = checker.cir;
    if (failure_index >= cir.expected_failures.items.items.len or
        retirement_index >= cir.expected_consumer_retirements.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const failure = cir.expected_failures.items.items[failure_index];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.direct_binder_lookup_checked_error,
        failure.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(lookup_expr), failure.owner_node);
    try std.testing.expectEqual(@intFromEnum(site.pattern_idx), failure.site_node);
    try std.testing.expectEqual(@intFromEnum(site.formal_var), failure.raw_peer_var);
    const direct = failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(active.source_failure_index, direct.local_record_index);
    const cause = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(active.source_retirement_index, cause.index);

    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    try std.testing.expectEqual(@intFromEnum(lookup_expr), retirement.retired_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        retirement.decodedKind().?,
    );
    try std.testing.expectEqual(CIR.Node.Tag.expr_var, retirement.decodedOriginalNodeTag().?);
    const original_payload: [4]u32 = @bitCast(original_node.getPayload());
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&original_payload),
        std.mem.asBytes(&retirement.original_payload),
    );
    try std.testing.expectEqual(@intFromEnum(diagnostic_idx), retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, @intCast(failure_refs_start)), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 1), retirement.expected_failures_len);
    try std.testing.expectEqual(failure_refs_start + 1, cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(
        failure_index,
        cir.expected_retirement_failures.items.items[failure_refs_start].failure_index,
    );
    for (checker.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr == lookup_expr) return error.TestUnexpectedResult;
    }
}

const DirectBinderLookupCompletionTestStage = struct {
    site: DirectBinderTransactionTestSite,
    active: ActiveDirectBinderFailure,
    lookup_expr: CIR.Expr.Idx,
    failure_index: u32,
    retirement_index: u32,
    diagnostic_idx: CIR.Diagnostic.Idx,
    original_node: CIR.Node,
};

fn stageDirectBinderLookupCompletionForTest(
    test_env: anytype,
) !DirectBinderLookupCompletionTestStage {
    const checker = &test_env.checker;
    const cir = test_env.module_env;
    const site = try directBinderTransactionTestSite(test_env);
    try stageDirectBinderTransactionSourceForTest(checker, site);
    try activateDirectBinderTransactionForTest(checker, site, 0);
    const active = try expectSingleActiveDirectBinderTransactionForTest(checker, site);
    const lookup_expr = cir.store.sliceExpr(site.lookup_exprs)[0];
    const failure_index: u32 = @intCast(cir.expected_failures.items.items.len);
    const retirement_index: u32 = @intCast(cir.expected_consumer_retirements.items.items.len);
    const drafts_start = checker.annotation_expected_failure_drafts.items.len;
    const cause = try checker.publishDirectBinderLookupCheckedError(
        lookup_expr,
        site.pattern_idx,
        active,
    );
    try std.testing.expectEqual(
        retirement_index,
        cause.decodedExpectedConsumerRetirement().?.index,
    );
    _ = try expectDirectBinderLookupDraftForTest(
        checker,
        site,
        active,
        lookup_expr,
        failure_index,
        retirement_index,
    );
    try std.testing.expectEqual(
        @as(usize, failure_index) + 1,
        cir.expected_failures.items.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, retirement_index) + 1,
        cir.expected_consumer_retirements.items.items.len,
    );
    try std.testing.expectEqual(
        drafts_start + 1,
        checker.annotation_expected_failure_drafts.items.len,
    );
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);
    const original_node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(lookup_expr));
    try std.testing.expectEqual(CIR.Node.Tag.expr_var, original_node.tag);
    const diagnostic_idx = try addDirectBinderLookupDiagnosticForTest(
        checker,
        site,
        lookup_expr,
    );
    return .{
        .site = site,
        .active = active,
        .lookup_expr = lookup_expr,
        .failure_index = failure_index,
        .retirement_index = retirement_index,
        .diagnostic_idx = diagnostic_idx,
        .original_node = original_node,
    };
}

test "invalid where alias direct source publication is atomic across OOM" {
    const TestEnv = @import("test/TestEnv.zig");
    var provider = try TestEnv.init(
        "DirectBinderTransactionA",
        direct_binder_transaction_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    var calibration_consumer = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderSourceOomB",
        direct_binder_transaction_consumer_source,
        "DirectBinderTransactionA",
        &provider,
    );
    defer calibration_consumer.deinit();
    try calibration_consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const calibration_checker = &calibration_consumer.checker;
    const calibration_cir = calibration_consumer.module_env;
    const calibration_site = try directBinderTransactionTestSite(&calibration_consumer);
    try prepareDirectBinderTransactionCheckerForTest(
        calibration_checker,
        calibration_site,
    );
    var calibration_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const calibration_gpa = calibration_allocator.allocator();
    var calibration_env = try Env.init(calibration_gpa, .outermost);
    defer calibration_env.deinit(calibration_gpa);
    var calibration_accumulator = AnnotationGenerationAccumulator{};
    const allocation_base = calibration_allocator.alloc_index;
    calibration_allocator.resize_fail_index = calibration_allocator.resize_index;
    {
        const saved_checker_gpa = calibration_checker.gpa;
        const saved_cir_gpa = calibration_cir.gpa;
        const saved_types_gpa = calibration_checker.types.gpa;
        calibration_checker.gpa = calibration_gpa;
        calibration_cir.gpa = calibration_gpa;
        calibration_checker.types.gpa = calibration_gpa;
        defer {
            calibration_checker.types.gpa = saved_types_gpa;
            calibration_cir.gpa = saved_cir_gpa;
            calibration_checker.gpa = saved_checker_gpa;
        }
        try publishDirectBinderTransactionSourceForTest(
            calibration_checker,
            calibration_site,
            &calibration_env,
            &calibration_accumulator,
        );
    }
    const calibration_allocations = calibration_allocator.alloc_index - allocation_base;
    try std.testing.expect(!calibration_allocator.has_induced_failure);
    try std.testing.expect(calibration_allocations > 0);
    const calibration_source = try expectSingleDirectBinderTransactionSourceForTest(
        calibration_checker,
        calibration_site,
    );
    try std.testing.expect(calibration_checker.types.resolveVar(
        calibration_site.formal_var,
    ).desc.content == .err);
    const calibration_failure = calibration_cir.expected_failures.items.items[0];
    const calibration_retirement = calibration_cir.expected_consumer_retirements.items.items[0];
    const calibration_draft = calibration_checker.annotation_expected_failure_drafts.items[0];
    var calibration_retry = AnnotationGenerationAccumulator{};
    try publishDirectBinderTransactionSourceForTest(
        calibration_checker,
        calibration_site,
        &calibration_env,
        &calibration_retry,
    );
    try std.testing.expect(std.meta.eql(
        calibration_source,
        try expectSingleDirectBinderTransactionSourceForTest(
            calibration_checker,
            calibration_site,
        ),
    ));
    try std.testing.expect(expectedFailuresEqual(
        calibration_failure,
        calibration_cir.expected_failures.items.items[0],
    ));
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&calibration_retirement),
        std.mem.asBytes(&calibration_cir.expected_consumer_retirements.items.items[0]),
    );
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&calibration_draft),
        std.mem.asBytes(&calibration_checker.annotation_expected_failure_drafts.items[0]),
    );
    const calibration_retried = calibration_retry.first_failure orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(calibration_source.failure_index, calibration_retried.failure_index);

    var failure_index: usize = 0;
    while (failure_index < calibration_allocations) : (failure_index += 1) {
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "DirectBinderSourceOomB",
            direct_binder_transaction_consumer_source,
            "DirectBinderTransactionA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        const checker = &consumer.checker;
        const cir = consumer.module_env;
        const site = try directBinderTransactionTestSite(&consumer);
        try prepareDirectBinderTransactionCheckerForTest(checker, site);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_failures.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), checker.annotation_expected_failure_drafts.items.len);
        try std.testing.expectEqual(@as(usize, 0), checker.direct_formal_failure_sources.items.len);
        try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
        const original_formal = checker.types.resolveVar(site.formal_var);

        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = std.math.maxInt(usize),
            .resize_fail_index = std.math.maxInt(usize),
        });
        const failing_allocator = failing.allocator();
        var env = try Env.init(failing_allocator, .outermost);
        defer env.deinit(failing_allocator);
        var accumulator = AnnotationGenerationAccumulator{};
        const failure_allocation_base = failing.alloc_index;
        failing.fail_index = std.math.add(
            usize,
            failure_allocation_base,
            failure_index,
        ) catch return error.TestUnexpectedResult;
        failing.resize_fail_index = failing.resize_index;
        const result = blk: {
            const saved_checker_gpa = checker.gpa;
            const saved_cir_gpa = cir.gpa;
            const saved_types_gpa = checker.types.gpa;
            checker.gpa = failing_allocator;
            cir.gpa = failing_allocator;
            checker.types.gpa = failing_allocator;
            defer {
                checker.types.gpa = saved_types_gpa;
                cir.gpa = saved_cir_gpa;
                checker.gpa = saved_checker_gpa;
            }
            break :blk publishDirectBinderTransactionSourceForTest(
                checker,
                site,
                &env,
                &accumulator,
            );
        };
        try std.testing.expectError(error.OutOfMemory, result);
        try std.testing.expect(failing.has_induced_failure);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_failures.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), checker.annotation_expected_failure_drafts.items.len);
        try std.testing.expectEqual(@as(usize, 0), checker.direct_formal_failure_sources.items.len);
        try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
        try std.testing.expect(accumulator.first_failure == null);
        try std.testing.expect(accumulator.suppression == null);
        try std.testing.expect(std.meta.eql(
            original_formal,
            checker.types.resolveVar(site.formal_var),
        ));

        failing.fail_index = std.math.maxInt(usize);
        failing.resize_fail_index = std.math.maxInt(usize);
        var retry_accumulator = AnnotationGenerationAccumulator{};
        try publishDirectBinderTransactionSourceForTest(
            checker,
            site,
            &env,
            &retry_accumulator,
        );
        const source = try expectSingleDirectBinderTransactionSourceForTest(checker, site);
        try std.testing.expect(checker.types.resolveVar(site.formal_var).desc.content == .err);
        const saved_failure = cir.expected_failures.items.items[0];
        const saved_retirement = cir.expected_consumer_retirements.items.items[0];
        const saved_draft = checker.annotation_expected_failure_drafts.items[0];
        var revisit_accumulator = AnnotationGenerationAccumulator{};
        try publishDirectBinderTransactionSourceForTest(
            checker,
            site,
            &env,
            &revisit_accumulator,
        );
        try std.testing.expect(std.meta.eql(
            source,
            try expectSingleDirectBinderTransactionSourceForTest(checker, site),
        ));
        try std.testing.expect(expectedFailuresEqual(
            saved_failure,
            cir.expected_failures.items.items[0],
        ));
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&saved_retirement),
            std.mem.asBytes(&cir.expected_consumer_retirements.items.items[0]),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&saved_draft),
            std.mem.asBytes(&checker.annotation_expected_failure_drafts.items[0]),
        );
        const retried = retry_accumulator.first_failure orelse
            return error.TestUnexpectedResult;
        const revisited = revisit_accumulator.first_failure orelse
            return error.TestUnexpectedResult;
        try std.testing.expectEqual(source.failure_index, retried.failure_index);
        try std.testing.expectEqual(source.failure_index, revisited.failure_index);
    }
}

test "invalid where alias direct binder lookup publication rolls back and retries" {
    const TestEnv = @import("test/TestEnv.zig");
    var provider = try TestEnv.init(
        "DirectBinderTransactionA",
        direct_binder_transaction_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    // Activation has its own allocation boundary. A failed capacity reserve
    // leaves the authentic source tuple untouched and no partially active
    // binder; the same exact source then activates once under the real retry.
    {
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "DirectBinderActivationOomB",
            direct_binder_transaction_consumer_source,
            "DirectBinderTransactionA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        const checker = &consumer.checker;
        const cir = consumer.module_env;
        const site = try directBinderTransactionTestSite(&consumer);
        try stageDirectBinderTransactionSourceForTest(checker, site);
        const source_before = try expectSingleDirectBinderTransactionSourceForTest(checker, site);
        const failure_before = cir.expected_failures.items.items[0];
        const retirement_before = cir.expected_consumer_retirements.items.items[0];
        const draft_before = checker.annotation_expected_failure_drafts.items[0];
        try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);

        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = 0,
            .resize_fail_index = 0,
        });
        const failing_gpa = failing.allocator();
        const result = blk: {
            const saved_checker_gpa = checker.gpa;
            const saved_cir_gpa = cir.gpa;
            const saved_types_gpa = checker.types.gpa;
            checker.gpa = failing_gpa;
            cir.gpa = failing_gpa;
            checker.types.gpa = failing_gpa;
            defer {
                checker.types.gpa = saved_types_gpa;
                cir.gpa = saved_cir_gpa;
                checker.gpa = saved_checker_gpa;
            }
            break :blk activateDirectBinderTransactionForTest(checker, site, 0);
        };
        try std.testing.expectError(error.OutOfMemory, result);
        try std.testing.expect(failing.has_induced_failure);
        try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
        try std.testing.expect(std.meta.eql(
            source_before,
            try expectSingleDirectBinderTransactionSourceForTest(checker, site),
        ));
        try std.testing.expect(expectedFailuresEqual(
            failure_before,
            cir.expected_failures.items.items[0],
        ));
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&retirement_before),
            std.mem.asBytes(&cir.expected_consumer_retirements.items.items[0]),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&draft_before),
            std.mem.asBytes(&checker.annotation_expected_failure_drafts.items[0]),
        );

        try activateDirectBinderTransactionForTest(checker, site, 0);
        const active = try expectSingleActiveDirectBinderTransactionForTest(checker, site);

        // Probe publication owns only the new lookup tuple. Its upstream
        // source and activation predate the Probe and must survive rollback.
        const lookup_expr = cir.store.sliceExpr(site.lookup_exprs)[0];
        const failures_before_probe = cir.expected_failures.items.items.len;
        const retirements_before_probe = cir.expected_consumer_retirements.items.items.len;
        const drafts_before_probe = checker.annotation_expected_failure_drafts.items.len;
        const failure_refs_before_probe = cir.expected_retirement_failures.items.items.len;
        const retired_consumers_before_probe = cir.expected_retired_consumers.items.items.len;
        const lookup_node_before_probe = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(lookup_expr));
        {
            var probe = try checker.beginProbe(null);
            var probe_open = true;
            errdefer if (probe_open) probe.rollback();
            const cause = try checker.publishDirectBinderLookupCheckedError(
                lookup_expr,
                site.pattern_idx,
                active,
            );
            try std.testing.expectEqual(
                @as(u32, @intCast(retirements_before_probe)),
                cause.decodedExpectedConsumerRetirement().?.index,
            );
            try std.testing.expectEqual(failures_before_probe + 1, cir.expected_failures.items.items.len);
            try std.testing.expectEqual(
                retirements_before_probe + 1,
                cir.expected_consumer_retirements.items.items.len,
            );
            try std.testing.expectEqual(drafts_before_probe + 1, checker.annotation_expected_failure_drafts.items.len);
            probe.rollback();
            probe_open = false;
        }
        try std.testing.expectEqual(failures_before_probe, cir.expected_failures.items.items.len);
        try std.testing.expectEqual(retirements_before_probe, cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(drafts_before_probe, checker.annotation_expected_failure_drafts.items.len);
        try std.testing.expectEqual(failure_refs_before_probe, cir.expected_retirement_failures.items.items.len);
        try std.testing.expectEqual(retired_consumers_before_probe, cir.expected_retired_consumers.items.items.len);
        try std.testing.expect(expectedFailuresEqual(
            failure_before,
            cir.expected_failures.items.items[0],
        ));
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&retirement_before),
            std.mem.asBytes(&cir.expected_consumer_retirements.items.items[0]),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&draft_before),
            std.mem.asBytes(&checker.annotation_expected_failure_drafts.items[0]),
        );
        const lookup_node_after_probe = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(lookup_expr));
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&lookup_node_before_probe),
            std.mem.asBytes(&lookup_node_after_probe),
        );
        try std.testing.expect(std.meta.eql(source_before, checker.direct_formal_failure_sources.items[0]));
        try std.testing.expect(std.meta.eql(active, checker.active_direct_binder_failures.items[0]));
        const republished = try checker.publishDirectBinderLookupCheckedError(
            lookup_expr,
            site.pattern_idx,
            active,
        );
        try std.testing.expectEqual(
            @as(u32, @intCast(retirements_before_probe)),
            republished.decodedExpectedConsumerRetirement().?.index,
        );
        try std.testing.expectEqual(failures_before_probe + 1, cir.expected_failures.items.items.len);
        try std.testing.expectEqual(retirements_before_probe + 1, cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(drafts_before_probe + 1, checker.annotation_expected_failure_drafts.items.len);
        try std.testing.expectEqual(failure_refs_before_probe, cir.expected_retirement_failures.items.items.len);
        _ = try expectDirectBinderLookupDraftForTest(
            checker,
            site,
            active,
            lookup_expr,
            @intCast(failures_before_probe),
            @intCast(retirements_before_probe),
        );
    }

    // Calibrate the exact real append boundary after normally publishing as
    // many distinct canonical lookup expressions as current capacities allow.
    var calibration_consumer = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderLookupOomB",
        direct_binder_transaction_consumer_source,
        "DirectBinderTransactionA",
        &provider,
    );
    defer calibration_consumer.deinit();
    try calibration_consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const calibration_checker = &calibration_consumer.checker;
    const calibration_cir = calibration_consumer.module_env;
    const calibration_site = try directBinderTransactionTestSite(&calibration_consumer);
    try stageDirectBinderTransactionSourceForTest(calibration_checker, calibration_site);
    try activateDirectBinderTransactionForTest(calibration_checker, calibration_site, 0);
    const calibration_active = try expectSingleActiveDirectBinderTransactionForTest(
        calibration_checker,
        calibration_site,
    );
    const calibration_target = try directBinderLookupAllocationTargetForTest(
        calibration_checker,
        calibration_site,
        calibration_active,
    );
    const calibration_failure_start = calibration_cir.expected_failures.items.items.len;
    const calibration_retirement_start = calibration_cir.expected_consumer_retirements.items.items.len;
    const calibration_draft_start = calibration_checker.annotation_expected_failure_drafts.items.len;
    var calibration_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const calibration_gpa = calibration_allocator.allocator();
    const allocation_base = calibration_allocator.alloc_index;
    calibration_allocator.resize_fail_index = calibration_allocator.resize_index;
    const calibration_cause = blk: {
        const saved_checker_gpa = calibration_checker.gpa;
        const saved_cir_gpa = calibration_cir.gpa;
        const saved_types_gpa = calibration_checker.types.gpa;
        calibration_checker.gpa = calibration_gpa;
        calibration_cir.gpa = calibration_gpa;
        calibration_checker.types.gpa = calibration_gpa;
        defer {
            calibration_checker.types.gpa = saved_types_gpa;
            calibration_cir.gpa = saved_cir_gpa;
            calibration_checker.gpa = saved_checker_gpa;
        }
        break :blk try calibration_checker.publishDirectBinderLookupCheckedError(
            calibration_target,
            calibration_site.pattern_idx,
            calibration_active,
        );
    };
    const calibration_allocations = calibration_allocator.alloc_index - allocation_base;
    try std.testing.expect(!calibration_allocator.has_induced_failure);
    try std.testing.expect(calibration_allocations > 0);
    try std.testing.expectEqual(
        @as(u32, @intCast(calibration_retirement_start)),
        calibration_cause.decodedExpectedConsumerRetirement().?.index,
    );
    _ = try expectDirectBinderLookupDraftForTest(
        calibration_checker,
        calibration_site,
        calibration_active,
        calibration_target,
        @intCast(calibration_failure_start),
        @intCast(calibration_retirement_start),
    );
    try std.testing.expectEqual(
        calibration_failure_start + 1,
        calibration_cir.expected_failures.items.items.len,
    );
    try std.testing.expectEqual(
        calibration_retirement_start + 1,
        calibration_cir.expected_consumer_retirements.items.items.len,
    );
    try std.testing.expectEqual(
        calibration_draft_start + 1,
        calibration_checker.annotation_expected_failure_drafts.items.len,
    );
    const calibration_failures_len = calibration_cir.expected_failures.items.items.len;
    const calibration_retirements_len = calibration_cir.expected_consumer_retirements.items.items.len;
    const calibration_drafts_len = calibration_checker.annotation_expected_failure_drafts.items.len;
    const revisited_cause = try calibration_checker.publishDirectBinderLookupCheckedError(
        calibration_target,
        calibration_site.pattern_idx,
        calibration_active,
    );
    try std.testing.expect(expectedCauseOwnersEqual(calibration_cause, revisited_cause));
    try std.testing.expectEqual(calibration_failures_len, calibration_cir.expected_failures.items.items.len);
    try std.testing.expectEqual(
        calibration_retirements_len,
        calibration_cir.expected_consumer_retirements.items.items.len,
    );
    try std.testing.expectEqual(calibration_drafts_len, calibration_checker.annotation_expected_failure_drafts.items.len);

    var failure_index: usize = 0;
    while (failure_index < calibration_allocations) : (failure_index += 1) {
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "DirectBinderLookupOomB",
            direct_binder_transaction_consumer_source,
            "DirectBinderTransactionA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        const checker = &consumer.checker;
        const cir = consumer.module_env;
        const site = try directBinderTransactionTestSite(&consumer);
        try stageDirectBinderTransactionSourceForTest(checker, site);
        try activateDirectBinderTransactionForTest(checker, site, 0);
        const active = try expectSingleActiveDirectBinderTransactionForTest(checker, site);
        const target = try directBinderLookupAllocationTargetForTest(checker, site, active);
        try std.testing.expectEqual(calibration_target, target);

        const failures_before = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedFailure,
            cir.expected_failures.items.items,
        );
        defer std.testing.allocator.free(failures_before);
        const retirements_before = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedConsumerRetirement,
            cir.expected_consumer_retirements.items.items,
        );
        defer std.testing.allocator.free(retirements_before);
        const drafts_before = try std.testing.allocator.dupe(
            AnnotationExpectedFailureDraft,
            checker.annotation_expected_failure_drafts.items,
        );
        defer std.testing.allocator.free(drafts_before);
        const sources_before = try std.testing.allocator.dupe(
            DirectFormalFailureSource,
            checker.direct_formal_failure_sources.items,
        );
        defer std.testing.allocator.free(sources_before);
        const active_before = try std.testing.allocator.dupe(
            ActiveDirectBinderFailure,
            checker.active_direct_binder_failures.items,
        );
        defer std.testing.allocator.free(active_before);
        const failure_refs_before = cir.expected_retirement_failures.items.items.len;
        const retired_consumers_before = cir.expected_retired_consumers.items.items.len;
        const diagnostics_before = try DirectBinderDiagnosticState.capture(cir);
        defer diagnostics_before.deinit();
        const target_node_before = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(target));

        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = std.math.maxInt(usize),
            .resize_fail_index = std.math.maxInt(usize),
        });
        const failing_gpa = failing.allocator();
        const failure_allocation_base = failing.alloc_index;
        failing.fail_index = std.math.add(
            usize,
            failure_allocation_base,
            failure_index,
        ) catch return error.TestUnexpectedResult;
        failing.resize_fail_index = failing.resize_index;
        const result = blk: {
            const saved_checker_gpa = checker.gpa;
            const saved_cir_gpa = cir.gpa;
            const saved_types_gpa = checker.types.gpa;
            checker.gpa = failing_gpa;
            cir.gpa = failing_gpa;
            checker.types.gpa = failing_gpa;
            defer {
                checker.types.gpa = saved_types_gpa;
                cir.gpa = saved_cir_gpa;
                checker.gpa = saved_checker_gpa;
            }
            break :blk checker.publishDirectBinderLookupCheckedError(
                target,
                site.pattern_idx,
                active,
            );
        };
        try std.testing.expectError(error.OutOfMemory, result);
        try std.testing.expect(failing.has_induced_failure);
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(failures_before),
            std.mem.sliceAsBytes(cir.expected_failures.items.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(retirements_before),
            std.mem.sliceAsBytes(cir.expected_consumer_retirements.items.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(drafts_before),
            std.mem.sliceAsBytes(checker.annotation_expected_failure_drafts.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(sources_before),
            std.mem.sliceAsBytes(checker.direct_formal_failure_sources.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(active_before),
            std.mem.sliceAsBytes(checker.active_direct_binder_failures.items),
        );
        try std.testing.expectEqual(failure_refs_before, cir.expected_retirement_failures.items.items.len);
        try std.testing.expectEqual(retired_consumers_before, cir.expected_retired_consumers.items.items.len);
        try diagnostics_before.expectUnchanged(cir);
        const target_node_after = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(target));
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&target_node_before),
            std.mem.asBytes(&target_node_after),
        );

        const retry = try checker.publishDirectBinderLookupCheckedError(
            target,
            site.pattern_idx,
            active,
        );
        try std.testing.expectEqual(
            @as(u32, @intCast(retirements_before.len)),
            retry.decodedExpectedConsumerRetirement().?.index,
        );
        _ = try expectDirectBinderLookupDraftForTest(
            checker,
            site,
            active,
            target,
            @intCast(failures_before.len),
            @intCast(retirements_before.len),
        );
        try std.testing.expectEqual(failures_before.len + 1, cir.expected_failures.items.items.len);
        try std.testing.expectEqual(
            retirements_before.len + 1,
            cir.expected_consumer_retirements.items.items.len,
        );
        try std.testing.expectEqual(
            drafts_before.len + 1,
            checker.annotation_expected_failure_drafts.items.len,
        );
        try std.testing.expectEqual(failure_refs_before, cir.expected_retirement_failures.items.items.len);
        const retry_failures_len = cir.expected_failures.items.items.len;
        const retry_retirements_len = cir.expected_consumer_retirements.items.items.len;
        const retry_drafts_len = checker.annotation_expected_failure_drafts.items.len;
        const revisit = try checker.publishDirectBinderLookupCheckedError(
            target,
            site.pattern_idx,
            active,
        );
        try std.testing.expect(expectedCauseOwnersEqual(retry, revisit));
        try std.testing.expectEqual(retry_failures_len, cir.expected_failures.items.items.len);
        try std.testing.expectEqual(retry_retirements_len, cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(retry_drafts_len, checker.annotation_expected_failure_drafts.items.len);
    }
}

test "invalid where alias direct binder lookup completion is atomic across OOM" {
    const TestEnv = @import("test/TestEnv.zig");
    var provider = try TestEnv.init(
        "DirectBinderTransactionA",
        direct_binder_transaction_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    var calibration_consumer = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderCompletionOomB",
        direct_binder_transaction_consumer_source,
        "DirectBinderTransactionA",
        &provider,
    );
    defer calibration_consumer.deinit();
    try calibration_consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const calibration_checker = &calibration_consumer.checker;
    const calibration_cir = calibration_consumer.module_env;
    const calibration_stage = try stageDirectBinderLookupCompletionForTest(
        &calibration_consumer,
    );
    const calibration_failures = try std.testing.allocator.dupe(
        ModuleEnv.ExpectedFailure,
        calibration_cir.expected_failures.items.items,
    );
    defer std.testing.allocator.free(calibration_failures);
    const calibration_source_retirement =
        calibration_cir.expected_consumer_retirements.items.items[0];
    const calibration_source = calibration_checker.direct_formal_failure_sources.items[0];
    const calibration_active = calibration_checker.active_direct_binder_failures.items[0];
    const calibration_source_draft = calibration_checker.annotation_expected_failure_drafts.items[0];
    const calibration_failure_refs_start =
        calibration_cir.expected_retirement_failures.items.items.len;
    const calibration_diagnostics = try DirectBinderDiagnosticState.capture(calibration_cir);
    defer calibration_diagnostics.deinit();
    try std.testing.expectEqual(@as(usize, 2), calibration_failures.len);
    try std.testing.expectEqual(@as(usize, 2), calibration_checker.annotation_expected_failure_drafts.items.len);
    var calibration_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const calibration_gpa = calibration_allocator.allocator();
    const allocation_base = calibration_allocator.alloc_index;
    calibration_allocator.resize_fail_index = calibration_allocator.resize_index;
    {
        const saved_checker_gpa = calibration_checker.gpa;
        const saved_cir_gpa = calibration_cir.gpa;
        const saved_types_gpa = calibration_checker.types.gpa;
        calibration_checker.gpa = calibration_gpa;
        calibration_cir.gpa = calibration_gpa;
        calibration_checker.types.gpa = calibration_gpa;
        defer {
            calibration_checker.types.gpa = saved_types_gpa;
            calibration_cir.gpa = saved_cir_gpa;
            calibration_checker.gpa = saved_checker_gpa;
        }
        try calibration_checker.completeIneligibleFailureRetirement(
            calibration_stage.lookup_expr,
            calibration_stage.diagnostic_idx,
        );
    }
    const calibration_allocations = calibration_allocator.alloc_index - allocation_base;
    try std.testing.expect(!calibration_allocator.has_induced_failure);
    try std.testing.expect(calibration_allocations > 0);
    try calibration_diagnostics.expectUnchanged(calibration_cir);
    try std.testing.expectEqualSlices(
        u8,
        std.mem.sliceAsBytes(calibration_failures),
        std.mem.sliceAsBytes(calibration_cir.expected_failures.items.items),
    );
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&calibration_source_retirement),
        std.mem.asBytes(&calibration_cir.expected_consumer_retirements.items.items[0]),
    );
    try std.testing.expect(std.meta.eql(
        calibration_source,
        calibration_checker.direct_formal_failure_sources.items[0],
    ));
    try std.testing.expect(std.meta.eql(
        calibration_active,
        calibration_checker.active_direct_binder_failures.items[0],
    ));
    try std.testing.expectEqual(@as(usize, 1), calibration_checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&calibration_source_draft),
        std.mem.asBytes(&calibration_checker.annotation_expected_failure_drafts.items[0]),
    );
    try expectCompletedDirectBinderLookupForTest(
        calibration_checker,
        calibration_stage.site,
        calibration_stage.active,
        calibration_stage.lookup_expr,
        calibration_stage.failure_index,
        calibration_stage.retirement_index,
        calibration_failure_refs_start,
        calibration_stage.diagnostic_idx,
        calibration_stage.original_node,
    );
    try std.testing.expect(
        calibration_cir.store.getExpr(calibration_stage.lookup_expr) == .e_lookup_local,
    );
    try calibration_checker.replaceExprWithRuntimeError(
        calibration_stage.lookup_expr,
        calibration_stage.diagnostic_idx,
    );
    const calibration_rewritten = calibration_cir.store.getExpr(calibration_stage.lookup_expr);
    if (calibration_rewritten != .e_runtime_error or
        calibration_rewritten.e_runtime_error.diagnostic != calibration_stage.diagnostic_idx)
    {
        return error.TestUnexpectedResult;
    }
    try expectCompletedDirectBinderLookupForTest(
        calibration_checker,
        calibration_stage.site,
        calibration_stage.active,
        calibration_stage.lookup_expr,
        calibration_stage.failure_index,
        calibration_stage.retirement_index,
        calibration_failure_refs_start,
        calibration_stage.diagnostic_idx,
        calibration_stage.original_node,
    );

    var failure_index: usize = 0;
    while (failure_index < calibration_allocations) : (failure_index += 1) {
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "DirectBinderCompletionOomB",
            direct_binder_transaction_consumer_source,
            "DirectBinderTransactionA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        const checker = &consumer.checker;
        const cir = consumer.module_env;
        const stage = try stageDirectBinderLookupCompletionForTest(&consumer);
        try std.testing.expectEqual(calibration_stage.lookup_expr, stage.lookup_expr);
        try std.testing.expectEqual(calibration_stage.failure_index, stage.failure_index);
        try std.testing.expectEqual(calibration_stage.retirement_index, stage.retirement_index);

        const failures_before = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedFailure,
            cir.expected_failures.items.items,
        );
        defer std.testing.allocator.free(failures_before);
        const retirements_before = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedConsumerRetirement,
            cir.expected_consumer_retirements.items.items,
        );
        defer std.testing.allocator.free(retirements_before);
        const failure_refs_before = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedRetirementFailure,
            cir.expected_retirement_failures.items.items,
        );
        defer std.testing.allocator.free(failure_refs_before);
        const drafts_before = try std.testing.allocator.dupe(
            AnnotationExpectedFailureDraft,
            checker.annotation_expected_failure_drafts.items,
        );
        defer std.testing.allocator.free(drafts_before);
        const sources_before = try std.testing.allocator.dupe(
            DirectFormalFailureSource,
            checker.direct_formal_failure_sources.items,
        );
        defer std.testing.allocator.free(sources_before);
        const active_before = try std.testing.allocator.dupe(
            ActiveDirectBinderFailure,
            checker.active_direct_binder_failures.items,
        );
        defer std.testing.allocator.free(active_before);
        const retired_consumers_before = cir.expected_retired_consumers.items.items.len;
        const diagnostics_before = try DirectBinderDiagnosticState.capture(cir);
        defer diagnostics_before.deinit();
        const node_before = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(stage.lookup_expr));
        try std.testing.expectEqual(@as(usize, 2), drafts_before.len);
        try std.testing.expectEqual(@as(usize, 0), failure_refs_before.len);

        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = std.math.maxInt(usize),
            .resize_fail_index = std.math.maxInt(usize),
        });
        const failing_gpa = failing.allocator();
        const failure_allocation_base = failing.alloc_index;
        failing.fail_index = std.math.add(
            usize,
            failure_allocation_base,
            failure_index,
        ) catch return error.TestUnexpectedResult;
        failing.resize_fail_index = failing.resize_index;
        const result = blk: {
            const saved_checker_gpa = checker.gpa;
            const saved_cir_gpa = cir.gpa;
            const saved_types_gpa = checker.types.gpa;
            checker.gpa = failing_gpa;
            cir.gpa = failing_gpa;
            checker.types.gpa = failing_gpa;
            defer {
                checker.types.gpa = saved_types_gpa;
                cir.gpa = saved_cir_gpa;
                checker.gpa = saved_checker_gpa;
            }
            break :blk checker.completeIneligibleFailureRetirement(
                stage.lookup_expr,
                stage.diagnostic_idx,
            );
        };
        try std.testing.expectError(error.OutOfMemory, result);
        try std.testing.expect(failing.has_induced_failure);
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(failures_before),
            std.mem.sliceAsBytes(cir.expected_failures.items.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(retirements_before),
            std.mem.sliceAsBytes(cir.expected_consumer_retirements.items.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(failure_refs_before),
            std.mem.sliceAsBytes(cir.expected_retirement_failures.items.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(drafts_before),
            std.mem.sliceAsBytes(checker.annotation_expected_failure_drafts.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(sources_before),
            std.mem.sliceAsBytes(checker.direct_formal_failure_sources.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(active_before),
            std.mem.sliceAsBytes(checker.active_direct_binder_failures.items),
        );
        try std.testing.expectEqual(retired_consumers_before, cir.expected_retired_consumers.items.items.len);
        try diagnostics_before.expectUnchanged(cir);
        const node_after_failure = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(stage.lookup_expr));
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&node_before),
            std.mem.asBytes(&node_after_failure),
        );
        _ = try expectDirectBinderLookupDraftForTest(
            checker,
            stage.site,
            stage.active,
            stage.lookup_expr,
            stage.failure_index,
            stage.retirement_index,
        );

        try checker.replaceExprWithRuntimeError(stage.lookup_expr, stage.diagnostic_idx);
        const rewritten = cir.store.getExpr(stage.lookup_expr);
        if (rewritten != .e_runtime_error or
            rewritten.e_runtime_error.diagnostic != stage.diagnostic_idx)
        {
            return error.TestUnexpectedResult;
        }
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(failures_before),
            std.mem.sliceAsBytes(cir.expected_failures.items.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&retirements_before[0]),
            std.mem.asBytes(&cir.expected_consumer_retirements.items.items[0]),
        );
        try std.testing.expectEqual(@as(usize, 1), checker.annotation_expected_failure_drafts.items.len);
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&drafts_before[0]),
            std.mem.asBytes(&checker.annotation_expected_failure_drafts.items[0]),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(sources_before),
            std.mem.sliceAsBytes(checker.direct_formal_failure_sources.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(active_before),
            std.mem.sliceAsBytes(checker.active_direct_binder_failures.items),
        );
        try std.testing.expectEqual(retired_consumers_before, cir.expected_retired_consumers.items.items.len);
        try diagnostics_before.expectUnchanged(cir);
        try expectCompletedDirectBinderLookupForTest(
            checker,
            stage.site,
            stage.active,
            stage.lookup_expr,
            stage.failure_index,
            stage.retirement_index,
            failure_refs_before.len,
            stage.diagnostic_idx,
            stage.original_node,
        );
    }
}

test "invalid where alias direct binder lookup retains its exact checked error" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderFailureA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import DirectBinderFailureA exposing [Status]
        \\
        \\first : a -> a where [a.Status]
        \\first = |value| value
    ;
    var consumer = try TestEnv.initWithImport(
        "DirectBinderFailureB",
        consumer_source,
        "DirectBinderFailureA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderFailureB",
        consumer_source,
        "DirectBinderFailureA",
        &provider,
    );
    defer fresh_env.deinit();
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });

    const cir = consumer.module_env;
    const failures = cir.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 2), failures.len);
    try std.testing.expectEqual(
        @as(usize, 2),
        cir.expected_consumer_retirements.items.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 2),
        cir.expected_retirement_failures.items.items.len,
    );
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
    try std.testing.expectEqual(
        @as(usize, 0),
        consumer.checker.annotation_expected_failure_drafts.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        consumer.checker.direct_formal_failure_sources.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        consumer.checker.active_direct_binder_failures.items.len,
    );
    var lookup_failure_index: ?u32 = null;
    for (failures, 0..) |failure, failure_index| {
        if (failure.decodedKind() != .direct_binder_lookup_checked_error) continue;
        if (lookup_failure_index != null) return error.TestUnexpectedResult;
        lookup_failure_index = @intCast(failure_index);
    }
    const selected_failure_index = lookup_failure_index orelse return error.TestUnexpectedResult;
    const lookup_failure = &failures[selected_failure_index];
    const direct = lookup_failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        ModuleEnv.SubjectAuthority.DirectPhase.direct_binder_lookup_checked_error,
        lookup_failure.subject_authority.decodedDirectPhase().?,
    );
    try std.testing.expect(direct.local_record_index < selected_failure_index);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
        failures[direct.local_record_index].decodedKind().?,
    );
    const source_retirement = lookup_failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(expectedAnnotationRetirementOwnsFailure(
        cir,
        source_retirement.index,
        direct.local_record_index,
        failures[direct.local_record_index].owner_node,
    ));
    const source_direct = failures[direct.local_record_index]
        .subject_authority.decodedDirect() orelse return error.TestUnexpectedResult;
    try std.testing.expect(
        source_direct.local_record_index <
            cir.body_annotation_malformed_type_publications.items.items.len,
    );
    const body_publication = &cir.body_annotation_malformed_type_publications.items.items[
        source_direct.local_record_index
    ];
    const attachment_index = cir.bodyAnnotationAttachmentIndex(
        body_publication.decodedAttachmentKind() orelse return error.TestUnexpectedResult,
        body_publication.attachment_node,
        @enumFromInt(body_publication.annotation_root),
        @enumFromInt(body_publication.body_expr),
    ) orelse return error.TestUnexpectedResult;
    const attachment = &cir.body_annotation_attachments.items.items[attachment_index];
    const saved_attachment = attachment.*;
    const saved_body_publication = body_publication.*;
    try std.testing.expect(saved_attachment.body_expr != lookup_failure.owner_node);
    attachment.body_expr = lookup_failure.owner_node;
    body_publication.body_expr = lookup_failure.owner_node;
    try std.testing.expect(!bodyAnnotationMalformedTypePublicationIsLocallyValid(
        cir,
        body_publication.*,
    ));
    attachment.* = saved_attachment;
    body_publication.* = saved_body_publication;
    try std.testing.expect(bodyAnnotationMalformedTypePublicationIsLocallyValid(
        cir,
        body_publication.*,
    ));
    const lookup_snapshot = expectedLookupRetirementOwningFailure(
        cir,
        selected_failure_index,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(lookup_failure.owner_node, cir.expected_consumer_retirements.items.items[
        lookup_snapshot.retirement_index
    ].retired_node);
    try std.testing.expectEqual(lookup_failure.site_node, @intFromEnum(lookup_snapshot.pattern_idx));
    try std.testing.expect(directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure.*,
        selected_failure_index,
        direct,
    ));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try validateExpectedFailureContext(cir, context);

    const saved_failure = lookup_failure.*;
    lookup_failure.subject_authority.payload.direct.local_record_index = selected_failure_index;
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    lookup_failure.* = saved_failure;

    lookup_failure.slot = lookup_failure.slot + 1;
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    lookup_failure.* = saved_failure;

    const retirement = &cir.expected_consumer_retirements.items.items[
        lookup_snapshot.retirement_index
    ];
    const saved_retirement = retirement.*;
    retirement.expected_failures_len = 2;
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    retirement.* = saved_retirement;

    const source_retirement_row = &cir.expected_consumer_retirements.items.items[
        source_retirement.index
    ];
    const saved_source_payload = source_retirement_row.original_payload;
    source_retirement_row.original_payload[0] +%= 1;
    const accepted_forged_source_snapshot = validateExpectedFailureContext(cir, context);
    source_retirement_row.original_payload = saved_source_payload;
    try std.testing.expectError(error.CorruptArtifact, accepted_forged_source_snapshot);
}

test "invalid where alias direct binder owner inverse rejects sibling and bounded coordinates" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("direct-binder owner inverse fixture failed at {s}\n", .{failure_stage});
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderOwnerInverseA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    failure_stage = "consumer initialization";
    const consumer_source =
        \\import DirectBinderOwnerInverseA exposing [Status]
        \\
        \\first : a, b -> a where [a.Status]
        \\first = |value, _other| value
    ;
    var consumer = try TestEnv.initWithImport(
        "DirectBinderOwnerInverseB",
        consumer_source,
        "DirectBinderOwnerInverseA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderOwnerInverseB",
        consumer_source,
        "DirectBinderOwnerInverseA",
        &provider,
    );
    defer fresh_env.deinit();

    failure_stage = "diagnostics and lifecycle";
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
    const cir = consumer.module_env;
    try std.testing.expectEqual(@as(usize, 2), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retirement_failures.items.items.len);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);

    failure_stage = "canonical topology";
    const candidate_def_idx = consumer.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const fresh_def_idx = fresh_env.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const candidate_topology = try directBinderOwnerInverseTestProof(cir, candidate_def_idx);
    const fresh_topology = try directBinderOwnerInverseTestProof(
        fresh_env.module_env,
        fresh_def_idx,
    );
    try std.testing.expect(std.meta.eql(candidate_topology, fresh_topology));

    const lookup_proof = try uniqueDirectBinderLookupTestProof(cir);
    const lookup_failure = cir.expected_failures.items.items[lookup_proof.failure_index];
    try std.testing.expectEqual(
        @intFromEnum(candidate_topology.formals[0]),
        lookup_failure.raw_peer_var,
    );
    const source_retirement = &cir.expected_consumer_retirements.items.items[
        lookup_proof.source_retirement_index
    ];
    if (source_retirement.decodedOriginalNodeTag() != .expr_lambda) {
        return error.TestUnexpectedResult;
    }
    const source_payload: CIR.Node.Payload = @bitCast(source_retirement.original_payload);
    if (source_payload.expr_lambda.args_len != 2 or
        !rangeFits(
            source_payload.expr_lambda.args_start,
            source_payload.expr_lambda.args_len,
            cir.store.index_data.items.items.len,
        ))
    {
        return error.TestUnexpectedResult;
    }
    const candidate_patterns = cir.store.index_data.items.items[source_payload.expr_lambda.args_start..][0..source_payload.expr_lambda.args_len];
    if (candidate_patterns[0] != @intFromEnum(lookup_proof.pattern_idx) or
        candidate_patterns[0] == candidate_patterns[1] or
        cir.store.nodes.get(@enumFromInt(candidate_patterns[0])).tag != .pattern_identifier or
        cir.store.nodes.get(@enumFromInt(candidate_patterns[1])).tag != .pattern_identifier)
    {
        return error.TestUnexpectedResult;
    }

    const fresh_def = fresh_env.module_env.store.getDef(fresh_def_idx);
    const fresh_lambda = fresh_env.module_env.store.getExpr(fresh_def.expr);
    if (fresh_lambda != .e_lambda) return error.TestUnexpectedResult;
    const fresh_patterns = fresh_env.module_env.store.slicePatterns(fresh_lambda.e_lambda.args);
    if (fresh_patterns.len != 2 or
        @intFromEnum(fresh_patterns[0]) != candidate_patterns[0] or
        @intFromEnum(fresh_patterns[1]) != candidate_patterns[1] or
        fresh_env.module_env.store.getPattern(fresh_patterns[0]) != .assign or
        fresh_env.module_env.store.getPattern(fresh_patterns[1]) != .assign)
    {
        return error.TestUnexpectedResult;
    }
    const fresh_body = fresh_env.module_env.store.getExpr(fresh_lambda.e_lambda.body);
    if (fresh_body != .e_lookup_local or
        fresh_body.e_lookup_local.pattern_idx != fresh_patterns[0] or
        @intFromEnum(fresh_lambda.e_lambda.body) != lookup_failure.owner_node)
    {
        return error.TestUnexpectedResult;
    }

    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);

    failure_stage = "candidate receiver sibling";
    const candidate_receiver_node_idx = ModuleEnv.nodeIdxFrom(candidate_topology.receiver_idx);
    const saved_candidate_receiver_node = cir.store.nodes.get(candidate_receiver_node_idx);
    var changed_candidate_receiver_node = saved_candidate_receiver_node;
    var changed_candidate_receiver_payload = changed_candidate_receiver_node.getPayload();
    changed_candidate_receiver_payload.ty_rigid_var_lookup.ref =
        @intFromEnum(candidate_topology.formals[1]);
    changed_candidate_receiver_node.setPayload(changed_candidate_receiver_payload);
    cir.store.nodes.set(candidate_receiver_node_idx, changed_candidate_receiver_node);
    const accepted_candidate_receiver = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_receiver_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    cir.store.nodes.set(candidate_receiver_node_idx, saved_candidate_receiver_node);
    try std.testing.expect(!accepted_candidate_receiver);
    try std.testing.expect(!accepted_candidate_receiver_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "fresh receiver sibling";
    const fresh_receiver_node_idx = ModuleEnv.nodeIdxFrom(fresh_topology.receiver_idx);
    const saved_fresh_receiver_node = fresh_env.module_env.store.nodes.get(fresh_receiver_node_idx);
    var changed_fresh_receiver_node = saved_fresh_receiver_node;
    var changed_fresh_receiver_payload = changed_fresh_receiver_node.getPayload();
    changed_fresh_receiver_payload.ty_rigid_var_lookup.ref =
        @intFromEnum(fresh_topology.formals[1]);
    changed_fresh_receiver_node.setPayload(changed_fresh_receiver_payload);
    fresh_env.module_env.store.nodes.set(fresh_receiver_node_idx, changed_fresh_receiver_node);
    const accepted_fresh_receiver = validateExpectedFailureContext(cir, context);
    fresh_env.module_env.store.nodes.set(fresh_receiver_node_idx, saved_fresh_receiver_node);
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_receiver);
    try validateExpectedFailureContext(cir, context);

    failure_stage = "candidate function argument span";
    const candidate_function_node_idx = ModuleEnv.nodeIdxFrom(candidate_topology.function_idx);
    const saved_candidate_function_node = cir.store.nodes.get(candidate_function_node_idx);
    var changed_candidate_function_node = saved_candidate_function_node;
    var changed_candidate_function_payload = changed_candidate_function_node.getPayload();
    changed_candidate_function_payload.ty_fn.args_start =
        @intCast(cir.store.index_data.items.items.len + 1);
    changed_candidate_function_node.setPayload(changed_candidate_function_payload);
    cir.store.nodes.set(candidate_function_node_idx, changed_candidate_function_node);
    const accepted_candidate_args = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_args_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    cir.store.nodes.set(candidate_function_node_idx, saved_candidate_function_node);
    try std.testing.expect(!accepted_candidate_args);
    try std.testing.expect(!accepted_candidate_args_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "fresh function argument span";
    const fresh_function_node_idx = ModuleEnv.nodeIdxFrom(fresh_topology.function_idx);
    const saved_fresh_function_node = fresh_env.module_env.store.nodes.get(fresh_function_node_idx);
    var changed_fresh_function_node = saved_fresh_function_node;
    var changed_fresh_function_payload = changed_fresh_function_node.getPayload();
    changed_fresh_function_payload.ty_fn.args_start =
        @intCast(fresh_env.module_env.store.index_data.items.items.len + 1);
    changed_fresh_function_node.setPayload(changed_fresh_function_payload);
    fresh_env.module_env.store.nodes.set(fresh_function_node_idx, changed_fresh_function_node);
    const accepted_fresh_args = validateExpectedFailureContext(cir, context);
    fresh_env.module_env.store.nodes.set(fresh_function_node_idx, saved_fresh_function_node);
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_args);
    try validateExpectedFailureContext(cir, context);

    failure_stage = "candidate annotation pattern span";
    const saved_source_retirement = source_retirement.*;
    var changed_source_retirement = saved_source_retirement;
    var changed_source_payload: CIR.Node.Payload = @bitCast(changed_source_retirement.original_payload);
    changed_source_payload.expr_lambda.args_start =
        @intCast(cir.store.index_data.items.items.len + 1);
    changed_source_retirement.original_payload = @bitCast(changed_source_payload);
    source_retirement.* = changed_source_retirement;
    const accepted_candidate_pattern_span = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_pattern_span_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    source_retirement.* = saved_source_retirement;
    try std.testing.expect(!accepted_candidate_pattern_span);
    try std.testing.expect(!accepted_candidate_pattern_span_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate sibling pattern";
    const candidate_pattern_entry = &cir.store.index_data.items.items[
        source_payload.expr_lambda.args_start
    ];
    const saved_candidate_pattern = candidate_pattern_entry.*;
    candidate_pattern_entry.* = candidate_patterns[1];
    const accepted_candidate_pattern = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_pattern_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    candidate_pattern_entry.* = saved_candidate_pattern;
    try std.testing.expect(!accepted_candidate_pattern);
    try std.testing.expect(!accepted_candidate_pattern_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate pattern index";
    candidate_pattern_entry.* = @intCast(cir.store.nodes.len());
    const accepted_candidate_pattern_index = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_pattern_index_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    candidate_pattern_entry.* = saved_candidate_pattern;
    try std.testing.expect(!accepted_candidate_pattern_index);
    try std.testing.expect(!accepted_candidate_pattern_index_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "fresh sibling pattern";
    const fresh_pattern_entry = &fresh_env.module_env.store.index_data.items.items[
        fresh_lambda.e_lambda.args.span.start
    ];
    const saved_fresh_pattern = fresh_pattern_entry.*;
    fresh_pattern_entry.* = @intFromEnum(fresh_patterns[1]);
    const accepted_fresh_pattern = validateExpectedFailureContext(cir, context);
    fresh_pattern_entry.* = saved_fresh_pattern;
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_pattern);
    try validateExpectedFailureContext(cir, context);

    failure_stage = "candidate owner clause span";
    const candidate_owner = &cir.store.where_clause_owners.items.items[
        candidate_topology.owner_row_index
    ];
    const saved_candidate_owner = candidate_owner.*;
    candidate_owner.clauses_start = @intCast(cir.store.index_data.items.items.len + 1);
    const accepted_candidate_owner = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_owner_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    candidate_owner.* = saved_candidate_owner;
    try std.testing.expect(!accepted_candidate_owner);
    try std.testing.expect(!accepted_candidate_owner_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate owner flag";
    candidate_owner.owned_by_annotation = false;
    const accepted_candidate_owner_flag = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_owner_flag_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    candidate_owner.* = saved_candidate_owner;
    try std.testing.expect(!accepted_candidate_owner_flag);
    try std.testing.expect(!accepted_candidate_owner_flag_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate owner sibling rigid";
    candidate_owner.rigid_var = @intFromEnum(candidate_topology.formals[1]);
    const accepted_candidate_owner_rigid = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_owner_rigid_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    candidate_owner.* = saved_candidate_owner;
    try std.testing.expect(!accepted_candidate_owner_rigid);
    try std.testing.expect(!accepted_candidate_owner_rigid_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate owner padding";
    candidate_owner._padding[0] = 1;
    const accepted_candidate_owner_padding = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_owner_padding_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    candidate_owner.* = saved_candidate_owner;
    try std.testing.expect(!accepted_candidate_owner_padding);
    try std.testing.expect(!accepted_candidate_owner_padding_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate written clause tag";
    const candidate_annotation = cir.store.getAnnotation(candidate_topology.annotation_idx);
    const candidate_where = candidate_annotation.where orelse return error.TestUnexpectedResult;
    const candidate_written_entry = &cir.store.index_data.items.items[candidate_where.span.start];
    const saved_candidate_written_entry = candidate_written_entry.*;
    candidate_written_entry.* = @intFromEnum(candidate_topology.formals[0]);
    const accepted_candidate_written_tag = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_written_tag_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    candidate_written_entry.* = saved_candidate_written_entry;
    try std.testing.expect(!accepted_candidate_written_tag);
    try std.testing.expect(!accepted_candidate_written_tag_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "fresh owner span";
    const fresh_annotation_node = fresh_env.module_env.store.nodes.get(
        ModuleEnv.nodeIdxFrom(fresh_topology.annotation_idx),
    );
    if (fresh_annotation_node.tag != .annotation) return error.TestUnexpectedResult;
    const fresh_annotation_payload = fresh_annotation_node.getPayload().annotation;
    if (!fresh_annotation_payload.flags.has_where or
        fresh_annotation_payload.where_span2_idx >=
            fresh_env.module_env.store.span_with_node_data.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const fresh_where_storage = fresh_env.module_env.store.span_with_node_data.items.items[
        fresh_annotation_payload.where_span2_idx
    ];
    if (fresh_where_storage.node >= fresh_env.module_env.store.span2_data.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const fresh_owner_span = &fresh_env.module_env.store.span2_data.items.items[
        fresh_where_storage.node
    ];
    const saved_fresh_owner_span = fresh_owner_span.*;
    fresh_owner_span.start = @intCast(
        fresh_env.module_env.store.where_clause_owners.items.items.len + 1,
    );
    const accepted_fresh_owner_span = validateExpectedFailureContext(cir, context);
    fresh_owner_span.* = saved_fresh_owner_span;
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_owner_span);
    try validateExpectedFailureContext(cir, context);

    failure_stage = "candidate alias padding";
    const candidate_where_node_idx = ModuleEnv.nodeIdxFrom(candidate_topology.where_idx);
    const saved_candidate_where_node = cir.store.nodes.get(candidate_where_node_idx);
    var changed_candidate_where_node = saved_candidate_where_node;
    var changed_candidate_where_payload = changed_candidate_where_node.getPayload();
    changed_candidate_where_payload.where_alias._padding[0] = 1;
    changed_candidate_where_node.setPayload(changed_candidate_where_payload);
    cir.store.nodes.set(candidate_where_node_idx, changed_candidate_where_node);
    const accepted_candidate_alias = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_alias_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    cir.store.nodes.set(candidate_where_node_idx, saved_candidate_where_node);
    try std.testing.expect(!accepted_candidate_alias);
    try std.testing.expect(!accepted_candidate_alias_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate alias receiver index";
    var changed_candidate_receiver_index_node = saved_candidate_where_node;
    var changed_candidate_receiver_index_payload = changed_candidate_receiver_index_node.getPayload();
    changed_candidate_receiver_index_payload.where_alias.var_idx = @intCast(cir.store.nodes.len());
    changed_candidate_receiver_index_node.setPayload(changed_candidate_receiver_index_payload);
    cir.store.nodes.set(candidate_where_node_idx, changed_candidate_receiver_index_node);
    const accepted_candidate_receiver_index = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_receiver_index_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    cir.store.nodes.set(candidate_where_node_idx, saved_candidate_where_node);
    try std.testing.expect(!accepted_candidate_receiver_index);
    try std.testing.expect(!accepted_candidate_receiver_index_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate alias receiver tag";
    const source_failure = cir.expected_failures.items.items[lookup_proof.direct.local_record_index];
    const source_diagnostic = source_failure.cause_owner.decodedCirDiagnostic() orelse
        return error.TestUnexpectedResult;
    if (source_diagnostic.index >= @intFromEnum(candidate_topology.where_idx) or
        cir.store.nodes.get(@enumFromInt(source_diagnostic.index)).tag == .ty_rigid_var or
        cir.store.nodes.get(@enumFromInt(source_diagnostic.index)).tag == .ty_rigid_var_lookup)
    {
        return error.TestUnexpectedResult;
    }
    var changed_candidate_receiver_tag_node = saved_candidate_where_node;
    var changed_candidate_receiver_tag_payload = changed_candidate_receiver_tag_node.getPayload();
    changed_candidate_receiver_tag_payload.where_alias.var_idx = source_diagnostic.index;
    changed_candidate_receiver_tag_node.setPayload(changed_candidate_receiver_tag_payload);
    cir.store.nodes.set(candidate_where_node_idx, changed_candidate_receiver_tag_node);
    const accepted_candidate_receiver_tag = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_receiver_tag_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    cir.store.nodes.set(candidate_where_node_idx, saved_candidate_where_node);
    try std.testing.expect(!accepted_candidate_receiver_tag);
    try std.testing.expect(!accepted_candidate_receiver_tag_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "candidate alias target tag";
    var changed_candidate_target_tag_node = saved_candidate_where_node;
    var changed_candidate_target_tag_payload = changed_candidate_target_tag_node.getPayload();
    changed_candidate_target_tag_payload.where_alias.alias_idx =
        @intFromEnum(candidate_topology.receiver_idx);
    changed_candidate_target_tag_node.setPayload(changed_candidate_target_tag_payload);
    cir.store.nodes.set(candidate_where_node_idx, changed_candidate_target_tag_node);
    const accepted_candidate_target_tag = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_target_tag_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    cir.store.nodes.set(candidate_where_node_idx, saved_candidate_where_node);
    try std.testing.expect(!accepted_candidate_target_tag);
    try std.testing.expect(!accepted_candidate_target_tag_retirement);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "fresh alias target";
    const fresh_where_node_idx = ModuleEnv.nodeIdxFrom(fresh_topology.where_idx);
    const saved_fresh_where_node = fresh_env.module_env.store.nodes.get(fresh_where_node_idx);
    var changed_fresh_where_node = saved_fresh_where_node;
    var changed_fresh_where_payload = changed_fresh_where_node.getPayload();
    changed_fresh_where_payload.where_alias.alias_idx =
        @intCast(fresh_env.module_env.store.nodes.len());
    changed_fresh_where_node.setPayload(changed_fresh_where_payload);
    fresh_env.module_env.store.nodes.set(fresh_where_node_idx, changed_fresh_where_node);
    const accepted_fresh_alias = validateExpectedFailureContext(cir, context);
    fresh_env.module_env.store.nodes.set(fresh_where_node_idx, saved_fresh_where_node);
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_alias);
    try validateExpectedFailureContext(cir, context);

    failure_stage = "candidate attachment node";
    const attachment_proof = try directBinderBodyAttachmentTestProof(cir, lookup_proof);
    const candidate_attachment = &cir.body_annotation_attachments.items.items[
        attachment_proof.attachment_index
    ];
    const saved_candidate_attachment = candidate_attachment.*;
    candidate_attachment.attachment_node = @intCast(cir.store.nodes.len());
    const accepted_candidate_attachment_row = cir.bodyAnnotationAttachmentIsLocallyValid(
        attachment_proof.attachment_index,
    );
    const accepted_candidate_attachment = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_attachment_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    candidate_attachment.* = saved_candidate_attachment;
    try std.testing.expect(!accepted_candidate_attachment_row);
    try std.testing.expect(!accepted_candidate_attachment);
    try std.testing.expect(!accepted_candidate_attachment_retirement);
    try std.testing.expect(cir.bodyAnnotationAttachmentIsLocallyValid(
        attachment_proof.attachment_index,
    ));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    failure_stage = "fresh attachment annotation";
    if (attachment_proof.attachment_index >=
        fresh_env.module_env.body_annotation_attachments.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const fresh_attachment = &fresh_env.module_env.body_annotation_attachments.items.items[
        attachment_proof.attachment_index
    ];
    if (!std.meta.eql(saved_candidate_attachment, fresh_attachment.*)) {
        return error.TestUnexpectedResult;
    }
    const saved_fresh_attachment = fresh_attachment.*;
    fresh_attachment.annotation_root = @intCast(fresh_env.module_env.store.nodes.len());
    const accepted_fresh_attachment_row = fresh_env.module_env.bodyAnnotationAttachmentIsLocallyValid(
        attachment_proof.attachment_index,
    );
    const accepted_fresh_attachment = validateExpectedFailureContext(cir, context);
    fresh_attachment.* = saved_fresh_attachment;
    try std.testing.expect(!accepted_fresh_attachment_row);
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_attachment);
    try std.testing.expect(fresh_env.module_env.bodyAnnotationAttachmentIsLocallyValid(
        attachment_proof.attachment_index,
    ));
    try validateExpectedFailureContext(cir, context);
}

test "invalid where alias direct binder recovery rebuilds and serializes canonically" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderSerdeA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import DirectBinderSerdeA exposing [Status]
        \\
        \\first : a -> a where [a.Status]
        \\first = |value| value
    ;
    var consumer = try TestEnv.initWithImport(
        "DirectBinderSerdeB",
        consumer_source,
        "DirectBinderSerdeA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderSerdeB",
        consumer_source,
        "DirectBinderSerdeA",
        &provider,
    );
    defer fresh_env.deinit();
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
    try expectDirectBinderTransientListsEmpty(&consumer.checker);

    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    const baseline_proof = try expectSerializedDirectBinderRecoveryState(
        consumer.module_env,
        context,
        null,
    );

    const canonical_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        consumer.module_env,
    );
    defer std.testing.allocator.free(canonical_before);
    try consumer.checker.rebuildCheckedBoundaryWhereMethodState();
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    const canonical_after_first = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        consumer.module_env,
    );
    defer std.testing.allocator.free(canonical_after_first);
    try std.testing.expectEqualSlices(u8, canonical_before, canonical_after_first);
    _ = try expectSerializedDirectBinderRecoveryState(
        consumer.module_env,
        context,
        baseline_proof,
    );

    try consumer.checker.rebuildCheckedBoundaryWhereMethodState();
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    const canonical_after_second = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        consumer.module_env,
    );
    defer std.testing.allocator.free(canonical_after_second);
    try std.testing.expectEqualSlices(u8, canonical_before, canonical_after_second);
    _ = try expectSerializedDirectBinderRecoveryState(
        consumer.module_env,
        context,
        baseline_proof,
    );

    const buffer = try serializeModuleEnvForDeserializationTest(
        std.testing.allocator,
        consumer.module_env,
    );
    defer std.testing.allocator.free(buffer);
    try std.testing.expectEqualSlices(u8, canonical_after_second, buffer);
    const base_addr = @intFromPtr(buffer.ptr);
    const serialized: *const ModuleEnv.Serialized = @ptrCast(@alignCast(buffer.ptr));
    try serialized.validate(buffer.len);
    try std.testing.expect(serialized.imports.imports.len != 0);

    inline for (.{
        "expected_failures",
        "expected_consumer_retirements",
        "expected_retirement_failures",
        "malformed_type_annotation_publications",
        "body_annotation_attachments",
        "body_annotation_malformed_type_publications",
    }) |field_name| {
        try expectSerializedRecoveryPoolHeaderCorruptionRejected(
            field_name,
            serialized,
            buffer.len,
        );
    }
    try serialized.validate(buffer.len);

    const readonly = try serialized.deserializeInto(
        base_addr,
        std.testing.allocator,
        consumer_source,
        "DirectBinderSerdeB",
    );
    defer {
        readonly.imports.deinitMapOnly(std.testing.allocator);
        readonly.import_mapping.deinit();
        std.testing.allocator.destroy(readonly);
    }
    try std.testing.expect(!readonly.w6b_semantically_validated);
    _ = try expectSerializedDirectBinderRecoveryState(readonly, context, baseline_proof);
    const readonly_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        readonly,
    );
    defer std.testing.allocator.free(readonly_bytes);
    try std.testing.expectEqualSlices(u8, canonical_after_second, readonly_bytes);

    const mutable = try serialized.deserializeWithMutableTypes(
        base_addr,
        std.testing.allocator,
        consumer_source,
        "DirectBinderSerdeB",
    );
    defer {
        mutable.deinitCachedModule();
        std.testing.allocator.destroy(mutable);
    }
    try std.testing.expect(!mutable.w6b_semantically_validated);
    _ = try expectSerializedDirectBinderRecoveryState(mutable, context, baseline_proof);
    const mutable_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        mutable,
    );
    defer std.testing.allocator.free(mutable_bytes);
    try std.testing.expectEqualSlices(u8, canonical_after_second, mutable_bytes);
}

test "invalid where alias direct binder lookup retains its captured annotation owner" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("captured direct-binder fixture failed at {s}\n", .{failure_stage});
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderCapturedA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    failure_stage = "consumer initialization";
    const consumer_source =
        \\import DirectBinderCapturedA exposing [Status]
        \\
        \\main = |captured| {
        \\    first : a -> a where [a.Status]
        \\    first = |value| {
        \\        _ = captured
        \\        value
        \\    }
        \\    {}
        \\}
    ;
    var consumer = try TestEnv.initWithImport(
        "DirectBinderCapturedB",
        consumer_source,
        "DirectBinderCapturedA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderCapturedB",
        consumer_source,
        "DirectBinderCapturedA",
        &provider,
    );
    defer fresh_env.deinit();
    failure_stage = "canonical diagnostics";
    try consumer.assertCanErrors(&.{
        "Type Not Exposed",
        "Undeclared Type",
        "Unused Variable",
    });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());

    failure_stage = "ledger inventory";
    const cir = consumer.module_env;
    try std.testing.expectEqual(@as(usize, 2), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retirement_failures.items.items.len);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    const proof = try uniqueDirectBinderLookupTestProof(cir);
    failure_stage = "captured owner topology";
    const lookup_failure = cir.expected_failures.items.items[proof.failure_index];
    const source_failure = cir.expected_failures.items.items[proof.direct.local_record_index];
    const source_direct = source_failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    if (source_direct.local_record_index >=
        cir.body_annotation_malformed_type_publications.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const publication = cir.body_annotation_malformed_type_publications.items.items[
        source_direct.local_record_index
    ];
    try std.testing.expectEqual(
        ModuleEnv.BodyAnnotationMalformedTypePublication.AttachmentKind.local_decl,
        publication.decodedAttachmentKind().?,
    );
    try std.testing.expectEqual(source_failure.owner_node, publication.body_expr);
    const source_retirement = cir.expected_consumer_retirements.items.items[
        proof.source_retirement_index
    ];
    try std.testing.expectEqual(publication.body_expr, source_retirement.retired_node);
    try std.testing.expectEqual(CIR.Node.Tag.expr_closure, source_retirement.decodedOriginalNodeTag().?);
    const source_payload: CIR.Node.Payload = @bitCast(source_retirement.original_payload);
    const closure_data_index = source_payload.expr_closure.closure_data_idx;
    if (closure_data_index >= cir.store.closure_data.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const closure_data = cir.store.closure_data.items.items[closure_data_index];
    const lambda_pattern = annotationRetirementDirectPatternAtSlot(
        cir,
        proof.source_retirement_index,
        lookup_failure.slot,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(lambda_pattern.lambda_expr, closure_data.lambda_idx);
    try std.testing.expectEqual(proof.pattern_idx, lambda_pattern.pattern_idx);
    const lambda_expr: CIR.Expr.Idx = @enumFromInt(lambda_pattern.lambda_expr);
    const lambda = cir.store.getExpr(lambda_expr);
    if (lambda != .e_lambda) return error.TestUnexpectedResult;
    const fresh_lambda = fresh_env.module_env.store.getExpr(lambda_expr);
    if (fresh_lambda != .e_lambda or
        !std.meta.eql(lambda.e_lambda, fresh_lambda.e_lambda))
    {
        return error.TestUnexpectedResult;
    }
    const body = fresh_env.module_env.store.getExpr(fresh_lambda.e_lambda.body);
    if (body != .e_block) return error.TestUnexpectedResult;
    try std.testing.expectEqual(@intFromEnum(body.e_block.final_expr), lookup_failure.owner_node);

    failure_stage = "fresh replay";
    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try validateExpectedFailureContext(cir, context);

    failure_stage = "fresh closure child mismatch";
    const fresh_main_def_idx = fresh_env.can.explicitRootDefByName("main") orelse
        return error.TestUnexpectedResult;
    const fresh_main = fresh_env.module_env.store.getDef(fresh_main_def_idx);
    try std.testing.expect(fresh_env.module_env.store.getExpr(fresh_main.expr) == .e_lambda);
    if (closure_data_index >= fresh_env.module_env.store.closure_data.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const fresh_closure_data = &fresh_env.module_env.store.closure_data.items.items[
        closure_data_index
    ];
    const saved_fresh_closure_data = fresh_closure_data.*;
    try std.testing.expect(saved_fresh_closure_data.lambda_idx != @intFromEnum(fresh_main.expr));
    fresh_closure_data.lambda_idx = @intFromEnum(fresh_main.expr);
    const accepted_retargeted_lambda = validateExpectedFailureContext(cir, context);
    fresh_closure_data.* = saved_fresh_closure_data;
    try std.testing.expectError(error.CorruptArtifact, accepted_retargeted_lambda);
    try validateExpectedFailureContext(cir, context);
}

test "invalid where alias direct binder lookup reaches an outer binder through a nested closure" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("nested direct-binder fixture failed at {s}\n", .{failure_stage});
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderNestedA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    failure_stage = "consumer initialization";
    const consumer_source =
        \\import DirectBinderNestedA exposing [Status]
        \\
        \\first : a -> ({} -> a) where [a.Status]
        \\first = |value| |{}| value
    ;
    var consumer = try TestEnv.initWithImport(
        "DirectBinderNestedB",
        consumer_source,
        "DirectBinderNestedA",
