    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderNestedB",
        consumer_source,
        "DirectBinderNestedA",
        &provider,
    );
    defer fresh_env.deinit();
    failure_stage = "canonical diagnostics";
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());

    failure_stage = "ledger inventory";
    const cir = consumer.module_env;
    try std.testing.expectEqual(@as(usize, 2), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retirement_failures.items.items.len);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    const proof = try uniqueDirectBinderLookupTestProof(cir);
    failure_stage = "outer binder topology";
    const lookup_failure = cir.expected_failures.items.items[proof.failure_index];
    const source_failure = cir.expected_failures.items.items[proof.direct.local_record_index];
    const source_direct = source_failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    if (source_direct.local_record_index >=
        cir.body_annotation_malformed_type_publications.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const publication = cir.body_annotation_malformed_type_publications.items.items[
        source_direct.local_record_index
    ];
    try std.testing.expectEqual(
        ModuleEnv.BodyAnnotationMalformedTypePublication.AttachmentKind.top_level_def,
        publication.decodedAttachmentKind().?,
    );
    try std.testing.expectEqual(source_failure.owner_node, publication.body_expr);
    const source_retirement = cir.expected_consumer_retirements.items.items[
        proof.source_retirement_index
    ];
    try std.testing.expectEqual(publication.body_expr, source_retirement.retired_node);
    try std.testing.expectEqual(CIR.Node.Tag.expr_lambda, source_retirement.decodedOriginalNodeTag().?);
    const source_payload: CIR.Node.Payload = @bitCast(source_retirement.original_payload);
    const outer_lambda = source_payload.expr_lambda;
    const fresh_first_def_idx = fresh_env.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const fresh_first = fresh_env.module_env.store.getDef(fresh_first_def_idx);
    try std.testing.expectEqual(source_retirement.retired_node, @intFromEnum(fresh_first.expr));
    const fresh_outer = fresh_env.module_env.store.getExpr(fresh_first.expr);
    if (fresh_outer != .e_lambda) return error.TestUnexpectedResult;
    try std.testing.expectEqual(outer_lambda.body, @intFromEnum(fresh_outer.e_lambda.body));
    const fresh_outer_body: CIR.Expr.Idx = @enumFromInt(outer_lambda.body);
    const inner_closure = fresh_env.module_env.store.getExpr(fresh_outer_body);
    if (inner_closure != .e_closure) return error.TestUnexpectedResult;
    const inner_lambda = fresh_env.module_env.store.getExpr(inner_closure.e_closure.lambda_idx);
    if (inner_lambda != .e_lambda) return error.TestUnexpectedResult;
    try std.testing.expectEqual(@intFromEnum(inner_lambda.e_lambda.body), lookup_failure.owner_node);
    try std.testing.expectEqual(proof.pattern_idx, @as(CIR.Pattern.Idx, @enumFromInt(lookup_failure.site_node)));
    const outer_args = fresh_env.module_env.store.slicePatterns(fresh_outer.e_lambda.args);
    const inner_args = fresh_env.module_env.store.slicePatterns(inner_lambda.e_lambda.args);
    try std.testing.expectEqual(@as(usize, 1), outer_args.len);
    try std.testing.expectEqual(@as(usize, 1), inner_args.len);
    try std.testing.expectEqual(outer_args[0], proof.pattern_idx);
    try std.testing.expect(inner_args[0] != proof.pattern_idx);
    try std.testing.expect(fresh_env.module_env.store.getPattern(inner_args[0]) != .assign);

    failure_stage = "fresh replay";
    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try validateExpectedFailureContext(cir, context);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
}

test "invalid where alias direct binder transport excludes non-direct formal and pattern edges" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("excluded direct-binder fixture failed at {s}\n", .{failure_stage});
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderExcludedA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    failure_stage = "consumer initialization";
    const consumer_source =
        \\import DirectBinderExcludedA exposing [Status]
        \\
        \\repeated : a, a -> a where [a.Status]
        \\repeated = |direct, repeated_ref| repeated_ref
        \\
        \\destructured : a -> a where [a.Status]
        \\destructured = |(value, _)| value
        \\
        \\nested_formal : (a, U64) -> (a, U64) where [a.Status]
        \\nested_formal = |pair| pair
        \\
        \\clean : a, U64 -> U64 where [a.Status]
        \\clean = |bad, good| good
    ;
    var consumer = try TestEnv.initWithImport(
        "DirectBinderExcludedB",
        consumer_source,
        "DirectBinderExcludedA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderExcludedB",
        consumer_source,
        "DirectBinderExcludedA",
        &provider,
    );
    defer fresh_env.deinit();
    failure_stage = "canonical diagnostics";
    try consumer.assertCanErrors(&.{
        "Type Not Exposed",
        "Undeclared Type",
        "Unused Variable",
        "Undeclared Type",
        "Undeclared Type",
        "Undeclared Type",
        "Unused Variable",
    });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());

    failure_stage = "ledger exclusions";
    const cir = consumer.module_env;
    const failures = cir.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 4), failures.len);
    try std.testing.expectEqual(@as(usize, 4), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 4), cir.expected_retirement_failures.items.items.len);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    for (failures) |failure| {
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
            failure.decodedKind().?,
        );
    }

    const repeated_def_idx = consumer.can.explicitRootDefByName("repeated") orelse
        return error.TestUnexpectedResult;
    const destructured_def_idx = consumer.can.explicitRootDefByName("destructured") orelse
        return error.TestUnexpectedResult;
    const nested_formal_def_idx = consumer.can.explicitRootDefByName("nested_formal") orelse
        return error.TestUnexpectedResult;
    const clean_def_idx = consumer.can.explicitRootDefByName("clean") orelse
        return error.TestUnexpectedResult;
    const def_indices = [_]CIR.Def.Idx{
        repeated_def_idx,
        destructured_def_idx,
        nested_formal_def_idx,
        clean_def_idx,
    };
    for (def_indices) |def_idx| {
        const def = cir.store.getDef(def_idx);
        var failure_index: ?u32 = null;
        for (failures, 0..) |failure, index| {
            if (failure.owner_node != @intFromEnum(def.expr)) continue;
            if (failure_index != null) return error.TestUnexpectedResult;
            failure_index = @intCast(index);
        }
        const selected = failure_index orelse return error.TestUnexpectedResult;
        const retirement_index = expectedFailureOwningRetirement(cir, selected) orelse
            return error.TestUnexpectedResult;
        try std.testing.expect(expectedAnnotationRetirementOwnsFailure(
            cir,
            retirement_index,
            selected,
            @intFromEnum(def.expr),
        ));
    }

    failure_stage = "repeated formal topology";
    const repeated_def = cir.store.getDef(repeated_def_idx);
    const repeated_annotation_idx = repeated_def.annotation orelse return error.TestUnexpectedResult;
    const repeated_annotation = cir.store.getAnnotation(repeated_annotation_idx);
    const repeated_fn = cir.store.getTypeAnno(repeated_annotation.anno);
    if (repeated_fn != .@"fn") return error.TestUnexpectedResult;
    const repeated_formals = cir.store.sliceTypeAnnos(repeated_fn.@"fn".args);
    try std.testing.expectEqual(@as(usize, 2), repeated_formals.len);
    try std.testing.expect(cir.store.getTypeAnno(repeated_formals[0]) == .rigid_var);
    const repeated_ref = cir.store.getTypeAnno(repeated_formals[1]);
    if (repeated_ref != .rigid_var_lookup) return error.TestUnexpectedResult;
    try std.testing.expectEqual(repeated_formals[0], repeated_ref.rigid_var_lookup.ref);
    const fresh_repeated_idx = fresh_env.can.explicitRootDefByName("repeated") orelse
        return error.TestUnexpectedResult;
    const fresh_repeated = fresh_env.module_env.store.getDef(fresh_repeated_idx);
    const fresh_repeated_lambda = fresh_env.module_env.store.getExpr(fresh_repeated.expr);
    if (fresh_repeated_lambda != .e_lambda) return error.TestUnexpectedResult;
    const repeated_patterns = fresh_env.module_env.store.slicePatterns(fresh_repeated_lambda.e_lambda.args);
    try std.testing.expectEqual(@as(usize, 2), repeated_patterns.len);
    try std.testing.expect(fresh_env.module_env.store.getPattern(repeated_patterns[0]) == .assign);
    try std.testing.expect(fresh_env.module_env.store.getPattern(repeated_patterns[1]) == .assign);
    try std.testing.expect(repeated_patterns[0] != repeated_patterns[1]);
    const repeated_body = fresh_env.module_env.store.getExpr(fresh_repeated_lambda.e_lambda.body);
    if (repeated_body != .e_lookup_local) return error.TestUnexpectedResult;
    try std.testing.expectEqual(repeated_patterns[1], repeated_body.e_lookup_local.pattern_idx);

    failure_stage = "destructured pattern topology";
    const destructured_def = cir.store.getDef(destructured_def_idx);
    const destructured_annotation_idx = destructured_def.annotation orelse
        return error.TestUnexpectedResult;
    const destructured_annotation = cir.store.getAnnotation(destructured_annotation_idx);
    const destructured_fn = cir.store.getTypeAnno(destructured_annotation.anno);
    if (destructured_fn != .@"fn") return error.TestUnexpectedResult;
    const destructured_formals = cir.store.sliceTypeAnnos(destructured_fn.@"fn".args);
    try std.testing.expectEqual(@as(usize, 1), destructured_formals.len);
    try std.testing.expect(cir.store.getTypeAnno(destructured_formals[0]) == .rigid_var);
    const fresh_destructured_idx = fresh_env.can.explicitRootDefByName("destructured") orelse
        return error.TestUnexpectedResult;
    const fresh_destructured = fresh_env.module_env.store.getDef(fresh_destructured_idx);
    const fresh_destructured_lambda = fresh_env.module_env.store.getExpr(fresh_destructured.expr);
    if (fresh_destructured_lambda != .e_lambda) return error.TestUnexpectedResult;
    const destructured_patterns = fresh_env.module_env.store.slicePatterns(fresh_destructured_lambda.e_lambda.args);
    try std.testing.expectEqual(@as(usize, 1), destructured_patterns.len);
    const destructured_pattern = fresh_env.module_env.store.getPattern(destructured_patterns[0]);
    if (destructured_pattern != .tuple) return error.TestUnexpectedResult;
    const destructured_children = fresh_env.module_env.store.slicePatterns(
        destructured_pattern.tuple.patterns,
    );
    try std.testing.expectEqual(@as(usize, 2), destructured_children.len);
    const destructured_body = fresh_env.module_env.store.getExpr(fresh_destructured_lambda.e_lambda.body);
    if (destructured_body != .e_lookup_local) return error.TestUnexpectedResult;
    try std.testing.expectEqual(destructured_children[0], destructured_body.e_lookup_local.pattern_idx);

    failure_stage = "nested formal topology";
    const nested_formal_def = cir.store.getDef(nested_formal_def_idx);
    const nested_formal_annotation_idx = nested_formal_def.annotation orelse
        return error.TestUnexpectedResult;
    const nested_formal_annotation = cir.store.getAnnotation(nested_formal_annotation_idx);
    const nested_formal_fn = cir.store.getTypeAnno(nested_formal_annotation.anno);
    if (nested_formal_fn != .@"fn") return error.TestUnexpectedResult;
    const nested_formals = cir.store.sliceTypeAnnos(nested_formal_fn.@"fn".args);
    try std.testing.expectEqual(@as(usize, 1), nested_formals.len);
    try std.testing.expect(cir.store.getTypeAnno(nested_formals[0]) == .tuple);
    const fresh_nested_idx = fresh_env.can.explicitRootDefByName("nested_formal") orelse
        return error.TestUnexpectedResult;
    const fresh_nested = fresh_env.module_env.store.getDef(fresh_nested_idx);
    const fresh_nested_lambda = fresh_env.module_env.store.getExpr(fresh_nested.expr);
    if (fresh_nested_lambda != .e_lambda) return error.TestUnexpectedResult;
    const nested_patterns = fresh_env.module_env.store.slicePatterns(fresh_nested_lambda.e_lambda.args);
    try std.testing.expectEqual(@as(usize, 1), nested_patterns.len);
    try std.testing.expect(fresh_env.module_env.store.getPattern(nested_patterns[0]) == .assign);
    const nested_body = fresh_env.module_env.store.getExpr(fresh_nested_lambda.e_lambda.body);
    if (nested_body != .e_lookup_local) return error.TestUnexpectedResult;
    try std.testing.expectEqual(nested_patterns[0], nested_body.e_lookup_local.pattern_idx);

    failure_stage = "clean sibling topology";
    const clean_def = cir.store.getDef(clean_def_idx);
    const clean_annotation_idx = clean_def.annotation orelse return error.TestUnexpectedResult;
    const clean_annotation = cir.store.getAnnotation(clean_annotation_idx);
    const clean_fn = cir.store.getTypeAnno(clean_annotation.anno);
    if (clean_fn != .@"fn") return error.TestUnexpectedResult;
    const clean_formals = cir.store.sliceTypeAnnos(clean_fn.@"fn".args);
    try std.testing.expectEqual(@as(usize, 2), clean_formals.len);
    try std.testing.expect(cir.store.getTypeAnno(clean_formals[0]) == .rigid_var);
    const clean_second = cir.store.getTypeAnno(clean_formals[1]);
    if (clean_second != .lookup or clean_second.lookup.base != .builtin or
        clean_second.lookup.base.builtin != .u64 or
        !clean_second.lookup.name.eql(cir.idents.u64))
    {
        return error.TestUnexpectedResult;
    }
    const fresh_clean_idx = fresh_env.can.explicitRootDefByName("clean") orelse
        return error.TestUnexpectedResult;
    const fresh_clean = fresh_env.module_env.store.getDef(fresh_clean_idx);
    const fresh_clean_lambda = fresh_env.module_env.store.getExpr(fresh_clean.expr);
    if (fresh_clean_lambda != .e_lambda) return error.TestUnexpectedResult;
    const clean_patterns = fresh_env.module_env.store.slicePatterns(fresh_clean_lambda.e_lambda.args);
    try std.testing.expectEqual(@as(usize, 2), clean_patterns.len);
    try std.testing.expect(fresh_env.module_env.store.getPattern(clean_patterns[0]) == .assign);
    try std.testing.expect(fresh_env.module_env.store.getPattern(clean_patterns[1]) == .assign);
    const clean_body = fresh_env.module_env.store.getExpr(fresh_clean_lambda.e_lambda.body);
    if (clean_body != .e_lookup_local) return error.TestUnexpectedResult;
    try std.testing.expect(clean_patterns[0] != clean_body.e_lookup_local.pattern_idx);
    try std.testing.expectEqual(clean_patterns[1], clean_body.e_lookup_local.pattern_idx);

    failure_stage = "fresh replay";
    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);
}

test "invalid where alias direct binder selects the source-ordered first malformed alias" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("multiple-alias direct-binder fixture failed at {s}\n", .{failure_stage});
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
        \\a.Mode : where [a.mode : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderMultipleA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    failure_stage = "consumer initialization";
    const consumer_source =
        \\import DirectBinderMultipleA exposing [Status, Mode]
        \\
        \\first : a -> a where [a.Status, a.Mode]
        \\first = |value| value
    ;
    var consumer = try TestEnv.initWithImport(
        "DirectBinderMultipleB",
        consumer_source,
        "DirectBinderMultipleA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderMultipleB",
        consumer_source,
        "DirectBinderMultipleA",
        &provider,
    );
    defer fresh_env.deinit();
    failure_stage = "canonical diagnostics";
    try consumer.assertCanErrors(&.{
        "Type Not Exposed",
        "Type Not Exposed",
        "Undeclared Type",
        "Undeclared Type",
    });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());

    failure_stage = "ledger inventory";
    const cir = consumer.module_env;
    const failures = cir.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 3), failures.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), cir.expected_retirement_failures.items.items.len);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    const proof = try uniqueDirectBinderLookupTestProof(cir);
    const lookup_failure = &failures[proof.failure_index];

    failure_stage = "source ordering topology";
    const first_def_idx = consumer.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const first_def = cir.store.getDef(first_def_idx);
    const annotation_idx = first_def.annotation orelse return error.TestUnexpectedResult;
    const annotation = cir.store.getAnnotation(annotation_idx);
    const where = annotation.where orelse return error.TestUnexpectedResult;
    const clauses = cir.store.sliceWhereClauses(where);
    try std.testing.expectEqual(@as(usize, 2), clauses.len);
    const first_clause = cir.store.getWhereClause(clauses[0]);
    const second_clause = cir.store.getWhereClause(clauses[1]);
    if (first_clause != .w_alias or second_clause != .w_alias) {
        return error.TestUnexpectedResult;
    }
    try std.testing.expect(cir.store.getTypeAnno(first_clause.w_alias.alias) == .malformed);
    try std.testing.expect(cir.store.getTypeAnno(second_clause.w_alias.alias) == .malformed);

    var first_source_failure: ?u32 = null;
    var second_source_failure: ?u32 = null;
    for (failures, 0..) |failure, failure_index| {
        if (failure.decodedKind() != .annotation_malformed_type) continue;
        if (failure.site_node == @intFromEnum(first_clause.w_alias.alias)) {
            if (first_source_failure != null) return error.TestUnexpectedResult;
            first_source_failure = @intCast(failure_index);
        } else if (failure.site_node == @intFromEnum(second_clause.w_alias.alias)) {
            if (second_source_failure != null) return error.TestUnexpectedResult;
            second_source_failure = @intCast(failure_index);
        } else {
            return error.TestUnexpectedResult;
        }
    }
    const first_failure_index = first_source_failure orelse return error.TestUnexpectedResult;
    const second_failure_index = second_source_failure orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(first_failure_index, proof.direct.local_record_index);
    const source_retirement = cir.expected_consumer_retirements.items.items[
        proof.source_retirement_index
    ];
    try std.testing.expectEqual(@as(u32, 2), source_retirement.expected_failures_len);
    try std.testing.expect(expectedRetirementOwnsFailure(
        cir,
        proof.source_retirement_index,
        first_failure_index,
    ));
    try std.testing.expect(expectedRetirementOwnsFailure(
        cir,
        proof.source_retirement_index,
        second_failure_index,
    ));
    const selected_target = firstMalformedWhereAliasTargetForRigid(
        cir,
        annotation_idx,
        lookup_failure.raw_peer_var,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(first_clause.w_alias.alias, selected_target);

    failure_stage = "fresh replay";
    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);

    failure_stage = "later source substitution";
    const saved_failure = lookup_failure.*;
    lookup_failure.subject_authority.payload.direct.local_record_index = second_failure_index;
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    const accepted_later_source = validateExpectedFailureContext(cir, context);
    lookup_failure.* = saved_failure;
    try std.testing.expectError(error.CorruptArtifact, accepted_later_source);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);
}

test "malformed where publication modes and suffix transactions are exhaustive" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\main : U64 where [42, 43]
        \\main = 1
    ;
    var test_env = try TestEnv.initUncheckedForTesting("MalformedWhereModes", source);
    defer test_env.deinit();

    const checker = &test_env.checker;
    const cir = test_env.module_env;
    const main_def_idx = test_env.can.explicitRootDefByName("main") orelse unreachable;
    const main_def = cir.store.getDef(main_def_idx);
    const annotation_idx = main_def.annotation orelse unreachable;
    const annotation = cir.store.getAnnotation(annotation_idx);
    const where = annotation.where orelse return error.TestUnexpectedResult;
    const clauses = cir.store.sliceWhereClauses(where);
    try std.testing.expectEqual(@as(usize, 2), clauses.len);
    const first_malformed = cir.store.getWhereClause(clauses[0]);
    try std.testing.expect(first_malformed == .w_malformed);
    const attachment = BodyAnnotationAttachment{
        .kind = .top_level_def,
        .node = @intFromEnum(main_def_idx),
    };
    _ = bodyAnnotationAttachmentIndexForWhereClause(
        cir,
        attachment,
        @intFromEnum(annotation_idx),
        main_def.expr,
        annotation.anno,
        clauses[0],
    ) orelse return error.TestUnexpectedResult;

    const baseline_failures = cir.expected_failures.items.items.len;
    const baseline_retirements = cir.expected_consumer_retirements.items.items.len;
    const baseline_drafts = checker.annotation_expected_failure_drafts.items.len;
    for (std.enums.values(AnnotationFailurePublicationMode.NoPublicationReason)) |reason| {
        var accumulator = AnnotationGenerationAccumulator{};
        const failure = (try checker.malformedWhereAnnotationGenerationFailure(
            annotation.anno,
            clauses[0],
            0,
            first_malformed.w_malformed.diagnostic,
            .{ .annotation = .{
                .where = where,
                .producer_owner_node = @intFromEnum(annotation_idx),
                .failure_publication = .{ .no_publication = reason },
                .failure_accumulator = &accumulator,
                .where_source_publication = switch (reason) {
                    .predeclared_scheme => .{ .no_publication = .predeclared_scheme },
                    .uninitialized_var => .{ .no_publication = .uninitialized_var },
                    .platform_requirement => .{ .no_publication = .platform_requirement },
                    .where_alias_declaration => .{ .no_publication = .where_alias_declaration },
                },
                .opening = .implicit_open,
            } },
        )) orelse return error.TestUnexpectedResult;
        accumulator.record(failure);
        accumulator.assertNoPublication();
        consumeNonPublishingAnnotationOutcome(accumulator.finish(ModuleEnv.varFrom(annotation.anno)));
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.annotation_malformed_where,
            failure.kind,
        );
        try std.testing.expectEqual(
            @intFromEnum(first_malformed.w_malformed.diagnostic),
            failure.cause_owner.decodedCirDiagnostic().?.index,
        );
        try std.testing.expectEqual(baseline_failures, cir.expected_failures.items.items.len);
        try std.testing.expectEqual(baseline_retirements, cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(baseline_drafts, checker.annotation_expected_failure_drafts.items.len);
    }

    var type_decl_accumulator = AnnotationGenerationAccumulator{};
    const type_decl_result = try checker.malformedWhereAnnotationGenerationFailure(
        annotation.anno,
        clauses[0],
        0,
        first_malformed.w_malformed.diagnostic,
        .{ .type_decl = .{
            .idx = @enumFromInt(0),
            .name = @bitCast(@as(u32, 0)),
            .type_ = .alias,
            .backing_var = ModuleEnv.varFrom(annotation.anno),
            .is_opaque = false,
            .num_args = 0,
        } },
    );
    _ = &type_decl_accumulator;
    try std.testing.expectEqual(@as(?AnnotationGenerationFailure, null), type_decl_result);
    try std.testing.expectEqual(baseline_failures, cir.expected_failures.items.items.len);
    try std.testing.expectEqual(baseline_retirements, cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(baseline_drafts, checker.annotation_expected_failure_drafts.items.len);

    try cir.expected_failures.items.ensureUnusedCapacity(cir.gpa, 1);
    try cir.expected_consumer_retirements.items.ensureUnusedCapacity(cir.gpa, 1);
    try std.testing.expectEqual(@as(usize, 0), checker.annotation_expected_failure_drafts.capacity);
    const original_checker_gpa = checker.gpa;
    const original_cir_gpa = cir.gpa;
    var failing_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = 0,
    });
    checker.gpa = failing_allocator.allocator();
    cir.gpa = failing_allocator.allocator();
    var oom_accumulator = AnnotationGenerationAccumulator{};
    const oom_result = checker.malformedWhereAnnotationGenerationFailure(
        annotation.anno,
        clauses[0],
        0,
        first_malformed.w_malformed.diagnostic,
        .{ .annotation = .{
            .where = where,
            .producer_owner_node = @intFromEnum(annotation_idx),
            .failure_publication = .{ .body_expression = .{
                .owner_expr = main_def.expr,
                .attachment = attachment,
            } },
            .failure_accumulator = &oom_accumulator,
            .where_source_publication = .body_annotation,
            .opening = .implicit_open,
        } },
    );
    checker.gpa = original_checker_gpa;
    cir.gpa = original_cir_gpa;
    try std.testing.expectError(error.OutOfMemory, oom_result);
    try std.testing.expect(failing_allocator.has_induced_failure);
    try std.testing.expectEqual(baseline_failures, cir.expected_failures.items.items.len);
    try std.testing.expectEqual(baseline_retirements, cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(baseline_drafts, checker.annotation_expected_failure_drafts.items.len);

    {
        var probe = try checker.beginProbe(null);
        var probe_open = true;
        errdefer if (probe_open) probe.rollback();
        var probe_accumulator = AnnotationGenerationAccumulator{};
        const saw_malformed = try checker.scanMalformedWhereClauses(
            annotation.anno,
            where,
            .{ .annotation = .{
                .where = where,
                .producer_owner_node = @intFromEnum(annotation_idx),
                .failure_publication = .{ .body_expression = .{
                    .owner_expr = main_def.expr,
                    .attachment = attachment,
                } },
                .failure_accumulator = &probe_accumulator,
                .where_source_publication = .body_annotation,
                .opening = .implicit_open,
            } },
        );
        try std.testing.expect(saw_malformed);
        try std.testing.expectEqual(baseline_failures + 2, cir.expected_failures.items.items.len);
        try std.testing.expectEqual(baseline_retirements + 1, cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(baseline_drafts + 2, checker.annotation_expected_failure_drafts.items.len);
        probe.rollback();
        probe_open = false;
    }
    try std.testing.expectEqual(baseline_failures, cir.expected_failures.items.items.len);
    try std.testing.expectEqual(baseline_retirements, cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(baseline_drafts, checker.annotation_expected_failure_drafts.items.len);
}

/// Test-only fixture discovery: find the unique canonical builtin-Num node
/// structurally owned by one exact generic body-annotation attachment. Durable
/// admission never scans; it replays the producer-authored node and index.
fn uniqueBuiltinNumTestSiteInBodyAttachment(
    cir: *const ModuleEnv,
    attachment_index: u32,
) error{TestUnexpectedResult}!CIR.TypeAnno.Idx {
    var found: ?CIR.TypeAnno.Idx = null;
    var raw_node: u32 = 0;
    while (raw_node < cir.store.nodes.len()) : (raw_node += 1) {
        if (builtinNotTypeSite(cir, raw_node) == null) continue;
        const candidate: CIR.TypeAnno.Idx = @enumFromInt(raw_node);
        if (!cir.bodyAnnotationAttachmentContainsTypeAnno(attachment_index, candidate)) continue;
        if (found != null) return error.TestUnexpectedResult;
        found = candidate;
    }
    return found orelse error.TestUnexpectedResult;
}

test "builtin Num annotation failure authenticates lookup and apply sites" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\lookup_value : Num
        \\lookup_value = 1
        \\
        \\apply_value : Num(U8)
        \\apply_value = 1
        \\
        \\nested_value : List(Num)
        \\nested_value = []
    ;
    var test_env = try TestEnv.init("BuiltinNumFailure", source);
    defer test_env.deinit();
    var fresh_env = try TestEnv.init("BuiltinNumFailure", source);
    defer fresh_env.deinit();

    const cir = test_env.module_env;
    const lookup_def_idx = test_env.can.explicitRootDefByName("lookup_value") orelse unreachable;
    const apply_def_idx = test_env.can.explicitRootDefByName("apply_value") orelse unreachable;
    const nested_def_idx = test_env.can.explicitRootDefByName("nested_value") orelse unreachable;
    const lookup_def = cir.store.getDef(lookup_def_idx);
    const apply_def = cir.store.getDef(apply_def_idx);
    const nested_def = cir.store.getDef(nested_def_idx);
    const failures = cir.expected_failures.items.items;
    try std.testing.expectEqual(@as(usize, 3), failures.len);
    const lookup_failure_index: usize = for (failures, 0..) |failure, failure_index| {
        if (failure.owner_node == @intFromEnum(lookup_def.expr)) break failure_index;
    } else return error.TestUnexpectedResult;
    const apply_failure_index: usize = for (failures, 0..) |failure, failure_index| {
        if (failure.owner_node == @intFromEnum(apply_def.expr)) break failure_index;
    } else return error.TestUnexpectedResult;
    const nested_failure_index: usize = for (failures, 0..) |failure, failure_index| {
        if (failure.owner_node == @intFromEnum(nested_def.expr)) break failure_index;
    } else return error.TestUnexpectedResult;
    const lookup_site: CIR.TypeAnno.Idx = @enumFromInt(failures[lookup_failure_index].site_node);
    const apply_site: CIR.TypeAnno.Idx = @enumFromInt(failures[apply_failure_index].site_node);
    const nested_site: CIR.TypeAnno.Idx = @enumFromInt(failures[nested_failure_index].site_node);
    try std.testing.expectEqual(CIR.Node.Tag.ty_lookup, cir.store.nodes.get(ModuleEnv.nodeIdxFrom(lookup_site)).tag);
    try std.testing.expectEqual(CIR.Node.Tag.ty_apply, cir.store.nodes.get(ModuleEnv.nodeIdxFrom(apply_site)).tag);
    try std.testing.expectEqual(CIR.Node.Tag.ty_lookup, cir.store.nodes.get(ModuleEnv.nodeIdxFrom(nested_site)).tag);
    const lookup_anno = cir.store.getTypeAnno(lookup_site);
    const apply_anno = cir.store.getTypeAnno(apply_site);
    const nested_anno = cir.store.getTypeAnno(nested_site);
    try std.testing.expect(lookup_anno == .lookup);
    try std.testing.expect(apply_anno == .apply);
    try std.testing.expect(nested_anno == .lookup);
    const apply_args = cir.store.sliceTypeAnnos(apply_anno.apply.args);
    try std.testing.expectEqual(@as(usize, 1), apply_args.len);
    const expected_sites = [_]CIR.TypeAnno.Idx{ lookup_site, apply_site, nested_site };
    const expected_owners = [_]CIR.Expr.Idx{ lookup_def.expr, apply_def.expr, nested_def.expr };
    const failure_indices = [_]usize{ lookup_failure_index, apply_failure_index, nested_failure_index };
    for (failure_indices, expected_sites, expected_owners) |failure_index, site, owner_expr| {
        const failure = failures[failure_index];
        try std.testing.expect(failure.hasLegalTags());
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.annotation_builtin_not_type,
            failure.decodedKind().?,
        );
        try std.testing.expectEqual(@intFromEnum(owner_expr), failure.owner_node);
        try std.testing.expectEqual(@intFromEnum(site), failure.site_node);
        try std.testing.expectEqual(@intFromEnum(ModuleEnv.varFrom(owner_expr)), failure.raw_owner_var);
        try std.testing.expectEqual(@intFromEnum(ModuleEnv.varFrom(site)), failure.raw_subject_var);
        try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.raw_peer_var);
        try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.constraint_index);
        try std.testing.expectEqual(@as(u32, 0), failure.slot);
        try std.testing.expectEqual(ModuleEnv.ExpectedFailure.none, failure.plan_index);
        try std.testing.expect(failure.cause_owner.hasCanonicalTags(false));
        try std.testing.expectEqual(ModuleEnv.CauseOwner.none, failure.cause_owner.kind);
        const direct = failure.subject_authority.decodedDirect() orelse unreachable;
        try std.testing.expectEqual(
            ModuleEnv.SubjectAuthority.DirectPhase.annotation_builtin_not_type,
            failure.subject_authority.decodedDirectPhase().?,
        );
        try std.testing.expectEqual(@intFromEnum(site), direct.producer_node);
        try std.testing.expect(direct.local_record_index < cir.body_annotation_attachments.items.items.len);
        const attachment = cir.body_annotation_attachments.items.items[direct.local_record_index];
        try std.testing.expectEqual(@intFromEnum(owner_expr), attachment.body_expr);
        try std.testing.expect(cir.bodyAnnotationAttachmentContainsTypeAnno(
            direct.local_record_index,
            site,
        ));
        try std.testing.expect(builtinNotTypeExpectedFailureIsLocallyValid(cir, failure, direct));
    }
    try std.testing.expectEqual(@as(usize, 0), cir.malformed_type_annotation_publications.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), cir.body_annotation_malformed_type_publications.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), test_env.checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    const context = ImportResolution.freshEmpty(fresh_env.module_env);
    try validateExpectedFailureContext(cir, context);

    const lookup_failure = &failures[lookup_failure_index];
    const saved_lookup_failure = lookup_failure.*;
    const apply_direct = failures[apply_failure_index].subject_authority.decodedDirect() orelse unreachable;

    lookup_failure.subject_authority.payload.direct.local_record_index = apply_direct.local_record_index;
    const accepted_sibling_attachment = validateExpectedFailureRetirementLocal(&cir.types, cir);
    lookup_failure.* = saved_lookup_failure;
    try std.testing.expect(!accepted_sibling_attachment);

    lookup_failure.subject_authority.payload.direct.local_record_index = ModuleEnv.SubjectAuthority.none;
    const accepted_missing_attachment = validateExpectedFailureRetirementLocal(&cir.types, cir);
    lookup_failure.* = saved_lookup_failure;
    try std.testing.expect(!accepted_missing_attachment);

    lookup_failure.site_node = @intFromEnum(nested_site);
    lookup_failure.raw_subject_var = @intFromEnum(ModuleEnv.varFrom(nested_site));
    lookup_failure.subject_authority.payload.direct.producer_node = @intFromEnum(nested_site);
    const accepted_detached_site = validateExpectedFailureRetirementLocal(&cir.types, cir);
    lookup_failure.* = saved_lookup_failure;
    try std.testing.expect(!accepted_detached_site);

    lookup_failure.cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(0);
    const accepted_cause = validateExpectedFailureRetirementLocal(&cir.types, cir);
    lookup_failure.* = saved_lookup_failure;
    try std.testing.expect(!accepted_cause);

    lookup_failure.slot = 1;
    const accepted_slot = validateExpectedFailureRetirementLocal(&cir.types, cir);
    lookup_failure.* = saved_lookup_failure;
    try std.testing.expect(!accepted_slot);

    const apply_arg_anno = cir.store.getTypeAnno(apply_args[0]);
    try std.testing.expect(apply_arg_anno == .lookup);
    const lookup_node_idx = ModuleEnv.nodeIdxFrom(lookup_site);
    const saved_lookup_node = cir.store.nodes.get(lookup_node_idx);
    var changed_lookup_node = saved_lookup_node;
    var changed_lookup_payload = changed_lookup_node.getPayload();
    changed_lookup_payload.ty_lookup.name = @bitCast(apply_arg_anno.lookup.name);
    changed_lookup_node.setPayload(changed_lookup_payload);
    cir.store.nodes.set(lookup_node_idx, changed_lookup_node);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    const accepted_cached_name = validateExpectedFailureContext(cir, context);
    cir.store.nodes.set(lookup_node_idx, saved_lookup_node);
    try std.testing.expectError(error.CorruptArtifact, accepted_cached_name);

    const apply_node_idx = ModuleEnv.nodeIdxFrom(apply_site);
    const saved_apply_node = cir.store.nodes.get(apply_node_idx);
    cir.store.nodes.set(lookup_node_idx, saved_apply_node);
    cir.store.nodes.set(apply_node_idx, saved_lookup_node);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    const accepted_swapped_forms = validateExpectedFailureContext(cir, context);
    cir.store.nodes.set(lookup_node_idx, saved_lookup_node);
    cir.store.nodes.set(apply_node_idx, saved_apply_node);
    try std.testing.expectError(error.CorruptArtifact, accepted_swapped_forms);

    const saved_apply_arg = apply_args[0];
    apply_args[0] = nested_site;
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    const accepted_cached_args = validateExpectedFailureContext(cir, context);
    apply_args[0] = saved_apply_arg;
    try std.testing.expectError(error.CorruptArtifact, accepted_cached_args);

    const apply_payload = saved_apply_node.getPayload().ty_apply;
    const apply_data = &cir.store.type_apply_data.items.items[apply_payload.type_apply_data_idx];
    const saved_apply_data = apply_data.*;
    apply_data.value1 = @intFromEnum(CIR.TypeAnno.Builtin.u8);
    const accepted_other_builtin = validateExpectedFailureRetirementLocal(&cir.types, cir);
    apply_data.* = saved_apply_data;
    try std.testing.expect(!accepted_other_builtin);

    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);
}

test "builtin Num annotation failure suppresses a preexisting runtime-error owner" {
