    try std.testing.expect(validateExpectedFailureRetirementLocal(
        &test_env.module_env.types,
        test_env.module_env,
    ));
}

test "builtin Num publication modes and draft transaction are exhaustive" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\main : Num
        \\main = 1
    ;
    var test_env = try TestEnv.initUncheckedForTesting("BuiltinNumModes", source);
    defer test_env.deinit();

    const checker = &test_env.checker;
    const cir = test_env.module_env;
    const main_def_idx = test_env.can.explicitRootDefByName("main") orelse unreachable;
    const main_def = cir.store.getDef(main_def_idx);
    const annotation_idx = main_def.annotation orelse unreachable;
    const attachment = BodyAnnotationAttachment{
        .kind = .top_level_def,
        .node = @intFromEnum(main_def_idx),
    };
    const attachment_index = cir.bodyAnnotationAttachmentIndex(
        attachment.kind,
        attachment.node,
        annotation_idx,
        main_def.expr,
    ) orelse return error.TestUnexpectedResult;
    const site = try uniqueBuiltinNumTestSiteInBodyAttachment(cir, attachment_index);

    const baseline_failures = cir.expected_failures.items.items.len;
    const baseline_retirements = cir.expected_consumer_retirements.items.items.len;
    const baseline_drafts = checker.annotation_expected_failure_drafts.items.len;
    for (std.enums.values(AnnotationFailurePublicationMode.NoPublicationReason)) |reason| {
        var accumulator = AnnotationGenerationAccumulator{};
        const failure = (try checker.builtinNotTypeAnnotationGenerationFailure(site, .{ .annotation = .{
            .where = null,
            .producer_owner_node = @intFromEnum(annotation_idx),
            .failure_publication = .{ .no_publication = reason },
            .failure_accumulator = &accumulator,
            .where_source_publication = switch (reason) {
                .predeclared_scheme => .{ .no_publication = .predeclared_scheme },
                .uninitialized_var => .{ .no_publication = .uninitialized_var },
                .platform_requirement => .{ .no_publication = .platform_requirement },
                .where_alias_declaration => .{ .no_publication = .where_alias_declaration },
            },
            .opening = .implicit_open,
        } })) orelse return error.TestUnexpectedResult;
        accumulator.record(failure);
        accumulator.assertNoPublication();
        consumeNonPublishingAnnotationOutcome(accumulator.finish(ModuleEnv.varFrom(annotation_idx)));
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.annotation_builtin_not_type,
            failure.kind,
        );
        try std.testing.expect(failure.cause_owner.hasCanonicalTags(false));
        try std.testing.expectEqual(ModuleEnv.CauseOwner.none, failure.cause_owner.kind);
        try std.testing.expectEqual(baseline_failures, cir.expected_failures.items.items.len);
        try std.testing.expectEqual(baseline_retirements, cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(baseline_drafts, checker.annotation_expected_failure_drafts.items.len);
    }

    // Pre-reserve the two durable appends, then force the sole draft allocation
    // to fail after both succeed. This proves the producer's errdefer removes
    // its partial failure and retirement.
    try cir.expected_failures.items.ensureUnusedCapacity(cir.gpa, 1);
    try cir.expected_consumer_retirements.items.ensureUnusedCapacity(cir.gpa, 1);
    try std.testing.expect(
        cir.expected_failures.items.items.len < cir.expected_failures.items.capacity,
    );
    try std.testing.expect(
        cir.expected_consumer_retirements.items.items.len <
            cir.expected_consumer_retirements.items.capacity,
    );
    try std.testing.expectEqual(@as(usize, 0), checker.annotation_expected_failure_drafts.capacity);
    const original_checker_gpa = checker.gpa;
    const original_cir_gpa = cir.gpa;
    var failing_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = 0,
    });
    checker.gpa = failing_allocator.allocator();
    cir.gpa = failing_allocator.allocator();
    var oom_accumulator = AnnotationGenerationAccumulator{};
    const oom_result = checker.builtinNotTypeAnnotationGenerationFailure(site, .{ .annotation = .{
        .where = null,
        .producer_owner_node = @intFromEnum(annotation_idx),
        .failure_publication = .{ .body_expression = .{
            .owner_expr = main_def.expr,
            .attachment = attachment,
        } },
        .failure_accumulator = &oom_accumulator,
        .where_source_publication = .body_annotation,
        .opening = .implicit_open,
    } });
    checker.gpa = original_checker_gpa;
    cir.gpa = original_cir_gpa;
    try std.testing.expectError(error.OutOfMemory, oom_result);
    try std.testing.expect(failing_allocator.has_induced_failure);
    try std.testing.expectEqual(baseline_failures, cir.expected_failures.items.items.len);
    try std.testing.expectEqual(baseline_retirements, cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(baseline_drafts, checker.annotation_expected_failure_drafts.items.len);

    {
        var probe = try checker.beginProbe(null);
        var probe_open = true;
        errdefer if (probe_open) probe.rollback();
        var probe_accumulator = AnnotationGenerationAccumulator{};
        const failure = (try checker.builtinNotTypeAnnotationGenerationFailure(site, .{ .annotation = .{
            .where = null,
            .producer_owner_node = @intFromEnum(annotation_idx),
            .failure_publication = .{ .body_expression = .{
                .owner_expr = main_def.expr,
                .attachment = attachment,
            } },
            .failure_accumulator = &probe_accumulator,
            .where_source_publication = .body_annotation,
            .opening = .implicit_open,
        } })) orelse return error.TestUnexpectedResult;
        probe_accumulator.record(failure);
        try std.testing.expectEqual(baseline_failures + 1, cir.expected_failures.items.items.len);
        try std.testing.expectEqual(baseline_retirements + 1, cir.expected_consumer_retirements.items.items.len);
        try std.testing.expectEqual(baseline_drafts + 1, checker.annotation_expected_failure_drafts.items.len);
        probe.rollback();
        probe_open = false;
    }
    try std.testing.expectEqual(baseline_failures, cir.expected_failures.items.items.len);
    try std.testing.expectEqual(baseline_retirements, cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(baseline_drafts, checker.annotation_expected_failure_drafts.items.len);
}

test "Expected failure and retirement order replays one combined causal DAG" {
    const makeFailure = struct {
        fn call(owner_node: u32, cause_owner: ModuleEnv.CauseOwner) ModuleEnv.ExpectedFailure {
            const has_cause = cause_owner.kind != ModuleEnv.CauseOwner.none;
            return .{
                .owner_node = owner_node,
                .site_node = owner_node,
                .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
                .kind = @intFromEnum(if (has_cause)
                    ModuleEnv.ExpectedFailure.Kind.annotation_child_failure
                else
                    ModuleEnv.ExpectedFailure.Kind.annotation_where_receiver_not_introduced),
                .raw_owner_var = owner_node,
                .raw_subject_var = owner_node,
                .raw_peer_var = ModuleEnv.ExpectedFailure.none,
                .constraint_index = ModuleEnv.ExpectedFailure.none,
                .slot = 0,
                .plan_index = ModuleEnv.ExpectedFailure.none,
                .subject_authority = ModuleEnv.SubjectAuthority.direct(
                    owner_node,
                    if (has_cause)
                        .annotation_child_before_copy
                    else
                        .annotation_where_receiver_not_introduced,
                    null,
                ),
                .cause_owner = cause_owner,
            };
        }
    }.call;
    const makeRetirement = struct {
        fn call(retired_node: u32, expected_failures_len: u32) ModuleEnv.ExpectedConsumerRetirement {
            return .{
                .retired_node = retired_node,
                .owner_kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression),
                .original_node_tag = @intFromEnum(CIR.Node.Tag.expr_call),
                .original_payload = .{ 0, 0, 0, 0 },
                .kind = @intFromEnum(ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible),
                .retired_consumers_start = 0,
                .retired_consumers_len = 0,
                .diagnostic_index = 0,
                .expected_failures_start = 0,
                .expected_failures_len = expected_failures_len,
                .rejection_owner_kind = ModuleEnv.ExpectedConsumerRetirement.none,
                .rejection_owner_index = ModuleEnv.ExpectedConsumerRetirement.none,
                .rejection_subject_var = ModuleEnv.ExpectedConsumerRetirement.none,
            };
        }
    }.call;

    // Failure 1 has the smaller semantic key, but it is blocked on the
    // retirement, which is itself blocked on failure 0.
    const ordered_failures = [_]ModuleEnv.ExpectedFailure{
        makeFailure(20, ModuleEnv.CauseOwner.inactive()),
        makeFailure(10, ModuleEnv.CauseOwner.expectedConsumerRetirement(0)),
    };
    const ordered_retirements = [_]ModuleEnv.ExpectedConsumerRetirement{
        makeRetirement(30, 1),
    };
    const ordered_retirement_failures = [_]ModuleEnv.ExpectedRetirementFailure{
        .{ .failure_index = 0 },
    };
    try std.testing.expect(expectedFailureRetirementOrderIsCanonical(
        &ordered_failures,
        &ordered_retirements,
        &ordered_retirement_failures,
    ));

    const swapped_ready_failures = [_]ModuleEnv.ExpectedFailure{
        makeFailure(20, ModuleEnv.CauseOwner.inactive()),
        makeFailure(10, ModuleEnv.CauseOwner.inactive()),
    };
    try std.testing.expect(!expectedFailureRetirementOrderIsCanonical(
        &swapped_ready_failures,
        &.{},
        &.{},
    ));

    const cyclic_failures = [_]ModuleEnv.ExpectedFailure{
        makeFailure(20, ModuleEnv.CauseOwner.expectedConsumerRetirement(0)),
    };
    const cyclic_retirements = [_]ModuleEnv.ExpectedConsumerRetirement{
        makeRetirement(30, 1),
    };
    const cyclic_retirement_failures = [_]ModuleEnv.ExpectedRetirementFailure{
        .{ .failure_index = 0 },
    };
    try std.testing.expect(!expectedFailureRetirementOrderIsCanonical(
        &cyclic_failures,
        &cyclic_retirements,
        &cyclic_retirement_failures,
    ));

    // A provider-owned cause is a terminal edge in this module's local DAG.
    const external_terminal_cause = [_]ModuleEnv.ExpectedFailure{
        makeFailure(20, ModuleEnv.CauseOwner.providerWhereAliasCheckedError(3, 4)),
    };
    try std.testing.expect(expectedFailureRetirementOrderIsCanonical(
        &external_terminal_cause,
        &.{},
        &.{},
    ));

    // An absent local predecessor leaves the row disconnected rather than
    // being treated as a terminal external cause.
    const missing_local_cause = [_]ModuleEnv.ExpectedFailure{
        makeFailure(20, ModuleEnv.CauseOwner.expectedFailure(9)),
    };
    try std.testing.expect(!expectedFailureRetirementOrderIsCanonical(
        &missing_local_cause,
        &.{},
        &.{},
    ));
}

test "local marker copy publishes exact root relation and immediate basis" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("LocalMarkerCopy", "{}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const markers = try appendTestWhereMethodMarkerRef(checker, 1);
    const callable = try checker.freshFromContentAtRank(
        .{ .structure = .empty_record },
        &env,
        Region.zero(),
        .generalized,
    );
    const source_constraints = try checker.types.appendStaticDispatchConstraints(&.{.{
        .fn_name = checker.cir.idents.is_eq,
        .fn_var = callable,
        .origin = .{ .where_clause = .{} },
        .where_method_markers = markers,
    }});
    const source_root = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init().withConstraints(source_constraints) },
        &env,
        Region.zero(),
        .generalized,
    );

    const copied = try checker.instantiateVarWithMarkerCopy(
        source_root,
        &env,
        .{ .explicit = Region.zero() },
        .{ .type_annotation = .{ .node = 0 } },
        .if_marker_carried,
    );
    const step_index = copied.copy_step orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 0), step_index);
    try std.testing.expectEqual(@as(usize, 1), checker.cir.where_marker_copy_steps.items.items.len);
    const step = checker.cir.where_marker_copy_steps.items.items[step_index];
    try std.testing.expectEqual(@intFromEnum(source_root), step.source_root_var);
    try std.testing.expectEqual(@intFromEnum(checker.types.resolveVar(copied.var_).var_), step.destination_root_var);
    const pairs = checker.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len];
    try std.testing.expect(pairs.len >= 2);
    const root_pair = for (pairs) |pair| {
        if (pair.source_var == step.source_root_var and
            pair.destination_var == step.destination_root_var) break pair;
    } else return error.TestUnexpectedResult;
    try std.testing.expectEqual(step.destination_root_var, root_pair.destination_var);
    try std.testing.expectEqual(@as(u32, 0), root_pair.discovery_depth);
    try std.testing.expectEqual(std.math.maxInt(u32), root_pair.predecessor_pair_offset);
    try std.testing.expectEqual(std.math.maxInt(u32), root_pair.predecessor_edge_ordinal);

    const copied_constraints = checker.types.sliceStaticDispatchConstraints(
        checker.types.resolveVar(copied.var_).desc.content.flex.constraints,
    );
    try std.testing.expectEqual(@as(usize, 1), copied_constraints.len);
    const copied_bases = checker.types.sliceWhereMethodMarkerBases(
        copied_constraints[0].where_method_marker_bases,
    );
    try std.testing.expectEqual(@as(usize, 1), copied_bases.len);
    try std.testing.expectEqual(step_index, copied_bases[0].copy_step);
    try std.testing.expectEqual(@as(u32, @intFromEnum(source_constraints.start)), copied_bases[0].source_constraint_index);
    try std.testing.expectEqual(@as(u32, 0), copied_bases[0].source_contract_offset);

    const constraint_pairs = checker.cir.where_marker_constraint_copy_pairs.items.items[step.constraint_pairs_start..][0..step.constraint_pairs_len];
    try std.testing.expectEqual(@as(usize, 1), constraint_pairs.len);
    try std.testing.expect(
        constraint_pairs[0].source_constraint_index != constraint_pairs[0].destination_constraint_index,
    );
    try std.testing.expectEqual(@as(usize, 1), checker.cir.dispatch_settlement_sources.items.items.len);
    try std.testing.expectEqual(@as(usize, 1), checker.cir.selected_receiver_anchors.items.items.len);
    const source = checker.cir.dispatch_settlement_sources.items.items[0]
        .decodedCopiedConstraint() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 0), source.anchor_index);
    try std.testing.expectEqual(
        ModuleEnv.CopiedConstraintComponentRef.Kind.root_graph,
        source.receiver_component_ref.decodedKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.CopiedConstraintComponentRef.Kind.root_graph,
        source.function_component_ref.decodedKind().?,
    );
    try std.testing.expectEqual(step_index, source.receiver_component_ref.copy_step_index);
    try std.testing.expectEqual(step_index, source.function_component_ref.copy_step_index);
    try std.testing.expectEqual(@as(u32, 0), source.function_component_ref.constraint_pair_offset);
    const anchor = checker.cir.selected_receiver_anchors.items.items[source.anchor_index];
    try std.testing.expectEqual(source.receiver_component_ref.occurrence_offset, anchor.receiver_occurrence_offset);
    try std.testing.expectEqual(source.function_component_ref.constraint_pair_offset, anchor.constraint_pair_offset);
    const evidence = checker.types.sliceConstraintEvidenceHandles(copied_constraints[0].constraint_evidence);
    try std.testing.expectEqual(@as(usize, 1), evidence.len);
    try std.testing.expectEqual(
        types_mod.ConstraintEvidenceHandle.Kind.selected_receiver_anchor,
        evidence[0].decodedKind().?,
    );
    try std.testing.expectEqual(source.anchor_index, evidence[0].index);
    try std.testing.expect(validateCopiedConstraintSourceComponents(
        checker.cir,
        checker.cir.dispatch_settlement_sources.items.items[0].payload.copied_constraint,
    ));
    var primary_count: usize = 0;
    const step_witnesses = checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len];
    for (step_witnesses) |witness| {
        if (witness.constraint_pair_offset != 0) continue;
        switch (witness.decodedEdgeKind() orelse return error.TestUnexpectedResult) {
            .static_dispatch_function, .scheme_requirement_function => primary_count += 1,
            else => {},
        }
    }
    try std.testing.expectEqual(@as(usize, 1), primary_count);
    // This unit fixture invokes the provisional producer after TestEnv's
    // terminal boundary. Apply the same production BFS canonicalization that
    // the checked-boundary transaction applies before local admission.
    for (pairs) |pair| {
        if (pair.source_var == step.source_root_var and pair.destination_var == step.destination_root_var) continue;
        try std.testing.expectEqual(std.math.maxInt(u32), pair.discovery_depth);
        try std.testing.expectEqual(std.math.maxInt(u32), pair.predecessor_pair_offset);
        try std.testing.expectEqual(std.math.maxInt(u32), pair.predecessor_edge_ordinal);
    }
    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
        checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len],
        step_witnesses,
        step.root_occurrence_offset,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    // The anchor cannot survive deletion or duplication of its unique source
    // producer, even though all remaining raw endpoints still solve to the
    // same types.
    const source_row = checker.cir.dispatch_settlement_sources.items.items[0];
    checker.cir.dispatch_settlement_sources.items.shrinkRetainingCapacity(0);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    try checker.cir.dispatch_settlement_sources.items.ensureUnusedCapacity(std.testing.allocator, 2);
    checker.cir.dispatch_settlement_sources.items.appendAssumeCapacity(source_row);
    checker.cir.dispatch_settlement_sources.items.appendAssumeCapacity(source_row);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    checker.cir.dispatch_settlement_sources.items.shrinkRetainingCapacity(1);

    // Pair-bearing reference edges do not hide a second primary producer.
    // Retarget a forged static witness to another exact occurrence in the
    // same proof so it is non-duplicate and structurally in-bounds.
    const witness_pool = &checker.cir.where_marker_copy_witnesses.items;
    const witness_len_before = witness_pool.items.len;
    const step_witness_len_before = checker.cir.where_marker_copy_steps.items.items[step_index].witnesses_len;
    const witness_backup = try std.testing.allocator.dupe(
        ModuleEnv.WhereMarkerCopyWitness,
        witness_pool.items[step.witnesses_start..][0..step.witnesses_len],
    );
    defer std.testing.allocator.free(witness_backup);
    const primary = for (witness_backup) |witness| {
        if (witness.decodedEdgeKind() == .static_dispatch_function) break witness;
    } else return error.TestUnexpectedResult;
    var forged_primary = primary;
    forged_primary.child_occurrence_offset = primary.parent_occurrence_offset;
    try witness_pool.ensureUnusedCapacity(std.testing.allocator, 1);
    witness_pool.appendAssumeCapacity(forged_primary);
    checker.cir.where_marker_copy_steps.items.items[step_index].witnesses_len += 1;
    std.mem.sortUnstable(
        ModuleEnv.WhereMarkerCopyWitness,
        witness_pool.items[step.witnesses_start..][0 .. step.witnesses_len + 1],
        {},
        whereMarkerCopyWitnessLessThan,
    );
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    witness_pool.shrinkRetainingCapacity(witness_len_before);
    checker.cir.where_marker_copy_steps.items.items[step_index].witnesses_len = step_witness_len_before;
    @memcpy(
        witness_pool.items[step.witnesses_start..][0..step.witnesses_len],
        witness_backup,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
}

const TestCopiedOpenLiteralCopy = struct {
    source_root: Var,
    destination_root: Var,
    copy_step: u32,
};

fn appendTestCopiedOpenLiteralCopy(
    checker: *Self,
    env: *Env,
    insert_unreferenced_constraint_gap: bool,
) Allocator.Error!TestCopiedOpenLiteralCopy {
    const callable = try checker.freshFromContentAtRank(
        .{ .structure = .empty_record },
        env,
        Region.zero(),
        .generalized,
    );
    const source_constraints = try checker.types.appendStaticDispatchConstraints(&.{
        .{
            .fn_name = checker.cir.idents.from_numeral,
            .fn_var = callable,
            .origin = .{ .where_clause = .{} },
        },
        .{
            .fn_name = checker.cir.idents.from_quote,
            .fn_var = callable,
            .origin = .{ .where_clause = .{} },
        },
        .{
            .fn_name = checker.cir.idents.from_interpolation,
            .fn_var = callable,
            .origin = .{ .where_clause = .{} },
        },
        .{
            .fn_name = checker.cir.idents.is_eq,
            .fn_var = callable,
            .origin = .{ .where_clause = .{} },
        },
    });
    const source_root = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init().withConstraints(source_constraints) },
        env,
        Region.zero(),
        .generalized,
    );
    if (insert_unreferenced_constraint_gap) {
        _ = try checker.types.appendStaticDispatchConstraints(&.{.{
            .fn_name = checker.cir.idents.is_eq,
            .fn_var = callable,
            .origin = .{ .where_clause = .{} },
        }});
    }

    const copied = try checker.instantiateVarWithMarkerCopy(
        source_root,
        env,
        .{ .explicit = Region.zero() },
        .{ .type_annotation = .{ .node = 0 } },
        .if_marker_carried,
    );
    return .{
        .source_root = source_root,
        .destination_root = copied.var_,
        .copy_step = copied.copy_step orelse
            std.debug.panic("copied-open-literal test fixture did not publish its proof step", .{}),
    };
}

fn appendTestCopiedOpenLiteralMoves(
    checker: *Self,
    copy_step: u32,
) Allocator.Error![3]u32 {
    const step = checker.cir.where_marker_copy_steps.items.items[copy_step];
    if (step.copied_groups_len != 1) {
        std.debug.panic("copied-open-literal movement fixture expected one group", .{});
    }
    const group = checker.cir.copied_open_literal_groups.items.items[step.copied_groups_start];
    if (group.events_len != 3) {
        std.debug.panic("copied-open-literal movement fixture expected three events", .{});
    }
    const events = checker.cir.copied_open_literal_events.items.items[group.events_start..][0..group.events_len];
    var destinations: [3]u32 = undefined;
    for (events, 0..) |event, event_offset| {
        const source_constraint_index = group.destination_constraints_start +
            event.constraint_offset;
        const source_constraint = checker.types.static_dispatch_constraints.items.items[
            source_constraint_index
        ];
        const destination = try checker.types.appendStaticDispatchConstraints(&.{source_constraint});
        const destination_constraint_index: u32 = @intFromEnum(destination.start);
        try checker.appendConstraintEvidenceMoves(
            &.{source_constraint_index},
            destination_constraint_index,
        );
        destinations[event_offset] = destination_constraint_index;
    }
    return destinations;
}

fn swapTestCopiedLiteralEventIndex(
    event_index: u32,
    first_start: u32,
    second_start: u32,
    events_len: u32,
) u32 {
    if (event_index >= first_start and event_index - first_start < events_len) {
        return second_start + (event_index - first_start);
    }
    if (event_index >= second_start and event_index - second_start < events_len) {
        return first_start + (event_index - second_start);
    }
    return event_index;
}

test "one local copied open receiver publishes one event and handle per literal constraint" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initUncheckedForTesting("LocalCopiedOpenLiteralGroup", "main = {}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const copied = try appendTestCopiedOpenLiteralCopy(checker, &env, false);
    const step_index = copied.copy_step;
    const step = checker.cir.where_marker_copy_steps.items.items[step_index];
    try std.testing.expectEqual(@as(u32, 1), step.copied_groups_len);
    try std.testing.expectEqual(@as(usize, 1), checker.cir.copied_open_literal_groups.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), checker.cir.copied_open_literal_events.items.items.len);

    const group = checker.cir.copied_open_literal_groups.items.items[step.copied_groups_start];
    try std.testing.expectEqual(step_index, group.copy_step_index);
    try std.testing.expectEqual(ModuleEnv.CopiedOpenLiteralComponent.Kind.root_graph, group.component.decodedKind().?);
    try std.testing.expectEqual(@as(u32, 4), group.source_constraints_len);
    try std.testing.expectEqual(group.source_constraints_len, group.destination_constraints_len);
    try std.testing.expectEqual(@as(u32, 3), group.events_len);
    const events = checker.cir.copied_open_literal_events.items.items[group.events_start..][0..group.events_len];
    const expected_kinds = [_]ModuleEnv.CopiedOpenLiteralEvent.LiteralKind{
        .numeral,
        .quote,
        .interpolation,
    };
    for (events, expected_kinds, 0..) |event, expected_kind, event_offset| {
        try std.testing.expectEqual(@as(u32, 0), event.group_index);
        try std.testing.expectEqual(@as(u32, @intCast(event_offset)), event.constraint_offset);
        try std.testing.expectEqual(expected_kind, event.decodedLiteralKind().?);
    }

    const destination_constraints = checker.types.sliceStaticDispatchConstraints(
        checker.types.resolveVar(copied.destination_root).desc.content.flex.constraints,
    );
    try std.testing.expectEqual(@as(usize, 4), destination_constraints.len);
    for (destination_constraints, 0..) |constraint, constraint_offset| {
        const handles = checker.types.sliceConstraintEvidenceHandles(constraint.constraint_evidence);
        try std.testing.expectEqual(@as(usize, if (constraint_offset < 3) 2 else 1), handles.len);
        try std.testing.expectEqual(
            types_mod.ConstraintEvidenceHandle.Kind.selected_receiver_anchor,
            handles[0].decodedKind().?,
        );
        if (constraint_offset < 3) {
            try std.testing.expectEqual(
                types_mod.ConstraintEvidenceHandle.Kind.copied_literal_event,
                handles[1].decodedKind().?,
            );
            try std.testing.expectEqual(@as(u32, @intCast(constraint_offset)), handles[1].index);
        }
    }

    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
        checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len],
        checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len],
        step.root_occurrence_offset,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
}

test "local fresh-flex copy witness survives exact validation rebuild and serde" {
    const TestEnv = @import("test/TestEnv.zig");
    const source = "main = {}";
    var test_env = try TestEnv.initUncheckedForTesting("FreshFlexCopyWitness", source);
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const copied = try appendTestCopiedOpenLiteralCopy(checker, &env, false);
    const step = checker.cir.where_marker_copy_steps.items.items[copied.copy_step];
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerCopyStep.CopyPolicy.ranked_fresh_flex_close,
        step.decodedCopyPolicy().?,
    );
    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
        checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len],
        checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len],
        step.root_occurrence_offset,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const occurrences = checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
    const root_occurrence = occurrences[step.root_occurrence_offset];
    const witnesses = checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len];
    var creation_offset: ?u32 = null;
    var constraint_edge_count: usize = 0;
    for (witnesses, 0..) |witness, witness_offset| {
        if (witness.decodedEdgeKind() == .static_dispatch_function) {
            constraint_edge_count += 1;
        }
        if (witness.decodedAction() != .flex_fresh_flex_copy) continue;
        if (creation_offset != null) return error.TestUnexpectedResult;
        creation_offset = @intCast(witness_offset);
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyWitness.EdgeKind.root_copy_action,
            witness.decodedEdgeKind().?,
        );
        try std.testing.expectEqual(@as(u32, 0), witness.edge_index);
        try std.testing.expectEqual(@as(u32, 0), witness.edge_name);
        try std.testing.expectEqual(@as(u32, 0), witness.edge_origin_module);
        try std.testing.expectEqual(@as(u32, 0), witness.edge_source_decl);
        try std.testing.expectEqual(std.math.maxInt(u32), witness.constraint_pair_offset);
        try std.testing.expectEqual(step.root_occurrence_offset, witness.parent_occurrence_offset);
        try std.testing.expectEqual(step.root_occurrence_offset, witness.child_occurrence_offset);
        try std.testing.expectEqual(root_occurrence.raw_source_var, witness.raw_source_var);
        try std.testing.expectEqual(root_occurrence.raw_destination_var, witness.raw_destination_var);
        try std.testing.expect(witness.raw_source_var != witness.raw_destination_var);
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyWitness.AuxiliaryOriginKind.none,
            witness.decodedAuxiliaryOriginKind().?,
        );
        try std.testing.expectEqual(@as(u32, 0), witness.auxiliary_origin_step);
        try std.testing.expectEqual(@as(u32, 0), witness.auxiliary_origin_index);
    }
    try std.testing.expectEqual(@as(usize, 4), constraint_edge_count);
    const root_pair = checker.cir.where_marker_copy_pairs.items.items[
        step.pairs_start + root_occurrence.canonical_pair_offset
    ];
    try std.testing.expectEqual(
        @as(Var, @enumFromInt(root_pair.source_var)),
        checker.types.resolveVar(@enumFromInt(root_occurrence.raw_source_var)).var_,
    );
    try std.testing.expectEqual(
        @as(Var, @enumFromInt(root_pair.destination_var)),
        checker.types.resolveVar(@enumFromInt(root_occurrence.raw_destination_var)).var_,
    );
    const source_constraints = checker.types.sliceStaticDispatchConstraints(
        checker.types.resolveVar(copied.source_root).desc.content.flex.constraints,
    );
    const destination_constraints = checker.types.sliceStaticDispatchConstraints(
        checker.types.resolveVar(copied.destination_root).desc.content.flex.constraints,
    );
    const alternate_raw_source: u32 = @intFromEnum(source_constraints[0].fn_var);
    const alternate_raw_destination: u32 = @intFromEnum(destination_constraints[0].fn_var);
    try std.testing.expect(alternate_raw_source != root_occurrence.raw_source_var);
    try std.testing.expect(alternate_raw_source != root_occurrence.raw_destination_var);
    try std.testing.expect(alternate_raw_destination != root_occurrence.raw_source_var);
    try std.testing.expect(alternate_raw_destination != root_occurrence.raw_destination_var);
    const creation_index = step.witnesses_start +
        (creation_offset orelse return error.TestUnexpectedResult);
    const original = checker.cir.where_marker_copy_witnesses.items.items[creation_index];

    const action_values = std.enums.values(ModuleEnv.WhereMarkerCopyWitness.Action);
    try std.testing.expectEqual(
        @as(u32, @intCast(action_values.len - 1)),
        @intFromEnum(ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_fresh_flex_copy),
    );
    for ([_]ModuleEnv.WhereMarkerCopyStep.CopyPolicy{
        .ranked_fresh_flex_close,
        .ranked_fresh_flex_close_scheme,
        .ranked_fresh_flex_preserve,
        .ranked_fresh_flex_resolve_positive,
        .ranked_fresh_flex_resolve_negative,
        .ranked_fresh_flex_defer_positive,
        .ranked_fresh_flex_defer_negative,
        .ranked_substitute_rigids_close,
        .ranked_substitute_rigids_preserve,
        .ranked_substitute_rigids_resolve_positive,
        .ranked_substitute_rigids_resolve_negative,
        .ranked_substitute_rigids_defer_positive,
        .ranked_substitute_rigids_defer_negative,
        .all_fresh_rigid_preserve,
        .all_fresh_flex_preserve,
    }) |policy| {
        inline for (.{
            ModuleEnv.WhereMarkerCopyWitness.Action.flex_fresh_flex_copy,
            ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_fresh_flex_copy,
        }) |action| {
            try std.testing.expect(whereMarkerCopyPolicyAllowsAction(policy, action));
        }
    }
    for ([_]ModuleEnv.WhereMarkerCopyStep.CopyPolicy{
        .cross_module_import,
        .all_share_leaves_resolve_positive,
    }) |policy| {
        inline for (.{
            ModuleEnv.WhereMarkerCopyWitness.Action.flex_fresh_flex_copy,
            ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_fresh_flex_copy,
        }) |action| {
            try std.testing.expect(!whereMarkerCopyPolicyAllowsAction(policy, action));
        }
    }

    var creation = &checker.cir.where_marker_copy_witnesses.items.items[creation_index];
    creation.action = std.math.maxInt(u32);
    const accepted_unknown_action = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_unknown_action);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.action = @intFromEnum(ModuleEnv.WhereMarkerCopyWitness.Action.rigid_fresh_rigid_cut);
    const accepted_swapped_action = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_swapped_action);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.raw_source_var = std.math.maxInt(u32);
    const accepted_absent_source = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_absent_source);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.raw_destination_var = creation.raw_source_var;
    const accepted_equal_raw_ids = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_equal_raw_ids);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.raw_source_var = @intCast(checker.types.len());
    const accepted_source_out_of_range = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_source_out_of_range);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.raw_destination_var = @intCast(checker.types.len());
    const accepted_destination_out_of_range = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_destination_out_of_range);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.raw_source_var = alternate_raw_source;
    const accepted_wrong_child_source = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_wrong_child_source);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.raw_destination_var = alternate_raw_destination;
    const accepted_wrong_child_destination = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_wrong_child_destination);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.auxiliary_origin_kind = @intFromEnum(
        ModuleEnv.WhereMarkerCopyWitness.AuxiliaryOriginKind.scheme_use,
    );
    const accepted_auxiliary = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_auxiliary);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.auxiliary_origin_step = 1;
    const accepted_auxiliary_step = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_auxiliary_step);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    creation.auxiliary_origin_index = 1;
    const accepted_auxiliary_index = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    creation.* = original;
    try std.testing.expect(!accepted_auxiliary_index);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    try checker.rebuildCheckedBoundaryWhereMethodState();
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    const canonical_once = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(canonical_once);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    const canonical_twice = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(canonical_twice);
    try std.testing.expectEqualSlices(u8, canonical_once, canonical_twice);

    const buffer = try serializeModuleEnvForDeserializationTest(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(buffer);
    try std.testing.expectEqualSlices(u8, canonical_twice, buffer);
    const base_addr = @intFromPtr(buffer.ptr);
    const serialized: *const ModuleEnv.Serialized = @ptrCast(@alignCast(buffer.ptr));
    try serialized.validate(buffer.len);

    const readonly = try serialized.deserializeInto(
        base_addr,
        std.testing.allocator,
        source,
        "FreshFlexCopyWitness",
    );
    defer {
        readonly.imports.deinitMapOnly(std.testing.allocator);
        readonly.import_mapping.deinit();
        std.testing.allocator.destroy(readonly);
    }
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&readonly.types, readonly));
    var readonly_action_count: usize = 0;
    for (readonly.where_marker_copy_witnesses.items.items) |witness| {
        readonly_action_count += @intFromBool(witness.decodedAction() == .flex_fresh_flex_copy);
    }
    try std.testing.expectEqual(@as(usize, 1), readonly_action_count);
    const readonly_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        readonly,
    );
    defer std.testing.allocator.free(readonly_bytes);
    try std.testing.expectEqualSlices(u8, canonical_twice, readonly_bytes);

    const mutable = try serialized.deserializeWithMutableTypes(
        base_addr,
        std.testing.allocator,
        source,
        "FreshFlexCopyWitness",
    );
    defer {
        mutable.deinitCachedModule();
        std.testing.allocator.destroy(mutable);
    }
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&mutable.types, mutable));
    var mutable_action_count: usize = 0;
    for (mutable.where_marker_copy_witnesses.items.items) |witness| {
        mutable_action_count += @intFromBool(witness.decodedAction() == .flex_fresh_flex_copy);
    }
    try std.testing.expectEqual(@as(usize, 1), mutable_action_count);
    const mutable_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        mutable,
    );
    defer std.testing.allocator.free(mutable_bytes);
    try std.testing.expectEqualSlices(u8, canonical_twice, mutable_bytes);
}

test "one exact raw mapping has one fresh-flex allocation witness" {
