    const step_index = copied.copy_step orelse return error.TestUnexpectedResult;
    const step = checker.cir.where_marker_copy_steps.items.items[step_index];
    const occurrences = checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
    const witnesses = checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len];
    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
        occurrences,
        witnesses,
        step.root_occurrence_offset,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    var first_edge_absolute: ?u32 = null;
    var repeated_edge_absolute: ?u32 = null;
    for (witnesses, 0..) |witness, witness_offset| {
        if (witness.decodedEdgeKind() != .tuple_element) continue;
        if (witness.edge_index == 0) {
            try std.testing.expectEqual(
                ModuleEnv.WhereMarkerCopyWitness.Action.flex_fresh_flex_copy,
                witness.decodedAction().?,
            );
            first_edge_absolute = step.witnesses_start + @as(u32, @intCast(witness_offset));
        } else if (witness.edge_index == 1) {
            try std.testing.expectEqual(
                ModuleEnv.WhereMarkerCopyWitness.Action.traverse,
                witness.decodedAction().?,
            );
            try std.testing.expectEqual(std.math.maxInt(u32), witness.raw_source_var);
            try std.testing.expectEqual(std.math.maxInt(u32), witness.raw_destination_var);
            repeated_edge_absolute = step.witnesses_start + @as(u32, @intCast(witness_offset));
        }
    }
    const first_index = first_edge_absolute orelse return error.TestUnexpectedResult;
    const repeated_index = repeated_edge_absolute orelse return error.TestUnexpectedResult;
    const first_edge = checker.cir.where_marker_copy_witnesses.items.items[first_index];
    const repeated_before = checker.cir.where_marker_copy_witnesses.items.items[repeated_index];
    try std.testing.expectEqual(
        first_edge.child_occurrence_offset,
        repeated_before.child_occurrence_offset,
    );

    // The repeated tuple edge is an authentic memoized traversal. Giving it
    // otherwise exact allocation fields would create a second authority for
    // the same raw mapping and must fail before any graph-shape replay.
    const child = occurrences[repeated_before.child_occurrence_offset];
    var repeated = &checker.cir.where_marker_copy_witnesses.items.items[repeated_index];
    repeated.action = @intFromEnum(ModuleEnv.WhereMarkerCopyWitness.Action.flex_fresh_flex_copy);
    repeated.raw_source_var = child.raw_source_var;
    repeated.raw_destination_var = child.raw_destination_var;
    const accepted_duplicate_allocation = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    repeated.* = repeated_before;
    try std.testing.expect(!accepted_duplicate_allocation);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
}

test "attached interpolation fresh copies are structural non-ingress witnesses" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initUncheckedForTesting(
        "StructuralInterpolationFreshCopy",
        "main = {}",
    );
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const callable = try checker.freshFromContentAtRank(
        .{ .structure = .empty_record },
        &env,
        Region.zero(),
        .generalized,
    );
    const interpolation_part = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init() },
        &env,
        Region.zero(),
        .generalized,
    );
    const interpolation_item = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init() },
        &env,
        Region.zero(),
        .generalized,
    );
    const interpolation_parts = try checker.types.appendInterpolationParts(&.{.{
        .var_ = interpolation_part,
        .region = Region.zero(),
    }});
    const source_constraints = try checker.types.appendStaticDispatchConstraints(&.{.{
        .fn_name = checker.cir.idents.from_interpolation,
        .fn_var = callable,
        .origin = .{ .where_clause = .{} },
        .interpolation = .{
            .expr_region = StaticDispatchConstraint.OptRegion.some(Region.zero()),
            .item_var = interpolation_item,
            .interpolated_parts = interpolation_parts,
        },
    }});
    const source_root = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init().withConstraints(source_constraints) },
        &env,
        Region.zero(),
        .generalized,
    );
    const copied = try checker.instantiateVarWithMarkerCopy(
        source_root,
        &env,
        .{ .explicit = Region.zero() },
        .{ .type_annotation = .{ .node = 0 } },
        .eager_support,
    );
    const step_index = copied.copy_step orelse return error.TestUnexpectedResult;
    const step = checker.cir.where_marker_copy_steps.items.items[step_index];
    const occurrences = checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
    const witnesses = checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len];
    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
        occurrences,
        witnesses,
        step.root_occurrence_offset,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    var root_creation_count: usize = 0;
    var primary_count: usize = 0;
    var interpolation_count: usize = 0;
    for (witnesses, 0..) |witness, witness_offset| {
        const edge_kind = witness.decodedEdgeKind() orelse return error.TestUnexpectedResult;
        if (edge_kind == .root_copy_action) {
            try std.testing.expectEqual(
                ModuleEnv.WhereMarkerCopyWitness.Action.flex_fresh_flex_copy,
                witness.decodedAction().?,
            );
            root_creation_count += 1;
        }
        if (edge_kind == .static_dispatch_function) {
            try std.testing.expectEqual(@as(u32, 0), witness.constraint_pair_offset);
            try std.testing.expect(
                !whereMarkerWitnessActionIsRequirementComponentIngress(witness.decodedAction().?),
            );
            primary_count += 1;
        }
        if (edge_kind != .interpolation_part and edge_kind != .interpolation_item) continue;
        try std.testing.expectEqual(@as(u32, 0), witness.constraint_pair_offset);
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyWitness.Action.flex_fresh_flex_copy,
            witness.decodedAction().?,
        );
        interpolation_count += 1;

        // This child genuinely allocated, but its pair primary is the attached
        // structural function. Relabeling the exact raw witness as a virtual
        // combined ingress must be rejected even beside a non-traverse root.
        const absolute = step.witnesses_start + @as(u32, @intCast(witness_offset));
        const before = checker.cir.where_marker_copy_witnesses.items.items[absolute];
        var candidate = &checker.cir.where_marker_copy_witnesses.items.items[absolute];
        candidate.action = @intFromEnum(
            ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_fresh_flex_copy,
        );
        const accepted_virtual_relabel = validateWhereMarkerCopyProofLocal(
            checker.types,
            checker.cir,
        );
        candidate.* = before;
        try std.testing.expect(!accepted_virtual_relabel);
        try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    }
    try std.testing.expectEqual(@as(usize, 1), root_creation_count);
    try std.testing.expectEqual(@as(usize, 1), primary_count);
    try std.testing.expectEqual(@as(usize, 2), interpolation_count);
}

test "Probe rollback owns copied open literal groups events handles and moves" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initUncheckedForTesting("CopiedOpenLiteralProbeRollback", "main = {}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const before = .{
        .constraints = checker.types.static_dispatch_constraints.items.items.len,
        .handles = checker.types.constraint_evidence_handles.items.items.len,
        .steps = checker.cir.where_marker_copy_steps.items.items.len,
        .pairs = checker.cir.where_marker_copy_pairs.items.items.len,
        .occurrences = checker.cir.where_marker_copy_occurrences.items.items.len,
        .constraint_pairs = checker.cir.where_marker_constraint_copy_pairs.items.items.len,
        .witnesses = checker.cir.where_marker_copy_witnesses.items.items.len,
        .groups = checker.cir.copied_open_literal_groups.items.items.len,
        .events = checker.cir.copied_open_literal_events.items.items.len,
        .anchors = checker.cir.selected_receiver_anchors.items.items.len,
        .sources = checker.cir.dispatch_settlement_sources.items.items.len,
        .moves = checker.cir.constraint_evidence_moves.items.items.len,
    };

    var probe = try checker.beginProbe(&env);
    var probe_open = true;
    errdefer if (probe_open) probe.rollback();
    const copied = try appendTestCopiedOpenLiteralCopy(checker, &env, true);
    _ = try appendTestCopiedOpenLiteralMoves(checker, copied.copy_step);
    try std.testing.expect(checker.cir.copied_open_literal_groups.items.items.len > before.groups);
    try std.testing.expect(checker.cir.copied_open_literal_events.items.items.len >= before.events + 3);
    try std.testing.expect(checker.types.constraint_evidence_handles.items.items.len > before.handles);
    try std.testing.expect(checker.cir.constraint_evidence_moves.items.items.len >= before.moves + 3);
    probe.rollback();
    probe_open = false;

    try std.testing.expectEqual(before.constraints, checker.types.static_dispatch_constraints.items.items.len);
    try std.testing.expectEqual(before.handles, checker.types.constraint_evidence_handles.items.items.len);
    try std.testing.expectEqual(before.steps, checker.cir.where_marker_copy_steps.items.items.len);
    try std.testing.expectEqual(before.pairs, checker.cir.where_marker_copy_pairs.items.items.len);
    try std.testing.expectEqual(before.occurrences, checker.cir.where_marker_copy_occurrences.items.items.len);
    try std.testing.expectEqual(before.constraint_pairs, checker.cir.where_marker_constraint_copy_pairs.items.items.len);
    try std.testing.expectEqual(before.witnesses, checker.cir.where_marker_copy_witnesses.items.items.len);
    try std.testing.expectEqual(before.groups, checker.cir.copied_open_literal_groups.items.items.len);
    try std.testing.expectEqual(before.events, checker.cir.copied_open_literal_events.items.items.len);
    try std.testing.expectEqual(before.anchors, checker.cir.selected_receiver_anchors.items.items.len);
    try std.testing.expectEqual(before.sources, checker.cir.dispatch_settlement_sources.items.items.len);
    try std.testing.expectEqual(before.moves, checker.cir.constraint_evidence_moves.items.items.len);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
}

test "copied open literal local proof rejects missing duplicate orphan and cross-attached rows" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initUncheckedForTesting("CopiedOpenLiteralCorruption", "main = {}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const copied = try appendTestCopiedOpenLiteralCopy(checker, &env, false);
    const provisional_step = checker.cir.where_marker_copy_steps.items.items[copied.copy_step];
    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[provisional_step.pairs_start..][0..provisional_step.pairs_len],
        checker.cir.where_marker_copy_occurrences.items.items[provisional_step.occurrences_start..][0..provisional_step.occurrences_len],
        checker.cir.where_marker_copy_witnesses.items.items[provisional_step.witnesses_start..][0..provisional_step.witnesses_len],
        provisional_step.root_occurrence_offset,
    );
    const step = &checker.cir.where_marker_copy_steps.items.items[copied.copy_step];
    const group_index = step.copied_groups_start;
    var group = &checker.cir.copied_open_literal_groups.items.items[group_index];
    const group_before = group.*;
    const events = checker.cir.copied_open_literal_events.items.items[group.events_start..][0..group.events_len];
    try std.testing.expectEqual(@as(usize, 3), events.len);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    // A step cannot omit its group while leaving the group pool orphaned.
    step.copied_groups_len = 0;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    step.copied_groups_len = 1;
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    // Nor can an otherwise well-formed duplicate group sit outside every
    // owner range.
    const group_pool = &checker.cir.copied_open_literal_groups.items;
    const group_pool_len = group_pool.items.len;
    try group_pool.ensureUnusedCapacity(checker.cir.gpa, 1);
    group_pool.appendAssumeCapacity(group_before);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    group_pool.shrinkRetainingCapacity(group_pool_len);
    group = &checker.cir.copied_open_literal_groups.items.items[group_index];
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    // Group ownership and source/destination range coordinates are exact
    // foreign keys, not advisory metadata.
    group.copy_step_index = std.math.maxInt(u32);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    group.* = group_before;
    group.source_constraints_start += 1;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    group.* = group_before;
    group.destination_constraints_len -= 1;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    group.* = group_before;
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const event_pool = &checker.cir.copied_open_literal_events.items;
    const event_pool_len = event_pool.items.len;
    const final_event = event_pool.items[event_pool_len - 1];
    try event_pool.ensureUnusedCapacity(checker.cir.gpa, 1);

    // Missing and orphan event rows both break the gapless group partition.
    event_pool.shrinkRetainingCapacity(event_pool_len - 1);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    event_pool.appendAssumeCapacity(final_event);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    event_pool.appendAssumeCapacity(final_event);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    event_pool.shrinkRetainingCapacity(event_pool_len);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    // Duplicate and reordered rows cannot masquerade as the literal event
    // inventory of the source range.
    event_pool.appendAssumeCapacity(final_event);
    group.events_len += 1;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    group.events_len -= 1;
    event_pool.shrinkRetainingCapacity(event_pool_len);
    std.mem.swap(
        ModuleEnv.CopiedOpenLiteralEvent,
        &event_pool.items[group.events_start],
        &event_pool.items[group.events_start + 1],
    );
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    std.mem.swap(
        ModuleEnv.CopiedOpenLiteralEvent,
        &event_pool.items[group.events_start],
        &event_pool.items[group.events_start + 1],
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const creation_constraint = &checker.types.static_dispatch_constraints.items.items[
        group.destination_constraints_start
    ];
    const creation_evidence_before = creation_constraint.constraint_evidence;
    const creation_handles = checker.types.constraint_evidence_handles.items.items[creation_evidence_before.start..][0..creation_evidence_before.len];
    try std.testing.expectEqual(@as(usize, 2), creation_handles.len);
    const selected_handle = creation_handles[0];
    const event_handle = creation_handles[1];

    // Every event owns one exact handle at its creation constraint.
    creation_constraint.constraint_evidence.len = 1;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    creation_constraint.constraint_evidence = creation_evidence_before;
    creation_handles[0] = event_handle;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    creation_handles[0] = selected_handle;
    creation_handles[1].index += 1;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    creation_handles[1] = event_handle;
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
}

test "copied open literal checked boundary remaps reordered groups events handles and moves" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initUncheckedForTesting("CopiedOpenLiteralBoundaryRemap", "main = {}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    const step_base = checker.cir.where_marker_copy_steps.items.items.len;
    const group_base = checker.cir.copied_open_literal_groups.items.items.len;
    const event_base = checker.cir.copied_open_literal_events.items.items.len;
    const constraint_base = checker.types.static_dispatch_constraints.items.items.len;
    const discarded_step = try checker.reserveLocalWhereMarkerCopyStep();
    try std.testing.expectEqual(@as(u32, @intCast(step_base)), discarded_step);
    checker.discardReservedLocalWhereMarkerCopyStep(discarded_step);

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const first = try appendTestCopiedOpenLiteralCopy(checker, &env, true);
    const moved_destinations = try appendTestCopiedOpenLiteralMoves(checker, first.copy_step);
    const second = try appendTestCopiedOpenLiteralCopy(checker, &env, true);
    try std.testing.expect(first.copy_step > discarded_step);
    try std.testing.expect(second.copy_step > first.copy_step);
    try std.testing.expect(moved_destinations[0] < moved_destinations[1]);
    try std.testing.expect(moved_destinations[1] < moved_destinations[2]);

    const first_step = &checker.cir.where_marker_copy_steps.items.items[first.copy_step];
    const second_step = &checker.cir.where_marker_copy_steps.items.items[second.copy_step];
    try std.testing.expectEqual(@as(u32, 1), first_step.copied_groups_len);
    try std.testing.expectEqual(@as(u32, 1), second_step.copied_groups_len);
    const first_group_index = first_step.copied_groups_start;
    const second_group_index = second_step.copied_groups_start;
    try std.testing.expectEqual(@as(u32, @intCast(group_base)), first_group_index);
    try std.testing.expectEqual(first_group_index + 1, second_group_index);

    const groups = checker.cir.copied_open_literal_groups.items.items;
    const first_group = groups[first_group_index];
    const second_group = groups[second_group_index];
    try std.testing.expectEqual(@as(u32, 3), first_group.events_len);
    try std.testing.expectEqual(first_group.events_len, second_group.events_len);
    try std.testing.expectEqual(@as(u32, @intCast(event_base)), first_group.events_start);
    try std.testing.expectEqual(first_group.events_start + first_group.events_len, second_group.events_start);

    var first_events: [3]ModuleEnv.CopiedOpenLiteralEvent = undefined;
    var second_events: [3]ModuleEnv.CopiedOpenLiteralEvent = undefined;
    @memcpy(
        first_events[0..],
        checker.cir.copied_open_literal_events.items.items[first_group.events_start..][0..3],
    );
    @memcpy(
        second_events[0..],
        checker.cir.copied_open_literal_events.items.items[second_group.events_start..][0..3],
    );

    // Model the valid preterminal order produced when an earlier reserved
    // outer step finishes after a nested step: owner ranges partition the
    // pools exactly, but their physical group/event blocks are not in step-id
    // order. The checked boundary must canonicalize this without guessing.
    groups[first_group_index] = second_group;
    groups[first_group_index].events_start = first_group.events_start;
    groups[second_group_index] = first_group;
    groups[second_group_index].events_start = second_group.events_start;
    first_step.copied_groups_start = second_group_index;
    second_step.copied_groups_start = first_group_index;
    @memcpy(
        checker.cir.copied_open_literal_events.items.items[first_group.events_start..][0..3],
        second_events[0..],
    );
    @memcpy(
        checker.cir.copied_open_literal_events.items.items[second_group.events_start..][0..3],
        first_events[0..],
    );
    for (checker.cir.copied_open_literal_events.items.items[first_group.events_start..][0..3]) |*event| {
        event.group_index = first_group_index;
    }
    for (checker.cir.copied_open_literal_events.items.items[second_group.events_start..][0..3]) |*event| {
        event.group_index = second_group_index;
    }
    for (checker.types.constraint_evidence_handles.items.items) |*handle| {
        if (handle.decodedKind() != .copied_literal_event) continue;
        handle.index = swapTestCopiedLiteralEventIndex(
            handle.index,
            first_group.events_start,
            second_group.events_start,
            first_group.events_len,
        );
    }
    for (checker.cir.constraint_evidence_moves.items.items) |*move| {
        if (move.handle.decodedKind() != .copied_literal_event) continue;
        move.handle.index = swapTestCopiedLiteralEventIndex(
            move.handle.index,
            first_group.events_start,
            second_group.events_start,
            first_group.events_len,
        );
    }

    // Final-form admission intentionally rejects the provisional owner order,
    // while the transaction's preterminal validator accepts the exact
    // nonoverlapping partition and prepares its canonical relocation.
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    {
        var transaction = CheckedBoundaryRebuild.init(checker);
        defer transaction.deinit();
        try transaction.validateAndOrder();
    }

    const constraints_before = checker.types.static_dispatch_constraints.items.items.len;
    const old_first_group_index = first_step.copied_groups_start;
    const old_first_group = groups[old_first_group_index];
    try checker.rebuildCheckedBoundaryWhereMethodState();
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    try std.testing.expectEqual(
        constraint_base + 8 + 8 + 3,
        checker.types.static_dispatch_constraints.items.items.len,
    );
    try std.testing.expectEqual(
        constraints_before - 2,
        checker.types.static_dispatch_constraints.items.items.len,
    );

    const first_destination_root: u32 = @intFromEnum(
        checker.types.resolveVar(first.destination_root).var_,
    );
    const new_first_step_index: u32 = for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.destination_root_var == first_destination_root) break @intCast(step_index);
    } else return error.TestUnexpectedResult;
    try std.testing.expect(new_first_step_index < first.copy_step);
    const new_first_step = checker.cir.where_marker_copy_steps.items.items[new_first_step_index];
    const new_first_group_index = new_first_step.copied_groups_start;
    const new_first_group = checker.cir.copied_open_literal_groups.items.items[new_first_group_index];
    try std.testing.expect(new_first_group_index < old_first_group_index);
    try std.testing.expectEqual(new_first_step_index, new_first_group.copy_step_index);
    try std.testing.expectEqual(@as(u32, 4), new_first_group.source_constraints_len);
    try std.testing.expectEqual(new_first_group.source_constraints_len, new_first_group.destination_constraints_len);
    try std.testing.expect(new_first_group.destination_constraints_start < old_first_group.destination_constraints_start);
    try std.testing.expectEqual(@as(u32, 3), new_first_group.events_len);
    try std.testing.expect(new_first_group.events_start < old_first_group.events_start);

    var copied_move_count: usize = 0;
    for (checker.cir.copied_open_literal_events.items.items[new_first_group.events_start..][0..new_first_group.events_len], 0..) |event, event_offset| {
        const event_index = new_first_group.events_start + @as(u32, @intCast(event_offset));
        try std.testing.expectEqual(new_first_group_index, event.group_index);
        const creation_constraint_index = new_first_group.destination_constraints_start +
            event.constraint_offset;
        const creation_constraint = checker.types.static_dispatch_constraints.items.items[
            creation_constraint_index
        ];
        var creation_handle_count: usize = 0;
        for (checker.types.sliceConstraintEvidenceHandles(creation_constraint.constraint_evidence)) |handle| {
            if (handle.decodedKind() == .copied_literal_event and handle.index == event_index) {
                creation_handle_count += 1;
            }
        }
        try std.testing.expectEqual(@as(usize, 1), creation_handle_count);
        for (checker.cir.constraint_evidence_moves.items.items) |move| {
            if (move.handle.decodedKind() != .copied_literal_event or
                move.handle.index != event_index)
            {
                continue;
            }
            try std.testing.expectEqual(creation_constraint_index, move.source_constraint_index);
            try std.testing.expect(move.destination_constraint_index > move.source_constraint_index);
            copied_move_count += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 3), copied_move_count);

    // A second terminal pass is canonical-byte-idempotent, including the
    // remapped group/event pools, handle ranges, movements, and descriptor
    // constraint ranges. Successful rebuilds replace owned allocations, so
    // canonical serialization—not pointer identity—is the idempotence check.
    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_before);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const serialized_after = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_after);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
}

test "virtual requirement fresh-flex copies survive exact local publication and serde" {
    const TestEnv = @import("test/TestEnv.zig");
    const source = "main = {}";
    var test_env = try TestEnv.initExpr("VirtualRequirementFreshFlexCopy", source);
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const scheme_root = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init() },
        &env,
        Region.zero(),
        .generalized,
    );
    const attached_callable = try checker.freshFromContentAtRank(
        .{ .structure = .empty_record },
        &env,
        Region.zero(),
        .generalized,
    );
    const attached_range = try checker.types.appendStaticDispatchConstraints(&.{.{
        .fn_name = checker.cir.idents.is_eq,
        .fn_var = attached_callable,
        .origin = .{ .where_clause = .{} },
    }});
    const attached_source_index: u32 = @intFromEnum(attached_range.start);
    const receiver = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init().withConstraints(attached_range) },
        &env,
        Region.zero(),
        .outermost,
    );
    const interface_elems = try checker.types.appendVars(&.{receiver});
    const boundary_interface = try checker.freshFromContentAtRank(
        .{ .structure = .{ .tuple = .{ .elems = interface_elems } } },
        &env,
        Region.zero(),
        .outermost,
    );

    const rigid_name = try checker.cir.insertIdent(base.Ident.for_text("detached_callable"));
    const detached_callable = try checker.freshFromContentAtRank(
        .{ .rigid = Rigid.init(rigid_name) },
        &env,
        Region.zero(),
        .outermost,
    );
    const second_rigid_name = try checker.cir.insertIdent(base.Ident.for_text("second_detached_callable"));
    const second_detached_callable = try checker.freshFromContentAtRank(
        .{ .rigid = Rigid.init(second_rigid_name) },
        &env,
        Region.zero(),
        .outermost,
    );
    const interpolation_part = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init() },
        &env,
        Region.zero(),
        .generalized,
    );
    const interpolation_item = try checker.freshFromContentAtRank(
        .{ .flex = Flex.init() },
        &env,
        Region.zero(),
        .generalized,
    );
    const interpolation_parts = try checker.types.appendInterpolationParts(&.{.{
        .var_ = interpolation_part,
        .region = Region.zero(),
    }});
    const detached_constraint = StaticDispatchConstraint{
        .fn_name = checker.cir.idents.is_eq,
        .fn_var = detached_callable,
        .origin = .{ .where_clause = .{} },
        .interpolation = .{
            .expr_region = StaticDispatchConstraint.OptRegion.some(Region.zero()),
            .item_var = interpolation_item,
            .interpolated_parts = interpolation_parts,
        },
    };
    const second_method_name = try checker.cir.insertIdent(base.Ident.for_text("second_requirement"));
    const second_detached_constraint = StaticDispatchConstraint{
        .fn_name = second_method_name,
        .fn_var = second_detached_callable,
        .origin = .{ .where_clause = .{} },
    };

    // Exercise the real detached-registration and boundary-capture operations
    // over controlled typed requirement inputs. Each detached source occurrence
    // is distinct from the attached occurrence on the receiver, while
    // structural_origin retains that exact creation relation. The explicit
    // generated-codec input is consumed by capture and later forces the
    // receiver component copy; this fixture does not claim upstream codec
    // classification or parsed-file admission coverage.
    const candidates_before = checker.scheme_requirement_candidates.items.len;
    const constraints_before_detached = checker.types.static_dispatch_constraints.items.items.len;
    const previous_active_scheme_root = checker.active_scheme_root;
    checker.active_scheme_root = scheme_root;
    defer checker.active_scheme_root = previous_active_scheme_root;
    try checker.registerInstantiatedSchemeRequirement(.{
        .scheme_receiver_var = receiver,
        .receiver_var = receiver,
        .scheme_fn_var = detached_callable,
        .constraint = detached_constraint,
        .source_constraint_index = std.math.maxInt(u32),
        .deferred_generated_codec = true,
        .structural_origin = .{
            .receiver_var = receiver,
            .constraint_fn_var = attached_callable,
        },
    }, null, null, null, &env);
    const detached_source_index: u32 = @intCast(constraints_before_detached);
    const constraints_before_second = checker.types.static_dispatch_constraints.items.items.len;
    try checker.registerInstantiatedSchemeRequirement(.{
        .scheme_receiver_var = receiver,
        .receiver_var = receiver,
        .scheme_fn_var = second_detached_callable,
        .constraint = second_detached_constraint,
        .source_constraint_index = std.math.maxInt(u32),
        .deferred_generated_codec = true,
        .structural_origin = .{
            .receiver_var = receiver,
            .constraint_fn_var = attached_callable,
        },
    }, null, null, null, &env);
    const second_detached_source_index: u32 = @intCast(constraints_before_second);
    try std.testing.expect(detached_source_index != attached_source_index);
    try std.testing.expect(second_detached_source_index != attached_source_index);
    try std.testing.expect(second_detached_source_index != detached_source_index);
    try std.testing.expectEqual(
        constraints_before_detached + 2,
        checker.types.static_dispatch_constraints.items.items.len,
    );
    try std.testing.expectEqual(candidates_before + 2, checker.scheme_requirement_candidates.items.len);
    const detached_candidate = checker.scheme_requirement_candidates.items[candidates_before];
    const second_detached_candidate = checker.scheme_requirement_candidates.items[candidates_before + 1];
    try std.testing.expectEqual(SchemeRequirementCandidate.Source.scheme_copy, detached_candidate.source);
    try std.testing.expectEqual(detached_source_index, detached_candidate.constraint_index);
    try std.testing.expectEqual(receiver, detached_candidate.structural_origin.receiver_var);
    try std.testing.expectEqual(attached_callable, detached_candidate.structural_origin.constraint_fn_var);
    try std.testing.expectEqual(SchemeRequirementCandidate.Source.scheme_copy, second_detached_candidate.source);
    try std.testing.expectEqual(second_detached_source_index, second_detached_candidate.constraint_index);
    try std.testing.expectEqual(receiver, second_detached_candidate.structural_origin.receiver_var);
    try std.testing.expectEqual(attached_callable, second_detached_candidate.structural_origin.constraint_fn_var);

    try checker.captureSchemeDispatchRequirements(&.{.{
        .owner = scheme_root,
        .interface = boundary_interface,
    }}, &env);
    try std.testing.expectEqual(candidates_before, checker.scheme_requirement_candidates.items.len);
    const scheme_index = checker.typeSchemeIndexForRoot(scheme_root) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        @as(usize, 2),
        checker.type_schemes.items[scheme_index].dispatch_requirements.items.len,
    );
    const captured = checker.type_schemes.items[scheme_index].dispatch_requirements.items[0];
    const second_captured = checker.type_schemes.items[scheme_index].dispatch_requirements.items[1];
    try std.testing.expect(captured.deferred_generated_codec);
    try std.testing.expectEqual(detached_source_index, captured.constraint_index);
    try std.testing.expectEqual(receiver, captured.structural_origin.receiver_var);
    try std.testing.expectEqual(attached_callable, captured.structural_origin.constraint_fn_var);
    try std.testing.expect(second_captured.deferred_generated_codec);
    try std.testing.expectEqual(second_detached_source_index, second_captured.constraint_index);
    try std.testing.expectEqual(receiver, second_captured.structural_origin.receiver_var);
    try std.testing.expectEqual(attached_callable, second_captured.structural_origin.constraint_fn_var);

    // Real binding generalization publishes this classification after
    // requirement capture. A TypeScheme side table alone is not binding-scheme
    // authority: value-restricted side tables deliberately retain the ordinary
    // copy policy. Mirror the exact producer before exercising the scheme use.
    try checker.publishBindingScheme(scheme_root);
    try std.testing.expect(checker.isBindingSchemeVar(scheme_root));

    // Registration and capture above are the typed local-integration boundary.
    // The copy below exercises the real instantiator, detached registrar,
    // translation, and durable proof validator; it is not a parsed checked-file
    // admission or a source-level generated-codec producer test.
    checker.active_scheme_root = null;
    const copied = try checker.instantiateVarWithMarkerCopy(
        scheme_root,
        &env,
        .{ .explicit = Region.zero() },
        .{ .type_annotation = .{ .node = 0 } },
        .eager_support,
    );
    const step_index = copied.copy_step orelse return error.TestUnexpectedResult;
    const step = checker.cir.where_marker_copy_steps.items.items[step_index];
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerCopyStep.CopyPolicy.ranked_fresh_flex_close_scheme,
        step.decodedCopyPolicy().?,
    );
    try std.testing.expectEqual(@as(u32, 3), step.constraint_pairs_len);
    const constraint_pairs = checker.cir.where_marker_constraint_copy_pairs.items.items[step.constraint_pairs_start..][0..step.constraint_pairs_len];
    try std.testing.expectEqual(attached_source_index, constraint_pairs[0].source_constraint_index);
    try std.testing.expectEqual(detached_source_index, constraint_pairs[1].source_constraint_index);
    try std.testing.expectEqual(second_detached_source_index, constraint_pairs[2].source_constraint_index);
    try std.testing.expect(
        constraint_pairs[0].destination_constraint_index != attached_source_index and
            constraint_pairs[1].destination_constraint_index != detached_source_index and
            constraint_pairs[2].destination_constraint_index != second_detached_source_index,
    );

    const occurrences = checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
    const witnesses = checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len];
    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
        occurrences,
        witnesses,
        step.root_occurrence_offset,
    );
    const ExpectedIngress = struct {
        edge_kind: ModuleEnv.WhereMarkerCopyWitness.EdgeKind,
        edge_index: u32,
        raw_source: u32,
    };
    const expected_ingresses = [_]ExpectedIngress{
        .{ .edge_kind = .scheme_requirement_receiver, .edge_index = 0, .raw_source = @intFromEnum(receiver) },
        .{ .edge_kind = .scheme_requirement_function, .edge_index = 0, .raw_source = @intFromEnum(detached_callable) },
        .{ .edge_kind = .interpolation_part, .edge_index = 0, .raw_source = @intFromEnum(interpolation_part) },
        .{ .edge_kind = .interpolation_item, .edge_index = 0, .raw_source = @intFromEnum(interpolation_item) },
        .{ .edge_kind = .scheme_requirement_function, .edge_index = 1, .raw_source = @intFromEnum(second_detached_callable) },
    };
    var combined_receiver_absolute: ?u32 = null;
    var combined_interpolation_absolute: ?u32 = null;
    var memoized_receiver_absolute: ?u32 = null;
    for (expected_ingresses) |expected| {
        var matches: usize = 0;
        for (witnesses, 0..) |witness, witness_offset| {
            if (witness.decodedEdgeKind() != expected.edge_kind or
                witness.edge_index != expected.edge_index or
                witness.decodedAction() != .requirement_component_fresh_flex_copy)
            {
                continue;
            }
            matches += 1;
            try std.testing.expectEqual(step.root_occurrence_offset, witness.parent_occurrence_offset);
            try std.testing.expectEqual(expected.raw_source, witness.raw_source_var);
            const occurrence = occurrences[witness.child_occurrence_offset];
            try std.testing.expectEqual(occurrence.raw_source_var, witness.raw_source_var);
            try std.testing.expectEqual(occurrence.raw_destination_var, witness.raw_destination_var);
            try std.testing.expect(witness.raw_source_var != witness.raw_destination_var);
            try std.testing.expectEqual(
                ModuleEnv.WhereMarkerCopyWitness.AuxiliaryOriginKind.none,
                witness.decodedAuxiliaryOriginKind().?,
            );
            try std.testing.expectEqual(@as(u32, 0), witness.auxiliary_origin_step);
            try std.testing.expectEqual(@as(u32, 0), witness.auxiliary_origin_index);
            if (expected.edge_kind == .scheme_requirement_receiver) {
                combined_receiver_absolute = step.witnesses_start + @as(u32, @intCast(witness_offset));
                const destination = checker.types.resolveVar(@enumFromInt(witness.raw_destination_var));
                try std.testing.expect(destination.desc.content == .flex);
                try std.testing.expectEqual(@as(usize, 1), destination.desc.content.flex.constraints.len());
            }
            if (expected.edge_kind == .scheme_requirement_function) {
                try std.testing.expect(
                    checker.types.resolveVar(@enumFromInt(witness.raw_source_var)).desc.content == .rigid,
                );
                try std.testing.expect(
                    checker.types.resolveVar(@enumFromInt(witness.raw_destination_var)).desc.content == .flex,
                );
            }
            if (expected.edge_kind == .interpolation_part) {
                combined_interpolation_absolute = step.witnesses_start +
                    @as(u32, @intCast(witness_offset));
            }
        }
        try std.testing.expectEqual(@as(usize, 1), matches);
    }
    for (witnesses, 0..) |witness, witness_offset| {
        if (witness.decodedEdgeKind() != .scheme_requirement_receiver or witness.edge_index != 1) continue;
        if (memoized_receiver_absolute != null) return error.TestUnexpectedResult;
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_ingress,
            witness.decodedAction().?,
        );
        try std.testing.expectEqual(std.math.maxInt(u32), witness.raw_source_var);
        try std.testing.expectEqual(std.math.maxInt(u32), witness.raw_destination_var);
        memoized_receiver_absolute = step.witnesses_start + @as(u32, @intCast(witness_offset));
    }

    var root_action_count: usize = 0;
    for (witnesses) |witness| {
        if (witness.decodedEdgeKind() != .root_copy_action) continue;
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyWitness.Action.flex_fresh_flex_copy,
            witness.decodedAction().?,
        );
        root_action_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), root_action_count);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    for (checker.cir.dispatch_settlement_sources.items.items, 0..) |settlement_source, source_index| {
        if (settlement_source.decodedKind() != .copied_constraint) continue;
        try std.testing.expect(validateDispatchSettlementSourceContext(
            checker.cir,
            @intCast(source_index),
        ));
    }

    const receiver_absolute = combined_receiver_absolute orelse return error.TestUnexpectedResult;
    const memoized_receiver_index = memoized_receiver_absolute orelse return error.TestUnexpectedResult;
    const original_receiver = checker.cir.where_marker_copy_witnesses.items.items[receiver_absolute];
    var receiver_witness = &checker.cir.where_marker_copy_witnesses.items.items[receiver_absolute];
    receiver_witness.action = @intFromEnum(ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_ingress);
    const accepted_hidden_creation = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    receiver_witness.* = original_receiver;
    try std.testing.expect(!accepted_hidden_creation);

    receiver_witness.edge_kind = @intFromEnum(ModuleEnv.WhereMarkerCopyWitness.EdgeKind.tuple_element);
    const accepted_structural_combined = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    receiver_witness.* = original_receiver;
    try std.testing.expect(!accepted_structural_combined);

    receiver_witness.raw_source_var = std.math.maxInt(u32);
    const accepted_missing_raw_source = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    receiver_witness.* = original_receiver;
    try std.testing.expect(!accepted_missing_raw_source);

    receiver_witness.raw_destination_var = receiver_witness.raw_source_var;
    const accepted_equal_endpoints = validateWhereMarkerCopyProofLocal(checker.types, checker.cir);
    receiver_witness.* = original_receiver;
    try std.testing.expect(!accepted_equal_endpoints);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const interpolation_index = combined_interpolation_absolute orelse
        return error.TestUnexpectedResult;
    const interpolation_before = checker.cir.where_marker_copy_witnesses.items.items[
        interpolation_index
    ];
    var interpolation_witness = &checker.cir.where_marker_copy_witnesses.items.items[
        interpolation_index
    ];
    interpolation_witness.action = @intFromEnum(
        ModuleEnv.WhereMarkerCopyWitness.Action.flex_fresh_flex_copy,
    );
    const accepted_structural_virtual_interpolation = validateWhereMarkerCopyProofLocal(
        checker.types,
        checker.cir,
    );
    interpolation_witness.* = interpolation_before;
    try std.testing.expect(!accepted_structural_virtual_interpolation);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const memoized_receiver_before = checker.cir.where_marker_copy_witnesses.items.items[
        memoized_receiver_index
    ];
    try std.testing.expectEqual(
        original_receiver.child_occurrence_offset,
        memoized_receiver_before.child_occurrence_offset,
    );
    const memoized_child = occurrences[memoized_receiver_before.child_occurrence_offset];
    var memoized_receiver = &checker.cir.where_marker_copy_witnesses.items.items[
        memoized_receiver_index
    ];
    memoized_receiver.action = @intFromEnum(
        ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_fresh_flex_copy,
    );
    memoized_receiver.raw_source_var = memoized_child.raw_source_var;
    memoized_receiver.raw_destination_var = memoized_child.raw_destination_var;
    const accepted_duplicate_virtual_allocation = validateWhereMarkerCopyProofLocal(
        checker.types,
        checker.cir,
    );
    memoized_receiver.* = memoized_receiver_before;
    try std.testing.expect(!accepted_duplicate_virtual_allocation);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    try checker.rebuildCheckedBoundaryWhereMethodState();
    const canonical_once = try serializeModuleEnvForCanonicalComparison(std.testing.allocator, checker.cir);
    defer std.testing.allocator.free(canonical_once);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const canonical_twice = try serializeModuleEnvForCanonicalComparison(std.testing.allocator, checker.cir);
    defer std.testing.allocator.free(canonical_twice);
    try std.testing.expectEqualSlices(u8, canonical_once, canonical_twice);

    const buffer = try serializeModuleEnvForDeserializationTest(std.testing.allocator, checker.cir);
    defer std.testing.allocator.free(buffer);
    try std.testing.expectEqualSlices(u8, canonical_twice, buffer);
    const base_addr = @intFromPtr(buffer.ptr);
    const serialized: *const ModuleEnv.Serialized = @ptrCast(@alignCast(buffer.ptr));
    try serialized.validate(buffer.len);

    const readonly = try serialized.deserializeInto(
        base_addr,
        std.testing.allocator,
        source,
        "VirtualRequirementFreshFlexCopy",
    );
    defer {
        readonly.imports.deinitMapOnly(std.testing.allocator);
        readonly.import_mapping.deinit();
        std.testing.allocator.destroy(readonly);
    }
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&readonly.types, readonly));
    var readonly_combined_count: usize = 0;
    for (readonly.where_marker_copy_witnesses.items.items) |witness| {
        readonly_combined_count += @intFromBool(
            witness.decodedAction() == .requirement_component_fresh_flex_copy,
        );
    }
    try std.testing.expectEqual(@as(usize, 5), readonly_combined_count);
    const readonly_bytes = try serializeModuleEnvForCanonicalComparison(std.testing.allocator, readonly);
    defer std.testing.allocator.free(readonly_bytes);
    try std.testing.expectEqualSlices(u8, canonical_twice, readonly_bytes);

    const mutable = try serialized.deserializeWithMutableTypes(
        base_addr,
        std.testing.allocator,
        source,
        "VirtualRequirementFreshFlexCopy",
    );
    defer {
        mutable.deinitCachedModule();
        std.testing.allocator.destroy(mutable);
    }
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&mutable.types, mutable));
    var mutable_combined_count: usize = 0;
    for (mutable.where_marker_copy_witnesses.items.items) |witness| {
        mutable_combined_count += @intFromBool(
            witness.decodedAction() == .requirement_component_fresh_flex_copy,
        );
    }
    try std.testing.expectEqual(@as(usize, 5), mutable_combined_count);
    const mutable_bytes = try serializeModuleEnvForCanonicalComparison(std.testing.allocator, mutable);
    defer std.testing.allocator.free(mutable_bytes);
    try std.testing.expectEqualSlices(u8, canonical_twice, mutable_bytes);
}

const record_update_root_authority_test_source =
    \\redirected = |container, first_value, second_value| (
    \\    { ..container, data: first_value },
    \\    { ..container, data: second_value },
    \\)
    \\
    \\direct = |first_value, second_value| {
    \\    ..{ data: first_value },
    \\    data: second_value,
    \\}
;

const aggregate_expected_projection_inverse_test_source =
    \\main : { outer : { value : U8 } }
    \\main = { outer: { value: 1.U8 } }
;

const record_update_projection_inverse_test_source =
    \\direct = |first_value, second_value| {
    \\    ..{ data: first_value },
    \\    data: second_value,
    \\}
    \\
    \\first_support = |container, value| { ..container, data: value }
    \\second_support = |container, value| { ..container, data: value }
;

fn recordUpdateProjectionInverseRecord(
    test_env: anytype,
    def_name: []const u8,
    base_kind: enum { literal, lookup },
) !CIR.Expr.Idx {
    const cir = test_env.module_env;
    const def_idx = test_env.can.explicitRootDefByName(def_name) orelse
        return error.TestUnexpectedResult;
    const def = cir.store.getDef(def_idx);
    const lambda = cir.store.getExpr(def.expr);
    if (lambda != .e_lambda) return error.TestUnexpectedResult;
    const record_expr = lambda.e_lambda.body;
    const record = cir.store.getExpr(record_expr);
    if (record != .e_record or record.e_record.ext == null or
        cir.store.sliceRecordFields(record.e_record.fields).len != 1 or
        cir.store.sliceUnsetFields(record.e_record.unsets).len != 0)
    {
        return error.TestUnexpectedResult;
    }
    const base_expr = record.e_record.ext.?;
    switch (base_kind) {
        .literal => {
            const base_record = cir.store.getExpr(base_expr);
            if (base_record != .e_record or base_record.e_record.ext != null) {
                return error.TestUnexpectedResult;
            }
        },
        .lookup => {
            const patterns = cir.store.slicePatterns(lambda.e_lambda.args);
            if (patterns.len != 2) return error.TestUnexpectedResult;
            const base_lookup = cir.store.getExpr(base_expr);
            if (base_lookup != .e_lookup_local or
                base_lookup.e_lookup_local.pattern_idx != patterns[0])
            {
                return error.TestUnexpectedResult;
            }
        },
    }
    return record_expr;
}

const RecordUpdateRootAuthorityTestTopology = struct {
    redirected_lambda: CIR.Expr.Idx,
    redirected_container_pattern: CIR.Pattern.Idx,
    redirected_records: [2]CIR.Expr.Idx,
    redirected_bases: [2]CIR.Expr.Idx,
    direct_record: CIR.Expr.Idx,
    direct_base: CIR.Expr.Idx,
};

fn recordUpdateRootAuthorityTestTopology(test_env: anytype) !RecordUpdateRootAuthorityTestTopology {
    const cir = test_env.module_env;
    const redirected_def_idx = test_env.can.explicitRootDefByName("redirected") orelse
        return error.TestUnexpectedResult;
    const redirected_def = cir.store.getDef(redirected_def_idx);
    const redirected_lambda = cir.store.getExpr(redirected_def.expr);
    if (redirected_lambda != .e_lambda) return error.TestUnexpectedResult;
    const redirected_patterns = cir.store.slicePatterns(redirected_lambda.e_lambda.args);
    if (redirected_patterns.len != 3) return error.TestUnexpectedResult;
    const redirected_body = cir.store.getExpr(redirected_lambda.e_lambda.body);
    if (redirected_body != .e_tuple) return error.TestUnexpectedResult;
    const redirected_records = cir.store.sliceExpr(redirected_body.e_tuple.elems);
    if (redirected_records.len != 2) return error.TestUnexpectedResult;

    var record_exprs: [2]CIR.Expr.Idx = undefined;
    var base_exprs: [2]CIR.Expr.Idx = undefined;
    for (redirected_records, 0..) |record_expr, index| {
        const record = cir.store.getExpr(record_expr);
        if (record != .e_record or record.e_record.ext == null) {
            return error.TestUnexpectedResult;
        }
        const base_expr = record.e_record.ext.?;
        const base_expression = cir.store.getExpr(base_expr);
        if (base_expression != .e_lookup_local or
            base_expression.e_lookup_local.pattern_idx != redirected_patterns[0])
        {
            return error.TestUnexpectedResult;
        }
        record_exprs[index] = record_expr;
        base_exprs[index] = base_expr;
    }
    if (base_exprs[0] == base_exprs[1]) return error.TestUnexpectedResult;

    const direct_def_idx = test_env.can.explicitRootDefByName("direct") orelse
        return error.TestUnexpectedResult;
    const direct_def = cir.store.getDef(direct_def_idx);
    const direct_lambda = cir.store.getExpr(direct_def.expr);
    if (direct_lambda != .e_lambda) return error.TestUnexpectedResult;
    const direct_record_expr = direct_lambda.e_lambda.body;
    const direct_record = cir.store.getExpr(direct_record_expr);
    if (direct_record != .e_record or direct_record.e_record.ext == null) {
        return error.TestUnexpectedResult;
    }
    const direct_base_expr = direct_record.e_record.ext.?;
    const direct_base = cir.store.getExpr(direct_base_expr);
    if (direct_base != .e_record or direct_base.e_record.ext != null) {
        return error.TestUnexpectedResult;
    }

    return .{
        .redirected_lambda = redirected_def.expr,
        .redirected_container_pattern = redirected_patterns[0],
        .redirected_records = record_exprs,
        .redirected_bases = base_exprs,
        .direct_record = direct_record_expr,
        .direct_base = direct_base_expr,
    };
}

const RecordUpdateRootAuthorityTestProof = struct {
    step_index: u32,
    record_expr: CIR.Expr.Idx,
    base_expr: CIR.Expr.Idx,
    fields_ext_index: u32,
    root_occurrence_index: u32,
    root_witness_index: u32,
    field_plan_index: u32,
    selected_raw_root: u32,
    selected_canonical_root: u32,
};

fn expectRecordUpdateRootAuthorityTestProof(
    cir: *const ModuleEnv,
    record_expr: CIR.Expr.Idx,
    expected_binding: ModuleEnv.WhereMarkerRecordUpdateBaseOrigin.RootBinding,
) !RecordUpdateRootAuthorityTestProof {
    const raw_record: u32 = @intFromEnum(record_expr);
    var failure_stage: []const u8 = "record payload";
    var diagnostic_plan: u32 = ModuleEnv.ExpectedConsumptionPlan.none;
    var diagnostic_parent_step: u32 = ModuleEnv.ExpectedConsumptionPlan.none;
    var diagnostic_produced_step: u32 = ModuleEnv.ExpectedConsumptionPlan.none;
    errdefer std.debug.print(
        "record-update authority proof failed for record {d} ({s}) at {s}; plan={d} parent_step={d} produced_step={d}\n",
        .{
            raw_record,
            @tagName(expected_binding),
            failure_stage,
            diagnostic_plan,
            diagnostic_parent_step,
            diagnostic_produced_step,
        },
    );
    const record_node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(record_expr));
    if (record_node.tag != .expr_record) return error.TestUnexpectedResult;
    const fields_ext_index = record_node.getPayload().expr_record.fields_ext_idx;
    if (fields_ext_index >= cir.store.span_with_node_data.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const record = cir.store.getExpr(record_expr);
    if (record != .e_record or record.e_record.ext == null) return error.TestUnexpectedResult;
    const base_expr = record.e_record.ext.?;

    failure_stage = "record-update base step";
    var matching_step_index: ?u32 = null;
    for (cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.decodedKind() != .record_update_base or
            step.origin.record_update_base.record_expr != raw_record)
        {
            continue;
        }
        if (matching_step_index != null) return error.TestUnexpectedResult;
        matching_step_index = @intCast(step_index);
    }
    const step_index = matching_step_index orelse return error.TestUnexpectedResult;
    const step = cir.where_marker_copy_steps.items.items[step_index];
    const origin = step.origin.record_update_base;
    try std.testing.expectEqual(@intFromEnum(base_expr), origin.base_expr);
    try std.testing.expectEqual(expected_binding, origin.decodedRootBinding().?);
    try std.testing.expectEqual(@as(u32, 0), origin.reserved_1);
    try std.testing.expectEqual(@as(u32, 0), origin.reserved_2);
    try std.testing.expectEqual(@as(u32, 0), origin.reserved_3);
    if (!rangeFits(step.pairs_start, step.pairs_len, cir.where_marker_copy_pairs.items.items.len) or
        !rangeFits(
            step.occurrences_start,
            step.occurrences_len,
            cir.where_marker_copy_occurrences.items.items.len,
        ) or !rangeFits(
        step.witnesses_start,
        step.witnesses_len,
        cir.where_marker_copy_witnesses.items.items.len,
    ) or step.root_occurrence_offset >= step.occurrences_len) {
        return error.TestUnexpectedResult;
    }
    failure_stage = "base root occurrence";
    const pairs = cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len];
    const occurrences = cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
    const witnesses = cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len];
    const root_occurrence = occurrences[step.root_occurrence_offset];
    if (root_occurrence.canonical_pair_offset >= pairs.len) return error.TestUnexpectedResult;
    const root_pair = pairs[root_occurrence.canonical_pair_offset];
    try std.testing.expectEqual(step.source_root_var, root_pair.source_var);
    try std.testing.expectEqual(step.destination_root_var, root_pair.destination_var);
    try std.testing.expectEqual(@as(u32, 0), root_pair.discovery_depth);
    try std.testing.expectEqual(std.math.maxInt(u32), root_pair.predecessor_pair_offset);
    try std.testing.expectEqual(std.math.maxInt(u32), root_pair.predecessor_edge_ordinal);

    failure_stage = "root binding";
    switch (expected_binding) {
        .direct_request => {
            try std.testing.expectEqual(origin.base_expr, root_occurrence.raw_source_var);
        },
        .redirected_identity_share => {
            try std.testing.expect(origin.base_expr != root_occurrence.raw_source_var);
            try std.testing.expectEqual(
                root_occurrence.raw_source_var,
                root_occurrence.raw_destination_var,
            );
            try std.testing.expectEqual(root_pair.source_var, root_pair.destination_var);
            try std.testing.expectEqual(
                cir.types.resolveVar(@enumFromInt(origin.base_expr)).var_,
                @as(Var, @enumFromInt(root_pair.source_var)),
            );
        },
    }

    failure_stage = "root witness";
    var root_witness_offset: ?u32 = null;
    for (witnesses, 0..) |witness, witness_offset| {
        if (witness.decodedEdgeKind() != .root_copy_action) continue;
        if (root_witness_offset != null) return error.TestUnexpectedResult;
        root_witness_offset = @intCast(witness_offset);
        try std.testing.expectEqual(step.root_occurrence_offset, witness.parent_occurrence_offset);
        try std.testing.expectEqual(step.root_occurrence_offset, witness.child_occurrence_offset);
        try std.testing.expectEqual(std.math.maxInt(u32), witness.constraint_pair_offset);
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyWitness.Action.local_raw_identity_share_cut,
            witness.decodedAction().?,
        );
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyWitness.AuxiliaryOriginKind.none,
            witness.decodedAuxiliaryOriginKind().?,
        );
        try std.testing.expectEqual(@as(u32, 0), witness.auxiliary_origin_step);
        try std.testing.expectEqual(@as(u32, 0), witness.auxiliary_origin_index);
        try std.testing.expectEqual(root_occurrence.raw_source_var, witness.raw_source_var);
        try std.testing.expectEqual(root_occurrence.raw_destination_var, witness.raw_destination_var);
    }
    const root_witness = root_witness_offset orelse return error.TestUnexpectedResult;

    failure_stage = "record field plan";
    const fields = cir.store.sliceRecordFields(record.e_record.fields);
    if (fields.len != 1) return error.TestUnexpectedResult;
    const field = cir.store.getRecordField(fields[0]);
    var matching_plan_index: ?u32 = null;
    for (cir.expected_consumption_plans.items.items, 0..) |plan, plan_index| {
        if (plan.decodedRole() != .record_update_field or plan.owner_node != raw_record) continue;
        if (matching_plan_index != null) return error.TestUnexpectedResult;
        try std.testing.expect(plan.hasLegalTags());
        try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Outcome.anchored, plan.decodedOutcome().?);
        try std.testing.expectEqual(@intFromEnum(field.value), plan.site_node);
        try std.testing.expectEqual(@as(u32, 0), plan.slot);
        try std.testing.expectEqual(
            ModuleEnv.ExpectedMarkerAuthority.Kind.copy_occurrence,
            plan.parent_authority.decodedKind().?,
        );
        matching_plan_index = @intCast(plan_index);
    }
    const field_plan_index = matching_plan_index orelse return error.TestUnexpectedResult;
    diagnostic_plan = field_plan_index;
    const plan = cir.expected_consumption_plans.items.items[field_plan_index];
    diagnostic_parent_step = plan.parent_authority.payload.copy_occurrence.copy_step;
    diagnostic_produced_step = plan.produced_copy_step;
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerCopyOccurrenceSide.destination,
        plan.decodedProducedSide().?,
    );

    const base_authority: ModuleEnv.ExpectedMarkerAuthority = .{
        .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.copy_occurrence),
        .payload = .{ .copy_occurrence = .{
            .copy_step = step_index,
            .occurrence_offset = step.root_occurrence_offset,
            .side = @intFromEnum(ModuleEnv.WhereMarkerCopyOccurrenceSide.destination),
        } },
    };
    const plan_parent = plan.parent_authority.payload.copy_occurrence;
    const parent_is_base = expectedMarkerAuthoritiesEqual(plan.parent_authority, base_authority);
    const projection_step_index = if (parent_is_base)
        plan.produced_copy_step
    else
        plan_parent.copy_step;
    failure_stage = "expected projection step";
    try std.testing.expect(projection_step_index > step_index);
    if (projection_step_index >= cir.where_marker_copy_steps.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const projection_step = cir.where_marker_copy_steps.items.items[projection_step_index];
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerCopyStep.Kind.aggregate_expected_projection,
        projection_step.decodedKind().?,
    );
    const projection_origin = projection_step.origin.aggregate_expected_projection;
    try std.testing.expectEqual(raw_record, projection_origin.consumer_node);
    try std.testing.expectEqual(field_plan_index, projection_origin.expected_plan_index);
    try std.testing.expect(expectedMarkerAuthoritiesEqual(
        base_authority,
        projection_origin.parent_authority,
    ));
    if (!rangeFits(
        projection_step.occurrences_start,
        projection_step.occurrences_len,
        cir.where_marker_copy_occurrences.items.items.len,
    ) or projection_step.root_occurrence_offset >= projection_step.occurrences_len) {
        return error.TestUnexpectedResult;
    }
    const projection_root_occurrence = cir.where_marker_copy_occurrences.items.items[
        projection_step.occurrences_start + projection_step.root_occurrence_offset
    ];
    try std.testing.expectEqual(
        root_occurrence.raw_destination_var,
        projection_root_occurrence.raw_source_var,
    );
    const projection_root_authority: ModuleEnv.ExpectedMarkerAuthority = .{
        .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.copy_occurrence),
        .payload = .{ .copy_occurrence = .{
            .copy_step = projection_step_index,
            .occurrence_offset = projection_step.root_occurrence_offset,
            .side = @intFromEnum(ModuleEnv.WhereMarkerCopyOccurrenceSide.destination),
        } },
    };

    if (parent_is_base) {
        failure_stage = "projected field occurrence";
        try std.testing.expectEqual(projection_step_index, plan.produced_copy_step);
        try std.testing.expect(plan.produced_occurrence_offset < projection_step.occurrences_len);

        const projection_witnesses = cir.where_marker_copy_witnesses.items.items[projection_step.witnesses_start..][0..projection_step.witnesses_len];
        var field_edge_count: usize = 0;
        for (projection_witnesses) |witness| {
            const edge_kind = witness.decodedEdgeKind() orelse return error.TestUnexpectedResult;
            if (witness.parent_occurrence_offset == projection_step.root_occurrence_offset and
                witness.child_occurrence_offset == plan.produced_occurrence_offset and
                (edge_kind == .record_field_type or edge_kind == .record_unbound_field_type) and
                witness.edge_index == 0 and witness.edge_name == @as(u32, @bitCast(field.name)))
            {
                field_edge_count += 1;
            }
        }
        try std.testing.expectEqual(@as(usize, 1), field_edge_count);
    } else {
        failure_stage = "fresh-shape support step";
        try std.testing.expect(expectedMarkerAuthoritiesEqual(
            projection_root_authority,
            plan.parent_authority,
        ));
        try std.testing.expect(plan.produced_copy_step > projection_step_index);
        if (plan.produced_copy_step >= cir.where_marker_copy_steps.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const support_step = cir.where_marker_copy_steps.items.items[plan.produced_copy_step];
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyStep.Kind.aggregate_fresh_shape_child,
            support_step.decodedKind().?,
        );
        const support_origin = support_step.origin.aggregate_fresh_shape_child;
        try std.testing.expectEqual(field_plan_index, support_origin.expected_plans_start);
        try std.testing.expectEqual(@as(u32, 1), support_origin.expected_plans_len);
        try std.testing.expect(expectedMarkerAuthoritiesEqual(
            projection_root_authority,
            support_origin.parent_authority,
        ));
        try std.testing.expectEqual(support_step.root_occurrence_offset, plan.produced_occurrence_offset);
        if (!rangeFits(
            support_step.occurrences_start,
            support_step.occurrences_len,
            cir.where_marker_copy_occurrences.items.items.len,
        ) or support_step.root_occurrence_offset >= support_step.occurrences_len) {
            return error.TestUnexpectedResult;
        }
        const support_root_occurrence = cir.where_marker_copy_occurrences.items.items[
            support_step.occurrences_start + support_step.root_occurrence_offset
        ];
        try std.testing.expectEqual(plan.raw_consumer_var, support_root_occurrence.raw_source_var);
    }

    return .{
        .step_index = step_index,
        .record_expr = record_expr,
        .base_expr = base_expr,
        .fields_ext_index = fields_ext_index,
        .root_occurrence_index = step.occurrences_start + step.root_occurrence_offset,
        .root_witness_index = step.witnesses_start + root_witness,
        .field_plan_index = field_plan_index,
        .selected_raw_root = root_occurrence.raw_source_var,
        .selected_canonical_root = root_pair.source_var,
    };
}

fn recordUpdateRootAuthorityFreshContext(test_env: anytype) ImportResolution {
    return ImportResolution.freshSupplied(
        test_env.module_env,
        .{
            .envs = test_env.checker.imported_modules,
            .modules = test_env.checker.validated_imported_modules,
        },
        .{
            .envs = test_env.checker.owner_modules,
            .modules = test_env.checker.validated_owner_modules,
        },
        test_env.checker.platform_dependency_index,
    );
}

const record_update_direct_binder_owner_retirement_source =
    \\import RecordUpdateLiveOwnerA exposing [Status]
    \\
    \\first : a -> a where [a.Status]
    \\first = |value| { ..value, x: 1.U8 }
;

const record_update_preexisting_malformed_base_source =
    \\main = { ..(1..<5..<10), x: 1.U8 }
;

const record_update_projection_empty_base_source =
    \\test = {
    \\    r = {}
    \\    { ..r, hello: 10.U8 }
    \\}
;

const record_update_projection_typo_base_source =
    \\test = {
    \\    r = { hello: "world" }
    \\    { ..r, hllo: "goodbye" }
    \\}
;

