fn recordUpdateProjectionRelationPhase(
    checker: *const Self,
    base_raw_var: Var,
    selected_source: Var,
) RecordUpdateProjectionRelationPhase {
    return .{
        .base_content = std.meta.activeTag(checker.types.resolveVar(base_raw_var).desc.content),
        .selected_source_content = std.meta.activeTag(
            checker.types.resolveVar(selected_source).desc.content,
        ),
        .base_shares_selected_source = recordUpdateProjectionVarsShare(
            checker,
            base_raw_var,
            selected_source,
        ),
    };
}

fn recordUpdateProjectionVarIsBuiltinU8(checker: *const Self, var_: Var) bool {
    const content = checker.types.resolveVar(var_).desc.content;
    const nominal = content.unwrapNominalType() orelse return false;
    if (!nominal.originIsBuiltin() or
        nominal.origin_module != checker.builtinOriginModule() or
        nominal.args.len() != 0 or
        !nominal.isOpaque())
    {
        return false;
    }
    const num_kind = checker.builtinNumKindFromNominalType(nominal) orelse return false;
    return num_kind == .u8;
}

fn recordUpdateProjectionBaseHasPendingHelloU8(
    checker: *const Self,
    base_var: Var,
    field_name: Ident.Idx,
) bool {
    const content = checker.types.resolveVar(base_var).desc.content;
    if (content != .structure or content.structure != .record) return false;
    const record = content.structure.record;
    const fields = checker.types.getRecordFieldsSlice(record.fields);
    if (fields.len != 1 or fields.items(.name)[0] != field_name) return false;
    const field_var = switch (fields.items(.presence)[0].decode()) {
        .required => return false,
        .unknown => |unknown| pending: {
            if (checker.types.resolveVar(unknown.presence).desc.content != .flex) return false;
            break :pending unknown.var_;
        },
    };
    const ext = checker.types.resolveVar(record.ext).desc.content;
    return ext == .structure and ext.structure == .empty_record and
        recordUpdateProjectionVarIsBuiltinU8(checker, field_var);
}

fn recordUpdateProjectionCheckedErrorBaseFieldObservation(
    checker: *const Self,
    base_var: Var,
    field_name: Ident.Idx,
) RecordUpdateProjectionCheckedErrorBaseFieldObservation {
    const content = checker.types.resolveVar(base_var).desc.content;
    if (content != .structure or content.structure != .record) return .{
        .record_field_count = null,
        .field_name_matches = false,
        .presence = null,
        .payload_content = null,
        .payload_is_builtin_u8 = false,
        .extension_content = null,
        .extension_is_empty_record = false,
    };
    const record = content.structure.record;
    const fields = checker.types.getRecordFieldsSlice(record.fields);
    const ext_content = std.meta.activeTag(checker.types.resolveVar(record.ext).desc.content);
    if (fields.len != 1 or fields.items(.name)[0] != field_name) return .{
        .record_field_count = fields.len,
        .field_name_matches = false,
        .presence = null,
        .payload_content = null,
        .payload_is_builtin_u8 = false,
        .extension_content = ext_content,
        .extension_is_empty_record = false,
    };
    const decoded = fields.items(.presence)[0].decode();
    const payload_var: Var, const presence: RecordUpdateProjectionCheckedErrorFieldPresence = switch (decoded) {
        .required => |required| .{ required, .required },
        .unknown => |unknown| presence: {
            const presence_content = checker.types.resolveVar(unknown.presence).desc.content;
            const observed_presence: RecordUpdateProjectionCheckedErrorFieldPresence = switch (presence_content) {
                .flex => .kind_flex,
                .field_presence => |field_presence| switch (field_presence) {
                    .required => .kind_required,
                    .optional => .kind_optional,
                    .defaulted => .kind_defaulted,
                },
                else => .kind_other,
            };
            break :presence .{ unknown.var_, observed_presence };
        },
    };
    return .{
        .record_field_count = fields.len,
        .field_name_matches = true,
        .presence = presence,
        .payload_content = std.meta.activeTag(checker.types.resolveVar(payload_var).desc.content),
        .payload_is_builtin_u8 = recordUpdateProjectionVarIsBuiltinU8(checker, payload_var),
        .extension_content = ext_content,
        .extension_is_empty_record = blk: {
            const ext = checker.types.resolveVar(record.ext).desc.content;
            break :blk ext == .structure and ext.structure == .empty_record;
        },
    };
}

fn recordUpdateProjectionAnchoredFieldCopyProof(
    checker: *const Self,
    topology: RecordUpdateProjectionRelationTopology,
    plan_index: u32,
    base_authority: ModuleEnv.ExpectedMarkerAuthority,
    projected: Expected.ExpectedType,
) !RecordUpdateProjectionAnchoredFieldCopyProof {
    const cir = checker.cir;
    if (plan_index >= cir.expected_consumption_plans.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const plan = cir.expected_consumption_plans.items.items[plan_index];
    if (!plan.hasLegalTags() or
        plan.decodedRole() != .record_update_field or
        plan.decodedOutcome() != .anchored or
        plan.decodedReason() != null or
        plan.owner_node != @intFromEnum(topology.record_expr) or
        plan.site_node != @intFromEnum(topology.field_expr) or
        plan.slot != 0 or
        !expectedMarkerAuthoritiesEqual(plan.parent_authority, base_authority) or
        plan.produced_copy_step >= cir.where_marker_copy_steps.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const anchor = switch (projected.marker_authority) {
        .anchored => |authority| authority.copy_occurrence,
        .evidence_free => return error.TestUnexpectedResult,
    };
    if (anchor.copy_step != plan.produced_copy_step or
        anchor.occurrence_offset != plan.produced_occurrence_offset or
        anchor.side != plan.decodedProducedSide().? or
        anchor.side != .destination or
        checker.expectedMarkerAnchorRawVar(anchor) != projected.var_)
    {
        return error.TestUnexpectedResult;
    }

    const step_index = plan.produced_copy_step;
    const step = cir.where_marker_copy_steps.items.items[step_index];
    if (step.decodedKind() != .aggregate_expected_projection or
        step.origin.aggregate_expected_projection.consumer_node != @intFromEnum(topology.record_expr) or
        step.origin.aggregate_expected_projection.expected_plan_index != plan_index or
        !expectedMarkerAuthoritiesEqual(
            step.origin.aggregate_expected_projection.parent_authority,
            base_authority,
        ) or
        !rangeFits(
            step.occurrences_start,
            step.occurrences_len,
            cir.where_marker_copy_occurrences.items.items.len,
        ) or
        !rangeFits(step.pairs_start, step.pairs_len, cir.where_marker_copy_pairs.items.items.len) or
        !rangeFits(
            step.witnesses_start,
            step.witnesses_len,
            cir.where_marker_copy_witnesses.items.items.len,
        ) or
        step.root_occurrence_offset >= step.occurrences_len or
        plan.produced_occurrence_offset >= step.occurrences_len)
    {
        return error.TestUnexpectedResult;
    }
    const root_occurrence_index = step.occurrences_start + step.root_occurrence_offset;
    const field_occurrence_index = step.occurrences_start + plan.produced_occurrence_offset;
    const root_occurrence = cir.where_marker_copy_occurrences.items.items[root_occurrence_index];
    const field_occurrence = cir.where_marker_copy_occurrences.items.items[field_occurrence_index];
    if (field_occurrence.raw_destination_var != @intFromEnum(projected.var_) or
        field_occurrence.canonical_pair_offset >= step.pairs_len)
    {
        return error.TestUnexpectedResult;
    }
    const field_pair_index = step.pairs_start + field_occurrence.canonical_pair_offset;
    const field_pair = cir.where_marker_copy_pairs.items.items[field_pair_index];
    var field_witness_index: ?u32 = null;
    for (
        cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len],
        0..,
    ) |witness, witness_offset| {
        if (witness.parent_occurrence_offset != step.root_occurrence_offset or
            witness.child_occurrence_offset != plan.produced_occurrence_offset or
            witness.decodedEdgeKind() != .record_field_type or
            witness.edge_index != 0 or
            witness.edge_name != @as(u32, @bitCast(topology.field_name)))
        {
            continue;
        }
        if (field_witness_index != null) return error.TestUnexpectedResult;
        field_witness_index = step.witnesses_start + @as(u32, @intCast(witness_offset));
    }
    const witness_index = field_witness_index orelse return error.TestUnexpectedResult;
    return .{
        .expected_var = projected.var_,
        .anchor = anchor,
        .step_index = step_index,
        .step = step,
        .root_occurrence_index = root_occurrence_index,
        .root_occurrence = root_occurrence,
        .field_occurrence_index = field_occurrence_index,
        .field_occurrence = field_occurrence,
        .field_pair_index = field_pair_index,
        .field_pair = field_pair,
        .field_witness_index = witness_index,
        .field_witness = cir.where_marker_copy_witnesses.items.items[witness_index],
    };
}

fn expectRecordUpdateProjectionBasePublication(
    checker: *const Self,
    env: *Env,
    stage: StagedRecordUpdateBasePlanPublication,
    result: PublishedRecordUpdateBasePlan,
) !StagedRecordUpdateBasePlanPublicationProof {
    const root_proof = try expectStagedRecordUpdateRootPublication(
        checker,
        env,
        stage.root,
        result.copy,
        false,
    );
    try std.testing.expectEqual(stage.expected_plans_start, result.plan_index);
    try std.testing.expectEqual(result.copy.copy_step.?, result.anchor.copy_step);
    try std.testing.expectEqual(@as(u32, 0), result.anchor.occurrence_offset);
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerCopyOccurrenceSide.destination,
        result.anchor.side,
    );
    try std.testing.expectEqual(
        @as(usize, stage.expected_plans_start + 1),
        checker.cir.expected_consumption_plans.items.items.len,
    );
    const plan = checker.cir.expected_consumption_plans.items.items[result.plan_index];
    try std.testing.expect(plan.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(stage.root.record_expr), plan.owner_node);
    try std.testing.expectEqual(@intFromEnum(stage.root.base_expr), plan.site_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Role.record_update_base,
        plan.decodedRole().?,
    );
    try std.testing.expectEqual(@as(u32, 0), plan.slot);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Outcome.source_root_copy,
        plan.decodedOutcome().?,
    );
    try std.testing.expect(plan.decodedReason() == null);
    try std.testing.expectEqual(@intFromEnum(stage.root.requested_var), plan.raw_consumer_var);
    try std.testing.expectEqual(ModuleEnv.ExpectedMarkerAuthority.none, plan.parent_authority.kind);
    try std.testing.expect(plan.parent_authority.hasCanonicalTags(false));
    try std.testing.expectEqual(result.anchor.copy_step, plan.produced_copy_step);
    try std.testing.expectEqual(result.anchor.occurrence_offset, plan.produced_occurrence_offset);
    try std.testing.expectEqual(result.anchor.side, plan.decodedProducedSide().?);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.none, plan.call_root_plan_index);
    try std.testing.expectEqual(ModuleEnv.CauseOwner.none, plan.failure_owner.kind);
    try std.testing.expect(plan.failure_owner.hasCanonicalTags(false));
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.none,
        plan.failure_cause_plan_index,
    );
    try std.testing.expect(plan.decodedSourceRetirementIndex() == null);
    try std.testing.expect(expectedRecordUpdateBasePlanMatchesStep(checker.cir, plan));

    try std.testing.expectEqual(
        stage.registrations_start + 1,
        checker.record_update_expected_plan_registrations.items.len,
    );
    const registration = checker.record_update_expected_plan_registrations.items[
        stage.registrations_start
    ];
    try std.testing.expectEqual(stage.root.record_expr, registration.owner_expr);
    try std.testing.expectEqual(result.plan_index, registration.plan_index);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Role.record_update_base,
        registration.role,
    );
    try std.testing.expectEqual(@as(u32, 0), registration.slot);
    try std.testing.expectEqual(stage.root.base_expr, registration.site);
    try std.testing.expectEqual(
        stage.owner_retirement_drafts_start,
        checker.record_update_owner_retirement_drafts.items.len,
    );
    try std.testing.expectEqual(
        stage.registrations_consumed,
        checker.record_update_expected_plan_registrations_consumed,
    );
    try std.testing.expect(!checker.record_update_expected_plan_registrations_consumed);

    return .{
        .root = root_proof,
        .plan = plan,
        .registration = registration,
    };
}

fn expectRecordUpdateMalformedSuppliedFieldPreRetirementCorruptions(
    cir: *ModuleEnv,
    topology: RecordUpdateProjectionRelationTopology,
    base_plan_index: u32,
) !void {
    const checked = topology.checked_error_field orelse return error.TestUnexpectedResult;
    const field_node: u32 = @intFromEnum(topology.field_expr);
    const plans = cir.expected_consumption_plans.items.items;
    if (base_plan_index >= plans.len) return error.TestUnexpectedResult;
    const base_plan = plans[base_plan_index];
    try std.testing.expect(recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
    try std.testing.expect(expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    try std.testing.expectEqual(@as(usize, 0), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 1), cir.malformed_expression_publications.items.items.len);
    const saved_publication = cir.malformed_expression_publications.items.items[0];
    try std.testing.expect(std.meta.eql(checked.malformed_publication, saved_publication));

    {
        const saved_len = cir.malformed_expression_publications.items.items.len;
        defer cir.malformed_expression_publications.items.items.len = saved_len;
        // The unchanged malformed node without typed expression publication
        // is indistinguishable from an unauthenticated checker rewrite here.
        cir.malformed_expression_publications.items.items.len = 0;
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }
    try std.testing.expect(std.meta.eql(
        saved_publication,
        cir.malformed_expression_publications.items.items[0],
    ));

    {
        const saved = cir.malformed_expression_publications.items.items[0];
        defer cir.malformed_expression_publications.items.items[0] = saved;
        cir.malformed_expression_publications.items.items[0].expr_node =
            @intFromEnum(checked.base_literal_expr);
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    {
        const saved = cir.malformed_expression_publications.items.items[0];
        defer cir.malformed_expression_publications.items.items[0] = saved;
        cir.malformed_expression_publications.items.items[0].diagnostic_index =
            @intCast(cir.store.nodes.len());
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    // Both coordinates are in bounds and diagnostic-tagged, but only the
    // original diagnostic is embedded in the malformed expression payload.
    {
        const alternate_diagnostic: u32 = @intFromEnum(checked.base_literal_expr);
        const alternate_node_idx: CIR.Node.Idx = @enumFromInt(alternate_diagnostic);
        const saved_alternate_node = cir.store.nodes.get(alternate_node_idx);
        const diagnostic_node = cir.store.nodes.get(@enumFromInt(
            @intFromEnum(checked.field_diagnostic),
        ));
        const saved_publication_row = cir.malformed_expression_publications.items.items[0];
        defer {
            cir.store.nodes.set(alternate_node_idx, saved_alternate_node);
            cir.malformed_expression_publications.items.items[0] = saved_publication_row;
        }
        cir.store.nodes.set(alternate_node_idx, diagnostic_node);
        cir.malformed_expression_publications.items.items[0].diagnostic_index =
            alternate_diagnostic;
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    const PayloadCorruption = enum { padding, reserved, diagnostic_oob };
    inline for ([_]PayloadCorruption{ .padding, .reserved, .diagnostic_oob }) |corruption| {
        const node_idx = ModuleEnv.nodeIdxFrom(topology.field_expr);
        const saved_node = cir.store.nodes.get(node_idx);
        defer cir.store.nodes.set(node_idx, saved_node);
        var corrupted_node = saved_node;
        var payload = corrupted_node.getPayload();
        switch (corruption) {
            .padding => payload.diag_single_value._padding[0] = 1,
            .reserved => payload.diag_single_value._reserved = 1,
            .diagnostic_oob => payload.diag_single_value.value = @intCast(
                cir.store.nodes.len(),
            ),
        }
        corrupted_node.setPayload(payload);
        cir.store.nodes.set(node_idx, corrupted_node);
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    try cir.malformed_expression_publications.items.ensureUnusedCapacity(cir.gpa, 1);
    {
        const saved_len = cir.malformed_expression_publications.items.items.len;
        defer cir.malformed_expression_publications.items.items.len = saved_len;
        _ = cir.malformed_expression_publications.appendAssumeCapacity(saved_publication);
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }
    {
        const saved_len = cir.malformed_expression_publications.items.items.len;
        defer cir.malformed_expression_publications.items.items.len = saved_len;
        var invalid_duplicate = saved_publication;
        invalid_duplicate.diagnostic_index = @intCast(cir.store.nodes.len());
        _ = cir.malformed_expression_publications.appendAssumeCapacity(invalid_duplicate);
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    try cir.malformed_type_annotation_publications.items.ensureUnusedCapacity(cir.gpa, 1);
    {
        const expression_len = cir.malformed_expression_publications.items.items.len;
        const type_len = cir.malformed_type_annotation_publications.items.items.len;
        defer {
            cir.malformed_expression_publications.items.items.len = expression_len;
            cir.malformed_type_annotation_publications.items.items.len = type_len;
        }
        cir.malformed_expression_publications.items.items.len = 0;
        _ = cir.malformed_type_annotation_publications.appendAssumeCapacity(.{
            .annotation_node = field_node,
            .diagnostic_index = @intFromEnum(checked.field_diagnostic),
        });
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    try std.testing.expect(recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
    try std.testing.expect(expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    try std.testing.expect(std.meta.eql(
        saved_publication,
        cir.malformed_expression_publications.items.items[0],
    ));
}

fn expectRecordUpdateMalformedSuppliedFieldPostRetirementCorruptions(
    cir: *ModuleEnv,
    topology: RecordUpdateProjectionRelationTopology,
    base_plan_index: u32,
    retirement_index: u32,
) !void {
    const checked = topology.checked_error_field orelse return error.TestUnexpectedResult;
    const field_node: u32 = @intFromEnum(topology.field_expr);
    const plans = cir.expected_consumption_plans.items.items;
    if (base_plan_index >= plans.len or
        retirement_index >= cir.expected_consumer_retirements.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const base_plan = plans[base_plan_index];
    const saved_retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    try std.testing.expect(recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
    try std.testing.expect(expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    // This scalar syntax predicate intentionally cannot distinguish the valid
    // pre-consumption phase from a deleted or retargeted completed R0. The
    // checked child's status/cause and completion validators own that fact.
    {
        const retirement = &cir.expected_consumer_retirements.items.items[retirement_index];
        defer retirement.* = saved_retirement;
        retirement.retired_node = @intFromEnum(checked.base_literal_expr);
        try std.testing.expect(recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    const RetirementCorruption = enum {
        owner_kind,
        original_tag,
        original_payload,
        other_kind,
        diagnostic,
        consumer_start,
        consumer_len,
        failure_start,
        failure_len,
        rejection_kind,
        rejection_index,
        rejection_subject,
        reserved_0,
        reserved_1,
    };
    inline for ([_]RetirementCorruption{
        .owner_kind,
        .original_tag,
        .original_payload,
        .other_kind,
        .diagnostic,
        .consumer_start,
        .consumer_len,
        .failure_start,
        .failure_len,
        .rejection_kind,
        .rejection_index,
        .rejection_subject,
        .reserved_0,
        .reserved_1,
    }) |corruption| {
        const retirement = &cir.expected_consumer_retirements.items.items[retirement_index];
        defer retirement.* = saved_retirement;
        switch (corruption) {
            .owner_kind => retirement.owner_kind = @intFromEnum(
                ModuleEnv.ExpectedConsumerRetirement.OwnerKind.pattern,
            ),
            .original_tag => retirement.original_node_tag = @intFromEnum(
                CIR.Node.Tag.expr_typed_int,
            ),
            .original_payload => retirement.original_payload[0] +%= 1,
            .other_kind => {
                retirement.kind = @intFromEnum(
                    ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
                );
                retirement.original_node_tag = @intFromEnum(CIR.Node.Tag.expr_typed_int);
                retirement.original_payload = @bitCast(cir.store.nodes.get(
                    ModuleEnv.nodeIdxFrom(checked.base_literal_expr),
                ).getPayload());
                try std.testing.expect(retirement.hasLegalTags());
            },
            .diagnostic => retirement.diagnostic_index = @intCast(cir.store.nodes.len()),
            .consumer_start => retirement.retired_consumers_start = 1,
            .consumer_len => retirement.retired_consumers_len = 1,
            .failure_start => retirement.expected_failures_start = 1,
            .failure_len => retirement.expected_failures_len = 1,
            .rejection_kind => {
                retirement.rejection_owner_kind = @intFromEnum(
                    ModuleEnv.ExpectedConsumerRetirement.RejectionOwnerKind.rejected_static_dispatch,
                );
                retirement.rejection_owner_index = 0;
                retirement.rejection_subject_var = field_node;
            },
            .rejection_index => retirement.rejection_owner_index = 0,
            .rejection_subject => retirement.rejection_subject_var = field_node,
            .reserved_0 => retirement.reserved_0 = 1,
            .reserved_1 => retirement.reserved_1 = 1,
        }
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    // Keep both diagnostic coordinates in bounds while making R0 disagree
    // with the canonical malformed child's embedded diagnostic.
    {
        const alternate_diagnostic: u32 = @intFromEnum(checked.base_literal_expr);
        const alternate_node_idx: CIR.Node.Idx = @enumFromInt(alternate_diagnostic);
        const saved_alternate_node = cir.store.nodes.get(alternate_node_idx);
        const diagnostic_node = cir.store.nodes.get(@enumFromInt(
            @intFromEnum(checked.field_diagnostic),
        ));
        const retirement = &cir.expected_consumer_retirements.items.items[retirement_index];
        defer {
            cir.store.nodes.set(alternate_node_idx, saved_alternate_node);
            retirement.* = saved_retirement;
        }
        cir.store.nodes.set(alternate_node_idx, diagnostic_node);
        retirement.diagnostic_index = alternate_diagnostic;
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    try cir.expected_consumer_retirements.items.ensureUnusedCapacity(cir.gpa, 1);
    {
        const saved_len = cir.expected_consumer_retirements.items.items.len;
        defer cir.expected_consumer_retirements.items.items.len = saved_len;
        _ = cir.expected_consumer_retirements.appendAssumeCapacity(saved_retirement);
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }
    {
        const saved_len = cir.expected_consumer_retirements.items.items.len;
        defer cir.expected_consumer_retirements.items.items.len = saved_len;
        var invalid_duplicate = saved_retirement;
        invalid_duplicate.reserved_0 = 1;
        _ = cir.expected_consumer_retirements.appendAssumeCapacity(invalid_duplicate);
        try std.testing.expect(!recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
        try std.testing.expect(!expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    }

    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&saved_retirement),
        std.mem.asBytes(&cir.expected_consumer_retirements.items.items[retirement_index]),
    );
    try std.testing.expect(recordUpdateSuppliedFieldSyntaxIsLocallyValid(cir, field_node));
    try std.testing.expect(expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
}

const RecordUpdateProjectionAvailabilityCopyLengths = struct {
    steps: usize,
    pairs: usize,
    occurrences: usize,
    constraint_pairs: usize,
    witnesses: usize,
    copied_groups: usize,
    copied_events: usize,
    substitutions: usize,
    selected_anchors: usize,
    evidence_handles: usize,
    settlement_sources: usize,
    scheme_uses: usize,
    scheme_use_pairs: usize,

    fn capture(checker: *const Self) @This() {
        const cir = checker.cir;
        return .{
            .steps = cir.where_marker_copy_steps.items.items.len,
            .pairs = cir.where_marker_copy_pairs.items.items.len,
            .occurrences = cir.where_marker_copy_occurrences.items.items.len,
            .constraint_pairs = cir.where_marker_constraint_copy_pairs.items.items.len,
            .witnesses = cir.where_marker_copy_witnesses.items.items.len,
            .copied_groups = cir.copied_open_literal_groups.items.items.len,
            .copied_events = cir.copied_open_literal_events.items.items.len,
            .substitutions = cir.where_marker_platform_substitutions.items.items.len,
            .selected_anchors = cir.selected_receiver_anchors.items.items.len,
            .evidence_handles = checker.types.constraint_evidence_handles.items.items.len,
            .settlement_sources = cir.dispatch_settlement_sources.items.items.len,
            .scheme_uses = cir.scheme_uses.items.items.len,
            .scheme_use_pairs = cir.scheme_use_pairs.items.items.len,
        };
    }

    fn expectEqual(self: @This(), checker: *const Self) !void {
        try std.testing.expect(std.meta.eql(self, capture(checker)));
    }
};

const RecordUpdateProjectionAvailabilityTransactionProof = struct {
    plan_index: u32,
    plan: ModuleEnv.ExpectedConsumptionPlan,
    registration: RecordUpdateExpectedPlanRegistration,
    slot: ExpectedFreshShapeSlot,

    fn expectEqual(self: @This(), other: @This()) !void {
        try std.testing.expectEqual(self.plan_index, other.plan_index);
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&self.plan),
            std.mem.asBytes(&other.plan),
        );
        try std.testing.expect(std.meta.eql(self.registration, other.registration));
        try std.testing.expect(std.meta.eql(self.slot, other.slot));
    }
};

const RecordUpdateProjectionAvailabilityAllocationStateSnapshot = struct {
    transaction: RecordUpdateRootTransactionSnapshot,
    pending_record_updates: []PendingRecordUpdate,
    optional_field_accesses: []OptionalFieldAccess,
    aggregate_drafts: []AggregateExpectedRetirementDraft,
    owner_ranges: []ExpectedOwnerPlanRange,
    nodes: [3]CheckedErrorRecordUpdateBasePlanNodeSnapshot,
    copy_lengths: RecordUpdateProjectionAvailabilityCopyLengths,
    frame_status: CheckedExprStatus,
    instantiation_source_expr: ?CIR.Expr.Idx,

    fn capture(
        gpa: Allocator,
        checker: *const Self,
        env: *Env,
        topology: RecordUpdateProjectionRelationTopology,
        frame_status: CheckedExprStatus,
    ) !@This() {
        var transaction = try RecordUpdateRootTransactionSnapshot.capture(gpa, checker, env);
        errdefer transaction.deinit(gpa);
        const pending_record_updates = try gpa.dupe(
            PendingRecordUpdate,
            checker.pending_record_updates.items,
        );
        errdefer gpa.free(pending_record_updates);
        const optional_field_accesses = try gpa.dupe(
            OptionalFieldAccess,
            checker.optional_field_accesses.items,
        );
        errdefer gpa.free(optional_field_accesses);
        const aggregate_drafts = try gpa.dupe(
            AggregateExpectedRetirementDraft,
            checker.aggregate_expected_retirement_drafts.items,
        );
        errdefer gpa.free(aggregate_drafts);
        const owner_ranges = try gpa.dupe(
            ExpectedOwnerPlanRange,
            checker.expected_owner_plan_ranges.items,
        );
        errdefer gpa.free(owner_ranges);
        return .{
            .transaction = transaction,
            .pending_record_updates = pending_record_updates,
            .optional_field_accesses = optional_field_accesses,
            .aggregate_drafts = aggregate_drafts,
            .owner_ranges = owner_ranges,
            .nodes = .{
                CheckedErrorRecordUpdateBasePlanNodeSnapshot.capture(checker.cir, topology.record_expr),
                CheckedErrorRecordUpdateBasePlanNodeSnapshot.capture(checker.cir, topology.base_expr),
                CheckedErrorRecordUpdateBasePlanNodeSnapshot.capture(checker.cir, topology.field_expr),
            },
            .copy_lengths = RecordUpdateProjectionAvailabilityCopyLengths.capture(checker),
            .frame_status = frame_status,
            .instantiation_source_expr = checker.instantiation_source_expr,
        };
    }

    fn expectEqual(
        self: *const @This(),
        gpa: Allocator,
        checker: *const Self,
        env: *Env,
        frame_status: CheckedExprStatus,
    ) !void {
        try self.transaction.expectEqual(gpa, checker, env);
        try expectRecordUpdateTestSemanticSlicesEqual(
            self.pending_record_updates,
            checker.pending_record_updates.items,
        );
        try expectRecordUpdateTestSemanticSlicesEqual(
            self.optional_field_accesses,
            checker.optional_field_accesses.items,
        );
        try expectRecordUpdateTestSemanticSlicesEqual(
            self.aggregate_drafts,
            checker.aggregate_expected_retirement_drafts.items,
        );
        try expectRecordUpdateTestSemanticSlicesEqual(
            self.owner_ranges,
            checker.expected_owner_plan_ranges.items,
        );
        for (self.nodes) |node| try node.expectEqual(checker.cir);
        try self.copy_lengths.expectEqual(checker);
        try expectCheckedExprStatusesEqual(self.frame_status, frame_status);
        try std.testing.expectEqual(self.instantiation_source_expr, checker.instantiation_source_expr);
    }

    fn expectSameInstanceRollback(
        self: *const @This(),
        gpa: Allocator,
        checker: *const Self,
        env: *Env,
        frame_status: CheckedExprStatus,
    ) !void {
        try self.expectEqual(gpa, checker, env, frame_status);
        try self.transaction.cross_copy.expectEqual(checker);
    }

    fn deinit(self: *@This(), gpa: Allocator) void {
        gpa.free(self.owner_ranges);
        gpa.free(self.aggregate_drafts);
        gpa.free(self.optional_field_accesses);
        gpa.free(self.pending_record_updates);
        self.transaction.deinit(gpa);
        self.* = undefined;
    }
};

const RecordUpdateProjectionAvailabilityAllocationCalibration = struct {
    before: RecordUpdateProjectionAvailabilityAllocationStateSnapshot,
    after: RecordUpdateProjectionAvailabilityAllocationStateSnapshot,
    proof: RecordUpdateProjectionAvailabilityTransactionProof,
    allocation_count: usize,

    fn deinit(self: *@This(), gpa: Allocator) void {
        self.after.deinit(gpa);
        self.before.deinit(gpa);
        self.* = undefined;
    }
};

const RecordUpdateProjectionAvailabilityAllocationRun = union(enum) {
    calibrate: *?RecordUpdateProjectionAvailabilityAllocationCalibration,
    fail_and_retry: struct {
        failure_index: usize,
        calibration: *const RecordUpdateProjectionAvailabilityAllocationCalibration,
    },
};

const RecordUpdateProjectionAvailabilityAllocationController = struct {
    allocator: *std.testing.FailingAllocator,
    run: RecordUpdateProjectionAvailabilityAllocationRun,
};

fn disableRecordUpdateProjectionAvailabilityFailure(
    allocator: *std.testing.FailingAllocator,
) void {
    allocator.fail_index = std.math.maxInt(usize);
    allocator.resize_fail_index = std.math.maxInt(usize);
}

fn expectRecordUpdateProjectionAvailabilityAllocatorOwnership(
    checker: *const Self,
    env: *const Env,
    allocator: *std.testing.FailingAllocator,
) !void {
    const measured = allocator.allocator();
    try std.testing.expect(std.meta.eql(measured, checker.gpa));
    try std.testing.expect(std.meta.eql(measured, checker.cir.gpa));
    try std.testing.expect(std.meta.eql(measured, checker.types.gpa));
    try std.testing.expect(std.meta.eql(measured, checker.env_pool.gpa));
    try std.testing.expect(std.meta.eql(measured, env.var_pool.allocator));
}

fn constrainRecordUpdateProjectionAvailabilityCapacityForTest(
    checker: *Self,
    published_base: PublishedRecordUpdateBasePlan,
    base_proof: StagedRecordUpdateBasePlanPublicationProof,
) !void {
    const plans = &checker.cir.expected_consumption_plans.items;
    const registrations = &checker.record_update_expected_plan_registrations;
    if (plans.items.len != 1 or published_base.plan_index != 0 or
        registrations.items.len != 1)
    {
        return error.TestUnexpectedResult;
    }
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&base_proof.plan),
        std.mem.asBytes(&plans.items[0]),
    );
    try std.testing.expect(std.meta.eql(base_proof.registration, registrations.items[0]));
    const saved_plans = try std.testing.allocator.dupe(
        ModuleEnv.ExpectedConsumptionPlan,
        plans.items,
    );
    defer std.testing.allocator.free(saved_plans);
    const saved_registrations = try std.testing.allocator.dupe(
        RecordUpdateExpectedPlanRegistration,
        registrations.items,
    );
    defer std.testing.allocator.free(saved_registrations);
    try plans.shrinkToLen(checker.cir.gpa);
    try registrations.shrinkToLen(checker.gpa);
    try std.testing.expectEqual(plans.items.len, plans.capacity);
    try std.testing.expectEqual(registrations.items.len, registrations.capacity);
    try std.testing.expectEqualSlices(
        u8,
        std.mem.sliceAsBytes(saved_plans),
        std.mem.sliceAsBytes(plans.items),
    );
    try expectRecordUpdateExpectedPlanRegistrationsEqual(
        saved_registrations,
        registrations.items,
    );
}

fn expectRecordUpdateProjectionAvailabilityNoFailureState(checker: *const Self) !void {
    const cir = checker.cir;
    try std.testing.expectEqual(@as(usize, 0), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.aggregate_expected_retirement_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.record_update_owner_retirement_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.direct_formal_failure_sources.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.problems.problems.items.len);
    try std.testing.expect(!checker.record_update_expected_plan_registrations_consumed);
}

fn expectStagedRecordUpdateProjectionUnavailable(
    checker: *const Self,
    topology: RecordUpdateProjectionRelationTopology,
    published_base: PublishedRecordUpdateBasePlan,
    slot: ExpectedFreshShapeSlot,
    expected_plan_index: u32,
    expected_registration_index: usize,
) !RecordUpdateProjectionAvailabilityTransactionProof {
    const cir = checker.cir;
    try std.testing.expectEqual(expected_plan_index, slot.expected_plan);
    try std.testing.expectEqual(topology.field_expr, slot.site);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.record_update_field, slot.role);
    try std.testing.expectEqual(@as(u32, 0), slot.slot);
    try std.testing.expect(slot.raw_fresh_var != ModuleEnv.varFrom(slot.site));
    try std.testing.expectEqual(@as(usize, expected_plan_index + 1), cir.expected_consumption_plans.items.items.len);
    try std.testing.expectEqual(expected_registration_index + 1, checker.record_update_expected_plan_registrations.items.len);
    const plan = cir.expected_consumption_plans.items.items[expected_plan_index];
    try std.testing.expect(plan.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), plan.owner_node);
    try std.testing.expectEqual(@intFromEnum(topology.field_expr), plan.site_node);
    try std.testing.expectEqual(@intFromEnum(topology.field_expr), plan.raw_consumer_var);
    try std.testing.expect(plan.raw_consumer_var != @intFromEnum(slot.raw_fresh_var));
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.record_update_field, plan.decodedRole().?);
    try std.testing.expectEqual(@as(u32, 0), plan.slot);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Outcome.not_projected, plan.decodedOutcome().?);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_projection_unavailable,
        plan.decodedReason().?,
    );
    const base_authority = encodeExpectedParentAuthority(.{
        .copy_occurrence = published_base.anchor,
    });
    try std.testing.expect(expectedMarkerAuthoritiesEqual(base_authority, plan.parent_authority));
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.none, plan.produced_copy_step);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.none, plan.produced_occurrence_offset);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.none, plan.produced_side);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.none, plan.call_root_plan_index);
    try std.testing.expect(plan.failure_owner.hasCanonicalTags(false));
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.none, plan.failure_cause_plan_index);
    try std.testing.expect(plan.decodedSourceRetirementIndex() == null);
    try std.testing.expect(expectedRecordUpdateFieldBeginsAtBase(
        cir,
        expected_plan_index,
        plan,
        base_authority,
    ));
    try std.testing.expect(expectedFreshShapePlanMatchesCir(cir, plan));

    const registration = checker.record_update_expected_plan_registrations.items[
        expected_registration_index
    ];
    try std.testing.expectEqual(topology.record_expr, registration.owner_expr);
    try std.testing.expectEqual(expected_plan_index, registration.plan_index);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.record_update_field, registration.role);
    try std.testing.expectEqual(@as(u32, 0), registration.slot);
    try std.testing.expectEqual(topology.field_expr, registration.site);
    try std.testing.expect(validateRecordUpdateExpectedPlanRegistrations(checker));
    return .{
        .plan_index = expected_plan_index,
        .plan = plan,
        .registration = registration,
        .slot = slot,
    };
}

fn runRecordUpdateProjectionAvailabilityAllocationController(
    checker: *Self,
    env: *Env,
    topology: RecordUpdateProjectionRelationTopology,
    published_base: PublishedRecordUpdateBasePlan,
    base_proof: StagedRecordUpdateBasePlanPublicationProof,
    projected_record: Var,
    initial_slot: ExpectedFreshShapeSlot,
    field_name: u32,
    update_context: problem.Context,
    frame_status: *const CheckedExprStatus,
    controller: *RecordUpdateProjectionAvailabilityAllocationController,
) !void {
    defer disableRecordUpdateProjectionAvailabilityFailure(controller.allocator);
    try expectRecordUpdateProjectionAvailabilityAllocatorOwnership(
        checker,
        env,
        controller.allocator,
    );
    if (initial_slot.expected_plan != ModuleEnv.ExpectedConsumptionPlan.none or
        initial_slot.role != .record_update_field or initial_slot.slot != 0 or
        initial_slot.site != topology.field_expr or
        checker.pending_record_updates.items.len != 1 or
        checker.optional_field_accesses.items.len != 0)
    {
        return error.TestUnexpectedResult;
    }
    switch (frame_status.*) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }
    try expectRecordUpdateProjectionAvailabilityNoFailureState(checker);
    try constrainRecordUpdateProjectionAvailabilityCapacityForTest(
        checker,
        published_base,
        base_proof,
    );

    const cir = checker.cir;
    const expected_plan_index: u32 = @intCast(cir.expected_consumption_plans.items.items.len);
    const expected_registration_index = checker.record_update_expected_plan_registrations.items.len;
    var before = try RecordUpdateProjectionAvailabilityAllocationStateSnapshot.capture(
        std.testing.allocator,
        checker,
        env,
        topology,
        frame_status.*,
    );
    errdefer before.deinit(std.testing.allocator);

    switch (controller.run) {
        .calibrate => |output| {
            if (output.* != null) return error.TestUnexpectedResult;
            const allocation_base = controller.allocator.alloc_index;
            controller.allocator.resize_fail_index = controller.allocator.resize_index;
            var slot = initial_slot;
            const outcome = try checker.projectExpectedRecordUpdateField(
                topology.record_expr,
                published_base.plan_index,
                .{
                    .var_ = published_base.copy.var_,
                    .context = update_context,
                    .marker_authority = .{ .anchored = .{ .copy_occurrence = published_base.anchor } },
                    .status = .established,
                },
                projected_record,
                &slot,
                field_name,
                env,
            );
            disableRecordUpdateProjectionAvailabilityFailure(controller.allocator);
            switch (outcome) {
                .not_projected => {},
                .established, .suppressed => return error.TestUnexpectedResult,
            }
            const allocation_count = controller.allocator.alloc_index - allocation_base;
            try std.testing.expect(!controller.allocator.has_induced_failure);
            try std.testing.expect(allocation_count >= 4);
            const proof = try expectStagedRecordUpdateProjectionUnavailable(
                checker,
                topology,
                published_base,
                slot,
                expected_plan_index,
                expected_registration_index,
            );
            try before.copy_lengths.expectEqual(checker);
            try expectRecordUpdateProjectionAvailabilityNoFailureState(checker);
            var after = try RecordUpdateProjectionAvailabilityAllocationStateSnapshot.capture(
                std.testing.allocator,
                checker,
                env,
                topology,
                frame_status.*,
            );
            errdefer after.deinit(std.testing.allocator);
            output.* = .{
                .before = before,
                .after = after,
                .proof = proof,
                .allocation_count = allocation_count,
            };
        },
        .fail_and_retry => |injected| {
            try injected.calibration.before.expectEqual(
                std.testing.allocator,
                checker,
                env,
                frame_status.*,
            );
            const failure_allocation_base = controller.allocator.alloc_index;
            const failure_allocation_index = std.math.add(
                usize,
                failure_allocation_base,
                injected.failure_index,
            ) catch return error.TestUnexpectedResult;
            controller.allocator.fail_index = failure_allocation_index;
            controller.allocator.resize_fail_index = controller.allocator.resize_index;
            var failed_slot = initial_slot;
            const failed = checker.projectExpectedRecordUpdateField(
                topology.record_expr,
                published_base.plan_index,
                .{
                    .var_ = published_base.copy.var_,
                    .context = update_context,
                    .marker_authority = .{ .anchored = .{ .copy_occurrence = published_base.anchor } },
                    .status = .established,
                },
                projected_record,
                &failed_slot,
                field_name,
                env,
            );
            disableRecordUpdateProjectionAvailabilityFailure(controller.allocator);
            try std.testing.expectError(error.OutOfMemory, failed);
            try std.testing.expect(controller.allocator.has_induced_failure);
            try std.testing.expectEqual(
                failure_allocation_index,
                controller.allocator.alloc_index,
            );
            try std.testing.expectEqual(initial_slot.site, failed_slot.site);
            try std.testing.expectEqual(initial_slot.role, failed_slot.role);
            try std.testing.expectEqual(initial_slot.slot, failed_slot.slot);
            try std.testing.expectEqual(initial_slot.raw_fresh_var, failed_slot.raw_fresh_var);
            if (failed_slot.expected_plan != ModuleEnv.ExpectedConsumptionPlan.none and
                failed_slot.expected_plan != expected_plan_index)
            {
                return error.TestUnexpectedResult;
            }
            try before.expectSameInstanceRollback(
                std.testing.allocator,
                checker,
                env,
                frame_status.*,
            );
            try expectRecordUpdateProjectionAvailabilityNoFailureState(checker);
            try std.testing.expectEqual(expected_plan_index, cir.expected_consumption_plans.items.items.len);
            try std.testing.expectEqual(
                expected_registration_index,
                checker.record_update_expected_plan_registrations.items.len,
            );

            // The caller-local slot is outside the Probe contract. Retry from
            // another copy of the immutable pending input, never by repairing
            // the slot that observed the failed attempt.
            var retry_slot = initial_slot;
            const retry_outcome = try checker.projectExpectedRecordUpdateField(
                topology.record_expr,
                published_base.plan_index,
                .{
                    .var_ = published_base.copy.var_,
                    .context = update_context,
                    .marker_authority = .{ .anchored = .{ .copy_occurrence = published_base.anchor } },
                    .status = .established,
                },
                projected_record,
                &retry_slot,
                field_name,
                env,
            );
            switch (retry_outcome) {
                .not_projected => {},
                .established, .suppressed => return error.TestUnexpectedResult,
            }
            const retry_proof = try expectStagedRecordUpdateProjectionUnavailable(
                checker,
                topology,
                published_base,
                retry_slot,
                expected_plan_index,
                expected_registration_index,
            );
            try injected.calibration.proof.expectEqual(retry_proof);
            try before.copy_lengths.expectEqual(checker);
            try expectRecordUpdateProjectionAvailabilityNoFailureState(checker);
            try injected.calibration.after.expectEqual(
                std.testing.allocator,
                checker,
                env,
                frame_status.*,
            );
            before.deinit(std.testing.allocator);
        },
    }
}

fn expectRecordUpdateProjectionAvailabilityOuterRollback(
    checker: *Self,
    env: *Env,
    topology: RecordUpdateProjectionRelationTopology,
    published_base: PublishedRecordUpdateBasePlan,
    projected_record: Var,
    initial_slot: ExpectedFreshShapeSlot,
    field_name: u32,
    update_context: problem.Context,
    frame_status: *const CheckedExprStatus,
) !void {
    if (initial_slot.expected_plan != ModuleEnv.ExpectedConsumptionPlan.none or
        initial_slot.role != .record_update_field or initial_slot.slot != 0 or
        initial_slot.site != topology.field_expr)
    {
        return error.TestUnexpectedResult;
    }
    switch (frame_status.*) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }
    const cir = checker.cir;
    const expected_plan_index: u32 = @intCast(cir.expected_consumption_plans.items.items.len);
    const expected_registration_index = checker.record_update_expected_plan_registrations.items.len;
    if (published_base.plan_index >= expected_plan_index or expected_registration_index == 0) {
        return error.TestUnexpectedResult;
    }
    const base_plan_before = cir.expected_consumption_plans.items.items[published_base.plan_index];
    const base_registration_before = checker.record_update_expected_plan_registrations.items[
        expected_registration_index - 1
    ];
    try std.testing.expectEqual(published_base.plan_index, base_registration_before.plan_index);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.record_update_base, base_registration_before.role);
    const pending_record_updates_len = checker.pending_record_updates.items.len;
    const retirements_len = cir.expected_consumer_retirements.items.items.len;
    const failures_len = cir.expected_failures.items.items.len;
    const retirement_failures_len = cir.expected_retirement_failures.items.items.len;
    const retired_consumers_len = cir.expected_retired_consumers.items.items.len;
    const optional_field_accesses_len = checker.optional_field_accesses.items.len;
    const aggregate_drafts_len = checker.aggregate_expected_retirement_drafts.items.len;
    const owner_ranges_len = checker.expected_owner_plan_ranges.items.len;
    const owner_drafts_len = checker.record_update_owner_retirement_drafts.items.len;
    const registrations_consumed = checker.record_update_expected_plan_registrations_consumed;
    const copy_lengths = RecordUpdateProjectionAvailabilityCopyLengths.capture(checker);
    var before = try RecordUpdateRootTransactionSnapshot.capture(
        std.testing.allocator,
        checker,
        env,
    );
    defer before.deinit(std.testing.allocator);

    const initial_probe_depth = checker.probe_depth;
    var outer = try checker.beginLocalMarkerCopyTransaction(env);
    var outer_open = true;
    defer if (outer_open) outer.rollback();
    try std.testing.expectEqual(initial_probe_depth + 1, checker.probe_depth);
    var rolled_slot = initial_slot;
    const rolled_outcome = try checker.projectExpectedRecordUpdateField(
        topology.record_expr,
        published_base.plan_index,
        .{
            .var_ = published_base.copy.var_,
            .context = update_context,
            .marker_authority = .{ .anchored = .{ .copy_occurrence = published_base.anchor } },
            .status = .established,
        },
        projected_record,
        &rolled_slot,
        field_name,
        env,
    );
    switch (rolled_outcome) {
        .not_projected => {},
        .established, .suppressed => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(initial_probe_depth + 1, checker.probe_depth);
    const rolled_proof = try expectStagedRecordUpdateProjectionUnavailable(
        checker,
        topology,
        published_base,
        rolled_slot,
        expected_plan_index,
        expected_registration_index,
    );
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&base_plan_before),
        std.mem.asBytes(&cir.expected_consumption_plans.items.items[published_base.plan_index]),
    );
    try std.testing.expect(std.meta.eql(
        base_registration_before,
        checker.record_update_expected_plan_registrations.items[expected_registration_index - 1],
    ));
    try copy_lengths.expectEqual(checker);
    try std.testing.expectEqual(pending_record_updates_len, checker.pending_record_updates.items.len);
    try std.testing.expectEqual(retirements_len, cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(failures_len, cir.expected_failures.items.items.len);
    try std.testing.expectEqual(retirement_failures_len, cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(retired_consumers_len, cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(optional_field_accesses_len, checker.optional_field_accesses.items.len);
    try std.testing.expectEqual(aggregate_drafts_len, checker.aggregate_expected_retirement_drafts.items.len);
    try std.testing.expectEqual(owner_ranges_len, checker.expected_owner_plan_ranges.items.len);
    try std.testing.expectEqual(owner_drafts_len, checker.record_update_owner_retirement_drafts.items.len);
    try std.testing.expectEqual(registrations_consumed, checker.record_update_expected_plan_registrations_consumed);
    switch (frame_status.*) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }

    outer.rollback();
    outer_open = false;
    try std.testing.expectEqual(initial_probe_depth, checker.probe_depth);
    try before.expectEqual(std.testing.allocator, checker, env);
    try before.cross_copy.expectEqual(checker);
    try copy_lengths.expectEqual(checker);
    try std.testing.expectEqual(expected_plan_index, cir.expected_consumption_plans.items.items.len);
    try std.testing.expectEqual(expected_registration_index, checker.record_update_expected_plan_registrations.items.len);
    try std.testing.expectEqual(pending_record_updates_len, checker.pending_record_updates.items.len);
    try std.testing.expectEqual(optional_field_accesses_len, checker.optional_field_accesses.items.len);
    try std.testing.expectEqual(aggregate_drafts_len, checker.aggregate_expected_retirement_drafts.items.len);
    try std.testing.expectEqual(owner_ranges_len, checker.expected_owner_plan_ranges.items.len);
    try std.testing.expectEqual(owner_drafts_len, checker.record_update_owner_retirement_drafts.items.len);
    try std.testing.expectEqual(registrations_consumed, checker.record_update_expected_plan_registrations_consumed);
    switch (frame_status.*) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }

    var retry_slot = initial_slot;
    const retry_outcome = try checker.projectExpectedRecordUpdateField(
        topology.record_expr,
        published_base.plan_index,
        .{
            .var_ = published_base.copy.var_,
            .context = update_context,
            .marker_authority = .{ .anchored = .{ .copy_occurrence = published_base.anchor } },
            .status = .established,
        },
        projected_record,
        &retry_slot,
        field_name,
        env,
    );
    switch (retry_outcome) {
        .not_projected => {},
        .established, .suppressed => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(initial_probe_depth, checker.probe_depth);
    const retry_proof = try expectStagedRecordUpdateProjectionUnavailable(
        checker,
        topology,
        published_base,
        retry_slot,
        expected_plan_index,
        expected_registration_index,
    );
    try rolled_proof.expectEqual(retry_proof);
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&base_plan_before),
        std.mem.asBytes(&cir.expected_consumption_plans.items.items[published_base.plan_index]),
    );
    try std.testing.expect(std.meta.eql(
        base_registration_before,
        checker.record_update_expected_plan_registrations.items[expected_registration_index - 1],
    ));
    try copy_lengths.expectEqual(checker);
    try std.testing.expectEqual(pending_record_updates_len, checker.pending_record_updates.items.len);
    try std.testing.expectEqual(retirements_len, cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(failures_len, cir.expected_failures.items.items.len);
    try std.testing.expectEqual(retirement_failures_len, cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(retired_consumers_len, cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(optional_field_accesses_len, checker.optional_field_accesses.items.len);
    try std.testing.expectEqual(aggregate_drafts_len, checker.aggregate_expected_retirement_drafts.items.len);
    try std.testing.expectEqual(owner_ranges_len, checker.expected_owner_plan_ranges.items.len);
    try std.testing.expectEqual(owner_drafts_len, checker.record_update_owner_retirement_drafts.items.len);
    try std.testing.expectEqual(registrations_consumed, checker.record_update_expected_plan_registrations_consumed);
    switch (frame_status.*) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }
}

/// Run the real block-local binding and record-update producer chronology.
/// The relation boundary reaches the final base relation; the transaction
/// boundaries stop immediately after retrying the field projection. Every
/// mode stops before either expression frame finishes, without the later
/// checker-rewrite sweep, group publication, or terminal admission.
fn calibrateRecordUpdateProjectionRelation(
    test_env: anytype,
    fixture: RecordUpdateProjectionRelationFixture,
    mode: RecordUpdateProjectionRelationMode,
    boundary: RecordUpdateProjectionCalibrationBoundary,
) !?RecordUpdateProjectionRelationCalibration {
    var failure_stage: []const u8 = "canonical topology";
    var diagnostic_actual_relation: ?RecordUpdateProjectionRelationResult = null;
    var diagnostic_final_relation: ?RecordUpdateProjectionRelationResult = null;
    errdefer std.debug.print(
        "record-update projection relation {s}/{s} failed at {s}; actual={any} final={any}\n",
        .{
            @tagName(fixture),
            @tagName(mode),
            failure_stage,
            diagnostic_actual_relation,
            diagnostic_final_relation,
        },
    );
    const checker = &test_env.checker;
    // `TestEnv` returns its checker by value, so refresh the TypeWriter's
    // borrowed mapping after the fixture has reached this final address.
    checker.fixupTypeWriter();
    try std.testing.expect(checker.type_writer.import_mapping.? == &checker.import_mapping);
    const cir = test_env.module_env;
    const topology = try recordUpdateProjectionRelationTopology(test_env, fixture);
    const def = cir.store.getDef(topology.def_idx);
    const block = cir.store.getExpr(topology.block_expr).e_block;
    const record = cir.store.getExpr(topology.record_expr).e_record;
    const field_indices = cir.store.sliceRecordFields(record.fields);
    if (field_indices.len != 1) return error.TestUnexpectedResult;
    const field = cir.store.getRecordField(field_indices[0]);
    if (def.annotation != null or checker.platform_required_defs.get(topology.def_idx) != null or
        isFunctionDef(&cir.store, cir.store.getExpr(def.expr)) or
        checker.isExecutableRootDef(topology.def_idx))
    {
        return error.TestUnexpectedResult;
    }

    checker.beginTypecheck();
    try ensureTypeStoreIsFilled(checker);
    try checker.reserveWhereAliasDeclarationPublications();
    try checker.collectHostBoundaryAnnotations();
    var env = try checker.env_pool.acquire();
    defer checker.env_pool.release(env);
    try std.testing.expectEqual(Rank.generalized, env.rank());
    try checker.copyBuiltinTypes();
    for (0..cir.builtin_statements.span.len) |statement_offset| {
        const statement = cir.store.statementAt(cir.builtin_statements, statement_offset);
        try checker.generateStmtTypeDeclType(statement, &env);
    }
    try std.testing.expectEqual(@as(u32, 0), cir.type_decls.span.len);
    try std.testing.expectEqual(@as(u32, 0), cir.forward_type_decls.span.len);
    try std.testing.expectEqual(@as(usize, 0), cir.requires_types.items.items.len);
    try std.testing.expect(checker.platform_requirements == null);
    try std.testing.expectEqual(@as(usize, 0), checker.platform_required_defs.count());
    for (0..cir.all_statements.span.len) |statement_offset| {
        switch (cir.store.getStatement(cir.store.statementAt(
            cir.all_statements,
            statement_offset,
        ))) {
            .s_alias_decl, .s_nominal_decl, .s_where_alias_decl, .s_runtime_error => return error.TestUnexpectedResult,
            else => {},
        }
    }
    try checker.finalizeTypeDeclarationValidity();
    try env.var_pool.pushRank();
    try std.testing.expectEqual(Rank.outermost, env.rank());

    for (cir.store.sliceDefs(cir.all_defs)) |module_def_idx| {
        const module_def = cir.store.getDef(module_def_idx);
        checker.setTopLevelPattern(module_def.pattern, .{
            .def_idx = module_def_idx,
            .def_name = null,
            .status = .not_processed,
        });
    }
    try checker.setupCheckOrder();
    try checker.predeclareAnnotatedDefSchemes(&env);
    const group_index = checker.defGroupIndex(topology.def_idx) orelse
        return error.TestUnexpectedResult;
    const scc = checker.check_order.?.sccs[group_index];
    if (group_index != 0 or checker.check_order.?.sccs.len != 1 or
        cir.all_defs.span.len != 1 or scc.is_recursive or scc.defs.len != 1 or
        scc.defs[0] != topology.def_idx or
        checker.shouldGeneralize(cir.store.getExpr(def.expr), def.annotation, true, false))
    {
        return error.TestUnexpectedResult;
    }
    try std.testing.expect(checker.active_scheme_root == null);
    try std.testing.expect(checker.active_generalized_target_share_group == null);
    try std.testing.expect(!checker.checking_executable_root);
    try std.testing.expect(!checker.checking_immediate_callee);
    try std.testing.expectEqual(
        checker.ambiguity_candidates.items.len,
        checker.ambiguity_candidates_def_start,
    );
    try std.testing.expectEqual(
        checker.checked_lambda_params.items.len,
        checker.checked_lambda_params_def_start,
    );
    try std.testing.expectEqual(
        checker.open_literal_vars.items.len,
        checker.open_literal_vars_def_start,
    );
    const saved_group_scheme_root = checker.active_scheme_root;
    const saved_generalized_share_group = checker.active_generalized_target_share_group;
    checker.active_scheme_root = null;
    checker.active_generalized_target_share_group = null;
    defer {
        checker.active_scheme_root = saved_group_scheme_root;
        checker.active_generalized_target_share_group = saved_generalized_share_group;
    }
    try std.testing.expectEqual(GroupState.pending, checker.group_states.items[group_index]);
    checker.group_states.items[group_index] = .checking;
    const pending_targets_top = checker.pending_dispatch_targets.items.len;
    const pending_predeclared_uses_top = checker.pending_predeclared_scheme_uses.items.len;
    try checker.group_stack.append(checker.gpa, .{
        .group_index = group_index,
        .base_rank = .outermost,
        .def_check_rank = .outermost,
        .boundary_rank = .outermost,
        .pending_targets_top = pending_targets_top,
        .pending_predeclared_uses_top = pending_predeclared_uses_top,
    });
    defer {
        std.debug.assert(checker.pending_dispatch_targets.items.len == pending_targets_top);
        std.debug.assert(checker.pending_predeclared_scheme_uses.items.len ==
            pending_predeclared_uses_top);
        _ = checker.group_stack.pop();
        checker.setTopLevelPattern(def.pattern, .{
            .def_idx = topology.def_idx,
            .def_name = null,
            .status = .not_processed,
        });
        // The solver state intentionally remains at this partial seam and the
        // disposable TestEnv must not be re-entered. Restore only the driver
        // bookkeeping so destruction never claims the unfinished group ran.
        checker.group_states.items[group_index] = .pending;
    }
    try std.testing.expectEqual(Rank.outermost, checker.currentDefCheckRank());
    try std.testing.expectEqual(Rank.outermost, checker.currentGroupBoundaryRank());
    try std.testing.expectEqual(@as(?u32, group_index), checker.currentGroupIndex());

    // Mirror the nonrecursive `checkDef` prefix. These fixtures have no
    // top-level annotation or value-generalization boundary, but their real
    // binding-RHS and compile-time-root Expected still own the enclosing block
    // frame. The refinement fixture's block-local annotation is checked later
    // by the ordinary stored-field body path.
    failure_stage = "top-level definition context";
    const saved_checking_executable_root = checker.checking_executable_root;
    const saved_ambiguity_candidates_def_start = checker.ambiguity_candidates_def_start;
    const saved_checked_lambda_params_def_start = checker.checked_lambda_params_def_start;
    const saved_open_literal_vars_def_start = checker.open_literal_vars_def_start;
    const saved_enclosing_func_name = checker.enclosing_func_name;
    const saved_checking_immediate_callee = checker.checking_immediate_callee;
    const saved_active_scheme_root = checker.active_scheme_root;
    checker.checking_executable_root = false;
    checker.ambiguity_candidates_def_start = checker.ambiguity_candidates.items.len;
    checker.checked_lambda_params_def_start = checker.checked_lambda_params.items.len;
    checker.open_literal_vars_def_start = checker.open_literal_vars.items.len;
    checker.checking_immediate_callee = false;
    checker.active_scheme_root = saved_active_scheme_root;
    defer {
        checker.checking_executable_root = saved_checking_executable_root;
        checker.ambiguity_candidates_def_start = saved_ambiguity_candidates_def_start;
        checker.checked_lambda_params_def_start = saved_checked_lambda_params_def_start;
        checker.open_literal_vars_def_start = saved_open_literal_vars_def_start;
        checker.enclosing_func_name = saved_enclosing_func_name;
        checker.checking_immediate_callee = saved_checking_immediate_callee;
        checker.active_scheme_root = saved_active_scheme_root;
    }
    const def_var = ModuleEnv.varFrom(topology.def_idx);
    const def_pattern_var = ModuleEnv.varFrom(def.pattern);
    checker.setTopLevelPattern(def.pattern, .{
        .def_idx = topology.def_idx,
        .def_name = checker.getPatternIdent(def.pattern),
        .status = .processing,
    });
    try checker.setVarRank(def_var, &env);
    try checker.setVarRank(def_pattern_var, &env);
    try checker.checkPattern(def.pattern, .bound, &env);
    checker.enclosing_func_name = checker.getPatternIdent(def.pattern);
    checker.checking_binding_rhs = true;
    checker.checking_binding_rhs_pattern = def.pattern;
    const exhaustiveness_scope = checker.exhaustiveness_context.enterCompileTimeRoot();
    defer exhaustiveness_scope.leave();
    var block_frame = try checker.beginExprCheckFrame(
        topology.block_expr,
        &env,
        Expected.none().forComptimeRoot(),
    );
    defer block_frame.deinit();
    try std.testing.expect(block_frame.is_binding_rhs);
    try std.testing.expect(!block_frame.should_generalize);
    try std.testing.expectEqual(topology.block_expr, checker.instantiation_source_expr.?);
    const hoist_scope = checker.beginHoistLexicalScope();
    defer checker.endHoistLexicalScope(hoist_scope);
    failure_stage = "block-local binding";
    const statements = try checker.checkBlockStatements(
        block.stmts,
        &env,
        block_frame.expr_region,
        block_frame.nested_expected.forStatement(),
    );
    try std.testing.expect(!statements.does_fx);
    try std.testing.expect(!statements.diverges);
    try std.testing.expect(!statements.blocks_later_hoists);

    const binding_pattern_var = ModuleEnv.varFrom(topology.binding_pattern);
    const binding_value_var = ModuleEnv.varFrom(topology.binding_value);
    try std.testing.expectEqual(
        checker.types.resolveVar(binding_pattern_var).var_,
        checker.types.resolveVar(binding_value_var).var_,
    );
    try std.testing.expect(checker.types.resolveVar(binding_pattern_var).desc.rank != .generalized);

    try std.testing.expect(!block_frame.is_call_arg);
    try std.testing.expect(!block_frame.is_immediate_callee);
    try std.testing.expect(!checker.checking_call_arg);
    try std.testing.expect(!checker.checking_immediate_callee);
    try std.testing.expect(checker.checking_immediate_call_root_token == null);
    checker.checking_call_arg = block_frame.is_call_arg;
    checker.checking_immediate_callee = block_frame.is_immediate_callee;
    failure_stage = "record expression frame";
    var record_frame = try checker.beginExprCheckFrame(
        topology.record_expr,
        &env,
        block_frame.nested_expected,
    );
    defer record_frame.deinit();
    try std.testing.expectEqual(topology.record_expr, checker.instantiation_source_expr.?);
    try std.testing.expect(record_frame.expr == .e_record);
    try std.testing.expect(!record_frame.is_binding_rhs);
    try std.testing.expectEqual(
        ModuleEnv.varFrom(topology.record_expr),
        record_frame.expr_var,
    );
    try std.testing.expect(record_frame.mb_anno_vars == null);
    try std.testing.expectEqual(
        HoistPosition.comptime_root,
        record_frame.nested_expected.hoist_position,
    );
    try std.testing.expectEqual(block_frame.is_call_arg, record_frame.is_call_arg);
    try std.testing.expectEqual(
        block_frame.is_immediate_callee,
        record_frame.is_immediate_callee,
    );

    failure_stage = "base check";
    const child_expected = record_frame.nested_expected.forStatement();
    const base_outcome = try checker.checkExpr(topology.base_expr, &env, child_expected);
    failure_stage = "base check status";
    try std.testing.expect(!base_outcome.does_fx);
    switch (base_outcome.status) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }
    failure_stage = "base retained-source identity";
    const base_raw_var = ModuleEnv.varFrom(topology.base_expr);
    const selected_base = checker.types.resolveVar(base_raw_var);
    try std.testing.expect(base_raw_var != selected_base.var_);
    try std.testing.expectEqual(
        checker.types.resolveVar(binding_pattern_var).var_,
        selected_base.var_,
    );
    const binding_root_before_base = checker.types.resolveVar(binding_pattern_var).var_;
    const base_stage = StagedRecordUpdateBasePlanPublication{
        .root = .{
            .record_expr = topology.record_expr,
            .base_expr = topology.base_expr,
            .requested_var = base_raw_var,
            .selected_root = selected_base.var_,
            .copy_steps_start = @intCast(cir.where_marker_copy_steps.items.items.len),
            .copy_pairs_start = @intCast(cir.where_marker_copy_pairs.items.items.len),
            .copy_occurrences_start = @intCast(cir.where_marker_copy_occurrences.items.items.len),
            .constraint_pairs_start = @intCast(cir.where_marker_constraint_copy_pairs.items.items.len),
            .copy_witnesses_start = @intCast(cir.where_marker_copy_witnesses.items.items.len),
            .copied_groups_start = @intCast(cir.copied_open_literal_groups.items.items.len),
            .copied_events_start = @intCast(cir.copied_open_literal_events.items.items.len),
            .selected_anchors_start = @intCast(cir.selected_receiver_anchors.items.items.len),
            .evidence_handles_start = @intCast(checker.types.constraint_evidence_handles.items.items.len),
            .settlement_sources_start = @intCast(cir.dispatch_settlement_sources.items.items.len),
            .scheme_uses_start = @intCast(cir.scheme_uses.items.items.len),
            .scheme_use_pairs_start = @intCast(cir.scheme_use_pairs.items.items.len),
            .current_rank_len = env.var_pool.getVarsForRank(env.rank()).len,
        },
        .status = base_outcome.status,
        .expected_plans_start = @intCast(cir.expected_consumption_plans.items.items.len),
        .registrations_start = checker.record_update_expected_plan_registrations.items.len,
        .owner_retirement_drafts_start = checker.record_update_owner_retirement_drafts.items.len,
        .registrations_consumed = checker.record_update_expected_plan_registrations_consumed,
    };
    failure_stage = "base plan publication";
    const published_base = try checker.publishRecordUpdateBasePlan(
        topology.record_expr,
        topology.base_expr,
        base_raw_var,
        base_outcome.status,
        &env,
    );
    failure_stage = "base publication proof";
    const base_publication = try expectRecordUpdateProjectionBasePublication(
        checker,
        &env,
        base_stage,
        published_base,
    );
    if (fixture == .checked_error_field) {
        failure_stage = "pre-retirement supplied-field syntax corruptions";
        try expectRecordUpdateMalformedSuppliedFieldPreRetirementCorruptions(
            cir,
            topology,
            published_base.plan_index,
        );
    }

    failure_stage = "projected field shape";
    const field_kind_var = try checker.fresh(&env, record_frame.expr_region);
    const projected_field_value = try checker.fresh(&env, record_frame.expr_region);
    var slot = pendingExpectedFreshShapeSlot(
        field.value,
        .record_update_field,
        0,
        projected_field_value,
    );
    try checker.pending_record_updates.append(checker.gpa, .{
        .presence_var = field_kind_var,
        .region = record_frame.expr_region,
    });
    const projected_record = try checker.freshFromContent(.{
        .structure = .{ .record_unbound = try checker.types.appendRecordFields(&.{.{
            .name = field.name,
            .presence = .unknown(field_kind_var, projected_field_value),
        }}) },
    }, &env, record_frame.expr_region);
    const update_context = problem.Context{ .record_update = .{
        .field_name = field.name,
        .field_region_idx = @enumFromInt(@intFromEnum(field.value)),
        .record_region_idx = @enumFromInt(@intFromEnum(base_raw_var)),
        .record_name = checker.getExprPatternIdent(topology.base_expr),
    } };
    switch (boundary) {
        .full_relations => {},
        .availability_outer_rollback => {
            if (fixture != .optional_width_refinement) return error.TestUnexpectedResult;
            failure_stage = "availability outer transaction rollback";
            try expectRecordUpdateProjectionAvailabilityOuterRollback(
                checker,
                &env,
                topology,
                published_base,
                projected_record,
                slot,
                @bitCast(field.name),
                update_context,
                &record_frame.checked_status,
            );
            return null;
        },
        .availability_allocation => |controller| {
            if (fixture != .optional_width_refinement) return error.TestUnexpectedResult;
            failure_stage = "availability allocation transaction";
            try runRecordUpdateProjectionAvailabilityAllocationController(
                checker,
                &env,
                topology,
                published_base,
                base_publication,
                projected_record,
                slot,
                @bitCast(field.name),
                update_context,
                &record_frame.checked_status,
                controller,
            );
            return null;
        },
    }
    failure_stage = "field projection";
    const projection = try checker.projectExpectedRecordUpdateField(
        topology.record_expr,
        published_base.plan_index,
        .{
            .var_ = published_base.copy.var_,
            .context = update_context,
            .marker_authority = .{ .anchored = .{ .copy_occurrence = published_base.anchor } },
            .status = .established,
        },
        projected_record,
        &slot,
        @bitCast(field.name),
        &env,
    );
    const projected_expected: ?Expected.ExpectedType = switch (fixture) {
        .empty_base, .typo_base, .optional_width_refinement => switch (projection) {
            .not_projected => null,
            .established, .suppressed => return error.TestUnexpectedResult,
        },
        .checked_error_field => switch (projection) {
            .established => |expected_field| expected_field,
            .not_projected, .suppressed => return error.TestUnexpectedResult,
        },
    };
    switch (record_frame.checked_status) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }
    const field_plan = cir.expected_consumption_plans.items.items[slot.expected_plan];
    try std.testing.expect(field_plan.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), field_plan.owner_node);
    try std.testing.expectEqual(@intFromEnum(field.value), field_plan.site_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Role.record_update_field,
        field_plan.decodedRole().?,
    );
    try std.testing.expectEqual(@as(u32, 0), field_plan.slot);
    const base_authority = encodeExpectedParentAuthority(.{
        .copy_occurrence = published_base.anchor,
    });
    try std.testing.expect(expectedMarkerAuthoritiesEqual(
        field_plan.parent_authority,
        base_authority,
    ));
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.none, field_plan.call_root_plan_index);
    try std.testing.expectEqual(ModuleEnv.CauseOwner.none, field_plan.failure_owner.kind);
    try std.testing.expect(field_plan.failure_owner.hasCanonicalTags(false));
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.none,
        field_plan.failure_cause_plan_index,
    );
    try std.testing.expect(field_plan.decodedSourceRetirementIndex() == null);
    try std.testing.expect(field_plan.raw_consumer_var < checker.types.len());
    try std.testing.expect(expectedRecordUpdateFieldBeginsAtBase(
        cir,
        slot.expected_plan,
        field_plan,
        base_authority,
    ));
    try std.testing.expect(expectedFreshShapePlanMatchesCir(cir, field_plan));
    const anchored_field_copy: ?RecordUpdateProjectionAnchoredFieldCopyProof = switch (fixture) {
        .empty_base, .typo_base, .optional_width_refinement => unavailable: {
            try std.testing.expectEqual(
                ModuleEnv.ExpectedConsumptionPlan.Outcome.not_projected,
                field_plan.decodedOutcome().?,
            );
            try std.testing.expectEqual(
                ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_projection_unavailable,
                field_plan.decodedReason().?,
            );
            try std.testing.expectEqual(@intFromEnum(field.value), field_plan.raw_consumer_var);
            try std.testing.expect(field_plan.raw_consumer_var != @intFromEnum(projected_field_value));
            try std.testing.expectEqual(
                ModuleEnv.ExpectedConsumptionPlan.none,
                field_plan.produced_copy_step,
            );
            try std.testing.expectEqual(
                ModuleEnv.ExpectedConsumptionPlan.none,
                field_plan.produced_occurrence_offset,
            );
            try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.none, field_plan.produced_side);
            for (cir.where_marker_copy_steps.items.items) |step| {
                switch (step.decodedKind() orelse return error.TestUnexpectedResult) {
                    .aggregate_expected_projection => try std.testing.expect(
                        step.origin.aggregate_expected_projection.expected_plan_index != slot.expected_plan,
                    ),
