test "record-update projection availability: unavailable field plan has closed coordinates" {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    const module_name = "RecordUpdateProjectionAvailabilityCoordinates";
    var failure_stage: []const u8 = "checked source";
    errdefer std.debug.print(
        "record-update projection availability coordinate test failed at {s}\n",
        .{failure_stage},
    );

    var checked = try TestEnv.init(module_name, record_update_projection_refinement_source);
    defer checked.deinit();
    try checked.assertNoErrors();
    try std.testing.expectEqual(@as(usize, 0), checked.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try checked.typeProblemCount());

    failure_stage = "distinct fresh source";
    var fresh_env = try TestEnv.initUncheckedWithAdmittedBuiltinForTesting(
        module_name,
        record_update_projection_refinement_source,
        checked.builtin_module,
        checked.builtin_validation,
        compiled_builtins.builtinIndices(CIR),
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{});
    const topology = try recordUpdateProjectionRelationTopology(
        &fresh_env,
        .optional_width_refinement,
    );
    try std.testing.expect(std.meta.eql(
        topology,
        try recordUpdateProjectionRelationTopology(&checked, .optional_width_refinement),
    ));

    failure_stage = "baseline contexts";
    const baseline = try expectRecordUpdateProjectionAvailabilityCheckedContexts(
        &checked,
        &fresh_env,
        topology,
    );
    const plans = checked.module_env.expected_consumption_plans.items.items;
    const saved_field_plan = plans[baseline.field_plan_index];
    const base_plan = plans[baseline.base_plan_index];
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerCopyOccurrenceSide.destination,
        base_plan.decodedProducedSide().?,
    );
    const Corruption = enum {
        raw,
        site_and_raw,
        slot,
        owner,
        role,
        parent,
        cause,
        predecessor,
        produced,
        call,
        source_retirement,
        retirement_backed_relation_failure,
        superseded_projection_failure_tuple,
    };
    inline for (std.enums.values(Corruption)) |corruption| {
        failure_stage = @tagName(corruption);
        const field_plan = &plans[baseline.field_plan_index];
        field_plan.* = saved_field_plan;
        defer field_plan.* = saved_field_plan;
        const tags_remain_legal = switch (corruption) {
            .raw => blk: {
                field_plan.raw_consumer_var = @intFromEnum(topology.tracked_literal_expr);
                break :blk false;
            },
            .site_and_raw => blk: {
                field_plan.site_node = @intFromEnum(topology.tracked_literal_expr);
                field_plan.raw_consumer_var = @intFromEnum(topology.tracked_literal_expr);
                break :blk true;
            },
            .slot => blk: {
                field_plan.slot = 1;
                break :blk true;
            },
            .owner => blk: {
                field_plan.owner_node = @intFromEnum(topology.base_expr);
                break :blk true;
            },
            .role => blk: {
                field_plan.role = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Role.record_field);
                break :blk false;
            },
            .parent => blk: {
                field_plan.parent_authority.payload.copy_occurrence.side = @intFromEnum(
                    ModuleEnv.WhereMarkerCopyOccurrenceSide.source,
                );
                break :blk true;
            },
            .cause => blk: {
                field_plan.failure_owner = ModuleEnv.CauseOwner.expectedFailure(0);
                break :blk false;
            },
            .predecessor => blk: {
                field_plan.failure_cause_plan_index = baseline.base_plan_index;
                break :blk false;
            },
            .produced => blk: {
                field_plan.produced_copy_step = base_plan.produced_copy_step;
                field_plan.produced_occurrence_offset = base_plan.produced_occurrence_offset;
                field_plan.produced_side = base_plan.produced_side;
                break :blk false;
            },
            .call => blk: {
                field_plan.call_root_plan_index = baseline.base_plan_index;
                break :blk false;
            },
            .source_retirement => blk: {
                field_plan.source_retirement_index_plus_one = 1;
                break :blk false;
            },
            .retirement_backed_relation_failure => blk: {
                field_plan.outcome = @intFromEnum(
                    ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error,
                );
                field_plan.reason = @intFromEnum(
                    ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_field_relation_rejected,
                );
                field_plan.failure_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(0);
                break :blk true;
            },
            .superseded_projection_failure_tuple => blk: {
                field_plan.outcome = @intFromEnum(
                    ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error,
                );
                field_plan.failure_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(0);
                break :blk false;
            },
        };
        try std.testing.expectEqual(tags_remain_legal, field_plan.hasLegalTags());
        try std.testing.expect(!validateExpectedRecordUpdatePlans(
            &checked.module_env.types,
            checked.module_env,
        ));

        field_plan.* = saved_field_plan;
        const restored = try expectRecordUpdateProjectionAvailabilityCheckedContexts(
            &checked,
            &fresh_env,
            topology,
        );
        try baseline.expectEqual(restored);
    }
}

test "record-update projection availability: rebuild and serialization preserve unavailable fields" {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    const module_name = "RecordUpdateProjectionAvailabilityRebuildSerde";
    var failure_stage: []const u8 = "checked source";
    errdefer std.debug.print(
        "record-update projection availability rebuild/serde test failed at {s}\n",
        .{failure_stage},
    );

    var checked = try TestEnv.init(module_name, record_update_projection_refinement_source);
    defer checked.deinit();
    try checked.assertNoErrors();
    try std.testing.expectEqual(@as(usize, 0), checked.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try checked.typeProblemCount());

    failure_stage = "distinct fresh source";
    var fresh_env = try TestEnv.initUncheckedWithAdmittedBuiltinForTesting(
        module_name,
        record_update_projection_refinement_source,
        checked.builtin_module,
        checked.builtin_validation,
        compiled_builtins.builtinIndices(CIR),
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{});
    const fresh_topology = try recordUpdateProjectionRelationTopology(
        &fresh_env,
        .optional_width_refinement,
    );
    try std.testing.expect(checked.module_env != fresh_env.module_env);
    try std.testing.expect(std.meta.eql(
        fresh_topology,
        try recordUpdateProjectionRelationTopology(&checked, .optional_width_refinement),
    ));

    failure_stage = "terminal baseline";
    const baseline_proof = try expectRecordUpdateProjectionAvailabilityCheckedContexts(
        &checked,
        &fresh_env,
        fresh_topology,
    );
    try std.testing.expect(validateExpectedRecordUpdatePlans(
        &checked.module_env.types,
        checked.module_env,
    ));
    try std.testing.expect(validateLocalW6bProof(
        &checked.module_env.types,
        checked.module_env,
    ));
    const canonical_baseline = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checked.module_env,
    );
    defer std.testing.allocator.free(canonical_baseline);

    failure_stage = "first repeated rebuild";
    try checked.checker.rebuildCheckedBoundaryWhereMethodState();
    const first_topology = try recordUpdateProjectionRelationTopology(
        &checked,
        .optional_width_refinement,
    );
    try std.testing.expect(std.meta.eql(fresh_topology, first_topology));
    const first_proof = try expectRecordUpdateProjectionAvailabilityCheckedContexts(
        &checked,
        &fresh_env,
        first_topology,
    );
    try baseline_proof.expectEqual(first_proof);
    const canonical_first = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checked.module_env,
    );
    defer std.testing.allocator.free(canonical_first);
    try std.testing.expectEqualSlices(u8, canonical_baseline, canonical_first);

    failure_stage = "second repeated rebuild";
    try checked.checker.rebuildCheckedBoundaryWhereMethodState();
    const second_topology = try recordUpdateProjectionRelationTopology(
        &checked,
        .optional_width_refinement,
    );
    try std.testing.expect(std.meta.eql(fresh_topology, second_topology));
    const second_proof = try expectRecordUpdateProjectionAvailabilityCheckedContexts(
        &checked,
        &fresh_env,
        second_topology,
    );
    try baseline_proof.expectEqual(second_proof);
    const canonical_second = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checked.module_env,
    );
    defer std.testing.allocator.free(canonical_second);
    try std.testing.expectEqualSlices(u8, canonical_baseline, canonical_second);

    failure_stage = "aligned serialization";
    const buffer = try serializeModuleEnvForDeserializationTest(
        std.testing.allocator,
        checked.module_env,
    );
    defer std.testing.allocator.free(buffer);
    try std.testing.expectEqualSlices(u8, canonical_baseline, buffer);
    const buffer_start = @intFromPtr(buffer.ptr);
    const buffer_end = std.math.add(usize, buffer_start, buffer.len) catch
        return error.TestUnexpectedResult;
    const serialized: *const ModuleEnv.Serialized = @ptrCast(@alignCast(buffer.ptr));
    try serialized.validate(buffer.len);

    failure_stage = "readonly deserialization";
    const readonly = try serialized.deserializeInto(
        buffer_start,
        std.testing.allocator,
        record_update_projection_refinement_source,
        module_name,
    );
    defer {
        readonly.imports.deinitMapOnly(std.testing.allocator);
        readonly.import_mapping.deinit();
        std.testing.allocator.destroy(readonly);
    }
    try std.testing.expect(!readonly.w6b_semantically_validated);
    try std.testing.expect(readonly != checked.module_env);
    try std.testing.expect(readonly != fresh_env.module_env);
    const readonly_plan_address = @intFromPtr(
        readonly.expected_consumption_plans.items.items.ptr,
    );
    const readonly_node_address = @intFromPtr(readonly.store.nodes.items.bytes);
    const readonly_type_address = @intFromPtr(
        readonly.types.slots.backing.items.items.ptr,
    );
    try std.testing.expect(readonly_plan_address >= buffer_start and
        readonly_plan_address < buffer_end);
    try std.testing.expect(readonly_node_address >= buffer_start and
        readonly_node_address < buffer_end);
    try std.testing.expect(readonly_type_address >= buffer_start and
        readonly_type_address < buffer_end);
    const readonly_proof = try expectRecordUpdateProjectionAvailabilityLocalAndFresh(
        readonly,
        fresh_env.module_env,
        checked.builtin_module.env,
        fresh_topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try baseline_proof.expectEqual(readonly_proof);
    const readonly_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        readonly,
    );
    defer std.testing.allocator.free(readonly_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, readonly_bytes);

    failure_stage = "mutable deserialization";
    const mutable = try serialized.deserializeWithMutableTypes(
        buffer_start,
        std.testing.allocator,
        record_update_projection_refinement_source,
        module_name,
    );
    defer {
        mutable.deinitCachedModule();
        std.testing.allocator.destroy(mutable);
    }
    try std.testing.expect(!mutable.w6b_semantically_validated);
    try std.testing.expect(mutable != checked.module_env);
    try std.testing.expect(mutable != fresh_env.module_env);
    try std.testing.expect(mutable != readonly);
    const mutable_plan_address = @intFromPtr(
        mutable.expected_consumption_plans.items.items.ptr,
    );
    const mutable_node_address = @intFromPtr(mutable.store.nodes.items.bytes);
    const mutable_type_address = @intFromPtr(
        mutable.types.slots.backing.items.items.ptr,
    );
    try std.testing.expect(mutable_plan_address < buffer_start or
        mutable_plan_address >= buffer_end);
    try std.testing.expectEqual(readonly_node_address, mutable_node_address);
    try std.testing.expect(mutable_node_address >= buffer_start and
        mutable_node_address < buffer_end);
    try std.testing.expect(mutable_type_address < buffer_start or
        mutable_type_address >= buffer_end);
    const mutable_proof = try expectRecordUpdateProjectionAvailabilityLocalAndFresh(
        mutable,
        fresh_env.module_env,
        checked.builtin_module.env,
        fresh_topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try baseline_proof.expectEqual(mutable_proof);
    try std.testing.expect(validateExpectedRecordUpdatePlans(&mutable.types, mutable));
    try std.testing.expect(validateLocalW6bProof(&mutable.types, mutable));
    const mutable_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        mutable,
    );
    defer std.testing.allocator.free(mutable_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, mutable_bytes);

    failure_stage = "mutable parent-authority isolation";
    const mutable_plans = mutable.expected_consumption_plans.items.items;
    {
        const saved_field_plan = mutable_plans[mutable_proof.field_plan_index];
        defer mutable_plans[mutable_proof.field_plan_index] = saved_field_plan;
        mutable_plans[mutable_proof.field_plan_index]
            .parent_authority.payload.copy_occurrence.side = @intFromEnum(
            ModuleEnv.WhereMarkerCopyOccurrenceSide.source,
        );
        const changed_field_plan = mutable_plans[mutable_proof.field_plan_index];
        try std.testing.expect(changed_field_plan.hasLegalTags());
        try std.testing.expect(!validateExpectedRecordUpdatePlans(&mutable.types, mutable));
        try std.testing.expect(!validateLocalW6bProof(&mutable.types, mutable));

        const original_during = try expectRecordUpdateProjectionAvailabilityLocalAndFresh(
            checked.module_env,
            fresh_env.module_env,
            checked.builtin_module.env,
            fresh_topology,
            recordUpdateRootAuthorityFreshContext(&fresh_env),
        );
        const readonly_during = try expectRecordUpdateProjectionAvailabilityLocalAndFresh(
            readonly,
            fresh_env.module_env,
            checked.builtin_module.env,
            fresh_topology,
            recordUpdateRootAuthorityFreshContext(&fresh_env),
        );
        try baseline_proof.expectEqual(original_during);
        try baseline_proof.expectEqual(readonly_during);
        try expectRecordUpdateProjectionAvailabilityTransientState(&checked.checker);
        try expectRecordUpdateProjectionAvailabilityProducedReplay(
            &checked.checker,
            checked.builtin_module.env,
        );
        try serialized.validate(buffer.len);
        try std.testing.expectEqualSlices(u8, canonical_baseline, buffer);

        const original_during_bytes = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            checked.module_env,
        );
        defer std.testing.allocator.free(original_during_bytes);
        const readonly_during_bytes = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            readonly,
        );
        defer std.testing.allocator.free(readonly_during_bytes);
        const mutable_corrupt_bytes = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            mutable,
        );
        defer std.testing.allocator.free(mutable_corrupt_bytes);
        try std.testing.expectEqualSlices(u8, canonical_baseline, original_during_bytes);
        try std.testing.expectEqualSlices(u8, canonical_baseline, readonly_during_bytes);
        try std.testing.expect(!std.mem.eql(u8, canonical_baseline, mutable_corrupt_bytes));
    }

    failure_stage = "mutable restoration";
    try std.testing.expect(validateExpectedRecordUpdatePlans(&mutable.types, mutable));
    try std.testing.expect(validateLocalW6bProof(&mutable.types, mutable));
    const mutable_restored = try expectRecordUpdateProjectionAvailabilityLocalAndFresh(
        mutable,
        fresh_env.module_env,
        checked.builtin_module.env,
        fresh_topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    const original_restored = try expectRecordUpdateProjectionAvailabilityLocalAndFresh(
        checked.module_env,
        fresh_env.module_env,
        checked.builtin_module.env,
        fresh_topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    const readonly_restored = try expectRecordUpdateProjectionAvailabilityLocalAndFresh(
        readonly,
        fresh_env.module_env,
        checked.builtin_module.env,
        fresh_topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try baseline_proof.expectEqual(mutable_restored);
    try baseline_proof.expectEqual(original_restored);
    try baseline_proof.expectEqual(readonly_restored);
    try expectRecordUpdateProjectionAvailabilityTransientState(&checked.checker);
    try expectRecordUpdateProjectionAvailabilityProducedReplay(
        &checked.checker,
        checked.builtin_module.env,
    );
    try serialized.validate(buffer.len);
    try std.testing.expectEqualSlices(u8, canonical_baseline, buffer);
    const mutable_restored_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        mutable,
    );
    defer std.testing.allocator.free(mutable_restored_bytes);
    const original_restored_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checked.module_env,
    );
    defer std.testing.allocator.free(original_restored_bytes);
    const readonly_restored_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        readonly,
    );
    defer std.testing.allocator.free(readonly_restored_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, mutable_restored_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, original_restored_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, readonly_restored_bytes);
}

const RecordUpdatePreexistingMalformedBaseTopology = struct {
    def_idx: CIR.Def.Idx,
    record_expr: CIR.Expr.Idx,
    base_expr: CIR.Expr.Idx,
    field_expr: CIR.Expr.Idx,
    base_diagnostic: CIR.Diagnostic.Idx,
    malformed_publication: ModuleEnv.MalformedExpressionPublication,
};

/// Decode the canonical unchecked source before checking rewrites the outer
/// record. The chained range is already a typed canonicalization-authored
/// malformed expression, while its enclosing record and numeric field remain
/// ordinary live expression nodes.
fn recordUpdatePreexistingMalformedBaseTopology(
    test_env: anytype,
) error{TestUnexpectedResult}!RecordUpdatePreexistingMalformedBaseTopology {
    var topology_stage: []const u8 = "root definition";
    errdefer std.debug.print(
        "preexisting malformed record-update topology failed at {s}\n",
        .{topology_stage},
    );
    const cir = test_env.module_env;
    const def_idx = test_env.can.explicitRootDefByName("main") orelse
        return error.TestUnexpectedResult;
    topology_stage = "live record owner";
    const record_expr = cir.store.getDef(def_idx).expr;
    const record = cir.store.getExpr(record_expr);
    if (record != .e_record or record.e_record.ext == null or
        cir.store.sliceUnsetFields(record.e_record.unsets).len != 0)
    {
        return error.TestUnexpectedResult;
    }
    topology_stage = "single healthy x field";
    const fields = cir.store.sliceRecordFields(record.e_record.fields);
    if (fields.len != 1) return error.TestUnexpectedResult;
    const field = cir.store.getRecordField(fields[0]);
    const field_expression = cir.store.getExpr(field.value);
    if (!std.mem.eql(u8, cir.getIdent(field.name), "x") or
        field_expression != .e_typed_int or
        !std.mem.eql(u8, cir.getIdent(field_expression.e_typed_int.type_name), "U8") or
        field_expression.e_typed_int.value.toI128() != 1)
    {
        return error.TestUnexpectedResult;
    }
    topology_stage = "chained-range malformed base";
    const base_expr = record.e_record.ext.?;
    const base_expression = cir.store.getExpr(base_expr);
    if (base_expression != .e_runtime_error or
        cir.store.getDiagnostic(base_expression.e_runtime_error.diagnostic) != .range_op_chained)
    {
        return error.TestUnexpectedResult;
    }
    topology_stage = "typed node phases";
    const base_node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(base_expr));
    if (base_node.tag != .malformed or
        cir.store.nodes.get(ModuleEnv.nodeIdxFrom(record_expr)).tag != .expr_record or
        !isExprNodeTag(cir.store.nodes.get(ModuleEnv.nodeIdxFrom(field.value)).tag))
    {
        return error.TestUnexpectedResult;
    }
    topology_stage = "singleton malformed publication";
    const publications = cir.malformed_expression_publications.items.items;
    if (publications.len != 1) return error.TestUnexpectedResult;
    const publication = publications[0];
    topology_stage = "malformed publication inverse";
    if (!publication.hasLegalTags() or
        publication.expr_node != @intFromEnum(base_expr) or
        publication.diagnostic_index != @intFromEnum(base_expression.e_runtime_error.diagnostic) or
        !malformedExpressionPublicationIsLocallyValid(cir, publication))
    {
        return error.TestUnexpectedResult;
    }
    return .{
        .def_idx = def_idx,
        .record_expr = record_expr,
        .base_expr = base_expr,
        .field_expr = field.value,
        .base_diagnostic = base_expression.e_runtime_error.diagnostic,
        .malformed_publication = publication,
    };
}

const RecordUpdateCheckedErrorBaseTopology = struct {
    def_idx: CIR.Def.Idx,
    annotation_idx: CIR.Annotation.Idx,
    where: CIR.WhereClause.Span,
    where_idx: CIR.WhereClause.Idx,
    owner_expr: CIR.Expr.Idx,
    lambda_expr: CIR.Expr.Idx,
    pattern_idx: CIR.Pattern.Idx,
    formal_var: Var,
    record_expr: CIR.Expr.Idx,
    base_expr: CIR.Expr.Idx,
};

fn recordUpdateCheckedErrorBaseTopology(
    test_env: anytype,
) error{TestUnexpectedResult}!RecordUpdateCheckedErrorBaseTopology {
    const cir = test_env.module_env;
    const def_idx = test_env.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const def = cir.store.getDef(def_idx);
    const annotation_idx = def.annotation orelse return error.TestUnexpectedResult;
    const annotation = cir.store.getAnnotation(annotation_idx);
    const where = annotation.where orelse return error.TestUnexpectedResult;
    const clauses = cir.store.sliceWhereClauses(where);
    if (clauses.len != 1) return error.TestUnexpectedResult;
    const where_idx = clauses[0];
    const clause = cir.store.getWhereClause(where_idx);
    if (clause != .w_alias or cir.store.getTypeAnno(clause.w_alias.alias) != .malformed) {
        return error.TestUnexpectedResult;
    }
    const annotation_fn = cir.store.getTypeAnno(annotation.anno);
    if (annotation_fn != .@"fn") return error.TestUnexpectedResult;
    const formals = cir.store.sliceTypeAnnos(annotation_fn.@"fn".args);
    if (formals.len != 1 or cir.store.getTypeAnno(formals[0]) != .rigid_var) {
        return error.TestUnexpectedResult;
    }
    const result = cir.store.getTypeAnno(annotation_fn.@"fn".ret);
    if (result != .rigid_var_lookup or result.rigid_var_lookup.ref != formals[0]) {
        return error.TestUnexpectedResult;
    }
    const receiver = cir.store.getTypeAnno(clause.w_alias.var_);
    if (receiver != .rigid_var_lookup or receiver.rigid_var_lookup.ref != formals[0]) {
        return error.TestUnexpectedResult;
    }
    var matching_owner_count: usize = 0;
    var matching_clause_count: usize = 0;
    for (cir.store.sliceWhereClauseOwners(where)) |where_owner| {
        if (!where_owner.owned_by_annotation or
            where_owner.rigid_var != @intFromEnum(formals[0]))
        {
            continue;
        }
        matching_owner_count += 1;
        for (cir.store.sliceWhereClausesForOwner(where_owner)) |owned_where| {
            if (owned_where == where_idx) matching_clause_count += 1;
        }
    }
    if (matching_owner_count != 1 or matching_clause_count != 1) {
        return error.TestUnexpectedResult;
    }
    const lambda = cir.store.getExpr(def.expr);
    if (lambda != .e_lambda) return error.TestUnexpectedResult;
    const patterns = cir.store.slicePatterns(lambda.e_lambda.args);
    if (patterns.len != 1 or cir.store.getPattern(patterns[0]) != .assign) {
        return error.TestUnexpectedResult;
    }
    const record_expr = lambda.e_lambda.body;
    const record = cir.store.getExpr(record_expr);
    if (record != .e_record or record.e_record.ext == null) {
        return error.TestUnexpectedResult;
    }
    const base_expr = record.e_record.ext.?;
    const base_expression = cir.store.getExpr(base_expr);
    if (base_expression != .e_lookup_local or
        base_expression.e_lookup_local.pattern_idx != patterns[0])
    {
        return error.TestUnexpectedResult;
    }
    return .{
        .def_idx = def_idx,
        .annotation_idx = annotation_idx,
        .where = where,
        .where_idx = where_idx,
        .owner_expr = def.expr,
        .lambda_expr = def.expr,
        .pattern_idx = patterns[0],
        .formal_var = ModuleEnv.varFrom(formals[0]),
        .record_expr = record_expr,
        .base_expr = base_expr,
    };
}

const RecordUpdateDirectBinderOwnerTopology = struct {
    def_idx: CIR.Def.Idx,
    annotation_idx: CIR.Annotation.Idx,
    where: CIR.WhereClause.Span,
    where_idx: CIR.WhereClause.Idx,
    owner_expr: CIR.Expr.Idx,
    lambda_expr: CIR.Expr.Idx,
    pattern_idx: CIR.Pattern.Idx,
    formal_var: Var,
    record_expr: CIR.Expr.Idx,
    base_expr: CIR.Expr.Idx,
    field_expr: CIR.Expr.Idx,
};

fn recordUpdateDirectBinderOwnerTopology(
    test_env: anytype,
) error{TestUnexpectedResult}!RecordUpdateDirectBinderOwnerTopology {
    const common = try recordUpdateCheckedErrorBaseTopology(test_env);
    const cir = test_env.module_env;
    const record = cir.store.getExpr(common.record_expr);
    if (record != .e_record or
        cir.store.sliceUnsetFields(record.e_record.unsets).len != 0)
    {
        return error.TestUnexpectedResult;
    }
    const fields = cir.store.sliceRecordFields(record.e_record.fields);
    if (fields.len != 1) return error.TestUnexpectedResult;
    const field = cir.store.getRecordField(fields[0]);
    if (!std.mem.eql(u8, cir.getIdent(field.name), "x")) {
        return error.TestUnexpectedResult;
    }
    return .{
        .def_idx = common.def_idx,
        .annotation_idx = common.annotation_idx,
        .where = common.where,
        .where_idx = common.where_idx,
        .owner_expr = common.owner_expr,
        .lambda_expr = common.lambda_expr,
        .pattern_idx = common.pattern_idx,
        .formal_var = common.formal_var,
        .record_expr = common.record_expr,
        .base_expr = common.base_expr,
        .field_expr = field.value,
    };
}

fn recordUpdateCheckedErrorBaseTopologyFromOwner(
    topology: RecordUpdateDirectBinderOwnerTopology,
) RecordUpdateCheckedErrorBaseTopology {
    return .{
        .def_idx = topology.def_idx,
        .annotation_idx = topology.annotation_idx,
        .where = topology.where,
        .where_idx = topology.where_idx,
        .owner_expr = topology.owner_expr,
        .lambda_expr = topology.lambda_expr,
        .pattern_idx = topology.pattern_idx,
        .formal_var = topology.formal_var,
        .record_expr = topology.record_expr,
        .base_expr = topology.base_expr,
    };
}

const RecordUpdateBaseRootSelectionProof = struct {
    step_index: u32,
    root_occurrence_index: u32,
    selected_raw_root: u32,
    selected_canonical_root: u32,
};

const PendingRecordUpdateOwnerCompletionProof = struct {
    draft: RecordUpdateOwnerRetirementDraft,
    plans: RecordUpdateOwnerPlanPair,
    base_plan: ModuleEnv.ExpectedConsumptionPlan,
    field_plan: ModuleEnv.ExpectedConsumptionPlan,
    source_retirement: ModuleEnv.ExpectedConsumerRetirement,
    source_retirement_index: u32,
    owner_retirement: ModuleEnv.ExpectedConsumerRetirement,
    root_selection: RecordUpdateBaseRootSelectionProof,

    fn expectEquivalent(
        self: @This(),
        actual: @This(),
    ) !void {
        try expectRecordUpdateOwnerRetirementDraftsEqual(
            &.{self.draft},
            &.{actual.draft},
        );
        try std.testing.expect(std.meta.eql(self.plans, actual.plans));
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&self.base_plan),
            std.mem.asBytes(&actual.base_plan),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&self.field_plan),
            std.mem.asBytes(&actual.field_plan),
        );
        try std.testing.expectEqual(self.source_retirement_index, actual.source_retirement_index);
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&self.source_retirement),
            std.mem.asBytes(&actual.source_retirement),
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.asBytes(&self.owner_retirement),
            std.mem.asBytes(&actual.owner_retirement),
        );
        try std.testing.expect(std.meta.eql(self.root_selection, actual.root_selection));
    }
};

fn expectPendingRecordUpdateOwnerCompletion(
    checker: *const Self,
    topology: RecordUpdateDirectBinderOwnerTopology,
) !PendingRecordUpdateOwnerCompletionProof {
    const cir = checker.cir;
    var failure_stage: []const u8 = "node phases";
    errdefer std.debug.print(
        "pending record-update completion proof failed at {s}\n",
        .{failure_stage},
    );
    try std.testing.expect(cir.store.getExpr(topology.record_expr) == .e_record);
    try std.testing.expect(cir.store.getExpr(topology.base_expr) == .e_runtime_error);
    try std.testing.expect(isExprNodeTag(
        cir.store.nodes.get(ModuleEnv.nodeIdxFrom(topology.field_expr)).tag,
    ));
    try std.testing.expect(checker.erroneous_value_exprs.contains(topology.record_expr));
    try std.testing.expectEqual(@as(u32, 0), checker.probe_depth);

    failure_stage = "direct-binder and owner identities";
    const draft = try uniqueRecordUpdateOwnerRetirementDraft(checker, topology.record_expr);
    const plans = try uniqueRecordUpdateOwnerPlanPair(cir, topology.record_expr);
    try std.testing.expectEqual(plans.base, draft.base_plan_index);
    try std.testing.expect(recordUpdateOwnerExpectedMembershipAtProducer(
        checker,
        topology.record_expr,
        draft.base_plan_index,
        draft.base_cause,
    ));
    try std.testing.expect(validateRecordUpdateExpectedPlanRegistrations(checker));

    failure_stage = "base plan";
    const base_plan = cir.expected_consumption_plans.items.items[plans.base];
    const field_plan = cir.expected_consumption_plans.items.items[plans.field];
    try std.testing.expect(base_plan.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Role.record_update_base,
        base_plan.decodedRole().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Outcome.source_root_copy_checked_error,
        base_plan.decodedOutcome().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_base_checked_error,
        base_plan.decodedReason().?,
    );
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), base_plan.owner_node);
    try std.testing.expectEqual(@intFromEnum(topology.base_expr), base_plan.site_node);
    try std.testing.expectEqual(@as(u32, 0), base_plan.slot);
    try std.testing.expectEqual(@intFromEnum(topology.base_expr), base_plan.raw_consumer_var);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.none,
        base_plan.failure_cause_plan_index,
    );
    try std.testing.expect(expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    try std.testing.expect(expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
        cir,
        base_plan,
    ));
    const source_retirement_index = base_plan.decodedSourceRetirementIndex() orelse
        return error.TestUnexpectedResult;
    const lookup_failure_index = completedDirectBinderLookupFailureForRetirement(
        cir,
        source_retirement_index,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(directBinderLookupFailureHasBasicRetirementIdentity(
        cir,
        source_retirement_index,
        lookup_failure_index,
    ));
    const lookup_failure = cir.expected_failures.items.items[lookup_failure_index];
    const lookup_direct = lookup_failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    const annotation_retirement = lookup_failure.cause_owner.decodedExpectedConsumerRetirement() orelse
        return error.TestUnexpectedResult;
    if (annotation_retirement.index >= cir.expected_consumer_retirements.items.items.len or
        lookup_direct.local_record_index >= cir.expected_failures.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const annotation_retirement_row = cir.expected_consumer_retirements.items.items[
        annotation_retirement.index
    ];
    const annotation_failure = cir.expected_failures.items.items[
        lookup_direct.local_record_index
    ];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
        annotation_failure.decodedKind().?,
    );
    try std.testing.expectEqual(@as(usize, 1), checker.annotation_expected_failure_drafts.items.len);
    const annotation_draft = checker.annotation_expected_failure_drafts.items[0];
    try std.testing.expectEqual(
        annotation_retirement_row.retired_node,
        @intFromEnum(annotation_draft.owner_expr),
    );
    try std.testing.expectEqual(annotation_retirement.index, annotation_draft.retirement_index);
    try std.testing.expectEqual(lookup_direct.local_record_index, annotation_draft.failure_index);
    try std.testing.expectEqual(
        AnnotationExpectedFailureDraft.ProducerKind.annotation,
        annotation_draft.producer_kind,
    );
    try std.testing.expectEqual(@as(usize, 0), checker.aggregate_expected_retirement_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.direct_formal_failure_sources.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
    try std.testing.expect(expectedCauseOwnersEqual(
        base_plan.failure_owner,
        ModuleEnv.CauseOwner.expectedConsumerRetirement(source_retirement_index),
    ));
    try std.testing.expect(expectedCauseOwnersEqual(draft.base_cause, base_plan.failure_owner));

    failure_stage = "field plan";
    try std.testing.expect(field_plan.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Role.record_update_field,
        field_plan.decodedRole().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error,
        field_plan.decodedOutcome().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_field_base_checked_error,
        field_plan.decodedReason().?,
    );
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), field_plan.owner_node);
    try std.testing.expectEqual(@intFromEnum(topology.field_expr), field_plan.site_node);
    try std.testing.expectEqual(@as(u32, 0), field_plan.slot);
    try std.testing.expectEqual(plans.base, field_plan.failure_cause_plan_index);
    try std.testing.expect(expectedCauseOwnersEqual(base_plan.failure_owner, field_plan.failure_owner));
    try std.testing.expect(expectedFreshShapePlanMatchesCir(cir, field_plan));
    const base_authority = expectedRecordUpdateBaseAuthority(base_plan) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(expectedRecordUpdateFieldBeginsAtBase(
        cir,
        plans.field,
        field_plan,
        base_authority,
    ));

    failure_stage = "base copy root";
    if (base_plan.produced_copy_step >= cir.where_marker_copy_steps.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const step = cir.where_marker_copy_steps.items.items[base_plan.produced_copy_step];
    const origin = step.origin.record_update_base;
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), origin.record_expr);
    try std.testing.expectEqual(@intFromEnum(topology.base_expr), origin.base_expr);
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerRecordUpdateBaseOrigin.RootBinding.redirected_identity_share,
        origin.decodedRootBinding().?,
    );
    try std.testing.expectEqual(step.root_occurrence_offset, base_plan.produced_occurrence_offset);
    if (!rangeFits(
        step.occurrences_start,
        step.occurrences_len,
        cir.where_marker_copy_occurrences.items.items.len,
    ) or !rangeFits(
        step.pairs_start,
        step.pairs_len,
        cir.where_marker_copy_pairs.items.items.len,
    ) or step.root_occurrence_offset >= step.occurrences_len) {
        return error.TestUnexpectedResult;
    }
    const root_occurrence_index = step.occurrences_start + step.root_occurrence_offset;
    const root_occurrence = cir.where_marker_copy_occurrences.items.items[root_occurrence_index];
    if (root_occurrence.canonical_pair_offset >= step.pairs_len) {
        return error.TestUnexpectedResult;
    }
    const root_pair = cir.where_marker_copy_pairs.items.items[
        step.pairs_start + root_occurrence.canonical_pair_offset
    ];
    try std.testing.expect(base_plan.raw_consumer_var != root_occurrence.raw_source_var);
    try std.testing.expectEqual(root_occurrence.raw_source_var, root_occurrence.raw_destination_var);
    try std.testing.expectEqual(root_pair.source_var, root_pair.destination_var);
    try std.testing.expectEqual(step.source_root_var, root_pair.source_var);
    try std.testing.expectEqual(step.destination_root_var, root_pair.destination_var);
    const current_requested_root = cir.types.resolveVar(
        @enumFromInt(base_plan.raw_consumer_var),
    ).var_;
    const current_occurrence_root = cir.types.resolveVar(
        @enumFromInt(root_occurrence.raw_source_var),
    ).var_;
    const current_selected_root = cir.types.resolveVar(
        @enumFromInt(root_pair.source_var),
    ).var_;
    try std.testing.expectEqual(current_requested_root, current_occurrence_root);
    try std.testing.expectEqual(current_requested_root, current_selected_root);
    try std.testing.expect(
        @intFromEnum(current_selected_root) != root_pair.source_var,
    );

    failure_stage = "source retirement";
    if (source_retirement_index >= cir.expected_consumer_retirements.items.items.len or
        draft.retirement_index >= cir.expected_consumer_retirements.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const source_retirement = cir.expected_consumer_retirements.items.items[
        source_retirement_index
    ];
    try std.testing.expect(source_retirement.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        source_retirement.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(topology.base_expr), source_retirement.retired_node);
    const base_expression = cir.store.getExpr(topology.base_expr);
    try std.testing.expectEqual(
        @intFromEnum(base_expression.e_runtime_error.diagnostic),
        source_retirement.diagnostic_index,
    );

    failure_stage = "pending owner retirement";
    const owner_retirement = cir.expected_consumer_retirements.items.items[
        draft.retirement_index
    ];
    try std.testing.expect(draft.retirement_index != source_retirement_index);
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), owner_retirement.retired_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression,
        owner_retirement.decodedOwnerKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_expected,
        owner_retirement.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(CIR.Node.Tag.expr_record), draft.original_node_tag);
    try std.testing.expectEqual(draft.original_node_tag, owner_retirement.original_node_tag);
    try std.testing.expectEqualSlices(
        u32,
        &draft.original_payload,
        &owner_retirement.original_payload,
    );
    try std.testing.expect(pendingExpectedConsumerRetirementHasCanonicalInactiveWords(
        owner_retirement,
    ));
    try std.testing.expectEqual(
        draft.retirement_index,
        pendingExpressionRetirementAtProducer(checker, topology.record_expr).?,
    );

    failure_stage = "registered membership";
    var owner_registration_count: usize = 0;
    for (checker.record_update_expected_plan_registrations.items) |registration| {
        if (registration.owner_expr != topology.record_expr) continue;
        owner_registration_count += 1;
        switch (registration.role) {
            .record_update_base => {
                try std.testing.expectEqual(plans.base, registration.plan_index);
                try std.testing.expectEqual(@as(u32, 0), registration.slot);
                try std.testing.expectEqual(topology.base_expr, registration.site);
            },
            .record_update_field => {
                try std.testing.expectEqual(plans.field, registration.plan_index);
                try std.testing.expectEqual(@as(u32, 0), registration.slot);
                try std.testing.expectEqual(topology.field_expr, registration.site);
            },
            else => return error.TestUnexpectedResult,
        }
    }
    try std.testing.expectEqual(@as(usize, 2), owner_registration_count);
    try std.testing.expect(!checker.record_update_expected_plan_registrations_consumed);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.items.len);

    return .{
        .draft = draft,
        .plans = plans,
        .base_plan = base_plan,
        .field_plan = field_plan,
        .source_retirement = source_retirement,
        .source_retirement_index = source_retirement_index,
        .owner_retirement = owner_retirement,
        .root_selection = .{
            .step_index = base_plan.produced_copy_step,
            .root_occurrence_index = root_occurrence_index,
            .selected_raw_root = root_occurrence.raw_source_var,
            .selected_canonical_root = root_pair.source_var,
        },
    };
}

const StagedRecordUpdateOwnerCompletion = struct {
    env: Env,
    topology: RecordUpdateDirectBinderOwnerTopology,
    diagnostic: CIR.Diagnostic.Idx,
    pending: PendingRecordUpdateOwnerCompletionProof,
};

fn stageRecordUpdateOwnerCompletionThroughLeafPoison(
    test_env: anytype,
) !StagedRecordUpdateOwnerCompletion {
    const topology = try recordUpdateDirectBinderOwnerTopology(test_env);
    const env = try stageDirectBinderCallPairThroughPrePoison(test_env);
    errdefer test_env.checker.env_pool.release(env);
    try test_env.checker.poisonErroneousValueUses();
    const pending = try expectPendingRecordUpdateOwnerCompletion(
        &test_env.checker,
        topology,
    );
    const diagnostic = try test_env.module_env.addDiagnostic(.{ .erroneous_value_expr = .{
        .region = test_env.module_env.store.getExprRegion(topology.record_expr),
    } });
    const diagnostic_value = test_env.module_env.store.getDiagnostic(diagnostic);
    if (diagnostic_value != .erroneous_value_expr or !std.meta.eql(
        test_env.module_env.store.getExprRegion(topology.record_expr),
        diagnostic_value.erroneous_value_expr.region,
    )) return error.TestUnexpectedResult;
    return .{
        .env = env,
        .topology = topology,
        .diagnostic = diagnostic,
        .pending = pending,
    };
}

fn expectRecordUpdateOwnerCompletionCommitted(
    checker: *const Self,
    stage: StagedRecordUpdateOwnerCompletion,
) !RetiredRecordUpdateOwnerSnapshot {
    const cir = checker.cir;
    try std.testing.expect(cir.store.getExpr(stage.topology.record_expr) == .e_runtime_error);
    try std.testing.expect(cir.store.getExpr(stage.topology.base_expr) == .e_runtime_error);
    const record = cir.store.getExpr(stage.topology.record_expr);
    try std.testing.expectEqual(stage.diagnostic, record.e_runtime_error.diagnostic);
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&stage.pending.base_plan),
        std.mem.asBytes(&cir.expected_consumption_plans.items.items[stage.pending.plans.base]),
    );
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&stage.pending.field_plan),
        std.mem.asBytes(&cir.expected_consumption_plans.items.items[stage.pending.plans.field]),
    );
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&stage.pending.source_retirement),
        std.mem.asBytes(&cir.expected_consumer_retirements.items.items[
            stage.pending.source_retirement_index
        ]),
    );
    const completed = try expectCompletedRecordUpdateOwnerPair(
        cir,
        stage.topology.record_expr,
        stage.topology.base_expr,
        stage.topology.field_expr,
    );
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(stage.pending.draft.retirement_index, completed.retirement_index);
    try std.testing.expectEqual(@intFromEnum(stage.diagnostic), completed.retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), completed.retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), completed.retirement.expected_failures_len);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.none,
        completed.retirement.rejection_owner_kind,
    );
    var expected_retirement = stage.pending.owner_retirement;
    expected_retirement.retired_consumers_start = 0;
    expected_retirement.retired_consumers_len = 2;
    expected_retirement.diagnostic_index = @intFromEnum(stage.diagnostic);
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&expected_retirement),
        std.mem.asBytes(&completed.retirement),
    );
    var expected_consumers = [2]ModuleEnv.ExpectedRetiredConsumer{
        .{
            .plan_index = stage.pending.plans.base,
            .owner_node = stage.pending.base_plan.owner_node,
            .site_node = stage.pending.base_plan.site_node,
            .role = stage.pending.base_plan.role,
            .slot = stage.pending.base_plan.slot,
            .raw_owner_var = @intFromEnum(stage.topology.record_expr),
            .raw_consumer_var = stage.pending.base_plan.raw_consumer_var,
            .reason = @intFromEnum(
                ModuleEnv.ExpectedRetiredConsumer.RetirementOnlyReason.record_update_retired_after_base_checked_error,
            ),
        },
        .{
            .plan_index = stage.pending.plans.field,
            .owner_node = stage.pending.field_plan.owner_node,
            .site_node = stage.pending.field_plan.site_node,
            .role = stage.pending.field_plan.role,
            .slot = stage.pending.field_plan.slot,
            .raw_owner_var = @intFromEnum(stage.topology.record_expr),
            .raw_consumer_var = stage.pending.field_plan.raw_consumer_var,
            .reason = @intFromEnum(
                ModuleEnv.ExpectedRetiredConsumer.RetirementOnlyReason.record_update_retired_after_base_checked_error,
            ),
        },
    };
    std.mem.sortUnstable(
        ModuleEnv.ExpectedRetiredConsumer,
        &expected_consumers,
        {},
        expectedRetiredConsumerLessThan,
    );
    try std.testing.expectEqualSlices(
        u8,
        std.mem.sliceAsBytes(&expected_consumers),
        std.mem.sliceAsBytes(cir.expected_retired_consumers.items.items),
    );
    try std.testing.expectEqual(@as(usize, 0), checker.record_update_owner_retirement_drafts.items.len);
    try std.testing.expect(!checker.record_update_expected_plan_registrations_consumed);
    try std.testing.expect(validateRecordUpdateExpectedPlanRegistrations(checker));
    return completed;
}

fn finishRecordUpdateOwnerCompletionTest(
    test_env: anytype,
    fresh_env: anytype,
    stage: *StagedRecordUpdateOwnerCompletion,
) ![]u8 {
    const checker = &test_env.checker;
    const cir = checker.cir;
    try checker.checkFileFromPrePoison(&stage.env);
    _ = try expectCompletedRecordUpdateOwnerPair(
        cir,
        stage.topology.record_expr,
        stage.topology.base_expr,
        stage.topology.field_expr,
    );
    const lookup = try uniqueDirectBinderLookupTestProof(cir);
    const plans = try uniqueRecordUpdateOwnerPlanPair(cir, stage.topology.record_expr);
    try std.testing.expectEqual(
        lookup.lookup_retirement_index,
        cir.expected_consumption_plans.items.items[plans.base].decodedSourceRetirementIndex().?,
    );
    try expectDirectBinderTransientListsEmpty(checker);
    try std.testing.expect(checker.record_update_expected_plan_registrations_consumed);
    try std.testing.expectEqual(
        @as(usize, 0),
        checker.record_update_expected_plan_registrations.items.len,
    );
    try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
    const context = recordUpdateRootAuthorityFreshContext(fresh_env);
    try validateExpectedFailureContext(cir, context);
    try validateWhereMarkerCopySourceNamespaces(cir, test_env.builtin_module.env, context);
    _ = try checker.validatedModule();
    try std.testing.expectEqual(@as(usize, 0), checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try test_env.typeProblemCount());
    return serializeModuleEnvForCanonicalComparison(std.testing.allocator, cir);
}

const record_update_unset_only_owner_retirement_source =
    \\import RecordUpdateUnsetOnlyOwnerA exposing [Status]
    \\
    \\first : a -> a where [a.Status]
    \\first = |value| { ..value, x: _ }
;

const RecordUpdateUnsetOnlyOwnerTopology = struct {
    producer: RecordUpdateCheckedErrorBaseTopology,
    record_expr: CIR.Expr.Idx,
    lookup_expr: CIR.Expr.Idx,
    unset_field: CIR.UnsetField.Idx,
};

fn recordUpdateUnsetOnlyOwnerTopology(
    test_env: anytype,
) error{TestUnexpectedResult}!RecordUpdateUnsetOnlyOwnerTopology {
    const producer = try recordUpdateCheckedErrorBaseTopology(test_env);
    const cir = test_env.module_env;
    const record = cir.store.getExpr(producer.record_expr);
    if (record != .e_record or
        cir.store.sliceRecordFields(record.e_record.fields).len != 0)
    {
        return error.TestUnexpectedResult;
    }
    const unsets = cir.store.sliceUnsetFields(record.e_record.unsets);
    if (unsets.len != 1) return error.TestUnexpectedResult;
    if (!std.mem.eql(u8, cir.getIdent(cir.store.getUnsetField(unsets[0]).name), "x")) {
        return error.TestUnexpectedResult;
    }
    return .{
        .producer = producer,
        .record_expr = producer.record_expr,
        .lookup_expr = producer.base_expr,
        .unset_field = unsets[0],
    };
}

const record_update_interleaved_owner_retirement_source =
    \\import RecordUpdateInterleavedOwnerA exposing [Status]
    \\
    \\first : a -> a where [a.Status]
    \\first = |value| {
    \\    ..value,
    \\    a: { ..{ seed: 1.U8 }, seed: 2.U8 },
    \\    z: 3.U8,
    \\}
;

const RecordUpdateInterleavedOwnerTopology = struct {
    outer_expr: CIR.Expr.Idx,
    lookup_expr: CIR.Expr.Idx,
    nested_expr: CIR.Expr.Idx,
    nested_base_expr: CIR.Expr.Idx,
    nested_field_expr: CIR.Expr.Idx,
    outer_after_expr: CIR.Expr.Idx,
};

fn recordUpdateInterleavedOwnerTopology(
    test_env: anytype,
) error{TestUnexpectedResult}!RecordUpdateInterleavedOwnerTopology {
    const cir = test_env.module_env;
    const def_idx = test_env.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const def = cir.store.getDef(def_idx);
    const lambda = cir.store.getExpr(def.expr);
    if (lambda != .e_lambda) return error.TestUnexpectedResult;
    const patterns = cir.store.slicePatterns(lambda.e_lambda.args);
    if (patterns.len != 1 or cir.store.getPattern(patterns[0]) != .assign) {
        return error.TestUnexpectedResult;
    }
    const outer_expr = lambda.e_lambda.body;
    const outer = cir.store.getExpr(outer_expr);
    if (outer != .e_record or outer.e_record.ext == null or
        cir.store.sliceUnsetFields(outer.e_record.unsets).len != 0)
    {
        return error.TestUnexpectedResult;
    }
    const outer_fields = cir.store.sliceRecordFields(outer.e_record.fields);
    if (outer_fields.len != 2) return error.TestUnexpectedResult;
    const first_field = cir.store.getRecordField(outer_fields[0]);
    const second_field = cir.store.getRecordField(outer_fields[1]);
    if (!std.mem.eql(u8, cir.getIdent(first_field.name), "a") or
        !std.mem.eql(u8, cir.getIdent(second_field.name), "z"))
    {
        return error.TestUnexpectedResult;
    }
    const lookup_expr = outer.e_record.ext.?;
    const lookup = cir.store.getExpr(lookup_expr);
    if (lookup != .e_lookup_local or lookup.e_lookup_local.pattern_idx != patterns[0]) {
        return error.TestUnexpectedResult;
    }
    const nested_expr = first_field.value;
    const nested = cir.store.getExpr(nested_expr);
    if (nested != .e_record or nested.e_record.ext == null or
        cir.store.sliceUnsetFields(nested.e_record.unsets).len != 0)
    {
        return error.TestUnexpectedResult;
    }
    const nested_fields = cir.store.sliceRecordFields(nested.e_record.fields);
    if (nested_fields.len != 1) return error.TestUnexpectedResult;
    const nested_field = cir.store.getRecordField(nested_fields[0]);
    if (!std.mem.eql(u8, cir.getIdent(nested_field.name), "seed")) {
        return error.TestUnexpectedResult;
    }
    const nested_base_expr = nested.e_record.ext.?;
    const nested_base = cir.store.getExpr(nested_base_expr);
    if (nested_base != .e_record or nested_base.e_record.ext != null or
        cir.store.sliceUnsetFields(nested_base.e_record.unsets).len != 0)
    {
        return error.TestUnexpectedResult;
    }
    const nested_base_fields = cir.store.sliceRecordFields(nested_base.e_record.fields);
    if (nested_base_fields.len != 1 or
        !std.mem.eql(
            u8,
            cir.getIdent(cir.store.getRecordField(nested_base_fields[0]).name),
            "seed",
        ))
    {
        return error.TestUnexpectedResult;
    }
    return .{
        .outer_expr = outer_expr,
        .lookup_expr = lookup_expr,
        .nested_expr = nested_expr,
        .nested_base_expr = nested_base_expr,
        .nested_field_expr = nested_field.value,
        .outer_after_expr = second_field.value,
    };
}

const nested_record_update_owner_retirement_source =
    \\import RecordUpdateNestedOwnerA exposing [Status]
    \\
    \\first : a -> a where [a.Status]
    \\first = |value| { ..({ ..value, inner: 1.U8 }), outer: 2.U8 }
;

const NestedRecordUpdateOwnerTopology = struct {
    outer_expr: CIR.Expr.Idx,
    inner_expr: CIR.Expr.Idx,
    lookup_expr: CIR.Expr.Idx,
    outer_field_expr: CIR.Expr.Idx,
    inner_field_expr: CIR.Expr.Idx,
};

fn nestedRecordUpdateOwnerTopology(
    test_env: anytype,
) error{TestUnexpectedResult}!NestedRecordUpdateOwnerTopology {
    const cir = test_env.module_env;
    const def_idx = test_env.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const def = cir.store.getDef(def_idx);
    const lambda = cir.store.getExpr(def.expr);
    if (lambda != .e_lambda) return error.TestUnexpectedResult;
    const patterns = cir.store.slicePatterns(lambda.e_lambda.args);
    if (patterns.len != 1 or cir.store.getPattern(patterns[0]) != .assign) {
        return error.TestUnexpectedResult;
    }
    const outer_expr = lambda.e_lambda.body;
    const outer = cir.store.getExpr(outer_expr);
    if (outer != .e_record or outer.e_record.ext == null) {
        return error.TestUnexpectedResult;
    }
    const outer_fields = cir.store.sliceRecordFields(outer.e_record.fields);
    if (outer_fields.len != 1 or cir.store.sliceUnsetFields(outer.e_record.unsets).len != 0) {
        return error.TestUnexpectedResult;
    }
    const inner_expr = outer.e_record.ext.?;
    const inner = cir.store.getExpr(inner_expr);
    if (inner != .e_record or inner.e_record.ext == null) {
        return error.TestUnexpectedResult;
    }
    const inner_fields = cir.store.sliceRecordFields(inner.e_record.fields);
    if (inner_fields.len != 1 or cir.store.sliceUnsetFields(inner.e_record.unsets).len != 0) {
        return error.TestUnexpectedResult;
    }
    const lookup_expr = inner.e_record.ext.?;
    const lookup = cir.store.getExpr(lookup_expr);
    if (lookup != .e_lookup_local or lookup.e_lookup_local.pattern_idx != patterns[0]) {
        return error.TestUnexpectedResult;
    }
    return .{
        .outer_expr = outer_expr,
        .inner_expr = inner_expr,
        .lookup_expr = lookup_expr,
        .outer_field_expr = cir.store.getRecordField(outer_fields[0]).value,
        .inner_field_expr = cir.store.getRecordField(inner_fields[0]).value,
    };
}

const RecordUpdateOwnerPlanPair = struct {
    base: u32,
    field: u32,
};

fn uniqueRecordUpdateOwnerPlanPair(
    cir: *const ModuleEnv,
    owner_expr: CIR.Expr.Idx,
) error{TestUnexpectedResult}!RecordUpdateOwnerPlanPair {
    var base_plan: ?u32 = null;
    var field_plan: ?u32 = null;
    for (cir.expected_consumption_plans.items.items, 0..) |plan, plan_index| {
        if (plan.owner_node != @intFromEnum(owner_expr)) continue;
        switch (plan.decodedRole() orelse return error.TestUnexpectedResult) {
            .record_update_base => {
                if (base_plan != null) return error.TestUnexpectedResult;
                base_plan = @intCast(plan_index);
            },
            .record_update_field => {
                if (field_plan != null) return error.TestUnexpectedResult;
                field_plan = @intCast(plan_index);
            },
            else => return error.TestUnexpectedResult,
        }
    }
    return .{
        .base = base_plan orelse return error.TestUnexpectedResult,
        .field = field_plan orelse return error.TestUnexpectedResult,
    };
}

const RecordUpdateOwnerPlanSet = struct {
    base: u32,
    fields: [2]u32,
    fields_len: u32,
};

fn uniqueRecordUpdateOwnerPlanSet(
    cir: *const ModuleEnv,
    owner_expr: CIR.Expr.Idx,
    expected_fields_len: u32,
) error{TestUnexpectedResult}!RecordUpdateOwnerPlanSet {
    if (expected_fields_len > 2) return error.TestUnexpectedResult;
    const none = ModuleEnv.ExpectedConsumptionPlan.none;
    var result = RecordUpdateOwnerPlanSet{
        .base = none,
        .fields = .{ none, none },
        .fields_len = expected_fields_len,
    };
    for (cir.expected_consumption_plans.items.items, 0..) |plan, plan_index| {
        if (plan.owner_node != @intFromEnum(owner_expr)) continue;
        switch (plan.decodedRole() orelse return error.TestUnexpectedResult) {
            .record_update_base => {
                if (result.base != none or plan.slot != 0) return error.TestUnexpectedResult;
                result.base = @intCast(plan_index);
            },
            .record_update_field => {
                if (plan.slot >= expected_fields_len or result.fields[plan.slot] != none) {
                    return error.TestUnexpectedResult;
                }
                result.fields[plan.slot] = @intCast(plan_index);
            },
            else => return error.TestUnexpectedResult,
        }
    }
    if (result.base == none) return error.TestUnexpectedResult;
    for (result.fields[0..expected_fields_len]) |field| {
        if (field == none) return error.TestUnexpectedResult;
    }
    return result;
}

const CompletedRecordUpdateOwnerPlanSet = struct {
    owner: RetiredRecordUpdateOwnerSnapshot,
    plans: RecordUpdateOwnerPlanSet,
};

const CompletedPreexistingMalformedRecordUpdateOwner = struct {
    base_retirement_index: u32,
    owner_retirement_index: u32,
    base_plan_index: u32,
    field_plan_index: u32,
};

fn expectCompletedRecordUpdateOwnerPlanSet(
    cir: *const ModuleEnv,
    owner_expr: CIR.Expr.Idx,
    base_expr: CIR.Expr.Idx,
    field_exprs: []const CIR.Expr.Idx,
    expected_unsets_len: u32,
) !CompletedRecordUpdateOwnerPlanSet {
    if (field_exprs.len > 2) return error.TestUnexpectedResult;
    const plans = try uniqueRecordUpdateOwnerPlanSet(
        cir,
        owner_expr,
        @intCast(field_exprs.len),
    );
    const owner = retiredRecordUpdateOwnerSnapshot(
        cir,
        @intFromEnum(owner_expr),
        .retired,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@intFromEnum(base_expr), owner.syntax.base_expr);
    try std.testing.expectEqual(@as(u32, @intCast(field_exprs.len)), owner.syntax.fields_len);
    try std.testing.expectEqual(expected_unsets_len, owner.syntax.unsets_len);
    try std.testing.expectEqual(
        @as(u32, @intCast(field_exprs.len + 1)),
        owner.retirement.retired_consumers_len,
    );

    const base_plan = cir.expected_consumption_plans.items.items[plans.base];
    try std.testing.expect(base_plan.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Outcome.source_root_copy_checked_error,
        base_plan.decodedOutcome().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_base_checked_error,
        base_plan.decodedReason().?,
    );
    try std.testing.expectEqual(@intFromEnum(base_expr), base_plan.site_node);
    try std.testing.expect(expectedRecordUpdateBaseSourceRetirementIsLocallyValid(cir, base_plan));
    for (field_exprs, 0..) |field_expr, slot| {
        const field_plan = cir.expected_consumption_plans.items.items[plans.fields[slot]];
        try std.testing.expect(field_plan.hasLegalTags());
        try std.testing.expectEqual(
            ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error,
            field_plan.decodedOutcome().?,
        );
        try std.testing.expectEqual(
            ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_field_base_checked_error,
            field_plan.decodedReason().?,
        );
        try std.testing.expectEqual(@intFromEnum(field_expr), field_plan.site_node);
        try std.testing.expectEqual(@as(u32, @intCast(slot)), field_plan.slot);
        try std.testing.expectEqual(plans.base, field_plan.failure_cause_plan_index);
        try std.testing.expect(expectedCauseOwnersEqual(
            base_plan.failure_owner,
            field_plan.failure_owner,
        ));
    }

    const consumers = cir.expected_retired_consumers.items.items[owner.retirement.retired_consumers_start..][0..owner.retirement.retired_consumers_len];
    try std.testing.expect(expectedRetiredRecordUpdateOwnerRangeIsLocallyValid(
        &cir.types,
        cir,
        owner.retirement,
        owner.retirement_index,
        consumers,
    ));
    var saw_base = false;
    var saw_fields = [_]bool{ false, false };
    for (consumers) |consumer| {
        try std.testing.expectEqual(
            ModuleEnv.ExpectedRetiredConsumer.RetirementOnlyReason.record_update_retired_after_base_checked_error,
            consumer.decodedRetirementOnlyReason().?,
        );
        try std.testing.expect(consumer.decodedReason() == null);
        if (consumer.plan_index == plans.base) {
            try std.testing.expect(!saw_base);
            saw_base = true;
            continue;
        }
        var matched_field = false;
        for (plans.fields[0..plans.fields_len], 0..) |field_plan_index, slot| {
            if (consumer.plan_index != field_plan_index) continue;
            try std.testing.expect(!saw_fields[slot]);
            saw_fields[slot] = true;
            matched_field = true;
        }
        if (!matched_field) return error.TestUnexpectedResult;
    }
    try std.testing.expect(saw_base);
    for (saw_fields[0..plans.fields_len]) |saw_field| {
        try std.testing.expect(saw_field);
    }
    return .{ .owner = owner, .plans = plans };
}

fn expectCompletedPreexistingMalformedRecordUpdateOwner(
    cir: *const ModuleEnv,
    fresh_cir: *const ModuleEnv,
    topology: RecordUpdatePreexistingMalformedBaseTopology,
) !CompletedPreexistingMalformedRecordUpdateOwner {
    try std.testing.expectEqual(@as(usize, 0), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_consumption_plans.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);

    const completed = try expectCompletedRecordUpdateOwnerPlanSet(
        cir,
        topology.record_expr,
        topology.base_expr,
        &.{topology.field_expr},
        0,
    );
    try std.testing.expectEqual(@as(u32, 0), completed.plans.base);
    try std.testing.expectEqual(@as(u32, 1), completed.plans.fields[0]);
    try std.testing.expectEqual(@as(u32, 1), completed.owner.retirement_index);

    const base_plan = cir.expected_consumption_plans.items.items[completed.plans.base];
    const field_plan = cir.expected_consumption_plans.items.items[completed.plans.fields[0]];
    const base_retirement_index = base_plan.decodedSourceRetirementIndex() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 0), base_retirement_index);
    try std.testing.expectEqual(@as(u32, 1), base_plan.source_retirement_index_plus_one);
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), base_plan.owner_node);
    try std.testing.expectEqual(@intFromEnum(topology.base_expr), base_plan.site_node);
    try std.testing.expectEqual(@intFromEnum(topology.base_expr), base_plan.raw_consumer_var);
    try std.testing.expect(expectedCauseOwnersEqual(
        ModuleEnv.CauseOwner.expectedConsumerRetirement(base_retirement_index),
        base_plan.failure_owner,
    ));
    try std.testing.expect(expectedRecordUpdateBasePlanMatchesStep(cir, base_plan));
    try std.testing.expect(expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
        cir,
        base_plan,
    ));
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), field_plan.owner_node);
    try std.testing.expectEqual(@intFromEnum(topology.field_expr), field_plan.site_node);
    try std.testing.expect(field_plan.raw_consumer_var < cir.types.len());
    try std.testing.expect(field_plan.raw_consumer_var != @intFromEnum(topology.field_expr));
    try std.testing.expectEqual(completed.plans.base, field_plan.failure_cause_plan_index);
    try std.testing.expect(expectedCauseOwnersEqual(
        base_plan.failure_owner,
        field_plan.failure_owner,
    ));
    const base_authority = expectedRecordUpdateBaseAuthority(base_plan) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(expectedRecordUpdateFieldBeginsAtBase(
        cir,
        completed.plans.fields[0],
        field_plan,
        base_authority,
    ));

    const base_retirement = cir.expected_consumer_retirements.items.items[
        base_retirement_index
    ];
    try std.testing.expect(base_retirement.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression,
        base_retirement.decodedOwnerKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.preexisting_runtime_error,
        base_retirement.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(topology.base_expr), base_retirement.retired_node);
    try std.testing.expectEqual(CIR.Node.Tag.malformed, base_retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(
        @intFromEnum(topology.base_diagnostic),
        base_retirement.diagnostic_index,
    );
    try std.testing.expectEqual(@as(u32, 0), base_retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 0), base_retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 0), base_retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), base_retirement.expected_failures_len);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.none,
        base_retirement.rejection_owner_kind,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.none,
        base_retirement.rejection_owner_index,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.none,
        base_retirement.rejection_subject_var,
    );
    try std.testing.expectEqual(@as(u32, 0), base_retirement.reserved_0);
    try std.testing.expectEqual(@as(u32, 0), base_retirement.reserved_1);
    const fresh_base_node = fresh_cir.store.nodes.get(ModuleEnv.nodeIdxFrom(topology.base_expr));
    const fresh_base_payload: [4]u32 = @bitCast(fresh_base_node.getPayload());
    try std.testing.expectEqual(CIR.Node.Tag.malformed, fresh_base_node.tag);
    try std.testing.expectEqualSlices(
        u32,
        &fresh_base_payload,
        &base_retirement.original_payload,
    );
    try std.testing.expect(expectedConsumerRetirementNodeIsLocallyValid(
        cir,
        base_retirement,
    ));

    const owner_retirement = completed.owner.retirement;
    try std.testing.expect(owner_retirement.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_expected,
        owner_retirement.decodedKind().?,
    );
    try std.testing.expectEqual(@intFromEnum(topology.record_expr), owner_retirement.retired_node);
    try std.testing.expectEqual(CIR.Node.Tag.expr_record, owner_retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(@as(u32, 0), owner_retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 2), owner_retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 0), owner_retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), owner_retirement.expected_failures_len);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.none,
        owner_retirement.rejection_owner_kind,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.none,
        owner_retirement.rejection_owner_index,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.none,
        owner_retirement.rejection_subject_var,
    );
    try std.testing.expectEqual(@as(u32, 0), owner_retirement.reserved_0);
    try std.testing.expectEqual(@as(u32, 0), owner_retirement.reserved_1);
    const checked_record = cir.store.getExpr(topology.record_expr);
    if (checked_record != .e_runtime_error) return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        @intFromEnum(checked_record.e_runtime_error.diagnostic),
        owner_retirement.diagnostic_index,
    );
    const fresh_record_node = fresh_cir.store.nodes.get(ModuleEnv.nodeIdxFrom(
        topology.record_expr,
    ));
    const fresh_record_payload: [4]u32 = @bitCast(fresh_record_node.getPayload());
    try std.testing.expectEqual(CIR.Node.Tag.expr_record, fresh_record_node.tag);
    try std.testing.expectEqualSlices(
        u32,
        &fresh_record_payload,
        &owner_retirement.original_payload,
    );
    try std.testing.expect(expectedConsumerRetirementNodeIsLocallyValid(
        cir,
        owner_retirement,
    ));

    const publications = cir.malformed_expression_publications.items.items;
    const fresh_publications = fresh_cir.malformed_expression_publications.items.items;
    try std.testing.expectEqual(@as(usize, 1), publications.len);
    try std.testing.expectEqual(@as(usize, 1), fresh_publications.len);
    try std.testing.expect(malformedExpressionPublicationIsLocallyValid(cir, publications[0]));
    try std.testing.expect(malformedExpressionPublicationIsLocallyValid(
        fresh_cir,
        fresh_publications[0],
    ));
    try std.testing.expectEqual(topology.malformed_publication.expr_node, publications[0].expr_node);
    try std.testing.expectEqual(
        topology.malformed_publication.diagnostic_index,
        publications[0].diagnostic_index,
    );
    try std.testing.expectEqual(publications[0].expr_node, fresh_publications[0].expr_node);
    try std.testing.expectEqual(
        publications[0].diagnostic_index,
        fresh_publications[0].diagnostic_index,
    );

    return .{
        .base_retirement_index = base_retirement_index,
        .owner_retirement_index = completed.owner.retirement_index,
        .base_plan_index = completed.plans.base,
        .field_plan_index = completed.plans.fields[0],
    };
}

fn preexistingMalformedRecordUpdateProducedContext(
    checker: *const Self,
) ImportResolution {
    return ImportResolution.producedSupplied(
        checker.cir,
        .{
            .envs = checker.imported_modules,
            .modules = checker.validated_imported_modules,
        },
        .{
            .envs = checker.owner_modules,
            .modules = checker.validated_owner_modules,
        },
        checker.platform_dependency_index,
    );
}

fn expectPreexistingMalformedRecordUpdateLocalAndFresh(
    cir: *const ModuleEnv,
    fresh_cir: *const ModuleEnv,
    builtin_env: *const ModuleEnv,
    topology: RecordUpdatePreexistingMalformedBaseTopology,
    fresh_context: ImportResolution,
) !CompletedPreexistingMalformedRecordUpdateOwner {
    if (fresh_context.resolution_env != fresh_cir or
        fresh_context.expected_failure_replay != .fresh_canonical)
    {
        return error.TestUnexpectedResult;
    }
    const proof = try expectCompletedPreexistingMalformedRecordUpdateOwner(
        cir,
        fresh_cir,
        topology,
    );
    try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, fresh_context);
    try validateWhereMarkerCopySourceNamespaces(cir, builtin_env, fresh_context);
    return proof;
}

fn expectPreexistingMalformedRecordUpdateProducedReplay(
    checker: *const Self,
    builtin_env: *const ModuleEnv,
) !void {
    const context = preexistingMalformedRecordUpdateProducedContext(checker);
    if (context.resolution_env != checker.cir or
        context.expected_failure_replay != .produced)
    {
        return error.TestUnexpectedResult;
    }
    try validateExpectedFailureContext(checker.cir, context);
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);
    const capability = try checker.validatedModule();
    try std.testing.expectEqual(checker.cir, try capability.validate());
}

fn expectPreexistingMalformedRecordUpdateCheckerTransientState(
