    try std.testing.expect(std.meta.eql(fresh_topology, topology));
    var env = try stageDirectBinderCallPairThroughPrePoison(&consumer);
    defer consumer.checker.env_pool.release(env);
    const checker = &consumer.checker;
    const cir = consumer.module_env;

    const outer_plans = try uniqueRecordUpdateOwnerPlanSet(cir, topology.outer_expr, 2);
    const nested_plans = try uniqueRecordUpdateOwnerPlanSet(cir, topology.nested_expr, 1);
    try std.testing.expect(outer_plans.base < outer_plans.fields[0]);
    try std.testing.expect(outer_plans.fields[0] < nested_plans.base);
    try std.testing.expect(nested_plans.base < nested_plans.fields[0]);
    try std.testing.expect(nested_plans.fields[0] < outer_plans.fields[1]);
    const outer_draft = try uniqueRecordUpdateOwnerRetirementDraft(checker, topology.outer_expr);
    try std.testing.expectEqual(outer_plans.base, outer_draft.base_plan_index);
    try std.testing.expect(recordUpdateOwnerExpectedMembershipAtProducer(
        checker,
        topology.outer_expr,
        outer_draft.base_plan_index,
        outer_draft.base_cause,
    ));
    try std.testing.expect(validateRecordUpdateExpectedPlanRegistrations(checker));
    var outer_registration_count: usize = 0;
    var nested_registration_count: usize = 0;
    for (checker.record_update_expected_plan_registrations.items) |registration| {
        if (registration.owner_expr == topology.outer_expr) outer_registration_count += 1;
        if (registration.owner_expr == topology.nested_expr) nested_registration_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 3), outer_registration_count);
    try std.testing.expectEqual(@as(usize, 2), nested_registration_count);
    var nested_draft_count: usize = 0;
    for (checker.record_update_owner_retirement_drafts.items) |draft| {
        nested_draft_count += @intFromBool(draft.owner_expr == topology.nested_expr);
    }
    try std.testing.expectEqual(@as(usize, 0), nested_draft_count);
    try std.testing.expect(checker.erroneous_value_exprs.contains(topology.outer_expr));
    try std.testing.expect(!checker.erroneous_value_exprs.contains(topology.nested_expr));
    try expectHealthyRecordUpdatePlanSet(
        cir,
        topology.nested_expr,
        topology.nested_base_expr,
        topology.nested_field_expr,
        nested_plans,
    );

    const pending_outer_base = cir.expected_consumption_plans.items.items[outer_plans.base];
    const pending_source_retirement = pending_outer_base.decodedSourceRetirementIndex() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        pending_source_retirement,
        pendingExpressionRetirementAtProducer(checker, topology.lookup_expr).?,
    );
    try std.testing.expect(outer_draft.retirement_index != pending_source_retirement);
    const outer_sites = [_]CIR.Expr.Idx{ topology.nested_expr, topology.outer_after_expr };
    for (outer_plans.fields, 0..) |field_plan_index, slot| {
        const field_plan = cir.expected_consumption_plans.items.items[field_plan_index];
        try std.testing.expectEqual(
            ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error,
            field_plan.decodedOutcome().?,
        );
        try std.testing.expectEqual(
            ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_field_base_checked_error,
            field_plan.decodedReason().?,
        );
        try std.testing.expectEqual(@intFromEnum(outer_sites[slot]), field_plan.site_node);
        try std.testing.expectEqual(@as(u32, @intCast(slot)), field_plan.slot);
        try std.testing.expectEqual(outer_plans.base, field_plan.failure_cause_plan_index);
        try std.testing.expect(expectedCauseOwnersEqual(
            pending_outer_base.failure_owner,
            field_plan.failure_owner,
        ));
    }

    failure_stage = "unmodified production tail";
    try checker.checkFileFromPrePoison(&env);
    try std.testing.expect(cir.store.getExpr(topology.outer_expr) == .e_runtime_error);
    try std.testing.expect(cir.store.getExpr(topology.lookup_expr) == .e_runtime_error);
    try std.testing.expect(cir.store.getExpr(topology.nested_expr) == .e_record);
    try std.testing.expect(cir.store.getExpr(topology.nested_base_expr) == .e_record);
    const lookup = try uniqueDirectBinderLookupTestProof(cir);
    const completed_outer = try expectCompletedRecordUpdateOwnerPlanSet(
        cir,
        topology.outer_expr,
        topology.lookup_expr,
        &outer_sites,
        0,
    );
    try std.testing.expectEqual(
        lookup.lookup_retirement_index,
        cir.expected_consumption_plans.items.items[
            completed_outer.plans.base
        ].decodedSourceRetirementIndex().?,
    );
    try std.testing.expect(
        completed_outer.owner.retirement_index != lookup.lookup_retirement_index,
    );
    const terminal_nested_plans = try uniqueRecordUpdateOwnerPlanSet(
        cir,
        topology.nested_expr,
        1,
    );
    try expectHealthyRecordUpdatePlanSet(
        cir,
        topology.nested_expr,
        topology.nested_base_expr,
        topology.nested_field_expr,
        terminal_nested_plans,
    );
    const outer_consumers = cir.expected_retired_consumers.items.items[completed_outer.owner.retirement.retired_consumers_start..][0..completed_outer.owner.retirement.retired_consumers_len];
    for (outer_consumers) |consumer_row| {
        try std.testing.expect(consumer_row.plan_index != terminal_nested_plans.base);
        try std.testing.expect(consumer_row.plan_index != terminal_nested_plans.fields[0]);
    }
    for (cir.expected_consumer_retirements.items.items) |retirement| {
        try std.testing.expect(
            retirement.decodedOwnerKind() != .expression or
                retirement.retired_node != @intFromEnum(topology.nested_expr),
        );
    }
    try expectDirectBinderTransientListsEmpty(checker);
    try std.testing.expect(checker.record_update_expected_plan_registrations_consumed);
    try std.testing.expectEqual(
        @as(usize, 0),
        checker.record_update_expected_plan_registrations.items.len,
    );

    failure_stage = "terminal local and fresh admission";
    try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
    const context = recordUpdateRootAuthorityFreshContext(&fresh_env);
    try validateExpectedFailureContext(cir, context);
    try validateWhereMarkerCopySourceNamespaces(cir, consumer.builtin_module.env, context);
    _ = try checker.validatedModule();
    try std.testing.expectEqual(@as(usize, 0), checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
}

test "record-update owner retirement: nested checked base supports both owner poison orders" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    var poison_order: NestedRecordUpdatePoisonOrder = .outer_then_inner;
    errdefer std.debug.print(
        "nested record-update owner-retirement fixture failed at {s}, order {s}\n",
        .{ failure_stage, @tagName(poison_order) },
    );

    var provider = try TestEnv.init(
        "RecordUpdateNestedOwnerA",
        direct_binder_transaction_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "RecordUpdateNestedOwnerB",
        nested_record_update_owner_retirement_source,
        "RecordUpdateNestedOwnerA",
        &provider,
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const fresh_topology = try nestedRecordUpdateOwnerTopology(&fresh_env);

    var outer_first_bytes: ?[]u8 = null;
    defer if (outer_first_bytes) |bytes| std.testing.allocator.free(bytes);
    const orders = [_]NestedRecordUpdatePoisonOrder{ .outer_then_inner, .inner_then_outer };
    for (orders) |order| {
        poison_order = order;
        failure_stage = "staged producer";
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "RecordUpdateNestedOwnerB",
            nested_record_update_owner_retirement_source,
            "RecordUpdateNestedOwnerA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        const topology = try nestedRecordUpdateOwnerTopology(&consumer);
        try std.testing.expect(std.meta.eql(fresh_topology, topology));
        var env = try stageDirectBinderCallPairThroughPrePoison(&consumer);
        defer consumer.checker.env_pool.release(env);
        const checker = &consumer.checker;
        const cir = consumer.module_env;
        const pending = try expectPendingNestedRecordUpdateOwnerProof(checker, topology);

        failure_stage = "real leaf value-use sweep";
        try checker.poisonErroneousValueUses();
        try std.testing.expect(cir.store.getExpr(topology.lookup_expr) == .e_runtime_error);
        try std.testing.expect(cir.store.getExpr(topology.inner_expr) == .e_record);
        try std.testing.expect(cir.store.getExpr(topology.outer_expr) == .e_record);
        try std.testing.expect(expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
            cir,
            cir.expected_consumption_plans.items.items[pending.inner_plans.base],
        ));
        try std.testing.expectEqual(
            pending.inner_retirement,
            pendingExpressionRetirementAtProducer(checker, topology.inner_expr).?,
        );
        const outer_draft = try uniqueRecordUpdateOwnerRetirementDraft(
            checker,
            topology.outer_expr,
        );
        try std.testing.expect(recordUpdateOwnerExpectedMembershipAtProducer(
            checker,
            topology.outer_expr,
            outer_draft.base_plan_index,
            outer_draft.base_cause,
        ));

        const inner_diagnostic = try checker.cir.addDiagnostic(.{ .erroneous_value_expr = .{
            .region = checker.cir.store.getExprRegion(topology.inner_expr),
        } });
        const outer_diagnostic = try checker.cir.addDiagnostic(.{ .erroneous_value_expr = .{
            .region = checker.cir.store.getExprRegion(topology.outer_expr),
        } });
        failure_stage = "selected central replacement order";
        switch (order) {
            .outer_then_inner => {
                try checker.replaceExprWithRuntimeError(topology.outer_expr, outer_diagnostic);
                try std.testing.expect(cir.store.getExpr(topology.outer_expr) == .e_runtime_error);
                try std.testing.expect(cir.store.getExpr(topology.inner_expr) == .e_record);
                try std.testing.expectEqual(
                    pending.inner_retirement,
                    pendingExpressionRetirementAtProducer(checker, topology.inner_expr).?,
                );
                try checker.replaceExprWithRuntimeError(topology.inner_expr, inner_diagnostic);
            },
            .inner_then_outer => {
                try checker.replaceExprWithRuntimeError(topology.inner_expr, inner_diagnostic);
                try std.testing.expect(cir.store.getExpr(topology.inner_expr) == .e_runtime_error);
                try std.testing.expect(cir.store.getExpr(topology.outer_expr) == .e_record);
                try std.testing.expect(expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
                    cir,
                    cir.expected_consumption_plans.items.items[pending.outer_plans.base],
                ));
                try checker.replaceExprWithRuntimeError(topology.outer_expr, outer_diagnostic);
            },
        }

        failure_stage = "unmodified production tail";
        try checker.checkFileFromPrePoison(&env);
        try std.testing.expect(cir.store.getExpr(topology.lookup_expr) == .e_runtime_error);
        try std.testing.expect(cir.store.getExpr(topology.inner_expr) == .e_runtime_error);
        try std.testing.expect(cir.store.getExpr(topology.outer_expr) == .e_runtime_error);
        const lookup = try uniqueDirectBinderLookupTestProof(cir);
        const inner = try expectCompletedRecordUpdateOwnerPair(
            cir,
            topology.inner_expr,
            topology.lookup_expr,
            topology.inner_field_expr,
        );
        const outer = try expectCompletedRecordUpdateOwnerPair(
            cir,
            topology.outer_expr,
            topology.inner_expr,
            topology.outer_field_expr,
        );
        const terminal_inner_plans = try uniqueRecordUpdateOwnerPlanPair(cir, topology.inner_expr);
        const terminal_outer_plans = try uniqueRecordUpdateOwnerPlanPair(cir, topology.outer_expr);
        try std.testing.expectEqual(
            lookup.lookup_retirement_index,
            cir.expected_consumption_plans.items.items[
                terminal_inner_plans.base
            ].decodedSourceRetirementIndex().?,
        );
        try std.testing.expectEqual(
            inner.retirement_index,
            cir.expected_consumption_plans.items.items[
                terminal_outer_plans.base
            ].decodedSourceRetirementIndex().?,
        );
        try std.testing.expect(inner.retirement_index != lookup.lookup_retirement_index);
        try std.testing.expect(outer.retirement_index != inner.retirement_index);
        try expectDirectBinderTransientListsEmpty(checker);
        try std.testing.expect(checker.record_update_expected_plan_registrations_consumed);
        try std.testing.expectEqual(
            @as(usize, 0),
            checker.record_update_expected_plan_registrations.items.len,
        );
        try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
        try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
        try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
        const context = recordUpdateRootAuthorityFreshContext(&fresh_env);
        try validateExpectedFailureContext(cir, context);
        try validateWhereMarkerCopySourceNamespaces(cir, consumer.builtin_module.env, context);
        _ = try checker.validatedModule();
        try std.testing.expectEqual(@as(usize, 0), checker.problems.problems.items.len);
        try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());

        const serialized = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        if (outer_first_bytes) |expected| {
            defer std.testing.allocator.free(serialized);
            try std.testing.expectEqualSlices(u8, expected, serialized);
        } else {
            outer_first_bytes = serialized;
        }
    }
}

test "record-update owner retirement: checked-base completion reaches its authentic central boundary" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print(
        "record-update owner completion fixture failed at {s}\n",
        .{failure_stage},
    );

    var provider = try TestEnv.init(
        "RecordUpdateLiveOwnerA",
        direct_binder_transaction_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "RecordUpdateLiveOwnerB",
        record_update_direct_binder_owner_retirement_source,
        "RecordUpdateLiveOwnerA",
        &provider,
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const fresh_topology = try recordUpdateDirectBinderOwnerTopology(&fresh_env);

    failure_stage = "authentic pre-completion stage";
    var consumer = try TestEnv.initUncheckedWithImportForTesting(
        "RecordUpdateLiveOwnerB",
        record_update_direct_binder_owner_retirement_source,
        "RecordUpdateLiveOwnerA",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    var stage = try stageRecordUpdateOwnerCompletionThroughLeafPoison(&consumer);
    defer consumer.checker.env_pool.release(stage.env);
    try std.testing.expect(std.meta.eql(fresh_topology, stage.topology));
    const checker = &consumer.checker;
    try std.testing.expectEqual(
        @as(usize, 0),
        checker.cir.expected_retired_consumers.items.capacity,
    );
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.capacity());

    failure_stage = "real central completion";
    var allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const allocation_base = allocator.alloc_index;
    allocator.resize_fail_index = allocator.resize_index;
    try replaceExprWithRuntimeErrorWithAllocatorForTest(
        checker,
        stage.topology.record_expr,
        stage.diagnostic,
        allocator.allocator(),
    );
    const allocation_count = allocator.alloc_index - allocation_base;
    try std.testing.expect(!allocator.has_induced_failure);
    try std.testing.expect(allocation_count > 0);
    _ = try expectRecordUpdateOwnerCompletionCommitted(checker, stage);
    try std.testing.expectEqual(@as(usize, 2), checker.hoist_invalidated_exprs.count());
    try std.testing.expect(checker.hoist_invalidated_exprs.contains(stage.topology.field_expr));
    try std.testing.expect(checker.hoist_invalidated_exprs.contains(stage.topology.base_expr));
    try std.testing.expect(!checker.hoist_invalidated_exprs.contains(stage.topology.record_expr));

    failure_stage = "real tail and fresh admission";
    const completed = try finishRecordUpdateOwnerCompletionTest(
        &consumer,
        &fresh_env,
        &stage,
    );
    defer std.testing.allocator.free(completed);
}

test "record-update owner retirement: direct-binder checked base retires its exact plan group" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("record-update owner-retirement fixture failed at {s}\n", .{failure_stage});

    var provider = try TestEnv.init(
        "RecordUpdateLiveOwnerA",
        direct_binder_transaction_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    failure_stage = "checked consumer";
    var consumer = try TestEnv.initWithImport(
        "RecordUpdateLiveOwnerB",
        record_update_direct_binder_owner_retirement_source,
        "RecordUpdateLiveOwnerA",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());

    failure_stage = "fresh canonical topology";
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "RecordUpdateLiveOwnerB",
        record_update_direct_binder_owner_retirement_source,
        "RecordUpdateLiveOwnerA",
        &provider,
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const topology = try recordUpdateDirectBinderOwnerTopology(&fresh_env);
    const record_expr = topology.record_expr;
    const base_expr = topology.base_expr;
    const field_expr = topology.field_expr;

    failure_stage = "terminal producer ownership";
    const cir = consumer.module_env;
    try std.testing.expect(cir.store.getExpr(record_expr) == .e_runtime_error);
    try std.testing.expect(cir.store.getExpr(base_expr) == .e_runtime_error);
    const lookup = try uniqueDirectBinderLookupTestProof(cir);
    const lookup_failure = cir.expected_failures.items.items[lookup.failure_index];
    try std.testing.expectEqual(@intFromEnum(base_expr), lookup_failure.owner_node);
    try std.testing.expectEqual(
        @intFromEnum(base_expr),
        cir.expected_consumer_retirements.items.items[
            lookup.lookup_retirement_index
        ].retired_node,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        cir.expected_consumer_retirements.items.items[
            lookup.lookup_retirement_index
        ].decodedKind().?,
    );

    var base_plan_index: ?u32 = null;
    var field_plan_index: ?u32 = null;
    for (cir.expected_consumption_plans.items.items, 0..) |plan, plan_index| {
        if (plan.owner_node != @intFromEnum(record_expr)) continue;
        switch (plan.decodedRole() orelse return error.TestUnexpectedResult) {
            .record_update_base => {
                if (base_plan_index != null) return error.TestUnexpectedResult;
                base_plan_index = @intCast(plan_index);
            },
            .record_update_field => {
                if (field_plan_index != null) return error.TestUnexpectedResult;
                field_plan_index = @intCast(plan_index);
            },
            else => return error.TestUnexpectedResult,
        }
    }
    const base_plan_raw = base_plan_index orelse return error.TestUnexpectedResult;
    const field_plan_raw = field_plan_index orelse return error.TestUnexpectedResult;
    const base_plan = cir.expected_consumption_plans.items.items[base_plan_raw];
    const field_plan = cir.expected_consumption_plans.items.items[field_plan_raw];
    try std.testing.expect(base_plan.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Outcome.source_root_copy_checked_error,
        base_plan.decodedOutcome().?,
    );
    try std.testing.expectEqual(@intFromEnum(record_expr), base_plan.owner_node);
    try std.testing.expectEqual(@intFromEnum(base_expr), base_plan.site_node);
    try std.testing.expectEqual(@as(u32, 0), base_plan.slot);
    try std.testing.expectEqual(@intFromEnum(base_expr), base_plan.raw_consumer_var);
    try std.testing.expectEqual(
        lookup.lookup_retirement_index,
        base_plan.decodedSourceRetirementIndex().?,
    );
    try std.testing.expect(expectedCauseOwnersEqual(
        base_plan.failure_owner,
        ModuleEnv.CauseOwner.expectedConsumerRetirement(lookup.lookup_retirement_index),
    ));
    try std.testing.expect(field_plan.hasLegalTags());
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error,
        field_plan.decodedOutcome().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.record_update_field_base_checked_error,
        field_plan.decodedReason().?,
    );
    try std.testing.expectEqual(@intFromEnum(field_expr), field_plan.site_node);
    try std.testing.expectEqual(@as(u32, 0), field_plan.slot);
    try std.testing.expectEqual(base_plan_raw, field_plan.failure_cause_plan_index);
    try std.testing.expect(expectedCauseOwnersEqual(
        base_plan.failure_owner,
        field_plan.failure_owner,
    ));
    const outer = retiredRecordUpdateOwnerSnapshot(
        cir,
        @intFromEnum(record_expr),
        .retired,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(outer.retirement_index != lookup.lookup_retirement_index);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_expected,
        outer.retirement.decodedKind().?,
    );
    try std.testing.expectEqual(@as(u32, 0), outer.retirement.expected_failures_len);
    try std.testing.expectEqual(@as(u32, 2), outer.retirement.retired_consumers_len);
    try std.testing.expectEqual(@intFromEnum(base_expr), outer.syntax.base_expr);
    try std.testing.expectEqual(@as(u32, 1), outer.syntax.fields_len);
    const outer_consumers = cir.expected_retired_consumers.items.items[outer.retirement.retired_consumers_start..][0..outer.retirement.retired_consumers_len];
    try std.testing.expect(expectedRetiredRecordUpdateOwnerRangeIsLocallyValid(
        &cir.types,
        cir,
        outer.retirement,
        outer.retirement_index,
        outer_consumers,
    ));
    var saw_base = false;
    var saw_field = false;
    for (outer_consumers) |retired_consumer| {
        try std.testing.expectEqual(
            ModuleEnv.ExpectedRetiredConsumer.RetirementOnlyReason.record_update_retired_after_base_checked_error,
            retired_consumer.decodedRetirementOnlyReason().?,
        );
        try std.testing.expect(retired_consumer.decodedReason() == null);
        if (retired_consumer.plan_index == base_plan_raw) {
            try std.testing.expect(!saw_base);
            saw_base = true;
        } else if (retired_consumer.plan_index == field_plan_raw) {
            try std.testing.expect(!saw_field);
            saw_field = true;
        } else {
            return error.TestUnexpectedResult;
        }
    }
    try std.testing.expect(saw_base and saw_field);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);

    failure_stage = "terminal local and fresh admission";
    try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
    const context = recordUpdateRootAuthorityFreshContext(&fresh_env);
    try validateExpectedFailureContext(cir, context);
    try validateWhereMarkerCopySourceNamespaces(
        cir,
        consumer.builtin_module.env,
        context,
    );
    _ = try consumer.checker.validatedModule();
}

test "record-update owner retirement: preexisting malformed base reuses its exact retirement" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "checked source";
    errdefer std.debug.print(
        "preexisting malformed record-update base failed at {s}\n",
        .{failure_stage},
    );

    var checked = try TestEnv.init(
        "RecordUpdatePreexistingMalformedBase",
        record_update_preexisting_malformed_base_source,
    );
    defer checked.deinit();
    try checked.assertCanErrors(&.{"Chained Range"});
    try std.testing.expectEqual(@as(usize, 0), checked.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try checked.typeProblemCount());

    failure_stage = "fresh initialization";
    var fresh_env = try TestEnv.initUncheckedForTesting(
        "RecordUpdatePreexistingMalformedBase",
        record_update_preexisting_malformed_base_source,
    );
    defer fresh_env.deinit();
    failure_stage = "fresh Chained Range diagnostic";
    try fresh_env.assertCanErrors(&.{"Chained Range"});
    failure_stage = "fresh record topology";
    const topology = try recordUpdatePreexistingMalformedBaseTopology(&fresh_env);
    const cir = checked.module_env;

    failure_stage = "terminal node phases";
    const checked_record = cir.store.getExpr(topology.record_expr);
    const checked_base = cir.store.getExpr(topology.base_expr);
    try std.testing.expect(checked_record == .e_runtime_error);
    try std.testing.expect(checked_base == .e_runtime_error);
    try std.testing.expectEqual(topology.base_diagnostic, checked_base.e_runtime_error.diagnostic);
    try std.testing.expect(
        cir.store.getDiagnostic(checked_base.e_runtime_error.diagnostic) == .range_op_chained,
    );
    try std.testing.expect(
        cir.store.getDiagnostic(checked_record.e_runtime_error.diagnostic) == .erroneous_value_expr,
    );
    const checked_field = cir.store.getExpr(topology.field_expr);
    try std.testing.expect(checked_field == .e_typed_int);
    try std.testing.expectEqual(@as(i128, 1), checked_field.e_typed_int.value.toI128());
    try std.testing.expectEqualStrings(
        "U8",
        cir.getIdent(checked_field.e_typed_int.type_name),
    );

    failure_stage = "exact R_B P_B P_F R_U graph";
    const proof = try expectCompletedPreexistingMalformedRecordUpdateOwner(
        cir,
        fresh_env.module_env,
        topology,
    );
    try expectDirectBinderTransientListsEmpty(&checked.checker);
    try std.testing.expectEqual(
        @as(usize, 0),
        checked.checker.aggregate_expected_retirement_drafts.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        checked.checker.record_update_expected_plan_registrations.items.len,
    );
    try std.testing.expect(
        checked.checker.record_update_expected_plan_registrations_consumed,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        checked.checker.optional_field_accesses.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        checked.checker.pending_record_updates.items.len,
    );

    failure_stage = "local and produced replay";
    try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
    const produced_context = ImportResolution.producedSupplied(
        cir,
        .{
            .envs = checked.checker.imported_modules,
            .modules = checked.checker.validated_imported_modules,
        },
        .{
            .envs = checked.checker.owner_modules,
            .modules = checked.checker.validated_owner_modules,
        },
        checked.checker.platform_dependency_index,
    );
    try validateExpectedFailureContext(cir, produced_context);
    try validateWhereMarkerCopySourceNamespaces(
        cir,
        checked.builtin_module.env,
        produced_context,
    );
    _ = try checked.checker.validatedModule();

    failure_stage = "distinct fresh replay";
    const fresh_context = recordUpdateRootAuthorityFreshContext(&fresh_env);
    try validateExpectedFailureContext(cir, fresh_context);
    try validateWhereMarkerCopySourceNamespaces(
        cir,
        checked.builtin_module.env,
        fresh_context,
    );

    failure_stage = "P_B source-retirement retarget rejection";
    const plans = cir.expected_consumption_plans.items.items;
    {
        const saved_base_plan = plans[proof.base_plan_index];
        defer plans[proof.base_plan_index] = saved_base_plan;
        plans[proof.base_plan_index].source_retirement_index_plus_one =
            proof.owner_retirement_index + 1;
        const retargeted_base_plan = plans[proof.base_plan_index];
        try std.testing.expect(retargeted_base_plan.hasLegalTags());
        try std.testing.expectEqual(
            proof.owner_retirement_index,
            retargeted_base_plan.decodedSourceRetirementIndex().?,
        );
        try std.testing.expect(!expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
            cir,
            retargeted_base_plan,
        ));
        try std.testing.expect(!validateExpectedRecordUpdatePlans(&cir.types, cir));
    }

    failure_stage = "P_B source-retirement restoration";
    _ = try expectCompletedPreexistingMalformedRecordUpdateOwner(
        cir,
        fresh_env.module_env,
        topology,
    );
    try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, produced_context);
    try validateWhereMarkerCopySourceNamespaces(
        cir,
        checked.builtin_module.env,
        produced_context,
    );
    try validateExpectedFailureContext(cir, fresh_context);
    try validateWhereMarkerCopySourceNamespaces(
        cir,
        checked.builtin_module.env,
        fresh_context,
    );

    failure_stage = "R_B phase forgery isolation";
    const retirements = cir.expected_consumer_retirements.items.items;
    const healthy_field_node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(topology.field_expr));
    try std.testing.expectEqual(CIR.Node.Tag.expr_typed_int, healthy_field_node.tag);
    {
        const saved_base_retirement = retirements[proof.base_retirement_index];
        defer retirements[proof.base_retirement_index] = saved_base_retirement;
        retirements[proof.base_retirement_index].kind = @intFromEnum(
            ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_ineligible,
        );
        retirements[proof.base_retirement_index].original_node_tag =
            @intFromEnum(healthy_field_node.tag);
        retirements[proof.base_retirement_index].original_payload =
            @bitCast(healthy_field_node.getPayload());

        const forged_base_retirement = retirements[proof.base_retirement_index];
        try std.testing.expect(forged_base_retirement.hasLegalTags());
        try std.testing.expect(expectedConsumerRetirementNodeIsLocallyValid(
            cir,
            forged_base_retirement,
        ));
        try std.testing.expect(expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
            cir,
            plans[proof.base_plan_index],
        ));
        try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
        try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
        try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
        try validateExpectedFailureContext(cir, produced_context);
        try validateWhereMarkerCopySourceNamespaces(
            cir,
            checked.builtin_module.env,
            produced_context,
        );
        try std.testing.expectError(
            error.CorruptArtifact,
            validateWhereMarkerCopySourceNamespaces(
                cir,
                checked.builtin_module.env,
                fresh_context,
            ),
        );
    }

    failure_stage = "R_B phase-forgery restoration";
    _ = try expectCompletedPreexistingMalformedRecordUpdateOwner(
        cir,
        fresh_env.module_env,
        topology,
    );
    try std.testing.expect(validateExpectedRecordUpdatePlans(&cir.types, cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, produced_context);
    try validateWhereMarkerCopySourceNamespaces(
        cir,
        checked.builtin_module.env,
        produced_context,
    );
    try validateExpectedFailureContext(cir, fresh_context);
    try validateWhereMarkerCopySourceNamespaces(
        cir,
        checked.builtin_module.env,
        fresh_context,
    );
}

test "record-update owner retirement: preexisting malformed base rebuilds and serializes active recovery" {
    const TestEnv = @import("test/TestEnv.zig");
    const module_name = "RecordUpdatePreexistingMalformedBaseRebuildSerde";
    var failure_stage: []const u8 = "checked source";
    errdefer std.debug.print(
        "preexisting malformed record-update rebuild/serde failed at {s}\n",
        .{failure_stage},
    );

    var checked = try TestEnv.init(
        module_name,
        record_update_preexisting_malformed_base_source,
    );
    defer checked.deinit();
    try checked.assertCanErrors(&.{"Chained Range"});
    try std.testing.expectEqual(@as(usize, 0), checked.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try checked.typeProblemCount());

    failure_stage = "distinct fresh source";
    var fresh_env = try TestEnv.initUncheckedForTesting(
        module_name,
        record_update_preexisting_malformed_base_source,
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{"Chained Range"});
    const topology = try recordUpdatePreexistingMalformedBaseTopology(&fresh_env);
    const cir = checked.module_env;

    failure_stage = "terminal baseline";
    const baseline_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
        cir,
        fresh_env.module_env,
        checked.builtin_module.env,
        topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try expectPreexistingMalformedRecordUpdateCheckerTransientState(&checked.checker);
    try expectPreexistingMalformedRecordUpdateProducedReplay(
        &checked.checker,
        checked.builtin_module.env,
    );
    const canonical_baseline = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        cir,
    );
    defer std.testing.allocator.free(canonical_baseline);

    failure_stage = "first repeated rebuild";
    try checked.checker.rebuildCheckedBoundaryWhereMethodState();
    const first_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
        cir,
        fresh_env.module_env,
        checked.builtin_module.env,
        topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try std.testing.expect(std.meta.eql(baseline_proof, first_proof));
    try expectPreexistingMalformedRecordUpdateCheckerTransientState(&checked.checker);
    try expectPreexistingMalformedRecordUpdateProducedReplay(
        &checked.checker,
        checked.builtin_module.env,
    );
    const canonical_first = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        cir,
    );
    defer std.testing.allocator.free(canonical_first);
    try std.testing.expectEqualSlices(u8, canonical_baseline, canonical_first);

    failure_stage = "second repeated rebuild";
    try checked.checker.rebuildCheckedBoundaryWhereMethodState();
    const second_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
        cir,
        fresh_env.module_env,
        checked.builtin_module.env,
        topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try std.testing.expect(std.meta.eql(baseline_proof, second_proof));
    try expectPreexistingMalformedRecordUpdateCheckerTransientState(&checked.checker);
    try expectPreexistingMalformedRecordUpdateProducedReplay(
        &checked.checker,
        checked.builtin_module.env,
    );
    const canonical_second = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        cir,
    );
    defer std.testing.allocator.free(canonical_second);
    try std.testing.expectEqualSlices(u8, canonical_baseline, canonical_second);

    failure_stage = "aligned serialization";
    const buffer = try serializeModuleEnvForDeserializationTest(
        std.testing.allocator,
        cir,
    );
    defer std.testing.allocator.free(buffer);
    try std.testing.expectEqualSlices(u8, canonical_baseline, buffer);
    const base_addr = @intFromPtr(buffer.ptr);
    const serialized: *const ModuleEnv.Serialized = @ptrCast(@alignCast(buffer.ptr));
    try serialized.validate(buffer.len);

    failure_stage = "readonly deserialization";
    const readonly = try serialized.deserializeInto(
        base_addr,
        std.testing.allocator,
        record_update_preexisting_malformed_base_source,
        module_name,
    );
    defer {
        readonly.imports.deinitMapOnly(std.testing.allocator);
        readonly.import_mapping.deinit();
        std.testing.allocator.destroy(readonly);
    }
    try std.testing.expect(!readonly.w6b_semantically_validated);
    const readonly_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
        readonly,
        fresh_env.module_env,
        checked.builtin_module.env,
        topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try std.testing.expect(std.meta.eql(baseline_proof, readonly_proof));
    const readonly_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        readonly,
    );
    defer std.testing.allocator.free(readonly_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, readonly_bytes);

    failure_stage = "mutable deserialization";
    const mutable = try serialized.deserializeWithMutableTypes(
        base_addr,
        std.testing.allocator,
        record_update_preexisting_malformed_base_source,
        module_name,
    );
    defer {
        mutable.deinitCachedModule();
        std.testing.allocator.destroy(mutable);
    }
    try std.testing.expect(!mutable.w6b_semantically_validated);
    const mutable_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
        mutable,
        fresh_env.module_env,
        checked.builtin_module.env,
        topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try std.testing.expect(std.meta.eql(baseline_proof, mutable_proof));
    const mutable_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        mutable,
    );
    defer std.testing.allocator.free(mutable_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, mutable_bytes);

    failure_stage = "mutable source-retirement isolation";
    const mutable_plans = mutable.expected_consumption_plans.items.items;
    {
        const saved_base_plan = mutable_plans[mutable_proof.base_plan_index];
        defer mutable_plans[mutable_proof.base_plan_index] = saved_base_plan;
        mutable_plans[mutable_proof.base_plan_index].source_retirement_index_plus_one =
            mutable_proof.owner_retirement_index + 1;
        const changed_base_plan = mutable_plans[mutable_proof.base_plan_index];
        try std.testing.expect(changed_base_plan.hasLegalTags());
        try std.testing.expectEqual(
            mutable_proof.owner_retirement_index,
            changed_base_plan.decodedSourceRetirementIndex().?,
        );
        try std.testing.expect(!expectedRecordUpdateBaseSourceRetirementIsLocallyValid(
            mutable,
            changed_base_plan,
        ));
        try std.testing.expect(!validateExpectedRecordUpdatePlans(&mutable.types, mutable));

        const original_during_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
            cir,
            fresh_env.module_env,
            checked.builtin_module.env,
            topology,
            recordUpdateRootAuthorityFreshContext(&fresh_env),
        );
        const readonly_during_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
            readonly,
            fresh_env.module_env,
            checked.builtin_module.env,
            topology,
            recordUpdateRootAuthorityFreshContext(&fresh_env),
        );
        try std.testing.expect(std.meta.eql(baseline_proof, original_during_proof));
        try std.testing.expect(std.meta.eql(baseline_proof, readonly_during_proof));
        try expectPreexistingMalformedRecordUpdateProducedReplay(
            &checked.checker,
            checked.builtin_module.env,
        );
        try serialized.validate(buffer.len);
        try std.testing.expectEqualSlices(u8, canonical_baseline, buffer);
        const original_during_bytes = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        defer std.testing.allocator.free(original_during_bytes);
        const readonly_during_bytes = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            readonly,
        );
        defer std.testing.allocator.free(readonly_during_bytes);
        try std.testing.expectEqualSlices(u8, canonical_baseline, original_during_bytes);
        try std.testing.expectEqualSlices(u8, canonical_baseline, readonly_during_bytes);
    }

    failure_stage = "mutable restoration";
    const mutable_restored_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
        mutable,
        fresh_env.module_env,
        checked.builtin_module.env,
        topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    const original_restored_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
        cir,
        fresh_env.module_env,
        checked.builtin_module.env,
        topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    const readonly_restored_proof = try expectPreexistingMalformedRecordUpdateLocalAndFresh(
        readonly,
        fresh_env.module_env,
        checked.builtin_module.env,
        topology,
        recordUpdateRootAuthorityFreshContext(&fresh_env),
    );
    try std.testing.expect(std.meta.eql(baseline_proof, mutable_restored_proof));
    try std.testing.expect(std.meta.eql(baseline_proof, original_restored_proof));
    try std.testing.expect(std.meta.eql(baseline_proof, readonly_restored_proof));
    try expectPreexistingMalformedRecordUpdateProducedReplay(
        &checked.checker,
        checked.builtin_module.env,
    );
    try serialized.validate(buffer.len);
    try std.testing.expectEqualSlices(u8, canonical_baseline, buffer);
    const mutable_restored_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        mutable,
    );
    defer std.testing.allocator.free(mutable_restored_bytes);
    const original_restored_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        cir,
    );
    defer std.testing.allocator.free(original_restored_bytes);
    const readonly_restored_bytes = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        readonly,
    );
    defer std.testing.allocator.free(readonly_restored_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, mutable_restored_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, original_restored_bytes);
    try std.testing.expectEqualSlices(u8, canonical_baseline, readonly_restored_bytes);
}

test "record-update root authority: direct and redirected selections survive rebuild serde and fresh admission" {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    var failure_stage: []const u8 = "checked fixture";
    errdefer std.debug.print("record-update root authority fixture failed at {s}\n", .{failure_stage});

    var test_env = try TestEnv.init("RecordUpdateRootAuthority", record_update_root_authority_test_source);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    var fresh_env = try TestEnv.initUncheckedWithAdmittedBuiltinForTesting(
        "RecordUpdateRootAuthority",
        record_update_root_authority_test_source,
        test_env.builtin_module,
        test_env.builtin_validation,
        compiled_builtins.builtinIndices(CIR),
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{});
    const topology = try recordUpdateRootAuthorityTestTopology(&test_env);
    const fresh_topology = try recordUpdateRootAuthorityTestTopology(&fresh_env);
    try std.testing.expect(std.meta.eql(topology, fresh_topology));

    failure_stage = "authentic producer proofs";
    const first = try expectRecordUpdateRootAuthorityTestProof(
        test_env.module_env,
        topology.redirected_records[0],
        .redirected_identity_share,
    );
    const second = try expectRecordUpdateRootAuthorityTestProof(
        test_env.module_env,
        topology.redirected_records[1],
        .redirected_identity_share,
    );
    const direct = try expectRecordUpdateRootAuthorityTestProof(
        test_env.module_env,
        topology.direct_record,
        .direct_request,
    );
    try std.testing.expect(first.base_expr != second.base_expr);
    const first_resolved_root: u32 = @intFromEnum(
        test_env.module_env.types.resolveVar(@enumFromInt(first.selected_raw_root)).var_,
    );
    const second_resolved_root: u32 = @intFromEnum(
        test_env.module_env.types.resolveVar(@enumFromInt(second.selected_raw_root)).var_,
    );
    try std.testing.expectEqual(first.selected_canonical_root, first_resolved_root);
    try std.testing.expectEqual(second.selected_canonical_root, second_resolved_root);
    try std.testing.expectEqual(first_resolved_root, second_resolved_root);
    try std.testing.expect(
        first.selected_raw_root != first_resolved_root or
            second.selected_raw_root != second_resolved_root,
    );
    try std.testing.expect(direct.base_expr == @as(CIR.Expr.Idx, @enumFromInt(direct.selected_raw_root)));
    try std.testing.expect(validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    ));
    const context = recordUpdateRootAuthorityFreshContext(&fresh_env);
    try validateWhereMarkerCopySourceNamespaces(
        test_env.module_env,
        test_env.builtin_module.env,
        context,
    );

    failure_stage = "closed binding corruptions";
    const first_step = &test_env.module_env.where_marker_copy_steps.items.items[first.step_index];
    const saved_first_step = first_step.*;
    first_step.origin.record_update_base.root_binding = 2;
    const accepted_unknown_binding = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_step.* = saved_first_step;
    try std.testing.expect(!accepted_unknown_binding);

    first_step.origin.record_update_base.root_binding = @intFromEnum(
        ModuleEnv.WhereMarkerRecordUpdateBaseOrigin.RootBinding.direct_request,
    );
    const accepted_redirect_as_direct = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_step.* = saved_first_step;
    try std.testing.expect(!accepted_redirect_as_direct);

    const direct_step = &test_env.module_env.where_marker_copy_steps.items.items[direct.step_index];
    const saved_direct_step = direct_step.*;
    direct_step.origin.record_update_base.root_binding = @intFromEnum(
        ModuleEnv.WhereMarkerRecordUpdateBaseOrigin.RootBinding.redirected_identity_share,
    );
    const accepted_direct_as_redirect = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    direct_step.* = saved_direct_step;
    try std.testing.expect(!accepted_direct_as_redirect);

    first_step.origin.record_update_base.reserved_1 = 1;
    const accepted_reserved = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_step.* = saved_first_step;
    try std.testing.expect(!accepted_reserved);

    first_step.origin.record_update_base.reserved_2 = 1;
    const accepted_reserved_2 = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_step.* = saved_first_step;
    try std.testing.expect(!accepted_reserved_2);

    first_step.origin.record_update_base.reserved_3 = 1;
    const accepted_reserved_3 = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_step.* = saved_first_step;
    try std.testing.expect(!accepted_reserved_3);

    first_step.origin.record_update_base.record_expr = @intFromEnum(first.base_expr);
    const accepted_wrong_record_owner = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_step.* = saved_first_step;
    try std.testing.expect(!accepted_wrong_record_owner);

    first_step.origin.record_update_base.base_expr = std.math.maxInt(u32);
    const accepted_missing_base = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_step.* = saved_first_step;
    try std.testing.expect(!accepted_missing_base);

    first_step.root_occurrence_offset = first_step.occurrences_len;
    const accepted_missing_root_occurrence = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_step.* = saved_first_step;
    try std.testing.expect(!accepted_missing_root_occurrence);

    const first_root_occurrence = &test_env.module_env.where_marker_copy_occurrences.items.items[
        first.root_occurrence_index
    ];
    const saved_first_root_occurrence = first_root_occurrence.*;
    first_root_occurrence.canonical_pair_offset = first_step.pairs_len;
    const accepted_missing_root_pair = validateWhereMarkerCopyProofLocal(
        &test_env.module_env.types,
        test_env.module_env,
    );
    first_root_occurrence.* = saved_first_root_occurrence;
