    });
    const calibration_gpa = calibration_allocator.allocator();
    var calibration_env = try Env.init(calibration_gpa, .generalized);
    defer calibration_env.deinit(calibration_gpa);
    const calibration_stage = try stageRecordUpdateBasePlanPublication(
        &calibration_test_env,
        &calibration_env,
    );
    try std.testing.expectEqual(@as(u32, 0), calibration_stage.expected_plans_start);
    try std.testing.expectEqual(@as(usize, 0), calibration_stage.registrations_start);
    try std.testing.expectEqual(@as(usize, 0), calibration_stage.owner_retirement_drafts_start);
    try std.testing.expect(!calibration_stage.registrations_consumed);
    try std.testing.expectEqual(
        @as(usize, 0),
        calibration_test_env.module_env.expected_consumption_plans.items.capacity,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        calibration_test_env.checker.record_update_expected_plan_registrations.capacity,
    );
    var calibration_before = try RecordUpdateRootTransactionSnapshot.capture(
        std.testing.allocator,
        &calibration_test_env.checker,
        &calibration_env,
    );
    defer calibration_before.deinit(std.testing.allocator);
    const allocation_base = calibration_allocator.alloc_index;
    calibration_allocator.resize_fail_index = calibration_allocator.resize_index;
    const calibration_result = try publishStagedRecordUpdateBasePlanWithAllocator(
        &calibration_test_env.checker,
        &calibration_env,
        calibration_gpa,
        calibration_stage,
    );
    const allocation_count = calibration_allocator.alloc_index - allocation_base;
    try std.testing.expect(!calibration_allocator.has_induced_failure);
    try std.testing.expect(allocation_count > 0);
    const calibration_proof = try expectStagedRecordUpdateBasePlanPublication(
        &calibration_test_env.checker,
        &calibration_env,
        calibration_stage,
        calibration_result,
    );
    var calibration_after = try RecordUpdateRootTransactionSnapshot.capture(
        std.testing.allocator,
        &calibration_test_env.checker,
        &calibration_env,
    );
    defer calibration_after.deinit(std.testing.allocator);

    var induced_failures: usize = 0;
    for (0..allocation_count) |failure_index| {
        var failure_stage: []const u8 = "fixture staging";
        errdefer std.debug.print(
            "record-update base-plan allocation sweep failed at index={} stage={s}\n",
            .{ failure_index, failure_stage },
        );
        var failed_test_env = try TestEnv.initUncheckedWithAdmittedBuiltinForTesting(
            "RecordUpdateBasePlanOomCalibration",
            record_update_root_authority_test_source,
            builtin_module,
            builtin_validation,
            builtin_indices,
        );
        defer failed_test_env.deinit();
        try failed_test_env.assertCanErrors(&.{});
        var injected = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = std.math.maxInt(usize),
            .resize_fail_index = std.math.maxInt(usize),
        });
        const injected_gpa = injected.allocator();
        var failed_env = try Env.init(injected_gpa, .generalized);
        defer failed_env.deinit(injected_gpa);
        const stage = try stageRecordUpdateBasePlanPublication(&failed_test_env, &failed_env);
        try expectStagedRecordUpdateBasePlanStagesEqual(calibration_stage, stage);
        try std.testing.expectEqual(
            @as(usize, 0),
            failed_test_env.module_env.expected_consumption_plans.items.capacity,
        );
        try std.testing.expectEqual(
            @as(usize, 0),
            failed_test_env.checker.record_update_expected_plan_registrations.capacity,
        );
        var before = try RecordUpdateRootTransactionSnapshot.capture(
            std.testing.allocator,
            &failed_test_env.checker,
            &failed_env,
        );
        defer before.deinit(std.testing.allocator);
        try calibration_before.expectEqual(
            std.testing.allocator,
            &failed_test_env.checker,
            &failed_env,
        );

        failure_stage = "injected full base publication";
        const failure_allocation_base = injected.alloc_index;
        injected.fail_index = std.math.add(
            usize,
            failure_allocation_base,
            failure_index,
        ) catch return error.TestUnexpectedResult;
        injected.resize_fail_index = injected.resize_index;
        const failed_result = publishStagedRecordUpdateBasePlanWithAllocator(
            &failed_test_env.checker,
            &failed_env,
            injected_gpa,
            stage,
        );
        try std.testing.expectError(error.OutOfMemory, failed_result);
        try std.testing.expect(injected.has_induced_failure);
        induced_failures += 1;

        failure_stage = "complete rollback";
        try before.expectEqual(
            std.testing.allocator,
            &failed_test_env.checker,
            &failed_env,
        );
        try before.cross_copy.expectEqual(&failed_test_env.checker);
        try std.testing.expectEqual(
            @as(usize, stage.expected_plans_start),
            failed_test_env.module_env.expected_consumption_plans.items.items.len,
        );
        try std.testing.expectEqual(
            stage.registrations_start,
            failed_test_env.checker.record_update_expected_plan_registrations.items.len,
        );
        try std.testing.expectEqual(
            stage.owner_retirement_drafts_start,
            failed_test_env.checker.record_update_owner_retirement_drafts.items.len,
        );
        try std.testing.expectEqual(
            stage.registrations_consumed,
            failed_test_env.checker.record_update_expected_plan_registrations_consumed,
        );

        failure_stage = "same-instance retry";
        injected.fail_index = std.math.maxInt(usize);
        injected.resize_fail_index = std.math.maxInt(usize);
        const retry_result = try publishStagedRecordUpdateBasePlanWithAllocator(
            &failed_test_env.checker,
            &failed_env,
            injected_gpa,
            stage,
        );
        const retry_proof = try expectStagedRecordUpdateBasePlanPublication(
            &failed_test_env.checker,
            &failed_env,
            stage,
            retry_result,
        );
        try calibration_proof.expectEqual(retry_proof);
        try calibration_after.expectEqual(
            std.testing.allocator,
            &failed_test_env.checker,
            &failed_env,
        );
    }
    try std.testing.expectEqual(allocation_count, induced_failures);
}

test "record-update owner retirement: outer local transaction restores a nonempty base-plan prefix" {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    const builtin_indices = compiled_builtins.builtinIndices(CIR);
    var builtin_module = try can.BuiltinStatic.moduleView(
        std.testing.allocator,
        compiled_builtins.builtin_bin[0..],
        "Builtin",
        compiled_builtins.builtin_source,
    );
    defer builtin_module.deinit();
    var owned_builtin_validation = try admitBuiltinOwned(
        std.testing.allocator,
        builtin_module.env,
        builtin_indices,
    );
    defer owned_builtin_validation.deinit();

    var test_env = try TestEnv.initUncheckedWithAdmittedBuiltinForTesting(
        "RecordUpdateBasePlanOuterRollback",
        record_update_root_authority_test_source,
        builtin_module,
        owned_builtin_validation.capability(),
        builtin_indices,
    );
    defer test_env.deinit();
    try test_env.assertCanErrors(&.{});
    const checker = &test_env.checker;
    var env = try Env.init(checker.gpa, .generalized);
    defer env.deinit(checker.gpa);
    const topology = try beginRecordUpdateRootPublicationFixture(&test_env, &env);
    try checker.checkPattern(topology.redirected_container_pattern, .fn_arg, &env);

    const first_stage = try stageCheckedRecordUpdateBase(&test_env, &env, topology, 0);
    switch (first_stage.status) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }
    const first_result = try publishStagedRecordUpdateBasePlanWithAllocator(
        checker,
        &env,
        checker.gpa,
        first_stage,
    );
    _ = try expectStagedRecordUpdateBasePlanPublication(
        checker,
        &env,
        first_stage,
        first_result,
    );

    const second_stage = try stageCheckedRecordUpdateBase(&test_env, &env, topology, 1);
    switch (second_stage.status) {
        .established => {},
        .checked_error => return error.TestUnexpectedResult,
    }
    try std.testing.expect(first_stage.root.record_expr != second_stage.root.record_expr);
    try std.testing.expect(first_stage.root.base_expr != second_stage.root.base_expr);
    try std.testing.expect(first_stage.root.requested_var != second_stage.root.requested_var);
    try std.testing.expectEqual(first_stage.root.selected_root, second_stage.root.selected_root);
    try std.testing.expectEqual(first_stage.expected_plans_start + 1, second_stage.expected_plans_start);
    try std.testing.expectEqual(first_stage.registrations_start + 1, second_stage.registrations_start);

    var before = try RecordUpdateRootTransactionSnapshot.capture(
        std.testing.allocator,
        checker,
        &env,
    );
    defer before.deinit(std.testing.allocator);
    const initial_probe_depth = checker.probe_depth;
    var outer = try checker.beginLocalMarkerCopyTransaction(&env);
    defer outer.rollback();
    try std.testing.expectEqual(initial_probe_depth + 1, checker.probe_depth);
    const rolled_back_result = try publishStagedRecordUpdateBasePlanWithAllocator(
        checker,
        &env,
        checker.gpa,
        second_stage,
    );
    try std.testing.expectEqual(initial_probe_depth + 1, checker.probe_depth);
    const rolled_back_proof = try expectStagedRecordUpdateBasePlanPublication(
        checker,
        &env,
        second_stage,
        rolled_back_result,
    );

    outer.rollback();
    try std.testing.expectEqual(initial_probe_depth, checker.probe_depth);
    try before.expectEqual(std.testing.allocator, checker, &env);
    try before.cross_copy.expectEqual(checker);
    try std.testing.expectEqual(
        @as(usize, second_stage.expected_plans_start),
        checker.cir.expected_consumption_plans.items.items.len,
    );
    try std.testing.expectEqual(
        second_stage.registrations_start,
        checker.record_update_expected_plan_registrations.items.len,
    );

    const retry_result = try publishStagedRecordUpdateBasePlanWithAllocator(
        checker,
        &env,
        checker.gpa,
        second_stage,
    );
    const retry_proof = try expectStagedRecordUpdateBasePlanPublication(
        checker,
        &env,
        second_stage,
        retry_result,
    );
    try rolled_back_proof.expectEqual(retry_proof);
}

test "local detached scheme copied source has exact paired and identity-skip converses" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("LocalSchemeRequirementCopy", "{}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const scheme_root = try checker.freshFromContentAtRank(
        .{ .structure = .empty_record },
        &env,
        Region.zero(),
        .generalized,
    );
    const callable = try checker.freshFromContentAtRank(
        .{ .structure = .empty_record },
        &env,
        Region.zero(),
        .generalized,
    );
    const source_range = try checker.types.appendStaticDispatchConstraints(&.{.{
        .fn_name = checker.cir.idents.is_eq,
        .fn_var = callable,
        .origin = .{ .where_clause = .{} },
    }});
    const source_constraint_index: u32 = @intFromEnum(source_range.start);
    // This is the real detached-requirement overlap: the shared receiver
    // still owns the creation constraint while the explicit scheme entry
    // independently copies that exact source occurrence's callable.
    const receiver = try checker.freshFromContent(
        .{ .flex = Flex{ .name = null, .constraints = source_range } },
        &env,
        Region.zero(),
    );
    const scheme_index = try checker.ensureTypeScheme(scheme_root, .generalized);
    try checker.type_schemes.items[scheme_index].dispatch_requirements.append(checker.gpa, .{
        .receiver_var = receiver,
        .constraint = checker.types.getStaticDispatchConstraintAt(source_constraint_index),
        .constraint_index = source_constraint_index,
        .deferred_generated_codec = false,
        .failure_expr = null,
        .structural_origin = .{
            .receiver_var = receiver,
            .constraint_fn_var = callable,
        },
    });

    const constraints_before = checker.types.static_dispatch_constraints.items.items.len;
    const copied = try checker.instantiateVarWithMarkerCopy(
        scheme_root,
        &env,
        .{ .explicit = Region.zero() },
        .{ .type_annotation = .{ .node = 0 } },
        .if_marker_carried,
    );
    const step_index = copied.copy_step orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 0), step_index);
    try std.testing.expectEqual(
        constraints_before + 1,
        checker.types.static_dispatch_constraints.items.items.len,
    );
    const step = checker.cir.where_marker_copy_steps.items.items[step_index];
    try std.testing.expectEqual(@as(u32, 1), step.constraint_pairs_len);
    try std.testing.expectEqual(@as(u32, 3), step.witnesses_len);
    const occurrences = checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
    const constraint_pairs = checker.cir.where_marker_constraint_copy_pairs.items.items[step.constraint_pairs_start..][0..step.constraint_pairs_len];
    const witnesses = checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len];
    try std.testing.expectEqual(source_constraint_index, constraint_pairs[0].source_constraint_index);
    try std.testing.expect(constraint_pairs[0].destination_constraint_index != source_constraint_index);
    var receiver_witness_index: ?usize = null;
    var function_witness_index: ?usize = null;
    var root_witness_count: usize = 0;
    for (witnesses, 0..) |witness, witness_index| {
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyWitness.AuxiliaryOriginKind.none,
            witness.decodedAuxiliaryOriginKind().?,
        );
        try std.testing.expectEqual(@as(u32, 0), witness.edge_index);
        switch (witness.decodedEdgeKind().?) {
            .root_copy_action => {
                root_witness_count += 1;
                try std.testing.expectEqual(step.root_occurrence_offset, witness.parent_occurrence_offset);
                try std.testing.expectEqual(step.root_occurrence_offset, witness.child_occurrence_offset);
                try std.testing.expectEqual(std.math.maxInt(u32), witness.constraint_pair_offset);
                try std.testing.expectEqual(
                    ModuleEnv.WhereMarkerCopyWitness.Action.traverse,
                    witness.decodedAction().?,
                );
            },
            .scheme_requirement_receiver => {
                try std.testing.expectEqual(step.root_occurrence_offset, witness.parent_occurrence_offset);
                try std.testing.expectEqual(
                    ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_ingress,
                    witness.decodedAction().?,
                );
                try std.testing.expectEqual(std.math.maxInt(u32), witness.constraint_pair_offset);
                receiver_witness_index = witness_index;
            },
            .scheme_requirement_function => {
                try std.testing.expectEqual(step.root_occurrence_offset, witness.parent_occurrence_offset);
                try std.testing.expectEqual(
                    ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_ingress,
                    witness.decodedAction().?,
                );
                try std.testing.expectEqual(@as(u32, 0), witness.constraint_pair_offset);
                function_witness_index = witness_index;
            },
            else => return error.TestUnexpectedResult,
        }
    }
    try std.testing.expectEqual(@as(usize, 1), root_witness_count);
    const receiver_witness = witnesses[receiver_witness_index orelse return error.TestUnexpectedResult];
    const function_witness = witnesses[function_witness_index orelse return error.TestUnexpectedResult];
    const receiver_occurrence = occurrences[receiver_witness.child_occurrence_offset];
    try std.testing.expectEqual(@intFromEnum(receiver), receiver_occurrence.raw_source_var);
    try std.testing.expectEqual(@intFromEnum(receiver), receiver_occurrence.raw_destination_var);

    try std.testing.expectEqual(@as(usize, 1), checker.cir.dispatch_settlement_sources.items.items.len);
    try std.testing.expectEqual(@as(usize, 1), checker.cir.selected_receiver_anchors.items.items.len);
    const source = checker.cir.dispatch_settlement_sources.items.items[0]
        .decodedCopiedConstraint() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        ModuleEnv.CopiedConstraintComponentRef.Kind.scheme_requirement,
        source.receiver_component_ref.decodedKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.CopiedConstraintComponentRef.Kind.scheme_requirement,
        source.function_component_ref.decodedKind().?,
    );
    try std.testing.expectEqual(step_index, source.receiver_component_ref.copy_step_index);
    try std.testing.expectEqual(step_index, source.function_component_ref.copy_step_index);
    try std.testing.expectEqual(@as(u32, 0), source.receiver_component_ref.requirement_ordinal);
    try std.testing.expectEqual(@as(u32, 0), source.function_component_ref.requirement_ordinal);
    try std.testing.expectEqual(receiver_witness.child_occurrence_offset, source.receiver_component_ref.occurrence_offset);
    try std.testing.expectEqual(function_witness.child_occurrence_offset, source.function_component_ref.occurrence_offset);
    const anchor = checker.cir.selected_receiver_anchors.items.items[source.anchor_index];
    try std.testing.expectEqual(receiver_occurrence.raw_destination_var, anchor.receiver_var);
    try std.testing.expectEqual(source.receiver_component_ref.occurrence_offset, anchor.receiver_occurrence_offset);
    try std.testing.expectEqual(source.function_component_ref.constraint_pair_offset, anchor.constraint_pair_offset);
    const destination_constraint = checker.types.static_dispatch_constraints.items.items[anchor.constraint_index];
    const evidence = checker.types.sliceConstraintEvidenceHandles(destination_constraint.constraint_evidence);
    try std.testing.expectEqual(@as(usize, 1), evidence.len);
    try std.testing.expectEqual(source.anchor_index, evidence[0].index);

    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
        occurrences,
        witnesses,
        step.root_occurrence_offset,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const receiver_absolute_index = step.witnesses_start +
        @as(u32, @intCast(receiver_witness_index.?));
    const saved_receiver_witness = checker.cir.where_marker_copy_witnesses.items.items[receiver_absolute_index];
    checker.cir.where_marker_copy_witnesses.items.items[receiver_absolute_index].action =
        @intFromEnum(ModuleEnv.WhereMarkerCopyWitness.Action.traverse);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    checker.cir.where_marker_copy_witnesses.items.items[receiver_absolute_index] = saved_receiver_witness;

    checker.cir.where_marker_copy_witnesses.items.items[receiver_absolute_index].auxiliary_origin_kind =
        @intFromEnum(ModuleEnv.WhereMarkerCopyWitness.AuxiliaryOriginKind.binding_scheme_codec_requirement);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    checker.cir.where_marker_copy_witnesses.items.items[receiver_absolute_index] = saved_receiver_witness;

    // Shape validation may retain the same receiver and intentionally omit the
    // function half. The exact identity occurrence, not a solved-shape scan,
    // is the complete authority for this receiver-only arm.
    const sources_before_skip = checker.cir.dispatch_settlement_sources.items.items.len;
    const anchors_before_skip = checker.cir.selected_receiver_anchors.items.items.len;
    const handles_before_skip = checker.types.constraint_evidence_handles.items.items.len;
    const constraints_before_skip = checker.types.static_dispatch_constraints.items.items.len;
    checker.pending_shape_validation_instantiation = true;
    const skipped = try checker.instantiateVarWithMarkerCopy(
        scheme_root,
        &env,
        .{ .explicit = Region.zero() },
        .{ .type_annotation = .{ .node = 0 } },
        .eager_support,
    );
    try std.testing.expect(!checker.pending_shape_validation_instantiation);
    const skipped_step_index = skipped.copy_step orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 1), skipped_step_index);
    const skipped_step = checker.cir.where_marker_copy_steps.items.items[skipped_step_index];
    try std.testing.expectEqual(@as(u32, 0), skipped_step.constraint_pairs_len);
    try std.testing.expectEqual(@as(u32, 2), skipped_step.witnesses_len);
    try std.testing.expectEqual(
        constraints_before_skip,
        checker.types.static_dispatch_constraints.items.items.len,
    );
    try std.testing.expectEqual(sources_before_skip, checker.cir.dispatch_settlement_sources.items.items.len);
    try std.testing.expectEqual(anchors_before_skip, checker.cir.selected_receiver_anchors.items.items.len);
    try std.testing.expectEqual(handles_before_skip, checker.types.constraint_evidence_handles.items.items.len);
    const skipped_occurrences = checker.cir.where_marker_copy_occurrences.items.items[skipped_step.occurrences_start..][0..skipped_step.occurrences_len];
    const skipped_witnesses = checker.cir.where_marker_copy_witnesses.items.items[skipped_step.witnesses_start..][0..skipped_step.witnesses_len];
    var skipped_receiver_witness_index: ?usize = null;
    var skipped_root_witness_count: usize = 0;
    for (skipped_witnesses, 0..) |witness, witness_index| {
        switch (witness.decodedEdgeKind() orelse return error.TestUnexpectedResult) {
            .root_copy_action => {
                skipped_root_witness_count += 1;
                try std.testing.expectEqual(skipped_step.root_occurrence_offset, witness.parent_occurrence_offset);
                try std.testing.expectEqual(skipped_step.root_occurrence_offset, witness.child_occurrence_offset);
                try std.testing.expectEqual(
                    ModuleEnv.WhereMarkerCopyWitness.Action.traverse,
                    witness.decodedAction().?,
                );
            },
            .scheme_requirement_receiver => {
                if (skipped_receiver_witness_index != null) return error.TestUnexpectedResult;
                skipped_receiver_witness_index = witness_index;
            },
            else => return error.TestUnexpectedResult,
        }
    }
    try std.testing.expectEqual(@as(usize, 1), skipped_root_witness_count);
    const skipped_receiver_index = skipped_receiver_witness_index orelse return error.TestUnexpectedResult;
    const skipped_receiver_witness = skipped_witnesses[skipped_receiver_index];
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerCopyWitness.EdgeKind.scheme_requirement_receiver,
        skipped_receiver_witness.decodedEdgeKind().?,
    );
    try std.testing.expectEqual(skipped_step.root_occurrence_offset, skipped_receiver_witness.parent_occurrence_offset);
    const skipped_receiver_occurrence = skipped_occurrences[skipped_receiver_witness.child_occurrence_offset];
    try std.testing.expectEqual(skipped_receiver_occurrence.raw_source_var, skipped_receiver_occurrence.raw_destination_var);
    canonicalizeCheckedBoundaryCopyPairBfs(
        checker.cir.where_marker_copy_pairs.items.items[skipped_step.pairs_start..][0..skipped_step.pairs_len],
        skipped_occurrences,
        skipped_witnesses,
        skipped_step.root_occurrence_offset,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    // A terminating shared receiver owns only its raw occurrence witness. A
    // forged identity constraint row has no producer append and no primary
    // function witness, even when its source index names a real constraint.
    try std.testing.expectEqual(
        checker.cir.where_marker_constraint_copy_pairs.items.items.len,
        @as(usize, skipped_step.constraint_pairs_start),
    );
    try checker.cir.where_marker_constraint_copy_pairs.items.append(checker.gpa, .{
        .source_constraint_index = source_constraint_index,
        .destination_constraint_index = source_constraint_index,
    });
    checker.cir.where_marker_copy_steps.items.items[skipped_step_index].constraint_pairs_len = 1;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    checker.cir.where_marker_copy_steps.items.items[skipped_step_index].constraint_pairs_len = 0;
    checker.cir.where_marker_constraint_copy_pairs.items.shrinkRetainingCapacity(
        skipped_step.constraint_pairs_start,
    );
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const skipped_witness_index: usize = skipped_step.witnesses_start + skipped_receiver_index;
    const saved_skipped_witness = checker.cir.where_marker_copy_witnesses.items.items[skipped_witness_index];
    checker.cir.where_marker_copy_witnesses.items.items[skipped_witness_index].action =
        @intFromEnum(ModuleEnv.WhereMarkerCopyWitness.Action.traverse);
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
    checker.cir.where_marker_copy_witnesses.items.items[skipped_witness_index] = saved_skipped_witness;
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
}

test "binding codec copied source keeps split components and remaps an earlier function pair" {
    const allocator = std.testing.allocator;
    const requirement_ordinal: u32 = 7;
    var source_env = try ModuleEnv.init(allocator, "");
    defer source_env.deinit();
    var destination_env = try ModuleEnv.init(allocator, "");
    defer destination_env.deinit();

    // The binding root and both detached components share this leaf through
    // the one import mapping. The receiver additionally contains a raw
    // redirect to itself. That second request is a distinct copy occurrence
    // with exactly the same canonical pair and destination as the root, so it
    // is a same-shaped sibling without relying on post-copy unification.
    const shared_leaf = try source_env.types.freshFromContent(.{ .structure = .empty_record });
    const binding_elems = try source_env.types.appendVars(&.{shared_leaf});
    const binding_root = try source_env.types.freshFromContent(.{ .structure = .{ .tuple = .{
        .elems = binding_elems,
    } } });
    const predicted_receiver: Var = @enumFromInt(@as(u32, @intCast(source_env.types.len() + 1)));
    const receiver_sibling = try source_env.types.freshRedirect(predicted_receiver);
    const receiver_elems = try source_env.types.appendVars(&.{ receiver_sibling, shared_leaf });
    const source_receiver = try source_env.types.freshFromContent(.{ .structure = .{ .tuple = .{
        .elems = receiver_elems,
    } } });
    try std.testing.expectEqual(predicted_receiver, source_receiver);
    try std.testing.expectEqual(
        source_env.types.resolveVar(source_receiver).var_,
        source_env.types.resolveVar(receiver_sibling).var_,
    );

    // Source index 0 is the detached binding-codec requirement. Source index
    // 1 is attached to the requirement function itself, so its ordinary graph
    // copy publishes pair/source/anchor/handle offset 0 before detached ingress
    // inserts source index 0 ahead of it.
    const predicted_function: Var = @enumFromInt(@as(u32, @intCast(source_env.types.len())));
    const detached_name = try source_env.insertIdent(base.Ident.for_text("detached_codec"));
    const attached_name = try source_env.insertIdent(base.Ident.for_text("attached_codec"));
    const detached_range = try source_env.types.appendStaticDispatchConstraints(&.{.{
        .fn_name = detached_name,
        .fn_var = predicted_function,
        .origin = .{ .where_clause = .{} },
    }});
    const attached_range = try source_env.types.appendStaticDispatchConstraints(&.{.{
        .fn_name = attached_name,
        .fn_var = shared_leaf,
        .origin = .{ .where_clause = .{} },
    }});
    const source_function = try source_env.types.freshFromContent(.{
        .flex = Flex.init().withConstraints(attached_range),
    });
    try std.testing.expectEqual(predicted_function, source_function);
    const detached_constraint_index: u32 = @intFromEnum(detached_range.start);
    try std.testing.expectEqual(@as(u32, 0), detached_constraint_index);
    try std.testing.expectEqual(@as(u32, 1), @as(u32, @intFromEnum(attached_range.start)));
    const detached_constraint = source_env.types.getStaticDispatchConstraintAt(
        detached_constraint_index,
    );

    var mapping = std.AutoHashMap(Var, Var).init(allocator);
    defer mapping.deinit();
    const copied_binding = try copy_import.copyVarWithMarkerLineageSupport(
        &source_env.types,
        &destination_env.types,
        binding_root,
        &mapping,
        null,
        &source_env,
        &destination_env,
        allocator,
        .{ .external_cir_node = .{ .node = @intFromEnum(binding_root) } },
    );
    const binding_root_step = copied_binding.copy_step orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 0), binding_root_step);
    var binding_mapping_origins = try copy_import.initBindingCodecMappingOrigins(
        allocator,
        &destination_env,
        &mapping,
        binding_root_step,
    );
    defer binding_mapping_origins.deinit();

    const copied = try copy_import.copyImportedConstraintWithMarkerLineage(
        &source_env.types,
        &destination_env.types,
        source_receiver,
        detached_constraint_index,
        detached_constraint,
        &mapping,
        &binding_mapping_origins,
        &source_env,
        &destination_env,
        allocator,
        binding_root_step,
        requirement_ordinal,
    );
    try std.testing.expectEqual(@as(u32, 1), copied.receiver_copy_step);
    try std.testing.expectEqual(@as(u32, 2), copied.function_copy_step);
    try std.testing.expect(copied.receiver_copy_step != copied.function_copy_step);

    try std.testing.expectEqual(@as(usize, 3), destination_env.where_marker_copy_steps.items.items.len);
    try std.testing.expectEqual(@as(usize, 6), destination_env.where_marker_copy_pairs.items.items.len);
    try std.testing.expectEqual(@as(usize, 7), destination_env.where_marker_copy_occurrences.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), destination_env.where_marker_constraint_copy_pairs.items.items.len);
    try std.testing.expectEqual(@as(usize, 5), destination_env.where_marker_copy_witnesses.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), destination_env.types.static_dispatch_constraints.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), destination_env.selected_receiver_anchors.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), destination_env.dispatch_settlement_sources.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), destination_env.types.constraint_evidence_handles.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), destination_env.types.where_method_marker_contracts.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), destination_env.types.where_method_marker_bases.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), destination_env.types.where_method_marker_path_steps.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), destination_env.where_marker_platform_substitutions.items.items.len);

    const receiver_step = destination_env.where_marker_copy_steps.items.items[copied.receiver_copy_step];
    const function_step = destination_env.where_marker_copy_steps.items.items[copied.function_copy_step];
    try std.testing.expectEqual(ModuleEnv.WhereMarkerCopyStep.Kind.binding_codec_receiver, receiver_step.decodedKind().?);
    try std.testing.expectEqual(ModuleEnv.WhereMarkerCopyStep.Kind.binding_codec_function, function_step.decodedKind().?);
    try std.testing.expectEqual(binding_root_step, receiver_step.origin.binding_codec_receiver.binding_root_step);
    try std.testing.expectEqual(binding_root_step, function_step.origin.binding_codec_function.binding_root_step);
    try std.testing.expectEqual(requirement_ordinal, receiver_step.origin.binding_codec_receiver.requirement_ordinal);
    try std.testing.expectEqual(requirement_ordinal, function_step.origin.binding_codec_function.requirement_ordinal);
    try std.testing.expectEqual(@as(u32, 2), function_step.constraint_pairs_len);
    try std.testing.expectEqual(@as(u32, 2), function_step.witnesses_len);

    const function_pairs = destination_env.where_marker_constraint_copy_pairs.items.items[function_step.constraint_pairs_start..][0..function_step.constraint_pairs_len];
    try std.testing.expectEqual(@as(u32, 0), function_pairs[0].source_constraint_index);
    try std.testing.expectEqual(@as(u32, 1), function_pairs[0].destination_constraint_index);
    try std.testing.expectEqual(@as(u32, 1), function_pairs[1].source_constraint_index);
    try std.testing.expectEqual(@as(u32, 0), function_pairs[1].destination_constraint_index);

    const attached_source = destination_env.dispatch_settlement_sources.items.items[0]
        .decodedCopiedConstraint() orelse return error.TestUnexpectedResult;
    const binding_source = destination_env.dispatch_settlement_sources.items.items[1]
        .decodedCopiedConstraint() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 0), attached_source.anchor_index);
    try std.testing.expectEqual(
        ModuleEnv.CopiedConstraintComponentRef.Kind.root_graph,
        attached_source.receiver_component_ref.decodedKind().?,
    );
    try std.testing.expectEqual(copied.function_copy_step, attached_source.receiver_component_ref.copy_step_index);
    try std.testing.expectEqual(copied.function_copy_step, attached_source.function_component_ref.copy_step_index);
    try std.testing.expectEqual(@as(u32, 1), attached_source.function_component_ref.constraint_pair_offset);
    try std.testing.expectEqual(@as(u32, 1), destination_env.selected_receiver_anchors.items.items[0].constraint_pair_offset);

    try std.testing.expectEqual(@as(u32, 1), binding_source.anchor_index);
    try std.testing.expectEqual(
        ModuleEnv.CopiedConstraintComponentRef.Kind.binding_codec_receiver,
        binding_source.receiver_component_ref.decodedKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.CopiedConstraintComponentRef.Kind.binding_codec_function,
        binding_source.function_component_ref.decodedKind().?,
    );
    try std.testing.expectEqual(copied.receiver_copy_step, binding_source.receiver_component_ref.copy_step_index);
    try std.testing.expectEqual(copied.function_copy_step, binding_source.function_component_ref.copy_step_index);
    try std.testing.expectEqual(binding_root_step, binding_source.receiver_component_ref.binding_root_step);
    try std.testing.expectEqual(binding_root_step, binding_source.function_component_ref.binding_root_step);
    try std.testing.expectEqual(requirement_ordinal, binding_source.receiver_component_ref.requirement_ordinal);
    try std.testing.expectEqual(requirement_ordinal, binding_source.function_component_ref.requirement_ordinal);
    try std.testing.expectEqual(@as(u32, 0), binding_source.function_component_ref.constraint_pair_offset);
    const binding_anchor = destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index];
    try std.testing.expectEqual(copied.receiver_copy_step, binding_anchor.copy_step);
    try std.testing.expectEqual(binding_source.receiver_component_ref.occurrence_offset, binding_anchor.receiver_occurrence_offset);
    try std.testing.expectEqual(binding_source.function_component_ref.constraint_pair_offset, binding_anchor.constraint_pair_offset);
    try std.testing.expectEqual(copied.constraint_index, binding_anchor.constraint_index);

    for (destination_env.types.static_dispatch_constraints.items.items, 0..) |constraint, constraint_index| {
        const evidence = destination_env.types.sliceConstraintEvidenceHandles(constraint.constraint_evidence);
        try std.testing.expectEqual(@as(usize, 1), evidence.len);
        try std.testing.expectEqual(
            types_mod.ConstraintEvidenceHandle.Kind.selected_receiver_anchor,
            evidence[0].decodedKind().?,
        );
        try std.testing.expectEqual(@as(u32, @intCast(constraint_index)), evidence[0].index);
    }

    const function_witnesses = destination_env.where_marker_copy_witnesses.items.items[function_step.witnesses_start..][0..function_step.witnesses_len];
    var static_witness_count: usize = 0;
    var ingress_witness_count: usize = 0;
    for (function_witnesses) |witness| switch (witness.decodedEdgeKind() orelse return error.TestUnexpectedResult) {
        .static_dispatch_function => {
            static_witness_count += 1;
            try std.testing.expectEqual(@as(u32, 1), witness.constraint_pair_offset);
        },
        .scheme_requirement_function => {
            ingress_witness_count += 1;
            try std.testing.expectEqual(@as(u32, 0), witness.constraint_pair_offset);
            try std.testing.expectEqual(requirement_ordinal, witness.edge_index);
            try std.testing.expectEqual(
                ModuleEnv.WhereMarkerCopyWitness.Action.requirement_component_ingress,
                witness.decodedAction().?,
            );
            try std.testing.expectEqual(
                ModuleEnv.WhereMarkerCopyWitness.AuxiliaryOriginKind.binding_scheme_codec_requirement,
                witness.decodedAuxiliaryOriginKind().?,
            );
            try std.testing.expectEqual(requirement_ordinal, witness.auxiliary_origin_index);
        },
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), static_witness_count);
    try std.testing.expectEqual(@as(usize, 1), ingress_witness_count);

    const receiver_occurrences = destination_env.where_marker_copy_occurrences.items.items[receiver_step.occurrences_start..][0..receiver_step.occurrences_len];
    const sibling_occurrence_offset: u32 = for (receiver_occurrences, 0..) |occurrence, occurrence_offset| {
        if (occurrence.raw_source_var == @intFromEnum(receiver_sibling)) break @intCast(occurrence_offset);
    } else return error.TestUnexpectedResult;
    try std.testing.expect(sibling_occurrence_offset != receiver_step.root_occurrence_offset);
    const root_occurrence = receiver_occurrences[receiver_step.root_occurrence_offset];
    const sibling_occurrence = receiver_occurrences[sibling_occurrence_offset];
    try std.testing.expectEqual(root_occurrence.raw_destination_var, sibling_occurrence.raw_destination_var);
    try std.testing.expectEqual(root_occurrence.canonical_pair_offset, sibling_occurrence.canonical_pair_offset);

    // Draft producers leave non-root BFS words unset. Stamp every step with
    // the exact production terminal canonicalizer before asking admission to
    // consume either copied source.
    for (destination_env.where_marker_copy_steps.items.items) |step| {
        canonicalizeCheckedBoundaryCopyPairBfs(
            destination_env.where_marker_copy_pairs.items.items[step.pairs_start..][0..step.pairs_len],
            destination_env.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len],
            destination_env.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len],
            step.root_occurrence_offset,
        );
    }
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&destination_env.types, &destination_env));
    try std.testing.expect(validateDispatchSettlementSourceContext(&destination_env, 0));
    try std.testing.expect(validateDispatchSettlementSourceContext(&destination_env, 1));

    const binding_source_row = destination_env.dispatch_settlement_sources.items.items[1];
    const binding_anchor_row = destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index];

    // A coordinated anchor projection cannot turn the receiver component into
    // the function component. All occurrence/receiver words are retargeted
    // together so the typed child-step role is the rejecting coordinate.
    const function_root_occurrence = destination_env.where_marker_copy_occurrences.items.items[
        function_step.occurrences_start + function_step.root_occurrence_offset
    ];
    destination_env.dispatch_settlement_sources.items.items[1]
        .payload.copied_constraint.receiver_component_ref.copy_step_index = copied.function_copy_step;
    destination_env.dispatch_settlement_sources.items.items[1]
        .payload.copied_constraint.receiver_component_ref.occurrence_offset = function_step.root_occurrence_offset;
    destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index].copy_step = copied.function_copy_step;
    destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index]
        .receiver_occurrence_offset = function_step.root_occurrence_offset;
    destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index]
        .receiver_var = function_root_occurrence.raw_destination_var;
    try std.testing.expect(!validateDispatchSettlementSourceContext(&destination_env, 1));
    destination_env.dispatch_settlement_sources.items.items[1] = binding_source_row;
    destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index] = binding_anchor_row;

    destination_env.dispatch_settlement_sources.items.items[1]
        .payload.copied_constraint.receiver_component_ref.binding_root_step = copied.receiver_copy_step;
    destination_env.dispatch_settlement_sources.items.items[1]
        .payload.copied_constraint.function_component_ref.binding_root_step = copied.receiver_copy_step;
    try std.testing.expect(!validateDispatchSettlementSourceContext(&destination_env, 1));
    destination_env.dispatch_settlement_sources.items.items[1] = binding_source_row;

    destination_env.dispatch_settlement_sources.items.items[1]
        .payload.copied_constraint.receiver_component_ref.requirement_ordinal = requirement_ordinal + 1;
    destination_env.dispatch_settlement_sources.items.items[1]
        .payload.copied_constraint.function_component_ref.requirement_ordinal = requirement_ordinal + 1;
    try std.testing.expect(!validateDispatchSettlementSourceContext(&destination_env, 1));
    destination_env.dispatch_settlement_sources.items.items[1] = binding_source_row;

    destination_env.dispatch_settlement_sources.items.items[1]
        .payload.copied_constraint.function_component_ref.constraint_pair_offset = 1;
    destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index].constraint_pair_offset = 1;
    try std.testing.expect(!validateDispatchSettlementSourceContext(&destination_env, 1));
    destination_env.dispatch_settlement_sources.items.items[1] = binding_source_row;
    destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index] = binding_anchor_row;

    // The sibling has the same raw destination and canonical solved pair, so
    // only the immutable receiver-occurrence coordinate distinguishes it from
    // the authored root occurrence.
    destination_env.dispatch_settlement_sources.items.items[1]
        .payload.copied_constraint.receiver_component_ref.occurrence_offset = sibling_occurrence_offset;
    destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index]
        .receiver_occurrence_offset = sibling_occurrence_offset;
    try std.testing.expect(!validateDispatchSettlementSourceContext(&destination_env, 1));
    destination_env.dispatch_settlement_sources.items.items[1] = binding_source_row;
    destination_env.selected_receiver_anchors.items.items[binding_source.anchor_index] = binding_anchor_row;

    try std.testing.expect(validateWhereMarkerCopyProofLocal(&destination_env.types, &destination_env));
    try std.testing.expect(validateDispatchSettlementSourceContext(&destination_env, 0));
    try std.testing.expect(validateDispatchSettlementSourceContext(&destination_env, 1));

    // The provenance table preserves the component which first authored each
    // mapping across every later requirement. A second requirement is an
    // authenticated reuse consumer, but its identical pair is not valid
    // provenance for a third requirement's cut.
    const second = try copy_import.copyImportedConstraintWithMarkerLineage(
        &source_env.types,
        &destination_env.types,
        source_receiver,
        detached_constraint_index,
        detached_constraint,
        &mapping,
        &binding_mapping_origins,
        &source_env,
        &destination_env,
        allocator,
        binding_root_step,
        requirement_ordinal + 1,
    );
    const third = try copy_import.copyImportedConstraintWithMarkerLineage(
        &source_env.types,
        &destination_env.types,
        source_receiver,
        detached_constraint_index,
        detached_constraint,
        &mapping,
        &binding_mapping_origins,
        &source_env,
        &destination_env,
        allocator,
        binding_root_step,
        requirement_ordinal + 2,
    );
    for ([_]u32{
        second.receiver_copy_step,
        second.function_copy_step,
        third.receiver_copy_step,
        third.function_copy_step,
    }) |step_index| {
        const component_step = destination_env.where_marker_copy_steps.items.items[step_index];
        canonicalizeCheckedBoundaryCopyPairBfs(
            destination_env.where_marker_copy_pairs.items.items[component_step.pairs_start..][0..component_step.pairs_len],
            destination_env.where_marker_copy_occurrences.items.items[component_step.occurrences_start..][0..component_step.occurrences_len],
            destination_env.where_marker_copy_witnesses.items.items[component_step.witnesses_start..][0..component_step.witnesses_len],
            component_step.root_occurrence_offset,
        );
    }
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&destination_env.types, &destination_env));

    const second_receiver_step = destination_env.where_marker_copy_steps.items.items[second.receiver_copy_step];
    const third_receiver_step = destination_env.where_marker_copy_steps.items.items[third.receiver_copy_step];
    const third_witnesses = destination_env.where_marker_copy_witnesses.items.items[third_receiver_step.witnesses_start..][0..third_receiver_step.witnesses_len];
    const third_root_witness_offset: u32 = for (third_witnesses, 0..) |witness, witness_offset| {
        if (witness.decodedEdgeKind() == .root_copy_action and
            witness.decodedAction() == .binding_codec_reuse_cut)
        {
            try std.testing.expectEqual(copied.receiver_copy_step, witness.auxiliary_origin_step);
            break @intCast(witness_offset);
        }
    } else return error.TestUnexpectedResult;
    const third_witness_index = third_receiver_step.witnesses_start + third_root_witness_offset;
    const saved_third_root_witness = destination_env.where_marker_copy_witnesses.items.items[third_witness_index];
    const original_pair = destination_env.where_marker_copy_pairs.items.items[
        destination_env.where_marker_copy_steps.items.items[saved_third_root_witness.auxiliary_origin_step].pairs_start +
            saved_third_root_witness.auxiliary_origin_index
    ];
    const second_matching_pair_offset: u32 = for (
        destination_env.where_marker_copy_pairs.items.items[second_receiver_step.pairs_start..][0..second_receiver_step.pairs_len],
        0..,
    ) |pair, pair_offset| {
        if (std.meta.eql(pair, original_pair)) break @intCast(pair_offset);
    } else return error.TestUnexpectedResult;

    destination_env.where_marker_copy_witnesses.items.items[third_witness_index].auxiliary_origin_step =
        second.receiver_copy_step;
    destination_env.where_marker_copy_witnesses.items.items[third_witness_index].auxiliary_origin_index =
        second_matching_pair_offset;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(&destination_env.types, &destination_env));
    destination_env.where_marker_copy_witnesses.items.items[third_witness_index] = saved_third_root_witness;
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&destination_env.types, &destination_env));
}

test "scheme requirement candidate capture reads evidence published through its exact occurrence" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("SchemeCandidatePublishedEvidence", "{}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const owner = try checker.types.freshFromContent(.{ .structure = .empty_record });
    const callable = try checker.types.freshFromContent(.{ .structure = .empty_record });
    const constraint_range = try checker.types.appendStaticDispatchConstraints(&.{.{
        .fn_name = checker.cir.idents.is_eq,
        .fn_var = callable,
        .origin = .{ .where_clause = .{} },
    }});
    const constraint_index: u32 = @intFromEnum(constraint_range.start);
    const original_constraint = checker.types.getStaticDispatchConstraintAt(constraint_index);

    checker.active_scheme_root = owner;
    defer checker.active_scheme_root = null;
    try checker.recordSchemeRequirementCandidate(
        owner,
        original_constraint,
        constraint_index,
        .scheme_copy,
        .{ .receiver_var = owner, .constraint_fn_var = callable },
        true,
    );

    // Local copy publication runs after candidate registration. Mutate only
    // the exact indexed occurrence, just as that producer does when it
    // attaches its selected-receiver/copied-literal handle set.
    const published_evidence = try checker.types.appendConstraintEvidenceHandles(&.{.{
        .kind = @intFromEnum(types_mod.ConstraintEvidenceHandle.Kind.where_requirement_source),
        .index = 73,
    }});
    checker.types.static_dispatch_constraints.items.items[constraint_index].constraint_evidence = published_evidence;

    try checker.captureSchemeDispatchRequirements(
        &.{.{ .owner = owner, .interface = owner }},
        &env,
    );
    const scheme_index = checker.typeSchemeIndexForRoot(owner) orelse return error.TestUnexpectedResult;
    const requirements = checker.type_schemes.items[scheme_index].dispatch_requirements.items;
    try std.testing.expectEqual(@as(usize, 1), requirements.len);
    try std.testing.expectEqual(constraint_index, requirements[0].constraint_index);
    try std.testing.expectEqual(published_evidence, requirements[0].constraint.constraint_evidence);
    try std.testing.expect(std.meta.eql(
        checker.types.getStaticDispatchConstraintAt(constraint_index),
        requirements[0].constraint,
    ));
}

test "exact root substitution does not re-own its caller rank-pool entry" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("ExactRootSubstitutionOwnership", "{}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    var env = try Env.init(checker.gpa, .outermost);
    defer env.deinit(checker.gpa);
    const seed = try checker.fresh(&env, Region.zero());
    const rigid_name = try checker.cir.insertIdent(base.Ident.for_text("seeded"));
    const source = try checker.types.freshFromContentWithRank(
        .{ .rigid = Rigid.init(rigid_name) },
        .generalized,
    );
    try checker.fillInRegionsThrough(source);
    checker.setRegionAt(source, Region.zero());

    var substitutions = std.AutoHashMapUnmanaged(Ident.Idx, Var){};
    defer substitutions.deinit(checker.gpa);
    try substitutions.put(checker.gpa, rigid_name, seed);
    var instantiator = Instantiator{
        .store = checker.types,
        .idents = checker.cir.getIdentStoreConst(),
        .var_map = &checker.var_map,
        .current_rank = env.rank(),
        .rigid_behavior = .{ .substitute_rigids = &substitutions },
        .polarity_var_ident = checker.cir.idents.polarity_var,
        .anonymous_ext_ident = checker.cir.idents.open_ext,
    };
    const pool_len_before = env.var_pool.getVarsForRank(.outermost).len;
    const open_literals_before = checker.open_literal_vars.items.len;
    const ambiguity_candidates_before = checker.ambiguity_candidates.items.len;

    const instantiated = try checker.instantiateVarHelp(
        source,
        &instantiator,
        &env,
        .{ .explicit = Region.zero() },
        false,
    );
    try std.testing.expectEqual(seed, instantiated);
    try std.testing.expectEqual(pool_len_before, env.var_pool.getVarsForRank(.outermost).len);
    try std.testing.expectEqual(open_literals_before, checker.open_literal_vars.items.len);
    try std.testing.expectEqual(ambiguity_candidates_before, checker.ambiguity_candidates.items.len);
}

fn expectLiteralGroupOwnsOneOfRepeatedDestinationOccurrences(
    checker: *const Self,
    group: ModuleEnv.CopiedOpenLiteralGroup,
) !void {
    if (group.copy_step_index >= checker.cir.where_marker_copy_steps.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const step = checker.cir.where_marker_copy_steps.items.items[group.copy_step_index];
    if (group.receiver_occurrence_offset >= step.occurrences_len or
        !rangeFits(
            step.occurrences_start,
            step.occurrences_len,
            checker.cir.where_marker_copy_occurrences.items.items.len,
        ) or
        !rangeFits(
            step.copied_groups_start,
            step.copied_groups_len,
            checker.cir.copied_open_literal_groups.items.items.len,
        ))
    {
        return error.TestUnexpectedResult;
    }
    const occurrences = checker.cir.where_marker_copy_occurrences.items.items[step.occurrences_start..][0..step.occurrences_len];
    const raw_destination = occurrences[group.receiver_occurrence_offset].raw_destination_var;
    var matching_occurrences: usize = 0;
    for (occurrences) |occurrence| {
        matching_occurrences += @intFromBool(occurrence.raw_destination_var == raw_destination);
    }
    try std.testing.expect(matching_occurrences > 1);

    var matching_groups: usize = 0;
    for (checker.cir.copied_open_literal_groups.items.items[step.copied_groups_start..][0..step.copied_groups_len]) |candidate| {
        if (candidate.receiver_occurrence_offset >= occurrences.len) {
            return error.TestUnexpectedResult;
        }
        matching_groups += @intFromBool(
            occurrences[candidate.receiver_occurrence_offset].raw_destination_var == raw_destination,
        );
    }
    try std.testing.expectEqual(@as(usize, 1), matching_groups);
}

test "copy_import accepts a binding codec with a function-owned open numeral" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\Format := [Default].{
        \\    rename_field : Format, Str -> Str
        \\    rename_field = |_, name| name
        \\
        \\    encode_record : state, U64, (state, (state, Str, (state -> Try(state, [])) -> Try(state, [])) -> Try(state, [])) -> Try(state, [])
        \\    encode_record = |state, _, write_fields|
        \\        write_fields(state, |field_state, _, write_value| write_value(field_state))
        \\}
        \\
        \\Wrap(a) :: { item : a }.{
        \\    encoder_for : _
        \\}
        \\
        \\encode : value, state -> Try(state, [])
        \\    where [
        \\        value.encoder_for : Format -> (value, state -> Try(state, [])),
        \\    ]
        \\encode = |value, state| {
        \\    Shape : value
        \\    encode_value = Shape.encoder_for(Format.Default)
        \\    encode_value(value, state)
        \\}
        \\
        \\A := [A].{
        \\    make : a -> a
        \\    make = |item| {
        \\        _ignored = encode(Wrap.{ item: item }, 0)
        \\        item
        \\    }
        \\}
    ;
    var provider = try TestEnv.init("A", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();
    try std.testing.expect(
        provider.module_env.binding_scheme_codec_requirements.items.items.len != 0,
    );

    const consumer_source =
        \\import A
        \\
        \\forward = A.make
    ;
    var consumer = try TestEnv.initWithImport(
        "B",
        consumer_source,
        "A",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertNoErrors();
    const checker = &consumer.checker;

    var matching_events: usize = 0;
    for (checker.cir.copied_open_literal_groups.items.items) |group| {
        if (group.component.decodedKind() != .binding_codec_function) continue;
        if (group.copy_step_index >= checker.cir.where_marker_copy_steps.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const step = checker.cir.where_marker_copy_steps.items.items[group.copy_step_index];
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyStep.Kind.binding_codec_function,
            step.decodedKind().?,
        );
        try std.testing.expectEqual(
            step.origin.binding_codec_function.binding_root_step,
            group.component.binding_root_step,
        );
        try std.testing.expectEqual(
            step.origin.binding_codec_function.requirement_ordinal,
            group.component.requirement_ordinal,
        );
        var group_has_numeral = false;
        for (checker.cir.copied_open_literal_events.items.items[group.events_start..][0..group.events_len]) |event| {
            group_has_numeral = group_has_numeral or event.decodedLiteralKind() == .numeral;
            matching_events += @intFromBool(event.decodedLiteralKind() == .numeral);
        }
        if (group_has_numeral) {
            try expectLiteralGroupOwnsOneOfRepeatedDestinationOccurrences(checker, group);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), matching_events);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_before);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const serialized_after = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_after);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after);
}

test "copy_import accepts a binding codec with a receiver-owned open numeral" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\Format := [Default].{
        \\    rename_field : Format, Str -> Str
        \\    rename_field = |_, name| name
        \\
        \\    encode_record : state, U64, (state, (state, Str, (state -> Try(state, [])) -> Try(state, [])) -> Try(state, [])) -> Try(state, [])
        \\    encode_record = |state, _, write_fields|
        \\        write_fields(state, |field_state, _, write_value| write_value(field_state))
        \\}
        \\
        \\Wrap(a, b) :: { item : a, seed : b }.{
        \\    encoder_for : _
        \\}
        \\
        \\encode : value, state -> Try(state, [])
        \\    where [
        \\        value.encoder_for : Format -> (value, state -> Try(state, [])),
        \\    ]
        \\encode = |value, state| {
        \\    Shape : value
        \\    encode_value = Shape.encoder_for(Format.Default)
        \\    encode_value(value, state)
        \\}
        \\
        \\A := [A].{
        \\    make : a -> a
        \\    make = |item| {
        \\        seed = 0
        \\        _ignored = encode(Wrap.{ item: item, seed: seed }, seed)
        \\        item
        \\    }
        \\}
    ;
    var provider = try TestEnv.init("A", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();
    try std.testing.expect(
        provider.module_env.binding_scheme_codec_requirements.items.items.len != 0,
    );

    const consumer_source =
        \\import A
        \\
        \\forward = A.make
    ;
    var consumer = try TestEnv.initWithImport(
        "B",
        consumer_source,
        "A",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertNoErrors();
    const checker = &consumer.checker;

    var matching_events: usize = 0;
    var literal_receiver_step_index: ?u32 = null;
    var literal_receiver_pair_offset: ?u32 = null;
    var literal_binding_root_step: ?u32 = null;
    var literal_requirement_ordinal: ?u32 = null;
    for (checker.cir.copied_open_literal_groups.items.items) |group| {
        if (group.component.decodedKind() != .binding_codec_receiver) continue;
        if (group.copy_step_index >= checker.cir.where_marker_copy_steps.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const step = checker.cir.where_marker_copy_steps.items.items[group.copy_step_index];
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyStep.Kind.binding_codec_receiver,
            step.decodedKind().?,
        );
        try std.testing.expectEqual(
            step.origin.binding_codec_receiver.binding_root_step,
            group.component.binding_root_step,
        );
        try std.testing.expectEqual(
            step.origin.binding_codec_receiver.requirement_ordinal,
            group.component.requirement_ordinal,
        );
        var group_has_numeral = false;
        for (checker.cir.copied_open_literal_events.items.items[group.events_start..][0..group.events_len]) |event| {
            if (event.decodedLiteralKind() != .numeral) continue;
            group_has_numeral = true;
            matching_events += 1;
            if (literal_receiver_step_index != null) return error.TestUnexpectedResult;
            const receiver_occurrence = checker.cir.where_marker_copy_occurrences.items.items[
                step.occurrences_start + group.receiver_occurrence_offset
            ];
            literal_receiver_step_index = group.copy_step_index;
            literal_receiver_pair_offset = receiver_occurrence.canonical_pair_offset;
            literal_binding_root_step = group.component.binding_root_step;
            literal_requirement_ordinal = group.component.requirement_ordinal;
        }
        if (group_has_numeral) {
            try expectLiteralGroupOwnsOneOfRepeatedDestinationOccurrences(checker, group);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), matching_events);

    // The function graph consumes the same open state variable that the
    // receiver component freshly copied. Its cut must cite that exact prior
    // component pair, rather than pretending the binding-root copy owned it.
    const receiver_step_index = literal_receiver_step_index orelse
        return error.TestUnexpectedResult;
    const receiver_pair_offset = literal_receiver_pair_offset orelse
        return error.TestUnexpectedResult;
    const binding_root_step = literal_binding_root_step orelse
        return error.TestUnexpectedResult;
    const requirement_ordinal = literal_requirement_ordinal orelse
        return error.TestUnexpectedResult;
    var matching_function_steps: usize = 0;
    var matching_receiver_cuts: usize = 0;
    for (checker.cir.where_marker_copy_steps.items.items) |step| {
        if (step.decodedKind() != .binding_codec_function or
            step.origin.binding_codec_function.binding_root_step != binding_root_step or
            step.origin.binding_codec_function.requirement_ordinal != requirement_ordinal)
        {
            continue;
        }
        matching_function_steps += 1;
        for (checker.cir.where_marker_copy_witnesses.items.items[step.witnesses_start..][0..step.witnesses_len]) |witness| {
            if (witness.decodedAction() != .binding_codec_reuse_cut or
                witness.decodedAuxiliaryOriginKind() != .binding_copy_pair or
                witness.auxiliary_origin_step != receiver_step_index or
                witness.auxiliary_origin_index != receiver_pair_offset)
            {
                continue;
            }
            matching_receiver_cuts += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 1), matching_function_steps);
    try std.testing.expectEqual(@as(usize, 1), matching_receiver_cuts);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));

    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_before);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const serialized_after = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_after);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after);
}

fn testFindNominalSourceDecl(env: *const ModuleEnv, name: []const u8) !u32 {
    const expected_ident = env.common.findIdent(name) orelse return error.TestUnexpectedResult;
    var found: ?u32 = null;
    for (0..env.type_decls.span.len) |offset| {
        const statement_index = env.store.statementAt(env.type_decls, @intCast(offset));
        const statement = env.store.getStatement(statement_index);
        if (statement != .s_nominal_decl) continue;
        const header = env.store.getTypeHeader(statement.s_nominal_decl.header);
        if (!header.relative_name.eql(expected_ident)) continue;
        if (found != null) return error.TestUnexpectedResult;
        found = @intFromEnum(statement_index);
    }
    return found orelse error.TestUnexpectedResult;
}

fn testFindAliasSourceDecl(env: *const ModuleEnv, name: []const u8) !u32 {
    const expected_ident = env.common.findIdent(name) orelse return error.TestUnexpectedResult;
    var found: ?u32 = null;
    for (0..env.type_decls.span.len) |offset| {
        const statement_index = env.store.statementAt(env.type_decls, @intCast(offset));
        const statement = env.store.getStatement(statement_index);
        if (statement != .s_alias_decl) continue;
        const header = env.store.getTypeHeader(statement.s_alias_decl.header);
        if (!header.relative_name.eql(expected_ident)) continue;
        if (found != null) return error.TestUnexpectedResult;
        found = @intFromEnum(statement_index);
    }
    return found orelse error.TestUnexpectedResult;
}

const TestSelectedOwnerValidation = struct {
    root_origin: bool,
    terminal_context: bool,
};

fn testSelectedOwnerValidation(
    env: *const ModuleEnv,
    builtin_env: *const ModuleEnv,
    context: ImportResolution,
    root_step_index: usize,
) TestSelectedOwnerValidation {
    const terminal_context = validateSelectedMethodDecisionsContext(env, builtin_env, context);
    const steps = env.where_marker_copy_steps.items.items;
    if (root_step_index >= steps.len) return .{ .root_origin = false, .terminal_context = terminal_context };
    const authority = whereMarkerCrossRootAuthority(
        env,
        builtin_env,
        context,
        steps,
        root_step_index,
    ) orelse return .{ .root_origin = false, .terminal_context = terminal_context };
    return .{
        .root_origin = validateSelectedWhereMarkerOrigin(
            env,
            builtin_env,
            context,
            root_step_index,
            steps[root_step_index],
            authority,
        ),
        .terminal_context = terminal_context,
    };
}

test "selected method marker copy retains its exact dispatch occurrence" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\SelectedOriginProvider := [Runner].{
        \\    run : SelectedOriginProvider, a -> [One] where [a.pick : a -> [One]]
        \\    run = |_, value| value.pick()
        \\}
        \\
        \\SiblingRunner := [Sibling].{
        \\    run : SiblingRunner, a -> [One] where [a.pick : a -> [One]]
        \\    run = |_, value| value.pick()
        \\}
    ;
    var provider = try TestEnv.init("SelectedOriginProvider", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import SelectedOriginProvider
        \\
        \\Choice := [Choice].{
        \\    pick : Choice -> [One]
        \\    pick = |_| One
        \\}
        \\
        \\runner = SelectedOriginProvider.Runner
        \\choice = Choice.Choice
        \\out = (if True { |value| value.run(choice) } else { |value| value.run(choice) })(runner)
    ;
    var consumer = try TestEnv.initWithImport(
        "SelectedOriginConsumer",
        consumer_source,
        "SelectedOriginProvider",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertNoErrors();

    const checker = &consumer.checker;
    const provider_identity = checker.cir.lookupModuleIdentity(
        provider.module_env.contentIdentityHash() orelse return error.TestUnexpectedResult,
    ) orelse return error.TestUnexpectedResult;
    const provider_owner_decl = try testFindNominalSourceDecl(
        provider.module_env,
        "SelectedOriginProvider",
    );
    const sibling_owner_decl = try testFindNominalSourceDecl(provider.module_env, "SiblingRunner");
    // A second terminal rebuild must authenticate the selected provider from
    // the durable decision/root relation. The checker's transient imported-
    // method cache still carries preterminal step ordinals and is not an
    // authority for this replay.
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const constraints = checker.types.static_dispatch_constraints.items.items;
    const scheme_uses = checker.cir.scheme_uses.items.items;
    var selected_count: usize = 0;
    var selected_step_index: ?usize = null;
    for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.decodedKind().? != .selected_dispatch_method) continue;
        selected_count += 1;
        selected_step_index = step_index;
        const origin = step.origin.selected_dispatch_method;
        try std.testing.expect(origin.decision_index < checker.cir.selected_method_decisions.items.items.len);
        const decision = checker.cir.selected_method_decisions.items.items[origin.decision_index];
        try std.testing.expectEqual(ModuleEnv.SelectedMethodDecision.State.complete, decision.decodedState().?);
        try std.testing.expectEqual(@as(u32, @intCast(step_index)), decision.root_copy_step);
        const scheme_use = scheme_uses[decision.scheme_use_index];
        try std.testing.expectEqual(
            checker.types.resolveVar(@enumFromInt(step.destination_root_var)).var_,
            checker.types.resolveVar(@enumFromInt(scheme_use.scheme_root)).var_,
        );
    }
    try std.testing.expectEqual(@as(usize, 1), selected_count);
    try std.testing.expectEqual(@as(usize, 2), checker.cir.selected_method_decisions.items.items.len);
    const all_anchors = checker.cir.selected_receiver_anchors.items.items;
    var branch_anchor_indices: [2]u32 = undefined;
    var branch_anchor_count: usize = 0;

    var selected_move_count: usize = 0;
    var moved_anchor_count: usize = 0;
    for (checker.cir.selected_method_decisions.items.items) |decision| {
        try std.testing.expectEqual(ModuleEnv.SelectedMethodDecision.State.complete, decision.decodedState().?);
        try std.testing.expect(decision.constraint_index < constraints.len);
        try std.testing.expect(decision.receiver_var < checker.types.len());
        try std.testing.expect(decision.scheme_use_index < scheme_uses.len);
        const constraint = constraints[decision.constraint_index];
        const terminal_handles = checker.types.sliceConstraintEvidenceHandles(constraint.constraint_evidence);
        const decision_moves = checker.cir.selected_method_decision_moves.items.items[decision.constraint_moves_start..][0..decision.constraint_moves_len];
        selected_move_count += decision.constraint_moves_len;
        var first_selected_anchor: ?u32 = null;
        var raw_dispatch_anchor: ?u32 = null;
        for (terminal_handles) |handle| {
            if (handle.decodedKind() != .selected_receiver_anchor) continue;
            const anchor = all_anchors[handle.index];
            if (first_selected_anchor == null) {
                first_selected_anchor = handle.index;
                try std.testing.expectEqual(anchor.receiver_var, decision.receiver_var);
            }
            if (anchor.receiver_var == decision.receiver_var and
                anchor.decodedKind() == .dispatch_expr)
            {
                if (raw_dispatch_anchor != null) return error.TestUnexpectedResult;
                raw_dispatch_anchor = handle.index;
            }
            if (anchor.constraint_index == decision.constraint_index) continue;
            moved_anchor_count += 1;
            var saw_source = false;
            var saw_terminal = false;
            for (decision_moves) |move_ref| {
                if (move_ref.receiver_anchor_index != handle.index) continue;
                const move = checker.cir.constraint_evidence_moves.items.items[move_ref.constraint_move_index];
                saw_source = saw_source or move.source_constraint_index == anchor.constraint_index;
                saw_terminal = saw_terminal or move.destination_constraint_index == decision.constraint_index;
            }
            try std.testing.expect(saw_source);
            try std.testing.expect(saw_terminal);
        }
        try std.testing.expect(first_selected_anchor != null);
        if (branch_anchor_count >= branch_anchor_indices.len) return error.TestUnexpectedResult;
        branch_anchor_indices[branch_anchor_count] = raw_dispatch_anchor orelse
            return error.TestUnexpectedResult;
        branch_anchor_count += 1;
        const scheme_use = scheme_uses[decision.scheme_use_index];
        try std.testing.expectEqual(
            ModuleEnv.SchemeUseRecord.Slot.dispatch_target,
            std.enums.fromInt(ModuleEnv.SchemeUseRecord.Slot, scheme_use.slot_kind).?,
        );
        try std.testing.expectEqual(@intFromEnum(constraint.fn_var), scheme_use.slot_data);
        try std.testing.expect(decision.provider_dependency_index < checker.owner_modules.len);
        try std.testing.expectEqual(
            @intFromPtr(provider.module_env),
            @intFromPtr(checker.owner_modules[decision.provider_dependency_index]),
        );
        try std.testing.expectEqual(
            @intFromEnum(provider_identity),
            decision.receiver_owner_origin_module,
        );
        try std.testing.expectEqual(provider_owner_decl, decision.receiver_owner_source_decl);
    }
    // The two branch-local receiver constraints merge before the selected
    // callable is applied to the nominal runner. Their exact receiver anchor
    // chain must remain accepted while a same-typed raw sibling receiver
    // retarget below is rejected.
    try std.testing.expect(selected_move_count != 0);
    try std.testing.expectEqual(branch_anchor_indices.len, branch_anchor_count);
    try std.testing.expect(moved_anchor_count != 0);
    for (branch_anchor_indices) |anchor_index| {
        var terminal_owner_count: usize = 0;
        for (checker.cir.selected_method_decisions.items.items) |decision| {
            const constraint = constraints[decision.constraint_index];
            for (checker.types.sliceConstraintEvidenceHandles(constraint.constraint_evidence)) |handle| {
                if (handle.decodedKind() == .selected_receiver_anchor and handle.index == anchor_index) {
                    terminal_owner_count += 1;
                }
            }
        }
        try std.testing.expectEqual(@as(usize, 1), terminal_owner_count);
    }
    for (checker.cir.constraint_evidence_moves.items.items, 0..) |move, move_index| {
        if (move.handle.decodedKind() != .selected_receiver_anchor) continue;
        var decision_owner_count: usize = 0;
        for (checker.cir.selected_method_decisions.items.items) |decision| {
            for (checker.cir.selected_method_decision_moves.items.items[decision.constraint_moves_start..][0..decision.constraint_moves_len]) |move_ref| {
                if (move_ref.receiver_anchor_index == move.handle.index and
                    move_ref.constraint_move_index == @as(u32, @intCast(move_index)))
                {
                    decision_owner_count += 1;
                }
            }
        }
        try std.testing.expectEqual(@as(usize, 1), decision_owner_count);
    }

    const context = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );

    // These two branch-local raw receivers have legitimately merged by the
    // terminal boundary. Retargeting one immutable source snapshot to the
    // same-shaped sibling must still fail exact raw-coordinate replay; root
    // equality is not source authority.
    const first_branch_anchor = all_anchors[branch_anchor_indices[0]];
    const second_branch_anchor = all_anchors[branch_anchor_indices[1]];
    try std.testing.expectEqual(
        ModuleEnv.SelectedMethodDecision.ReceiverAnchorKind.dispatch_expr,
        first_branch_anchor.decodedKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.SelectedMethodDecision.ReceiverAnchorKind.dispatch_expr,
        second_branch_anchor.decodedKind().?,
    );
    try std.testing.expect(first_branch_anchor.node != second_branch_anchor.node);
    try std.testing.expect(first_branch_anchor.receiver_var != second_branch_anchor.receiver_var);
    try std.testing.expect(selectedResolvedVarsEqual(
        checker.cir,
        first_branch_anchor.receiver_var,
        second_branch_anchor.receiver_var,
    ));
    const first_source_index: usize = for (checker.cir.dispatch_settlement_sources.items.items, 0..) |source, source_index| {
        if (source.decodedKind() == .dispatch_expr and
            source.payload.dispatch_expr.anchor_index == branch_anchor_indices[0])
        {
            break source_index;
        }
    } else return error.TestUnexpectedResult;
    const first_source = &checker.cir.dispatch_settlement_sources.items.items[first_source_index];
    const first_raw_receiver = first_source.payload.dispatch_expr.receiver_var;
    first_source.payload.dispatch_expr.receiver_var = second_branch_anchor.receiver_var;
    const sibling_source_result = validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );
    first_source.payload.dispatch_expr.receiver_var = first_raw_receiver;
    try std.testing.expectError(error.CorruptArtifact, sibling_source_result);
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );

    const second_source_index: usize = for (checker.cir.dispatch_settlement_sources.items.items, 0..) |source, source_index| {
        if (source.decodedKind() == .dispatch_expr and
            source.payload.dispatch_expr.anchor_index == branch_anchor_indices[1])
        {
            break source_index;
        }
    } else return error.TestUnexpectedResult;
    const original_first_source = checker.cir.dispatch_settlement_sources.items.items[first_source_index];
    const second_source = checker.cir.dispatch_settlement_sources.items.items[second_source_index];
    const first_dispatch_source = original_first_source.payload.dispatch_expr;
    const second_dispatch_source = second_source.payload.dispatch_expr;
    try std.testing.expectEqual(
        ModuleEnv.DispatchSettlementSource.OriginalNodeKind.dispatch_call,
        original_first_source.decodedOriginalNodeKind().?,
    );
    try std.testing.expect(checker.cir.store.getExpr(@enumFromInt(first_dispatch_source.node_index)) == .e_dispatch_call);

    var first_terminal_receiver: ?u32 = null;
    for (checker.cir.selected_method_decisions.items.items) |candidate| {
        const terminal_constraint = constraints[candidate.constraint_index];
        for (checker.types.sliceConstraintEvidenceHandles(terminal_constraint.constraint_evidence)) |handle| {
            if (handle.decodedKind() != .selected_receiver_anchor or
                handle.index != branch_anchor_indices[0])
            {
                continue;
            }
            if (first_terminal_receiver != null) return error.TestUnexpectedResult;
            first_terminal_receiver = candidate.receiver_var;
        }
    }
    const terminal_receiver = first_terminal_receiver orelse return error.TestUnexpectedResult;
    try std.testing.expect(validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    ));

    // A live dispatch is authenticated from the complete immutable source
    // tuple. Every tuple coordinate remains binding even though later
    // selected-decision validation no longer re-reads the live CIR payload.
    try std.testing.expect(first_dispatch_source.node_index != second_dispatch_source.node_index);
    checker.cir.dispatch_settlement_sources.items.items[first_source_index]
        .payload.dispatch_expr.node_index = second_dispatch_source.node_index;
    try std.testing.expect(!validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    ));
    checker.cir.dispatch_settlement_sources.items.items[first_source_index] = original_first_source;

    checker.cir.dispatch_settlement_sources.items.items[first_source_index]
        .payload.dispatch_expr.original_node_kind = std.math.maxInt(u32);
    try std.testing.expect(!validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    ));
    checker.cir.dispatch_settlement_sources.items.items[first_source_index] = original_first_source;

    try std.testing.expect(constraints[first_branch_anchor.constraint_index].origin == .method_call);
    checker.cir.dispatch_settlement_sources.items.items[first_source_index]
        .payload.dispatch_expr.original_node_kind =
        @intFromEnum(ModuleEnv.DispatchSettlementSource.OriginalNodeKind.method_eq_is_eq);
    try std.testing.expect(!validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    ));
    checker.cir.dispatch_settlement_sources.items.items[first_source_index] = original_first_source;

    try std.testing.expect(first_dispatch_source.constraint_fn_var != second_dispatch_source.constraint_fn_var);
    checker.cir.dispatch_settlement_sources.items.items[first_source_index]
        .payload.dispatch_expr.constraint_fn_var = second_dispatch_source.constraint_fn_var;
    try std.testing.expect(!validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    ));
    checker.cir.dispatch_settlement_sources.items.items[first_source_index] = original_first_source;

    const is_eq_ident: u32 = @bitCast(checker.cir.idents.is_eq);
    try std.testing.expect(first_dispatch_source.method_ident != is_eq_ident);
    checker.cir.dispatch_settlement_sources.items.items[first_source_index]
        .payload.dispatch_expr.method_ident = is_eq_ident;
    try std.testing.expect(!validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    ));
    checker.cir.dispatch_settlement_sources.items.items[first_source_index] = original_first_source;

    const source_len = checker.cir.dispatch_settlement_sources.items.items.len;
    const removed_source = checker.cir.dispatch_settlement_sources.items.orderedRemove(first_source_index);
    try std.testing.expectEqual(original_first_source.kind, removed_source.kind);
    try std.testing.expect(std.meta.eql(
        original_first_source.payload.dispatch_expr,
        removed_source.payload.dispatch_expr,
    ));
    const missing_source_is_valid = validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    );
    try checker.cir.dispatch_settlement_sources.items.insert(
        checker.cir.gpa,
        first_source_index,
        removed_source,
    );
    try std.testing.expect(!missing_source_is_valid);

    try checker.cir.dispatch_settlement_sources.items.ensureUnusedCapacity(checker.cir.gpa, 1);
    checker.cir.dispatch_settlement_sources.items.appendAssumeCapacity(original_first_source);
    const duplicate_source_is_valid = validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    );
    checker.cir.dispatch_settlement_sources.items.shrinkRetainingCapacity(source_len);
    try std.testing.expect(!duplicate_source_is_valid);
    try std.testing.expect(validateSelectedReceiverAnchorContext(
        checker.cir,
        branch_anchor_indices[0],
        terminal_receiver,
    ));
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );

    const step_index = selected_step_index orelse return error.TestUnexpectedResult;
    const step = &checker.cir.where_marker_copy_steps.items.items[step_index];
    const decision_index = step.origin.selected_dispatch_method.decision_index;
    const decision = &checker.cir.selected_method_decisions.items.items[decision_index];
    const selected_constraint_index = decision.constraint_index;
    const selected_constraint = constraints[selected_constraint_index];
    const provider_run_ident = provider.module_env.common.findIdent("run") orelse
        return error.TestUnexpectedResult;
    const sibling_binding = provider.module_env.lookupMethodBindingForOwnerConst(
        @enumFromInt(sibling_owner_decl),
        provider_run_ident,
    ) orelse return error.TestUnexpectedResult;
    const valid_owner = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    try std.testing.expect(valid_owner.root_origin);
    try std.testing.expect(valid_owner.terminal_context);

    const selected_owner_origin_module = decision.receiver_owner_origin_module;
    decision.receiver_owner_origin_module = ModuleEnv.SelectedMethodDecision.none;
    const missing_owner = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.receiver_owner_origin_module = selected_owner_origin_module;
    try std.testing.expect(!missing_owner.root_origin);
    try std.testing.expect(!missing_owner.terminal_context);

    const out_of_range_owner_identity = std.math.cast(
        u32,
        checker.cir.module_identities.count(),
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(out_of_range_owner_identity != ModuleEnv.SelectedMethodDecision.none);
    decision.receiver_owner_origin_module = out_of_range_owner_identity;
    const invalid_owner_identity = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.receiver_owner_origin_module = selected_owner_origin_module;
    try std.testing.expect(!invalid_owner_identity.root_origin);
    try std.testing.expect(!invalid_owner_identity.terminal_context);

    try std.testing.expect(selected_owner_origin_module != @intFromEnum(checker.cir.self_module_identity));
    decision.receiver_owner_origin_module = @intFromEnum(checker.cir.self_module_identity);
    const wrong_owner = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.receiver_owner_origin_module = selected_owner_origin_module;
    try std.testing.expect(!wrong_owner.root_origin);
    try std.testing.expect(!wrong_owner.terminal_context);

    const selected_owner_source_decl = decision.receiver_owner_source_decl;
    const selected_provider_type_node = decision.provider_type_node;
    const selected_provider_def = decision.provider_def;
    const selected_method_entry_index = decision.provider_method_entry_index;
    const selected_method_entry = provider.module_env.lookupMethodBindingEntryFromOwnerAndMethodEnvsConst(
        provider.module_env,
        selected_owner_source_decl,
        checker.cir,
        selected_constraint.fn_name,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(selected_method_entry.entry_index, selected_method_entry_index);
    try std.testing.expectEqual(selected_provider_type_node, @intFromEnum(selected_method_entry.binding.type_node_idx));
    try std.testing.expectEqual(selected_provider_def, @intFromEnum(selected_method_entry.binding.def_idx));

    decision.provider_method_entry_index = ModuleEnv.SelectedMethodDecision.none;
    const missing_method_entry = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.provider_method_entry_index = selected_method_entry_index;
    try std.testing.expect(!missing_method_entry.root_origin);
    try std.testing.expect(!missing_method_entry.terminal_context);

    const out_of_range_method_entry = std.math.cast(
        u32,
        provider.module_env.method_defs.entries.items.len,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(out_of_range_method_entry != ModuleEnv.SelectedMethodDecision.none);
    decision.provider_method_entry_index = out_of_range_method_entry;
    const invalid_method_entry = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.provider_method_entry_index = selected_method_entry_index;
    try std.testing.expect(!invalid_method_entry.root_origin);
    try std.testing.expect(!invalid_method_entry.terminal_context);

    decision.receiver_owner_source_decl = ModuleEnv.SelectedMethodDecision.none;
    const missing_owner_decl = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.receiver_owner_source_decl = selected_owner_source_decl;
    try std.testing.expect(!missing_owner_decl.root_origin);
    try std.testing.expect(!missing_owner_decl.terminal_context);

    const out_of_range_owner_decl = std.math.cast(u32, provider.module_env.store.nodes.len()) orelse
        return error.TestUnexpectedResult;
    decision.receiver_owner_source_decl = out_of_range_owner_decl;
    const out_of_range_decl = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.receiver_owner_source_decl = selected_owner_source_decl;
    try std.testing.expect(!out_of_range_decl.root_origin);
    try std.testing.expect(!out_of_range_decl.terminal_context);

    try std.testing.expect(selected_owner_source_decl != sibling_owner_decl);
    decision.receiver_owner_source_decl = sibling_owner_decl;
    const wrong_owner_decl = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.receiver_owner_source_decl = selected_owner_source_decl;
    try std.testing.expect(!wrong_owner_decl.root_origin);
    try std.testing.expect(!wrong_owner_decl.terminal_context);

    decision.provider_type_node = @intFromEnum(sibling_binding.type_node_idx);
    decision.provider_def = @intFromEnum(sibling_binding.def_idx);
    const wrong_provider_binding = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    decision.provider_type_node = selected_provider_type_node;
    decision.provider_def = selected_provider_def;
    try std.testing.expect(!wrong_provider_binding.root_origin);
    try std.testing.expect(!wrong_provider_binding.terminal_context);

    // A finalized method-table key is not declaration authority. Forge an
    // otherwise exact owner+method key at an in-range non-type node while
    // retaining the decision's real provider binding. The explicit owner-node
    // guard must reject both contextual consumers even though an unguarded
    // registry lookup would succeed.
    const invalid_owner_decl = selected_provider_type_node;
    try std.testing.expect(invalid_owner_decl < provider.module_env.store.nodes.len());
    try std.testing.expect(!ownerModuleEnvSourceDeclMatches(provider.module_env, invalid_owner_decl));
    {
        const method_entries = provider.module_env.method_defs.entries.items;
        const saved_entries = try std.testing.allocator.dupe(ModuleEnv.MethodDefs.Entry, method_entries);
        defer std.testing.allocator.free(saved_entries);
        const saved_sorted = provider.module_env.method_defs.sorted;
        const saved_deduplicated = provider.module_env.method_defs.deduplicated;
        const saved_owner_source_decl = decision.receiver_owner_source_decl;
        const saved_method_entry_index = decision.provider_method_entry_index;
        defer {
            @memcpy(provider.module_env.method_defs.entries.items, saved_entries);
            provider.module_env.method_defs.sorted = saved_sorted;
            provider.module_env.method_defs.deduplicated = saved_deduplicated;
            decision.receiver_owner_source_decl = saved_owner_source_decl;
            decision.provider_method_entry_index = saved_method_entry_index;
        }

        var matching_entry: ?usize = null;
        for (method_entries, 0..) |entry, entry_index| {
            if (!entry.key.ownerModuleIdent().eql(provider.module_env.qualified_module_ident) or
                @intFromEnum(entry.key.owner) != selected_owner_source_decl or
                !entry.key.methodIdent().eql(provider_run_ident) or
                @intFromEnum(entry.value.type_node_idx) != selected_provider_type_node or
                @intFromEnum(entry.value.def_idx) != selected_provider_def)
            {
                continue;
            }
            if (matching_entry != null) return error.TestUnexpectedResult;
            matching_entry = entry_index;
        }
        provider.module_env.method_defs.entries.items[
            matching_entry orelse return error.TestUnexpectedResult
        ].key.owner = @enumFromInt(invalid_owner_decl);
        provider.module_env.method_defs.sorted = false;
        provider.module_env.method_defs.deduplicated = false;
        provider.module_env.method_defs.ensureSortedUnique();
        const forged_entry = provider.module_env.lookupMethodBindingEntryFromOwnerAndMethodEnvsConst(
            provider.module_env,
            invalid_owner_decl,
            checker.cir,
            selected_constraint.fn_name,
        ) orelse return error.TestUnexpectedResult;
        const forged_binding = forged_entry.binding;
        try std.testing.expectEqual(selected_provider_type_node, @intFromEnum(forged_binding.type_node_idx));
        try std.testing.expectEqual(selected_provider_def, @intFromEnum(forged_binding.def_idx));

        decision.receiver_owner_source_decl = invalid_owner_decl;
        decision.provider_method_entry_index = forged_entry.entry_index;
        const forged_non_decl_owner = testSelectedOwnerValidation(
            checker.cir,
            consumer.builtin_module.env,
            context,
            step_index,
        );
        try std.testing.expect(!forged_non_decl_owner.root_origin);
        try std.testing.expect(!forged_non_decl_owner.terminal_context);
    }

    const sibling_constraint_index: u32 = for (constraints, 0..) |constraint, constraint_index| {
        if (constraint_index == @as(usize, selected_constraint_index) or
            constraint.fn_var == selected_constraint.fn_var or
            !constraint.fn_name.eql(selected_constraint.fn_name))
        {
            continue;
        }
        break @intCast(constraint_index);
    } else return error.TestUnexpectedResult;
    const sibling_constraint = constraints[sibling_constraint_index];
    const selected_scheme_use_index = decision.scheme_use_index;
    const selected_scheme_use = scheme_uses[selected_scheme_use_index];
    const sibling_scheme_use_index: u32 = for (scheme_uses, 0..) |scheme_use, scheme_use_index| {
        if (scheme_use.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target) or
            scheme_use.slot_data != @intFromEnum(sibling_constraint.fn_var) or
            scheme_use.scheme_root != selected_scheme_use.scheme_root)
        {
            continue;
        }
        break @intCast(scheme_use_index);
    } else return error.TestUnexpectedResult;
    const sibling_intro = sibling_constraint.provenance.intro_expr.get() orelse
        return error.TestUnexpectedResult;
    const sibling_expr = checker.cir.store.getExpr(@enumFromInt(sibling_intro));
    if (sibling_expr != .e_dispatch_call) return error.TestUnexpectedResult;
    const sibling_receiver = @intFromEnum(ModuleEnv.varFrom(sibling_expr.e_dispatch_call.receiver));

    const selected_state = decision.state;
    decision.state = @intFromEnum(ModuleEnv.SelectedMethodDecision.State.reserved);
    try std.testing.expectError(
        error.CorruptArtifact,
        validateWhereMarkerCopySourceNamespaces(
            checker.cir,
            consumer.builtin_module.env,
            context,
        ),
    );
    decision.state = selected_state;

    const selected_root_copy_step = decision.root_copy_step;
    decision.root_copy_step = decision.use_copy_step;
    try std.testing.expectError(
        error.CorruptArtifact,
        validateWhereMarkerCopySourceNamespaces(
            checker.cir,
            consumer.builtin_module.env,
            context,
        ),
    );
    decision.root_copy_step = selected_root_copy_step;

    const selected_provider_dependency = decision.provider_dependency_index;
    const sibling_provider_dependency: u32 = for (checker.owner_modules, 0..) |owner, owner_index| {
        if (owner != provider.module_env) break @intCast(owner_index);
    } else return error.TestUnexpectedResult;
    decision.provider_dependency_index = sibling_provider_dependency;
    try std.testing.expectError(
        error.CorruptArtifact,
        validateWhereMarkerCopySourceNamespaces(
            checker.cir,
            consumer.builtin_module.env,
            context,
        ),
    );
    decision.provider_dependency_index = selected_provider_dependency;

    decision.constraint_index = sibling_constraint_index;
    const sibling_retarget_result = validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );
    decision.constraint_index = selected_constraint_index;
    try std.testing.expectError(
        error.CorruptArtifact,
        sibling_retarget_result,
    );

    const selected_receiver = decision.receiver_var;
    decision.receiver_var = sibling_receiver;
    const receiver_owner_retarget = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        step_index,
    );
    const receiver_retarget_result = validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );
    decision.receiver_var = selected_receiver;
    try std.testing.expect(!receiver_owner_retarget.root_origin);
    try std.testing.expect(!receiver_owner_retarget.terminal_context);
    try std.testing.expectError(
        error.CorruptArtifact,
        receiver_retarget_result,
    );

    decision.constraint_index = sibling_constraint_index;
    decision.scheme_use_index = sibling_scheme_use_index;
    decision.receiver_var = sibling_receiver;
    const whole_sibling_retarget_result = validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );
    decision.constraint_index = selected_constraint_index;
    decision.scheme_use_index = selected_scheme_use_index;
    decision.receiver_var = selected_receiver;
    try std.testing.expectError(
        error.CorruptArtifact,
        whole_sibling_retarget_result,
    );
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );
}

test "selected method decision preserves its exact receiver-extension row" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\module [Base, Extensions]
        \\
        \\Base := [Base]
        \\
        \\Extensions := [].{
        \\    run : Base -> [One]
        \\    run = |_| One
        \\}
    ;
    var provider = try TestEnv.init("SelectedReceiverExtensionProvider", provider_source);
    defer provider.deinit();
    // Explicit exports still use the supported legacy module header, whose
    // deprecation is the sole canonicalization diagnostic for this provider.
    try provider.assertOneCanError("Module Header Deprecated");
    try std.testing.expectEqual(@as(usize, 0), provider.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try provider.typeProblemCount());

    const consumer_source =
        \\import SelectedReceiverExtensionProvider
        \\
        \\out : SelectedReceiverExtensionProvider.Base -> [One]
        \\out = |value| value.run()
    ;
    var consumer = try TestEnv.initWithImport(
        "SelectedReceiverExtensionConsumer",
        consumer_source,
        "SelectedReceiverExtensionProvider",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertNoErrors();

    const checker = &consumer.checker;
    const provider_identity = checker.cir.lookupModuleIdentity(
        provider.module_env.contentIdentityHash() orelse return error.TestUnexpectedResult,
    ) orelse return error.TestUnexpectedResult;
    const base_source_decl = try testFindNominalSourceDecl(provider.module_env, "Base");
    const extensions_source_decl = try testFindNominalSourceDecl(provider.module_env, "Extensions");
    try std.testing.expect(base_source_decl != extensions_source_decl);
    const run_ident = checker.cir.common.findIdent("run") orelse return error.TestUnexpectedResult;

    var run_decision_count: usize = 0;
    var run_decision_index: ?u32 = null;
    for (checker.cir.selected_method_decisions.items.items, 0..) |decision, decision_index| {
        if (decision.decodedState() != .complete or
            decision.constraint_index >= checker.types.static_dispatch_constraints.items.items.len)
        {
            return error.TestUnexpectedResult;
        }
        const constraint = checker.types.static_dispatch_constraints.items.items[decision.constraint_index];
        if (!constraint.fn_name.eql(run_ident)) continue;
        run_decision_count += 1;
        run_decision_index = @intCast(decision_index);
        try std.testing.expectEqual(
            @intFromEnum(provider_identity),
            decision.receiver_owner_origin_module,
        );
        try std.testing.expectEqual(base_source_decl, decision.receiver_owner_source_decl);
        try std.testing.expect(decision.receiver_owner_source_decl != extensions_source_decl);
        const entry = provider.module_env.lookupMethodBindingEntryFromOwnerAndMethodEnvsConst(
            provider.module_env,
            base_source_decl,
            checker.cir,
            constraint.fn_name,
        ) orelse return error.TestUnexpectedResult;
        const binding = entry.binding;
        try std.testing.expectEqual(entry.entry_index, decision.provider_method_entry_index);
        try std.testing.expectEqual(decision.provider_type_node, @intFromEnum(binding.type_node_idx));
        try std.testing.expectEqual(decision.provider_def, @intFromEnum(binding.def_idx));
    }
    try std.testing.expectEqual(@as(usize, 1), run_decision_count);

    const context = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    const selected_decision_index = run_decision_index orelse return error.TestUnexpectedResult;
    const selected_step_index: usize = for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.decodedKind() == .selected_dispatch_method and
            step.origin.selected_dispatch_method.decision_index == selected_decision_index)
        {
            break step_index;
        }
    } else return error.TestUnexpectedResult;
    const decision = &checker.cir.selected_method_decisions.items.items[selected_decision_index];
    const constraint = checker.types.static_dispatch_constraints.items.items[decision.constraint_index];
    const receiver_entry = provider.module_env.lookupMethodBindingEntryFromOwnerAndMethodEnvsConst(
        provider.module_env,
        base_source_decl,
        checker.cir,
        constraint.fn_name,
    ) orelse return error.TestUnexpectedResult;
    const extensions_entry = provider.module_env.lookupMethodBindingEntryFromOwnerAndMethodEnvsConst(
        provider.module_env,
        extensions_source_decl,
        checker.cir,
        constraint.fn_name,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.meta.eql(receiver_entry.binding, extensions_entry.binding));
    try std.testing.expect(receiver_entry.entry_index != extensions_entry.entry_index);
    try std.testing.expectEqual(receiver_entry.entry_index, decision.provider_method_entry_index);

    const exact_receiver_owner = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        selected_step_index,
    );
    try std.testing.expect(exact_receiver_owner.root_origin);
    try std.testing.expect(exact_receiver_owner.terminal_context);

    decision.receiver_owner_source_decl = extensions_source_decl;
    const wrong_namespace_owner = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        selected_step_index,
    );
    decision.receiver_owner_source_decl = base_source_decl;
    try std.testing.expect(!wrong_namespace_owner.root_origin);
    try std.testing.expect(!wrong_namespace_owner.terminal_context);

    decision.provider_method_entry_index = extensions_entry.entry_index;
    const wrong_namespace_entry = testSelectedOwnerValidation(
        checker.cir,
        consumer.builtin_module.env,
        context,
        selected_step_index,
    );
    decision.provider_method_entry_index = receiver_entry.entry_index;
    try std.testing.expect(!wrong_namespace_entry.root_origin);
    try std.testing.expect(!wrong_namespace_entry.terminal_context);

    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );
    try std.testing.expect(validateSelectedMethodDecisionsContext(
        checker.cir,
        consumer.builtin_module.env,
        context,
    ));
}

test "rejected selected method preserves its exact declaration-owner method row" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\module [Base, Alias, Extensions]
        \\
        \\Base := [Base]
        \\Alias : Base
        \\
        \\Extensions := [].{
        \\    run : Alias -> [One]
        \\    run = |_| One
        \\}
    ;
    var provider = try TestEnv.init("SelectedNamespaceProvider", provider_source);
    defer provider.deinit();
    // Explicit exports still use the supported legacy module header, whose
    // deprecation is the sole canonicalization diagnostic for this provider.
    try provider.assertOneCanError("Module Header Deprecated");
    try std.testing.expectEqual(@as(usize, 0), provider.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try provider.typeProblemCount());

    const consumer_source =
        \\import SelectedNamespaceProvider
        \\
        \\bad : SelectedNamespaceProvider.Extensions -> [One]
        \\bad = |value| value.run()
    ;
    var consumer = try TestEnv.initWithImport(
        "SelectedNamespaceConsumer",
        consumer_source,
        "SelectedNamespaceProvider",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertCanErrors(&.{});
    try consumer.assertOneTypeError("Type Mismatch");
    try std.testing.expectEqual(@as(usize, 1), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 1), try consumer.typeProblemCount());

    const checker = &consumer.checker;
    const run_ident = checker.cir.common.findIdent("run") orelse return error.TestUnexpectedResult;
    const mismatch = switch (checker.problems.problems.items[0]) {
        .type_mismatch => |mismatch_payload| mismatch_payload,
        else => return error.TestUnexpectedResult,
    };
    if (mismatch.context != .method_type) return error.TestUnexpectedResult;
    try std.testing.expect(mismatch.context.method_type.method_name.eql(run_ident));
    const provider_identity = checker.cir.lookupModuleIdentity(
        provider.module_env.contentIdentityHash() orelse return error.TestUnexpectedResult,
    ) orelse return error.TestUnexpectedResult;
    const alias_source_decl = try testFindAliasSourceDecl(provider.module_env, "Alias");
    const extensions_source_decl = try testFindNominalSourceDecl(provider.module_env, "Extensions");

    var run_decision_index: ?u32 = null;
    for (checker.cir.selected_method_decisions.items.items, 0..) |decision, decision_index| {
        if (decision.decodedState() != .complete or
            decision.constraint_index >= checker.types.static_dispatch_constraints.items.items.len)
        {
            return error.TestUnexpectedResult;
        }
        const constraint = checker.types.static_dispatch_constraints.items.items[decision.constraint_index];
        if (!constraint.fn_name.eql(run_ident)) continue;
        if (run_decision_index != null) return error.TestUnexpectedResult;
        run_decision_index = @intCast(decision_index);
    }
    const decision_index = run_decision_index orelse return error.TestUnexpectedResult;
    const decision = checker.cir.selected_method_decisions.items.items[decision_index];
    const constraint = checker.types.static_dispatch_constraints.items.items[decision.constraint_index];
    try std.testing.expectEqual(@intFromEnum(provider_identity), decision.receiver_owner_origin_module);
    try std.testing.expectEqual(extensions_source_decl, decision.receiver_owner_source_decl);

    const namespace_entry = provider.module_env.lookupMethodBindingEntryFromOwnerAndMethodEnvsConst(
        provider.module_env,
        extensions_source_decl,
        checker.cir,
        constraint.fn_name,
    ) orelse return error.TestUnexpectedResult;
    const alias_entry = provider.module_env.lookupMethodBindingEntryFromOwnerAndMethodEnvsConst(
        provider.module_env,
        alias_source_decl,
        checker.cir,
        constraint.fn_name,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.meta.eql(namespace_entry.binding, alias_entry.binding));
    try std.testing.expect(namespace_entry.entry_index != alias_entry.entry_index);
    try std.testing.expectEqual(namespace_entry.entry_index, decision.provider_method_entry_index);
    try std.testing.expectEqual(decision.provider_type_node, @intFromEnum(namespace_entry.binding.type_node_idx));
    try std.testing.expectEqual(decision.provider_def, @intFromEnum(namespace_entry.binding.def_idx));

    const context = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        consumer.builtin_module.env,
        context,
    );
    try std.testing.expect(validateSelectedMethodDecisionsContext(
        checker.cir,
        consumer.builtin_module.env,
        context,
    ));
}

test "selected method imported binding classification rollback is exhaustive" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\SelectedRollbackProvider := [Runner].{
        \\    run : SelectedRollbackProvider, a -> [One] where [a.pick : a -> [One]]
        \\    run = |_, value| value.pick()
        \\}
    ;
    var provider = try TestEnv.init("SelectedRollbackProvider", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import SelectedRollbackProvider
        \\
        \\Choice := [Choice].{
        \\    pick : Choice -> [One]
        \\    pick = |_| One
        \\}
        \\
        \\runner = SelectedRollbackProvider.Runner
        \\choice = Choice.Choice
        \\out = runner.run(choice)
    ;

    var fail_index: usize = 0;
    var induced_failures: usize = 0;
    var reached_success = false;
    while (!reached_success) {
        var consumer = try TestEnv.initWithImport(
            "SelectedRollbackConsumer",
            consumer_source,
            "SelectedRollbackProvider",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertNoErrors();
        const checker = &consumer.checker;

        const selected_decision_index: u32 = for (checker.cir.where_marker_copy_steps.items.items) |step| {
            if (step.decodedKind() == .selected_dispatch_method) {
                break step.origin.selected_dispatch_method.decision_index;
            }
        } else return error.TestUnexpectedResult;
        if (selected_decision_index >= checker.cir.selected_method_decisions.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const decision = checker.cir.selected_method_decisions.items.items[selected_decision_index];
        if (decision.constraint_index >= checker.types.static_dispatch_constraints.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const selected_constraint = checker.types.static_dispatch_constraints.items.items[
            decision.constraint_index
        ];
        const provider_type_node: CIR.Node.Idx = @enumFromInt(decision.provider_type_node);
        try std.testing.expect(provider.module_env.nodeIsBindingScheme(provider_type_node));
        const cache_key = ImportedMethodSchemeKey{
            .env = provider.module_env,
            .type_node_idx = provider_type_node,
        };
        const original_cache_index = checker.imported_method_scheme_by_source.get(cache_key) orelse
            return error.TestUnexpectedResult;
        const original_cached_scheme = checker.imported_method_schemes.items[original_cache_index];
        try std.testing.expect(checker.isBindingSchemeVar(original_cached_scheme.scheme_var));
        try std.testing.expect(checker.imported_method_scheme_by_source.remove(cache_key));

        const imported_schemes_len = checker.imported_method_schemes.items.len;
        const synthetic_binding_count = checker.synthetic_binding_schemes.count();
        const binding_journal_len = checker.binding_scheme_mutation_journal.items.len;
        const type_len = checker.types.len();
        const contracts_len = checker.types.where_method_marker_contracts.items.items.len;
        const bases_len = checker.types.where_method_marker_bases.items.items.len;
        const type_paths_len = checker.types.where_method_marker_path_steps.items.items.len;
        const evidence_handles_len = checker.types.constraint_evidence_handles.items.items.len;
        const type_schemes_len = checker.type_schemes.items.len;
        const scheme_uses_len = checker.cir.scheme_uses.items.items.len;
        const copy_steps_len = checker.cir.where_marker_copy_steps.items.items.len;
        const copy_pairs_len = checker.cir.where_marker_copy_pairs.items.items.len;
        const copy_occurrences_len = checker.cir.where_marker_copy_occurrences.items.items.len;
        const constraint_pairs_len = checker.cir.where_marker_constraint_copy_pairs.items.items.len;
        const copy_witnesses_len = checker.cir.where_marker_copy_witnesses.items.items.len;
        const copied_groups_len = checker.cir.copied_open_literal_groups.items.items.len;
        const copied_events_len = checker.cir.copied_open_literal_events.items.items.len;
        const marker_moves_len = checker.cir.where_marker_constraint_moves.items.items.len;
        const marker_move_offsets_len = checker.cir.where_marker_constraint_move_offsets.items.items.len;
        const evidence_moves_len = checker.cir.constraint_evidence_moves.items.items.len;
        const platform_substitutions_len = checker.cir.where_marker_platform_substitutions.items.items.len;
        const probe_depth = checker.probe_depth;
        const store_savepoint_depth = checker.types.savepoint_depth;
        const ident_savepoint_depth = checker.cir.common.idents.interner.savepoint_depth;
        const identity_savepoint_depth = checker.cir.module_identities.savepoint_depth;
        var owned_state = try ProbeCrossCopyOwnedStateSnapshot.capture(
            std.testing.allocator,
            checker,
        );
        defer owned_state.deinit();

        const candidate_var: Var = @enumFromInt(decision.receiver_var);
        var candidate_env = try Env.init(checker.gpa, .outermost);
        defer candidate_env.deinit(checker.gpa);
        var outer = try checker.beginCommitProbe(&candidate_env);
        var outer_open = true;
        defer if (outer_open) outer.rollback();

        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = fail_index,
            // Force every grow/remap through the allocation failure index;
            // otherwise in-place resizes would escape exhaustive injection.
            .resize_fail_index = 0,
        });
        const failing_gpa = failing.allocator();
        const original_checker_gpa = checker.gpa;
        const original_cir_gpa = checker.cir.gpa;
        const original_types_gpa = checker.types.gpa;
        checker.gpa = failing_gpa;
        checker.cir.gpa = failing_gpa;
        checker.types.gpa = failing_gpa;
        const result = checker.staticDispatchConstraintAcceptsCandidate(
            &outer,
            decision.constraint_index,
            selected_constraint,
            candidate_var,
            &candidate_env,
        );
        checker.gpa = original_checker_gpa;
        checker.cir.gpa = original_cir_gpa;
        checker.types.gpa = original_types_gpa;

        var discarded_scheme: ?Var = null;
        if (result) |accepted| {
            try std.testing.expect(!failing.has_induced_failure);
            try std.testing.expect(accepted);
            const new_cache_index = checker.imported_method_scheme_by_source.get(cache_key) orelse
                return error.TestUnexpectedResult;
            const new_scheme = checker.imported_method_schemes.items[new_cache_index].scheme_var;
            try std.testing.expect(new_scheme != original_cached_scheme.scheme_var);
            try std.testing.expect(checker.isBindingSchemeVar(new_scheme));
            var candidate_root_count: usize = 0;
            for (checker.cir.where_marker_copy_steps.items.items[copy_steps_len..]) |new_step| {
                candidate_root_count += @intFromBool(
                    new_step.decodedKind() == .candidate_probe_method_root,
                );
            }
            try std.testing.expectEqual(@as(usize, 1), candidate_root_count);
            try std.testing.expectEqual(
                synthetic_binding_count + 1,
                checker.synthetic_binding_schemes.count(),
            );
            try std.testing.expectEqual(
                binding_journal_len + 1,
                checker.binding_scheme_mutation_journal.items.len,
            );
            try std.testing.expectEqual(
                imported_schemes_len + 1,
                checker.imported_method_schemes.items.len,
            );
            discarded_scheme = new_scheme;
            reached_success = true;
        } else |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
            try std.testing.expect(failing.has_induced_failure);
            induced_failures += 1;
        }
        outer.rollback();
        outer_open = false;

        try owned_state.expectEqual(checker);
        try std.testing.expectEqual(imported_schemes_len, checker.imported_method_schemes.items.len);
        try std.testing.expectEqual(synthetic_binding_count, checker.synthetic_binding_schemes.count());
        try std.testing.expectEqual(binding_journal_len, checker.binding_scheme_mutation_journal.items.len);
        try std.testing.expectEqual(type_len, checker.types.len());
        try std.testing.expectEqual(contracts_len, checker.types.where_method_marker_contracts.items.items.len);
        try std.testing.expectEqual(bases_len, checker.types.where_method_marker_bases.items.items.len);
        try std.testing.expectEqual(type_paths_len, checker.types.where_method_marker_path_steps.items.items.len);
        try std.testing.expectEqual(evidence_handles_len, checker.types.constraint_evidence_handles.items.items.len);
        try std.testing.expectEqual(type_schemes_len, checker.type_schemes.items.len);
        try std.testing.expectEqual(scheme_uses_len, checker.cir.scheme_uses.items.items.len);
        try std.testing.expectEqual(copy_steps_len, checker.cir.where_marker_copy_steps.items.items.len);
        try std.testing.expectEqual(copy_pairs_len, checker.cir.where_marker_copy_pairs.items.items.len);
        try std.testing.expectEqual(copy_occurrences_len, checker.cir.where_marker_copy_occurrences.items.items.len);
        try std.testing.expectEqual(constraint_pairs_len, checker.cir.where_marker_constraint_copy_pairs.items.items.len);
        try std.testing.expectEqual(copy_witnesses_len, checker.cir.where_marker_copy_witnesses.items.items.len);
        try std.testing.expectEqual(copied_groups_len, checker.cir.copied_open_literal_groups.items.items.len);
        try std.testing.expectEqual(copied_events_len, checker.cir.copied_open_literal_events.items.items.len);
        try std.testing.expectEqual(marker_moves_len, checker.cir.where_marker_constraint_moves.items.items.len);
        try std.testing.expectEqual(marker_move_offsets_len, checker.cir.where_marker_constraint_move_offsets.items.items.len);
        try std.testing.expectEqual(evidence_moves_len, checker.cir.constraint_evidence_moves.items.items.len);
        try std.testing.expectEqual(platform_substitutions_len, checker.cir.where_marker_platform_substitutions.items.items.len);
        try std.testing.expectEqual(probe_depth, checker.probe_depth);
        try std.testing.expectEqual(store_savepoint_depth, checker.types.savepoint_depth);
        try std.testing.expectEqual(ident_savepoint_depth, checker.cir.common.idents.interner.savepoint_depth);
        try std.testing.expectEqual(identity_savepoint_depth, checker.cir.module_identities.savepoint_depth);
        try std.testing.expect(!checker.imported_method_scheme_by_source.contains(cache_key));
        try std.testing.expect(checker.isBindingSchemeVar(original_cached_scheme.scheme_var));

        if (discarded_scheme) |discarded| {
            try std.testing.expect(!checker.synthetic_binding_schemes.contains(discarded));
            var reuse_probe = try checker.beginProbe(null);
            var reuse_open = true;
            defer if (reuse_open) reuse_probe.rollback();
            var reused = try checker.types.fresh();
            while (@intFromEnum(reused) < @intFromEnum(discarded)) {
                reused = try checker.types.fresh();
            }
            try std.testing.expectEqual(discarded, reused);
            try std.testing.expect(!checker.isBindingSchemeVar(reused));
            reuse_probe.rollback();
            reuse_open = false;
        }

        if (!reached_success) {
            fail_index = std.math.add(usize, fail_index, 1) catch
                return error.TestUnexpectedResult;
        }
    }
    try std.testing.expect(induced_failures != 0);
}

test "for-loop dispatch plans close both slots and reject coordinate corruption" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\{
        \\    for _first in [1.U64] {}
        \\    for _second in [2.U64] {}
        \\    {}
        \\}
    ;
    var test_env = try TestEnv.initExpr("ForLoopDispatchClosure", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    const checker = &test_env.checker;

    try std.testing.expect(validateForLoopDispatchPlansContext(checker.cir));
    try std.testing.expectEqual(@as(usize, 2), checker.cir.for_loop_dispatch_plans.items.items.len);

    // A second and third boundary pass must preserve the canonical producer
    // rows byte-for-byte; all slices are reacquired after each rebuilding
    // operation because replacement pools may move.
    const canonical_plans = try std.testing.allocator.dupe(
        ModuleEnv.ForLoopDispatchPlan,
        checker.cir.for_loop_dispatch_plans.items.items,
    );
    defer std.testing.allocator.free(canonical_plans);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    try std.testing.expectEqualSlices(
        ModuleEnv.ForLoopDispatchPlan,
        canonical_plans,
        checker.cir.for_loop_dispatch_plans.items.items,
    );
    try checker.rebuildCheckedBoundaryWhereMethodState();
    try std.testing.expectEqualSlices(
        ModuleEnv.ForLoopDispatchPlan,
        canonical_plans,
        checker.cir.for_loop_dispatch_plans.items.items,
    );
    try std.testing.expect(validateForLoopDispatchPlansContext(checker.cir));

    // Probe rollback owns this new list just like every other checked-boundary
    // pool. The suffix cannot survive an inner commit followed by rollback of
    // the enclosing probe frame.
    try checker.cir.for_loop_dispatch_plans.items.ensureUnusedCapacity(checker.cir.gpa, 1);
    const plan_len = checker.cir.for_loop_dispatch_plans.items.items.len;
    var outer_probe = try checker.beginProbe(null);
    var outer_probe_open = true;
    errdefer if (outer_probe_open) outer_probe.rollback();
    var inner_probe = try checker.beginProbe(null);
    var inner_probe_open = true;
    errdefer if (inner_probe_open) inner_probe.rollback();
    checker.cir.for_loop_dispatch_plans.items.appendAssumeCapacity(
        checker.cir.for_loop_dispatch_plans.items.items[0],
    );
    inner_probe.commit();
    inner_probe_open = false;
    outer_probe.rollback();
    outer_probe_open = false;
    try std.testing.expectEqual(plan_len, checker.cir.for_loop_dispatch_plans.items.items.len);
    try std.testing.expect(validateForLoopDispatchPlansContext(checker.cir));

    const plans = checker.cir.for_loop_dispatch_plans.items.items;
    const settlement_sources = checker.cir.dispatch_settlement_sources.items.items;
    var source_indexes: [2][2]usize = undefined;
    var source_seen = [_][2]bool{.{ false, false }} ** 2;
    for (settlement_sources, 0..) |settlement_source, source_index| {
        if (settlement_source.decodedKind() != .for_loop_dispatch) continue;
        const row = settlement_source.payload.for_loop_dispatch;
        if (row.plan_index >= plans.len or row.slot > @intFromEnum(ModuleEnv.DispatchSettlementSource.ForLoopSlot.next)) {
            return error.TestUnexpectedResult;
        }
        source_indexes[row.plan_index][row.slot] = source_index;
        source_seen[row.plan_index][row.slot] = true;
    }
    for (source_seen) |slots| for (slots) |seen| try std.testing.expect(seen);

    const resolution = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        checker.builtin_ctx.builtin_module orelse checker.cir,
        resolution,
    );
    try std.testing.expect(validateSelectedMethodDecisionsContext(
        checker.cir,
        checker.builtin_ctx.builtin_module orelse checker.cir,
        resolution,
    ));
    var first_iter_decision: ?u32 = null;
    for (plans, 0..) |plan, plan_index| {
        try std.testing.expect(plan.node_idx != 0);
        const live_slots = .{
            .{ .slot = ModuleEnv.DispatchSettlementSource.ForLoopSlot.iter, .outcome = plan.iter_outcome },
            .{ .slot = ModuleEnv.DispatchSettlementSource.ForLoopSlot.next, .outcome = plan.next_outcome },
        };
        inline for (live_slots) |live_slot| {
            try std.testing.expectEqual(
                ModuleEnv.ForLoopDispatchOutcome.Kind.live_constraint,
                live_slot.outcome.decodedKind().?,
            );
            const constraint_index = live_slot.outcome.constraintIndex().?;
            const site = forLoopDispatchSchemeUseSite(checker.cir, constraint_index) orelse
                return error.TestUnexpectedResult;
            try std.testing.expectEqual(@as(u32, @intCast(plan_index)), site.plan_index);
            try std.testing.expectEqual(live_slot.slot, site.slot);
            try std.testing.expectEqual(plan.node_idx, site.node_idx);
            var matching_decision: ?u32 = null;
            for (checker.cir.selected_method_decisions.items.items, 0..) |decision, decision_index| {
                if (decision.constraint_index != constraint_index) continue;
                if (matching_decision != null) return error.TestUnexpectedResult;
                matching_decision = @intCast(decision_index);
            }
            const decision_index = matching_decision orelse return error.TestUnexpectedResult;
            const decision = checker.cir.selected_method_decisions.items.items[decision_index];
            try std.testing.expectEqual(
                plan.node_idx,
                checker.cir.scheme_uses.items.items[decision.scheme_use_index].node_idx,
            );
            if (plan_index == 0 and live_slot.slot == .iter) first_iter_decision = decision_index;
        }
    }

    const iter_decision = checker.cir.selected_method_decisions.items.items[
        first_iter_decision orelse return error.TestUnexpectedResult
    ];
    const iter_use = &checker.cir.scheme_uses.items.items[iter_decision.scheme_use_index];
    const original_iter_use_node = iter_use.node_idx;
    iter_use.node_idx = plans[1].node_idx;
    try std.testing.expectError(error.CorruptArtifact, validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        checker.builtin_ctx.builtin_module orelse checker.cir,
        resolution,
    ));
    try std.testing.expect(!validateSelectedMethodDecisionsContext(
        checker.cir,
        checker.builtin_ctx.builtin_module orelse checker.cir,
        resolution,
    ));
    iter_use.node_idx = original_iter_use_node;
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        checker.builtin_ctx.builtin_module orelse checker.cir,
        resolution,
    );
    try std.testing.expect(validateSelectedMethodDecisionsContext(
        checker.cir,
        checker.builtin_ctx.builtin_module orelse checker.cir,
        resolution,
    ));

    const first_node = plans[0].node_idx;
    plans[0].node_idx = plans[1].node_idx;
    try std.testing.expect(!validateForLoopDispatchPlansContext(checker.cir));
    plans[0].node_idx = first_node;

    const one_payload_var = plans[0].step_topology.one_payload_var;
    plans[0].step_topology.one_payload_var = @intCast(checker.types.len());
    try std.testing.expect(!validateForLoopDispatchPlansContext(checker.cir));
    plans[0].step_topology.one_payload_var = one_payload_var;

    const first_iter_source = &settlement_sources[source_indexes[0][@intFromEnum(ModuleEnv.DispatchSettlementSource.ForLoopSlot.iter)]];
    const first_next_source = &settlement_sources[source_indexes[0][@intFromEnum(ModuleEnv.DispatchSettlementSource.ForLoopSlot.next)]];
    const original_iter_plan = first_iter_source.payload.for_loop_dispatch.plan_index;
    first_iter_source.payload.for_loop_dispatch.plan_index = ModuleEnv.DispatchSettlementSource.none;
    try std.testing.expect(!validateForLoopDispatchPlansContext(checker.cir));
    first_iter_source.payload.for_loop_dispatch.plan_index = original_iter_plan;

    const original_next_slot = first_next_source.payload.for_loop_dispatch.slot;
    first_next_source.payload.for_loop_dispatch.slot = @intFromEnum(ModuleEnv.DispatchSettlementSource.ForLoopSlot.iter);
    try std.testing.expect(!validateForLoopDispatchPlansContext(checker.cir));
    first_next_source.payload.for_loop_dispatch.slot = original_next_slot;

    first_iter_source.payload.for_loop_dispatch.plan_index = 1;
    try std.testing.expect(!validateForLoopDispatchPlansContext(checker.cir));
    first_iter_source.payload.for_loop_dispatch.plan_index = original_iter_plan;

    const original_iter_anchor = first_iter_source.payload.for_loop_dispatch.anchor_index;
    first_iter_source.payload.for_loop_dispatch.anchor_index = first_next_source.payload.for_loop_dispatch.anchor_index;
    try std.testing.expect(!validateForLoopDispatchPlansContext(checker.cir));
    first_iter_source.payload.for_loop_dispatch.anchor_index = original_iter_anchor;

    const live_iter_outcome = plans[0].iter_outcome;
    plans[0].iter_outcome = ModuleEnv.ForLoopDispatchOutcome.rejectedBeforeConstraint(
        @intCast(checker.cir.rejected_static_dispatches.items.items.len),
    );
    try std.testing.expect(!validateForLoopDispatchPlansContext(checker.cir));
    plans[0].iter_outcome = live_iter_outcome;
    try std.testing.expect(validateForLoopDispatchPlansContext(checker.cir));

    const rejected_source =
        \\{
        \\    for _item in missing_iterable {}
        \\    {}
        \\}
    ;
    var rejected_env = try TestEnv.initExpr("RejectedForLoopDispatchClosure", rejected_source);
    defer rejected_env.deinit();
    const rejected_checker = &rejected_env.checker;
    const rejected_plans = rejected_checker.cir.for_loop_dispatch_plans.items.items;
    try std.testing.expectEqual(@as(usize, 1), rejected_plans.len);
    try std.testing.expectEqual(
        ModuleEnv.ForLoopDispatchOutcome.Kind.rejected_before_constraint,
        rejected_plans[0].iter_outcome.decodedKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ForLoopDispatchOutcome.Kind.rejected_before_constraint,
        rejected_plans[0].next_outcome.decodedKind().?,
    );
    for ([_]u32{ rejected_plans[0].iter_fn_var, rejected_plans[0].next_fn_var }) |rejected_fn_var| {
        for (rejected_checker.cir.scheme_uses.items.items) |use| {
            try std.testing.expect(!(use.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target) and
                use.slot_data == rejected_fn_var));
        }
    }
    try std.testing.expect(validateForLoopDispatchPlansContext(rejected_checker.cir));

    const rejected_next = rejected_plans[0].next_outcome;
    rejected_plans[0].next_outcome = ModuleEnv.ForLoopDispatchOutcome.rejectedBeforeConstraint(
        rejected_plans[0].iter_outcome.rejectionIndex().?,
    );
    try std.testing.expect(!validateForLoopDispatchPlansContext(rejected_checker.cir));
    rejected_plans[0].next_outcome = rejected_next;

    rejected_plans[0].next_outcome = ModuleEnv.ForLoopDispatchOutcome.liveConstraint(
        @intCast(rejected_checker.types.static_dispatch_constraints.items.items.len),
        @intCast(rejected_checker.cir.selected_receiver_anchors.items.items.len),
    );
    try std.testing.expect(!validateForLoopDispatchPlansContext(rejected_checker.cir));
    rejected_plans[0].next_outcome = rejected_next;
    try std.testing.expect(validateForLoopDispatchPlansContext(rejected_checker.cir));
}

test "recursive imported where alias predeclaration publishes only durable body lineage" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\module [Status]
        \\
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("A", provider_source);
    defer provider.deinit();

    const consumer_source =
        \\import A exposing [Status]
        \\
        \\first : a, U64 -> [Off, On] where [a.Status]
        \\first = |value, count| if count == 0.U64 {
        \\    second(value, 1.U64)
        \\} else {
        \\    value.status()
        \\}
        \\
        \\second : a, U64 -> [Off, On] where [a.Status]
        \\second = |value, count| if count == 0.U64 {
        \\    first(value, 1.U64)
        \\} else {
        \\    value.status()
        \\}
    ;
    var consumer = try TestEnv.initWithImport("B", consumer_source, "A", &provider);
    defer consumer.deinit();
    try consumer.assertNoErrors();

    const checker = &consumer.checker;
    const constraints = checker.types.static_dispatch_constraints.items.items;
    const contracts = checker.types.where_method_marker_contracts.items.items;
    try std.testing.expectEqual(@as(usize, 0), checker.predeclared_anno_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.predeclared_anno_events.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.predeclared_anno_orphan_pairs.items.len);

    var durable_body_annotations = std.AutoHashMap(u32, void).init(std.testing.allocator);
    defer durable_body_annotations.deinit();
    var durable_body_basis_count: usize = 0;
    var durable_predeclared_support_count: usize = 0;
    for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        const annotation_node = switch (step.decodedKind().?) {
            .type_annotation => step.origin.type_annotation.node,
            .predeclared_annotation => predeclared: {
                durable_predeclared_support_count += 1;
                break :predeclared step.origin.predeclared_annotation.node;
            },
            else => continue,
        };
        if (annotation_node >= checker.cir.store.nodes.len() or
            checker.cir.store.nodes.get(@enumFromInt(annotation_node)).tag != .annotation)
        {
            continue;
        }

        var step_had_body_basis = false;
        for (constraints) |constraint| {
            const bases = checker.types.sliceWhereMethodMarkerBases(
                constraint.where_method_marker_bases,
            );
            for (bases) |basis| {
                if (basis.copy_step != @as(u32, @intCast(step_index))) continue;
                step_had_body_basis = true;
                durable_body_basis_count += 1;
                try std.testing.expect(basis.source_constraint_index < constraints.len);
                const source_constraint = constraints[basis.source_constraint_index];
                try std.testing.expect(basis.source_contract_offset < source_constraint.where_method_markers.len());
                const source_contract = contracts[
                    @intFromEnum(source_constraint.where_method_markers.start) +
                        basis.source_contract_offset
                ];

                // A rebased basis names the exact immutable regenerated
                // source occurrence captured by the annotation event. It is
                // not required to equal whichever constraint range remains
                // attached to the solved live annotation descriptor.
                var exact_source_matches: usize = 0;
                for (checker.cir.where_method_sources.items.items) |source| {
                    if (source.owner_node != annotation_node or
                        source.retained_constraint_index != basis.source_constraint_index)
                    {
                        continue;
                    }
                    for (contracts[source.source_contracts_start..][0..source.source_contracts_len]) |candidate| {
                        if (candidate.position != source_contract.position) continue;
                        const source_path = checker.types.where_method_marker_path_steps.items.items[source_contract.path_start..][0..source_contract.path_len];
                        const candidate_path = checker.types.where_method_marker_path_steps.items.items[candidate.path_start..][0..candidate.path_len];
                        if (types_mod.compareWhereMethodMarkerPathSlices(source_path, candidate_path) == .eq and
                            types_mod.whereMethodMarkerNominalNamesMatch(source_path, candidate_path))
                        {
                            exact_source_matches += 1;
                        }
                    }
                }
                try std.testing.expectEqual(@as(usize, 1), exact_source_matches);
            }
        }
        if (step_had_body_basis) try durable_body_annotations.put(annotation_node, {});
    }
    try std.testing.expectEqual(@as(usize, 2), durable_body_annotations.count());
    try std.testing.expect(durable_body_basis_count >= 2);
    try std.testing.expectEqual(@as(usize, 2), durable_predeclared_support_count);
}

test "predeclared annotation rebase preserves two literal receiver group order" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\pair_zero : {} -> { x : a, y : b } where [
        \\    a.from_numeral : Numeral -> Try(a, [InvalidNumeral(Str)]),
        \\    b.from_numeral : Numeral -> Try(b, [InvalidNumeral(Str)]),
        \\]
        \\pair_zero = |_| { x: 0, y: 0 }
    ;
    var test_env = try TestEnv.init("PredeclaredLiteralGroupOrder", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    const checker = &test_env.checker;

    var matching_step_index: ?u32 = null;
    for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.decodedKind() != .predeclared_annotation or step.copied_groups_len != 2) continue;
        if (matching_step_index != null) return error.TestUnexpectedResult;
        matching_step_index = @intCast(step_index);
    }
    const step_index = matching_step_index orelse return error.TestUnexpectedResult;
    const step = checker.cir.where_marker_copy_steps.items.items[step_index];
    const groups = checker.cir.copied_open_literal_groups.items.items[step.copied_groups_start..][0..step.copied_groups_len];
    try std.testing.expect(ModuleEnv.CopiedOpenLiteralGroup.canonicalLessThan(groups[0], groups[1]));
    try std.testing.expect(groups[0].receiver_occurrence_offset < groups[1].receiver_occurrence_offset);
    try std.testing.expect(groups[0].source_constraints_start < groups[1].source_constraints_start);
    try std.testing.expect(groups[0].destination_constraints_start < groups[1].destination_constraints_start);
    for (groups, 0..) |group, group_offset| {
        try std.testing.expectEqual(step_index, group.copy_step_index);
        try std.testing.expectEqual(
            ModuleEnv.CopiedOpenLiteralComponent.Kind.root_graph,
            group.component.decodedKind().?,
        );
        try std.testing.expectEqual(@as(u32, 1), group.source_constraints_len);
        try std.testing.expectEqual(@as(u32, 1), group.destination_constraints_len);
        try std.testing.expectEqual(@as(u32, 1), group.events_len);
        const event = checker.cir.copied_open_literal_events.items.items[group.events_start];
        try std.testing.expectEqual(
            step.copied_groups_start + @as(u32, @intCast(group_offset)),
            event.group_index,
        );
        try std.testing.expectEqual(@as(u32, 0), event.constraint_offset);
        try std.testing.expectEqual(
            ModuleEnv.CopiedOpenLiteralEvent.LiteralKind.numeral,
            event.decodedLiteralKind().?,
        );
    }

    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_before);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const serialized_after = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_after);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after);
    try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
}

const DefaultFixtureBindingDecision = struct {
    pattern_idx: CIR.Pattern.Idx,
    scheme_use_index: u32,
    driver_copy_step: u32,
    decision_index: u32,
};

const DefaultFixtureConstraint = struct {
    index: u32,
    offset: u32,
    fn_var: Var,
};

const DefaultFixtureRoot = struct {
    step_index: usize,
    decision_index: u32,
    constraint: DefaultFixtureConstraint,
};

fn testFindUniqueAssignmentPattern(
    cir: *const ModuleEnv,
    name: []const u8,
) !CIR.Pattern.Idx {
    var found: ?CIR.Pattern.Idx = null;
    for (0..cir.store.nodes.len()) |raw_node| {
        const node_idx: CIR.Node.Idx = @enumFromInt(@as(u32, @intCast(raw_node)));
        if (cir.store.nodes.get(node_idx).tag != .pattern_identifier) continue;
        const pattern_idx: CIR.Pattern.Idx = @enumFromInt(@as(u32, @intCast(raw_node)));
        const pattern = cir.store.getPattern(pattern_idx);
        if (pattern != .assign or
            !std.mem.eql(u8, cir.getIdentStoreConst().getText(pattern.assign.ident), name))
        {
            continue;
        }
        if (found != null) return error.TestUnexpectedResult;
        found = pattern_idx;
    }
    return found orelse error.TestUnexpectedResult;
}

/// Locate a specialization-default decision through the producer-owned local
/// binding instantiation which contributed its receiver. This deliberately
/// does not recover the binding from the current use expression: a rejected
/// compatibility check may already have retired that node to `runtime_error`.
fn testDefaultDecisionForBinding(
    checker: *const Self,
    binding_name: []const u8,
) !DefaultFixtureBindingDecision {
    const pattern_idx = try testFindUniqueAssignmentPattern(checker.cir, binding_name);
    const raw_pattern = @intFromEnum(pattern_idx);
    const steps = checker.cir.where_marker_copy_steps.items.items;
    const uses = checker.cir.scheme_uses.items.items;
    const pairs = checker.cir.where_marker_copy_pairs.items.items;
    var found: ?DefaultFixtureBindingDecision = null;

    for (checker.cir.default_decisions.items.items, 0..) |decision, decision_index| {
        if (!rangeFits(
            decision.contributors_start,
            decision.contributors_len,
            checker.cir.default_decision_contributors.items.items.len,
        )) return error.TestUnexpectedResult;
        const contributors = checker.cir.default_decision_contributors.items.items[decision.contributors_start..][0..decision.contributors_len];
        for (contributors) |contributor| {
            if (contributor.decodedDriverKind() != .instantiation_copy or
                contributor.driver_copy_step >= steps.len)
            {
                continue;
            }
            const step = steps[contributor.driver_copy_step];
            if (step.decodedKind() != .scheme_use or
                step.origin.scheme_use.scheme_use_index >= uses.len)
            {
                continue;
            }
            const use = uses[step.origin.scheme_use.scheme_use_index];
            if (use.scheme_root != raw_pattern) continue;

            if (step.root_occurrence_offset >= step.occurrences_len or
                !rangeFits(
                    step.occurrences_start,
                    step.occurrences_len,
                    checker.cir.where_marker_copy_occurrences.items.items.len,
                ) or
                !rangeFits(step.pairs_start, step.pairs_len, pairs.len))
            {
                return error.TestUnexpectedResult;
            }
            const root_occurrence = checker.cir.where_marker_copy_occurrences.items.items[
                step.occurrences_start + step.root_occurrence_offset
            ];
            if (root_occurrence.canonical_pair_offset >= step.pairs_len) {
                return error.TestUnexpectedResult;
            }
            const root_pair = pairs[step.pairs_start + root_occurrence.canonical_pair_offset];
            try std.testing.expectEqual(raw_pattern, root_occurrence.raw_source_var);
            try std.testing.expectEqual(step.source_root_var, root_pair.source_var);
            try std.testing.expectEqual(
                checker.types.resolveVar(@enumFromInt(raw_pattern)).var_,
                @as(Var, @enumFromInt(root_pair.source_var)),
            );
            try std.testing.expectEqual(
                ModuleEnv.SchemeUseRecord.Slot.value_use,
                std.enums.fromInt(ModuleEnv.SchemeUseRecord.Slot, use.slot_kind).?,
            );
            try std.testing.expectEqual(@as(u32, 0), use.slot_data);
            try std.testing.expect(contributor.driver_pair_offset < step.pairs_len);
            const pair = pairs[step.pairs_start + contributor.driver_pair_offset];
            try std.testing.expectEqual(
                checker.types.resolveVar(@enumFromInt(decision.receiver_var)).var_,
                checker.types.resolveVar(@enumFromInt(pair.destination_var)).var_,
            );
            if (found != null) return error.TestUnexpectedResult;
            found = .{
                .pattern_idx = pattern_idx,
                .scheme_use_index = step.origin.scheme_use.scheme_use_index,
                .driver_copy_step = contributor.driver_copy_step,
                .decision_index = @intCast(decision_index),
            };
        }
    }
    return found orelse error.TestUnexpectedResult;
}

fn testFindUniqueDefaultConstraint(
    checker: *Self,
    decision_index: u32,
    method_ident: Ident.Idx,
    arity: u32,
) !DefaultFixtureConstraint {
    if (decision_index >= checker.cir.default_decisions.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const decision = checker.cir.default_decisions.items.items[decision_index];
    if (!rangeFits(
        decision.constraints_start,
        decision.constraints_len,
        checker.types.static_dispatch_constraints.items.items.len,
    )) return error.TestUnexpectedResult;
    var found: ?DefaultFixtureConstraint = null;
    var offset: u32 = 0;
    while (offset < decision.constraints_len) : (offset += 1) {
        const constraint_index = decision.constraints_start + offset;
        const constraint = checker.types.static_dispatch_constraints.items.items[constraint_index];
        if (!constraint.fn_name.eql(method_ident) or
            (checker.callableArity(constraint.fn_var) orelse continue) != arity)
        {
            continue;
        }
        if (found != null) return error.TestUnexpectedResult;
        found = .{
            .index = constraint_index,
            .offset = offset,
            .fn_var = constraint.fn_var,
        };
    }
    return found orelse error.TestUnexpectedResult;
}

fn testFindUniqueDefaultRoot(
    checker: *Self,
    method_ident: Ident.Idx,
    arity: u32,
) !DefaultFixtureRoot {
    var found: ?DefaultFixtureRoot = null;
    for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.decodedKind() != .default_method) continue;
        const origin = step.origin.default_method;
        if (origin.decision_index >= checker.cir.default_decisions.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const decision = checker.cir.default_decisions.items.items[origin.decision_index];
        if (origin.constraint_offset >= decision.constraints_len) return error.TestUnexpectedResult;
        const constraint_index = decision.constraints_start + origin.constraint_offset;
        const constraint = checker.types.static_dispatch_constraints.items.items[constraint_index];
        if (!constraint.fn_name.eql(method_ident) or
            (checker.callableArity(constraint.fn_var) orelse continue) != arity)
        {
            continue;
        }
        if (found != null) return error.TestUnexpectedResult;
        found = .{
            .step_index = step_index,
            .decision_index = origin.decision_index,
            .constraint = .{
                .index = constraint_index,
                .offset = origin.constraint_offset,
                .fn_var = constraint.fn_var,
            },
        };
    }
    return found orelse error.TestUnexpectedResult;
}

fn testFindDefaultMethodUse(
    checker: *const Self,
    root_step_index: usize,
    decision_index: u32,
    constraint: DefaultFixtureConstraint,
) !?usize {
    const steps = checker.cir.where_marker_copy_steps.items.items;
    if (root_step_index >= steps.len or steps[root_step_index].decodedKind() != .default_method) {
        return error.TestUnexpectedResult;
    }
    const root = steps[root_step_index];
    var found: ?usize = null;
    for (steps, 0..) |step, step_index| {
        if (step.decodedKind() != .default_method_use) continue;
        const origin = step.origin.default_method_use;
        if (origin.root_copy_step != @as(u32, @intCast(root_step_index)) or
            origin.decision_index != decision_index or
            origin.constraint_offset != constraint.offset)
        {
            continue;
        }
        if (found != null or origin.scheme_use_index >= checker.cir.scheme_uses.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const use = checker.cir.scheme_uses.items.items[origin.scheme_use_index];
        try std.testing.expectEqual(@as(u32, 0), origin.reserved_1);
        try std.testing.expectEqual(@as(u32, 0), origin.reserved_2);
        try std.testing.expectEqual(
            ModuleEnv.SchemeUseRecord.Slot.dispatch_target,
            std.enums.fromInt(ModuleEnv.SchemeUseRecord.Slot, use.slot_kind).?,
        );
        try std.testing.expectEqual(@intFromEnum(constraint.fn_var), use.slot_data);
        try std.testing.expectEqual(root.destination_root_var, step.source_root_var);
        try std.testing.expectEqual(root.destination_root_var, use.scheme_root);
        try std.testing.expectEqual(
            if (constraintIntroExpr(
                checker.types.static_dispatch_constraints.items.items[constraint.index],
            )) |expr| @intFromEnum(expr) else 0,
            use.node_idx,
        );
        found = step_index;
    }
    return found;
}

fn testCountDefaultMethodUses(checker: *const Self, root_step_index: usize) usize {
    var count: usize = 0;
    for (checker.cir.where_marker_copy_steps.items.items) |step| {
        if (step.decodedKind() == .default_method_use and
            step.origin.default_method_use.root_copy_step == @as(u32, @intCast(root_step_index)))
        {
            count += 1;
        }
    }
    return count;
}

/// Require the committed default child to be the sole producer and target for
/// its raw dispatch edge. The method var is compared with the child copy's raw
/// root occurrence, before checked-boundary rebuilding resolves step roots.
fn testExpectSoleDefaultDispatchTarget(
    checker: *const Self,
    builtin_env: *const ModuleEnv,
    use_step_index: usize,
    constraint: DefaultFixtureConstraint,
) !void {
    const steps = checker.cir.where_marker_copy_steps.items.items;
    if (use_step_index >= steps.len) return error.TestUnexpectedResult;
    const use_step = steps[use_step_index];
    if (use_step.decodedKind() != .default_method_use or
        use_step.root_occurrence_offset >= use_step.occurrences_len or
        !rangeFits(
            use_step.occurrences_start,
            use_step.occurrences_len,
            checker.cir.where_marker_copy_occurrences.items.items.len,
        ))
    {
        return error.TestUnexpectedResult;
    }
    const origin = use_step.origin.default_method_use;
    if (origin.root_copy_step >= steps.len) return error.TestUnexpectedResult;
    const root_step = steps[origin.root_copy_step];
    if (root_step.decodedKind() != .default_method) return error.TestUnexpectedResult;
    const root_origin = root_step.origin.default_method;
    const root_occurrence = checker.cir.where_marker_copy_occurrences.items.items[
        use_step.occurrences_start + use_step.root_occurrence_offset
    ];

    const target_index = checker.dispatch_target_instantiation_by_fn_var.get(constraint.fn_var) orelse
        return error.TestUnexpectedResult;
    if (target_index >= checker.dispatch_target_instantiations.items.len) {
        return error.TestUnexpectedResult;
    }
    const target = checker.dispatch_target_instantiations.items[target_index];
    try std.testing.expectEqual(constraint.fn_var, target.constraint_fn_var);
    try std.testing.expect(!target.is_literal_conversion);
    try std.testing.expectEqual(
        checker.dispatch_derivation_by_child_fn_var.get(constraint.fn_var),
        target.parent_constraint_fn_var,
    );
    try std.testing.expectEqual(@intFromPtr(builtin_env), @intFromPtr(target.target_env));
    try std.testing.expectEqual(
        @as(CIR.Node.Idx, @enumFromInt(root_origin.provider_type_node)),
        target.target_binding.type_node_idx,
    );
    try std.testing.expectEqual(
        @as(CIR.Def.Idx, @enumFromInt(root_origin.provider_def)),
        target.target_binding.def_idx,
    );
    try std.testing.expect(target.method_name.eql(
        checker.types.static_dispatch_constraints.items.items[constraint.index].fn_name,
    ));
    try std.testing.expectEqual(
        @as(Var, @enumFromInt(root_occurrence.raw_destination_var)),
        target.method_var,
    );

    var target_row_count: usize = 0;
    for (checker.dispatch_target_instantiations.items) |candidate| {
        target_row_count += @intFromBool(candidate.constraint_fn_var == constraint.fn_var);
    }
    try std.testing.expectEqual(@as(usize, 1), target_row_count);

    var dispatch_use_count: usize = 0;
    for (checker.cir.scheme_uses.items.items) |use| {
        dispatch_use_count += @intFromBool(
            use.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target) and
                use.slot_data == @intFromEnum(constraint.fn_var),
        );
    }
    try std.testing.expectEqual(@as(usize, 1), dispatch_use_count);

    var selected_decision_count: usize = 0;
    for (checker.cir.selected_method_decisions.items.items) |decision| {
        if (decision.decodedState() != .complete or
            decision.scheme_use_index >= checker.cir.scheme_uses.items.items.len)
        {
            continue;
        }
        const use = checker.cir.scheme_uses.items.items[decision.scheme_use_index];
        selected_decision_count += @intFromBool(
            use.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target) and
                use.slot_data == @intFromEnum(constraint.fn_var),
        );
    }
    try std.testing.expectEqual(@as(usize, 0), selected_decision_count);
    try std.testing.expect(
        checker.settled_static_dispatch_constraint_fns.contains(constraint.fn_var),
    );
}

fn testExpectNoDispatchTargetForRawFn(checker: *const Self, fn_var: Var) !void {
    try std.testing.expect(checker.dispatch_target_instantiation_by_fn_var.get(fn_var) == null);
    for (checker.dispatch_target_instantiations.items) |target| {
        try std.testing.expect(target.constraint_fn_var != fn_var);
    }
    for (checker.cir.scheme_uses.items.items) |use| {
        try std.testing.expect(!(use.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target) and
            use.slot_data == @intFromEnum(fn_var)));
    }
}

const StagedDefaultTargetCompatibility = struct {
    main_expr: CIR.Expr.Idx,
    literal_var: Var,
    driver: OpenLiteralDriver,
    registration_index: usize,
    receiver_var: Var,
    constraints: StaticDispatchConstraint.SafeList.Range,
    plus: DefaultFixtureConstraint,
};

fn testStageDefaultTargetCompatibility(
    checker: *Self,
    main_expr: CIR.Expr.Idx,
    env: *Env,
) !StagedDefaultTargetCompatibility {
    const original_expr = checker.cir.store.getExpr(main_expr);
    if (original_expr != .e_binop or original_expr.e_binop.op != .add) {
        return error.TestUnexpectedResult;
    }
    const lhs_expr = original_expr.e_binop.lhs;

    checker.beginTypecheck();
    try ensureTypeStoreIsFilled(checker);
    try checker.reserveWhereAliasDeclarationPublications();
    try checker.collectHostBoundaryAnnotations();
    try checker.copyBuiltinTypes();
    for (0..checker.cir.builtin_statements.span.len) |stmt_offset| {
        const stmt_idx = checker.cir.store.statementAt(
            checker.cir.builtin_statements,
            stmt_offset,
        );
        try checker.generateStmtTypeDeclType(stmt_idx, env);
    }
    try checker.finalizeTypeDeclarationValidity();
    try env.var_pool.pushRank();
    try std.testing.expectEqual(Rank.outermost, env.rank());
    _ = try checker.checkExpr(main_expr, env, Expected.none());

    const checked_expr = checker.cir.store.getExpr(main_expr);
    if (checked_expr != .e_dispatch_call) return error.TestUnexpectedResult;
    const call = checked_expr.e_dispatch_call;
    if (call.receiver != lhs_expr or
        !call.method_name.eql(checker.cir.idents.plus) or
        call.surface_origin != .binop or
        call.surface_origin.binop != .add)
    {
        return error.TestUnexpectedResult;
    }

    try std.testing.expectEqual(
        checker.open_literal_vars.items.len,
        checker.open_literal_creation_drivers.items.len,
    );
    const lhs_node = ModuleEnv.nodeIdxFrom(lhs_expr);
    var literal_var: ?Var = null;
    var literal_driver: ?OpenLiteralDriver = null;
    var registration_index: ?usize = null;
    for (
        checker.open_literal_vars.items,
        checker.open_literal_creation_drivers.items,
        0..,
    ) |candidate_var, registration, candidate_index| {
        if (registration.driver != .literal_creation) continue;
        const creation = registration.driver.literal_creation;
        if (creation.source_node != lhs_node or
            creation.occurrence_kind != .expr or
            creation.kind != .numeral)
        {
            continue;
        }
        if (literal_var != null) return error.TestUnexpectedResult;
        literal_var = candidate_var;
        literal_driver = registration.driver;
        registration_index = candidate_index;
        try std.testing.expectEqual(@as(?u32, null), registration.decision_draft_index);
    }
    const raw_literal_var = literal_var orelse return error.TestUnexpectedResult;
    const driver = literal_driver orelse return error.TestUnexpectedResult;
    const exact_registration_index = registration_index orelse
        return error.TestUnexpectedResult;
    const receiver = checker.types.resolveVar(raw_literal_var);
    const constraints = contentConstraintRange(receiver.desc.content) orelse
        return error.TestUnexpectedResult;

    var plus_constraint: ?DefaultFixtureConstraint = null;
    var constraint_offset: u32 = 0;
    while (constraint_offset < constraints.len()) : (constraint_offset += 1) {
        const constraint_index = @intFromEnum(constraints.start) + constraint_offset;
        const constraint = checker.types.static_dispatch_constraints.items.items[constraint_index];
        if (!constraint.fn_name.eql(checker.cir.idents.plus) or
            constraint.fn_var != call.constraint_fn_var or
            constraint.origin != .desugared_binop or
            constraint.origin.desugared_binop.negated or
            constraintIntroExpr(constraint) != main_expr or
            (checker.callableArity(constraint.fn_var) orelse continue) != 2)
        {
            continue;
        }
        if (plus_constraint != null) return error.TestUnexpectedResult;
        plus_constraint = .{
            .index = constraint_index,
            .offset = constraint_offset,
            .fn_var = constraint.fn_var,
        };
    }
    const plus = plus_constraint orelse return error.TestUnexpectedResult;

    // The open-numeral ledger independently authenticates that this exact
    // receiver/range came from the source lhs, rather than from a later shape
    // reconstruction over the merged constraint component.
    var numeral_driver_count: usize = 0;
    for (checker.open_numeral_literals.items) |numeral| {
        if (numeral.source_node != lhs_node or
            checker.types.resolveVar(numeral.var_).var_ != receiver.var_ or
            !numeral.constraint.fn_name.eql(checker.cir.idents.from_numeral) or
            numeral.constraint.origin != .from_literal or
            numeral.constraint.origin.from_literal != .numeral)
        {
            continue;
        }
        numeral_driver_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), numeral_driver_count);

    return .{
        .main_expr = main_expr,
        .literal_var = raw_literal_var,
        .driver = driver,
        .registration_index = exact_registration_index,
        .receiver_var = receiver.var_,
        .constraints = constraints,
        .plus = plus,
    };
}

fn testCheckFlexVarConstraintCompatibilityWithAllocator(
    checker: *Self,
    env: *Env,
    allocator: Allocator,
    literal_var: Var,
    driver: OpenLiteralDriver,
) Allocator.Error!bool {
    const original_checker_gpa = checker.gpa;
    const original_cir_gpa = checker.cir.gpa;
    const original_types_gpa = checker.types.gpa;
    checker.gpa = allocator;
    checker.cir.gpa = allocator;
    checker.types.gpa = allocator;
    defer {
        checker.gpa = original_checker_gpa;
        checker.cir.gpa = original_cir_gpa;
        checker.types.gpa = original_types_gpa;
    }

    return checker.checkFlexVarConstraintCompatibility(
        literal_var,
        env,
        true,
        .{ .open_literal_driver = driver },
    );
}

test "staged default target compatibility is atomic across every routed allocation" {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    const prepared_builtin_indices = compiled_builtins.builtinIndices(CIR);
    var builtin_module = try can.BuiltinStatic.moduleView(
        std.testing.allocator,
        compiled_builtins.builtin_bin[0..],
        "Builtin",
        compiled_builtins.builtin_source,
    );
    defer builtin_module.deinit();
    var owned_builtin_validation = try admitBuiltinOwned(
        std.testing.allocator,
        builtin_module.env,
        prepared_builtin_indices,
    );
    defer owned_builtin_validation.deinit();
    const builtin_validation = owned_builtin_validation.capability();

    var test_env = try TestEnv.initUncheckedWithAdmittedBuiltinForTesting(
        "DefaultTargetOomCalibration",
        "main = 5 + 6",
        builtin_module,
        builtin_validation,
        prepared_builtin_indices,
    );
    defer test_env.deinit();
    try test_env.assertCanErrors(&.{});

    // This allocator is owned by the caller and outlives both the Env and the
    // checker state that a successful CommitProbe leaves allocated from it.
    // Failed resizes fall back to counted allocations so the exhaustive sweep
    // below cannot miss in-place growth.
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const failing_gpa = failing.allocator();
    var env = try Env.init(failing_gpa, .generalized);
    defer env.deinit(failing_gpa);

    const checker = &test_env.checker;
    const main_def_idx = test_env.can.explicitRootDefByName("main") orelse
        return error.TestUnexpectedResult;
    const main_def = checker.cir.store.getDef(main_def_idx);
    const main_expr = main_def.expr;

    // Mirror checkExprRepl only through the real expression checker. This
    // deliberately stops before default finalization so the exact ordinary
    // literal edge can be driven once by the compatibility producer below.
    const staged = try testStageDefaultTargetCompatibility(checker, main_expr, &env);
    const raw_literal_var = staged.literal_var;
    const driver = staged.driver;
    const exact_registration_index = staged.registration_index;
    const receiver_before = checker.types.resolveVar(raw_literal_var);
    try std.testing.expectEqual(staged.receiver_var, receiver_before.var_);
    const constraints = staged.constraints;
    const plus = staged.plus;

    try std.testing.expect(!checker.default_decision_drafts_frozen);
    try std.testing.expectEqual(@as(usize, 0), checker.cir.default_decisions.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.default_decision_drafts.items.len);
    try testExpectNoDispatchTargetForRawFn(checker, plus.fn_var);

    const rank_before = env.rank();
    const deferred_before = env.deferred_static_dispatch_constraints.items.items.len;
    const probe_depth_before = checker.probe_depth;
    const commit_probe_active_before = checker.commit_probe_active;
    const store_savepoint_depth_before = checker.types.savepoint_depth;
    const ident_savepoint_depth_before = checker.cir.common.idents.interner.savepoint_depth;
    const identity_savepoint_depth_before = checker.cir.module_identities.savepoint_depth;
    const evidence_target_site_before = checker.evidence_target_site;
    const problems_before = checker.problems.problems.items.len;
    const allocation_base = failing.alloc_index;
    failing.resize_fail_index = failing.resize_index;

    const had_error = try testCheckFlexVarConstraintCompatibilityWithAllocator(
        checker,
        &env,
        failing_gpa,
        raw_literal_var,
        driver,
    );
    const calibration_allocations = failing.alloc_index - allocation_base;
    try std.testing.expect(!had_error);
    try std.testing.expect(!failing.has_induced_failure);
    try std.testing.expect(calibration_allocations > 0);

    try std.testing.expectEqual(rank_before, env.rank());
    try std.testing.expect(env.deferred_static_dispatch_constraints.items.items.len >= deferred_before);
    try std.testing.expectEqual(probe_depth_before, checker.probe_depth);
    try std.testing.expectEqual(commit_probe_active_before, checker.commit_probe_active);
    try std.testing.expectEqual(store_savepoint_depth_before, checker.types.savepoint_depth);
    try std.testing.expectEqual(
        ident_savepoint_depth_before,
        checker.cir.common.idents.interner.savepoint_depth,
    );
    try std.testing.expectEqual(
        identity_savepoint_depth_before,
        checker.cir.module_identities.savepoint_depth,
    );
    try std.testing.expect(std.meta.eql(evidence_target_site_before, checker.evidence_target_site));
    try std.testing.expectEqual(problems_before, checker.problems.problems.items.len);

    const draft_index = checker.open_literal_creation_drivers.items[
        exact_registration_index
    ].decision_draft_index orelse return error.TestUnexpectedResult;
    if (draft_index >= checker.default_decision_drafts.items.len) {
        return error.TestUnexpectedResult;
    }
    const draft = checker.default_decision_drafts.items[draft_index];
    try std.testing.expectEqual(receiver_before.var_, draft.receiver_var);
    try std.testing.expectEqual(@intFromEnum(constraints.start), @intFromEnum(draft.constraints.start));
    try std.testing.expectEqual(constraints.len(), draft.constraints.len());
    try std.testing.expectEqual(literal_defaulting.DefaultTarget.dec, draft.target);
    var matching_contributors: usize = 0;
    for (checker.default_decision_draft_contributors.items) |contributor| {
        try std.testing.expectEqual(draft_index, contributor.decision_draft_index);
        try std.testing.expect(std.meta.eql(driver, contributor.driver));
        matching_contributors += 1;
    }
    try std.testing.expectEqual(@as(usize, 2), matching_contributors);
    try std.testing.expectEqual(
        matching_contributors,
        checker.default_decision_draft_contributors.items.len,
    );
    for (checker.open_literal_creation_drivers.items, 0..) |registration, registration_index| {
        const expected_draft_index: ?u32 = if (registration_index == exact_registration_index)
            draft_index
        else
            null;
        try std.testing.expectEqual(expected_draft_index, registration.decision_draft_index);
    }

    const builtin_env = checker.builtin_ctx.builtin_module orelse
        return error.TestUnexpectedResult;
    const builtin_indices = checker.builtin_ctx.builtin_indices orelse
        return error.TestUnexpectedResult;
    const method_entry = builtin_env.lookupMethodBindingEntryFromTwoEnvsAndDeclConst(
        @intFromEnum(builtin_indices.dec_type),
        checker.cir,
        checker.cir.idents.plus,
    ) orelse return error.TestUnexpectedResult;

    var root_step_index: ?usize = null;
    for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.decodedKind() != .default_method) continue;
        const origin = step.origin.default_method;
        if (origin.decision_index != draft_index or origin.constraint_offset != plus.offset) continue;
        if (root_step_index != null) return error.TestUnexpectedResult;
        root_step_index = step_index;
        try std.testing.expectEqual(@as(u32, 0), origin.reserved_0);
        try std.testing.expectEqual(@intFromEnum(builtin_indices.dec_type), origin.builtin_decl_index);
        try std.testing.expectEqual(@intFromEnum(method_entry.binding.type_node_idx), origin.provider_type_node);
        try std.testing.expectEqual(@intFromEnum(method_entry.binding.def_idx), origin.provider_def);
    }
    const root_index = root_step_index orelse return error.TestUnexpectedResult;
    const raw_root_index: u32 = @intCast(root_index);
    const root_step = checker.cir.where_marker_copy_steps.items.items[root_index];

    const imported_index = checker.imported_method_scheme_by_source.get(.{
        .env = builtin_env,
        .type_node_idx = method_entry.binding.type_node_idx,
    }) orelse return error.TestUnexpectedResult;
    if (imported_index >= checker.imported_method_schemes.items.len) {
        return error.TestUnexpectedResult;
    }
    const imported = checker.imported_method_schemes.items[imported_index];
    try std.testing.expectEqual(raw_root_index, imported.copy_step);
    if (root_step.root_occurrence_offset >= root_step.occurrences_len or
        !rangeFits(
            root_step.occurrences_start,
            root_step.occurrences_len,
            checker.cir.where_marker_copy_occurrences.items.items.len,
        ) or
        !rangeFits(
            root_step.pairs_start,
            root_step.pairs_len,
            checker.cir.where_marker_copy_pairs.items.items.len,
        ))
    {
        return error.TestUnexpectedResult;
    }
    const imported_root_occurrence = checker.cir.where_marker_copy_occurrences.items.items[
        root_step.occurrences_start + root_step.root_occurrence_offset
    ];
    if (imported_root_occurrence.canonical_pair_offset >= root_step.pairs_len) {
        return error.TestUnexpectedResult;
    }
    const imported_root_pair = checker.cir.where_marker_copy_pairs.items.items[
        root_step.pairs_start + imported_root_occurrence.canonical_pair_offset
    ];
    try std.testing.expectEqual(
        @intFromEnum(imported.scheme_var),
        imported_root_occurrence.raw_destination_var,
    );
    try std.testing.expectEqual(root_step.source_root_var, imported_root_pair.source_var);
    try std.testing.expectEqual(root_step.destination_root_var, imported_root_pair.destination_var);

    var child_step_index: ?usize = null;
    var scheme_use_index: ?u32 = null;
    for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.decodedKind() != .default_method_use) continue;
        const origin = step.origin.default_method_use;
        if (origin.decision_index != draft_index or
            origin.constraint_offset != plus.offset or
            origin.root_copy_step != raw_root_index)
        {
            continue;
        }
        if (child_step_index != null) return error.TestUnexpectedResult;
        child_step_index = step_index;
        scheme_use_index = origin.scheme_use_index;
        try std.testing.expectEqual(@as(u32, 0), origin.reserved_1);
        try std.testing.expectEqual(@as(u32, 0), origin.reserved_2);
    }
    const child_index = child_step_index orelse return error.TestUnexpectedResult;
    const use_index = scheme_use_index orelse return error.TestUnexpectedResult;
    if (use_index >= checker.cir.scheme_uses.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const child_step = checker.cir.where_marker_copy_steps.items.items[child_index];
    const use = checker.cir.scheme_uses.items.items[use_index];
    try std.testing.expectEqual(
        ModuleEnv.SchemeUseRecord.Slot.dispatch_target,
        std.enums.fromInt(ModuleEnv.SchemeUseRecord.Slot, use.slot_kind).?,
    );
    try std.testing.expectEqual(@intFromEnum(plus.fn_var), use.slot_data);
    try std.testing.expectEqual(@intFromEnum(main_expr), use.node_idx);
    if (child_step.root_occurrence_offset >= child_step.occurrences_len or
        !rangeFits(
            child_step.occurrences_start,
            child_step.occurrences_len,
            checker.cir.where_marker_copy_occurrences.items.items.len,
        ) or
        !rangeFits(
            child_step.pairs_start,
            child_step.pairs_len,
            checker.cir.where_marker_copy_pairs.items.items.len,
        ))
    {
        return error.TestUnexpectedResult;
    }
    const root_occurrence = checker.cir.where_marker_copy_occurrences.items.items[
        child_step.occurrences_start + child_step.root_occurrence_offset
    ];
    if (root_occurrence.canonical_pair_offset >= child_step.pairs_len) {
        return error.TestUnexpectedResult;
    }
    const child_root_pair = checker.cir.where_marker_copy_pairs.items.items[
        child_step.pairs_start + root_occurrence.canonical_pair_offset
    ];
    try std.testing.expectEqual(@intFromEnum(imported.scheme_var), use.scheme_root);
    try std.testing.expectEqual(use.scheme_root, root_occurrence.raw_source_var);
    try std.testing.expectEqual(child_step.source_root_var, child_root_pair.source_var);
    try std.testing.expectEqual(child_step.destination_root_var, child_root_pair.destination_var);

    const target_index = checker.dispatch_target_instantiation_by_fn_var.get(plus.fn_var) orelse
        return error.TestUnexpectedResult;
    if (target_index >= checker.dispatch_target_instantiations.items.len) {
        return error.TestUnexpectedResult;
    }
    const target = checker.dispatch_target_instantiations.items[target_index];
    try std.testing.expectEqual(plus.fn_var, target.constraint_fn_var);
    try std.testing.expect(!target.is_literal_conversion);
    try std.testing.expectEqual(raw_literal_var, target.receiver_var);
    try std.testing.expectEqual(@as(?Var, null), target.parent_constraint_fn_var);
    try std.testing.expectEqual(@intFromPtr(builtin_env), @intFromPtr(target.target_env));
    try std.testing.expect(std.meta.eql(method_entry.binding, target.target_binding));
    try std.testing.expectEqual(method_entry.entry_index, target.provider_method_entry_index);
    try std.testing.expect(target.method_name.eql(checker.cir.idents.plus));
    try std.testing.expectEqual(
        @as(Var, @enumFromInt(root_occurrence.raw_destination_var)),
        target.method_var,
    );
    try std.testing.expectEqual(
        @as(?u32, target_index),
        checker.dispatch_target_instantiation_by_fn_var.get(plus.fn_var),
    );

    try std.testing.expectEqual(
        checker.dispatch_target_instantiations.items.len,
        checker.dispatch_target_instantiation_by_fn_var.count(),
    );
    for (checker.dispatch_target_instantiations.items, 0..) |candidate, candidate_index| {
        try std.testing.expectEqual(
            @as(?u32, @intCast(candidate_index)),
            checker.dispatch_target_instantiation_by_fn_var.get(candidate.constraint_fn_var),
        );
    }
    var matching_uses: usize = 0;
    for (checker.cir.scheme_uses.items.items) |candidate| {
        matching_uses += @intFromBool(
            candidate.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target) and
                candidate.slot_data == @intFromEnum(plus.fn_var),
        );
    }
    try std.testing.expectEqual(@as(usize, 1), matching_uses);
    try std.testing.expectEqual(@as(usize, 0), checker.cir.selected_method_decisions.items.items.len);
    try std.testing.expect(!checker.settled_static_dispatch_constraint_fns.contains(plus.fn_var));

    var saw_failure_before_root = false;
    var saw_committed_root_without_target = false;
    var failure_index: usize = 0;
    while (failure_index < calibration_allocations) : (failure_index += 1) {
        var failed_test_env = try TestEnv.initUncheckedWithAdmittedBuiltinForTesting(
            "DefaultTargetOomCalibration",
            "main = 5 + 6",
            builtin_module,
            builtin_validation,
            prepared_builtin_indices,
        );
        defer failed_test_env.deinit();
        try failed_test_env.assertCanErrors(&.{});

        // Keep both objects caller-owned and immobile. A successful Probe
        // commit can retain allocator pointers in the Env and VarMap; the
        // failing allocator therefore outlives their deinitialization too.
        var injected = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = std.math.maxInt(usize),
            .resize_fail_index = std.math.maxInt(usize),
        });
        const injected_gpa = injected.allocator();
        var failed_env = try Env.init(injected_gpa, .generalized);
        defer failed_env.deinit(injected_gpa);

        const failed_checker = &failed_test_env.checker;
        const failed_main_def_idx = failed_test_env.can.explicitRootDefByName("main") orelse
            return error.TestUnexpectedResult;
        const failed_main_expr = failed_checker.cir.store.getDef(failed_main_def_idx).expr;
        const failed_staged = try testStageDefaultTargetCompatibility(
            failed_checker,
            failed_main_expr,
            &failed_env,
        );
        try std.testing.expect(!failed_checker.default_decision_drafts_frozen);
        try std.testing.expectEqual(
            @as(usize, 0),
            failed_checker.default_decision_drafts.items.len,
        );
        try testExpectNoDispatchTargetForRawFn(failed_checker, failed_staged.plus.fn_var);

        const receiver_snapshot = failed_checker.types.resolveVar(failed_staged.literal_var);
        const callable_snapshot = failed_checker.types.resolveVar(failed_staged.plus.fn_var);
        const constraint_snapshot = failed_checker.types.static_dispatch_constraints.items.items[
            failed_staged.plus.index
        ];
        const rank_before_failure = failed_env.rank();
        const rank_lists = failed_env.var_pool.slice();
        const rank_lengths = try std.testing.allocator.alloc(usize, rank_lists.len);
        defer std.testing.allocator.free(rank_lengths);
        for (rank_lists, rank_lengths) |rank_list, *rank_len| {
            rank_len.* = rank_list.items.len;
        }
        const deferred_before_failure = failed_env.deferred_static_dispatch_constraints.items.items.len;
        const problems_before_failure = failed_checker.problems.problems.items.len;
        const snapshots_before_failure = failed_checker.snapshots.mark();
        const types_len_before_failure = failed_checker.types.len();
        const regions_before_failure = failed_checker.regions.items.items.len;
        const scheme_uses_before_failure = failed_checker.cir.scheme_uses.items.items.len;
        const scheme_use_pairs_before_failure = failed_checker.cir.scheme_use_pairs.items.items.len;
        const marker_uses_before_failure = failed_checker.cir.where_method_marker_uses.items.items.len;
        const copy_steps_before_failure = failed_checker.cir.where_marker_copy_steps.items.items.len;
        const copy_pairs_before_failure = failed_checker.cir.where_marker_copy_pairs.items.items.len;
        const copy_occurrences_before_failure = failed_checker.cir.where_marker_copy_occurrences.items.items.len;
        const copy_witnesses_before_failure = failed_checker.cir.where_marker_copy_witnesses.items.items.len;
        const derivations_before_failure = failed_checker.dispatch_derivations.items.len;
        const derivation_map_before_failure = failed_checker.dispatch_derivation_by_child_fn_var.count();
        const targets_before_failure = failed_checker.dispatch_target_instantiations.items.len;
        const target_map_before_failure = failed_checker.dispatch_target_instantiation_by_fn_var.count();
        const probe_depth_before_failure = failed_checker.probe_depth;
        const commit_probe_before_failure = failed_checker.commit_probe_active;
        const store_depth_before_failure = failed_checker.types.savepoint_depth;
        const ident_depth_before_failure = failed_checker.cir.common.idents.interner.savepoint_depth;
        const identity_depth_before_failure = failed_checker.cir.module_identities.savepoint_depth;
        const evidence_site_before_failure = failed_checker.evidence_target_site;
        const draft_journal_before_failure = failed_checker.default_decision_draft_assignment_journal.items.len;

        var failure_stage: []const u8 = "compatibility";
        errdefer std.debug.print(
            "default-target allocation sweep failed at failure_index={} stage={s}\n",
            .{ failure_index, failure_stage },
        );
        const failure_allocation_base = injected.alloc_index;
        injected.fail_index = std.math.add(
            usize,
            failure_allocation_base,
            failure_index,
        ) catch return error.TestUnexpectedResult;
        injected.resize_fail_index = injected.resize_index;
        const failure_result = testCheckFlexVarConstraintCompatibilityWithAllocator(
            failed_checker,
            &failed_env,
            injected_gpa,
            failed_staged.literal_var,
            failed_staged.driver,
        );
        try std.testing.expectError(error.OutOfMemory, failure_result);
        try std.testing.expect(injected.has_induced_failure);

        failure_stage = "rollback-state";
        const receiver_after = failed_checker.types.resolveVar(failed_staged.literal_var);
        const callable_after = failed_checker.types.resolveVar(failed_staged.plus.fn_var);
        try std.testing.expectEqual(receiver_snapshot.var_, receiver_after.var_);
        try std.testing.expect(std.meta.eql(receiver_snapshot.desc, receiver_after.desc));
        try std.testing.expectEqual(callable_snapshot.var_, callable_after.var_);
        try std.testing.expect(std.meta.eql(callable_snapshot.desc, callable_after.desc));
        try std.testing.expect(std.meta.eql(
            constraint_snapshot,
            failed_checker.types.static_dispatch_constraints.items.items[failed_staged.plus.index],
        ));
        try std.testing.expectEqual(rank_before_failure, failed_env.rank());
        try std.testing.expectEqual(rank_lengths.len, failed_env.var_pool.slice().len);
        for (rank_lengths, 0..) |expected_len, rank_index| {
            try std.testing.expectEqual(
                expected_len,
                failed_env.var_pool.getVarsForRank(@enumFromInt(rank_index)).len,
            );
        }
        try std.testing.expectEqual(
            deferred_before_failure,
            failed_env.deferred_static_dispatch_constraints.items.items.len,
        );
        try std.testing.expectEqual(problems_before_failure, failed_checker.problems.problems.items.len);
        try std.testing.expect(std.meta.eql(snapshots_before_failure, failed_checker.snapshots.mark()));
        try std.testing.expectEqual(
            scheme_uses_before_failure,
            failed_checker.cir.scheme_uses.items.items.len,
        );
        try std.testing.expectEqual(
            scheme_use_pairs_before_failure,
            failed_checker.cir.scheme_use_pairs.items.items.len,
        );
        try std.testing.expectEqual(
            marker_uses_before_failure,
            failed_checker.cir.where_method_marker_uses.items.items.len,
        );
        try std.testing.expectEqual(
            derivations_before_failure,
            failed_checker.dispatch_derivations.items.len,
        );
        try std.testing.expectEqual(
            derivation_map_before_failure,
            failed_checker.dispatch_derivation_by_child_fn_var.count(),
        );
        try std.testing.expectEqual(
            targets_before_failure,
            failed_checker.dispatch_target_instantiations.items.len,
        );
        try std.testing.expectEqual(
            target_map_before_failure,
            failed_checker.dispatch_target_instantiation_by_fn_var.count(),
        );
        try std.testing.expectEqual(probe_depth_before_failure, failed_checker.probe_depth);
        try std.testing.expectEqual(commit_probe_before_failure, failed_checker.commit_probe_active);
        try std.testing.expectEqual(store_depth_before_failure, failed_checker.types.savepoint_depth);
        try std.testing.expectEqual(
            ident_depth_before_failure,
            failed_checker.cir.common.idents.interner.savepoint_depth,
        );
        try std.testing.expectEqual(
            identity_depth_before_failure,
            failed_checker.cir.module_identities.savepoint_depth,
        );
        try std.testing.expect(std.meta.eql(
            evidence_site_before_failure,
            failed_checker.evidence_target_site,
        ));
        try std.testing.expectEqual(
            draft_journal_before_failure,
            failed_checker.default_decision_draft_assignment_journal.items.len,
        );

        failure_stage = "publication-absence";
        try testExpectNoDispatchTargetForRawFn(failed_checker, failed_staged.plus.fn_var);
        try std.testing.expect(
            failed_checker.dispatch_derivation_by_child_fn_var.get(failed_staged.plus.fn_var) == null,
        );
        try std.testing.expect(
            !failed_checker.settled_static_dispatch_constraint_fns.contains(failed_staged.plus.fn_var),
        );
        try std.testing.expectEqual(
            failed_checker.dispatch_target_instantiations.items.len,
            failed_checker.dispatch_target_instantiation_by_fn_var.count(),
        );
        for (failed_checker.dispatch_target_instantiations.items, 0..) |candidate, candidate_index| {
            try std.testing.expectEqual(
                @as(?u32, @intCast(candidate_index)),
                failed_checker.dispatch_target_instantiation_by_fn_var.get(candidate.constraint_fn_var),
            );
        }
        var child_count: usize = 0;
        for (failed_checker.cir.where_marker_copy_steps.items.items) |step| {
            child_count += @intFromBool(step.decodedKind() == .default_method_use);
        }
        try std.testing.expectEqual(@as(usize, 0), child_count);
        try std.testing.expectEqual(
            @as(usize, 0),
            failed_checker.cir.selected_method_decisions.items.items.len,
        );
        try std.testing.expect(!failed_checker.default_decision_drafts_frozen);
        try std.testing.expectEqual(
            @as(usize, 0),
            failed_checker.cir.default_decisions.items.items.len,
        );

        failure_stage = "draft-ledger";
        const maybe_draft_index = failed_checker.open_literal_creation_drivers.items[
            failed_staged.registration_index
        ].decision_draft_index;
        if (maybe_draft_index) |failed_draft_index| {
            try std.testing.expectEqual(
                @as(usize, 1),
                failed_checker.default_decision_drafts.items.len,
            );
            if (failed_draft_index >= failed_checker.default_decision_drafts.items.len) {
                return error.TestUnexpectedResult;
            }
            const failed_draft = failed_checker.default_decision_drafts.items[failed_draft_index];
            try std.testing.expectEqual(failed_staged.receiver_var, failed_draft.receiver_var);
            try std.testing.expectEqual(
                @intFromEnum(failed_staged.constraints.start),
                @intFromEnum(failed_draft.constraints.start),
            );
            try std.testing.expectEqual(failed_staged.constraints.len(), failed_draft.constraints.len());
            try std.testing.expectEqual(literal_defaulting.DefaultTarget.dec, failed_draft.target);
            var failed_contributor_count: usize = 0;
            for (failed_checker.default_decision_draft_contributors.items) |contributor| {
                try std.testing.expectEqual(failed_draft_index, contributor.decision_draft_index);
                try std.testing.expect(std.meta.eql(failed_staged.driver, contributor.driver));
                failed_contributor_count += 1;
            }
            try std.testing.expectEqual(@as(usize, 2), failed_contributor_count);
            try std.testing.expectEqual(
                failed_contributor_count,
                failed_checker.default_decision_draft_contributors.items.len,
            );
        } else {
            try std.testing.expectEqual(
                @as(usize, 0),
                failed_checker.default_decision_drafts.items.len,
            );
            try std.testing.expectEqual(
                @as(usize, 0),
                failed_checker.default_decision_draft_contributors.items.len,
            );
        }
        for (failed_checker.open_literal_creation_drivers.items, 0..) |registration, registration_index| {
            const expected_draft_index: ?u32 = if (registration_index == failed_staged.registration_index)
                maybe_draft_index
            else
                null;
            try std.testing.expectEqual(expected_draft_index, registration.decision_draft_index);
        }

        failure_stage = "cache-root";
        const failed_builtin_env = failed_checker.builtin_ctx.builtin_module orelse
            return error.TestUnexpectedResult;
        const failed_builtin_indices = failed_checker.builtin_ctx.builtin_indices orelse
            return error.TestUnexpectedResult;
        const failed_method_entry = failed_builtin_env.lookupMethodBindingEntryFromTwoEnvsAndDeclConst(
            @intFromEnum(failed_builtin_indices.dec_type),
            failed_checker.cir,
            failed_checker.cir.idents.plus,
        ) orelse return error.TestUnexpectedResult;
        const failed_cache_key = ImportedMethodSchemeKey{
            .env = failed_builtin_env,
            .type_node_idx = failed_method_entry.binding.type_node_idx,
        };
        try std.testing.expectEqual(
            failed_checker.imported_method_schemes.items.len,
            failed_checker.imported_method_scheme_by_source.count(),
        );
        for (failed_checker.imported_method_schemes.items, 0..) |candidate, candidate_index| {
            try std.testing.expectEqual(
                @as(?u32, @intCast(candidate_index)),
                failed_checker.imported_method_scheme_by_source.get(candidate.key),
            );
        }

        var failed_root_index: ?usize = null;
        for (failed_checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
            if (step.decodedKind() != .default_method) continue;
            if (failed_root_index != null) return error.TestUnexpectedResult;
            failed_root_index = step_index;
        }
        const failed_cache_index = failed_checker.imported_method_scheme_by_source.get(failed_cache_key);
        try std.testing.expectEqual(failed_root_index != null, failed_cache_index != null);
        try std.testing.expectEqual(
            copy_steps_before_failure + @intFromBool(failed_root_index != null),
            failed_checker.cir.where_marker_copy_steps.items.items.len,
        );
        if (failed_root_index) |surviving_root_index| {
            const failed_draft_index = maybe_draft_index orelse
                return error.TestUnexpectedResult;
            const surviving_root = failed_checker.cir.where_marker_copy_steps.items.items[
                surviving_root_index
            ];
            const surviving_origin = surviving_root.origin.default_method;
            try std.testing.expectEqual(failed_draft_index, surviving_origin.decision_index);
            try std.testing.expectEqual(failed_staged.plus.offset, surviving_origin.constraint_offset);
            try std.testing.expectEqual(@as(u32, 0), surviving_origin.reserved_0);
            try std.testing.expectEqual(
                @intFromEnum(failed_builtin_indices.dec_type),
                surviving_origin.builtin_decl_index,
            );
            try std.testing.expectEqual(
                @intFromEnum(failed_method_entry.binding.type_node_idx),
                surviving_origin.provider_type_node,
            );
            try std.testing.expectEqual(
                @intFromEnum(failed_method_entry.binding.def_idx),
                surviving_origin.provider_def,
            );

            const surviving_cache_index = failed_cache_index.?;
            if (surviving_cache_index >= failed_checker.imported_method_schemes.items.len or
                surviving_root.root_occurrence_offset >= surviving_root.occurrences_len or
                !rangeFits(
                    surviving_root.occurrences_start,
                    surviving_root.occurrences_len,
                    failed_checker.cir.where_marker_copy_occurrences.items.items.len,
                ) or
                !rangeFits(
                    surviving_root.pairs_start,
                    surviving_root.pairs_len,
                    failed_checker.cir.where_marker_copy_pairs.items.items.len,
                ) or
                !rangeFits(
                    surviving_root.witnesses_start,
                    surviving_root.witnesses_len,
                    failed_checker.cir.where_marker_copy_witnesses.items.items.len,
                ))
            {
                return error.TestUnexpectedResult;
            }
            failure_stage = "root-prefix";
            try std.testing.expectEqual(
                @as(usize, 1),
                failed_checker.imported_method_schemes.items.len,
            );
            const surviving_cache = failed_checker.imported_method_schemes.items[
                surviving_cache_index
            ];
            try std.testing.expect(std.meta.eql(failed_cache_key, surviving_cache.key));
            try std.testing.expectEqual(
                @as(u32, @intCast(surviving_root_index)),
                surviving_cache.copy_step,
            );
            const surviving_occurrence = failed_checker.cir.where_marker_copy_occurrences.items.items[
                surviving_root.occurrences_start + surviving_root.root_occurrence_offset
            ];
            try std.testing.expectEqual(
                @intFromEnum(surviving_cache.scheme_var),
                surviving_occurrence.raw_destination_var,
            );
            if (surviving_occurrence.canonical_pair_offset >= surviving_root.pairs_len) {
                return error.TestUnexpectedResult;
            }
            const surviving_pair = failed_checker.cir.where_marker_copy_pairs.items.items[
                surviving_root.pairs_start + surviving_occurrence.canonical_pair_offset
            ];
            try std.testing.expectEqual(surviving_root.source_root_var, surviving_pair.source_var);
            try std.testing.expectEqual(
                surviving_root.destination_root_var,
                surviving_pair.destination_var,
            );
            try std.testing.expectEqual(
                copy_pairs_before_failure,
                @as(usize, surviving_root.pairs_start),
            );
            try std.testing.expectEqual(
                copy_pairs_before_failure + @as(usize, surviving_root.pairs_len),
                failed_checker.cir.where_marker_copy_pairs.items.items.len,
            );
            try std.testing.expectEqual(
                copy_occurrences_before_failure,
                @as(usize, surviving_root.occurrences_start),
            );
            try std.testing.expectEqual(
                copy_occurrences_before_failure + @as(usize, surviving_root.occurrences_len),
                failed_checker.cir.where_marker_copy_occurrences.items.items.len,
            );
            try std.testing.expectEqual(
                copy_witnesses_before_failure,
                @as(usize, surviving_root.witnesses_start),
            );
            try std.testing.expectEqual(
                copy_witnesses_before_failure + @as(usize, surviving_root.witnesses_len),
                failed_checker.cir.where_marker_copy_witnesses.items.items.len,
            );
            const surviving_occurrences = failed_checker.cir.where_marker_copy_occurrences.items.items[surviving_root.occurrences_start..][0..surviving_root.occurrences_len];
            try std.testing.expect(surviving_occurrences.len > 0);
            var root_destination_end = types_len_before_failure;
            for (surviving_occurrences) |occurrence| {
                if (occurrence.raw_destination_var < types_len_before_failure) {
                    return error.TestUnexpectedResult;
                }
                const occurrence_end = std.math.add(
                    u32,
                    occurrence.raw_destination_var,
                    1,
                ) catch return error.TestUnexpectedResult;
                root_destination_end = @max(root_destination_end, occurrence_end);
            }
            try std.testing.expectEqual(root_destination_end, failed_checker.types.len());
            try std.testing.expectEqual(
                @as(usize, @intCast(root_destination_end)),
                failed_checker.regions.items.items.len,
            );
            saw_committed_root_without_target = true;
        } else {
            try std.testing.expectEqual(
                @as(usize, 0),
                failed_checker.imported_method_schemes.items.len,
            );
            try std.testing.expectEqual(
                copy_pairs_before_failure,
                failed_checker.cir.where_marker_copy_pairs.items.items.len,
            );
            try std.testing.expectEqual(
                copy_occurrences_before_failure,
                failed_checker.cir.where_marker_copy_occurrences.items.items.len,
            );
            try std.testing.expectEqual(
                copy_witnesses_before_failure,
                failed_checker.cir.where_marker_copy_witnesses.items.items.len,
            );
            try std.testing.expectEqual(types_len_before_failure, failed_checker.types.len());
            try std.testing.expectEqual(
                regions_before_failure,
                failed_checker.regions.items.items.len,
            );
            saw_failure_before_root = true;
        }
    }
    try std.testing.expect(saw_failure_before_root);
    try std.testing.expect(saw_committed_root_without_target);
}

fn testCountDefaultRootsForMethod(checker: *const Self, method_ident: Ident.Idx) !usize {
    var count: usize = 0;
    for (checker.cir.where_marker_copy_steps.items.items) |step| {
        if (step.decodedKind() != .default_method) continue;
        const origin = step.origin.default_method;
        if (origin.decision_index >= checker.cir.default_decisions.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const decision = checker.cir.default_decisions.items.items[origin.decision_index];
        if (origin.constraint_offset >= decision.constraints_len) return error.TestUnexpectedResult;
        const constraint = checker.types.static_dispatch_constraints.items.items[
            decision.constraints_start + origin.constraint_offset
        ];
        if (constraint.fn_name.eql(method_ident)) count += 1;
    }
    return count;
}

fn testExpectLiveBindingSchemeUse(
    checker: *const Self,
    binding: DefaultFixtureBindingDecision,
) !void {
    if (binding.scheme_use_index >= checker.cir.scheme_uses.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const use = checker.cir.scheme_uses.items.items[binding.scheme_use_index];
    try std.testing.expectEqual(@intFromEnum(binding.pattern_idx), use.scheme_root);
    const expr = checker.cir.store.getExpr(@enumFromInt(use.node_idx));
    if (expr != .e_lookup_local or expr.e_lookup_local.pattern_idx != binding.pattern_idx) {
        return error.TestUnexpectedResult;
    }
}

fn testSnapshotTypeHasIdent(
    checker: *const Self,
    initial: snapshot_mod.SnapshotContentIdx,
    expected: Ident.Idx,
) bool {
    var current = initial;
    while (true) {
        switch (checker.snapshots.getContent(current)) {
            .alias => |alias| {
                if (alias.ident.ident_idx.eql(expected)) return true;
                current = alias.backing;
            },
            .structure => |structure| return switch (structure) {
                .nominal_type => |nominal| nominal.ident.ident_idx.eql(expected),
                else => false,
            },
            .flex, .rigid, .recursive, .err => return false,
        }
    }
}

test "default method copied root authenticates its exact Builtin owner" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\run = || {
        \\    my_dec = 7.Dec
        \\    f = |x| x + my_dec
        \\    _ = (f, |x| Str.inspect(x))
        \\    {}
        \\}
    ;
    var test_env = try TestEnv.init("DefaultMethodOwner", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    const checker = &test_env.checker;
    const builtin_env = checker.builtin_ctx.builtin_module orelse
        return error.TestUnexpectedResult;
    const builtin_indices = checker.builtin_ctx.builtin_indices orelse
        return error.TestUnexpectedResult;
    const context = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    try std.testing.expect(validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);

    const binding = try testDefaultDecisionForBinding(checker, "f");
    try testExpectLiveBindingSchemeUse(checker, binding);
    const plus_constraint = try testFindUniqueDefaultConstraint(
        checker,
        binding.decision_index,
        checker.cir.idents.plus,
        2,
    );
    const plus_root = try testFindUniqueDefaultRoot(checker, checker.cir.idents.plus, 2);
    try std.testing.expectEqual(binding.decision_index, plus_root.decision_index);
    try std.testing.expectEqual(plus_constraint.offset, plus_root.constraint.offset);

    // Replacing the receiver-owner statement with the method type node would
    // satisfy the old cross-domain equality check. It must fail the exact
    // MethodKey(owner, method) -> MethodBinding(type-node, def) replay.
    const default_step_index = plus_root.step_index;
    const default_step = &checker.cir.where_marker_copy_steps.items.items[default_step_index];
    const default_origin = default_step.origin.default_method;
    try std.testing.expectEqual(@as(u32, 0), default_origin.reserved_0);
    try std.testing.expect(default_origin.builtin_decl_index != default_origin.provider_type_node);
    try std.testing.expectEqual(
        ModuleEnv.DefaultDecision.Target.dec,
        checker.cir.default_decisions.items.items[binding.decision_index].decodedTarget().?,
    );
    const authority = whereMarkerCrossRootAuthority(
        checker.cir,
        builtin_env,
        context,
        checker.cir.where_marker_copy_steps.items.items,
        default_step_index,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@intFromPtr(builtin_env), @intFromPtr(authority.provider));
    try std.testing.expectEqual(default_origin.provider_type_node, authority.raw_source_root);
    const plus_use_step = try testFindDefaultMethodUse(
        checker,
        default_step_index,
        binding.decision_index,
        plus_constraint,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), testCountDefaultMethodUses(checker, default_step_index));
    try testExpectSoleDefaultDispatchTarget(
        checker,
        builtin_env,
        plus_use_step,
        plus_constraint,
    );

    const original_reserved = default_step.origin.default_method.reserved_0;
    default_step.origin.default_method.reserved_0 = 1;
    const noncanonical_root_result = validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        builtin_env,
        context,
    );
    default_step.origin.default_method.reserved_0 = original_reserved;
    try std.testing.expectError(error.CorruptArtifact, noncanonical_root_result);

    const original_builtin_decl_index = default_step.origin.default_method.builtin_decl_index;
    default_step.origin.default_method.builtin_decl_index =
        default_step.origin.default_method.provider_type_node;
    const wrong_owner_result = validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        builtin_env,
        context,
    );
    default_step.origin.default_method.builtin_decl_index = original_builtin_decl_index;
    try std.testing.expectError(error.CorruptArtifact, wrong_owner_result);
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);

    const decision_index = default_step.origin.default_method.decision_index;
    const decision = &checker.cir.default_decisions.items.items[decision_index];
    const original_target = decision.target;
    decision.target = @intFromEnum(switch (decision.decodedTarget() orelse
        return error.TestUnexpectedResult) {
        .dec => ModuleEnv.DefaultDecision.Target.str,
        .str => ModuleEnv.DefaultDecision.Target.dec,
    });
    try std.testing.expect(!validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));
    decision.target = original_target;
    try std.testing.expect(validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));

    const selected_constraint = &checker.types.static_dispatch_constraints.items.items[plus_constraint.index];
    const original_fn_name = selected_constraint.fn_name;
    selected_constraint.fn_name = @bitCast(@as(u32, std.math.maxInt(u32)));
    try std.testing.expect(!validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));
    const invalid_ident_result = validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        builtin_env,
        context,
    );
    selected_constraint.fn_name = original_fn_name;
    try std.testing.expectError(error.CorruptArtifact, invalid_ident_result);
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);

    // Repeated canonical publication must use only the durable decision,
    // owner-key, and binding value after every transient method cache is gone.
    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_before);
    checker.imported_method_schemes.clearRetainingCapacity();
    checker.imported_method_scheme_by_source.clearRetainingCapacity();
    _ = checker.checkedBoundaryCrossStepProvider(
        checker.cir.where_marker_copy_steps.items.items,
        @intCast(default_step_index),
    );
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const serialized_after = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_after);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after);
    try std.testing.expect(validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);
}

test "rejected first default target reuses its exact cached root on a later accepted copy" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\run = || {
        \\    my_dec = 7.Dec
        \\    bad = |x| (-x, x.plus())
        \\    good = |x| (-x, x.plus(my_dec))
        \\    _ = (bad, good, |x| Str.inspect(x))
        \\    {}
        \\}
    ;
    var test_env = try TestEnv.init("RejectedFirstDefaultMethod", source);
    defer test_env.deinit();
    try test_env.assertOneTypeError("Type Mismatch");
    try test_env.assertCanErrors(&.{});
    try std.testing.expectEqual(@as(usize, 1), test_env.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 1), try test_env.typeProblemCount());

    const checker = &test_env.checker;
    const builtin_env = checker.builtin_ctx.builtin_module orelse
        return error.TestUnexpectedResult;
    const builtin_indices = checker.builtin_ctx.builtin_indices orelse
        return error.TestUnexpectedResult;
    const context = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    try std.testing.expect(validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);

    const bad_binding = try testDefaultDecisionForBinding(checker, "bad");
    const good_binding = try testDefaultDecisionForBinding(checker, "good");
    try std.testing.expect(bad_binding.pattern_idx != good_binding.pattern_idx);
    try std.testing.expect(bad_binding.scheme_use_index != good_binding.scheme_use_index);
    try std.testing.expect(bad_binding.driver_copy_step != good_binding.driver_copy_step);
    try std.testing.expect(bad_binding.decision_index != good_binding.decision_index);

    const bad_plus = try testFindUniqueDefaultConstraint(
        checker,
        bad_binding.decision_index,
        checker.cir.idents.plus,
        1,
    );
    const good_plus = try testFindUniqueDefaultConstraint(
        checker,
        good_binding.decision_index,
        checker.cir.idents.plus,
        2,
    );
    try std.testing.expect(bad_plus.fn_var != good_plus.fn_var);
    const plus_root = try testFindUniqueDefaultRoot(checker, checker.cir.idents.plus, 1);
    try std.testing.expectEqual(@as(usize, 1), try testCountDefaultRootsForMethod(
        checker,
        checker.cir.idents.plus,
    ));
    try std.testing.expectEqual(bad_binding.decision_index, plus_root.decision_index);
    try std.testing.expectEqual(bad_plus.offset, plus_root.constraint.offset);

    const root_step = checker.cir.where_marker_copy_steps.items.items[plus_root.step_index];
    try std.testing.expectEqual(
        @intFromEnum(builtin_indices.dec_type),
        root_step.origin.default_method.builtin_decl_index,
    );
    try std.testing.expectEqual(
        ModuleEnv.DefaultDecision.Target.dec,
        checker.cir.default_decisions.items.items[bad_binding.decision_index].decodedTarget().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.DefaultDecision.Target.dec,
        checker.cir.default_decisions.items.items[good_binding.decision_index].decodedTarget().?,
    );
    try std.testing.expect(try testFindDefaultMethodUse(
        checker,
        plus_root.step_index,
        bad_binding.decision_index,
        bad_plus,
    ) == null);
    const good_use_step = try testFindDefaultMethodUse(
        checker,
        plus_root.step_index,
        good_binding.decision_index,
        good_plus,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), testCountDefaultMethodUses(
        checker,
        plus_root.step_index,
    ));
    try testExpectNoDispatchTargetForRawFn(checker, bad_plus.fn_var);
    try testExpectSoleDefaultDispatchTarget(
        checker,
        builtin_env,
        good_use_step,
        good_plus,
    );

    const mismatch = switch (checker.problems.problems.items[0]) {
        .type_mismatch => |mismatch| if (mismatch.context == .method_type)
            mismatch
        else
            return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(mismatch.context.method_type.method_name.eql(checker.cir.idents.plus));
    const expected_fn = switch (checker.snapshots.getContentUnwrapAlias(mismatch.types.expected_snapshot)) {
        .structure => |structure| switch (structure) {
            .fn_pure, .fn_effectful, .fn_unbound => |fn_| fn_,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    const rejected_fn = switch (checker.snapshots.getContentUnwrapAlias(mismatch.types.actual_snapshot)) {
        .structure => |structure| switch (structure) {
            .fn_pure, .fn_effectful, .fn_unbound => |fn_| fn_,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 2), checker.snapshots.sliceVars(expected_fn.args).len);
    try std.testing.expectEqual(@as(usize, 1), checker.snapshots.sliceVars(rejected_fn.args).len);

    // The failed use expression may already be a runtime error. Its durable
    // contributor remains tied to the raw `bad` binding scheme above, rather
    // than being rediscovered from this mutable expression shape.
    const bad_use = checker.cir.scheme_uses.items.items[bad_binding.scheme_use_index];
    try std.testing.expectEqual(@intFromEnum(bad_binding.pattern_idx), bad_use.scheme_root);
    try testExpectLiveBindingSchemeUse(checker, good_binding);

    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_before);
    checker.imported_method_schemes.clearRetainingCapacity();
    checker.imported_method_scheme_by_source.clearRetainingCapacity();
    _ = checker.checkedBoundaryCrossStepProvider(
        checker.cir.where_marker_copy_steps.items.items,
        @intCast(plus_root.step_index),
    );
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const serialized_after = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_after);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after);
    try std.testing.expect(validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);
}

test "default target signature rejection rolls back its child and raw-edge publication" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\run = || {
        \\    my_dec = 7.Dec
        \\    my_str : Str
        \\    my_str = "bad"
        \\    bad = |x| (-x, x.plus(my_str))
        \\    good = |x| (-x, x.plus(my_dec))
        \\    _ = (bad, good, |x| Str.inspect(x))
        \\    {}
        \\}
    ;
    var test_env = try TestEnv.init("DefaultMethodSignatureRollback", source);
    defer test_env.deinit();
    try test_env.assertOneTypeError("Type Mismatch");
    try test_env.assertCanErrors(&.{});
    try std.testing.expectEqual(@as(usize, 1), test_env.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 1), try test_env.typeProblemCount());
    const checker = &test_env.checker;
    const builtin_env = checker.builtin_ctx.builtin_module orelse
        return error.TestUnexpectedResult;

    const bad_binding = try testDefaultDecisionForBinding(checker, "bad");
    const good_binding = try testDefaultDecisionForBinding(checker, "good");
    try std.testing.expect(bad_binding.pattern_idx != good_binding.pattern_idx);
    try std.testing.expect(bad_binding.scheme_use_index != good_binding.scheme_use_index);
    try std.testing.expect(bad_binding.driver_copy_step != good_binding.driver_copy_step);
    try std.testing.expect(bad_binding.decision_index != good_binding.decision_index);
    const bad_plus = try testFindUniqueDefaultConstraint(
        checker,
        bad_binding.decision_index,
        checker.cir.idents.plus,
        2,
    );
    const good_plus = try testFindUniqueDefaultConstraint(
        checker,
        good_binding.decision_index,
        checker.cir.idents.plus,
        2,
    );
    try std.testing.expect(bad_plus.fn_var != good_plus.fn_var);

    const plus_root = try testFindUniqueDefaultRoot(checker, checker.cir.idents.plus, 2);
    try std.testing.expectEqual(@as(usize, 1), try testCountDefaultRootsForMethod(
        checker,
        checker.cir.idents.plus,
    ));
    try std.testing.expectEqual(bad_binding.decision_index, plus_root.decision_index);
    try std.testing.expectEqual(bad_plus.offset, plus_root.constraint.offset);
    try std.testing.expect(try testFindDefaultMethodUse(
        checker,
        plus_root.step_index,
        bad_binding.decision_index,
        bad_plus,
    ) == null);
    const good_use_step = try testFindDefaultMethodUse(
        checker,
        plus_root.step_index,
        good_binding.decision_index,
        good_plus,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), testCountDefaultMethodUses(
        checker,
        plus_root.step_index,
    ));
    try testExpectNoDispatchTargetForRawFn(checker, bad_plus.fn_var);
    try testExpectSoleDefaultDispatchTarget(
        checker,
        builtin_env,
        good_use_step,
        good_plus,
    );

    // Canonical constraint order visits plus before unary negation. Rolling
    // plus back must leave the decision able to continue and commit its exact
    // later negate child instead of abandoning or corrupting the suffix.
    const bad_negate = try testFindUniqueDefaultConstraint(
        checker,
        bad_binding.decision_index,
        checker.cir.idents.negate,
        1,
    );
    try std.testing.expect(bad_plus.offset < bad_negate.offset);
    const negate_root = try testFindUniqueDefaultRoot(checker, checker.cir.idents.negate, 1);
    const bad_negate_use_step = try testFindDefaultMethodUse(
        checker,
        negate_root.step_index,
        bad_binding.decision_index,
        bad_negate,
    ) orelse return error.TestUnexpectedResult;
    try testExpectSoleDefaultDispatchTarget(
        checker,
        builtin_env,
        bad_negate_use_step,
        bad_negate,
    );

    const mismatch = switch (checker.problems.problems.items[0]) {
        .type_mismatch => |mismatch| if (mismatch.context == .method_type)
            mismatch
        else
            return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(mismatch.context.method_type.method_name.eql(checker.cir.idents.plus));
    try std.testing.expectEqual(bad_plus.fn_var, mismatch.types.actual_var);
    const expected_fn = switch (checker.snapshots.getContentUnwrapAlias(mismatch.types.expected_snapshot)) {
        .structure => |structure| switch (structure) {
            .fn_pure, .fn_effectful, .fn_unbound => |fn_| fn_,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    const rejected_fn = switch (checker.snapshots.getContentUnwrapAlias(mismatch.types.actual_snapshot)) {
        .structure => |structure| switch (structure) {
            .fn_pure, .fn_effectful, .fn_unbound => |fn_| fn_,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    const expected_args = checker.snapshots.sliceVars(expected_fn.args);
    const rejected_args = checker.snapshots.sliceVars(rejected_fn.args);
    try std.testing.expectEqual(@as(usize, 2), expected_args.len);
    try std.testing.expectEqual(@as(usize, 2), rejected_args.len);
    try std.testing.expect(testSnapshotTypeHasIdent(
        checker,
        expected_args[1],
        checker.cir.idents.dec_type,
    ));
    // Imported nominal snapshots retain their fully qualified Builtin identity
    // even though diagnostics render this one as the surface name `Str`.
    try std.testing.expect(testSnapshotTypeHasIdent(
        checker,
        rejected_args[1],
        checker.cir.idents.builtin_str,
    ));

    var rejection_count: usize = 0;
    for (checker.cir.rejected_static_dispatches.items.items) |rejection| {
        rejection_count += @intFromBool(rejection.fnVar() == bad_plus.fn_var);
    }
    try std.testing.expectEqual(@as(usize, 1), rejection_count);
    const bad_use = checker.cir.scheme_uses.items.items[bad_binding.scheme_use_index];
    try std.testing.expectEqual(@intFromEnum(bad_binding.pattern_idx), bad_use.scheme_root);
    try testExpectLiveBindingSchemeUse(checker, good_binding);
}

test "one default decision retains same-binding plus constraints at distinct offsets" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\run = || {
        \\    my_dec = 7.Dec
        \\    f = |x| (-x, x.plus(my_dec), x.plus(my_dec))
        \\    _ = (f, |x| Str.inspect(x))
        \\    {}
        \\}
    ;
    var test_env = try TestEnv.init("SiblingDefaultMethodOffsets", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    const checker = &test_env.checker;
    const builtin_env = checker.builtin_ctx.builtin_module orelse
        return error.TestUnexpectedResult;
    const builtin_indices = checker.builtin_ctx.builtin_indices orelse
        return error.TestUnexpectedResult;
    const context = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    try std.testing.expect(validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);

    const binding = try testDefaultDecisionForBinding(checker, "f");
    try testExpectLiveBindingSchemeUse(checker, binding);
    const decision = checker.cir.default_decisions.items.items[binding.decision_index];
    try std.testing.expectEqual(ModuleEnv.DefaultDecision.Target.dec, decision.decodedTarget().?);
    var plus_constraints: [2]DefaultFixtureConstraint = undefined;
    var plus_count: usize = 0;
    var offset: u32 = 0;
    while (offset < decision.constraints_len) : (offset += 1) {
        const constraint_index = decision.constraints_start + offset;
        const constraint = checker.types.static_dispatch_constraints.items.items[constraint_index];
        if (!constraint.fn_name.eql(checker.cir.idents.plus) or
            (checker.callableArity(constraint.fn_var) orelse continue) != 2)
        {
            continue;
        }
        if (plus_count >= plus_constraints.len) return error.TestUnexpectedResult;
        plus_constraints[plus_count] = .{
            .index = constraint_index,
            .offset = offset,
            .fn_var = constraint.fn_var,
        };
        plus_count += 1;
    }
    try std.testing.expectEqual(plus_constraints.len, plus_count);
    try std.testing.expect(plus_constraints[0].offset != plus_constraints[1].offset);
    try std.testing.expect(plus_constraints[0].fn_var != plus_constraints[1].fn_var);
    const first_intro = constraintIntroExpr(
        checker.types.static_dispatch_constraints.items.items[plus_constraints[0].index],
    ) orelse return error.TestUnexpectedResult;
    const second_intro = constraintIntroExpr(
        checker.types.static_dispatch_constraints.items.items[plus_constraints[1].index],
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(first_intro != second_intro);

    const plus_root = try testFindUniqueDefaultRoot(checker, checker.cir.idents.plus, 2);
    try std.testing.expectEqual(@as(usize, 1), try testCountDefaultRootsForMethod(
        checker,
        checker.cir.idents.plus,
    ));
    try std.testing.expectEqual(binding.decision_index, plus_root.decision_index);
    try std.testing.expect(
        plus_root.constraint.offset == plus_constraints[0].offset or
            plus_root.constraint.offset == plus_constraints[1].offset,
    );
    const first_use_step = try testFindDefaultMethodUse(
        checker,
        plus_root.step_index,
        binding.decision_index,
        plus_constraints[0],
    ) orelse return error.TestUnexpectedResult;
    const second_use_step = try testFindDefaultMethodUse(
        checker,
        plus_root.step_index,
        binding.decision_index,
        plus_constraints[1],
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(first_use_step != second_use_step);
    try std.testing.expectEqual(@as(usize, 2), testCountDefaultMethodUses(
        checker,
        plus_root.step_index,
    ));
    try testExpectSoleDefaultDispatchTarget(
        checker,
        builtin_env,
        first_use_step,
        plus_constraints[0],
    );
    try testExpectSoleDefaultDispatchTarget(
        checker,
        builtin_env,
        second_use_step,
        plus_constraints[1],
    );

    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_before);
    checker.imported_method_schemes.clearRetainingCapacity();
    checker.imported_method_scheme_by_source.clearRetainingCapacity();
    _ = checker.checkedBoundaryCrossStepProvider(
        checker.cir.where_marker_copy_steps.items.items,
        @intCast(plus_root.step_index),
    );
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const serialized_after = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_after);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after);
    try std.testing.expect(validateDefaultDecisionTargetContext(
        checker.types,
        checker.cir,
        builtin_indices,
    ));
    try validateWhereMarkerCopySourceNamespaces(checker.cir, builtin_env, context);
}

test "default target keeps its non-null selected parent through ordinary re-drive" {
    const TestEnv = @import("test/TestEnv.zig");
    // Selecting inferred `make` copies the returned closure's non-literal
    // arithmetic requirement while `make` is the active evidence target. The
    // direct discard reaches specialization without a binding re-copy, so the
    // resulting Dec.plus default edge must retain that selected parent.
    const source =
        \\Parent := [Value].{
        \\    make = |_| {
        \\        my_dec = 7.Dec
        \\        |x| x + my_dec
        \\    }
        \\}
        \\run = || {
        \\    _ = ((Parent.Value).make(), |x| Str.inspect(x))
        \\    {}
        \\}
    ;
    var test_env = try TestEnv.init("DefaultMethodParentLineage", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    const checker = &test_env.checker;
    const builtin_env = checker.builtin_ctx.builtin_module orelse
        return error.TestUnexpectedResult;

    const plus_root = try testFindUniqueDefaultRoot(checker, checker.cir.idents.plus, 2);
    try std.testing.expectEqual(@as(usize, 1), try testCountDefaultRootsForMethod(
        checker,
        checker.cir.idents.plus,
    ));
    const plus_use_step = try testFindDefaultMethodUse(
        checker,
        plus_root.step_index,
        plus_root.decision_index,
        plus_root.constraint,
    ) orelse return error.TestUnexpectedResult;
    try testExpectSoleDefaultDispatchTarget(
        checker,
        builtin_env,
        plus_use_step,
        plus_root.constraint,
    );

    const child_target_index = checker.dispatch_target_instantiation_by_fn_var.get(
        plus_root.constraint.fn_var,
    ) orelse return error.TestUnexpectedResult;
    const child_target = checker.dispatch_target_instantiations.items[child_target_index];
    const parent_fn_var = child_target.parent_constraint_fn_var orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        parent_fn_var,
        checker.dispatch_derivation_by_child_fn_var.get(plus_root.constraint.fn_var) orelse
            return error.TestUnexpectedResult,
    );
    try std.testing.expect(parent_fn_var != plus_root.constraint.fn_var);

    const parent_target_index = checker.dispatch_target_instantiation_by_fn_var.get(parent_fn_var) orelse
        return error.TestUnexpectedResult;
    const parent_target = checker.dispatch_target_instantiations.items[parent_target_index];
    const make_ident = checker.cir.getIdentStoreConst().lookup(base.Ident.for_text("make")) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(parent_fn_var, parent_target.constraint_fn_var);
    try std.testing.expect(parent_target.method_name.eql(make_ident));
    try std.testing.expectEqual(@intFromPtr(checker.cir), @intFromPtr(parent_target.target_env));
    try std.testing.expect(
        checker.settled_static_dispatch_constraint_fns.contains(parent_fn_var),
    );
}

test "selected target remains the exact authority for shared cache lookup" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\run = || {
        \\    my_dec = 7.Dec
        \\    _ = (5.Dec).plus(my_dec)
        \\    {}
        \\}
    ;
    var test_env = try TestEnv.init("SelectedThenDefaultTargetReuse", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    const checker = &test_env.checker;
    const builtin_env = checker.builtin_ctx.builtin_module orelse
        return error.TestUnexpectedResult;
    const builtin_indices = checker.builtin_ctx.builtin_indices orelse
        return error.TestUnexpectedResult;

    var selected_constraint_index: ?u32 = null;
    for (checker.cir.selected_method_decisions.items.items) |decision| {
        if (decision.decodedState() != .complete or
            decision.constraint_index >= checker.types.static_dispatch_constraints.items.items.len or
            decision.scheme_use_index >= checker.cir.scheme_uses.items.items.len)
        {
            continue;
        }
        const constraint = checker.types.static_dispatch_constraints.items.items[
            decision.constraint_index
        ];
        if (!constraint.fn_name.eql(checker.cir.idents.plus) or
            (checker.callableArity(constraint.fn_var) orelse continue) != 2)
        {
            continue;
        }
        const use = checker.cir.scheme_uses.items.items[decision.scheme_use_index];
        if (use.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target) or
            use.slot_data != @intFromEnum(constraint.fn_var))
        {
            return error.TestUnexpectedResult;
        }
        if (selected_constraint_index != null) return error.TestUnexpectedResult;
        selected_constraint_index = decision.constraint_index;
    }
    const exact_constraint_index = selected_constraint_index orelse
        return error.TestUnexpectedResult;
    const selected_constraint = checker.types.static_dispatch_constraints.items.items[
        exact_constraint_index
    ];
    const selected_target_index = checker.dispatch_target_instantiation_by_fn_var.get(
        selected_constraint.fn_var,
    ) orelse return error.TestUnexpectedResult;
    if (selected_target_index >= checker.dispatch_target_instantiations.items.len) {
        return error.TestUnexpectedResult;
    }
    const selected_target = checker.dispatch_target_instantiations.items[selected_target_index];
    const expected_binding = builtin_env.lookupMethodBindingFromTwoEnvsAndDeclConst(
        @intFromEnum(builtin_indices.dec_type),
        checker.cir,
        checker.cir.idents.plus,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@intFromPtr(builtin_env), @intFromPtr(selected_target.target_env));
    try std.testing.expect(std.meta.eql(expected_binding, selected_target.target_binding));
    try std.testing.expectEqual(@as(?Var, null), selected_target.parent_constraint_fn_var);
    try std.testing.expectEqual(
        @as(?u32, selected_target_index),
        checker.dispatch_target_instantiation_by_fn_var.get(selected_target.constraint_fn_var),
    );
    try std.testing.expectEqual(@as(usize, 0), try testCountDefaultRootsForMethod(
        checker,
        checker.cir.idents.plus,
    ));
    try std.testing.expectEqual(selected_constraint.fn_var, selected_target.constraint_fn_var);
    try std.testing.expect(selected_constraint.fn_name.eql(checker.cir.idents.plus));

    var selected_decision_count: usize = 0;
    for (checker.cir.selected_method_decisions.items.items) |decision| {
        if (decision.decodedState() != .complete or
            decision.constraint_index != exact_constraint_index)
        {
            continue;
        }
        if (decision.scheme_use_index >= checker.cir.scheme_uses.items.items.len) {
            return error.TestUnexpectedResult;
        }
        const use = checker.cir.scheme_uses.items.items[decision.scheme_use_index];
        try std.testing.expectEqual(
            ModuleEnv.SchemeUseRecord.Slot.dispatch_target,
            std.enums.fromInt(ModuleEnv.SchemeUseRecord.Slot, use.slot_kind).?,
        );
        try std.testing.expectEqual(@intFromEnum(selected_target.constraint_fn_var), use.slot_data);
        try std.testing.expectEqual(
            @intFromEnum(selected_target.target_binding.type_node_idx),
            decision.provider_type_node,
        );
        try std.testing.expectEqual(
            @intFromEnum(selected_target.target_binding.def_idx),
            decision.provider_def,
        );
        selected_decision_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), selected_decision_count);

    const targets_len = checker.dispatch_target_instantiations.items.len;
    const target_map_count = checker.dispatch_target_instantiation_by_fn_var.count();
    const uses_len = checker.cir.scheme_uses.items.items.len;
    const decisions_len = checker.cir.selected_method_decisions.items.items.len;
    const copy_steps_len = checker.cir.where_marker_copy_steps.items.items.len;
    // Both ordinary selection and default compatibility use this exact cache
    // lookup. This exercises reuse of an authentic selected row; it is not a
    // second default-compatibility pass.
    const reused_index = checker.cachedDispatchTargetInstantiationIndex(
        selected_constraint,
        selected_target.parent_constraint_fn_var,
        .{
            .env = selected_target.target_env,
            .is_this_module = selected_target.target_env == checker.cir,
            .binding = selected_target.target_binding,
            .provider_method_entry_index = selected_target.provider_method_entry_index,
        },
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(selected_target_index, reused_index);
    try std.testing.expectEqual(
        selected_target.method_var,
        checker.dispatch_target_instantiations.items[reused_index].method_var,
    );
    try std.testing.expectEqual(targets_len, checker.dispatch_target_instantiations.items.len);
    try std.testing.expectEqual(target_map_count, checker.dispatch_target_instantiation_by_fn_var.count());
    try std.testing.expectEqual(uses_len, checker.cir.scheme_uses.items.items.len);
    try std.testing.expectEqual(decisions_len, checker.cir.selected_method_decisions.items.items.len);
    try std.testing.expectEqual(copy_steps_len, checker.cir.where_marker_copy_steps.items.items.len);
}

test "outer-arity rejected dispatch retains immutable receiver authority after CIR retirement" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\run = || {
        \\    bad = || (5).plus()
        \\    good = |x| (5).plus(x)
        \\    _ = (bad, good, {})
        \\    {}
        \\}
    ;
    var test_env = try TestEnv.init("RejectedDefaultMethodArity", source);
    defer test_env.deinit();
    const checker = &test_env.checker;

    // The rejected call is retired to a runtime error after its outer-arity
    // diagnostic. Its producer-authored dispatch source and moved receiver
    // anchor remain the authority for its previously committed selected
    // decision after the subsequent callable unification is rejected.
    const plus_ident: u32 = @bitCast(checker.cir.idents.plus);
    var retired_plus_source_index: ?usize = null;
    var retired_plus_anchor_index: ?u32 = null;
    var live_plus_source_index: ?usize = null;
    var live_plus_anchor_index: ?u32 = null;
    for (checker.cir.dispatch_settlement_sources.items.items, 0..) |settlement_source, source_index| {
        if (settlement_source.decodedKind() != .dispatch_expr or
            settlement_source.payload.dispatch_expr.method_ident != plus_ident)
        {
            continue;
        }
        const dispatch_source = settlement_source.payload.dispatch_expr;
        try std.testing.expectEqual(
            ModuleEnv.DispatchSettlementSource.OriginalNodeKind.dispatch_call,
            settlement_source.decodedOriginalNodeKind().?,
        );
        switch (checker.cir.store.getExpr(@enumFromInt(dispatch_source.node_index))) {
            .e_runtime_error => {
                if (retired_plus_source_index != null) return error.TestUnexpectedResult;
                retired_plus_source_index = source_index;
                retired_plus_anchor_index = dispatch_source.anchor_index;
            },
            .e_dispatch_call => {
                if (live_plus_source_index != null) return error.TestUnexpectedResult;
                live_plus_source_index = source_index;
                live_plus_anchor_index = dispatch_source.anchor_index;
            },
            else => return error.TestUnexpectedResult,
        }
    }
    const retired_source_index = retired_plus_source_index orelse return error.TestUnexpectedResult;
    const retired_anchor_index = retired_plus_anchor_index orelse return error.TestUnexpectedResult;
    const live_source_index = live_plus_source_index orelse return error.TestUnexpectedResult;
    const live_anchor_index = live_plus_anchor_index orelse return error.TestUnexpectedResult;
    try std.testing.expect(retired_source_index != live_source_index);
    try std.testing.expect(retired_anchor_index != live_anchor_index);
    try std.testing.expect(validateDispatchSettlementSourceContext(
        checker.cir,
        retired_source_index,
    ));
    try std.testing.expect(validateDispatchSettlementSourceContext(
        checker.cir,
        live_source_index,
    ));

    var retired_terminal_receiver: ?u32 = null;
    var live_terminal_receiver: ?u32 = null;
    for (checker.cir.selected_method_decisions.items.items) |decision| {
        const constraint = checker.types.static_dispatch_constraints.items.items[decision.constraint_index];
        for (checker.types.sliceConstraintEvidenceHandles(constraint.constraint_evidence)) |handle| {
            if (handle.decodedKind() != .selected_receiver_anchor) continue;
            if (handle.index == retired_anchor_index) {
                if (retired_terminal_receiver != null) return error.TestUnexpectedResult;
                retired_terminal_receiver = decision.receiver_var;
            } else if (handle.index == live_anchor_index) {
                if (live_terminal_receiver != null) return error.TestUnexpectedResult;
                live_terminal_receiver = decision.receiver_var;
            }
        }
    }
    try std.testing.expect(validateSelectedReceiverAnchorContext(
        checker.cir,
        retired_anchor_index,
        retired_terminal_receiver orelse return error.TestUnexpectedResult,
    ));
    try std.testing.expect(validateSelectedReceiverAnchorContext(
        checker.cir,
        live_anchor_index,
        live_terminal_receiver orelse return error.TestUnexpectedResult,
    ));

    const context = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        test_env.builtin_module.env,
        context,
    );

    var mismatch_count: usize = 0;
    var literal_defaulted_count: usize = 0;
    for (checker.problems.problems.items) |problem_| switch (problem_) {
        .type_mismatch => |mismatch| {
            mismatch_count += 1;
            if (mismatch.context != .method_type) return error.TestUnexpectedResult;
            try std.testing.expect(mismatch.context.method_type.method_name.eql(checker.cir.idents.plus));

            const method_fn = switch (checker.snapshots.getContentUnwrapAlias(mismatch.types.expected_snapshot)) {
                .structure => |structure| switch (structure) {
                    .fn_pure, .fn_effectful, .fn_unbound => |fn_| fn_,
                    else => return error.TestUnexpectedResult,
                },
                else => return error.TestUnexpectedResult,
            };
            const rejected_call_fn = switch (checker.snapshots.getContentUnwrapAlias(mismatch.types.actual_snapshot)) {
                .structure => |structure| switch (structure) {
                    .fn_pure, .fn_effectful, .fn_unbound => |fn_| fn_,
                    else => return error.TestUnexpectedResult,
                },
                else => return error.TestUnexpectedResult,
            };
            try std.testing.expectEqual(@as(usize, 2), checker.snapshots.sliceVars(method_fn.args).len);
            try std.testing.expectEqual(@as(usize, 1), checker.snapshots.sliceVars(rejected_call_fn.args).len);
        },
        .literal_defaulted => literal_defaulted_count += 1,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), mismatch_count);
    try std.testing.expectEqual(@as(usize, 2), literal_defaulted_count);
    try std.testing.expectEqual(@as(usize, 1), try test_env.typeProblemCount());

    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_before);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    const serialized_after = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(serialized_after);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after);
    try validateWhereMarkerCopySourceNamespaces(
        checker.cir,
        test_env.builtin_module.env,
        context,
    );
}

const direct_binder_call_pair_provider_source =
    \\a.Status : where [a.status : a -> [Off, On]]
;

const direct_binder_call_pair_consumer_source =
    \\import DirectBinderCallPairA exposing [Status]
    \\
    \\first : a -> a where [a.Status]
    \\first = |value| (|left, _right| left)(value, value)
;

const invalidation_retry_provider_source =
    \\a.Status : where [a.status : a -> [Off, On]]
;

const invalidation_retry_consumer_source =
    \\import InvalidationRetryA exposing [Status]
    \\
    \\Cfg := { value : U8 ?? 7 }
    \\
    \\first : a, U64 -> {} where [a.Status]
    \\first = |value, open| {
    \\    _ = ([Cfg.{}, Cfg.{ value: 3 }], open)
    \\    _ = (|left, _middle, _right| left)(
    \\        value,
    \\        (Cfg.{}, Cfg.{ value: 5 }, Cfg.{}),
    \\        value,
    \\    )
    \\    _ = ([Cfg.{}, Cfg.{ value: 9 }], open)
    \\    {}
    \\}
;

const InvalidationRetryTestTopology = struct {
    outer_lambda: CIR.Expr.Idx,
    outer_body: CIR.Expr.Idx,
    outer_final: CIR.Expr.Idx,
    outer_pattern: CIR.Pattern.Idx,
    call_expr: CIR.Expr.Idx,
    call_callee: CIR.Expr.Idx,
    call_callee_body: CIR.Expr.Idx,
    call_retirement_index: u32,
    call_plan_start: u32,
    call_argument_sites: [3]CIR.Expr.Idx,
    call_failure_indices: [2]u32,
    source_retirement_index: u32,
    source_retired_expr: CIR.Expr.Idx,
    before_wrapper: CIR.Expr.Idx,
    before_open: CIR.Expr.Idx,
    before_list: CIR.Expr.Idx,
    before_nominals: [2]CIR.Expr.Idx,
    before_backings: [2]CIR.Expr.Idx,
    before_numeral: CIR.Expr.Idx,
    middle_tuple: CIR.Expr.Idx,
    middle_nominals: [3]CIR.Expr.Idx,
    middle_backings: [3]CIR.Expr.Idx,
    middle_numeral: CIR.Expr.Idx,
    after_wrapper: CIR.Expr.Idx,
    after_open: CIR.Expr.Idx,
    after_list: CIR.Expr.Idx,
    after_nominals: [2]CIR.Expr.Idx,
    after_backings: [2]CIR.Expr.Idx,
    after_numeral: CIR.Expr.Idx,
    default_numeral: CIR.Expr.Idx,
};

fn expectInvalidationRetryPatternName(
    checker: *const Self,
    pattern_idx: CIR.Pattern.Idx,
    expected_name: []const u8,
) !void {
    const ident = checker.getPatternIdent(pattern_idx) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(expected_name, checker.cir.getIdent(ident));
}

fn invalidationRetryNominalBacking(
    cir: *const ModuleEnv,
    nominal_expr: CIR.Expr.Idx,
) !CIR.Expr.Idx {
    const nominal = cir.store.getExpr(nominal_expr);
    const backing = switch (nominal) {
        .e_nominal => |value| value.backing_expr,
        else => return error.TestUnexpectedResult,
    };
    switch (cir.store.getExpr(backing)) {
        .e_record, .e_empty_record => {},
        else => return error.TestUnexpectedResult,
    }
    return backing;
}

fn expectInvalidationRetryEmptyBacking(
    cir: *const ModuleEnv,
    nominal_expr: CIR.Expr.Idx,
) !CIR.Expr.Idx {
    const backing = try invalidationRetryNominalBacking(cir, nominal_expr);
    try std.testing.expect(cir.store.getExpr(backing) == .e_empty_record);
    return backing;
}

fn expectInvalidationRetryExplicitBacking(
    cir: *const ModuleEnv,
    nominal_expr: CIR.Expr.Idx,
    expected_value: i128,
) !struct { backing: CIR.Expr.Idx, numeral: CIR.Expr.Idx } {
    const backing = try invalidationRetryNominalBacking(cir, nominal_expr);
    const record = switch (cir.store.getExpr(backing)) {
        .e_record => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(record.ext == null);
    try std.testing.expectEqual(@as(usize, 0), cir.store.sliceUnsetFields(record.unsets).len);
    const fields = cir.store.sliceRecordFields(record.fields);
    try std.testing.expectEqual(@as(usize, 1), fields.len);
    const field = cir.store.getRecordField(fields[0]);
    try std.testing.expectEqualStrings("value", cir.getIdent(field.name));
    const numeral = switch (cir.store.getExpr(field.value)) {
        .e_num => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(expected_value, numeral.value.toI128());
    return .{ .backing = backing, .numeral = field.value };
}

fn expectInvalidationRetryList(
    cir: *const ModuleEnv,
    list_expr: CIR.Expr.Idx,
    expected_value: i128,
) !struct { nominals: [2]CIR.Expr.Idx, backings: [2]CIR.Expr.Idx, numeral: CIR.Expr.Idx } {
    const list = switch (cir.store.getExpr(list_expr)) {
        .e_list => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const elems = cir.store.sliceExpr(list.elems);
    try std.testing.expectEqual(@as(usize, 2), elems.len);
    const explicit = try expectInvalidationRetryExplicitBacking(cir, elems[1], expected_value);
    return .{
        .nominals = .{ elems[0], elems[1] },
        .backings = .{
            try expectInvalidationRetryEmptyBacking(cir, elems[0]),
            explicit.backing,
        },
        .numeral = explicit.numeral,
    };
}

fn expectInvalidationRetryAggregatePlanRange(
    cir: *const ModuleEnv,
    start: u32,
    owner: CIR.Expr.Idx,
    child_role: ModuleEnv.ExpectedConsumptionPlan.Role,
    child_sites: []const CIR.Expr.Idx,
) !void {
    errdefer std.debug.print(
        "invalidation fixture aggregate range mismatch: start={d}, owner={d}, role={s}, children={d}\n",
        .{ start, @intFromEnum(owner), @tagName(child_role), child_sites.len },
    );
    const plans = cir.expected_consumption_plans.items.items;
    try std.testing.expect(rangeFits(start, @intCast(child_sites.len + 1), plans.len));
    const root = plans[@intCast(start)];
    try std.testing.expect(root.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(owner), root.owner_node);
    try std.testing.expectEqual(@intFromEnum(owner), root.site_node);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.aggregate_owner, root.decodedRole().?);
    for (child_sites, 0..) |site, slot| {
        const child = plans[@as(usize, @intCast(start)) + 1 + slot];
        try std.testing.expect(child.hasLegalTags());
        try std.testing.expectEqual(@intFromEnum(owner), child.owner_node);
        try std.testing.expectEqual(@intFromEnum(site), child.site_node);
        try std.testing.expectEqual(child_role, child.decodedRole().?);
        try std.testing.expectEqual(@as(u32, @intCast(slot)), child.slot);
    }
}

fn expectInvalidationRetryTopology(
    test_env: anytype,
) !InvalidationRetryTestTopology {
    const checker = &test_env.checker;
    const cir = checker.cir;
    var failure_stage: []const u8 = "outer function topology";
    errdefer std.debug.print(
        "invalidation fixture topology mismatch at {s}: plans={d}, failures={d}, retirements={d}, omissions={d}, literals={d}, roots={d}, expr_map={d}, binding_map={d}\n",
        .{
            failure_stage,
            cir.expected_consumption_plans.items.items.len,
            cir.expected_failures.items.items.len,
            cir.expected_consumer_retirements.items.items.len,
            cir.record_omitted_defaults.items.items.len,
            cir.store.literalDispatchPlans().len,
            checker.selected_hoisted_roots.items.len,
            checker.hoist_selected_exprs.count(),
            checker.hoist_selected_bindings.count(),
        },
    );
    const first_def_idx = test_env.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const first_def = cir.store.getDef(first_def_idx);
    const outer_lambda = switch (cir.store.getExpr(first_def.expr)) {
        .e_lambda => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const outer_patterns = cir.store.slicePatterns(outer_lambda.args);
    try std.testing.expectEqual(@as(usize, 2), outer_patterns.len);
    try expectInvalidationRetryPatternName(checker, outer_patterns[0], "value");
    try expectInvalidationRetryPatternName(checker, outer_patterns[1], "open");
    const outer_block = switch (cir.store.getExpr(outer_lambda.body)) {
        .e_block => |value| value,
        else => return error.TestUnexpectedResult,
    };
    failure_stage = "three statement coordinates";
    const statements = cir.store.sliceStatements(outer_block.stmts);
    try std.testing.expectEqual(@as(usize, 3), statements.len);
    var statement_decls: [3]@FieldType(CIR.Statement, "s_decl") = undefined;
    for (statements, 0..) |statement_idx, statement_offset| {
        const statement = cir.store.getStatement(statement_idx);
        if (statement != .s_decl) return error.TestUnexpectedResult;
        statement_decls[statement_offset] = statement.s_decl;
        try std.testing.expect(cir.store.getPattern(statement.s_decl.pattern) == .underscore);
    }
    const before_decl = statement_decls[0];
    const call_decl = statement_decls[1];
    const after_decl = statement_decls[2];
    try std.testing.expect(cir.store.getPattern(call_decl.pattern) == .underscore);
    try std.testing.expect(cir.store.getExpr(outer_block.final_expr) == .e_empty_record);

    failure_stage = "before and after runtime-dependent wrappers";
    const before_wrapper = switch (cir.store.getExpr(before_decl.expr)) {
        .e_tuple => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const before_wrapper_elems = cir.store.sliceExpr(before_wrapper.elems);
    try std.testing.expectEqual(@as(usize, 2), before_wrapper_elems.len);
    const before_list = try expectInvalidationRetryList(cir, before_wrapper_elems[0], 3);
    try std.testing.expectEqual(
        outer_patterns[1],
        switch (cir.store.getExpr(before_wrapper_elems[1])) {
            .e_lookup_local => |lookup| lookup.pattern_idx,
            else => return error.TestUnexpectedResult,
        },
    );
    const after_wrapper = switch (cir.store.getExpr(after_decl.expr)) {
        .e_tuple => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const after_wrapper_elems = cir.store.sliceExpr(after_wrapper.elems);
    try std.testing.expectEqual(@as(usize, 2), after_wrapper_elems.len);
    const after_list = try expectInvalidationRetryList(cir, after_wrapper_elems[0], 9);
    try std.testing.expectEqual(
        outer_patterns[1],
        switch (cir.store.getExpr(after_wrapper_elems[1])) {
            .e_lookup_local => |lookup| lookup.pattern_idx,
            else => return error.TestUnexpectedResult,
        },
    );
    failure_stage = "central direct-binder call topology";
    const call = switch (cir.store.getExpr(call_decl.expr)) {
        .e_call => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(call.constraint_fn_var == null);
    const call_arguments = cir.store.sliceExpr(call.args);
    try std.testing.expectEqual(@as(usize, 3), call_arguments.len);
    const call_formals_lambda = switch (cir.store.getExpr(call.func)) {
        .e_lambda => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const call_formals = cir.store.slicePatterns(call_formals_lambda.args);
    try std.testing.expectEqual(@as(usize, 3), call_formals.len);
    try expectInvalidationRetryPatternName(checker, call_formals[0], "left");
    try expectInvalidationRetryPatternName(checker, call_formals[1], "_middle");
    try expectInvalidationRetryPatternName(checker, call_formals[2], "_right");
    try std.testing.expectEqual(
        call_formals[0],
        switch (cir.store.getExpr(call_formals_lambda.body)) {
            .e_lookup_local => |lookup| lookup.pattern_idx,
            else => return error.TestUnexpectedResult,
        },
    );
    try std.testing.expectEqual(
        outer_patterns[0],
        switch (cir.store.getExpr(call_arguments[0])) {
            .e_lookup_local => |lookup| lookup.pattern_idx,
            else => return error.TestUnexpectedResult,
        },
    );
    try std.testing.expectEqual(
        outer_patterns[0],
        switch (cir.store.getExpr(call_arguments[2])) {
            .e_lookup_local => |lookup| lookup.pattern_idx,
            else => return error.TestUnexpectedResult,
        },
    );
    const middle = switch (cir.store.getExpr(call_arguments[1])) {
        .e_tuple => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const middle_elems = cir.store.sliceExpr(middle.elems);
    try std.testing.expectEqual(@as(usize, 3), middle_elems.len);
    const middle_explicit = try expectInvalidationRetryExplicitBacking(cir, middle_elems[1], 5);
    const middle_backings = [3]CIR.Expr.Idx{
        try expectInvalidationRetryEmptyBacking(cir, middle_elems[0]),
        middle_explicit.backing,
        try expectInvalidationRetryEmptyBacking(cir, middle_elems[2]),
    };

    failure_stage = "pending failure and retirement ledgers";
    try std.testing.expectEqual(@as(usize, 5), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 4), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), cir.expected_call_formals.items.items.len);
    try std.testing.expectEqual(@as(usize, 4), cir.expected_call_slot_tokens.items.items.len);
    try std.testing.expectEqual(@as(usize, 5), checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 1), checker.aggregate_expected_retirement_drafts.items.len);
    const aggregate = checker.aggregate_expected_retirement_drafts.items[0];
    try std.testing.expectEqual(call_decl.expr, aggregate.owner_expr);
    try std.testing.expectEqual(@as(u32, 4), aggregate.plans_len);
    try std.testing.expect(rangeFits(
        aggregate.plans_start,
        aggregate.plans_len,
        cir.expected_consumption_plans.items.items.len,
    ));
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error,
        aggregate.retired_reason,
    );
    try std.testing.expect(aggregate.retirement_index < cir.expected_consumer_retirements.items.items.len);
    const call_retirement = cir.expected_consumer_retirements.items.items[aggregate.retirement_index];
    try std.testing.expectEqual(@intFromEnum(call_decl.expr), call_retirement.retired_node);
    try std.testing.expectEqual(CIR.Node.Tag.expr_call, call_retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, call_retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), call_retirement.expected_failures_len);
    try std.testing.expectEqual(@as(u32, 0), call_retirement.retired_consumers_len);
    try std.testing.expect(checker.erroneous_value_exprs.contains(call_decl.expr));

    const call_node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(call_decl.expr));
    const call_snapshot = expectedCallOperandProducerSnapshotFromPayload(
        cir,
        call_node.getPayload(),
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 3), call_snapshot.args_len);
    const root_plan = cir.expected_consumption_plans.items.items[aggregate.plans_start];
    try std.testing.expect(expectedCallRootPlanMatchesSnapshot(cir, root_plan, call_snapshot));
    const root_token_index = expectedCallSlotTokenIndex(
        cir,
        @intFromEnum(call_decl.expr),
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse return error.TestUnexpectedResult;
    const validated_root = ExpectedCallValidatedRoot{
        .plan_index = aggregate.plans_start,
        .plan = root_plan,
        .call = call_snapshot,
        .root_token_index = root_token_index,
    };
    for (0..3) |slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        const argument_plan_index = aggregate.plans_start + 1 + slot;
        try std.testing.expect(expectedCallArgumentPlanIsTerminal(
            cir,
            validated_root,
            argument_plan_index,
            slot,
        ));
        const slot_token_index = expectedCallSlotTokenIndex(
            cir,
            @intFromEnum(call_decl.expr),
            .argument,
            slot,
        ) orelse return error.TestUnexpectedResult;
        var matching_formals: usize = 0;
        for (cir.expected_call_formals.items.items) |formal| {
            if (formal.owner_node != @intFromEnum(call_decl.expr) or formal.slot != slot) continue;
            try std.testing.expect(expectedCallFormalMatchesValidatedRoot(
                cir,
                formal,
                validated_root,
                argument_plan_index,
                slot_token_index,
            ));
            matching_formals += 1;
        }
        try std.testing.expectEqual(@as(usize, 1), matching_formals);
    }

    failure_stage = "all aggregate consumption plan ranges";
    // The call owns one contiguous four-plan range. Eight independent
    // aggregate groups in this richer source publish the other twenty-two
    // rows; none may be mistaken for call authority merely because it is in
    // the same module-wide pool.
    try std.testing.expectEqual(@as(usize, 26), cir.expected_consumption_plans.items.items.len);
    try std.testing.expectEqual(@as(u32, 8), aggregate.plans_start);
    try expectInvalidationRetryAggregatePlanRange(
        cir,
        0,
        before_decl.expr,
        .tuple_element,
        before_wrapper_elems,
    );
    try expectInvalidationRetryAggregatePlanRange(
        cir,
        3,
        before_wrapper_elems[0],
        .list_element,
        &before_list.nominals,
    );
    try expectInvalidationRetryAggregatePlanRange(
        cir,
        6,
        before_list.backings[1],
        .record_field,
        &.{before_list.numeral},
    );
    try expectInvalidationRetryAggregatePlanRange(
        cir,
        12,
        call_arguments[1],
        .tuple_element,
        middle_elems,
    );
    try expectInvalidationRetryAggregatePlanRange(
        cir,
        16,
        middle_backings[1],
        .record_field,
        &.{middle_explicit.numeral},
    );
    try expectInvalidationRetryAggregatePlanRange(
        cir,
        18,
        after_decl.expr,
        .tuple_element,
        after_wrapper_elems,
    );
    try expectInvalidationRetryAggregatePlanRange(
        cir,
        21,
        after_wrapper_elems[0],
        .list_element,
        &after_list.nominals,
    );
    try expectInvalidationRetryAggregatePlanRange(
        cir,
        24,
        after_list.backings[1],
        .record_field,
        &.{after_list.numeral},
    );
    var call_owned_plans: usize = 0;
    for (cir.expected_consumption_plans.items.items, 0..) |plan, plan_index| {
        try std.testing.expect(plan.hasLegalTags());
        if (plan.owner_node != @intFromEnum(call_decl.expr)) continue;
        try std.testing.expect(plan_index >= aggregate.plans_start and
            plan_index < aggregate.plans_start + aggregate.plans_len);
        call_owned_plans += 1;
    }
    try std.testing.expectEqual(@as(usize, 4), call_owned_plans);

    failure_stage = "exact failure family partition";
    var call_failure_indices: [2]u32 = undefined;
    var call_failure_count: usize = 0;
    var annotation_failure_count: usize = 0;
    var lookup_failure_count: usize = 0;
    for (cir.expected_failures.items.items, 0..) |failure, failure_index| {
        switch (failure.decodedKind() orelse return error.TestUnexpectedResult) {
            .annotation_malformed_type => annotation_failure_count += 1,
            .direct_binder_lookup_checked_error => lookup_failure_count += 1,
            .call_operand_checked_error => {
                if (call_failure_count >= call_failure_indices.len) return error.TestUnexpectedResult;
                try std.testing.expect(failure.owner_node == @intFromEnum(call_decl.expr));
                try std.testing.expect(failure.slot == 0 or failure.slot == 2);
                try std.testing.expectEqual(
                    @intFromEnum(call_arguments[failure.slot]),
                    failure.site_node,
                );
                call_failure_indices[call_failure_count] = @intCast(failure_index);
                call_failure_count += 1;
            },
            else => return error.TestUnexpectedResult,
        }
    }
    try std.testing.expectEqual(@as(usize, 1), annotation_failure_count);
    try std.testing.expectEqual(@as(usize, 2), lookup_failure_count);
    try std.testing.expectEqual(call_failure_indices.len, call_failure_count);
    try std.testing.expect(
        cir.expected_failures.items.items[call_failure_indices[0]].slot <
            cir.expected_failures.items.items[call_failure_indices[1]].slot,
    );
    var source_retirement_index: ?u32 = null;
    for (call_failure_indices) |call_failure_index| {
        const lookup_retirement = cir.expected_failures.items.items[call_failure_index]
            .cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        const lookup_failure_index = checker.directBinderLookupFailureForCallCompletion(
            lookup_retirement.index,
        ) orelse return error.TestUnexpectedResult;
        const source_retirement = cir.expected_failures.items.items[lookup_failure_index]
            .cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        if (source_retirement_index) |expected| {
            try std.testing.expectEqual(expected, source_retirement.index);
        } else {
            source_retirement_index = source_retirement.index;
        }
    }
    const exact_source_retirement_index = source_retirement_index orelse
        return error.TestUnexpectedResult;
    const source_retirement = cir.expected_consumer_retirements.items.items[
        exact_source_retirement_index
    ];
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, source_retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), source_retirement.expected_failures_len);
    const source_retired_expr: CIR.Expr.Idx = @enumFromInt(source_retirement.retired_node);
    try std.testing.expectEqual(first_def.expr, source_retired_expr);
    const expected_erroneous_exprs = [4]CIR.Expr.Idx{
        call_arguments[0],
        call_arguments[2],
        call_decl.expr,
        source_retired_expr,
    };
    try std.testing.expectEqual(expected_erroneous_exprs.len, checker.erroneous_value_exprs.count());
    for (expected_erroneous_exprs, 0..) |expr, index| {
        for (expected_erroneous_exprs[0..index]) |previous| {
            try std.testing.expect(expr != previous);
        }
        try std.testing.expect(checker.erroneous_value_exprs.contains(expr));
    }

    failure_stage = "record omission ownership";
    const expected_omission_exprs = [4]CIR.Expr.Idx{
        before_list.backings[0],
        middle_backings[0],
        middle_backings[2],
        after_list.backings[0],
    };
    const omissions = cir.record_omitted_defaults.items.items;
    try std.testing.expectEqual(expected_omission_exprs.len, omissions.len);
    var default_numeral: ?CIR.Expr.Idx = null;
    for (omissions, 0..) |omitted, omission_index| {
        try std.testing.expectEqual(expected_omission_exprs[omission_index], omitted.expr);
        try std.testing.expectEqualStrings("value", cir.getIdent(omitted.field_name));
        try std.testing.expectEqual(cir.selfModuleIdentity(), omitted.origin_module);
        const default_expr: CIR.Expr.Idx = @enumFromInt(omitted.default_expr_node);
        if (default_numeral) |previous| {
            try std.testing.expectEqual(previous, default_expr);
        } else {
            default_numeral = default_expr;
        }
    }
    const exact_default = default_numeral orelse return error.TestUnexpectedResult;
    const default_value = switch (cir.store.getExpr(exact_default)) {
        .e_num => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(i128, 7), default_value.value.toI128());

    failure_stage = "literal dispatch plan ownership";
    const expected_literal_owners = [4]CIR.Expr.Idx{
        before_list.numeral,
        middle_explicit.numeral,
        after_list.numeral,
        exact_default,
    };
    const literal_plans = cir.store.literalDispatchPlans();
    try std.testing.expectEqual(expected_literal_owners.len, literal_plans.len);
    var observed_literal_owners = [_]bool{false} ** expected_literal_owners.len;
    for (literal_plans) |plan| {
        var matched = false;
        for (expected_literal_owners, 0..) |owner, owner_index| {
            if (plan.node_idx != @intFromEnum(owner)) continue;
            try std.testing.expect(!observed_literal_owners[owner_index]);
            observed_literal_owners[owner_index] = true;
            matched = true;
            break;
        }
        try std.testing.expect(matched);
        try std.testing.expectEqual(can.NodeStore.LiteralDispatchPlan.Kind.numeral, plan.dispatchKind());
        try std.testing.expectEqual(can.NodeStore.LiteralDispatchPlan.Resolution.unresolved, plan.dispatchResolution());
    }
    try std.testing.expect(std.mem.allEqual(bool, &observed_literal_owners, true));

    failure_stage = "selected hoist root identities";
    try std.testing.expectEqual(@as(usize, 3), checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(@as(usize, 3), checker.hoist_selected_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_bindings.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_pattern_validations.count());
    const selected = checker.selected_hoisted_roots.items;
    const middle_root_index = checker.hoist_selected_exprs.get(call_arguments[1]) orelse
        return error.TestUnexpectedResult;
    const before_root_index = checker.hoist_selected_exprs.get(before_wrapper_elems[0]) orelse
        return error.TestUnexpectedResult;
    const after_root_index = checker.hoist_selected_exprs.get(after_wrapper_elems[0]) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(middle_root_index != before_root_index and
        middle_root_index != after_root_index and before_root_index != after_root_index);
    try std.testing.expectEqual(call_arguments[1], selected[middle_root_index].expr);
    try std.testing.expect(selected[middle_root_index].pattern == null and
        selected[middle_root_index].body == .expr);
    try std.testing.expectEqual(before_wrapper_elems[0], selected[before_root_index].expr);
    try std.testing.expect(selected[before_root_index].pattern == null and
        selected[before_root_index].body == .expr);
    try std.testing.expectEqual(after_wrapper_elems[0], selected[after_root_index].expr);
    try std.testing.expect(selected[after_root_index].pattern == null and
        selected[after_root_index].body == .expr);
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.count());

    return .{
        .outer_lambda = first_def.expr,
        .outer_body = outer_lambda.body,
        .outer_final = outer_block.final_expr,
        .outer_pattern = outer_patterns[0],
        .call_expr = call_decl.expr,
        .call_callee = call.func,
        .call_callee_body = call_formals_lambda.body,
        .call_retirement_index = aggregate.retirement_index,
        .call_plan_start = aggregate.plans_start,
        .call_argument_sites = .{ call_arguments[0], call_arguments[1], call_arguments[2] },
        .call_failure_indices = call_failure_indices,
        .source_retirement_index = exact_source_retirement_index,
        .source_retired_expr = source_retired_expr,
        .before_wrapper = before_decl.expr,
        .before_open = before_wrapper_elems[1],
        .before_list = before_wrapper_elems[0],
        .before_nominals = before_list.nominals,
        .before_backings = before_list.backings,
        .before_numeral = before_list.numeral,
        .middle_tuple = call_arguments[1],
        .middle_nominals = .{ middle_elems[0], middle_elems[1], middle_elems[2] },
        .middle_backings = middle_backings,
        .middle_numeral = middle_explicit.numeral,
        .after_wrapper = after_decl.expr,
        .after_open = after_wrapper_elems[1],
        .after_list = after_wrapper_elems[0],
        .after_nominals = after_list.nominals,
        .after_backings = after_list.backings,
        .after_numeral = after_list.numeral,
        .default_numeral = exact_default,
    };
}

fn invalidationRetryExpectedDiscovery(
    topology: InvalidationRetryTestTopology,
) [12]CIR.Expr.Idx {
    return .{
        topology.call_callee,
        topology.call_argument_sites[0],
        topology.middle_tuple,
        topology.call_argument_sites[2],
        topology.call_callee_body,
        topology.middle_nominals[0],
        topology.middle_nominals[1],
        topology.middle_nominals[2],
        topology.middle_backings[0],
        topology.middle_backings[1],
        topology.middle_backings[2],
        topology.middle_numeral,
    };
}

fn expectInvalidationRetryDiscoveryWithAllocator(
    checker: *Self,
    topology: InvalidationRetryTestTopology,
    allocator: Allocator,
) !void {
    const saved_gpa = checker.gpa;
    checker.gpa = allocator;
    defer checker.gpa = saved_gpa;

    var discovered: ExprInvalidationDiscovery = .empty;
    defer discovered.deinit(allocator);
    try checker.discoverInvalidatedExprChildren(topology.call_expr, &discovered);
    var next: usize = 0;
    while (next < discovered.count()) : (next += 1) {
        try checker.discoverInvalidatedExprChildren(discovered.keys()[next], &discovered);
    }
    const expected = invalidationRetryExpectedDiscovery(topology);
    try std.testing.expectEqualSlices(CIR.Expr.Idx, &expected, discovered.keys());
}

fn invalidateExprSubtreeMetadataWithAllocatorForTest(
    checker: *Self,
    root: CIR.Expr.Idx,
    allocator: Allocator,
) Allocator.Error!void {
    const saved_gpa = checker.gpa;
    checker.gpa = allocator;
    defer checker.gpa = saved_gpa;
    try checker.invalidateExprSubtreeMetadata(root);
}

fn replaceExprWithRuntimeErrorWithAllocatorForTest(
    checker: *Self,
    expr: CIR.Expr.Idx,
    diagnostic: CIR.Diagnostic.Idx,
    allocator: Allocator,
) Allocator.Error!void {
    const saved_checker_gpa = checker.gpa;
    const saved_cir_gpa = checker.cir.gpa;
    const saved_types_gpa = checker.types.gpa;
    checker.gpa = allocator;
    checker.cir.gpa = allocator;
    checker.types.gpa = allocator;
    defer {
        checker.types.gpa = saved_types_gpa;
        checker.cir.gpa = saved_cir_gpa;
        checker.gpa = saved_checker_gpa;
    }
    try checker.replaceExprWithRuntimeError(expr, diagnostic);
}

fn expectRecordUpdateOwnerCompletionDiscoveryWithAllocator(
    checker: *Self,
    topology: RecordUpdateDirectBinderOwnerTopology,
    allocator: Allocator,
) !void {
    const saved_gpa = checker.gpa;
    checker.gpa = allocator;
    defer checker.gpa = saved_gpa;

    var discovered: ExprInvalidationDiscovery = .empty;
    defer discovered.deinit(allocator);
    try checker.discoverInvalidatedExprChildren(topology.record_expr, &discovered);
    var next: usize = 0;
    while (next < discovered.count()) : (next += 1) {
        try checker.discoverInvalidatedExprChildren(discovered.keys()[next], &discovered);
    }
    const expected = [_]CIR.Expr.Idx{
        topology.field_expr,
        topology.base_expr,
    };
    try std.testing.expectEqualSlices(CIR.Expr.Idx, &expected, discovered.keys());
    try std.testing.expect(!discovered.contains(topology.record_expr));
}

fn invalidationRetryExpectedTerminalDiscovery(
    topology: InvalidationRetryTestTopology,
) [31]CIR.Expr.Idx {
    const call_discovery = invalidationRetryExpectedDiscovery(topology);
    return call_discovery ++ [_]CIR.Expr.Idx{
        topology.outer_body,
        topology.before_wrapper,
        topology.call_expr,
        topology.after_wrapper,
        topology.outer_final,
        topology.before_list,
        topology.before_open,
        topology.after_list,
        topology.after_open,
        topology.before_nominals[0],
        topology.before_nominals[1],
        topology.after_nominals[0],
        topology.after_nominals[1],
        topology.before_backings[0],
        topology.before_backings[1],
        topology.after_backings[0],
        topology.after_backings[1],
        topology.before_numeral,
        topology.after_numeral,
    };
}

const InvalidationRetrySelectedExprEntry = struct {
    expr: CIR.Expr.Idx,
    root_index: u32,
};

const InvalidationRetryLiteralOwnerNode = struct {
    expr: CIR.Expr.Idx,
    tag: CIR.Node.Tag,
    payload: [4]u32,
};

/// Semantic snapshot of the four checker-owned metadata families affected by
/// runtime-error subtree invalidation. ModuleEnv ledger rows are captured by
/// `DirectBinderCallCompletionLedgerSnapshot`; this snapshot owns the selected
/// root bodies and also pins every literal owner's dense-plan stamp.
const InvalidationRetryMetadataSnapshot = struct {
    selected_roots: []hoist_roots.SelectedHoistedRoot,
    selected_expr_entries: []InvalidationRetrySelectedExprEntry,
    selected_binding_count: usize,
    selected_validation_count: usize,
    invalidated_exprs: []CIR.Expr.Idx,
    literal_plans: []can.NodeStore.LiteralDispatchPlan,
    literal_owner_nodes: []InvalidationRetryLiteralOwnerNode,
    omissions: []ModuleEnv.RecordOmittedDefault,

    fn capture(
        checker: *const Self,
        literal_owners: []const CIR.Expr.Idx,
    ) !InvalidationRetryMetadataSnapshot {
        const allocator = std.testing.allocator;
        if (checker.hoist_selected_bindings.count() != 0 or
            checker.hoist_selected_pattern_validations.count() != 0)
        {
            return error.TestUnexpectedResult;
        }
        const selected_roots = try allocator.alloc(
            hoist_roots.SelectedHoistedRoot,
            checker.selected_hoisted_roots.items.len,
        );
        var initialized_roots: usize = 0;
        errdefer {
            hoist_roots.deinitSelectedRootBodies(
                allocator,
                selected_roots[0..initialized_roots],
            );
            allocator.free(selected_roots);
        }
        for (checker.selected_hoisted_roots.items, 0..) |root, root_index| {
            selected_roots[root_index] = try hoist_roots.cloneSelectedRoot(
                allocator,
                root,
            );
            initialized_roots += 1;
        }

        const selected_expr_entries = try allocator.alloc(
            InvalidationRetrySelectedExprEntry,
            checker.hoist_selected_exprs.count(),
        );
        errdefer allocator.free(selected_expr_entries);
        var selected_expr_iter = checker.hoist_selected_exprs.iterator();
        var selected_expr_index: usize = 0;
        while (selected_expr_iter.next()) |entry| : (selected_expr_index += 1) {
            selected_expr_entries[selected_expr_index] = .{
                .expr = entry.key_ptr.*,
                .root_index = entry.value_ptr.*,
            };
        }

        const invalidated_exprs = try allocator.alloc(
            CIR.Expr.Idx,
            checker.hoist_invalidated_exprs.count(),
        );
        errdefer allocator.free(invalidated_exprs);
        var invalidated_iter = checker.hoist_invalidated_exprs.keyIterator();
        var invalidated_index: usize = 0;
        while (invalidated_iter.next()) |expr| : (invalidated_index += 1) {
            invalidated_exprs[invalidated_index] = expr.*;
        }

        const literal_plans = try allocator.dupe(
            can.NodeStore.LiteralDispatchPlan,
            checker.cir.store.literalDispatchPlans(),
        );
        errdefer allocator.free(literal_plans);
        const literal_owner_nodes = try allocator.alloc(
            InvalidationRetryLiteralOwnerNode,
            literal_owners.len,
        );
        errdefer allocator.free(literal_owner_nodes);
        for (literal_owners, literal_owner_nodes) |expr, *snapshot| {
            const node = checker.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(expr));
            snapshot.* = .{
                .expr = expr,
                .tag = node.tag,
                .payload = @bitCast(node.getPayload()),
            };
        }
        const omissions = try allocator.dupe(
            ModuleEnv.RecordOmittedDefault,
            checker.cir.record_omitted_defaults.items.items,
        );
        errdefer allocator.free(omissions);

        return .{
            .selected_roots = selected_roots,
            .selected_expr_entries = selected_expr_entries,
            .selected_binding_count = checker.hoist_selected_bindings.count(),
            .selected_validation_count = checker.hoist_selected_pattern_validations.count(),
            .invalidated_exprs = invalidated_exprs,
            .literal_plans = literal_plans,
            .literal_owner_nodes = literal_owner_nodes,
            .omissions = omissions,
        };
    }

    fn selectedStateMatches(
        self: InvalidationRetryMetadataSnapshot,
        checker: *const Self,
    ) bool {
        if (self.selected_roots.len != checker.selected_hoisted_roots.items.len or
            self.selected_expr_entries.len != checker.hoist_selected_exprs.count() or
            self.selected_binding_count != checker.hoist_selected_bindings.count() or
            self.selected_validation_count != checker.hoist_selected_pattern_validations.count())
        {
            return false;
        }
        for (self.selected_roots, checker.selected_hoisted_roots.items) |expected, actual| {
            if (!std.meta.eql(expected, actual)) return false;
        }
        for (self.selected_expr_entries) |entry| {
            if (checker.hoist_selected_exprs.get(entry.expr) != entry.root_index) return false;
        }
        return true;
    }

    fn invalidatedStateMatches(
        self: InvalidationRetryMetadataSnapshot,
        checker: *const Self,
    ) bool {
        if (self.invalidated_exprs.len != checker.hoist_invalidated_exprs.count()) return false;
        for (self.invalidated_exprs) |expr| {
            if (!checker.hoist_invalidated_exprs.contains(expr)) return false;
        }
        return true;
    }

    fn literalStateMatches(
        self: InvalidationRetryMetadataSnapshot,
        checker: *const Self,
    ) bool {
        if (!std.mem.eql(
            u8,
            std.mem.sliceAsBytes(self.literal_plans),
            std.mem.sliceAsBytes(checker.cir.store.literalDispatchPlans()),
        )) return false;
        for (self.literal_owner_nodes) |expected| {
            const actual = checker.cir.store.nodes.get(ModuleEnv.nodeIdxFrom(expected.expr));
            const actual_payload: [4]u32 = @bitCast(actual.getPayload());
            if (actual.tag != expected.tag or
                !std.mem.eql(u32, &expected.payload, &actual_payload))
            {
                return false;
            }
        }
        return true;
    }

    fn omissionStateMatches(
        self: InvalidationRetryMetadataSnapshot,
        checker: *const Self,
    ) bool {
        return std.mem.eql(
            u8,
            std.mem.sliceAsBytes(self.omissions),
            std.mem.sliceAsBytes(checker.cir.record_omitted_defaults.items.items),
        );
    }

    fn matches(
        self: InvalidationRetryMetadataSnapshot,
        checker: *const Self,
    ) bool {
        return self.selectedStateMatches(checker) and
            self.invalidatedStateMatches(checker) and
            self.literalStateMatches(checker) and
            self.omissionStateMatches(checker);
    }

    fn deinit(self: *InvalidationRetryMetadataSnapshot) void {
        const allocator = std.testing.allocator;
        hoist_roots.freeSelectedRootSlice(allocator, self.selected_roots);
        allocator.free(self.selected_expr_entries);
        allocator.free(self.invalidated_exprs);
        allocator.free(self.literal_plans);
        allocator.free(self.literal_owner_nodes);
        allocator.free(self.omissions);
        self.* = undefined;
    }
};

const RecordUpdateOwnerCompletionNodeSnapshot = struct {
    expr: CIR.Expr.Idx,
    tag: CIR.Node.Tag,
    payload: [4]u32,

    fn capture(cir: *const ModuleEnv, expr: CIR.Expr.Idx) @This() {
        const node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(expr));
        return .{
            .expr = expr,
            .tag = node.tag,
            .payload = @bitCast(node.getPayload()),
        };
    }

    fn matches(self: @This(), cir: *const ModuleEnv) bool {
        const node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(self.expr));
        const payload: [4]u32 = @bitCast(node.getPayload());
        return self.tag == node.tag and std.mem.eql(u32, &self.payload, &payload);
    }
};

/// Full logical state surrounding one authentic checked-base owner
/// completion. The transaction snapshot covers types, durable proof rows,
/// private registrations/drafts, consume-once state, and checker scratch. The
/// metadata and node snapshots additionally cover the destructive subtree
/// invalidation and the exact CIR payloads it is allowed to rewrite.
const RecordUpdateOwnerCompletionStateSnapshot = struct {
    transaction: RecordUpdateRootTransactionSnapshot,
    metadata: InvalidationRetryMetadataSnapshot,
    diagnostics: DirectBinderDiagnosticState,
    erroneous_exprs: []CIR.Expr.Idx,
    annotation_drafts: []AnnotationExpectedFailureDraft,
    aggregate_drafts: []AggregateExpectedRetirementDraft,
    direct_sources: []DirectFormalFailureSource,
    active_failures: []ActiveDirectBinderFailure,
    nodes: [3]RecordUpdateOwnerCompletionNodeSnapshot,
    diagnostic_region: Region,

    fn capture(
        checker: *const Self,
        stage: *StagedRecordUpdateOwnerCompletion,
    ) !@This() {
        const allocator = std.testing.allocator;
        var transaction = try RecordUpdateRootTransactionSnapshot.capture(
            allocator,
            checker,
            &stage.env,
        );
        errdefer transaction.deinit(allocator);
        var metadata = try InvalidationRetryMetadataSnapshot.capture(
            checker,
            &.{stage.topology.field_expr},
        );
        errdefer metadata.deinit();
        const diagnostics = try DirectBinderDiagnosticState.capture(checker.cir);
        errdefer diagnostics.deinit();
        const erroneous_exprs = try allocator.alloc(
            CIR.Expr.Idx,
            checker.erroneous_value_exprs.count(),
        );
        errdefer allocator.free(erroneous_exprs);
        const annotation_drafts = try allocator.dupe(
            AnnotationExpectedFailureDraft,
            checker.annotation_expected_failure_drafts.items,
        );
        errdefer allocator.free(annotation_drafts);
        const aggregate_drafts = try allocator.dupe(
            AggregateExpectedRetirementDraft,
            checker.aggregate_expected_retirement_drafts.items,
        );
        errdefer allocator.free(aggregate_drafts);
        const direct_sources = try allocator.dupe(
            DirectFormalFailureSource,
            checker.direct_formal_failure_sources.items,
        );
        errdefer allocator.free(direct_sources);
        const active_failures = try allocator.dupe(
            ActiveDirectBinderFailure,
            checker.active_direct_binder_failures.items,
        );
        errdefer allocator.free(active_failures);
        var erroneous_iter = checker.erroneous_value_exprs.keyIterator();
        var erroneous_index: usize = 0;
        while (erroneous_iter.next()) |expr| : (erroneous_index += 1) {
            erroneous_exprs[erroneous_index] = expr.*;
        }
        if (erroneous_index != erroneous_exprs.len) return error.TestUnexpectedResult;
        const diagnostic = checker.cir.store.getDiagnostic(stage.diagnostic);
        if (diagnostic != .erroneous_value_expr) return error.TestUnexpectedResult;
        return .{
            .transaction = transaction,
            .metadata = metadata,
            .diagnostics = diagnostics,
            .erroneous_exprs = erroneous_exprs,
            .annotation_drafts = annotation_drafts,
            .aggregate_drafts = aggregate_drafts,
            .direct_sources = direct_sources,
            .active_failures = active_failures,
            .nodes = .{
                RecordUpdateOwnerCompletionNodeSnapshot.capture(
                    checker.cir,
                    stage.topology.record_expr,
                ),
                RecordUpdateOwnerCompletionNodeSnapshot.capture(
                    checker.cir,
                    stage.topology.base_expr,
                ),
                RecordUpdateOwnerCompletionNodeSnapshot.capture(
                    checker.cir,
                    stage.topology.field_expr,
                ),
            },
            .diagnostic_region = diagnostic.erroneous_value_expr.region,
        };
    }

    fn expectEqual(
        self: *const @This(),
        checker: *const Self,
        stage: *StagedRecordUpdateOwnerCompletion,
    ) !void {
        try self.transaction.expectEqual(
            std.testing.allocator,
            checker,
            &stage.env,
        );
        try std.testing.expect(self.metadata.matches(checker));
        try self.diagnostics.expectUnchanged(checker.cir);
        try std.testing.expectEqual(self.erroneous_exprs.len, checker.erroneous_value_exprs.count());
        for (self.erroneous_exprs) |expr| {
            try std.testing.expect(checker.erroneous_value_exprs.contains(expr));
        }
        try expectRecordUpdateTestSemanticSlicesEqual(
            self.annotation_drafts,
            checker.annotation_expected_failure_drafts.items,
        );
        try expectRecordUpdateTestSemanticSlicesEqual(
            self.aggregate_drafts,
            checker.aggregate_expected_retirement_drafts.items,
        );
        try expectRecordUpdateTestSemanticSlicesEqual(
            self.direct_sources,
            checker.direct_formal_failure_sources.items,
        );
        try expectRecordUpdateTestSemanticSlicesEqual(
            self.active_failures,
            checker.active_direct_binder_failures.items,
        );
        for (self.nodes) |node| {
            try std.testing.expect(node.matches(checker.cir));
        }
        const diagnostic = checker.cir.store.getDiagnostic(stage.diagnostic);
        try std.testing.expect(diagnostic == .erroneous_value_expr);
        try std.testing.expect(std.meta.eql(
            self.diagnostic_region,
            diagnostic.erroneous_value_expr.region,
        ));
    }

    fn expectSameInstanceRollback(
        self: *const @This(),
        checker: *const Self,
        stage: *StagedRecordUpdateOwnerCompletion,
    ) !void {
        try self.expectEqual(checker, stage);
        try self.transaction.cross_copy.expectEqual(checker);
    }

    fn deinit(self: *@This()) void {
        const allocator = std.testing.allocator;
        allocator.free(self.active_failures);
        allocator.free(self.direct_sources);
        allocator.free(self.aggregate_drafts);
        allocator.free(self.annotation_drafts);
        allocator.free(self.erroneous_exprs);
        self.diagnostics.deinit();
        self.metadata.deinit();
        self.transaction.deinit(allocator);
        self.* = undefined;
    }
};

test "record-update owner retirement: checked-base completion is atomic across every allocation" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    var injected_failure_index: usize = std.math.maxInt(usize);
    errdefer std.debug.print(
        "record-update owner completion OOM fixture failed at {s}, allocation {d}\n",
        .{ failure_stage, injected_failure_index },
    );

    var provider = try TestEnv.init(
        "RecordUpdateLiveOwnerA",
        direct_binder_transaction_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "RecordUpdateLiveOwnerB",
        record_update_direct_binder_owner_retirement_source,
        "RecordUpdateLiveOwnerA",
        &provider,
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const fresh_topology = try recordUpdateDirectBinderOwnerTopology(&fresh_env);

    failure_stage = "calibration staging";
    var calibration = try TestEnv.initUncheckedWithImportForTesting(
        "RecordUpdateLiveOwnerB",
        record_update_direct_binder_owner_retirement_source,
        "RecordUpdateLiveOwnerA",
        &provider,
    );
    defer calibration.deinit();
    try calibration.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    var calibration_stage = try stageRecordUpdateOwnerCompletionThroughLeafPoison(&calibration);
    defer calibration.checker.env_pool.release(calibration_stage.env);
    try std.testing.expect(std.meta.eql(fresh_topology, calibration_stage.topology));
    const calibration_checker = &calibration.checker;
    const calibration_cir = calibration.module_env;
    try std.testing.expectEqual(
        @as(usize, 1),
        calibration_checker.record_update_owner_retirement_drafts.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 2),
        calibration_checker.record_update_expected_plan_registrations.items.len,
    );
    try std.testing.expect(!calibration_checker.record_update_expected_plan_registrations_consumed);
    try std.testing.expectEqual(
        @as(usize, 0),
        calibration_cir.expected_retired_consumers.items.items.len,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        calibration_cir.expected_retired_consumers.items.capacity,
    );
    try std.testing.expectEqual(@as(usize, 0), calibration_checker.hoist_invalidated_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), calibration_checker.hoist_invalidated_exprs.capacity());
    try std.testing.expectEqual(@as(usize, 1), calibration_cir.store.literalDispatchPlans().len);
    const pending_literal = calibration_cir.store.literalDispatchPlanForNode(
        ModuleEnv.nodeIdxFrom(calibration_stage.topology.field_expr),
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        @intFromEnum(calibration_stage.topology.field_expr),
        pending_literal.node_idx,
    );
    try std.testing.expectEqual(
        can.NodeStore.LiteralDispatchPlan.Kind.numeral,
        pending_literal.dispatchKind(),
    );
    try std.testing.expectEqual(
        can.NodeStore.LiteralDispatchPlan.Resolution.unresolved,
        pending_literal.dispatchResolution(),
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        calibration_cir.record_omitted_defaults.items.items.len,
    );
    var calibration_pending = try RecordUpdateOwnerCompletionStateSnapshot.capture(
        calibration_checker,
        &calibration_stage,
    );
    defer calibration_pending.deinit();

    failure_stage = "private discovery calibration";
    var discovery_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const discovery_base = discovery_allocator.alloc_index;
    discovery_allocator.resize_fail_index = discovery_allocator.resize_index;
    try expectRecordUpdateOwnerCompletionDiscoveryWithAllocator(
        calibration_checker,
        calibration_stage.topology,
        discovery_allocator.allocator(),
    );
    const discovery_allocations = discovery_allocator.alloc_index - discovery_base;
    try std.testing.expect(!discovery_allocator.has_induced_failure);
    try std.testing.expect(discovery_allocations > 0);
    try calibration_pending.expectEqual(calibration_checker, &calibration_stage);

    failure_stage = "central completion calibration";
    var calibration_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const allocation_base = calibration_allocator.alloc_index;
    calibration_allocator.resize_fail_index = calibration_allocator.resize_index;
    try replaceExprWithRuntimeErrorWithAllocatorForTest(
        calibration_checker,
        calibration_stage.topology.record_expr,
        calibration_stage.diagnostic,
        calibration_allocator.allocator(),
    );
    const allocation_count = calibration_allocator.alloc_index - allocation_base;
    try std.testing.expect(!calibration_allocator.has_induced_failure);
    try std.testing.expectEqual(discovery_allocations + 2, allocation_count);
    _ = try expectRecordUpdateOwnerCompletionCommitted(
        calibration_checker,
        calibration_stage,
    );
    try std.testing.expectEqual(@as(usize, 2), calibration_checker.hoist_invalidated_exprs.count());
    try std.testing.expect(calibration_checker.hoist_invalidated_exprs.contains(
        calibration_stage.topology.field_expr,
    ));
    try std.testing.expect(calibration_checker.hoist_invalidated_exprs.contains(
        calibration_stage.topology.base_expr,
    ));
    try std.testing.expect(!calibration_checker.hoist_invalidated_exprs.contains(
        calibration_stage.topology.record_expr,
    ));
    try std.testing.expectEqual(@as(usize, 0), calibration_cir.store.literalDispatchPlans().len);
    try std.testing.expect(calibration_cir.store.literalDispatchPlanForNode(
        ModuleEnv.nodeIdxFrom(calibration_stage.topology.field_expr),
    ) == null);
    var calibration_committed = try RecordUpdateOwnerCompletionStateSnapshot.capture(
        calibration_checker,
        &calibration_stage,
    );
    defer calibration_committed.deinit();

    failure_stage = "calibration full tail";
    const terminal_bytes = try finishRecordUpdateOwnerCompletionTest(
        &calibration,
        &fresh_env,
        &calibration_stage,
    );
    defer std.testing.allocator.free(terminal_bytes);

    var induced_failures: usize = 0;
    for (0..allocation_count) |failure_index| {
        injected_failure_index = failure_index;
        failure_stage = "failure staging";
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "RecordUpdateLiveOwnerB",
            record_update_direct_binder_owner_retirement_source,
            "RecordUpdateLiveOwnerA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        var stage = try stageRecordUpdateOwnerCompletionThroughLeafPoison(&consumer);
        defer consumer.checker.env_pool.release(stage.env);
        const checker = &consumer.checker;
        const cir = consumer.module_env;
        try std.testing.expect(std.meta.eql(calibration_stage.topology, stage.topology));
        try calibration_stage.pending.expectEquivalent(stage.pending);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.capacity);
        try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.count());
        try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.capacity());
        try std.testing.expectEqual(@as(usize, 1), cir.store.literalDispatchPlans().len);
        try std.testing.expect(cir.store.literalDispatchPlanForNode(
            ModuleEnv.nodeIdxFrom(stage.topology.field_expr),
        ) != null);
        var before = try RecordUpdateOwnerCompletionStateSnapshot.capture(checker, &stage);
        defer before.deinit();
        try calibration_pending.expectEqual(checker, &stage);

        failure_stage = "injected central completion";
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = std.math.maxInt(usize),
            .resize_fail_index = std.math.maxInt(usize),
        });
        const failure_allocation_base = failing.alloc_index;
        failing.fail_index = std.math.add(
            usize,
            failure_allocation_base,
            failure_index,
        ) catch return error.TestUnexpectedResult;
        failing.resize_fail_index = failing.resize_index;
        const result = replaceExprWithRuntimeErrorWithAllocatorForTest(
            checker,
            stage.topology.record_expr,
            stage.diagnostic,
            failing.allocator(),
        );
        try std.testing.expectError(error.OutOfMemory, result);
        try std.testing.expect(failing.has_induced_failure);
        induced_failures += 1;

        failure_stage = "exact logical rollback";
        try before.expectSameInstanceRollback(checker, &stage);
        try calibration_pending.expectEqual(checker, &stage);
        const pending_after_failure = try expectPendingRecordUpdateOwnerCompletion(
            checker,
            stage.topology,
        );
        try stage.pending.expectEquivalent(pending_after_failure);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.items.len);
        if (failure_index == 0) {
            try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.capacity);
        } else {
            try std.testing.expect(cir.expected_retired_consumers.items.capacity >= 2);
        }
        try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.count());
        try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.capacity());
        try std.testing.expect(cir.store.getExpr(stage.topology.record_expr) == .e_record);
        try std.testing.expectEqual(@as(usize, 1), cir.store.literalDispatchPlans().len);
        try std.testing.expect(cir.store.literalDispatchPlanForNode(
            ModuleEnv.nodeIdxFrom(stage.topology.field_expr),
        ) != null);

        failure_stage = "same-instance retry";
        failing.fail_index = std.math.maxInt(usize);
        failing.resize_fail_index = std.math.maxInt(usize);
        try replaceExprWithRuntimeErrorWithAllocatorForTest(
            checker,
            stage.topology.record_expr,
            stage.diagnostic,
            failing.allocator(),
        );
        _ = try expectRecordUpdateOwnerCompletionCommitted(checker, stage);
        try calibration_committed.expectEqual(checker, &stage);
        try std.testing.expectEqual(@as(usize, 0), cir.store.literalDispatchPlans().len);
        try std.testing.expect(cir.store.literalDispatchPlanForNode(
            ModuleEnv.nodeIdxFrom(stage.topology.field_expr),
        ) == null);

        failure_stage = "same-instance full tail";
        const completed_bytes = try finishRecordUpdateOwnerCompletionTest(
            &consumer,
            &fresh_env,
            &stage,
        );
        defer std.testing.allocator.free(completed_bytes);
        try std.testing.expectEqualSlices(u8, terminal_bytes, completed_bytes);
    }
    try std.testing.expectEqual(allocation_count, induced_failures);
}

fn invalidationRetryLiteralOwners(
    topology: InvalidationRetryTestTopology,
) [4]CIR.Expr.Idx {
    return .{
        topology.before_numeral,
        topology.middle_numeral,
        topology.after_numeral,
        topology.default_numeral,
    };
}

const InvalidationRetryTestStage = struct {
    env: Env,
    topology: InvalidationRetryTestTopology,
    diagnostic: CIR.Diagnostic.Idx,
};

fn stageInvalidationRetryThroughPrePoison(test_env: anytype) !InvalidationRetryTestStage {
    const env = try stageDirectBinderCallPairThroughPrePoison(test_env);
    errdefer test_env.checker.env_pool.release(env);
    const topology = try expectInvalidationRetryTopology(test_env);
    try std.testing.expectEqual(@as(usize, 0), test_env.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try test_env.typeProblemCount());
    const diagnostic = try addCallOperandCompletionDiagnosticForTest(
        &test_env.checker,
        topology.call_expr,
    );
    return .{
        .env = env,
        .topology = topology,
        .diagnostic = diagnostic,
    };
}

fn expectInvalidationRetryCallCompletedWhileLookupsPending(
    checker: *const Self,
    topology: InvalidationRetryTestTopology,
    diagnostic_idx: CIR.Diagnostic.Idx,
) !void {
    const cir = checker.cir;
    const failures = cir.expected_failures.items.items;
    const retirements = cir.expected_consumer_retirements.items.items;
    const plans = cir.expected_consumption_plans.items.items;
    try std.testing.expectEqual(@as(usize, 5), failures.len);
    try std.testing.expectEqual(@as(usize, 4), retirements.len);
    try std.testing.expectEqual(@as(usize, 4), cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.aggregate_expected_retirement_drafts.items.len);

    const rewritten = cir.store.getExpr(topology.call_expr);
    if (rewritten != .e_runtime_error or rewritten.e_runtime_error.diagnostic != diagnostic_idx) {
        return error.TestUnexpectedResult;
    }
    const retirement = retirements[topology.call_retirement_index];
    try std.testing.expect(retirement.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(topology.call_expr), retirement.retired_node);
    try std.testing.expectEqual(CIR.Node.Tag.expr_call, retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(@intFromEnum(diagnostic_idx), retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 4), retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 2), retirement.expected_failures_len);
    try std.testing.expect(expectedConsumerRetirementNodeIsLocallyValid(cir, retirement));

    const call_payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    try std.testing.expectEqual(@as(u32, 0), call_payload.expr_call.constraint_fn_var_plus_one);
    const call_snapshot = expectedCallOperandRetirementTopologyFromPayload(
        cir,
        call_payload,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 3), call_snapshot.args_len);
    const root_plan = plans[topology.call_plan_start];
    try std.testing.expect(expectedCallRootPlanMatchesSnapshot(cir, root_plan, call_snapshot));
    const root_token_index = expectedCallSlotTokenIndex(
        cir,
        @intFromEnum(topology.call_expr),
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse return error.TestUnexpectedResult;
    const validated_root = ExpectedCallValidatedRoot{
        .plan_index = topology.call_plan_start,
        .plan = root_plan,
        .call = call_snapshot,
        .root_token_index = root_token_index,
    };

    const consumers = cir.expected_retired_consumers.items.items;
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.call_root, consumers[0].decodedRole().?);
    try std.testing.expectEqual(topology.call_plan_start, consumers[0].plan_index);
    try std.testing.expectEqual(root_plan.site_node, consumers[0].site_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error,
        consumers[0].decodedReason().?,
    );
    for (0..3) |slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        const consumer = consumers[slot_usize + 1];
        try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.call_argument, consumer.decodedRole().?);
        try std.testing.expectEqual(slot, consumer.slot);
        try std.testing.expectEqual(topology.call_plan_start + 1 + slot, consumer.plan_index);
        try std.testing.expectEqual(@intFromEnum(topology.call_argument_sites[slot_usize]), consumer.site_node);
        try std.testing.expectEqual(
            ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error,
            consumer.decodedReason().?,
        );
        try std.testing.expect(expectedCallArgumentPlanIsTerminal(
            cir,
            validated_root,
            consumer.plan_index,
            slot,
        ));
    }

    const references = cir.expected_retirement_failures.items.items;
    try std.testing.expectEqual(topology.call_failure_indices[0], references[0].failure_index);
    try std.testing.expectEqual(topology.call_failure_indices[1], references[1].failure_index);
    try std.testing.expect(expectedFailureKeyLessThan(
        failures,
        references[0].failure_index,
        references[1].failure_index,
    ));

    var source_retirement_index: ?u32 = null;
    for (topology.call_failure_indices) |failure_index| {
        const failure = failures[failure_index];
        const lookup_retirement_index = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        try std.testing.expectEqual(failure.site_node, retirements[lookup_retirement_index.index].retired_node);
        const lookup_failure_index = checker.directBinderLookupFailureForCallCompletion(
            lookup_retirement_index.index,
        ) orelse return error.TestUnexpectedResult;
        const lookup_failure = failures[lookup_failure_index];
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.direct_binder_lookup_checked_error,
            lookup_failure.decodedKind().?,
        );
        const lookup_retirement = retirements[lookup_retirement_index.index];
        try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, lookup_retirement.diagnostic_index);
        try std.testing.expectEqual(@as(u32, 0), lookup_retirement.expected_failures_len);
        try std.testing.expect(cir.store.getExpr(@enumFromInt(failure.site_node)) == .e_lookup_local);
        const source = lookup_failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        if (source_retirement_index) |expected| {
            try std.testing.expectEqual(expected, source.index);
        } else {
            source_retirement_index = source.index;
        }
    }
    const source_retirement = retirements[
        source_retirement_index orelse
            return error.TestUnexpectedResult
    ];
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, source_retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), source_retirement.expected_failures_len);
    for (checker.annotation_expected_failure_drafts.items) |draft| {
        try std.testing.expect(draft.owner_expr != topology.call_expr);
    }
    try std.testing.expectEqual(@as(usize, 0), checker.direct_formal_failure_sources.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
}

fn expectInvalidationRetryIsolatedMetadataCommit(
    checker: *const Self,
    topology: InvalidationRetryTestTopology,
) !void {
    const expected_discovery = invalidationRetryExpectedDiscovery(topology);
    try std.testing.expectEqual(expected_discovery.len, checker.hoist_invalidated_exprs.count());
    for (expected_discovery) |expr| {
        try std.testing.expect(checker.hoist_invalidated_exprs.contains(expr));
    }
    try std.testing.expect(!checker.hoist_invalidated_exprs.contains(topology.call_expr));
    try std.testing.expect(!checker.hoist_invalidated_exprs.contains(topology.before_list));
    try std.testing.expect(!checker.hoist_invalidated_exprs.contains(topology.after_list));
    try std.testing.expectEqual(@as(usize, 3), checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(@as(usize, 3), checker.hoist_selected_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_bindings.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_pattern_validations.count());
    const middle_root = checker.hoist_selected_exprs.get(topology.middle_tuple) orelse
        return error.TestUnexpectedResult;
    const before_root = checker.hoist_selected_exprs.get(topology.before_list) orelse
        return error.TestUnexpectedResult;
    const after_root = checker.hoist_selected_exprs.get(topology.after_list) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(middle_root != before_root and
        middle_root != after_root and before_root != after_root);
    try std.testing.expect(checker.hoist_invalidated_exprs.contains(
        checker.selected_hoisted_roots.items[middle_root].expr,
    ));
    try std.testing.expect(!checker.hoist_invalidated_exprs.contains(
        checker.selected_hoisted_roots.items[before_root].expr,
    ));
    try std.testing.expect(!checker.hoist_invalidated_exprs.contains(
        checker.selected_hoisted_roots.items[after_root].expr,
    ));

    const omissions = checker.cir.record_omitted_defaults.items.items;
    try std.testing.expectEqual(@as(usize, 2), omissions.len);
    try std.testing.expectEqual(topology.before_backings[0], omissions[0].expr);
    try std.testing.expectEqual(topology.after_backings[0], omissions[1].expr);
    for (omissions) |omitted| {
        try std.testing.expectEqual(@intFromEnum(topology.default_numeral), omitted.default_expr_node);
    }

    try std.testing.expectEqual(@as(usize, 3), checker.cir.store.literalDispatchPlans().len);
    try std.testing.expect(checker.cir.store.literalDispatchPlanForNode(
        ModuleEnv.nodeIdxFrom(topology.middle_numeral),
    ) == null);
    for ([_]CIR.Expr.Idx{
        topology.before_numeral,
        topology.after_numeral,
        topology.default_numeral,
    }) |owner| {
        const plan = checker.cir.store.literalDispatchPlanForNode(
            ModuleEnv.nodeIdxFrom(owner),
        ) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@intFromEnum(owner), plan.node_idx);
        try std.testing.expectEqual(can.NodeStore.LiteralDispatchPlan.Kind.numeral, plan.dispatchKind());
        try std.testing.expectEqual(can.NodeStore.LiteralDispatchPlan.Resolution.unresolved, plan.dispatchResolution());
    }
}

fn expectInvalidationRetryTerminalMetadata(
    checker: *const Self,
    topology: InvalidationRetryTestTopology,
    expected_invalidated: []const CIR.Expr.Idx,
) !void {
    try std.testing.expectEqual(expected_invalidated.len, checker.hoist_invalidated_exprs.count());
    for (expected_invalidated, 0..) |expr, index| {
        for (expected_invalidated[0..index]) |previous| {
            try std.testing.expect(expr != previous);
        }
        try std.testing.expect(checker.hoist_invalidated_exprs.contains(expr));
    }
    try std.testing.expect(!checker.hoist_invalidated_exprs.contains(topology.outer_lambda));
    try std.testing.expect(!checker.hoist_invalidated_exprs.contains(topology.default_numeral));
    try std.testing.expectEqual(@as(usize, 0), checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_bindings.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_pattern_validations.count());
    try std.testing.expectEqual(@as(usize, 0), checker.cir.record_omitted_defaults.items.items.len);

    const literal_plans = checker.cir.store.literalDispatchPlans();
    try std.testing.expectEqual(@as(usize, 1), literal_plans.len);
    try std.testing.expectEqual(@intFromEnum(topology.default_numeral), literal_plans[0].node_idx);
    try std.testing.expect(checker.cir.store.literalDispatchPlanForNode(
        ModuleEnv.nodeIdxFrom(topology.before_numeral),
    ) == null);
    try std.testing.expect(checker.cir.store.literalDispatchPlanForNode(
        ModuleEnv.nodeIdxFrom(topology.middle_numeral),
    ) == null);
    try std.testing.expect(checker.cir.store.literalDispatchPlanForNode(
        ModuleEnv.nodeIdxFrom(topology.after_numeral),
    ) == null);
    const default_plan = checker.cir.store.literalDispatchPlanForNode(
        ModuleEnv.nodeIdxFrom(topology.default_numeral),
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(literal_plans[0].node_idx, default_plan.node_idx);
    try std.testing.expectEqual(literal_plans[0].target_var, default_plan.target_var);
    try std.testing.expectEqual(literal_plans[0].fn_var, default_plan.fn_var);
    try std.testing.expectEqual(literal_plans[0].kind, default_plan.kind);
    try std.testing.expectEqual(literal_plans[0].resolution, default_plan.resolution);
    try std.testing.expectEqual(can.NodeStore.LiteralDispatchPlan.Kind.numeral, default_plan.dispatchKind());
    try std.testing.expectEqual(
        can.NodeStore.LiteralDispatchPlan.Resolution.builtin_direct,
        default_plan.dispatchResolution(),
    );

    try std.testing.expectEqual(@as(usize, 26), checker.cir.expected_consumption_plans.items.items.len);
    try std.testing.expectEqual(@as(usize, 5), checker.cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 4), checker.cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 5), checker.cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 4), checker.cir.expected_retired_consumers.items.items.len);
    try expectDirectBinderTransientListsEmpty(checker);
    try std.testing.expect(validateExpectedCallPlans(checker.cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(
        &checker.cir.types,
        checker.cir,
    ));
}

/// Resume the exact production file-check tail while the staged solver Env is
/// still borrowed from the checker pool.
fn finishInvalidationRetryFileCheck(
    test_env: anytype,
    fresh_env: anytype,
    env: *Env,
    topology: InvalidationRetryTestTopology,
    expected_invalidated: []const CIR.Expr.Idx,
) !void {
    const checker = &test_env.checker;
    try checker.checkFileFromPrePoison(env);
    try expectInvalidationRetryTerminalMetadata(checker, topology, expected_invalidated);

    const fresh_context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    _ = try checker.validatedModule();
    try validateExpectedFailureContext(checker.cir, fresh_context);
    try std.testing.expectEqual(@as(usize, 0), checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try test_env.typeProblemCount());
}

const PendingDirectBinderCallOperandTestProof = struct {
    call_expr: CIR.Expr.Idx,
    retirement_index: u32,
    root_plan_index: u32,
    root_token_index: u32,
    failure_indices: [2]u32,
    lookup_failure_indices: [2]u32,
    lookup_retirement_indices: [2]u32,
    argument_plan_indices: [2]u32,
    formal_indices: [2]u32,
    slot_token_indices: [2]u32,
    argument_sites: [2]u32,
    pattern_idx: CIR.Pattern.Idx,
    source_failure_index: u32,
    source_retirement_index: u32,
};

/// Enter exactly the production file-check phase which has authored every
/// typed relation but has not run either destructive poison sweep. The caller
/// retains the pooled solver environment until its staged completion work is
/// finished, matching `checkFileInternal`'s lifetime.
fn stageDirectBinderCallPairThroughPrePoison(test_env: anytype) !Env {
    const checker = &test_env.checker;
    checker.beginTypecheck();
    try ensureTypeStoreIsFilled(checker);
    try checker.reserveWhereAliasDeclarationPublications();
    try checker.collectHostBoundaryAnnotations();
    var env = try checker.env_pool.acquire();
    errdefer checker.env_pool.release(env);
    try checker.checkFileThroughPrePoison(false, &env);
    return env;
}

/// Recover the authentic incomplete call-retirement relation at the exact
/// pre-poison boundary. The proof follows the producer-authored plans, tokens,
/// formals, drafts, and direct-lookup causes rather than solved error state.
fn expectPendingTwoDirectBinderCallOperandFailures(
    checker: *const Self,
) !PendingDirectBinderCallOperandTestProof {
    const cir = checker.cir;
    const failures = cir.expected_failures.items.items;
    const retirements = cir.expected_consumer_retirements.items.items;
    const plans = cir.expected_consumption_plans.items.items;
    const formals = cir.expected_call_formals.items.items;
    const tokens = cir.expected_call_slot_tokens.items.items;

    try std.testing.expectEqual(@as(usize, 5), failures.len);
    try std.testing.expectEqual(@as(usize, 4), retirements.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(@as(usize, 5), checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 1), checker.aggregate_expected_retirement_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.direct_formal_failure_sources.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
    try std.testing.expect(validateExpectedCallSlotTokens(cir));

    var annotation_failure_count: usize = 0;
    var lookup_failure_count: usize = 0;
    var call_failure_count: usize = 0;
    for (failures) |failure| switch (failure.decodedKind() orelse
        return error.TestUnexpectedResult) {
        .annotation_malformed_type => annotation_failure_count += 1,
        .direct_binder_lookup_checked_error => lookup_failure_count += 1,
        .call_operand_checked_error => call_failure_count += 1,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), annotation_failure_count);
    try std.testing.expectEqual(@as(usize, 2), lookup_failure_count);
    try std.testing.expectEqual(@as(usize, 2), call_failure_count);

    const aggregate = checker.aggregate_expected_retirement_drafts.items[0];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error,
        aggregate.retired_reason,
    );
    try std.testing.expectEqual(@as(u32, 3), aggregate.plans_len);
    try std.testing.expect(rangeFits(aggregate.plans_start, aggregate.plans_len, plans.len));
    try std.testing.expect(aggregate.retirement_index < retirements.len);
    const call_expr = aggregate.owner_expr;
    const call_node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(call_expr));
    try std.testing.expectEqual(CIR.Node.Tag.expr_call, call_node.tag);
    const call = switch (cir.store.getExpr(call_expr)) {
        .e_call => |present| present,
        else => return error.TestUnexpectedResult,
    };
    const arguments = cir.store.sliceExpr(call.args);
    try std.testing.expectEqual(@as(usize, 2), arguments.len);
    try std.testing.expect(call.constraint_fn_var == null);
    try std.testing.expectEqual(
        @as(u32, 0),
        call_node.getPayload().expr_call.constraint_fn_var_plus_one,
    );
    try std.testing.expect(checker.erroneous_value_exprs.contains(call_expr));

    const retirement = retirements[aggregate.retirement_index];
    try std.testing.expectEqual(@intFromEnum(call_expr), retirement.retired_node);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.OwnerKind.expression,
        retirement.decodedOwnerKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumerRetirement.Kind.checker_rewrite_expected,
        retirement.decodedKind().?,
    );
    try std.testing.expectEqual(CIR.Node.Tag.expr_call, retirement.decodedOriginalNodeTag().?);
    const current_payload_words: [4]u32 = @bitCast(call_node.getPayload());
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&retirement.original_payload),
        std.mem.asBytes(&current_payload_words),
    );
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_len);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, retirement.rejection_owner_kind);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, retirement.rejection_owner_index);
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, retirement.rejection_subject_var);
    try std.testing.expectEqual(@as(u32, 0), retirement.reserved_0);
    try std.testing.expectEqual(@as(u32, 0), retirement.reserved_1);

    const call_snapshot = expectedCallOperandProducerSnapshotFromPayload(
        cir,
        call_node.getPayload(),
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 2), call_snapshot.args_len);
    const root_plan = plans[aggregate.plans_start];
    try std.testing.expect(expectedCallRootPlanMatchesSnapshot(cir, root_plan, call_snapshot));
    const root_token_index = expectedCallSlotTokenIndex(
        cir,
        @intFromEnum(call_expr),
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse return error.TestUnexpectedResult;
    const validated_root = ExpectedCallValidatedRoot{
        .plan_index = aggregate.plans_start,
        .plan = root_plan,
        .call = call_snapshot,
        .root_token_index = root_token_index,
    };

    var result = PendingDirectBinderCallOperandTestProof{
        .call_expr = call_expr,
        .retirement_index = aggregate.retirement_index,
        .root_plan_index = aggregate.plans_start,
        .root_token_index = root_token_index,
        .failure_indices = undefined,
        .lookup_failure_indices = undefined,
        .lookup_retirement_indices = undefined,
        .argument_plan_indices = undefined,
        .formal_indices = undefined,
        .slot_token_indices = undefined,
        .argument_sites = undefined,
        .pattern_idx = undefined,
        .source_failure_index = undefined,
        .source_retirement_index = undefined,
    };
    var exact_pattern: ?CIR.Pattern.Idx = null;
    var exact_source_failure: ?u32 = null;
    var exact_source_retirement: ?u32 = null;
    var owned_call_drafts: usize = 0;
    for (checker.annotation_expected_failure_drafts.items) |draft| {
        if (draft.owner_expr == call_expr) owned_call_drafts += 1;
    }
    try std.testing.expectEqual(@as(usize, 2), owned_call_drafts);

    for (arguments, 0..) |argument_expr, slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        const argument_plan_index = aggregate.plans_start + 1 + slot;
        result.argument_plan_indices[slot_usize] = argument_plan_index;
        result.argument_sites[slot_usize] = @intFromEnum(argument_expr);
        try std.testing.expect(expectedCallArgumentPlanIsTerminal(
            cir,
            validated_root,
            argument_plan_index,
            slot,
        ));

        const slot_token_index = expectedCallSlotTokenIndex(
            cir,
            @intFromEnum(call_expr),
            .argument,
            slot,
        ) orelse return error.TestUnexpectedResult;
        result.slot_token_indices[slot_usize] = slot_token_index;
        try std.testing.expectEqual(@intFromEnum(argument_expr), tokens[slot_token_index].site_node);

        var formal_index: ?u32 = null;
        for (formals, 0..) |formal, candidate_index| {
            if (formal.owner_node != @intFromEnum(call_expr) or formal.slot != slot) continue;
            if (formal_index != null or !expectedCallFormalMatchesValidatedRoot(
                cir,
                formal,
                validated_root,
                argument_plan_index,
                slot_token_index,
            )) return error.TestUnexpectedResult;
            formal_index = @intCast(candidate_index);
        }
        const exact_formal_index = formal_index orelse return error.TestUnexpectedResult;
        result.formal_indices[slot_usize] = exact_formal_index;

        var failure_index: ?u32 = null;
        for (checker.annotation_expected_failure_drafts.items) |draft| {
            if (draft.owner_expr != call_expr) continue;
            if (draft.producer_kind != .call_operand or
                draft.retirement_index != aggregate.retirement_index or
                draft.failure_index >= failures.len)
            {
                return error.TestUnexpectedResult;
            }
            const candidate = failures[draft.failure_index];
            if (candidate.slot != slot) continue;
            if (failure_index != null) return error.TestUnexpectedResult;
            failure_index = draft.failure_index;
        }
        const exact_failure_index = failure_index orelse return error.TestUnexpectedResult;
        result.failure_indices[slot_usize] = exact_failure_index;
        const failure = failures[exact_failure_index];
        const source_retirement = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        const expected_failure = callOperandExpectedFailure(
            call_expr,
            argument_expr,
            slot,
            argument_plan_index,
            @enumFromInt(formals[exact_formal_index].raw_formal_var),
            source_retirement.index,
        );
        try std.testing.expect(expectedFailuresEqual(failure, expected_failure));

        const lookup_failure_index = checker.directBinderLookupFailureForCallCompletion(
            source_retirement.index,
        ) orelse return error.TestUnexpectedResult;
        result.lookup_failure_indices[slot_usize] = lookup_failure_index;
        result.lookup_retirement_indices[slot_usize] = source_retirement.index;
        try std.testing.expect(expectedFailureOwningRetirement(cir, lookup_failure_index) == null);

        const lookup_retirement = retirements[source_retirement.index];
        try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, lookup_retirement.diagnostic_index);
        try std.testing.expectEqual(@as(u32, 0), lookup_retirement.expected_failures_start);
        try std.testing.expectEqual(@as(u32, 0), lookup_retirement.expected_failures_len);
        try std.testing.expect(cir.store.getExpr(argument_expr) == .e_lookup_local);
        const lookup_payload: CIR.Node.Payload = @bitCast(lookup_retirement.original_payload);
        const pattern_idx: CIR.Pattern.Idx = @enumFromInt(lookup_payload.expr_var.pattern_idx);
        if (exact_pattern) |pattern| {
            try std.testing.expectEqual(pattern, pattern_idx);
        } else {
            exact_pattern = pattern_idx;
        }
        const lookup_failure = failures[lookup_failure_index];
        const annotation_retirement = lookup_failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        const direct = lookup_failure.subject_authority.decodedDirect() orelse
            return error.TestUnexpectedResult;
        if (exact_source_failure) |source_failure| {
            try std.testing.expectEqual(source_failure, direct.local_record_index);
        } else {
            exact_source_failure = direct.local_record_index;
        }
        if (exact_source_retirement) |source_retirement_index| {
            try std.testing.expectEqual(source_retirement_index, annotation_retirement.index);
        } else {
            exact_source_retirement = annotation_retirement.index;
        }
    }
    try std.testing.expect(result.argument_sites[0] != result.argument_sites[1]);
    try std.testing.expect(result.failure_indices[0] != result.failure_indices[1]);
    try std.testing.expect(result.lookup_failure_indices[0] != result.lookup_failure_indices[1]);
    try std.testing.expect(result.lookup_retirement_indices[0] != result.lookup_retirement_indices[1]);
    result.pattern_idx = exact_pattern orelse return error.TestUnexpectedResult;
    result.source_failure_index = exact_source_failure orelse return error.TestUnexpectedResult;
    result.source_retirement_index = exact_source_retirement orelse
        return error.TestUnexpectedResult;

    const source_retirement = retirements[result.source_retirement_index];
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, source_retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), source_retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), source_retirement.expected_failures_len);
    try std.testing.expect(isExprNodeTag(cir.store.nodes.get(
        @enumFromInt(source_retirement.retired_node),
    ).tag));
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.annotation_malformed_type,
        failures[result.source_failure_index].decodedKind().?,
    );
    var source_drafts: usize = 0;
    for (checker.annotation_expected_failure_drafts.items) |draft| {
        if (draft.retirement_index != result.source_retirement_index) continue;
        try std.testing.expectEqual(source_retirement.retired_node, @intFromEnum(draft.owner_expr));
        try std.testing.expectEqual(result.source_failure_index, draft.failure_index);
        try std.testing.expectEqual(AnnotationExpectedFailureDraft.ProducerKind.annotation, draft.producer_kind);
        source_drafts += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), source_drafts);
    return result;
}

fn expectTestSlicesByteEqual(
    comptime T: type,
    expected: []const T,
    actual: []const T,
) !void {
    try std.testing.expectEqualSlices(
        u8,
        std.mem.sliceAsBytes(expected),
        std.mem.sliceAsBytes(actual),
    );
}

const DirectBinderCallCompletionLedgerSnapshot = struct {
    expected_failures: []ModuleEnv.ExpectedFailure,
    retirements: []ModuleEnv.ExpectedConsumerRetirement,
    plans: []ModuleEnv.ExpectedConsumptionPlan,
    formals: []ModuleEnv.ExpectedCallFormal,
    tokens: []ModuleEnv.ExpectedCallSlotToken,
    failure_refs: []ModuleEnv.ExpectedRetirementFailure,
    retired_consumers: []ModuleEnv.ExpectedRetiredConsumer,
    malformed_type_publications: []ModuleEnv.MalformedTypeAnnotationPublication,
    body_publications: []ModuleEnv.BodyAnnotationMalformedTypePublication,
    body_attachments: []ModuleEnv.BodyAnnotationAttachment,
    annotation_drafts: []AnnotationExpectedFailureDraft,
    aggregate_drafts: []AggregateExpectedRetirementDraft,
    value_lookups: []ValueLookupEntry,
    direct_sources: []DirectFormalFailureSource,
    active_failures: []ActiveDirectBinderFailure,
    call_tag: CIR.Node.Tag,
    call_payload: [4]u32,
    diagnostics: DirectBinderDiagnosticState,

    fn capture(
        checker: *const Self,
        call_expr: CIR.Expr.Idx,
    ) !DirectBinderCallCompletionLedgerSnapshot {
        const cir = checker.cir;
        const expected_failures = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedFailure,
            cir.expected_failures.items.items,
        );
        errdefer std.testing.allocator.free(expected_failures);
        const retirements = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedConsumerRetirement,
            cir.expected_consumer_retirements.items.items,
        );
        errdefer std.testing.allocator.free(retirements);
        const plans = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedConsumptionPlan,
            cir.expected_consumption_plans.items.items,
        );
        errdefer std.testing.allocator.free(plans);
        const formals = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedCallFormal,
            cir.expected_call_formals.items.items,
        );
        errdefer std.testing.allocator.free(formals);
        const tokens = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedCallSlotToken,
            cir.expected_call_slot_tokens.items.items,
        );
        errdefer std.testing.allocator.free(tokens);
        const failure_refs = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedRetirementFailure,
            cir.expected_retirement_failures.items.items,
        );
        errdefer std.testing.allocator.free(failure_refs);
        const retired_consumers = try std.testing.allocator.dupe(
            ModuleEnv.ExpectedRetiredConsumer,
            cir.expected_retired_consumers.items.items,
        );
        errdefer std.testing.allocator.free(retired_consumers);
        const malformed_type_publications = try std.testing.allocator.dupe(
            ModuleEnv.MalformedTypeAnnotationPublication,
            cir.malformed_type_annotation_publications.items.items,
        );
        errdefer std.testing.allocator.free(malformed_type_publications);
        const body_publications = try std.testing.allocator.dupe(
            ModuleEnv.BodyAnnotationMalformedTypePublication,
            cir.body_annotation_malformed_type_publications.items.items,
        );
        errdefer std.testing.allocator.free(body_publications);
        const body_attachments = try std.testing.allocator.dupe(
            ModuleEnv.BodyAnnotationAttachment,
            cir.body_annotation_attachments.items.items,
        );
        errdefer std.testing.allocator.free(body_attachments);
        const annotation_drafts = try std.testing.allocator.dupe(
            AnnotationExpectedFailureDraft,
            checker.annotation_expected_failure_drafts.items,
        );
        errdefer std.testing.allocator.free(annotation_drafts);
        const aggregate_drafts = try std.testing.allocator.dupe(
            AggregateExpectedRetirementDraft,
            checker.aggregate_expected_retirement_drafts.items,
        );
        errdefer std.testing.allocator.free(aggregate_drafts);
        const value_lookups = try std.testing.allocator.dupe(
            ValueLookupEntry,
            checker.value_lookup_tracking.items,
        );
        errdefer std.testing.allocator.free(value_lookups);
        const direct_sources = try std.testing.allocator.dupe(
            DirectFormalFailureSource,
            checker.direct_formal_failure_sources.items,
        );
        errdefer std.testing.allocator.free(direct_sources);
        const active_failures = try std.testing.allocator.dupe(
            ActiveDirectBinderFailure,
            checker.active_direct_binder_failures.items,
        );
        errdefer std.testing.allocator.free(active_failures);
        const diagnostics = try DirectBinderDiagnosticState.capture(cir);
        errdefer diagnostics.deinit();
        const call_node = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(call_expr));
        return .{
            .expected_failures = expected_failures,
            .retirements = retirements,
            .plans = plans,
            .formals = formals,
            .tokens = tokens,
            .failure_refs = failure_refs,
            .retired_consumers = retired_consumers,
            .malformed_type_publications = malformed_type_publications,
            .body_publications = body_publications,
            .body_attachments = body_attachments,
            .annotation_drafts = annotation_drafts,
            .aggregate_drafts = aggregate_drafts,
            .value_lookups = value_lookups,
            .direct_sources = direct_sources,
            .active_failures = active_failures,
            .call_tag = call_node.tag,
            .call_payload = @bitCast(call_node.getPayload()),
            .diagnostics = diagnostics,
        };
    }

    fn expectUnchanged(
        self: DirectBinderCallCompletionLedgerSnapshot,
        checker: *const Self,
        call_expr: CIR.Expr.Idx,
    ) !void {
        const cir = checker.cir;
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedFailure, self.expected_failures, cir.expected_failures.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedConsumerRetirement, self.retirements, cir.expected_consumer_retirements.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedConsumptionPlan, self.plans, cir.expected_consumption_plans.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedCallFormal, self.formals, cir.expected_call_formals.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedCallSlotToken, self.tokens, cir.expected_call_slot_tokens.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedRetirementFailure, self.failure_refs, cir.expected_retirement_failures.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedRetiredConsumer, self.retired_consumers, cir.expected_retired_consumers.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.MalformedTypeAnnotationPublication, self.malformed_type_publications, cir.malformed_type_annotation_publications.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.BodyAnnotationMalformedTypePublication, self.body_publications, cir.body_annotation_malformed_type_publications.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.BodyAnnotationAttachment, self.body_attachments, cir.body_annotation_attachments.items.items);
        try std.testing.expectEqualSlices(
            AnnotationExpectedFailureDraft,
            self.annotation_drafts,
            checker.annotation_expected_failure_drafts.items,
        );
        try std.testing.expectEqualSlices(
            AggregateExpectedRetirementDraft,
            self.aggregate_drafts,
            checker.aggregate_expected_retirement_drafts.items,
        );
        try std.testing.expectEqualSlices(
            ValueLookupEntry,
            self.value_lookups,
            checker.value_lookup_tracking.items,
        );
        try std.testing.expectEqualSlices(
            DirectFormalFailureSource,
            self.direct_sources,
            checker.direct_formal_failure_sources.items,
        );
        try std.testing.expectEqualSlices(
            ActiveDirectBinderFailure,
            self.active_failures,
            checker.active_direct_binder_failures.items,
        );
        const current_call = cir.store.nodes.get(ModuleEnv.nodeIdxFrom(call_expr));
        try std.testing.expectEqual(self.call_tag, current_call.tag);
        const current_payload: [4]u32 = @bitCast(current_call.getPayload());
        try std.testing.expectEqual(self.call_payload, current_payload);
        try self.diagnostics.expectUnchanged(cir);
    }

    fn expectOnlyCallCompletionChanged(
        self: DirectBinderCallCompletionLedgerSnapshot,
        checker: *const Self,
        call_expr: CIR.Expr.Idx,
        retirement_index: u32,
    ) !void {
        const cir = checker.cir;
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedFailure, self.expected_failures, cir.expected_failures.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedConsumptionPlan, self.plans, cir.expected_consumption_plans.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedCallFormal, self.formals, cir.expected_call_formals.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.ExpectedCallSlotToken, self.tokens, cir.expected_call_slot_tokens.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.MalformedTypeAnnotationPublication, self.malformed_type_publications, cir.malformed_type_annotation_publications.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.BodyAnnotationMalformedTypePublication, self.body_publications, cir.body_annotation_malformed_type_publications.items.items);
        try expectTestSlicesByteEqual(ModuleEnv.BodyAnnotationAttachment, self.body_attachments, cir.body_annotation_attachments.items.items);
        try std.testing.expectEqualSlices(ValueLookupEntry, self.value_lookups, checker.value_lookup_tracking.items);
        try std.testing.expectEqualSlices(DirectFormalFailureSource, self.direct_sources, checker.direct_formal_failure_sources.items);
        try std.testing.expectEqualSlices(ActiveDirectBinderFailure, self.active_failures, checker.active_direct_binder_failures.items);
        try std.testing.expectEqual(self.retirements.len, cir.expected_consumer_retirements.items.items.len);
        for (self.retirements, cir.expected_consumer_retirements.items.items, 0..) |before, after, index| {
            if (index == retirement_index) continue;
            try std.testing.expectEqualSlices(
                u8,
                std.mem.asBytes(&before),
                std.mem.asBytes(&after),
            );
        }
        const call_retirement = cir.expected_consumer_retirements.items.items[retirement_index];
        try std.testing.expectEqual(
            self.call_tag,
            call_retirement.decodedOriginalNodeTag() orelse
                return error.TestUnexpectedResult,
        );
        try std.testing.expectEqual(self.call_payload, call_retirement.original_payload);
        var retained_draft_index: usize = 0;
        for (self.annotation_drafts) |draft| {
            if (draft.owner_expr == call_expr) continue;
            if (retained_draft_index >= checker.annotation_expected_failure_drafts.items.len or
                !std.meta.eql(
                    draft,
                    checker.annotation_expected_failure_drafts.items[retained_draft_index],
                ))
            {
                return error.TestUnexpectedResult;
            }
            retained_draft_index += 1;
        }
        try std.testing.expectEqual(retained_draft_index, checker.annotation_expected_failure_drafts.items.len);
        try std.testing.expectEqual(@as(usize, 0), checker.aggregate_expected_retirement_drafts.items.len);
        try self.diagnostics.expectUnchanged(cir);
    }

    fn deinit(self: *DirectBinderCallCompletionLedgerSnapshot) void {
        std.testing.allocator.free(self.expected_failures);
        std.testing.allocator.free(self.retirements);
        std.testing.allocator.free(self.plans);
        std.testing.allocator.free(self.formals);
        std.testing.allocator.free(self.tokens);
        std.testing.allocator.free(self.failure_refs);
        std.testing.allocator.free(self.retired_consumers);
        std.testing.allocator.free(self.malformed_type_publications);
        std.testing.allocator.free(self.body_publications);
        std.testing.allocator.free(self.body_attachments);
        std.testing.allocator.free(self.annotation_drafts);
        std.testing.allocator.free(self.aggregate_drafts);
        std.testing.allocator.free(self.value_lookups);
        std.testing.allocator.free(self.direct_sources);
        std.testing.allocator.free(self.active_failures);
        self.diagnostics.deinit();
        self.* = undefined;
    }
};

fn expectDirectBinderCallPairInvalidationMetadataAbsent(checker: *const Self) !void {
    try std.testing.expectEqual(@as(usize, 0), checker.cir.store.literalDispatchPlans().len);
    try std.testing.expectEqual(@as(usize, 0), checker.cir.record_omitted_defaults.items.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.selected_hoisted_roots.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_bindings.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_selected_pattern_validations.count());
}

fn addCallOperandCompletionDiagnosticForTest(
    checker: *Self,
    call_expr: CIR.Expr.Idx,
) !CIR.Diagnostic.Idx {
    const diagnostic_idx = try checker.cir.addDiagnostic(.{ .erroneous_value_expr = .{
        .region = checker.cir.store.getExprRegion(call_expr),
    } });
    if (checker.cir.store.getDiagnostic(diagnostic_idx) != .erroneous_value_expr) {
        return error.TestUnexpectedResult;
    }
    return diagnostic_idx;
}

/// The dual-range call transaction may complete before either direct lookup or
/// its source annotation does. Pin that legitimate intermediate state without
/// invoking terminal replay which deliberately requires all three upstream
/// retirements to be complete.
fn expectCallOperandRetirementCompletedWhileLookupsPending(
    checker: *const Self,
    proof: PendingDirectBinderCallOperandTestProof,
    diagnostic_idx: CIR.Diagnostic.Idx,
) !void {
    const cir = checker.cir;
    const failures = cir.expected_failures.items.items;
    const retirements = cir.expected_consumer_retirements.items.items;
    const plans = cir.expected_consumption_plans.items.items;
    try std.testing.expectEqual(@as(usize, 5), failures.len);
    try std.testing.expectEqual(@as(usize, 4), retirements.len);
    try std.testing.expectEqual(@as(usize, 3), cir.expected_retired_consumers.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), checker.annotation_expected_failure_drafts.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.aggregate_expected_retirement_drafts.items.len);

    const rewritten = cir.store.getExpr(proof.call_expr);
    if (rewritten != .e_runtime_error or
        rewritten.e_runtime_error.diagnostic != diagnostic_idx)
    {
        return error.TestUnexpectedResult;
    }
    const retirement = retirements[proof.retirement_index];
    try std.testing.expect(retirement.hasLegalTags());
    try std.testing.expectEqual(@intFromEnum(proof.call_expr), retirement.retired_node);
    try std.testing.expectEqual(CIR.Node.Tag.expr_call, retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(@intFromEnum(diagnostic_idx), retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), retirement.retired_consumers_start);
    try std.testing.expectEqual(@as(u32, 3), retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 0), retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 2), retirement.expected_failures_len);
    try std.testing.expect(expectedConsumerRetirementNodeIsLocallyValid(cir, retirement));

    const call_payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    try std.testing.expectEqual(
        @as(u32, 0),
        call_payload.expr_call.constraint_fn_var_plus_one,
    );
    const call_snapshot = expectedCallOperandRetirementTopologyFromPayload(
        cir,
        call_payload,
    ) orelse return error.TestUnexpectedResult;
    const root_plan = plans[proof.root_plan_index];
    try std.testing.expect(expectedCallRootPlanMatchesSnapshot(cir, root_plan, call_snapshot));
    const validated_root = ExpectedCallValidatedRoot{
        .plan_index = proof.root_plan_index,
        .plan = root_plan,
        .call = call_snapshot,
        .root_token_index = proof.root_token_index,
    };
    const consumers = cir.expected_retired_consumers.items.items;
    for (consumers, 0..) |consumer, consumer_index| {
        try std.testing.expectEqual(
            ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error,
            consumer.decodedReason().?,
        );
        if (consumer_index == 0) {
            try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.call_root, consumer.decodedRole().?);
            try std.testing.expectEqual(proof.root_plan_index, consumer.plan_index);
            try std.testing.expectEqual(root_plan.site_node, consumer.site_node);
        } else {
            const slot_usize = consumer_index - 1;
            const slot: u32 = @intCast(slot_usize);
            try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.call_argument, consumer.decodedRole().?);
            try std.testing.expectEqual(slot, consumer.slot);
            try std.testing.expectEqual(proof.argument_plan_indices[slot_usize], consumer.plan_index);
            try std.testing.expectEqual(proof.argument_sites[slot_usize], consumer.site_node);
            try std.testing.expect(expectedCallArgumentPlanIsTerminal(
                cir,
                validated_root,
                consumer.plan_index,
                slot,
            ));
        }
    }
    const references = cir.expected_retirement_failures.items.items;
    try std.testing.expectEqual(proof.failure_indices[0], references[0].failure_index);
    try std.testing.expectEqual(proof.failure_indices[1], references[1].failure_index);
    try std.testing.expect(expectedFailureKeyLessThan(
        failures,
        references[0].failure_index,
        references[1].failure_index,
    ));

    for (0..2) |slot| {
        const lookup_retirement = retirements[proof.lookup_retirement_indices[slot]];
        try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, lookup_retirement.diagnostic_index);
        try std.testing.expectEqual(@as(u32, 0), lookup_retirement.expected_failures_start);
        try std.testing.expectEqual(@as(u32, 0), lookup_retirement.expected_failures_len);
        try std.testing.expect(cir.store.getExpr(@enumFromInt(
            proof.argument_sites[slot],
        )) == .e_lookup_local);
        const lookup_failure_index = checker.directBinderLookupFailureForCallCompletion(
            proof.lookup_retirement_indices[slot],
        ) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(
            proof.lookup_failure_indices[slot],
            lookup_failure_index,
        );
    }
    const source_retirement = retirements[proof.source_retirement_index];
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumerRetirement.none, source_retirement.diagnostic_index);
    try std.testing.expectEqual(@as(u32, 0), source_retirement.expected_failures_start);
    try std.testing.expectEqual(@as(u32, 0), source_retirement.expected_failures_len);
    for (checker.annotation_expected_failure_drafts.items) |draft| {
        try std.testing.expect(draft.owner_expr != proof.call_expr);
    }
    try std.testing.expectEqual(@as(usize, 0), checker.direct_formal_failure_sources.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.active_direct_binder_failures.items.len);
}

const DirectBinderCallOperandTestProof = struct {
    retirement_index: u32,
    root_plan_index: u32,
    root_token_index: u32,
    failure_indices: [2]u32,
    lookup_failure_indices: [2]u32,
    lookup_retirement_indices: [2]u32,
    argument_plan_indices: [2]u32,
    formal_indices: [2]u32,
    slot_token_indices: [2]u32,
    argument_sites: [2]u32,
    pattern_idx: CIR.Pattern.Idx,
    source_retirement_index: u32,
};

/// Test-only extraction of the complete authentic one-call/two-direct-operand
/// recovery relation. Every index is recovered through the durable inverse it
/// participates in; no solved error bit or row adjacency selects authority.
fn expectTwoDirectBinderCallOperandFailures(
    cir: *const ModuleEnv,
) !DirectBinderCallOperandTestProof {
    const failures = cir.expected_failures.items.items;
    const retirements = cir.expected_consumer_retirements.items.items;
    const failure_refs = cir.expected_retirement_failures.items.items;
    const retired_consumers = cir.expected_retired_consumers.items.items;
    const plans = cir.expected_consumption_plans.items.items;
    const formals = cir.expected_call_formals.items.items;
    const tokens = cir.expected_call_slot_tokens.items.items;

    try std.testing.expectEqual(@as(usize, 5), failures.len);
    try std.testing.expectEqual(@as(usize, 4), retirements.len);
    try std.testing.expectEqual(@as(usize, 5), failure_refs.len);
    try std.testing.expectEqual(@as(usize, 3), retired_consumers.len);

    var annotation_failure_count: usize = 0;
    var lookup_failure_count: usize = 0;
    var call_failure_count: usize = 0;
    for (failures) |failure| switch (failure.decodedKind() orelse
        return error.TestUnexpectedResult) {
        .annotation_malformed_type => annotation_failure_count += 1,
        .direct_binder_lookup_checked_error => lookup_failure_count += 1,
        .call_operand_checked_error => call_failure_count += 1,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), annotation_failure_count);
    try std.testing.expectEqual(@as(usize, 2), lookup_failure_count);
    try std.testing.expectEqual(@as(usize, 2), call_failure_count);

    var retirement_index: ?u32 = null;
    var snapshot: ?ExpectedCallOperandRetirementSnapshot = null;
    for (retirements, 0..) |_, candidate_index| {
        const candidate = expectedCallOperandRetirementSnapshot(
            &cir.types,
            cir,
            @intCast(candidate_index),
        ) orelse continue;
        if (retirement_index != null) return error.TestUnexpectedResult;
        retirement_index = @intCast(candidate_index);
        snapshot = candidate;
    }
    const exact_retirement_index = retirement_index orelse
        return error.TestUnexpectedResult;
    const exact_snapshot = snapshot orelse return error.TestUnexpectedResult;
    const retirement = retirements[exact_retirement_index];
    try std.testing.expectEqual(@as(u32, 2), exact_snapshot.call.args_len);
    try std.testing.expectEqual(@as(u32, 3), retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 2), retirement.expected_failures_len);
    try std.testing.expectEqual(CIR.Node.Tag.expr_call, retirement.decodedOriginalNodeTag().?);
    const original_payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    try std.testing.expectEqual(
        @as(u32, 0),
        original_payload.expr_call.constraint_fn_var_plus_one,
    );
    try std.testing.expect(cir.store.getExpr(@enumFromInt(retirement.retired_node)) ==
        .e_runtime_error);
    try std.testing.expect(cir.store.getDiagnostic(@enumFromInt(retirement.diagnostic_index)) ==
        .erroneous_value_expr);

    const root_token_index = expectedCallSlotTokenIndex(
        cir,
        retirement.retired_node,
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse return error.TestUnexpectedResult;
    const root_token = tokens[root_token_index];
    try std.testing.expectEqual(exact_snapshot.call.func, root_token.site_node);
    try std.testing.expectEqual(@as(u32, 2), root_token.cardinality);
    const root_plan = plans[exact_snapshot.root_plan_index];
    const validated_root = ExpectedCallValidatedRoot{
        .plan_index = exact_snapshot.root_plan_index,
        .plan = root_plan,
        .call = exact_snapshot.call,
        .root_token_index = root_token_index,
    };

    const consumers = retired_consumers[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
    try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.call_root, consumers[0].decodedRole().?);
    try std.testing.expectEqual(exact_snapshot.root_plan_index, consumers[0].plan_index);
    try std.testing.expectEqual(
        ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error,
        consumers[0].decodedReason().?,
    );

    var result = DirectBinderCallOperandTestProof{
        .retirement_index = exact_retirement_index,
        .root_plan_index = exact_snapshot.root_plan_index,
        .root_token_index = root_token_index,
        .failure_indices = undefined,
        .lookup_failure_indices = undefined,
        .lookup_retirement_indices = undefined,
        .argument_plan_indices = undefined,
        .formal_indices = undefined,
        .slot_token_indices = undefined,
        .argument_sites = undefined,
        .pattern_idx = undefined,
        .source_retirement_index = undefined,
    };
    var populated_slots = [_]bool{false} ** 2;
    var exact_pattern: ?CIR.Pattern.Idx = null;
    var exact_source_retirement: ?u32 = null;
    for (0..2) |slot_usize| {
        const slot: u32 = @intCast(slot_usize);
        const consumer = consumers[slot_usize + 1];
        try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Role.call_argument, consumer.decodedRole().?);
        try std.testing.expectEqual(slot, consumer.slot);
        try std.testing.expectEqual(
            ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error,
            consumer.decodedReason().?,
        );
        result.argument_plan_indices[slot_usize] = consumer.plan_index;
        result.argument_sites[slot_usize] = cir.store.index_data.items.items[
            exact_snapshot.call.args_start + slot
        ];
        try std.testing.expectEqual(result.argument_sites[slot_usize], consumer.site_node);
        try std.testing.expect(expectedCallArgumentPlanIsTerminal(
            cir,
            validated_root,
            consumer.plan_index,
            slot,
        ));

        const slot_token_index = expectedCallSlotTokenIndex(
            cir,
            retirement.retired_node,
            .argument,
            slot,
        ) orelse return error.TestUnexpectedResult;
        result.slot_token_indices[slot_usize] = slot_token_index;
        const slot_token = tokens[slot_token_index];
        try std.testing.expectEqual(result.argument_sites[slot_usize], slot_token.site_node);
        try std.testing.expectEqual(@as(u32, 2), slot_token.cardinality);

        var formal_index: ?u32 = null;
        for (formals, 0..) |formal, candidate_index| {
            if (formal.owner_node != retirement.retired_node or formal.slot != slot) continue;
            if (formal_index != null) return error.TestUnexpectedResult;
            formal_index = @intCast(candidate_index);
            try std.testing.expect(expectedCallFormalMatchesValidatedRoot(
                cir,
                formal,
                validated_root,
                consumer.plan_index,
                slot_token_index,
            ));
        }
        const exact_formal_index = formal_index orelse return error.TestUnexpectedResult;
        result.formal_indices[slot_usize] = exact_formal_index;

        var failure_index: ?u32 = null;
        const owned_failure_refs = failure_refs[retirement.expected_failures_start..][0..retirement.expected_failures_len];
        for (owned_failure_refs) |reference| {
            const failure = failures[reference.failure_index];
            if (failure.slot != slot) continue;
            if (failure_index != null) return error.TestUnexpectedResult;
            failure_index = reference.failure_index;
        }
        const exact_failure_index = failure_index orelse return error.TestUnexpectedResult;
        const failure = failures[exact_failure_index];
        result.failure_indices[slot_usize] = exact_failure_index;
        populated_slots[slot_usize] = true;
        try std.testing.expectEqual(result.argument_sites[slot_usize], failure.site_node);
        try std.testing.expectEqual(result.argument_sites[slot_usize], failure.raw_peer_var);
        try std.testing.expectEqual(retirement.retired_node, failure.owner_node);
        try std.testing.expectEqual(retirement.retired_node, failure.raw_owner_var);
        try std.testing.expectEqual(consumer.plan_index, failure.plan_index);
        const subject = failure.subject_authority.decodedExpectedProducerRootPlan() orelse
            return error.TestUnexpectedResult;
        try std.testing.expectEqual(consumer.plan_index, subject.plan_index);
        try std.testing.expectEqual(failure.raw_subject_var, subject.raw_var);
        try std.testing.expectEqual(
            formals[exact_formal_index].raw_formal_var,
            failure.raw_subject_var,
        );
        try std.testing.expect(callOperandExpectedFailureIsLocallyValid(
            &cir.types,
            cir,
            failure,
            exact_failure_index,
            subject,
        ));

        const lookup_retirement = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        result.lookup_retirement_indices[slot_usize] = lookup_retirement.index;
        try std.testing.expectEqual(
            failure.site_node,
            retirements[lookup_retirement.index].retired_node,
        );
        const lookup_failure_index = completedDirectBinderLookupFailureForRetirement(
            cir,
            lookup_retirement.index,
        ) orelse return error.TestUnexpectedResult;
        result.lookup_failure_indices[slot_usize] = lookup_failure_index;
        const lookup_failure = failures[lookup_failure_index];
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.direct_binder_lookup_checked_error,
            lookup_failure.decodedKind().?,
        );
        try std.testing.expectEqual(failure.site_node, lookup_failure.owner_node);
        const direct = lookup_failure.subject_authority.decodedDirect() orelse
            return error.TestUnexpectedResult;
        try std.testing.expect(directBinderLookupExpectedFailureIsLocallyValid(
            &cir.types,
            cir,
            lookup_failure,
            lookup_failure_index,
            direct,
        ));
        const lookup_snapshot = expectedLookupRetirementOwningFailure(
            cir,
            lookup_failure_index,
        ) orelse return error.TestUnexpectedResult;
        if (exact_pattern) |pattern| {
            try std.testing.expectEqual(pattern, lookup_snapshot.pattern_idx);
        } else {
            exact_pattern = lookup_snapshot.pattern_idx;
        }
        const source_retirement = lookup_failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        if (exact_source_retirement) |source| {
            try std.testing.expectEqual(source, source_retirement.index);
        } else {
            exact_source_retirement = source_retirement.index;
        }
    }
    try std.testing.expect(populated_slots[0] and populated_slots[1]);
    try std.testing.expect(result.failure_indices[0] != result.failure_indices[1]);
    try std.testing.expect(result.lookup_failure_indices[0] != result.lookup_failure_indices[1]);
    try std.testing.expect(result.lookup_retirement_indices[0] != result.lookup_retirement_indices[1]);
    result.pattern_idx = exact_pattern orelse return error.TestUnexpectedResult;
    result.source_retirement_index = exact_source_retirement orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(expectedCallOperandRetirementIsLocallyValid(
        &cir.types,
        cir,
        exact_retirement_index,
    ));
    try std.testing.expect(validateExpectedCallPlans(cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    return result;
}

fn callOperandCandidateIsLocallyValid(cir: *const ModuleEnv) bool {
    return validateExpectedCallPlans(cir) and
        validateExpectedFailureRetirementLocal(&cir.types, cir);
}

fn callOperandCandidateMatchesFresh(
    cir: *const ModuleEnv,
    context: ImportResolution,
) bool {
    validateExpectedFailureContext(cir, context) catch return false;
    return true;
}

fn finishDirectBinderCallPairAfterCallCompletion(
    test_env: anytype,
    fresh_env: anytype,
) !DirectBinderCallOperandTestProof {
    const checker = &test_env.checker;
    try checker.poisonErroneousValueUses();
    try checker.poisonErroneousValueExprs();
    try checker.finalizeDefaultDecisionDrafts();
    try checker.finalizeWhereAliasExpansions();
    try checker.rebuildCheckedBoundaryWhereMethodState();
    try expectDirectBinderTransientListsEmpty(checker);
    const proof = try expectTwoDirectBinderCallOperandFailures(checker.cir);
    const produced_context = ImportResolution.producedSupplied(
        checker.cir,
        .{ .envs = checker.imported_modules, .modules = checker.validated_imported_modules },
        .{ .envs = checker.owner_modules, .modules = checker.validated_owner_modules },
        checker.platform_dependency_index,
    );
    const fresh_context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try validateExpectedFailureContext(checker.cir, produced_context);
    try validateExpectedFailureContext(checker.cir, fresh_context);
    const once = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(once);
    try checker.rebuildCheckedBoundaryWhereMethodState();
    try expectDirectBinderTransientListsEmpty(checker);
    _ = try expectTwoDirectBinderCallOperandFailures(checker.cir);
    try validateExpectedFailureContext(checker.cir, produced_context);
    try validateExpectedFailureContext(checker.cir, fresh_context);
    const twice = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(twice);
    try std.testing.expectEqualSlices(u8, once, twice);
    try std.testing.expectEqual(@as(usize, 0), checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try test_env.typeProblemCount());
    return proof;
}

test "invalid where alias retires two direct call operands and rebuilds exactly" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("two-operand direct-binder call fixture failed at {s}\n", .{failure_stage});
    var provider = try TestEnv.init(
        "DirectBinderCallPairA",
        direct_binder_call_pair_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    failure_stage = "consumer initialization";
    var consumer = try TestEnv.initWithImport(
        "DirectBinderCallPairB",
        direct_binder_call_pair_consumer_source,
        "DirectBinderCallPairA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderCallPairB",
        direct_binder_call_pair_consumer_source,
        "DirectBinderCallPairA",
        &provider,
    );
    defer fresh_env.deinit();
    failure_stage = "diagnostics";
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
    try expectDirectBinderTransientListsEmpty(&consumer.checker);

    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    const produced_context = ImportResolution.producedSupplied(
        consumer.module_env,
        .{ .envs = consumer.checker.imported_modules, .modules = consumer.checker.validated_imported_modules },
        .{ .envs = consumer.checker.owner_modules, .modules = consumer.checker.validated_owner_modules },
        consumer.checker.platform_dependency_index,
    );
    failure_stage = "durable relation";
    const before = try expectTwoDirectBinderCallOperandFailures(consumer.module_env);
    try validateExpectedFailureContext(consumer.module_env, produced_context);
    try validateExpectedFailureContext(consumer.module_env, context);

    // The production index builder coalesces an exact repeated tracking row
    // without selecting a new authority or publishing any durable evidence.
    failure_stage = "tracking revisit";
    const tracking_len = consumer.checker.value_lookup_tracking.items.len;
    const duplicate_entry_index: usize = for (consumer.checker.value_lookup_tracking.items, 0..) |entry, entry_index| {
        if (@intFromEnum(entry.expr_idx) == before.argument_sites[0]) break entry_index;
    } else return error.TestUnexpectedResult;
    const duplicate_entry = consumer.checker.value_lookup_tracking.items[duplicate_entry_index];
    const failures_before_duplicate = consumer.module_env.expected_failures.items.items.len;
    const retirements_before_duplicate = consumer.module_env.expected_consumer_retirements.items.items.len;
    const references_before_duplicate = consumer.module_env.expected_retirement_failures.items.items.len;
    const first_entries = try std.testing.allocator.alloc(
        u32,
        consumer.module_env.store.nodes.len(),
    );
    defer std.testing.allocator.free(first_entries);
    try consumer.checker.buildValidatedValueLookupEntryIndex(first_entries);
    const selected_before_duplicate = first_entries[before.argument_sites[0]];
    try consumer.checker.value_lookup_tracking.append(consumer.checker.gpa, duplicate_entry);
    defer consumer.checker.value_lookup_tracking.items.len = tracking_len;
    try consumer.checker.buildValidatedValueLookupEntryIndex(first_entries);
    try std.testing.expectEqual(
        selected_before_duplicate,
        first_entries[before.argument_sites[0]],
    );
    try std.testing.expectEqual(failures_before_duplicate, consumer.module_env.expected_failures.items.items.len);
    try std.testing.expectEqual(retirements_before_duplicate, consumer.module_env.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(references_before_duplicate, consumer.module_env.expected_retirement_failures.items.items.len);
    consumer.checker.value_lookup_tracking.items.len = tracking_len;
    const serialized_before = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        consumer.module_env,
    );
    defer std.testing.allocator.free(serialized_before);

    failure_stage = "first rebuild";
    try consumer.checker.rebuildCheckedBoundaryWhereMethodState();
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    const after_first = try expectTwoDirectBinderCallOperandFailures(consumer.module_env);
    try validateExpectedFailureContext(consumer.module_env, produced_context);
    try validateExpectedFailureContext(consumer.module_env, context);
    const serialized_after_first = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        consumer.module_env,
    );
    defer std.testing.allocator.free(serialized_after_first);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after_first);
    try std.testing.expectEqual(before.retirement_index, after_first.retirement_index);
    try std.testing.expectEqual(before.root_plan_index, after_first.root_plan_index);
    try std.testing.expectEqual(before.failure_indices, after_first.failure_indices);
    try std.testing.expectEqual(before.lookup_failure_indices, after_first.lookup_failure_indices);
    try std.testing.expectEqual(before.lookup_retirement_indices, after_first.lookup_retirement_indices);
    try std.testing.expectEqual(before.argument_plan_indices, after_first.argument_plan_indices);
    try std.testing.expectEqual(before.formal_indices, after_first.formal_indices);
    try std.testing.expectEqual(before.slot_token_indices, after_first.slot_token_indices);
    try std.testing.expectEqual(before.argument_sites, after_first.argument_sites);

    failure_stage = "second rebuild";
    try consumer.checker.rebuildCheckedBoundaryWhereMethodState();
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    const after_second = try expectTwoDirectBinderCallOperandFailures(consumer.module_env);
    try validateExpectedFailureContext(consumer.module_env, produced_context);
    try validateExpectedFailureContext(consumer.module_env, context);
    const serialized_after_second = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        consumer.module_env,
    );
    defer std.testing.allocator.free(serialized_after_second);
    try std.testing.expectEqualSlices(u8, serialized_before, serialized_after_second);
    try std.testing.expectEqual(after_first.retirement_index, after_second.retirement_index);
    try std.testing.expectEqual(after_first.failure_indices, after_second.failure_indices);
    try std.testing.expectEqual(after_first.argument_plan_indices, after_second.argument_plan_indices);
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
}

test "direct call operand retirement rejects incomplete and retargeted relations" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("direct-binder call corruption fixture failed at {s}\n", .{failure_stage});
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderCallCorruptA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import DirectBinderCallCorruptA exposing [Status]
        \\
        \\first : a -> a where [a.Status]
        \\first = |value| (|left, _right| left)(value, value)
    ;
    failure_stage = "consumer initialization";
    var consumer = try TestEnv.initWithImport(
        "DirectBinderCallCorruptB",
        consumer_source,
        "DirectBinderCallCorruptA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderCallCorruptB",
        consumer_source,
        "DirectBinderCallCorruptA",
        &provider,
    );
    defer fresh_env.deinit();
    failure_stage = "baseline";
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
    const cir = consumer.module_env;
    const proof = try expectTwoDirectBinderCallOperandFailures(cir);
    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try validateExpectedFailureContext(cir, context);

    const retirements = cir.expected_consumer_retirements.items.items;
    const references = cir.expected_retirement_failures.items.items;
    const consumers = cir.expected_retired_consumers.items.items;
    const failures = cir.expected_failures.items.items;
    const plans = cir.expected_consumption_plans.items.items;
    const formals = cir.expected_call_formals.items.items;
    const retirement = &retirements[proof.retirement_index];
    const reference_range = references[retirement.expected_failures_start..][0..retirement.expected_failures_len];
    const consumer_range = consumers[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];

    // Dropping either direction of either owned range must not leave a
    // plausible nonempty retirement certificate.
    failure_stage = "missing and duplicate ranges";
    const saved_retirement = retirement.*;
    retirement.expected_failures_len = 1;
    const missing_failure_local = callOperandCandidateIsLocallyValid(cir);
    const missing_failure_fresh = callOperandCandidateMatchesFresh(cir, context);
    retirement.* = saved_retirement;
    try std.testing.expect(!missing_failure_local);
    try std.testing.expect(!missing_failure_fresh);

    // Remove the terminal F_C and its terminal owned reference together while
    // retaining the completed R_L/F_L at that exact argument. The scalar R_C
    // snapshot remains locally well-formed; only the explicit R_L-to-F_C
    // converse can reject the coordinated omission.
    const omitted_failure_index = @max(proof.failure_indices[0], proof.failure_indices[1]);
    if (@as(usize, omitted_failure_index) + 1 != cir.expected_failures.items.items.len or
        @as(usize, retirement.expected_failures_start) +
            @as(usize, retirement.expected_failures_len) !=
            cir.expected_retirement_failures.items.items.len or
        cir.expected_retirement_failures.items.items[
            cir.expected_retirement_failures.items.items.len - 1
        ].failure_index != omitted_failure_index)
    {
        return error.TestUnexpectedResult;
    }
    const failure_pool_len = cir.expected_failures.items.items.len;
    const reference_pool_len = cir.expected_retirement_failures.items.items.len;
    cir.expected_failures.items.items.len = failure_pool_len - 1;
    cir.expected_retirement_failures.items.items.len = reference_pool_len - 1;
    retirement.expected_failures_len -= 1;
    const omitted_failure_basic = expectedCallOperandRetirementSnapshot(
        &cir.types,
        cir,
        proof.retirement_index,
    ) != null;
    const omitted_failure_complete = expectedCallOperandRetirementIsLocallyValid(
        &cir.types,
        cir,
        proof.retirement_index,
    );
    const omitted_failure_local = callOperandCandidateIsLocallyValid(cir);
    cir.expected_failures.items.items.len = failure_pool_len;
    cir.expected_retirement_failures.items.items.len = reference_pool_len;
    retirement.* = saved_retirement;
    try std.testing.expect(omitted_failure_basic);
    try std.testing.expect(!omitted_failure_complete);
    try std.testing.expect(!omitted_failure_local);

    retirement.retired_consumers_len = 2;
    const missing_consumer_local = callOperandCandidateIsLocallyValid(cir);
    const missing_consumer_fresh = callOperandCandidateMatchesFresh(cir, context);
    retirement.* = saved_retirement;
    try std.testing.expect(!missing_consumer_local);
    try std.testing.expect(!missing_consumer_fresh);

    const saved_second_reference = reference_range[1];
    reference_range[1] = reference_range[0];
    const duplicate_failure_local = callOperandCandidateIsLocallyValid(cir);
    const duplicate_failure_fresh = callOperandCandidateMatchesFresh(cir, context);
    reference_range[1] = saved_second_reference;
    try std.testing.expect(!duplicate_failure_local);
    try std.testing.expect(!duplicate_failure_fresh);

    const saved_second_consumer = consumer_range[1];
    consumer_range[1] = consumer_range[0];
    const duplicate_consumer_local = callOperandCandidateIsLocallyValid(cir);
    const duplicate_consumer_fresh = callOperandCandidateMatchesFresh(cir, context);
    consumer_range[1] = saved_second_consumer;
    try std.testing.expect(!duplicate_consumer_local);
    try std.testing.expect(!duplicate_consumer_fresh);

    // The ambiguity-owned `.call_retired` reason is legal for the same roles,
    // but it cannot substitute for this operand-caused retirement.
    const saved_argument_consumer = consumer_range[1];
    consumer_range[1].reason = @intFromEnum(
        ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired,
    );
    const ambiguity_reason_local = callOperandCandidateIsLocallyValid(cir);
    const ambiguity_reason_fresh = callOperandCandidateMatchesFresh(cir, context);
    consumer_range[1] = saved_argument_consumer;
    try std.testing.expect(!ambiguity_reason_local);
    try std.testing.expect(!ambiguity_reason_fresh);

    // Keep all call-slot fields self-consistent with the sibling while leaving
    // the original lookup cause in place. The exact site-to-cause inverse must
    // reject this coordinated, same-shaped retarget.
    failure_stage = "failure identity and causes";
    const first_failure_index = proof.failure_indices[0];
    const second_failure_index = proof.failure_indices[1];
    const saved_first_failure = failures[first_failure_index];
    const second_failure = failures[second_failure_index];
    failures[first_failure_index].site_node = second_failure.site_node;
    failures[first_failure_index].raw_peer_var = second_failure.raw_peer_var;
    failures[first_failure_index].slot = second_failure.slot;
    failures[first_failure_index].plan_index = second_failure.plan_index;
    failures[first_failure_index].raw_subject_var = second_failure.raw_subject_var;
    failures[first_failure_index].subject_authority = second_failure.subject_authority;
    const sibling_failure_tags = failures[first_failure_index].hasLegalTagsAt(first_failure_index);
    const sibling_failure_local = callOperandCandidateIsLocallyValid(cir);
    const sibling_failure_fresh = callOperandCandidateMatchesFresh(cir, context);
    failures[first_failure_index] = saved_first_failure;
    try std.testing.expect(sibling_failure_tags);
    try std.testing.expect(!sibling_failure_local);
    try std.testing.expect(!sibling_failure_fresh);

    failures[first_failure_index].cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(
        proof.lookup_retirement_indices[1],
    );
    const sibling_cause_tags = failures[first_failure_index].hasLegalTagsAt(first_failure_index);
    const sibling_cause_local = callOperandCandidateIsLocallyValid(cir);
    const sibling_cause_fresh = callOperandCandidateMatchesFresh(cir, context);
    failures[first_failure_index] = saved_first_failure;
    try std.testing.expect(sibling_cause_tags);
    try std.testing.expect(!sibling_cause_local);
    try std.testing.expect(!sibling_cause_fresh);

    // A call failure cannot cite its own R_C as if it were the completed
    // direct-lookup R_L for this argument.
    failures[first_failure_index].cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(
        proof.retirement_index,
    );
    const cyclic_failure_tags = failures[first_failure_index].hasLegalTagsAt(first_failure_index);
    const cyclic_failure_local = callOperandCandidateIsLocallyValid(cir);
    const cyclic_failure_fresh = callOperandCandidateMatchesFresh(cir, context);
    failures[first_failure_index] = saved_first_failure;
    try std.testing.expect(cyclic_failure_tags);
    try std.testing.expect(!cyclic_failure_local);
    try std.testing.expect(!cyclic_failure_fresh);

    const first_formal_index = proof.formal_indices[0];
    const saved_first_formal = formals[first_formal_index];
    formals[first_formal_index].raw_formal_var = formals[proof.formal_indices[1]].raw_formal_var;
    const sibling_formal_tags = formals[first_formal_index].hasCanonicalTags();
    const sibling_formal_local = callOperandCandidateIsLocallyValid(cir);
    const sibling_formal_fresh = callOperandCandidateMatchesFresh(cir, context);
    formals[first_formal_index] = saved_first_formal;
    try std.testing.expect(sibling_formal_tags);
    try std.testing.expect(!sibling_formal_local);
    try std.testing.expect(!sibling_formal_fresh);

    // Successful producer-root plans remain unchanged while R_C retires their
    // consumers. A legal same-node checked-error plan is not interchangeable.
    failure_stage = "successful plan preservation";
    const saved_root_plan = plans[proof.root_plan_index];
    plans[proof.root_plan_index].outcome = @intFromEnum(
        ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error,
    );
    plans[proof.root_plan_index].reason = @intFromEnum(
        ModuleEnv.ExpectedConsumptionPlan.Reason.call_retired_after_operand_checked_error,
    );
    plans[proof.root_plan_index].failure_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(
        proof.retirement_index,
    );
    const changed_root_tags = plans[proof.root_plan_index].hasLegalTags();
    const changed_root_local = callOperandCandidateIsLocallyValid(cir);
    const changed_root_fresh = callOperandCandidateMatchesFresh(cir, context);
    plans[proof.root_plan_index] = saved_root_plan;
    try std.testing.expect(changed_root_tags);
    try std.testing.expect(!changed_root_local);
    try std.testing.expect(!changed_root_fresh);

    const first_argument_plan_index = proof.argument_plan_indices[0];
    const saved_first_argument_plan = plans[first_argument_plan_index];
    plans[first_argument_plan_index].outcome = @intFromEnum(
        ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error,
    );
    plans[first_argument_plan_index].reason = @intFromEnum(
        ModuleEnv.ExpectedConsumptionPlan.Reason.call_operand_checked_error,
    );
    plans[first_argument_plan_index].call_root_plan_index =
        ModuleEnv.ExpectedConsumptionPlan.none;
    plans[first_argument_plan_index].parent_authority = .{
        .kind = @intFromEnum(ModuleEnv.ExpectedMarkerAuthority.Kind.producer_root_plan),
        .payload = .{ .producer_root_plan = .{
            .plan_index = proof.root_plan_index,
            .raw_var = plans[proof.root_plan_index].raw_consumer_var,
        } },
    };
    plans[first_argument_plan_index].failure_owner =
        ModuleEnv.CauseOwner.expectedConsumerRetirement(
            proof.lookup_retirement_indices[0],
        );
    const changed_argument_tags = plans[first_argument_plan_index].hasLegalTags();
    const changed_argument_local = callOperandCandidateIsLocallyValid(cir);
    const changed_argument_fresh = callOperandCandidateMatchesFresh(cir, context);
    plans[first_argument_plan_index] = saved_first_argument_plan;
    try std.testing.expect(changed_argument_tags);
    try std.testing.expect(!changed_argument_local);
    try std.testing.expect(!changed_argument_fresh);

    failure_stage = "original payload";
    var changed_payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    changed_payload.expr_call.constraint_fn_var_plus_one = 1;
    retirement.original_payload = @bitCast(changed_payload);
    const stamped_local = callOperandCandidateIsLocallyValid(cir);
    const stamped_fresh = callOperandCandidateMatchesFresh(cir, context);
    retirement.* = saved_retirement;
    try std.testing.expect(!stamped_local);
    try std.testing.expect(!stamped_fresh);

    changed_payload = @bitCast(retirement.original_payload);
    changed_payload.expr_call.called_via = @intFromEnum(base.CalledVia.record_builder);
    retirement.original_payload = @bitCast(changed_payload);
    const called_via_local = callOperandCandidateIsLocallyValid(cir);
    const called_via_fresh = callOperandCandidateMatchesFresh(cir, context);
    retirement.* = saved_retirement;
    try std.testing.expect(!called_via_local);
    try std.testing.expect(!called_via_fresh);

    changed_payload = @bitCast(retirement.original_payload);
    changed_payload.expr_call.func = proof.argument_sites[0];
    retirement.original_payload = @bitCast(changed_payload);
    const callee_site_local = callOperandCandidateIsLocallyValid(cir);
    const callee_site_fresh = callOperandCandidateMatchesFresh(cir, context);
    retirement.* = saved_retirement;
    try std.testing.expect(!callee_site_local);
    try std.testing.expect(!callee_site_fresh);

    try std.testing.expect(callOperandCandidateIsLocallyValid(cir));
    try std.testing.expect(callOperandCandidateMatchesFresh(cir, context));
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
}

test "invalid where alias call operand dual-range completion is atomic across OOM" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    var injected_failure_index: usize = std.math.maxInt(usize);
    errdefer std.debug.print(
        "call operand dual-range OOM fixture failed at {s}, allocation {d}\n",
        .{ failure_stage, injected_failure_index },
    );

    var provider = try TestEnv.init(
        "DirectBinderCallPairA",
        direct_binder_call_pair_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderCallPairB",
        direct_binder_call_pair_consumer_source,
        "DirectBinderCallPairA",
        &provider,
    );
    defer fresh_env.deinit();

    failure_stage = "calibration staging";
    var calibration_consumer = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderCallPairB",
        direct_binder_call_pair_consumer_source,
        "DirectBinderCallPairA",
        &provider,
    );
    defer calibration_consumer.deinit();
    try calibration_consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const calibration_env = try stageDirectBinderCallPairThroughPrePoison(
        &calibration_consumer,
    );
    defer calibration_consumer.checker.env_pool.release(calibration_env);
    const calibration_checker = &calibration_consumer.checker;
    const calibration_cir = calibration_consumer.module_env;
    const calibration_proof = try expectPendingTwoDirectBinderCallOperandFailures(
        calibration_checker,
    );
    try expectDirectBinderCallPairInvalidationMetadataAbsent(calibration_checker);
    try std.testing.expectEqual(@as(usize, 0), calibration_cir.expected_retired_consumers.items.capacity);
    try std.testing.expectEqual(@as(usize, 0), calibration_cir.expected_retirement_failures.items.capacity);
    const calibration_diagnostic = try addCallOperandCompletionDiagnosticForTest(
        calibration_checker,
        calibration_proof.call_expr,
    );
    var calibration_snapshot = try DirectBinderCallCompletionLedgerSnapshot.capture(
        calibration_checker,
        calibration_proof.call_expr,
    );
    defer calibration_snapshot.deinit();
    const calibration_pending = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        calibration_cir,
    );
    defer std.testing.allocator.free(calibration_pending);

    failure_stage = "calibration completion";
    var calibration_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const calibration_gpa = calibration_allocator.allocator();
    const allocation_base = calibration_allocator.alloc_index;
    calibration_allocator.resize_fail_index = calibration_allocator.resize_index;
    {
        const saved_checker_gpa = calibration_checker.gpa;
        const saved_cir_gpa = calibration_cir.gpa;
        const saved_types_gpa = calibration_checker.types.gpa;
        calibration_checker.gpa = calibration_gpa;
        calibration_cir.gpa = calibration_gpa;
        calibration_checker.types.gpa = calibration_gpa;
        defer {
            calibration_checker.types.gpa = saved_types_gpa;
            calibration_cir.gpa = saved_cir_gpa;
            calibration_checker.gpa = saved_checker_gpa;
        }
        try calibration_checker.replaceExprWithRuntimeError(
            calibration_proof.call_expr,
            calibration_diagnostic,
        );
    }
    const calibration_allocations = calibration_allocator.alloc_index - allocation_base;
    try std.testing.expect(!calibration_allocator.has_induced_failure);
    try std.testing.expect(calibration_allocations > 0);
    try calibration_snapshot.expectOnlyCallCompletionChanged(
        calibration_checker,
        calibration_proof.call_expr,
        calibration_proof.retirement_index,
    );
    try expectCallOperandRetirementCompletedWhileLookupsPending(
        calibration_checker,
        calibration_proof,
        calibration_diagnostic,
    );
    try std.testing.expect(calibration_cir.expected_retired_consumers.items.capacity >= 3);
    try std.testing.expect(calibration_cir.expected_retirement_failures.items.capacity >= 2);
    try expectDirectBinderCallPairInvalidationMetadataAbsent(calibration_checker);
    failure_stage = "calibration terminal replay";
    _ = try finishDirectBinderCallPairAfterCallCompletion(
        &calibration_consumer,
        &fresh_env,
    );
    const calibration_completed = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        calibration_cir,
    );
    defer std.testing.allocator.free(calibration_completed);

    var inter_reservation_failure_count: usize = 0;
    var failure_index: usize = 0;
    while (failure_index < calibration_allocations) : (failure_index += 1) {
        injected_failure_index = failure_index;
        failure_stage = "fault staging";
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "DirectBinderCallPairB",
            direct_binder_call_pair_consumer_source,
            "DirectBinderCallPairA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        const env = try stageDirectBinderCallPairThroughPrePoison(&consumer);
        defer consumer.checker.env_pool.release(env);
        const checker = &consumer.checker;
        const cir = consumer.module_env;
        const proof = try expectPendingTwoDirectBinderCallOperandFailures(checker);
        try std.testing.expect(std.meta.eql(calibration_proof, proof));
        try expectDirectBinderCallPairInvalidationMetadataAbsent(checker);
        const retired_capacity_before = cir.expected_retired_consumers.items.capacity;
        const failure_ref_capacity_before = cir.expected_retirement_failures.items.capacity;
        try std.testing.expectEqual(@as(usize, 0), retired_capacity_before);
        try std.testing.expectEqual(@as(usize, 0), failure_ref_capacity_before);
        const diagnostic_idx = try addCallOperandCompletionDiagnosticForTest(
            checker,
            proof.call_expr,
        );
        const pending_serialized = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        defer std.testing.allocator.free(pending_serialized);
        try std.testing.expectEqualSlices(
            u8,
            calibration_pending,
            pending_serialized,
        );
        var snapshot = try DirectBinderCallCompletionLedgerSnapshot.capture(
            checker,
            proof.call_expr,
        );
        defer snapshot.deinit();

        failure_stage = "injected central completion";
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = std.math.maxInt(usize),
            .resize_fail_index = std.math.maxInt(usize),
        });
        const failing_gpa = failing.allocator();
        const failure_allocation_base = failing.alloc_index;
        failing.fail_index = std.math.add(
            usize,
            failure_allocation_base,
            failure_index,
        ) catch return error.TestUnexpectedResult;
        failing.resize_fail_index = failing.resize_index;
        const result = blk: {
            const saved_checker_gpa = checker.gpa;
            const saved_cir_gpa = cir.gpa;
            const saved_types_gpa = checker.types.gpa;
            checker.gpa = failing_gpa;
            cir.gpa = failing_gpa;
            checker.types.gpa = failing_gpa;
            defer {
                checker.types.gpa = saved_types_gpa;
                cir.gpa = saved_cir_gpa;
                checker.gpa = saved_checker_gpa;
            }
            break :blk checker.replaceExprWithRuntimeError(
                proof.call_expr,
                diagnostic_idx,
            );
        };
        try std.testing.expectError(error.OutOfMemory, result);
        try std.testing.expect(failing.has_induced_failure);
        try snapshot.expectUnchanged(checker, proof.call_expr);
        try expectDirectBinderCallPairInvalidationMetadataAbsent(checker);
        const after_failure = try expectPendingTwoDirectBinderCallOperandFailures(checker);
        try std.testing.expect(std.meta.eql(proof, after_failure));
        try std.testing.expectEqual(@as(usize, 0), cir.expected_retired_consumers.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), cir.expected_retirement_failures.items.items.len);
        const retired_capacity_after = cir.expected_retired_consumers.items.capacity;
        const failure_ref_capacity_after = cir.expected_retirement_failures.items.capacity;
        try std.testing.expect(!(failure_ref_capacity_after > failure_ref_capacity_before and
            retired_capacity_after == retired_capacity_before));
        if (retired_capacity_after > retired_capacity_before and
            failure_ref_capacity_after == failure_ref_capacity_before)
        {
            inter_reservation_failure_count += 1;
        }

        failure_stage = "exact retry";
        try checker.replaceExprWithRuntimeError(proof.call_expr, diagnostic_idx);
        try snapshot.expectOnlyCallCompletionChanged(
            checker,
            proof.call_expr,
            proof.retirement_index,
        );
        try expectCallOperandRetirementCompletedWhileLookupsPending(
            checker,
            proof,
            diagnostic_idx,
        );
        try expectDirectBinderCallPairInvalidationMetadataAbsent(checker);

        failure_stage = "terminal retry replay";
        _ = try finishDirectBinderCallPairAfterCallCompletion(&consumer, &fresh_env);
        const retry_completed = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        defer std.testing.allocator.free(retry_completed);
        try std.testing.expectEqualSlices(
            u8,
            calibration_completed,
            retry_completed,
        );
    }
    try std.testing.expectEqual(@as(usize, 1), inter_reservation_failure_count);
}

test "runtime-error invalidation fixture publishes exact offside metadata" {
    const TestEnv = @import("test/TestEnv.zig");
    var provider = try TestEnv.init(
        "InvalidationRetryA",
        invalidation_retry_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    var consumer = try TestEnv.initUncheckedWithImportForTesting(
        "InvalidationRetryB",
        invalidation_retry_consumer_source,
        "InvalidationRetryA",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const env = try stageDirectBinderCallPairThroughPrePoison(&consumer);
    defer consumer.checker.env_pool.release(env);
    const checker = &consumer.checker;
    const topology = try expectInvalidationRetryTopology(&consumer);
    try std.testing.expectEqual(@as(usize, 0), checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());

    var discovered: ExprInvalidationDiscovery = .empty;
    defer discovered.deinit(std.testing.allocator);
    const saved_gpa = checker.gpa;
    checker.gpa = std.testing.allocator;
    defer checker.gpa = saved_gpa;
    try checker.discoverInvalidatedExprChildren(topology.call_expr, &discovered);
    var next: usize = 0;
    while (next < discovered.count()) : (next += 1) {
        try checker.discoverInvalidatedExprChildren(discovered.keys()[next], &discovered);
    }
    const expected_discovery = invalidationRetryExpectedDiscovery(topology);
    try std.testing.expectEqualSlices(
        CIR.Expr.Idx,
        &expected_discovery,
        discovered.keys(),
    );
    try std.testing.expect(!discovered.contains(topology.call_expr));
    try std.testing.expect(!discovered.contains(topology.default_numeral));
    try std.testing.expect(!discovered.contains(topology.before_list));
    try std.testing.expect(!discovered.contains(topology.after_list));
    try std.testing.expect(checker.omittedDefaultBelongsToInvalidatedSubtree(
        topology.before_backings[0],
        topology.before_backings[0],
    ));
    try std.testing.expect(!checker.omittedDefaultBelongsToInvalidatedSubtree(
        topology.call_expr,
        topology.before_backings[0],
    ));
}

test "runtime-error invalidation removes an authentic root-owned omission" {
    const TestEnv = @import("test/TestEnv.zig");
    var provider = try TestEnv.init(
        "InvalidationRetryA",
        invalidation_retry_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    var consumer = try TestEnv.initUncheckedWithImportForTesting(
        "InvalidationRetryB",
        invalidation_retry_consumer_source,
        "InvalidationRetryA",
        &provider,
    );
    defer consumer.deinit();
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const env = try stageDirectBinderCallPairThroughPrePoison(&consumer);
    defer consumer.checker.env_pool.release(env);
    const checker = &consumer.checker;
    const topology = try expectInvalidationRetryTopology(&consumer);
    try std.testing.expectEqual(@as(usize, 0), checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
    const literal_owners = invalidationRetryLiteralOwners(topology);
    var before = try InvalidationRetryMetadataSnapshot.capture(checker, &literal_owners);
    defer before.deinit();

    const omitted_root = topology.before_backings[0];
    try checker.invalidateExprSubtreeMetadata(omitted_root);
    try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.count());
    try std.testing.expect(before.selectedStateMatches(checker));
    try std.testing.expect(before.literalStateMatches(checker));
    const omissions = checker.cir.record_omitted_defaults.items.items;
    try std.testing.expectEqual(before.omissions.len - 1, omissions.len);
    var retained: usize = 0;
    var removed: usize = 0;
    for (before.omissions) |omitted| {
        if (omitted.expr == omitted_root) {
            removed += 1;
            continue;
        }
        try std.testing.expect(std.meta.eql(omitted, omissions[retained]));
        retained += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), removed);
    try std.testing.expectEqual(omissions.len, retained);

    const once = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(once);
    var committed = try InvalidationRetryMetadataSnapshot.capture(checker, &literal_owners);
    defer committed.deinit();
    try checker.invalidateExprSubtreeMetadata(omitted_root);
    try std.testing.expect(committed.matches(checker));
    const twice = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        checker.cir,
    );
    defer std.testing.allocator.free(twice);
    try std.testing.expectEqualSlices(u8, once, twice);
}

test "runtime-error subtree invalidation and central rewrite are atomic across OOM" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    var injected_failure_index: usize = std.math.maxInt(usize);
    errdefer std.debug.print(
        "runtime-error invalidation OOM fixture failed at {s}, allocation {d}\n",
        .{ failure_stage, injected_failure_index },
    );

    var provider = try TestEnv.init(
        "InvalidationRetryA",
        invalidation_retry_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "InvalidationRetryB",
        invalidation_retry_consumer_source,
        "InvalidationRetryA",
        &provider,
    );
    defer fresh_env.deinit();
    try fresh_env.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });

    // First calibrate the private ordered discovery independently. Then run
    // the complete invalidation on the same otherwise untouched checker. The
    // strict allocation-count difference proves that this authentic empty
    // durable map reaches its own reservation allocation.
    failure_stage = "direct calibration staging";
    var direct_calibration = try TestEnv.initUncheckedWithImportForTesting(
        "InvalidationRetryB",
        invalidation_retry_consumer_source,
        "InvalidationRetryA",
        &provider,
    );
    defer direct_calibration.deinit();
    try direct_calibration.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    const direct_stage = try stageInvalidationRetryThroughPrePoison(&direct_calibration);
    defer direct_calibration.checker.env_pool.release(direct_stage.env);
    const direct_checker = &direct_calibration.checker;
    const literal_owners = invalidationRetryLiteralOwners(direct_stage.topology);
    try std.testing.expectEqual(@as(usize, 0), direct_checker.hoist_invalidated_exprs.count());
    try std.testing.expectEqual(@as(usize, 0), direct_checker.hoist_invalidated_exprs.capacity());
    var direct_ledger = try DirectBinderCallCompletionLedgerSnapshot.capture(
        direct_checker,
        direct_stage.topology.call_expr,
    );
    defer direct_ledger.deinit();
    var pending_metadata = try InvalidationRetryMetadataSnapshot.capture(
        direct_checker,
        &literal_owners,
    );
    defer pending_metadata.deinit();
    const pending_serialized = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        direct_checker.cir,
    );
    defer std.testing.allocator.free(pending_serialized);

    failure_stage = "private discovery calibration";
    var discovery_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const discovery_base = discovery_allocator.alloc_index;
    discovery_allocator.resize_fail_index = discovery_allocator.resize_index;
    try expectInvalidationRetryDiscoveryWithAllocator(
        direct_checker,
        direct_stage.topology,
        discovery_allocator.allocator(),
    );
    const discovery_allocations = discovery_allocator.alloc_index - discovery_base;
    try std.testing.expect(!discovery_allocator.has_induced_failure);
    try std.testing.expect(discovery_allocations > 0);
    try std.testing.expect(pending_metadata.matches(direct_checker));
    try direct_ledger.expectUnchanged(direct_checker, direct_stage.topology.call_expr);

    failure_stage = "direct invalidation calibration";
    var direct_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const direct_base = direct_allocator.alloc_index;
    direct_allocator.resize_fail_index = direct_allocator.resize_index;
    try invalidateExprSubtreeMetadataWithAllocatorForTest(
        direct_checker,
        direct_stage.topology.call_expr,
        direct_allocator.allocator(),
    );
    const direct_allocations = direct_allocator.alloc_index - direct_base;
    try std.testing.expect(!direct_allocator.has_induced_failure);
    try std.testing.expect(direct_allocations > discovery_allocations);
    try direct_ledger.expectUnchanged(direct_checker, direct_stage.topology.call_expr);
    try expectInvalidationRetryIsolatedMetadataCommit(
        direct_checker,
        direct_stage.topology,
    );
    var committed_metadata = try InvalidationRetryMetadataSnapshot.capture(
        direct_checker,
        &literal_owners,
    );
    defer committed_metadata.deinit();
    const committed_serialized = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        direct_checker.cir,
    );
    defer std.testing.allocator.free(committed_serialized);

    failure_stage = "direct calibration idempotence";
    try direct_checker.invalidateExprSubtreeMetadata(direct_stage.topology.call_expr);
    try std.testing.expect(committed_metadata.matches(direct_checker));
    const direct_twice = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        direct_checker.cir,
    );
    defer std.testing.allocator.free(direct_twice);
    try std.testing.expectEqualSlices(u8, committed_serialized, direct_twice);

    var observed_durable_reservation_failure = false;
    var direct_failure_index: usize = 0;
    while (direct_failure_index < direct_allocations) : (direct_failure_index += 1) {
        injected_failure_index = direct_failure_index;
        failure_stage = "direct fault staging";
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "InvalidationRetryB",
            invalidation_retry_consumer_source,
            "InvalidationRetryA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        const stage = try stageInvalidationRetryThroughPrePoison(&consumer);
        defer consumer.checker.env_pool.release(stage.env);
        const checker = &consumer.checker;
        try std.testing.expect(std.meta.eql(direct_stage.topology, stage.topology));
        try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.count());
        try std.testing.expectEqual(@as(usize, 0), checker.hoist_invalidated_exprs.capacity());
        var ledger = try DirectBinderCallCompletionLedgerSnapshot.capture(
            checker,
            stage.topology.call_expr,
        );
        defer ledger.deinit();
        var before_metadata = try InvalidationRetryMetadataSnapshot.capture(
            checker,
            &literal_owners,
        );
        defer before_metadata.deinit();
        try std.testing.expect(pending_metadata.matches(checker));
        const before_serialized = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            checker.cir,
        );
        defer std.testing.allocator.free(before_serialized);
        try std.testing.expectEqualSlices(u8, pending_serialized, before_serialized);

        failure_stage = "injected direct invalidation";
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = direct_failure_index,
            .resize_fail_index = std.math.maxInt(usize),
        });
        failing.resize_fail_index = failing.resize_index;
        const result = invalidateExprSubtreeMetadataWithAllocatorForTest(
            checker,
            stage.topology.call_expr,
            failing.allocator(),
        );
        try std.testing.expectError(error.OutOfMemory, result);
        try std.testing.expect(failing.has_induced_failure);
        if (direct_failure_index >= discovery_allocations) {
            observed_durable_reservation_failure = true;
        }
        try ledger.expectUnchanged(checker, stage.topology.call_expr);
        try std.testing.expect(before_metadata.matches(checker));
        try std.testing.expect(pending_metadata.matches(checker));
        const failed_serialized = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            checker.cir,
        );
        defer std.testing.allocator.free(failed_serialized);
        try std.testing.expectEqualSlices(u8, before_serialized, failed_serialized);

        failure_stage = "direct exact retry";
        try checker.invalidateExprSubtreeMetadata(stage.topology.call_expr);
        try ledger.expectUnchanged(checker, stage.topology.call_expr);
        try expectInvalidationRetryIsolatedMetadataCommit(checker, stage.topology);
        try std.testing.expect(committed_metadata.matches(checker));
        const retried_serialized = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            checker.cir,
        );
        defer std.testing.allocator.free(retried_serialized);
        try std.testing.expectEqualSlices(u8, committed_serialized, retried_serialized);

        failure_stage = "direct retry idempotence";
        try checker.invalidateExprSubtreeMetadata(stage.topology.call_expr);
        try std.testing.expect(committed_metadata.matches(checker));
        const retry_twice = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            checker.cir,
        );
        defer std.testing.allocator.free(retry_twice);
        try std.testing.expectEqualSlices(u8, retried_serialized, retry_twice);
    }
    try std.testing.expect(observed_durable_reservation_failure);

    // Calibrate the real central replacement separately. The invalidation is
    // its exact allocation prefix; every later induced failure must therefore
    // observe the complete metadata commit while the call ledger remains
    // wholly pending.
    injected_failure_index = std.math.maxInt(usize);
    failure_stage = "central calibration staging";
    var central_calibration = try TestEnv.initUncheckedWithImportForTesting(
        "InvalidationRetryB",
        invalidation_retry_consumer_source,
        "InvalidationRetryA",
        &provider,
    );
    defer central_calibration.deinit();
    try central_calibration.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    var central_stage = try stageInvalidationRetryThroughPrePoison(&central_calibration);
    defer central_calibration.checker.env_pool.release(central_stage.env);
    const central_checker = &central_calibration.checker;
    try std.testing.expect(std.meta.eql(direct_stage.topology, central_stage.topology));
    try std.testing.expect(pending_metadata.matches(central_checker));
    const central_pending_serialized = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        central_checker.cir,
    );
    defer std.testing.allocator.free(central_pending_serialized);
    try std.testing.expectEqualSlices(u8, pending_serialized, central_pending_serialized);
    try std.testing.expectEqual(
        @as(usize, 0),
        central_checker.cir.expected_retired_consumers.items.capacity,
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        central_checker.cir.expected_retirement_failures.items.capacity,
    );
    var central_ledger = try DirectBinderCallCompletionLedgerSnapshot.capture(
        central_checker,
        central_stage.topology.call_expr,
    );
    defer central_ledger.deinit();

    failure_stage = "central replacement calibration";
    var central_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = std.math.maxInt(usize),
        .resize_fail_index = std.math.maxInt(usize),
    });
    const central_base = central_allocator.alloc_index;
    central_allocator.resize_fail_index = central_allocator.resize_index;
    try replaceExprWithRuntimeErrorWithAllocatorForTest(
        central_checker,
        central_stage.topology.call_expr,
        central_stage.diagnostic,
        central_allocator.allocator(),
    );
    const central_allocations = central_allocator.alloc_index - central_base;
    try std.testing.expect(!central_allocator.has_induced_failure);
    try std.testing.expect(central_allocations > direct_allocations);
    try central_ledger.expectOnlyCallCompletionChanged(
        central_checker,
        central_stage.topology.call_expr,
        central_stage.topology.call_retirement_index,
    );
    try expectInvalidationRetryCallCompletedWhileLookupsPending(
        central_checker,
        central_stage.topology,
        central_stage.diagnostic,
    );
    try expectInvalidationRetryIsolatedMetadataCommit(
        central_checker,
        central_stage.topology,
    );
    try std.testing.expect(committed_metadata.matches(central_checker));
    const central_committed_serialized = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        central_checker.cir,
    );
    defer std.testing.allocator.free(central_committed_serialized);

    failure_stage = "central calibration idempotence";
    try central_checker.replaceExprWithRuntimeError(
        central_stage.topology.call_expr,
        central_stage.diagnostic,
    );
    try std.testing.expect(committed_metadata.matches(central_checker));
    const central_twice = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        central_checker.cir,
    );
    defer std.testing.allocator.free(central_twice);
    try std.testing.expectEqualSlices(
        u8,
        central_committed_serialized,
        central_twice,
    );

    const terminal_discovery = invalidationRetryExpectedTerminalDiscovery(
        central_stage.topology,
    );
    failure_stage = "central calibration terminal replay";
    try finishInvalidationRetryFileCheck(
        &central_calibration,
        &fresh_env,
        &central_stage.env,
        central_stage.topology,
        &terminal_discovery,
    );
    const terminal_serialized = try serializeModuleEnvForCanonicalComparison(
        std.testing.allocator,
        central_checker.cir,
    );
    defer std.testing.allocator.free(terminal_serialized);

    var observed_pending_failure = false;
    var observed_committed_failure = false;
    var inter_reservation_failure_count: usize = 0;
    var central_failure_index: usize = 0;
    while (central_failure_index < central_allocations) : (central_failure_index += 1) {
        injected_failure_index = central_failure_index;
        failure_stage = "central fault staging";
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "InvalidationRetryB",
            invalidation_retry_consumer_source,
            "InvalidationRetryA",
            &provider,
        );
        defer consumer.deinit();
        try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
        var stage = try stageInvalidationRetryThroughPrePoison(&consumer);
        defer consumer.checker.env_pool.release(stage.env);
        const checker = &consumer.checker;
        const cir = checker.cir;
        try std.testing.expect(std.meta.eql(central_stage.topology, stage.topology));
        try std.testing.expect(pending_metadata.matches(checker));
        const pending = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        defer std.testing.allocator.free(pending);
        try std.testing.expectEqualSlices(u8, pending_serialized, pending);
        var ledger = try DirectBinderCallCompletionLedgerSnapshot.capture(
            checker,
            stage.topology.call_expr,
        );
        defer ledger.deinit();
        const retired_capacity_before = cir.expected_retired_consumers.items.capacity;
        const failure_ref_capacity_before = cir.expected_retirement_failures.items.capacity;
        try std.testing.expectEqual(@as(usize, 0), retired_capacity_before);
        try std.testing.expectEqual(@as(usize, 0), failure_ref_capacity_before);

        failure_stage = "injected central rewrite";
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = central_failure_index,
            .resize_fail_index = std.math.maxInt(usize),
        });
        failing.resize_fail_index = failing.resize_index;
        const result = replaceExprWithRuntimeErrorWithAllocatorForTest(
            checker,
            stage.topology.call_expr,
            stage.diagnostic,
            failing.allocator(),
        );
        try std.testing.expectError(error.OutOfMemory, result);
        try std.testing.expect(failing.has_induced_failure);
        try ledger.expectUnchanged(checker, stage.topology.call_expr);
        const failed = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        defer std.testing.allocator.free(failed);
        if (central_failure_index < direct_allocations) {
            observed_pending_failure = true;
            try std.testing.expect(pending_metadata.matches(checker));
            try std.testing.expectEqualSlices(u8, pending_serialized, failed);
        } else {
            observed_committed_failure = true;
            try expectInvalidationRetryIsolatedMetadataCommit(checker, stage.topology);
            try std.testing.expect(committed_metadata.matches(checker));
            try std.testing.expectEqualSlices(u8, committed_serialized, failed);
        }

        const retired_capacity_after = cir.expected_retired_consumers.items.capacity;
        const failure_ref_capacity_after = cir.expected_retirement_failures.items.capacity;
        try std.testing.expect(!(failure_ref_capacity_after > failure_ref_capacity_before and
            retired_capacity_after == retired_capacity_before));
        if (retired_capacity_after > retired_capacity_before and
            failure_ref_capacity_after == failure_ref_capacity_before)
        {
            inter_reservation_failure_count += 1;
        }

        failure_stage = "central exact retry";
        try checker.replaceExprWithRuntimeError(
            stage.topology.call_expr,
            stage.diagnostic,
        );
        try ledger.expectOnlyCallCompletionChanged(
            checker,
            stage.topology.call_expr,
            stage.topology.call_retirement_index,
        );
        try expectInvalidationRetryCallCompletedWhileLookupsPending(
            checker,
            stage.topology,
            stage.diagnostic,
        );
        try expectInvalidationRetryIsolatedMetadataCommit(checker, stage.topology);
        try std.testing.expect(committed_metadata.matches(checker));
        const retried = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        defer std.testing.allocator.free(retried);
        try std.testing.expectEqualSlices(u8, central_committed_serialized, retried);

        failure_stage = "central retry idempotence";
        try checker.replaceExprWithRuntimeError(
            stage.topology.call_expr,
            stage.diagnostic,
        );
        try std.testing.expect(committed_metadata.matches(checker));
        const retried_twice = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        defer std.testing.allocator.free(retried_twice);
        try std.testing.expectEqualSlices(u8, retried, retried_twice);

        failure_stage = "central terminal retry replay";
        try finishInvalidationRetryFileCheck(
            &consumer,
            &fresh_env,
            &stage.env,
            stage.topology,
            &terminal_discovery,
        );
        const completed = try serializeModuleEnvForCanonicalComparison(
            std.testing.allocator,
            cir,
        );
        defer std.testing.allocator.free(completed);
        try std.testing.expectEqualSlices(u8, terminal_serialized, completed);
    }
    try std.testing.expect(observed_pending_failure);
    try std.testing.expect(observed_committed_failure);
    try std.testing.expectEqual(@as(usize, 1), inter_reservation_failure_count);
}

fn expectInvalidationCycleDiscovery(
    checker: *Self,
    root: CIR.Expr.Idx,
    expected: []const CIR.Expr.Idx,
) !void {
    var discovered: ExprInvalidationDiscovery = .empty;
    defer discovered.deinit(checker.gpa);
    try checker.discoverInvalidatedExprChildren(root, &discovered);
    var next: usize = 0;
    while (next < discovered.count()) : (next += 1) {
        try checker.discoverInvalidatedExprChildren(discovered.keys()[next], &discovered);
    }
    try std.testing.expectEqualSlices(CIR.Expr.Idx, expected, discovered.keys());
    try checker.invalidateExprSubtreeMetadata(root);
    try std.testing.expectEqual(expected.len, checker.hoist_invalidated_exprs.count());
    for (expected) |expr| {
        try std.testing.expect(checker.hoist_invalidated_exprs.contains(expr));
    }
    try checker.invalidateExprSubtreeMetadata(root);
    try std.testing.expectEqual(expected.len, checker.hoist_invalidated_exprs.count());
    for (expected) |expr| {
        try std.testing.expect(checker.hoist_invalidated_exprs.contains(expr));
    }
}

test "runtime-error invalidation terminates an authentic expression-return lambda cycle" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initUncheckedForTesting("InvalidationExprReturnCycle",
        \\expr_cycle = || {
        \\    return {}
        \\}
    );
    defer test_env.deinit();
    try test_env.assertCanErrors(&.{});
    const def_idx = test_env.can.explicitRootDefByName("expr_cycle") orelse
        return error.TestUnexpectedResult;
    const lambda_idx = test_env.module_env.store.getDef(def_idx).expr;
    const lambda = switch (test_env.module_env.store.getExpr(lambda_idx)) {
        .e_lambda => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 0), test_env.module_env.store.slicePatterns(lambda.args).len);
    const block = switch (test_env.module_env.store.getExpr(lambda.body)) {
        .e_block => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 0), test_env.module_env.store.sliceStatements(block.stmts).len);
    const return_expr = switch (test_env.module_env.store.getExpr(block.final_expr)) {
        .e_return => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(lambda_idx, return_expr.lambda);
    try std.testing.expectEqual(
        @FieldType(CIR.Expr, "e_return").ReturnContext.return_expr,
        return_expr.context,
    );
    try std.testing.expect(test_env.module_env.store.getExpr(return_expr.expr) == .e_empty_record);
    const expected = [_]CIR.Expr.Idx{
        lambda.body,
        block.final_expr,
        return_expr.expr,
        lambda_idx,
    };
    try expectInvalidationCycleDiscovery(&test_env.checker, lambda_idx, &expected);
}

test "runtime-error invalidation terminates an authentic statement-return lambda cycle" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initUncheckedForTesting("InvalidationStatementReturnCycle",
        \\stmt_cycle = || {
        \\    return {}
        \\    {}
        \\}
    );
    defer test_env.deinit();
    try test_env.assertCanErrors(&.{});
    const def_idx = test_env.can.explicitRootDefByName("stmt_cycle") orelse
        return error.TestUnexpectedResult;
    const lambda_idx = test_env.module_env.store.getDef(def_idx).expr;
    const lambda = switch (test_env.module_env.store.getExpr(lambda_idx)) {
        .e_lambda => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 0), test_env.module_env.store.slicePatterns(lambda.args).len);
    const block = switch (test_env.module_env.store.getExpr(lambda.body)) {
        .e_block => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const statements = test_env.module_env.store.sliceStatements(block.stmts);
    try std.testing.expectEqual(@as(usize, 1), statements.len);
    const return_statement = switch (test_env.module_env.store.getStatement(statements[0])) {
        .s_return => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(lambda_idx, return_statement.lambda);
    try std.testing.expect(test_env.module_env.store.getExpr(return_statement.expr) == .e_empty_record);
    try std.testing.expect(test_env.module_env.store.getExpr(block.final_expr) == .e_empty_record);
    try std.testing.expect(return_statement.expr != block.final_expr);
    const expected = [_]CIR.Expr.Idx{
        lambda.body,
        return_statement.expr,
        lambda_idx,
        block.final_expr,
    };
    try expectInvalidationCycleDiscovery(&test_env.checker, lambda_idx, &expected);
}

test "invalid where alias keeps qualifying call operands beside a preexisting error" {
    const TestEnv = @import("test/TestEnv.zig");
    var failure_stage: []const u8 = "provider";
    errdefer std.debug.print("mixed direct-binder call fixture failed at {s}\n", .{failure_stage});
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("DirectBinderMixedCallA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import DirectBinderMixedCallA exposing [Status]
        \\
        \\first : a -> a where [a.Status]
        \\first = |value| (|left, _right| left)(value, 1..<5..<10)
    ;
    failure_stage = "consumer initialization";
    var consumer = try TestEnv.initWithImport(
        "DirectBinderMixedCallB",
        consumer_source,
        "DirectBinderMixedCallA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderMixedCallB",
        consumer_source,
        "DirectBinderMixedCallA",
        &provider,
    );
    defer fresh_env.deinit();
    failure_stage = "diagnostics";
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type", "Chained Range" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
    try expectDirectBinderTransientListsEmpty(&consumer.checker);

    failure_stage = "durable relation";
    const cir = consumer.module_env;
    try std.testing.expectEqual(@as(usize, 3), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 4), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), cir.expected_retirement_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 3), cir.expected_retired_consumers.items.items.len);
    var annotation_failure_count: usize = 0;
    var lookup_failure_count: usize = 0;
    var call_failure_count: usize = 0;
    for (cir.expected_failures.items.items) |failure| switch (failure.decodedKind() orelse
        return error.TestUnexpectedResult) {
        .annotation_malformed_type => annotation_failure_count += 1,
        .direct_binder_lookup_checked_error => lookup_failure_count += 1,
        .call_operand_checked_error => call_failure_count += 1,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), annotation_failure_count);
    try std.testing.expectEqual(@as(usize, 1), lookup_failure_count);
    try std.testing.expectEqual(@as(usize, 1), call_failure_count);
    var call_retirement_index: ?u32 = null;
    var preexisting_retirement_index: ?u32 = null;
    for (cir.expected_consumer_retirements.items.items, 0..) |retirement, retirement_index| {
        if (expectedCallOperandRetirementSnapshot(
            &cir.types,
            cir,
            @intCast(retirement_index),
        )) |_| {
            if (call_retirement_index != null) return error.TestUnexpectedResult;
            call_retirement_index = @intCast(retirement_index);
        } else if (retirement.decodedKind() == .preexisting_runtime_error) {
            if (preexisting_retirement_index != null) return error.TestUnexpectedResult;
            preexisting_retirement_index = @intCast(retirement_index);
        }
    }
    const exact_call_retirement = call_retirement_index orelse
        return error.TestUnexpectedResult;
    const exact_preexisting = preexisting_retirement_index orelse
        return error.TestUnexpectedResult;
    const call_retirement = cir.expected_consumer_retirements.items.items[
        exact_call_retirement
    ];
    const call_snapshot = expectedCallOperandRetirementSnapshot(
        &cir.types,
        cir,
        exact_call_retirement,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 2), call_snapshot.call.args_len);
    try std.testing.expectEqual(@as(u32, 3), call_retirement.retired_consumers_len);
    try std.testing.expectEqual(@as(u32, 1), call_retirement.expected_failures_len);
    const owned_ref = cir.expected_retirement_failures.items.items[
        call_retirement.expected_failures_start
    ];
    const call_failure = cir.expected_failures.items.items[owned_ref.failure_index];
    try std.testing.expectEqual(
        ModuleEnv.ExpectedFailure.Kind.call_operand_checked_error,
        call_failure.decodedKind().?,
    );
    try std.testing.expectEqual(@as(u32, 0), call_failure.slot);
    try std.testing.expectEqual(
        cir.store.index_data.items.items[call_snapshot.call.args_start],
        call_failure.site_node,
    );
    const unsupported_site = cir.store.index_data.items.items[
        call_snapshot.call.args_start + 1
    ];
    try std.testing.expectEqual(
        unsupported_site,
        cir.expected_consumer_retirements.items.items[exact_preexisting].retired_node,
    );

    // The unsupported malformed sibling is admitted only through the exact
    // typed baseline returned by its real expression check. A missing status,
    // another cause namespace, another retirement kind, or a coordinated
    // sibling-site retarget remains a legal encoding but supplies no authority.
    const unsupported_expr: CIR.Expr.Idx = @enumFromInt(unsupported_site);
    const exact_preexisting_cause = ModuleEnv.CauseOwner.expectedConsumerRetirement(
        exact_preexisting,
    );
    const exact_preexisting_status: CheckedExprStatus = .{
        .checked_error = exact_preexisting_cause,
    };
    try std.testing.expect(exact_preexisting_cause.hasCanonicalTags(true));
    try std.testing.expect(preexistingMalformedCallOperandStatusMatches(
        cir,
        unsupported_expr,
        exact_preexisting_status,
    ));
    try std.testing.expect(!preexistingMalformedCallOperandStatusMatches(
        cir,
        unsupported_expr,
        .established,
    ));

    const wrong_namespace_cause = ModuleEnv.CauseOwner.expectedFailure(
        owned_ref.failure_index,
    );
    try std.testing.expect(wrong_namespace_cause.hasCanonicalTags(true));
    try std.testing.expect(!preexistingMalformedCallOperandStatusMatches(
        cir,
        unsupported_expr,
        .{ .checked_error = wrong_namespace_cause },
    ));

    const wrong_retirement_cause = ModuleEnv.CauseOwner.expectedConsumerRetirement(
        exact_call_retirement,
    );
    try std.testing.expect(wrong_retirement_cause.hasCanonicalTags(true));
    try std.testing.expect(cir.expected_consumer_retirements.items.items[
        exact_call_retirement
    ].hasLegalTags());
    try std.testing.expect(!preexistingMalformedCallOperandStatusMatches(
        cir,
        unsupported_expr,
        .{ .checked_error = wrong_retirement_cause },
    ));

    const preexisting_retirement = &cir.expected_consumer_retirements.items.items[
        exact_preexisting
    ];
    const saved_preexisting_retirement = preexisting_retirement.*;
    try std.testing.expect(call_failure.site_node != unsupported_site);
    preexisting_retirement.retired_node = call_failure.site_node;
    const sibling_retirement_tags = preexisting_retirement.hasLegalTags();
    const sibling_retirement_status = preexistingMalformedCallOperandStatusMatches(
        cir,
        unsupported_expr,
        exact_preexisting_status,
    );
    preexisting_retirement.* = saved_preexisting_retirement;
    try std.testing.expect(sibling_retirement_tags);
    try std.testing.expect(!sibling_retirement_status);
    try std.testing.expect(preexistingMalformedCallOperandStatusMatches(
        cir,
        unsupported_expr,
        exact_preexisting_status,
    ));

    for (cir.expected_failures.items.items) |failure| {
        if (failure.decodedKind() == .call_operand_checked_error) {
            try std.testing.expectEqual(@as(u32, 0), failure.slot);
        }
    }
    try std.testing.expect(expectedCallOperandRetirementIsLocallyValid(
        &cir.types,
        cir,
        exact_call_retirement,
    ));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    const produced_context = ImportResolution.producedSupplied(
        cir,
        .{ .envs = consumer.checker.imported_modules, .modules = consumer.checker.validated_imported_modules },
        .{ .envs = consumer.checker.owner_modules, .modules = consumer.checker.validated_owner_modules },
        consumer.checker.platform_dependency_index,
    );
    failure_stage = "context replay";
    try validateExpectedFailureContext(cir, produced_context);
    try validateExpectedFailureContext(cir, context);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
}

test "invalid imported where alias retires checked call formals without losing producer authority" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("BoundaryOomA", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    // Keep this historical source byte-for-byte intact. Its independent call
    // families jointly pin the original regression and may not be reduced to
    // a smaller, merely plausible fixture.
    const consumer_source =
        \\import BoundaryOomA exposing [Status]
        \\
        \\first : a, U64 -> [Off, On] where [a.Status]
        \\first = |value, count| if count == 0.U64 { second(value, 1.U64) } else { value.status() }
        \\
        \\second : a, U64 -> [Off, On] where [a.Status]
        \\second = |value, count| if count == 0.U64 { first(value, 1.U64) } else { value.status() }
        \\
        \\applyKnown : (Str -> Str), Str -> Str
        \\applyKnown = |function, value| function(value)
        \\instantiated = (|value| value)("instantiated")
        \\applyFresh = |function, value| function(value)
        \\
        \\make_zero : {} -> a where [
        \\    a.from_numeral : Numeral -> Try(a, [InvalidNumeral(Str)]),
        \\]
        \\make_zero = |_| 0
        \\zero_one = make_zero({})
        \\zero_two = make_zero({})
        \\zero_three = make_zero({})
        \\looped = |_| {
        \\    for _item in [1.U64] {}
        \\    {}
        \\}
    ;
    var consumer = try TestEnv.initWithImport(
        "BoundaryOomB",
        consumer_source,
        "BoundaryOomA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "BoundaryOomB",
        consumer_source,
        "BoundaryOomA",
        &provider,
    );
    defer fresh_env.deinit();

    // Retain the source's actual canonicalization failure as part of the
    // regression contract rather than accepting only the recovery ledger.
    const diagnostics = try consumer.module_env.getDiagnostics();
    defer consumer.gpa.free(diagnostics);
    var type_not_exposed_count: usize = 0;
    for (diagnostics) |diagnostic| {
        type_not_exposed_count += @intFromBool(diagnostic == .type_not_exposed);
    }
    try std.testing.expect(type_not_exposed_count != 0);

    const cir = consumer.module_env;
    var annotated_callee_failures: usize = 0;
    var call_operand_failures: usize = 0;
    var first_lookup_cause: ?u32 = null;
    for (cir.expected_failures.items.items, 0..) |failure, failure_index| {
        switch (failure.decodedKind() orelse return error.TestUnexpectedResult) {
            .annotated_binding_lookup_checked_error => {
                annotated_callee_failures += 1;
                try std.testing.expect(expectedFailureSubjectIsLocallyValid(
                    &cir.types,
                    cir,
                    failure,
                    @intCast(failure_index),
                ));
            },
            .call_operand_checked_error => {
                call_operand_failures += 1;
                const subject = failure.subject_authority.decodedExpectedProducerRootPlan() orelse
                    return error.TestUnexpectedResult;
                try std.testing.expect(callOperandExpectedFailureIsLocallyValid(
                    &cir.types,
                    cir,
                    failure,
                    @intCast(failure_index),
                    subject,
                ));
                const lookup_cause = failure.cause_owner.decodedExpectedConsumerRetirement() orelse
                    return error.TestUnexpectedResult;
                if (first_lookup_cause) |first| {
                    try std.testing.expect(first != lookup_cause.index);
                } else {
                    first_lookup_cause = lookup_cause.index;
                }
            },
            else => {},
        }
    }
    try std.testing.expectEqual(@as(usize, 2), annotated_callee_failures);
    try std.testing.expectEqual(@as(usize, 2), call_operand_failures);

    const first_def_idx = consumer.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const second_def_idx = consumer.can.explicitRootDefByName("second") orelse
        return error.TestUnexpectedResult;
    const first_def = cir.store.getDef(first_def_idx);
    const second_def = cir.store.getDef(second_def_idx);
    var first_calls_second: usize = 0;
    var second_calls_first: usize = 0;
    var call_operand_retirements: usize = 0;
    var call_operand_retirement_indices: [2]u32 = undefined;
    for (cir.expected_consumer_retirements.items.items, 0..) |retirement, retirement_index| {
        const snapshot = expectedCallOperandRetirementSnapshot(
            &cir.types,
            cir,
            @intCast(retirement_index),
        ) orelse continue;
        if (call_operand_retirements >= call_operand_retirement_indices.len) {
            return error.TestUnexpectedResult;
        }
        call_operand_retirement_indices[call_operand_retirements] = @intCast(retirement_index);
        call_operand_retirements += 1;
        try std.testing.expectEqual(@as(u32, 2), snapshot.call.args_len);
        try std.testing.expectEqual(@as(u32, 3), retirement.retired_consumers_len);
        try std.testing.expectEqual(@as(u32, 1), retirement.expected_failures_len);
        const original_payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
        try std.testing.expectEqual(@as(u32, 0), original_payload.expr_call.constraint_fn_var_plus_one);
        try std.testing.expect(expectedCallOperandRetirementIsLocallyValid(
            &cir.types,
            cir,
            @intCast(retirement_index),
        ));

        const failure_ref = cir.expected_retirement_failures.items.items[
            retirement.expected_failures_start
        ];
        const call_failure = cir.expected_failures.items.items[failure_ref.failure_index];
        try std.testing.expectEqual(
            ModuleEnv.ExpectedFailure.Kind.call_operand_checked_error,
            call_failure.decodedKind().?,
        );
        try std.testing.expectEqual(@as(u32, 0), call_failure.slot);
        try std.testing.expectEqual(
            cir.store.index_data.items.items[snapshot.call.args_start],
            call_failure.site_node,
        );
        const lookup_retirement = call_failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        const lookup_failure_index = completedDirectBinderLookupFailureForRetirement(
            cir,
            lookup_retirement.index,
        ) orelse return error.TestUnexpectedResult;
        const lookup_failure = cir.expected_failures.items.items[lookup_failure_index];
        try std.testing.expectEqual(call_failure.site_node, lookup_failure.owner_node);
        const annotation_retirement = lookup_failure.cause_owner.decodedExpectedConsumerRetirement() orelse
            return error.TestUnexpectedResult;
        const direct_pattern = annotationRetirementDirectPatternAtSlot(
            cir,
            annotation_retirement.index,
            0,
        ) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(
            @as(CIR.Pattern.Idx, @enumFromInt(lookup_failure.site_node)),
            direct_pattern.pattern_idx,
        );

        var callee_pattern: ?CIR.Pattern.Idx = null;
        for (cir.expected_failures.items.items, 0..) |failure, failure_index| {
            if (failure.decodedKind() != .annotated_binding_lookup_checked_error or
                failure.owner_node != snapshot.call.func)
            {
                continue;
            }
            const callee_snapshot = expectedLookupRetirementOwningFailure(
                cir,
                @intCast(failure_index),
            ) orelse return error.TestUnexpectedResult;
            if (callee_pattern != null) return error.TestUnexpectedResult;
            callee_pattern = callee_snapshot.pattern_idx;
        }
        const exact_callee_pattern = callee_pattern orelse
            return error.TestUnexpectedResult;
        const source_owner = cir.expected_consumer_retirements.items.items[
            annotation_retirement.index
        ].retired_node;
        if (source_owner == @intFromEnum(first_def.expr) and
            exact_callee_pattern == second_def.pattern)
        {
            first_calls_second += 1;
        } else if (source_owner == @intFromEnum(second_def.expr) and
            exact_callee_pattern == first_def.pattern)
        {
            second_calls_first += 1;
        } else {
            return error.TestUnexpectedResult;
        }
    }
    try std.testing.expectEqual(@as(usize, 2), call_operand_retirements);
    try std.testing.expectEqual(@as(usize, 1), first_calls_second);
    try std.testing.expectEqual(@as(usize, 1), second_calls_first);
    try std.testing.expect(validateExpectedCallPlans(cir));
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    const fresh_context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try validateExpectedFailureContext(cir, fresh_context);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);

    // The two recursive calls are same-shaped siblings. Moving the complete
    // F_C authority of one to the other leaves every field individually legal,
    // but duplicates the second call and omits the first.
    const first_retirement_index = call_operand_retirement_indices[0];
    const second_retirement_index = call_operand_retirement_indices[1];
    const first_retirement = &cir.expected_consumer_retirements.items.items[
        first_retirement_index
    ];
    const second_retirement = &cir.expected_consumer_retirements.items.items[
        second_retirement_index
    ];
    const first_failure_ref = cir.expected_retirement_failures.items.items[
        first_retirement.expected_failures_start
    ];
    const second_failure_ref = cir.expected_retirement_failures.items.items[
        second_retirement.expected_failures_start
    ];
    const first_call_failure = &cir.expected_failures.items.items[first_failure_ref.failure_index];
    const second_call_failure = cir.expected_failures.items.items[second_failure_ref.failure_index];
    const saved_first_call_failure = first_call_failure.*;
    first_call_failure.* = second_call_failure;
    const sibling_failure_tags = first_call_failure.hasLegalTagsAt(first_failure_ref.failure_index);
    const sibling_failure_local = callOperandCandidateIsLocallyValid(cir);
    const sibling_failure_fresh = callOperandCandidateMatchesFresh(cir, fresh_context);
    first_call_failure.* = saved_first_call_failure;
    try std.testing.expect(sibling_failure_tags);
    try std.testing.expect(!sibling_failure_local);
    try std.testing.expect(!sibling_failure_fresh);

    const saved_first_failure_start = first_retirement.expected_failures_start;
    first_retirement.expected_failures_start = second_retirement.expected_failures_start;
    const sibling_failure_range_local = callOperandCandidateIsLocallyValid(cir);
    const sibling_failure_range_fresh = callOperandCandidateMatchesFresh(cir, fresh_context);
    first_retirement.expected_failures_start = saved_first_failure_start;
    try std.testing.expect(!sibling_failure_range_local);
    try std.testing.expect(!sibling_failure_range_fresh);

    const saved_first_consumer_start = first_retirement.retired_consumers_start;
    first_retirement.retired_consumers_start = second_retirement.retired_consumers_start;
    const sibling_consumer_range_local = callOperandCandidateIsLocallyValid(cir);
    const sibling_consumer_range_fresh = callOperandCandidateMatchesFresh(cir, fresh_context);
    first_retirement.retired_consumers_start = saved_first_consumer_start;
    try std.testing.expect(!sibling_consumer_range_local);
    try std.testing.expect(!sibling_consumer_range_fresh);

    const first_snapshot = expectedCallOperandRetirementSnapshot(
        &cir.types,
        cir,
        first_retirement_index,
    ) orelse return error.TestUnexpectedResult;
    const first_callee_pattern = expectedCallLookupPatternAtToken(
        cir,
        expectedCallSlotTokenIndex(
            cir,
            first_retirement.retired_node,
            .root,
            ModuleEnv.ExpectedCallSlotToken.none,
        ) orelse return error.TestUnexpectedResult,
    ) orelse return error.TestUnexpectedResult;
    var annotated_callee_retirement: ?u32 = null;
    for (cir.expected_failures.items.items, 0..) |failure, failure_index| {
        if (failure.decodedKind() != .annotated_binding_lookup_checked_error or
            failure.owner_node != first_snapshot.call.func)
        {
            continue;
        }
        const lookup = expectedLookupRetirementOwningFailure(
            cir,
            @intCast(failure_index),
        ) orelse return error.TestUnexpectedResult;
        if (lookup.pattern_idx != first_callee_pattern or annotated_callee_retirement != null) {
            return error.TestUnexpectedResult;
        }
        annotated_callee_retirement = lookup.retirement_index;
    }
    const exact_annotated_callee_retirement = annotated_callee_retirement orelse
        return error.TestUnexpectedResult;
    first_call_failure.cause_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(
        exact_annotated_callee_retirement,
    );
    const callee_cause_tags = first_call_failure.hasLegalTagsAt(first_failure_ref.failure_index);
    const callee_cause_local = callOperandCandidateIsLocallyValid(cir);
    const callee_cause_fresh = callOperandCandidateMatchesFresh(cir, fresh_context);
    first_call_failure.* = saved_first_call_failure;
    try std.testing.expect(callee_cause_tags);
    try std.testing.expect(!callee_cause_local);
    try std.testing.expect(!callee_cause_fresh);

    // A predeclared recursive call's copied source is the exact scheme
    // destination, not the binder-pattern variable. Moving the root occurrence
    // back to that pattern must fail the origin-specific inverse.
    const first_root_token_index = expectedCallSlotTokenIndex(
        cir,
        first_retirement.retired_node,
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse return error.TestUnexpectedResult;
    const first_instantiation_step = expectedCallInstantiationStepForLookup(
        cir,
        first_root_token_index,
        first_callee_pattern,
    ) orelse return error.TestUnexpectedResult;
    const first_step = cir.where_marker_copy_steps.items.items[first_instantiation_step];
    const first_origin = first_step.origin.expected_call_instantiation;
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.SourceKind.local_predeclared_annotation,
        first_origin.decodedSourceKind().?,
    );
    const first_root_occurrence_index = first_step.occurrences_start +
        first_step.root_occurrence_offset;
    const saved_first_root_occurrence = cir.where_marker_copy_occurrences.items.items[
        first_root_occurrence_index
    ];
    const pattern_var = @intFromEnum(ModuleEnv.varFrom(first_callee_pattern));
    try std.testing.expect(saved_first_root_occurrence.raw_source_var != pattern_var);
    cir.where_marker_copy_occurrences.items.items[
        first_root_occurrence_index
    ].raw_source_var = pattern_var;
    const pattern_source_origin = expectedCallInstantiationStepMatchesLookupOrigin(
        cir,
        first_instantiation_step,
        first_root_token_index,
        first_callee_pattern,
    );
    const pattern_source_local = callOperandCandidateIsLocallyValid(cir);
    const pattern_source_fresh = callOperandCandidateMatchesFresh(cir, fresh_context);
    cir.where_marker_copy_occurrences.items.items[
        first_root_occurrence_index
    ] = saved_first_root_occurrence;
    try std.testing.expect(!pattern_source_origin);
    try std.testing.expect(!pattern_source_local);
    try std.testing.expect(!pattern_source_fresh);

    const second_snapshot = expectedCallOperandRetirementSnapshot(
        &cir.types,
        cir,
        second_retirement_index,
    ) orelse return error.TestUnexpectedResult;
    const second_root_token_index = expectedCallSlotTokenIndex(
        cir,
        second_retirement.retired_node,
        .root,
        ModuleEnv.ExpectedCallSlotToken.none,
    ) orelse return error.TestUnexpectedResult;
    const second_callee_pattern = expectedCallLookupPatternAtToken(
        cir,
        second_root_token_index,
    ) orelse return error.TestUnexpectedResult;
    const second_instantiation_step = expectedCallInstantiationStepForLookup(
        cir,
        second_root_token_index,
        second_callee_pattern,
    ) orelse return error.TestUnexpectedResult;
    const second_step = cir.where_marker_copy_steps.items.items[second_instantiation_step];
    const second_origin = second_step.origin.expected_call_instantiation;
    try std.testing.expectEqual(first_snapshot.call.args_len, second_snapshot.call.args_len);
    try std.testing.expect(first_origin.source_support_step != second_origin.source_support_step);
    const second_support = cir.where_marker_copy_steps.items.items[
        second_origin.source_support_step
    ];
    const second_support_root = expectedCallCopyStepRootOccurrence(cir, second_support) orelse
        return error.TestUnexpectedResult;
    const saved_first_origin = cir.where_marker_copy_steps.items.items[first_instantiation_step]
        .origin.expected_call_instantiation;
    cir.where_marker_copy_steps.items.items[first_instantiation_step]
        .origin.expected_call_instantiation.source_support_step =
        second_origin.source_support_step;
    cir.where_marker_copy_occurrences.items.items[
        first_root_occurrence_index
    ].raw_source_var = second_support_root.raw_destination_var;
    const sibling_support_origin = expectedCallInstantiationStepMatchesLookupOrigin(
        cir,
        first_instantiation_step,
        first_root_token_index,
        first_callee_pattern,
    );
    const sibling_support_local = callOperandCandidateIsLocallyValid(cir);
    const sibling_support_fresh = callOperandCandidateMatchesFresh(cir, fresh_context);
    cir.where_marker_copy_steps.items.items[first_instantiation_step]
        .origin.expected_call_instantiation = saved_first_origin;
    cir.where_marker_copy_occurrences.items.items[
        first_root_occurrence_index
    ] = saved_first_root_occurrence;
    try std.testing.expect(!sibling_support_origin);
    try std.testing.expect(!sibling_support_local);
    try std.testing.expect(!sibling_support_fresh);

    try std.testing.expect(callOperandCandidateIsLocallyValid(cir));
    try std.testing.expect(callOperandCandidateMatchesFresh(cir, fresh_context));
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
}

test "checked-boundary where-marker rebuild is an exhaustive OOM no-op" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\a.Status : where [a.status : a -> [Off, On]]
    ;
    var provider = try TestEnv.init("Status", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import Status
        \\
        \\first : a, U64 -> [Off, On] where [a.Status]
        \\first = |value, count| if count == 0.U64 { second(value, 1.U64) } else { value.status() }
        \\
        \\second : a, U64 -> [Off, On] where [a.Status]
        \\second = |value, count| if count == 0.U64 { first(value, 1.U64) } else { value.status() }
        \\
        \\applyKnown : (Str -> Str), Str -> Str
        \\applyKnown = |function, value| function(value)
        \\instantiated = (|value| value)("instantiated")
        \\applyFresh = |function, value| function(value)
        \\
        \\make_zero : {} -> a where [
        \\    a.from_numeral : Numeral -> Try(a, [InvalidNumeral(Str)]),
        \\]
        \\make_zero = |_| 0
        \\zeros = [make_zero({}), make_zero({}), make_zero({}), make_zero({})]
        \\looped = |_| {
        \\    for _item in [1.U64] {}
        \\    {}
        \\}
    ;
    var consumer = try TestEnv.initWithImport(
        "BoundaryOomB",
        consumer_source,
        "Status",
        &provider,
    );
    var consumer_live = true;
    defer if (consumer_live) consumer.deinit();
    const checker = &consumer.checker;
    try consumer.assertNoErrors();

    var formal_origin_counts = [_]usize{0} ** std.enums.values(
        ModuleEnv.ExpectedCallFormal.FormalOrigin,
    ).len;
    for (checker.cir.expected_call_formals.items.items) |formal| {
        const origin = formal.decodedFormalOrigin() orelse return error.TestUnexpectedResult;
        formal_origin_counts[@intFromEnum(origin)] += 1;
    }
    for (formal_origin_counts) |count| try std.testing.expect(count != 0);
    try std.testing.expect(checker.cir.external_lookup_tokens.items.items.len != 0);
    try std.testing.expect(checker.cir.external_cache_seeds.items.items.len != 0);
    try std.testing.expect(checker.cir.for_loop_dispatch_plans.items.items.len != 0);
    try std.testing.expect(checker.cir.copied_open_literal_groups.items.items.len != 0);
    try std.testing.expect(checker.cir.copied_open_literal_events.items.items.len != 0);
    var copied_numeral_event_count: usize = 0;
    for (checker.cir.copied_open_literal_events.items.items) |event| {
        copied_numeral_event_count += @intFromBool(event.decodedLiteralKind() == .numeral);
    }
    try std.testing.expect(copied_numeral_event_count >= 4);
    var copied_literal_move_count: usize = 0;
    for (checker.cir.constraint_evidence_moves.items.items) |move| {
        copied_literal_move_count += @intFromBool(move.handle.decodedKind() == .copied_literal_event);
    }
    try std.testing.expect(copied_literal_move_count >= 3);

    // Discard every transient import/method cache, require at least one exact
    // producer from the former cache-fallback domain, and resolve every cross
    // step through its durable typed origin before this rebuild and all OOM
    // retries. This fixture authors a candidate-probe method root; it does not
    // rely on a particular provisional step number.
    checker.import_cache.clearRetainingCapacity();
    checker.imported_method_schemes.clearRetainingCapacity();
    checker.imported_method_scheme_by_source.clearRetainingCapacity();
    var durable_cross_step_count: usize = 0;
    var former_cache_fallback_count: usize = 0;
    for (checker.cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        const kind = step.decodedKind() orelse return error.TestUnexpectedResult;
        if (kind.sourceNamespace() != .cross_module) continue;
        former_cache_fallback_count += @intFromBool(switch (kind) {
            .external_cir_node,
            .external_numeric_suffix,
            .external_where_alias_receiver,
            .external_where_alias_parameter,
            .generated_codec_method,
            .inspect_method,
            .associated_method,
            .default_method,
            .candidate_probe_method_root,
            => true,
            else => false,
        });
        _ = checker.checkedBoundaryCrossStepProvider(
            checker.cir.where_marker_copy_steps.items.items,
            @intCast(step_index),
        );
        durable_cross_step_count += 1;
    }
    try std.testing.expect(durable_cross_step_count != 0);
    try std.testing.expect(former_cache_fallback_count != 0);

    var state_snapshot = try CheckedBoundaryStateSnapshot.capture(
        std.testing.allocator,
        checker,
    );
    defer state_snapshot.deinit(std.testing.allocator);
    const live_ranges_before = try std.testing.allocator.alloc(
        ?types_mod.StaticDispatchConstraint.SafeList.Range,
        checker.types.checkedBoundaryDescriptorCount(),
    );
    defer std.testing.allocator.free(live_ranges_before);
    checker.types.snapshotCheckedBoundaryLiveConstraintRanges(live_ranges_before);

    const original_checker_gpa = checker.gpa;
    const original_types_gpa = checker.types.gpa;
    const original_cir_gpa = checker.cir.gpa;
    var fail_index: usize = 0;
    while (true) {
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = fail_index,
            // Force grow/remap paths through the same failure sequence as
            // fresh allocations; an in-place resize is not an OOM attempt.
            .resize_fail_index = 0,
        });
        const failing_gpa = failing.allocator();
        checker.gpa = failing_gpa;
        checker.types.gpa = failing_gpa;
        checker.cir.gpa = failing_gpa;

        checker.rebuildCheckedBoundaryWhereMethodState() catch |err| {
            checker.gpa = original_checker_gpa;
            checker.types.gpa = original_types_gpa;
            checker.cir.gpa = original_cir_gpa;
            try std.testing.expectEqual(error.OutOfMemory, err);
            try std.testing.expect(failing.has_induced_failure);

            try state_snapshot.expectUnchanged(checker);
            const live_ranges_after = try std.testing.allocator.alloc(
                ?types_mod.StaticDispatchConstraint.SafeList.Range,
                live_ranges_before.len,
            );
            defer std.testing.allocator.free(live_ranges_after);
            checker.types.snapshotCheckedBoundaryLiveConstraintRanges(live_ranges_after);
            try std.testing.expectEqualSlices(
                ?types_mod.StaticDispatchConstraint.SafeList.Range,
                live_ranges_before,
                live_ranges_after,
            );
            fail_index = std.math.add(usize, fail_index, 1) catch
                return error.TestUnexpectedResult;
            continue;
        };

        // Every successful replacement allocation is owned by this
        // loop-local failing allocator. Teardown must run inside its scope on
        // success, including if any assertion below returns early.
        defer {
            consumer.deinit();
            consumer_live = false;
        }
        try std.testing.expect(!failing.has_induced_failure);
        try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, checker.cir));
        try std.testing.expect(validateExpectedCallPlans(checker.cir));
        try std.testing.expect(checker.cir.where_marker_copy_occurrences.items.items.len != 0);
        try std.testing.expect(checker.cir.copied_open_literal_groups.items.items.len != 0);
        try std.testing.expect(checker.cir.copied_open_literal_events.items.items.len != 0);
        try std.testing.expectEqual(@as(u32, 0), checker.probe_depth);
        break;
    }
}

test "typecheck lifecycle publishes a terminal env and rejects a second checker" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("OneShotTypecheck", "{}");
    defer test_env.deinit();

    const cir = test_env.module_env;
    try std.testing.expectEqual(ModuleEnv.TypecheckState.checked_file, cir.typecheck_state);

    const builtin_env = test_env.builtin_module.env;
    const imported_modules: []const *const ModuleEnv = &.{builtin_env};
    const imported_validations: []const ValidatedModuleEnv = &.{test_env.builtin_validation};
    try std.testing.expectError(
        error.CorruptArtifact,
        init(
            std.testing.allocator,
            &cir.types,
            cir,
            .{ .envs = imported_modules, .modules = imported_validations },
            &test_env.module_envs,
            &cir.store.regions,
            test_env.checker.builtin_ctx,
        ),
    );

    // The lifecycle tag is not the only authority: clearing it cannot make
    // output owned by the completed checker into a canonical input again.
    cir.typecheck_state = .canonical_unchecked;
    defer cir.typecheck_state = .checked_file;
    try std.testing.expectError(
        error.CorruptArtifact,
        init(
            std.testing.allocator,
            &cir.types,
            cir,
            .{ .envs = imported_modules, .modules = imported_validations },
            &test_env.module_envs,
            &cir.store.regions,
            test_env.checker.builtin_ctx,
        ),
    );
}

