test "where alias declaration publications reject corrupt rank outcome and partition" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\a.Leaf : where [a.leaf : a -> Str]
        \\a.Parent : where [a.Leaf]
    ;
    var test_env = try TestEnv.init("AliasPublicationCorruption", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    const cir = test_env.module_env;
    const publications = cir.where_alias_declaration_publications.items.items;
    try std.testing.expectEqual(@as(usize, 2), publications.len);
    try std.testing.expectEqual(@as(u32, 1), publications[1].dependency_rank);

    const context = ImportResolution.producedSupplied(
        cir,
        .{ .envs = test_env.checker.imported_modules, .modules = test_env.checker.validated_imported_modules },
        .{ .envs = test_env.checker.owner_modules, .modules = test_env.checker.validated_owner_modules },
        test_env.checker.platform_dependency_index,
    );

    const saved_rank = publications[1].dependency_rank;
    publications[1].dependency_rank = saved_rank + 1;
    try std.testing.expectError(error.CorruptArtifact, validateWhereAliasExpansionContext(cir, context));
    publications[1].dependency_rank = saved_rank;

    const saved_outcome = publications[0].outcome;
    publications[0].outcome = std.math.maxInt(u32);
    try std.testing.expectError(error.CorruptArtifact, validateWhereAliasExpansionLocalState(&cir.types, cir));
    publications[0].outcome = saved_outcome;

    const saved_start = publications[1].expansions_start;
    publications[1].expansions_start +%= 1;
    try std.testing.expectError(error.CorruptArtifact, validateWhereAliasExpansionLocalState(&cir.types, cir));
    publications[1].expansions_start = saved_start;

    const saved_len = publications[0].expansions_len;
    publications[0].expansions_len = 0;
    try std.testing.expectError(error.CorruptArtifact, validateWhereAliasExpansionLocalState(&cir.types, cir));
    publications[0].expansions_len = saved_len;

    const publication_len = cir.where_alias_declaration_publications.items.items.len;
    cir.where_alias_declaration_publications.items.items.len = publication_len - 1;
    try std.testing.expectError(error.CorruptArtifact, validateWhereAliasExpansionLocalState(&cir.types, cir));
    cir.where_alias_declaration_publications.items.items.len = publication_len;

    const duplicate = cir.where_alias_declaration_publications.items.items[1];
    try cir.where_alias_declaration_publications.items.append(std.testing.allocator, duplicate);
    try std.testing.expectError(error.CorruptArtifact, validateWhereAliasExpansionLocalState(&cir.types, cir));
    cir.where_alias_declaration_publications.items.items.len = publication_len;
}

