test "where alias publication finalization remaps local Expected failure handles only" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\a.Good : where [a.good : a -> Str]
        \\a.Bad : where [a.Bad]
    ;
    var test_env = try TestEnv.init("AliasPublicationHandleRemap", source);
    defer test_env.deinit();
    const checker = &test_env.checker;
    const cir = test_env.module_env;
    const publications = cir.where_alias_declaration_publications.items.items;
    try std.testing.expectEqual(@as(usize, 2), publications.len);
    try std.testing.expectEqual(@as(usize, 0), cir.expected_failures.items.items.len);

    const canonical_checked_index: usize = if (publications[0].decodedOutcome() == .checked_error)
        0
    else if (publications[1].decodedOutcome() == .checked_error)
        1
    else
        return error.TestUnexpectedResult;
    std.mem.swap(
        ModuleEnv.WhereAliasDeclarationPublication,
        &publications[0],
        &publications[1],
    );
    const transient_checked_index: u32 = @intCast(1 - canonical_checked_index);

    _ = try cir.expected_failures.append(std.testing.allocator, .{
        .owner_node = 0,
        .site_node = 0,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.annotation_where_alias_publication_error),
        .raw_owner_var = 0,
        .raw_subject_var = 0,
        .raw_peer_var = ModuleEnv.ExpectedFailure.none,
        .constraint_index = ModuleEnv.ExpectedFailure.none,
        .slot = 0,
        .plan_index = ModuleEnv.ExpectedFailure.none,
        .subject_authority = ModuleEnv.SubjectAuthority.direct(
            0,
            .annotation_local_where_alias_checked_error,
            transient_checked_index,
        ),
        .cause_owner = ModuleEnv.CauseOwner.inactive(),
    });
    _ = try cir.expected_failures.append(std.testing.allocator, .{
        .owner_node = 0,
        .site_node = 0,
        .owner_kind = @intFromEnum(ModuleEnv.ExpectedFailure.OwnerKind.expression),
        .kind = @intFromEnum(ModuleEnv.ExpectedFailure.Kind.annotation_where_alias_publication_error),
        .raw_owner_var = 0,
        .raw_subject_var = 0,
        .raw_peer_var = ModuleEnv.ExpectedFailure.none,
        .constraint_index = ModuleEnv.ExpectedFailure.none,
        .slot = 1,
        .plan_index = ModuleEnv.ExpectedFailure.none,
        .subject_authority = ModuleEnv.SubjectAuthority.providerWhereAliasCheckedError(7, 9),
        .cause_owner = ModuleEnv.CauseOwner.providerWhereAliasCheckedError(7, 9),
    });

    const publications_before = try std.testing.allocator.dupe(
        ModuleEnv.WhereAliasDeclarationPublication,
        publications,
    );
    defer std.testing.allocator.free(publications_before);
    const expansions_before = try std.testing.allocator.dupe(
        ModuleEnv.WhereAliasExpansion,
        cir.where_alias_expansions.items.items,
    );
    defer std.testing.allocator.free(expansions_before);
    const failures_before = try std.testing.allocator.dupe(
        ModuleEnv.ExpectedFailure,
        cir.expected_failures.items.items,
    );
    defer std.testing.allocator.free(failures_before);

    for (0..4) |fail_index| {
        var failing_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = fail_index,
        });
        checker.gpa = failing_allocator.allocator();
        try std.testing.expectError(error.OutOfMemory, checker.finalizeWhereAliasExpansions());
        checker.gpa = std.testing.allocator;
        try std.testing.expectEqualSlices(
            ModuleEnv.WhereAliasDeclarationPublication,
            publications_before,
            publications,
        );
        try std.testing.expectEqualSlices(
            ModuleEnv.WhereAliasExpansion,
            expansions_before,
            cir.where_alias_expansions.items.items,
        );
        try std.testing.expectEqualSlices(
            u8,
            std.mem.sliceAsBytes(failures_before),
            std.mem.sliceAsBytes(cir.expected_failures.items.items),
        );
    }

    try checker.finalizeWhereAliasExpansions();
    try std.testing.expect(compareWhereAliasDeclarationPublications(publications[0], publications[1]) == .lt);
    const relocated_local = cir.expected_failures.items.items[0].subject_authority.decodedDirect().?;
    try std.testing.expectEqual(@as(u32, @intCast(canonical_checked_index)), relocated_local.local_record_index);
    const unchanged_provider = cir.expected_failures.items.items[1].subject_authority
        .decodedProviderWhereAliasCheckedError().?;
    try std.testing.expectEqual(@as(u32, 7), unchanged_provider.dependency_index);
    try std.testing.expectEqual(@as(u32, 9), unchanged_provider.publication_index);
}

