        .{
            .fn_name = checker.cir.idents.is_eq,
            .fn_var = second_callable,
            .origin = .{ .where_clause = .{} },
            .where_method_markers = second_markers,
            .constraint_evidence = second_evidence,
        },
        .{
            .fn_name = checker.cir.idents.is_eq,
            .fn_var = sibling_callable,
            .origin = .{ .where_clause = .{} },
            .where_method_markers = sibling_markers,
            .constraint_evidence = sibling_evidence,
        },
    });
    const scheme = try checker.types.freshFromContent(.{ .flex = Flex.init().withConstraints(constraints) });
    const first_constraint_index: u32 = @intFromEnum(constraints.start);
    const second_constraint_index = first_constraint_index + 1;
    const sibling_constraint_index = first_constraint_index + 2;

    // Exhaust the current backing allocation. Merging the second (duplicate)
    // row must therefore relocate the store before the iterator reaches the
    // distinct later sibling.
    while (checker.types.static_dispatch_constraints.items.items.len <
        checker.types.static_dispatch_constraints.items.capacity)
    {
        _ = try checker.types.appendStaticDispatchConstraints(&.{.{
            .fn_name = checker.cir.idents.is_eq,
            .fn_var = first_callable,
            .origin = .method_call,
        }});
    }
    const exhausted_capacity = checker.types.static_dispatch_constraints.items.capacity;
    const original_backing = checker.types.static_dispatch_constraints.items.items.ptr;
    const first_merged_index: u32 = @intCast(checker.types.static_dispatch_constraints.items.items.len);
    const evidence_moves_start = checker.cir.constraint_evidence_moves.items.items.len;

    // Refuse every in-place resize/remap while still allowing replacement
    // allocation. The duplicate row's merge must move the backing buffer, so
    // the distinct sibling is fetched only after the original slice would
    // have become dangling.
    var moving_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .resize_fail_index = 0,
    });
    const original_store_gpa = checker.types.gpa;
    checker.types.gpa = moving_allocator.allocator();
    defer checker.types.gpa = original_store_gpa;
    try checker.deduplicateGeneralizedDispatchRequirements(scheme);
    try std.testing.expect(checker.types.static_dispatch_constraints.items.capacity > exhausted_capacity);
    try std.testing.expect(checker.types.static_dispatch_constraints.items.items.ptr != original_backing);
    const retained_range = checker.types.resolveVar(scheme).desc.content.flex.constraints;
    try std.testing.expectEqual(@as(u32, 2), retained_range.len());
    const retained = checker.types.sliceStaticDispatchConstraints(retained_range);
    try std.testing.expectEqual(first_callable, retained[0].fn_var);
    try std.testing.expectEqual(@as(u32, 2), retained[0].where_method_markers.len());
    try std.testing.expectEqual(@as(u32, 2), retained[0].constraint_evidence.len);
    try std.testing.expectEqual(sibling_callable, retained[1].fn_var);
    try std.testing.expectEqual(@as(u32, 1), retained[1].where_method_markers.len());
    try std.testing.expectEqual(@as(u32, 1), retained[1].constraint_evidence.len);

    const retained_start: u32 = @intFromEnum(retained_range.start);
    const expected_moves = [_]struct {
        source: u32,
        destination: u32,
        handle_index: u32,
    }{
        .{ .source = first_constraint_index, .destination = first_merged_index, .handle_index = 10 },
        .{ .source = second_constraint_index, .destination = first_merged_index, .handle_index = 11 },
        .{ .source = first_merged_index, .destination = retained_start, .handle_index = 10 },
        .{ .source = first_merged_index, .destination = retained_start, .handle_index = 11 },
        .{ .source = sibling_constraint_index, .destination = retained_start + 1, .handle_index = 12 },
    };
    const appended_moves = checker.cir.constraint_evidence_moves.items.items[evidence_moves_start..];
    try std.testing.expectEqual(expected_moves.len, appended_moves.len);
    for (expected_moves) |expected| {
        var matches: usize = 0;
        for (appended_moves) |move| {
            matches += @intFromBool(
                move.source_constraint_index == expected.source and
                    move.destination_constraint_index == expected.destination and
                    move.handle.decodedKind() == .where_requirement_source and
                    move.handle.index == expected.handle_index,
            );
        }
        try std.testing.expectEqual(@as(usize, 1), matches);
    }
}

test "where method producer side-table generalized dedup unions every marker ref" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("MarkerSideTableDedup", "{}");
    defer test_env.deinit();
    const checker = &test_env.checker;

    const first_markers = try appendTestWhereMethodMarkerRef(checker, 1);
    const second_markers = try appendTestWhereMethodMarkerRef(checker, 2);
    const scheme = try checker.types.freshFromContent(.{ .structure = .empty_record });
    const receiver = try checker.types.freshFromContent(.{ .structure = .empty_record });
    const first_callable = try checker.types.freshFromContent(.{ .structure = .empty_record });
    const second_callable = try checker.types.freshFromContent(.{ .structure = .empty_record });
    const owned_constraints = try checker.types.appendStaticDispatchConstraints(&.{
        .{
            .fn_name = checker.cir.idents.is_eq,
            .fn_var = first_callable,
            .origin = .{ .where_clause = .{} },
            .where_method_markers = first_markers,
        },
        .{
            .fn_name = checker.cir.idents.is_eq,
            .fn_var = second_callable,
            .origin = .{ .where_clause = .{} },
            .where_method_markers = second_markers,
        },
    });
    const first_constraint_index: u32 = @intFromEnum(owned_constraints.start);
    const second_constraint_index = first_constraint_index + 1;
    const scheme_idx = try checker.ensureTypeScheme(scheme, .generalized);
    try checker.type_schemes.items[scheme_idx].dispatch_requirements.append(checker.gpa, .{
        .receiver_var = receiver,
        .constraint = checker.types.getStaticDispatchConstraintAt(first_constraint_index),
        .constraint_index = first_constraint_index,
        .deferred_generated_codec = false,
        .failure_expr = null,
        .structural_origin = .{ .receiver_var = receiver, .constraint_fn_var = first_callable },
    });
    try checker.type_schemes.items[scheme_idx].dispatch_requirements.append(checker.gpa, .{
        .receiver_var = receiver,
        .constraint = checker.types.getStaticDispatchConstraintAt(second_constraint_index),
        .constraint_index = second_constraint_index,
        .deferred_generated_codec = true,
        .failure_expr = null,
        .structural_origin = .{ .receiver_var = receiver, .constraint_fn_var = second_callable },
    });

    try checker.deduplicateGeneralizedDispatchRequirements(scheme);
    const retained = &checker.type_schemes.items[scheme_idx].dispatch_requirements;
    try std.testing.expectEqual(@as(usize, 1), retained.items.len);
    try std.testing.expect(retained.items[0].deferred_generated_codec);
    try std.testing.expectEqual(@as(u32, 2), retained.items[0].constraint.where_method_markers.len());
    try std.testing.expect(std.meta.eql(
        retained.items[0].constraint,
        checker.types.getStaticDispatchConstraintAt(retained.items[0].constraint_index),
    ));
}

