fn validateDerivedEncodeNominal(
    self: *Self,
    nominal_var: Var,
    nominal: types_mod.NominalType,
    encoding_var: Var,
    state_var: Var,
    err_var: Var,
    constraint: StaticDispatchConstraint,
    env: *Env,
    region: Region,
    walk: *DerivedCodecWalk,
) Allocator.Error!DerivedParseValidation {
    if (self.nominalIsBuiltinBoolType(nominal)) {
        return try self.validateEncodeFormatMethod(encoding_var, state_var, nominal_var, .bool, err_var, constraint, env, region);
    }
    if (self.nominalIsBuiltinStrType(nominal)) {
        return try self.validateEncodeFormatMethod(encoding_var, state_var, nominal_var, .str, err_var, constraint, env, region);
    }
    if (self.builtinNumKindFromNominalType(nominal)) |num_kind| {
        return try self.validateEncodeFormatMethod(encoding_var, state_var, nominal_var, encodeSpecDeclForNumKind(num_kind), err_var, constraint, env, region);
    }
    // A user opaque over a builtin scalar (`Money := F64`, `Username := Str`) validates its derived
    // encoder through the backing scalar, threading the same err_var: error-row unification then
    // rejects a fallible backing (F32/F64) exactly as a bare scalar is, and passes an infallible one
    // (Str/Bool/int/Dec), instead of slipping through to a lowering panic.
    // `varResolvesToBuiltinScalarNominal` admits only ground scalars, so the declaration's backing
    // template equals the instance here and is safe to unify directly.
    if (self.nominalDeclBackingTemplate(nominal)) |backing_var| {
        if (self.varResolvesToBuiltinScalarNominal(backing_var)) {
            return try self.validateDerivedEncodeVar(backing_var, encoding_var, state_var, err_var, constraint, env, region, walk);
        }
    }
    if (self.nominalListPayloadVar(nominal)) |payload_var| {
        switch (try self.validateDerivedEncodeListMethods(encoding_var, state_var, err_var, constraint, env, region)) {
            .ok => {},
            .unsupported, .reported_error => |result| return result,
        }
        return try self.validateDerivedEncodeVar(payload_var, encoding_var, state_var, err_var, constraint, env, region, walk);
    }
    if (self.nominalBoxPayloadVar(nominal)) |payload_var| {
        return try self.validateDerivedEncodeVar(payload_var, encoding_var, state_var, err_var, constraint, env, region, walk);
    }
    if (self.nominalSetPayloadVar(nominal)) |payload_var| {
        switch (try self.validateDerivedEncodeListMethods(encoding_var, state_var, err_var, constraint, env, region)) {
            .ok => {},
            .unsupported, .reported_error => |result| return result,
        }
        switch (try self.validateSetToListMethod(nominal_var, nominal, payload_var, constraint, env, region)) {
            .ok => {},
            .unsupported, .reported_error => |result| return result,
        }
        return try self.validateDerivedEncodeVar(payload_var, encoding_var, state_var, err_var, constraint, env, region, walk);
    }
    if (self.nominalDictKeyValueVars(nominal)) |args| {
        switch (try self.validateDerivedEncodeDictMethods(encoding_var, state_var, err_var, constraint, env, region)) {
            .ok => {},
            .unsupported, .reported_error => |result| return result,
        }
        if (try self.varSupportsStringRenderedDictKey(args.key)) {
            switch (try self.validateEncodeKeyMethod(args.key, encoding_var, state_var, err_var, constraint, env, region)) {
                .ok => {},
                .unsupported, .reported_error => |result| return result,
            }
            if (try self.varIsClosedUnitTagUnion(args.key)) {
                const str_var = try self.freshStr(env, region);
                switch (try self.validateEncodeKeyMethod(str_var, encoding_var, state_var, err_var, constraint, env, region)) {
                    .ok => {},
                    .unsupported, .reported_error => |result| return result,
                }
            }
        } else {
            // Mirrors the parse side: `encode_key_start` is what admits a key
            // the format cannot render as a key string.
            switch (try self.validateDictProtocolMethod(encoding_var, state_var, "encode_key_start", try self.freshFromContent(try self.mkTryContent(state_var, err_var), env, region), constraint, env, region, null)) {
                .ok => {},
                .unsupported, .reported_error => |result| return result,
            }
            switch (try self.validateDerivedEncodeVar(args.key, encoding_var, state_var, err_var, constraint, env, region, walk)) {
                .ok => {},
                .unsupported, .reported_error => |result| return result,
            }
        }
        switch (try self.validateDictToListMethod(nominal_var, nominal, args.key, args.value, constraint, env, region)) {
            .ok => {},
            .unsupported, .reported_error => |result| return result,
        }
        return try self.validateDerivedEncodeVar(args.value, encoding_var, state_var, err_var, constraint, env, region, walk);
    }
    if (self.nominalIsBuiltinTryType(nominal)) {
        const info = try self.nullTryInfoFromNominal(nominal) orelse return .unsupported;
        switch (try self.validateEncodeFormatMethod(encoding_var, state_var, state_var, .null, err_var, constraint, env, region)) {
            .ok => {},
            .unsupported, .reported_error => |result| return result,
        }
        return try self.validateDerivedEncodeVar(info.ok_var, encoding_var, state_var, err_var, constraint, env, region, walk);
    }

    const original_env, _ = self.ownerEnvForOriginModule(
        nominal.origin_module,
        nominal.sourceDeclOptional(),
        nominal.originIsBuiltin(),
        "encoder_for nominal field",
    );
    const method_lookup = self.lookupStaticDispatchMethodBinding(
        original_env,
        nominal.sourceDeclOptional(),
        self.cir,
        self.cir.idents.encoder_for,
    ) orelse {
        return try self.reportDerivedParseMissingMethod(nominal_var, self.cir.idents.encoder_for, constraint, env);
    };

    const expected_ret = try self.freshFromContent(try self.mkTryContent(state_var, err_var), env, region);
    const expected_runtime_fn = try self.freshFromContent(try self.types.mkFuncUnbound(&.{ nominal_var, state_var }, expected_ret), env, region);
    const expected_fn = try self.freshFromContent(try self.types.mkFuncUnbound(&.{encoding_var}, expected_runtime_fn), env, region);
    const method_var = try self.instantiateGeneratedCodecMethodTarget(method_lookup, expected_fn, env, region);
    const result = try self.unifyInContext(method_var, expected_fn, env, .{
        .method_type = .{
            .constraint_var = nominal_var,
            .dispatcher_name = nominal.ident.ident_idx,
            .method_name = constraint.fn_name,
        },
    });
    if (result.isEstablished() and isGeneratedStructuralCodecMethodBinding(method_lookup, .encoder)) {
        switch (try self.takeDerivedCodecBackingWalk(walk, nominal)) {
            .accounted_for => {},
            .unbounded => return .unsupported,
            .walk_backing => {
                walk.nominal_backing_depth += 1;
                defer walk.nominal_backing_depth -= 1;
                const nested_calls_start = self.scratch_generated_codec_calls.items.len;
                defer self.scratch_generated_codec_calls.shrinkRetainingCapacity(nested_calls_start);
                const backing_var = ((try self.openNominalBackingForApp(nominal, env, region, null)) orelse
                    return .reported_error).var_;
                switch (try self.validateDerivedEncodeVar(
                    backing_var,
                    encoding_var,
                    state_var,
                    err_var,
                    constraint,
                    env,
                    region,
                    walk,
                )) {
                    .ok => try self.recordGeneratedCodecDerivationSnapshot(
                        .encoder,
                        expected_fn,
                        expected_runtime_fn,
                        nominal_var,
                        encoding_var,
                        state_var,
                        err_var,
                        self.scratch_generated_codec_calls.items[nested_calls_start..],
                        env,
                        region,
                    ),
                    .unsupported, .reported_error => |validation| return validation,
                }
            },
        }
    }
    return try self.finishGeneratedCodecMethodValidation(
        result,
        self.cir.idents.encoder_for,
        nominal_var,
        expected_fn,
        expected_fn,
        nominal_var,
    );
}

const FlexConstraintCompatibilityOptions = struct {
    /// The exact callable obligations to validate. When no target is supplied,
    /// the receiver's attached constraints still choose its specialization
    /// default; this range says which independently copied edges need proof
    /// against that owner.
    constraints: ?StaticDispatchConstraint.SafeList.Range = null,
    /// Target already selected by the pinning-frontier/defaulting judgment.
    /// Supplying it keeps exact per-edge validation linear in the number of
    /// obligations instead of rescanning the receiver range for every edge.
    default_target: ?literal_defaulting.DefaultTarget = null,
    /// Stable transient selection draft authorizing `default_target`. Required
    /// for specialization; terminal publication remaps it to the durable row.
    default_decision_draft_index: ?u32 = null,
    /// Producer-authored ordinary-literal event. Ordinary compatibility joins
    /// or reserves its explicit decision draft before copying any method.
    open_literal_driver: ?OpenLiteralDriver = null,
    /// Relative start within the durable decision's complete constraint range.
    /// Exact copied-edge validation may check one row at a time, but origins
    /// always retain offsets relative to the complete selected range.
    default_constraint_offset_base: u32 = 0,
    allow_generalized: bool = false,
    allow_arithmetic_default: bool = false,
    error_expr: ?CIR.Expr.Idx = null,
};

/// Check if a flex var's specialization default satisfies all its constraints.
/// Ordinary generalized schemes remain abstract; a recorded instantiated copy
/// may be checked after generalization because its exact use expression is
/// supplied in `options` and owns any resulting runtime error.
fn checkFlexVarConstraintCompatibility(
    self: *Self,
    var_: Var,
    env: *Env,
    is_numeric_default_pass: bool,
    options: FlexConstraintCompatibilityOptions,
) Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (resolved.desc.rank == .generalized and !options.allow_generalized) return false;

    if ((options.default_target != null) != (options.constraints != null)) {
        std.debug.panic("exact default compatibility supplied only half of its target/range selection", .{});
    }
    const has_exact_selected_target = options.default_target != null;
    const default_constraints_range = if (resolved.desc.content == .flex)
        resolved.desc.content.flex.constraints
    else if (has_exact_selected_target)
        options.constraints.?
    else
        return false;
    if (default_constraints_range.len() == 0) return false;

    const default_constraints = self.types.sliceStaticDispatchConstraints(default_constraints_range);
    const default_target = options.default_target orelse if (options.allow_arithmetic_default) blk: {
        // Instantiated, unpinned where-clause receivers are materialized by
        // publication using this exact specialization rule, including its
        // arithmetic-only Dec default. Validate the same explicit target here.
        break :blk self.specializationDefaultTargetForConstraints(default_constraints) orelse return false;
    } else blk: {
        // Ordinary flex compatibility is only for variables carrying literal
        // provenance. Arithmetic-only flexes remain polymorphic until a later
        // specialization explicitly materializes them.
        const kind = literal_defaulting.dominantKind(self.literalMethodIdents(), default_constraints) orelse return false;
        break :blk literal_defaulting.defaultTargetForKind(kind);
    };

    const constraints_range = options.constraints orelse default_constraints_range;
    if ((options.default_decision_draft_index != null) == (options.open_literal_driver != null)) {
        std.debug.panic("default compatibility must carry exactly one producer-authored driver", .{});
    }
    if (has_exact_selected_target != (options.default_decision_draft_index != null)) {
        std.debug.panic("specialization default compatibility omitted or spuriously carried its decision draft", .{});
    }
    const decision_draft_index = options.default_decision_draft_index orelse
        try self.registerDefaultDecisionDraft(
            resolved.var_,
            default_constraints_range,
            default_target,
            options.open_literal_driver.?,
        );
    {
        if (decision_draft_index >= self.default_decision_drafts.items.len) {
            std.debug.panic("default compatibility named an absent decision draft", .{});
        }
        const decision = self.default_decision_drafts.items[decision_draft_index];
        if (decision.receiver_var != resolved.var_ or
            @intFromEnum(decision.constraints.start) + options.default_constraint_offset_base !=
                @intFromEnum(constraints_range.start) or
            options.default_constraint_offset_base > decision.constraints.len() or
            constraints_range.len() > decision.constraints.len() - options.default_constraint_offset_base)
        {
            std.debug.panic("default compatibility did not match its exact decision receiver/range", .{});
        }
        if (decision.target != default_target) {
            std.debug.panic("default compatibility target differed from its decision draft", .{});
        }
    }

    // Validate that all other constraints can be satisfied by the default type.
    const builtin_env = self.builtin_ctx.builtin_module orelse return false;
    const indices = self.builtin_ctx.builtin_indices orelse return false;
    const default_type_stmt = switch (default_target) {
        .dec => indices.dec_type,
        .str => indices.str_type,
    };
    const default_type_ident = switch (default_target) {
        .dec => self.cir.idents.dec_type,
        .str => self.cir.idents.str,
    };
    const region = self.getRegionAt(var_);

    const constraints_start: usize = @intFromEnum(constraints_range.start);
    var had_error = false;
    var constraint_i: usize = 0;
    while (constraint_i < constraints_range.len()) : (constraint_i += 1) {
        // Instantiating and unifying the method below can grow the constraint
        // store, so re-fetch each entry instead of retaining a backing slice.
        const constraint = self.types.static_dispatch_constraints.items.items[constraints_start + constraint_i];

        // A constraint already rejected durably has its diagnostic; the
        // receiver stays flex after a rejected validation (the commit-probe
        // rolls the attempt back without poisoning), so a later visit of the
        // same equivalence class—another worklist entry or dispatcher record
        // resolving to it—must not re-validate and re-report the identical
        // mismatch.
        if (self.staticDispatchConstraintIsInactive(constraint)) continue;

        // Skip the literal-origin constraint the default type satisfies by
        // definition. (With both literal kinds present, the var defaults to Dec and
        // the from_quote constraint must still be validated against it.)
        switch (constraint.origin) {
            .from_literal => |lit| switch (lit) {
                .numeral => if (default_target == .dec) continue,
                .quote, .interpolation => if (default_target == .str) continue,
            },
            .desugared_binop,
            .desugared_unaryop,
            .method_call,
            .where_clause,
            => {},
        }

        // Validate the exact method type, not only its name. A default owner can
        // have a same-named method whose signature does not discharge this
        // constraint; publishing that name as evidence would defer a typing
        // error until post-check lowering.
        const method_entry = builtin_env.lookupMethodBindingEntryFromTwoEnvsAndDeclConst(
            @intFromEnum(default_type_stmt),
            self.cir,
            constraint.fn_name,
        ) orelse {
            try self.reportConstraintErrorAt(
                var_,
                constraint,
                .{ .missing_method = .nominal },
                env,
                is_numeric_default_pass,
                options.error_expr,
            );
            had_error = true;
            continue;
        };
        const method_binding = method_entry.binding;
        const method_lookup: StaticDispatchMethodBinding = .{
            .env = builtin_env,
            .is_this_module = false,
            .binding = method_binding,
            .provider_method_entry_index = method_entry.entry_index,
        };
        // Capture the parent before importing or instantiating the target can
        // record child obligations. A prior selection of this exact raw edge
        // is already its sole target; default compatibility reuses that
        // committed fact without publishing new default provenance.
        const parent_constraint_fn_var = self.dispatch_derivation_by_child_fn_var.get(constraint.fn_var);
        if (self.cachedDispatchTargetInstantiationIndex(
            constraint,
            parent_constraint_fn_var,
            method_lookup,
        ) != null) continue;

        const imported_scheme = try self.importedMethodSchemeFromSource(
            builtin_env,
            method_binding.type_node_idx,
            .{
                .default_method = .{
                    // Transient draft id; `finalizeDefaultDecisionDrafts` remaps
                    // every such origin atomically before checked publication.
                    .decision_index = decision_draft_index,
                    .constraint_offset = options.default_constraint_offset_base + @as(u32, @intCast(constraint_i)),
                    // A selected target exists before a compatible method use
                    // does. Only the successful child step names a SchemeUse.
                    .reserved_0 = 0,
                    .builtin_decl_index = @intFromEnum(default_type_stmt),
                    .provider_type_node = @intFromEnum(method_binding.type_node_idx),
                    .provider_def = @intFromEnum(method_binding.def_idx),
                },
            },
        );
        const imported_scheme_index = self.imported_method_scheme_by_source.get(.{
            .env = builtin_env,
            .type_node_idx = method_binding.type_node_idx,
        }) orelse std.debug.panic("default method cache omitted its exact imported root", .{});
        const imported_scheme_entry = self.imported_method_schemes.items[imported_scheme_index];
        if (imported_scheme_entry.scheme_var != imported_scheme or
            imported_scheme_entry.copy_step >= self.cir.where_marker_copy_steps.items.items.len)
        {
            std.debug.panic("default method cache returned a mismatched root entry", .{});
        }
        const target_arity = self.callableArity(imported_scheme);
        const constraint_arity = self.callableArity(constraint.fn_var);

        // An outer-arity difference is already an exact proof of failure and
        // avoids allocating a throwaway target instantiation. Every remaining
        // case is validated speculatively: instantiate the default owner's
        // method and unify it against the recorded relation inside a
        // commit-probe. Success commits in place—the real unify wrapper
        // already propagated regions, ranks, and deferred constraints into the
        // live env. Failure rolls the entire attempt back as one unit: the
        // store's partial merges, the nested obligations the incompatible
        // target's own scheme recorded, and every evidence buffer the attempt
        // grew—so a rejected target leaves the receiver, and every var
        // reachable through the relation's argument graph, exactly as they
        // stood. (Obligations deferred before this attempt survive; only the
        // attempt's own recordings vanish with the store rewind.)
        const target_accepted = accepted: {
            if (target_arity != null and constraint_arity != null and target_arity.? != constraint_arity.?) {
                break :accepted false;
            }

            // Selection state belongs to the edge immediately before its sole
            // target copy/unification. Recursive rejection is committed and
            // therefore deliberately happens outside the compatibility probe.
            const prepared = (try self.prepareDispatchTargetInstantiation(
                var_,
                parent_constraint_fn_var,
                constraint,
                method_lookup,
                env,
                options.error_expr,
            )) orelse {
                had_error = true;
                continue;
            };
            // Reserve both sides of the raw-edge cache before the target-copy
            // transaction. Publication itself is then infallible and the
            // CommitProbe can roll child evidence and the cache row back as a
            // single suffix on signature failure or later allocation failure.
            try self.ensureDispatchTargetInstantiationCapacity();

            var commit_probe = try self.beginCommitProbe(env);
            var committed = false;
            defer if (!committed) commit_probe.rollback();

            const method_var = method_var: {
                const previous_evidence_target_site = self.evidence_target_site;
                self.evidence_target_site = .{
                    .node_idx = if (constraintIntroExpr(constraint)) |expr| @intFromEnum(expr) else 0,
                    .constraint_fn_var = constraint.fn_var,
                };
                defer self.evidence_target_site = previous_evidence_target_site;

                break :method_var try self.instantiateDefaultMethodSchemeUse(
                    imported_scheme,
                    env,
                    .{ .explicit = region },
                    decision_draft_index,
                    options.default_constraint_offset_base + @as(u32, @intCast(constraint_i)),
                    imported_scheme_entry.copy_step,
                );
            };

            // The mismatch is reported below, after the rollback, against the
            // pristine relation—occurrence-directed poisoning must not run
            // under the savepoint.
            const result = try commit_probe.unify(method_var, constraint.fn_var);
            if (!result.isEstablished()) break :accepted false;

            self.publishDispatchTargetInstantiation(prepared, method_var);
            committed = true;
            commit_probe.commit();
            break :accepted true;
        };
        if (!target_accepted) {
            // Report the signature mismatch against the untouched types the
            // rollback restored: the default owner's declared scheme versus
            // the relation as the program actually constrained it.
            const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, imported_scheme);
            const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, constraint.fn_var);
            _ = try self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
                .types = .{
                    .expected_var = imported_scheme,
                    .expected_snapshot = expected_snapshot,
                    .actual_var = constraint.fn_var,
                    .actual_snapshot = actual_snapshot,
                },
                .context = .{ .method_type = .{
                    .constraint_var = var_,
                    .source_region = if (options.error_expr) |expr_idx|
                        self.cir.store.getExprRegion(expr_idx)
                    else
                        null,
                    .dispatcher_name = default_type_ident,
                    .method_name = constraint.fn_name,
                } },
            } });

            // Checking owns both the diagnostic and the executable failure.
            // The source expression becomes a runtime error, while the exact
            // rejected obligation tells publication to emit `checked_error`.
            try self.poisonConstraintFailureSource(var_, constraint, options.error_expr);
            try self.markStaticDispatchRejected(constraint);
            had_error = true;
        }
    }

    return had_error;
}

fn checkAllFromNumeralFlexConstraintCompatibility(
    self: *Self,
    env: *Env,
    is_numeric_default_pass: bool,
) Allocator.Error!void {
    // Iterate the tracked open-literal worklist, not the whole store;
    // `checkFlexVarConstraintCompatibility` re-resolves and no-ops on non-literal
    // or already-resolved vars.
    const literal_count = self.open_literal_vars.items.len;
    if (literal_count != self.open_literal_creation_drivers.items.len) {
        std.debug.panic("literal worklist lost its producer-authored driver alignment", .{});
    }
    var i: usize = 0;
    while (i < literal_count) : (i += 1) {
        _ = try self.checkFlexVarConstraintCompatibility(
            self.open_literal_vars.items[i],
            env,
            is_numeric_default_pass,
            .{ .open_literal_driver = self.open_literal_creation_drivers.items[i].driver },
        );
    }
}

/// Record a branch-body-vs-expected `type_mismatch` with roles fixed by the
/// caller: the branch body is the "actual", the shared return is the "expected".
/// This is what makes the rendered message + region correct regardless of the
/// merge operand order used to commit the types.
fn recordBranchTypeMismatch(self: *Self, body_var: Var, expected_ret: Var, ctx: problem.Context) std.mem.Allocator.Error!void {
    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, expected_ret);
    const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, body_var);
    _ = try self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
        .types = .{
            .expected_var = expected_ret,
            .expected_snapshot = expected_snapshot,
            .actual_var = body_var,
            .actual_snapshot = actual_snapshot,
        },
        .context = ctx,
    } });
}

/// Probe whether `body_var` can unify with `target`, recording and committing
/// nothing: run the non-recording raw-unifier probe inside a `beginProbe` scope,
/// then always roll back. Nothing in the live solver state is disturbed.
fn probeBranchCompatible(self: *Self, body_var: Var, target: Var) std.mem.Allocator.Error!bool {
    var probe = try self.beginProbe(null);
    defer probe.rollback();
    return try self.probeUnifyWithoutRecordingProblems(body_var, target);
}

/// Record a branch-vs-`mismatch_against` diagnostic (actual = branch body),
/// queue the exact raw body for the centralized runtime-error rewrite, and
/// poison only that body's own solved class. The pristine Expected class is
/// diagnostic authority, never an error redirect target.
fn reportBranchMismatchAndQueueError(
    self: *Self,
    body_expr_idx: CIR.Expr.Idx,
    body_var: Var,
    mismatch_against: Var,
    ctx: problem.Context,
) std.mem.Allocator.Error!void {
    try self.recordBranchTypeMismatch(body_var, mismatch_against, ctx);
    try self.erroneous_value_exprs.put(self.gpa, body_expr_idx, {});
    try self.markErroneous(body_var);
}

/// Check one if/match branch body against the shared expected return type, and
/// fold a compatible body into the per-expression accumulator `acc`.
///
/// `acc` is a fresh var owned by the enclosing `checkIfElseExpr` /
/// `checkMatchExpr`; it accumulates the meet of every compatible branch body and
/// is unified with the shared `expected_ret` exactly once, at the end of the
/// expression. Branches therefore never merge into `expected_ret` directly: the
/// shared annotated return var is no longer the per-branch union-find hub, so
/// the "which operand survives" question (see `store.union_`) can no longer
/// affect branch checking, and one earlier branch can no longer refine the
/// annotation seen by a later branch.
///
/// Branch bodies are checked in two steps, so a failed fold can never corrupt
/// `acc` (or `expected_ret`):
///   1. A pure, fully-rolled-back probe (see `probeBranchCompatible`) against the
///      pristine `expected_ret`: catches a body that does not match the annotated
///      return type. Reported against `expected_ret`. This MUST stay a
///      rolled-back probe—branches never merge into the shared annotation var
///      (see above).
///   2. One real unify against `acc` inside a `CommitProbe`: the fold and the
///      compatibility check are the same operation. Success commits in place—the
///      wrapper already propagated regions/rank/deferred-constraints into the live
///      `env`, so nothing is redone. Failure catches a body that matches the
///      annotation yet diverges from an earlier sibling already folded in—only
///      observable when the annotation is LOOSER than the accumulated branches,
///      e.g. an inferred `_` return, where step (1) passes for every branch but
///      the branches still disagree. The commit-probe rollback then restores every
///      store and buffer (including the unifier's own mismatch problem and
///      snapshots), leaving `body_var` and `acc` pristine, and the mismatch is
///      reported against `acc`.
/// `expected_ret` stays untouched on every path.
fn checkBranchBodyAgainstExpected(
    self: *Self,
    branch_owner: CIR.Expr.Idx,
    body_expr_idx: CIR.Expr.Idx,
    expected_ret: Var,
    acc: *Var,
    authority: *ExpectedParentAuthority,
    seed_plan_index: u32,
    expected_plan_index: u32,
    body_status: CheckedExprStatus,
    ctx: problem.Context,
    env: *Env,
) std.mem.Allocator.Error!void {
    const body_var = ModuleEnv.varFrom(body_expr_idx);
    if (expected_plan_index >= self.cir.expected_consumption_plans.items.items.len) {
        std.debug.panic("branch body lost its exact contribution plan", .{});
    }
    const plan = &self.cir.expected_consumption_plans.items.items[expected_plan_index];
    if (plan.decodedRole() != .branch_contribution or
        plan.decodedOutcome() != .reserved or
        plan.owner_node != @intFromEnum(branch_owner) or
        plan.site_node != @intFromEnum(body_expr_idx) or
        plan.raw_consumer_var != @intFromEnum(body_var) or
        self.expectedParentAuthorityRawVar(authority.*) != acc.*)
    {
        std.debug.panic("branch body contribution changed its producer plan", .{});
    }

    switch (body_status) {
        .established => {},
        .checked_error => |cause| {
            settleExpectedPlanWithoutProducedEndpoint(
                plan,
                .checked_error,
                .branch_body_error_short_circuit,
                encodeExpectedParentAuthority(authority.*),
                cause,
                ModuleEnv.ExpectedConsumptionPlan.none,
            );
            return;
        },
    }

    // A few legacy expression producers queue their exact raw owner for the
    // centralized runtime-error rewrite before ExprCheckFrame has a typed
    // status channel. Consume that producer-authored queue entry now and mint
    // the durable body-retirement cause; the solved `.err` is only checked as
    // consistency and never selects this path.
    if (self.erroneous_value_exprs.contains(body_expr_idx)) {
        if (self.types.resolveVar(body_var).desc.content != .err) {
            std.debug.panic("queued erroneous branch body did not carry its producer error", .{});
        }
        var publication = try self.beginLocalMarkerCopyTransaction(env);
        defer publication.rollback();
        const cause = try self.reserveBranchBodyRetirement(body_expr_idx);
        settleExpectedPlanWithoutProducedEndpoint(
            plan,
            .checked_error,
            .branch_body_error_short_circuit,
            encodeExpectedParentAuthority(authority.*),
            cause,
            ModuleEnv.ExpectedConsumptionPlan.none,
        );
        publication.commit();
        return;
    }

    // An already-unified body truthfully retains the immediately preceding
    // branch authority; it does not publish a fabricated replacement copy.
    // If body already resolves to expected, it is correctly constrained and we
    // must NOT fold it into `acc`—that would run `unify(expected_ret, acc)` and
    // redirect the shared expected var into the accumulator (the very mutation
    // this accumulator design exists to avoid).
    const rb = self.types.resolveVar(body_var);
    const re = self.types.resolveVar(expected_ret);
    if (rb.desc.content == .err or re.desc.content == .err) {
        std.debug.panic(
            "established branch relation observed unauthenticated solved error state",
            .{},
        );
    }
    if (rb.var_ == re.var_) {
        if (seed_plan_index >= self.cir.expected_consumption_plans.items.items.len) {
            std.debug.panic("retained branch body lost its exact seed plan", .{});
        }
        const seed_plan = self.cir.expected_consumption_plans.items.items[seed_plan_index];
        if (seed_plan.decodedRole() != .branch_seed or
            seed_plan.decodedOutcome() != .anchored)
        {
            std.debug.panic("retained branch body named a non-anchored seed", .{});
        }
        const pristine_authority = decodeExpectedParentAuthority(seed_plan.parent_authority);
        if (self.types.resolveVar(self.expectedParentAuthorityRawVar(pristine_authority)).var_ != rb.var_) {
            std.debug.panic("retained branch body did not equal its pristine Expected authority", .{});
        }
        settleExpectedPlanWithoutProducedEndpoint(
            plan,
            .retained,
            .branch_body_already_expected,
            encodeExpectedParentAuthority(pristine_authority),
            ModuleEnv.CauseOwner.inactive(),
            ModuleEnv.ExpectedConsumptionPlan.none,
        );
        return;
    }

    // Probe (1): does the body match the annotated return type?
    if (!try self.probeBranchCompatible(body_var, expected_ret)) {
        try self.reportBranchMismatchAndQueueError(body_expr_idx, body_var, expected_ret, ctx);
        var publication = try self.beginLocalMarkerCopyTransaction(env);
        defer publication.rollback();
        const cause = try self.reserveBranchBodyRetirement(body_expr_idx);
        settleExpectedPlanWithoutProducedEndpoint(
            plan,
            .checked_error,
            .branch_expected_compatibility_rejected,
            encodeExpectedParentAuthority(authority.*),
            cause,
            ModuleEnv.ExpectedConsumptionPlan.none,
        );
        publication.commit();
        return;
    }

    // Step (2): fold the body into the accumulator with one real unify inside a
    // commit-probe. Success keeps the merge (regions/rank/deferred constraints
    // already propagated into env); failure falls through to the report below
    // AFTER the scope's rollback, so the snapshots it takes see the pristine vars.
    {
        var commit_probe = try self.beginCommitProbe(env);
        var committed = false;
        defer if (!committed) commit_probe.rollback();

        const result = try commit_probe.unifyInContext(body_var, acc.*, ctx);
        if (result.isEstablished()) {
            committed = true;
            commit_probe.commit();
            const prior_authority = authority.*;
            self.completeExpectedBranchRelatedPlan(
                expected_plan_index,
                body_var,
                prior_authority,
            );
            // The successful relation is the evidence. The semantic
            // accumulator remains the exact same raw variable; a detached
            // destination copy would have no typing role and would incorrectly
            // enqueue its inherited where constraints as live dispatches.
            authority.* = .{ .relation_plan = .{
                .plan_index = expected_plan_index,
                .raw_var = acc.*,
            } };
            return;
        }
    }

    // The body matches the annotation (step 1) yet diverges from an earlier sibling
    // already folded into `acc`; rollback has restored everything the failed unify
    // touched. (Distinct from a step-(1) failure only when the annotation is looser
    // than `acc`.)
    try self.reportBranchMismatchAndQueueError(body_expr_idx, body_var, acc.*, ctx);
    var publication = try self.beginLocalMarkerCopyTransaction(env);
    defer publication.rollback();
    const cause = try self.reserveBranchBodyRetirement(body_expr_idx);
    settleExpectedPlanWithoutProducedEndpoint(
        plan,
        .checked_error,
        .branch_accumulator_fold_rejected,
        encodeExpectedParentAuthority(authority.*),
        cause,
        ModuleEnv.ExpectedConsumptionPlan.none,
    );
    publication.commit();
}

/// Relate the unchanged accumulator to the exact CIR owner and pristine
/// Expected root. The relation-plan row and both solver relations share one
/// rollback boundary; no unused destination copy is created.
fn completeExpectedBranchFinal(
    self: *Self,
    owner: CIR.Expr.Idx,
    expected_ret: Var,
    acc: Var,
    authority: ExpectedParentAuthority,
    plans: ExpectedBranchPlanRange,
    env: *Env,
) std.mem.Allocator.Error!void {
    if (self.expectedParentAuthorityRawVar(authority) != acc) {
        std.debug.panic("branch final relation lost its immediately preceding authority", .{});
    }
    const final_plan = &self.cir.expected_consumption_plans.items.items[plans.final_plan];
    if (final_plan.decodedRole() != .branch_final or
        final_plan.decodedOutcome() != .reserved or
        final_plan.owner_node != @intFromEnum(owner) or
        final_plan.site_node != @intFromEnum(owner) or
        final_plan.raw_consumer_var != @intFromEnum(ModuleEnv.varFrom(owner)))
    {
        std.debug.panic("branch final relation changed its exhaustive plan", .{});
    }

    var publication = try self.beginLocalMarkerCopyTransaction(env);
    defer publication.rollback();
    const owner_var = ModuleEnv.varFrom(owner);
    // The surrounding transaction owns the one Store savepoint for both
    // relations. Running the full wrapper directly retains rank/region and
    // deferred-constraint bookkeeping without nesting a CommitProbe.
    const owner_result = try self.runUnify(
        owner_var,
        acc,
        env,
        .{ .on_mismatch = .write_no_report },
    );
    const expected_result = if (owner_result.isEstablished())
        try self.runUnify(
            owner_var,
            expected_ret,
            env,
            .{ .on_mismatch = .write_no_report },
        )
    else
        owner_result;
    if (owner_result.isEstablished() and expected_result.isEstablished()) {
        self.completeExpectedBranchRelatedPlan(
            plans.final_plan,
            owner_var,
            authority,
        );
        publication.commit();
        return;
    }
    publication.rollback();

    try self.recordBranchTypeMismatch(owner_var, expected_ret, .none);
    try self.erroneous_value_exprs.put(self.gpa, owner, {});
    try self.markErroneous(owner_var);
    var rejection = try self.beginLocalMarkerCopyTransaction(env);
    defer rejection.rollback();
    const cause = try self.reserveExpectedPlanRetirement(
        owner,
        plans.seed_plan,
        plans.contributions_len + 2,
        .branch_retired_after_failure,
    );
    settleExpectedPlanWithoutProducedEndpoint(
        final_plan,
        .checked_error,
        .branch_final_relation_rejected,
        encodeExpectedParentAuthority(authority),
        cause,
        ModuleEnv.ExpectedConsumptionPlan.none,
    );
    rejection.commit();
}

/// Check if a type variable contains any error types anywhere in its structure.
/// This is used to determine if an expression's type contains errors, in which case
/// we should use the annotation type for the pattern instead of the expression type.
/// This handles cases like `Error -> Error` where the root is a function but the
/// argument/return types are errors.
///
/// The walk runs on the shared explicit visit stack, so structures of any
/// depth cannot exhaust the native stack. The answer is existential over the
/// reachable graph—the visited set only prunes—so no particular visit order
/// is required.
fn varContainsError(self: *Self, root_var: Var, visited: *std.AutoHashMap(Var, void)) std.mem.Allocator.Error!bool {
    const stack = &self.type_visit_stack;
    const stack_base = stack.items.len;
    defer stack.items.len = stack_base;
    try stack.append(self.gpa, root_var);

    while (stack.items.len > stack_base) {
        const var_ = stack.pop().?;
        const resolved = self.types.resolveVar(var_);

        // Check if we've already visited this var (cycle detection)
        if (visited.contains(resolved.var_)) continue;
        try visited.put(resolved.var_, {});

        switch (resolved.desc.content) {
            .err => return true,
            .flex, .rigid, .field_presence => {},
            .alias => |alias| {
                try stack.append(self.gpa, self.types.getAliasBackingVar(alias));
                try stack.appendSlice(self.gpa, self.types.sliceAliasArgs(alias));
            },
            .structure => |flat_type| switch (flat_type) {
                .tuple => |tuple| try stack.appendSlice(self.gpa, self.types.sliceVars(tuple.elems)),
                .nominal_type => |nominal| {
                    // An application of an invalid declaration is erroneous; a valid
                    // declaration's backing contains no errors by construction.
                    if (self.types.nominalDeclIsInvalid(nominal)) return true;
                    try stack.appendSlice(self.gpa, self.types.sliceNominalArgs(nominal));
                },
                .fn_pure, .fn_effectful, .fn_unbound => |func| {
                    try stack.appendSlice(self.gpa, self.types.sliceVars(func.args));
                    try stack.append(self.gpa, func.ret);
                },
                .record => |record| {
                    const fields = self.types.getRecordFieldsSlice(record.fields);
                    for (fields.items(.presence)) |presence| {
                        try stack.append(self.gpa, presence.typeVar());
                        if (presence.presenceVar()) |presence_var| try stack.append(self.gpa, presence_var);
                    }
                    try stack.append(self.gpa, record.ext);
                },
                .record_unbound => |fields| {
                    const fields_slice = self.types.getRecordFieldsSlice(fields);
                    for (fields_slice.items(.presence)) |presence| {
                        try stack.append(self.gpa, presence.typeVar());
                        if (presence.presenceVar()) |presence_var| try stack.append(self.gpa, presence_var);
                    }
                },
                .tag_union => |tag_union| {
                    const tags = self.types.getTagsSlice(tag_union.tags);
                    for (tags.items(.args)) |tag_args| {
                        try stack.appendSlice(self.gpa, self.types.sliceVars(tag_args));
                    }
                    try stack.append(self.gpa, tag_union.ext);
                },
                .empty_record, .empty_tag_union => {},
            },
        }
    }
    return false;
}

/// Record that checking rejected this exact static-dispatch obligation. Rejection
/// is evidence metadata, not a type fact: mutating the callable return can poison
/// a valid receiver when the method contract shares its argument and result.
fn markStaticDispatchRejected(self: *Self, constraint: StaticDispatchConstraint) Allocator.Error!void {
    return self.markStaticDispatchFnRejected(constraint.fn_var);
}

/// The marker rides the constraint callable's equivalence class, so a site whose
/// callable unified into an already-rejected class is rejected too and needs no
/// second durable record.
fn markStaticDispatchFnRejected(self: *Self, fn_var: Var) Allocator.Error!void {
    if (!try self.types.markVarStaticDispatchRejected(fn_var)) return;
    try self.cir.recordRejectedStaticDispatch(fn_var);
}

/// Find the source region of the string literal whose from_quote constraint
/// resolved into `dispatcher_var`, for error reporting. The constraint itself
/// carries no region, but the literal's dispatch plan records its source node.
fn quoteLiteralRegionForDispatcher(self: *Self, constraint: StaticDispatchConstraint, dispatcher_var: Var) ?Region {
    const kind = constraint.origin.literalKind() orelse return null;
    if (kind != .quote) return null;
    const resolved_dispatcher = self.types.resolveVar(dispatcher_var).var_;
    for (self.cir.store.literalDispatchPlans()) |plan| {
        if (plan.dispatchKind() != .quote) continue;
        const target: Var = @enumFromInt(plan.target_var);
        if (self.types.resolveVar(target).var_ != resolved_dispatcher) continue;
        return self.cir.store.getNodeRegion(@enumFromInt(plan.node_idx));
    }
    return null;
}

const ReportedConstraintError = struct {
    dispatcher: Var,
    fn_name: Ident.Idx,
};

const ConstraintErrorKind = union(enum) {
    missing_method: problem.DispatcherDoesNotImplMethod.DispatcherType,
    not_nominal,
};

/// Report a constraint validation error
fn reportConstraintError(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    kind: ConstraintErrorKind,
    env: *Env,
    is_numeric_default_pass: bool,
) Allocator.Error!void {
    return self.reportConstraintErrorAt(
        dispatcher_var,
        constraint,
        kind,
        env,
        is_numeric_default_pass,
        null,
    );
}

fn reportConstraintErrorAt(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    kind: ConstraintErrorKind,
    env: *Env,
    is_numeric_default_pass: bool,
    explicit_error_expr: ?CIR.Expr.Idx,
) Allocator.Error!void {
    const dedup_key = ReportedConstraintError{
        .dispatcher = self.types.resolveVar(dispatcher_var).var_,
        .fn_name = constraint.fn_name,
    };
    const dedup_entry = try self.reported_constraint_errors.getOrPut(dedup_key);
    if (dedup_entry.found_existing) {
        try self.poisonConstraintFailure(dispatcher_var, constraint, env, explicit_error_expr);
        try self.markStaticDispatchRejected(constraint);
        return;
    }

    const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, dispatcher_var);
    const constraint_problem = switch (kind) {
        .missing_method => |dispatcher_type| problem.Problem{
            .static_dispatch = .{
                .dispatcher_does_not_impl_method = .{
                    .dispatcher_var = dispatcher_var,
                    .dispatcher_snapshot = snapshot,
                    .dispatcher_type = dispatcher_type,
                    .fn_var = constraint.fn_var,
                    .method_name = constraint.fn_name,
                    .origin = constraint.origin,
                    .num_literal = constraint.origin.numeralInfo(),
                    .quote_region = self.quoteLiteralRegionForDispatcher(constraint, dispatcher_var),
                    // Only a numeral literal defaulted to Dec earns the numeric hint.
                    // The cascade pass (`is_numeric_default_pass`) also reports errors
                    // for quote literals defaulted to Str (e.g. `"a" > "b"`); those must
                    // NOT claim "this numeric literal was given the type Dec".
                    .defaulted_from_numeric_literal = is_numeric_default_pass and self.isDecNominal(dispatcher_var),
                },
            },
        },
        .not_nominal => problem.Problem{ .static_dispatch = .{
            .dispatcher_not_nominal = .{
                .dispatcher_var = dispatcher_var,
                .dispatcher_snapshot = snapshot,
                .fn_var = constraint.fn_var,
                .method_name = constraint.fn_name,
            },
        } },
    };
    _ = try self.problems.appendProblem(self.cir.gpa, constraint_problem);

    try self.poisonConstraintFailure(dispatcher_var, constraint, env, explicit_error_expr);
    try self.markStaticDispatchRejected(constraint);
}

/// Report an error when an anonymous type doesn't support equality
fn reportEqualityError(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    env: *Env,
) Allocator.Error!void {
    const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, dispatcher_var);
    const equality_problem = problem.Problem{ .static_dispatch = .{
        .type_does_not_support_equality = .{
            .dispatcher_var = dispatcher_var,
            .dispatcher_snapshot = snapshot,
            .fn_var = constraint.fn_var,
        },
    } };
    _ = try self.problems.appendProblem(self.cir.gpa, equality_problem);

    try self.poisonConstraintFailure(dispatcher_var, constraint, env, null);
    try self.markStaticDispatchRejected(constraint);
}

fn reportDerivedMapError(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    env: *Env,
) Allocator.Error!void {
    const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, dispatcher_var);
    _ = try self.problems.appendProblem(self.cir.gpa, .{ .static_dispatch = .{
        .type_does_not_support_map = .{
            .dispatcher_snapshot = snapshot,
            .fn_var = constraint.fn_var,
            .method_name = constraint.fn_name,
        },
    } });

    try self.poisonConstraintFailure(dispatcher_var, constraint, env, null);
    try self.markStaticDispatchRejected(constraint);
}

/// Pool for reusing Env instances to avoid repeated allocations
const EnvPool = struct {
    available: std.ArrayList(Env),
    gpa: Allocator,

    fn init(gpa: Allocator) std.mem.Allocator.Error!EnvPool {
        var pool = try std.ArrayList(Env).initCapacity(gpa, 8);
        for (0..8) |_| {
            pool.appendAssumeCapacity(try Env.init(gpa, .generalized));
        }
        return .{
            .available = pool,
            .gpa = gpa,
        };
    }

    fn deinit(self: *EnvPool) void {
        for (self.available.items) |*env| {
            env.deinit(self.gpa);
        }
        self.available.deinit(self.gpa);
    }

    /// Acquire an Env from the pool, or create a new one if none available
    fn acquire(self: *EnvPool) std.mem.Allocator.Error!Env {
        const trace = tracy.trace(@src());
        defer trace.end();

        if (self.available.pop()) |env| {
            // Reset the env for reuse
            var reused_env = env;
            try reused_env.reset(.generalized);
            return reused_env;
        } else {
            // Otherwise init a new one and ensure there's room to put it back
            // into the pool when we're done using it
            try self.available.ensureUnusedCapacity(self.gpa, 1);
            return try Env.init(self.gpa, .generalized);
        }
    }

    /// Return an Env to the pool for reuse.
    /// If the pool cannot fit it, then deinit the env
    ///
    /// * If we acquire an existing env from the pool, there should be a slot
    ///   available to return it
    /// * If we init a new env when we acquire, the acquire func should expand the
    ///   pool so we have room to return it
    fn release(self: *EnvPool, env: Env) void {
        const trace = tracy.trace(@src());
        defer trace.end();

        var releasable_env = env;
        releasable_env.reset(.generalized) catch {
            // If we can't reset the env, deinit it and don't return it to the pool
            releasable_env.deinit(self.gpa);
            return;
        };
        self.available.append(self.gpa, releasable_env) catch {
            // If we can't add to the pool, just deinit this env
            releasable_env.deinit(self.gpa);
        };
    }
};

/// Create the import mapping for type display names in error messages.
///
/// This builds a mapping from fully-qualified type identifiers to their shortest display names
/// based on what's in scope. The mapping is built from:
/// 1. Auto-imported builtin types (e.g., Bool, Str, Dec, U64, etc.)
/// 2. User import statements with their aliases
///
/// When multiple imports could refer to the same type, the shortest name wins.
/// This ensures error messages show types the way users would write them in their code.
pub fn createImportMapping(
    gpa: std.mem.Allocator,
    idents: *Ident.Store,
    cir: *const ModuleEnv,
    builtin_module: ?*const ModuleEnv,
    builtin_indices: ?CIR.BuiltinIndices,
) std.mem.Allocator.Error!types_mod.import_mapping.ImportMapping {
    var mapping = types_mod.import_mapping.ImportMapping.init(gpa);
    errdefer mapping.deinit();

    // Step 1: Add auto-imported builtin types
    if (builtin_module) |builtin_env| {
        if (builtin_indices) |indices| {
            inline for (CIR.builtin_type_specs) |spec| {
                const stmt_idx: CIR.Statement.Idx = @field(indices, spec.type_field);

                // Skip invalid statement indices (index 0 is typically invalid/sentinel)
                if (@intFromEnum(stmt_idx) != 0) {
                    const stmt = builtin_env.store.getStatement(stmt_idx);
                    const header_idx = switch (stmt) {
                        .s_nominal_decl => |decl| decl.header,
                        .s_alias_decl => |alias| alias.header,
                        .s_decl,
                        .s_var,
                        .s_var_uninitialized,
                        .s_reassign,
                        .s_crash,
                        .s_dbg,
                        .s_expr,
                        .s_expect,
                        .s_for,
                        .s_while,
                        .s_infinite_loop,
                        .s_breakable_loop,
                        .s_break,
                        .s_return,
                        .s_import,
                        .s_where_alias_decl,
                        .s_type_anno,
                        .s_type_var_alias,
                        .s_runtime_error,
                        => null,
                    };
                    if (header_idx) |hdr_idx| {
                        const header = builtin_env.store.getTypeHeader(hdr_idx);
                        const qualified_name = builtin_env.getIdentText(header.name);
                        const relative_name = builtin_env.getIdentText(header.relative_name);

                        // Extract display name (last component after dots)
                        const display_name = blk: {
                            var last_dot: usize = 0;
                            for (qualified_name, 0..) |c, i| {
                                if (c == '.') last_dot = i + 1;
                            }
                            break :blk qualified_name[last_dot..];
                        };

                        const qualified_ident = try idents.insert(gpa, Ident.for_text(qualified_name));
                        const relative_ident = try idents.insert(gpa, Ident.for_text(relative_name));
                        const display_ident = try idents.insert(gpa, Ident.for_text(display_name));

                        // Add mapping for qualified_name -> display_name
                        if (mapping.get(qualified_ident)) |existing_ident| {
                            const existing_name = idents.getText(existing_ident);
                            if (displayNameIsBetter(display_name, existing_name)) {
                                try mapping.put(qualified_ident, display_ident);
                            }
                        } else {
                            try mapping.put(qualified_ident, display_ident);
                        }

                        // Also add mapping for relative_name -> display_name
                        // This ensures types stored with relative_name (like "Num.Numeral") also map to display_name
                        if (mapping.get(relative_ident)) |existing_ident| {
                            const existing_name = idents.getText(existing_ident);
                            if (displayNameIsBetter(display_name, existing_name)) {
                                try mapping.put(relative_ident, display_ident);
                            }
                        } else {
                            try mapping.put(relative_ident, display_ident);
                        }
                    }
                    // else: Skip non-nominal/alias statements (e.g., nested types that aren't directly importable)
                }
            }
        }
    }

    // Step 2: Copy user import mappings from the ModuleEnv
    // These were built during canonicalization when processing import statements
    var iter = cir.import_mapping.iterator();
    while (iter.next()) |entry| {
        const qualified_ident = entry.key_ptr.*;
        const local_ident = entry.value_ptr.*;

        // Get the text for comparison
        const local_name = cir.getIdentText(local_ident);

        if (mapping.get(qualified_ident)) |existing_display| {
            // Only replace if the new name is "better"
            const existing_name = idents.getText(existing_display);
            if (displayNameIsBetter(local_name, existing_name)) {
                try mapping.put(qualified_ident, local_ident);
            }
        } else {
            try mapping.put(qualified_ident, local_ident);
        }
    }

    return mapping;
}

/// Determine if `new_name` is a "better" display name than `existing_name`.
/// Returns true if new_name should replace existing_name.
///
/// The rules are:
/// 1. Shorter names are better (fewer characters to read in error messages)
/// 2. For equal lengths, lexicographically smaller wins (deterministic regardless of import order)
pub fn displayNameIsBetter(new_name: []const u8, existing_name: []const u8) bool {
    // Shorter is better
    if (new_name.len != existing_name.len) {
        return new_name.len < existing_name.len;
    }
    // Equal length: lexicographic comparison (lower byte value wins)
    for (new_name, existing_name) |new_byte, existing_byte| {
        if (new_byte != existing_byte) {
            return new_byte < existing_byte;
        }
    }
    // Identical strings - no replacement needed
    return false;
}

test "parent branch aggregate retirement preserves only its exact no-Expected range" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\choose : Bool -> U64
        \\choose = |flag| if flag 1 else [["bad"]]
    ;
    var test_env = try TestEnv.init("ParentRetiredAggregateNoExpected", source);
    defer test_env.deinit();
    try test_env.assertOneTypeError("Type Mismatch");

    const cir = test_env.module_env;
    const plans = cir.expected_consumption_plans.items.items;
    const retirements = cir.expected_consumer_retirements.items.items;
    const retired_consumers = cir.expected_retired_consumers.items.items;
    const retirement_index: u32 = for (retirements, 0..) |retirement, index| {
        if (retirement.retired_consumers_len == 0) continue;
        const first = retired_consumers[retirement.retired_consumers_start];
        if (first.decodedReason() == .aggregate_retired_by_parent_branch_failure) {
            break @intCast(index);
        }
    } else return error.TestUnexpectedResult;
    const retirement = &retirements[retirement_index];
    try std.testing.expectEqual(CIR.Node.Tag.expr_list, retirement.decodedOriginalNodeTag().?);
    try std.testing.expectEqual(@as(u32, 2), retirement.retired_consumers_len);
    const consumers = retired_consumers[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
    for (consumers) |consumer| {
        const plan = plans[consumer.plan_index];
        try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Outcome.not_projected, plan.decodedOutcome().?);
        try std.testing.expectEqual(ModuleEnv.ExpectedConsumptionPlan.Reason.aggregate_no_expected, plan.decodedReason().?);
    }
    try std.testing.expect(consumers[1].plan_index > consumers[0].plan_index + 1);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    const saved_consumer_reason = consumers[0].reason;
    consumers[0].reason = @intFromEnum(
        ModuleEnv.ExpectedConsumptionPlan.Reason.aggregate_retired_after_child_relation,
    );
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    consumers[0].reason = saved_consumer_reason;

    const first_plan_index = consumers[0].plan_index;
    const saved_plan = plans[first_plan_index];
    plans[first_plan_index].outcome = @intFromEnum(ModuleEnv.ExpectedConsumptionPlan.Outcome.checked_error);
    plans[first_plan_index].reason = @intFromEnum(
        ModuleEnv.ExpectedConsumptionPlan.Reason.aggregate_retired_by_parent_branch_failure,
    );
    plans[first_plan_index].failure_owner = ModuleEnv.CauseOwner.expectedConsumerRetirement(
        retirement_index,
    );
    try std.testing.expect(plans[first_plan_index].hasLegalTags());
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    plans[first_plan_index] = saved_plan;

    std.mem.swap(u32, &consumers[0].plan_index, &consumers[1].plan_index);
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    std.mem.swap(u32, &consumers[0].plan_index, &consumers[1].plan_index);

    const nested_plan_index: u32 = for (plans, 0..) |plan, plan_index| {
        if (plan.owner_node != retirement.retired_node and
            plan.decodedRole() == .aggregate_owner)
        {
            break @intCast(plan_index);
        }
    } else return error.TestUnexpectedResult;
    const saved_consumer = consumers[1];
    const nested_plan = plans[nested_plan_index];
    consumers[1] = .{
        .plan_index = nested_plan_index,
        .owner_node = nested_plan.owner_node,
        .site_node = nested_plan.site_node,
        .role = nested_plan.role,
        .slot = nested_plan.slot,
        .raw_owner_var = nested_plan.owner_node,
        .raw_consumer_var = nested_plan.raw_consumer_var,
        .reason = @intFromEnum(
            ModuleEnv.ExpectedConsumptionPlan.Reason.aggregate_retired_by_parent_branch_failure,
        ),
    };
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    consumers[1] = saved_consumer;

    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
}

test "direct known call formal admits a canonical empty effect-dependency range" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\apply : (Str -> Str), Str -> Str
        \\apply = |function, value| function(value)
    ;
    var test_env = try TestEnv.init("DirectCallFormalEmptyEffects", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const cir = test_env.module_env;
    var found_direct = false;
    for (cir.expected_call_formals.items.items) |formal| {
        if (formal.decodedFormalOrigin() != .direct_monomorphic_or_alias) continue;
        const desc = cir.types.immutableRootDescriptor(
            @enumFromInt(formal.immutable_exposure_var),
        ) orelse return error.TestUnexpectedResult;
        const func = desc.content.unwrapFunc() orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(u32, 0), func.effect_deps.len());
        found_direct = true;
    }
    try std.testing.expect(found_direct);
    try std.testing.expect(validateExpectedCallPlans(cir));
}

test "recursive monomorphic predeclared calls remain direct" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\loop : Bool -> Bool
        \\loop = |flag| if flag { False } else { loop(True) }
        \\out = loop(False)
    ;
    var test_env = try TestEnv.init("MonomorphicPredeclaredCall", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const cir = test_env.module_env;
    var loop_formals: usize = 0;
    for (cir.expected_call_formals.items.items) |formal| {
        const token = cir.expected_call_slot_tokens.items.items[
            formal.call_root_token_index
        ];
        const callee = cir.store.getExpr(@enumFromInt(token.site_node));
        if (callee != .e_lookup_local) continue;
        const pattern = cir.store.getPattern(callee.e_lookup_local.pattern_idx);
        if (pattern != .assign or
            !std.mem.eql(
                u8,
                cir.getIdentStoreConst().getText(pattern.assign.ident),
                "loop",
            ))
        {
            continue;
        }
        loop_formals += 1;
        try std.testing.expectEqual(
            ModuleEnv.ExpectedCallFormal.FormalOrigin.direct_monomorphic_or_alias,
            formal.decodedFormalOrigin().?,
        );
        try std.testing.expectEqual(
            ModuleEnv.ExpectedCallFormal.none,
            formal.instantiation_copy_step,
        );
    }
    try std.testing.expect(loop_formals >= 2);

    for (cir.where_marker_copy_steps.items.items) |step| {
        if (step.decodedKind() != .expected_call_instantiation) continue;
        try std.testing.expect(
            step.origin.expected_call_instantiation.decodedSourceKind() !=
                .local_predeclared_annotation,
        );
    }
    try std.testing.expect(validateExpectedCallPlans(cir));
}

const CallFormalLedgerFixture = struct {
    const TestEnv = @import("test/TestEnv.zig");

    const provider_source =
        \\CallFormalProvider :: {}.{
        \\    identity : a -> a
        \\    identity = |value| value
        \\    other : a -> a
        \\    other = |value| value
        \\}
    ;
    const consumer_source =
        \\import CallFormalProvider exposing [identity, other]
        \\
        \\applyKnown : (Str -> Str), Str -> Str
        \\applyKnown = |function, value| function(value)
        \\localIdentity : a -> a
        \\localIdentity = |value| value
        \\localInstantiated = localIdentity("local")
        \\externalInstantiated = identity("external")
        \\externalOther = other("other")
        \\applyFresh = |function, value| function(value)
        \\applyPair = |function, first, second| function(first, second)
        \\paired = applyPair(|first, second| [first, second], "left", "right")
        \\zero : () -> {}
        \\zero = || {}
        \\zeroResult = zero()
        \\zeroAgain = zero()
    ;

    provider: TestEnv,
    consumer: TestEnv,
    direct_index: usize,
    instantiated_index: usize,
    fresh_index: usize,
    external_instantiation_steps: [2]u32,

    fn init() !@This() {
        var provider = try TestEnv.init("CallFormalProvider", provider_source);
        errdefer provider.deinit();
        try provider.assertNoErrors();

        var consumer = try TestEnv.initWithImport(
            "CallFormalCorruption",
            consumer_source,
            "CallFormalProvider",
            &provider,
        );
        errdefer consumer.deinit();
        try consumer.assertNoErrors();

        const cir = consumer.module_env;
        const formals = cir.expected_call_formals.items.items;
        var direct_index: ?usize = null;
        var instantiated_index: ?usize = null;
        var fresh_index: ?usize = null;
        var saw_local_instantiation = false;
        var saw_external_instantiation = false;
        var external_instantiation_steps: [2]u32 = undefined;
        var external_instantiation_step_count: usize = 0;
        for (formals, 0..) |formal, index| {
            switch (formal.decodedFormalOrigin() orelse return error.TestUnexpectedResult) {
                .direct_monomorphic_or_alias => direct_index = direct_index orelse index,
                .explicitly_instantiated => {
                    instantiated_index = instantiated_index orelse index;
                    const token = cir.expected_call_slot_tokens.items.items[
                        formal.call_root_token_index
                    ];
                    switch (cir.store.getExpr(@enumFromInt(token.site_node))) {
                        .e_lookup_local => saw_local_instantiation = true,
                        .e_lookup_external => {
                            saw_external_instantiation = true;
                            var already_recorded = false;
                            for (external_instantiation_steps[0..external_instantiation_step_count]) |step_index| {
                                if (step_index == formal.instantiation_copy_step) {
                                    already_recorded = true;
                                    break;
                                }
                            }
                            if (!already_recorded) {
                                if (external_instantiation_step_count >= external_instantiation_steps.len) {
                                    return error.TestUnexpectedResult;
                                }
                                external_instantiation_steps[external_instantiation_step_count] =
                                    formal.instantiation_copy_step;
                                external_instantiation_step_count += 1;
                            }
                        },
                        else => return error.TestUnexpectedResult,
                    }
                },
                .fresh_arity_shape => fresh_index = fresh_index orelse index,
            }
        }

        const direct = direct_index orelse return error.TestUnexpectedResult;
        const instantiated = instantiated_index orelse return error.TestUnexpectedResult;
        const fresh_formal_index = fresh_index orelse return error.TestUnexpectedResult;
        try std.testing.expect(saw_local_instantiation);
        try std.testing.expect(saw_external_instantiation);
        try std.testing.expectEqual(
            external_instantiation_steps.len,
            external_instantiation_step_count,
        );
        try std.testing.expect(validateExpectedCallPlans(cir));

        return .{
            .provider = provider,
            .consumer = consumer,
            .direct_index = direct,
            .instantiated_index = instantiated,
            .fresh_index = fresh_formal_index,
            .external_instantiation_steps = external_instantiation_steps,
        };
    }

    fn deinit(self: *@This()) void {
        self.consumer.deinit();
        self.provider.deinit();
        self.* = undefined;
    }
};

test "terminal call plan traversal rejects reordered roots and unchanged-count sibling corruption" {
    var fixture = try CallFormalLedgerFixture.init();
    defer fixture.deinit();

    const cir = fixture.consumer.module_env;
    const plans = cir.expected_consumption_plans.items.items;
    const formals = cir.expected_call_formals.items.items;
    var zero_roots: [2]usize = undefined;
    var zero_root_count: usize = 0;
    var nonzero_root: ?usize = null;
    var sibling_formals: [2]usize = undefined;
    var sibling_count: usize = 0;
    var sibling_root: ?u32 = null;
    for (plans, 0..) |plan, plan_index| {
        if (plan.decodedRole() != .call_root) continue;
        const call = expectedCallOwnerSnapshot(cir, plan.owner_node) orelse
            return error.TestUnexpectedResult;
        if (call.args_len == 0) {
            if (zero_root_count < zero_roots.len) {
                zero_roots[zero_root_count] = plan_index;
            }
            zero_root_count += 1;
        } else {
            nonzero_root = nonzero_root orelse plan_index;
        }
        if (call.args_len < 2 or sibling_root != null) continue;
        sibling_root = @intCast(plan_index);
        for (formals, 0..) |formal, formal_index| {
            if (formal.call_root_plan_index != plan_index or formal.slot >= 2) continue;
            sibling_formals[formal.slot] = formal_index;
            sibling_count += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 2), sibling_count);
    try std.testing.expect(zero_root_count >= zero_roots.len);
    try std.testing.expect(validateExpectedCallPlans(cir));

    // Canonical call tokens exist before checking and therefore validate
    // without the later checker-owned relation stamp. This authentic root's
    // checked snapshot was stamped, and may not use its token as a substitute
    // after that stamp is corrupted away.
    const checked_owner: CIR.Node.Idx = @enumFromInt(plans[zero_roots[0]].owner_node);
    const saved_checked_node = cir.store.nodes.get(checked_owner);
    try std.testing.expect(saved_checked_node.tag == .expr_call);
    var unstamped_checked_node = saved_checked_node;
    var unstamped_checked_payload = unstamped_checked_node.getPayload();
    try std.testing.expect(unstamped_checked_payload.expr_call.constraint_fn_var_plus_one != 0);
    unstamped_checked_payload.expr_call.constraint_fn_var_plus_one = 0;
    unstamped_checked_node.setPayload(unstamped_checked_payload);
    cir.store.nodes.set(checked_owner, unstamped_checked_node);
    try std.testing.expect(validateExpectedCallSlotTokens(cir));
    try std.testing.expect(!validateExpectedCallPlans(cir));
    cir.store.nodes.set(checked_owner, saved_checked_node);
    try std.testing.expect(validateExpectedCallPlans(cir));

    // Dependency-free roots are a strict owner-ordered subsequence. These two
    // authentic zero-argument roots have neither formals nor argument-plan
    // references, so swapping only their rows leaves each local root predicate
    // valid and isolates the noncanonical terminal order.
    const zero_a = zero_roots[0];
    const zero_b = zero_roots[1];
    try std.testing.expect(expectedCallRootPlanIsCanonical(cir, plans[zero_a]));
    try std.testing.expect(expectedCallRootPlanIsCanonical(cir, plans[zero_b]));
    std.mem.swap(ModuleEnv.ExpectedConsumptionPlan, &plans[zero_a], &plans[zero_b]);
    try std.testing.expect(expectedCallRootPlanIsCanonical(cir, plans[zero_a]));
    try std.testing.expect(expectedCallRootPlanIsCanonical(cir, plans[zero_b]));
    try std.testing.expect(!validateExpectedCallPlans(cir));
    std.mem.swap(ModuleEnv.ExpectedConsumptionPlan, &plans[zero_a], &plans[zero_b]);

    // Replacing the zero-argument root by a second existing root keeps the
    // number of roots unchanged, but leaves one missing identity and one
    // duplicate. Zero-argument groups have no formal rows to mask the defect.
    const missing_zero = zero_a;
    const duplicate_nonzero = nonzero_root orelse return error.TestUnexpectedResult;
    const saved_zero = plans[missing_zero];
    plans[missing_zero] = plans[duplicate_nonzero];
    try std.testing.expect(!validateExpectedCallPlans(cir));
    plans[missing_zero] = saved_zero;

    const first_sibling = sibling_formals[0];
    const second_sibling = sibling_formals[1];
    const first_argument = formals[first_sibling].argument_plan_index;
    const second_argument = formals[second_sibling].argument_plan_index;
    try std.testing.expect(first_argument != second_argument);

    // Argument plans are allowed to be physically interleaved, but their raw
    // root and source slot remain exact. A same-owner sibling swap is not a
    // valid alternative ordering.
    std.mem.swap(
        ModuleEnv.ExpectedConsumptionPlan,
        &plans[first_argument],
        &plans[second_argument],
    );
    try std.testing.expect(!validateExpectedCallPlans(cir));
    std.mem.swap(
        ModuleEnv.ExpectedConsumptionPlan,
        &plans[first_argument],
        &plans[second_argument],
    );

    // Keep the argument-plan cardinality unchanged while duplicating one slot
    // and omitting its sibling. The formal-to-plan injection plus total count
    // must reject this coordinated corruption.
    const saved_second_argument = plans[second_argument];
    plans[second_argument] = plans[first_argument];
    try std.testing.expect(!validateExpectedCallPlans(cir));
    plans[second_argument] = saved_second_argument;

    const saved_first_root = plans[first_argument].call_root_plan_index;
    try std.testing.expect(saved_first_root != zero_a);
    plans[first_argument].call_root_plan_index = @intCast(zero_a);
    try std.testing.expect(!validateExpectedCallPlans(cir));
    plans[first_argument].call_root_plan_index = saved_first_root;

    // The formal table's full semantic ordering is itself part of the terminal
    // certificate, independently of each row's locally valid tags.
    std.mem.swap(
        ModuleEnv.ExpectedCallFormal,
        &formals[first_sibling],
        &formals[second_sibling],
    );
    try std.testing.expect(!validateExpectedCallPlans(cir));
    std.mem.swap(
        ModuleEnv.ExpectedCallFormal,
        &formals[first_sibling],
        &formals[second_sibling],
    );
    try std.testing.expect(validateExpectedCallPlans(cir));
}

test "terminal call plan admission accepts canonical child calls orphaned by a rejected record builder" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\NoMap(a) := { value : a }.{
        \\    wrap : a -> NoMap(a)
        \\    wrap = |value| { value: value }
        \\}
        \\identity = |value| value
        \\orphaned = { first: identity("left"), second: identity("right") }.NoMap
    ;
    var test_env = try TestEnv.init("ExpectedCallOrphan", source);
    defer test_env.deinit();
    try test_env.assertOneCanError("Record Builder Not Supported");

    const cir = test_env.module_env;
    const plans = cir.expected_consumption_plans.items.items;
    var orphaned_call_count: usize = 0;
    for (0..cir.store.nodes.len()) |raw_node| {
        if (cir.store.nodes.get(@enumFromInt(raw_node)).tag != .expr_call) continue;
        const owner_node = std.math.cast(u32, raw_node) orelse
            return error.TestUnexpectedResult;
        var has_root_plan = false;
        for (plans) |plan| {
            if (plan.decodedRole() == .call_root and plan.owner_node == owner_node) {
                has_root_plan = true;
                break;
            }
        }
        if (!has_root_plan) orphaned_call_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 2), orphaned_call_count);
    try std.testing.expect(validateExpectedCallPlans(cir));
}

test "terminal call plan admission handles one large real formal group" {
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = std.testing.allocator;
    const arity = 96;
    var source: std.ArrayList(u8) = .empty;
    defer source.deinit(allocator);

    try source.appendSlice(allocator,
        \\BuilderBox(a) := { value : a }.{
        \\    map2 : BuilderBox(a), BuilderBox(b), (a, b -> c) -> BuilderBox(c)
        \\    map2 = |first, second, combine| { value: combine(first.value, second.value) }
        \\    wrap : a -> BuilderBox(a)
        \\    wrap = |value| { value: value }
        \\}
        \\left = BuilderBox.wrap("left")
        \\right = BuilderBox.wrap("right")
        \\built = { first: left, second: right }.BuilderBox
        \\
    );
    try source.appendSlice(allocator, "many = |");
    for (0..arity) |slot| {
        if (slot != 0) try source.appendSlice(allocator, ", ");
        const name = try std.fmt.allocPrint(allocator, "value{d}", .{slot});
        defer allocator.free(name);
        try source.appendSlice(allocator, name);
    }
    try source.appendSlice(allocator, "| [");
    for (0..arity) |slot| {
        if (slot != 0) try source.appendSlice(allocator, ", ");
        const name = try std.fmt.allocPrint(allocator, "value{d}", .{slot});
        defer allocator.free(name);
        try source.appendSlice(allocator, name);
    }
    try source.appendSlice(allocator, "]\nresult = many(");
    for (0..arity) |slot| {
        if (slot != 0) try source.appendSlice(allocator, ", ");
        const value = try std.fmt.allocPrint(allocator, "\"value{d}\"", .{slot});
        defer allocator.free(value);
        try source.appendSlice(allocator, value);
    }
    try source.appendSlice(allocator, ")\n");

    var test_env = try TestEnv.init("LargeExpectedCallFormalGroup", source.items);
    defer test_env.deinit();
    try test_env.assertNoErrors();
    const cir = test_env.module_env;
    try std.testing.expect(validateExpectedCallPlans(cir));

    var large_root: ?u32 = null;
    var record_builder_roots: usize = 0;
    for (cir.expected_consumption_plans.items.items, 0..) |plan, plan_index| {
        if (plan.decodedRole() != .call_root) continue;
        const call = expectedCallOwnerSnapshot(cir, plan.owner_node) orelse
            return error.TestUnexpectedResult;
        if (call.called_via == .record_builder) record_builder_roots += 1;
        if (call.args_len != arity) continue;
        if (large_root != null) return error.TestUnexpectedResult;
        large_root = @intCast(plan_index);
    }
    const root = large_root orelse return error.TestUnexpectedResult;
    var formal_count: usize = 0;
    for (cir.expected_call_formals.items.items) |formal| {
        if (formal.call_root_plan_index == root) formal_count += 1;
    }
    try std.testing.expectEqual(@as(usize, arity), formal_count);
    try std.testing.expect(record_builder_roots != 0);
}

test "call formal instantiation origin proof rejects seed and sibling retargets" {
    var fixture = try CallFormalLedgerFixture.init();
    defer fixture.deinit();

    const cir = fixture.consumer.module_env;
    const first_step_index = fixture.external_instantiation_steps[0];
    const second_step_index = fixture.external_instantiation_steps[1];
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.SourceKind.external_import_root,
        cir.where_marker_copy_steps.items.items[first_step_index]
            .origin.expected_call_instantiation.decodedSourceKind().?,
    );
    try std.testing.expectEqual(
        ModuleEnv.WhereMarkerExpectedCallInstantiationOrigin.SourceKind.external_import_root,
        cir.where_marker_copy_steps.items.items[second_step_index]
            .origin.expected_call_instantiation.decodedSourceKind().?,
    );

    const saved_first_origin = cir.where_marker_copy_steps.items.items[first_step_index]
        .origin.expected_call_instantiation;
    const saved_second_origin = cir.where_marker_copy_steps.items.items[second_step_index]
        .origin.expected_call_instantiation;

    cir.where_marker_copy_steps.items.items[first_step_index]
        .origin.expected_call_instantiation.source_seed_index =
        saved_second_origin.source_seed_index;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(&cir.types, cir));
    cir.where_marker_copy_steps.items.items[first_step_index]
        .origin.expected_call_instantiation = saved_first_origin;

    cir.where_marker_copy_steps.items.items[first_step_index]
        .origin.expected_call_instantiation = saved_second_origin;
    cir.where_marker_copy_steps.items.items[second_step_index]
        .origin.expected_call_instantiation = saved_first_origin;
    try std.testing.expect(!validateWhereMarkerCopyProofLocal(&cir.types, cir));
    cir.where_marker_copy_steps.items.items[first_step_index]
        .origin.expected_call_instantiation = saved_first_origin;
    cir.where_marker_copy_steps.items.items[second_step_index]
        .origin.expected_call_instantiation = saved_second_origin;
    try std.testing.expect(validateWhereMarkerCopyProofLocal(&cir.types, cir));

    var local_step_index: ?u32 = null;
    var local_pattern: ?CIR.Pattern.Idx = null;
    for (cir.where_marker_copy_steps.items.items, 0..) |step, step_index| {
        if (step.decodedKind() != .expected_call_instantiation or
            step.origin.expected_call_instantiation.decodedSourceKind() !=
                .local_binding_pattern)
        {
            continue;
        }
        const token_index = step.origin.expected_call_instantiation.call_root_token_index;
        const pattern_idx = expectedCallLookupPatternAtToken(cir, token_index) orelse continue;
        const pattern = cir.store.getPattern(pattern_idx);
        if (pattern != .assign or !std.mem.eql(
            u8,
            cir.getIdentStoreConst().getText(pattern.assign.ident),
            "localIdentity",
        )) continue;
        if (local_step_index != null) return error.TestUnexpectedResult;
        local_step_index = @intCast(step_index);
        local_pattern = pattern_idx;
    }
    const exact_local_step_index = local_step_index orelse return error.TestUnexpectedResult;
    const exact_local_pattern = local_pattern orelse return error.TestUnexpectedResult;
    const local_step = cir.where_marker_copy_steps.items.items[exact_local_step_index];
    const local_token_index = local_step.origin.expected_call_instantiation.call_root_token_index;
    try std.testing.expect(expectedCallInstantiationStepMatchesLookupOrigin(
        cir,
        exact_local_step_index,
        local_token_index,
        exact_local_pattern,
    ));
    const local_root_occurrence_index = local_step.occurrences_start +
        local_step.root_occurrence_offset;
    const saved_local_root_occurrence = cir.where_marker_copy_occurrences.items.items[
        local_root_occurrence_index
    ];
    try std.testing.expectEqual(
        @intFromEnum(ModuleEnv.varFrom(exact_local_pattern)),
        saved_local_root_occurrence.raw_source_var,
    );
    try std.testing.expect(
        saved_local_root_occurrence.raw_destination_var !=
            saved_local_root_occurrence.raw_source_var,
    );
    cir.where_marker_copy_occurrences.items.items[
        local_root_occurrence_index
    ].raw_source_var = saved_local_root_occurrence.raw_destination_var;
    const retargeted_local_origin = expectedCallInstantiationStepMatchesLookupOrigin(
        cir,
        exact_local_step_index,
        local_token_index,
        exact_local_pattern,
    );
    const retargeted_local_plans = validateExpectedCallPlans(cir);
    cir.where_marker_copy_occurrences.items.items[
        local_root_occurrence_index
    ] = saved_local_root_occurrence;
    try std.testing.expect(!retargeted_local_origin);
    try std.testing.expect(!retargeted_local_plans);
    try std.testing.expect(validateExpectedCallPlans(cir));
}

