        const saved_instantiated = formals[instantiated];
        formals[instantiated].instantiation_formal_occurrence +%= 1;
        try std.testing.expect(!validateExpectedCallPlans(cir));
        formals[instantiated] = saved_instantiated;

        formals[instantiated].immutable_exposure_var = saved_direct.immutable_exposure_var;
        try std.testing.expect(!formals[instantiated].hasCanonicalTags());
        try std.testing.expect(!validateExpectedCallPlans(cir));
        formals[instantiated] = saved_instantiated;

        const saved_fresh = formals[fresh_formal_index];
        formals[fresh_formal_index].fresh_args_start +%= 1;
        try std.testing.expect(!validateExpectedCallPlans(cir));
        formals[fresh_formal_index] = saved_fresh;

        formals[fresh_formal_index].instantiation_formal_occurrence = 0;
        try std.testing.expect(!formals[fresh_formal_index].hasCanonicalTags());
        try std.testing.expect(!validateExpectedCallPlans(cir));
        formals[fresh_formal_index] = saved_fresh;
    }

    const formal_len = cir.expected_call_formals.items.items.len;
    cir.expected_call_formals.items.items.len = formal_len - 1;
    try std.testing.expect(!validateExpectedCallPlans(cir));
    cir.expected_call_formals.items.items.len = formal_len;

    try cir.expected_call_formals.items.append(std.testing.allocator, saved_direct);
    try std.testing.expect(!validateExpectedCallPlans(cir));
    cir.expected_call_formals.items.items.len = formal_len;

    const token_len = cir.expected_call_slot_tokens.items.items.len;
    cir.expected_call_slot_tokens.items.items.len = token_len - 1;
    try std.testing.expect(!validateExpectedCallPlans(cir));
    cir.expected_call_slot_tokens.items.items.len = token_len;

    const duplicate_token = cir.expected_call_slot_tokens.items.items[0];
    try cir.expected_call_slot_tokens.items.append(std.testing.allocator, duplicate_token);
    try std.testing.expect(!validateExpectedCallPlans(cir));
    cir.expected_call_slot_tokens.items.items.len = token_len;
    try std.testing.expect(validateExpectedCallPlans(cir));
}

test "call formal Probe rollback restores formal and copy-proof ledgers" {
    var fixture = try CallFormalLedgerFixture.init();
    defer fixture.deinit();

    const cir = fixture.consumer.module_env;
    const saved_direct = cir.expected_call_formals.items.items[fixture.direct_index];
    const formal_len = cir.expected_call_formals.items.items.len;
    const proof_step_len = cir.where_marker_copy_steps.items.items.len;
    const proof_pair_len = cir.where_marker_copy_pairs.items.items.len;
    const proof_occurrence_len = cir.where_marker_copy_occurrences.items.items.len;
    const proof_witness_len = cir.where_marker_copy_witnesses.items.items.len;

    {
        var probe = try fixture.consumer.checker.beginProbe(null);
        var probe_open = true;
        errdefer if (probe_open) probe.rollback();
        try cir.expected_call_formals.items.append(cir.gpa, saved_direct);
        try std.testing.expectEqual(
            formal_len + 1,
            cir.expected_call_formals.items.items.len,
        );
        probe.rollback();
        probe_open = false;
    }

    try std.testing.expectEqual(formal_len, cir.expected_call_formals.items.items.len);
    try std.testing.expectEqual(proof_step_len, cir.where_marker_copy_steps.items.items.len);
    try std.testing.expectEqual(proof_pair_len, cir.where_marker_copy_pairs.items.items.len);
    try std.testing.expectEqual(
        proof_occurrence_len,
        cir.where_marker_copy_occurrences.items.items.len,
    );
    try std.testing.expectEqual(
        proof_witness_len,
        cir.where_marker_copy_witnesses.items.items.len,
    );
    try std.testing.expect(validateExpectedCallPlans(cir));
}

const ProbeCrossCopyOwnedStateSnapshot = struct {
    const VarMapEntry = struct { key: Var, value: Var };

    allocator: Allocator,
    ident_count: u32,
    ident_bytes: []u8,
    ident_index_bytes: []u8,
    module_identity_count: u32,
    module_identity_bytes: []u8,
    module_identity_ranges_bytes: []u8,
    module_identity_index_bytes: []u8,
    module_identity_displays_len: usize,
    module_identity_displays_bytes: []u8,
    var_map_capacity: u32,
    var_map_entries: []VarMapEntry,

    fn capture(allocator: Allocator, checker: *const Self) Allocator.Error!@This() {
        const ident_interner = &checker.cir.common.idents.interner;
        const module_interner = &checker.cir.module_identities;
        const ident_bytes = try allocator.dupe(u8, ident_interner.bytes.items.items);
        errdefer allocator.free(ident_bytes);
        const ident_index_bytes = try allocator.dupe(
            u8,
            std.mem.sliceAsBytes(ident_interner.index.items.items),
        );
        errdefer allocator.free(ident_index_bytes);
        const module_identity_bytes = try allocator.dupe(u8, module_interner.bytes.items.items);
        errdefer allocator.free(module_identity_bytes);
        const module_identity_ranges_bytes = try allocator.dupe(
            u8,
            std.mem.sliceAsBytes(module_interner.ranges.items.items),
        );
        errdefer allocator.free(module_identity_ranges_bytes);
        const module_identity_index_bytes = try allocator.dupe(
            u8,
            std.mem.sliceAsBytes(module_interner.index.items.items),
        );
        errdefer allocator.free(module_identity_index_bytes);
        const module_identity_displays_bytes = try allocator.dupe(
            u8,
            std.mem.sliceAsBytes(checker.cir.module_identity_displays.items.items),
        );
        errdefer allocator.free(module_identity_displays_bytes);
        const var_map_entries = try allocator.alloc(VarMapEntry, checker.var_map.count());
        errdefer allocator.free(var_map_entries);
        var iterator = checker.var_map.iterator();
        var index: usize = 0;
        while (iterator.next()) |entry| : (index += 1) {
            var_map_entries[index] = .{ .key = entry.key_ptr.*, .value = entry.value_ptr.* };
        }
        std.debug.assert(index == var_map_entries.len);
        return .{
            .allocator = allocator,
            .ident_count = ident_interner.entry_count,
            .ident_bytes = ident_bytes,
            .ident_index_bytes = ident_index_bytes,
            .module_identity_count = module_interner.count(),
            .module_identity_bytes = module_identity_bytes,
            .module_identity_ranges_bytes = module_identity_ranges_bytes,
            .module_identity_index_bytes = module_identity_index_bytes,
            .module_identity_displays_len = checker.cir.module_identity_displays.items.items.len,
            .module_identity_displays_bytes = module_identity_displays_bytes,
            .var_map_capacity = checker.var_map.capacity(),
            .var_map_entries = var_map_entries,
        };
    }

    fn expectSameItems(self: *const @This(), checker: *const Self) !void {
        const ident_interner = &checker.cir.common.idents.interner;
        const module_interner = &checker.cir.module_identities;
        try std.testing.expectEqual(self.ident_count, ident_interner.entry_count);
        try std.testing.expectEqualSlices(u8, self.ident_bytes, ident_interner.bytes.items.items);
        try std.testing.expectEqualSlices(
            u8,
            self.ident_index_bytes,
            std.mem.sliceAsBytes(ident_interner.index.items.items),
        );
        try std.testing.expectEqual(self.module_identity_count, module_interner.count());
        try std.testing.expectEqualSlices(u8, self.module_identity_bytes, module_interner.bytes.items.items);
        try std.testing.expectEqualSlices(
            u8,
            self.module_identity_ranges_bytes,
            std.mem.sliceAsBytes(module_interner.ranges.items.items),
        );
        try std.testing.expectEqualSlices(
            u8,
            self.module_identity_index_bytes,
            std.mem.sliceAsBytes(module_interner.index.items.items),
        );
        try std.testing.expectEqual(
            self.module_identity_displays_len,
            checker.cir.module_identity_displays.items.items.len,
        );
        try std.testing.expectEqualSlices(
            u8,
            self.module_identity_displays_bytes,
            std.mem.sliceAsBytes(checker.cir.module_identity_displays.items.items),
        );
        try std.testing.expectEqual(self.var_map_entries.len, checker.var_map.count());
        for (self.var_map_entries) |entry| {
            try std.testing.expectEqual(entry.value, checker.var_map.get(entry.key).?);
        }
    }

    fn expectEqual(self: *const @This(), checker: *const Self) !void {
        try self.expectSameItems(checker);
        try std.testing.expectEqual(self.var_map_capacity, checker.var_map.capacity());
    }

    fn deinit(self: *@This()) void {
        self.allocator.free(self.var_map_entries);
        self.allocator.free(self.module_identity_displays_bytes);
        self.allocator.free(self.module_identity_index_bytes);
        self.allocator.free(self.module_identity_ranges_bytes);
        self.allocator.free(self.module_identity_bytes);
        self.allocator.free(self.ident_index_bytes);
        self.allocator.free(self.ident_bytes);
        self.* = undefined;
    }
};

const ExternalCacheSeedFixture = struct {
    const TestEnv = @import("test/TestEnv.zig");

    const provider_source =
        \\ExternalSeedProvider :: {}.{
        \\    identity : a -> a
        \\    identity = |value| value
        \\}
    ;
    const consumer_source =
        \\import ExternalSeedProvider exposing [identity]
        \\first = identity("first")
        \\second = identity("second")
    ;

    provider: TestEnv,
    checked: TestEnv,
    seed_index: usize,
    minimum_token_index: u32,
    sibling_token_index: u32,

    fn init() !@This() {
        var provider = try TestEnv.init("ExternalSeedProvider", provider_source);
        errdefer provider.deinit();
        try provider.assertNoErrors();

        var checked = try TestEnv.initWithImport(
            "ExternalSeedConsumer",
            consumer_source,
            "ExternalSeedProvider",
            &provider,
        );
        errdefer checked.deinit();
        try checked.assertNoErrors();

        const cir = checked.module_env;
        const tokens = cir.external_lookup_tokens.items.items;
        const seeds = cir.external_cache_seeds.items.items;
        try std.testing.expectEqual(@as(usize, 2), tokens.len);
        try std.testing.expectEqual(@as(usize, 1), seeds.len);
        try std.testing.expect(validateExternalLookupTokenProducerInventory(cir));
        try std.testing.expect(validateExternalCacheSeedsLocal(cir));

        const seed_index: usize = 0;
        const minimum_token_index = seeds[seed_index].seed_token;
        const sibling_token_index: u32 = if (minimum_token_index == 0) 1 else 0;
        try std.testing.expect(ModuleEnv.ExternalLookupKey.eql(
            tokens[minimum_token_index].key,
            tokens[sibling_token_index].key,
        ));

        return .{
            .provider = provider,
            .checked = checked,
            .seed_index = seed_index,
            .minimum_token_index = minimum_token_index,
            .sibling_token_index = sibling_token_index,
        };
    }

    fn initFreshConsumer(self: *const @This()) !TestEnv {
        return TestEnv.initWithImport(
            "ExternalSeedConsumer",
            consumer_source,
            "ExternalSeedProvider",
            &self.provider,
        );
    }

    fn deinit(self: *@This()) void {
        self.checked.deinit();
        self.provider.deinit();
        self.* = undefined;
    }
};

test "external cache seed proof rejects seed and support retargets" {
    var fixture = try ExternalCacheSeedFixture.init();
    defer fixture.deinit();

    const cir = fixture.checked.module_env;
    const seed_index = fixture.seed_index;
    const sibling_index = fixture.sibling_token_index;
    const saved_seed = cir.external_cache_seeds.items.items[seed_index];

    cir.external_cache_seeds.items.items[seed_index].seed_token = sibling_index;
    cir.external_cache_seeds.items.items[seed_index].seed_node =
        cir.external_lookup_tokens.items.items[sibling_index].origin_node;
    try std.testing.expect(!validateExternalCacheSeedsLocal(cir));
    cir.external_cache_seeds.items.items[seed_index] = saved_seed;

    cir.external_cache_seeds.items.items[seed_index].state =
        @intFromEnum(ModuleEnv.ExternalCacheSeed.State.reserved);
    cir.external_cache_seeds.items.items[seed_index].support_step =
        ModuleEnv.ExternalCacheSeed.none;
    try std.testing.expect(!validateExternalCacheSeedsLocal(cir));
    cir.external_cache_seeds.items.items[seed_index] = saved_seed;

    const support_index = saved_seed.support_step;
    const support = cir.where_marker_copy_steps.items.items[support_index];
    const root_occurrence_index = support.occurrences_start + support.root_occurrence_offset;
    const support_root =
        cir.where_marker_copy_occurrences.items.items[root_occurrence_index];
    const root_pair_index = support.pairs_start + support_root.canonical_pair_offset;
    const support_root_pair = cir.where_marker_copy_pairs.items.items[root_pair_index];
    try std.testing.expectEqual(saved_seed.key.target_node, support_root.raw_source_var);
    try std.testing.expect(support_root.raw_source_var != support.source_root_var);
    try std.testing.expectEqual(support.source_root_var, support_root_pair.source_var);
    try std.testing.expectEqual(
        support.destination_root_var,
        support_root_pair.destination_var,
    );

    cir.where_marker_copy_occurrences.items.items[root_occurrence_index].raw_source_var =
        support.source_root_var;
    try std.testing.expect(!validateExternalCacheSeedsLocal(cir));
    cir.where_marker_copy_occurrences.items.items[root_occurrence_index] = support_root;

    const saved_support_origin = support.origin.external_cache_seed;
    cir.where_marker_copy_steps.items.items[support_index]
        .origin.external_cache_seed.seed_row = ModuleEnv.ExternalCacheSeed.none;
    try std.testing.expect(!validateExternalCacheSeedsLocal(cir));
    cir.where_marker_copy_steps.items.items[support_index]
        .origin.external_cache_seed = saved_support_origin;

    const seed_len = cir.external_cache_seeds.items.items.len;
    cir.external_cache_seeds.items.items.len = 0;
    try std.testing.expect(!validateExternalCacheSeedsLocal(cir));
    cir.external_cache_seeds.items.items.len = seed_len;
    try std.testing.expect(validateExternalCacheSeedsLocal(cir));
}

