test "external cache seed context mismatch and Probe rollback" {
    var fixture = try ExternalCacheSeedFixture.init();
    defer fixture.deinit();
    var fresh_consumer = try fixture.initFreshConsumer();
    defer fresh_consumer.deinit();
    try fresh_consumer.assertNoErrors();

    const cir = fixture.checked.module_env;
    const minimum_index = fixture.minimum_token_index;
    const sibling_index = fixture.sibling_token_index;
    const context = ImportResolution{
        .resolution_env = fresh_consumer.module_env,
        .imported_modules = .{ .supplied = .{
            .envs = fresh_consumer.checker.imported_modules,
            .modules = fresh_consumer.checker.validated_imported_modules,
        } },
        .semantic_dependencies = .{ .supplied = .{
            .envs = fresh_consumer.checker.owner_modules,
            .modules = fresh_consumer.checker.validated_owner_modules,
        } },
        .platform_dependency_index = fresh_consumer.checker.platform_dependency_index,
        .expected_failure_replay = .fresh_canonical,
    };

    try validateExternalLookupTokenContext(cir, context);
    const saved_sibling_token = cir.external_lookup_tokens.items.items[sibling_index];
    cir.external_lookup_tokens.items.items[sibling_index].origin_node =
        cir.external_lookup_tokens.items.items[minimum_index].origin_node;
    try std.testing.expectError(
        error.CorruptArtifact,
        validateExternalLookupTokenContext(cir, context),
    );
    cir.external_lookup_tokens.items.items[sibling_index] = saved_sibling_token;
    try validateExternalLookupTokenContext(cir, context);

    // Force a genuine cache miss inside an outer Probe. The miss owns an
    // inner Probe which commits its seed/copy/cache insertion to the outer
    // scope; rolling the outer scope back must still erase that entire suffix.
    const saved_seed = cir.external_cache_seeds.items.items[fixture.seed_index];
    const cache_key = ImportCacheKey{
        .resolved_module_idx = saved_seed.key.resolved_module_idx,
        .node_idx = @enumFromInt(saved_seed.key.target_node),
    };
    const saved_cached_copy = fixture.checked.checker.import_cache.get(cache_key) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(fixture.checked.checker.import_cache.remove(cache_key));

    const seeds_before = cir.external_cache_seeds.items.items.len;
    const steps_before = cir.where_marker_copy_steps.items.items.len;
    const pairs_before = cir.where_marker_copy_pairs.items.items.len;
    const occurrences_before = cir.where_marker_copy_occurrences.items.items.len;
    const constraint_pairs_before = cir.where_marker_constraint_copy_pairs.items.items.len;
    const witnesses_before = cir.where_marker_copy_witnesses.items.items.len;
    const type_schemes_before = fixture.checked.checker.type_schemes.items.len;
    const types_before = fixture.checked.checker.types.len();
    const cache_journal_before =
        fixture.checked.checker.import_cache_insertion_journal.items.len;
    const binding_journal_before =
        fixture.checked.checker.binding_scheme_mutation_journal.items.len;

    {
        var outer = try fixture.checked.checker.beginProbe(null);
        var outer_open = true;
        errdefer if (outer_open) outer.rollback();
        const lookup_token = cir.external_lookup_tokens.items.items[minimum_index];
        _ = (try fixture.checked.checker.resolveVarFromExternal(
            @enumFromInt(lookup_token.import_idx),
            lookup_token.key.target_node,
            .{
                .site_kind = lookup_token.decodedSiteKind() orelse
                    return error.TestUnexpectedResult,
                .origin_node = lookup_token.origin_node,
                .parameter_ordinal = lookup_token.parameter_ordinal,
            },
        )) orelse return error.TestUnexpectedResult;

        try std.testing.expect(fixture.checked.checker.import_cache.get(cache_key) != null);
        try std.testing.expectEqual(
            seeds_before + 1,
            cir.external_cache_seeds.items.items.len,
        );
        try std.testing.expect(cir.where_marker_copy_steps.items.items.len > steps_before);
        try std.testing.expectEqual(
            cache_journal_before + 1,
            fixture.checked.checker.import_cache_insertion_journal.items.len,
        );
        outer.rollback();
        outer_open = false;
    }

    try std.testing.expect(fixture.checked.checker.import_cache.get(cache_key) == null);
    try std.testing.expectEqual(seeds_before, cir.external_cache_seeds.items.items.len);
    try std.testing.expectEqual(steps_before, cir.where_marker_copy_steps.items.items.len);
    try std.testing.expectEqual(pairs_before, cir.where_marker_copy_pairs.items.items.len);
    try std.testing.expectEqual(
        occurrences_before,
        cir.where_marker_copy_occurrences.items.items.len,
    );
    try std.testing.expectEqual(
        constraint_pairs_before,
        cir.where_marker_constraint_copy_pairs.items.items.len,
    );
    try std.testing.expectEqual(
        witnesses_before,
        cir.where_marker_copy_witnesses.items.items.len,
    );
    try std.testing.expectEqual(
        type_schemes_before,
        fixture.checked.checker.type_schemes.items.len,
    );
    try std.testing.expectEqual(types_before, fixture.checked.checker.types.len());
    try std.testing.expectEqual(
        cache_journal_before,
        fixture.checked.checker.import_cache_insertion_journal.items.len,
    );
    try std.testing.expectEqual(
        binding_journal_before,
        fixture.checked.checker.binding_scheme_mutation_journal.items.len,
    );

    fixture.checked.checker.import_cache.putAssumeCapacityNoClobber(
        cache_key,
        saved_cached_copy,
    );
    try std.testing.expect(validateExternalCacheSeedsLocal(cir));
}

test "cold external nominal cache miss is wholly owned by an outer Probe" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\ColdProbeProvider :: {}.{
        \\    FreshProbeNominal := [FreshProbePayload(Str)]
        \\    fresh_probe_value : FreshProbeNominal
        \\    fresh_probe_value = FreshProbePayload("payload")
        \\}
    ;
    var provider = try TestEnv.init("ColdProbeProvider", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const consumer_source =
        \\import ColdProbeProvider exposing [fresh_probe_value]
        \\result = fresh_probe_value
    ;
    var consumer = try TestEnv.initUncheckedWithImportForTesting(
        "ColdProbeConsumer",
        consumer_source,
        "ColdProbeProvider",
        &provider,
    );
    defer consumer.deinit();
    const checker = &consumer.checker;
    const cir = consumer.module_env;
    try checker.ensureTypeStoreIsFilled();
    try std.testing.expectEqual(@as(usize, 0), checker.import_cache.count());

    const token = for (cir.external_lookup_tokens.items.items) |candidate| {
        if (candidate.decodedSiteKind() == .external_lookup_expr) break candidate;
    } else return error.TestUnexpectedResult;
    const provider_hash = provider.module_env.contentIdentityHash() orelse
        return error.TestUnexpectedResult;
    // Bind the exact producer-authored nominal spelling rather than assuming
    // whether the provider stores it qualified or unqualified.
    const provider_target = provider.checker.types.resolveVar(
        @enumFromInt(token.key.target_node),
    ).desc.content;
    if (provider_target != .structure or provider_target.structure != .nominal_type) {
        return error.TestUnexpectedResult;
    }
    const nominal_name = base.Ident.for_text(provider.module_env.getIdent(
        provider_target.structure.nominal_type.ident.ident_idx,
    ));
    try std.testing.expect(cir.lookupModuleIdentity(provider_hash) == null);
    try std.testing.expect(cir.getIdentStoreConst().lookup(nominal_name) == null);

    var snapshot = try ProbeCrossCopyOwnedStateSnapshot.capture(std.testing.allocator, checker);
    defer snapshot.deinit();
    const types_before = checker.types.len();
    const seeds_before = cir.external_cache_seeds.items.items.len;
    const steps_before = cir.where_marker_copy_steps.items.items.len;
    const pairs_before = cir.where_marker_copy_pairs.items.items.len;
    const occurrences_before = cir.where_marker_copy_occurrences.items.items.len;
    const constraint_pairs_before = cir.where_marker_constraint_copy_pairs.items.items.len;
    const witnesses_before = cir.where_marker_copy_witnesses.items.items.len;
    const cache_journal_before = checker.import_cache_insertion_journal.items.len;

    {
        var outer = try checker.beginProbe(null);
        var outer_open = true;
        errdefer if (outer_open) outer.rollback();
        _ = (try checker.resolveVarFromExternal(
            @enumFromInt(token.import_idx),
            token.key.target_node,
            .{
                .site_kind = token.decodedSiteKind() orelse return error.TestUnexpectedResult,
                .origin_node = token.origin_node,
                .parameter_ordinal = token.parameter_ordinal,
            },
        )) orelse return error.TestUnexpectedResult;

        try std.testing.expect(cir.lookupModuleIdentity(provider_hash) != null);
        try std.testing.expect(cir.getIdentStoreConst().lookup(nominal_name) != null);
        try std.testing.expect(cir.common.idents.interner.entry_count > snapshot.ident_count);
        try std.testing.expect(cir.module_identities.count() > snapshot.module_identity_count);
        try std.testing.expect(
            cir.module_identity_displays.items.items.len > snapshot.module_identity_displays_len,
        );
        try std.testing.expect(checker.var_map.count() > snapshot.var_map_entries.len);
        try std.testing.expect(checker.types.len() > types_before);
        try std.testing.expect(cir.external_cache_seeds.items.items.len > seeds_before);
        try std.testing.expect(cir.where_marker_copy_steps.items.items.len > steps_before);
        try std.testing.expect(checker.import_cache.count() != 0);
        outer.rollback();
        outer_open = false;
    }

    try snapshot.expectEqual(checker);
    try std.testing.expect(cir.lookupModuleIdentity(provider_hash) == null);
    try std.testing.expect(cir.getIdentStoreConst().lookup(nominal_name) == null);
    try std.testing.expectEqual(types_before, checker.types.len());
    try std.testing.expectEqual(seeds_before, cir.external_cache_seeds.items.items.len);
    try std.testing.expectEqual(steps_before, cir.where_marker_copy_steps.items.items.len);
    try std.testing.expectEqual(pairs_before, cir.where_marker_copy_pairs.items.items.len);
    try std.testing.expectEqual(occurrences_before, cir.where_marker_copy_occurrences.items.items.len);
    try std.testing.expectEqual(
        constraint_pairs_before,
        cir.where_marker_constraint_copy_pairs.items.items.len,
    );
    try std.testing.expectEqual(witnesses_before, cir.where_marker_copy_witnesses.items.items.len);
    try std.testing.expectEqual(cache_journal_before, checker.import_cache_insertion_journal.items.len);
    try std.testing.expectEqual(@as(usize, 0), checker.import_cache.count());
}

test "nested Probe close order preserves exact interner display and var-map ownership" {
    const TestEnv = @import("test/TestEnv.zig");
    var test_env = try TestEnv.initExpr("NestedProbeOwnedState", "{}");
    defer test_env.deinit();
    const checker = &test_env.checker;
    const cir = test_env.module_env;

    const baseline_key = try checker.types.fresh();
    const baseline_value = try checker.types.fresh();
    try checker.var_map.put(baseline_key, baseline_value);

    var before_outer_commit = try ProbeCrossCopyOwnedStateSnapshot.capture(
        std.testing.allocator,
        checker,
    );
    defer before_outer_commit.deinit();
    {
        var outer = try checker.beginProbe(null);
        var outer_open = true;
        errdefer if (outer_open) outer.rollback();
        const outer_ident = try cir.insertIdent(base.Ident.for_text("probe_outer_kept"));
        const outer_hash = [_]u8{0x91} ** @sizeOf(base.ModuleIdentity.Hash);
        _ = try cir.internModuleIdentity(&outer_hash, outer_ident);
        const outer_key = try checker.types.fresh();
        const outer_value = try checker.types.fresh();
        try checker.var_map.put(outer_key, outer_value);

        var after_outer_mutation = try ProbeCrossCopyOwnedStateSnapshot.capture(
            std.testing.allocator,
            checker,
        );
        defer after_outer_mutation.deinit();
        {
            var inner = try checker.beginProbe(null);
            var inner_open = true;
            errdefer if (inner_open) inner.rollback();
            const inner_ident = try cir.insertIdent(base.Ident.for_text("probe_inner_rolled_back"));
            const inner_hash = [_]u8{0x92} ** @sizeOf(base.ModuleIdentity.Hash);
            _ = try cir.internModuleIdentity(&inner_hash, inner_ident);
            try checker.var_map.put(try checker.types.fresh(), try checker.types.fresh());
            inner.rollback();
            inner_open = false;
        }
        try after_outer_mutation.expectEqual(checker);
        outer.commit();
        outer_open = false;
    }
    try std.testing.expect(cir.getIdentStoreConst().lookup(base.Ident.for_text("probe_outer_kept")) != null);
    try std.testing.expect(cir.getIdentStoreConst().lookup(base.Ident.for_text("probe_inner_rolled_back")) == null);

    var before_outer_rollback = try ProbeCrossCopyOwnedStateSnapshot.capture(
        std.testing.allocator,
        checker,
    );
    defer before_outer_rollback.deinit();
    {
        var outer = try checker.beginProbe(null);
        var outer_open = true;
        errdefer if (outer_open) outer.rollback();
        const outer_ident = try cir.insertIdent(base.Ident.for_text("probe_outer_rolled_back"));
        const outer_hash = [_]u8{0x93} ** @sizeOf(base.ModuleIdentity.Hash);
        _ = try cir.internModuleIdentity(&outer_hash, outer_ident);
        try checker.var_map.put(try checker.types.fresh(), try checker.types.fresh());
        {
            var inner = try checker.beginProbe(null);
            var inner_open = true;
            errdefer if (inner_open) inner.rollback();
            const inner_ident = try cir.insertIdent(base.Ident.for_text("probe_inner_committed"));
            const inner_hash = [_]u8{0x94} ** @sizeOf(base.ModuleIdentity.Hash);
            _ = try cir.internModuleIdentity(&inner_hash, inner_ident);
            try checker.var_map.put(try checker.types.fresh(), try checker.types.fresh());
            inner.commit();
            inner_open = false;
        }
        outer.rollback();
        outer_open = false;
    }
    try before_outer_rollback.expectEqual(checker);
    try std.testing.expect(cir.getIdentStoreConst().lookup(base.Ident.for_text("probe_outer_rolled_back")) == null);
    try std.testing.expect(cir.getIdentStoreConst().lookup(base.Ident.for_text("probe_inner_committed")) == null);
    try std.testing.expect(before_outer_commit.var_map_entries.len < checker.var_map.count());
}

