test "checker module input ownership is an exhaustive OOM transaction" {
    const TestEnv = @import("test/TestEnv.zig");
    var provider = try TestEnv.init("OwnedModuleInputProvider", "value = 1");
    defer provider.deinit();
    try provider.assertNoErrors();
    const capability = try provider.checker.validatedModule();

    const Helper = struct {
        fn run(
            allocator: Allocator,
            env: *const ModuleEnv,
            validated: ValidatedModuleEnv,
        ) !void {
            const imported_envs = [_]*const ModuleEnv{env};
            const imported_capabilities = [_]ValidatedModuleEnv{validated};
            const owner_envs = [_]*const ModuleEnv{env};
            const owner_capabilities = [_]ValidatedModuleEnv{validated};
            const imported = ValidatedModuleSet{
                .envs = &imported_envs,
                .modules = &imported_capabilities,
            };
            const owners = ValidatedModuleSet{
                .envs = &owner_envs,
                .modules = &owner_capabilities,
            };
            const owned = try OwnedModuleInputs.init(allocator, imported, owners);
            defer owned.deinit(allocator);

            try std.testing.expect(owned.imported_envs.ptr != imported.envs.ptr);
            try std.testing.expect(owned.imported_capabilities.ptr != imported.modules.ptr);
            try std.testing.expect(owned.owner_envs.ptr != owners.envs.ptr);
            try std.testing.expect(owned.owner_capabilities.ptr != owners.modules.ptr);
            try std.testing.expect(owned.imported_envs.ptr != owned.owner_envs.ptr);
            try std.testing.expectEqual(env, owned.imported_envs[0]);
            try std.testing.expectEqual(validated.handle, owned.imported_capabilities[0].handle);
            try std.testing.expectEqual(env, owned.owner_envs[0]);
            try std.testing.expectEqual(validated.handle, owned.owner_capabilities[0].handle);
        }
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        Helper.run,
        .{ provider.module_env, capability },
    );
}

test "external cache first miss is an exhaustive OOM transaction" {
    const TestEnv = @import("test/TestEnv.zig");
    const provider_source =
        \\ExternalMissProvider :: {}.{
        \\    FreshMissNominal := [FreshMissPayload(Str)]
        \\    identity : a, FreshMissNominal -> a
        \\    identity = |value, _nominal| value
        \\}
    ;
    var provider = try TestEnv.init("ExternalMissProvider", provider_source);
    defer provider.deinit();
    try provider.assertNoErrors();

    const source =
        \\import ExternalMissProvider exposing [identity]
        \\result = identity("value")
    ;
    var induced_failures: usize = 0;
    var reached_success = false;
    for (0..128) |fail_index| {
        var consumer = try TestEnv.initUncheckedWithImportForTesting(
            "ExternalMissConsumer",
            source,
            "ExternalMissProvider",
            &provider,
        );
        defer consumer.deinit();
        const checker = &consumer.checker;
        const cir = consumer.module_env;
        const token = for (cir.external_lookup_tokens.items.items) |candidate| {
            if (candidate.decodedSiteKind() == .external_lookup_expr) break candidate;
        } else return error.TestUnexpectedResult;
        const site_kind = token.decodedSiteKind() orelse return error.TestUnexpectedResult;
        try checker.ensureTypeStoreIsFilled();

        const types_len = checker.types.len();
        const contracts_len = checker.types.where_method_marker_contracts.items.items.len;
        const bases_len = checker.types.where_method_marker_bases.items.items.len;
        const type_paths_len = checker.types.where_method_marker_path_steps.items.items.len;
        const steps_len = cir.where_marker_copy_steps.items.items.len;
        const pairs_len = cir.where_marker_copy_pairs.items.items.len;
        const occurrences_len = cir.where_marker_copy_occurrences.items.items.len;
        const constraint_pairs_len = cir.where_marker_constraint_copy_pairs.items.items.len;
        const witnesses_len = cir.where_marker_copy_witnesses.items.items.len;
        const moves_len = cir.where_marker_constraint_moves.items.items.len;
        const move_offsets_len = cir.where_marker_constraint_move_offsets.items.items.len;
        const substitutions_len = cir.where_marker_platform_substitutions.items.items.len;
        const seeds_len = cir.external_cache_seeds.items.items.len;
        const schemes_len = checker.type_schemes.items.len;
        const cache_count = checker.import_cache.count();
        const cache_journal_len = checker.import_cache_insertion_journal.items.len;
        const binding_journal_len = checker.binding_scheme_mutation_journal.items.len;
        const synthetic_bindings_count = checker.synthetic_binding_schemes.count();
        const probe_depth = checker.probe_depth;
        const store_savepoint_depth = checker.types.savepoint_depth;
        const ident_savepoint_depth = cir.common.idents.interner.savepoint_depth;
        const identity_savepoint_depth = cir.module_identities.savepoint_depth;
        var cross_copy_owned_state = try ProbeCrossCopyOwnedStateSnapshot.capture(
            std.testing.allocator,
            checker,
        );
        defer cross_copy_owned_state.deinit();
        try std.testing.expectEqual(@as(usize, 0), seeds_len);
        try std.testing.expectEqual(@as(usize, 0), cache_count);

        // The real cache miss opens and commits an inner Probe. Keep one
        // normally allocated outer Probe around the failure-injected call so
        // both a successful inner commit and every failed suffix must restore
        // the exact pre-probe state when the outer owner rolls back.
        var outer = try checker.beginProbe(null);
        var outer_open = true;
        errdefer if (outer_open) outer.rollback();

        var failing = std.testing.FailingAllocator.init(
            std.testing.allocator,
            .{ .fail_index = fail_index, .resize_fail_index = 0 },
        );
        const failing_gpa = failing.allocator();
        const saved_checker_gpa = checker.gpa;
        const saved_cir_gpa = cir.gpa;
        const saved_types_gpa = checker.types.gpa;
        checker.gpa = failing_gpa;
        cir.gpa = failing_gpa;
        checker.types.gpa = failing_gpa;
        const result = checker.resolveVarFromExternal(
            @enumFromInt(token.import_idx),
            token.key.target_node,
            .{
                .site_kind = site_kind,
                .origin_node = token.origin_node,
                .parameter_ordinal = token.parameter_ordinal,
            },
        );
        checker.gpa = saved_checker_gpa;
        cir.gpa = saved_cir_gpa;
        checker.types.gpa = saved_types_gpa;

        if (result) |maybe_external| {
            try std.testing.expect(!failing.has_induced_failure);
            try std.testing.expect(maybe_external != null);
            try std.testing.expectEqual(@as(usize, 1), cir.external_cache_seeds.items.items.len);
            try std.testing.expectEqual(@as(usize, 1), checker.import_cache.count());
            try std.testing.expectEqual(cache_journal_len + 1, checker.import_cache_insertion_journal.items.len);
            try std.testing.expectEqual(binding_journal_len + 1, checker.binding_scheme_mutation_journal.items.len);
            try std.testing.expectEqual(
                synthetic_bindings_count + 1,
                checker.synthetic_binding_schemes.count(),
            );
            try std.testing.expectEqual(probe_depth + 1, checker.probe_depth);
            try std.testing.expectEqual(store_savepoint_depth + 1, checker.types.savepoint_depth);
            try std.testing.expectEqual(ident_savepoint_depth + 1, cir.common.idents.interner.savepoint_depth);
            try std.testing.expectEqual(identity_savepoint_depth + 1, cir.module_identities.savepoint_depth);
            try std.testing.expect(
                cir.common.idents.interner.entry_count > cross_copy_owned_state.ident_count,
            );
            try std.testing.expect(
                cir.module_identities.count() > cross_copy_owned_state.module_identity_count,
            );
            try std.testing.expect(
                cir.module_identity_displays.items.items.len >
                    cross_copy_owned_state.module_identity_displays_len,
            );
            try std.testing.expect(checker.var_map.count() > cross_copy_owned_state.var_map_entries.len);
            try std.testing.expect(cir.where_marker_copy_steps.items.items.len > steps_len);
            try std.testing.expect(cir.where_marker_copy_pairs.items.items.len > pairs_len);
            try std.testing.expect(cir.where_marker_copy_occurrences.items.items.len > occurrences_len);
            try std.testing.expect(cir.where_marker_copy_witnesses.items.items.len > witnesses_len);
            try std.testing.expect(validateExternalCacheSeedsLocal(cir));
            outer.rollback();
            outer_open = false;
            try cross_copy_owned_state.expectEqual(checker);
            try std.testing.expectEqual(types_len, checker.types.len());
            try std.testing.expectEqual(contracts_len, checker.types.where_method_marker_contracts.items.items.len);
            try std.testing.expectEqual(bases_len, checker.types.where_method_marker_bases.items.items.len);
            try std.testing.expectEqual(type_paths_len, checker.types.where_method_marker_path_steps.items.items.len);
            try std.testing.expectEqual(seeds_len, cir.external_cache_seeds.items.items.len);
            try std.testing.expectEqual(steps_len, cir.where_marker_copy_steps.items.items.len);
            try std.testing.expectEqual(pairs_len, cir.where_marker_copy_pairs.items.items.len);
            try std.testing.expectEqual(occurrences_len, cir.where_marker_copy_occurrences.items.items.len);
            try std.testing.expectEqual(constraint_pairs_len, cir.where_marker_constraint_copy_pairs.items.items.len);
            try std.testing.expectEqual(witnesses_len, cir.where_marker_copy_witnesses.items.items.len);
            try std.testing.expectEqual(moves_len, cir.where_marker_constraint_moves.items.items.len);
            try std.testing.expectEqual(move_offsets_len, cir.where_marker_constraint_move_offsets.items.items.len);
            try std.testing.expectEqual(substitutions_len, cir.where_marker_platform_substitutions.items.items.len);
            try std.testing.expectEqual(schemes_len, checker.type_schemes.items.len);
            try std.testing.expectEqual(cache_count, checker.import_cache.count());
            try std.testing.expectEqual(cache_journal_len, checker.import_cache_insertion_journal.items.len);
            try std.testing.expectEqual(binding_journal_len, checker.binding_scheme_mutation_journal.items.len);
            try std.testing.expectEqual(synthetic_bindings_count, checker.synthetic_binding_schemes.count());
            try std.testing.expectEqual(probe_depth, checker.probe_depth);
            try std.testing.expectEqual(store_savepoint_depth, checker.types.savepoint_depth);
            try std.testing.expectEqual(ident_savepoint_depth, cir.common.idents.interner.savepoint_depth);
            try std.testing.expectEqual(identity_savepoint_depth, cir.module_identities.savepoint_depth);
            reached_success = true;
            break;
        } else |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
            try std.testing.expect(failing.has_induced_failure);
            induced_failures += 1;
            outer.rollback();
            outer_open = false;
            try std.testing.expectEqual(types_len, checker.types.len());
            try std.testing.expectEqual(contracts_len, checker.types.where_method_marker_contracts.items.items.len);
            try std.testing.expectEqual(bases_len, checker.types.where_method_marker_bases.items.items.len);
            try std.testing.expectEqual(type_paths_len, checker.types.where_method_marker_path_steps.items.items.len);
            try std.testing.expectEqual(steps_len, cir.where_marker_copy_steps.items.items.len);
            try std.testing.expectEqual(pairs_len, cir.where_marker_copy_pairs.items.items.len);
            try std.testing.expectEqual(occurrences_len, cir.where_marker_copy_occurrences.items.items.len);
            try std.testing.expectEqual(constraint_pairs_len, cir.where_marker_constraint_copy_pairs.items.items.len);
            try std.testing.expectEqual(witnesses_len, cir.where_marker_copy_witnesses.items.items.len);
            try std.testing.expectEqual(moves_len, cir.where_marker_constraint_moves.items.items.len);
            try std.testing.expectEqual(move_offsets_len, cir.where_marker_constraint_move_offsets.items.items.len);
            try std.testing.expectEqual(substitutions_len, cir.where_marker_platform_substitutions.items.items.len);
            try std.testing.expectEqual(seeds_len, cir.external_cache_seeds.items.items.len);
            try std.testing.expectEqual(schemes_len, checker.type_schemes.items.len);
            try std.testing.expectEqual(cache_count, checker.import_cache.count());
            try std.testing.expectEqual(cache_journal_len, checker.import_cache_insertion_journal.items.len);
            try std.testing.expectEqual(binding_journal_len, checker.binding_scheme_mutation_journal.items.len);
            try std.testing.expectEqual(synthetic_bindings_count, checker.synthetic_binding_schemes.count());
            try std.testing.expectEqual(probe_depth, checker.probe_depth);
            try std.testing.expectEqual(store_savepoint_depth, checker.types.savepoint_depth);
            try std.testing.expectEqual(ident_savepoint_depth, cir.common.idents.interner.savepoint_depth);
            try std.testing.expectEqual(identity_savepoint_depth, cir.module_identities.savepoint_depth);
            try cross_copy_owned_state.expectEqual(checker);
        }
    }
    try std.testing.expect(reached_success);
    try std.testing.expect(induced_failures > 0);
}

test "platform requirement alias substitution is an exhaustive public-copy OOM transaction" {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    const platform_source =
        \\platform ""
        \\    requires { [Model : model] for prog : { init : {} -> Model, tick : Model -> Model } }
        \\    exposes []
        \\    packages {}
        \\    provides {}
    ;
    var platform = try TestEnv.init("PlatformCopyOomSource", platform_source);
    defer platform.deinit();
    try platform.assertNoErrors();

    const platform_cir = platform.module_env;
    try std.testing.expectEqual(@as(usize, 1), platform_cir.requires_types.items.items.len);
    const required = platform_cir.requires_types.items.items[0];
    const aliases = platform_cir.for_clause_aliases.sliceRange(required.type_aliases);
    try std.testing.expectEqual(@as(usize, 1), aliases.len);
    const for_alias = aliases[0];
    const alias_statement = platform_cir.store.getStatement(for_alias.alias_stmt_idx);
    if (alias_statement != .s_alias_decl) return error.TestUnexpectedResult;
    const alias_decl = alias_statement.s_alias_decl;
    const platform_alias_resolved = platform_cir.types.resolveVar(
        ModuleEnv.varFrom(for_alias.alias_stmt_idx),
    );
    if (platform_alias_resolved.desc.content != .alias) return error.TestUnexpectedResult;
    const platform_alias_var = platform_alias_resolved.var_;
    const platform_alias = platform_alias_resolved.desc.content.alias;
    const platform_alias_source = copy_import.AliasSource{
        .origin_module = platform_alias.origin_module,
        .source_decl = platform_alias.source_decl.toOptional() orelse
            return error.TestUnexpectedResult,
    };
    const platform_identity_annotation = ModuleEnv.varFrom(alias_decl.anno);
    const platform_identity_var = platform_cir.types.resolveVar(
        platform_identity_annotation,
    ).var_;
    try std.testing.expect(platform_alias_var != platform_identity_var);

    const requirement_root = ModuleEnv.varFrom(required.type_anno);
    const requirement_resolved = platform_cir.types.resolveVar(requirement_root);
    if (requirement_resolved.desc.content != .structure or
        requirement_resolved.desc.content.structure != .record)
    {
        return error.TestUnexpectedResult;
    }
    try std.testing.expect(requirement_resolved.var_ != platform_alias_var);
    try std.testing.expect(requirement_resolved.var_ != platform_identity_var);
    const requirement_fields = platform_cir.types.getRecordFieldsSlice(
        requirement_resolved.desc.content.structure.record.fields,
    );
    var platform_alias_occurrence: ?Var = null;
    for (requirement_fields.items(.name), requirement_fields.items(.presence)) |name, presence| {
        if (!std.mem.eql(u8, platform_cir.getIdent(name), "init")) continue;
        if (platform_alias_occurrence != null) return error.TestUnexpectedResult;
        const function = platform_cir.types.resolveVar(presence.typeVar()).desc.content.unwrapFunc() orelse
            return error.TestUnexpectedResult;
        platform_alias_occurrence = function.ret;
    }
    const exact_platform_alias_occurrence = platform_alias_occurrence orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(
        platform_alias_var,
        platform_cir.types.resolveVar(exact_platform_alias_occurrence).var_,
    );
    const requirement_alias = platform_cir.types.resolveVar(exact_platform_alias_occurrence).desc.content.alias;
    try std.testing.expectEqual(platform_alias_source.origin_module, requirement_alias.origin_module);
    try std.testing.expectEqual(
        platform_alias_source.source_decl,
        requirement_alias.source_decl.toOptional() orelse return error.TestUnexpectedResult,
    );

    const app_source =
        \\app [prog] {}
        \\
        \\Model : {}
        \\prog : { init : {} -> Model, tick : Model -> Model }
        \\prog = { init: |_| {}, tick: |model| model }
    ;
    const builtin_indices = compiled_builtins.builtinIndices(CIR);
    var saw_oom = false;
    var reached_success = false;
    for (0..256) |fail_index| {
        var app = try TestEnv.initWithAdmittedBuiltinForTesting(
            "PlatformCopyOomApp",
            app_source,
            platform.builtin_module,
            platform.builtin_validation,
            builtin_indices,
        );
        defer app.deinit();
        try app.assertNoErrors();
        const checker = &app.checker;
        const app_cir = app.module_env;
        try std.testing.expect(app_cir.module_kind == .app or app_cir.module_kind == .default_app);

        const model_ident = try app_cir.insertIdent(base.Ident.for_text("Model"));
        const app_type_stmt = checker.appTypeDeclByIdent(model_ident) orelse
            return error.TestUnexpectedResult;
        const prog_ident = try app_cir.insertIdent(base.Ident.for_text("prog"));
        const prog_def = checker.exposedAppDefByIdent(prog_ident) orelse
            return error.TestUnexpectedResult;
        const app_type_region = app_cir.store.getNodeRegion(
            ModuleEnv.nodeIdxFrom(app_type_stmt),
        );

        var env = try Env.init(checker.gpa, .outermost);
        defer env.deinit(checker.gpa);
        const app_copy = try checker.instantiateVarWithMarkerCopy(
            ModuleEnv.varFrom(app_type_stmt),
            &env,
            .{ .explicit = app_type_region },
            .{ .platform_alias_app_decl = .{
                .platform_alias_statement = @intFromEnum(for_alias.alias_stmt_idx),
                .app_declaration_node = @intFromEnum(app_type_stmt),
            } },
            .eager_support,
        );
        const app_instantiation_step = app_copy.copy_step orelse
            return error.TestUnexpectedResult;
        const app_step = app_cir.where_marker_copy_steps.items.items[app_instantiation_step];
        try std.testing.expectEqual(
            ModuleEnv.WhereMarkerCopyStep.Kind.platform_alias_app_decl,
            app_step.decodedKind() orelse return error.TestUnexpectedResult,
        );
        try std.testing.expectEqual(
            @intFromEnum(for_alias.alias_stmt_idx),
            app_step.origin.platform_alias_app_decl.platform_alias_statement,
        );
        try std.testing.expectEqual(
            @intFromEnum(app_type_stmt),
            app_step.origin.platform_alias_app_decl.app_declaration_node,
        );
        // This fixture invokes the provisional local producer after TestEnv's
        // checked boundary. Apply the same deterministic terminal BFS before
        // taking the transaction baseline so the successful cross-module
        // step can be admitted together with its cited local authority.
        for (app_cir.where_marker_copy_steps.items.items) |local_step| {
            canonicalizeCheckedBoundaryCopyPairBfs(
                app_cir.where_marker_copy_pairs.items.items[local_step.pairs_start..][0..local_step.pairs_len],
                app_cir.where_marker_copy_occurrences.items.items[local_step.occurrences_start..][0..local_step.occurrences_len],
                app_cir.where_marker_copy_witnesses.items.items[local_step.witnesses_start..][0..local_step.witnesses_len],
                local_step.root_occurrence_offset,
            );
        }
        try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, app_cir));

        checker.var_map.clearRetainingCapacity();
        try checker.var_map.put(platform_alias_var, app_copy.var_);
        try checker.var_map.put(platform_identity_var, app_copy.var_);
        var alias_source_mapping = std.AutoHashMap(copy_import.AliasSource, Var).init(
            std.testing.allocator,
        );
        defer alias_source_mapping.deinit();
        try alias_source_mapping.put(platform_alias_source, app_copy.var_);

        const substitutions = [_]copy_import.PlatformAliasSubstitutionInput{.{
            .platform_alias_var = platform_alias_var,
            .platform_identity_var = platform_identity_var,
            .platform_alias_source = platform_alias_source,
            .platform_alias_statement = @intFromEnum(for_alias.alias_stmt_idx),
            .app_declaration_node = @intFromEnum(app_type_stmt),
            .app_instantiation_step = app_instantiation_step,
        }};
        var baseline = try copy_import.testing.DestinationSnapshot.capture(
            std.testing.allocator,
            checker.types,
            app_cir,
            &checker.var_map,
        );
        defer baseline.deinit();

        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = fail_index,
            .resize_fail_index = 0,
        });
        const failing_allocator = failing.allocator();
        const result = blk: {
            const saved_store_gpa = checker.types.gpa;
            const saved_env_gpa = app_cir.gpa;
            const saved_mapping_allocator = checker.var_map.allocator;
            checker.types.gpa = failing_allocator;
            app_cir.gpa = failing_allocator;
            checker.var_map.allocator = failing_allocator;
            defer {
                checker.var_map.allocator = saved_mapping_allocator;
                app_cir.gpa = saved_env_gpa;
                checker.types.gpa = saved_store_gpa;
            }
            break :blk copy_import.copyVarWithMarkerLineageSupport(
                &platform_cir.types,
                checker.types,
                requirement_root,
                &checker.var_map,
                &alias_source_mapping,
                platform_cir,
                app_cir,
                failing_allocator,
                .{ .platform_requirement = .{
                    .requires_index = 0,
                    .solution_def = @intFromEnum(prog_def),
                    .substitutions = &substitutions,
                } },
            );
        };

        if (result) |copied| {
            try std.testing.expect(!failing.has_induced_failure);
            const copied_step_index = copied.copy_step orelse
                return error.TestUnexpectedResult;
            try std.testing.expectEqual(
                @as(u32, @intCast(baseline.copy_steps.len)),
                copied_step_index,
            );
            try std.testing.expectEqual(app_copy.var_, checker.var_map.get(platform_alias_var).?);
            try std.testing.expectEqual(app_copy.var_, checker.var_map.get(platform_identity_var).?);
            try std.testing.expectEqual(app_copy.var_, alias_source_mapping.get(platform_alias_source).?);
            try std.testing.expectEqual(baseline.copy_steps.len + 1, app_cir.where_marker_copy_steps.items.items.len);
            try std.testing.expect(app_cir.where_marker_copy_pairs.items.items.len > baseline.copy_pairs.len);
            try std.testing.expect(app_cir.where_marker_copy_occurrences.items.items.len > baseline.copy_occurrences.len);
            try std.testing.expectEqual(baseline.constraint_pairs.len, app_cir.where_marker_constraint_copy_pairs.items.items.len);
            try std.testing.expect(app_cir.where_marker_copy_witnesses.items.items.len > baseline.copy_witnesses.len);
            try std.testing.expectEqual(baseline.platform_substitutions.len + 1, app_cir.where_marker_platform_substitutions.items.items.len);
            try std.testing.expectEqual(baseline.selected_anchors.len, app_cir.selected_receiver_anchors.items.items.len);
            try std.testing.expectEqual(baseline.settlement_sources.len, app_cir.dispatch_settlement_sources.items.items.len);

            const copied_step = app_cir.where_marker_copy_steps.items.items[copied_step_index];
            try std.testing.expectEqual(
                ModuleEnv.WhereMarkerCopyStep.Kind.platform_requirement,
                copied_step.decodedKind() orelse return error.TestUnexpectedResult,
            );
            try std.testing.expectEqual(
                ModuleEnv.WhereMarkerCopyStep.CopyPolicy.cross_module_import,
                copied_step.decodedCopyPolicy() orelse return error.TestUnexpectedResult,
            );
            try std.testing.expectEqual(
                @intFromEnum(requirement_resolved.var_),
                copied_step.source_root_var,
            );
            try std.testing.expectEqual(
                @intFromEnum(checker.types.resolveVar(copied.var_).var_),
                copied_step.destination_root_var,
            );
            try std.testing.expectEqual(
                @as(u32, @intCast(baseline.copy_pairs.len)),
                copied_step.pairs_start,
            );
            try std.testing.expectEqual(
                @as(u32, @intCast(baseline.copy_occurrences.len)),
                copied_step.occurrences_start,
            );
            try std.testing.expectEqual(
                @as(u32, @intCast(baseline.copy_witnesses.len)),
                copied_step.witnesses_start,
            );
            const root_occurrence = app_cir.where_marker_copy_occurrences.items.items[
                copied_step.occurrences_start + copied_step.root_occurrence_offset
            ];
            try std.testing.expectEqual(@intFromEnum(requirement_root), root_occurrence.raw_source_var);
            try std.testing.expectEqual(@intFromEnum(copied.var_), root_occurrence.raw_destination_var);
            const root_pair = app_cir.where_marker_copy_pairs.items.items[
                copied_step.pairs_start + root_occurrence.canonical_pair_offset
            ];
            try std.testing.expectEqual(copied_step.source_root_var, root_pair.source_var);
            try std.testing.expectEqual(copied_step.destination_root_var, root_pair.destination_var);
            try std.testing.expectEqual(@as(u32, 0), root_pair.discovery_depth);
            try std.testing.expectEqual(std.math.maxInt(u32), root_pair.predecessor_pair_offset);
            try std.testing.expectEqual(std.math.maxInt(u32), root_pair.predecessor_edge_ordinal);
            const origin = copied_step.origin.platform_requirement;
            try std.testing.expectEqual(@as(u32, 0), origin.requires_index);
            try std.testing.expectEqual(@intFromEnum(prog_def), origin.solution_def);
            try std.testing.expectEqual(
                @as(u32, @intCast(baseline.platform_substitutions.len)),
                origin.substitutions_start,
            );
            try std.testing.expectEqual(@as(u32, 1), origin.substitutions_len);
            const durable_substitution = app_cir.where_marker_platform_substitutions.items.items[
                origin.substitutions_start
            ];
            try std.testing.expectEqual(
                @intFromEnum(for_alias.alias_stmt_idx),
                durable_substitution.platform_alias_statement,
            );
            try std.testing.expectEqual(
                @intFromEnum(app_type_stmt),
                durable_substitution.app_declaration_node,
            );
            try std.testing.expectEqual(
                app_instantiation_step,
                durable_substitution.app_instantiation_step,
            );
            try std.testing.expect(app_instantiation_step < copied_step_index);
            const witnesses = app_cir.where_marker_copy_witnesses.items.items[copied_step.witnesses_start..][0..copied_step.witnesses_len];
            const app_root_occurrence = app_cir.where_marker_copy_occurrences.items.items[
                app_step.occurrences_start + app_step.root_occurrence_offset
            ];
            try std.testing.expectEqual(
                @intFromEnum(app_copy.var_),
                app_root_occurrence.raw_destination_var,
            );
            var substitution_cut_count: usize = 0;
            for (witnesses) |witness| {
                if (witness.decodedAction() != .platform_preseed_cut or
                    witness.decodedAuxiliaryOriginKind() != .platform_substitution or
                    witness.auxiliary_origin_index != 0)
                {
                    continue;
                }
                const child_occurrence = app_cir.where_marker_copy_occurrences.items.items[
                    copied_step.occurrences_start + witness.child_occurrence_offset
                ];
                try std.testing.expectEqual(
                    @intFromEnum(exact_platform_alias_occurrence),
                    child_occurrence.raw_source_var,
                );
                try std.testing.expectEqual(
                    platform_alias_var,
                    platform_cir.types.resolveVar(
                        @enumFromInt(child_occurrence.raw_source_var),
                    ).var_,
                );
                try std.testing.expectEqual(
                    app_root_occurrence.raw_destination_var,
                    child_occurrence.raw_destination_var,
                );
                substitution_cut_count += 1;
            }
            try std.testing.expectEqual(@as(usize, 1), substitution_cut_count);
            try baseline.expectRuntimeOwnerRestored(checker.types, app_cir);
            try baseline.expectRetainedProofPrefixesEqual(app_cir, &checker.var_map);
            try copy_import.testing.expectPublicCopyClosed(checker.types, app_cir);
            canonicalizeCheckedBoundaryCopyPairBfs(
                app_cir.where_marker_copy_pairs.items.items[copied_step.pairs_start..][0..copied_step.pairs_len],
                app_cir.where_marker_copy_occurrences.items.items[copied_step.occurrences_start..][0..copied_step.occurrences_len],
                witnesses,
                copied_step.root_occurrence_offset,
            );
            try std.testing.expect(validateWhereMarkerCopyProofLocal(checker.types, app_cir));
            reached_success = true;
            break;
        } else |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
            try std.testing.expect(failing.has_induced_failure);
            saw_oom = true;
            try baseline.expectEqual(checker.types, app_cir, &checker.var_map);
            try copy_import.testing.expectPublicCopyClosed(checker.types, app_cir);
        }
    }
    try std.testing.expect(saw_oom);
    try std.testing.expect(reached_success);
}

test "canonical call slot tokens require exact fresh-context stream equality" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\applyTwo = |function, first, second| function(first, second)
        \\left = applyTwo(|a, b| (a, b), "left", "right")
        \\right = applyTwo(|a, b| (b, a), "left", "right")
    ;
    var checked = try TestEnv.init("CallTokenContext", source);
    defer checked.deinit();
    var fresh_canonical = try TestEnv.init("CallTokenContext", source);
    defer fresh_canonical.deinit();
    try checked.assertNoErrors();
    try fresh_canonical.assertNoErrors();

    const checked_env = checked.module_env;
    const fresh_env = fresh_canonical.module_env;
    try validateExpectedCallSlotTokenContext(checked_env, fresh_env);
    const rows = checked_env.expected_call_slot_tokens.items.items;
    try std.testing.expect(rows.len >= 6);

    var first_root_index: ?usize = null;
    var second_root_index: ?usize = null;
    var argument_index: ?usize = null;
    for (rows, 0..) |row, index| {
        switch (row.decodedRole() orelse return error.TestUnexpectedResult) {
            .root => {
                if (first_root_index == null) {
                    first_root_index = index;
                } else if (second_root_index == null) {
                    second_root_index = index;
                }
            },
            .argument => argument_index = argument_index orelse index,
        }
    }
    const first_root = first_root_index orelse return error.TestUnexpectedResult;
    const second_root = second_root_index orelse return error.TestUnexpectedResult;
    const argument = argument_index orelse return error.TestUnexpectedResult;

    const saved_root = rows[first_root];
    rows[first_root].owner_node = rows[second_root].owner_node;
    try std.testing.expectError(
        error.CorruptArtifact,
        validateExpectedCallSlotTokenContext(checked_env, fresh_env),
    );
    rows[first_root] = saved_root;

    rows[first_root].site_node = rows[second_root].site_node;
    try std.testing.expectError(
        error.CorruptArtifact,
        validateExpectedCallSlotTokenContext(checked_env, fresh_env),
    );
    rows[first_root] = saved_root;

    rows[first_root].called_via = @intFromEnum(ModuleEnv.ExpectedCallKind.record_builder);
    try std.testing.expectError(
        error.CorruptArtifact,
        validateExpectedCallSlotTokenContext(checked_env, fresh_env),
    );
    rows[first_root] = saved_root;

    const saved_argument = rows[argument];
    rows[argument].slot +%= 1;
    try std.testing.expectError(
        error.CorruptArtifact,
        validateExpectedCallSlotTokenContext(checked_env, fresh_env),
    );
    rows[argument] = saved_argument;

    std.mem.swap(
        ModuleEnv.ExpectedCallSlotToken,
        &rows[first_root],
        &rows[argument],
    );
    try std.testing.expectError(
        error.CorruptArtifact,
        validateExpectedCallSlotTokenContext(checked_env, fresh_env),
    );
    std.mem.swap(
        ModuleEnv.ExpectedCallSlotToken,
        &rows[first_root],
        &rows[argument],
    );

    const row_len = rows.len;
    checked_env.expected_call_slot_tokens.items.items.len = row_len - 1;
    try std.testing.expectError(
        error.CorruptArtifact,
        validateExpectedCallSlotTokenContext(checked_env, fresh_env),
    );
    checked_env.expected_call_slot_tokens.items.items.len = row_len;
    try checked_env.expected_call_slot_tokens.items.append(
        std.testing.allocator,
        saved_argument,
    );
    try std.testing.expectError(
        error.CorruptArtifact,
        validateExpectedCallSlotTokenContext(checked_env, fresh_env),
    );
    checked_env.expected_call_slot_tokens.items.items.len = row_len;
    try validateExpectedCallSlotTokenContext(checked_env, fresh_env);
}

test "creation ambiguity retirement replays call Span2 indirection and rejects cross-kind range retargets" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\make : {} -> a
        \\make = |_| crash "no value"
        \\left = make({})
        \\right = make({})
        \\left_use = left.to_i128()
        \\right_use = right.to_i128()
    ;
    var test_env = try TestEnv.init("CreationAmbiguityCallRetirement", source);
    defer test_env.deinit();

    const cir = test_env.module_env;
    const ambiguity_rows = cir.expected_ambiguity_retirements.items.items;
    var call_row_indexes: [2]u32 = undefined;
    var call_row_count: usize = 0;
    for (ambiguity_rows, 0..) |row, row_index| {
        if (row.decodedKind() != .creation_dispatch_call) continue;
        if (call_row_count >= call_row_indexes.len) return error.TestUnexpectedResult;
        call_row_indexes[call_row_count] = @intCast(row_index);
        call_row_count += 1;
    }
    try std.testing.expectEqual(call_row_indexes.len, call_row_count);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateExpectedCallPlans(cir));

    const first_index = call_row_indexes[0];
    const second_index = call_row_indexes[1];
    const first = &ambiguity_rows[first_index];
    const second = ambiguity_rows[second_index];
    try std.testing.expect(first.hasCanonicalTags());
    try std.testing.expect(second.hasCanonicalTags());
    try std.testing.expect(first.retired_expr != second.retired_expr);
    try std.testing.expect(first.consumer_root_plan != second.consumer_root_plan);

    var first_retired_formal_index: ?usize = null;
    var first_retired_formal_count: usize = 0;
    for (cir.expected_call_formals.items.items, 0..) |formal, formal_index| {
        if (formal.call_root_plan_index != first.consumer_root_plan) continue;
        first_retired_formal_index = formal_index;
        first_retired_formal_count += 1;
        try std.testing.expectEqual(first.retired_expr, formal.owner_node);
        try std.testing.expectEqual(
            ModuleEnv.ExpectedCallFormal.FormalOrigin.explicitly_instantiated,
            formal.decodedFormalOrigin().?,
        );
    }
    try std.testing.expectEqual(@as(usize, 1), first_retired_formal_count);
    const retired_formal = &cir.expected_call_formals.items.items[
        first_retired_formal_index orelse return error.TestUnexpectedResult
    ];
    const saved_retired_formal_owner = retired_formal.owner_node;
    retired_formal.owner_node = second.retired_expr;
    try std.testing.expect(!validateExpectedCallPlans(cir));
    retired_formal.owner_node = saved_retired_formal_owner;
    try std.testing.expect(validateExpectedCallPlans(cir));

    const retirement_index: u32 = for (
        cir.expected_consumer_retirements.items.items,
        0..,
    ) |retirement, index| {
        if (retirement.decodedRejectionOwnerKind() == .expected_ambiguity_retirement and
            retirement.rejection_owner_index == first_index)
        {
            break @intCast(index);
        }
    } else return error.TestUnexpectedResult;
    const retirement = cir.expected_consumer_retirements.items.items[retirement_index];
    try std.testing.expectEqual(CIR.Node.Tag.expr_call, retirement.decodedOriginalNodeTag().?);
    const payload: CIR.Node.Payload = @bitCast(retirement.original_payload);
    const call = payload.expr_call;
    const args_span = cir.store.span2_data.items.items[call.args_span2_idx];
    try std.testing.expectEqual(@as(u32, 1), args_span.len);
    const exact_arg_site = cir.store.index_data.items.items[args_span.start];
    try std.testing.expect(exact_arg_site != args_span.start);

    const consumers = cir.expected_retired_consumers.items.items[retirement.retired_consumers_start..][0..retirement.retired_consumers_len];
    const argument_consumer = for (consumers) |*consumer| {
        if (consumer.decodedRole() == .call_argument) break consumer;
    } else return error.TestUnexpectedResult;
    try std.testing.expectEqual(exact_arg_site, argument_consumer.site_node);

    // Coordinately restamping both durable rows with the Span2 storage offset
    // must not authenticate the wrong CIR argument node. The replay follows
    // `index_data[span.start + slot]`, never `span.start + slot` itself.
    const argument_plan = &cir.expected_consumption_plans.items.items[argument_consumer.plan_index];
    const saved_plan_site = argument_plan.site_node;
    const saved_consumer_site = argument_consumer.site_node;
    argument_plan.site_node = args_span.start;
    argument_consumer.site_node = args_span.start;
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(!validateExpectedCallPlans(cir));
    argument_plan.site_node = saved_plan_site;
    argument_consumer.site_node = saved_consumer_site;
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));

    // Kind/source/group and active-field rules are a closed product. A call
    // cannot borrow the branch kind or activate one copy-driver coordinate.
    const saved_kind = first.kind;
    first.kind = @intFromEnum(
        ModuleEnv.ExpectedAmbiguityRetirement.Kind.body_forced_instantiation_branch,
    );
    try std.testing.expect(!first.hasCanonicalTags());
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    first.kind = saved_kind;
    const saved_copy_step = first.copy_step;
    first.copy_step = 0;
    try std.testing.expect(!first.hasCanonicalTags());
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    first.copy_step = saved_copy_step;

    // A same-shaped sibling call root is not interchangeable even when the
    // group cardinality remains identical.
    const saved_root = first.consumer_root_plan;
    first.consumer_root_plan = second.consumer_root_plan;
    try std.testing.expect(first.hasCanonicalTags());
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    first.consumer_root_plan = saved_root;
    const saved_count = first.consumer_plan_count;
    first.consumer_plan_count += 1;
    try std.testing.expect(first.hasCanonicalTags());
    try std.testing.expect(!validateExpectedFailureRetirementLocal(&cir.types, cir));
    first.consumer_plan_count = saved_count;

    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(validateExpectedCallPlans(cir));
}

const DirectBinderDeepTypeTestProof = struct {
    annotation_idx: CIR.Annotation.Idx,
    outer_formal: CIR.TypeAnno.Idx,
    first_nested_fn: CIR.TypeAnno.Idx,
    deepest_return_occurrence: CIR.TypeAnno.Idx,
};

/// Test-only replay of the exact nested return syntax emitted by the generated
/// direct-binder fixture. Parentheses are structural CIR nodes, and the final
/// rigid lookup is an occurrence distinct from the rigid declaration it names.
fn directBinderDeepTypeTestProof(
    cir: *const ModuleEnv,
    def_idx: CIR.Def.Idx,
    expected_depth: usize,
) error{TestUnexpectedResult}!DirectBinderDeepTypeTestProof {
    const def = cir.store.getDef(def_idx);
    const annotation_idx = def.annotation orelse return error.TestUnexpectedResult;
    const annotation = cir.store.getAnnotation(annotation_idx);
    const outer = cir.store.getTypeAnno(annotation.anno);
    if (outer != .@"fn") return error.TestUnexpectedResult;
    const outer_formals = cir.store.sliceTypeAnnos(outer.@"fn".args);
    if (outer_formals.len != 1 or
        cir.store.getTypeAnno(outer_formals[0]) != .rigid_var)
    {
        return error.TestUnexpectedResult;
    }

    var current = outer.@"fn".ret;
    var first_nested_fn: ?CIR.TypeAnno.Idx = null;
    for (0..expected_depth) |_| {
        const parens = cir.store.getTypeAnno(current);
        if (parens != .parens) return error.TestUnexpectedResult;
        current = parens.parens.anno;
        const nested = cir.store.getTypeAnno(current);
        if (nested != .@"fn") return error.TestUnexpectedResult;
        first_nested_fn = first_nested_fn orelse current;
        current = nested.@"fn".ret;
    }
    const deepest = cir.store.getTypeAnno(current);
    if (deepest != .rigid_var_lookup or
        deepest.rigid_var_lookup.ref != outer_formals[0] or
        current == outer_formals[0])
    {
        return error.TestUnexpectedResult;
    }
    return .{
        .annotation_idx = annotation_idx,
        .outer_formal = outer_formals[0],
        .first_nested_fn = first_nested_fn orelse return error.TestUnexpectedResult,
        .deepest_return_occurrence = current,
    };
}

const DirectBinderBodyAttachmentTestProof = struct {
    publication: ModuleEnv.BodyAnnotationMalformedTypePublication,
    attachment_index: u32,
};

fn directBinderBodyAttachmentTestProof(
    cir: *const ModuleEnv,
    proof: DirectBinderLookupTestProof,
) error{TestUnexpectedResult}!DirectBinderBodyAttachmentTestProof {
    if (proof.direct.local_record_index >= cir.expected_failures.items.items.len) {
        return error.TestUnexpectedResult;
    }
    const source_failure = cir.expected_failures.items.items[proof.direct.local_record_index];
    const source_direct = source_failure.subject_authority.decodedDirect() orelse
        return error.TestUnexpectedResult;
    if (source_direct.local_record_index >=
        cir.body_annotation_malformed_type_publications.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const publication = cir.body_annotation_malformed_type_publications.items.items[
        source_direct.local_record_index
    ];
    if (publication.body_expr != source_failure.owner_node) return error.TestUnexpectedResult;
    const attachment_index = cir.bodyAnnotationAttachmentIndex(
        publication.decodedAttachmentKind() orelse return error.TestUnexpectedResult,
        publication.attachment_node,
        @enumFromInt(publication.annotation_root),
        @enumFromInt(publication.body_expr),
    ) orelse return error.TestUnexpectedResult;
    if (!cir.bodyAnnotationAttachmentIsLocallyValid(attachment_index)) {
        return error.TestUnexpectedResult;
    }
    return .{
        .publication = publication,
        .attachment_index = attachment_index,
    };
}

test "invalid where alias direct binder deep replay rejects bounded topology corruption" {
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = std.testing.allocator;
    const expected_depth: usize = 128;
    var failure_stage: []const u8 = "source construction";
    errdefer std.debug.print("deep direct-binder fixture failed at {s}\n", .{failure_stage});

    var source: std.ArrayList(u8) = .empty;
    defer source.deinit(allocator);
    try source.appendSlice(
        allocator,
        "import DirectBinderDeepA exposing [Status]\n\nfirst : a -> ",
    );
    for (0..expected_depth) |_| try source.appendSlice(allocator, "({} -> ");
    try source.appendSlice(allocator, "a");
    for (0..expected_depth) |_| try source.appendSlice(allocator, ")");
    try source.appendSlice(allocator, " where [a.Status]\nfirst = |value| ");
    for (0..expected_depth) |_| try source.appendSlice(allocator, "|{}| ");
    try source.appendSlice(allocator, "value\n");

    failure_stage = "provider";
    var provider = try TestEnv.init(
        "DirectBinderDeepA",
        direct_binder_transaction_provider_source,
    );
    defer provider.deinit();
    try provider.assertNoErrors();

    failure_stage = "consumer initialization";
    var consumer = try TestEnv.initWithImport(
        "DirectBinderDeepB",
        source.items,
        "DirectBinderDeepA",
        &provider,
    );
    defer consumer.deinit();
    var fresh_env = try TestEnv.initUncheckedWithImportForTesting(
        "DirectBinderDeepB",
        source.items,
        "DirectBinderDeepA",
        &provider,
    );
    defer fresh_env.deinit();

    failure_stage = "diagnostics and lifecycle";
    try consumer.assertCanErrors(&.{ "Type Not Exposed", "Undeclared Type" });
    try std.testing.expectEqual(@as(usize, 0), consumer.checker.problems.problems.items.len);
    try std.testing.expectEqual(@as(usize, 0), try consumer.typeProblemCount());
    const cir = consumer.module_env;
    try std.testing.expectEqual(@as(usize, 2), cir.expected_failures.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_consumer_retirements.items.items.len);
    try std.testing.expectEqual(@as(usize, 2), cir.expected_retirement_failures.items.items.len);
    try expectDirectBinderTransientListsEmpty(&consumer.checker);
    const lookup_proof = try uniqueDirectBinderLookupTestProof(cir);
    const lookup_failure = cir.expected_failures.items.items[lookup_proof.failure_index];
    const attachment_proof = try directBinderBodyAttachmentTestProof(cir, lookup_proof);

    failure_stage = "deep type topology";
    const candidate_def_idx = consumer.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const fresh_def_idx = fresh_env.can.explicitRootDefByName("first") orelse
        return error.TestUnexpectedResult;
    const candidate_type = try directBinderDeepTypeTestProof(
        cir,
        candidate_def_idx,
        expected_depth,
    );
    const fresh_type = try directBinderDeepTypeTestProof(
        fresh_env.module_env,
        fresh_def_idx,
        expected_depth,
    );
    try std.testing.expect(std.meta.eql(candidate_type, fresh_type));
    try std.testing.expectEqual(
        @intFromEnum(candidate_type.outer_formal),
        lookup_failure.raw_peer_var,
    );

    const fresh_attachment_index = fresh_env.module_env.bodyAnnotationAttachmentIndex(
        attachment_proof.publication.decodedAttachmentKind() orelse
            return error.TestUnexpectedResult,
        attachment_proof.publication.attachment_node,
        @enumFromInt(attachment_proof.publication.annotation_root),
        @enumFromInt(attachment_proof.publication.body_expr),
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cir.bodyAnnotationAttachmentContainsTypeAnno(
        attachment_proof.attachment_index,
        candidate_type.deepest_return_occurrence,
    ));
    try std.testing.expect(fresh_env.module_env.bodyAnnotationAttachmentContainsTypeAnno(
        fresh_attachment_index,
        fresh_type.deepest_return_occurrence,
    ));

    failure_stage = "deep runtime topology";
    const fresh_def = fresh_env.module_env.store.getDef(fresh_def_idx);
    const fresh_outer = fresh_env.module_env.store.getExpr(fresh_def.expr);
    if (fresh_outer != .e_lambda) return error.TestUnexpectedResult;
    const outer_patterns = fresh_env.module_env.store.slicePatterns(fresh_outer.e_lambda.args);
    if (outer_patterns.len != 1 or outer_patterns[0] != lookup_proof.pattern_idx) {
        return error.TestUnexpectedResult;
    }
    var current_expr = fresh_outer.e_lambda.body;
    for (0..expected_depth) |_| {
        const closure = fresh_env.module_env.store.getExpr(current_expr);
        if (closure != .e_closure) return error.TestUnexpectedResult;
        const lambda = fresh_env.module_env.store.getExpr(closure.e_closure.lambda_idx);
        if (lambda != .e_lambda) return error.TestUnexpectedResult;
        const nested_patterns = fresh_env.module_env.store.slicePatterns(lambda.e_lambda.args);
        if (nested_patterns.len != 1 or nested_patterns[0] == lookup_proof.pattern_idx) {
            return error.TestUnexpectedResult;
        }
        current_expr = lambda.e_lambda.body;
    }
    const deepest_lookup = fresh_env.module_env.store.getExpr(current_expr);
    if (deepest_lookup != .e_lookup_local or
        deepest_lookup.e_lookup_local.pattern_idx != lookup_proof.pattern_idx or
        @intFromEnum(current_expr) != lookup_failure.owner_node)
    {
        return error.TestUnexpectedResult;
    }

    const context = ImportResolution.freshSupplied(
        fresh_env.module_env,
        .{ .envs = fresh_env.checker.imported_modules, .modules = fresh_env.checker.validated_imported_modules },
        .{ .envs = fresh_env.checker.owner_modules, .modules = fresh_env.checker.validated_owner_modules },
        fresh_env.checker.platform_dependency_index,
    );
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try validateExpectedFailureContext(cir, context);

    failure_stage = "candidate formal tag";
    const candidate_annotation = cir.store.getAnnotation(candidate_type.annotation_idx);
    const candidate_function_node_idx = ModuleEnv.nodeIdxFrom(candidate_annotation.anno);
    const candidate_function_node = cir.store.nodes.get(candidate_function_node_idx);
    if (candidate_function_node.tag != .ty_fn) return error.TestUnexpectedResult;
    const candidate_function = candidate_function_node.getPayload().ty_fn;
    if (candidate_function.args_len != 1 or
        !rangeFits(
            candidate_function.args_start,
            candidate_function.args_len,
            cir.store.index_data.items.items.len,
        ))
    {
        return error.TestUnexpectedResult;
    }
    const candidate_formal_raw = cir.store.index_data.items.items[candidate_function.args_start];
    if (candidate_formal_raw != @intFromEnum(candidate_type.outer_formal)) {
        return error.TestUnexpectedResult;
    }
    const candidate_formal_node_idx: CIR.Node.Idx = @enumFromInt(candidate_formal_raw);
    const saved_candidate_formal_node = cir.store.nodes.get(candidate_formal_node_idx);
    var changed_candidate_formal_node = saved_candidate_formal_node;
    changed_candidate_formal_node.tag = .expr_num;
    cir.store.nodes.set(candidate_formal_node_idx, changed_candidate_formal_node);
    const accepted_candidate_tag = directBinderLookupExpectedFailureIsLocallyValid(
        &cir.types,
        cir,
        lookup_failure,
        lookup_proof.failure_index,
        lookup_proof.direct,
    );
    const accepted_candidate_retirement = validateExpectedFailureRetirementLocal(
        &cir.types,
        cir,
    );
    const accepted_candidate_membership = cir.bodyAnnotationAttachmentContainsTypeAnno(
        attachment_proof.attachment_index,
        candidate_type.deepest_return_occurrence,
    );
    cir.store.nodes.set(candidate_formal_node_idx, saved_candidate_formal_node);
    try std.testing.expect(!accepted_candidate_tag);
    try std.testing.expect(!accepted_candidate_retirement);
    try std.testing.expect(!accepted_candidate_membership);
    try std.testing.expect(validateExpectedFailureRetirementLocal(&cir.types, cir));
    try std.testing.expect(cir.bodyAnnotationAttachmentContainsTypeAnno(
        attachment_proof.attachment_index,
        candidate_type.deepest_return_occurrence,
    ));

    failure_stage = "fresh formal index";
    const fresh_annotation = fresh_env.module_env.store.getAnnotation(fresh_type.annotation_idx);
    const fresh_function_node_idx = ModuleEnv.nodeIdxFrom(fresh_annotation.anno);
    const fresh_function_node = fresh_env.module_env.store.nodes.get(fresh_function_node_idx);
    if (fresh_function_node.tag != .ty_fn) return error.TestUnexpectedResult;
    const fresh_function = fresh_function_node.getPayload().ty_fn;
    if (fresh_function.args_len != 1 or
        !rangeFits(
            fresh_function.args_start,
            fresh_function.args_len,
            fresh_env.module_env.store.index_data.items.items.len,
        ))
    {
        return error.TestUnexpectedResult;
    }
    const fresh_formal_entry = &fresh_env.module_env.store.index_data.items.items[
        fresh_function.args_start
    ];
    const saved_fresh_formal_raw = fresh_formal_entry.*;
    fresh_formal_entry.* = @intCast(fresh_env.module_env.store.nodes.len());
    const accepted_fresh_index = validateExpectedFailureContext(cir, context);
    const accepted_fresh_index_membership =
        fresh_env.module_env.bodyAnnotationAttachmentContainsTypeAnno(
            fresh_attachment_index,
            fresh_type.deepest_return_occurrence,
        );
    fresh_formal_entry.* = saved_fresh_formal_raw;
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_index);
    try std.testing.expect(!accepted_fresh_index_membership);
    try validateExpectedFailureContext(cir, context);
    try std.testing.expect(fresh_env.module_env.bodyAnnotationAttachmentContainsTypeAnno(
        fresh_attachment_index,
        fresh_type.deepest_return_occurrence,
    ));

    failure_stage = "fresh where span";
    const fresh_annotation_node = fresh_env.module_env.store.nodes.get(
        ModuleEnv.nodeIdxFrom(fresh_type.annotation_idx),
    );
    if (fresh_annotation_node.tag != .annotation) return error.TestUnexpectedResult;
    const fresh_annotation_payload = fresh_annotation_node.getPayload().annotation;
    if (!fresh_annotation_payload.flags.has_where or
        fresh_annotation_payload.where_span2_idx >=
            fresh_env.module_env.store.span_with_node_data.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const fresh_where_storage = &fresh_env.module_env.store.span_with_node_data.items.items[
        fresh_annotation_payload.where_span2_idx
    ];
    const saved_fresh_where_storage = fresh_where_storage.*;
    fresh_where_storage.start = @intCast(fresh_env.module_env.store.index_data.items.items.len + 1);
    const accepted_fresh_span = validateExpectedFailureContext(cir, context);
    const accepted_fresh_span_membership =
        fresh_env.module_env.bodyAnnotationAttachmentContainsTypeAnno(
            fresh_attachment_index,
            fresh_type.deepest_return_occurrence,
        );
    fresh_where_storage.* = saved_fresh_where_storage;
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_span);
    try std.testing.expect(!accepted_fresh_span_membership);
    try validateExpectedFailureContext(cir, context);
    try std.testing.expect(fresh_env.module_env.bodyAnnotationAttachmentContainsTypeAnno(
        fresh_attachment_index,
        fresh_type.deepest_return_occurrence,
    ));

    failure_stage = "fresh attachment coordinate";
    const fresh_attachment = &fresh_env.module_env.body_annotation_attachments.items.items[
        fresh_attachment_index
    ];
    const saved_fresh_attachment = fresh_attachment.*;
    try std.testing.expect(saved_fresh_attachment.body_expr != lookup_failure.owner_node);
    fresh_attachment.body_expr = lookup_failure.owner_node;
    const accepted_fresh_attachment = validateExpectedFailureContext(cir, context);
    const accepted_fresh_attachment_row =
        fresh_env.module_env.bodyAnnotationAttachmentIsLocallyValid(fresh_attachment_index);
    fresh_attachment.* = saved_fresh_attachment;
    try std.testing.expectError(error.CorruptArtifact, accepted_fresh_attachment);
    try std.testing.expect(!accepted_fresh_attachment_row);
    try validateExpectedFailureContext(cir, context);
    try std.testing.expect(
        fresh_env.module_env.bodyAnnotationAttachmentIsLocallyValid(fresh_attachment_index),
    );

    failure_stage = "fresh return cycle";
    const fresh_nested_fn_node = fresh_env.module_env.store.nodes.get(
        ModuleEnv.nodeIdxFrom(fresh_type.first_nested_fn),
    );
    if (fresh_nested_fn_node.tag != .ty_fn) return error.TestUnexpectedResult;
    const fresh_nested_fn = fresh_nested_fn_node.getPayload().ty_fn;
    if (fresh_nested_fn.fn_info_span2_idx >=
        fresh_env.module_env.store.span2_data.items.items.len)
    {
        return error.TestUnexpectedResult;
    }
    const fresh_nested_fn_info = &fresh_env.module_env.store.span2_data.items.items[
        fresh_nested_fn.fn_info_span2_idx
    ];
    const saved_fresh_nested_fn_info = fresh_nested_fn_info.*;
    fresh_nested_fn_info.len = @intFromEnum(fresh_type.first_nested_fn);
    const accepted_return_cycle =
        fresh_env.module_env.bodyAnnotationAttachmentContainsTypeAnno(
            fresh_attachment_index,
            fresh_type.deepest_return_occurrence,
        );
    fresh_nested_fn_info.* = saved_fresh_nested_fn_info;
    try std.testing.expect(!accepted_return_cycle);
    try std.testing.expect(fresh_env.module_env.bodyAnnotationAttachmentContainsTypeAnno(
        fresh_attachment_index,
        fresh_type.deepest_return_occurrence,
    ));
    try validateExpectedFailureContext(cir, context);
}
